    private static readonly double[] FontScaleFactors = [0.75, 0.875, 1.0, 1.125, 1.25, 1.4, 1.6];
    private static readonly IReadOnlyDictionary<string, double> FontSizeBaseValues =
        new Dictionary<string, double> {
            ["FontSizeTiny"]     = 10,
            ["FontSizeXSmall"]   = 11,
            ["FontSizeSmall"]    = 12,
            ["FontSizeBody"]     = 13,
            ["FontSizeNormal"]   = 13,
            ["FontSizeMedium"]   = 14,
            ["FontSizeLarge"]    = 15,
            ["FontSizeLargePlus"]= 16,
            ["FontSizeSubtitle"] = 18,
            ["FontSizeCallout"]  = 18,
            ["FontSizeTitle"]    = 20,
            ["FontSizeHeading"]  = 22,
            ["FontSizeHero"]     = 52,
            ["FontSizeDisplay"]  = 180,
        };

    // Pre-multiplied font sizes for every (level, key) pair so ApplyFontSizeScale
    // does nothing but N dictionary writes — no floating-point math at scroll time.
    private static readonly IReadOnlyList<IReadOnlyDictionary<string, double>> PrecomputedFontSizesByLevel =
        BuildPrecomputedFontSizes();

    private static IReadOnlyList<IReadOnlyDictionary<string, double>> BuildPrecomputedFontSizes()
    {
        var result = new IReadOnlyDictionary<string, double>[FontScaleFactors.Length];
        for (var i = 0; i < FontScaleFactors.Length; i++)
        {
            var factor = FontScaleFactors[i];
            var dict   = new Dictionary<string, double>(FontSizeBaseValues.Count);
            foreach (var (key, baseSize) in FontSizeBaseValues)
                dict[key] = Math.Round(baseSize * factor, 1);
            result[i] = dict;
        }
        return result;
    }

    // One WPF ResourceDictionary per scale level. Swapping a single MergedDictionaries slot
    // fires one ResourcesChanged event instead of 14 individual key writes, cutting the
    // WPF visual-tree invalidation cost by ~14×.
    private static readonly ResourceDictionary[] PrecomputedResourceDictsByLevel =
        BuildPrecomputedResourceDicts();

    private static ResourceDictionary[] BuildPrecomputedResourceDicts()
    {
        var result = new ResourceDictionary[FontScaleFactors.Length];
        for (var i = 0; i < FontScaleFactors.Length; i++)
        {
            var dict  = new ResourceDictionary();
            var sizes = PrecomputedFontSizesByLevel[i];
            foreach (var (key, value) in sizes)
                dict[key] = value;
            result[i] = dict;
        }
        return result;
    }
