    internal MainWindow(string? startupFolder = null, WorkspaceOwnershipLease? startupWorkspaceLease = null, IWorkspacePaths? workspacePaths = null, ScreenshotRefreshOptions? screenshotRefreshOptions = null, bool noWorkspaceOnStart = false, IServiceProvider? serviceProvider = null)
    {
        _settingsStore = serviceProvider?.GetRequiredService<ApplicationSettingsStore>() ?? new ApplicationSettingsStore();
        _modelProfileStore = serviceProvider?.GetService<ModelProfileStore>() ?? new ModelProfileStore(_settingsStore);
        _teamRosterLoader = serviceProvider?.GetRequiredService<SquadTeamRosterLoader>() ?? new SquadTeamRosterLoader();
        _routingDocumentService = serviceProvider?.GetRequiredService<SquadRoutingDocumentService>() ?? new SquadRoutingDocumentService();
        _installationStateService = serviceProvider?.GetRequiredService<SquadInstallationStateService>() ?? new SquadInstallationStateService();
        _installerService = serviceProvider?.GetRequiredService<SquadInstallerService>() ?? new SquadInstallerService();
        _cliSelectionStore = serviceProvider?.GetService<ISquadCliSelectionStore>() ??
                             new SquadCliSelectionStore(_settingsStore);
        _cliResolutionService = serviceProvider?.GetService<ISquadCliResolutionService>() ??
                                new SquadCliResolutionService(
                                    new SystemProcessRunner(),
                                    new SystemEnvironmentProvider(),
                                    _cliSelectionStore);
        _cliModelCatalogService = serviceProvider?.GetService<ICliModelCatalogService>() ??
                                  new CliModelCatalogService(workspacePaths ?? WorkspacePathsProvider.Discover());
        _squadOrchestrationService = serviceProvider?.GetService<SquadOrchestrationService>() ?? new SquadOrchestrationService();
        _squadWatchHealthService = serviceProvider?.GetService<SquadWatchHealthService>() ?? new SquadWatchHealthService();
        _instanceRegistry = serviceProvider?.GetRequiredService<RunningInstanceRegistry>() ?? new RunningInstanceRegistry();
        _restartCoordinatorStateStore = serviceProvider?.GetRequiredService<RestartCoordinatorStateStore>() ?? new RestartCoordinatorStateStore();
        _pastedImageStore = serviceProvider?.GetRequiredService<PastedImageStore>() ?? new PastedImageStore();
        _clipboardEditorStateStore = serviceProvider?.GetRequiredService<ClipboardEditorStateStore>() ??
            new ClipboardEditorStateStore(Path.Combine(
                SquadDashPaths.WorkspaceStateDirectory((workspacePaths ?? WorkspacePathsProvider.Discover()).ApplicationRoot),
                "clipboard-editors"));
        var rawQueue = serviceProvider?.GetRequiredService<PromptQueue>() ?? new PromptQueue();
        _promptQueueCoordinator = new PromptQueueCoordinator(rawQueue);
        _promptQueueCoordinator.BranchIndicatorUpdateRequested +=
            () => Dispatcher.InvokeAsync(UpdateBranchIndicator, System.Windows.Threading.DispatcherPriority.Normal);
        _hostCommandRegistry = serviceProvider?.GetRequiredService<HostCommandRegistry>() ?? new HostCommandRegistry();
        _postedUiActionTracker = serviceProvider?.GetRequiredService<PostedUiActionTracker>() ?? new PostedUiActionTracker();
        _uiActionReplayRegistry = serviceProvider?.GetRequiredService<UiActionReplayRegistry>() ?? new UiActionReplayRegistry();
        _fixtureLoaderRegistry = serviceProvider?.GetRequiredService<FixtureLoaderRegistry>() ?? new FixtureLoaderRegistry();
        _workspacePaths = workspacePaths ?? WorkspacePathsProvider.Discover();
        _screenshotRefreshOptions = screenshotRefreshOptions ?? ScreenshotRefreshOptions.None;
        _liveElementLocatorAdapter = new Screenshots.LiveElementLocatorAdapter(
            findByName: name => name == "TourQuickReplyPanel"
                ? VisualTreeSearch.FindLastByName(this, name)
                : VisualTreeSearch.FindByName(this, name),
            getBoundsRelativeToWindow: element =>
            {
                try
                {
                    var transform = element.TransformToAncestor(this);
                    var origin    = transform.Transform(new Point(0, 0));
                    return new Rect(origin.X, origin.Y, element.ActualWidth, element.ActualHeight);
                }
                catch { return Rect.Empty; }
            },
            isVisible: element => element.Visibility == Visibility.Visible && element.ActualWidth > 0);
        _screenshotService = new ScreenshotService(_workspacePaths, _uiActionReplayRegistry, _fixtureLoaderRegistry, _liveElementLocatorAdapter);
        var ctorSw = Stopwatch.StartNew();
        SquadDashTrace.Write(TraceCategory.Startup, "Constructor: begin.");
        AgentArtifactStore.CleanupExpiredArchives(
            _workspacePaths.ApplicationRoot,
            DateTimeOffset.Now,
            AgentArtifactStore.ArchiveRetention);
        var initialSettings = _settingsStore.Load();
        _bridge = new SquadSdkProcess(_workspacePaths);
        _bridge.ByokProviderSettings = BuildByokSettings(initialSettings);
        _bridge.CopilotDefaultModel = BuildCopilotDefaultModel(initialSettings);
        _bridge.ActiveProfile = ResolveActiveProfile(initialSettings);
        _bridge.TemporaryAgentRoute = BuildTemporaryAgentRoute();
        _bridge.BridgeDiagnosticsEnabled = initialSettings.BridgeDiagnosticsEnabled;
        _startupFolderArgument = startupFolder;
        _startupWorkspaceLease = startupWorkspaceLease;
        _noWorkspaceOnStart    = noWorkspaceOnStart;
        _squadCliAdapter = new SquadCliAdapter(
            _workspacePaths,
            _cliResolutionService,
            (op, ex) => HandleUiCallbackException(op, ex));
        _workspaceUpgradeService = serviceProvider?.GetService<IWorkspaceUpgradeService>() ??
            new WorkspaceUpgradeService(
                new SquadInstallerServiceProcessRunner(),
                _installerService,
                _cliResolutionService);
        _workspacePendingUpgradeStore = serviceProvider?.GetService<IWorkspacePendingUpgradeStore>() ??
            new WorkspacePendingUpgradeStore(_settingsStore);
        _workspaceOpenCoordinator = new WorkspaceOpenCoordinator(_instanceRegistry);
        _pushNotificationService = new PushNotificationService(_settingsStore);
        SoundNotifications = new SoundNotificationService(_settingsStore, () => BuildTtsProvider(_settingsSnapshot));
        _guidedTourCoordinator = new GuidedTourCoordinator(
            dispatcher: Dispatcher,
            isIntelliSensePopupOpen: () => IntelliSensePopup.IsOpen,
            clearIntelliSenseStateIfNeeded: () =>
            {
                if (_intelliSenseState is not null)
                {
                    _intelliSenseState = null;
                    _intelliSenseOwnerBox = null;
                    UpdateIntelliSensePopup();
                }
            });
        InitializeComponent();
        // Dynamic dock-size providers must exist before a workspace layout is restored or a
        // side-zone visibility change requests its initial height allocation.
        LoopPanelBorder.MaximumUsefulSizeProvider = orientation =>
            orientation == DockResizeOrientation.Vertical ? ComputeLoopPanelUsefulHeight() : null;
        BranchIndicatorStrip.ToolTip = MakeThemedToolTip("Click for Branch options");
        this.AddHandler(UIElement.GotFocusEvent, new RoutedEventHandler(OnWindowElementGotFocus), true);
        _restartStatusPanelControl = (RestartStatusPanel?)FindName("RestartStatusPanelControl");
        _dockingService = new PanelDockingService(
            new Dictionary<string, FrameworkElement>
            {
                ["loop"]         = LoopPanelBorder,
                ["tasks"]        = TasksPanelBorder,
                ["approvals"]    = ApprovalPanelBorder,
                ["notes"]        = NotesPanelBorder,
                ["maintenance"]  = CodeHealthPanelBorder,
                ["inbox"]        = InboxPanelBorder,
                ["plans"]        = PlansPanelBorder,
            },
            LeftZonePanel,
            RightZonePanel,
            Left2ZonePanel,
            Right2ZonePanel,
            Left3ZonePanel,
            Right3ZonePanel,
            Left4ZonePanel,
            Right4ZonePanel,
            Left5ZonePanel,
            Right5ZonePanel,
            Left6ZonePanel,
            Right6ZonePanel,
            TopZonePanelsGrid,
            LeftZoneColumn,
            RightZoneColumn,
            Left2ZoneColumn,
            Right2ZoneColumn,
            Left3ZoneColumn,
            Right3ZoneColumn,
            Left4ZoneColumn,
