            backgroundTaskPresenter: _backgroundTaskPresenter,
            squadCliAdapter: _squadCliAdapter,
            getIsPromptRunning: () => _isPromptRunning,
            setIsPromptRunning: v =>
            {
                _isPromptRunning = v;
                SyncGateChangeActivity(v);
                SyncPlanTaskCorrectionActivity(v);
                _idleDetectionService?.SetPromptActive(v);
                if (v)
                {
                    // Clear stale completion timestamp AND remove the "Completed N ago" footer
                    // paragraph so it doesn't linger while the new turn is streaming.
                    MaybeReactivateThread(CoordinatorThread);
                    _inboxSavedForCurrentTurn = false;
                }
                else
                {
                    CoordinatorThread.CompletedAt = DateTimeOffset.Now;
                    SyncQueuePauseLabel();
                    UpdateCompletedTimeFooters();
                    _backgroundTaskPresenter.PromoteDeferredBackgroundAgentReports("coordinator_idle");
                    SquadDashTrace.Write("Queue", $"setIsPromptRunning(false): queueCount={_promptQueue.Count} deferred={_deferredShutdown} restartPending={_restartPending} isClosing={_isClosing}");
                    ApplyPendingBridgeSettingsRestartIfIdle("prompt-finished");
                    if (_deferredShutdown == DeferredShutdownMode.AfterCurrentTurn)
                    {
                        // User chose "close after this turn" — don't drain, just close.
                        Close();
                    }
                    else if (_deferredShutdown == DeferredShutdownMode.AfterAllQueued)
                    {
                        if (_promptQueue.Count > 0)
                        {
                            if (CanAutoDispatchPromptQueue("deferred-shutdown") && GetAutoDispatchCandidate() is not null)
                                _ = DrainQueueAsync(); // keep draining
                            else
                                SquadDashTrace.Write("Shutdown", $"Deferred shutdown still waiting for queued items count={_promptQueue.Count}.");
                        }
                        else
                        {
                            Close(); // queue exhausted — shut down
                        }
                    }
                    else if (_restartPending)
                    {
                        // Rebuild-triggered restart: close only after every in-flight activity
                        // that can mutate transcript/agent state is safely idle.
                        TryCompletePendingRestart("prompt-finished");
                    }
                    else
                    {
                        if (_promptQueue.Count > 0 && CanAutoDispatchPromptQueue("prompt-finished") && GetAutoDispatchCandidate() is not null)
                        {
                            if (LastTurnNeedsInput())
                                HandleQueuePausedForInput();
                            else
                                _ = DrainQueueAsync();
                        }
                        else
                        {
                            // Only play the "queue empty" sound when the queue genuinely drained.
                            // GetAutoDispatchCandidate() also returns null when the queue is
                            // manually paused (items still present), so guard on Count == 0 to
                            // avoid firing the sound when the user clicked Pause.
                            if (_promptQueue.Count == 0)
                            {
                                SoundNotifications.Play(SoundEvent.QueueEmpty);
                                // Resume a queued loop now that there are no more items to drain.
                                bool loopAboutToStart = _loopQueued || _loopInterruptedByQueue || _loopPausedForQuickReply;
                                if (_queueDrainActive)
                                {
                                    SquadDashTrace.Write("Loop",
                                        "Queued loop resume deferred until the dispatched queue turn has fully unwound.");
                                }
                                else
                                {
                                    _ = MaybeFireQueuedLoopAsync();
                                }
                                if (!loopAboutToStart)
                                    TryFireDeferredCodeHealth();
                            }
                        }
                    }
                }
                SyncQueuePanel();
                SyncLoopPanel();
                // Refresh branch indicator after each turn — git operations run during the turn
                // (e.g. checkout, merge, push) may have changed HEAD while _isPromptRunning was true.
                // The FileSystemWatcher usually catches this, but a post-turn refresh guarantees
                // the indicator is always correct when the user can next interact with it.
                if (!v) UpdateBranchIndicator();
                if (_remoteAccessActive)
                    _ = _bridge.BroadcastRcStatusAsync(v);
                UpdateRestartStatusPanelVisibility();
                if (!v) {
                    TryDispatchPendingDecomposeRecoveryResponse();
                    TryPresentPendingInterruptedPromptRecovery();
                    TryStartPendingAutomaticInterruptedPromptRecovery();
                }
            },
            getIsClosing: () => _isClosing,
            getRestartPending: () => _restartPending,
            close: () => TryCompletePendingRestart("prompt-controller-finally"),
            getPendingRoutingRepairRecheck: () => _pendingRoutingRepairRecheck,
            setPendingRoutingRepairRecheck: v => _pendingRoutingRepairRecheck = v,
            getPendingSupplementalInstruction: () => _pendingSupplementalPromptInstruction,
            clearPendingSupplementalInstruction: () => { _pendingSupplementalPromptInstruction = null; },
            getPendingQuickReplyRoutingInstruction: () => _pendingQuickReplyRoutingInstruction,
            getPendingQuickReplyRouteMode: () => _pendingQuickReplyLaunch?.RouteMode,
            updateInteractiveControlState: () => UpdateInteractiveControlState(),
            updateLeadAgent: (status, bubble, detail) => UpdateLeadAgent(status, bubble, detail),
            updateSessionState: state => UpdateSessionState(state),
            refreshAgentCards: () => RefreshAgentCards(),
            refreshSidebar: () => RefreshSidebar(),
            setInstallStatus: msg => SetInstallStatus(msg),
            canShowOwnedWindow: () => CanShowOwnedWindow(),
            showTextWindow: (title, content) => ShowTextWindow(title, content),
            clearSessionView: () => ClearSessionView(clearAgentReports: true),
            showTasksStatusWindow: () => ShowTasksStatusWindow(),
            hideTasksStatusWindow: () => HideTasksStatusWindow(),
            showApprovalWindow: () => ShowApprovalPanel(),
            showLiveTraceWindow: () => ShowTraceWindow(),
            showScreenshotHealthWindow: () => ShowScreenshotHealthWindow(),
            runDoctor: () => RunDoctorButton_Click(null!, null!),
            showCastAgentWindow: () => ShowCastAgentWindow(),
            enqueuePrompt: (text, isSystemInjected) => EnqueuePrompt(text, isSystemInjected),
            showScreenshotOverlay: () => ShowScreenshotOverlay(),
            triggerCodeHealthCycle: () => {
                SquadDashTrace.Write("UI", "triggerCodeHealthCycle: scheduling code health on next idle");
                _codeHealthPendingOnIdle = true;
                TryFireDeferredCodeHealth();
            },
            showRuntimeIssue: msg => ShowRuntimeIssue(msg),
            clearRuntimeIssue: () => ClearRuntimeIssue(),
            waitForRoutingRepairSettleAsync: () => WaitForRoutingRepairStateToSettleAsync(),
            maybePublishRoutingIssue: (reason, force) => MaybePublishRoutingIssueSystemEntry(reason, force),
            promptHealthTimer: _promptHealthTimer,
            waitForBridgeUiEventsAppliedAsync: WaitForBridgeUiEventsAppliedAsync,
            getModelObservedThisSession: () => _modelObservedThisSession,
            workspacePaths: _workspacePaths,
            instructionProvider: serviceProvider?.GetRequiredService<IPromptInstructionProvider>() ?? new DefaultPromptInstructionProvider(),
            getSubmittedAttachments: () => _pendingTranscriptAttachments ?? Array.Empty<FollowUpAttachment>(),
            promptBuilder: serviceProvider?.GetRequiredService<ISquadBridgePromptBuilder>(),
            consumeInterruptedPromptFreshnessInstructionAsync: ConsumeInterruptedPromptFreshnessInstructionAsync,
            prepareBridgeForTurn: RefreshBridgeModelSettingsBeforeDispatch,
            onInterruptedPromptRecoverySaved: HandleInterruptedPromptRecoverySaved,
            onInterruptedPromptRecoveryCleared: ReleaseInterruptedPromptRecoveryHold);
        _pec.TryHandlePlanRuntimeFailure = error =>
            TryHandleActivePlanValidationProviderFailure(error, confirmedProviderEvent: false);

        InitializeHostCommands();
        SquadDashTrace.Write(TraceCategory.Startup, $"Constructor: InitializeHostCommands {ctorSw.ElapsedMilliseconds}ms.");

        _loopController = new LoopController(
            // ExecuteLoopIterationAsync accesses WPF components — must run on the UI thread.
            // It spans multiple AI turns when the AI responds with quick replies.
            executePromptAsync: (prompt, sessionId) =>
                Dispatcher.InvokeAsync(() => ExecuteLoopIterationAsync(prompt, sessionId)).Task.Unwrap(),
            abortPrompt: () => _bridge.AbortPrompt(),
            onIterationStarted: n =>
                Dispatcher.Invoke(() => OnNativeLoopIterationStarted(n)),
            onStopped: () =>
                Dispatcher.Invoke(OnNativeLoopStopped),
            onError: msg =>
                Dispatcher.Invoke(() => OnNativeLoopError(msg)),
            onIterationCompleted: n =>
                Dispatcher.Invoke(() => OnNativeLoopIterationCompleted(n)),
            onWaiting: nextAt =>
                Dispatcher.Invoke(() => OnNativeLoopWaiting(nextAt)),
            onBeforeIteration: () =>
                Dispatcher.InvokeAsync(() => DrainQueueBeforeLoopIterationAsync())
                          .Task.Unwrap(),
            onBeforeWait: () =>
                Dispatcher.InvokeAsync(() => DrainQueueIfNeededAsync())
                          .Task.Unwrap(),
            isIterationTimeoutSuspended: () => _restartPending);

        var transcriptCommitResolver = new GitCommitReferenceResolver(
            () => _currentWorkspace?.FolderPath);
        _markdownRenderer = new MarkdownDocumentRenderer(
            getFontSize: () => _transcriptFontSize,
            getWorkspaceGitHubUrl: () => _workspaceGitHubUrl,
            onLinkClicked: target => HandleTranscriptLinkClick(target),
            onException: (op, ex) => HandleUiCallbackException(op, ex),
            resolveContinuationThread: entry => TryResolveQuickReplyContinuationThread(entry),
            onQuickReplyButtonClick: QuickReplyButton_Click,
            appendResponseSegment: (thread, text, newLine) => AppendResponseSegment(thread, text, newLine),
            scrollToEndIfAtBottom: thread => ScrollToEndIfAtBottom(thread),
            getCoordinatorThread: () => CoordinatorThread,
            resolvePlanDisplayName: referenceId =>
            {
                var title = _planStore?.LoadByPlanOrTaskReference(referenceId)?.Title?.Trim();
                if (string.IsNullOrWhiteSpace(title) && _currentWorkspace is not null)
                {
                    title = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath)
                        .LoadByPlanOrTaskReference(referenceId)?.Group.GroupTitle?.Trim();
                }
                return string.IsNullOrWhiteSpace(title) ? null : title;
            },
            resolvesToCommit: transcriptCommitResolver.ResolvesToCommit);

        RegisterUiReplayActions();
        RegisterFixtureLoaders();
        ctorSw.Stop();
        SquadDashTrace.Write(TraceCategory.Startup, $"Constructor: complete {ctorSw.ElapsedMilliseconds}ms total.");
    }

    private void InitializeTranscriptSearchController()
    {
        if (_search is not null)
            return;

        _search = new TranscriptSearchController(
            dispatcher: Dispatcher,
            searchBox: SearchBox,
            focusPromptTextBox: () => PromptTextBox.Focus(),
            findPrevButton: FindPrevButton,
            findNextButton: FindNextButton,
            searchMatchCountText: SearchMatchCountText,
            clearSearchButton: ClearSearchButton,
            outputTextBox: OutputTextBox,
            conversationManager: _conversationManager,
            agentThreadRegistry: _agentThreadRegistry,
            getSelectedThread: () => _selectedTranscriptThread,
            getCoordinatorThread: () => CoordinatorThread,
            selectTranscriptThread: t => SelectTranscriptThread(t),
            getActiveTranscriptBox: () => ActiveTranscriptBox,
            getActiveScrollController: () => ActiveScrollController,
            getTranscriptScrollViewer: () => _transcriptScrollViewer,
            flashGlowHighlightForThread: thread =>
            {
                if (ReferenceEquals(thread, CoordinatorThread))
                    FlashGlowHighlight(MainTranscriptBorder, Colors.CornflowerBlue);
                else
                {
                    var entry = _secondaryTranscripts.FirstOrDefault(e => ReferenceEquals(e.Thread, thread));
                    if (entry is not null)
                        FlashGlowHighlight(entry.PanelBorder, ColorFromHex(entry.Agent.AccentColorHex));
                    else
                        FlashGlowHighlight(MainTranscriptBorder, Colors.CornflowerBlue);
                }
            },
            syncPromptNavButtons: () => SyncPromptNavButtons(),
            handleException: (op, ex) => HandleUiCallbackException(op, ex));
        _search.WireEventHandlers();
    }

    // ── Replay action registration ──────────────────────────────────────────

    /// <summary>
    /// Registers all <see cref="IReplayableUiAction"/> instances with
    /// <see cref="_uiActionReplayRegistry"/> at startup.
    /// Add new concrete actions here as they are implemented in Phase 3.
    /// </summary>
    private void RegisterUiReplayActions()
    {
        _uiActionReplayRegistry.Register(new OpenPreferencesWindowAction(
            openPreferencesWindow: () => PreferencesMenuItem_Click(this, new System.Windows.RoutedEventArgs()),
            getPreferencesWindow: () => _preferencesWindow is { IsVisible: true } ? _preferencesWindow : null));
