    private void MainWindow_ContentRendered(object? sender, EventArgs e)
    {
        try
        {
            ContentRendered -= MainWindow_ContentRendered;
            UpdateAgentPanelWidths();
            UpdateRosterHeightCap();
            SquadDashTrace.Write(
                "Startup",
                $"ContentRendered: ActiveH={ActiveAgentItemsControl.ActualHeight:F0} ActiveViewport={ActiveAgentsScrollViewer.ActualHeight:F0} " +
                $"InactiveH={InactiveAgentItemsControl.ActualHeight:F0} InactiveViewport={InactiveAgentsScrollViewer.ActualHeight:F0} RootH={StatusAgentPanelsGrid.ActualHeight:F0}");
            if (ActiveAgentItemsControl.ActualHeight < 1 || InactiveAgentItemsControl.ActualHeight < 1)
                ScheduleAgentPanelLayoutRefresh();
            TryNudgeAgentLaneLayout();
            SquadDashTrace.Write(
                "Startup",
                $"ContentRendered post-refresh: ActiveH={ActiveAgentItemsControl.ActualHeight:F0} ActiveViewport={ActiveAgentsScrollViewer.ActualHeight:F0} " +
                $"InactiveH={InactiveAgentItemsControl.ActualHeight:F0} InactiveViewport={InactiveAgentsScrollViewer.ActualHeight:F0} RootH={StatusAgentPanelsGrid.ActualHeight:F0}");

            // When the window is restored to maximized state on startup, WPF's WindowChrome
            // HWND hook can miss the initial WM_NCCALCSIZE/WM_NCPAINT messages — particularly
            // on non-primary monitors with a different DPI — leaving the title bar chrome
            // (caption buttons and background) transparent/unrendered. Re-applying the
            // WindowChrome at ContentRendered forces the non-client area to repaint correctly.
            if (WindowState == WindowState.Maximized)
            {
                var chrome = System.Windows.Shell.WindowChrome.GetWindowChrome(this);
                if (chrome is not null)
                    System.Windows.Shell.WindowChrome.SetWindowChrome(this, chrome);
                InvalidateVisual();
            }

            PromptTextBox.Focus();
            LogMainLayoutPositions();
            ApplyTopLevelMenuPopupCallbacks();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(MainWindow_ContentRendered), ex);
        }
    }

    private void LogMainLayoutPositions()
    {
        static string Pos(FrameworkElement el, UIElement root)
        {
            var pt = el.TranslatePoint(new System.Windows.Point(0, 0), root);
            return $"x={pt.X:F0} y={pt.Y:F0} w={el.ActualWidth:F0} h={el.ActualHeight:F0} bottom={pt.Y + el.ActualHeight:F0}";
        }
        SquadDashTrace.Write(TraceCategory.UI,
            $"[LayoutPositions] StatusPanelBorder:    {Pos(StatusPanelBorder,    this)}");
        SquadDashTrace.Write(TraceCategory.UI,
            $"[LayoutPositions] TranscriptPanelsGrid: {Pos(TranscriptPanelsGrid, this)}");
        SquadDashTrace.Write(TraceCategory.UI,
            $"[LayoutPositions] PromptBorder:         {Pos(PromptBorder,         this)}");
        SquadDashTrace.Write(TraceCategory.UI,
            $"[LayoutPositions] Gap StatusPanel→Transcript: {TranslatePoint(new System.Windows.Point(0,0), this).Y:F0}" +
            $" | gap={TranscriptPanelsGrid.TranslatePoint(new System.Windows.Point(0,0), this).Y - (StatusPanelBorder.TranslatePoint(new System.Windows.Point(0,0), this).Y + StatusPanelBorder.ActualHeight):F0}px" +
            $" | gap2={PromptBorder.TranslatePoint(new System.Windows.Point(0,0), this).Y - (TranscriptPanelsGrid.TranslatePoint(new System.Windows.Point(0,0), this).Y + TranscriptPanelsGrid.ActualHeight):F0}px");
    }

    private async void MainWindow_Activated(object? sender, EventArgs e)
    {
        try
        {
            SquadDashTrace.Write("Approval",
                $"MainWindow_Activated entered deferred={_deferredApprovalCallout is not null} "
                + $"wpfIsActive={IsActive} {WindowHelper.DescribeForegroundOwnership()}.");

            // Re-sync scroll state on every activation so that an RDP reconnect —
            // which can leave the transcript viewport at the top without firing the
            // events that normally show/hide the scroll-to-bottom button — is corrected
            // the moment the user sees the window.
            ActiveScrollController.SyncScrollState();

            // Branch may have changed while SquadDash was in the background (e.g. via
            // an external VCS tool).  The FileSystemWatcher can miss those events, so do
            // a lightweight async re-check on every activation.
            _ = RefreshBranchIfChangedAsync();

            // WPF can raise Activated before Win32 GetForegroundWindow has finished moving
            // foreground ownership during a mouse-click activation. Yield through the input
            // transition, then revalidate using the real foreground process. The display path
            // performs the same check again, so a quick switch away remains safe.
            await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.ContextIdle);
            SquadDashTrace.Write("Approval",
                $"MainWindow_Activated settled deferred={_deferredApprovalCallout is not null} "
                + $"wpfIsActive={IsActive} {WindowHelper.DescribeForegroundOwnership()}.");
            await TryShowDeferredApprovalCalloutAsync();
            await TryShowDeferredPlanInboxCalloutAsync();

            if (!_pendingPowerShellInstallRecheck)
                return;

            _pendingPowerShellInstallRecheck = false;
            await RefreshInstallationStateAsync();
            if (await Task.Run(WorkspaceIssueFactory.IsPowerShellAvailable) &&
                WorkspaceIssueFactory.IsMissingPowerShellIssue(_runtimeIssue))
            {
                ClearRuntimeIssue();
                await RefreshInstallationStateAsync();
                SetInstallStatus("PowerShell 7 was detected. Setup looks good now.");
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(MainWindow_Activated), ex);
        }
    }

    private async void MainWindow_Loaded(object sender, RoutedEventArgs e)
    {
        try
        {
            DocEditorToolbar.TargetRichTextBox = DocSourceTextBox;

            DeveloperMenuItem.Visibility = Visibility.Collapsed;

            // Wire the search highlight adorner unconditionally (idempotent).
            _search.EnsureAdornersInitialized();
            RefreshActiveTranscriptScrollViewer();

            // Allow the agent card glow (DropShadowEffect) to render outside the scroll
            // viewport on all four sides.  The ScrollContentPresenter inside the default
            // ScrollViewer template sets its own Clip property (a RectangleGeometry equal
            // to the viewport rect) during ArrangeOverride; ClipToBounds=False on the outer
            // ScrollViewer does not affect that explicit Clip.  We subscribe to LayoutUpdated
            // once and re-inflate the SCP clip after every layout pass so the glow is never
            // cropped.  Keep this idempotent because LayoutUpdated can run many times while
            // other parts of the window are changing.
            ActiveAgentsScrollViewer.LayoutUpdated += (_, _) =>
            {
                InflateAgentScrollViewerClip(ActiveAgentsScrollViewer);
                UpdateAgentCardGlowOverlayPosition();
                UpdateRosterHeightCap();
            };
            InactiveAgentsScrollViewer.LayoutUpdated += (_, _) =>
            {
                try
                {
                    InflateAgentScrollViewerClip(InactiveAgentsScrollViewer);
                    UpdateAgentCardGlowOverlayPosition();
                    UpdateRosterHeightCap();
                }
                catch (Exception ex)
                {
                    HandleUiCallbackException("InactiveAgentsScrollViewer.LayoutUpdated", ex);
                }
            };

            if (_startupInitialized)
                return;

            _startupInitialized = true;

            // Global shortcut: F12 → toggle UI Reveal on the active window.
            // The InputManager routing lambda was already subscribed to the static
            // InputManager.Current.PreProcessInput in the constructor; here we just
            // register the GlobalPreProcessInput handler with the broker.
            _onGlobalPreProcessInput = msg => OnGlobalPreProcessInput(msg.Sender, msg.Args);
            _broker.Subscribe(_onGlobalPreProcessInput);
            PreviewMouseLeftButtonDown += (_, _) => FrmUltimateCallout.CloseAllNonSticky();

            // HintEngine is a singleton; use a WeakReference capture so this MainWindow
            // does not stay alive via the singleton's event subscription.
            _onHintRequested = msg => OnHintEngineHintRequested(msg.Sender, msg.Hint);
            _broker.Subscribe(_onHintRequested);
            {
                var localBrokerRef = new WeakReference<WeakEventBroker>(_broker);
                HintEngine.Instance.HintRequested += (hintSender, hint) =>
                {
                    if (localBrokerRef.TryGetTarget(out var b))
                        b.Publish(new HintRequestedMessage(hintSender, hint));
                };
            }

            // Capture Shift state once, before any async work, while we're still on the UI thread.
            _startupShiftHeld = Keyboard.IsKeyDown(Key.LeftShift) || Keyboard.IsKeyDown(Key.RightShift);

            var loadedSw = Stopwatch.StartNew();
            var phaseSw = Stopwatch.StartNew();
            SquadDashTrace.Write(TraceCategory.Startup, "MainWindow_Loaded: begin deferred init.");

            ConfigureRestartRequestWatcher();
            SquadDashTrace.Write(TraceCategory.Startup, $"MainWindow_Loaded: ConfigureRestartRequestWatcher {phaseSw.ElapsedMilliseconds}ms.");

            // When an AI doc-revision completes, check if a deferred restart can now proceed.
            // MarkdownDocumentWindow.RevisionCompleted is a static event; route it through the
            // broker via a WeakReference capture to prevent this MainWindow from being retained.
            _onDocRevisionCompleted = _ => OnDocRevisionCompleted();
            _broker.Subscribe(_onDocRevisionCompleted);
            {
                var localBrokerRef = new WeakReference<WeakEventBroker>(_broker);
                MarkdownDocumentWindow.RevisionCompleted += () =>
                {
                    if (localBrokerRef.TryGetTarget(out var b))
                        b.Publish(new DocRevisionCompletedMessage());
                };
            }

            phaseSw.Restart();
            await InitializeWorkspace(_startupFolderArgument);
            SquadDashTrace.Write(TraceCategory.Startup, $"MainWindow_Loaded: InitializeWorkspace {phaseSw.ElapsedMilliseconds}ms.");

            // If Shift was held and we actually suppressed something, show a single transcript hint.
            if (_startupShiftHeld && (_promptQueue.HasReadyItems || _loopQueued || _settingsSnapshot.LoopActiveOnExit))
            {
                AppendLine("⏸ Startup paused — Shift was held. Queue and loop auto-resume suppressed.",
                           (Brush)FindResource("SubtleText"));
            }

            phaseSw.Restart();
            RestoreUtilityWindowVisibility();
            SquadDashTrace.Write(TraceCategory.Startup, $"MainWindow_Loaded: RestoreUtilityWindowVisibility {phaseSw.ElapsedMilliseconds}ms.");

            // Restore any clipboard editors whose state was saved before the last restart.
            _ = RestoreClipboardEditorsAsync();
            // Clean up stale pending state files (>7 days old) in the background.
            _ = _clipboardEditorStateStore.CleanupStaleFilesAsync();

            // Grant focus before the async version-check so the user can type immediately
            // without waiting for the npx squad --version probe to complete.
            if (PromptTextBox.IsVisible)
                _ = Dispatcher.BeginInvoke(DispatcherPriority.Input, () => PromptTextBox.Focus());

            // Fire-and-forget the version probe — it takes ~1.5 s and only affects status
            // display.  Show the title immediately with whatever is already known; the probe
            // will refresh it once it completes.
            UpdateStatusTitle();
            var resolveVersionSw = Stopwatch.StartNew();
            _ = _squadCliAdapter.ResolveSquadVersionAsync(_currentWorkspace?.FolderPath).ContinueWith(_ =>
                Dispatcher.Invoke(() =>
                {
                    resolveVersionSw.Stop();
                    SquadDashTrace.Write(TraceCategory.Startup, $"MainWindow_Loaded: ResolveSquadVersionAsync {resolveVersionSw.ElapsedMilliseconds}ms (async complete).");
                    UpdateStatusTitle();
                    SyncLoopPanel();
                    UpdateSquadUpdateBadge();
                    _ = RefreshWorkspaceUpgradeStateAsync();
                }));
            SquadDashTrace.Write(TraceCategory.Startup, "MainWindow_Loaded: ResolveSquadVersionAsync started (non-blocking).");
            _ = _squadCliAdapter.CheckForSquadUpdateAsync().ContinueWith(_ => Dispatcher.Invoke(UpdateSquadUpdateBadge));

            loadedSw.Stop();
            SquadDashTrace.Write(TraceCategory.Startup, $"MainWindow_Loaded: complete {loadedSw.ElapsedMilliseconds}ms total.");

            // First-run guided tour offer (fire-and-forget after a short delay so UI is settled)
            _ = Dispatcher.BeginInvoke(OfferGuidedTourOnFirstRun, System.Windows.Threading.DispatcherPriority.ApplicationIdle);

            // Screenshot refresh mode: run the automated pass then shut down.
            if (_screenshotRefreshOptions.Mode != ScreenshotRefreshMode.None)
                await RunScreenshotRefreshAsync(_screenshotRefreshOptions);

            // Pre-warm the definition registry so right-click "Refresh screenshot" is
            // available immediately without an async lookup delay.
            _ = _screenshotService.WarmDefinitionRegistryCacheAsync();
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Startup", $"Deferred startup initialization failed: {ex}");
            HandleUiCallbackException(nameof(MainWindow_Loaded), ex);
        }
    }

    // ── Screenshot refresh mode ─────────────────────────────────────────────────────

    private async Task RunScreenshotRefreshAsync(ScreenshotRefreshOptions options)
    {
        SquadDashTrace.Write("Screenshot", $"Starting refresh run: Mode={options.Mode} Target={options.TargetName ?? "(all)"}");

        try
        {
            var screenshotsDir = _workspacePaths.ScreenshotsDirectory;
            var definitions = await ScreenshotDefinitionRegistry.LoadAsync(screenshotsDir).ConfigureAwait(true);
            var runner = new ScreenshotRefreshRunner(
                definitions,
                _uiActionReplayRegistry,
                _fixtureLoaderRegistry,
                screenshotsDir,
                applyThemeAsync: async name =>
                {
                    await Dispatcher.InvokeAsync(() => ApplyTheme(name));
                },
                getActiveTheme: () => _activeThemeName);

            runner.CaptureRequested += OnScreenshotCaptureRequested;

            try
            {
                await runner.RunAsync(options).ConfigureAwait(true);
            }
            finally
            {
                runner.CaptureRequested -= OnScreenshotCaptureRequested;
            }
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Screenshot", $"Refresh run failed: {ex}");
            Console.Error.WriteLine($"[screenshot] Refresh aborted: {ex.Message}");
        }
        finally
        {
            SquadDashTrace.Write("Screenshot", "Refresh run complete — shutting down.");
            Application.Current.Shutdown();
        }
    }

    private Task WarmDefinitionRegistryCacheAsync()
        => _screenshotService.WarmDefinitionRegistryCacheAsync();

    /// <summary>
    /// Runs a single-definition screenshot refreshfrom the right-click context menu,
    /// without shutting down afterwards.  Applies the fixture, replays the action,
    /// captures, restores, copies to the doc image path, and reloads the viewer.
    /// </summary>
    private async Task RefreshDocImageAsync(string definitionName)
    {
        SquadDashTrace.Write("Screenshot", $"RefreshDocImage: {definitionName}");
        try
        {
            var screenshotsDir = _workspacePaths.ScreenshotsDirectory;
            // Always reload from disk so we have the latest definition state.
            var definitions = await Screenshots.ScreenshotDefinitionRegistry.LoadAsync(screenshotsDir)
                                               .ConfigureAwait(true);
            _screenshotService.CachedDefinitionRegistry = definitions;

            // "Refresh screenshot" from the right-click menu always re-captures in the
            // currently visible theme.  If the stored definition says a different theme,
            // update it now so the runner applies the correct theme and the definition
            // stays in sync with the image the user is actually looking at.
            var existingDef = definitions.TryGet(definitionName);
            if (existingDef is not null
                && !string.Equals(existingDef.Theme, _activeThemeName, StringComparison.OrdinalIgnoreCase))
            {
                definitions.AddOrUpdate(existingDef with { Theme = _activeThemeName });
                await definitions.SaveAsync().ConfigureAwait(true);
                _screenshotService.CachedDefinitionRegistry = definitions;
            }

            var runner = new Screenshots.ScreenshotRefreshRunner(
                definitions,
                _uiActionReplayRegistry,
                _fixtureLoaderRegistry,
                screenshotsDir,
                applyThemeAsync: async name =>
                {
                    await Dispatcher.InvokeAsync(() => ApplyTheme(name));
                },
                getActiveTheme: () => _activeThemeName);

            runner.CaptureRequested += OnScreenshotCaptureRequested;
            try
            {
                await runner.RunAsync(
                    new Screenshots.ScreenshotRefreshOptions(
                        Mode:       Screenshots.ScreenshotRefreshMode.Named,
                        TargetName: definitionName)
                    ).ConfigureAwait(true);
            }
            finally
            {
                runner.CaptureRequested -= OnScreenshotCaptureRequested;
            }

            // Reload the doc viewer so the updated image appears immediately.
            if (!string.IsNullOrEmpty(_currentDocPath) && File.Exists(_currentDocPath))
            {
                var raw      = File.ReadAllText(_currentDocPath);
                var markdown = StripDocFrontMatter(raw, out _);
                var title    = (DocTopicsTreeView?.SelectedItem as TreeViewItem)?.Header?.ToString()
                               ?? "Documentation";
                var html = MarkdownHtmlBuilder.Build(
                    markdown, title, filePath: _currentDocPath,
                    isDark: AgentStatusCard.IsDarkTheme);
                DocMarkdownViewer.NavigateToString(html);
            }

            // Reload the Tasks panel from disk so any changes made before the refresh are visible.
            LoadTasksPanel();

            AppendLine($"✅ Screenshot refreshed: {definitionName}");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Screenshot", $"RefreshDocImage failed for '{definitionName}': {ex}");
            AppendLine($"[screenshot] Refresh failed for '{definitionName}': {ex.Message}",
                       ThemeBrush("SystemErrorText"));
        }
    }


    private void OnScreenshotCaptureRequested(object? sender, ScreenshotCaptureRequestedEventArgs e)
    {
        try
        {
            // The runner may raise this event from a thread-pool thread (ConfigureAwait(false)
            // inside RunOneAsync). All WPF visual-tree access and RenderTargetBitmap work must
            // run on the dispatcher thread — so we marshal the entire capture body through
            // Dispatcher.Invoke, including the render-flush pass.
            Dispatcher.Invoke(() =>
            {
                try
                {
                    // Switch to Natural tint (stop 0) so all doc screenshots have a
                    // consistent baseline appearance, then restore the user's tint after.
                    int savedTintStop = _activeTintStop;
                    try
                    {
                        if (savedTintStop != 0)
                            SetWorkspaceTintStop(0, immediate: true);

                        // Allow WPF to finish any pending layout/rendering before capturing,
                        // including the tint change applied above.
                        Dispatcher.Invoke(() => { }, System.Windows.Threading.DispatcherPriority.Render);

                        var dpi = VisualTreeHelper.GetDpi(this);
                        var pxW = (int)Math.Round(ActualWidth * dpi.DpiScaleX);
                        var pxH = (int)Math.Round(ActualHeight * dpi.DpiScaleY);

                        var rtb = new System.Windows.Media.Imaging.RenderTargetBitmap(
                            pxW, pxH,
                            dpi.PixelsPerInchX, dpi.PixelsPerInchY,
                            System.Windows.Media.PixelFormats.Pbgra32);
                        rtb.Render(this);
                        rtb.Freeze();

                        // If the definition specified a sub-region, crop the RTB to that area.
                        // Prefer live anchor-based bounds so that panel moves are handled correctly;
                        // fall back to the stored CaptureBounds when live resolution fails.
                        BitmapSource bitmapToSave = rtb;
                        var liveBounds = TryResolveLiveBounds(e);
                        var cropBounds = liveBounds ?? e.CaptureBounds;
                        if (cropBounds is { } bounds)
                        {
                            // Always convert the logical-pixel bounds using the *current* runtime DPI
                            // scale — NOT the DPI stored in CaptureBounds.  The RTB was rendered at
                            // the current dpi.PixelsPerInchX/Y, so pixel coordinates must use the
                            // same scale.  Using the stored bounds.DpiX/Y would produce the wrong
                            // crop on any machine whose DPI differs from the original capture machine.
                            var pixelX = (int)Math.Round(bounds.X * dpi.DpiScaleX);
                            var pixelY = (int)Math.Round(bounds.Y * dpi.DpiScaleY);
                            var pixelW = (int)Math.Round(bounds.Width * dpi.DpiScaleX);
                            var pixelH = (int)Math.Round(bounds.Height * dpi.DpiScaleY);

                            // Clamp to the RTB dimensions so we never request an out-of-bounds rect.
                            pixelX = Math.Max(0, Math.Min(pixelX, rtb.PixelWidth - 1));
                            pixelY = Math.Max(0, Math.Min(pixelY, rtb.PixelHeight - 1));
                            pixelW = Math.Max(1, Math.Min(pixelW, rtb.PixelWidth - pixelX));
                            pixelH = Math.Max(1, Math.Min(pixelH, rtb.PixelHeight - pixelY));

                            bitmapToSave = new CroppedBitmap(
                                rtb, new System.Windows.Int32Rect(pixelX, pixelY, pixelW, pixelH));
                        }

                        // Normalise DPI metadata to 96 DPI so the saved PNG has a consistent,
                        // predictable size in documentation viewers regardless of the monitor's
                        // physical DPI.  Physical pixels are copied 1:1 — no resampling.
                        bitmapToSave = DpiHelper.NormalizeTo96Dpi(bitmapToSave);

                        var dir = Path.GetDirectoryName(e.OutputPath);
                        if (!string.IsNullOrEmpty(dir))
                            Directory.CreateDirectory(dir);

                        using var stream = File.Create(e.OutputPath);
                        var encoder = new PngBitmapEncoder();
                        encoder.Frames.Add(BitmapFrame.Create(bitmapToSave));
                        encoder.Save(stream);

                        e.SignalSaved();
                    }
                    finally
                    {
                        if (savedTintStop != 0)
                            SetWorkspaceTintStop(savedTintStop, immediate: true);
                    }
                }
                catch (Exception ex)
                {
                    e.SignalFailed(ex.Message);
                }
            });
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(OnScreenshotCaptureRequested), ex);
        }
    }

    /// <summary>
    /// Attempts to derive a live <see cref="Screenshots.CaptureBounds"/> by locating
    /// the named WPF elements stored in each edge anchor of <paramref name="e"/> and
    /// computing the bounding box from their current screen positions.
    /// </summary>
    /// <returns>
    /// A freshly computed <see cref="Screenshots.CaptureBounds"/> when all four edge
    /// anchors resolve to a visible element; <c>null</c> when any anchor cannot be
    /// resolved (callers should fall back to the stored bounds).
    /// </returns>
    private Screenshots.CaptureBounds? TryResolveLiveBounds(
        Screenshots.ScreenshotCaptureRequestedEventArgs e)
    {
        // Require all four anchors to be present.
        if (e.TopAnchor    is not { } top    || top.ElementNames.Count    == 0) return null;
        if (e.RightAnchor  is not { } right  || right.ElementNames.Count  == 0) return null;
        if (e.BottomAnchor is not { } bottom || bottom.ElementNames.Count == 0) return null;
        if (e.LeftAnchor   is not { } left   || left.ElementNames.Count   == 0) return null;

        var topEl    = FindName(top.ElementNames[0])    as FrameworkElement;
        var rightEl  = FindName(right.ElementNames[0])  as FrameworkElement;
        var bottomEl = FindName(bottom.ElementNames[0]) as FrameworkElement;
        var leftEl   = FindName(left.ElementNames[0])   as FrameworkElement;

        if (topEl is null || rightEl is null || bottomEl is null || leftEl is null)
        {
            SquadDashTrace.Write("Screenshot",
                $"[{e.DefinitionName}] Live anchor resolution failed — one or more elements not found; falling back to stored bounds.");
            return null;
        }

        try
        {
            Rect TopRect    = GetElementBoundsInWindow(topEl);
            Rect RightRect  = GetElementBoundsInWindow(rightEl);
            Rect BottomRect = GetElementBoundsInWindow(bottomEl);
            Rect LeftRect   = GetElementBoundsInWindow(leftEl);

            if (TopRect.IsEmpty || RightRect.IsEmpty || BottomRect.IsEmpty || LeftRect.IsEmpty)
            {
                SquadDashTrace.Write("Screenshot",
                    $"[{e.DefinitionName}] Live anchor resolution failed — element has no layout; falling back to stored bounds.");
                return null;
            }

            // Each anchor stores the distance from the element's matching edge to the
            // capture region edge.  Invert to get the capture region edge coordinates.
            //   Top anchor:    captureTop    = element.Top    − distanceToEdge
            //   Bottom anchor: captureBottom = element.Bottom + distanceToEdge
            //   Left anchor:   captureLeft   = element.Left   − distanceToEdge
            //   Right anchor:  captureRight  = element.Right  + distanceToEdge
            var captureTop    = TopRect.Top      - top.DistanceToEdge;
            var captureBottom = BottomRect.Bottom + bottom.DistanceToEdge;
            var captureLeft   = LeftRect.Left    - left.DistanceToEdge;
            var captureRight  = RightRect.Right  + right.DistanceToEdge;

            var width  = captureRight - captureLeft;
            var height = captureBottom - captureTop;

            if (width <= 0 || height <= 0)
            {
                SquadDashTrace.Write("Screenshot",
                    $"[{e.DefinitionName}] Live anchor resolution produced zero/negative size; falling back to stored bounds.");
                return null;
            }

            var dpiScale = VisualTreeHelper.GetDpi(this);
            SquadDashTrace.Write("Screenshot",
                $"[{e.DefinitionName}] Live bounds resolved: ({captureLeft:F1}, {captureTop:F1}) {width:F1}×{height:F1}");

            return new Screenshots.CaptureBounds(
                captureLeft, captureTop, width, height,
                dpiScale.DpiScaleX, dpiScale.DpiScaleY);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Screenshot",
                $"[{e.DefinitionName}] Live anchor resolution threw: {ex.Message}; falling back to stored bounds.");
            return null;
        }
    }

    private Rect GetElementBoundsInWindow(FrameworkElement element)
    {
        try
        {
            var transform = element.TransformToAncestor(this);
            var origin    = transform.Transform(new Point(0, 0));
            return new Rect(origin.X, origin.Y, element.ActualWidth, element.ActualHeight);
        }
        catch { return Rect.Empty; }
    }

    private async Task InitializeWorkspace(string? startupFolder)
    {
        var initWsSw = Stopwatch.StartNew();
        SquadDashTrace.Write(TraceCategory.Startup, "InitializeWorkspace: begin.");
        var initialSnapshot = _settingsStore.Load();
        _settingsManager = new SettingsSnapshotManager(_settingsStore, initialSnapshot);
        _bridge.BridgeDiagnosticsEnabled = _settingsSnapshot.BridgeDiagnosticsEnabled;
        RefreshBridgeDiagnosticsMenuCheckmark();
        AgentStatusCard.AvatarsSettingEnabled = _settingsSnapshot.ShowAgentAvatars;
        SquadDashTrace.Write(TraceCategory.Startup, $"InitializeWorkspace: settings loaded {initWsSw.ElapsedMilliseconds}ms.");
        _promptFontSize = Math.Clamp(_settingsSnapshot.PromptFontSize, PromptFontSizeMin, PromptFontSizeMax);
        _transcriptFontSize = Math.Clamp(_settingsSnapshot.TranscriptFontSize, TranscriptFontSizeMin, TranscriptFontSizeMax);
        _docSourceFontSize = Math.Clamp(_settingsSnapshot.DocSourceFontSize, DocSourceFontSizeMin, DocSourceFontSizeMax);
        _inboxFontSize = Math.Clamp(_settingsSnapshot.InboxFontSize, InboxFontSizeMin, InboxFontSizeMax);
        _fontScaleLevel = Math.Clamp(_settingsSnapshot.FontSizeScaleLevel, 0, FontScaleFactors.Length - 1);
        _squadCliAdapter.LastObservedModel = _settingsSnapshot.LastUsedModel;
        ApplyViewMode();
        ApplyPromptFontSize();
        ApplyTranscriptFontSize();
        ApplyDocSourceFontSize();
        ApplyFontSizeScale();
        _themePreference = _settingsSnapshot.Theme ?? "Auto";
        var resolvedTheme = string.Equals(_themePreference, "Auto", StringComparison.OrdinalIgnoreCase)
            ? GetWindowsTheme()
            : _themePreference;
        ApplyTheme(resolvedTheme);
        RefreshRecentFoldersMenu(_settingsSnapshot.RecentFolders);
        UpdateVoiceHintVisibility();
        SquadDashTrace.Write(TraceCategory.Startup, $"InitializeWorkspace: theme/UI applied {initWsSw.ElapsedMilliseconds}ms.");
        await RefreshInstallationStateAsync();
        RefreshDeveloperRuntimeIssuePreview();
        SquadDashTrace.Write(TraceCategory.Startup, $"InitializeWorkspace: installation state refreshed {initWsSw.ElapsedMilliseconds}ms.");

        var candidateFolder = _noWorkspaceOnStart
            ? null
            : StartupWorkspaceResolver.Resolve(
                startupFolder,
                _settingsSnapshot.LastOpenedFolder,
                TryGetApplicationRoot());

        if (!string.IsNullOrWhiteSpace(candidateFolder))
        {
            SquadDashTrace.Write(TraceCategory.Startup, $"InitializeWorkspace: opening workspace at {initWsSw.ElapsedMilliseconds}ms.");
            await OpenWorkspace(
                candidateFolder,
                rememberFolder: true,
                closeWindowIfActivatedExisting: true,
                showBlockedDialog: false);
            SquadDashTrace.Write(TraceCategory.Startup, $"InitializeWorkspace: complete (with workspace) {initWsSw.ElapsedMilliseconds}ms total.");
            return;
        }

        UpdateWindowTitle();
        RefreshAgentCards();
        RefreshSidebar();
        UpdateInteractiveControlState();
        SyncNoWorkspaceHintOverlay();
        UpdateRunningInstanceRegistration();
        _workspacePendingUpgradeState = WorkspacePendingUpgradeState.None;
        UpdateSquadUpdateBadge();
        SquadDashTrace.Write(TraceCategory.Startup, $"InitializeWorkspace: complete (no workspace) {initWsSw.ElapsedMilliseconds}ms total.");
    }

    private string? TryGetApplicationRoot()
    {
        try
        {
            return _workspacePaths.ApplicationRoot;
        }
        catch
        {
            return null;
        }
    }

    private string GetActiveArtifactWorkspaceRoot() =>
        AgentArtifactStore.ResolveActiveWorkspaceRoot(
            _currentWorkspace?.FolderPath,
            _workspacePaths.ApplicationRoot);

    private async void RunButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (IsActiveQueueItemLocked())
                return;

            if (_currentWorkspace is null)
            {
                MessageBox.Show(
                    "Open a folder before sending a prompt.",
                    "No Workspace",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
                return;
            }

            // Editing a queued tab while the queue is running or paused → return
            // keyboard focus to the main draft instead of dispatching the item.
            // When the queue is idle the original direct-dispatch path is correct.
            if (_activeTabId is not null)
            {
                if (_queuePausedNotificationFired && IsRightmostQueueTabActive())
                {
                    await DispatchRightmostQueuedTabAsQuickReplyAsync(_activeTabId);
                    return;
                }

                // A slash command in a queued tab must execute immediately regardless of
                // queue state — remove the slot, restore the main draft, then dispatch.
                var queuedText = PromptTextBox.Text.Trim();
                if (LocalPromptSubmissionPolicy.IsImmediateLocalCommand(queuedText))
                {
                    var capturedId = _activeTabId;
                    _promptQueue.Remove(capturedId);
                    _activeTabId = null;
                    SetPromptTextBoxLogicalBuffer(
                        _queuePreEditDraft ?? string.Empty,
                        _queuePreEditDraftCaretIndex,
                        _queuePreEditDraftSelectionStart,
                        _queuePreEditDraftSelectionLength,
                        "slash-command-from-queued-tab");
                    _queuePreEditDraft = null;
                    UpdateFollowUpStrip();
                    SyncQueuePanel();
                    SquadDashTrace.Write("UI", $"Slash command {queuedText} executed from queued tab — slot removed");
                    await _pec.ExecutePromptAsync(queuedText, addToHistory: true, clearPromptBox: false);
                    SyncPromptTextBoxSimBorder();
                    return;
                }

                // Intercept: a step is subscribed to SimulatedSend and the active tab is a
                // tour-typed item → fire the trigger instead of dispatching to AI.
                if (_guidedTourCoordinator.HasSimulatedSendClickedHandler &&
                    _promptQueue.Items.Any(i => i.Id == _activeTabId && i.SourceTag == TourTypeTag))
                {
                    StopTypeIntoPromptAnimation(); // removes the TourTypeTag item and resets _guidedTourCoordinator.TypeItemIsSimulated
                    _guidedTourCoordinator.RaiseSimulatedSendClicked();
                    return;
                }

                if (_isPromptRunning || IsNativeLoopRunning || IsQueueDispatchHeld || HasPendingDirectQuickReplyAgentFollowUp())
                {
                    OnQueueTabClicked(null);
                    if (_queueManuallyPaused)
                        ShowQueuePausedCallout();
                    return;
                }
                await DispatchQueuedTabAsync(_activeTabId);
                return;
            }

            var prompt = PromptTextBox.Text.Trim();
            if (string.IsNullOrWhiteSpace(prompt) && !(_followUpAttachments.TryGetValue("", out var clickAttachCheck) && clickAttachCheck.Count > 0))
                return;

            SquadDashTrace.Write("UI", "Prompt sent: SendButton click");

            // Local-only slash commands(e.g. /trace, /cast, /hire alias) must execute immediately
            // regardless of whether the coordinator is busy or items are queued.
            // PromptExecutionController.TryHandleLocalCommand never touches the AI, so
            // there is no risk of a concurrent AI call. For /cast specifically, if the
            // user completes a cast while a prompt is running, the PEC's enqueuePrompt
            // callback adds the resulting cast prompt to the back of the queue.
            if (LocalPromptSubmissionPolicy.IsImmediateLocalCommand(prompt))
            {
                AutoActivateCoordinatorTranscriptOnPromptSubmit();
                await _pec.ExecutePromptAsync(prompt, addToHistory: true, clearPromptBox: true);
                SyncPromptTextBoxSimBorder();
                return;
            }

            if (_interruptedPromptRecoveryHold is not null)
            {
                var supersededRecovery = _interruptedPromptRecoveryHold;
                GetInterruptedPromptRecoveryStore()?.Clear("superseded-by-submitted-prompt");
                ReleaseInterruptedPromptRecoveryHold("submitted-edited-or-new-prompt", resumePendingWork: false);
                if (_lastQuickReplyEntry?.AllowQuickReplies == true)
                {
                    _pec.DisableQuickReplies(_lastQuickReplyEntry);
                    ClearActiveQuickReplyState(_lastQuickReplyEntry);
                }
                SquadDashTrace.Write(
                    "Recovery",
                    $"User submission superseded recovery id={supersededRecovery.RecoveryId}; existing queue and loop ordering remain preserved.");
            }

            if (_isPromptRunning || IsNativeLoopRunning || IsQueueDispatchHeld || HasPendingDirectQuickReplyAgentFollowUp())
            {
                if (IsNativeLoopRunning && _loopFollowUpTcs == null)
                {
                    var firstPlanQueueInterrupt = !_loopInterruptedByQueue;
                    _loopInterruptedByQueue = true;
                    if (firstPlanQueueInterrupt)
                        AnnouncePlanQueueDrainPause();
                }
                EnqueueCurrentPrompt();
                if (_queueManuallyPaused)
                    ShowQueuePausedCallout();
                return;
            }

            if (_promptHasVoiceInput)
            {
                _promptHasVoiceInput = false;
                prompt += "\n(some or all of this prompt was dictated by voice)";
            }

            _markdownRenderer.DismissKeyboardHint();
            ResetQueuePausedState();
            if (_remoteAccessActive)
                _ = _bridge.BroadcastRcPromptAsync(prompt);
            AutoActivateCoordinatorTranscriptOnPromptSubmit();
            HandleOpenEditorsBeforeSend("");
            await _pec.ExecutePromptAsync(ApplyFollowUpHeader(prompt, ""), addToHistory: true, clearPromptBox: true);

            // In fullscreen mode the prompt was peeked temporarily — hide it again now.
            if (_transcriptFullScreenEnabled && _fullScreenPromptVisible)
                HideFullScreenPrompt();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException("Run", ex);
        }
    }

    // ── Prompt Queue ──────────────────────────────────────────────────────────

    private PromptQueueItem? EnqueuePrompt(
        string text,
        bool isSystemInjected,
        bool forceAtTail = false,
        string? sourceTag = null,
        bool drain = true)
    {
        if (string.IsNullOrWhiteSpace(text))
            return null;

        var item = new PromptQueueItem {
            Text             = text,
            SequenceNumber   = _promptQueueCoordinator.NextSequenceNumber(),
            QueueNumber      = NextQueueNumber(),
            IsSystemInjected = isSystemInjected,
            SourceTag        = sourceTag,
            IsLocked         = string.Equals(
                sourceTag,
                PlanRepairReplayPolicy.TaskResultRepairSourceTag,
                StringComparison.Ordinal),
            DisplayLabel     = string.Equals(
                sourceTag,
                PlanRepairReplayPolicy.TaskResultRepairSourceTag,
                StringComparison.Ordinal)
                    ? "Plan result repair"
                    : null,
            ReadOnlyDisplayText = string.Equals(
                sourceTag,
                PlanRepairReplayPolicy.TaskResultRepairSourceTag,
                StringComparison.Ordinal)
                    ? PlanRepairReplayPolicy.BuildQueueDescription(text)
                    : null,
        };
        var isPlanRepair = string.Equals(
            sourceTag,
            PlanRepairReplayPolicy.TaskResultRepairSourceTag,
            StringComparison.Ordinal);
        if (isSystemInjected && !forceAtTail && !isPlanRepair && _activeTabId is null && !IsQueueDispatchHeld) {
            _promptQueue.EnqueueItemAtFront(item);
            _promptQueue.RenumberSequentially();
        }
        else {
            _promptQueue.EnqueueItem(item);
            PlaceNewQueueItemBeforePlanContinuation(item);
        }
        SquadDashTrace.Write(
            "Queue",
            $"Enqueued prompt {DescribeQueueItemForTrace(item)} queueCount={_promptQueue.Count}");
        SyncQueuePanel();
        if (_loopIsWaiting) _loopController.CancelLoopWait();
        if (drain)
            _ = DrainQueueIfNeededAsync();
        return item;
    }

    private void EnqueueCurrentPrompt()
    {
        var text = PromptTextBox.Text.Trim();
        var hasDraftAttachments = _followUpAttachments.TryGetValue("", out var draftAttachCheck) && draftAttachCheck.Count > 0;
        if (string.IsNullOrWhiteSpace(text) && !hasDraftAttachments) return;

        var isDictated = _promptHasVoiceInput;
        _promptHasVoiceInput = false;

        _promptQueue.Enqueue(text, _promptQueueCoordinator.NextSequenceNumber(), isDictated);
        var item = _promptQueue.Items[^1];
        item.QueueNumber = NextQueueNumber();
        PlaceNewQueueItemBeforePlanContinuation(item);
        SquadDashTrace.Write("Queue", $"Enqueued current prompt {DescribeQueueItemForTrace(item)}queueCount={_promptQueue.Count}");
        _loopFollowUpTcs?.TrySetResult(true);

        // Transfer any draft follow-up attachments to the new queue item.
        if (_followUpAttachments.TryGetValue("", out var draftList) && draftList.Count > 0)
        {
            _followUpAttachments.Remove("");
            _followUpAttachments[item.Id] = draftList;
        }

        ClearPromptTextBoxLogicalBuffer("enqueue-current");
        SyncQueuePanel();
        UpdateFollowUpStrip();
        PersistDraftFollowUp();
    }

    private void EnqueueRcPrompt(string text)
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        _promptQueue.Enqueue(text, _promptQueueCoordinator.NextSequenceNumber(), isFromRemote: true);
        var queued = _promptQueue.Items[^1];
        queued.QueueNumber = NextQueueNumber();
        PlaceNewQueueItemBeforePlanContinuation(queued);
        SquadDashTrace.Write("Queue", $"Enqueued remote prompt {DescribeQueueItemForTrace(queued)} queueCount={_promptQueue.Count}");
        SyncQueuePanel();
        if (_loopIsWaiting) _loopController.CancelLoopWait();
        _ = DrainQueueIfNeededAsync();
    }

    private void EnqueueRcPrompt(string text, List<FollowUpAttachment> attachments)
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        _promptQueue.Enqueue(text, _promptQueueCoordinator.NextSequenceNumber(), isFromRemote: true);
        var queued = _promptQueue.Items[^1];
        queued.QueueNumber = NextQueueNumber();
        PlaceNewQueueItemBeforePlanContinuation(queued);
        if (attachments.Count > 0)
            _followUpAttachments[queued.Id] = attachments;
        SquadDashTrace.Write("Queue", $"Enqueued remote prompt {DescribeQueueItemForTrace(queued)} queueCount={_promptQueue.Count}");
        SyncQueuePanel();
        if (_loopIsWaiting) _loopController.CancelLoopWait();
        _ = DrainQueueIfNeededAsync();
    }

    /// <summary>
    /// Ctrl+Enter handler. Moves the active tab to the front of the queue.
    /// If the user is on the Active Draft tab, enqueues the current text at the front.
    /// Shows a transient "« Now at the front of the queue." label in the tab strip.
    /// </summary>
    private void PrioritizeActiveTabToFront()
    {
        if (_activeTabId is null)
        {
            // Active Draft — enqueue at front if there is text.
            var text = PromptTextBox.Text.Trim();
            if (string.IsNullOrWhiteSpace(text)) return;

            RecordHintFeatureUsed(PromptHintFeature.CtrlEnterPrioritize);

            var isDictated = _promptHasVoiceInput;
            _promptHasVoiceInput = false;

            var item = _promptQueue.EnqueueAtFront(text, _promptQueueCoordinator.NextSequenceNumber());
            item.QueueNumber = NextQueueNumber();
            _promptQueue.RenumberSequentially();

            if (_followUpAttachments.TryGetValue("", out var draftList) && draftList.Count > 0)
            {
                _followUpAttachments.Remove("");
                _followUpAttachments[item.Id] = draftList;
            }

            ClearPromptTextBoxLogicalBuffer("prioritize-draft");
            UpdateFollowUpStrip();
            PersistDraftFollowUp();
            ShowPriorityFeedback(item.Id);
            SyncQueuePanel();
        }
        else
        {
            // Queued tab — move it to the front (no-op if already first).
            var capturedId = _activeTabId;
            if (!IsCtrlEnterPrioritizeApplicable()) return;

            RecordHintFeatureUsed(PromptHintFeature.CtrlEnterPrioritize);

            _promptQueue.MoveToFront(capturedId);
            _promptQueue.RenumberSequentially();
            ShowPriorityFeedback(capturedId);
            SyncQueuePanel();

            // Restore prompt box state for the still-active tab.
            var activeItem = _promptQueue.Items.FirstOrDefault(i => i.Id == capturedId);
            if (activeItem is not null)
            {
                SetPromptTextBoxLogicalBuffer(
                    activeItem.Text,
                    activeItem.CaretIndex,
                    activeItem.SelectionStart,
                    activeItem.SelectionLength,
                    "prioritize-restore-active-tab");
            }
        }
    }

    /// <summary>
    /// Returns the next queue number for today (local time). Resets to 1 whenever the
    /// local date changes since the last call (midnight rollover handled lazily).
    /// </summary>
    private int NextQueueNumber()
    {
        var today = DateTime.Now.ToString("yyyy-MM-dd");
        if (_queueCounterDate != today)
        {
            _queueDayCounter  = 0;
            _queueCounterDate = today;
        }
        return ++_queueDayCounter;
    }

    private void AddEmptyQueueSlot()
    {
        _promptQueue.EnqueueAtFront(string.Empty, _promptQueueCoordinator.NextSequenceNumber());
        var item = _promptQueue.Items[0];
        item.QueueNumber = NextQueueNumber();
        SyncQueuePanel();
        OnQueueTabClicked(item.Id);
        PromptTextBox.Focus();
        _guidedTourCoordinator.RaiseNewQueueSlotAtFront();
    }

    // Appends to the TAIL of the internal list, which SyncQueuePanel renders as the leftmost tab.
    private void AddEmptyQueueSlotAtEnd()
    {
        _promptQueue.Enqueue(string.Empty, _promptQueueCoordinator.NextSequenceNumber());
        var item = _promptQueue.Items[^1];
        item.QueueNumber = NextQueueNumber();
        SyncQueuePanel();
        OnQueueTabClicked(item.Id);
        PromptTextBox.Focus();
    }

    /// <summary>
    /// Records <paramref name="id"/> as the recently-prioritized item and starts a 3-second
    /// timer that clears the feedback label once it expires. <see cref="SyncQueuePanel"/> reads
    /// <c>_priorityFeedbackId</c> to inject the "« Now at the front of the queue." label.
    /// </summary>
    private void ShowPriorityFeedback(string id)
    {
        _priorityFeedbackTimer?.Stop();
        _priorityFeedbackId = id;

        var timer = new DispatcherTimer { Interval = UiTimingConstants.QueueFeedbackClearDelay };
        timer.Tick += (_, _) =>
        {
            timer.Stop();
            _priorityFeedbackTimer = null;
            _priorityFeedbackId = null;
            SyncQueuePanel();
        };
        _priorityFeedbackTimer = timer;
        timer.Start();
    }

    private async Task DispatchQueuedTabAsync(string id)
    {
        var item = _promptQueue.Items.FirstOrDefault(i => i.Id == id);
        if (item is null) return;

        var prompt = PromptTextBox.Text.Trim();
        if (string.IsNullOrWhiteSpace(prompt)) return;

        item.Text = prompt;

        // Switch back to Active Draft.
        _activeTabId = null;
        SetPromptTextBoxLogicalBuffer(
            _queuePreEditDraft ?? string.Empty,
            _queuePreEditDraftCaretIndex,
            _queuePreEditDraftSelectionStart,
            _queuePreEditDraftSelectionLength,
            "dispatch-queued-tab-restore-draft");
        _queuePreEditDraft = null;
        UpdateFollowUpStrip();

        if (_isPromptRunning || IsNativeLoopRunning || HasPendingDirectQuickReplyAgentFollowUp())
        {
            // Coordinator busy — item stays in queue with updated text.
            SyncQueuePanel();
            return;
        }

        _promptQueue.Remove(id);
        // Resuming via Send: clear any manual pause so the queue continues after dispatch.
        if (_queueManuallyPaused || _queuePausePending)
            SetQueuePaused(false);
        SyncQueuePanel();

        try
        {
            ResetQueuePausedState();
            HandleOpenEditorsBeforeSend(id);
            _pec.PendingQueueItemCount = _promptQueue.Count;
            _pec.CurrentDispatchedItem = item;
            _pendingPromptIsSystemInjected = item.IsSystemInjected;
            _pendingPromptSuppressTranscript = ShouldSuppressQueuedPromptTranscript(item);
            await _pec.ExecutePromptAsync(
                ApplyFollowUpHeader(ApplyDictationAnnotation(item), id),
                addToHistory: !item.IsSystemInjected,
                clearPromptBox: false,
                displayPrompt: BuildQueuedPromptDisplayText(item));
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(DispatchQueuedTabAsync), ex);
        }
        finally
        {
            _pendingPromptIsSystemInjected = false;
            _pendingPromptSuppressTranscript = false;
            _pec.PendingQueueItemCount = 0;
            _pec.CurrentDispatchedItem = null;
        }
    }

    private async Task DispatchRightmostQueuedTabAsQuickReplyAsync(string id)
    {
        var item = _promptQueue.Items.FirstOrDefault(i => i.Id == id);
        if (item is null) return;

        var prompt = PromptTextBox.Text.Trim();
        if (string.IsNullOrWhiteSpace(prompt)) return;

        item.Text = prompt;

        var entry = _lastQuickReplyEntry;
        if (entry is not null)
            _pec.DisableQuickReplies(entry);
        ClearActiveQuickReplyState(entry);

        _activeTabId = null;
        SetPromptTextBoxLogicalBuffer(
            _queuePreEditDraft ?? string.Empty,
            _queuePreEditDraftCaretIndex,
            _queuePreEditDraftSelectionStart,
            _queuePreEditDraftSelectionLength,
            "dispatch-queued-tab-as-qr-restore-draft");
        _queuePreEditDraft = null;
        UpdateFollowUpStrip();

        _promptQueue.Remove(id);
        if (_queueManuallyPaused || _queuePausePending)
            SetQueuePaused(false);
        ResetQueuePausedState();
        SyncQueuePanel();

        try
        {
            SquadDashTrace.Write("UI", $"Prompt sent: rightmost queued tab as quick-reply answer id={id}");
            _pec.PendingQueueItemCount = _promptQueue.Count;
            _pec.CurrentDispatchedItem = item;
            _pendingPromptIsSystemInjected = item.IsSystemInjected;
            _pendingPromptSuppressTranscript = ShouldSuppressQueuedPromptTranscript(item);
            await _pec.ExecutePromptAsync(
                ApplyFollowUpHeader(ApplyDictationAnnotation(item), id),
                addToHistory: !item.IsSystemInjected,
                clearPromptBox: false,
                displayPrompt: BuildQueuedPromptDisplayText(item));
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(DispatchRightmostQueuedTabAsQuickReplyAsync), ex);
        }
        finally
        {
            _pendingPromptIsSystemInjected = false;
            _pendingPromptSuppressTranscript = false;
            _pec.PendingQueueItemCount = 0;
            _pec.CurrentDispatchedItem = null;
            _loopFollowUpTcs?.TrySetResult(true);
        }
    }

    private PromptQueueItem? GetAutoDispatchCandidate()
        => _promptQueue.GetAutoDispatchCandidate(
            _activeTabId,
            IsQueueDispatchHeld,
            TourDummyTag,
            TourTypeTag);

    private bool CanAutoDispatchPromptQueue(string reason)
    {
        var recoveryAssessmentMayFinishBeforeRestart = _restartPending &&
            _pendingPlanRecoveryAssessment is not null &&
            _promptQueue.Items.Any(item => string.Equals(
                item.SourceTag, PlanRecoveryAssessmentQueueTag, StringComparison.Ordinal));
        if (_isPromptRunning || _queueDrainActive || IsNativeLoopRunning || _isClosing ||
            (_restartPending && !recoveryAssessmentMayFinishBeforeRestart))
            return false;

        if (_backgroundTaskPresenter.HasBackgroundTasks())
        {
            SquadDashTrace.Write(
                "Queue",
                $"Auto-dispatch blocked by active background work reason={reason} queueCount={_promptQueue.Count}");
            return false;
        }

        if (HasPendingDirectQuickReplyAgentFollowUp())
        {
            SquadDashTrace.Write(
                "Queue",
                $"Auto-dispatch blocked by direct named-agent quick reply follow-up reason={reason} queueCount={_promptQueue.Count} pending={_directQuickReplyAgentThreadIds.Count}");
            return false;
        }

        if (_loopFollowUpTcs != null)
        {
            SquadDashTrace.Write("Queue", $"Auto-dispatch blocked — loop follow-up TCS pending (loop owns dispatch) reason={reason}");
            return false;
        }

        return true;
    }

    private async Task DrainQueueAsync()
    {
        if (!CanAutoDispatchPromptQueue(nameof(DrainQueueAsync)))
        {
            SquadDashTrace.Write(
                "Queue",
                $"DrainQueueAsync: skipped running={_isPromptRunning} loop={IsNativeLoopRunning} closing={_isClosing} restart={_restartPending} background={_backgroundTaskPresenter.HasBackgroundTasks()}");
            return;
        }

        var item = GetAutoDispatchCandidate();
        if (item is null)
        {
            if (IsRightmostQueueTabActive())
                HandleRightmostTabHold();
            await MaybeFireQueuedLoopAsync();
            return;
        }

        // Silently discard items that have no text and no attachments.
        while (item is not null && IsEmptyQueueItem(item))
        {
            SquadDashTrace.Write("Queue", $"DrainQueueAsync: discarding empty item #{item.SequenceNumber}");
            _promptQueue.Remove(item.Id);
            _followUpAttachments.Remove(item.Id);
            SyncQueuePanel();
            item = GetAutoDispatchCandidate();
        }
        if (item is null)
        {
            if (IsRightmostQueueTabActive())
                HandleRightmostTabHold();
            await MaybeFireQueuedLoopAsync();
            return;
        }

        if (string.Equals(item.SourceTag, QueuedPlanStartTag, StringComparison.Ordinal))
        {
            _promptQueue.Remove(item.Id);
            SyncQueuePanel();
            if (!QueuedPlanStart.TryDecode(item.Text, out var request) || request is null)
            {
                AppendLine("⚠ A queued plan start was invalid and was discarded.",
                    (Brush)FindResource("SubtleText"));
                if (_promptQueue.Count > 0)
                    _ = DrainQueueAsync();
                return;
            }

            var plan = _planStore?.Load(request.PlanId);
            if (plan is null || PlanLifecycleStatus.IsTerminal(plan.LifecycleStatus))
            {
                AppendLine(
                    $"⚠ Queued start for plan “{request.DisplayName}” was discarded because the plan is no longer pending.",
                    (Brush)FindResource("SubtleText"));
                if (_promptQueue.Count > 0)
                    _ = DrainQueueAsync();
                return;
            }

            SquadDashTrace.Write("Queue", $"Dispatching queued plan start plan={request.PlanId}.");
            await StartOrResumeDurablePlanAsync(plan);
            return;
        }

        HandleOpenEditorsBeforeSend(item.Id);
        SquadDashTrace.Write("Queue", $"DrainQueueAsync: dispatching {DescribeQueueItemForTrace(item)} queueCount={_promptQueue.Count}");
        _promptQueue.Remove(item.Id);
        SyncQueuePanel();

        if (!item.IsSystemInjected)
            AppendLine($"📤 Dispatching queued item #{item.QueueNumber}…", (Brush)FindResource("SubtleText"));

        try
        {
            if (_remoteAccessActive && !item.IsFromRemote)
                _ = _bridge.BroadcastRcPromptAsync(item.Text);
            _pec.PendingQueueItemCount = _promptQueue.Count;
            _pec.CurrentDispatchedItem = item;
            AutoActivateCoordinatorTranscriptOnPromptSubmit();
            _queueDrainActive = true;
            _pendingPromptIsSystemInjected = item.IsSystemInjected;
            _pendingPromptSuppressTranscript = ShouldSuppressQueuedPromptTranscript(item);
            await _pec.ExecutePromptAsync(
                ApplyFollowUpHeader(ApplyDictationAnnotation(item), item.Id),
                addToHistory: !item.IsSystemInjected,
                clearPromptBox: false,
                displayPrompt: BuildQueuedPromptDisplayText(item));
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(DrainQueueAsync), ex);
        }
        finally
        {
            _queueDrainActive = false;
            _pendingPromptIsSystemInjected = false;
            _pendingPromptSuppressTranscript = false;
            _pec.PendingQueueItemCount = 0;
            _pec.CurrentDispatchedItem = null;
        }
        // setIsPromptRunning(false) deliberately defers loop resume while this queue dispatch is
        // still unwinding. Resume only after ExecutePromptAsync and its coordinator gate are done.
        if (_promptQueue.Count == 0)
            await MaybeFireQueuedLoopAsync();
        else if (CanAutoDispatchPromptQueue("queue-turn-complete") && GetAutoDispatchCandidate() is not null)
            _ = DrainQueueAsync();
    }

    private static string ApplyDictationAnnotation(PromptQueueItem item) =>
        item.IsDictated ? item.Text + "\n(some or all of this prompt was dictated by voice)" : item.Text;

    private static bool ShouldSuppressQueuedPromptTranscript(PromptQueueItem item) =>
        PlanProposalTranscriptPolicy.ShouldSuppressInternalTurn(item.SourceTag);

    private static string? BuildQueuedPromptDisplayText(PromptQueueItem item)
    {
        if (!item.IsSystemInjected)
            return null;

        return string.Equals(item.SourceTag, "decompose-repair", StringComparison.Ordinal)
            ? SystemTranscriptStatusPrefix +
              "SquadDash could not accept the task plan. The exact validation failure and complete schema " +
              "were sent back to AI automatically; waiting for one corrected plan now…"
            : string.Equals(item.SourceTag, "decompose-replan", StringComparison.Ordinal)
                ? SystemTranscriptStatusPrefix +
                  "SquadDash asked AI to replace the blocked plan step with smaller dependency-aware steps; waiting for the revised plan now…"
                : string.Equals(item.SourceTag, "plan-gate-response-repair", StringComparison.Ordinal)
                    ? SystemTranscriptStatusPrefix +
                      "SquadDash is repairing a missing approval-response classification. No plan state has changed…"
                    : string.Equals(
                        item.SourceTag,
                        PlanRepairReplayPolicy.TaskResultRepairSourceTag,
                        StringComparison.Ordinal)
                        ? SystemTranscriptStatusPrefix +
                          "Correcting the current step result without repeating implementation work…"
                        : null;
    }

    private static string DescribeQueueItemForTrace(PromptQueueItem item) =>
        $"id={ShortQueueItemId(item.Id)} seq={item.SequenceNumber} chars={item.Text.Length} hash={StableQueueTextHash(item.Text)} dictated={item.IsDictated} remote={item.IsFromRemote} system={item.IsSystemInjected} sim={item.IsSimEntry}";

    private static string DescribeQueueForTrace(IReadOnlyList<PromptQueueItem> items) {
        if (items.Count == 0)
            return "[]";

        return "[" + string.Join(", ", items.Select(DescribeQueueItemForTrace)) + "]";
    }

    private string QueueLastChangedForTrace() =>
        _conversationManager.ConversationState.QueueLastChangedAt?.ToUniversalTime().ToString("O") ?? "null";

    private static string ShortQueueItemId(string id) =>
        id.Length <= 8 ? id : id[..8];

    private static string StableQueueTextHash(string text) {
        unchecked
        {
            const uint offset = 2166136261;
            const uint prime = 16777619;
            var hash = offset;
            foreach (var ch in text)
            {
                hash ^= ch;
                hash *= prime;
            }
            return hash.ToString("x8");
        }
    }

    // Returns true when a queued item has no text and no attachments — it should be silently discarded.
    private bool IsEmptyQueueItem(PromptQueueItem item) =>
        string.IsNullOrWhiteSpace(item.Text) &&
        (!_followUpAttachments.TryGetValue(item.Id, out var atts) || atts.Count == 0);

    private async Task DrainQueueIfNeededAsync()
    {
        // During a decompose loop the queue must not auto-drain — the loop orchestrates iterations.
        if (_activeDecomposeGroupId is not null) return;

        while (CanAutoDispatchPromptQueue(nameof(DrainQueueIfNeededAsync)) && !LastTurnNeedsInput())
        {
            var item = GetAutoDispatchCandidate();
            if (item is null) break;

            if (string.Equals(item.SourceTag, PlanContinuationQueueTag, StringComparison.Ordinal))
            {
                _promptQueue.Remove(item.Id);
                SyncQueuePanel();
                SquadDashTrace.Write("Queue", "Discarded stale plan-continuation queue item outside plan execution.");
                continue;
            }

            if (string.Equals(item.SourceTag, QueuedLoopJobTag, StringComparison.Ordinal))
            {
                _promptQueue.Remove(item.Id);
                SyncQueuePanel();
                if (!QueuedLoopJob.TryDecode(item.Text, out var job) || job is null)
                {
                    AppendLoopOutputLine("⚠ A queued filtered loop was invalid and was discarded.", LoopLifecycleBrush);
                    continue;
                }

                SquadDashTrace.Write("Queue",
                    $"Starting queued loop job label='{job.DisplayLabel}' tasks={job.TaskCount}.");
                await QueueOrStartLoopAsync(LoopMode.NativeAgents, job.Execution);
                break;
            }

            if (string.Equals(item.SourceTag, QueuedPlanStartTag, StringComparison.Ordinal))
            {
                _promptQueue.Remove(item.Id);
                SyncQueuePanel();
                if (!QueuedPlanStart.TryDecode(item.Text, out var request) || request is null)
                {
                    AppendLine("⚠ A queued plan start was invalid and was discarded.",
                        (Brush)FindResource("SubtleText"));
                    continue;
                }

                var plan = _planStore?.Load(request.PlanId);
                if (plan is null || PlanLifecycleStatus.IsTerminal(plan.LifecycleStatus))
                {
                    AppendLine(
                        $"⚠ Queued start for plan “{request.DisplayName}” was discarded because the plan is no longer pending.",
                        (Brush)FindResource("SubtleText"));
                    continue;
                }

                SquadDashTrace.Write("Queue", $"Dispatching queued plan start plan={request.PlanId}.");
                await StartOrResumeDurablePlanAsync(plan);
                break;
            }

            // Silently discard items that have no text and no attachments.
            if (IsEmptyQueueItem(item))
            {
                SquadDashTrace.Write("Queue", $"DrainQueueIfNeededAsync: discarding empty item #{item.SequenceNumber}");
                _promptQueue.Remove(item.Id);
                _followUpAttachments.Remove(item.Id);
                SyncQueuePanel();
                continue;
            }

            HandleOpenEditorsBeforeSend(item.Id);
            SquadDashTrace.Write("Queue", $"DrainQueueIfNeededAsync: dispatching {DescribeQueueItemForTrace(item)} queueCount={_promptQueue.Count}");
            SquadDashTrace.Write("UI", "Prompt sent: queue drain (item dispatched)");
            _promptQueue.Remove(item.Id);
            SyncQueuePanel();

            if (!item.IsSystemInjected)
                AppendLine($"📤 Dispatching queued item #{item.QueueNumber}…", (Brush)FindResource("SubtleText"));

            try
            {
                if (_remoteAccessActive && !item.IsFromRemote)
                    _ = _bridge.BroadcastRcPromptAsync(item.Text);
                _pec.PendingQueueItemCount = _promptQueue.Count;
                _pec.CurrentDispatchedItem = item;
                _queueDrainActive = true;
                _pendingPromptIsSystemInjected = item.IsSystemInjected;
                _pendingPromptSuppressTranscript = ShouldSuppressQueuedPromptTranscript(item);
                await _pec.ExecutePromptAsync(
                    ApplyFollowUpHeader(ApplyDictationAnnotation(item), item.Id),
                    addToHistory: !item.IsSystemInjected,
                    clearPromptBox: false,
                    displayPrompt: BuildQueuedPromptDisplayText(item));
            }
            catch (Exception ex)
            {
                HandleUiCallbackException(nameof(DrainQueueIfNeededAsync), ex);
                break;
            }
            finally
            {
                _queueDrainActive = false;
                _pendingPromptIsSystemInjected = false;
                _pendingPromptSuppressTranscript = false;
                _pec.PendingQueueItemCount = 0;
                _pec.CurrentDispatchedItem = null;
            }
        }

        if (_isClosing || _restartPending)
        {
            SquadDashTrace.Write("Queue", $"DrainQueueIfNeededAsync: aborted closing={_isClosing} restart={_restartPending} remaining={_promptQueue.Count}");
            if (IsNativeLoopRunning)
                _loopController.RequestStop();
            return;
        }

        if (LastTurnNeedsInput() && _promptQueue.Count > 0)
            HandleQueuePausedForInput();
        else if (IsRightmostQueueTabActive())
            HandleRightmostTabHold();

        await MaybeFireQueuedLoopAsync();
    }

    private void DrainQueueAfterBackgroundWorkChanged(string reason)
    {
        if (_promptQueue.Count == 0)
            return;

        if (!CanAutoDispatchPromptQueue(reason))
            return;

        if (LastTurnNeedsInput())
        {
            HandleQueuePausedForInput();
            return;
        }

        if (GetAutoDispatchCandidate() is not null)
            _ = DrainQueueIfNeededAsync();
        else if (IsRightmostQueueTabActive())
            HandleRightmostTabHold();
    }

    /// <summary>
    /// Drains all queued prompts one at a time before a loop iteration fires.
    /// Unlike the normal drain paths this runs while <see cref="IsNativeLoopRunning"/>
    /// is true — the loop intentionally pauses to let queued items complete first.
    /// </summary>
    private async Task DrainQueueBeforeLoopIterationAsync()
    {
        bool dispatched = false;
        while (!_isPromptRunning && !_isClosing && !_restartPending && !HasPendingDirectQuickReplyAgentFollowUp() && !LastTurnNeedsInput())
        {
            var item = GetAutoDispatchCandidate();
            if (item is null) break;

            if (string.Equals(item.SourceTag, PlanContinuationQueueTag, StringComparison.Ordinal))
            {
                _promptQueue.Remove(item.Id);
                SyncQueuePanel();
                SquadDashTrace.Write("Queue",
                    $"Plan continuation released at iteration boundary plan={_activeDecomposeGroupId ?? "(none)"}.");
                break;
            }


            // A loop job is serialized behind the currently-running loop. It is a host
            // operation, never an AI prompt, so leave it in place until this loop stops.
            if (string.Equals(item.SourceTag, QueuedLoopJobTag, StringComparison.Ordinal))
                break;

            // A plan start waits for the currently-running loop to release coordinator
            // ownership. It must never be submitted to AI as if its encoded payload were a prompt.
            if (string.Equals(item.SourceTag, QueuedPlanStartTag, StringComparison.Ordinal))
                break;

            // Silently discard items that have no text and no attachments.
            if (IsEmptyQueueItem(item))
            {
                SquadDashTrace.Write("Queue", $"DrainQueueBeforeLoopIterationAsync: discarding empty item #{item.SequenceNumber}");
                _promptQueue.Remove(item.Id);
                _followUpAttachments.Remove(item.Id);
                SyncQueuePanel();
                continue;
            }

            dispatched = true;
            HandleOpenEditorsBeforeSend(item.Id);
            SquadDashTrace.Write("Queue", $"DrainQueueBeforeLoopIterationAsync: dispatching {DescribeQueueItemForTrace(item)} queueCount={_promptQueue.Count}");
            _promptQueue.Remove(item.Id);
            SyncQueuePanel();

            if (!item.IsSystemInjected)
                AppendLine("📤 Dispatching queued item…", (Brush)FindResource("SubtleText"));

            try
            {
                if (_remoteAccessActive && !item.IsFromRemote)
                    _ = _bridge.BroadcastRcPromptAsync(item.Text);
                _pec.PendingQueueItemCount = _promptQueue.Count;
                _pec.CurrentDispatchedItem = item;
                _queueDrainActive = true;
                _pendingPromptIsSystemInjected = item.IsSystemInjected;
                _pendingPromptSuppressTranscript = ShouldSuppressQueuedPromptTranscript(item);
                await _pec.ExecutePromptAsync(
                    ApplyFollowUpHeader(ApplyDictationAnnotation(item), item.Id),
                    addToHistory: !item.IsSystemInjected,
                    clearPromptBox: false,
                    displayPrompt: BuildQueuedPromptDisplayText(item));
            }
            catch (Exception ex)
            {
                HandleUiCallbackException(nameof(DrainQueueBeforeLoopIterationAsync), ex);
                break;
            }
            finally
            {
                _queueDrainActive = false;
                _pendingPromptIsSystemInjected = false;
                _pendingPromptSuppressTranscript = false;
                _pec.PendingQueueItemCount = 0;
                _pec.CurrentDispatchedItem = null;
            }
        }

        // A queued prompt produced quick replies that need user input before the loop
        // can continue.  Stop the loop gracefully (the interrupt flag causes
        // OnNativeLoopStopped to re-queue it so it resumes once the user responds).
        // Only interrupt if we actually dispatched items this cycle — stale quick-reply
        // state from the loop's own previous iteration must not be treated as a pause signal.
        if (dispatched && LastTurnNeedsInput())
        {
            _loopInterruptedByQueue = true;
            SquadDashTrace.Write("Queue", "Loop paused — dispatched queue item produced quick replies requiring user input; _loopInterruptedByQueue set, loop RequestStop called.");
            _loopController.RequestStop();
            HandleQueuePausedForInput();
            return;
        }

        // If a restart or shutdown arrived while we were draining (or was already pending
        // before we entered), stop the loop so the next iteration never starts.
        if (_isClosing || _restartPending)
        {
            SquadDashTrace.Write("Loop", $"DrainQueueBeforeLoopIterationAsync: stopping loop before next iteration restart={_restartPending} closing={_isClosing}");
            _loopController.RequestStop();
            return;
        }

        if (_activeDecomposeGroupId is not null && _CodeHealthGroupRunner is not null)
        {
            var durablePlan = _planStore?.Load(_activeDecomposeGroupId);
            if (durablePlan is not null && TryActivateValidationForNextIteration(durablePlan))
                return;
            if (durablePlan is not null && PlanExecutionBoundaryPolicy.HasFailedValidation(durablePlan))
            {
                SquadDashTrace.Write(
                    "Loop",
                    $"Executing Plan stopped at failed validation group={_activeDecomposeGroupId}.");
                AppendLoopOutputLine(
                    "⏹ Executing Plan stopped — a contract validation failed.",
                    LoopLifecycleBrush);
                SuppressLoopResume("plan-validation-failed");
                _loopController.RequestStop();
                return;
            }

            var groupState = TrackFirstEligiblePlanStep(_activeDecomposeGroupId);
            var boundaryAction = PlanExecutionBoundaryPolicy.ResolvePreIteration(
                durablePlan,
                groupState);
            if (boundaryAction == PlanPreIterationBoundaryAction.Continue)
            {
                if (groupState == DecomposeGroupExecutionState.AwaitingApproval)
                {
                    SquadDashTrace.Write(
                        "Loop",
                        $"Executing Plan retained at non-human boundary group={_activeDecomposeGroupId}; awaiting validation or dependency progress.");
                }
                return;
            }
            if (boundaryAction == PlanPreIterationBoundaryAction.ActivateApproval &&
                durablePlan is not null)
            {
                var readyGateIds = ApprovalGateReadinessEvaluator.GetReadyGateIds(
                    ApprovalGateReadinessEvaluator.EvaluateGates(durablePlan));
                var boundaryTaskId = durablePlan.ApprovalGates
                    .Where(gate => readyGateIds.Contains(gate.GateId, StringComparer.Ordinal))
                    .SelectMany(gate => gate.AfterTaskIds)
                    .LastOrDefault()
                    ?? durablePlan.Tasks.LastOrDefault(task =>
                        task.Status is PlanTaskStatus.Complete or PlanTaskStatus.Superseded)?.TaskId
                    ?? _activeDecomposeGroupId;
                SquadDashTrace.Write(
                    "Loop",
                    $"Executing Plan activating approval before next iteration group={_activeDecomposeGroupId} task={boundaryTaskId}.");
                await ProcessPlanApprovalsAfterStepAsync(
                    _activeDecomposeGroupId,
                    durablePlan.Revision,
                    boundaryTaskId,
                    groupState,
                    durablePlan);
                return;
            }
            if (boundaryAction == PlanPreIterationBoundaryAction.Stop)
            {
                SquadDashTrace.Write(
                    "Loop",
                    $"Executing Plan stopped before next iteration group={_activeDecomposeGroupId} state={groupState}; no unrelated task will be selected.");
                AppendLoopOutputLine(
                    $"⏹ Executing Plan stopped — group {_activeDecomposeGroupId} is {groupState.ToString().ToLowerInvariant()}.",
                    LoopLifecycleBrush);
                SuppressLoopResume($"plan-{groupState.ToString().ToLowerInvariant()}");
                _loopController.RequestStop();
            }
        }
    }

    private bool LastTurnNeedsInput()
    {
        // Quick replies are active (AI gave the user choices to pick from).
        if (_lastQuickReplyEntry?.AllowQuickReplies == true)
        {
            SquadDashTrace.Write("Queue", "LastTurnNeedsInput: true — AllowQuickReplies is set on _lastQuickReplyEntry.");
            return true;
        }

        // AI explicitly signalled it needs human input before the queue continues.
        var lastResponseText = CoordinatorThread.CurrentTurn?.ResponseTextBuilder.ToString();
        var hasSentinel = lastResponseText?.Contains(PromptExecutionController.QueueAwaitInputSentinel,
                                                     StringComparison.Ordinal) == true;
        if (hasSentinel)
            SquadDashTrace.Write("Queue", "LastTurnNeedsInput: true — QueueAwaitInputSentinel found in last response text.");
        return hasSentinel;
    }

    private bool _queuePausedNotificationFired;
    private bool _rightmostTabHoldNotificationFired;

    private void HandleQueuePausedForInput()
    {
        // Only show the message once per pause to avoid spam.
        if (_queuePausedNotificationFired) return;
        _queuePausedNotificationFired = true;
        SquadDashTrace.Write("Queue", "Loop paused for user input — quick reply notification fired.");

        SyncSendButton();
        BuildShortcutsHint();
        SetQueuePaused(_queueManuallyPaused);

        _ = _pushNotificationService.NotifyEventAsync(
            "quick_reply_needed",
            "SquadDash",
            "AI needs your input before the queue continues.");
    }

    private void ResetQueuePausedState()
    {
        _queuePausedNotificationFired = false;
        _rightmostTabHoldNotificationFired = false;
        SyncSendButton();
        BuildShortcutsHint();
    }

    /// <summary>
    /// Returns true when the currently active queue tab is the rightmost one —
    /// i.e. the oldest/first-to-dispatch item (<c>items[0]</c>) is being edited.
    /// In this state the entire queue is held until the user clicks Send or switches tabs.
    /// </summary>
    private bool IsRightmostQueueTabActive() =>
        _activeTabId is not null &&
        _promptQueue.Count > 0 &&
        _promptQueue.Items[0].Id == _activeTabId &&
        !_promptQueue.Items[0].IsLocked;

    private int? GetActiveQueueTabIndex()
    {
        if (_activeTabId is null) return null;
        for (var i = 0; i < _promptQueue.Items.Count; i++)
            if (_promptQueue.Items[i].Id == _activeTabId) return i;
        return null;
    }

    private void HandleRightmostTabHold()
    {
        if (_rightmostTabHoldNotificationFired) return;
        _rightmostTabHoldNotificationFired = true;

        AppendLine("✋ Queued prompt is active — paused for edits. Click **Send** (or click another tab) to submit immediately.");

        SyncSendButton();

        _ = Dispatcher.InvokeAsync(() => {
            var isDark = Resources.Contains("IsDarkTheme") && (bool)Resources["IsDarkTheme"];
            var theme  = isDark ? CalloutTheme.Dark : CalloutTheme.Light;
            var fontSize = Resources.Contains("FontSizeBody") ? Convert.ToDouble(Resources["FontSizeBody"]) : 13.0;
            FrameworkElement target = GetActiveQueueTabBorder() ?? (FrameworkElement)QueueStatusLabel;
            FrmUltimateCallout.ShowCalloutBesideTarget(
                "The active queue tab is pausing dispatch.\n\nClick **Send** to submit it now, or select a different tab to drain the queue.",
                target,
                width: 300,
                theme: theme,
                fontSize: fontSize,
                placement: CalloutPlacement.North);
        }, System.Windows.Threading.DispatcherPriority.Loaded);
    }


    private async Task MaybeFireQueuedLoopAsync()
    {
        if (_interruptedPromptRecoveryHold is not null)
        {
            SquadDashTrace.Write(
                "Loop",
                $"Loop resume deferred by interrupted-prompt recovery id={_interruptedPromptRecoveryHold.RecoveryId}.");
            return;
        }

        if (_pendingDecomposeRecoveryResponse is not null || _pendingDecomposeRecoveryDispatchScheduled)
        {
            SquadDashTrace.Write(
                "Loop",
                "Queued loop resume deferred because a structured plan-recovery response owns the next execution transition.");
            return;
        }

        bool shouldResume = _loopQueued || _loopInterruptedByQueue || _loopPausedForQuickReply;
        if (!shouldResume || _isPromptRunning || IsLoopRunning || _queueDrainActive) return;
        if (!_promptQueue.IsDrained)
        {
            SquadDashTrace.Write(
                "Loop",
                $"MaybeFireQueuedLoopAsync: resume deferred until queue actually drains count={_promptQueue.Count} " +
                $"candidate={(GetAutoDispatchCandidate() is null ? "none" : "available")} activeTab={_activeTabId ?? "draft"}.");
            return;
        }
        bool wasQueueResume = _loopQueued || _loopInterruptedByQueue;
        bool wasQrResume    = _loopPausedForQuickReply;
        var queuedPlanId = wasQueueResume
            ? _activeDecomposeGroupId ??
              _conversationManager.ConversationState.ActiveLoopExecution?.DecomposeGroupId
            : null;
        int resumeFromIteration = Math.Max(_loopCurrentIteration, _loopQueuedResumeFromIteration);
        _loopQueued = false;
        _loopQueuedResumeFromIteration = 0;
        _loopInterruptedByQueue = false;
        _loopPausedForQuickReply = false;
        _conversationManager.UpdateQueuedPromptsState(
            _promptQueue.Items, _followUpAttachments,
            queueRightmostHeld: IsRightmostQueueTabActive(),
            loopQueuedToDequeue: false,
            activeDraftSimEntry: _pec.ActiveDraftSimEntry,
            activeTabIndex: GetActiveQueueTabIndex());
        SyncLoopPanel();
        try
        {
            var resumeMsg = wasQueueResume
                ? $"▶ Loop starting — {LoopTimestamp()} — queue drained."
                : $"▶ Loop resuming — {LoopTimestamp()} — quick replies answered.";
            SquadDashTrace.Write("Loop", $"MaybeFireQueuedLoopAsync: starting queued loop resumeFromIteration={resumeFromIteration} wasQueueResume={wasQueueResume} wasQrResume={wasQrResume} queueCount={_promptQueue.Count}");
            AppendLoopOutputLine(resumeMsg, LoopLifecycleBrush);
            var claimed = await ResumeLoopImmediateAsync(resumeFromIteration);
            if (!claimed)
                throw new InvalidOperationException("The saved loop execution could not be reclaimed safely.");
            if (wasQueueResume)
                AnnouncePlanQueueDrainResume(queuedPlanId);
        }
        catch (Exception ex)
        {
            var execution = _conversationManager.ConversationState.ActiveLoopExecution;
            AppendLoopOutputLine($"⏸ Queued loop was not resumed: {ex.Message}", LoopLifecycleBrush);
            SquadDashTrace.Write("Loop", $"Queued loop resume refused: {ex}");
            if (!string.IsNullOrWhiteSpace(execution?.DecomposeGroupId))
                InterruptPlanAfterFailedResume(execution, ex.Message);
            else
                ShowSystemTranscriptEntry(
                    $"Loop recovery paused: {ex.Message} The saved loop details were preserved.");
        }
    }

    private void AnnouncePlanQueueDrainPause()
    {
        if (_planQueueDrainPauseAnnounced)
            return;

        var planId = _activeDecomposeGroupId ??
                     _conversationManager.ConversationState.ActiveLoopExecution?.DecomposeGroupId;
        if (string.IsNullOrWhiteSpace(planId) || _planStore?.Load(planId) is not { } plan)
            return;

        _planQueueDrainPauseAnnounced = true;
        ShowSystemTranscriptEntry(PlanLoopTranscriptPresentation.BuildQueueDrainPauseMessage(plan));
    }

    private void AnnouncePlanQueueDrainResume(string? queuedPlanId)
    {
        var planId = queuedPlanId ??
                     _activeDecomposeGroupId ??
                     _conversationManager.ConversationState.ActiveLoopExecution?.DecomposeGroupId;
        var plan = string.IsNullOrWhiteSpace(planId) ? null : _planStore?.Load(planId);
        _planQueueDrainPauseAnnounced = false;
        if (!string.IsNullOrWhiteSpace(planId) && plan is null)
        {
            SquadDashTrace.Write(
                "Loop",
                $"Suppressed queued-plan resume announcement because durable plan {planId} could not be loaded.");
            return;
        }
        if (plan is not null && !PlanLoopTranscriptPresentation.ShouldAnnounceQueueDrainResume(plan))
        {
            SquadDashTrace.Write(
                "Loop",
                $"Suppressed queued-plan resume announcement because durable plan {plan.PlanId} is {plan.LifecycleStatus}.");
            return;
        }
        ShowSystemTranscriptEntry(plan is null
            ? "Queued prompts complete. Resuming the plan."
            : PlanLoopTranscriptPresentation.BuildQueueDrainResumeMessage(
                plan,
                _CodeHealthGroupRunner?.CurrentStepId,
                _CodeHealthGroupRunner?.GetCurrentStepTitle()));
    }

    private void BeginQueueStateHydration()
    {
        _queueStateHydrationInProgress = true;
        _conversationManager.BeginQueuedPromptsStateHydration();
    }

    private int? FlushSelectedQueueEditorToDraft()
    {
        var activeTabIndex = GetActiveQueueTabIndex();
        if (_activeTabId is null)
            return activeTabIndex;

        var current = _promptQueue.Items.FirstOrDefault(item => item.Id == _activeTabId);
        if (current is not null && !current.IsLocked)
        {
            current.Text = PromptTextBox.Text;
            current.CaretIndex = PromptTextBox.CaretIndex;
            current.SelectionStart = PromptTextBox.SelectionStart;
            current.SelectionLength = PromptTextBox.SelectionLength;
        }

        _activeTabId = null;
        SetPromptTextBoxLogicalBuffer(
            _queuePreEditDraft ?? string.Empty,
            _queuePreEditDraftCaretIndex,
            _queuePreEditDraftSelectionStart,
            _queuePreEditDraftSelectionLength,
            "queue-editor-flush");
        _queuePreEditDraft = null;
        ApplyPromptEditorLockState();
        return activeTabIndex;
    }

    private bool SaveAndDetachQueueForWorkspaceTransition()
    {
        if (_currentWorkspace is not null)
        {
            var queueWasRightmostHeld = IsRightmostQueueTabActive();
            var activeTabIndex = FlushSelectedQueueEditorToDraft();
            _conversationManager.UpdateQueuedPromptsState(
                _promptQueue.Items,
                _followUpAttachments,
                queueRightmostHeld: queueWasRightmostHeld,
                loopQueuedToDequeue: _loopQueued,
                activeDraftSimEntry: _pec.ActiveDraftSimEntry,
                activeTabIndex: activeTabIndex,
                queueDayCounter: _queueDayCounter,
                queueCounterDate: _queueCounterDate);
            if (!_conversationManager.TrySaveWorkspaceStateForTransition("open-workspace"))
                return false;
        }

        BeginQueueStateHydration();
        _promptQueue.Clear();
        _followUpAttachments.Clear();
        _activeTabId = null;
        _queuePreEditDraft = null;
        _queuePreEditDraftCaretIndex = 0;
        _queuePreEditDraftSelectionStart = 0;
        _queuePreEditDraftSelectionLength = 0;
        _queueManuallyPaused = false;
        _queueRecoveryHold = null;
        _interruptedPromptRecoveryHold = null;
        _pendingInterruptedPromptRecoveryPresentation = null;
        _pendingInterruptedPromptRecoveryRestoredAfterRestart = false;
        _pendingAutomaticInterruptedPromptRecovery = null;
        _loopStoppedForInterruptedPromptRecovery = false;
        _queuePausePending = false;
        _rightmostTabHoldNotificationFired = false;
        _loopQueued = false;
        _loopQueuedResumeFromIteration = 0;
        _queueDayCounter = 0;
        _queueCounterDate = string.Empty;
        _pec.ActiveDraftSimEntry = null;
        SetPromptTextBoxLogicalBuffer(string.Empty, 0, 0, 0, "workspace-queue-detach");
        SyncQueuePanel();
        return true;
    }

    private void CompleteQueueStateHydration()
    {
        _queueStateHydrationInProgress = false;
        _conversationManager.CompleteQueuedPromptsStateHydration();
        SyncQueuePanel();
        SquadDashTrace.Write(
            "Queue",
            $"Queue hydration completed: count={_promptQueue.Count} manualPause={_queueManuallyPaused} recoveryHold={_queueRecoveryHold?.PlanId ?? "none"} held={IsRightmostQueueTabActive()} activeTabIndex={GetActiveQueueTabIndex()?.ToString() ?? "null"} loopQueued={_loopQueued}");
        TryPresentPendingInterruptedPromptRecovery();
        TryStartPendingAutomaticInterruptedPromptRecovery();
    }

    private void SyncQueuePanel()
    {
        PreserveVisibleTranscriptViewportsThroughLayout(
            SyncQueuePanelCore,
            "queue panel synchronized");
    }

    private void SyncQueuePanelCore()
    {
        var swFull = Stopwatch.StartNew();
        var items = _promptQueue.Items;
        if (_activeTabId is not null && items.All(item => item.Id != _activeTabId))
        {
            _activeTabId = null;
            SetPromptTextBoxLogicalBuffer(
                _queuePreEditDraft ?? string.Empty,
                (_queuePreEditDraft ?? string.Empty).Length,
                0,
                0,
                "queue-removed-active-item");
            _queuePreEditDraft = null;
            ApplyPromptEditorLockState();
        }
        SetPromptStripVisibilityPreservingViewports(
            QueueTabBorder,
            items.Count > 0 || IsQueueDispatchHeld ? Visibility.Visible : Visibility.Collapsed,
            "queue strip visibility changed");
        QueueTabStrip.Children.Clear();

        if (items.Count > 0)
        {
            QueueTabStrip.Children.Add(CreateQueueTab(null, "Active Draft",
                tooltip: "This prompt has not been queued yet."));
            // Render newest item first (left) → oldest item last (far right).
            // The next-to-dispatch item is the first non-editing item in the list,
            // not necessarily the one with SequenceNumber==1 (items may have been dequeued
            // leaving gaps, so we identify the candidate by Id rather than by sequence number).
            var nextReadyId = items.FirstOrDefault(i => !i.IsEditing)?.Id;
            foreach (var item in items.Reverse())
            {
                bool isNext = item.Id == nextReadyId;
                var isPlanContinuation = string.Equals(
                    item.SourceTag, PlanContinuationQueueTag, StringComparison.Ordinal);
                var isQueuedLoop = string.Equals(
                    item.SourceTag, QueuedLoopJobTag, StringComparison.Ordinal);
                var isQueuedPlanStart = string.Equals(
                    item.SourceTag, QueuedPlanStartTag, StringComparison.Ordinal);
                var queuedLoop = isQueuedLoop && QueuedLoopJob.TryDecode(item.Text, out var decodedJob)
                    ? decodedJob
                    : null;
                var queuedPlanStart = isQueuedPlanStart &&
                                      QueuedPlanStart.TryDecode(item.Text, out var decodedPlanStart)
                    ? decodedPlanStart
                    : null;
                var label = !string.IsNullOrWhiteSpace(item.DisplayLabel)
                    ? item.DisplayLabel!
                    : isPlanContinuation
                    ? "Plan continuation"
                    : queuedLoop is not null ? queuedLoop.DisplayLabel
                    : isNext ? $"Queue #{item.QueueNumber}" : $"#{item.QueueNumber}";
                var tooltip = isPlanContinuation
                    ? "The plan advances one step when this item reaches the front. Drag it to place queued prompts before or after the next plan step."
                    : queuedLoop is not null
                        ? $"This filtered loop is queued behind the active loop ({queuedLoop.TaskCount} tasks)."
                    : queuedPlanStart is not null
                        ? $"Start “{queuedPlanStart.DisplayName}” after active and earlier queued work finishes. Delete this item to cancel the start."
                    : isNext ? "This prompt is next in the Squad queue."
                             : "This item is in the Squad queue.";
                QueueTabStrip.Children.Add(CreateQueueTab(item.Id, label, tooltip));
                if (item.Id == _priorityFeedbackId)
                    QueueTabStrip.Children.Add(CreatePriorityFeedbackLabel());
            }

        }

        SyncQueueTabHint();
        _conversationManager.UpdateQueuedPromptsState(items, _followUpAttachments, queueRightmostHeld: IsRightmostQueueTabActive(), loopQueuedToDequeue: _loopQueued, activeDraftSimEntry: _pec.ActiveDraftSimEntry, activeTabIndex: GetActiveQueueTabIndex(), queueDayCounter: _queueDayCounter, queueCounterDate: _queueCounterDate);
        SyncSendButton();
        BuildShortcutsHint();
        // Keep play/pause button icon/label in sync with current paused state.
        SetQueuePaused(_queueManuallyPaused);
        SyncPromptTextBoxSimBorder();
        SquadDashTrace.Write(TraceCategory.Performance,
            $"SyncQueuePanel: full rebuild of {items.Count} queued tabs in {swFull.ElapsedMilliseconds}ms");
        // Keep loop status in sync when queue count changes while loop is queued.
        if (_loopQueued)
            SyncLoopPanel();
    }

    private void SyncQueueTabHint()
    {
        // Remove any existing hint block.
        var existing = QueueTabStrip.Children.OfType<TextBlock>()
                           .FirstOrDefault(tb => tb.Tag as string == "QueueActiveTabHint");
        if (existing is not null)
            QueueTabStrip.Children.Remove(existing);

        if (_activeTabId is null) return;  // draft tab — no hint needed

        // When the active tab IS the rightmost tab and the queue is already paused
        // waiting for it, the warning is redundant — suppress it.
        if (IsRightmostQueueTabActive() && !_isPromptRunning) return;

        var items = _promptQueue.Items;
        var nextReadyId = items.FirstOrDefault(i => !i.IsEditing)?.Id;
        var activeItem = items.FirstOrDefault(i => i.Id == _activeTabId);
        if (activeItem is null) return;

        bool isNext = activeItem.Id == nextReadyId;
        var activeTabLabel = isNext ? $"Queue #{activeItem.QueueNumber}" : $"#{activeItem.QueueNumber}";
        var hint = new TextBlock
        {
            Text = $"Automatic prompting will pause when it's time to send this active tab (\"{activeTabLabel}\")",
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(10, 0, 8, 0),
            FontStyle = FontStyles.Italic,
            Tag = "QueueActiveTabHint",
        };
        hint.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeSmall");
        hint.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
        QueueTabStrip.Children.Add(hint);
    }

    private void SetQueuePaused(bool paused)
    {
        _queueManuallyPaused = paused;
        if (!paused && _queueRecoveryHold is null && _interruptedPromptRecoveryHold is null)
            _queueStopPauseState.RecordQueueResumed();
        var dispatchHeld = IsQueueDispatchHeld;
        EditPauseQueueDrainMenuItem.Visibility  = dispatchHeld ? Visibility.Collapsed : Visibility.Visible;
        EditResumeQueueDrainMenuItem.Visibility = dispatchHeld ? Visibility.Visible   : Visibility.Collapsed;
        // When pausing with no queued items the border is normally Collapsed;
        // make it visible so the play ▶ button and status label are shown.
        if (dispatchHeld && _promptQueue.Items.Count == 0)
            SetPromptStripVisibilityPreservingViewports(
                QueueTabBorder,
                Visibility.Visible,
                "empty queue entered held state");
        else if (!dispatchHeld && _promptQueue.Items.Count == 0)
            SetPromptStripVisibilityPreservingViewports(
                QueueTabBorder,
                Visibility.Collapsed,
                "empty queue left held state");
        if (paused && _isPromptRunning)
        {
            // Case 2: Pause requested while a turn is in progress → pending.
            _queuePausePending = true;
            QueueStatusLabel.Text = "Pausing after turn completes\u2026";
            QueuePlayPauseButton.ToolTip = MakeThemedToolTip("Click to cancel pause and resume automatic prompt queue processing.");
            // Show play icon ▶ — clicking again will cancel the pending pause.
            QueuePlayIcon.Visibility  = Visibility.Visible;
            QueuePauseIcon.Visibility = Visibility.Collapsed;
            // Pending is not fully-paused — ensure no stale styling.
            QueueStatusLabel.ClearValue(TextBlock.BackgroundProperty);
            QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
        }
        else
        {
            _queuePausePending = false;
            var qrbSuffix = _queuePausedNotificationFired ? " (AI waiting for your response)" : string.Empty;

            QueuePlayPauseButton.ToolTip = MakeThemedToolTip(dispatchHeld ? "Click to resume automatic prompt queue processing." : "Click to pause automatic prompt queue processing.");
            // Icon shows what clicking will DO (inverted from current state):
            //   Running → pause icon ⏸ (click will pause)
            //   Paused  → play icon  ▶ (click will resume)
            QueuePlayIcon.Visibility  = dispatchHeld ? Visibility.Visible   : Visibility.Collapsed;
            QueuePauseIcon.Visibility = dispatchHeld ? Visibility.Collapsed : Visibility.Visible;

            // High-contrast styling: black/yellow when paused, default when running.
            if (paused)
            {
                QueueStatusLabel.Text = $"Queue is paused{qrbSuffix}";
                QueueStatusLabel.SetResourceReference(TextBlock.BackgroundProperty, "ToastSurface");
                QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "ToastText");
            }
            else if (_interruptedPromptRecoveryHold is not null)
            {
                QueueStatusLabel.Text = "Queue is held for interrupted work recovery";
                QueueStatusLabel.SetResourceReference(TextBlock.BackgroundProperty, "ToastSurface");
                QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "ToastText");
                QueuePlayPauseButton.ToolTip = MakeThemedToolTip(
                    "Use the recovery card in the transcript before queued prompts can continue.");
            }
            else if (_queueRecoveryHold is not null)
            {
                QueueStatusLabel.Text = "Queue is held for plan recovery";
                QueueStatusLabel.SetResourceReference(TextBlock.BackgroundProperty, "ToastSurface");
                QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "ToastText");
                QueuePlayPauseButton.ToolTip = MakeThemedToolTip(
                    "Click to release the recovery hold and drain queued prompts. The interrupted plan remains preserved.");
            }
            else if (IsRightmostQueueTabActive())
            {
                // Queue is draining but blocked by the active (rightmost) tab.
                // Style the "(active tab pausing dispatch)" portion yellow-on-black,
                // matching the manual-pause indicator, to signal the hold clearly.
                QueueStatusLabel.ClearValue(TextBlock.BackgroundProperty);
                QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
                QueueStatusLabel.Inlines.Clear();
                QueueStatusLabel.Inlines.Add(new Run("Queue is draining "));
                QueueStatusLabel.Inlines.Add(new Run("(active tab pausing dispatch)")
                {
                    Foreground = Brushes.Yellow,
                    Background = Brushes.Black,
                });
            }
            else
            {
                QueueStatusLabel.Text = $"Queue is draining{qrbSuffix}";
                QueueStatusLabel.ClearValue(TextBlock.BackgroundProperty);
                QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
            }
        }
        // Save true when paused, false (not null) when resuming. Using null would cause the
        // merge logic in SaveDocsPanelState to preserve any stale "true" from a prior session.
        if (!_queueStateHydrationInProgress)
        {
            _docsPanelState = (_docsPanelState ?? new WorkspaceDocsPanelState()) with { QueuePaused = paused ? (bool?)true : false };
            _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
        }
    }

    private void ResumeQueueAfterStoppedWorkResponseIfNeeded()
    {
        if (!_queueStopPauseState.ConsumeResponseResume(_queueManuallyPaused || _queuePausePending))
            return;

        SquadDashTrace.Write("Queue", "Corrective response received after Stop — resuming automatic prompt queue processing.");
        SetQueuePaused(false);
    }

    private void SyncPromptTextBoxSimBorder()
    {
        bool isSim = _activeTabId is not null
            ? _promptQueue.Items.FirstOrDefault(i => i.Id == _activeTabId)?.IsSimEntry == true
            : _pec.ActiveDraftSimEntry.HasValue;

        if (isSim)
        {
            PromptTextBox.BorderThickness = new Thickness(3);
            PromptTextBox.BorderBrush = Brushes.MediumOrchid;
        }
        else
        {
            PromptTextBox.ClearValue(TextBox.BorderThicknessProperty);
            PromptTextBox.ClearValue(TextBox.BorderBrushProperty);
        }
    }

    private void SyncQueuePauseLabel()
    {
        if (_queuePausePending)
        {
            _queuePausePending = false;
            QueueStatusLabel.Text = "Queue is paused";
            // Turn has completed so the pending pause is now fully in effect.
            // Icon is already showing play ▶ (set during Case 2); update tooltip only.
            QueuePlayPauseButton.ToolTip = MakeThemedToolTip("Click to resume automatic prompt queue processing.");
            // Apply high-contrast styling now that pause is fully active.
            QueueStatusLabel.SetResourceReference(TextBlock.BackgroundProperty, "ToastSurface");
            QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "ToastText");
        }
        else
        {
            // Turn completed with no pending pause — ensure no stale styling remains.
            QueueStatusLabel.ClearValue(TextBlock.BackgroundProperty);
            QueueStatusLabel.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
        }
    }

    private void ToggleQueueDrain()
    {
        if (_interruptedPromptRecoveryHold is not null)
        {
            ShowSystemTranscriptEntry(
                "Queued prompts remain paused until you Continue, edit and submit, or dismiss the interrupted-work recovery card.");
            return;
        }

        if (_queuePausePending)
        {
            // Case 3: Cancel the pending pause — turn is still running but we resume.
            _queuePauseCallout?.Close();
            _queuePauseCallout = null;
            SetQueuePaused(false);
            return;
        }

        if (_queueManuallyPaused)
        {
            // Case 5: Resume from fully-paused state.
            _queuePauseCallout?.Close();
            _queuePauseCallout = null;
            SetQueuePaused(false);

            // If the rightmost tab is holding the queue, resume by submitting it directly.
            if (_rightmostTabHoldNotificationFired && _activeTabId is not null)
                _ = DispatchQueuedTabAsync(_activeTabId);
            else
                _ = DrainQueueIfNeededAsync();
        }
        else if (_queueRecoveryHold is not null)
        {
            // A system recovery hold is not a user pause. Play is still an explicit human
            // override that may release queued prompts without changing the preserved plan.
            ClearQueueRecoveryHold("user-play");
            _ = DrainQueueIfNeededAsync();
        }
        else
        {
            // Case 1 or 2: Pause (or schedule pause if a turn is active).
            SetQueuePaused(true);
            if (!_queuePausePending)
            {
                ShowQueuePausedCallout();
            }
        }
    }

    private void QueuePlayPauseButton_Click(object sender, RoutedEventArgs e) => ToggleQueueDrain();

    private bool IsQueueDispatchHeld =>
        _queueManuallyPaused ||
        _queueRecoveryHold is not null ||
        _interruptedPromptRecoveryHold is not null;

    private void SetQueueRecoveryHoldForRequiredPlan(
        TranscriptThreadState thread,
        string reason)
    {
        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        var planId = execution?.DecomposeGroupId ?? _activeDecomposeGroupId;
        if (string.IsNullOrWhiteSpace(planId))
            return;

        _queueRecoveryHold = new QueueRecoveryHoldState(
            planId,
            thread.AssignedPlanTaskId ?? execution?.PlanExecutionAttempt?.TaskId,
            execution?.PlanExecutionAttempt?.AttemptId,
            reason,
            DateTimeOffset.UtcNow);
        _conversationManager.PersistConversationState(
            _conversationManager.ConversationState with { QueueRecoveryHold = _queueRecoveryHold });
        SquadDashTrace.Write(
            "Queue",
            $"System recovery hold set plan={_queueRecoveryHold.PlanId} task={_queueRecoveryHold.TaskId ?? "none"} attempt={_queueRecoveryHold.AttemptId ?? "none"}; manualPause={_queueManuallyPaused}.");
        SyncQueuePanel();
    }

    private bool ClearQueueRecoveryHoldForPlan(
        string planId,
        string? taskId,
        string reason)
    {
        if (_queueRecoveryHold is null || !_queueRecoveryHold.Matches(planId, taskId))
            return false;

        ClearQueueRecoveryHold(reason);
        return true;
    }

    private void ClearQueueRecoveryHold(string reason)
    {
        if (_queueRecoveryHold is null)
            return;

        var released = _queueRecoveryHold;
        _queueRecoveryHold = null;
        _conversationManager.PersistConversationState(
            _conversationManager.ConversationState with { QueueRecoveryHold = null });
        SquadDashTrace.Write(
            "Queue",
            $"System recovery hold cleared reason={reason} plan={released.PlanId} task={released.TaskId ?? "none"}; manualPausePreserved={_queueManuallyPaused}.");
        SyncQueuePanel();
    }

    private void ShowQueuePausedCallout()
    {
        var isDark = Resources.Contains("IsDarkTheme") && (bool)Resources["IsDarkTheme"];
        var theme  = isDark ? CalloutTheme.Dark : CalloutTheme.Light;
        var fontSize = Application.Current?.Resources["FontSizeCallout"] is double calloutSize
            ? calloutSize
            : 18.0;
        _queuePauseCallout?.Close();
        _ = Dispatcher.InvokeAsync(() => {
            _queuePauseCallout = FrmUltimateCallout.ShowCalloutBesideTarget(
                "Queue drain is paused. Press **F5** or click ▶ to resume.",
                QueuePlayPauseButton,
                width: 260,
                theme: theme,
                fontSize: fontSize,
                placement: CalloutPlacement.North);
        }, System.Windows.Threading.DispatcherPriority.Loaded);
    }

    private void EditPauseQueueDrainMenuItem_Click(object sender, RoutedEventArgs e) => ToggleQueueDrain();
    private void EditResumeQueueDrainMenuItem_Click(object sender, RoutedEventArgs e) => ToggleQueueDrain();

    /// <summary>Returns the Border in QueueTabStrip whose Tag matches _activeTabId, or null.</summary>
    private Border? GetActiveQueueTabBorder()
    {
        if (_activeTabId is null) return null;
        foreach (UIElement child in QueueTabStrip.Children)
            if (child is Border b && b.Tag as string == _activeTabId)
                return b;
        return null;
    }

    /// <summary>
    /// Fast path for Ctrl+Tab cycling: only updates the two tabs whose active/inactive
    /// state changed, without tearing down and rebuilding the entire tab strip.
    /// </summary>
    private void FastSyncQueueTabActiveState(string? oldId, string? newId)
    {
        var sw = Stopwatch.StartNew();

        Border? oldBorder = null;
        Border? newBorder = null;
        TextBlock? hintBlock = null;

        foreach (UIElement child in QueueTabStrip.Children)
        {
            if (child is TextBlock tb)       { hintBlock = tb; continue; }
            if (child is not Border b)        continue;
            string? tabId = b.Tag as string;
            if (tabId == oldId || (tabId is null && oldId is null)) oldBorder = b;
            if (tabId == newId || (tabId is null && newId is null)) newBorder = b;
        }

        if (oldBorder is not null) ApplyQueueTabActiveState(oldBorder, isActive: false, isQueueItem: oldId is not null);
        if (newBorder is not null) ApplyQueueTabActiveState(newBorder, isActive: true,  isQueueItem: newId is not null);
        UpdateQueueTabHint(hintBlock, newId);

        _conversationManager.UpdateQueuedPromptsState(
            _promptQueue.Items, _followUpAttachments, queueRightmostHeld: IsRightmostQueueTabActive(), loopQueuedToDequeue: _loopQueued, activeDraftSimEntry: _pec.ActiveDraftSimEntry, activeTabIndex: GetActiveQueueTabIndex());
        SyncSendButton();

        SquadDashTrace.Write(TraceCategory.Performance,
            $"FastSyncQueueTabActiveState: {oldId ?? "draft"}→{newId ?? "draft"} in {sw.ElapsedMilliseconds}ms");
    }

    /// <summary>
    /// Holds the mutable content for a queue-tab tooltip. Queue tabs keep the same
    /// explicit ToolTip instance for their lifetime so an open WPF tooltip popup is
    /// never asked to switch between implicit (string) and explicit ToolTip content.
    /// </summary>
    private sealed record QueueTabToolTipContent(TextBlock Hint, TextBlock PauseWarning);

    private ToolTip BuildQueueTabTooltip(string plainTooltip, bool isActive)
    {
        var hintBlock = new TextBlock
        {
            Text = plainTooltip,
            TextWrapping = TextWrapping.Wrap,
            MaxWidth = 320,
        };
        var pauseBlock = new TextBlock
        {
            TextWrapping = TextWrapping.Wrap,
            MaxWidth = 320,
            Margin = new Thickness(0, 4, 0, 0),
            Opacity = 0.8,
            Visibility = isActive ? Visibility.Visible : Visibility.Collapsed,
        };
        pauseBlock.Inlines.Add(new System.Windows.Documents.Run("Because this tab is active, automatic queuing will pause when this prompt is reached. Select the "));
        pauseBlock.Inlines.Add(new System.Windows.Documents.Bold(new System.Windows.Documents.Run("Active Draft")));
        pauseBlock.Inlines.Add(new System.Windows.Documents.Run(" tab for uninterrupted prompt queuing."));
        var tipPanel = new StackPanel { MaxWidth = 320 };
        tipPanel.Children.Add(hintBlock);
        tipPanel.Children.Add(pauseBlock);
        var tt = new ToolTip { Content = tipPanel };
        tt.Tag = new QueueTabToolTipContent(hintBlock, pauseBlock);
        tt.SetResourceReference(Control.BackgroundProperty, "InputSurface");
        tt.SetResourceReference(Control.BorderBrushProperty, "InputBorder");
        tt.BorderThickness = new Thickness(1);
        tt.Padding = new Thickness(6, 4, 6, 4);
        return tt;
    }

    private static void UpdateQueueTabTooltip(ToolTip tooltip, string plainTooltip, bool isActive)
    {
        if (tooltip.Tag is not QueueTabToolTipContent content)
            return;

        content.Hint.Text = plainTooltip;
        content.PauseWarning.Visibility = isActive ? Visibility.Visible : Visibility.Collapsed;
    }

    /// <summary>
    /// Applies active or inactive visual styling to an existing tab Border element.
    /// Handles TextBlock-only tabs and StackPanel tabs (with optional paperclip/pause icons).
    /// </summary>
    private void ApplyQueueTabActiveState(Border tab, bool isActive, bool isQueueItem)
    {
        tab.BorderThickness = new Thickness(0, 0, 0, isActive ? 2 : 0);
        if (isActive)
            tab.SetResourceReference(Border.BorderBrushProperty, "QueueTabActiveBorder");
        else
            tab.BorderBrush = Brushes.Transparent;

        bool showPause = isQueueItem && isActive;

        void StyleText(TextBlock tb)
        {
            tb.FontWeight = isActive ? FontWeights.SemiBold : FontWeights.Normal;
            tb.SetResourceReference(TextBlock.ForegroundProperty,
                isActive ? "LabelText" : "QueueTabInactiveText");
        }

        if (tab.Child is TextBlock directText)
        {
            StyleText(directText);
            if (showPause)
            {
                // Promote from single TextBlock to StackPanel to accommodate the pause icon.
                tab.Child = null; // detach before reparenting
                var sp = new StackPanel { Orientation = Orientation.Horizontal, VerticalAlignment = VerticalAlignment.Center };
                sp.Children.Add(directText);
                sp.Children.Add(CreatePauseIcon());
                tab.Child = sp;
            }
        }
        else if (tab.Child is StackPanel panel)
        {
            if (panel.Children.Count > 0 && panel.Children[0] is TextBlock tbFirst)
                StyleText(tbFirst);

            // Update paperclip icon color (it tracks active state).
            foreach (UIElement c in panel.Children)
            {
                if (c is System.Windows.Shapes.Path pp && pp.Data == s_paperclipGeometry)
                    pp.SetResourceReference(System.Windows.Shapes.Path.FillProperty,
                        isActive ? "LabelText" : "QueueTabInactiveText");
            }

            // Add or remove pause icon.
            System.Windows.Shapes.Path? existingPause = null;
            foreach (UIElement c in panel.Children)
            {
                if (c is System.Windows.Shapes.Path pp && pp.Data == s_pauseGeometry)
                { existingPause = pp; break; }
            }

            if (showPause && existingPause is null)
            {
                panel.Children.Add(CreatePauseIcon());
            }
            else if (!showPause && existingPause is not null)
            {
                panel.Children.Remove(existingPause);
                // Demote back to plain TextBlock when no icons remain.
                if (panel.Children.Count == 1 && panel.Children[0] is TextBlock onlyText)
                {
                    panel.Children.Clear(); // detach before reparenting
                    tab.Child = onlyText;
                }
            }
        }

        // Sync the tooltip to match the new active state.
        // FastSyncQueueTabActiveState skips a full SyncQueuePanel rebuild, so the
        // tooltip must be updated here or it stays stale (e.g. showing the active-pause
        // warning on a tab that just became inactive).
        if (isQueueItem)
        {
            var tabId = tab.Tag as string;
            if (tabId is not null)
            {
                var nextReadyId = _promptQueue.Items.FirstOrDefault(i => !i.IsEditing)?.Id;
                var plainTooltip = tabId == nextReadyId
                    ? "This prompt is next in the Squad queue."
                    : "This item is in the Squad queue.";
                // Keep the ToolTip object stable while it may be open. Replacing a string
                // tooltip with an explicit ToolTip during the click route makes WPF's
                // implicit popup try to parent the new ToolTip and throws.
                if (tab.ToolTip is ToolTip queueTooltip)
                    UpdateQueueTabTooltip(queueTooltip, plainTooltip, isActive);
            }
        }
    }

    /// <summary>
    /// Updates (or adds/removes) the italic hint TextBlock at the end of the queue tab strip
    /// that warns the user about automatic queue pausing when a queued tab is active.
    /// </summary>
    private void UpdateQueueTabHint(TextBlock? existingHint, string? newActiveId)
    {
        string? activeTabLabel = null;
        if (newActiveId is not null)
        {
            var item = _promptQueue.Items.FirstOrDefault(i => i.Id == newActiveId);
            if (item is not null)
            {
                var nextReadyId = _promptQueue.Items.FirstOrDefault(i => !i.IsEditing)?.Id;
                activeTabLabel = item.Id == nextReadyId
                    ? $"Queue #{item.QueueNumber}"
                    : $"#{item.QueueNumber}";
            }
        }

        // Suppress the hint when the queue is already paused because the active tab is
        // the rightmost (first-to-dispatch) tab and no turn is in progress.
        bool rightmostPaused = newActiveId is not null
            && _promptQueue.Count > 0
            && _promptQueue.Items[0].Id == newActiveId
            && !_isPromptRunning;
        if (rightmostPaused)
            activeTabLabel = null;

        if (activeTabLabel is not null)
        {
            var text = $"Automatic prompting will pause when it's time to send this active tab (\"{activeTabLabel}\")";
            if (existingHint is not null)
            {
                existingHint.Text = text;
            }
            else
            {
                var hint = new TextBlock
                {
                    Text = text,
                    VerticalAlignment = VerticalAlignment.Center,
                    Margin = new Thickness(10, 0, 8, 0),
                    FontStyle = FontStyles.Italic,
                };
                hint.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeSmall");
                hint.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
                QueueTabStrip.Children.Add(hint);
            }
        }
        else if (existingHint is not null)
        {
            QueueTabStrip.Children.Remove(existingHint);
        }
    }

    private static readonly Geometry s_paperclipGeometry = Geometry.Parse(
        "M16.5,6 V17.5 C16.5,19.71 14.71,21.5 12.5,21.5 C10.29,21.5 8.5,19.71 8.5,17.5 V5 C8.5,3.62 9.62,2.5 11,2.5 C12.38,2.5 13.5,3.62 13.5,5 V15.5 C13.5,16.05 13.05,16.5 12.5,16.5 C11.95,16.5 11.5,16.05 11.5,15.5 V6 H10 V15.5 C10,16.88 11.12,18 12.5,18 C13.88,18 15,16.88 15,15.5 V5 C15,2.79 13.21,1 11,1 C8.79,1 7,2.79 7,5 V17.5 C7,20.54 9.46,23 12.5,23 C15.54,23 18,20.54 18,17.5 V6 H16.5 Z");

    // Two vertical bars — standard pause symbol
    private static readonly Geometry s_pauseGeometry = Geometry.Parse(
        "M3,1 H6 V13 H3 Z M8,1 H11 V13 H8 Z");

    private UIElement CreatePriorityFeedbackLabel()
    {
        var tb = new TextBlock
        {
            Text              = "« Now at the front of the queue.",
            FontStyle         = FontStyles.Italic,
            VerticalAlignment = VerticalAlignment.Center,
            Margin            = new Thickness(8, 0, 8, 0),
        };
        tb.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeSmall");
        tb.SetResourceReference(TextBlock.ForegroundProperty, "QueueTabActiveBorder");
        return tb;
    }

    private UIElement CreatePaperclipIcon(bool isActive)
    {
        var path = new System.Windows.Shapes.Path
        {
            Data             = s_paperclipGeometry,
            Stretch          = Stretch.Uniform,
            Width            = 10,
            Height           = 10,
            StrokeThickness  = 0,
            VerticalAlignment  = VerticalAlignment.Center,
            // Half a space-width gap between number and clip (~3px at 12px font)
            Margin = new Thickness(3, 0, 0, 0),
        };
        path.SetResourceReference(
            System.Windows.Shapes.Path.FillProperty,
            isActive ? "LabelText" : "QueueTabInactiveText");
        return path;
    }

    /// <summary>
    /// A paperclip icon wrapped in a transparent Button so the user can click it to open
    /// the attachment viewer for a queued-tab's follow-up attachments.
    /// </summary>
    private UIElement CreateQueueTabPaperclipButton(bool isActive, List<FollowUpAttachment> attachments)
    {
        var icon = CreatePaperclipIcon(isActive);
        var btn = new Button
        {
            Content           = icon,
            Width             = 16,
            Height            = 20,
            Padding           = new Thickness(0),
            Margin            = new Thickness(2, 0, 0, 0),
            VerticalAlignment = VerticalAlignment.Center,
            Cursor            = Cursors.Hand,
            Style             = (Style)FindResource("ThemedIconButtonStyle"),
            ToolTip           = MakeThemedToolTip("Click to view attached context items."),
        };
        var capturedList = attachments;
        btn.Click += (_, e) =>
        {
            e.Handled = true;
            if (capturedList.Count == 1 && capturedList[0].InboxMessageId is { } msgId)
                PromptAttachmentViewerWindow.Show(capturedList, CanShowOwnedWindow() ? this : null, m => OpenOrFocusInboxMessage(m));
            else if (capturedList.Count > 0)
                PromptAttachmentViewerWindow.Show(capturedList, CanShowOwnedWindow() ? this : null, m => OpenOrFocusInboxMessage(m));
        };
        return btn;
    }

    private UIElement CreatePauseIcon()
    {
        var path = new System.Windows.Shapes.Path
        {
            Data              = s_pauseGeometry,
            Stretch           = Stretch.Uniform,
            Width             = 9,
            Height            = 10,
            StrokeThickness   = 0,
            VerticalAlignment = VerticalAlignment.Center,
            Margin            = new Thickness(4, 0, 0, 0),
            Opacity           = 0.50,
        };
        path.SetResourceReference(System.Windows.Shapes.Path.FillProperty, "LabelText");

        var tipText = new TextBlock
        {
            Text        = "This tab is active. Automatic queuing will pause when this prompt is reached. Select the Active Draft tab for uninterrupted prompt queuing.",
            TextWrapping = TextWrapping.Wrap,
            MaxWidth    = 280,
        };
        var tipPathTt = new ToolTip { Content = tipText };
        tipPathTt.SetResourceReference(Control.BackgroundProperty, "InputSurface");
        tipPathTt.SetResourceReference(Control.BorderBrushProperty, "InputBorder");
        tipPathTt.BorderThickness = new Thickness(1);
        tipPathTt.Padding = new Thickness(6, 4, 6, 4);
        ToolTipService.SetToolTip(path, tipPathTt);
        return path;
    }

    private UIElement CreateQueueTab(string? id, string label, string? tooltip = null)
    {
        bool isActive = _activeTabId == id;
        var queueItem = id is null ? null : _promptQueue.Items.FirstOrDefault(item => item.Id == id);
        var isLocked = queueItem?.IsLocked == true;

        var textBlock = new TextBlock
        {
            Text = label,
            FontWeight = isActive ? FontWeights.SemiBold : FontWeights.Normal,
            VerticalAlignment = VerticalAlignment.Center,
        };
        textBlock.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeBody");
        // SetResourceReference keeps the brush live — updates automatically on theme switch.
        textBlock.SetResourceReference(
            TextBlock.ForegroundProperty,
            isActive ? "LabelText" : "QueueTabInactiveText");

        var tabKey = id ?? "";
        bool hasAttachment = _followUpAttachments.TryGetValue(tabKey, out var attachList) && attachList.Count > 0;
        bool showPause = id is not null && isActive && !isLocked;

        UIElement tabChild;
        if (hasAttachment || showPause)
        {
            var sp = new StackPanel
            {
                Orientation = Orientation.Horizontal,
                VerticalAlignment = VerticalAlignment.Center,
            };
            sp.Children.Add(textBlock);
            if (hasAttachment)
                sp.Children.Add(CreateQueueTabPaperclipButton(isActive, attachList!.ToList()));
            if (showPause)
                sp.Children.Add(CreatePauseIcon());
            tabChild = sp;
        }
        else
        {
            tabChild = textBlock;
        }

        object? tipContent = tooltip is null ? null
            : id is not null ? BuildQueueTabTooltip(tooltip, isActive)
            : (object)tooltip;

        var tab = new Border
        {
            Padding = new Thickness(12, 6, 12, 6),
            Margin = new Thickness(0, 0, 1, 0),
            Cursor = Cursors.Hand,
            BorderThickness = new Thickness(0, 0, 0, isActive ? 2 : 0),
            Background = Brushes.Transparent,
            Child = tabChild,
            ToolTip = tipContent,
        };
        if (isActive)
            tab.SetResourceReference(Border.BorderBrushProperty, "QueueTabActiveBorder");
        else
            tab.BorderBrush = Brushes.Transparent;

        if (id is not null)
        {
            var capturedId = id;
            var isPlanContinuation = string.Equals(
                queueItem?.SourceTag, PlanContinuationQueueTag, StringComparison.Ordinal);
            var isQueuedLoop = string.Equals(
                queueItem?.SourceTag, QueuedLoopJobTag, StringComparison.Ordinal);
            var isQueuedPlanStart = string.Equals(
                queueItem?.SourceTag, QueuedPlanStartTag, StringComparison.Ordinal);
            if (isQueuedLoop)
                tab.Cursor = Cursors.Arrow;
            var cm = MakeMenu();

            // Activate the tab on right-click so user can see what they're deleting.
            cm.Opened += (_, _) => OnQueueTabClicked(capturedId);

            // Only show Prioritize when this item is not already next-to-dispatch (index 0).
            bool isAlreadyFirst = _promptQueue.Items.Count > 0 && _promptQueue.Items[0].Id == capturedId;
            if (!isAlreadyFirst && !isQueuedLoop && !isQueuedPlanStart && !isPlanContinuation)
            {
                var prioritizeItem = MakeItem("Prioritize — send this next");
                prioritizeItem.Click += (_, _) => OnQueueTabPrioritize(capturedId);
                cm.Items.Add(prioritizeItem);
            }

            if (!isPlanContinuation)
            {
                var deleteItem = MakeItem("Delete queued item…");
                deleteItem.Click += (_, _) => OnQueueTabDeleteConfirm(capturedId, tab);
                cm.Items.Add(deleteItem);
            }
            tab.ContextMenu = cm;

            if (!isQueuedLoop && !isQueuedPlanStart && !isPlanContinuation)
            {
                // Drag-to-reorder: tag the tab so UpdateDropIndicator can identify it,
                // then wire up the four mouse events needed for the drag lifecycle.
                tab.Tag = capturedId;
                tab.MouseLeftButtonDown += (_, e) => OnQueueTabMouseDown(capturedId, tab, e);
                tab.MouseMove += (_, e) => OnQueueTabMouseMove(e);
                tab.MouseLeftButtonUp += (_, e) => OnQueueTabMouseUp(capturedId, e);
                tab.LostMouseCapture += (_, _) => CancelDrag();
            }
            else
            {
                tab.Tag = capturedId;
                tab.MouseLeftButtonUp += (_, _) => OnQueueTabClicked(capturedId);
            }
        }
        else
        {
            // Active Draft tab: simple click only — never draggable.
            tab.MouseLeftButtonUp += (_, _) => OnQueueTabClicked(null);
        }

        return tab;
    }

    /// <summary>
    /// Cycles the active queue tab left (reverse=true) or right (reverse=false).
    /// Tab order is: Active Draft (index 0) → queued items left-to-right.
    /// </summary>
    private void CycleQueueTab(bool reverse)
    {
        // Build ordered list matching visual layout: null = Active Draft (leftmost),
        // then items newest→oldest (left→right), mirroring the Reverse() in SyncQueuePanel.
        var tabIds = new List<string?> { null };
        foreach (var item in _promptQueue.Items.Reverse())
            tabIds.Add(item.Id);

        var currentIndex = tabIds.IndexOf(_activeTabId);
        if (currentIndex < 0) currentIndex = 0;

        int nextIndex = reverse
            ? (currentIndex - 1 + tabIds.Count) % tabIds.Count
            : (currentIndex + 1) % tabIds.Count;

        OnQueueTabClicked(tabIds[nextIndex]);
    }

    private void OnQueueTabClicked(string? id)
    {
        if (_activeTabId == id) return;

        PreserveVisibleTranscriptViewportsThroughLayout(
            () => OnQueueTabClickedCore(id),
            "active queue tab changed");
    }

    private void OnQueueTabClickedCore(string? id)
    {

        var sw = Stopwatch.StartNew();

        // Capture the old tab id before we change it — needed for the fast visual update.
        var previousId = _activeTabId;

        // Capture whether we're leaving the rightmost hold tab before the switch.
        bool wasRightmostHold = IsRightmostQueueTabActive();

        // Save current content + caret before switching.
        if (_activeTabId is null)
        {
            _queuePreEditDraft = PromptTextBox.Text;
            _queuePreEditDraftCaretIndex = PromptTextBox.CaretIndex;
            _queuePreEditDraftSelectionStart = PromptTextBox.SelectionStart;
            _queuePreEditDraftSelectionLength = PromptTextBox.SelectionLength;
        }
        else
        {
            var current = _promptQueue.Items.FirstOrDefault(i => i.Id == _activeTabId);
            if (current is not null && !current.IsLocked)
            {
                current.Text = PromptTextBox.Text;
                current.CaretIndex = PromptTextBox.CaretIndex;
                current.SelectionStart = PromptTextBox.SelectionStart;
                current.SelectionLength = PromptTextBox.SelectionLength;
            }
        }

        _activeTabId = id;

        if (id is null)
        {
            SetPromptTextBoxLogicalBuffer(
                _queuePreEditDraft ?? string.Empty,
                _queuePreEditDraftCaretIndex,
                _queuePreEditDraftSelectionStart,
                _queuePreEditDraftSelectionLength,
                "queue-tab-draft");
            _queuePreEditDraft = null;
        }
        else
        {
            var target = _promptQueue.Items.FirstOrDefault(i => i.Id == id);
            if (target is not null)
            {
                SetPromptTextBoxLogicalBuffer(
                    target.IsLocked
                        ? target.ReadOnlyDisplayText ?? target.Text
                        : target.Text,
                    target.CaretIndex,
                    target.SelectionStart,
                    target.SelectionLength,
                    "queue-tab-item");
            }
        }

        long msAfterText = sw.ElapsedMilliseconds;

        // Switching away from the rightmost hold tab releases the hold.
        // Reset the notification flag so it can fire again if re-activated, then drain.
        if (wasRightmostHold)
            _rightmostTabHoldNotificationFired = false;

        // Fast path: only update the two tabs whose visual state changed rather than
        // tearing down and rebuilding the entire tab strip on every Ctrl+Tab cycle.
        FastSyncQueueTabActiveState(previousId, id);
        ApplyPromptEditorLockState();
        SetQueuePaused(_queueManuallyPaused);
        long msAfterTabSync = sw.ElapsedMilliseconds;

        PromptTextBox.Focus();
        UpdateFollowUpStrip();

        SquadDashTrace.Write(TraceCategory.Performance,
            $"OnQueueTabClicked: {previousId ?? "draft"}→{id ?? "draft"} | " +
            $"text={msAfterText}ms tabSync={msAfterTabSync - msAfterText}ms " +
            $"followUp={(sw.ElapsedMilliseconds - msAfterTabSync)}ms total={sw.ElapsedMilliseconds}ms");

        if (wasRightmostHold && CanAutoDispatchPromptQueue("rightmost-tab-released"))
            _ = DrainQueueIfNeededAsync();
        SyncPromptTextBoxSimBorder();
    }

    private void OnQueueTabPrioritize(string id)
    {
        _promptQueue.MoveToFront(id);
        _promptQueue.RenumberSequentially();
        SyncQueuePanel();
        // _activeTabId is unchanged — restore prompt box to reflect the still-active tab.
        var activeItem = _activeTabId is not null
            ? _promptQueue.Items.FirstOrDefault(i => i.Id == _activeTabId)
            : null;
        if (activeItem is not null)
        {
            SetPromptTextBoxLogicalBuffer(
                activeItem.Text,
                activeItem.CaretIndex,
                activeItem.SelectionStart,
                activeItem.SelectionLength,
                "queue-prioritize-restore");
        }
    }

    private void OnQueueTabRemove(string id)
    {
        if (_activeTabId == id)
        {
            _activeTabId = null;
            SetPromptTextBoxLogicalBuffer(
                _queuePreEditDraft ?? string.Empty,
                _queuePreEditDraftCaretIndex,
                _queuePreEditDraftSelectionStart,
                _queuePreEditDraftSelectionLength,
                "queue-remove-restore-draft");
            _queuePreEditDraft = null;
            UpdateFollowUpStrip();
        }
        _promptQueue.Remove(id);
        if (string.Equals(
                _pendingPlanReviewCorrectionContext?.QueueItemId,
                id,
                StringComparison.Ordinal))
            ClearPendingPlanReviewCorrection(restoreCard: true);
        if (string.Equals(
                _pendingPlanTaskCorrectionContext?.QueueItemId,
                id,
                StringComparison.Ordinal))
            ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
        SyncQueuePanel();
        if (_categorizationCallout is { IsVisible: true })
        {
            _categorizationCallout.Close();
            _categorizationCallout = null;
        }
    }

    private void OnQueueTabDeleteConfirm(string id, FrameworkElement anchor)
    {
        var item = _promptQueue.Items.FirstOrDefault(i => i.Id == id);
        if (item is null) return;

        // When this item is the active tab, live edits are in PromptTextBox — not
        // yet written back to item.Text (that flush only happens on tab switch).
        // Read the live text so the empty-check reflects what the user sees.
        var effectiveText = _activeTabId == id ? PromptTextBox.Text : item.Text;

        // Empty items have nothing to confirm — delete immediately.
        // Tour/sim items in developer mode are also deleted without confirmation.
        if (string.IsNullOrWhiteSpace(effectiveText) ||
            (SquadDashEnvironment.IsDeveloperMode && IsTourOrSimTag(item.SourceTag)))
        {
            OnQueueTabRemove(id);
            return;
        }

        var preview = effectiveText.Length > 60 ? effectiveText[..57] + "…" : effectiveText;

        var dialog = new QueueItemDeleteConfirmWindow(
            $"#{item.QueueNumber}",
            preview,
            GetScreenRect(anchor),
            effectiveText)
        {
            Owner = this
        };
        if (dialog.ShowDialog() == true)
            OnQueueTabRemove(id);
    }

    /// <summary>
    /// Handles the Ctrl+Delete keyboard shortcut: deletes the active queue tab,
    /// prompting for confirmation when the item contains text.  Selects the nearest
    /// adjacent tab after deletion (left neighbour preferred; rightmost remaining as
    /// fallback; stays on the draft tab if the queue becomes empty).
    /// </summary>
    private void DeleteActiveQueueTabWithKeyboard()
    {
        if (_activeTabId is null) return;
        var id = _activeTabId;

        var item = _promptQueue.Items.FirstOrDefault(i => i.Id == id);
        if (item is null) return;

        // Active tab's live text lives in PromptTextBox (not yet flushed to item.Text).
        var effectiveText = PromptTextBox.Text;

        if (!string.IsNullOrWhiteSpace(effectiveText) &&
            !(SquadDashEnvironment.IsDeveloperMode && IsTourOrSimTag(item.SourceTag)))
        {
            var result = MessageBox.Show(
                "Are you sure you want to delete this queued item?",
                "Delete Queue Item",
                MessageBoxButton.YesNo,
                MessageBoxImage.Question);
            if (result != MessageBoxResult.Yes)
                return;
        }

        // Determine adjacent tab before removal.
        // Visual order matches CycleQueueTab: null (draft) at [0], Items.Reverse() after.
        var tabIds = new List<string?> { null };
        foreach (var itm in _promptQueue.Items.Reverse())
            tabIds.Add(itm.Id);

        var currentIndex = tabIds.IndexOf(id);
        string? nextId = currentIndex > 0
            ? tabIds[currentIndex - 1]               // prefer left neighbour
            : tabIds.LastOrDefault(t => t != id);    // rightmost remaining (fallback)

        OnQueueTabRemove(id);

        // Navigate to the adjacent tab; null means the draft tab, which OnQueueTabRemove
        // already restored, so only switch explicitly when nextId is a queue item.
        if (nextId is not null)
            OnQueueTabClicked(nextId);
    }

    // ── Queue tab drag-to-reorder ────────────────────────────────────────────

    /// <summary>
    /// Returns the shared drop-indicator <see cref="Border"/> (a narrow vertical bar),
    /// creating it on first call.  Uses a themed brush so it updates on theme switch.
    /// </summary>
    private Border GetOrCreateDropIndicator()
    {
        if (_dropIndicator is not null) return _dropIndicator;

        _dropIndicator = new Border
        {
            Width = 2,
            VerticalAlignment = VerticalAlignment.Stretch,
            IsHitTestVisible = false,
            Margin = new Thickness(0, 4, 0, 4),
        };
        _dropIndicator.SetResourceReference(Border.BackgroundProperty, "QueueTabActiveBorder");
        return _dropIndicator;
    }

    private void OnQueueTabMouseDown(string id, Border tab, MouseButtonEventArgs e)
    {
        _dragTabId = id;
        _dragStartPoint = e.GetPosition(QueueTabStrip);
        _isDragging = false;
        tab.CaptureMouse();
    }

    private void OnQueueTabMouseMove(MouseEventArgs e)
    {
        if (_dragTabId is null) return;

        var pos = e.GetPosition(QueueTabStrip);

        // Cancel if the cursor leaves the strip's bounds (with a small forgiveness margin).
        const double margin = 12.0;
        if (pos.X < -margin || pos.X > QueueTabStrip.ActualWidth + margin ||
            pos.Y < -margin || pos.Y > QueueTabStrip.ActualHeight + margin)
        {
            CancelDrag();
            return;
        }

        // Allow Escape to abort without dropping.
        if (Keyboard.IsKeyDown(Key.Escape))
        {
            CancelDrag();
            return;
        }

        if (!_isDragging)
        {
            var delta = pos - _dragStartPoint;
            if (Math.Abs(delta.X) < DragThreshold && Math.Abs(delta.Y) < DragThreshold)
                return;   // haven't moved far enough — still treating as potential click
            _isDragging = true;
        }

        UpdateDropIndicator(pos.X);
    }

    private void OnQueueTabMouseUp(string id, MouseButtonEventArgs e)
    {
        if (_dragTabId != id)
        {
            CancelDrag();
            return;
        }

        bool wasDragging = _isDragging;
        string? insertBeforeId = _dragInsertBeforeTabId;

        // Clear drag state (and release capture) before doing any work.
        CancelDrag();

        if (wasDragging)
            CommitQueueDrop(id, insertBeforeId);
        else
            OnQueueTabClicked(id);   // short press with no drag movement → treat as click
    }

    /// <summary>
    /// Clears all drag state, removes the drop indicator, and releases mouse capture.
    /// Safe to call multiple times (idempotent).  Called from LostMouseCapture,
    /// MouseLeftButtonUp, and the Escape / leave-strip cancel paths.
    /// </summary>
    private void CancelDrag()
    {
        // Capture the element reference before clearing state so the release below
        // doesn't attempt to re-enter via the LostMouseCapture handler when _dragTabId
        // has already been nulled out.
        var captured = Mouse.Captured as UIElement;

        _dragTabId = null;
        _isDragging = false;
        _dragInsertBeforeTabId = null;

        if (_dropIndicator is not null && QueueTabStrip.Children.Contains(_dropIndicator))
            QueueTabStrip.Children.Remove(_dropIndicator);

        // Releasing capture fires LostMouseCapture, which calls CancelDrag again —
        // but at that point _dragTabId is null and Mouse.Captured is null, so the
        // second call is a harmless no-op.
        captured?.ReleaseMouseCapture();
    }

    /// <summary>
    /// Repositions the drop indicator inside <see cref="QueueTabStrip"/> based on the
    /// current mouse X coordinate.  Also updates <see cref="_dragInsertBeforeTabId"/>.
    /// </summary>
    private void UpdateDropIndicator(double mouseX)
    {
        var indicator = GetOrCreateDropIndicator();

        // Remove the indicator first so the remaining children reflect the real tab order.
        QueueTabStrip.Children.Remove(indicator);

        // Walk queue tabs (children 1…N; child 0 is the pinned Active Draft tab).
        // Find the first non-dragged tab whose horizontal mid-point is to the right of
        // the cursor — the indicator (and the eventual drop) go *before* that tab.
        int insertAt = QueueTabStrip.Children.Count; // default: after all tabs
        string? insertBeforeId = null;

        for (int i = 1; i < QueueTabStrip.Children.Count; i++)
        {
            if (QueueTabStrip.Children[i] is not FrameworkElement child) continue;

            var tagId = child.Tag as string;
            if (tagId == _dragTabId) continue; // skip the tab that is being dragged

            var childLeft = child.TranslatePoint(new Point(0, 0), QueueTabStrip).X;
            var midX = childLeft + child.ActualWidth / 2;

            if (mouseX < midX)
            {
                insertBeforeId = tagId;
                insertAt = i;
                break;
            }
        }

        _dragInsertBeforeTabId = insertBeforeId;
        QueueTabStrip.Children.Insert(insertAt, indicator);
    }

    /// <summary>
    /// Called on mouse-up after an actual drag gesture.  Maps the visual drop position
    /// back to a logical <see cref="PromptQueue"/> index and performs the reorder.
    /// </summary>
    /// <remarks>
    /// <para>
    /// The strip renders <c>_items.Reverse()</c>, so visual-left = high logical index
    /// (dispatched last) and visual-right = low logical index (dispatched first).
    /// </para>
    /// <para>
    /// "Drop visually LEFT of tab X" means the dragged item is placed AFTER X in
    /// <c>_items</c> (higher logical index, dispatched later).
    /// </para>
    /// </remarks>
    private void CommitQueueDrop(string draggedId, string? insertBeforeId)
    {
        var items = _promptQueue.Items;

        // Locate the dragged item and the right-neighbour in the logical list.
        int dIdx = -1, rIdx = -1;
        for (int i = 0; i < items.Count; i++)
        {
            if (items[i].Id == draggedId) dIdx = i;
            if (items[i].Id == insertBeforeId) rIdx = i;
        }

        if (dIdx < 0) return; // dragged item no longer in queue — nothing to do

        int newIndex;
        if (insertBeforeId is null || rIdx < 0)
        {
            // No right-neighbour → drop at rightmost visual = logical index 0
            // (the item becomes the next to be dispatched).
            newIndex = 0;
        }
        else
        {
            // After removing the dragged item the right-neighbour's index shifts down
            // by 1 if it was logically after (= visually left of) the dragged item.
            int adjRIdx = rIdx > dIdx ? rIdx - 1 : rIdx;

            // Insert dragged AFTER right-neighbour in _items so it lands visually
            // to the LEFT of right-neighbour in the strip.
            newIndex = adjRIdx + 1;
        }

        _promptQueue.Reorder(draggedId, newIndex);
        _promptQueue.RenumberSequentially();
        SyncQueuePanel();
        ReattachCategorizationCalloutIfNeeded(draggedId);
    }

    /// <summary>Returns the bounding rect of a UI element in screen coordinates.</summary>
    private static Rect GetScreenRect(FrameworkElement element)
    {
        var topLeft = element.PointToScreen(new Point(0, 0));
        var bottomRight = element.PointToScreen(new Point(element.ActualWidth, element.ActualHeight));
        return new Rect(topLeft, bottomRight);
    }

    /// <summary>
    /// After a drag-reorder rebuilds the tab strip, repoints the categorization callout
    /// at the freshly-created Border for the same queue item.
    /// </summary>
    private void ReattachCategorizationCalloutIfNeeded(string draggedId)
    {
        if (_categorizationCallout is null || !_categorizationCallout.IsVisible) return;

        var tabBorder = QueueTabStrip.Children
            .OfType<Border>()
            .FirstOrDefault(b => b.Tag as string == draggedId);

        if (tabBorder is null)
        {
            _categorizationCallout.Close();
            _categorizationCallout = null;
            return;
        }

        _categorizationCallout.Repoint(tabBorder, FrmUltimateCallout.PlacementToAngle(CalloutPlacement.North));
    }

    private void SyncSendButton()
    {
        RunButton.Content = RunButtonLabelPolicy.Compute(
            coordinatorBusy: _isPromptRunning || IsNativeLoopRunning,
            queuePausedAwaitingInput: _queuePausedNotificationFired,
            queueCount: _promptQueue.Count,
            activeTabId: _activeTabId,
            queueManuallyPaused: IsQueueDispatchHeld,
            isRightmostTab: IsRightmostQueueTabActive());
        RunButton.IsEnabled = !IsActiveQueueItemLocked();
    }

    private bool IsActiveQueueItemLocked() =>
        _activeTabId is not null &&
        _promptQueue.Items.FirstOrDefault(item => item.Id == _activeTabId)?.IsLocked == true;

    private void ApplyPromptEditorLockState()
    {
        var isLocked = IsActiveQueueItemLocked();
        PromptTextBox.IsReadOnly = isLocked;
        PromptTextBox.SetResourceReference(
            Control.ForegroundProperty,
            isLocked ? "SubtleText" : "LabelText");
        SyncSendButton();
    }

    private async void AbortButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var abortTargets = BuildAbortConfirmationTargets();
            if (abortTargets.Count == 0)
            {
                var selectedThread = _selectedTranscriptThread ?? CoordinatorThread;
                SquadDashTrace.Write(
                    "UI",
                    $"AbortButton clicked but no abortable prompt or background task was resolved for thread={selectedThread.ThreadId}");
                return;
            }

            var dialog = new AbortAgentsConfirmationWindow(
                abortTargets,
                BuildAbortConfirmationTargets,
                GetScreenRect(AbortButton))
            {
                Owner = this
            };

            if (dialog.ShowDialog() != true || dialog.ConfirmedTargets.Count == 0)
            {
                SquadDashTrace.Write("UI", "Stop running work confirmation cancelled.");
                return;
            }

            await StopConfirmedRunningWorkAsync(dialog.ConfirmedTargets).ConfigureAwait(true);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException("Abort", ex);
        }
    }

    private IReadOnlyList<AbortAgentsConfirmationTarget> BuildAbortConfirmationTargets()
    {
        var targets = new List<AbortAgentsConfirmationTarget>();
        var seenBackgroundTaskIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        if (_isPromptRunning)
        {
            targets.Add(new AbortAgentsConfirmationTarget(
                "coordinator",
                "coordinator",
                "Coordinator",
                _pec.CurrentPromptStartedAt ?? CoordinatorThread.CurrentTurn?.StartedAt ?? DateTimeOffset.Now,
                IsCoordinator: true));
        }

        foreach (var target in _backgroundTaskPresenter.GetAbortTargets())
        {
            if (string.IsNullOrWhiteSpace(target.TaskId) || !seenBackgroundTaskIds.Add(target.TaskId))
                continue;

            targets.Add(new AbortAgentsConfirmationTarget(
                target.TaskId,
                target.TaskKind,
                target.DisplayLabel,
                target.StartedAt,
                IsCoordinator: false,
                target.AgentId,
                target.ToolCallId,
                target.TaskIdSource));
        }

        return targets;
    }

    private async Task StopConfirmedRunningWorkAsync(IReadOnlyList<AbortAgentsConfirmationTarget> targets)
    {
        var coordinatorWasStopped = targets.Any(target => target.IsCoordinator);
        var coordinatorStoppedAt = DateTimeOffset.UtcNow;
        if (coordinatorWasStopped)
        {
            _conversationManager.PersistConversationState(
                _conversationManager.ConversationState with
                {
                    ForceStoppedPromptAt = coordinatorStoppedAt.ToUniversalTime(),
                    ForceStoppedPromptHeadCommit = null,
                },
                "force-stopped-prompt-timestamp");
        }

        SquadDashTrace.Write(
            "UI",
            $"Stop running work confirmed targets={targets.Count} coordinator={targets.Any(target => target.IsCoordinator)} background={targets.Count(target => !target.IsCoordinator)} loop={IsLoopRunning} queueCount={_promptQueue.Count}");
        foreach (var target in targets)
        {
            SquadDashTrace.Write(
                "UI",
                $"Stop running work target kind={target.TaskKind} task={target.TaskId} idSource={target.TaskIdSource} coordinator={target.IsCoordinator} agentId={target.AgentId ?? "(none)"} toolCallId={target.ToolCallId ?? "(none)"} label={target.DisplayLabel}");
        }

        if (_activeDecomposeGroupId is not null && IsLoopRunning)
            _planAbortRequestedByUser = true;

        if (_promptQueue.Count > 0)
        {
            _queueStopPauseState.RecordStopPause(_queueManuallyPaused || _queuePausePending);
            SetQueuePaused(true);
        }

        if (IsLoopRunning)
            ForceStopLoopForRunningWorkStop();

        ForceFinalizeStoppedBackgroundThreads(targets);

        var result = _bridge.ForceStopRunningWork("abort-button-stop-all");
        _ignoreBridgeEventsThroughGeneration = Math.Max(
            _ignoreBridgeEventsThroughGeneration,
            result.ProcessGeneration);
        if (targets.Any(target => target.IsCoordinator))
            StartCoordinatorAbortWatchdog("force-stop", "[force-stopped]");

        _backgroundTaskPresenter.BackgroundAgents = Array.Empty<SquadBackgroundAgentInfo>();
        _backgroundTaskPresenter.BackgroundShells = Array.Empty<SquadBackgroundShellInfo>();
        _backgroundTaskPresenter.SkipNextBackgroundCompletionFallback = true;

        UpdateCompletedTimeFooters();
        SyncAgentCardsWithThreads();
        _backgroundTaskPresenter.RefreshLeadAgentBackgroundStatus();
        SyncQueuePanel();
        SyncSendButton();
        UpdateInteractiveControlState();
        if (coordinatorWasStopped)
            await RecordForceStoppedPromptContextAsync(coordinatorStoppedAt);
        TryCompletePendingRestart("running-work-force-stopped", emergencySaveBeforeClose: true);

        SquadDashTrace.Write(
            "UI",
            $"Stop running work completed bridgeGeneration={result.ProcessGeneration} hadBridgeProcess={result.HadActiveProcess} ignoredEventsThroughGeneration={_ignoreBridgeEventsThroughGeneration}");
    }

    private async Task RecordForceStoppedPromptContextAsync(DateTimeOffset stoppedAt)
    {
        var workspace = _currentWorkspace?.FolderPath;
        var stoppedHead = string.IsNullOrWhiteSpace(workspace)
            ? null
            : await TryGetGitShaAsync(workspace);
        _conversationManager.PersistConversationState(
            _conversationManager.ConversationState with
            {
                ForceStoppedPromptAt = stoppedAt.ToUniversalTime(),
                ForceStoppedPromptHeadCommit = stoppedHead,
            },
            "force-stopped-prompt-context");
        SquadDashTrace.Write(
            "PromptHealth",
            $"Recorded force-stop freshness baseline stoppedAt={stoppedAt.ToUniversalTime():O} head={stoppedHead ?? "unknown"}.");
    }

    private async Task<string?> ConsumeInterruptedPromptFreshnessInstructionAsync()
    {
        var state = _conversationManager.ConversationState;
        if (state.ForceStoppedPromptAt is not { } stoppedAt)
            return null;

        var workspace = _currentWorkspace?.FolderPath;
        var currentHead = string.IsNullOrWhiteSpace(workspace)
            ? null
            : await TryGetGitShaAsync(workspace);
        int? commitsSinceStop = null;
        var stoppedHead = state.ForceStoppedPromptHeadCommit;
        if (!string.IsNullOrWhiteSpace(workspace) &&
            IsFullGitSha(stoppedHead) &&
            IsFullGitSha(currentHead))
        {
            try
            {
                var countText = await RunGitAsync(workspace, $"rev-list --count {stoppedHead}..{currentHead}");
                if (int.TryParse(countText, out var count))
                    commitsSinceStop = count;
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write("PromptHealth", $"Could not calculate stopped-prompt commit distance: {ex.Message}");
            }
        }

        var observedAt = DateTimeOffset.UtcNow;
        var instruction = InterruptedPromptFreshnessContext.BuildInstruction(
            stoppedAt,
            observedAt,
            stoppedHead,
            currentHead,
            commitsSinceStop);

        var latest = _conversationManager.ConversationState;
        if (latest.ForceStoppedPromptAt == stoppedAt)
        {
            _conversationManager.PersistConversationState(
                latest with
                {
                    ForceStoppedPromptAt = null,
                    ForceStoppedPromptHeadCommit = null,
                },
                "consume-force-stopped-prompt-context");
        }

        SquadDashTrace.Write(
            "PromptHealth",
            $"Consumed force-stop freshness baseline ageSeconds={(observedAt - stoppedAt).TotalSeconds:F0} commitsSinceStop={commitsSinceStop?.ToString() ?? "unknown"} stoppedHead={stoppedHead ?? "unknown"} currentHead={currentHead ?? "unknown"}.");
        return instruction;
    }

    private static bool IsFullGitSha(string? value) =>
        value is { Length: 40 } && value.All(Uri.IsHexDigit);

    /// <summary>
    /// Gap 2 fix: immediately marks a background thread as Cancelled and finalizes it
    /// rather than waiting for the SDK to deliver a subagent_cancelled event (which may
    /// never arrive cleanly after a hard abort).
    /// </summary>
    private void ForceFinalizeCancelledBackgroundThread(string taskId)
    {
        var normalized = taskId.Trim();
        var thread = _agentThreadRegistry.ThreadOrder.FirstOrDefault(t =>
            !AgentThreadRegistry.IsTerminalBackgroundStatus(t.StatusText) &&
            (string.Equals(t.BackgroundTaskId, normalized, StringComparison.OrdinalIgnoreCase) ||
             string.Equals(t.AgentId, normalized, StringComparison.OrdinalIgnoreCase) ||
             string.Equals(t.ToolCallId, normalized, StringComparison.OrdinalIgnoreCase)));
        if (thread is null)
            return;

        SquadDashTrace.Write("UI", $"ForceFinalize cancelled thread agentId={thread.AgentId} title={thread.Title}");
        var summary = BackgroundTaskPresenter.BuildThreadCancellationSummary(thread);
        thread.StatusText = "Cancelled";
        thread.DetailText = summary;
        thread.IsCurrentBackgroundRun = false;
        thread.CompletedAt ??= DateTimeOffset.Now;
        _agentThreadRegistry.FinalizeAgentThread(thread);
        UpdateCompletedTimeFooters();
        _backgroundTaskPresenter.SkipNextBackgroundCompletionFallback = true;
        _backgroundTaskPresenter.AppendBackgroundNotice(
            summary, ThemeBrush("SystemInfoText"),
            BackgroundTaskPresenter.BuildThreadAnnouncementKey(thread) + ":cancelled");
        SyncAgentCardsWithThreads();
        _conversationManager.SaveAgentThreadToConversation(thread, DateTimeOffset.UtcNow);
    }

    private void ForceStopLoopForRunningWorkStop()
    {
        AppendLoopOutputLine("⚡ Loop force-stopped with running work.", new SolidColorBrush(Color.FromRgb(0xFF, 0x88, 0x44)));
        SuppressLoopResumeAfterExplicitStop("stop-running-work");
        if (_activeLoopMode == LoopMode.NativeAgents)
        {
            _loopController.RequestAbort();
            _loopFollowUpTcs?.TrySetResult(false);
        }
        else
        {
            _pec.SetIsLoopRunning(false);
        }

        SyncLoopPanel();
    }

    private void ForceFinalizeStoppedBackgroundThreads(IReadOnlyList<AbortAgentsConfirmationTarget> targets)
    {
        var finalizedThreads = new HashSet<TranscriptThreadState>(ReferenceEqualityComparer.Instance);
        foreach (var target in targets.Where(target => !target.IsCoordinator))
        {
            var thread = FindThreadForStopTarget(target);
            if (thread is not null)
                ForceFinalizeStoppedBackgroundThread(thread, target.TaskId, finalizedThreads);
        }

        foreach (var thread in _agentThreadRegistry.ThreadOrder.Where(_backgroundTaskPresenter.IsThreadCurrentRunForDisplay).ToArray())
            ForceFinalizeStoppedBackgroundThread(thread, thread.BackgroundTaskId ?? thread.AgentId ?? thread.ToolCallId ?? thread.ThreadId, finalizedThreads);
    }

    private TranscriptThreadState? FindThreadForStopTarget(AbortAgentsConfirmationTarget target)
    {
        return _agentThreadRegistry.ThreadOrder.FirstOrDefault(thread =>
            !AgentThreadRegistry.IsTerminalBackgroundStatus(thread.StatusText) &&
            (MatchesStopTarget(thread.BackgroundTaskId, target.TaskId) ||
             MatchesStopTarget(thread.AgentId, target.TaskId) ||
             MatchesStopTarget(thread.ToolCallId, target.TaskId) ||
             MatchesStopTarget(thread.AgentId, target.AgentId) ||
             MatchesStopTarget(thread.ToolCallId, target.ToolCallId)));
    }

    private static bool MatchesStopTarget(string? left, string? right) =>
        !string.IsNullOrWhiteSpace(left) &&
        !string.IsNullOrWhiteSpace(right) &&
        string.Equals(left.Trim(), right.Trim(), StringComparison.OrdinalIgnoreCase);

    private void ForceFinalizeStoppedBackgroundThread(
        TranscriptThreadState thread,
        string taskId,
        HashSet<TranscriptThreadState> finalizedThreads)
    {
        if (!finalizedThreads.Add(thread))
            return;

        var summary = BackgroundTaskPresenter.BuildThreadForceStopSummary(thread);
        SquadDashTrace.Write(
            "UI",
            $"Force-stopping background thread task={taskId} thread={thread.ThreadId} agentId={thread.AgentId ?? "(none)"} toolCallId={thread.ToolCallId ?? "(none)"} title={thread.Title ?? "(unknown)"}");
        thread.StatusText = "Interrupted";
        thread.DetailText = summary;
        thread.IsCurrentBackgroundRun = false;
        thread.CompletedAt ??= DateTimeOffset.Now;
        _agentThreadRegistry.FinalizeAgentThread(thread);
        CompleteDirectQuickReplyAgentThread(thread, "force_stop_running_work");
        _backgroundTaskPresenter.AppendBackgroundNotice(
            summary,
            ThemeBrush("SystemInfoText"),
            BackgroundTaskPresenter.BuildThreadAnnouncementKey(thread) + ":force-stopped");
        _conversationManager.SaveAgentThreadToConversation(thread, DateTimeOffset.UtcNow);
    }

    /// <summary>
    /// Gap 3 &amp; 4 fix: starts a short watchdog after a coordinator abort.  If
    /// <c>_isPromptRunning</c> is still true after the grace period the bridge task
    /// is assumed to be stuck and we force all prompt-running cleanup locally.
    /// </summary>
    private void StartCoordinatorAbortWatchdog(string reason = "abort", string marker = "[aborted]")
    {
        _ = Task.Delay(UiTimingConstants.AbortWatchdogDelay).ContinueWith(_ =>
            Dispatcher.InvokeAsync(() =>
            {
                if (!_isPromptRunning)
                    return;
                SquadDashTrace.Write("UI", $"AbortWatchdog: _isPromptRunning still true after 3 s reason={reason} — forcing coordinator cleanup.");
                ForceCoordinatorAbortCleanup(marker);
            }));
    }

    /// <summary>
    /// Resets all coordinator-turn UI state that would normally be cleared by the
    /// <c>setIsPromptRunning(false)</c> path in <c>ExecutePromptAsync</c>.  Only
    /// called from the abort watchdog when that path appears stuck.
    /// </summary>
    private void ForceCoordinatorAbortCleanup(string marker = "[aborted]")
    {
        _isPromptRunning = false;
        SyncGateChangeActivity(isPromptRunning: false);
        ClearPendingPlanReviewCorrection(restoreCard: true);
        ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
        UpdateRestartStatusPanelVisibility();
        CoordinatorThread.CompletedAt ??= DateTimeOffset.Now;
        // Close any still-spinning coordinator tool entries.
        _agentThreadRegistry.CompleteOutstandingAgentTools(CoordinatorThread);
        AppendLine(marker, ThemeBrush("SystemInfoText"));
        FinalizeCurrentTurnResponse();
        SyncQueuePauseLabel();
        UpdateCompletedTimeFooters();
        SyncQueuePanel();
        UpdateInteractiveControlState();
        UpdateSessionState("Ready");
        SquadDashTrace.Write("UI", "AbortWatchdog: forced coordinator cleanup complete.");
    }

    private void HandleEvent(SquadSdkEvent evt)
    {
        TraceSdkEvent(evt);
        if (ShouldIgnoreForceStoppedBridgeEvent(evt))
            return;

        if (_activeDecomposeGroupId is not null &&
            PlanIterationProgressPolicy.TryResolve(evt, out var progressKind))
            _loopController.RenewIterationLease(progressKind);

        if (!string.Equals(evt.Type, "sdk_diagnostics", StringComparison.Ordinal))
            _pec.MarkActivity(evt);

        if (!string.IsNullOrWhiteSpace(evt.Model))
        {
            var model = evt.Model.Trim();
            _squadCliAdapter.LastObservedModel = model;
            if (!_modelObservedThisSession ||
                !string.Equals(_settingsSnapshot.LastUsedModel, model, StringComparison.Ordinal))
            {
                _modelObservedThisSession = true;
                _settingsManager.Replace(_settingsStore.SaveLastUsedModel(model));
            }
        }

        switch (evt.Type)
        {
            case "session_ready":
                HandleSessionReady(evt);
                break;

            case "session_reset":
                HandleSessionReset(evt);
                break;

            case "thinking_started":
                EnsureCurrentTurnThinkingVisible();
                UpdateLeadAgent("Thinking", string.Empty, "Reasoning through the request.");
                UpdateSessionState("Thinking");
                break;

            case "thinking_delta":
                var thought = NormalizeThinkingChunk(evt.Text);
                if (!string.IsNullOrWhiteSpace(thought))
                {
                    UpdateLeadAgent("Thinking", string.Empty, FormatThinkingText(thought));
                    AppendThinkingText(thought, evt.Speaker);
                }
                break;

            case "tool":
                UpdateLeadAgent(
                    "Tooling",
                    string.Empty,
                    "Waiting for live tool execution events.");
                UpdateSessionState("Using tool");
                break;

            case "tool_start":
                StartToolExecution(evt);
                break;

            case "tool_progress":
                UpdateToolExecution(evt);
                break;

            case "tool_complete":
                CompleteToolExecution(evt);
                break;

            case "response_delta":
                NotePendingQuickReplyCoordinatorResponse();
                AppendText(evt.Chunk ?? string.Empty);
                UpdateLeadAgent("Streaming", string.Empty, "Writing the response.");
                UpdateSessionState("Streaming");
                break;

            case "sdk_diagnostics":
                HandleSdkDiagnostics(evt);
                break;

            case "background_tasks_changed":
                HandleBackgroundTasksChanged(evt);
                break;

            case "task_complete":
                HandleTaskComplete(evt);
                break;

            case "subagent_started":
                HandleSubagentStarted(evt);
                break;

            case "subagent_message_delta":
                HandleSubagentMessageDelta(evt);
                break;

            case "subagent_thinking_delta":
                HandleSubagentThinkingDelta(evt);
                break;

            case "subagent_message":
                HandleSubagentMessage(evt);
                break;

            case "subagent_tool_start":
                HandleSubagentToolStart(evt);
                break;

            case "subagent_tool_progress":
                HandleSubagentToolProgress(evt);
                break;

            case "subagent_tool_complete":
                HandleSubagentToolComplete(evt);
                break;

            case "subagent_completed":
                HandleSubagentCompleted(evt);
                break;

            case "subagent_failed":
                HandleSubagentFailed(evt);
                break;

            case "subagent_throttled":
                HandleSubagentThrottled(evt);
                break;

            case "subagent_resumed":
                HandleSubagentResumed(evt);
                break;

            case "subagent_cancelled":
                HandleSubagentCancelled(evt);
                break;

            case "loop_started":
                HandleLoopStarted(evt);
                break;

            case "loop_iteration":
                HandleLoopIteration(evt);
                break;

            case "loop_stopped":
                HandleLoopStopped(evt);
                _ = _pushNotificationService.NotifyEventAsync("loop_stopped", "SquadDash", "Loop stopped");
                break;

            case "loop_error":
                HandleLoopError(evt);
                break;

            case "loop_output":
                HandleLoopOutput(evt);
                break;

            case "watch_fleet_dispatched":
                HandleWatchFleetDispatched(evt);
                break;

            case "watch_wave_dispatched":
                HandleWatchWaveDispatched(evt);
                break;

            case "watch_hydration":
                HandleWatchHydration(evt);
                break;

            case "watch_retro":
                HandleWatchRetro(evt);
                break;

            case "watch_monitor_notification":
                HandleWatchMonitorNotification(evt);
                break;

            case "rc_prompt":
                EnqueueRcPrompt(evt.Text ?? string.Empty);
                break;

            case "rc_started":
                HandleRcStarted(evt);
                break;

            case "rc_tunnel_started":
                HandleRcTunnelStarted(evt);
                break;

            case "rc_tunnel_error":
                HandleRcTunnelError(evt);
                break;

            case "rc_stopped":
                HandleRcStopped(evt);
                _ = _pushNotificationService.NotifyEventAsync("rc_connection_dropped", "SquadDash", "Remote connection dropped");
                break;

            case "subsquads_listed":
                HandleSubSquadsListed(evt);
                break;

            case "subsquads_activated":
                HandleSubSquadsActivated(evt);
                break;

            case "subsquads_error":
                HandleSubSquadsError(evt);
                break;

            case "personal_agents_listed":
                HandlePersonalAgentsListed(evt);
                break;

            case "personal_init_done":
                HandlePersonalInitDone(evt);
                break;

            case "personal_error":
                HandlePersonalError(evt);
                break;

            case "rc_error":
                HandleRcError(evt);
                break;

            case "rc_audio_start":
                _ = HandleRcAudioStartAsync(evt);
                break;

            case "rc_audio_chunk":
                HandleRcAudioChunk(evt);
                break;

            case "rc_audio_end":
                _ = HandleRcAudioEndAsync(evt);
                break;

            case "done":
                _pec.ActiveToolName = null;
                var doneCurrentTurn = CoordinatorThread.CurrentTurn;
                FinalizeCurrentTurnResponse();
                CollapseCurrentTurnThinking();
                _conversationManager.SaveCurrentTurnToConversation(DateTimeOffset.Now, "bridge-done-event");
                _backgroundTaskPresenter.RefreshLeadAgentBackgroundStatus();
                FlushDeferredSystemLines();
                _leadAgent?.NotifyTurnEnded();
                foreach (var agentThread in _agentThreadRegistry.ThreadOrder)
                    FindAgentCardForThread(agentThread)?.NotifyTurnEnded();
                {
                    var agentName = _leadAgent?.Name ?? "Agent";
                    var rawResponse = doneCurrentTurn?.ResponseTextBuilder.ToString();
                    CaptureExecutingPlanStepResult(rawResponse);
                    var squadashPayload = PushNotificationService.ExtractSquadashPayload(rawResponse);
                    var notifSummary = (squadashPayload?.Notification is { Length: > 0 } sn ? sn : null)
                        ?? PushNotificationService.ExtractNotificationJson(rawResponse)
                        ?? PushNotificationService.BuildFallbackSummary(doneCurrentTurn?.Prompt);
                    var notifMessage = string.IsNullOrWhiteSpace(notifSummary)
                        ? $"{agentName} turn complete"
                        : notifSummary;
                    
                    // Collect tool outputs from main session and all spawned agent threads.
                    // Only include agent thread turns that STARTED at or after this main turn —
                    // SavedTurns accumulates for the entire session lifetime, so without this
                    // guard old turns from previous interactions would re-surface the same
                    // commit SHA on every subsequent turn completion.
                    var turnStartedAt = doneCurrentTurn?.StartedAt ?? DateTimeOffset.Now;
                    var allToolOutputs = new List<string?>();
                    if (doneCurrentTurn?.ToolEntries is not null)
                        allToolOutputs.AddRange(doneCurrentTurn.ToolEntries.Select(e => e.OutputText));
                    foreach (var agentThread in _agentThreadRegistry.ThreadOrder)
                    {
                        foreach (var turn in agentThread.SavedTurns.Where(t => t.StartedAt >= turnStartedAt))
                        {
                            if (turn.Tools is not null)
                                allToolOutputs.AddRange(turn.Tools.Select(t => t.OutputText));
                        }
                        if (agentThread.CurrentTurn?.ToolEntries is not null &&
                            agentThread.CurrentTurn.StartedAt >= turnStartedAt)
                            allToolOutputs.AddRange(agentThread.CurrentTurn.ToolEntries.Select(e => e.OutputText));
                    }

                    // Extract git commit info (SHA + message when available from git native output)
                    var commitInfo = PushNotificationService.ExtractGitCommitInfo(allToolOutputs, rawResponse);
                    if (_activeDecomposeGroupId is not null)
                        _capturedDecomposeTranscriptCommit = commitInfo?.CommitSha;
                    if (commitInfo is not null)
                    {
                        var readAgentOutputs = doneCurrentTurn?.ToolEntries
                            .Where(entry => string.Equals(entry.Descriptor.ToolName, "read_agent", StringComparison.OrdinalIgnoreCase))
                            .Select(entry => entry.OutputText)
                            ?? Enumerable.Empty<string?>();
                        var visibleCoordinatorResponse = GetSanitizedTurnResponseText(doneCurrentTurn);
                        var missingDelegatedNote = PushNotificationService.BuildMissingDelegatedCommitCompletionNote(
                            commitInfo,
                            visibleCoordinatorResponse,
                            readAgentOutputs);
                        if (missingDelegatedNote is not null)
                        {
                            AppendText(CoordinatorThread, "\n\n" + missingDelegatedNote);
                            FinalizeCurrentTurnResponse();
                            _conversationManager.SaveCurrentTurnToConversation(
                                DateTimeOffset.Now,
                                "bridge-done-generated-delegated-commit-note");
                            rawResponse = doneCurrentTurn?.ResponseTextBuilder.ToString();
                            SquadDashTrace.Write(
                                "Agents",
                                $"DelegatedCommitNote.Appended sha={commitInfo.CommitSha} responseChars={rawResponse?.Length ?? 0}");
                        }

                        notifMessage += $" [{commitInfo.CommitSha}]";
                        var commitUrl = _workspaceGitHubUrl is not null
                            ? $"{_workspaceGitHubUrl}/commit/{commitInfo.CommitSha}"
                            : null;
                        _ = _bridge.BroadcastRcCommitAsync(commitInfo.CommitSha, commitUrl);
                        SoundNotifications.Play(SoundEvent.CommitMade);

                        // ── Approval tracking ─────────────────────────────────────────────
                        // Prefer git's commit message when available; fallback to notifSummary or prompt hint
                        var description = !string.IsNullOrWhiteSpace(commitInfo.CommitMessage)
                            ? commitInfo.CommitMessage
                            : BuildApprovalDescription(notifSummary, doneCurrentTurn?.Prompt);
                        var hint = TruncatePromptHint(doneCurrentTurn?.Prompt, maxChars: 60);
                        bool touchesDecisionsFile = CommitTouchesDecisionsFile(commitInfo.CommitSha,
                            _currentWorkspace?.FolderPath ?? _workspacePaths.ApplicationRoot);
                        var featureGroup = commitInfo.FeatureGroup ?? TakePendingApprovalGroup(commitInfo.CommitSha);
                        var item = CommitApprovalItem.Create(commitInfo.CommitSha, commitUrl, description,
                                                                      turnStartedAt, hint,
                                                                      originalPrompt: doneCurrentTurn?.Prompt?.Trim(),
                                                                      touchesDecisionsFile: touchesDecisionsFile,
                                                                      featureGroup: featureGroup);
                        if (featureGroup is not null)
                            _featureGroupStore?.EnsureGroup(featureGroup);
                        // Guard: never add a duplicate SHA — a stale agent CurrentTurn or context
                        // echo can cause the same SHA to be detected on a subsequent turn.
                        var existingApprovalIdx = FindApprovalItemIndexBySha(item.CommitSha);
                        if (existingApprovalIdx < 0)
                        {
                            _approvalItems.Add(item);
                            _approvalStore?.Save(_approvalItems);
                            _approvalPanel?.AddItem(item);
                            SoundNotifications.Play(SoundEvent.ApprovalNeeded);
                        }
                        else if (!string.IsNullOrWhiteSpace(featureGroup) &&
                                 string.IsNullOrWhiteSpace(_approvalItems[existingApprovalIdx].FeatureGroup))
                        {
                            _approvalItems[existingApprovalIdx] = _approvalItems[existingApprovalIdx] with { FeatureGroup = featureGroup };
                            _approvalStore?.Save(_approvalItems);
                            _approvalPanel?.ReplaceAllItems(_approvalItems);
                        }
                        if (!string.IsNullOrWhiteSpace(featureGroup))
                            AnnotateCommitInTranscript(commitInfo.CommitSha, featureGroup);
                        // ─────────────────────────────────────────────────────────────────
                    }
                    _ = _pushNotificationService.NotifyEventAsync("assistant_turn_complete", "SquadDash", notifMessage);
                    SoundNotifications.Play(SoundEvent.PromptComplete);

                    // Process INBOX_MESSAGE_JSON blocks from this turn's response before handling
                    // any loop commands — the inbox must be persisted prior to command dispatch.
                    SquadDashTrace.Write(TraceCategory.Inbox,
                        $"INBOX_SAVE: done-event doneCurrentTurnNull={doneCurrentTurn is null} rawLen={rawResponse?.Length ?? -1}");

                    // For maintenance named-agent-direct runs, CoordinatorThread.CurrentTurn is null
                    // (BeginTranscriptTurn is never called), so rawResponse is null. Fall back to the
                    // latest Argus Weld sub-agent thread response which holds the INBOX_MESSAGE_JSON block.
                    if (rawResponse is null && FindLatestArgusWeldRunThread() is { } argusThread)
                    {
                        var argusResponse = argusThread.CurrentTurn?.ResponseTextBuilder.ToString();
                        if (!string.IsNullOrWhiteSpace(argusResponse))
                        {
                            SquadDashTrace.Write(TraceCategory.Inbox,
                                "INBOX_SAVE: done-event rawResponse was null — falling back to argus-weld thread response");
                            TrySaveInboxMessageFromResponse(argusResponse);
                        }
                    }

                    TrySaveInboxMessageFromResponse(rawResponse);
                    var handledHumanProofCoverageReview =
                        TryHandlePlanHumanProofCoverageReviewFromResponse(rawResponse);
                    if (!handledHumanProofCoverageReview &&
                        string.Equals(_pec.CurrentDispatchedItem?.SourceTag,
                            "plan-human-proof-coverage", StringComparison.Ordinal))
                    {
                        handledHumanProofCoverageReview = HandleMissingPlanHumanProofCoverageReview();
                    }
                    var handledVisualizerReview = TryHandlePlanVisualizerReviewFromResponse(rawResponse);
                    if (doneCurrentTurn?.SuppressTranscript == true &&
                        string.Equals(_pec.CurrentDispatchedItem?.SourceTag,
                            "plan-visualizer-review", StringComparison.Ordinal) &&
                        !handledVisualizerReview)
                    {
                        const string missingReview =
                            "The AI review finished without returning plan-review annotations. Try Review with AI again.";
                        SquadDashTrace.Write("PlanReview", missingReview);
                        foreach (var entry in _openPlanViewerWindows)
                            entry.Window.SetReviewRequestError(missingReview);
                    }

                    // TASKS_JSON is a host payload, not a maintenance-only payload.  Normal
                    // coordinator turns can emit it too, so process it at the same response
                    // finalization boundary as inbox and host-command payloads.  Maintenance
                    // responses remain owned by CodeHealthRunner's capture callback below.
                    if (_CodeHealthRunner?.IsRunning != true)
                    {
                        _lastResponseContainedTaskPlan = false;
                        var hasStagedRevisionPayload = _stagedPlanRevisionTurnCollectionState.Handled ||
                            TryApplyStagedPlanRevisionFromResponse(rawResponse, doneCurrentTurn);
                        var hasAcceptedRevisionPayload = !hasStagedRevisionPayload &&
                            TryStagePlanRevisionProposalFromResponse(rawResponse, doneCurrentTurn);
                        var hasRevisionPayload = hasStagedRevisionPayload || hasAcceptedRevisionPayload;
                        if (!hasRevisionPayload)
                            TryStartDecomposeGroupFromResponse(rawResponse, doneCurrentTurn);
                        var hasTasksPayload = _lastResponseContainedTaskPlan;
                        var hasDecisionPayload = rawResponse?.Contains("DECOMPOSE_DECISION_JSON:", StringComparison.Ordinal) == true;
                        if (hasRevisionPayload)
                        {
                            SquadDashTrace.Write("PlanRevision",
                                hasStagedRevisionPayload
                                    ? "Staged-plan revision protocol response was handled before ordinary plan protocols."
                                    : "Accepted-plan revision protocol response was handled before ordinary plan protocols.");
                        }
                        else if (hasTasksPayload && hasDecisionPayload)
                        {
                            AppendLine("⚠ The response contained both a task proposal and an execution decision. " +
                                       "SquadDash staged the proposal but ignored the decision; approval must come in a later turn.");
                            SquadDashTrace.Write(TraceCategory.General,
                                "Decompose decision ignored because TASKS_JSON appeared in the same response.");
                        }
                        else
                        {
                            TryApplyDecomposeDecisionFromResponse(rawResponse);
                            TryApplyPlanRecoveryAssessmentFromResponse(rawResponse);
                            TryApplyRecoveryOptionsFromResponse(rawResponse);
                            if (!TryRouteInterruptedStepResultToRecovery(rawResponse))
                                _ = ApplyDecomposeRecoveryFromResponseSafelyAsync(rawResponse);
                            var expectsReviewClarification =
                                HumanReviewResponseContractPolicy.RequiresClarificationProtocol(
                                    _pec.CurrentDispatchedItem?.SourceTag);
                            var hasReviewClarification =
                                TryHandleHumanReviewClarificationFromResponse(rawResponse);
                            if (expectsReviewClarification && !hasReviewClarification)
                                hasReviewClarification = HandleMissingHumanReviewClarificationResponse();
                            var hasUnifiedReviewResponse = !hasReviewClarification &&
                                TryHandleUnifiedPlanReviewResponse(rawResponse);
                            var hasReviewActivity = !hasReviewClarification && !hasUnifiedReviewResponse &&
                                TryHandlePlanReviewActivityFromResponse(rawResponse);
                            if (!hasReviewClarification && !hasUnifiedReviewResponse && !hasReviewActivity)
                            {
                                _ = TryHandleGateResponseFromResponseAsync(rawResponse);
                                TryHandleGateApprovalFromResponse(rawResponse);
                            }
                        }

                        if (_decomposeRepairPending && !hasTasksPayload && !handledHumanProofCoverageReview)
                        {
                            StopDecomposeRepair(
                                "The automatic task-plan repair response did not contain TASKS_JSON.");
                        }
                        if (_planRevisionRepairPending && !hasAcceptedRevisionPayload)
                        {
                            _planRevisionRepairPending = false;
                            _planRevisionRepairProposal = null;
                            AppendLine("⚠ The automatic plan-revision repair response did not contain PLAN_REVISION_JSON. " +
                                       "The plan remains unchanged.");
                        }
                        if (_stagedPlanRevisionRepairPending && !hasStagedRevisionPayload)
                        {
                            _stagedPlanRevisionRepairPending = false;
                            _stagedPlanRevisionRepairProposal = null;
                            AppendLine("⚠ The automatic staged-plan repair response did not contain " +
                                       "STAGED_PLAN_REVISION_JSON. The staged proposal remains unchanged.");
                            RestorePendingDecomposeApprovalSurfaces();
                        }
                    }

                    // Moving on to any new Coordinator turn, including a maintenance request,
                    // makes an older unhandled plan durable in the Inbox.
                    PromoteBypassedDecomposePlans(rawResponse);

                    // Handle SquadDash loop commands embedded in the AI response.
                    if (squadashPayload?.Command is string cmd)
                        HandleSquadashCommand(cmd);
                    if (_hostCommandExecutor is not null && rawResponse is not null)
                    {
                        var rawForCommandParsing = ToolTranscriptFormatter.StripSystemNotifications(rawResponse);
                        var commandResults = _hostCommandExecutor.TryParseAndExecute(
                            rawForCommandParsing, _hostCommandRegistry, _currentWorkspace?.FolderPath, out _);
                        if (commandResults is not null)
                        {
                            foreach (var (invocation, descriptor, result) in commandResults)
                            {
                                doneCurrentTurn?.HostCommandEntries.Add(new HostCommandTranscriptEntry(
                                    doneCurrentTurn, invocation, descriptor, result, DateTimeOffset.Now));

                                if (descriptor.ResultBehavior == HostCommandResultBehavior.InjectResultAsContext && result.HasOutput)
                                {
                                    _promptQueue.EnqueueAtFront(result.Output!, _promptQueueCoordinator.NextSequenceNumber());
                                    SyncQueuePanel();
                                    SyncSendButton();
                                }
                            }
                        }
                    }
                }
                if (_pendingRcRestartAfterReset)
                {
                    _pendingRcRestartAfterReset = false;
                    _ = RestartRcAfterSessionResetAsync();
                }
                break;

            case "error":
                PromoteBypassedDecomposePlans(null);
                _pec.ActiveToolName = null;
                _conversationManager.SaveCurrentTurnToConversation(DateTimeOffset.Now, "bridge-done-final-notification");
                HandlePromptFailure(evt);
                UpdateSessionState("Error");
                FlushDeferredSystemLines();
                SoundNotifications.Play(SoundEvent.PromptError);
                break;
        }
    }

    private void TraceSdkEvent(SquadSdkEvent evt)
    {
        switch (evt.Type)
        {
            case "thinking_delta":
            case "subagent_thinking_delta":
                _pendingThinkingDeltaTraceCount++;
                _pendingThinkingDeltaTraceChars += evt.Text?.Length ?? 0;
                FlushSdkDeltaTraceIfDue(force: false);
                return;

            case "response_delta":
                _pendingResponseDeltaTraceCount++;
                _pendingResponseDeltaTraceChars += evt.Chunk?.Length ?? 0;
                FlushSdkDeltaTraceIfDue(force: false);
                return;

            case "subagent_tool_start":
            case "subagent_tool_progress":
            case "subagent_tool_complete":
                if (string.Equals(evt.ToolName, "view", StringComparison.OrdinalIgnoreCase))
                {
                    TraceSubagentViewToolEvent();
                    return;
                }
                break;

            default:
                break;
        }

        FlushSdkDeltaTraceIfDue(force: true);
        FlushSubagentViewToolTraceIfDue(force: true);
        SquadDashTrace.Write(
            "UI",
            $"HandleEvent type={evt.Type ?? "(null)"} tool={evt.ToolName ?? "(none)"} chunkLen={evt.Chunk?.Length ?? 0}");
    }

    private void FlushSdkDeltaTraceIfDue(bool force)
    {
        if (!force && _sdkDeltaTraceStopwatch.ElapsedMilliseconds < 1000)
            return;

        var thinkingCount = _pendingThinkingDeltaTraceCount;
        var responseCount = _pendingResponseDeltaTraceCount;
        if (thinkingCount == 0 && responseCount == 0)
            return;

        var elapsedMs = Math.Max(1, _sdkDeltaTraceStopwatch.ElapsedMilliseconds);
        SquadDashTrace.Write(
            "UI",
            $"HandleEvent stream_delta summary elapsed={elapsedMs}ms " +
            $"thinkingCount={thinkingCount} thinkingChars={_pendingThinkingDeltaTraceChars} " +
            $"responseCount={responseCount} responseChars={_pendingResponseDeltaTraceChars}");

        _pendingThinkingDeltaTraceCount = 0;
        _pendingThinkingDeltaTraceChars = 0;
        _pendingResponseDeltaTraceCount = 0;
        _pendingResponseDeltaTraceChars = 0;
        _sdkDeltaTraceStopwatch.Restart();
    }

    private void TraceSubagentViewToolEvent()
    {
        FlushSdkDeltaTraceIfDue(force: true);
        _pendingSubagentViewToolTraceCount++;
        FlushSubagentViewToolTraceIfDue(force: false);
    }

    private void FlushSubagentViewToolTraceIfDue(bool force)
    {
        if (_pendingSubagentViewToolTraceCount == 0)
            return;

        if (!force && _subagentViewToolTraceStopwatch.ElapsedMilliseconds < 1000)
            return;

        var elapsedMs = Math.Max(1, _subagentViewToolTraceStopwatch.ElapsedMilliseconds);
        SquadDashTrace.Write(
            "UI",
            $"HandleEvent subagent view tool summary elapsed={elapsedMs}ms count={_pendingSubagentViewToolTraceCount}");
        _pendingSubagentViewToolTraceCount = 0;
        _subagentViewToolTraceStopwatch.Restart();
    }

    private void HandleSdkDiagnostics(SquadSdkEvent evt)
    {
        var summary = evt.DiagnosticPhase switch
        {
            "send_started" => $"send started method={evt.SendMethod ?? "(unknown)"}",
            "first_sdk_event" => $"first sdk event type={evt.DiagnosticEventType ?? evt.FirstSdkEventType ?? "(unknown)"} after={FormatSdkDiagnosticMs(evt.MillisecondsSinceSendStart)}",
            "first_thinking_event" => $"first thinking event after={FormatSdkDiagnosticMs(evt.TimeToFirstThinkingMs)}",
            "first_response_event" => $"first response event after={FormatSdkDiagnosticMs(evt.TimeToFirstResponseMs)}",
            "send_completed" => $"send completed total={FormatSdkDiagnosticMs(evt.MillisecondsSinceSendStart)} firstSdk={FormatSdkDiagnosticMs(evt.TimeToFirstSdkEventMs)} firstThinking={FormatSdkDiagnosticMs(evt.TimeToFirstThinkingMs)} firstResponse={FormatSdkDiagnosticMs(evt.TimeToFirstResponseMs)}",
            "send_failed" => $"send failed total={FormatSdkDiagnosticMs(evt.MillisecondsSinceSendStart)} firstSdk={FormatSdkDiagnosticMs(evt.TimeToFirstSdkEventMs)} firstThinking={FormatSdkDiagnosticMs(evt.TimeToFirstThinkingMs)} firstResponse={FormatSdkDiagnosticMs(evt.TimeToFirstResponseMs)} message={evt.Message ?? "(none)"}",
            "named_agent_handoff" => $"named-agent handoff {evt.Message ?? "(none)"}",
            "background_cancel_requested" => $"background cancel requested taskId={evt.TaskId ?? "(none)"} {evt.Message ?? "(none)"}",
            "background_cancel_completed" => $"background cancel completed taskId={evt.TaskId ?? "(none)"} {evt.Message ?? "(none)"}",
            _ => $"phase={evt.DiagnosticPhase ?? "(unknown)"} event={evt.DiagnosticEventType ?? evt.FirstSdkEventType ?? "(none)"} after={FormatSdkDiagnosticMs(evt.MillisecondsSinceSendStart)} message={evt.Message ?? "(none)"}"
        };

        SquadDashTrace.Write("SDK", summary);
    }

    private static string FormatSdkDiagnosticMs(int? value)
    {
        return value is int ms
            ? $"{ms}ms"
            : "(n/a)";
    }

    private void HandleBridgeError(string text)
    {
        SquadDashTrace.Write("UI", $"Bridge stderr: {text}");
        _pec.MarkActivity("bridge-stderr");

        if (text.Contains("ExperimentalWarning: SQLite") ||
            text.Contains("Use `node --trace-warnings") ||
            text.Contains("SquadClient connection took"))
        {
            return;
        }

        AppendLine("[stderr] " + text, ThemeBrush("SystemErrorText"));
    }

    private void HandleSessionReady(SquadSdkEvent evt)
    {
        if (_currentWorkspace is null || string.IsNullOrWhiteSpace(evt.SessionId))
            return;

        var sessionChanged = !string.Equals(
            _conversationManager.CurrentSessionId,
            evt.SessionId,
            StringComparison.OrdinalIgnoreCase);
        if (sessionChanged && evt.SessionResumed != true && _recentDelegationOutcomes.Count > 0)
        {
            _recentDelegationOutcomes.Clear();
            SquadDashTrace.Write("Routing", "Delegation outcome rollup reset for fresh coordinator session.");
        }

        _conversationManager.CurrentSessionId = evt.SessionId;
        _conversationManager.PersistConversationState(_conversationManager.ConversationState with
        {
            SessionId = _conversationManager.CurrentSessionId,
            SessionUpdatedAt = DateTimeOffset.UtcNow
        });

        SquadDashTrace.Write(
            "UI",
            $"Session ready id={evt.SessionId} resumed={evt.SessionResumed?.ToString() ?? "(unknown)"} diagnostics={SessionResumeDiagnosticsPresentation.BuildSummary(evt) ?? "(none)"}");
    }

    private void HandleSessionReset(SquadSdkEvent evt)
    {
        var diagnostics = PromptContextDiagnosticsPresentation.BuildTraceSummary(
            _conversationManager.CapturePromptContextDiagnostics(),
            DateTimeOffset.UtcNow);
        SquadDashTrace.Write(
            "Routing",
            $"Session reset requested after provider rejection. {diagnostics}");
        if (_recentDelegationOutcomes.Count > 0)
        {
            _recentDelegationOutcomes.Clear();
            SquadDashTrace.Write("Routing", "Delegation outcome rollup cleared after session reset.");
        }
        _conversationManager.CurrentSessionId = null;

        if (_currentWorkspace is not null)
        {
            _conversationManager.PersistConversationState(_conversationManager.ConversationState with
            {
                SessionId = null,
                SessionUpdatedAt = DateTimeOffset.UtcNow
            });
        }

        AppendLine(
            "[info] " + (string.IsNullOrWhiteSpace(evt.Message)
                ? "Squad reset the previous session after a provider error and is retrying your prompt in a fresh session."
                : evt.Message),
            ThemeBrush("SystemInfoText"));
        UpdateLeadAgent("Recovering", string.Empty, "Resetting the active Squad session and retrying the prompt.");
        UpdateSessionState("Recovering");

        if (_remoteAccessActive)
            _pendingRcRestartAfterReset = true;
    }

    private void HandleBackgroundTasksChanged(SquadSdkEvent evt)
    {
        _hasAuthoritativeBackgroundTaskSnapshot = true;
        var previousAgents = _backgroundTaskPresenter.BackgroundAgents;
        var previousShells = _backgroundTaskPresenter.BackgroundShells;
        _backgroundTaskPresenter.BackgroundAgents = evt.BackgroundAgents ?? Array.Empty<SquadBackgroundAgentInfo>();
        _backgroundTaskPresenter.BackgroundShells = evt.BackgroundShells ?? Array.Empty<SquadBackgroundShellInfo>();
        foreach (var shell in _backgroundTaskPresenter.BackgroundShells)
            if (!string.IsNullOrWhiteSpace(shell.ShellId) && !string.IsNullOrWhiteSpace(shell.Description))
                _shellDescriptions[shell.ShellId] = shell.Description;

        _agentThreadRegistry.SyncBackgroundAgentThreads(_backgroundTaskPresenter.BackgroundAgents);
        if (_workspaceConversationHydrated)
            ReconcileRestoredIncompleteToolsFromBackgroundSnapshot();
        SyncAgentCardsWithThreads();

        SquadDashTrace.Write(
            "UI",
            $"Background tasks updated session={evt.SessionId ?? _conversationManager.CurrentSessionId ?? "(unknown)"} {_backgroundTaskPresenter.BuildBackgroundTaskTraceSummary()}");

        _backgroundTaskPresenter.HandleRemovedBackgroundTasks(previousAgents, previousShells);

        if (!_isPromptRunning)
            _backgroundTaskPresenter.RefreshLeadAgentBackgroundStatus();

        UpdateInteractiveControlState();
        DrainQueueAfterBackgroundWorkChanged("background-tasks-changed");
        if (!_restartPending)
            ApplyPendingBridgeSettingsRestartIfIdle("background-tasks-changed");
        TryCompletePendingRestart("background-tasks-changed");
    }

    private void ReconcileRestoredIncompleteToolsFromBackgroundSnapshot()
    {
        var reconciliations = _conversationManager.ReconcileRestoredIncompleteTools(
            _backgroundTaskPresenter.BackgroundAgents,
            DateTimeOffset.UtcNow);
        foreach (var reconciliation in reconciliations)
        {
            ToolTranscriptEntry? entry = null;
            if (!string.IsNullOrWhiteSpace(reconciliation.ToolCallId) &&
                _agentThreadRegistry.TryGetToolEntry(reconciliation.ToolCallId, out var entryById))
            {
                entry = entryById;
            }
            entry ??= _agentThreadRegistry.ToolEntries.Values.FirstOrDefault(candidate =>
                !candidate.IsCompleted &&
                candidate.StartedAt == reconciliation.StartedAt &&
                string.Equals(
                    candidate.Descriptor.ToolName,
                    reconciliation.Descriptor.ToolName,
                    StringComparison.OrdinalIgnoreCase));
            if (entry is null)
                continue;

            entry.FinishedAt = reconciliation.FinishedAt;
            entry.ProgressText = reconciliation.ProgressText;
            entry.OutputText = reconciliation.OutputText;
            entry.DetailContent = reconciliation.DetailContent;
            entry.IsCompleted = true;
            entry.Success = reconciliation.Success;
            RenderToolEntry(entry);
        }

        if (reconciliations.Count > 0)
        {
            UpdateToolSpinnerState();
            SyncActiveToolName();
            SquadDashTrace.Write(
                "Persistence",
                $"Reconciled {reconciliations.Count} restored tool entr{(reconciliations.Count == 1 ? "y" : "ies")} from authoritative background-task snapshot.");
        }
    }

    private bool ShouldIgnoreForceStoppedBridgeEvent(SquadSdkEvent evt)
    {
        if (evt.BridgeProcessGeneration <= 0 ||
            evt.BridgeProcessGeneration > _ignoreBridgeEventsThroughGeneration)
            return false;

        SquadDashTrace.Write(
            "Bridge",
            $"Ignored event from force-stopped bridge generation={evt.BridgeProcessGeneration} type={evt.Type ?? "(none)"} session={evt.SessionId ?? "(none)"} requestId={evt.RequestId ?? "(none)"}");
        return true;
    }

    private void HandleTaskComplete(SquadSdkEvent evt)
    {
        SquadDashTrace.Write(
            "UI",
            $"Background task completed summary={evt.Summary ?? "(none)"}");

        if (!string.IsNullOrWhiteSpace(evt.Summary))
        {
            _backgroundTaskPresenter.SkipNextBackgroundCompletionFallback = true;
            _backgroundTaskPresenter.RecordBackgroundCompletion(
                evt.Summary.Trim(),
                $"task-summary:{evt.Summary.Trim()}");
        }

        if (!_isPromptRunning && !_backgroundTaskPresenter.HasBackgroundTasks())
            _backgroundTaskPresenter.RefreshLeadAgentBackgroundStatus();
    }

    private void HandleSubagentStarted(SquadSdkEvent evt)
    {
        var matchedPendingQuickReply = _pendingQuickReplyLaunch is { ExpectedAgentStarted: false } pendingLaunch &&
                                       QuickReplyAgentLaunchPolicy.MatchesExpectedAgent(
                                           pendingLaunch.ExpectedAgentHandle,
                                           pendingLaunch.ExpectedAgentLabel,
                                           evt);
        NotePendingQuickReplySubagentStarted(evt);
        if (ShouldSuppressSilentBackgroundAgent(evt))
        {
            SquadDashTrace.Write("UI", $"Silent background agent started agent={evt.AgentDisplayName ?? evt.AgentName ?? evt.AgentId ?? "(unknown)"}");
            return;
        }

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        
        // Mark as inbox-launched if this agent was dispatched from an inbox action
        if (!string.IsNullOrWhiteSpace(evt.AgentName) && _inboxLaunchedAgentHandles.Contains(evt.AgentName))
        {
            thread.LaunchedFromInbox = true;
            _inboxLaunchedAgentHandles.Remove(evt.AgentName);
            SquadDashTrace.Write(TraceCategory.Inbox, $"Marked agent thread as inbox-launched: {evt.AgentName}");
        }
        
        _agentThreadRegistry.EnsureAgentThreadTurnStarted(thread);
        _agentThreadRegistry.UpdateAgentThreadLifecycle(thread, evt, statusText: "Running", detailText: evt.AgentDescription ?? "Background work started.");
        if (matchedPendingQuickReply)
            TrackDirectQuickReplyAgentThread(thread);
        SquadDashTrace.Write(
            "UI",
            $"Subagent started {BackgroundTaskPresenter.BuildBackgroundAgentLabel(thread)} description={evt.AgentDescription?.Trim() ?? "(none)"}");
        SyncAgentCardsWithThreads();
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_started");
        // Persist the coordinator turn as an in-progress snapshot. It must not acquire a
        // CompletedAt timestamp until the delegated worker returns and the coordinator turn
        // actually finishes; otherwise an active delegation is presented as failed history.
        _conversationManager.PersistAgentThreadSnapshot(thread);
    }

    private void HandleSubagentMessageDelta(SquadSdkEvent evt)
    {
        if (ShouldSuppressSilentBackgroundAgent(evt))
            return;

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        MaybeReactivateThread(thread);
        _agentThreadRegistry.EnsureAgentThreadTurnStarted(thread);
        thread.StatusText = "Streaming";
        thread.IsCurrentBackgroundRun = true;
        if (!string.IsNullOrWhiteSpace(evt.Chunk))
        {
            AppendText(thread, evt.Chunk!);
            thread.ResponseStreamed = true;
            thread.LatestResponse = GetSanitizedTurnResponseTextOrNull(thread.CurrentTurn);
        }

        if (!string.IsNullOrWhiteSpace(thread.LatestResponse))
            thread.DetailText = BuildThreadPreview(thread.LatestResponse!);

        SyncThreadChip(thread);
        PulseAgentActivity(FindAgentCardForThread(thread), SpinnerActivityKind.Reading, thread);
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_message_delta");
        UpdateAgentCardFromThread(thread, syncBuckets: true);
        _conversationManager.SchedulePersistAgentThreadSnapshot(thread);
    }

    private void HandleSubagentThinkingDelta(SquadSdkEvent evt)
    {
        if (ShouldSuppressSilentBackgroundAgent(evt))
            return;

        var thought = NormalizeThinkingChunk(evt.Text ?? evt.ReasoningText);
        if (string.IsNullOrWhiteSpace(thought))
            return;

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        MaybeReactivateThread(thread);
        _agentThreadRegistry.EnsureAgentThreadTurnStarted(thread);
        thread.StatusText = "Thinking";
        thread.IsCurrentBackgroundRun = true;
        AppendThinkingText(thread, thought, thread.Title);
        thread.DetailText = FormatThinkingText(thought);
        SyncThreadChip(thread);
        PulseAgentActivity(FindAgentCardForThread(thread), SpinnerActivityKind.Thinking, thread);
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_thinking_delta");
        UpdateAgentCardFromThread(thread, syncBuckets: true);
        _conversationManager.SchedulePersistAgentThreadSnapshot(thread);
    }

    private void HandleSubagentMessage(SquadSdkEvent evt)
    {
        if (ShouldSuppressSilentBackgroundAgent(evt))
            return;

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        MaybeReactivateThread(thread);
        _agentThreadRegistry.EnsureAgentThreadTurnStarted(thread);
        thread.IsCurrentBackgroundRun = true;

        if (!string.IsNullOrWhiteSpace(evt.ReasoningText))
            AppendThinkingText(thread, evt.ReasoningText!, thread.Title);

        if (!string.IsNullOrWhiteSpace(evt.Text))
            ReconcileFinalSubagentResponseText(thread, evt.Text!);

        thread.LatestResponse = GetSanitizedTurnResponseTextOrNull(thread.CurrentTurn);
        thread.DetailText = !string.IsNullOrWhiteSpace(thread.LatestResponse)
            ? BuildThreadPreview(thread.LatestResponse!)
            : thread.DetailText;
        // Save inbox message BEFORE finalizing/rendering so the indicator paragraph is rendered
        // with a valid messageId (clickable link) rather than null (grey plain text).
        var rawResponse = thread.CurrentTurn?.ResponseTextBuilder.ToString();
        SquadDashTrace.Write(TraceCategory.Inbox,
            $"INBOX_SAVE: HandleSubagentMessage agent={thread.AgentId ?? thread.Title} currentTurnNull={thread.CurrentTurn is null} rawLen={rawResponse?.Length ?? -1}");
        if (string.IsNullOrWhiteSpace(rawResponse) && thread.ResponseStreamed)
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: HandleSubagentMessage — ResponseTextBuilder empty despite streaming for agent={thread.AgentId ?? thread.Title}");
        var messageId = TrySaveInboxMessageFromResponse(rawResponse);
        if (messageId is not null && thread.CurrentTurn?.ResponseEntries.Count > 0)
            thread.CurrentTurn.ResponseEntries[^1].InboxMessageId = messageId;

        FinalizeCurrentTurnResponse(thread);

        // Set or clear the completion-footer alias annotation (visual-only; does NOT write to
        // ResponseTextBuilder and is NOT part of the transcript search index).
        // Prefer the SDK event value; fall back to the named-agent route we sent at launch time.
        var subagentMsgAlias = evt.ProfileAlias;
        if (string.IsNullOrEmpty(subagentMsgAlias))
            subagentMsgAlias = ResolveRouteProfileAlias(thread);
        thread.CompletionFooterProfileAlias = string.IsNullOrEmpty(subagentMsgAlias) ? null : subagentMsgAlias;

        thread.ResponseStreamed = false;
        FindAgentCardForThread(thread)?.NotifyTurnEnded();

        SyncThreadChip(thread);
        UpdateAgentCardFromThread(thread);
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_message");
        _conversationManager.SaveAgentThreadToConversation(thread, DateTimeOffset.UtcNow);
    }

    private void ReconcileFinalSubagentResponseText(TranscriptThreadState thread, string finalText)
    {
        if (string.IsNullOrWhiteSpace(finalText))
            return;

        _agentThreadRegistry.EnsureAgentThreadTurnStarted(thread);
        var builder = thread.CurrentTurn?.ResponseTextBuilder;
        if (builder is null)
        {
            thread.LatestResponse = SanitizeResponseTextOrNull(finalText);
            return;
        }

        var current = builder.ToString();
        var merged = TranscriptTextUtilities.MergeStreamingAndFinalResponse(
            current,
            finalText,
            out var tailToAppend);

        if (!string.IsNullOrEmpty(tailToAppend))
        {
            AppendText(thread, tailToAppend);
        }
        else if (!string.Equals(merged, current, StringComparison.Ordinal))
        {
            builder.Clear();
            builder.Append(merged);
        }

        thread.LatestResponse = SanitizeResponseTextOrNull(merged);
    }

