    private void ObserveSubagentToolActivityIfMeaningful(
        TranscriptThreadState thread,
        SquadSdkEvent evt,
        string reason)
    {
        if (!PromptExecutionController.ShouldCountPromptActivity(evt, _restartPending))
        {
            SquadDashTrace.Write(
                "Agents",
                $"Ignored restart-pending delay-only subagent tool activity thread={thread.ThreadId} tool={evt.ToolName ?? "(none)"} reason={reason}");
            return;
        }

        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, reason);
    }

    private void HandleSubagentCompleted(SquadSdkEvent evt)
    {
        TryCollectStagedPlanRevisionFromVerifiedAgent(evt);
        if (ShouldSuppressSilentBackgroundAgent(evt))
        {
            SquadDashTrace.Write("UI", $"Silent background agent completed agent={evt.AgentDisplayName ?? evt.AgentName ?? evt.AgentId ?? "(unknown)"}");
            return;
        }

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        if (IsArgusWeldThread(thread))
            thread.SuppressCoordinatorPromotion = true;
        if (!string.IsNullOrWhiteSpace(evt.LatestResponse))
            ReconcileFinalSubagentResponseText(thread, evt.LatestResponse!);
        var directTaskPlanHandled = TryCollectInboxLaunchedTaskPlan(thread, evt.LatestResponse);
        _agentThreadRegistry.UpdateAgentThreadLifecycle(thread, evt, statusText: "Completed", detailText: AgentThreadRegistry.BuildThreadCompletionDetail(thread, evt));
        RecordPlanAgentCompletion(thread, evt, succeeded: true);
        // Pass the raw (unsanitized) response so ParseAndApplyApprovalGroups can detect
        // APPROVAL_GROUP_JSON blocks that SanitizeResponseText strips from display.
        _agentThreadRegistry.FinalizeAgentThread(thread, rawResponse: evt.LatestResponse);
        // Set or clear the completion-footer alias from the completion event. This mirrors the
        // same logic in HandleSubagentMessage and ensures the alias is always current when
        // UpdateCompletedTimeFooters creates the footer paragraph. Prefer the SDK event value;
        // fall back to the named-agent route we sent at launch time. If neither is available,
        // preserve whatever HandleSubagentMessage may have set.
        var subagentCompletedAlias = evt.ProfileAlias;
        if (string.IsNullOrEmpty(subagentCompletedAlias))
            subagentCompletedAlias = ResolveRouteProfileAlias(thread);
        if (!string.IsNullOrEmpty(subagentCompletedAlias))
            thread.CompletionFooterProfileAlias = subagentCompletedAlias;
        // If subagentCompletedAlias is still empty here, trust whatever HandleSubagentMessage already set.
        SquadDashTrace.Write("UI", $"HandleSubagentCompleted alias resolution: evtAlias={evt.ProfileAlias ?? "(null)"} resolvedAlias={subagentCompletedAlias ?? "(null)"} handle={thread.AgentId ?? thread.RequestedAgentHandle ?? "(unknown)"} footerAlias={thread.CompletionFooterProfileAlias ?? "(null)"}");
        UpdateCompletedTimeFooters();
        var summary = BackgroundTaskPresenter.BuildThreadCompletionSummary(thread);
        SquadDashTrace.Write("UI", $"Subagent completed {summary}");
        
        // If this agent was launched from an inbox action, also display the response in the Coordinator transcript
        if (thread.LaunchedFromInbox && !string.IsNullOrWhiteSpace(thread.LatestResponse))
        {
            var agentName = thread.AgentDisplayName ?? thread.AgentName ?? "Agent";
            var attributionLine = $"**{agentName} responded:**";
            
            AppendLine(CoordinatorThread, attributionLine, ThemeBrush("SubtleText"));
            AppendLine(CoordinatorThread, thread.LatestResponse!, null);
            
            SquadDashTrace.Write(
                TraceCategory.Inbox, 
                $"Added inbox-launched agent response to Coordinator transcript: {agentName} ({thread.LatestResponse!.Length} chars)");
        }
        
        var needsDirectQuickReplyFollowUp = CompleteDirectQuickReplyAgentThread(thread, "subagent_completed");

        var promoted = _backgroundTaskPresenter.PromoteBackgroundAgentReportNow(thread, "subagent_completed");
        switch (DirectQuickReplyCompletionPolicy.Decide(
                    needsDirectQuickReplyFollowUp,
                    _isPromptRunning,
                    promoted,
                    directTaskPlanHandled))
        {
            case DirectQuickReplyCompletionAction.RegisterSilentWatchdog:
                _pec.NotifySubagentCompletedDuringTurn(thread, thread.Title ?? evt.AgentDisplayName ?? evt.AgentName ?? "Unknown agent");
                break;
            case DirectQuickReplyCompletionAction.EnqueueCoordinatorFollowUp:
                EnqueueDirectQuickReplyAgentFollowUp(thread);
                break;
        }
        _backgroundTaskPresenter.SkipNextBackgroundCompletionFallback = true;
        _backgroundTaskPresenter.RecordBackgroundCompletion(summary, BackgroundTaskPresenter.BuildThreadAnnouncementKey(thread), appendNotice: !promoted);
        SyncAgentCardsWithThreads();
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_completed");
        _conversationManager.SaveAgentThreadToConversation(thread, DateTimeOffset.UtcNow);
        DrainQueueAfterBackgroundWorkChanged("subagent-completed");
        TryCompletePendingRestart("subagent-completed");
    }

    private bool TryCollectInboxLaunchedTaskPlan(
        TranscriptThreadState thread,
        string? rawResponse)
    {
        if (!thread.LaunchedFromInbox ||
            rawResponse?.Contains("TASKS_JSON:", StringComparison.Ordinal) != true)
        {
            return false;
        }

        TryStartDecomposeGroupFromResponse(rawResponse, thread.CurrentTurn);
        if (!_lastResponseContainedTaskPlan)
            return false;

        SquadDashTrace.Write(
            "PlanRouting",
            $"Collected TASKS_JSON directly from inbox-launched agent thread={thread.ThreadId} agent={thread.AgentId ?? thread.Title ?? "(unknown)"}; suppressed generic silent-completion recovery.");
        return true;
    }

    private void HandleSubagentFailed(SquadSdkEvent evt)
    {
        if (ShouldSuppressSilentBackgroundAgent(evt))
        {
            SquadDashTrace.Write("UI", $"Silent background agent failed agent={evt.AgentDisplayName ?? evt.AgentName ?? evt.AgentId ?? "(unknown)"} message={evt.Message ?? "(none)"}");
            return;
        }

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        var agentLabel = BackgroundTaskPresenter.BuildBackgroundAgentLabel(thread);
        var failure = ProviderFailurePresentation.Analyze(evt.Message, BuildProviderFailureContext(evt));
        var summary = failure.BuildThreadSummary(agentLabel);
        var status = ProviderFailureRecoveryPolicy.BuildThreadStatus(failure.Category);
        var detail = ProviderFailureRecoveryPolicy.IsRecoverableInterruption(failure.Category)
            ? summary + " Partial work and child-agent output remain available for recovery."
            : summary;
        _agentThreadRegistry.UpdateAgentThreadLifecycle(thread, evt, statusText: status, detailText: detail);
        thread.ErrorText = failure.RawError;
        thread.DetailText = detail;
        RecordPlanAgentCompletion(thread, evt, succeeded: false);
        _agentThreadRegistry.FinalizeAgentThread(thread);
        ProviderFailureTranscriptBlockFactory.Append(thread, failure, agentLabel, _transcriptFontSize);
        ProviderFailureTranscriptBlockFactory.AppendAggregated(
            CoordinatorThread,
            failure,
            agentLabel,
            _transcriptFontSize,
            evt.SessionId ?? evt.RequestId ?? "current-provider-operation",
            thread.CompletedAt ?? DateTimeOffset.Now,
            thread.ThreadId);
        ScrollToEndIfAtBottom(thread);
        ScrollToEndIfAtBottom(CoordinatorThread);
        StopRequiredPlanWorkAfterProviderFailure(thread, failure, agentLabel);
        UpdateCompletedTimeFooters();
        SquadDashTrace.Write("UI", $"Subagent {status.ToLowerInvariant()} {summary}");
        CompleteDirectQuickReplyAgentThread(thread, "subagent_failed");

        _backgroundTaskPresenter.SkipNextBackgroundCompletionFallback = true;
        SyncAgentCardsWithThreads();
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_failed");
        _conversationManager.SaveAgentThreadToConversation(thread, DateTimeOffset.UtcNow);
        DrainQueueAfterBackgroundWorkChanged("subagent-failed");
        TryCompletePendingRestart("subagent-failed");
    }

    private void HandleSubagentThrottled(SquadSdkEvent evt)
    {
        if (ShouldSuppressSilentBackgroundAgent(evt))
            return;

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        MaybeReactivateThread(thread);
        _agentThreadRegistry.EnsureAgentThreadTurnStarted(thread);
        var observedAt = DateTimeOffset.Now;
        thread.ThrottleRetryAt = ProviderThrottlePresentation.ResolveRetryAt(
            evt.RetryAt,
            evt.RetryDelayMs,
            observedAt);
        var retryLabel = evt.RetryCount is > 0 ? $"retry {evt.RetryCount}" : "retry";
        var delayLabel = evt.RetryDelayMs is > 0
            ? $" in {TimeSpan.FromMilliseconds(evt.RetryDelayMs.Value):g}"
            : string.Empty;
        var detail = $"Waiting for the provider rate limit to clear before {retryLabel}{delayLabel}; the agent keeps ownership of the task.";
        _agentThreadRegistry.UpdateAgentThreadLifecycle(thread, evt, statusText: "Throttled", detailText: detail);
        ProviderThrottleTranscriptBlockFactory.Append(
            thread,
            ProviderThrottlePresentation.BuildTranscriptNotice(evt.RetryDelayMs),
            observedAt,
            AllocateNarrativeSequence(thread.CurrentTurn!));
        SyncThreadChip(thread);
        FindAgentCardForThread(thread)?.NotifyActivityPaused();
        UpdateAgentCardFromThread(thread, syncBuckets: true);
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_throttled");
        _conversationManager.SchedulePersistAgentThreadSnapshot(thread);
        SquadDashTrace.Write(
            "UI",
            $"Subagent throttled agent={evt.AgentDisplayName ?? evt.AgentName ?? evt.AgentId ?? "(unknown)"} retry={evt.RetryCount?.ToString() ?? "(unknown)"} delayMs={evt.RetryDelayMs?.ToString() ?? "(unknown)"}");
    }

    private void HandleSubagentResumed(SquadSdkEvent evt)
    {
        if (ShouldSuppressSilentBackgroundAgent(evt))
            return;

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        MaybeReactivateThread(thread);
        _agentThreadRegistry.EnsureAgentThreadTurnStarted(thread);
        thread.ThrottleRetryAt = null;
        _agentThreadRegistry.UpdateAgentThreadLifecycle(
            thread,
            evt,
            statusText: "Running",
            detailText: "Provider wait ended; resuming work.");
        SyncThreadChip(thread);
        PulseAgentActivity(FindAgentCardForThread(thread), SpinnerActivityKind.Thinking, thread);
        UpdateAgentCardFromThread(thread, syncBuckets: true);
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_resumed");
        _conversationManager.SchedulePersistAgentThreadSnapshot(thread);
        SquadDashTrace.Write(
            "UI",
            $"Subagent resumed after throttling agent={evt.AgentDisplayName ?? evt.AgentName ?? evt.AgentId ?? "(unknown)"} retry={evt.RetryCount?.ToString() ?? "(unknown)"}");
    }

    private void StopRequiredPlanWorkAfterProviderFailure(
        TranscriptThreadState thread,
        ProviderFailurePresentation failure,
        string agentLabel)
    {
        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        var planExecutionActive = _activeDecomposeGroupId is not null || activeExecution?.IsExecutingPlan == true;
        if (ProviderFailureContinuationPolicy.ShouldPauseRequiredPlanWork(
                failure.Category,
                _isPromptRunning,
                planExecutionActive,
                thread.AssignedPlanTaskId,
                thread.RosterIdentityVerified))
        {
            var providerWaitReason =
                $"Required plan agent {agentLabel} could not complete because {failure.Title}. " +
                "SquadDash could not recover the provider request and paused the plan without discarding repository work.";
            _planProviderWaitInterruptionReason = providerWaitReason;
            SquadDashTrace.Write(
                "UI",
                $"Required plan agent provider throttling is pausing execution task={thread.AssignedPlanTaskId} " +
                $"agent={thread.AgentName ?? agentLabel} category={failure.Category}");

            SuppressLoopResume("required-plan-agent-provider-wait");
            DiscardObsoletePlanQueueItems("required-plan-agent-provider-wait");
            SetQueueRecoveryHoldForRequiredPlan(thread, providerWaitReason);
            if (IsLoopRunning)
            {
                if (_activeLoopMode == LoopMode.NativeAgents)
                {
                    _loopController.RequestStop();
                    _loopFollowUpTcs?.TrySetResult(false);
                }
                else
                {
                    _ = _bridge.StopLoopAsync();
                }
            }

            ScheduleDecomposeSystemEntry(
                providerWaitReason + " Resume the preserved plan after provider access is available.");
            return;
        }

        if (!ProviderFailureContinuationPolicy.ShouldInterruptRequiredPlanWork(
                failure.Category,
                _isPromptRunning,
                planExecutionActive,
                thread.AssignedPlanTaskId,
                thread.RosterIdentityVerified))
        {
            return;
        }

        var reason =
            $"Required plan agent {agentLabel} could not complete because {failure.Title}. " +
            "SquadDash stopped the coordinator and plan loop so no dependent work runs with a missing required result.";
        SquadDashTrace.Write(
            "UI",
            $"Required plan agent provider failure is stopping execution task={thread.AssignedPlanTaskId} " +
            $"agent={thread.AgentName ?? agentLabel} category={failure.Category}");

        SuppressLoopResume("required-plan-agent-provider-failure");
        DiscardObsoletePlanQueueItems("required-plan-agent-provider-failure");
        SetQueueRecoveryHoldForRequiredPlan(thread, reason);

        // Register the descriptive system interruption before aborting the loop. This
        // keeps provider failures out of the ordinary user-abort path and sends only one
        // bridge abort request for native loops.
        _bridge.InterruptPrompt(reason);

        if (IsLoopRunning)
        {
            if (_activeLoopMode == LoopMode.NativeAgents)
            {
                _loopController.RequestAbort(abortActivePrompt: false);
                _loopFollowUpTcs?.TrySetResult(false);
            }
            else
            {
                _ = _bridge.StopLoopAsync();
            }
        }

        StartCoordinatorAbortWatchdog(
            "required-plan-agent-provider-failure",
            "[interrupted: required plan agent provider failure]");
        ScheduleDecomposeSystemEntry(
            reason + " Correct the provider profile, then use the current plan recovery action to continue from the preserved state.");
    }

    private void HandlePromptFailure(SquadSdkEvent evt)
    {
        if (TryHandleActivePlanValidationProviderFailure(evt.Message, confirmedProviderEvent: true))
            return;

        var failure = ProviderFailurePresentation.Analyze(evt.Message, BuildProviderFailureContext(evt));
        ProviderFailureTranscriptBlockFactory.Append(CoordinatorThread, failure, "Coordinator", _transcriptFontSize);
        ScrollToEndIfAtBottom(CoordinatorThread);
        UpdateLeadAgent("Error", string.Empty, failure.BuildThreadSummary("Coordinator"));
        SquadDashTrace.Write(
            "UI",
            $"Prompt failed category={failure.Category} message={failure.RawError}");
    }

    private bool TryHandleActivePlanValidationProviderFailure(
        string? rawError,
        bool confirmedProviderEvent)
    {
        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (activeExecution?.IsExecutingPlan != true ||
            string.IsNullOrWhiteSpace(activeExecution.ActiveValidationId))
            return false;

        var failure = ProviderFailurePresentation.Analyze(rawError);
        if (!confirmedProviderEvent && failure.Category == ProviderFailureCategory.Unknown)
            return false;

        // Both the bridge event and ExecutePromptAsync can report the same provider exit.
        // Record it once and replace the two generic error surfaces with one phase-aware path.
        if (!string.IsNullOrWhiteSpace(activeExecution.ValidationProviderFailureReason))
            return true;

        var retryCount = activeExecution.ValidationProviderRetryCount + 1;
        _conversationManager.UpdateActiveLoopExecutionState(
            activeExecution with
            {
                ValidationProviderRetryCount = retryCount,
                ValidationProviderFailureReason = failure.RawError,
            });

        var plan = activeExecution.DecomposeGroupId is { Length: > 0 } planId
            ? _planStore?.Load(planId)
            : null;
        var validation = plan?.Validations?.FirstOrDefault(candidate =>
            string.Equals(candidate.ValidationId, activeExecution.ActiveValidationId, StringComparison.Ordinal));
        var title = validation?.Title ?? activeExecution.ActiveValidationId;
        ScheduleDecomposeSystemEntry(
            PlanValidationProviderFailurePresentation.BuildAttemptMessage(
                title,
                failure.RawError,
                willRetry: retryCount <= 1));
        SquadDashTrace.Write(
            "PlanValidation",
            $"Provider failure registered validation={activeExecution.ActiveValidationId} retry={retryCount} error={failure.RawError}");
        return true;
    }

    private ProviderFailureContext BuildProviderFailureContext(SquadSdkEvent evt)
    {
        var activeProfile = _bridge.ActiveProfile;
        return new ProviderFailureContext(
            evt.SessionModel ?? evt.Model ?? activeProfile?.Model,
            evt.ProfileAlias ?? activeProfile?.Alias,
            evt.ProviderBaseUrl ?? activeProfile?.ProviderUrl,
            evt.ProviderType ?? activeProfile?.ProviderType,
            evt.WireApi ?? activeProfile?.WireApi,
            evt.RequestedModel);
    }

    private void HandleSubagentCancelled(SquadSdkEvent evt)
    {
        if (ShouldSuppressSilentBackgroundAgent(evt))
        {
            SquadDashTrace.Write("UI", $"Silent background agent cancelled agent={evt.AgentDisplayName ?? evt.AgentName ?? evt.AgentId ?? "(unknown)"}");
            return;
        }

        var thread = _agentThreadRegistry.GetOrCreateAgentThread(evt);
        var summary = BackgroundTaskPresenter.BuildThreadCancellationSummary(thread);
        _agentThreadRegistry.UpdateAgentThreadLifecycle(thread, evt, statusText: "Cancelled", detailText: summary);
        RecordPlanAgentCompletion(thread, evt, succeeded: false);
        thread.CompletedAt ??= DateTimeOffset.Now;
        _agentThreadRegistry.FinalizeAgentThread(thread);
        UpdateCompletedTimeFooters();
        SquadDashTrace.Write("UI", $"Subagent cancelled {summary}");
        CompleteDirectQuickReplyAgentThread(thread, "subagent_cancelled");

        _backgroundTaskPresenter.SkipNextBackgroundCompletionFallback = true;
        _backgroundTaskPresenter.AppendBackgroundNotice(summary, ThemeBrush("SystemInfoText"), BackgroundTaskPresenter.BuildThreadAnnouncementKey(thread) + ":cancelled");
        SyncAgentCardsWithThreads();
        _backgroundTaskPresenter.ObserveBackgroundAgentActivity(thread, "subagent_cancelled");
        _conversationManager.SaveAgentThreadToConversation(thread, DateTimeOffset.UtcNow);
        DrainQueueAfterBackgroundWorkChanged("subagent-cancelled");
        TryCompletePendingRestart("subagent-cancelled");
    }

    private void HandleLoopStarted(SquadSdkEvent evt)
    {
        var isPlanLoop = _activeDecomposeGroupId is not null ||
                         _conversationManager.ConversationState.ActiveLoopExecution?.IsExecutingPlan == true;
        _pec.SetIsLoopRunning(true);
        _settingsManager.Replace(_settingsStore.SaveLoopActive(true));
        _loopCurrentIteration = 0;
        _loopQueued = false;
        _conversationManager.UpdateQueuedPromptsState(
            _promptQueue.Items, _followUpAttachments,
            queueRightmostHeld: IsRightmostQueueTabActive(),
            loopQueuedToDequeue: false,
            activeDraftSimEntry: _pec.ActiveDraftSimEntry,
            activeTabIndex: GetActiveQueueTabIndex());
        var label = string.IsNullOrWhiteSpace(evt.LoopMdPath)
            ? "🔁 Loop started"
            : $"🔁 Loop started: {evt.LoopMdPath.Replace('\\', '/')}";
        if (PlanLoopTranscriptPresentation.ShouldShowLoopBookkeeping(isPlanLoop))
            AppendLine(label);
        AppendLoopOutputLine($"▶ Loop started — {LoopTimestamp()}", LoopLifecycleBrush);
        SquadDashTrace.Write("UI", $"Loop started mdPath={evt.LoopMdPath ?? "(none)"}");
        SyncLoopPanel();
    }

    private void HandleLoopIteration(SquadSdkEvent evt)
    {
        if (evt.LoopIteration is int n) _loopCurrentIteration = n;
        var iterLabel = evt.LoopIteration is int m ? $"↩ Iteration {m}" : "↩ Iteration";
        if (PlanLoopTranscriptPresentation.ShouldShowLoopBookkeeping(
                _activeDecomposeGroupId is not null ||
                _conversationManager.ConversationState.ActiveLoopExecution?.IsExecutingPlan == true))
            AppendLine(iterLabel);
        SquadDashTrace.Write("UI", $"Loop iteration={evt.LoopIteration?.ToString() ?? "(unknown)"}");
        SoundNotifications.Play(SoundEvent.LoopIterationComplete);
        SyncLoopPanel();
    }

    private void HandleLoopStopped(SquadSdkEvent evt)
    {
        var wasPlanLoop = _activeDecomposeGroupId is not null ||
                          _conversationManager.ConversationState.ActiveLoopExecution?.IsExecutingPlan == true;
        CleanupActiveLoopCliProjection("loop-stopped");
        _pec.SetIsLoopRunning(false);
        ApplyPendingBridgeSettingsRestartIfIdle("loop-stopped");
        _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
        _conversationManager.UpdateActiveLoopExecutionState(null);
        _loopCurrentIteration = 0;
        AppendLoopOutputLine($"✅ Loop stopped — {LoopTimestamp()}", LoopLifecycleBrush);
        if (PlanLoopTranscriptPresentation.ShouldShowLoopBookkeeping(wasPlanLoop))
            AppendLine("✅ Loop stopped");
        SquadDashTrace.Write("UI", $"Loop stopped mdPath={evt.LoopMdPath ?? "(none)"}");
        SoundNotifications.Play(SoundEvent.LoopStopped);
        SyncLoopPanel();
        TryFireDeferredCodeHealth();
    }

    private void HandleLoopError(SquadSdkEvent evt)
    {
        CleanupActiveLoopCliProjection("loop-error");
        _pec.SetIsLoopRunning(false);
        ApplyPendingBridgeSettingsRestartIfIdle("loop-error");
        _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
        _conversationManager.UpdateActiveLoopExecutionState(null);
        _loopCurrentIteration = 0;
        _loopInterruptedByQueue = false; // abort — don't auto-resume
        var errorLabel = string.IsNullOrWhiteSpace(evt.Message)
            ? "❌ Loop error"
            : $"❌ Loop error: {evt.Message}";
        AppendLoopOutputLine(errorLabel, new System.Windows.Media.SolidColorBrush(System.Windows.Media.Color.FromRgb(0xFF, 0x88, 0x44)));
        AppendLine(errorLabel, ThemeBrush("SystemErrorText"));
        SquadDashTrace.Write("UI", $"Loop error message={evt.Message ?? "(none)"}");
        SyncLoopPanel();
    }

    private void CleanupActiveLoopCliProjection(string reason)
    {
        var projection = _activeLoopCliProjection;
        if (projection is null) return;

        _activeLoopCliProjection = null;
        SquadDashTrace.Write(
            "Loop",
            $"Cleaning Squad CLI loop projection reason={reason} source={projection.SourcePath} projection={projection.FilePath}");
        projection.Dispose();
    }

    // ── Native-loop controller callbacks (LoopMode.NativeAgents) ───────────

    /// <summary>
    /// Executes one loop iteration. After the initial AI response, if quick replies are
    /// presented the iteration stays "open": it waits for user follow-up, dispatches it,
    /// and repeats until the AI produces a response without quick replies. Only then does
    /// LoopController see the awaitable task complete, triggering _onIterationCompleted and
    /// the inter-iteration timer.
    /// </summary>
    private async Task ExecuteLoopIterationAsync(string prompt, string? sessionId)
    {
        var isExecutingPlan = _activeDecomposeGroupId is not null;

        async Task ExecuteWithTaskContextPolicyAsync(Func<Task> execute)
        {
            var previous = _pec.SuppressTasksContextForCurrentPrompt;
            _pec.SuppressTasksContextForCurrentPrompt = isExecutingPlan;
            try
            {
                await execute();
            }
            finally
            {
                _pec.SuppressTasksContextForCurrentPrompt = previous;
            }
        }

        if (isExecutingPlan &&
            _CodeHealthGroupRunner?.CurrentRevision is { } currentRevision &&
            _CodeHealthGroupRunner.CurrentStepId is { } currentTaskId &&
            PlanRepairReplayPolicy.ShouldFinalizeWithoutDispatch(
                _conversationManager.ConversationState.ActiveLoopExecution,
                _activeDecomposeGroupId!,
                currentRevision,
                currentTaskId))
        {
            var validatingPlan = _planStore?.Load(_activeDecomposeGroupId!);
            ScheduleDecomposeSystemEntry(validatingPlan is null
                ? "Reviewing completed work. No code changes will occur during this review."
                : PlanLoopTranscriptPresentation.BuildVerifyingCompletedWorkMessage(
                    validatingPlan,
                    currentTaskId,
                    _CodeHealthGroupRunner?.GetCurrentStepTitle()));
            await FinalizeExecutingPlanIterationAsync();
            return;
        }
        if (isExecutingPlan)
        {
            var continuationContext = await PrepareExecutingPlanIterationAsync();
            if (!string.IsNullOrWhiteSpace(continuationContext))
            {
                var isValidationTurn = _conversationManager.ConversationState
                    .ActiveLoopExecution?.ActiveValidationId is not null;
                prompt = isValidationTurn
                    ? continuationContext
                    : continuationContext + "\n\n" + prompt;
            }
        }
        var loopMdPath = isExecutingPlan
            ? _currentWorkspace is null
                ? string.Empty
                : HostInstructionStore.GetLegacyWorkspacePath(
                      _currentWorkspace.SquadFolderPath,
                      HostInstructionKind.PlanExecutionLoop) ?? string.Empty
            : GetEffectiveLoopMdPath();
        var displayPrompt = $"🔁 Loop · Iteration {_loopCurrentIteration}  [View {Path.GetFileName(loopMdPath)}](app://open-loop-md:{loopMdPath})";
        if (isExecutingPlan && _planStore?.Load(_activeDecomposeGroupId!) is { } executingPlan)
        {
            var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
            var activeValidation = activeExecution?.ActiveValidationId is { } activeValidationId
                ? executingPlan.Validations?.FirstOrDefault(validation =>
                    string.Equals(validation.ValidationId, activeValidationId, StringComparison.Ordinal))
                : null;
            var activeTask = executingPlan.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, _CodeHealthGroupRunner?.CurrentStepId, StringComparison.Ordinal));
            var phase = activeValidation is not null
                ? PlanTranscriptPhase.ValidatingPlan
                : activeExecution?.ActiveVerificationTaskId is not null
                    ? PlanTranscriptPhase.VerifyingWork
                    : activeTask?.Status == PlanTaskStatus.Reworking ||
                      activeExecution?.AssessedRecoveryContinuation is not null ||
                      !string.IsNullOrWhiteSpace(activeExecution?.VerificationReworkInstructions)
                        ? PlanTranscriptPhase.ReworkingTask
                        : PlanTranscriptPhase.Executing;
            var phaseTaskId = activeValidation is null ? _CodeHealthGroupRunner?.CurrentStepId : null;
            var phaseTitle = activeValidation?.Title ?? _CodeHealthGroupRunner?.GetCurrentStepTitle();
            var phaseKey = PlanLoopTranscriptPresentation.BuildPhaseKey(
                executingPlan.PlanId, phase, phaseTaskId ?? activeValidation?.ValidationId);
            displayPrompt = PlanLoopTranscriptPresentation.ShouldEmitPhaseHeading(
                _lastPlanTranscriptPhaseKey, phaseKey)
                ? PlanLoopTranscriptPresentation.BuildPhasePrompt(
                executingPlan,
                phaseTaskId,
                phaseTitle,
                loopMdPath,
                phase)
                : string.Empty;
            _lastPlanTranscriptPhaseKey = phaseKey;
        }
        if (isExecutingPlan)
            _pendingPromptIsSystemInjected = true;
        try
        {
            await ExecuteWithTaskContextPolicyAsync(() => _pec.ExecutePromptAsync(
                prompt,
                addToHistory: false,
                clearPromptBox: false,
                sessionIdOverride: sessionId,
                displayPrompt: isExecutingPlan
                    ? string.IsNullOrEmpty(displayPrompt)
                        ? string.Empty
                        : SystemTranscriptStatusPrefix + displayPrompt
                    : displayPrompt));
        }
        finally
        {
            if (isExecutingPlan)
                _pendingPromptIsSystemInjected = false;
        }

        while (LastTurnNeedsInput() && _loopController.StopState == LoopStopState.None)
        {
            _loopFollowUpTcs = new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
            AppendLoopOutputLine("⏸ Waiting for your response…", LoopLifecycleBrush);
            bool gotInput = await _loopFollowUpTcs.Task;
            _loopFollowUpTcs = null;
            if (!gotInput) return; // aborted

            // If a queue item arrived (typed message path), dequeue and dispatch it.
            // For quick-reply-click path, QuickReplyButton_Click dispatched the prompt
            // directly — item will be null, so we just re-check LastTurnNeedsInput().
            var item = GetAutoDispatchCandidate();
            if (item is null) continue;

            _promptQueue.Remove(item.Id);
            SyncQueuePanel();
            _pec.PendingQueueItemCount = _promptQueue.Count;
            _pec.CurrentDispatchedItem = item;
            _queueDrainActive = true;
            _pendingPromptIsSystemInjected = item.IsSystemInjected;
            _pendingPromptSuppressTranscript = ShouldSuppressQueuedPromptTranscript(item);
            try
            {
                await ExecuteWithTaskContextPolicyAsync(() => _pec.ExecutePromptAsync(
                    ApplyFollowUpHeader(ApplyDictationAnnotation(item), item.Id),
                    addToHistory: !item.IsSystemInjected,
                    clearPromptBox: false,
                    displayPrompt: BuildQueuedPromptDisplayText(item)));
            }
            finally
            {
                _queueDrainActive = false;
                _pendingPromptIsSystemInjected = false;
                _pendingPromptSuppressTranscript = false;
                _pec.PendingQueueItemCount = 0;
                _pec.CurrentDispatchedItem = null;
            }
        }

        if (_interruptedPromptRecoveryHold is not null || _loopStoppedForInterruptedPromptRecovery)
            return;

        if (isExecutingPlan)
            await FinalizeExecutingPlanIterationAsync();
    }

    private void OnNativeLoopIterationStarted(int iteration)
    {
        _loopCurrentIteration = iteration;
        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        var activeValidationId = activeExecution?.ActiveValidationId;
        var activeVerificationTaskId = activeExecution?.ActiveVerificationTaskId;
        if (_activeDecomposeGroupId is not null && activeValidationId is null)
            TrackFirstEligiblePlanStep(_activeDecomposeGroupId);
        else if (activeValidationId is not null)
            _CodeHealthGroupRunner?.ClearCurrentStep();
        var activePlan = _activeDecomposeGroupId is null
            ? null
            : _planStore?.Load(_activeDecomposeGroupId);
        var activeValidation = activeValidationId is null
            ? null
            : activePlan?.Validations?.FirstOrDefault(validation =>
                string.Equals(validation.ValidationId, activeValidationId, StringComparison.Ordinal));
        var activeVerificationTask = activeVerificationTaskId is null
            ? null
            : activePlan?.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, activeVerificationTaskId, StringComparison.Ordinal));
        _loopRoundExecutionIdentity = new LoopRoundExecutionIdentity(
            _activeDecomposeGroupId,
            activeExecution?.DecomposeRevision
                ?? _CodeHealthGroupRunner?.CurrentRevision,
            activeValidation?.ValidationId
                ?? activeVerificationTask?.TaskId
                ?? activeVerificationTaskId
                ?? _CodeHealthGroupRunner?.CurrentStepId,
            activeValidation?.Title
                ?? activeVerificationTask?.Title
                ?? _CodeHealthGroupRunner?.GetCurrentStepTitle());
        _loopRoundExecutionPhase = string.Equals(
                _pec.CurrentDispatchedItem?.SourceTag,
                PlanRepairReplayPolicy.TaskResultRepairSourceTag,
                StringComparison.Ordinal)
            ? "envelope_repair"
            : activeValidation is not null
                ? "validation"
                : activeVerificationTask is not null || activeVerificationTaskId is not null
                    ? "verification"
                    : "implementation";
        _loopIsWaiting = false;
        _loopRoundStartedAt = DateTimeOffset.Now;
        _loopPlanStartedAt ??= _loopRoundStartedAt;
        SetNativePlanRunnerActive(true, _activeDecomposeGroupId);
        _settingsManager.Replace(_settingsStore.SaveLoopActive(true));
        AppendLoopOutputLine($"▶ Round {iteration} started — {LoopTimestamp()}", LoopLifecycleBrush);
        if (PlanLoopTranscriptPresentation.ShouldShowLoopBookkeeping(_activeDecomposeGroupId is not null))
            AppendLine($"↩ Round {iteration}");
        _planExecutionLog?.Append(new PlanExecutionLogEntry(
            Kind: _loopRoundExecutionPhase == "implementation" ? "round_started" : "phase_started",
            Timestamp: DateTimeOffset.UtcNow.ToString("O"),
            PlanId: _loopRoundExecutionIdentity.PlanId,
            Revision: _loopRoundExecutionIdentity.Revision,
            Round: iteration,
            TaskId: _loopRoundExecutionIdentity.TaskId,
            TaskTitle: _loopRoundExecutionIdentity.TaskTitle,
            Message: null,
            Outcome: null,
            Phase: _loopRoundExecutionPhase));
        EnsurePlanContinuationQueueItem();
        SyncLoopPanel();
    }

    private void OnNativeLoopStopped()
    {
        _promptQueue.RemoveByTag(PlanContinuationQueueTag);
        SyncQueuePanel();
        int stoppedIteration = _loopCurrentIteration;
        int resumeFromIteration = _loopStoppedForInterruptedPromptRecovery
            ? _conversationManager.ConversationState.ActiveLoopExecution?.LastCompletedIteration
              ?? Math.Max(0, stoppedIteration - 1)
            : stoppedIteration;
        var stoppedExecution = _loopRoundExecutionIdentity;
        var stoppedPlanId = _activeDecomposeGroupId ?? stoppedExecution?.PlanId;
        bool hasInterrupt = _loopInterruptedByQueue;
        var resumeDecision = LoopStopResumePolicy.Resolve(
            resumeSuppressed: _loopResumeSuppressed,
            restartPending: _restartPending,
            interruptedByQueue: hasInterrupt,
            queueHasReadyItems: HasReadyPromptQueueItems(),
            loopAlreadyQueued: _loopQueued);
        bool shouldResumeAfterQueue = resumeDecision.ResumeAfterQueue;
        bool shouldPreserveForRestart = resumeDecision.PreserveForRestart;

        SetNativePlanRunnerActive(false, stoppedPlanId);
        TryDispatchPendingDecomposeRecoveryResponse();
        ApplyPendingBridgeSettingsRestartIfIdle("native-loop-stopped");
        _loopCurrentIteration = 0;
        _loopIsWaiting = false;
        _loopRoundStartedAt = null;

        var interruptedTaskId = _CodeHealthGroupRunner?.CurrentStepId ?? stoppedExecution?.TaskId;
        var pausedAfterStep = _pausePlanAfterCurrentStepRequested ||
                              (stoppedPlanId is not null && _planStore?.Load(stoppedPlanId)?.IsPaused == true);
        if (pausedAfterStep && stoppedPlanId is not null)
            RemovePlanPauseRequestedEntries(stoppedPlanId);
        var abortedByUser = _planAbortRequestedByUser;
        var providerWaitReason = _planProviderWaitInterruptionReason;
        var unacceptedStopReason = _restartPending
            ? "An application restart began before SquadDash could accept the current task result."
            : "Plan execution stopped before the current task was accepted.";
        var interruptionResult = PlanInterruptionPersistenceResult.NotNeeded;
        if (!resumeDecision.PreserveExecution && stoppedPlanId is not null)
        {
            interruptionResult = TryInterruptExecutingPlan(
                stoppedPlanId,
                interruptedTaskId,
                providerWaitReason ?? (pausedAfterStep
                    ? "Paused by user after the previous task was accepted."
                    : abortedByUser
                        ? "Current plan work was aborted by the user. Repository work was preserved for assessment."
                    : unacceptedStopReason),
                stoppedIteration,
                preferDurableTaskId: true);
            interruptedTaskId = interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Completed
                ? null
                : interruptionResult.Plan?.InterruptionData?.InterruptedTaskId ?? interruptedTaskId;
        }

        if (!resumeDecision.PreserveExecution)
        {
            _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
            if (interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Failed)
                ClearExecutingPlanRuntimeState();
            else
                ClearExecutingPlanState();
            _loopPlanStartedAt = null;
            _loopTotalActiveTime = TimeSpan.Zero;
        }
        AppendLoopOutputLine($"✅ Loop stopped — {LoopTimestamp()}", LoopLifecycleBrush);
        if (PlanLoopTranscriptPresentation.ShouldShowLoopBookkeeping(stoppedPlanId is not null))
            AppendLine("✅ Loop stopped");
        var completedAtStop = interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Completed;
        _planExecutionLog?.Append(new PlanExecutionLogEntry(
            Kind: completedAtStop ? "plan_completed" : "plan_stopped",
            Timestamp: DateTimeOffset.UtcNow.ToString("O"),
            PlanId: stoppedPlanId,
            Revision: stoppedExecution?.Revision,
            Round: stoppedIteration > 0 ? stoppedIteration : null,
            TaskId: interruptedTaskId,
            TaskTitle: stoppedExecution?.TaskTitle,
            Message: null,
            Outcome: completedAtStop ? "completed" : "stopped"));
        _loopRoundExecutionIdentity = null;

        if (completedAtStop && interruptionResult.Plan is { } completedPlan)
        {
            PublishPlanCompletionSummary(completedPlan);
            ScheduleDecomposeSystemEntry(
                PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(
                    completedPlan, "Final accepted state reconciled at loop shutdown"));
            ReconcileDecomposeRecoveryInboxMessages(completedPlan.PlanId);
        }
        else if (interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Persisted &&
                 interruptionResult.Plan is { } newlyInterruptedPlan)
        {
            ScheduleDecomposeSystemEntry(
                pausedAfterStep
                    ? $"Plan {newlyInterruptedPlan.Title} paused safely after the completed step. It can be resumed from the Plans panel."
                    : providerWaitReason is not null
                        ? $"Plan {newlyInterruptedPlan.PlanId} is preserved at {interruptedTaskId ?? "the current task"} after provider recovery was exhausted. Resume it after provider access is available."
                    : abortedByUser
                        ? $"Plan work was aborted at {interruptedTaskId ?? "the current task"}. Assess the preserved work before continuing."
                    : _restartPending
                        ? $"Plan {newlyInterruptedPlan.PlanId} was interrupted by an application restart before {interruptedTaskId ?? "the current task"} was accepted. The plan is preserved and can be resumed."
                        : $"Plan {newlyInterruptedPlan.PlanId} stopped before {interruptedTaskId ?? "the current task"} was accepted. The plan is preserved and can be resumed.",
                newlyInterruptedPlan.PlanId,
                newlyInterruptedPlan.Revision,
                interruptedTaskId);
            if (!pausedAfterStep && interruptedTaskId is not null)
                SaveDecomposeRecoveryInboxReminder(
                    newlyInterruptedPlan.PlanId,
                    newlyInterruptedPlan.Revision,
                    interruptedTaskId,
                    providerWaitReason ?? (abortedByUser
                        ? "Current plan work was aborted by the user. Repository work was preserved for assessment."
                        : unacceptedStopReason));
        }
        else if (interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Failed)
        {
            var persistenceMessage =
                $"Plan {stoppedPlanId} stopped, but SquadDash could not save its interrupted state. " +
                "The execution ownership was retained for recovery. " +
                (interruptionResult.Error ?? "Unknown persistence failure.");
            AppendLoopOutputLine($"⚠ {persistenceMessage}", LoopLifecycleBrush);
            ScheduleDecomposeSystemEntry(persistenceMessage);
        }

        if (_restartPending &&
            TryCompletePendingRestart("native-loop-stopped", emergencySaveBeforeClose: true))
        {
            if (shouldPreserveForRestart)
                _loopQueuedResumeFromIteration = Math.Max(_loopQueuedResumeFromIteration, resumeFromIteration);
            SquadDashTrace.Write("Loop", $"OnNativeLoopStopped: restart pending preserve={shouldPreserveForRestart} resumeSuppressed={_loopResumeSuppressed} resumeFromIteration={_loopQueuedResumeFromIteration} group={_activeDecomposeGroupId ?? "(none)"} queueCount={_promptQueue.Count}");
            SyncLoopPanel();
            return;
        }

        // If queue items arrived while the loop was running (or are still pending),
        // mark the loop for resume once the queue drains.  Abort goes through
        // OnNativeLoopError and intentionally does NOT re-queue.
        SquadDashTrace.Write("Queue", $"OnNativeLoopStopped: hasInterrupt={hasInterrupt} hasReadyItems={_promptQueue.HasReadyItems} loopQueued={_loopQueued}.");
        if (shouldResumeAfterQueue && !_loopQueued)
        {
            QueueLoopResumeAfterQueueDrain(resumeFromIteration, "native-loop-stopped", updateUi: false);
            AppendLoopOutputLine("🔁 Queue items pending — loop will resume after queue drains.", LoopLifecycleBrush);
        }

        _loopStoppedForInterruptedPromptRecovery = false;
        _loopResumeSuppressed = false;
        _pausePlanAfterCurrentStepRequested = false;
        _planAbortRequestedByUser = false;
        _planProviderWaitInterruptionReason = null;
        SoundNotifications.Play(SoundEvent.LoopStopped);
        SyncLoopPanel();
        if (interruptionResult.Outcome != PlanInterruptionPersistenceOutcome.Failed)
            TryFireDeferredCodeHealth();
        _ = DrainQueueIfNeededAsync();
    }

    private void OnNativeLoopError(string msg)
    {
        if (_loopController.LastTerminalException is PlanPreflightBlockedException preflightBlocked)
        {
            PausePlanForCleanWorktree(preflightBlocked);
            return;
        }
        DiscardObsoletePlanQueueItems("native-loop-error");
        var branchLeasePause = _planBranchLeasePausePending;
        var failedRound = _loopRoundExecutionIdentity;
        var failureIdentity = LoopRoundExecutionIdentity.ResolveFailure(
            failedRound,
            _activeDecomposeGroupId,
            _CodeHealthGroupRunner?.CurrentRevision,
            _CodeHealthGroupRunner?.CurrentStepId,
            _CodeHealthGroupRunner?.GetCurrentStepTitle());
        var blockedGroupId = failureIdentity.PlanId;
        var blockedTaskId = failureIdentity.TaskId;
        var blockedRevision = failureIdentity.Revision;
        var failedIteration = _loopCurrentIteration;
        var providerWaitReason = _planProviderWaitInterruptionReason;
        if (!_planAbortRequestedByUser && providerWaitReason is null && !branchLeasePause && blockedTaskId is not null && string.Equals(
                _CodeHealthGroupRunner?.CurrentStepId,
                blockedTaskId,
                StringComparison.Ordinal))
            _CodeHealthGroupRunner?.MarkCurrentStepFailed();
        var interruptionReason = providerWaitReason ?? (_planAbortRequestedByUser
            ? "Current plan work was aborted by the user. Repository work was preserved for assessment."
            : msg);
        var interruptionResult = blockedGroupId is null
            ? PlanInterruptionPersistenceResult.NotNeeded
            : TryInterruptExecutingPlan(
                blockedGroupId,
                blockedTaskId,
                interruptionReason,
                failedIteration,
                preferDurableTaskId: false);
        SetNativePlanRunnerActive(false, blockedGroupId);
        ApplyPendingBridgeSettingsRestartIfIdle("native-loop-error");
        _loopCurrentIteration = 0;
        _loopIsWaiting = false;
        _loopRoundStartedAt = null;
        _loopPlanStartedAt = null;
        _loopTotalActiveTime = TimeSpan.Zero;
        _loopInterruptedByQueue = false; // abort — don't auto-resume
        _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
        if (interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Failed)
            ClearExecutingPlanRuntimeState();
        else
            ClearExecutingPlanState();
        _loopResumeSuppressed = false;
        _pausePlanAfterCurrentStepRequested = false;
        if (interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Completed &&
            interruptionResult.Plan is { } completedPlan)
        {
            AppendLoopOutputLine(
                $"✅ Plan completion reconciled while the native loop was shutting down — {LoopTimestamp()}",
                LoopLifecycleBrush);
            _planExecutionLog?.Append(new PlanExecutionLogEntry(
                Kind: "plan_completed",
                Timestamp: DateTimeOffset.UtcNow.ToString("O"),
                PlanId: completedPlan.PlanId,
                Revision: completedPlan.Revision,
                Round: failedIteration > 0 ? failedIteration : null,
                TaskId: null,
                TaskTitle: null,
                Message: null,
                Outcome: "completed"));
            PublishPlanCompletionSummary(completedPlan);
            ScheduleDecomposeSystemEntry(
                PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(
                    completedPlan, "Final accepted state reconciled at loop shutdown"));
            ReconcileDecomposeRecoveryInboxMessages(completedPlan.PlanId);
            _planAbortRequestedByUser = false;
            _planBranchLeasePausePending = false;
            _planProviderWaitInterruptionReason = null;
            _loopRoundExecutionIdentity = null;
            SyncLoopPanel();
            SoundNotifications.Play(SoundEvent.LoopStopped);
            TryFireDeferredCodeHealth();
            return;
        }
        AppendLoopOutputLine(
            providerWaitReason is not null
                ? "⏸ Plan paused after provider recovery was exhausted; recovery state was preserved."
                : _planAbortRequestedByUser
                ? "⏹ Plan work aborted; recovery evidence was preserved."
                : branchLeasePause
                    ? "⏸ Plan paused before dispatch; the canonical branch needs attention."
                : $"❌ Loop error: {msg}",
            providerWaitReason is not null || _planAbortRequestedByUser || branchLeasePause
                ? LoopLifecycleBrush
                : ThemeBrush("SystemErrorText"));
        AppendLine(
            providerWaitReason is not null
                ? "⏸ Plan paused after provider recovery was exhausted. Resume it after provider access is available."
                : _planAbortRequestedByUser
                ? "⏹ Plan work aborted; recovery is available."
                : branchLeasePause
                    ? "⏸ Plan paused before dispatch. No task was started or failed."
                : $"❌ Loop error: {msg}",
            _planAbortRequestedByUser || branchLeasePause ? null : ThemeBrush("SystemErrorText"));
        _planExecutionLog?.Append(new PlanExecutionLogEntry(
            Kind: "plan_error",
            Timestamp: DateTimeOffset.UtcNow.ToString("O"),
            PlanId: blockedGroupId,
            Revision: blockedRevision,
            Round: failedIteration > 0 ? failedIteration : null,
            TaskId: blockedTaskId,
            TaskTitle: failureIdentity.TaskTitle,
            Message: msg,
            Outcome: "error"));
        SyncLoopPanel();
        if (interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Persisted &&
            blockedGroupId is not null && blockedTaskId is not null && blockedRevision is not null)
        {
            ScheduleDecomposeSystemEntry(
                providerWaitReason is not null
                    ? $"Plan {blockedGroupId} is preserved at {blockedTaskId}. Resume it after provider access is available."
                    : _planAbortRequestedByUser
                    ? $"Plan work was aborted at {blockedTaskId}. Assess the preserved work before continuing."
                    : branchLeasePause
                        ? $"Plan {blockedGroupId} paused before {blockedTaskId} started. {msg}"
                    : $"Plan {blockedGroupId} stopped at {blockedTaskId}: {msg}",
                blockedGroupId,
                blockedRevision,
                blockedTaskId);
            SaveDecomposeRecoveryInboxReminder(
                blockedGroupId,
                blockedRevision,
                blockedTaskId,
                interruptionReason);
        }
        _planAbortRequestedByUser = false;
        _planBranchLeasePausePending = false;
        _planProviderWaitInterruptionReason = null;
        if (interruptionResult.Outcome == PlanInterruptionPersistenceOutcome.Failed)
        {
            ScheduleDecomposeSystemEntry(
                $"SquadDash could not save the interrupted state for plan {blockedGroupId}. " +
                "The execution ownership was retained for recovery. " +
                (interruptionResult.Error ?? "Unknown persistence failure."));
        }
        _loopRoundExecutionIdentity = null;
        SoundNotifications.Play(SoundEvent.LoopStopped);
        if (interruptionResult.Outcome != PlanInterruptionPersistenceOutcome.Failed)
            TryFireDeferredCodeHealth();
    }

    private void PausePlanForCleanWorktree(
        PlanPreflightBlockedException blocked,
        string? planIdOverride = null)
    {
        var identity = LoopRoundExecutionIdentity.ResolveFailure(
            _loopRoundExecutionIdentity,
            _activeDecomposeGroupId,
            _CodeHealthGroupRunner?.CurrentRevision,
            _CodeHealthGroupRunner?.CurrentStepId,
            _CodeHealthGroupRunner?.GetCurrentStepTitle());
        var planId = planIdOverride ?? identity.PlanId;
        var durable = planId is null ? null : _planStore?.Load(planId);
        if (durable is null)
        {
            // Without a durable plan there is no safe continuation identity; use ordinary error
            // handling rather than guessing from a projection.
            _loopController.LastTerminalException = null;
            OnNativeLoopError(blocked.Message);
            return;
        }

        var waiting = PlanStoreUpdater.ApplyWaitingForCleanWorktree(durable);
        if (!TryPublishPlanProgress(waiting, out var saveError))
        {
            _loopController.LastTerminalException = null;
            OnNativeLoopError(saveError ?? blocked.Message);
            return;
        }

        SetNativePlanRunnerActive(false, durable.PlanId);
        _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
        _loopCurrentIteration = 0;
        _loopIsWaiting = false;
        _loopRoundStartedAt = null;
        _loopPlanStartedAt = null;
        _loopTotalActiveTime = TimeSpan.Zero;
        _loopInterruptedByQueue = false;
        ClearExecutingPlanState();
        _loopResumeSuppressed = false;
        _pausePlanAfterCurrentStepRequested = false;
        _planAbortRequestedByUser = false;
        _planBranchLeasePausePending = false;
        _loopRoundExecutionIdentity = null;

        AppendLoopOutputLine(
            $"⏳ Plan {durable.PlanId} is waiting for a clean worktree. No task failed.",
            LoopLifecycleBrush);
        AppendLine($"⏳ Plan {durable.PlanId} is waiting for you to commit or stash the listed changes.");

        var pending = PendingDecomposePlanAdapter.FromPlan(waiting);
        ShowTranscriptPlanPreflightRecovery(
            pending,
            action: "continue-working",
            branchOverride: waiting.Branch,
            blocked,
            sourceActionsPanel: null,
            CoordinatorThread.Document.Blocks,
            retryOverride: async () =>
            {
                var latest = _planStore?.Load(waiting.PlanId)
                    ?? throw new InvalidOperationException("The durable plan is no longer available.");
                await StartBackloggedDecomposeGroupAsync(
                    PendingDecomposePlanAdapter.FromPlan(latest).Group with
                    {
                        HostRevision = latest.Revision,
                    });
                return true;
            },
            retryLabel: "Resume when clean",
            autoRetryWhenReady: true);
        SyncLoopPanel();
        SoundNotifications.Play(SoundEvent.LoopStopped);
    }

    private void OnNativeLoopIterationCompleted(int iteration)
    {
        var completedExecution = _loopRoundExecutionIdentity;
        if (_loopRoundStartedAt.HasValue)
            _loopTotalActiveTime += DateTimeOffset.Now - _loopRoundStartedAt.Value;
        _settingsManager.Replace(_settingsStore.SaveLoopIteration(iteration));
        if (_conversationManager.ConversationState.ActiveLoopExecution is { } activeExecution)
            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with { LastCompletedIteration = iteration });
        AppendLoopOutputLine($"✓ Round {iteration} completed — {LoopTimestamp()}", LoopLifecycleBrush);
        if (PlanLoopTranscriptPresentation.ShouldShowLoopBookkeeping(completedExecution?.PlanId is not null))
            AppendLine($"  ✓ Round {iteration} complete");
        _planExecutionLog?.Append(new PlanExecutionLogEntry(
            Kind: _loopRoundExecutionPhase == "implementation" ? "round_completed" : "phase_completed",
            Timestamp: DateTimeOffset.UtcNow.ToString("O"),
            PlanId: completedExecution?.PlanId,
            Revision: completedExecution?.Revision,
            Round: iteration,
            TaskId: completedExecution?.TaskId,
            TaskTitle: completedExecution?.TaskTitle,
            Message: null,
            Outcome: "completed",
            Phase: _loopRoundExecutionPhase));
        if (_planExecutionLog is not null &&
            PlanLoopTranscriptPresentation.ShouldShowLoopBookkeeping(completedExecution?.PlanId is not null))
        {
            var taskDisplay = completedExecution?.TaskTitle
                           ?? completedExecution?.TaskId
                           ?? "(unknown task)";
            AppendLine($"  📋 Logged: Round {iteration} · {taskDisplay}", (Brush)FindResource("SubtleText"));
        }
        SoundNotifications.Play(SoundEvent.LoopIterationComplete);
        SyncLoopPanel();
    }

    private void SetNativePlanRunnerActive(bool active, string? planId)
    {
        if (IsLoopRunning == active)
            return;

        _pec.SetIsLoopRunning(active);
        RefreshOpenPlanViewerRunnerState(planId);
    }

    private void RefreshOpenPlanViewerRunnerState(string? planId)
    {
        if (string.IsNullOrWhiteSpace(planId))
            return;

        foreach (var entry in _openPlanViewerWindows.Where(entry =>
                     string.Equals(entry.GroupId, planId, StringComparison.Ordinal)))
            entry.Window.NotifyPlanRunnerStateChanged();
    }

    private void OnNativeLoopWaiting(DateTimeOffset nextAt)
    {
        _loopNextIterationAt = nextAt;
        _loopIsWaiting = true;
        SyncLoopPanel();

        if (_loopCountdownTimer == null)
        {
            _loopCountdownTimer = new DispatcherTimer { Interval = UiTimingConstants.LoopCountdownInterval };
            _loopCountdownTimer.Tick += (_, _) => {
                if (!_loopIsWaiting) { _loopCountdownTimer.Stop(); return; }
                SyncLoopPanel();
            };
        }
        _loopCountdownTimer.Start();
    }

    private static readonly Regex AnsiEscapeRegex = new(@"\x1B\[[0-9;]*[A-Za-z]", RegexOptions.Compiled);
    private static readonly SolidColorBrush LoopStderrBrush = new(Color.FromRgb(0xFF, 0x44, 0x44));
    private static readonly SolidColorBrush LoopLifecycleBrush = new(Color.FromRgb(0x88, 0x88, 0x88));

    private static string LoopTimestamp() => DateTime.Now.ToString("h:mm tt");

    private void HandleLoopOutput(SquadSdkEvent evt)
    {
        if (string.IsNullOrWhiteSpace(evt.OutputLine)) return;
        var raw = evt.OutputLine!;
        SquadDashTrace.Write("LoopOutput", raw);
        var line = AnsiEscapeRegex.Replace(raw, string.Empty).Trim();
        if (string.IsNullOrWhiteSpace(line)) return;
        if (line.StartsWith("[stderr]", StringComparison.Ordinal))
            AppendLoopOutputLine(line, LoopLifecycleBrush);
        else
            AppendLoopOutputLine(line);
    }

    private void AppendLoopOutputLine(string text, Brush? brush = null)
    {
        // Create window lazily for buffering, but do NOT show it automatically.
        // It is shown only via explicit "Show Loop Output" context-menu action.
        if (_loopOutputWindow is null)
        {
            _loopOutputWindow = new LoopOutputWindow();
            _loopOutputWindow.Owner = this;
        }
        _loopOutputWindow.AppendLine(text);
    }

    private void BackupAndClearLoopOutput()
    {
        _loopOutputWindow?.SaveAndClear();
    }

    private void OpenLoopOutputWindow()
    {
        if (_loopOutputWindow is { IsVisible: true })
        {
            _loopOutputWindow.Activate();
            return;
        }

        if (_loopOutputWindow is null)
        {
            _loopOutputWindow = new LoopOutputWindow();
            _loopOutputWindow.Owner = this;
        }

        // Position upper-right of the main window (use actual bounds, correct when maximized)
        var mainBounds = NativeMethods.GetActualWindowBoundsLogical(this);
        double mainLeft  = mainBounds.Width > 0 ? mainBounds.Left  : Left;
        double mainTop   = mainBounds.Width > 0 ? mainBounds.Top   : Top;
        double mainWidth = mainBounds.Width > 0 ? mainBounds.Width : (ActualWidth > 0 ? ActualWidth : Width);
        var w = _loopOutputWindow.Width;
        var margin = 20;
        _loopOutputWindow.Left = mainLeft + mainWidth - w - margin;
        _loopOutputWindow.Top  = mainTop + margin;
        WindowPlacementHelper.EnsureOnScreen(_loopOutputWindow, this);

        _loopOutputWindow.Show();
        _loopOutputWindow.Activate();
    }

    private void EnsureLoopOutputWindow()
    {
        if (_loopOutputWindow is not { IsVisible: true })
            OpenLoopOutputWindow();
    }

