    private void HandleSubSquadsError(SquadSdkEvent evt)
    {
        var msg = string.IsNullOrWhiteSpace(evt.Message) ? "SubSquads operation failed" : evt.Message;
        AppendLine($"📦 SubSquads error: {msg}", ThemeBrush("SystemErrorText"));
