            ? "Stop _Remote Access"
            : "Start _Remote Access";
    }

    private bool _lastSyncedLoopRunning;
    private double _lastLoopPanelUsefulHeight = double.NaN;

    private double ComputeLoopPanelUsefulHeight()
    {
        const double padding      = 20; // GripStripBorder Padding: top=8 + bottom=12
        const double titleRow     = 28;
        const double checkboxRow  = 28;
        const double buttonHeight = 28;
        const double buttonMargin = 4;

        double h = padding + titleRow;
        if (LoopStatusLabel?.Visibility == Visibility.Visible)
            h += 20 + 6;
        if (LoopContinuousContextPanel?.Visibility == Visibility.Visible)
            h += checkboxRow + 6;
        if (LoopPlanControlNotice?.Visibility == Visibility.Visible)
            h += 48;
        if (StartLoopButton?.Visibility == Visibility.Visible)
            h += buttonHeight;
        if (StopLoopButton?.Visibility == Visibility.Visible)
            h += buttonMargin + buttonHeight;
        if (AbortLoopButton?.Visibility == Visibility.Visible)
            h += buttonMargin + buttonHeight;
        if (LoopOptionsPanel?.Visibility == Visibility.Visible)
            h += 8 + Math.Min(LoopOptionsPanel.ActualHeight > 0 ? LoopOptionsPanel.ActualHeight : 200, 300);
        h += 16; // extra cushion for margins
        return Math.Clamp(h, 120, 520);
    }

    private void SyncLoopPanel()
    {
        if (LoopPanelBorder is null) return;
        SyncSendButton();
        LoopPanelBorder.Visibility = _loopPanelVisible ? Visibility.Visible : Visibility.Collapsed;
        _dockingService?.OnPanelVisibilityChanged("loop", _loopPanelVisible);
        NotifyToolPanelVisibilityChanged("loop", _loopPanelVisible);
        UpdateMainGridSideMargins();

        bool running = IsLoopRunning;

        if (running != _lastSyncedLoopRunning) {
            _lastSyncedLoopRunning = running;
            _idleDetectionService?.SetLoopActive(running);
        }

        bool nativeMode = _settingsSnapshot.LoopMode == LoopMode.NativeAgents;
        bool busyCoordinator = _isPromptRunning && nativeMode && !running;
        bool planControlled = _activeDecomposeGroupId is not null;

        LoopPlanControlNotice.Visibility = planControlled
            ? Visibility.Visible
            : Visibility.Collapsed;
        LoopContinuousContextPanel.Visibility = planControlled
            ? Visibility.Collapsed
            : Visibility.Visible;

        // In Queue Loop state: coordinator is busy in native mode, loop not yet running.
        if (planControlled)
        {
            StartLoopButton.Visibility = Visibility.Collapsed;
            StopLoopButton.Visibility = Visibility.Collapsed;
            AbortLoopButton.Visibility = Visibility.Collapsed;
        }
        else if (busyCoordinator || _loopQueued)
        {
            StartLoopButton.Visibility = Visibility.Visible;
            StartLoopButton.IsEnabled = !_loopQueued; // disable once already queued
            StartLoopButton.Content = _loopQueued ? "Loop Queued" : "Queue Loop";
        }
        else
        {
            StartLoopButton.Visibility = running ? Visibility.Collapsed : Visibility.Visible;
            StartLoopButton.IsEnabled = !running;
            StartLoopButton.Content = "Start Loop";
        }

        StopLoopButton.IsEnabled = running || _loopQueued;
        StopLoopButton.Content = (_loopQueued && !running) ? "✕ Dequeue Loop" : "■ Stop After This";
        if (!planControlled)
            AbortLoopButton.Visibility = running ? Visibility.Visible : Visibility.Collapsed;

        if (LoopFilePicker is not null)
        {
            LoopFilePicker.IsEnabled = !running;
            LoopFilePicker.Visibility = _activeDecomposeGroupId is not null
                ? Visibility.Collapsed
                : _loopFileEntries.Count > 1 ? Visibility.Visible : Visibility.Collapsed;
        }
        LoopContinuousContextCheckBox.IsEnabled = !running && !planControlled;
        LoopContinuousContextCheckBox.IsChecked = _settingsSnapshot.LoopContinuousContext;

        var executingPlanPrefix = _activeDecomposeGroupId is not null ? "Executing Plan · " : string.Empty;
        string status;
        if (_loopQueued)
            status = _promptQueue.Count > 0
                ? $"⏸ {executingPlanPrefix}Paused — dequeuing prompts"
                : $"⏸ {executingPlanPrefix}Starting after this turn";
        else if (running
            && _activeLoopMode == LoopMode.NativeAgents
            && _loopController.StopState == LoopStopState.StopRequested)
            status = $"◌ {executingPlanPrefix}Stopping after this iteration…";
        else if (running && _loopIsWaiting)
        {
            var remaining = _loopNextIterationAt - DateTimeOffset.Now;
            status = remaining.TotalSeconds > 60
                ? $"⏳ {executingPlanPrefix}Waiting · next in {(int)remaining.TotalMinutes}m"
                : remaining.TotalSeconds > 0
                    ? $"⏳ {executingPlanPrefix}Waiting · next in {(int)remaining.TotalSeconds}s"
                    : $"⏳ {executingPlanPrefix}Waiting…";
        }
        else if (running)
            status = _loopCurrentIteration > 0
                ? $"● {executingPlanPrefix}Running · Round {_loopCurrentIteration}"
                : $"● {executingPlanPrefix}Running";
        else if (_activePlanAwaitingGateApproval is not null)
            status = "⏸ Plan · Waiting for approval";
        else
            status = string.Empty;

        LoopStatusLabel.Text = status;
        LoopStatusLabel.Visibility = string.IsNullOrEmpty(status) ? Visibility.Collapsed : Visibility.Visible;

        // Plan execution detail panel
        if (_activeDecomposeGroupId is not null && running)
        {
            LoopPlanDetailPanel.Visibility = Visibility.Visible;

            var planTitle = _activeDecomposeGroupId;
            LoopPlanTitleLabel.Text = planTitle;
            LoopPlanTitleLabel.Visibility = Visibility.Visible;

            var taskTitle = _CodeHealthGroupRunner?.GetCurrentStepTitle();
            var taskId    = _CodeHealthGroupRunner?.CurrentStepId;
            var taskDisplay = taskTitle ?? taskId;
            if (!string.IsNullOrWhiteSpace(taskDisplay))
            {
                LoopPlanTaskLabel.Text = $"Task: {taskDisplay}";
                LoopPlanTaskLabel.Visibility = Visibility.Visible;
            }
            else
            {
                LoopPlanTaskLabel.Visibility = Visibility.Collapsed;
            }

            var timingParts = new System.Collections.Generic.List<string>();
            if (_loopRoundStartedAt.HasValue && !_loopIsWaiting)
            {
                var roundElapsed = DateTimeOffset.Now - _loopRoundStartedAt.Value;
                timingParts.Add($"Round: {StatusTimingPresentation.FormatDuration(roundElapsed)}");
            }
            var totalActive = _loopTotalActiveTime;
            if (_loopRoundStartedAt.HasValue && !_loopIsWaiting)
                totalActive += DateTimeOffset.Now - _loopRoundStartedAt.Value;
            if (totalActive > TimeSpan.FromSeconds(1))
                timingParts.Add($"Total: {StatusTimingPresentation.FormatDuration(totalActive)}");
            if (timingParts.Count > 0)
            {
                LoopPlanTimingLabel.Text = string.Join(" · ", timingParts);
                LoopPlanTimingLabel.Visibility = Visibility.Visible;
            }
            else
            {
                LoopPlanTimingLabel.Visibility = Visibility.Collapsed;
            }
        }
        else
        {
            LoopPlanDetailPanel.Visibility = Visibility.Collapsed;
        }

        if (LoopPanelDequeueMenuItem is not null)
            LoopPanelDequeueMenuItem.Visibility = _loopQueued ? Visibility.Visible : Visibility.Collapsed;

        RefreshLoopPanelUsefulHeightIfChanged();
    }

    private void RefreshLoopPanelUsefulHeightIfChanged(bool force = false)
    {
        var usefulHeight = ComputeLoopPanelUsefulHeight();
        if (!force && !double.IsNaN(_lastLoopPanelUsefulHeight) &&
            Math.Abs(usefulHeight - _lastLoopPanelUsefulHeight) < 1)
        {
            return;
        }

        _lastLoopPanelUsefulHeight = usefulHeight;
        if (_loopPanelVisible)
            _dockingService?.RefreshPanelUsefulHeight("loop");
    }

    private void ScheduleLoopPanelUsefulHeightRefresh(bool force = false)
    {
        _ = Dispatcher.BeginInvoke(
            DispatcherPriority.Loaded,
            () => RefreshLoopPanelUsefulHeightIfChanged(force));
    }

