    {
        var state = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
        _docsPanelState = state with { SelectedLoopFile = _selectedLoopMdPath };
        _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
    }

    private void RefreshLoopOptionsPanel()
    {
        LoopOptionsPanel.Children.Clear();
        LoopOptionsPanel.Visibility = Visibility.Collapsed;

        if (_selectedLoopMdPath is null)
        {
            ScheduleLoopPanelUsefulHeightRefresh(force: true);
            return;
        }

        LoopMdConfig? config;
        try { config = LoopMdParser.Parse(_selectedLoopMdPath); }
        catch
        {
            ScheduleLoopPanelUsefulHeightRefresh(force: true);
            return;
        }

        if (config?.Options is not { Count: > 0 })
        {
            ScheduleLoopPanelUsefulHeightRefresh(force: true);
            return;
        }

        bool inGroup = false;
        foreach (var opt in config.Options)
        {
            if (opt.Type == "group")
            {
                var header = new TextBlock
                {
                    Text       = opt.Label ?? opt.Key,
                    FontWeight = FontWeights.SemiBold,
                    Margin     = new Thickness(0, 6, 0, 2),
                };
                header.SetResourceReference(TextBlock.ForegroundProperty, "LabelText");
                header.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeBody");
                LoopOptionsPanel.Children.Add(header);
                inGroup = true;
                continue;
            }

            UIElement control = opt.Type switch
            {
                "bool" => CreateBoolOptionControl(opt),
                "int"  => CreateIntOptionControl(opt),
                "enum" => CreateEnumOptionControl(opt),
                _      => CreateIntOptionControl(opt),
            };

            if (inGroup && control is FrameworkElement fe)
                fe.Margin = new Thickness(fe.Margin.Left + 12, fe.Margin.Top, fe.Margin.Right, fe.Margin.Bottom);

            LoopOptionsPanel.Children.Add(control);
        }

        LoopOptionsPanel.Visibility = Visibility.Visible;
        RefreshLoopMergedView();
        ScheduleLoopPanelUsefulHeightRefresh(force: true);
    }

    private CheckBox CreateBoolOptionControl(LoopOption opt)
    {
        var cb = new CheckBox
        {
            Content   = opt.Label ?? opt.Key,
            IsChecked = opt.RawValue.Equals("true", StringComparison.OrdinalIgnoreCase),
            ToolTip   = string.IsNullOrEmpty(opt.Hint) ? null : MakeThemedToolTip(opt.Hint),
            Margin    = new Thickness(0, 0, 0, 4),
        };
        cb.SetResourceReference(Control.ForegroundProperty, "LabelText");
        cb.SetResourceReference(Control.FontSizeProperty, "FontSizeBody");

        var capturedPath = _selectedLoopMdPath;
        var capturedKey  = opt.Key;
        cb.Checked   += (_, _) => { LoopMdParser.UpdateOptionValue(capturedPath!, capturedKey, "true");  RefreshLoopMergedView(); };
        cb.Unchecked += (_, _) => { LoopMdParser.UpdateOptionValue(capturedPath!, capturedKey, "false"); RefreshLoopMergedView(); };
        return cb;
    }

    private UIElement CreateIntOptionControl(LoopOption opt)
    {
        var grid = new Grid { Margin = new Thickness(0, 0, 0, 4) };
        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

        var label = new TextBlock
        {
            Text              = opt.Label ?? opt.Key,
            ToolTip           = string.IsNullOrEmpty(opt.Hint) ? null : MakeThemedToolTip(opt.Hint),
            VerticalAlignment = VerticalAlignment.Center,
            Margin            = new Thickness(0, 0, 6, 0),
        };
        label.SetResourceReference(TextBlock.ForegroundProperty, "LabelText");
        label.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeBody");

        var tb = new TextBox
        {
            Text   = opt.RawValue,
            Width  = 50,
            HorizontalAlignment = HorizontalAlignment.Left,
        };
        tb.SetResourceReference(Control.BackgroundProperty, "InputSurface");
        tb.SetResourceReference(Control.BorderBrushProperty, "InputBorder");
        tb.SetResourceReference(Control.ForegroundProperty, "LabelText");
        tb.SetResourceReference(Control.FontSizeProperty, "FontSizeBody");

        var capturedPath = _selectedLoopMdPath;
        var capturedKey  = opt.Key;
        tb.LostFocus += (_, _) =>
        {
            var text = tb.Text.Trim();
            if (int.TryParse(text, out _))
            {
                tb.ClearValue(TextBox.BorderBrushProperty);
                if (TryFindResource("InputBorder") is System.Windows.Media.Brush b)
                    tb.BorderBrush = b;
                LoopMdParser.UpdateOptionValue(capturedPath!, capturedKey, text);
                RefreshLoopMergedView();
            }
            else
            {
                tb.BorderBrush = System.Windows.Media.Brushes.Red;
            }
        };

        Grid.SetColumn(label, 0);
        Grid.SetColumn(tb, 1);
        grid.Children.Add(label);
        grid.Children.Add(tb);
        return grid;
    }

    private UIElement CreateEnumOptionControl(LoopOption opt)
    {
        var capturedPath = _selectedLoopMdPath;
        var capturedKey  = opt.Key;

        // ≤ 5 choices → radio button group
        if (opt.Choices is not null && opt.Choices.Count <= 5)
        {
            var stack = new StackPanel { Margin = new Thickness(0, 0, 0, 4) };

            var label = new TextBlock
            {
                Text    = opt.Label ?? opt.Key,
                ToolTip = string.IsNullOrEmpty(opt.Hint) ? null : MakeThemedToolTip(opt.Hint),
                Margin  = new Thickness(0, 0, 0, 2),
            };
            label.SetResourceReference(TextBlock.ForegroundProperty, "LabelText");
            label.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeBody");
            stack.Children.Add(label);

            foreach (var choice in opt.Choices)
            {
                var rb = new RadioButton
                {
                    Content   = choice,
                    GroupName = opt.Key,
                    IsChecked = string.Equals(choice, opt.RawValue, StringComparison.Ordinal),
                    Margin    = new Thickness(12, 0, 0, 1),
                };
                rb.SetResourceReference(Control.ForegroundProperty, "LabelText");
                rb.SetResourceReference(Control.FontSizeProperty, "FontSizeBody");

                var capturedChoice = choice;
                rb.Checked += (_, _) =>
                {
                    LoopMdParser.UpdateOptionValue(capturedPath!, capturedKey, capturedChoice);
                    RefreshLoopMergedView();
                };

                stack.Children.Add(rb);
            }

            return stack;
        }

        // ≥ 6 choices (or null) → existing ComboBox layout
        var grid = new Grid { Margin = new Thickness(0, 0, 0, 4) };
        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        grid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });

        var comboLabel = new TextBlock
        {
            Text              = opt.Label ?? opt.Key,
            ToolTip           = string.IsNullOrEmpty(opt.Hint) ? null : MakeThemedToolTip(opt.Hint),
            VerticalAlignment = VerticalAlignment.Center,
            Margin            = new Thickness(0, 0, 6, 0),
        };
        comboLabel.SetResourceReference(TextBlock.ForegroundProperty, "LabelText");
        comboLabel.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeBody");

        var combo = new ComboBox
        {
            HorizontalAlignment = HorizontalAlignment.Left,
            MaxWidth            = 90,
        };
        combo.SetResourceReference(Control.StyleProperty, "ThemedComboBoxStyle");
        combo.SetResourceReference(Control.FontSizeProperty, "FontSizeBody");

        if (opt.Choices is not null)
            foreach (var choice in opt.Choices)
                combo.Items.Add(choice);

        combo.SelectedItem = opt.RawValue;

        combo.SelectionChanged += (_, _) =>
        {
            if (combo.SelectedItem is string selected)
            {
                LoopMdParser.UpdateOptionValue(capturedPath!, capturedKey, selected);
                RefreshLoopMergedView();
            }
        };

        Grid.SetColumn(comboLabel, 0);
        Grid.SetColumn(combo, 1);
        grid.Children.Add(comboLabel);
        grid.Children.Add(combo);
        return grid;
    }

    private void LoadTasksPanel()
    {
        if (TasksActivePanel is null) return;

        _tasksPanelController ??= new TasksPanelController(
            activePanel: TasksActivePanel,
            completedPanel: TasksCompletedPanel,
            completedSection: TasksCompletedSection,
            outerBorder: TasksPanelBorder,
            getTasksPath: () => _currentWorkspace is null
                                     ? null
                                     : Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md"),
            editTasksAction: () => EditTasksMenuItem_Click(this, new RoutedEventArgs()),
            reloadPanel: () => Dispatcher.BeginInvoke(LoadTasksPanel),
            attachFollowUp: task => AttachContextFollowUp(
                $"Task: {task.Text}",
                BuildTypedAttachmentBlock("task", task.Text, BuildTaskContentBody(task))),
            addToNewChat: task => { AddEmptyQueueSlot(); AttachContextFollowUp(
                $"Task: {task.Text}",
                BuildTypedAttachmentBlock("task", task.Text, BuildTaskContentBody(task))); },
            addToNotes: task => AddNoteFromTextWithTitle(
                $"Task - {task.Text}",
                BuildTaskContentBlock(task)),
            getRoster: () => _currentWorkspace is null
                                 ? []
                                 : _teamRosterLoader.Load(_currentWorkspace.FolderPath));
        _tasksPanelController.ClearFilterAction = () => { if (TasksFilterBox is not null) TasksFilterBox.Text = string.Empty; };

        // Wire dynamic max-width hint so splitter snap targets content width
        if (TasksPanelBorder is { } tpb && tpb.MaximumUsefulSizeProvider is null)
            tpb.MaximumUsefulSizeProvider = orientation => orientation switch
            {
                DockResizeOrientation.Horizontal => _tasksPanelController.GetMaximumUsefulWidth(),
                DockResizeOrientation.Vertical   => _tasksPanelController.GetMaximumUsefulHeight(),
                _                                => null
            };

        var workspace = _currentWorkspace;
        if (workspace is null) { _tasksPanelController.ShowEmpty("No workspace open"); return; }

        var tasksPath = Path.Combine(workspace.SquadFolderPath, "tasks.md");
        if (!File.Exists(tasksPath)) { _tasksPanelController.ShowEmpty("No tasks.md found"); return; }

        string[] lines;
        try { lines = File.ReadAllLines(tasksPath); }
        catch { _tasksPanelController.ShowEmpty("Could not read tasks.md"); return; }

        var parseResult = TasksPanelParser.Parse(lines);
        BuildTasksAgentSuggestions(parseResult);

        // Also gather completed items from completed-tasks.md (most-recent-first by file order)
        var completedTasksPath = Path.Combine(workspace.SquadFolderPath, "completed-tasks.md");
        IReadOnlyList<TaskItem> extraCompleted = [];
        if (File.Exists(completedTasksPath))
        {
            try
            {
                var completedLines = File.ReadAllLines(completedTasksPath);
                extraCompleted = TasksPanelParser.ParseCompletedFile(completedLines);
            }
            catch { /* ignore — best-effort */ }
        }

        // tasks.md ✅ section first (most recent), then completed-tasks.md items.
        // Deduplicate: skip completed-tasks.md items whose text already appears in the tasks.md set.
        List<TaskItem> allCompleted;
        if (parseResult.CompletedItems.Count == 0 && extraCompleted.Count == 0)
        {
            allCompleted = [];
        }
        else
        {
            allCompleted = [.. parseResult.CompletedItems];
            var seenTexts = new System.Collections.Generic.HashSet<string>(
                parseResult.CompletedItems.Select(i => i.Text.Trim()),
                StringComparer.OrdinalIgnoreCase);
            foreach (var item in extraCompleted)
            {
                if (seenTexts.Add(item.Text.Trim()))
                    allCompleted.Add(item);
            }
        }

        // Preserve structured plan metadata while merging completed-task history. Dropping
        // DecomposeGroups here leaves visible plan rows without an executable group lookup.
        var combined = parseResult.WithCompletedItems(allCompleted);
        _tasksPanelController.Refresh(combined);
        UpdateTasksDoThesePresentation(TasksFilterBox?.Text ?? string.Empty);
    }

    private Brush PriorityDotColor(string emoji) => emoji switch
    {
        "⚫" => (Brush)FindResource("PriorityCritical"),
        "🔴" => (Brush)FindResource("PriorityHigh"),
        "🟡" => (Brush)FindResource("PriorityMid"),
        "🟢" => (Brush)FindResource("PriorityLow"),
        "🔵" => (Brush)FindResource("PriorityLow"),
        _ => Brushes.Gray
    };

    private static string PriorityResourceKey(string emoji) => emoji switch
    {
        "⚫" => "PriorityCritical",
        "🔴" => "PriorityHigh",
        "🟡" => "PriorityMid",
        "🟢" => "PriorityLow",
        "🔵" => "PriorityLow",
        _ => "LabelText"
    };

    private async void StartLoopButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_currentWorkspace is null) return;

            var effectiveLoopMode = (Keyboard.Modifiers & ModifierKeys.Shift) != 0
                ? LoopMode.SquadCli
                : LoopMode.NativeAgents;

            await QueueOrStartLoopAsync(effectiveLoopMode);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(StartLoopButton_Click), ex);
        }
    }

    /// <summary>
    /// Sets the active loop mode and starts the loop immediately, or queues it to start
    /// automatically once the currently-running prompt (and any queued prompts) finish.
    /// </summary>
    private async Task QueueOrStartLoopAsync(
        LoopMode mode,
        ActiveLoopExecutionState? requestedExecution = null)
    {
        _conversationManager.UpdatePendingManualLoopResumeState(null);
        _activeLoopMode = mode;
        var queuedExecution = requestedExecution ?? BuildGeneralLoopExecutionState();
        _conversationManager.UpdateActiveLoopExecutionState(queuedExecution);
        if (mode == LoopMode.NativeAgents && (_isPromptRunning || HasQueuedWorkAheadOfNewLoop()))
        {
            QueueLoopResumeAfterQueueDrain(_loopCurrentIteration, "manual-start", updateUi: false);
            AppendLoopOutputLine($"⏳ Loop queued — {LoopTimestamp()} — will start after queue drains.", LoopLifecycleBrush);
            SyncLoopPanel();
            return;
        }
        await StartLoopImmediateAsync(resumeExecution: queuedExecution);
    }

    private async Task StartLoopImmediateAsync(
        int resumeFromIteration = 0,
        ActiveLoopExecutionState? resumeExecution = null)
    {
        if (_currentWorkspace is null) return;
        if (_activeLoopMode == LoopMode.NativeAgents && (_isPromptRunning || HasQueuedWorkAheadOfNewLoop()))
        {
            QueueLoopResumeAfterQueueDrain(resumeFromIteration, "start-loop-immediate-guard");
            return;
        }
        _loopResumeSuppressed = false;
        ClearExecutingPlanRuntimeState();
        BackupAndClearLoopOutput();
        var loopMdPath = !string.IsNullOrWhiteSpace(resumeExecution?.LoopPath)
            ? resumeExecution.LoopPath
            : GetEffectiveLoopMdPath();
        var filterText = resumeExecution?.FilterText ?? TasksFilterBox?.Text?.Trim() ?? "";
        var activeExecution = new ActiveLoopExecutionState(
            loopMdPath,
            filterText,
            LastCompletedIteration: Math.Max(0, resumeFromIteration));
        _conversationManager.UpdateActiveLoopExecutionState(activeExecution);

        if (_activeLoopMode == LoopMode.NativeAgents)
        {
            var config = LoopMdParser.Parse(loopMdPath);
            if (config == null)
            {
                OpenLoopConfigFlyout(loopMdPath, LoopConfigFlyoutMode.Configure, existingConfig: null);
                return;
            }
            await _loopController.StartAsync(config, _settingsSnapshot.LoopContinuousContext, _currentWorkspace?.FolderPath, resumeFromIteration, filterText, _featureGroupStore?.Load());
        }
        else
        {
            var config = LoopMdParser.Parse(loopMdPath)
                ?? throw new InvalidDataException($"Could not parse loop file for Squad CLI: {loopMdPath}");

            CleanupActiveLoopCliProjection("replace-before-start");
            var projection = LoopCliProjection.Create(
                sourcePath: loopMdPath,
                config,
                workspacePath: _currentWorkspace.FolderPath,
                filterText,
                featureGroups: _featureGroupStore?.Load());
            _activeLoopCliProjection = projection;
            try
            {
                await _bridge.RunLoopAsync(
                    projection.FilePath,
                    _currentWorkspace.FolderPath,
                    _conversationManager.CurrentSessionId,
                    displayLoopMdPath: loopMdPath);
            }
            catch
            {
                if (ReferenceEquals(_activeLoopCliProjection, projection))
                    CleanupActiveLoopCliProjection("start-failed");
                throw;
            }
        }
    }

    private ActiveLoopExecutionState BuildGeneralLoopExecutionState()
    {
        var loopPath = GetEffectiveLoopMdPath();
        var filterText = TasksFilterBox?.Text?.Trim() ?? "";
        return new ActiveLoopExecutionState(loopPath, filterText);
    }

    private void ClearExecutingPlanRuntimeState()
    {
        _CodeHealthGroupRunner?.ClearCurrentStep();
        _CodeHealthGroupRunner = null;
        _activeDecomposeGroupId = null;
        _decomposeContinuationTaskId = null;
        _decomposeContinuationPaths = [];
        _lastPlanTranscriptPhaseKey = null;
    }

    private void ClearExecutingPlanState()
    {
        ClearExecutingPlanRuntimeState();
        _conversationManager.UpdateActiveLoopExecutionState(null);
    }

    private void SuppressLoopResume(string reason)
    {
        _loopResumeSuppressed = true;
        _loopQueued = false;
        _loopQueuedResumeFromIteration = 0;
        _loopInterruptedByQueue = false;
        _loopPausedForQuickReply = false;
        _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
        // A running plan keeps its durable execution envelope until the terminal
        // callback has successfully persisted the plan outcome. Finalization observes
        // StopState and exits without attempting another protocol repair.
        if (_activeDecomposeGroupId is null || !_loopController.IsRunning)
            _conversationManager.UpdateActiveLoopExecutionState(null);
        _conversationManager.UpdateQueuedPromptsState(
            _promptQueue.Items, _followUpAttachments,
            queueRightmostHeld: IsRightmostQueueTabActive(),
            loopQueuedToDequeue: false,
            activeDraftSimEntry: _pec.ActiveDraftSimEntry,
            activeTabIndex: GetActiveQueueTabIndex());
        SquadDashTrace.Write(
            "Loop",
            $"Loop auto-resume suppressed reason={reason} restartPending={_restartPending} group={_activeDecomposeGroupId ?? "(none)"}");
    }

    private void SuppressLoopResumeAfterExplicitStop(string reason) =>
        SuppressLoopResume(reason);

    private async Task<bool> ResumeLoopImmediateAsync(int resumeFromIteration)
    {
        var resume = LoopResumeExecutionPolicy.Resolve(
            _conversationManager.ConversationState.ActiveLoopExecution,
            _activeDecomposeGroupId,
            _conversationManager.ConversationState.ActiveExecutingPlanGroupId);
        if (resume.Kind == LoopResumeExecutionKind.ExecutingPlan)
        {
            var started = await StartDecomposeLoopAsync(
                resume.GroupId!,
                resumeFromIteration: resumeFromIteration,
                expectedRevision: resume.Revision);
            if (!started)
                throw new InvalidOperationException(
                    $"Plan {resume.GroupId} could not reclaim its persisted execution state.");
            return true;
        }

        if (resume.Kind == LoopResumeExecutionKind.Refuse)
        {
            _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
            AppendLoopOutputLine(
                "⏹ Loop was not resumed because its exact path and filter were not persisted.",
                LoopLifecycleBrush);
            SquadDashTrace.Write(
                "Loop",
                $"Refused unsafe loop resume without persisted execution state resumeFromIteration={resumeFromIteration}.");
            return false;
        }

        await StartLoopImmediateAsync(resumeFromIteration, resume.Execution);
        return true;
    }

    private async Task ResumeLoopAfterRestartSafelyAsync(int resumeFromIteration)
    {
        if (_isClosing || _restartPending) return;

        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        try
        {
            AppendLoopOutputLine("🔄 Resuming loop after restart…", LoopLifecycleBrush);
            var claimed = await ResumeLoopImmediateAsync(resumeFromIteration);
            if (!claimed)
                throw new InvalidOperationException("The persisted loop execution could not be reclaimed safely.");

            // This global flag is retained only for backward compatibility. The workspace
            // envelope remains authoritative while the claimed loop is active, but the
            // legacy marker must not be consumed until its owning workspace has started.
            _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
        }
        catch (Exception ex)
        {
            // A restart can expose unfinished source changes from an interrupted plan
            // iteration. Refusing to run is correct, but it is a controlled pause—not an
            // unobserved TaskScheduler failure and not permission to select other work.
            AppendLoopOutputLine($"⏸ Loop was not resumed: {ex.Message}", LoopLifecycleBrush);
            SquadDashTrace.Write("Loop", $"Startup loop resume refused: {ex}");
            SyncLoopPanel();

            if (ex is PlanPreflightBlockedException preflightBlocked &&
                !string.IsNullOrWhiteSpace(execution?.DecomposeGroupId))
            {
                PausePlanForCleanWorktree(preflightBlocked, execution.DecomposeGroupId);
            }
            else if (!string.IsNullOrWhiteSpace(execution?.DecomposeGroupId))
            {
                InterruptPlanAfterFailedResume(execution, ex.Message);
            }
            else
            {
                // General loops have no plan recovery card. Keep the workspace envelope
                // so a user action or later restart can still reclaim the exact path/filter.
                ShowSystemTranscriptEntry(
                    $"Loop recovery paused after restart: {ex.Message} The saved loop details were preserved.");
            }
        }
    }

    private async Task<bool> StartDecomposeLoopAsync(
        string groupId,
        DecomposedTaskGroup? group = null,
        int resumeFromIteration = 0,
        string? expectedRevision = null,
        string? continuationTaskId = null,
        IReadOnlyList<string>? continuationPaths = null,
        AssessedRecoveryContinuationState? assessedRecoveryContinuation = null)
    {
        if (_currentWorkspace is null) return false;
        if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
        {
            SquadDashTrace.Write(
                "Loop",
                $"Deferred Executing Plan start because the coordinator slot is busy plan={groupId} " +
                $"promptRunning={_isPromptRunning} loopRunning={IsLoopRunning} queueDrain={_queueDrainActive}.");
            return false;
        }
        var isConfirmedContinuation = !string.IsNullOrWhiteSpace(continuationTaskId) &&
                                      continuationPaths is { Count: > 0 };
        var priorExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        var replayPendingResult = PlanRepairReplayPolicy.ShouldReplayBeforeMutationPreflight(
            priorExecution,
            groupId,
            expectedRevision);
        if (!isConfirmedContinuation && !replayPendingResult)
            await EnsurePlanWorktreeReadyAsync(_currentWorkspace.FolderPath, groupId);
        else if (replayPendingResult)
            SquadDashTrace.Write(
                "PlanRepair",
                $"Reclaiming persisted terminal result before mutation preflight plan={groupId} " +
                $"task={priorExecution!.RecoveryTaskId} revision={priorExecution.DecomposeRevision}.");

        string loopPath;
        try
        {
            loopPath = HostInstructionStore.EnsureAvailable(
                _currentWorkspace.SquadFolderPath,
                HostInstructionKind.PlanExecutionLoop).LegacyWorkspacePath!;
        }
        catch (Exception ex)
        {
            loopPath = HostInstructionStore.GetLegacyWorkspacePath(
                           _currentWorkspace.SquadFolderPath,
                           HostInstructionKind.PlanExecutionLoop) ?? string.Empty;
            SquadDashTrace.Write(
                TraceCategory.General,
                $"Executing Plan instruction refresh failed; using the available compatibility or embedded instruction: {ex.Message}");
        }
        LoopMdConfig? config = File.Exists(loopPath) ? LoopMdParser.Parse(loopPath) : null;
        if (config is null)
        {
            var content = SquadInstallerService.LoadEmbeddedLoopMarkdownPublic("loop-executing-plan.md");
            config = content is null ? null : LoopMdParser.ParseFromContent(content);
            if (config is null)
            {
                SquadDashTrace.Write(TraceCategory.General, "StartDecomposeLoopAsync: failed to load Executing Plan loop config.");
                return false;
            }
        }

        var tasksPath = System.IO.Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");
        _CodeHealthGroupRunner = new CodeHealthGroupRunner(
            new DecomposedTasksWriter(),
            tasksPath);

        var durablePlan = _planStore?.Load(groupId);
        if (durablePlan is not null)
            durablePlan = RepairPlanSchemaBeforeExecution(durablePlan);
        if (durablePlan is null && group is not null)
        {
            var approvedAt = DateTimeOffset.UtcNow;
            var initialRevision = group.HostRevision
                ?? PendingDecomposePlanStore.ComputeRevision(group);
            var approved = PendingDecomposePlanAdapter.ToPlan(
                new PendingDecomposePlan(initialRevision, group),
                approvedAt) with
            {
                LifecycleStatus = PlanLifecycleStatus.Approved,
                Timestamps = new PlanTimestamps(approvedAt, AcceptedAt: approvedAt),
            };
            if (!PendingDecomposePlanAdapter.RevisionIsValid(approved))
                throw new InvalidDataException(
                    $"Plan {groupId} does not match its approved durable revision.");
            if (!TryPublishPlanProgress(approved, out var initializationError))
                throw new InvalidDataException(
                    $"Plan {groupId} could not initialize its durable execution contract: {initializationError}");
            durablePlan = approved;
        }
        if (durablePlan is null)
        {
            _CodeHealthGroupRunner = null;
            _conversationManager.UpdateActiveLoopExecutionState(null);
            throw new InvalidDataException($"Plan {groupId} has no durable execution contract.");
        }
        var executionGroup = PendingDecomposePlanAdapter.FromPlan(durablePlan).Group with
        {
            HostRevision = durablePlan.Revision,
        };
        if (!CodeHealthGroupRunner.HasNoDependencyCycle(executionGroup, out var cycleIds))
        {
            _CodeHealthGroupRunner = null;
            _conversationManager.UpdateActiveLoopExecutionState(null);
            throw new InvalidDataException(
                $"Plan {groupId} contains a dependency cycle: {string.Join(", ", cycleIds ?? [])}.");
        }

        var revision = durablePlan.Revision;
        _CodeHealthGroupRunner.RefreshTaskDefinitions(executionGroup);
        RefreshPlanProjectionBestEffort(durablePlan, "loop-start");

        if (!string.IsNullOrWhiteSpace(expectedRevision) &&
            !string.Equals(expectedRevision, revision, StringComparison.Ordinal))
        {
            _CodeHealthGroupRunner = null;
            _conversationManager.UpdateActiveLoopExecutionState(null);
            SquadDashTrace.Write(
                "Loop",
                $"Refused stale Executing Plan resume group={groupId} persistedRevision={expectedRevision} currentRevision={revision}.");
            AppendLoopOutputLine(
                $"⏹ Plan {groupId} was not resumed because its revision changed.",
                LoopLifecycleBrush);
            return false;
        }

        _loopResumeSuppressed = false;
        _planBranchLeasePausePending = false;
        _activeDecomposeGroupId = groupId;
        _planExecutionLog = new PlanExecutionLog(_currentWorkspace.FolderPath);
        _planExecutionLog.Append(new PlanExecutionLogEntry(
            Kind: "plan_started",
            Timestamp: DateTimeOffset.UtcNow.ToString("O"),
            PlanId: groupId,
            Revision: revision,
            Round: resumeFromIteration > 0 ? resumeFromIteration : null,
            TaskId: _CodeHealthGroupRunner?.CurrentStepId,
            TaskTitle: _CodeHealthGroupRunner?.GetCurrentStepTitle(),
            Message: resumeFromIteration > 0
                ? $"Resumed from completed iteration {resumeFromIteration}."
                : null,
            Outcome: null));
        _decomposeContinuationTaskId = isConfirmedContinuation ? continuationTaskId : null;
        _decomposeContinuationPaths = isConfirmedContinuation ? [.. continuationPaths!] : [];
        var branchHead = (await RunGitAsync(
            _currentWorkspace.FolderPath,
            "rev-parse HEAD")).Trim();
        var executionBranch = executionGroup?.Branch?.Trim();
        if (string.IsNullOrWhiteSpace(executionBranch))
            throw new InvalidOperationException($"Plan {groupId} has no canonical branch.");
        var branchLease = replayPendingResult &&
                          priorExecution?.BranchLease is { } persistedLease &&
                          string.Equals(persistedLease.PlanId, groupId, StringComparison.Ordinal) &&
                          string.Equals(persistedLease.Revision, revision, StringComparison.Ordinal) &&
                          string.Equals(persistedLease.CanonicalBranch, executionBranch, StringComparison.Ordinal)
            ? persistedLease
            : new PlanBranchLease(
                groupId,
                revision,
                executionBranch,
                branchHead,
                DateTimeOffset.UtcNow);
        if (replayPendingResult)
            _decomposeIterationBaselineCommit = priorExecution?.TaskBaselineCommit ?? branchLease.BaselineCommit;
        _conversationManager.UpdateActiveLoopExecutionState(
            PlanExecutionResumeEnvelope.Create(
                loopPath,
                groupId,
                revision,
                resumeFromIteration,
                priorExecution,
                reclaimPersistedExecution: !string.IsNullOrWhiteSpace(expectedRevision),
                assessedRecoveryContinuation) with
            {
                BranchLease = branchLease,
            });

        // A reconstructed verification envelope has no in-memory runner identity from the
        // implementation round. Re-track the same pending task before the verifier starts so
        // an accepted verdict can apply the preserved candidate instead of failing with
        // "no tracked plan step" after verification succeeds.
        if (_conversationManager.ConversationState.ActiveLoopExecution?.ActiveVerificationTaskId is { } verificationTaskId)
        {
            TrackFirstEligiblePlanStep(groupId);
            if (!string.Equals(
                    _CodeHealthGroupRunner?.CurrentStepId,
                    verificationTaskId,
                    StringComparison.Ordinal))
            {
                _activeDecomposeGroupId = null;
                _CodeHealthGroupRunner = null;
                _conversationManager.UpdateActiveLoopExecutionState(null);
                throw new InvalidOperationException(
                    $"SquadDash could not restore task {verificationTaskId} as the active verification candidate.");
            }
        }

        if (!TryPublishPlanStarted(groupId, executionGroup, revision, out var planStartError))
        {
            _planExecutionLog.Append(new PlanExecutionLogEntry(
                Kind: "plan_start_failed",
                Timestamp: DateTimeOffset.UtcNow.ToString("O"),
                PlanId: groupId,
                Revision: revision,
                Round: resumeFromIteration > 0 ? resumeFromIteration : null,
                TaskId: _CodeHealthGroupRunner?.CurrentStepId,
                TaskTitle: _CodeHealthGroupRunner?.GetCurrentStepTitle(),
                Message: planStartError,
                Outcome: "blocked"));
            ScheduleDecomposeSystemEntry(
                $"Plan {groupId} did not start because its durable state could not be initialized: " +
                (planStartError ?? "unknown persistence failure"));
            _activeDecomposeGroupId = null;
            _CodeHealthGroupRunner = null;
            _conversationManager.UpdateActiveLoopExecutionState(null);
            return false;
        }

        // A resumed or assessed plan can arrive here with every implementation task complete
        // and a ready validation as its only executable work. Activate that validation before
        // the first loop iteration so the runner never fabricates or repeats a task turn.
        if (_planStore?.Load(groupId) is { } startedPlan &&
            PlanExecutionBoundaryPolicy.SelectValidation(startedPlan) is { } boundaryValidation)
        {
            ActivateValidationForNextIteration(groupId, startedPlan, boundaryValidation);
        }

        _activeLoopMode = LoopMode.NativeAgents;
        SyncLoopPanel();
        BackupAndClearLoopOutput();

        await _loopController.StartAsync(config, continuousContext: true,
            _currentWorkspace?.FolderPath, resumeFromIteration, filterText: groupId,
            featureGroups: _featureGroupStore?.Load(), hostAssignsExactPlanTask: true);
        if (_conversationManager.ConversationState.PendingPlanContinuation is { } continuation &&
            string.Equals(continuation.PlanId, groupId, StringComparison.Ordinal) &&
            string.Equals(continuation.Revision, revision, StringComparison.Ordinal))
        {
            _conversationManager.UpdatePendingPlanContinuationState(null);
            _pendingDecomposeRecoveryResponse = null;
            _pendingDecomposeRecoveryDispatchScheduled = false;
            _pendingDecomposeRecoveryDispatchScheduledAt = null;
            _pendingDecomposeRecoveryDispatchGeneration++;
            _pendingPlanContinuationClaimedAt = null;
            _pendingPlanContinuationDispatchAttempts = 0;
            SquadDashTrace.Write(
                "PlanRecovery",
                $"Cleared durable plan continuation after confirmed plan start plan={groupId} revision={revision}.");
        }
        var resumedTaskId = _conversationManager.ConversationState.ActiveLoopExecution?
            .PlanExecutionAttempt?.TaskId
            ?? _CodeHealthGroupRunner?.CurrentStepId;
        // StartAsync schedules the first plan turn. Do not race that turn by draining the
        // ordinary prompt queue here; the normal turn-completion path will resume draining.
        ClearQueueRecoveryHoldForPlan(groupId, resumedTaskId, "plan-started");
        return true;
    }

    /// <summary>
    /// Parses a TASKS_JSON payload from an ordinary response and stages it for user approval.
    /// Unlike maintenance mode, an ordinary response never grants execution permission itself.
    /// </summary>
    private void TryStartDecomposeGroupFromResponse(string? rawResponse, TranscriptTurnView? ownerView = null)
    {
        _lastResponseContainedTaskPlan = false;
        if (_currentWorkspace is null)
            return;

        var responseSegments = ownerView?.ResponseEntries
            .Select(entry => (string?)entry.RawTextBuilder.ToString())
            .ToArray();
        var protocolJsonBlocks = ownerView?.ResponseEntries
            .SelectMany(entry => entry.ProtocolJsonBlocks ??
                                 TranscriptTextUtilities.ExtractInspectableProtocolJsonBlocks(
                                     entry.RawTextBuilder.ToString()))
            .ToArray();
        if (!TaskPlanResponseResolver.TryResolve(
                rawResponse,
                responseSegments,
                protocolJsonBlocks,
                _currentWorkspace.FolderPath,
                out var parserInput,
                out var planResponseSource,
                out var resolutionDiagnostic,
                out var payloadDetected))
        {
            _lastResponseContainedTaskPlan = payloadDetected;
            if (payloadDetected)
            {
                var reason = string.IsNullOrWhiteSpace(resolutionDiagnostic)
                    ? "SquadDash could not resolve the submitted plan payload."
                    : resolutionDiagnostic;
                var retryResponse = !string.IsNullOrWhiteSpace(rawResponse)
                    ? rawResponse
                    : responseSegments is { Length: > 0 }
                        ? string.Join("\n", responseSegments)
                        : null;
                AppendPlanStagingFailure(reason, retryResponse, ownerView);
                if (_decomposeRepairPending)
                {
                    ResetDecomposeRepairState();
                    RestoreInterruptedPlanRecoverySurfaces();
                }
                SquadDashTrace.Write(TraceCategory.General,
                    $"TASKS_JSON transport was detected but not resolved: {reason}");
            }
            return;
        }
        _lastResponseContainedTaskPlan = true;

        if (!TasksJsonParser.TryParse(parserInput, out var group, out var parseDiagnostic) || group is null)
        {
            SquadDashTrace.Write(TraceCategory.General,
                "TASKS_JSON detected in completed response but parsing or validation failed: " +
                (parseDiagnostic?.Message ?? "unknown parser failure"));
            BeginPlanHumanProofCoverageReview(
                group: null,
                parserInput,
                additionalDiagnostics: parseDiagnostic?.GetRepairDiagnostics() ?? []);
            return;
        }

        if (PlanRevisionPromptContextParser.TryParse(ownerView?.Prompt, out var revisionContext) &&
            revisionContext is not null)
        {
            StageLegacyPlanRevisionResponse(group, revisionContext, planResponseSource, ownerView);
            return;
        }

        var preflightDiagnostics = new List<string>();
        if (!PlanAgentAssignmentCatalogValidator.TryValidate(
                group,
                _currentWorkspace!.SquadFolderPath,
                out var assignmentCatalogError,
                requireExplicitRouting:
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off,
                enforceAssignments:
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off))
        {
            SquadDashTrace.Write("PlanRouting", assignmentCatalogError ?? "Invalid plan agent assignment.");
            preflightDiagnostics.Add(assignmentCatalogError ?? "The plan has an invalid agent assignment.");
        }

        if (!TryValidateDecomposeRevisionAgainstWorkspace(group, out _, out var persistedRevisionError))
        {
            preflightDiagnostics.Add(persistedRevisionError ?? "The plan revision does not match the workspace.");
        }

        if (!DecomposePlanRevision.TryNormalize(group, out var normalizedGroup, out var revisionError))
        {
            SquadDashTrace.Write(TraceCategory.General,
                $"TASKS_JSON group '{group.GroupId}' rejected as an invalid revision: {revisionError}");
            preflightDiagnostics.Add(revisionError ?? "The plan revision could not be normalized.");
        }
        else
        {
            group = normalizedGroup;
        }

        preflightDiagnostics.AddRange(
            PlanHumanProofTitlePolicy.ValidateAiAuthoredPlan(group));

        SquadDashTrace.Write(TraceCategory.General,
            $"TASKS_JSON parsed from ordinary response for group '{group.GroupId}' — staging for approval.");
        if (!CodeHealthGroupRunner.HasNoDependencyCycle(group, out var cycleIds))
        {
            SquadDashTrace.Write(TraceCategory.General,
                $"TASKS_JSON group '{group.GroupId}' rejected before staging due to dependency cycle: {string.Join(", ", cycleIds!)}");
            preflightDiagnostics.Add(
                $"The task dependency graph contains a cycle involving: {string.Join(", ", cycleIds!)}");
        }
        if (IsDurablePlanArchived(group.GroupId))
        {
            new PendingDecomposePlanStore(_currentWorkspace!.SquadFolderPath).Archive(group.GroupId);
            SquadDashTrace.Write(TraceCategory.General,
                $"Discarded late task-plan proposal for archived plan '{group.GroupId}'.");
            ShowArchivedPlanRevisionRecovery(group, ownerView);
            return;
        }
        BeginPlanHumanProofCoverageReview(group, parserInput, preflightDiagnostics);
    }

    private bool BeginPlanHumanProofCoverageReview(
        DecomposedTaskGroup? group,
        string? rejectedCandidate,
        IReadOnlyList<string>? additionalDiagnostics = null)
    {
        if (_currentWorkspace is null) return false;
        rejectedCandidate = string.IsNullOrWhiteSpace(rejectedCandidate)
            ? group is null ? string.Empty : "TASKS_JSON:\n" + JsonSerializer.Serialize(group)
            : rejectedCandidate;
        if (string.IsNullOrWhiteSpace(rejectedCandidate))
        {
            AppendPlanStagingFailure(
                "The plan candidate was unavailable for complete preflight validation.",
                retryResponse: null,
                ownerView: null);
            return false;
        }
        UpdatePlanValidationStatus(
            _decomposeRepairPending
                ? "Plan corrections received. SquadDash is rechecking structure, ownership, and human-proof coverage…"
                : "Validating plan structure, ownership, and human-proof coverage…");
        var checkId = Guid.NewGuid().ToString("N");
        var candidateHash = PlanHumanProofCoverageReview.ComputeCandidateHash(rejectedCandidate);
        var pending = new PendingPlanHumanProofCoverageReview(
            checkId,
            candidateHash,
            group,
            rejectedCandidate,
            additionalDiagnostics ?? [],
            Attempt: 0);
        try
        {
            new PlanHumanProofCoverageCandidateStore(_currentWorkspace.SquadFolderPath)
                .Save(pending);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidDataException
                                      or InvalidOperationException)
        {
            RemovePlanValidationStatus();
            AppendPlanStagingFailure(
                $"The plan candidate could not be prepared for semantic preflight: {ex.Message}",
                rejectedCandidate,
                ownerView: null);
            return false;
        }

        _pendingPlanHumanProofCoverageReview = pending;
        EnqueuePlanHumanProofCoverageReview(checkId, candidateHash, correction: null);
        return true;
    }

    private void EnqueuePlanHumanProofCoverageReview(
        string checkId,
        string candidateHash,
        string? correction,
        bool drain = true)
    {
        var prompt = PlanHumanProofCoverageReview.BuildPrompt(checkId, candidateHash);
        if (!string.IsNullOrWhiteSpace(correction))
            prompt += $"\n\nYour previous response violated the required review envelope: {correction} " +
                      "Return the complete corrected envelope now.";
        var queued = EnqueuePrompt(
            prompt,
            isSystemInjected: true,
            sourceTag: PlanHumanProofCoverageQueueTag,
            drain: drain);
        if (queued is null)
        {
            FailPlanHumanProofCoverageReview(
                "SquadDash could not queue the plan-contract preflight.");
            return;
        }
        queued.IsLocked = true;
        queued.DisplayLabel = "Validate plan contracts";
        queued.ReadOnlyDisplayText =
            "AI is checking ownership, executable preparation, and human-observable checkpoints.";
        SyncQueuePanel();
    }

    private bool TryHandlePlanHumanProofCoverageReviewFromResponse(string? rawResponse)
    {
        if (rawResponse?.Contains(PlanHumanProofCoverageReview.Marker, StringComparison.Ordinal) != true)
            return false;
        var pending = _pendingPlanHumanProofCoverageReview;
        if (pending is null)
        {
            SquadDashTrace.Write("PlanPreflight",
                "Ignored a plan-contract result because no plan preflight is pending.");
            return true;
        }
        if (!PlanHumanProofCoverageReview.TryParse(rawResponse, out var review, out var error) || review is null)
            return RetryOrFailPlanHumanProofCoverageReview(error ?? "The semantic preflight result was invalid.");
        if (!string.Equals(review.CheckId, pending.CheckId, StringComparison.Ordinal) ||
            !string.Equals(review.CandidateHash, pending.CandidateHash, StringComparison.Ordinal))
            return RetryOrFailPlanHumanProofCoverageReview(
                "The semantic preflight result identified a different candidate.");

        if (pending.Group is not null)
        {
            var knownTargets = pending.Group.Tasks.Select(task => task.Id)
                .Concat((pending.Group.Validations ?? []).Select(validation => validation.ValidationId))
                .Append(pending.Group.GroupId)
                .ToHashSet(StringComparer.Ordinal);
            var unknown = review.Issues.FirstOrDefault(issue => !knownTargets.Contains(issue.TargetId));
            if (unknown is not null)
                return RetryOrFailPlanHumanProofCoverageReview(
                    $"The semantic preflight referenced unknown target '{unknown.TargetId}'.");
        }

        var diagnostics = pending.AdditionalDiagnostics.ToList();
        if (review.Status == "revision-required")
            diagnostics.AddRange(PlanHumanProofCoverageReview.BuildIssueRepairDiagnostics(review));
        if (diagnostics.Count > 0 || pending.Group is null)
        {
            _pendingPlanHumanProofCoverageReview = null;
            QueueDecomposeRepair(diagnostics, pending.RejectedCandidate);
            DeletePendingPlanHumanProofCoverageReviewBestEffort(
                pending.CheckId,
                "semantic preflight transitioned to plan repair");
            return true;
        }
        ResetDecomposeRepairState();
        SquadDashTrace.Write("PlanPreflight",
            $"Complete plan preflight passed plan={pending.Group.GroupId}.");
        var staged = StageValidatedDecomposeGroup(
            pending.Group,
            ownerView: null,
            retryResponse: pending.RejectedCandidate,
            humanProofCoverageChecked: true);
        _pendingPlanHumanProofCoverageReview = null;
        if (staged)
        {
            DeletePendingPlanHumanProofCoverageReviewBestEffort(
                pending.CheckId,
                "validated plan was durably staged");
        }
        return true;
    }

    private bool HandleMissingPlanHumanProofCoverageReview() =>
        RetryOrFailPlanHumanProofCoverageReview(
            $"The response did not contain {PlanHumanProofCoverageReview.Marker}.");

    private bool RetryOrFailPlanHumanProofCoverageReview(string reason)
    {
        var pending = _pendingPlanHumanProofCoverageReview;
        if (pending is null) return true;
        if (pending.Attempt < 1)
        {
            var retry = pending with
            {
                Attempt = pending.Attempt + 1,
                Correction = reason,
            };
            try
            {
                new PlanHumanProofCoverageCandidateStore(_currentWorkspace!.SquadFolderPath)
                    .Save(retry);
            }
            catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidDataException
                                          or InvalidOperationException)
            {
                FailPlanHumanProofCoverageReview(
                    "The plan-contract preflight retry state could not be persisted: " + ex.Message);
                return true;
            }
            _pendingPlanHumanProofCoverageReview = retry;
            EnqueuePlanHumanProofCoverageReview(
                retry.CheckId,
                retry.CandidateHash,
                reason);
            return true;
        }
        FailPlanHumanProofCoverageReview(
            "The plan-contract preflight was still invalid after one correction. " + reason);
        return true;
    }

    private void FailPlanHumanProofCoverageReview(string reason)
    {
        var pending = _pendingPlanHumanProofCoverageReview;
        _pendingPlanHumanProofCoverageReview = null;
        ResetDecomposeRepairState();
        if (pending is null) return;
        RemovePlanValidationStatus();
        AppendPlanStagingFailure(reason, pending.RejectedCandidate, ownerView: null);
        SquadDashTrace.Write("PlanPreflight", reason);
        DeletePendingPlanHumanProofCoverageReviewBestEffort(
            pending.CheckId,
            "semantic preflight failed");
    }

    private void RestorePendingPlanHumanProofCoverageReview()
    {
        if (_currentWorkspace is null) return;

        var store = new PlanHumanProofCoverageCandidateStore(_currentWorkspace.SquadFolderPath);
        var pending = store.Load(out var error);
        if (pending is null)
        {
            if (!string.IsNullOrWhiteSpace(error))
            {
                SquadDashTrace.Write("PlanPreflight", error);
                AppendLine("⚠ SquadDash preserved an interrupted plan preflight, but its correlation state " +
                           "could not be validated. The preserved files were not deleted. " + error);
            }
            return;
        }

        if (pending.Group is not null)
        {
            var alreadyStaged = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath)
                .Load(pending.Group.GroupId);
            var expectedRevision = PendingDecomposePlanStore.ComputeRevision(pending.Group);
            if (alreadyStaged is not null &&
                string.Equals(alreadyStaged.Revision, expectedRevision, StringComparison.Ordinal))
            {
                DeletePendingPlanHumanProofCoverageReviewBestEffort(
                    pending.CheckId,
                    "startup found the matching plan already staged");
                SquadDashTrace.Write("PlanPreflight",
                    $"Recovered completed preflight transaction plan={pending.Group.GroupId} " +
                    $"revision={expectedRevision}; no duplicate review was queued.");
                return;
            }
        }

        _pendingPlanHumanProofCoverageReview = pending;
        UpdatePlanValidationStatus("Resuming interrupted plan structure, ownership, and human-proof validation…");
        SquadDashTrace.Write("PlanPreflight",
            $"Restored pending plan preflight check={pending.CheckId} candidate={pending.CandidateHash} " +
            $"attempt={pending.Attempt} plan={pending.Group?.GroupId ?? "unparsed"}.");
    }

    private bool EnsurePendingPlanHumanProofCoverageReviewQueued()
    {
        var pending = _pendingPlanHumanProofCoverageReview;
        if (pending is null)
        {
            var orphaned = _promptQueue.Items
                .Where(item => string.Equals(
                    item.SourceTag, PlanHumanProofCoverageQueueTag, StringComparison.Ordinal))
                .ToArray();
            foreach (var item in orphaned)
            {
                _promptQueue.Remove(item.Id);
                SquadDashTrace.Write("PlanPreflight",
                    $"Discarded orphaned recovered plan-preflight queue item id={item.Id}.");
            }
            if (orphaned.Length > 0)
            {
                SyncQueuePanel();
                AppendLine("⚠ An interrupted plan validation could not be resumed because its " +
                           "candidate correlation was unavailable. Its orphaned queue item was removed; " +
                           "resubmit the original plan payload.");
            }
            return false;
        }

        var taggedItems = _promptQueue.Items
            .Where(item => string.Equals(
                item.SourceTag, PlanHumanProofCoverageQueueTag, StringComparison.Ordinal))
            .ToArray();
        var matching = taggedItems.FirstOrDefault(item =>
            item.Text.Contains(pending.CheckId, StringComparison.Ordinal) &&
            item.Text.Contains(pending.CandidateHash, StringComparison.Ordinal));

        foreach (var stale in taggedItems.Where(item => !ReferenceEquals(item, matching)))
        {
            _promptQueue.Remove(stale.Id);
            SquadDashTrace.Write("PlanPreflight",
                $"Discarded stale recovered plan-preflight queue item id={stale.Id}.");
        }

        if (matching is not null)
        {
            matching.IsLocked = true;
            matching.DisplayLabel = "Validate plan contracts";
            matching.ReadOnlyDisplayText =
                "AI is checking ownership, executable preparation, and human-observable checkpoints.";
            SyncQueuePanel();
            return false;
        }

        EnqueuePlanHumanProofCoverageReview(
            pending.CheckId,
            pending.CandidateHash,
            pending.Correction,
            drain: false);
        SquadDashTrace.Write("PlanPreflight",
            $"Requeued interrupted plan preflight check={pending.CheckId} candidate={pending.CandidateHash}.");
        return true;
    }

    private void DeletePendingPlanHumanProofCoverageReviewBestEffort(
        string checkId,
        string reason)
    {
        if (_currentWorkspace is null) return;
        try
        {
            new PlanHumanProofCoverageCandidateStore(_currentWorkspace.SquadFolderPath)
                .Delete(checkId);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            // A completed transaction left behind is safe: startup compares the staged revision
            // before deciding whether any review needs to be queued. Never turn cleanup failure
            // into a second plan-state transition.
            SquadDashTrace.Write("PlanPreflight",
                $"Could not clean preflight transaction {checkId} after {reason}: {ex.Message}");
        }
    }

    private void UpdatePlanValidationStatus(string status)
    {
        if (_planValidationStatusParagraph is null ||
            !CoordinatorThread.Document.Blocks.Contains(_planValidationStatusParagraph))
        {
            _planValidationStatusParagraph = CreateTranscriptParagraph(bottomMargin: 6);
            CoordinatorThread.Document.Blocks.Add(_planValidationStatusParagraph);
        }

        _planValidationStatusParagraph.Inlines.Clear();
        var prefix = new Run("Plan validation: ") { FontWeight = FontWeights.SemiBold };
        prefix.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        _planValidationStatusParagraph.Inlines.Add(prefix);
        var detail = new Run(status);
        detail.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        _planValidationStatusParagraph.Inlines.Add(detail);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private void RemovePlanValidationStatus()
    {
        if (_planValidationStatusParagraph is not null &&
            CoordinatorThread.Document.Blocks.Contains(_planValidationStatusParagraph))
        {
            CoordinatorThread.Document.Blocks.Remove(_planValidationStatusParagraph);
        }
        _planValidationStatusParagraph = null;
    }

    private void TryCollectStagedPlanRevisionFromVerifiedAgent(SquadSdkEvent evt)
    {
        if (evt.HostProtocolVerified != true ||
            !string.Equals(evt.HostProtocol, StagedPlanRevisionHostCollection.Protocol, StringComparison.Ordinal))
        {
            return;
        }

        _stagedPlanRevisionTurnCollectionState.MarkHandled(
            evt.HostProtocolGroupId ?? string.Empty,
            evt.HostProtocolBaseRevision ?? string.Empty);

        if (!StagedPlanRevisionHostCollection.TryCreateCandidate(evt, out var candidate, out var error) ||
            candidate is null)
        {
            SquadDashTrace.Write("PlanRevision",
                $"Rejected direct staged-plan collection toolCallId={evt.ToolCallId ?? "(none)"}: {error ?? "invalid correlation"}");
            QueueStagedPlanRevisionRepair(
                error ?? "The verified planning-agent response could not be correlated to its request.",
                null);
            return;
        }

        if (!_stagedPlanRevisionCollectionLedger.TryReserve(candidate.ToolCallId))
        {
            SquadDashTrace.Write("PlanRevision",
                $"Ignored duplicate direct staged-plan collection toolCallId={candidate.ToolCallId}.");
            return;
        }

        SquadDashTrace.Write("PlanRevision",
            $"Collecting verified staged-plan delta directly agent={candidate.AgentName} " +
            $"toolCallId={candidate.ToolCallId} group={candidate.Payload.GroupId} " +
            $"base={candidate.Payload.BaseRevision} " +
            $"correlation={evt.HostProtocolCorrelationSource ?? "unknown"}.");
        TryApplyStagedPlanRevisionFromResponse(candidate.RawResponse, ownerView: null);
    }

    private void StageLegacyPlanRevisionResponse(
        DecomposedTaskGroup proposal,
        PlanRevisionPromptContext context,
        string? responseSource,
        TranscriptTurnView? ownerView)
    {
        _planStore ??= _currentWorkspace is null ? null : new PlanStore(_currentWorkspace.SquadFolderPath);
        var current = _planStore?.Load(context.PlanId);
        if (current is null)
        {
            AppendLine($"⚠ Plan revision could not be applied because plan {context.PlanId} is no longer available.");
            return;
        }

        var payload = new PlanRevisionProposalPayload(
            context.PlanId,
            context.BaseRevision,
            $"Revise the plan definition for {current.Title}.",
            null,
            proposal);
        StageValidatedPlanRevisionProposal(current, payload, responseSource, ownerView);
    }

    private void StageValidatedPlanRevisionProposal(
        Plan current,
        PlanRevisionProposalPayload payload,
        string? responseSource,
        TranscriptTurnView? ownerView)
    {
        if (!PlanRevisionDeltaApplier.TryMaterialize(
                current, payload, out var revisedPlan, out var reopened, out var materializationError) ||
            revisedPlan is null)
        {
            QueuePlanRevisionRepair(materializationError ?? "The plan revision delta was invalid.", payload);
            return;
        }

        var result = PlanRevisionApplier.Apply(
            current,
            revisedPlan,
            payload.BaseRevision,
            DateTimeOffset.UtcNow,
            reopened);
        switch (result.Outcome)
        {
            case PlanRevisionApplyOutcome.NoChanges:
                AppendLine(PlanRevisionTranscriptPresentation.BuildNoChanges(result.PreservedLockedTaskCount));
                SquadDashTrace.Write("PlanRevision",
                    $"No changes plan={payload.PlanId} base={payload.BaseRevision} source={responseSource ?? "inline"}.");
                return;

            case PlanRevisionApplyOutcome.Stale:
                AppendLine($"⚠ Plan revision was not applied: {result.Error}");
                return;

            case PlanRevisionApplyOutcome.Invalid:
                QueuePlanRevisionRepair(result.Error ?? "The revised plan failed validation.", payload);
                return;

            case PlanRevisionApplyOutcome.Applied:
                break;
        }

        if (result.UpdatedPlan is not { } || result.EffectiveGroup is not { } effective)
        {
            QueuePlanRevisionRepair("The revised definition was incomplete.", payload);
            return;
        }

        if (!PlanAgentAssignmentCatalogValidator.TryValidate(
                effective,
                _currentWorkspace!.SquadFolderPath,
                out var assignmentCatalogError,
                requireExplicitRouting:
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off,
                enforceAssignments:
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off))
        {
            QueuePlanRevisionRepair(assignmentCatalogError ?? "Agent assignments were invalid.", payload);
            return;
        }

        var pending = new PendingPlanRevisionProposalStore(_currentWorkspace!.SquadFolderPath).Save(payload);
        SuppressCheckpointApprovalCardsForPendingRevision(current.PlanId);
        AppendPlanRevisionApprovalCard(current, pending, result, ownerView);
        _renderedPlanRevisionProposalIds.Add(pending.ProposalId);
        _planRevisionRepairPending = false;
        _planRevisionRepairProposal = null;
        SquadDashTrace.Write("PlanRevision",
            $"Staged proposal={pending.ProposalId} plan={payload.PlanId} base={payload.BaseRevision} " +
            $"changes={result.AppliedChangeCount} source={responseSource ?? "inline"}.");
        if (current.LifecycleStatus == PlanLifecycleStatus.Executing && IsLoopRunning)
        {
            SuppressLoopResume("plan-revision-awaiting-approval");
            _loopController.RequestStop();
            SquadDashTrace.Write("PlanRevision",
                $"Requested safe loop stop for proposal={pending.ProposalId} plan={payload.PlanId}.");
        }
    }

    private bool TryApplyStagedPlanRevisionFromResponse(
        string? rawResponse,
        TranscriptTurnView? ownerView)
    {
        if (rawResponse?.Contains(StagedPlanRevisionProposalParser.Marker, StringComparison.Ordinal) != true)
            return false;

        if (!StagedPlanRevisionProposalParser.TryParse(
                rawResponse, out var payload, out var parseError) || payload is null)
        {
            QueueStagedPlanRevisionRepair(
                parseError ?? "The staged-plan revision response was invalid.", null);
            return true;
        }
        if (_currentWorkspace is null)
        {
            _stagedPlanRevisionRepairPending = false;
            _stagedPlanRevisionRepairProposal = null;
            AppendLine("⚠ The staged plan could not be revised because no workspace is open.");
            return true;
        }

        var store = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath);
        var current = store.Load(payload.GroupId);
        if (current is null)
        {
            _stagedPlanRevisionRepairPending = false;
            _stagedPlanRevisionRepairProposal = null;
            AppendLine($"⚠ Staged plan {payload.GroupId} is no longer pending. No plan state changed.");
            return true;
        }

        var result = StagedPlanRevisionApplier.Apply(current, payload);
        switch (result.Outcome)
        {
            case StagedPlanRevisionOutcome.Stale:
                _stagedPlanRevisionRepairPending = false;
                _stagedPlanRevisionRepairProposal = null;
                AppendLine($"⚠ The staged-plan correction is stale. {result.Error} No plan state changed.");
                RestorePendingDecomposeApprovalSurfaces();
                return true;

            case StagedPlanRevisionOutcome.NoChanges:
                _stagedPlanRevisionRepairPending = false;
                _stagedPlanRevisionRepairProposal = null;
                AppendLine("No changes found in the staged-plan correction. The current proposal remains available for approval.");
                RestorePendingDecomposeApprovalSurfaces();
                return true;

            case StagedPlanRevisionOutcome.Invalid:
                QueueStagedPlanRevisionRepair(
                    result.Error ?? "The materialized staged-plan graph was invalid.", payload);
                return true;

            case StagedPlanRevisionOutcome.Applied:
                break;
        }

        var revised = result.RevisedGroup!;
        if (!PlanAgentAssignmentCatalogValidator.TryValidate(
                revised,
                _currentWorkspace.SquadFolderPath,
                out var assignmentError,
                requireExplicitRouting:
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off,
                enforceAssignments:
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off))
        {
            QueueStagedPlanRevisionRepair(
                assignmentError ?? "The materialized staged-plan assignments were invalid.", payload);
            return true;
        }
        if (!TryValidateDecomposeRevisionAgainstWorkspace(revised, out _, out var workspaceError))
        {
            QueueStagedPlanRevisionRepair(
                workspaceError ?? "The materialized staged plan did not match workspace state.", payload);
            return true;
        }

        _stagedPlanRevisionRepairPending = false;
        _stagedPlanRevisionRepairProposal = null;
        var fullProposal = "TASKS_JSON:\n" + System.Text.Json.JsonSerializer.Serialize(revised);
        if (StageValidatedDecomposeGroup(revised, ownerView, fullProposal))
        {
            SquadDashTrace.Write(
                "PlanRevision",
                $"Applied staged-plan delta group={payload.GroupId} base={payload.BaseRevision} " +
                $"revision={result.Revision} operations={payload.Operations.Count}.");
        }
        return true;
    }

    private void QueueStagedPlanRevisionRepair(
        string error,
        StagedPlanRevisionProposalPayload? payload)
    {
        if (_stagedPlanRevisionRepairPending)
        {
            _stagedPlanRevisionRepairPending = false;
            _stagedPlanRevisionRepairProposal = null;
            AppendLine("⚠ The staged-plan correction was still invalid after one repair attempt. " +
                       "The current proposal remains unchanged. Reason: " + error);
            RestorePendingDecomposeApprovalSurfaces();
            return;
        }

        _stagedPlanRevisionRepairPending = true;
        _stagedPlanRevisionRepairProposal = payload;
        _promptQueue.EnqueueAtFront(
            StagedPlanRevisionProposalParser.BuildRepairPrompt(error, payload),
            _promptQueueCoordinator.NextSequenceNumber(),
            sourceTag: "staged-plan-revision-repair",
            isSystemInjected: true);
        SyncQueuePanel();
        SyncSendButton();
        AppendLine("The staged-plan correction was invalid. SquadDash is asking the coordinator " +
                   "to correct the delta; the current proposal remains unchanged.");
    }

    private bool TryStagePlanRevisionProposalFromResponse(
        string? rawResponse,
        TranscriptTurnView? ownerView)
    {
        if (rawResponse?.Contains(PlanRevisionProposalParser.Marker, StringComparison.Ordinal) != true)
            return false;

        if (!PlanRevisionProposalParser.TryParse(rawResponse, out var payload, out var error) || payload is null)
        {
            QueuePlanRevisionRepair(error ?? "The plan revision response was invalid.", null);
            return true;
        }

        _planStore ??= _currentWorkspace is null ? null : new PlanStore(_currentWorkspace.SquadFolderPath);
        var current = _planStore?.Load(payload.PlanId);
        if (current is null)
        {
            QueuePlanRevisionRepair($"Plan {payload.PlanId} is not available in this workspace.", payload);
            return true;
        }
        if (!PlanRevisionPromptInjectionIsLegal(current))
        {
            AppendLine("⚠ The plan revision was not staged because the plan is not at a safe revision boundary. No plan state changed.");
            return true;
        }

        StageValidatedPlanRevisionProposal(current, payload, "PLAN_REVISION_JSON", ownerView);
        return true;
    }

    private static bool PlanRevisionPromptInjectionIsLegal(Plan plan) =>
        plan.Tasks.Any(task => task.Status is not (PlanTaskStatus.Complete or PlanTaskStatus.Superseded)) &&
        plan.LifecycleStatus is PlanLifecycleStatus.AwaitingApproval or
            PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked or PlanLifecycleStatus.Executing;

    private void QueuePlanRevisionRepair(string error, PlanRevisionProposalPayload? payload)
    {
        if (_planRevisionRepairPending)
        {
            _planRevisionRepairPending = false;
            _planRevisionRepairProposal = null;
            AppendLine("⚠ The plan revision response was still invalid after one repair attempt. The plan remains unchanged. " +
                       "Reason: " + error);
            return;
        }

        _planRevisionRepairPending = true;
        _planRevisionRepairProposal = payload;
        _promptQueue.EnqueueAtFront(
            PlanRevisionProposalParser.BuildRepairPrompt(error, payload),
            _promptQueueCoordinator.NextSequenceNumber(),
            sourceTag: "plan-revision-repair",
            isSystemInjected: true);
        SyncQueuePanel();
        SyncSendButton();
        AppendLine("The plan revision response was invalid. SquadDash is asking the coordinator to correct it; the plan remains unchanged.");
    }

    private async Task ApplyPendingPlanRevisionAsync(
        PendingPlanRevisionProposal pending,
        TextBlock status,
        FrameworkElement actions)
    {
        if (_currentWorkspace is null) return;
        _planStore ??= new PlanStore(_currentWorkspace.SquadFolderPath);
        var current = _planStore.Load(pending.Payload.PlanId);
        if (current is null ||
            !string.Equals(current.Revision, pending.Payload.BaseRevision, StringComparison.Ordinal))
        {
            status.Text = "This proposal is stale. The plan was not changed.";
            actions.IsEnabled = false;
            return;
        }

        var store = new PendingPlanRevisionProposalStore(_currentWorkspace.SquadFolderPath);
        var latest = store.Load(current.PlanId);
        if (latest is null || !string.Equals(latest.ProposalId, pending.ProposalId, StringComparison.Ordinal))
        {
            status.Text = "A newer proposal replaced this one. The plan was not changed.";
            actions.IsEnabled = false;
            return;
        }
        // A proposed-plan preview may have edited the same pending proposal in place.
        // Always approve the latest validated payload rather than the snapshot captured
        // when the transcript card was first rendered.
        pending = latest;

        if (!PlanRevisionDeltaApplier.TryMaterialize(
                current, pending.Payload, out var revisedPlan, out var reopened, out var materializationError) ||
            revisedPlan is null)
        {
            status.Text = "The proposal could not be applied: " +
                          (materializationError ?? "delta validation failed");
            actions.IsEnabled = true;
            return;
        }

        var result = PlanRevisionApplier.Apply(
            current,
            revisedPlan,
            pending.Payload.BaseRevision,
            DateTimeOffset.UtcNow,
            reopened);
        if (result.Outcome != PlanRevisionApplyOutcome.Applied ||
            result.UpdatedPlan is not { } updated || result.EffectiveGroup is not { } effective)
        {
            status.Text = result.Outcome == PlanRevisionApplyOutcome.NoChanges
                ? "The proposal no longer contains any changes."
                : "The proposal could not be applied: " + (result.Error ?? "validation failed");
            actions.IsEnabled = true;
            return;
        }

        try
        {
            new PlanRevisionHistoryStore(_currentWorkspace!.SquadFolderPath).SaveSnapshot(current);
        }
        catch (Exception ex)
        {
            AppendLine($"⚠ Plan revision was not applied because its revision history could not be saved: {ex.Message}");
            return;
        }
        if (!TryPublishPlanProgress(updated, out var publishError))
        {
            AppendLine($"⚠ Plan revision was not applied: {publishError}");
            return;
        }
        RefreshPlanProjectionBestEffort(updated, "approved plan revision");

        TrackAcceptedPlanRevisionForActiveExecution(current, updated);
        _CodeHealthGroupRunner?.RefreshTaskDefinitions(effective);
        store.Delete(current.PlanId);
        status.Text = "✓ Revision approved.";
        actions.Visibility = Visibility.Collapsed;
        AppendLine(PlanRevisionTranscriptPresentation.BuildApplied(
            updated.RevisionNumber,
            result.AppliedChangeCount,
            result.PreservedLockedTaskCount));
        SquadDashTrace.Write("PlanRevision",
            $"Applied plan={updated.PlanId} displayRevision={updated.RevisionNumber} " +
            $"changes={result.AppliedChangeCount} locked={result.PreservedLockedTaskCount} " +
            $"source=approved-proposal.");
        LoadTasksPanel();
        SyncPlansPanel();

        if (updated.LifecycleStatus == PlanLifecycleStatus.Interrupted && !updated.IsPaused)
        {
            try
            {
                await StartOrResumeDurablePlanAsync(updated);
                ResolveRecoveryTranscript(
                    "↩ Recovery resumed. The remaining plan was revised and execution continued.");
            }
            catch (PlanPreflightBlockedException blocked)
            {
                ScheduleApprovalResumeRetry(updated.PlanId, blocked);
            }
        }
    }

    private void AppendPlanRevisionApprovalCard(
        Plan current,
        PendingPlanRevisionProposal pending,
        PlanRevisionApplyResult preview,
        TranscriptTurnView? ownerView)
    {
        var blocks = ownerView?.NarrativeSection.Blocks ?? CoordinatorThread.Document.Blocks;
        var stack = new StackPanel { Margin = new Thickness(4) };

        var header = new TextBlock
        {
            Text = "Plan Revision - Approval Required",
            FontSize = _transcriptFontSize + 2,
            FontWeight = FontWeights.SemiBold,
            Margin = new Thickness(0, 0, 0, 6),
        };
        header.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
        stack.Children.Add(header);

        var planTitle = new TextBlock
        {
            FontSize = _transcriptFontSize,
            FontWeight = FontWeights.SemiBold,
            Margin = new Thickness(0, 0, 0, 8),
        };
        var planLink = new Hyperlink(new Run($"View current plan — revision {current.RevisionNumber}"))
        {
            Cursor = Cursors.Hand,
            ToolTip = "Open the currently authoritative plan",
        };
        planLink.Click += (_, _) => OpenPlanFromStore(current);
        System.Windows.Automation.AutomationProperties.SetName(planLink, $"Open plan {current.Title}");
        planTitle.Inlines.Add(planLink);
        if (preview.UpdatedPlan is { } proposedPlan)
        {
            planTitle.Inlines.Add(new Run("  ·  "));
            var proposedLink = new Hyperlink(new Run($"View proposed plan — revision {proposedPlan.RevisionNumber}"))
            {
                Cursor = Cursors.Hand,
                ToolTip = "Open the proposed revision; future pending steps can be edited before approval",
            };
            proposedLink.Click += (_, _) =>
            {
                var latestProposedPlan = ResolveLatestPendingRevisionPreview(current, pending) ?? proposedPlan;
                var previewPlan = latestProposedPlan with
                {
                    Summary = "PROPOSED REVISION — not active. " + latestProposedPlan.Summary,
                };
                var previewWindow = new PlanViewerWindow(
                    PendingDecomposePlanAdapter.FromPlan(previewPlan),
                    _currentWorkspace is null ? null : ReadGitBranch(_currentWorkspace.FolderPath),
                    _inboxFontSize,
                    durablePlan: previewPlan,
                    getSettings: () => _settingsSnapshot,
                    resolveAgentAvatar: ResolveAgentAvatarForPlanViewer,
                    saveDefinitionEdit: edited => SavePendingPlanRevisionEdit(pending, edited),
                    getAssignableAgents: GetAssignablePlanAgentsForViewer,
                    squadFolderPath: _currentWorkspace?.SquadFolderPath,
                    onDescriptionLinkClicked: HandleTranscriptLinkClick)
                {
                    Owner = CanShowOwnedWindow() ? this : null,
                    Title = $"Proposed Plan — {latestProposedPlan.DisplayName} — Revision {latestProposedPlan.RevisionNumber}",
                };
                previewWindow.Show();
            };
            System.Windows.Automation.AutomationProperties.SetName(
                proposedLink, $"View proposed revision {proposedPlan.RevisionNumber}");
            planTitle.Inlines.Add(proposedLink);
        }
        planTitle.SetResourceReference(TextBlock.ForegroundProperty, "LabelText");
        stack.Children.Add(planTitle);

        AddLabel("Proposed change");
        AddBody(pending.Payload.Summary, 8);
        AddLabel("Impact");
        PlanRevisionDeltaApplier.TryMaterialize(
            current, pending.Payload, out _, out var reopenIds, out _);
        if (reopenIds.Count > 0)
        {
            foreach (var taskId in reopenIds)
            {
                var task = current.Tasks.FirstOrDefault(candidate =>
                    string.Equals(candidate.TaskId, taskId, StringComparison.Ordinal));
                AddBody($"• Step {task?.DisplayStepLabel ?? taskId} will reopen with its revised specification.", 2);
            }
        }
        var futureChangeCount = Math.Max(0, preview.AppliedChangeCount - reopenIds.Count);
        if (futureChangeCount > 0)
            AddBody($"• {futureChangeCount} pending plan definition change(s) will be applied.", 2);
        if (preview.PreservedLockedTaskCount > 0)
            AddBody($"• {preview.PreservedLockedTaskCount} unaffected completed or active step(s) will remain unchanged.", 2);

        var status = new TextBlock
        {
            Text = "The current plan remains authoritative until you approve this revision.",
            TextWrapping = TextWrapping.Wrap,
            FontSize = _transcriptFontSize - 1,
            Margin = new Thickness(0, 6, 0, 8),
        };
        status.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
        stack.Children.Add(status);

        var actions = new WrapPanel { Orientation = Orientation.Horizontal };
        var approve = TranscriptQuickReplyFactory.CreateButton(
            current.IsPaused ? "Approve Revision" : "Approve Revision & Continue",
            _transcriptFontSize);
        var revise = TranscriptQuickReplyFactory.CreateButton(
            "✏️ Revise proposal",
            _transcriptFontSize);
        System.Windows.Automation.AutomationProperties.SetName(revise, "Revise proposal");
        var keep = TranscriptQuickReplyFactory.CreateButton(
            "Keep current plan",
            _transcriptFontSize);
        actions.Children.Add(approve);
        actions.Children.Add(revise);
        actions.Children.Add(keep);
        stack.Children.Add(actions);

        var card = new Border
        {
            Child = stack,
            CornerRadius = new CornerRadius(10),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(12, 10, 12, 10),
            MaxWidth = 760,
            HorizontalAlignment = HorizontalAlignment.Left,
        };
        card.SetResourceReference(Border.BackgroundProperty, "InputSurface");
        card.SetResourceReference(Border.BorderBrushProperty, "InputBorder");
        blocks.Add(TranscriptQuickReplyFactory.CreateContainer(card));

        approve.Click += async (_, _) =>
        {
            actions.IsEnabled = false;
            status.Text = "Applying the approved revision…";
            await ApplyPendingPlanRevisionAsync(pending, status, actions);
        };
        revise.Click += (_, _) =>
        {
            new PendingPlanRevisionProposalStore(_currentWorkspace!.SquadFolderPath)
                .Delete(pending.Payload.PlanId);
            actions.Visibility = Visibility.Collapsed;
            status.Text = "This proposal was withdrawn. Describe the revised proposal in the prompt box.";
            BeginPlanRevision(current);
        };
        keep.Click += (_, _) =>
        {
            new PendingPlanRevisionProposalStore(_currentWorkspace!.SquadFolderPath)
                .Delete(pending.Payload.PlanId);
            actions.Visibility = Visibility.Collapsed;
            status.Text = "Current plan kept. No plan content changed.";
            RestoreAwaitingApprovalGateUI(pending.Payload.PlanId);
        };
        ScrollToEndIfAtBottom(CoordinatorThread);

        void AddLabel(string text)
        {
            var label = new TextBlock
            {
                Text = text,
                FontSize = _transcriptFontSize - 1,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 3),
            };
            label.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
            stack.Children.Add(label);
        }

        void AddBody(string text, double bottom)
        {
            var body = new TextBlock
            {
                Text = text,
                TextWrapping = TextWrapping.Wrap,
                FontSize = _transcriptFontSize,
                Margin = new Thickness(0, 0, 0, bottom),
            };
            body.SetResourceReference(TextBlock.ForegroundProperty, "LabelText");
            stack.Children.Add(body);
        }
    }

    private void RestorePendingPlanRevisionApprovalCards()
    {
        if (_currentWorkspace is null || _planStore is null) return;
        var proposalStore = new PendingPlanRevisionProposalStore(_currentWorkspace.SquadFolderPath);
        foreach (var pending in proposalStore.LoadAll())
        {
            if (!_renderedPlanRevisionProposalIds.Add(pending.ProposalId)) continue;
            var current = _planStore.Load(pending.Payload.PlanId);
            if (current is null ||
                !string.Equals(current.Revision, pending.Payload.BaseRevision, StringComparison.Ordinal))
            {
                proposalStore.Delete(pending.Payload.PlanId);
                AppendLine($"A saved plan revision proposal for {pending.Payload.PlanId} became stale and was discarded. The plan was not changed.");
                continue;
            }

            if (!PlanRevisionDeltaApplier.TryMaterialize(
                    current, pending.Payload, out var revisedPlan, out var reopened, out _) ||
                revisedPlan is null)
            {
                proposalStore.Delete(pending.Payload.PlanId);
                AppendLine($"A saved plan revision proposal for {pending.Payload.PlanId} was no longer valid and was discarded. The plan was not changed.");
                continue;
            }

            var preview = PlanRevisionApplier.Apply(
                current,
                revisedPlan,
                pending.Payload.BaseRevision,
                pending.CreatedAt,
                reopened);
            if (preview.Outcome != PlanRevisionApplyOutcome.Applied)
            {
                proposalStore.Delete(pending.Payload.PlanId);
                AppendLine($"A saved plan revision proposal for {pending.Payload.PlanId} was no longer valid and was discarded. The plan was not changed.");
                continue;
            }
            AppendPlanRevisionApprovalCard(current, pending, preview, ownerView: null);
        }
    }

    private void TrackAcceptedPlanRevisionForActiveExecution(Plan previous, Plan updated)
    {
        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (execution is null ||
            !string.Equals(execution.DecomposeGroupId, updated.PlanId, StringComparison.Ordinal) ||
            string.Equals(execution.DecomposeRevision, updated.Revision, StringComparison.Ordinal))
            return;

        _conversationManager.UpdateActiveLoopExecutionState(
            execution with { PendingDecomposeRevision = updated.Revision });

        var hasInFlightWork = previous.Tasks.Any(task => PlanTaskStatus.IsWorkInProgress(task.Status)) ||
                              execution.ActiveValidationId is not null ||
                              execution.ActiveVerificationTaskId is not null ||
                              execution.PendingTaskVerification is not null;
        if (!hasInFlightWork)
            PromotePendingPlanRevisionAtBoundary(updated.PlanId);
    }

    private void PromotePendingPlanRevisionAtBoundary(string planId)
    {
        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (execution?.PendingDecomposeRevision is not { Length: > 0 } revision ||
            !string.Equals(execution.DecomposeGroupId, planId, StringComparison.Ordinal) ||
            execution.ActiveValidationId is not null ||
            execution.ActiveVerificationTaskId is not null ||
            execution.PendingTaskVerification is not null)
            return;

        _conversationManager.UpdateActiveLoopExecutionState(execution with
        {
            DecomposeRevision = revision,
            PendingDecomposeRevision = null,
            PlanExecutionAttempt = null,
            RecoveryTaskId = null,
            RecoveryAttemptId = null,
            RepairRequestCount = 0,
            FreshAttemptCount = 0,
            TaskBaselineCommit = null,
            PendingRepairResult = null,
            PendingInboxLinkRepairError = null,
            PendingInboxDeliveryRawResponse = null,
        });
        SquadDashTrace.Write("PlanRevision",
            $"Promoted active execution plan={planId} revision={revision} at a safe task boundary.");
    }

    private bool StageValidatedDecomposeGroup(
        DecomposedTaskGroup group,
        TranscriptTurnView? ownerView,
        string? retryResponse = null,
        bool humanProofCoverageChecked = false)
    {
        if (!humanProofCoverageChecked)
            return BeginPlanHumanProofCoverageReview(group, retryResponse);

        var store = new PendingDecomposePlanStore(_currentWorkspace!.SquadFolderPath);
        PendingDecomposePlan? previousPlan;
        PendingDecomposePlan plan;
        try
        {
            previousPlan = store.Load(group.GroupId);
            var revision = PendingDecomposePlanStore.ComputeRevision(group);
            plan = previousPlan is not null &&
                   string.Equals(previousPlan.Revision, revision, StringComparison.Ordinal)
                ? previousPlan
                : store.Save(group);

            var persisted = store.Load(group.GroupId);
            if (persisted is null ||
                !string.Equals(persisted.Revision, plan.Revision, StringComparison.Ordinal))
            {
                throw new InvalidDataException(
                    "The pending plan could not be reloaded with the revision that was written.");
            }
            plan = persisted;
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidDataException)
        {
            var reason = $"Plan {group.GroupId} was validated but could not be persisted: {ex.Message}";
            RemovePlanValidationStatus();
            AppendPlanStagingFailure(reason, retryResponse, ownerView);
            SquadDashTrace.Write(TraceCategory.General, reason);
            return false;
        }

        if (previousPlan is not null && !string.Equals(previousPlan.Revision, plan.Revision, StringComparison.Ordinal))
            ArchiveDecomposePlanInboxReminder(previousPlan);
        RemovePlanValidationStatus();
        try
        {
            if (DecomposePlanInbox.RequestsInboxDelivery(group))
                SaveDecomposePlanInboxReminder(plan, explicitlyRequested: true);
            else
                AppendPendingDecomposeApproval(plan, ownerView);
        }
        catch (Exception ex)
        {
            AppendLine($"⚠ Plan {group.GroupId} was persisted as revision {plan.Revision}, but SquadDash " +
                       $"could not display its approval controls: {ex.Message}");
            SquadDashTrace.Write(TraceCategory.General,
                $"Plan {group.GroupId} persisted but presentation failed: {ex}");
            return false;
        }

        SquadDashTrace.Write(TraceCategory.General,
            $"Plan {group.GroupId} staged and verified revision={plan.Revision} " +
            $"delivery={(DecomposePlanInbox.RequestsInboxDelivery(group) ? "inbox" : "transcript")}.");
        return true;
    }

    private void AppendPlanStagingFailure(
        string reason,
        string? retryResponse,
        TranscriptTurnView? ownerView)
    {
        RemovePlanValidationStatus();
        var visibleOwner = ownerView is { SuppressTranscript: false } ? ownerView : null;
        var blocks = visibleOwner?.NarrativeSection.Blocks ?? CoordinatorThread.Document.Blocks;
        var durableNotice = "Plan was not staged. " + reason;
        var message = CreateTranscriptParagraph(bottomMargin: 6);
        var warning = new Run("⚠ Plan was not staged. ") { FontWeight = FontWeights.SemiBold };
        warning.SetResourceReference(TextElement.ForegroundProperty, "PlanPreflightWarningText");
        message.Inlines.Add(warning);
        message.Inlines.Add(new Run(reason));
        blocks.Add(message);
        if (visibleOwner is null)
            _conversationManager.AppendDurableCoordinatorHostNotice(durableNotice);
        else
        {
            visibleOwner.HostNotices.Add(new TranscriptHostNoticeEntry(
                AllocateNarrativeSequence(visibleOwner),
                durableNotice,
                DateTimeOffset.Now));
            _conversationManager.SaveTranscriptTurnToConversation(
                visibleOwner,
                DateTimeOffset.UtcNow,
                "plan-staging-failure");
        }

        if (string.IsNullOrWhiteSpace(retryResponse))
            return;

        var panel = new WrapPanel { Orientation = Orientation.Horizontal };
        var button = TranscriptQuickReplyFactory.CreateButton(
            "Retry staging",
            _transcriptFontSize,
            toolTip: ToolTipHelper.MakeThemedToolTip(
                "Retry the same submitted payload without asking the agent to rewrite the plan."));
        panel.Children.Add(button);
        var container = new BlockUIContainer(panel) { Margin = new Thickness(0, 0, 0, 10) };
        blocks.Add(container);
        button.Click += (_, _) =>
        {
            if (_isPromptRunning)
            {
                AppendLine("Wait for the current prompt to finish before retrying plan staging.");
                return;
            }

            panel.IsEnabled = false;
            if (blocks.Contains(container))
                blocks.Remove(container);
            TryStartDecomposeGroupFromResponse(retryResponse, visibleOwner);
        };
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private sealed record ArchivedPlanRevisionRecoveryTag(string GroupId, string Revision);

    private void ShowArchivedPlanRevisionRecovery(
        DecomposedTaskGroup group,
        TranscriptTurnView? ownerView)
    {
        var revision = PendingDecomposePlanStore.ComputeRevision(group);
        var blocks = ownerView?.NarrativeSection.Blocks ?? CoordinatorThread.Document.Blocks;
        foreach (var existing in blocks.OfType<BlockUIContainer>().Where(block =>
                     block.Tag is ArchivedPlanRevisionRecoveryTag tag &&
                     string.Equals(tag.GroupId, group.GroupId, StringComparison.Ordinal)).ToArray())
            blocks.Remove(existing);

        var stack = new StackPanel();
        var title = new TextBlock
        {
            Text = "Plan revision paused",
            FontWeight = FontWeights.SemiBold,
            FontSize = _transcriptFontSize,
        };
        title.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        stack.Children.Add(title);

        var status = new TextBlock
        {
            Text = $"SquadDash received revision {revision} for “{group.GroupTitle}”, but the existing plan " +
                   "was archived while the request was running. The revision was not applied.",
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 4, 0, 8),
            FontSize = _transcriptFontSize,
        };
        status.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        stack.Children.Add(status);

        var buttons = new WrapPanel { Orientation = Orientation.Horizontal };
        var restoreButton = TranscriptQuickReplyFactory.CreateButton(
            "Restore plan and apply revision",
            _transcriptFontSize);
        var keepArchivedButton = TranscriptQuickReplyFactory.CreateButton(
            "Keep archived",
            _transcriptFontSize);
        buttons.Children.Add(restoreButton);
        buttons.Children.Add(keepArchivedButton);
        stack.Children.Add(buttons);

        var card = new Border
        {
            Child = stack,
            CornerRadius = new CornerRadius(10),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(12, 10, 12, 10),
            MaxWidth = 760,
            HorizontalAlignment = HorizontalAlignment.Left,
        };
        card.SetResourceReference(Border.BackgroundProperty, "PlanPreflightWarningSurface");
        card.SetResourceReference(Border.BorderBrushProperty, "PlanPreflightWarningBorder");
        var container = TranscriptQuickReplyFactory.CreateContainer(
            card,
            new ArchivedPlanRevisionRecoveryTag(group.GroupId, revision));
        blocks.Add(container);

        restoreButton.Click += (_, _) =>
        {
            buttons.IsEnabled = false;
            try
            {
                if (_currentWorkspace is null)
                {
                    status.Text = "Open the original workspace before restoring this plan revision.";
                    buttons.IsEnabled = true;
                    return;
                }

                _planStore ??= new PlanStore(_currentWorkspace.SquadFolderPath);
                var archived = _planStore.Load(group.GroupId);
                if (archived is null)
                {
                    status.Text = "The archived plan no longer exists. The revision was not applied.";
                    buttons.IsEnabled = true;
                    return;
                }

                var restored = PlanStoreUpdater.ApplyRestoredForRevision(archived);
                if (!TryPublishPlanProgress(restored, out var restoreError))
                {
                    status.Text = "SquadDash could not restore the plan: " + restoreError;
                    buttons.IsEnabled = true;
                    return;
                }

                StageValidatedDecomposeGroup(group, ownerView: null);
                if (blocks.Contains(container)) blocks.Remove(container);
                AppendLine($"✅ Restored plan {group.GroupId} and staged revision {revision} for approval.");
            }
            catch (Exception ex)
            {
                buttons.IsEnabled = true;
                status.Text = "SquadDash could not restore and stage the revision. Expand the error details in the transcript.";
                HandleUiCallbackException("Restore archived plan revision", ex);
            }
        };

        keepArchivedButton.Click += (_, _) =>
        {
            if (blocks.Contains(container)) blocks.Remove(container);
            AppendLine($"Kept plan {group.GroupId} archived; revision {revision} was not applied.");
        };

        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private bool TryValidateDecomposeRevisionAgainstWorkspace(
        DecomposedTaskGroup proposal,
        out bool isRevision,
        out string? error)
    {
        isRevision = false;
        error = null;
        if (_currentWorkspace is null)
        {
            error = "No workspace is open.";
            return false;
        }

        var hasReplacementTasks = proposal.Tasks.Any(task =>
            !string.IsNullOrWhiteSpace(task.ParentTaskId));
        var durablePlan = _planStore?.Load(proposal.GroupId);
        isRevision = durablePlan is not null;
        if (!hasReplacementTasks && durablePlan is null)
            return true;

        if (durablePlan is null)
        {
            error = $"The existing approved plan '{proposal.GroupId}' was not found, so its revision cannot be staged.";
            return false;
        }

        var existingGroup = PendingDecomposePlanAdapter.FromPlan(durablePlan).Group;
        var replaceableIds = durablePlan.Tasks
            .Where(task => task.Status is not (PlanTaskStatus.Complete or PlanTaskStatus.Superseded))
            .Select(task => task.TaskId)
            .ToHashSet(StringComparer.Ordinal);
        var completedIds = durablePlan.Tasks
            .Where(task => task.Status == PlanTaskStatus.Complete)
            .Select(task => task.TaskId)
            .ToHashSet(StringComparer.Ordinal);
        var editablePendingIds = durablePlan.Tasks
            .Where(task => task.Status == PlanTaskStatus.Pending)
            .Select(task => task.TaskId)
            .ToHashSet(StringComparer.Ordinal);
        return DecomposePlanRevision.TryValidateAgainstPersisted(
            proposal,
            existingGroup,
            replaceableIds,
            completedIds,
            editablePendingIds,
            out error);
    }

    private void QueueDecomposeRepair(
        IReadOnlyList<string> validationDiagnostics,
        string? rejectedCandidate)
    {
        var trackedDiagnostics = TaskPlanRepairRetryPolicy.NormalizeForTracking(validationDiagnostics);
        var candidateHash = string.IsNullOrWhiteSpace(rejectedCandidate)
            ? null
            : PlanHumanProofCoverageReview.ComputeCandidateHash(rejectedCandidate);
        var decision = TaskPlanRepairRetryPolicy.Evaluate(
            _decomposeRepairAttemptsQueued,
            _decomposeRepairDiagnostics,
            trackedDiagnostics,
            _decomposeRepairCandidateHash,
            candidateHash);
        var validationError = trackedDiagnostics.Count == 0
            ? null
            : string.Join(Environment.NewLine + "- ", trackedDiagnostics);
        if (!decision.ShouldRetry)
        {
            StopDecomposeRepair(
                $"The automatic task-plan repair was still invalid and SquadDash stopped retrying because {decision.Reason}." +
                (string.IsNullOrWhiteSpace(validationError) ? string.Empty : $" Reason: {validationError}"));
            return;
        }

        _decomposeRepairPending = true;
        _decomposeRepairAttemptsQueued++;
        _decomposeRepairDiagnostics = trackedDiagnostics;
        _decomposeRepairCandidateHash = candidateHash;
        UpdatePlanValidationStatus(
            _decomposeRepairAttemptsQueued == 1
                ? "SquadDash found plan-contract issues and asked AI to correct them automatically…"
                : "The first repair improved validation. SquadDash is trying one final correction…");
        var prompt = TaskPlanRepairPromptBuilder.Build(
            rejectedCandidate,
            validationError,
            DecomposePlanningInstructions.LoadSpecification());
        _promptQueue.EnqueueAtFront(
            prompt,
            _promptQueueCoordinator.NextSequenceNumber(),
            sourceTag: "decompose-repair",
            isSystemInjected: true);
        SyncQueuePanel();
        SyncSendButton();
    }

    private void StopDecomposeRepair(string reason)
    {
        ResetDecomposeRepairState();
        // Re-submitting an unchanged, deterministically invalid candidate cannot succeed.
        // Keep "Retry staging" for transport/storage failures where retrying the same bytes
        // can help, but do not offer it after validation has exhausted plan repairs.
        AppendPlanStagingFailure(reason, retryResponse: null, ownerView: null);
        RestoreInterruptedPlanRecoverySurfaces();
    }

    private void ResetDecomposeRepairState()
    {
        _decomposeRepairPending = false;
        _decomposeRepairAttemptsQueued = 0;
        _decomposeRepairDiagnostics = [];
        _decomposeRepairCandidateHash = null;
        RemovePlanValidationStatus();
    }

    private void AppendPendingDecomposeApproval(
        PendingDecomposePlan plan,
        TranscriptTurnView? ownerView = null,
        bool includeActions = true)
    {
        var group = plan.Group;
        var blocks = ownerView?.NarrativeSection.Blocks ?? CoordinatorThread.Document.Blocks;
        foreach (var existing in blocks.OfType<Block>().Where(block =>
                     (block.Tag is PendingDecomposePlanLinkTag linkTag &&
                      string.Equals(linkTag.GroupId, group.GroupId, StringComparison.Ordinal)) ||
                     (block.Tag is PendingDecomposeApprovalTag approvalTag &&
                      string.Equals(approvalTag.GroupId, group.GroupId, StringComparison.Ordinal))).ToArray())
        {
            blocks.Remove(existing);
        }
        var planLink = CreatePendingDecomposePlanLinkParagraph(plan);

        if (!includeActions)
        {
            blocks.Add(planLink);
            return;
        }

        var activeBranch = _currentWorkspace is null ? null : ReadGitBranch(_currentWorkspace.FolderPath);
        var panel = new WrapPanel { Orientation = Orientation.Horizontal };
        foreach (var action in DecomposePlanInbox.BuildActionDefinitions(plan, activeBranch))
            AddButton(action);
        var actionsContainer = TranscriptQuickReplyFactory.CreateContainer(
            panel,
            new PendingDecomposeApprovalTag(group.GroupId, plan.Revision));
        if (ownerView is null)
        {
            TranscriptQuickReplyFactory.ReplacePendingDecomposeApprovalSurface(
                CoordinatorThread.Document.Blocks,
                group.GroupId,
                planLink,
                actionsContainer);
        }
        else
        {
            blocks.Add(planLink);
            blocks.Add(actionsContainer);
        }
        ScrollToEndIfAtBottom(CoordinatorThread);

        void AddButton(DecomposePlanActionDefinition action)
        {
            var button = TranscriptQuickReplyFactory.CreateButton(
                action.Label,
                _transcriptFontSize,
                toolTip: ToolTipHelper.MakeThemedToolTip(action.Hint));
            button.Click += async (_, _) =>
            {
                if (_isPromptRunning &&
                    !DecomposePlanActionDispatchPolicy.CanApplyWhilePromptRunning(action.Action))
                {
                    AppendLine("Wait for the current prompt to finish before applying the task plan.");
                    return;
                }
                panel.IsEnabled = false;
                panel.Visibility = Visibility.Collapsed;
                try
                {
                    if (!await ApplyDecomposeDecisionAsync(plan, action.Action, action.Branch))
                    {
                        panel.IsEnabled = true;
                        panel.Visibility = Visibility.Visible;
                    }
                }
                catch (PlanPreflightBlockedException blocked)
                {
                    ShowTranscriptPlanPreflightRecovery(
                        plan, action.Action, action.Branch, blocked, panel, blocks);
                }
                catch (Exception ex)
                {
                    panel.IsEnabled = true;
                    panel.Visibility = Visibility.Visible;
                    HandleUiCallbackException("Decompose plan", ex);
                }
            };
            panel.Children.Add(button);
        }
    }

    private void RemovePendingDecomposeApprovalButtons()
    {
        TranscriptQuickReplyFactory.RemovePendingDecomposeApprovalContainers(
            CoordinatorThread.Document.Blocks,
            tag =>
            {
                if (_currentWorkspace is null)
                    return null;
                var plan = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath)
                    .Load(tag.GroupId);
                return plan is not null && string.Equals(plan.Revision, tag.Revision, StringComparison.Ordinal)
                    ? CreatePendingDecomposePlanLinkParagraph(plan)
                    : null;
            });
    }

    private void RestorePendingDecomposeApprovalSurfaces(bool promoteUnaddressedToInbox = false)
    {
        if (_currentWorkspace is null)
            return;

        var store = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath);
        foreach (var plan in store.LoadAll().OrderBy(candidate => candidate.CreatedAt))
        {
            if (IsDurablePlanArchived(plan.Group.GroupId))
            {
                store.Archive(plan.Group.GroupId);
                continue;
            }

            // Explicit Inbox delivery already has the user-requested durable surface.
            if (DecomposePlanInbox.RequestsInboxDelivery(plan.Group))
            {
                continue;
            }


            // An automatic "conversation moved on" reminder replaces the large action card,
            // but restart hydration must leave a compact, linked receipt in the transcript.
            var reminderId = DecomposePlanInbox.BuildMessageId(plan);
            var reminder = _inboxStore?.GetById(reminderId);
            if (reminder is not null &&
                DecomposePlanInbox.TryGetPlanAttachment(reminder, plan, out _))
            {
                AppendPlanMovedToInboxBanner(plan, reminder);
                if (DecomposePlanInbox.IsUnreadAutomaticReminder(plan, reminder))
                    SchedulePendingPlanInboxCallout(reminder.Id);
                continue;
            }
            if (_inboxStore?.Exists(reminderId, includeArchive: true) == true)
                continue;

            if (promoteUnaddressedToInbox && _inboxStore is not null &&
                DecomposePlanInbox.ShouldCreateAutomaticReminderOnWorkspaceHydration(
                    plan,
                    reminderExistsIncludingArchive: false))
            {
                SaveDecomposePlanInboxReminder(plan, explicitlyRequested: false);
                continue;
            }

            AppendPendingDecomposeApproval(plan);
            SquadDashTrace.Write(
                TraceCategory.UI,
                $"Restored pending plan approval surface group={plan.Group.GroupId} revision={plan.Revision} after transcript hydration.");
        }
    }

    private void AppendPlanMovedToInboxBanner(PendingDecomposePlan plan, InboxMessage message)
    {
        var blocks = CoordinatorThread.Document.Blocks;
        if (!DecomposePlanInbox.TryGetPlanAttachment(message, plan, out var attachment) || attachment is null)
            return;

        var paragraph = CreateTranscriptParagraph(bottomMargin: 6);
        paragraph.Tag = new PendingDecomposeInboxBannerTag(plan.Group.GroupId, plan.Revision);

        var prefix = new Run("✓ Plan moved to ");
        prefix.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        paragraph.Inlines.Add(prefix);

        var inboxLink = new Hyperlink(new Run("Inbox")) { Cursor = Cursors.Hand };
        inboxLink.SetResourceReference(TextElement.ForegroundProperty, "ActionLinkText");
        inboxLink.Click += (_, _) =>
        {
            _inboxStore?.MarkRead(message.Id);
            _inboxPanel?.Refresh(_inboxStore?.LoadAll() ?? []);
            ClearPendingPlanInboxCallout(message.Id);
            OpenOrFocusInboxMessage(message.Id);
        };
        paragraph.Inlines.Add(inboxLink);

        var separator = new Run(".  ");
        separator.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        paragraph.Inlines.Add(separator);

        var planLink = new Hyperlink(new Run("View plan")) { Cursor = Cursors.Hand };
        planLink.SetResourceReference(TextElement.ForegroundProperty, "ActionLinkText");
        planLink.Click += (_, _) => OpenDecomposePlanAttachment(attachment);
        paragraph.Inlines.Add(planLink);

        var replacedInPlace = TranscriptQuickReplyFactory.ReplacePendingDecomposeApprovalSurfaceWithInboxBanner(
            blocks,
            plan.Group.GroupId,
            paragraph);
        if (!replacedInPlace)
        {
            // The Inbox already owns the durable reminder. If the original tagged transcript
            // receipt did not survive hydration, appending a replacement here would invent a
            // new position in the conversation and make an old plan look newly moved. Leave the
            // transcript unchanged instead; live and intact restart paths still replace the
            // original receipt beside the turn that produced the plan.
            SquadDashTrace.Write(
                TraceCategory.UI,
                $"Pending-plan Inbox banner skipped because no historical transcript anchor survived group={plan.Group.GroupId} revision={plan.Revision}.");
        }
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private Paragraph CreatePendingDecomposePlanLinkParagraph(PendingDecomposePlan plan)
    {
        var presentation = PlanProposalTranscriptPolicy.BuildValidatedSummary(plan);
        var intro = CreateTranscriptParagraph(bottomMargin: 4);
        intro.Tag = new PendingDecomposePlanLinkTag(plan.Group.GroupId, plan.Revision);
        var receipt = new Run(presentation.Heading)
        {
            FontWeight = FontWeights.SemiBold,
        };
        receipt.SetResourceReference(TextElement.ForegroundProperty, "TaskSuccessText");
        intro.Inlines.Add(receipt);
        intro.Inlines.Add(new LineBreak());
        intro.Inlines.Add(new Run(presentation.Summary));
        intro.Inlines.Add(new LineBreak());
        var counts = new Run(presentation.Counts);
        counts.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        intro.Inlines.Add(counts);
        intro.Inlines.Add(new LineBreak());
        intro.Inlines.Add(new Run("If this plan is executed in a new branch, that branch will be:"));
        intro.Inlines.Add(new LineBreak());
        intro.Inlines.Add(new Run(presentation.Branch) { FontWeight = FontWeights.SemiBold });
        intro.Inlines.Add(new LineBreak());
        var revision = new Run(presentation.Identity);
        revision.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        intro.Inlines.Add(revision);
        intro.Inlines.Add(new LineBreak());
        var link = new Hyperlink(new Run("View task plan and dependencies")) { Cursor = Cursors.Hand };
        link.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
        link.Click += (_, _) => OpenDecomposePlanViewer(plan);
        intro.Inlines.Add(link);
        return intro;
    }

    private void TryApplyDecomposeDecisionFromResponse(string? rawResponse)
    {
        if (!DecomposeDecisionParser.TryParse(rawResponse, out var decision) || decision is null)
        {
            if (rawResponse?.Contains("DECOMPOSE_DECISION_JSON:", StringComparison.Ordinal) == true)
                AppendLine("⚠ The decomposition decision was malformed and was ignored; no task plan was changed or executed.");
            return;
        }
        if (_currentWorkspace is null)
            return;
        var store = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath);
        var plan = store.Load(decision.GroupId);
        if (plan is null)
        {
            SquadDashTrace.Write(TraceCategory.General, $"Decompose decision ignored: pending group '{decision.GroupId}' was not found.");
            return;
        }
        if (!string.Equals(plan.Revision, decision.Revision, StringComparison.Ordinal))
        {
            AppendLine($"⚠ Approval for {decision.GroupId} was ignored because its plan revision is stale.");
            SquadDashTrace.Write(TraceCategory.General,
                $"Decompose decision revision mismatch for '{decision.GroupId}': expected {plan.Revision}, received {decision.Revision}.");
            return;
        }
        Dispatcher.InvokeAsync(
            async () => await ApplyDecomposeDecisionSafelyAsync(plan, decision.Action, decision.Branch),
            System.Windows.Threading.DispatcherPriority.Background);
    }

    private async Task ApplyDecomposeRecoveryFromResponseSafelyAsync(string? rawResponse)
    {
        DecomposeRecoveryDecisionParser.TryParse(rawResponse, out var pendingDecision);
        if (pendingDecision is not null &&
            pendingDecision.Action is "continue-working" or "resume-verification")
        {
            var existing = _conversationManager.ConversationState.PendingPlanContinuation;
            if (existing is null ||
                !string.Equals(existing.PlanId, pendingDecision.GroupId, StringComparison.Ordinal) ||
                !string.Equals(existing.Revision, pendingDecision.Revision, StringComparison.Ordinal) ||
                !string.Equals(existing.Action, pendingDecision.Action, StringComparison.Ordinal))
            {
                _pendingPlanContinuationClaimedAt = null;
                _pendingPlanContinuationDispatchAttempts = 0;
                _conversationManager.UpdatePendingPlanContinuationState(
                    new PendingPlanContinuationState(
                        pendingDecision.GroupId,
                        pendingDecision.Revision,
                        pendingDecision.Action,
                        DateTimeOffset.UtcNow));
            }
        }

        if (DecomposeRecoveryDispatchPolicy.ShouldDefer(_isPromptRunning, _loopController.IsRunning) &&
            pendingDecision is not null)
        {
            _pendingDecomposeRecoveryResponse = rawResponse;
            SquadDashTrace.Write(
                "PromptHealth",
                $"Deferred decompose recovery until coordinator and loop are idle plan={pendingDecision.GroupId} action={pendingDecision.Action} promptRunning={_isPromptRunning} loopRunning={_loopController.IsRunning}.");
            return;
        }

        try { await TryApplyDecomposeRecoveryFromResponseAsync(rawResponse); }
        catch (Exception ex) { HandleUiCallbackException("Decompose recovery", ex); }
    }

    private void TryDispatchPendingDecomposeRecoveryResponse()
    {
        if (_pendingDecomposeRecoveryResponse is not { } rawResponse ||
            _isPromptRunning ||
            _loopController.IsRunning ||
            _pendingDecomposeRecoveryDispatchScheduled)
            return;

        _pendingDecomposeRecoveryDispatchScheduled = true;
        _pendingDecomposeRecoveryDispatchScheduledAt = DateTimeOffset.UtcNow;
        var dispatchGeneration = ++_pendingDecomposeRecoveryDispatchGeneration;
        Dispatcher.InvokeAsync(
            async () =>
            {
                if (dispatchGeneration != _pendingDecomposeRecoveryDispatchGeneration)
                    return;
                _pendingDecomposeRecoveryResponse = null;
                _pendingDecomposeRecoveryDispatchScheduled = false;
                _pendingDecomposeRecoveryDispatchScheduledAt = null;
                _pendingDecomposeRecoveryDispatchInFlight = true;
                _pendingPlanContinuationClaimedAt = DateTimeOffset.UtcNow;
                _pendingPlanContinuationDispatchAttempts++;
                try
                {
                    await ApplyDecomposeRecoveryFromResponseSafelyAsync(rawResponse);
                }
                finally
                {
                    _pendingDecomposeRecoveryDispatchInFlight = false;
                }
            },
            System.Windows.Threading.DispatcherPriority.Background);
    }

    private void EnsurePendingPlanContinuationDispatched()
    {
        if (_pendingDecomposeRecoveryDispatchInFlight)
            return;

        if (_pendingPlanContinuationClaimedAt is { } claimedAt &&
            _conversationManager.ConversationState.PendingPlanContinuation is { } claimed &&
            _planStore?.Load(claimed.PlanId) is { } claimedPlan)
        {
            var runnerOwnsPlan = _loopController.IsRunning &&
                                 string.Equals(_activeDecomposeGroupId, claimed.PlanId, StringComparison.Ordinal);
            var mayRetryLostClaim = !runnerOwnsPlan &&
                                    !_isPromptRunning &&
                                    claimedPlan.LifecycleStatus == PlanLifecycleStatus.Interrupted &&
                                    DateTimeOffset.UtcNow - claimedAt >= TimeSpan.FromSeconds(5) &&
                                    _pendingPlanContinuationDispatchAttempts < 3;
            if (!mayRetryLostClaim)
                return;

            _pendingPlanContinuationClaimedAt = null;
            SquadDashTrace.Write(
                "PlanRecovery",
                $"Retrying unconfirmed durable plan continuation plan={claimed.PlanId} attempt={_pendingPlanContinuationDispatchAttempts + 1}.");
        }

        if (_pendingDecomposeRecoveryDispatchScheduled &&
            _pendingDecomposeRecoveryDispatchScheduledAt is { } scheduledAt &&
            DateTimeOffset.UtcNow - scheduledAt >= TimeSpan.FromSeconds(5))
        {
            _pendingDecomposeRecoveryDispatchScheduled = false;
            _pendingDecomposeRecoveryDispatchScheduledAt = null;
            SquadDashTrace.Write(
                "PlanRecovery",
                "Reclaiming a deferred plan-continuation dispatch that did not reach the UI dispatcher.");
        }

        if (_pendingDecomposeRecoveryResponse is null &&
            _conversationManager.ConversationState.PendingPlanContinuation is { } pending)
            _pendingDecomposeRecoveryResponse = pending.BuildProtocolResponse();

        TryDispatchPendingDecomposeRecoveryResponse();
    }

    private void RestorePendingPlanContinuation()
    {
        var pending = _conversationManager.ConversationState.PendingPlanContinuation;
        if (pending is null || _planStore is null)
            return;

        var plan = _planStore.Load(pending.PlanId);
        if (plan is null ||
            PlanLifecycleStatus.IsTerminal(plan.LifecycleStatus) ||
            !string.Equals(plan.Revision, pending.Revision, StringComparison.Ordinal))
        {
            _conversationManager.UpdatePendingPlanContinuationState(null);
            return;
        }

        _pendingDecomposeRecoveryResponse = pending.BuildProtocolResponse();
        _pendingPlanContinuationClaimedAt = null;
        _pendingPlanContinuationDispatchAttempts = 0;
        SquadDashTrace.Write(
            "PlanRecovery",
            $"Restored durable plan continuation plan={pending.PlanId} action={pending.Action}.");
        TryDispatchPendingDecomposeRecoveryResponse();
    }

    private bool TryRouteInterruptedStepResultToRecovery(string? rawResponse)
    {
        if (!DecomposeStepResultParser.TryParse(rawResponse, out var result, out _) || result is null)
            return false;

        var plan = _planStore?.Load(result.GroupId);
        if (!InterruptedStepResultRecoveryPolicy.CanRouteToCommitReview(plan, result))
            return false;

        ScheduleDecomposeSystemEntry(
            $"Received a completed result for interrupted task {result.TaskId}. " +
            "Opening host-validated commit review before changing plan state.");
        Dispatcher.InvokeAsync(
            async () =>
            {
                try
                {
                    var latest = _planStore?.Load(result.GroupId);
                    if (!InterruptedStepResultRecoveryPolicy.CanRouteToCommitReview(latest, result))
                        return;
                    await AcceptInterruptedStepAfterReviewAsync(latest!);
                }
                catch (Exception ex)
                {
                    HandleUiCallbackException("Interrupted step-result recovery", ex);
                }
            },
            System.Windows.Threading.DispatcherPriority.Background);
        return true;
    }

    private async Task<bool> TryApplyDecomposeRecoveryFromResponseAsync(string? rawResponse)
    {
        if (!DecomposeRecoveryDecisionParser.TryParse(rawResponse, out var decision) || decision is null)
            return false;
        if (_currentWorkspace is null) return false;

        var durablePlan = _planStore?.Load(decision.GroupId);
        if (durablePlan is null)
        {
            ScheduleDecomposeSystemEntry($"Recovery ignored: durable plan {decision.GroupId} is no longer available.");
            return false;
        }
        var revision = durablePlan.Revision;
        if (!string.Equals(revision, decision.Revision, StringComparison.Ordinal))
        {
            ScheduleDecomposeSystemEntry($"Recovery ignored: plan {decision.GroupId} has changed since that response.");
            return false;
        }

        if (decision.Action == "continue-working" &&
            (durablePlan.LifecycleStatus is PlanLifecycleStatus.Approved or
                 PlanLifecycleStatus.WaitingForCleanWorktree ||
             PlanRecoveryResumePolicy.IsSafelyResumable(durablePlan)))
        {
            if (!TrySetPlanPauseState(durablePlan, pause: false, out var resumable, out var resumeError))
            {
                ReportPlanActionIssue(
                    durablePlan.PlanId,
                    "Plan still paused",
                    resumeError ?? "SquadDash could not save the request to resume this plan.");
                return true;
            }
            ClearPlanActionIssue(durablePlan.PlanId);
            PrepareForHostRecoveryAction();
            ScheduleDecomposeSystemEntry(
                $"Resume accepted for {resumable.Title}. SquadDash is checking its branch and worktree before continuing.");
            await StartOrResumeDurablePlanAsync(resumable);
            return true;
        }

        var recoveryTaskId = durablePlan.InterruptionData?.InterruptedTaskId
            ?? durablePlan.Tasks.FirstOrDefault(task =>
                task.Status is PlanTaskStatus.Failed or PlanTaskStatus.Partial or
                    PlanTaskStatus.HumanReviewRequired)?.TaskId;
        if (recoveryTaskId is null)
        {
            ScheduleDecomposeSystemEntry($"Recovery ignored: plan {decision.GroupId} does not have a failed or partial step.");
            return false;
        }

        var plan = PendingDecomposePlanAdapter.FromPlan(durablePlan);
        if (decision.Action is "resume-verification" or "assess-and-continue")
        {
            await AssessPlanRecoveryAsync(plan, recoveryTaskId);
            return true;
        }
        if (decision.Action == "assess-current-work")
        {
            await AssessPlanRecoveryAsync(plan, recoveryTaskId, advisoryOnly: true);
            return true;
        }
        if (decision.Action is "accept-step-complete" or "review-completed-work")
        {
            return durablePlan?.LifecycleStatus == PlanLifecycleStatus.Interrupted &&
                   await AcceptInterruptedStepAfterReviewAsync(durablePlan);
        }
        if (decision.Action == "replan-failed-task")
        {
            QueueDecomposeReplan(plan, recoveryTaskId);
            return true;
        }
        if (decision.Action == "request-corrections")
        {
            await QueuePlanRecoveryCorrectionAsync(plan, recoveryTaskId);
            return true;
        }
        if (decision.Action is "continue-working" or "retry-as-written")
            return await RetryDecomposeTaskAsync(plan, recoveryTaskId);
        return false;
    }

    private void QueueDecomposeReplan(
        PendingDecomposePlan plan,
        string taskId,
        string? repositoryContext = null)
    {
        var failedTask = plan.Group.Tasks.FirstOrDefault(task =>
            string.Equals(task.Id, taskId, StringComparison.Ordinal));
        if (failedTask is null) return;

        var durablePlan = _planStore?.Load(plan.Group.GroupId);
        var authoritativeContext =
            $"Plan ID: {plan.Group.GroupId}\n" +
            $"Base revision: {plan.Revision}\n" +
            $"Blocked task: {taskId}\n\n" +
            "Revise only the remaining plan. Preserve completed work and the authoritative plan identity. " +
            "Replace or decompose the blocked task with dependency-aware work based on the user's requested changes. " +
            "Do not execute implementation in this turn. Use the plan-revision protocol when it is available.\n\n" +
            (string.IsNullOrWhiteSpace(repositoryContext)
                ? string.Empty
                : "Repository context:\n" + repositoryContext.Trim() + "\n\n") +
            "Blocked task JSON:\n" + System.Text.Json.JsonSerializer.Serialize(failedTask) + "\n\n" +
            DecomposePlanningInstructions.LoadSpecification();
        var attachments = new List<FollowUpAttachment>();
        if (durablePlan is not null)
        {
            attachments.Add(new FollowUpAttachment(
                CommitSha: string.Empty,
                Description: $"Plan: {durablePlan.Title}",
                OriginalPrompt: null,
                ContentBlock: PlanRevisionPromptContextParser.BuildAttachment(durablePlan),
                FileReferencePath: $".squad/plans/{durablePlan.PlanId}.json",
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This plan attachment anchors the revision to the correct plan and revision. Remove it anyway?"));
        }
        else
        {
            attachments.Add(new FollowUpAttachment(
                CommitSha: string.Empty,
                Description: $"Plan: {plan.Group.GroupTitle}",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock(
                    "plan",
                    plan.Group.GroupTitle,
                    System.Text.Json.JsonSerializer.Serialize(plan.Group)),
                FileReferencePath: $".squad/plans/{plan.Group.GroupId}.json",
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This plan attachment anchors the revision to the correct plan. Remove it anyway?"));
        }
        attachments.Add(new FollowUpAttachment(
            CommitSha: string.Empty,
            Description: "Required replanning context",
            OriginalPrompt: null,
            ContentBlock: BuildTypedAttachmentBlock(
                "plan-continuation-context",
                "Required replanning context",
                authoritativeContext),
            RequiresRemovalConfirmation: true,
            RemovalWarning: "This context preserves the blocked step, repository state, and planning rules needed for a safe continuation. Remove it anyway?"));

        QueueEditablePlanPrompt(
            "Revise the remaining plan based on the requested changes below.\r\n\r\n" +
            "What should be different?\r\n\r\n" +
            "[Describe the change you want]\r\n",
            "[Describe the change you want]",
            "Revise remaining plan",
            "decompose-replan-draft",
            attachments);
    }

    private string QueueEditablePlanPrompt(
        string text,
        string selectedPlaceholder,
        string displayLabel,
        string sourceTag,
        IReadOnlyList<FollowUpAttachment> attachments)
    {
        var selectionStart = text.IndexOf(selectedPlaceholder, StringComparison.Ordinal);
        var item = new PromptQueueItem
        {
            Text = text,
            SequenceNumber = _promptQueueCoordinator.NextSequenceNumber(),
            QueueNumber = NextQueueNumber(),
            IsEditing = true,
            SourceTag = sourceTag,
            DisplayLabel = displayLabel,
            CaretIndex = selectionStart < 0 ? text.Length : selectionStart,
            SelectionStart = selectionStart < 0 ? text.Length : selectionStart,
            SelectionLength = selectionStart < 0 ? 0 : selectedPlaceholder.Length,
        };
        _promptQueue.EnqueueItemAtFront(item);
        _promptQueue.RenumberSequentially();
        if (attachments.Count > 0)
            _followUpAttachments[item.Id] = attachments.ToList();
        SyncQueuePanel();
        OnQueueTabClicked(item.Id);
        PromptTextBox.Focus();
        SyncSendButton();
        return item.Id;
    }

    private void QueueAddressUncheckedItems(
        Plan plan,
        string taskId,
        IReadOnlyList<PlanHumanReviewChecklistItem> checklistItems,
        string? activityGateId = null)
    {
        var uncheckedItems = checklistItems.Where(item => !item.IsChecked).ToArray();
        if (uncheckedItems.Length == 0)
            return;

        activityGateId ??= uncheckedItems
            .Select(item => item.GateId)
            .FirstOrDefault(gateId => plan.ApprovalGates.Any(gate =>
                string.Equals(gate.GateId, gateId, StringComparison.Ordinal)));
        var activityGate = plan.ApprovalGates.FirstOrDefault(gate =>
            string.Equals(gate.GateId, activityGateId, StringComparison.Ordinal));
        var approvalToken = _planApprovalRuntime?.Actions.GetCurrentToken(plan.PlanId);

        var task = plan.Tasks.FirstOrDefault(candidate =>
            string.Equals(candidate.TaskId, taskId, StringComparison.Ordinal));
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            task?.DisplayStepLabel,
            task?.Title ?? taskId);
        var checklistText = string.Join("\n", uncheckedItems.Select(item => $"- {item.Text}"));
        var context =
            $"Plan ID: {plan.PlanId}\n" +
            $"Revision: {plan.Revision}\n" +
            $"Task ID: {taskId}\n" +
            $"Candidate commit: {uncheckedItems[0].CandidateCommit}\n\n" +
            "The user is responding at an existing human-review boundary. Address only the requested " +
            "unchecked verification items and keep the plan paused. The response may be discussion, a direct " +
            "correction, plan rework, or a bounded amendment; report the chosen outcome through the correlated " +
            "PLAN_REVIEW_RESPONSE_JSON contract supplied in the prompt.\n\nUnchecked verification items:\n" + checklistText +
            (activityGate is not null && approvalToken is not null
                ? "\n\n" + PlanReviewResponseParser.BuildInstruction(
                    plan, activityGate, approvalToken, taskId)
                : string.Empty);
        var attachments = new List<FollowUpAttachment>
        {
            new(
                CommitSha: string.Empty,
                Description: $"Plan: {plan.Title}",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock("plan", plan.Title, BuildPlanContentBody(plan)),
                FileReferencePath: $".squad/plans/{plan.PlanId}.json",
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This plan attachment anchors the correction to the correct plan and revision. Remove it anyway?"),
            new(
                CommitSha: string.Empty,
                Description: "Required unchecked-item context",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock(
                    "plan-review-context",
                    "Required unchecked-item context",
                    context),
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This attachment identifies the unchecked verification items and keeps the plan paused correctly. Remove it anyway?"),
        };
        var queueItemId = QueueEditablePlanPrompt(
            $"Address the unchecked verification items for {stepLabel}.\r\n\r\n" +
            "Correct the following behavior:\r\n\r\n" +
            "[Describe the correction you want]\r\n",
            "[Describe the correction you want]",
            "Address unchecked items",
            "plan-review-correction-draft",
            attachments);
        if (!string.IsNullOrWhiteSpace(activityGateId))
        {
            _pendingPlanReviewCorrectionContext = new PendingPlanReviewCorrectionContext(
                queueItemId,
                plan.PlanId,
                activityGateId,
                taskId);
            if (approvalToken is not null && approvalToken.GateIds.Contains(activityGateId, StringComparer.Ordinal))
                _pendingGateResponseContext = new PendingGateResponseContext(approvalToken, activityGateId);
            SyncGateChangeActivity(isPromptRunning: false);
            SyncPlanTaskCorrectionActivity(isPromptRunning: false);
        }
    }

    private async Task QueuePlanRecoveryCorrectionAsync(PendingDecomposePlan plan, string taskId)
    {
        if (IsPlanRecoveryActionBusy(plan.Group.GroupId))
            throw new InvalidOperationException(
                "Wait for the current prompt, loop, or active plan task to finish before preparing recovery work.");

        if (_pendingPlanTaskCorrectionContext is not null)
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Correct plan step",
                "A plan-step correction is already prepared or running. Submit or remove that queued correction before preparing another one.");
            return;
        }

        var durable = _planStore?.Load(plan.Group.GroupId);
        var task = durable?.Tasks.FirstOrDefault(candidate =>
            string.Equals(candidate.TaskId, taskId, StringComparison.Ordinal));
        var evidence = durable?.InterruptionData?.TaskCommitEvidence;
        if (durable is null || task is null || evidence is null ||
            durable.LifecycleStatus is not (PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked) ||
            !string.Equals(evidence.TaskId, taskId, StringComparison.Ordinal))
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Continue working on step",
                "The plan or its recorded task evidence changed. Reopen the current recovery card.");
            return;
        }

        if (_currentWorkspace is null) return;
        var existingCorrection = durable.InterruptionData?.RecoveryCorrection;
        var currentHead = (await RunGitAsync(
            _currentWorkspace.FolderPath,
            "rev-parse HEAD")).Trim();
        var correctionBaseline = existingCorrection?.BaselineCommit ?? currentHead;
        await RunGitAsync(
            _currentWorkspace.FolderPath,
            $"merge-base --is-ancestor \"{evidence.Commit}\" \"{correctionBaseline}\"");
        if (existingCorrection is not null)
        {
            await RunGitAsync(
                _currentWorkspace.FolderPath,
                $"merge-base --is-ancestor \"{correctionBaseline}\" \"{currentHead}\"");
        }
        else
        {
            var prepared = durable with
            {
                InterruptionData = durable.InterruptionData! with
                {
                    RecoveryCorrection = new PlanRecoveryCorrectionContext(
                        correctionBaseline,
                        DateTimeOffset.UtcNow),
                },
            };
            if (!TryPublishPlanProgress(prepared, out var saveError))
                throw new InvalidOperationException(
                    saveError ?? "SquadDash could not preserve the correction baseline.");
            durable = prepared;
        }

        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            task.DisplayStepLabel,
            task.Title ?? task.Description);
        var context =
            $"Plan ID: {durable.PlanId}\n" +
            $"Revision: {durable.Revision}\n" +
            $"Task ID: {taskId}\n" +
            $"Recorded task commit: {evidence.Commit}\n\n" +
            $"Correction baseline: {correctionBaseline}\n\n" +
            (existingCorrection is null
                ? "The user concluded that this recorded task result needs bounded corrections. "
                : "A previously started correction was interrupted. Inspect and preserve all existing edits and commits since the correction baseline before doing more work. ") +
            "Implement only the requested correction on the current plan branch. Preserve the existing commit and accumulated work; " +
            "do not rerun the original task, continue downstream plan execution, revise the plan, or modify tasks.md. " +
            "Create one or more meaningful correction commits and run focused verification. Preserve useful commit history. End with PLAN_REVIEW_ACTIVITY_JSON " +
            "using activity manual-correction, the exact plan/revision/task identity above, and a concise summary of the correction.";
        var attachments = new List<FollowUpAttachment>
        {
            new(
                CommitSha: string.Empty,
                Description: $"Plan: {durable.Title}",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock("plan", durable.Title, BuildPlanContentBody(durable)),
                FileReferencePath: $".squad/plans/{durable.PlanId}.json",
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This plan attachment anchors the correction to the exact interrupted step. Remove it anyway?"),
            new(
                CommitSha: evidence.Commit,
                Description: $"Recorded result for {stepLabel}",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock(
                    "plan-recovery-correction",
                    $"Required correction context for {stepLabel}",
                    context),
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This context prevents completed work from being rerun and keeps the correction attached to the right step. Remove it anyway?"),
        };
        var queueItemId = QueueEditablePlanPrompt(
            (existingCorrection is null
                ? $"Continue working on {stepLabel} without repeating its completed work.\r\n\r\n"
                : $"Continue the existing repair for {stepLabel} without repeating completed work.\r\n\r\n") +
            "What is incomplete or needs correction?\r\n\r\n" +
            "[Describe the bounded correction]\r\n",
            "[Describe the bounded correction]",
            $"Correct {stepLabel}",
            "plan-recovery-correction-draft",
            attachments);
        _pendingPlanTaskCorrectionContext = new PendingPlanTaskCorrectionContext(
            queueItemId,
            durable.PlanId,
            taskId);
        TranscriptQuickReplyFactory.RemoveDecomposeRecoveryActions(
            CoordinatorThread.Document.Blocks,
            durable.PlanId);
        RetireRecoveryInboxActions(plan, taskId);
        SyncPlanTaskCorrectionActivity(isPromptRunning: false);
    }

    private void RetireRecoveryInboxActions(PendingDecomposePlan plan, string taskId)
    {
        if (_inboxStore is null) return;
        var messageId = DecomposePlanInbox.BuildRecoveryMessageId(plan, taskId);
        var message = _inboxStore.GetById(messageId);
        if (message is null) return;
        foreach (var action in message.Actions)
            _inboxStore.MarkActionUsed(messageId, action.Label);
        var updated = _inboxStore.GetById(messageId);
        if (updated is null) return;
        _inboxPanel?.Refresh(_inboxStore.LoadAll());
        RefreshOpenApprovalInboxWindows(messageId, updated);
    }

    private void QueueClarifyHumanReviewItem(Plan plan, PlanHumanReviewChecklistItem item)
    {
        var current = _planStore?.Load(plan.PlanId) ?? plan;
        var gate = current.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, item.GateId, StringComparison.Ordinal));
        if (gate is null || gate.Status is not (PlanGateStatus.Pending or PlanGateStatus.AwaitingApproval))
        {
            ReportPlanActionIssue(
                current.PlanId,
                "Clarify human review",
                "This review checkpoint changed before the clarification prompt could be created.");
            return;
        }

        var reviewedTask = gate.AfterTaskIds
            .Select(taskId => current.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, taskId, StringComparison.Ordinal)))
            .FirstOrDefault(task => task is not null);
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            reviewedTask?.DisplayStepLabel,
            reviewedTask?.Title ?? gate.Message);
        var protocol = PlanHumanReviewClarificationResponseParser.BuildProtocolContext(
            current, gate, item, stepLabel);
        var attachments = new List<FollowUpAttachment>
        {
            new(
                CommitSha: string.Empty,
                Description: $"Plan: {current.Title}",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock("plan", current.Title, BuildPlanContentBody(current)),
                FileReferencePath: $".squad/plans/{current.PlanId}.json",
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This plan anchors the clarification to the exact durable review boundary. Remove it anyway?"),
            new(
                CommitSha: string.Empty,
                Description: "Required human-review clarification context",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock(
                    "plan-human-review-clarification",
                    "Required human-review clarification context",
                    protocol),
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This attachment identifies the exact checklist item and response contract. Remove it anyway?"),
        };
        QueueEditablePlanPrompt(
            $"Clarify this human-review requirement:\r\n\r\n“{item.Text}”\r\n\r\n" +
            "My question or concern:\r\n\r\n" +
            "[Describe what is unclear, unobservable, redundant, or unsuitable for human review]\r\n",
            "[Describe what is unclear, unobservable, redundant, or unsuitable for human review]",
            "Clarify human review",
            "plan-human-review-clarification-draft",
            attachments);
    }

    private void QueueRefreshHumanReviewWording(Plan plan, PlanHumanReviewChecklistItem item)
    {
        var current = _planStore?.Load(plan.PlanId) ?? plan;
        var gate = current.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, item.GateId, StringComparison.Ordinal));
        if (gate is null || gate.Status is not (PlanGateStatus.Pending or PlanGateStatus.AwaitingApproval))
        {
            ReportPlanActionIssue(
                current.PlanId,
                "Refresh human review wording",
                "This review checkpoint changed before the wording-refresh prompt could be created.");
            return;
        }

        var currentItem = PlanHumanReviewChecklist.Build(current, [gate]).FirstOrDefault(candidate =>
            string.Equals(candidate.ItemId, item.ItemId, StringComparison.Ordinal));
        if (currentItem is null)
        {
            ReportPlanActionIssue(
                current.PlanId,
                "Refresh human review wording",
                "This human-review requirement is no longer part of the current checkpoint.");
            return;
        }

        var reviewedTask = gate.AfterTaskIds
            .Select(taskId => current.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, taskId, StringComparison.Ordinal)))
            .FirstOrDefault(task => task is not null);
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            reviewedTask?.DisplayStepLabel,
            reviewedTask?.Title ?? gate.Message);
        var protocol = PlanHumanReviewClarificationResponseParser.BuildRefreshWordingProtocolContext(
            current, gate, currentItem, stepLabel);
        var attachments = new List<FollowUpAttachment>
        {
            new(
                CommitSha: string.Empty,
                Description: $"Plan: {current.Title}",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock("plan", current.Title, BuildPlanContentBody(current)),
                FileReferencePath: $".squad/plans/{current.PlanId}.json",
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This plan anchors the wording refresh to the exact durable review boundary. Remove it anyway?"),
            new(
                CommitSha: string.Empty,
                Description: "Required human-review wording context",
                OriginalPrompt: null,
                ContentBlock: BuildTypedAttachmentBlock(
                    "plan-human-review-wording",
                    "Required human-review wording context",
                    protocol),
                RequiresRemovalConfirmation: true,
                RemovalWarning: "This attachment identifies the exact checklist item and constrained response contract. Remove it anyway?"),
        };
        QueueEditablePlanPrompt(
            $"Refresh this human-review requirement so it matches the current product and repository:\r\n\r\n“{currentItem.Text}”\r\n\r\n" +
            "Relevant change or context (optional):\r\n\r\n" +
            "[Describe a rename or behavioral change, or send as-is for repository-based assessment]\r\n",
            "[Describe a rename or behavioral change, or send as-is for repository-based assessment]",
            "Refresh human review wording",
            "plan-human-review-wording-draft",
            attachments);
    }

    private async Task<bool> RetryDecomposeTaskAsync(
        PendingDecomposePlan plan,
        string taskId,
        AssessedRecoveryContinuationState? assessedRecoveryContinuation = null,
        bool allowUncommittedPreservedWork = false,
        PlanRecoveryRepositorySnapshot? requiredPreservedSnapshot = null)
    {
        if (_currentWorkspace is null) return false;
        if (IsPlanRecoveryActionBusy(plan.Group.GroupId))
            throw new InvalidOperationException("Wait for the current prompt or loop to finish before retrying the plan.");

        var durablePlan = _planStore?.Load(plan.Group.GroupId)
            ?? throw new InvalidOperationException("The durable plan is no longer available.");
        var currentRevision = durablePlan.Revision;
        if (!string.Equals(currentRevision, plan.Revision, StringComparison.Ordinal))
            throw new InvalidOperationException("The plan changed after these recovery controls were created.");
        if (durablePlan.LifecycleStatus is not (PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked) ||
            !string.Equals(
                durablePlan.InterruptionData?.InterruptedTaskId,
                taskId,
                StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "The plan has already moved beyond this recovery point. SquadDash left its current state unchanged.");
        }
        var currentGroup = PendingDecomposePlanAdapter.FromPlan(durablePlan).Group with
        {
            HostRevision = currentRevision,
        };

        var workspace = _currentWorkspace.FolderPath;
        var activeBranch = ReadGitBranch(workspace);
        if (!string.Equals(activeBranch, currentGroup.Branch, StringComparison.Ordinal))
            throw new InvalidOperationException(
                $"Plan {currentGroup.GroupId} requires branch '{currentGroup.Branch}', but '{activeBranch}' is active.");

        var tasksRelativePath = await GetTasksRepositoryRelativePathAsync(workspace);
        string status;
        if (requiredPreservedSnapshot is not null)
        {
            var currentSnapshot = await CapturePlanRecoveryRepositorySnapshotAsync(workspace);
            if (!PlanRecoveryAssessmentSnapshotPolicy.Matches(
                    requiredPreservedSnapshot,
                    currentSnapshot))
            {
                throw new InvalidOperationException(
                    "The repository changed after recovery was assessed. SquadDash left the plan stopped so new work is not accepted without review.");
            }

            status = currentSnapshot.StatusSnapshot;
        }
        else
        {
            status = await RunGitAsync(workspace, "status --porcelain --untracked-files=all");
        }

        var allowed = tasksRelativePath is null ? Array.Empty<string>() : new[] { tasksRelativePath };
        DecomposeWorktreePolicy.HasOnlyAllowedChanges(status, allowed, out var preservedPaths);
        if (PlanRecoveryCommitReadiness.RequiresCommit(
                preservedPaths.Count,
                allowUncommittedPreservedWork))
        {
            var headBeforeWait = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
            var blocked = new PlanPreflightBlockedException(
                "Preserved work is uncommitted",
                preservedPaths,
                currentGroup.Branch);
            ShowTranscriptPlanPreflightRecovery(
                plan,
                action: "continue-working",
                branchOverride: currentGroup.Branch,
                blocked,
                sourceActionsPanel: null,
                CoordinatorThread.Document.Blocks,
                retryOverride: () => RetryDecomposeTaskAsync(
                    plan,
                    taskId,
                    assessedRecoveryContinuation,
                    allowUncommittedPreservedWork: true,
                    requiredPreservedSnapshot: requiredPreservedSnapshot),
                contentFactory: exception => PlanPreflightRecoveryContent.FromPreservedWork(exception, taskId),
                retryLabel: "Resume With Uncommitted Files…",
                retryToolTip: "Resume this task immediately from the listed uncommitted files so the task agent can finish and commit them. SquadDash will not wait for you to commit first.",
                retryTone: QuickReplyTone.Warning,
                readinessOverride: async () =>
                {
                    var workspaceClean = await IsPlanPreflightWorkspaceCleanAsync(plan.Group.GroupId);
                    if (!workspaceClean) return false;
                    var currentHead = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
                    return PlanRecoveryCommitReadiness.IsReady(workspaceClean, headBeforeWait, currentHead);
                },
                autoRetryWhenReady: true);
            return false;
        }

        var revalidatedBranch = ReadGitBranch(workspace);
        if (!string.Equals(revalidatedBranch, currentGroup.Branch, StringComparison.Ordinal))
            throw new InvalidOperationException(
                $"Plan {currentGroup.GroupId} requires branch '{currentGroup.Branch}', but '{revalidatedBranch}' is active.");

        // Canonical recovery is committed before its Markdown view is refreshed.
        var recoveredPlan = PlanStoreUpdater.ApplyRecoveryWithProvenance(
            durablePlan,
            taskId,
            durablePlan.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, taskId, StringComparison.Ordinal))?.Commit,
            "continue-working");
        if (!TryPublishPlanRecoveryProgress(
                durablePlan,
                recoveredPlan,
                out var persistedRecovery,
                out var recoverySaveError))
            throw new InvalidOperationException(
                recoverySaveError ?? "The durable recovery state could not be saved.");
        recoveredPlan = persistedRecovery!;
        RefreshPlanProjectionBestEffort(recoveredPlan, "continue-working");
        LoadTasksPanel();
        await StartBackloggedDecomposeGroupAsync(
            currentGroup with { HostRevision = currentRevision },
            preservedPaths.Count > 0 ? taskId : null,
            preservedPaths,
            assessedRecoveryContinuation);
        var durableTask = _planStore?.Load(plan.Group.GroupId)?.Tasks.FirstOrDefault(task =>
            string.Equals(task.TaskId, taskId, StringComparison.Ordinal));
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            durableTask?.DisplayStepLabel,
            durableTask?.Title ?? taskId);
        ResolveRecoveryTranscript(PlanTaskExecutionPolicy.IsVerificationOnly(durableTask)
            ? $"↩ Recovery resumed. Running {stepLabel} as a verification-only step against the current branch."
            : assessedRecoveryContinuation is not null
                ? $"↩ Recovery resumed. Continuing only the remaining work for {stepLabel}."
                : $"↩ Recovery resumed. Restarting {stepLabel} from the preserved repository state.");
        return true;
    }

    private async Task ApplyDecomposeDecisionSafelyAsync(PendingDecomposePlan plan, string action, string? branchOverride)
    {
        try { await ApplyDecomposeDecisionAsync(plan, action, branchOverride); }
        catch (PlanPreflightBlockedException blocked)
        {
            SquadDashTrace.Write("UI", $"Plan preflight blocked: {blocked.Message}");
            ShowTranscriptPlanPreflightRecovery(
                plan, action, branchOverride, blocked,
                sourceActionsPanel: null,
                CoordinatorThread.Document.Blocks);
        }
        catch (Exception ex) { HandleUiCallbackException("Decompose plan", ex); }
    }

    private const string PlanContinuationQueueTag = "plan-continuation";
    private const string PlanRecoveryAssessmentQueueTag = "plan-recovery-assessment";
    private const string QueuedLoopJobTag = "queued-loop-job";
    private const string QueuedPlanStartTag = "queued-plan-start";

    private int DiscardObsoletePlanQueueItems(
        string reason,
        bool includeRecoveryAssessments = false)
    {
        var removedContinuations = _promptQueue.RemoveByTag(PlanContinuationQueueTag);
        var removedAssessments = includeRecoveryAssessments
            ? _promptQueue.RemoveByTag(PlanRecoveryAssessmentQueueTag)
            : 0;
        var removed = removedContinuations + removedAssessments;
        if (removed == 0)
            return 0;

        SquadDashTrace.Write(
            "Queue",
            $"Discarded obsolete plan queue items reason={reason} " +
            $"continuations={removedContinuations} assessments={removedAssessments}.");
        SyncQueuePanel();
        return removed;
    }

    private static bool IsHostQueueItem(PromptQueueItem item) =>
        string.Equals(item.SourceTag, PlanContinuationQueueTag, StringComparison.Ordinal) ||
        string.Equals(item.SourceTag, QueuedLoopJobTag, StringComparison.Ordinal) ||
        string.Equals(item.SourceTag, QueuedPlanStartTag, StringComparison.Ordinal);

    private bool HasReadyPromptQueueItems() => _promptQueue.Items.Any(item =>
        !item.IsEditing && !IsHostQueueItem(item));

    private bool HasQueuedWorkAheadOfNewLoop() =>
        HasReadyPromptQueueItems() ||
        _promptQueue.Items.Any(item => string.Equals(
            item.SourceTag,
            QueuedPlanStartTag,
            StringComparison.Ordinal));

    private void PlaceNewQueueItemBeforePlanContinuation(PromptQueueItem item)
    {
        if (string.Equals(item.SourceTag, PlanContinuationQueueTag, StringComparison.Ordinal)) return;
        var continuation = _promptQueue.Items
            .Select((candidate, index) => (candidate, index))
            .FirstOrDefault(pair => string.Equals(
                pair.candidate.SourceTag,
                PlanContinuationQueueTag,
                StringComparison.Ordinal));
        if (continuation.candidate is null) return;
        var currentIndex = _promptQueue.Items
            .Select((candidate, index) => (candidate, index))
            .First(pair => ReferenceEquals(pair.candidate, item)).index;
        if (currentIndex > continuation.index)
            _promptQueue.Reorder(item.Id, continuation.index);
    }

    private void EnsurePlanContinuationQueueItem()
    {
        if (_activeDecomposeGroupId is null) return;
        _promptQueue.RemoveByTag(PlanContinuationQueueTag);
        var plan = _planStore?.Load(_activeDecomposeGroupId);
        var presentation = plan is null ? null : PlanContinuationQueuePresentation.Build(plan);
        if (presentation is null)
        {
            SyncQueuePanel();
            return;
        }
        _promptQueue.EnqueueItem(new PromptQueueItem
        {
            Text = $"Continue plan {_activeDecomposeGroupId}",
            SequenceNumber = _promptQueueCoordinator.NextSequenceNumber(),
            QueueNumber = NextQueueNumber(),
            IsSystemInjected = true,
            SourceTag = PlanContinuationQueueTag,
            IsLocked = true,
            DisplayLabel = presentation.Label,
            ReadOnlyDisplayText = presentation.Description,
        });
        SyncQueuePanel();
    }

    private void EnqueueFilteredLoopJob(QueuedLoopJob job)
    {
        _promptQueue.EnqueueItem(new PromptQueueItem
        {
            Text = job.Encode(),
            SequenceNumber = _promptQueueCoordinator.NextSequenceNumber(),
            QueueNumber = NextQueueNumber(),
            IsSystemInjected = true,
            SourceTag = QueuedLoopJobTag,
            IsLocked = true,
            DisplayLabel = job.DisplayLabel,
            ReadOnlyDisplayText =
                $"This is a locked filtered-loop job containing {job.TaskCount} task(s).\n\n" +
                "SquadDash will start it after the active loop finishes. Its task snapshot cannot be edited or sent manually.",
        });
        var continuation = _promptQueue.Items.FirstOrDefault(item => string.Equals(
            item.SourceTag,
            PlanContinuationQueueTag,
            StringComparison.Ordinal));
        if (continuation is not null)
            _promptQueue.Reorder(continuation.Id, _promptQueue.Count - 1);
        SyncQueuePanel();
        AppendLoopOutputLine(
            $"⏳ {job.DisplayLabel} queued behind the running loop.",
            LoopLifecycleBrush);
    }

    private async Task QueueOrStartDurablePlanAsync(Plan plan)
    {
        var shouldQueue = PlanStartQueuePolicy.ShouldQueue(
            coordinatorTurnActive: _isPromptRunning,
            loopActive: IsLoopRunning,
            queueDrainActive: _queueDrainActive,
            backgroundWorkActive: _backgroundTaskPresenter.HasBackgroundTasks(),
            directFollowUpPending: HasPendingDirectQuickReplyAgentFollowUp(),
            queueDispatchHeld: IsQueueDispatchHeld,
            queuedItemCount: _promptQueue.Count);
        if (!shouldQueue)
        {
            await StartOrResumeDurablePlanAsync(plan);
            return;
        }

        var alreadyQueued = _promptQueue.Items.Any(item =>
            string.Equals(item.SourceTag, QueuedPlanStartTag, StringComparison.Ordinal) &&
            QueuedPlanStart.TryDecode(item.Text, out var queued) &&
            string.Equals(queued?.PlanId, plan.PlanId, StringComparison.Ordinal));
        if (alreadyQueued)
            return;

        var request = new QueuedPlanStart(plan.PlanId, plan.DisplayName);
        _promptQueue.EnqueueItem(new PromptQueueItem
        {
            Text = request.Encode(),
            SequenceNumber = _promptQueueCoordinator.NextSequenceNumber(),
            QueueNumber = NextQueueNumber(),
            IsSystemInjected = true,
            SourceTag = QueuedPlanStartTag,
            IsLocked = true,
            DisplayLabel = $"Start plan: {plan.DisplayName}",
            ReadOnlyDisplayText =
                $"Start plan “{plan.DisplayName}” when the coordinator and all earlier queued work are idle.\n\n" +
                "This start request is saved across restarts. Delete this queued item to cancel it; the approved plan will remain pending.",
        });
        SyncQueuePanel();
        SquadDashTrace.Write(
            "Queue",
            $"Queued plan start plan={plan.PlanId} title='{plan.DisplayName}' queueCount={_promptQueue.Count}.");
    }

    private void ShowTranscriptPlanPreflightRecovery(
        PendingDecomposePlan plan,
        string action,
        string? branchOverride,
        PlanPreflightBlockedException exception,
        WrapPanel? sourceActionsPanel,
        BlockCollection blocks,
        Func<Task<bool>>? retryOverride = null,
        Func<PlanPreflightBlockedException, PlanPreflightRecoveryContent>? contentFactory = null,
        string retryLabel = "Retry",
        string? retryToolTip = null,
        QuickReplyTone retryTone = QuickReplyTone.Default,
        Func<Task<bool>>? readinessOverride = null,
        bool autoRetryWhenReady = true)
    {
        foreach (var existing in blocks.OfType<BlockUIContainer>().Where(block =>
                     block.Tag is PlanPreflightRecoveryTag tag &&
                     string.Equals(tag.GroupId, plan.Group.GroupId, StringComparison.Ordinal)).ToArray())
            blocks.Remove(existing);

        // Resuming from the Plan Viewer does not click (and therefore does not collapse) the
        // older transcript recovery button. The preflight card now owns the one valid retry,
        // so retire only that plan's older actions while preserving its explanation and link.
        TranscriptQuickReplyFactory.RemoveDecomposeRecoveryActions(
            CoordinatorThread.Document.Blocks,
            plan.Group.GroupId);

        var buildContent = contentFactory ?? PlanPreflightRecoveryContent.From;
        var content = buildContent(exception);
        var stack = new StackPanel();
        var header = new Grid();
        header.ColumnDefinitions.Add(new ColumnDefinition());
        header.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        var title = new TextBlock
        {
            Text = content.Title,
            FontWeight = FontWeights.SemiBold,
            FontSize = _transcriptFontSize,
            VerticalAlignment = VerticalAlignment.Center,
        };
        title.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        header.Children.Add(title);

        var headerButtons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Right,
            VerticalAlignment = VerticalAlignment.Center,
        };
        Grid.SetColumn(headerButtons, 1);

        var copyButton = new CopyButton
        {
            CopyTooltip = "Copy details",
            Width = 26,
            Height = 22,
            Padding = new Thickness(0),
            Margin = new Thickness(4, 2, 4, 2),
            HorizontalAlignment = HorizontalAlignment.Right,
            VerticalAlignment = VerticalAlignment.Center,
        };
        System.Windows.Automation.AutomationProperties.SetName(copyButton, "Copy details");
        headerButtons.Children.Add(copyButton);
        var dismissButton = new Button
        {
            Content = "×",
            Width = 22,
            Height = 22,
            Padding = new Thickness(0),
            Margin = new Thickness(0, 2, 0, 2),
            VerticalAlignment = VerticalAlignment.Center,
            ToolTip = ToolTipHelper.MakeThemedToolTip(
                "Dismiss this recovery card. The plan will remain in its current state."),
        };
        dismissButton.SetResourceReference(Button.StyleProperty, "PanelCloseButtonStyle");
        dismissButton.SetResourceReference(Button.FontSizeProperty, "FontSizeNormal");
        System.Windows.Automation.AutomationProperties.SetName(dismissButton, "Dismiss plan recovery card");
        headerButtons.Children.Add(dismissButton);
        header.Children.Add(headerButtons);
        stack.Children.Add(header);

        var summary = new TextBlock
        {
            Text = content.Summary,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 4, 0, 6),
            FontSize = _transcriptFontSize,
        };
        summary.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        stack.Children.Add(summary);

        var files = new TextBlock
        {
            Text = content.ChangedFilesSummary,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 0, 0, 6),
            FontSize = _transcriptFontSize,
        };
        files.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        files.Visibility = string.IsNullOrWhiteSpace(content.ChangedFilesSummary)
            ? Visibility.Collapsed
            : Visibility.Visible;
        stack.Children.Add(files);

        var detailsText = new TextBlock
        {
            Text = content.TechnicalDetails,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(8, 4, 0, 6),
            FontSize = _transcriptFontSize,
        };
        detailsText.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        var detailsHeader = new TextBlock
        {
            Text = "Technical details",
            FontSize = _transcriptFontSize,
        };
        detailsHeader.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        var details = new Expander
        {
            Header = detailsHeader,
            Content = detailsText,
            Margin = new Thickness(0, 0, 0, 6),
            FontSize = _transcriptFontSize,
        };
        details.SetResourceReference(Expander.ForegroundProperty, "PlanPreflightWarningText");
        if (TryFindResource("TranscriptExpanderStyle") is Style transcriptExpanderStyle)
            details.Style = transcriptExpanderStyle;
        stack.Children.Add(details);

        var readiness = new TextBlock
        {
            Text = content.RecoveryGuidance,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 0, 0, 6),
        };
        readiness.SetResourceReference(TextBlock.ForegroundProperty, "PlanPreflightWarningText");
        readiness.FontSize = _transcriptFontSize;
        stack.Children.Add(readiness);

        var utilities = new TextBlock
        {
            FontSize = _transcriptFontSize,
            Margin = new Thickness(0, 0, 0, 6),
        };
        var viewChangesLink = new Hyperlink(new Run("View changes")) { Cursor = Cursors.Hand };
        viewChangesLink.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
        if (!exception.RequiresRepositoryInitialization)
            utilities.Inlines.Add(viewChangesLink);
        else
            utilities.Visibility = Visibility.Collapsed;
        stack.Children.Add(utilities);

        var buttons = new WrapPanel { Orientation = Orientation.Horizontal };
        var retryButton = TranscriptQuickReplyFactory.CreateButton(
            exception.RequiresRepositoryInitialization
                ? "Initialize repository and start plan"
                : retryLabel,
            _transcriptFontSize,
            toolTip: retryToolTip is null ? null : ToolTipHelper.MakeThemedToolTip(retryToolTip),
            tone: retryTone);
        buttons.Children.Add(retryButton);
        stack.Children.Add(buttons);

        var card = new Border
        {
            Child = stack,
            CornerRadius = new CornerRadius(10),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(12, 10, 12, 10),
            MaxWidth = 760,
            HorizontalAlignment = HorizontalAlignment.Left,
        };
        card.SetResourceReference(Border.BackgroundProperty, "PlanPreflightWarningSurface");
        card.SetResourceReference(Border.BorderBrushProperty, "PlanPreflightWarningBorder");
        var container = TranscriptQuickReplyFactory.CreateContainer(
            card,
            new PlanPreflightRecoveryTag(plan.Group.GroupId, plan.Revision));
        blocks.Add(container);
        sourceActionsPanel?.SetCurrentValue(UIElement.VisibilityProperty, Visibility.Collapsed);

        DispatcherTimer? timer = null;
        dismissButton.Click += (_, _) =>
        {
            timer?.Stop();
            if (blocks.Contains(container))
                blocks.Remove(container);
            sourceActionsPanel?.SetCurrentValue(UIElement.VisibilityProperty, Visibility.Visible);
        };
        viewChangesLink.Click += (_, _) => _ = ShowPlanPreflightChangesAsync(exception);
        copyButton.Click += (_, _) =>
        {
            SetClipboardTextWithRetry(content.ClipboardText);
            readiness.Text = "Details copied to the clipboard.";
        };
        var retryInFlight = false;
        retryButton.Click += async (_, _) => await RetryPlanAsync("Checking the workspace and retrying…");

        async Task RetryPlanAsync(string progressText)
        {
            if (retryInFlight) return;
            retryInFlight = true;
            buttons.IsEnabled = false;
            readiness.Text = exception.RequiresRepositoryInitialization
                ? "Initializing the repository…"
                : progressText;
            try
            {
                if (exception.RequiresRepositoryInitialization &&
                    !await InitializeRepositoryForPlanAsync())
                {
                    buttons.IsEnabled = true;
                    readiness.Text = "The repository was not initialized. Review the transcript and try again.";
                    return;
                }
                var succeeded = retryOverride is null
                    ? await ApplyDecomposeDecisionAsync(plan, action, branchOverride)
                    : await retryOverride();
                if (succeeded)
                {
                    timer?.Stop();
                    container.Tag = new PlanPreflightRecoveryReceiptTag(
                        plan.Group.GroupId,
                        plan.Revision,
                        DateTimeOffset.Now);
                    title.Text = "✓ Workspace cleaned; plan resumed";
                    title.SetResourceReference(TextBlock.ForegroundProperty, "LabelText");
                    summary.Visibility = Visibility.Collapsed;
                    files.Visibility = Visibility.Collapsed;
                    details.Visibility = Visibility.Collapsed;
                    utilities.Visibility = Visibility.Collapsed;
                    copyButton.Visibility = Visibility.Collapsed;
                    buttons.Visibility = Visibility.Collapsed;
                    readiness.Text = $"The worktree became clean and SquadDash resumed the plan at {DateTimeOffset.Now:t}. No task was failed or reworked by this pause.";
                    readiness.FontWeight = FontWeights.Normal;
                    card.SetResourceReference(Border.BackgroundProperty, "TranscriptSurface");
                    card.SetResourceReference(Border.BorderBrushProperty, "InputBorder");
                    return;
                }
                buttons.IsEnabled = true;
                readiness.Text = "The plan did not start. Review the workspace and retry.";
            }
            catch (PlanPreflightBlockedException blocked)
            {
                if (blocks.Contains(container)) blocks.Remove(container);
                ShowTranscriptPlanPreflightRecovery(
                    plan, action, branchOverride, blocked, sourceActionsPanel, blocks,
                    retryOverride, contentFactory, retryLabel, retryToolTip, retryTone,
                    readinessOverride, autoRetryWhenReady);
            }
            catch (Exception ex)
            {
                buttons.IsEnabled = true;
                readiness.Text = "Retry failed. Expand technical details or review the error output.";
                HandleUiCallbackException("Decompose plan", ex);
            }
            finally
            {
                retryInFlight = false;
            }
        }

        var pollInFlight = false;
        timer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(1.5) };
        timer.Tick += async (_, _) =>
        {
            if (pollInFlight || !blocks.Contains(container))
            {
                if (!blocks.Contains(container)) timer.Stop();
                return;
            }
            pollInFlight = true;
            try
            {
                var currentDirtyPaths = await GetPlanPreflightDirtyPathsAsync(plan.Group.GroupId);
                if (currentDirtyPaths is not null)
                {
                    var refreshedContent = PlanPreflightRecoveryContent.TryRefreshFromDirtyPaths(
                        exception,
                        currentDirtyPaths,
                        buildContent);
                    if (refreshedContent is not null)
                    {
                        content = refreshedContent;
                        summary.Text = content.Summary;
                        files.Text = content.ChangedFilesSummary;
                        files.Visibility = string.IsNullOrWhiteSpace(content.ChangedFilesSummary)
                            ? Visibility.Collapsed
                            : Visibility.Visible;
                        detailsText.Text = content.TechnicalDetails;
                    }
                }

                var ready = readinessOverride is null
                    ? currentDirtyPaths is { Count: 0 }
                    : await readinessOverride();
                if (!ready) return;
                timer.Stop();
                summary.Visibility = Visibility.Collapsed;
                files.Visibility = Visibility.Collapsed;
                details.Visibility = Visibility.Collapsed;
                utilities.Visibility = Visibility.Collapsed;
                copyButton.Visibility = Visibility.Collapsed;
                readiness.Text = autoRetryWhenReady
                    ? "Committed changes detected. Resuming automatically…"
                    : "Workspace is clean. Retry is ready.";
                readiness.FontWeight = FontWeights.Bold;
                readiness.Margin = new Thickness(0, 6, 0, 6);
                card.SetResourceReference(Border.BackgroundProperty, "TranscriptSurface");
                retryButton.FontWeight = FontWeights.SemiBold;
                if (autoRetryWhenReady)
                    await RetryPlanAsync("Committed changes detected. Resuming automatically…");
            }
            finally { pollInFlight = false; }
        };
        if (!exception.RequiresRepositoryInitialization)
            timer.Start();
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private async Task<bool> ApplyDecomposeDecisionAsync(PendingDecomposePlan plan, string action, string? branchOverride)
    {
        if (_currentWorkspace is null) return false;
        if (_isPromptRunning &&
            !DecomposePlanActionDispatchPolicy.CanApplyWhilePromptRunning(action))
            throw new InvalidOperationException(
                "Wait for the current prompt to finish before applying the task plan.");
        var currentPlan = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Load(plan.Group.GroupId);
        if (currentPlan is null || !string.Equals(currentPlan.Revision, plan.Revision, StringComparison.Ordinal))
            throw new InvalidOperationException("This task-plan approval is stale. Use the controls on the latest plan response.");
        var group = plan.Group;
        if (!TasksJsonParser.TryParse(
                "TASKS_JSON:\n" + System.Text.Json.JsonSerializer.Serialize(group),
                out _,
                out var schemaDiagnostic))
            throw new InvalidOperationException(
                "The saved task plan no longer passes schema validation: " +
                (schemaDiagnostic?.Message ?? "unknown schema error"));
        if (!PlanAgentAssignmentCatalogValidator.TryValidate(
                group,
                _currentWorkspace.SquadFolderPath,
                out var assignmentCatalogError,
                requireExplicitRouting:
                    currentPlan.CreatedAt is not null &&
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off,
                enforceAssignments:
                    PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy) != PlanAgentRoutingPolicy.Off))
            throw new InvalidOperationException(assignmentCatalogError ?? "The saved plan has invalid agent assignments.");
        if (!CodeHealthGroupRunner.HasNoDependencyCycle(group, out _))
            throw new InvalidOperationException("The saved task plan contains a dependency cycle.");
        var workspace = _currentWorkspace.FolderPath;
        var effective = group with { HostRevision = plan.Revision };
        if (!TryValidateDecomposeRevisionAgainstWorkspace(group, out var isRevision, out var revisionError))
            throw new InvalidOperationException(
                "This revised plan no longer matches the accepted plan state. " + revisionError);
        Plan? revisedDurablePlan = null;
        if (action == "collect" && isRevision)
        {
            // "Add to Plans" is also the approval action for a new definition of an
            // already-collected plan. Publish that definition before entering the collection
            // service; otherwise its stale-Inbox guard mistakes the legitimate new revision
            // for an older proposal attempting to overwrite the durable plan.
            if (!TryPublishLegacyReplacementRevision(effective, out revisedDurablePlan, out var applyError))
                throw new InvalidOperationException(applyError ?? "SquadDash could not persist the approved revision.");
        }
        if (action == "collect")
        {
            var pendingStore = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath);
            var collectionService = new PlanCollectionService(
                _planStore ?? new PlanStore(_currentWorkspace.SquadFolderPath),
                pendingStore);
            var collectionCandidate = revisedDurablePlan is null
                ? plan
                : new PendingDecomposePlan(
                    revisedDurablePlan.Revision,
                    PendingDecomposePlanAdapter.FromPlan(revisedDurablePlan).Group,
                    plan.CreatedAt);
            var result = collectionService.Collect(collectionCandidate, DateTimeOffset.UtcNow);
            switch (result.Outcome)
            {
                case CollectionOutcome.Collected:
                case CollectionOutcome.AlreadyCollected:
                    var messageId = DecomposePlanInbox.BuildMessageId(plan);
                    _inboxStore?.MarkActionUsed(messageId, "Add to Plans");
                    _inboxPanel?.Refresh(_inboxStore?.LoadAll() ?? []);
                    if (result.Plan is { } collectedPlan)
                        _plansPanelController?.RevealCollectedPlan(collectedPlan);
                    AppendLine($"✅ Plan \"{group.GroupTitle}\" saved to Plans. Launch it when you're ready.");
                    return true;
                case CollectionOutcome.StaleRevisionRejected:
                    SquadDashTrace.Write(TraceCategory.General,
                        $"Collect action rejected: stale revision for '{group.GroupId}'.");
                    throw new InvalidOperationException(
                        "This plan has a newer revision. Use the controls on the latest plan response.");
                case CollectionOutcome.ActivePlanBlocked:
                    SquadDashTrace.Write(TraceCategory.General,
                        $"Collect action blocked: active plan exists for '{group.GroupId}'.");
                    throw new InvalidOperationException(
                        "An active plan with the same ID is already running. Complete or stop it first.");
                default:
                    return false;
            }
        }

        if (action != "add-to-backlog" && _loopController.IsRunning)
            throw new InvalidOperationException("Another loop is already running.");
        if (action == "execute-active-branch")
        {
            var active = ReadGitBranch(workspace);
            if (string.IsNullOrWhiteSpace(active) || active.StartsWith("(detached", StringComparison.Ordinal))
                throw new PlanPreflightBlockedException(
                    PlanPreflightBlockedException.RepositoryInitializationRequiredCondition,
                    [],
                    targetBranch: null);
            effective = effective with { Branch = active };
        }
        else if (action == "execute-new-branch")
        {
            var target = string.IsNullOrWhiteSpace(branchOverride) ? group.Branch : branchOverride.Trim();
            await PrepareDecomposeBranchAsync(workspace, target, group.GroupId);
            effective = effective with { Branch = target };
        }

        if (isRevision)
        {
            if (!TryPublishLegacyReplacementRevision(effective, out revisedDurablePlan, out var applyError))
                throw new InvalidOperationException(applyError ?? "SquadDash could not persist the approved revision.");
            effective = PendingDecomposePlanAdapter.FromPlan(revisedDurablePlan!).Group with
            {
                HostRevision = revisedDurablePlan!.Revision,
            };
        }

        if (action == "add-to-backlog")
        {
            if (revisedDurablePlan is null)
            {
                var collectionService = new PlanCollectionService(
                    _planStore ?? new PlanStore(_currentWorkspace.SquadFolderPath));
                var collected = collectionService.Collect(
                    new PendingDecomposePlan(plan.Revision, effective),
                    DateTimeOffset.UtcNow);
                if (collected.Outcome is not (CollectionOutcome.Collected or CollectionOutcome.AlreadyCollected) ||
                    collected.Plan is null)
                    return false;
                revisedDurablePlan = collected.Plan;
            }
            RefreshPlanProjectionBestEffort(revisedDurablePlan, "approved backlog plan");
            new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Delete(group.GroupId);
            ArchiveDecomposePlanInboxReminder(plan);
            AppendLine($"✅ Added decompose group {group.GroupId} to the backlog.");
            return true;
        }

        if (_loopController.IsRunning)
            throw new InvalidOperationException("Another loop started while this plan was being prepared.");
        if (await StartDecomposeLoopAsync(effective.GroupId, effective))
        {
            new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Delete(group.GroupId);
            ArchiveDecomposePlanInboxReminder(plan);
            return true;
        }
        return false;
    }

    /// <summary>
    /// Applies the legacy replacement-task revision format to the durable plan first. The
    /// markdown task list is refreshed afterward and has no veto over the accepted contract.
    /// </summary>
    private bool TryPublishLegacyReplacementRevision(
        DecomposedTaskGroup proposal,
        out Plan? published,
        out string? error)
    {
        published = null;
        error = null;
        var current = _planStore?.Load(proposal.GroupId);
        if (current is null)
        {
            error = $"The durable plan '{proposal.GroupId}' was not found.";
            return false;
        }

        var result = PlanRevisionApplier.Apply(
            current,
            proposal,
            current.Revision,
            DateTimeOffset.UtcNow);
        if (result.Outcome == PlanRevisionApplyOutcome.NoChanges)
        {
            published = current;
            return true;
        }
        if (result.Outcome != PlanRevisionApplyOutcome.Applied || result.UpdatedPlan is not { } updated)
        {
            error = result.Error ?? "The approved revision failed durable validation.";
            return false;
        }

        var supersededParentIds = proposal.Tasks
            .Where(task => !string.IsNullOrWhiteSpace(task.ParentTaskId))
            .Select(task => task.ParentTaskId!)
            .ToHashSet(StringComparer.Ordinal);
        if (supersededParentIds.Count > 0)
        {
            var tasks = updated.Tasks.Select(task => supersededParentIds.Contains(task.TaskId)
                ? task with
                {
                    Status = PlanTaskStatus.Superseded,
                    CompletionSummary = "Superseded by an approved replacement-task revision.",
                }
                : task).ToArray();
            updated = updated with
            {
                Tasks = tasks,
                Progress = updated.Progress with
                {
                    CompletedCount = tasks.Count(task => task.Status == PlanTaskStatus.Complete),
                    TotalCount = tasks.Count(task => task.Status != PlanTaskStatus.Superseded),
                },
            };
        }

        try
        {
            new PlanRevisionHistoryStore(_currentWorkspace!.SquadFolderPath).SaveSnapshot(current);
        }
        catch (Exception ex)
        {
            error = "The revision history snapshot could not be saved: " + ex.Message;
            return false;
        }
        if (!TryPublishPlanProgress(updated, out error))
            return false;

        RefreshPlanProjectionBestEffort(updated, "approved replacement revision");
        published = updated;
        return true;
    }

    private void PromoteBypassedDecomposePlans(string? rawResponse)
    {
        var captured = _pendingPlansAtCoordinatorTurnStart;
        _pendingPlansAtCoordinatorTurnStart = [];
        try
        {
            if (captured.Count == 0 || _currentWorkspace is null)
                return;

            var store = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath);
            foreach (var plan in captured)
            {
                if (IsDurablePlanArchived(plan.Group.GroupId))
                {
                    store.Archive(plan.Group.GroupId);
                    SquadDashTrace.Write(TraceCategory.Inbox,
                        $"Discarded bypassed proposal for archived plan '{plan.Group.GroupId}'.");
                    continue;
                }
                if (_stagedPlanRevisionTurnCollectionState.Addresses(plan) ||
                    DecomposePlanInbox.ResponseAddressesPlan(plan, rawResponse))
                {
                    continue;
                }

                var current = store.Load(plan.Group.GroupId);
                if (current is not null && string.Equals(current.Revision, plan.Revision, StringComparison.Ordinal))
                    SaveDecomposePlanInboxReminder(plan, explicitlyRequested: false);
            }
        }
        finally
        {
            _stagedPlanRevisionTurnCollectionState.Reset();
        }
    }

    private void SaveDecomposePlanInboxReminder(PendingDecomposePlan plan, bool explicitlyRequested)
    {
        if (_inboxStore is null)
            return;
        if (IsDurablePlanArchived(plan.Group.GroupId))
        {
            if (_currentWorkspace is not null)
                new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Archive(plan.Group.GroupId);
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"Suppressed Inbox delivery for archived plan '{plan.Group.GroupId}'.");
            return;
        }
        var activeBranch = _currentWorkspace is null ? null : ReadGitBranch(_currentWorkspace.FolderPath);
        var message = DecomposePlanInbox.BuildMessage(
            plan,
            DateTimeOffset.Now,
            explicitlyRequested,
            activeBranch);
        var alreadyDelivered = explicitlyRequested
            ? _inboxStore.GetById(message.Id) is not null
            : _inboxStore.Exists(message.Id, includeArchive: true);
        if (alreadyDelivered)
            return;

        _inboxStore.Save(message);
        _inboxPanel?.Refresh(_inboxStore.LoadAll());
        if (explicitlyRequested)
        {
            AppendInboxReceivedEntry(message.Subject, message.Id);
        }
        else
        {
            AppendPlanMovedToInboxBanner(plan, message);
            SchedulePendingPlanInboxCallout(message.Id);
        }
        SquadDashTrace.Write(TraceCategory.Inbox,
            $"Pending decompose plan '{plan.Group.GroupId}' delivered to Inbox (explicit={explicitlyRequested}).");
    }

    private void ArchiveDecomposePlanInboxReminder(PendingDecomposePlan plan)
    {
        if (_inboxStore is null)
            return;
        var messageId = DecomposePlanInbox.BuildMessageId(plan);
        _inboxStore.Archive(messageId);
        _inboxPanel?.Refresh(_inboxStore.LoadAll());
        foreach (var window in _openInboxWindows.Where(w => w.MessageId == messageId).ToArray())
            window.Close();
    }

    private bool TryHandlePlanVisualizerReviewFromResponse(string? rawResponse)
    {
        if (rawResponse?.Contains(PlanVisualizerReviewParser.Marker, StringComparison.Ordinal) != true)
            return false;
        if (!PlanVisualizerReviewParser.TryParse(rawResponse, out var review, out var error) || review is null)
        {
            NotifyReviewFailure(error ?? "The AI response did not contain a valid review payload.");
            return true;
        }
        if (_currentWorkspace is null)
        {
            NotifyReviewFailure("The review could not be attached because no workspace is open.", review.GroupId);
            return true;
        }

        var pending = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath)
            .Load(review.GroupId);
        if (pending is null ||
            !string.Equals(pending.Revision, review.BaseRevision, StringComparison.Ordinal))
        {
            NotifyReviewFailure("The AI review was stale and was not attached to the current plan revision.",
                review.GroupId);
            return true;
        }

        var invalidTarget = review.Annotations.FirstOrDefault(annotation => annotation.TargetKind switch
        {
            "plan" => !string.Equals(annotation.TargetId, pending.Group.GroupId, StringComparison.Ordinal),
            "task" => !pending.Group.Tasks.Any(task =>
                string.Equals(task.Id, annotation.TargetId, StringComparison.Ordinal)),
            "validation" => !(pending.Group.Validations ?? []).Any(validation =>
                string.Equals(validation.ValidationId, annotation.TargetId, StringComparison.Ordinal)),
            "gate" => !(pending.Group.ApprovalGates ?? []).Any(gate =>
                string.Equals(gate.GateId, annotation.TargetId, StringComparison.Ordinal)),
            _ => true,
        });
        if (invalidTarget is not null)
        {
            NotifyReviewFailure(
                $"The AI review referenced an unknown {invalidTarget.TargetKind} " +
                $"'{invalidTarget.TargetId}' and was not attached.",
                review.GroupId);
            return true;
        }

        var invalidHumanFinding = (review.HumanVerificationFindings ?? []).FirstOrDefault(finding =>
        {
            var gate = (pending.Group.ApprovalGates ?? []).FirstOrDefault(candidate =>
                string.Equals(candidate.GateId, finding.GateId, StringComparison.Ordinal));
            return gate is null || !(gate.ProofRequirements ?? []).Any(requirement =>
                string.Equals(requirement.RequirementId, finding.RequirementId, StringComparison.Ordinal));
        });
        if (invalidHumanFinding is not null)
        {
            NotifyReviewFailure(
                $"The AI review referenced unknown human-verification requirement " +
                $"'{invalidHumanFinding.GateId}/{invalidHumanFinding.RequirementId}' and was not attached.",
                review.GroupId);
            return true;
        }

        new PlanVisualizerReviewStore(_currentWorkspace.SquadFolderPath).Save(review);
        foreach (var entry in _openPlanViewerWindows.Where(entry =>
                     string.Equals(entry.GroupId, review.GroupId, StringComparison.Ordinal) &&
                     string.Equals(entry.Window.CurrentRevision, review.BaseRevision, StringComparison.Ordinal)))
            entry.Window.SetReviewAnnotations(review);
        return true;

        void NotifyReviewFailure(string message, string? targetGroupId = null)
        {
            SquadDashTrace.Write("PlanReview", message);
            foreach (var entry in _openPlanViewerWindows.Where(entry =>
                         targetGroupId is null ||
                         string.Equals(entry.GroupId, targetGroupId, StringComparison.Ordinal)))
                entry.Window.SetReviewRequestError(message);
        }
    }

    private void OpenReviewCard(Plan displayedPlan, string taskId)
    {
        var current = _planStore?.Load(displayedPlan.PlanId) ?? displayedPlan;
        var identity = new DecomposeRecoveryTag(current.PlanId, current.Revision, taskId);

        Border? FindCard(bool requireLiveActions)
        {
            var sections = CoordinatorThread.Document.Blocks
                .OfType<Section>()
                .Where(candidate =>
                    candidate.Tag is DecomposeRecoveryTag tag &&
                    string.Equals(tag.GroupId, identity.GroupId, StringComparison.Ordinal) &&
                    string.Equals(tag.Revision, identity.Revision, StringComparison.Ordinal) &&
                    string.Equals(tag.TaskId, identity.TaskId, StringComparison.Ordinal))
                .Reverse();
            foreach (var section in sections)
            {
                var container = section.Blocks.OfType<BlockUIContainer>().FirstOrDefault(candidate =>
                    candidate.Tag is DecomposeRecoveryCardTag cardTag &&
                    cardTag.Identity == identity &&
                    (!requireLiveActions || cardTag.ActionsPanel.Visibility == Visibility.Visible));
                if (container?.Child is Border border) return border;
            }
            return null;
        }

        var card = FindCard(requireLiveActions: true);
        if (card is null)
        {
            // Transcript cards are presentation state, not the source of truth. Reconstruct the
            // card from the durable plan if transcript compaction or later activity removed it.
            AppendDecomposeRecoveryActions(PendingDecomposePlanAdapter.FromPlan(current), taskId);
            card = FindCard(requireLiveActions: true) ?? FindCard(requireLiveActions: false);
        }

        if (card is null)
        {
            ReportPlanActionIssue(
                current.PlanId,
                "Open review card",
                "SquadDash could not reconstruct the review card from the current plan state.");
            return;
        }

        OutputTextBox.Focus();
        card.BringIntoView();
        var highlight = new DoubleAnimation(
            fromValue: 0.55,
            toValue: 1,
            duration: TimeSpan.FromMilliseconds(320))
        {
            AutoReverse = true,
            RepeatBehavior = new RepeatBehavior(2),
        };
        highlight.Completed += (_, _) =>
        {
            card.BeginAnimation(UIElement.OpacityProperty, null);
            card.Opacity = 1;
        };
        card.BeginAnimation(UIElement.OpacityProperty, highlight);
    }

    private void OpenDecomposePlanViewer(PendingDecomposePlan plan, Plan? durablePlan = null)
    {
        var groupId = plan.Group.GroupId;
        PendingDecomposePlan? livePlan = null;
        if (_currentWorkspace is not null)
        {
            var candidate = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath)
                .Load(groupId);
            if (candidate is not null && durablePlan is null)
            {
                // Transcript links retain the proposal revision they originally rendered. Once an
                // edit advances that revision, opening the old link must still show/reuse the live
                // editable proposal rather than constructing a stale read-only preview.
                plan = candidate;
                livePlan = candidate;
            }
            else if (candidate is not null &&
                     string.Equals(candidate.Revision, plan.Revision, StringComparison.Ordinal))
            {
                livePlan = candidate;
            }
        }
        var isInteractiveVisualizationFixture = groupId is
            "VIZLINEAR-20260729" or
            "VIZDIAMOND-20260729" or
            "VIZPARALLEL-20260729" or
            SimulationPlanFixtureBuilder.ValidationShieldGalleryPlanId;

        // If a viewer for this plan is already open, bring it to the front instead of opening another.
        var existing = _openPlanViewerWindows.FirstOrDefault(e =>
            string.Equals(e.GroupId, groupId, StringComparison.Ordinal) &&
            string.Equals(e.Window.CurrentRevision, plan.Revision, StringComparison.Ordinal));
        if (existing.Window is not null)
        {
            if (existing.Window.WindowState == WindowState.Minimized)
                existing.Window.WindowState = WindowState.Normal;
            existing.Window.Activate();
            existing.Window.Focus();
            existing.Window.PulseAttention();
            return;
        }

        // Auto-resolve the durable plan when not supplied by the caller (e.g. inbox link).
        // Without it the gate-editing controls (lock buttons, onGatesChanged) are suppressed.
        if (durablePlan is null && _planStore is not null)
        {
            var storedPlan = _planStore.Load(groupId);
            if (storedPlan is not null &&
                string.Equals(storedPlan.Revision, plan.Revision, StringComparison.Ordinal))
                durablePlan = storedPlan;
        }
        else if (durablePlan is not null &&
                 !string.Equals(durablePlan.Revision, plan.Revision, StringComparison.Ordinal))
        {
            // Never enable lifecycle or gate editing against a graph from another revision.
            durablePlan = null;
        }

        // The three visualization fixtures are an explicit, non-persistent approval-gate
        // playground. Give the viewer a durable-shaped in-memory model so every stop control is
        // interactive, but never publish it to PlanStore/tasks.md or expose execution actions.
        if (durablePlan is null && isInteractiveVisualizationFixture)
        {
            durablePlan = string.Equals(
                groupId,
                SimulationPlanFixtureBuilder.ValidationShieldGalleryPlanId,
                StringComparison.Ordinal)
                ? SimulationPlanFixtureBuilder.BuildValidationShieldGallery(plan)
                : PendingDecomposePlanAdapter.ToPlan(plan, plan.CreatedAt ?? DateTimeOffset.UtcNow) with
                {
                    Summary = "INTERACTIVE PREVIEW — approval-stop changes are temporary and reset when this window closes. " +
                              plan.Group.Summary,
                };
        }

        // Enable gate editing for pending inbox plans that have not yet started executing.
        // Synthesise a staged Plan so the viewer receives a non-null durablePlan and enables
        // its approval-stop controls.
        var isPendingPlanEdit = false;
        if (durablePlan is null && livePlan is not null && !isInteractiveVisualizationFixture)
        {
            durablePlan = PendingDecomposePlanAdapter.ToPlan(livePlan, livePlan.CreatedAt ?? DateTimeOffset.UtcNow);
            isPendingPlanEdit = true;
        }

        // Mutable reference so that gate edits keep the execution-action closure in sync
        // with the latest persisted revision.
        var latestLivePlan = livePlan;
        var latestInboxMessageId = livePlan is not null
            ? DecomposePlanInbox.BuildMessageId(livePlan)
            : (string?)null;

        var displayedPlan = durablePlan is not null
            ? PendingDecomposePlanAdapter.FromPlan(durablePlan)
            : livePlan ?? plan;
        var activeBranch = _currentWorkspace is null ? null : ReadGitBranch(_currentWorkspace.FolderPath);
        Func<DecomposePlanActionDefinition, Task<bool>>? applyAction =
            livePlan is not null
                ? ApplyFromViewerAsync
                : null;
        PlanViewerWindow? win = null;
        Action<Plan>? onGatesChanged = durablePlan is not null &&
                                       !PlanLifecycleStatus.IsTerminal(durablePlan.LifecycleStatus)
            ? isPendingPlanEdit
                ? gatedPlan =>
                  {
                      // Persist gate edits to the pending plan store, recompute revision,
                      // and atomically replace the host-owned inbox message.
                      var pendingStore = new PendingDecomposePlanStore(_currentWorkspace!.SquadFolderPath);
                      var branchNow = _currentWorkspace is null ? null : ReadGitBranch(_currentWorkspace.FolderPath);
                      var result = PendingPlanGateEditor.Apply(
                          gatedPlan, latestInboxMessageId, pendingStore, _inboxStore, branchNow);
                      latestLivePlan = result.UpdatedPlan;
                      latestInboxMessageId = result.NewInboxMessageId ?? latestInboxMessageId;
                      win?.RefreshPlan(
                          PendingDecomposePlanAdapter.FromPlan(result.SyntheticDurablePlan),
                          result.SyntheticDurablePlan);
                      if (_inboxStore is not null)
                          _inboxPanel?.Refresh(_inboxStore.LoadAll());
                  }
                : isInteractiveVisualizationFixture
                    ? gatedPlan =>
                      {
                          // Intentionally refresh only this window. The sandbox never touches
                          // PlanStore, tasks.md, Inbox content, or execution state.
                          win?.RefreshPlan(PendingDecomposePlanAdapter.FromPlan(gatedPlan), gatedPlan);
                      }
                    : gatedPlan =>
                  {
                      // The viewer may have been open while an approval was accepted. Merge its
                      // design edit into the latest store value so a stale snapshot can never
                      // remove or retarget that newly durable human decision.
                      var currentPlan = _planStore?.Load(gatedPlan.PlanId);
                      var planToPublish = currentPlan is null
                          ? gatedPlan
                          : PlanGateManager.ApplyEditableGateChanges(currentPlan, gatedPlan);
                      PublishPlanProgress(planToPublish);
                      _ = RefreshApprovalRequestAfterGateGuidanceEditAsync(planToPublish);
                      // Refresh the existing viewer in place so its handlers capture the newly saved
                      // immutable Plan without closing, flashing, or losing the window placement.
                      win?.RefreshPlan(PendingDecomposePlanAdapter.FromPlan(planToPublish), planToPublish);
                  }
            : null;
        Action<Plan>? onStartPlan = durablePlan?.LifecycleStatus == PlanLifecycleStatus.Approved
            ? p => _ = QueueOrStartDurablePlanAsync(p)
            : null;
        var isSafelyResumable = durablePlan is not null &&
                                PlanRecoveryResumePolicy.IsSafelyResumable(durablePlan);
        Action<Plan>? onResumePlan = durablePlan is not null &&
                                    !PlanLifecycleStatus.IsTerminal(durablePlan.LifecycleStatus)
            ? p =>
              {
                  var current = _planStore?.Load(p.PlanId) ?? p;
                  if (current.IsPaused &&
                      current.LifecycleStatus == PlanLifecycleStatus.Executing &&
                      string.Equals(_activeDecomposeGroupId, current.PlanId, StringComparison.Ordinal) &&
                      IsLoopRunning)
                  {
                      CancelPlanPauseAfterCurrentStep(current);
                      return;
                  }
                  if (!TrySetPlanPauseState(current, pause: false, out var resumed, out var resumeError))
                  {
                      ReportPlanActionIssue(
                          current.PlanId,
                          "Plan still paused",
                          resumeError ?? "SquadDash could not save the request to resume this plan.");
                      return;
                  }
                  ClearPlanActionIssue(current.PlanId);
                  var executingWithoutRunner = resumed.LifecycleStatus == PlanLifecycleStatus.Executing &&
                                               (!IsLoopRunning || !string.Equals(
                                                   _activeDecomposeGroupId,
                                                   resumed.PlanId,
                                                   StringComparison.Ordinal));
                  if (resumed.LifecycleStatus == PlanLifecycleStatus.Approved ||
                      PlanRecoveryResumePolicy.IsSafelyResumable(resumed) ||
                      executingWithoutRunner)
                  {
                      if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
                          ScheduleApprovalResumeWhenIdle(resumed.PlanId);
                      else
                          _ = StartOrResumeDurablePlanAsync(resumed);
                  }
              }
            : null;
        Action<Plan>? onPausePlan = durablePlan is not null &&
                                     !PlanLifecycleStatus.IsTerminal(durablePlan.LifecycleStatus)
            ? p =>
              {
                  var current = _planStore?.Load(p.PlanId) ?? p;
                  if (current.LifecycleStatus == PlanLifecycleStatus.Executing &&
                      string.Equals(_activeDecomposeGroupId, current.PlanId, StringComparison.Ordinal) &&
                      IsLoopRunning)
                  {
                      RequestPlanPauseAfterCurrentStep(current);
                      return;
                  }

                  if (!TrySetPlanPauseState(current, pause: true, out _, out var pauseError))
                  {
                      ReportPlanActionIssue(
                          current.PlanId,
                          "Pause not saved",
                          pauseError ?? "SquadDash could not save the pause request.");
                      return;
                  }
                  ClearPlanActionIssue(current.PlanId);
              }
            : null;
        var interruptedTaskId = durablePlan?.InterruptionData?.InterruptedTaskId;
        PlanRecoveryActionSetPresentation? ResolveInterruptedActionSet(Plan current)
        {
            var currentTaskId = current.InterruptionData?.InterruptedTaskId;
            return current.LifecycleStatus == PlanLifecycleStatus.Interrupted &&
                   !string.IsNullOrWhiteSpace(currentTaskId)
                ? PlanRecoveryActionSetBuilder.Build(
                    current,
                    currentTaskId!,
                    ReadCachedRecoveryHeadCommit(),
                    (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant),
                    includeEndPlan: PlanRecoveryControlPolicy.HasActionableInterruption(current),
                    correctionActivity: PlanTaskCorrectionActivityPolicy.Resolve(
                        _pendingPlanTaskCorrectionContext,
                        current.PlanId,
                        currentTaskId!,
                        _isPromptRunning,
                        _pec.CurrentDispatchedItem?.Id,
                        _pec.CurrentDispatchedItem?.SourceTag))
                : null;
        }
        var interruptedRecoveryActionSet = durablePlan is null
            ? null
            : ResolveInterruptedActionSet(durablePlan);
        var interruptedRecoveryAction = interruptedRecoveryActionSet?.Primary;
        var hasRecoveryAssessment = durablePlan?.InterruptionData?.RecoveryAssessment is not null &&
                                    !string.IsNullOrWhiteSpace(interruptedTaskId);
        var durableReviewAttention = durablePlan is null
            ? null
            : PlanReviewAttentionPresentationResolver.Resolve(durablePlan, interruptedTaskId);
        Func<Plan, Task<bool>>? onAdoptVerifiedCommitRange =
            durableReviewAttention is not null
                ? planToAccept => AcceptInterruptedStepAfterReviewAsync(planToAccept)
                : durablePlan?.LifecycleStatus == PlanLifecycleStatus.Interrupted && !isSafelyResumable
                ? interruptedRecoveryAction?.Kind switch
                {
                    PlanRecoverySurfaceActionKind.AcceptStep =>
                        planToAccept => AcceptInterruptedStepAfterReviewAsync(planToAccept),
                    PlanRecoverySurfaceActionKind.ResumeVerification when !hasRecoveryAssessment =>
                        AssessInterruptedPlanFromDurableAsync,
                    PlanRecoverySurfaceActionKind.ContinueWorking when !hasRecoveryAssessment =>
                        async current =>
                        {
                            var currentTaskId = current.InterruptionData?.InterruptedTaskId;
                            if (string.IsNullOrWhiteSpace(currentTaskId)) return false;
                            if (string.Equals(
                                    interruptedRecoveryAction.ProtocolAction,
                                    "request-corrections",
                                    StringComparison.Ordinal))
                            {
                                await QueuePlanRecoveryCorrectionAsync(
                                    PendingDecomposePlanAdapter.FromPlan(current), currentTaskId);
                                return true;
                            }
                            return await RetryDecomposeTaskAsync(
                                PendingDecomposePlanAdapter.FromPlan(current), currentTaskId);
                        },
                    _ => null,
                }
                : null;
        var interruptedPrimaryActionLabel = interruptedRecoveryAction?.Label;
        var interruptedPrimaryActionHint = interruptedRecoveryAction?.Hint;
        Action<Plan>? onEndPlan = durablePlan is not null &&
                                  PlanRecoveryControlPolicy.HasActionableInterruption(durablePlan)
            ? EndInterruptedPlan
            : null;
        Action<Plan>? onContinueInterruptedTask =
            interruptedRecoveryActionSet?.Actions.FirstOrDefault(action =>
                action.Kind == PlanRecoverySurfaceActionKind.ContinueWorking) is { } continueAction
                ? current =>
                {
                    var currentTaskId = current.InterruptionData?.InterruptedTaskId;
                    if (string.IsNullOrWhiteSpace(currentTaskId)) return;
                    if (string.Equals(continueAction.ProtocolAction, "request-corrections", StringComparison.Ordinal))
                        _ = QueuePlanRecoveryCorrectionAsync(
                            PendingDecomposePlanAdapter.FromPlan(current), currentTaskId);
                    else
                        _ = RetryDecomposeTaskAsync(
                            PendingDecomposePlanAdapter.FromPlan(current), currentTaskId);
                }
                : hasRecoveryAssessment
            ? current =>
            {
                PrepareForHostRecoveryAction();
                var currentTaskId = current.InterruptionData?.InterruptedTaskId;
                if (!string.IsNullOrWhiteSpace(currentTaskId))
                    _ = RetryDecomposeTaskAsync(PendingDecomposePlanAdapter.FromPlan(current), currentTaskId);
            }
            : null;
        Action<Plan>? onReplanRemainingWork = durablePlan?.LifecycleStatus == PlanLifecycleStatus.Interrupted &&
                                              !string.IsNullOrWhiteSpace(interruptedTaskId)
            ? current =>
            {
                PrepareForHostRecoveryAction();
                var currentTaskId = current.InterruptionData?.InterruptedTaskId;
                if (!string.IsNullOrWhiteSpace(currentTaskId))
                    QueueDecomposeReplan(PendingDecomposePlanAdapter.FromPlan(current), currentTaskId);
            }
            : null;
        // Keep gate action callbacks stable for the lifetime of an open viewer. Its durable
        // plan can refresh from Awaiting -> Approved -> Awaiting without recreating the window;
        // each handler reloads current state before deciding whether the action is still valid.
        Action<Plan, string>? onApproveGate = durablePlan is not null
            ? (p, gateId) =>
              {
                  var gate = p.ApprovalGates.FirstOrDefault(g =>
                      string.Equals(g.GateId, gateId, StringComparison.Ordinal));
                  if (gate is not null) ApproveCurrentPlan(p, gate.GateId);
              }
            : null;
        Action<Plan, string>? onUnapproveGate = durablePlan is not null
            ? (p, gateId) =>
              {
                  _ = UnapproveCurrentPlanAsync(p, gateId);
              }
            : null;
        Func<DecomposedTaskGroup, PlanDefinitionEditResult>? saveDefinitionEdit =
            isPendingPlanEdit && _currentWorkspace is not null
                ? editedGroup =>
                  {
                      var routingPolicy = PlanAgentRoutingPolicy.Normalize(
                          _settingsSnapshot.PlanAgentRoutingPolicy);
                      if (!PlanAgentAssignmentCatalogValidator.TryValidate(
                              editedGroup,
                              _currentWorkspace.SquadFolderPath,
                              out var assignmentError,
                              requireExplicitRouting: routingPolicy != PlanAgentRoutingPolicy.Off,
                              enforceAssignments: routingPolicy != PlanAgentRoutingPolicy.Off))
                          throw new InvalidOperationException(
                              assignmentError ?? "The edited plan has invalid agent assignments.");
                      var pendingStore = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath);
                      var result = PendingPlanEditor.Apply(
                          editedGroup,
                          latestLivePlan?.CreatedAt ?? displayedPlan.CreatedAt ?? DateTimeOffset.UtcNow,
                          latestInboxMessageId,
                          pendingStore,
                          _inboxStore,
                          ReadGitBranch(_currentWorkspace.FolderPath));
                      latestLivePlan = result.UpdatedPlan;
                      latestInboxMessageId = result.NewInboxMessageId ?? latestInboxMessageId;
                      new PlanVisualizerReviewStore(_currentWorkspace.SquadFolderPath).Delete(groupId);
                      if (_inboxStore is not null)
                          _inboxPanel?.Refresh(_inboxStore.LoadAll());
                      return new PlanDefinitionEditResult(
                          result.UpdatedPlan,
                          result.SyntheticDurablePlan);
                  }
                : durablePlan is not null &&
                  !isInteractiveVisualizationFixture &&
                  !PlanLifecycleStatus.IsTerminal(durablePlan.LifecycleStatus) &&
                  _currentWorkspace is not null &&
                  _planStore is not null
                    ? editedGroup =>
                      {
                          var current = _planStore.Load(groupId)
                              ?? throw new InvalidOperationException(
                                  "The plan is no longer available. Reopen it from the Plans panel.");
                          if (PlanLifecycleStatus.IsTerminal(current.LifecycleStatus))
                              throw new InvalidOperationException(
                                  "Completed, stopped, or archived plans cannot be edited.");
                          if (!StagedPlanEditor.TryValidateUnlockedChanges(current, editedGroup, out var lockError))
                              throw new InvalidOperationException(lockError ??
                                  "The edit would change work that has already started.");
                          var routingPolicy = PlanAgentRoutingPolicy.Normalize(
                              _settingsSnapshot.PlanAgentRoutingPolicy);
                          if (!PlanAgentAssignmentCatalogValidator.TryValidate(
                                  editedGroup,
                                  _currentWorkspace.SquadFolderPath,
                                  out var assignmentError,
                                  requireExplicitRouting: routingPolicy != PlanAgentRoutingPolicy.Off,
                                  enforceAssignments: routingPolicy != PlanAgentRoutingPolicy.Off))
                              throw new InvalidOperationException(
                                  assignmentError ?? "The edited plan has invalid agent assignments.");

                          var applied = PlanRevisionApplier.Apply(
                              current,
                              editedGroup,
                              current.Revision,
                              DateTimeOffset.UtcNow);
                          if (applied.Outcome == PlanRevisionApplyOutcome.NoChanges)
                              return new PlanDefinitionEditResult(
                                  PendingDecomposePlanAdapter.FromPlan(current), current);
                          if (applied.Outcome != PlanRevisionApplyOutcome.Applied || applied.UpdatedPlan is null)
                              throw new InvalidOperationException(
                                  applied.Error ?? "The plan edit could not be applied.");
                          if (!TryPublishPlanProgress(applied.UpdatedPlan, out var publishError))
                              throw new InvalidOperationException(
                                  publishError ?? "The edited plan could not be saved.");
                          TrackAcceptedPlanRevisionForActiveExecution(current, applied.UpdatedPlan);
                          var activeExecutionPlanId = _conversationManager.ConversationState
                              .ActiveLoopExecution?.DecomposeGroupId;
                          var runnerPlanId = _activeDecomposeGroupId ?? activeExecutionPlanId;
                          if (string.Equals(runnerPlanId, current.PlanId, StringComparison.Ordinal))
                          {
                              _CodeHealthGroupRunner?.RefreshTaskDefinitions(applied.EffectiveGroup!);
                          }
                          return new PlanDefinitionEditResult(
                              PendingDecomposePlanAdapter.FromPlan(applied.UpdatedPlan),
                              applied.UpdatedPlan);
                      }
                    : null;
        Action<PendingDecomposePlan>? requestAiReview =
            isPendingPlanEdit && _currentWorkspace is not null
                ? current =>
                  {
                      StagedPlanRevisionOutlineStore.Save(_currentWorkspace.SquadFolderPath, current);
                      var queuedReview = EnqueuePrompt(
                          PlanVisualizerReviewParser.BuildPrompt(current),
                          isSystemInjected: true,
                          sourceTag: "plan-visualizer-review");
                      if (queuedReview is not null)
                      {
                          queuedReview.IsLocked = true;
                          queuedReview.DisplayLabel = "Review plan";
                          queuedReview.ReadOnlyDisplayText =
                              "AI is reviewing the current staged-plan revision. Results will appear in the Plan Visualizer.";
                          SyncQueuePanel();
                      }
                  }
                : null;
        Action<PlanVisualizerReviewPayload?>? saveReviewState =
            isPendingPlanEdit && _currentWorkspace is not null
                ? review =>
                  {
                      var store = new PlanVisualizerReviewStore(_currentWorkspace.SquadFolderPath);
                      if (review is null) store.Delete(groupId);
                       else store.Save(review);
                   }
                : null;
        Action<Dictionary<string, double>>? saveLayoutNudges = _currentWorkspace is not null
            ? nudges => new PlanVisualizerLayoutStore(_currentWorkspace.SquadFolderPath).Save(groupId, nudges)
            : null;
        win = new PlanViewerWindow(
            // Plan proposal actions and prose mirror their Inbox presentation rather than
            // inheriting the independently zoomable coordinator transcript size.
            displayedPlan, activeBranch, _inboxFontSize, applyAction, durablePlan,
            onGatesChanged, onStartPlan, onResumePlan, onPausePlan, onAdoptVerifiedCommitRange,
            interruptedPrimaryActionLabel, interruptedPrimaryActionHint, onEndPlan, onApproveGate,
            onUnapproveGate,
            viewPreflightChanges: ShowPlanPreflightChangesAsync,
            isPreflightWorkspaceClean: () => IsPlanPreflightWorkspaceCleanAsync(groupId),
            getPreflightDirtyPaths: () => GetPlanPreflightDirtyPathsAsync(groupId),
            broker: _broker,
            onOpenCommit: sha => _ = OpenCommitWithRemoteCheckAsync(sha),
            resolveAgentAvatar: ResolveAgentAvatarForPlanViewer,
            isTaskActivityActive: taskId => PlanTaskActivityPulsePolicy.MatchesLiveTarget(
                groupId,
                _loopRoundExecutionIdentity?.PlanId,
                _loopRoundExecutionIdentity?.TaskId,
                taskId),
            isPlanRunnerActive: current =>
                IsLoopRunning && string.Equals(
                    _activeDecomposeGroupId,
                    current.PlanId,
                    StringComparison.Ordinal),
            isRecoveryAssessmentActive: taskId =>
                string.Equals(_pendingPlanRecoveryAssessment?.Plan.Group.GroupId, groupId, StringComparison.Ordinal) &&
                string.Equals(_pendingPlanRecoveryAssessment?.TaskId, taskId, StringComparison.Ordinal),
            resolveTaskCorrectionActivity: taskId =>
            {
                var taskCorrection = PlanTaskCorrectionActivityPolicy.Resolve(
                    _pendingPlanTaskCorrectionContext,
                    groupId,
                    taskId,
                    _isPromptRunning,
                    _pec.CurrentDispatchedItem?.Id,
                    _pec.CurrentDispatchedItem?.SourceTag);
                return taskCorrection != PlanTaskCorrectionActivityState.None
                    ? taskCorrection
                    : PlanReviewCorrectionTaskActivityPolicy.Resolve(
                        _pendingPlanReviewCorrectionContext,
                        groupId,
                        taskId,
                        _isPromptRunning,
                        _pec.CurrentDispatchedItem?.Id,
                        _pec.CurrentDispatchedItem?.SourceTag);
            },
            isApprovalChangeActivityActive: gateId =>
                _activeGateChangeActivity is { } activity &&
                string.Equals(activity.PlanId, groupId, StringComparison.Ordinal) &&
                string.Equals(activity.GateId, gateId, StringComparison.Ordinal),
            initializeRepository: InitializeRepositoryForPlanAsync,
            onOpenCommits: commits =>
            {
                if (commits.Count > 0)
                    _ = OpenEvidenceViewerAsync(commits);
                else
                    _ = OpenInterruptedTaskReviewAsync(groupId, durablePlan?.Revision ?? displayedPlan.Revision);
            },
            resolveTaskFileChanges: task => _currentWorkspace is null
                ? Task.FromResult<IReadOnlyList<PlanTaskFileChange>>([])
                : PlanTaskFileDiffResolver.ResolveAsync(_currentWorkspace.FolderPath, task),
            onOpenTaskFileDiff: (task, path) => _ = OpenTaskFileDiffAsync(task, path),
            onContinueInterruptedTask: onContinueInterruptedTask,
            onReplanRemainingWork: onReplanRemainingWork,
            onOpenReviewCard: (current, taskId) => OpenReviewCard(current, taskId),
            onReviewSelection: (item, isChecked) =>
                RecordHumanReviewChecklistSelection(groupId, item, isChecked),
            onAddressUncheckedItems: (current, taskId, items) =>
            {
                var attention = PlanReviewAttentionPresentationResolver.Resolve(current, taskId);
                if (attention is not null)
                    QueueAddressUncheckedItems(
                        current,
                        taskId,
                        items,
                        attention.Gate.GateId);
            },
            saveDefinitionEdit: saveDefinitionEdit,
            requestAiReview: requestAiReview,
            saveReviewState: saveReviewState,
            saveLayoutNudges: saveLayoutNudges,
            onFixValidation: (current, validationId) =>
                _ = FixFailedPlanValidationAsync(current.PlanId, validationId),
            onReviewValidation: (current, validationId) =>
                OpenPlanValidationDetails(current.PlanId, validationId),
            getSettings: () => _settingsSnapshot,
            getAssignableAgents: GetAssignablePlanAgentsForViewer,
            resolveInterruptedActionSet: ResolveInterruptedActionSet,
            onOpenInterruptedChanges: current =>
                _ = OpenInterruptedTaskReviewAsync(current.PlanId, current.Revision),
            squadFolderPath: _currentWorkspace?.SquadFolderPath,
            onDescriptionLinkClicked: HandleTranscriptLinkClick)
        {
            Owner = CanShowOwnedWindow() ? this : null,
        };
        _openPlanViewerWindows.Add((groupId, win));
        win.Closed += (_, _) => _openPlanViewerWindows.RemoveAll(e =>
            ReferenceEquals(e.Window, win));
        win.Closed += (_, _) => FloatingWindowPositionStore.Shared.Save($"PlanViewer:{groupId}", win);
        win.RestoreWindowGeometry(FloatingWindowPositionStore.Shared);
        win.Show();
        if (_currentWorkspace is not null)
        {
            var existingReview = new PlanVisualizerReviewStore(_currentWorkspace.SquadFolderPath)
                .Load(displayedPlan.Group.GroupId, displayedPlan.Revision);
            if (existingReview is not null)
                win.SetReviewAnnotations(existingReview);

            var existingNudges = new PlanVisualizerLayoutStore(_currentWorkspace.SquadFolderPath)
                .Load(displayedPlan.Group.GroupId);
            if (existingNudges is { Count: > 0 })
                win.SetLayoutNudges(existingNudges);
        }

        async Task<bool> ApplyFromViewerAsync(DecomposePlanActionDefinition action)
        {
            try
            {
                if (_isPromptRunning &&
                    !DecomposePlanActionDispatchPolicy.CanApplyWhilePromptRunning(action.Action))
                {
                    UIErrorHelper.ShowWarning(
                        "Plan Action",
                        "Wait for the current prompt to finish before applying the task plan.");
                    return false;
                }
                // Use the latest live plan so execution seals the most recent gate revision,
                // not the revision that was displayed when the viewer was first opened.
                return await ApplyDecomposeDecisionAsync(latestLivePlan ?? displayedPlan, action.Action, action.Branch);
            }
            catch (PlanPreflightBlockedException)
            {
                throw;
            }
            catch (Exception ex)
            {
                HandleUiCallbackException("Decompose plan", ex);
                return false;
            }
        }

    }

    private (ImageSource? Image, string Initial, Brush Accent)? ResolveAgentAvatarForPlanViewer(string agentHandle)
    {
        // Plan agent handles may use the folder slug ("fact-checker") or a name-based
        // slug ("verity-cross"). Try AccentStorageKey first, then humanized name match.
        var card = _agents.FirstOrDefault(a =>
            string.Equals(a.AccentStorageKey, agentHandle, StringComparison.OrdinalIgnoreCase));
        if (card is null)
        {
            var humanized = AgentThreadRegistry.HumanizeAgentName(agentHandle);
            card = _agents.FirstOrDefault(a =>
                string.Equals(a.Name, humanized, StringComparison.OrdinalIgnoreCase));
        }
        if (card is null) return null;
        return (card.AgentImageSource, card.Initial, card.EffectiveAccentBrush);
    }

    private IReadOnlyList<RosterAgent> GetAssignablePlanAgentsForViewer()
    {
        if (_currentWorkspace is null) return [];
        var teamPath = Path.Combine(_currentWorkspace.SquadFolderPath, "team.md");
        var roster = PlanStepAgentResolver.ParseTeamMd(
            File.Exists(teamPath) ? File.ReadAllText(teamPath) : string.Empty);
        return roster
            .Where(agent => agent.IsActive)
            .OrderBy(agent => agent.Name, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private void CaptureExecutingPlanStepResult(string? rawResponse)
    {
        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        var dispatchedItem = _pec.CurrentDispatchedItem;
        // A stopped plan can retain a durable repair context while ordinary user prompts
        // drain. Those turns are not plan results and must never overwrite a valid pending
        // repair result merely because they happen before the plan is reclaimed.
        if (!PlanRepairReplayPolicy.ShouldCaptureTurnResponse(
                activeExecution,
                activePlanRuntime: _activeDecomposeGroupId is not null,
                hasDispatchedQueueItem: dispatchedItem is not null,
                dispatchedItemIsSystemInjected: dispatchedItem?.IsSystemInjected == true,
                dispatchedItemSourceTag: dispatchedItem?.SourceTag))
            return;
        if (_activeDecomposeGroupId is not null &&
            activeExecution?.DecomposeGroupId is not null &&
            !string.Equals(activeExecution.DecomposeGroupId, _activeDecomposeGroupId, StringComparison.Ordinal))
            return;

        _capturedTaskVerificationRawResponse = rawResponse;

        var inboxDelivery = ValidateDeliveredPlanInboxOpenPaths(rawResponse);
        var inboxDecision = PlanInboxLinkRepairPolicy.Evaluate(
            activeExecution?.PendingInboxLinkRepairError,
            inboxDelivery.HasInboxDelivery,
            inboxDelivery.Error);
        _capturedPlanInboxOpenPathError = inboxDecision.ResultError;
        var stagedInboxResponse = inboxDelivery.HasInboxDelivery
            ? rawResponse
            : activeExecution?.PendingInboxDeliveryRawResponse;
        if (activeExecution is not null &&
            (!string.Equals(
                 activeExecution.PendingInboxLinkRepairError,
                 inboxDecision.PendingRepairError,
                 StringComparison.Ordinal) ||
             !string.Equals(
                 activeExecution.PendingInboxDeliveryRawResponse,
                 stagedInboxResponse,
                 StringComparison.Ordinal)))
        {
            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with
                {
                    PendingInboxLinkRepairError = inboxDecision.PendingRepairError,
                    PendingInboxDeliveryRawResponse = stagedInboxResponse,
                });
            activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        }

        if (PlanTaskVerificationResultParser.TryParse(rawResponse, out var verificationResult, out var verificationError))
        {
            _capturedTaskVerificationResult = verificationResult;
            _capturedTaskVerificationResultError = null;
        }
        else
        {
            _capturedTaskVerificationResult = null;
            _capturedTaskVerificationResultError = verificationError;
        }

        // Try to capture a validation result first
        if (PlanValidationResultParser.TryParse(rawResponse, out var valResult, out var valError))
        {
            _capturedValidationResult = valResult;
            _capturedValidationResultError = null;
        }
        else
        {
            _capturedValidationResult = null;
            _capturedValidationResultError = valError;
        }

        var resultOutcome = DecomposeStepResultParser.ParseDetailed(
            rawResponse,
            activeExecution?.DecomposeGroupId ?? _activeDecomposeGroupId,
            activeExecution?.RecoveryTaskId ?? _CodeHealthGroupRunner?.CurrentStepId,
            activeExecution?.DecomposeRevision ?? _CodeHealthGroupRunner?.CurrentRevision,
            activeExecution?.PlanExecutionAttempt?.AttemptId);
        var result = resultOutcome.Candidate;
        var error = resultOutcome.Error;
        _capturedDecomposeStepResult = result;
        _capturedDecomposeStepResultError = error;
        _capturedDecomposeStepResultViolations = resultOutcome.Violations;
        foreach (var canonicalization in resultOutcome.Canonicalizations)
            SquadDashTrace.Write("PlanContract", $"Canonicalized result envelope: {canonicalization}.");

        // Persist the captured result durably so it survives process restart.
        try
        {
            if (activeExecution is null || !activeExecution.IsExecutingPlan)
                return;
            // Only persist an implementation-result repair. Verification and validation have
            // their own envelopes; treating either as a task repair can suppress their next
            // prompt and falsely count an undispatched repair as a second failure.
            if (!PlanRepairReplayPolicy.ShouldPersistTaskRepairResponse(activeExecution))
                return;

            if (!PlanRepairReplayPolicy.TryCreatePendingResult(
                    activeExecution, result, error, out var pending, out var rejection,
                    resultOutcome.Violations))
            {
                SquadDashTrace.Write("PlanRepair", $"Repair response was not persisted: {rejection}.");
                return;
            }

            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with { PendingRepairResult = pending });
            SquadDashTrace.Write("PlanRepair",
                $"Persisted repaired task result plan={pending!.GroupId} task={pending.TaskId} " +
                $"attempt={pending.AttemptId ?? "(legacy)"} before loop reclaim={_activeDecomposeGroupId is null}.");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("PlanRepair", $"Failed to persist pending repair result: {ex.Message}");
        }
    }

    private async Task<string?> PrepareExecutingPlanIterationAsync()
    {
        if (_currentWorkspace is null || _activeDecomposeGroupId is null || _CodeHealthGroupRunner is null)
            throw new InvalidOperationException("The active plan execution state is incomplete.");

        _capturedDecomposeStepResult = null;
        _capturedDecomposeStepResultError = null;
        _capturedDecomposeStepResultViolations = [];
        _capturedPlanInboxOpenPathError = null;
        _capturedDecomposeTranscriptCommit = null;
        _capturedValidationResult = null;
        _capturedValidationResultError = null;
        _capturedTaskVerificationResult = null;
        _capturedTaskVerificationResultError = null;

        var activeExec = _conversationManager.ConversationState.ActiveLoopExecution;
        if (activeExec?.PendingInboxDeliveryRawResponse is not null &&
            activeExec.PendingInboxLinkRepairError is null &&
            activeExec.RepairRequestCount == 0 &&
            activeExec.PendingRepairResult is null)
        {
            activeExec = PlanInboxLinkRepairPolicy.ClearPendingDelivery(activeExec);
            _conversationManager.UpdateActiveLoopExecutionState(activeExec);
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                "INBOX_SAVE: discarded an unaccepted staged delivery at a fresh plan-iteration boundary");
        }
        if (activeExec?.IsExecutingPlan == true)
        {
            var phasePlan = _planStore?.Load(_activeDecomposeGroupId)
                ?? throw new InvalidOperationException($"Plan {_activeDecomposeGroupId} could not be loaded for branch verification.");
            var phaseLease = activeExec.BranchLease;
            if (phaseLease is null)
            {
                var canonicalHead = (await RunGitAsync(
                    _currentWorkspace.FolderPath,
                    $"rev-parse --verify \"refs/heads/{phasePlan.Branch.Replace("\"", "\\\"")}^{{commit}}\"")).Trim();
                phaseLease = new PlanBranchLease(
                    phasePlan.PlanId,
                    phasePlan.Revision,
                    phasePlan.Branch,
                    activeExec.TaskBaselineCommit ?? canonicalHead,
                    DateTimeOffset.UtcNow);
            }
            var phaseBranch = await EnforcePlanBranchLeaseAsync(
                phaseLease,
                candidateCommit: null,
                mutationAllowed: false);
            if (!phaseBranch.CanContinue)
            {
                _planBranchLeasePausePending = true;
                throw new PlanBranchLeaseViolationException(phaseBranch.Message);
            }
            if (phaseBranch.Repaired)
                ScheduleDecomposeSystemEntry(phaseBranch.Message);
        }
        if (activeExec?.VerificationEnvelopeRepairCount is not > 0)
            _capturedTaskVerificationRawResponse = null;
        if (activeExec?.ActiveVerificationTaskId is { } verificationTaskId)
        {
            var pending = activeExec.PendingTaskVerification
                ?? throw new InvalidOperationException($"Task {verificationTaskId} has no persisted candidate handoff to verify.");
            var plan = _planStore?.Load(_activeDecomposeGroupId)
                ?? throw new InvalidOperationException($"Plan {_activeDecomposeGroupId} could not be loaded for verification.");
            if (!PlanTaskStatus.IsVerifying(plan.Tasks.FirstOrDefault(candidate =>
                    string.Equals(candidate.TaskId, verificationTaskId, StringComparison.Ordinal))?.Status))
            {
                plan = PlanStoreUpdater.ApplyTaskVerificationStarted(plan, verificationTaskId);
                if (!TryPublishPlanProgress(plan, out var verificationStartError))
                    throw new InvalidOperationException(
                        $"Task {verificationTaskId} verification started, but its active state could not be persisted: " +
                        verificationStartError);
            }
            var task = plan.Tasks.FirstOrDefault(candidate =>
                string.Equals(candidate.TaskId, verificationTaskId, StringComparison.Ordinal))
                ?? throw new InvalidOperationException($"Plan {_activeDecomposeGroupId} is missing verification task {verificationTaskId}.");
            var candidate = JsonSerializer.Deserialize<DecomposeStepResult>(pending.CandidateResultJson)
                ?? throw new InvalidDataException($"Task {verificationTaskId} has an unreadable candidate result.");
            var isEnvelopeRepair = activeExec.VerificationEnvelopeRepairCount > 0;
            string verificationPrompt;
            if (isEnvelopeRepair)
            {
                verificationPrompt = PlanTaskVerificationPromptBuilder.BuildEnvelopeRepair(
                    plan,
                    task,
                    candidate,
                    _capturedTaskVerificationRawResponse,
                    _capturedTaskVerificationResultError);
            }
            else
            {
                var diffSummary = await RunGitAsync(
                    _currentWorkspace.FolderPath,
                    $"diff --stat \"{pending.BaselineCommit}\"..\"{candidate.VerificationTargetCommit}\"");
                verificationPrompt = PlanTaskVerificationPromptBuilder.Build(
                    plan,
                    task,
                    candidate,
                    pending.BaselineCommit,
                    pending.ChangedFiles,
                    diffSummary.Trim());
            }
            AppendPlanExecutionJournal(
                plan.PlanId,
                task.TaskId,
                isEnvelopeRepair ? "verification-envelope-repair-prompt-sent" : "verification-prompt-sent",
                verificationPrompt);
            return verificationPrompt;
        }

        if (activeExec?.ActiveValidationId is { } activeValidationId)
        {
            var plan = _planStore?.Load(_activeDecomposeGroupId)
                ?? throw new InvalidOperationException($"Plan {_activeDecomposeGroupId} could not be loaded for validation.");
            var validation = plan.Validations?.FirstOrDefault(candidate =>
                string.Equals(candidate.ValidationId, activeValidationId, StringComparison.Ordinal))
                ?? throw new InvalidOperationException(
                    $"Plan {_activeDecomposeGroupId} is missing active validation {activeValidationId}.");
            if (activeExec.ValidationRepairCount > 0 &&
                !string.IsNullOrWhiteSpace(activeExec.ValidationRepairReason))
            {
                var repairHead = (await RunGitAsync(
                    _currentWorkspace.FolderPath,
                    "rev-parse HEAD")).Trim();
                return PlanValidationRepairPrompt.Build(
                    plan,
                    validation,
                    activeExec.ValidationRepairReason,
                    repairHead);
            }

            var validationHead = (await RunGitAsync(
                _currentWorkspace.FolderPath,
                "rev-parse HEAD")).Trim();
            return PlanValidationPromptBuilder.Build(plan, validation, validationHead);
        }

        if (_CodeHealthGroupRunner.CurrentStepId is null || _CodeHealthGroupRunner.CurrentRevision is null)
            throw new InvalidOperationException(
                $"Plan {_activeDecomposeGroupId} has no dependency-eligible step to execute.");

        var durablePlan = _planStore?.Load(_activeDecomposeGroupId)
            ?? throw new InvalidDataException(
                $"Plan {_activeDecomposeGroupId} has no durable execution contract.");
        var group = PendingDecomposePlanAdapter.FromPlan(durablePlan).Group with
        {
            HostRevision = durablePlan.Revision,
        };
        var dispatchLease = activeExec?.BranchLease;
        if (dispatchLease is null ||
            !string.Equals(dispatchLease.PlanId, _activeDecomposeGroupId, StringComparison.Ordinal) ||
            !string.Equals(dispatchLease.Revision, group.HostRevision, StringComparison.Ordinal) ||
            !string.Equals(dispatchLease.CanonicalBranch, group.Branch, StringComparison.Ordinal))
        {
            var canonicalHead = (await RunGitAsync(
                _currentWorkspace.FolderPath,
                $"rev-parse --verify \"refs/heads/{group.Branch.Replace("\"", "\\\"")}^{{commit}}\"")).Trim();
            dispatchLease = new PlanBranchLease(
                _activeDecomposeGroupId,
                group.HostRevision ?? _CodeHealthGroupRunner.CurrentRevision ?? string.Empty,
                group.Branch,
                canonicalHead,
                DateTimeOffset.UtcNow);
        }
        var dispatchBranch = await EnforcePlanBranchLeaseAsync(
            dispatchLease,
            candidateCommit: null,
            mutationAllowed: false);
        if (!dispatchBranch.CanContinue)
        {
            _planBranchLeasePausePending = true;
            throw new PlanBranchLeaseViolationException(dispatchBranch.Message);
        }

        string? continuationContext = null;
        if (_decomposeContinuationTaskId is not null)
        {
            if (!string.Equals(
                    _decomposeContinuationTaskId,
                    _CodeHealthGroupRunner.CurrentStepId,
                    StringComparison.Ordinal))
                throw new InvalidOperationException(
                    $"Preserved work belongs to task {_decomposeContinuationTaskId}, but the next eligible task is " +
                    $"{_CodeHealthGroupRunner.CurrentStepId}.");

            var status = await RunGitAsync(
                _currentWorkspace.FolderPath,
                "status --porcelain --untracked-files=all");
            var tasksRelativePath = await GetTasksRepositoryRelativePathAsync(_currentWorkspace.FolderPath);
            var allowed = tasksRelativePath is null ? Array.Empty<string>() : new[] { tasksRelativePath };
            DecomposeWorktreePolicy.HasOnlyAllowedChanges(status, allowed, out var currentPaths);
            if (!DecomposeWorktreePolicy.MatchesConfirmedPaths(currentPaths, _decomposeContinuationPaths))
                throw new InvalidOperationException(
                    "The preserved worktree changed after recovery was confirmed. Reopen the recovery action and review the files again.");

            var taskId = _decomposeContinuationTaskId;
            var paths = _decomposeContinuationPaths;
            _decomposeContinuationTaskId = null;
            _decomposeContinuationPaths = [];
            continuationContext =
                $"RECOVERY CONTEXT (host-owned): Continue task {taskId} from the existing uncommitted work in these paths:\n" +
                string.Join("\n", paths.Select(path => $"- {path}")) +
                "\nInspect the existing diff and repository build configuration, finish the task without discarding valid work, " +
                "and commit the validated task changes in one or more meaningful commits. Do not rewrite useful commit history and do not commit tasks.md.";
        }
        else
        {
            await EnsurePlanWorktreeReadyAsync(_currentWorkspace.FolderPath);
        }
        var currentTaskId = _CodeHealthGroupRunner.CurrentStepId;
        var currentTask = group.Tasks.FirstOrDefault(task =>
            string.Equals(task.Id, currentTaskId, StringComparison.Ordinal));
        if (currentTask is null)
            throw new InvalidDataException($"Plan {_activeDecomposeGroupId} is missing task {currentTaskId}.");

        if (durablePlan is not null && currentTaskId is not null)
        {
            var startedPlan = PlanStoreUpdater.ApplyTaskStarted(durablePlan, currentTaskId);
            if (!ReferenceEquals(startedPlan, durablePlan) &&
                !TryPublishPlanProgress(startedPlan, out var startProjectionError))
                SquadDashTrace.Write(
                    "PlanProgress",
                    $"Could not publish executing task {currentTaskId}: {startProjectionError}");
        }

        var execution = _conversationManager.ConversationState.ActiveLoopExecution
            ?? throw new InvalidOperationException("The active plan execution was not persisted.");
        var observedHead = (await RunGitAsync(
            _currentWorkspace.FolderPath,
            "rev-parse HEAD")).Trim();
        _decomposeIterationBaselineCommit =
            string.Equals(execution.RecoveryTaskId, currentTaskId, StringComparison.Ordinal) &&
            !string.IsNullOrWhiteSpace(execution.TaskBaselineCommit)
                ? execution.TaskBaselineCommit
                : observedHead;

        var policy = PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy);
        var assignments = policy == PlanAgentRoutingPolicy.Off ? null : currentTask.AgentAssignments;
        if (assignments is { Count: > 1 })
            throw new InvalidOperationException(
                $"Task {currentTaskId} assigns {assignments.Count} primary agents. " +
                "Concurrent primary writers are disabled until SquadDash can provision isolated worktrees.");
        PlanExecutionAttemptState? attempt = null;
        var createdNewExecutionAttempt = false;
        string? assignedAgentDisplayName = null;
        if (assignments is { Count: 1 })
        {
            attempt = execution.PlanExecutionAttempt;
            if (attempt is null ||
                !string.Equals(attempt.TaskId, currentTaskId, StringComparison.Ordinal) ||
                !string.Equals(attempt.Revision, _CodeHealthGroupRunner.CurrentRevision, StringComparison.Ordinal) ||
                !string.Equals(attempt.Status, "active", StringComparison.Ordinal))
            {
                var teamPath = Path.Combine(_currentWorkspace.SquadFolderPath, "team.md");
                var roster = PlanStepAgentResolver.ParseTeamMd(
                    File.Exists(teamPath) ? File.ReadAllText(teamPath) : string.Empty);
                assignedAgentDisplayName = roster.FirstOrDefault(agent =>
                    string.Equals(agent.Handle, assignments[0].AgentHandle, StringComparison.OrdinalIgnoreCase))?.Name;
                attempt = PlanExecutionAttemptState.Create(
                    _activeDecomposeGroupId,
                    currentTaskId!,
                    _CodeHealthGroupRunner.CurrentRevision ?? string.Empty,
                    _currentWorkspace.FolderPath,
                    _currentWorkspace.SquadFolderPath,
                    assignments,
                    roster);
                createdNewExecutionAttempt = true;
            }
        }
        else if (policy != PlanAgentRoutingPolicy.Off &&
                 string.Equals(currentTask.AgentRoutingMode, "generic", StringComparison.Ordinal))
        {
            attempt = execution.PlanExecutionAttempt;
            if (attempt is null ||
                !attempt.AllowsGenericPrimary ||
                !string.Equals(attempt.TaskId, currentTaskId, StringComparison.Ordinal) ||
                !string.Equals(attempt.Revision, _CodeHealthGroupRunner.CurrentRevision, StringComparison.Ordinal) ||
                !string.Equals(attempt.Status, "active", StringComparison.Ordinal))
            {
                attempt = PlanExecutionAttemptState.CreateGeneric(
                    _activeDecomposeGroupId,
                    currentTaskId!,
                    _CodeHealthGroupRunner.CurrentRevision ?? string.Empty,
                    _currentWorkspace.FolderPath);
                createdNewExecutionAttempt = true;
            }
        }

        var attemptHistory = (execution.PreviousPlanExecutionAttempts ?? []).ToList();
        if (execution.PlanExecutionAttempt is { } replacedAttempt &&
            !string.Equals(replacedAttempt.AttemptId, attempt?.AttemptId, StringComparison.Ordinal))
        {
            attemptHistory.Add(replacedAttempt with {
                Status = string.Equals(replacedAttempt.Status, "active", StringComparison.Ordinal)
                    ? "superseded"
                    : replacedAttempt.Status
            });
        }
        var sameRecoveryTask = string.Equals(
            execution.RecoveryTaskId,
            currentTaskId,
            StringComparison.Ordinal);
        var sameRecoveryAttempt = sameRecoveryTask && string.Equals(
            execution.RecoveryAttemptId,
            attempt?.AttemptId,
            StringComparison.Ordinal);
        _conversationManager.UpdateActiveLoopExecutionState(
            execution with {
                PlanExecutionAttempt = attempt,
                PreviousPlanExecutionAttempts = attemptHistory,
                RecoveryTaskId = currentTaskId,
                RecoveryAttemptId = attempt?.AttemptId,
                RepairRequestCount = sameRecoveryAttempt ? execution.RepairRequestCount : 0,
                FreshAttemptCount = sameRecoveryTask ? execution.FreshAttemptCount : 0,
                TaskBaselineCommit = sameRecoveryTask
                    ? execution.TaskBaselineCommit ?? _decomposeIterationBaselineCommit
                    : _decomposeIterationBaselineCommit,
                BranchLease = dispatchLease with
                {
                    BaselineCommit = _decomposeIterationBaselineCommit!,
                    AcquiredAt = DateTimeOffset.UtcNow,
                },
            });
        if (createdNewExecutionAttempt && attempt is not null)
        {
            var currentTaskIndex = group.Tasks.ToList().FindIndex(task =>
                string.Equals(task.Id, currentTaskId, StringComparison.Ordinal));
            ScheduleDecomposeSystemEntry(
                PlanExecutionAttemptPresentation.BuildStartedMessage(
                    currentTaskIndex >= 0 ? (currentTaskIndex + 1).ToString() : null,
                    currentTask.Title ?? currentTask.Description,
                    assignedAgentDisplayName));
        }
        var routingContext = policy == PlanAgentRoutingPolicy.Off
            ? "## Serialized Plan Execution Safety\n\nAgent routing is disabled. " +
              "Use at most one write-capable primary worker for this task; do not run concurrent writers in the active worktree."
            : DecomposePlanningInstructions.BuildPlanStepRoutingContext(
                _currentWorkspace.SquadFolderPath,
                currentTaskId!,
                _CodeHealthGroupRunner.GetCurrentStepTitle() ?? currentTaskId!,
                _CodeHealthGroupRunner.GetCurrentStepDescription() ?? string.Empty,
                assignments,
                _CodeHealthGroupRunner.CurrentRevision,
                attempt,
                string.Equals(currentTask.AgentRoutingMode, "generic", StringComparison.Ordinal)
                    ? currentTask.GenericAgentReason
                    : null,
                group.Branch);
        string? assessedRecoveryContext = null;
        if (execution.AssessedRecoveryContinuation is { } assessed)
        {
            if (!string.Equals(assessed.PlanId, _activeDecomposeGroupId, StringComparison.Ordinal) ||
                !string.Equals(assessed.TaskId, currentTaskId, StringComparison.Ordinal))
                throw new InvalidOperationException(
                    $"Assessed recovery context belongs to {assessed.PlanId}/{assessed.TaskId}, but the next task is " +
                    $"{_activeDecomposeGroupId}/{currentTaskId}.");
            assessedRecoveryContext =
                $"RECOVERY ASSESSMENT (host-owned): AI previously classified task {currentTaskId} as partially complete.\n" +
                $"Assessment summary: {assessed.Summary}\nRemaining work:\n" +
                string.Join("\n", assessed.RemainingWork.Select(item => $"- {item}")) +
                "\nInspect and preserve valid existing work. Complete only the remaining work, validate the whole task, " +
                "and return the normal DECOMPOSE_STEP_RESULT_JSON payload. Do not repeat completed work and do not commit tasks.md.";
        }

        var effectiveProofRequirements = currentTask.ProofRequirements;
        if (effectiveProofRequirements is not { Count: > 0 } && durablePlan is not null)
        {
            effectiveProofRequirements = durablePlan.Tasks.FirstOrDefault(task =>
                    string.Equals(task.TaskId, currentTaskId, StringComparison.Ordinal))
                ?.ProofRequirements
                ?.Select(requirement => new DecomposedTaskProofRequirement(
                    requirement.RequirementId,
                    requirement.ProofType,
                    requirement.Description,
                    requirement.Question,
                    requirement.AccessMode,
                    requirement.VerificationRecipe,
                    requirement.FixtureTaskId,
                    requirement.FixtureOutputId,
                    requirement.Title))
                .ToArray();
        }
        string? proofContext = null;
        if (effectiveProofRequirements is { Count: > 0 })
        {
            var resultRequirements = PlanProofCapabilityPolicy.ResultEnvelopeRequirements(
                effectiveProofRequirements);
            var hostRequirements = effectiveProofRequirements
                .Where(requirement =>
                    PlanProofCapabilityPolicy.Classify(requirement.ProofType) == PlanProofExecutorKind.Host)
                .ToArray();
            proofContext =
                "## Required Task Proofs (approved plan contract)\n\n" +
                (resultRequirements.Count > 0
                    ? "A complete DECOMPOSE_STEP_RESULT_JSON must include `proofEvidence`, with one exact " +
                      "requirementId/proofType match for every worker-owned item below.\n" +
                      JsonSerializer.Serialize(resultRequirements)
                    : "No worker-owned proof evidence is required in the result envelope.") +
                (hostRequirements.Length > 0
                    ? "\n\nSquadDash records these host-owned proofs from validated execution evidence; do not claim or fabricate them:\n" +
                      JsonSerializer.Serialize(hostRequirements)
                    : string.Empty);
        }

        string? planExecutionContext = null;
        string? automaticContinuationContext = null;
        if (durablePlan is not null)
        {
            var durableTask = durablePlan.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, currentTaskId, StringComparison.Ordinal));
            if (durableTask is not null)
            {
                var projectionPath = PlanExecutionProjectionWriter.Write(
                    _conversationManager.ConversationStore.GetWorkspaceStateDirectory(
                        _currentWorkspace.FolderPath),
                    durablePlan);
                planExecutionContext = PlanExecutionContextBuilder.Build(durablePlan, durableTask) +
                    $"\n\nGenerated plan projection: `{projectionPath}`. The context above is authoritative for this turn; " +
                    "the projection is an inspectable plan-only reference and tasks.md is not an execution source. " +
                    "Inspect the current implementation and tests before changing anything. Treat requirements already satisfied by earlier or concurrent work as complete, avoid duplicating equivalent work, and report either the terminal changed commit or a `verified-no-op` result with requirement-scoped repository evidence from the current inspected snapshot; SquadDash records the full commit range without attributing concurrent commits to this step. " +
                    "Capability discovery must be non-mutating: never run a mutating subcommand followed by `--help` in the active workspace. Inspect top-level help, installed source, or official documentation, or use an isolated disposable copy. Specifically, never run `squad upgrade --help`; Squad CLI 0.10 executes the upgrade instead of showing subcommand help.";
                if (!string.IsNullOrWhiteSpace(durableTask.ResumeInstructions))
                {
                    automaticContinuationContext =
                        "## Focused automatic continuation (host-owned)\n\n" +
                        "The approved task contract above remains authoritative. Preserve completed work and focus this attempt on:\n" +
                        durableTask.ResumeInstructions +
                        "\n\nValidate the whole task before returning the normal result envelope. " +
                        "Do not omit contract requirements merely because this retry is focused.";
                }
            }
        }

        string? verificationReworkContext = null;
        if (!string.IsNullOrWhiteSpace(execution.VerificationReworkInstructions))
        {
            verificationReworkContext =
                "## Bounded verification rework\n\nThe independent verification pass found the following missing or overstated work. " +
                "Correct only these findings, then return a fresh complete task handoff:\n" +
                execution.VerificationReworkInstructions;
        }

        var verificationOnlyContext = PlanTaskExecutionPolicy.IsVerificationOnly(currentTask)
            ? "## Verification-Only Execution (host-owned)\n\n" +
              "This approved task verifies existing work and must not change source files or create a bookkeeping commit. " +
              "Run the declared checks against the current worktree, return their exact proof evidence, set `completionKind` " +
              "to `verified-no-op`, set `commit` to null, and set `evaluatedCommit` to the current HEAD. SquadDash will " +
              "accept the proof directly without a second independent review."
            : null;

        var contexts = new[]
            { planExecutionContext, continuationContext, assessedRecoveryContext, verificationReworkContext,
              automaticContinuationContext, verificationOnlyContext, routingContext, proofContext }
            .Where(value => !string.IsNullOrWhiteSpace(value));
        var taskContext = string.Join("\n\n", contexts);
        if (durablePlan is not null)
        {
            AppendPlanExecutionJournal(
                durablePlan.PlanId,
                currentTaskId!,
                string.IsNullOrWhiteSpace(verificationReworkContext)
                    ? "task-context-sent"
                    : "bounded-rework-context-sent",
                taskContext);
        }
        return taskContext;
    }

    private string? AppendPlanExecutionJournal(
        string planId,
        string taskId,
        string phase,
        string content)
    {
        if (_currentWorkspace is null) return null;
        try
        {
            var stateDirectory = _conversationManager.ConversationStore.GetWorkspaceStateDirectory(
                _currentWorkspace.FolderPath);
            var path = PlanExecutionJournal.Append(stateDirectory, planId, taskId, phase, content);
            return path;
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("PlanJournal", $"Could not append {phase} for {planId}/{taskId}: {ex.Message}");
            return null;
        }
    }

    private PlanExecutionAttemptState? CreatePlanExecutionAttempt(
        string groupId,
        string taskId,
        string revision,
        DecomposedSubTask task,
        IReadOnlyList<DecomposedAgentAssignment>? assignments,
        string routingPolicy)
    {
        if (_currentWorkspace is null || routingPolicy == PlanAgentRoutingPolicy.Off)
            return null;

        if (assignments is { Count: 1 })
        {
            var teamPath = Path.Combine(_currentWorkspace.SquadFolderPath, "team.md");
            var roster = PlanStepAgentResolver.ParseTeamMd(
                File.Exists(teamPath) ? File.ReadAllText(teamPath) : string.Empty);
            return PlanExecutionAttemptState.Create(
                groupId,
                taskId,
                revision,
                _currentWorkspace.FolderPath,
                _currentWorkspace.SquadFolderPath,
                assignments,
                roster);
        }

        return string.Equals(task.AgentRoutingMode, "generic", StringComparison.Ordinal)
            ? PlanExecutionAttemptState.CreateGeneric(
                groupId,
                taskId,
                revision,
                _currentWorkspace.FolderPath)
            : null;
    }

    private async Task FinalizeExecutingPlanIterationAsync()
    {
        if (_currentWorkspace is null || _activeDecomposeGroupId is null || _CodeHealthGroupRunner is null)
            return;

        var groupId = _activeDecomposeGroupId;
        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        var taskId = _CodeHealthGroupRunner.CurrentStepId ?? "unknown task";
        var revision = _CodeHealthGroupRunner.CurrentRevision ?? string.Empty;
        var hasTerminalResult = PlanRepairReplayPolicy.HasMatchingTerminalResult(
            activeExecution,
            groupId,
            revision,
            taskId,
            _capturedDecomposeStepResult);
        if (_loopController.StopState != LoopStopState.None && !hasTerminalResult)
        {
            SquadDashTrace.Write(
                "Loop",
                $"Skipping plan finalization after stop was requested plan={groupId} task={taskId}; no matching terminal result was captured.");
            return;
        }
        if (_loopController.StopState != LoopStopState.None)
        {
            SquadDashTrace.Write(
                "Loop",
                $"Finalizing captured terminal result before honoring stop plan={groupId} task={taskId}.");
        }

        // Candidate task work is verified before it can become accepted plan progress.
        if (activeExecution is not null &&
            (activeExecution.ActiveVerificationTaskId is not null || activeExecution.ActiveValidationId is not null))
        {
            var phasePlan = _planStore?.Load(groupId);
            var phaseLease = activeExecution.BranchLease;
            if (phaseLease is null && phasePlan is not null)
            {
                var canonicalHead = (await RunGitAsync(
                    _currentWorkspace.FolderPath,
                    $"rev-parse --verify \"refs/heads/{phasePlan.Branch.Replace("\"", "\\\"")}^{{commit}}\"")).Trim();
                phaseLease = new PlanBranchLease(
                    groupId,
                    phasePlan.Revision,
                    phasePlan.Branch,
                    activeExecution.TaskBaselineCommit ?? canonicalHead,
                    DateTimeOffset.UtcNow);
            }

            if (phaseLease is not null)
            {
                var phaseBranch = await EnforcePlanBranchLeaseAsync(
                    phaseLease,
                    candidateCommit: null,
                    mutationAllowed: false);
                if (!phaseBranch.CanContinue)
                {
                    StopAndOfferDecomposeRecovery(
                        groupId,
                        activeExecution.ActiveVerificationTaskId ?? _CodeHealthGroupRunner.CurrentStepId ?? "validation",
                        activeExecution.DecomposeRevision ?? string.Empty,
                        phaseBranch.Message);
                    return;
                }
                if (phaseBranch.Repaired)
                    ScheduleDecomposeSystemEntry(phaseBranch.Message);
            }
        }
        if (activeExecution?.ActiveVerificationTaskId is { } activeVerificationTaskId)
        {
            await FinalizeTaskVerificationTurnAsync(groupId, activeVerificationTaskId, activeExecution);
            return;
        }

        // Handle validation turn finalization if a validation is in progress
        if (activeExecution?.ActiveValidationId is { } activeValId)
        {
            await FinalizeValidationTurnAsync(groupId, activeValId);
            return;
        }

        var result = _capturedDecomposeStepResult;
        var error = _capturedDecomposeStepResultError;
        var resultViolations = _capturedDecomposeStepResultViolations;
        if (activeExecution is null)
        {
            // A graceful stop can clear the durable execution envelope while the
            // coordinator's current response is winding down. Never turn that race
            // into a second protocol failure or dereference a missing attempt.
            SquadDashTrace.Write(
                "Loop",
                $"Skipping plan finalization after execution ownership was released plan={groupId} task={taskId}.");
            return;
        }

        var replayingPendingResult = false;
        // Fall back to the persisted pending repair result if in-memory fields are empty (e.g., after restart).
        if (result is null && error is null && activeExecution.PendingRepairResult is { } pending)
        {
            if (pending.Matches(groupId, revision, activeExecution.PlanExecutionAttempt?.AttemptId) &&
                string.Equals(pending.TaskId, taskId, StringComparison.Ordinal))
            {
                if (pending.ResultJson is not null)
                {
                    try
                    {
                        result = JsonSerializer.Deserialize<DecomposeStepResult>(pending.ResultJson);
                        error = pending.ErrorText;
                        resultViolations = pending.Violations ?? [];
                    }
                    catch (Exception ex)
                    {
                        SquadDashTrace.Write("PlanRepair", $"Failed to deserialize persisted repair result: {ex.Message}");
                        error = "Persisted repair result could not be deserialized.";
                    }
                }
                else
                {
                    error = pending.ErrorText;
                }
                replayingPendingResult = true;
                _decomposeIterationBaselineCommit =
                    activeExecution.TaskBaselineCommit ?? activeExecution.BranchLease?.BaselineCommit;
                SquadDashTrace.Write("PlanRepair", $"Replaying persisted repair result for task={taskId} group={groupId}.");
            }
            else
            {
                // Stale or cross-scope pending result — discard it
                SquadDashTrace.Write("PlanRepair",
                    $"Discarding stale pending repair result: persisted group={pending.GroupId} rev={pending.Revision} task={pending.TaskId}, " +
                    $"current group={groupId} rev={revision} task={taskId}.");
                _conversationManager.UpdateActiveLoopExecutionState(
                    activeExecution with { PendingRepairResult = null });
                activeExecution = _conversationManager.ConversationState.ActiveLoopExecution!;
            }
        }
        var executionAttempt = activeExecution.PlanExecutionAttempt;
        IReadOnlyList<DecomposedAgentAssignment>? expectedAssignments = null;
        DecomposedSubTask? persistedTask = null;
        string? assignmentError = null;
        string? assignmentEvidenceError = null;
        var branchLeaseFailure = false;
        var hostEvidenceFailure = false;

        var canonicalPlan = _planStore?.Load(groupId);
        if (canonicalPlan is not null)
        {
            persistedTask = PendingDecomposePlanAdapter.FromPlan(canonicalPlan).Group.Tasks
                .FirstOrDefault(task => string.Equals(task.Id, taskId, StringComparison.Ordinal));
            expectedAssignments = persistedTask?.AgentAssignments;
        }
        else
            error = $"Plan {groupId} has no durable execution contract.";
        var verificationOnly = PlanTaskExecutionPolicy.IsVerificationOnly(persistedTask);

        var routingPolicy = PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy);
        if (routingPolicy != PlanAgentRoutingPolicy.Off &&
            string.Equals(persistedTask?.AgentRoutingMode, "generic", StringComparison.Ordinal))
        {
            assignmentEvidenceError = PlanAgentAssignmentValidator.ValidateGenericEvidence(
                taskId,
                revision,
                executionAttempt);
            assignmentError = assignmentEvidenceError;
            if (assignmentEvidenceError is null && result is not null)
                assignmentError = PlanAgentAssignmentValidator.ValidateGenericWrapUp(
                    taskId,
                    executionAttempt,
                    result.ExecutionAttemptId,
                    result.AgentExecutions);
        }
        else
        {
            assignmentEvidenceError = PlanAgentAssignmentValidator.Validate(
                taskId,
                revision,
                routingPolicy == PlanAgentRoutingPolicy.Off ? null : expectedAssignments,
                executionAttempt);
            assignmentError = assignmentEvidenceError;
            // A schema-invalid result has already produced a precise parser error. Do not
            // discard it by validating wrap-up fields on the deliberately cleared result;
            // doing so turns every schema error into a misleading "wrong attempt ID" error.
            if (assignmentEvidenceError is null &&
                routingPolicy != PlanAgentRoutingPolicy.Off &&
                result is not null)
                assignmentError = PlanAgentAssignmentValidator.ValidateWrapUp(
                    taskId,
                    expectedAssignments,
                    executionAttempt,
                    result?.ExecutionAttemptId,
                    result?.AgentExecutions);
        }
        if (assignmentError is null)
        {
            foreach (var advisory in PlanAgentAssignmentValidator.GetAdvisories(expectedAssignments, executionAttempt))
                SquadDashTrace.Write("PlanRouting", $"Plan {groupId} task {taskId}: {advisory}");
        }

        var resultDiagnostics = new List<string?> { error, assignmentError };
        if (result is not null)
        {
            var identityViolations = DecomposeStepResultContractDiagnostics.ValidateIdentityViolations(
                result, groupId, taskId, revision);
            resultViolations = resultViolations.Concat(identityViolations).ToArray();
            resultDiagnostics.AddRange(identityViolations.Select(violation => violation.Message));
        }
        if (result is not null && persistedTask is not null)
            resultDiagnostics.Add(PlanStepProofPolicy.Validate(persistedTask, result));
        resultDiagnostics.Add(
            _capturedPlanInboxOpenPathError ?? activeExecution.PendingInboxLinkRepairError);
        error = DecomposeStepResultContractDiagnostics.Combine(resultDiagnostics);

        if (canonicalPlan is not null)
        {
            var leaseBaseline = activeExecution.BranchLease?.BaselineCommit ??
                                activeExecution.TaskBaselineCommit ??
                                _decomposeIterationBaselineCommit;
            if (!string.IsNullOrWhiteSpace(leaseBaseline))
            {
                var branchLease = activeExecution.BranchLease ?? new PlanBranchLease(
                    groupId,
                    revision,
                    canonicalPlan.Branch,
                    leaseBaseline,
                    DateTimeOffset.UtcNow);
                var branchEnforcement = await EnforcePlanBranchLeaseAsync(
                    branchLease,
                    result?.VerificationTargetCommit,
                    mutationAllowed: !verificationOnly && result?.IsVerifiedNoOp != true,
                    transcriptCommit: _capturedDecomposeTranscriptCommit);
                if (!branchEnforcement.CanContinue)
                {
                    branchLeaseFailure = true;
                    error = DecomposeStepResultContractDiagnostics.Combine(
                        [error, branchEnforcement.Message]);
                }
                else if (branchEnforcement.Repaired)
                {
                    ScheduleDecomposeSystemEntry(branchEnforcement.Message);
                }
            }
        }

        PlanTaskCommitEvidence? taskCommitEvidence = null;
        if (result?.IsVerifiedNoOp == true &&
            string.Equals(result.GroupId, groupId, StringComparison.Ordinal) &&
            string.Equals(result.TaskId, taskId, StringComparison.Ordinal) &&
            string.Equals(result.Revision, revision, StringComparison.Ordinal) &&
            (executionAttempt is null ||
             string.Equals(result.ExecutionAttemptId, executionAttempt.AttemptId, StringComparison.Ordinal)))
        {
            var noOpValidation = await ValidateDecomposeStepNoOpAsync(
                result,
                activeExecution.TaskBaselineCommit ?? _decomposeIterationBaselineCommit);
            if (noOpValidation.Error is null &&
                !string.IsNullOrWhiteSpace(noOpValidation.EffectiveCommit))
            {
                result = result with { EvaluatedCommit = noOpValidation.EffectiveCommit };
            }
            else
            {
                hostEvidenceFailure = true;
                error = DecomposeStepResultContractDiagnostics.Combine([error, noOpValidation.Error]);
            }
        }

        if (result is not null &&
            !result.IsVerifiedNoOp &&
            !string.IsNullOrWhiteSpace(result.Commit) &&
            string.Equals(result.GroupId, groupId, StringComparison.Ordinal) &&
            string.Equals(result.TaskId, taskId, StringComparison.Ordinal) &&
            string.Equals(result.Revision, revision, StringComparison.Ordinal) &&
            (executionAttempt is null ||
             string.Equals(result.ExecutionAttemptId, executionAttempt.AttemptId, StringComparison.Ordinal)))
        {
            var commitValidation = await ValidateDecomposeStepCommitAsync(
                result,
                verificationOnly,
                baselineOverride: activeExecution.TaskBaselineCommit,
                transcriptCommit: _capturedDecomposeTranscriptCommit,
                skipWorktreePreflight: replayingPendingResult);
            if (commitValidation.Error is null &&
                !string.IsNullOrWhiteSpace(commitValidation.EffectiveCommit) &&
                !string.IsNullOrWhiteSpace(_decomposeIterationBaselineCommit))
            {
                result = result with
                {
                    Commit = commitValidation.EffectiveCommit,
                    Commits = commitValidation.Commits,
                    ExecutionAnomalies = commitValidation.Anomalies,
                };
                taskCommitEvidence = new PlanTaskCommitEvidence(
                    taskId,
                    executionAttempt?.AttemptId,
                    _decomposeIterationBaselineCommit!,
                    commitValidation.EffectiveCommit,
                    result.Summary,
                    result.Verification,
                    commitValidation.Commits,
                    commitValidation.ChangedFiles);
            }
            else
            {
                if (!string.IsNullOrWhiteSpace(commitValidation.Error))
                    hostEvidenceFailure = true;
                if (error is null)
                    error = commitValidation.Error;
            }
        }

        if (error is null && result is not null && taskCommitEvidence is not null)
            result = PlanProofCapabilityPolicy.AttachHostRecordedEvidence(
                persistedTask, result, taskCommitEvidence);

        if (error is not null || result is null)
        {
            // This envelope was examined and rejected. Clear it before selecting a bounded
            // repair action so a malformed result cannot replay forever. Valid results remain
            // durable until canonical plan progress has been committed below.
            if (activeExecution.PendingRepairResult is not null)
            {
                _conversationManager.UpdateActiveLoopExecutionState(
                    activeExecution with { PendingRepairResult = null });
                activeExecution = _conversationManager.ConversationState.ActiveLoopExecution!;
            }

            var recoveryAction = PlanExecutionRecoveryPolicy.Resolve(
                executionAttempt,
                routingPolicy == PlanAgentRoutingPolicy.Off ? null : expectedAssignments,
                activeExecution.RepairRequestCount,
                activeExecution.FreshAttemptCount,
                branchLeaseFailure || hostEvidenceFailure
                    ? PlanExecutionFailureKind.HostEvidence
                    : PlanExecutionFailureKind.EnvelopeContract);
            if (branchLeaseFailure)
                recoveryAction = PlanExecutionRecoveryAction.Block;
            var repairError = error ?? "no result envelope was returned";
            if (recoveryAction == PlanExecutionRecoveryAction.StartFreshAttempt &&
                persistedTask is not null && executionAttempt is not null)
            {
                var freshAttempt = CreatePlanExecutionAttempt(
                    groupId,
                    taskId,
                    revision,
                    persistedTask,
                    expectedAssignments,
                    routingPolicy);
                if (freshAttempt is not null)
                {
                    // Authoritative recovery gating: decision handler enforces bounded recovery
                    var durableTaskCommit = canonicalPlan?.Tasks.FirstOrDefault(t =>
                        string.Equals(t.TaskId, taskId, StringComparison.Ordinal))?.Commit;

                    if (_planRecoveryDecision is not null)
                    {
                        var decision = _planRecoveryDecision.HandleFreshAttemptDecision(
                            groupId, taskId, durableTaskCommit);
                        ScheduleDecomposeSystemEntry(decision.UserMessage);
                        if (!decision.Allowed)
                        {
                            recoveryAction = PlanExecutionRecoveryAction.Block;
                            goto recoveryBlocked;
                        }
                    }

                    var history = PlanExecutionRecoveryPolicy.ArchiveRejectedAttempt(
                        activeExecution.PreviousPlanExecutionAttempts,
                        executionAttempt,
                        freshAttempt);
                    _conversationManager.UpdateActiveLoopExecutionState(
                        activeExecution with {
                            PlanExecutionAttempt = freshAttempt,
                            PreviousPlanExecutionAttempts = history,
                            RecoveryTaskId = taskId,
                            RecoveryAttemptId = freshAttempt.AttemptId,
                            RepairRequestCount = 0,
                            FreshAttemptCount = activeExecution.FreshAttemptCount + 1,
                            PendingInboxLinkRepairError = null,
                            PendingInboxDeliveryRawResponse = null,
                        });
                    var routingContext = DecomposePlanningInstructions.BuildPlanStepRoutingContext(
                        _currentWorkspace.SquadFolderPath,
                        taskId,
                        _CodeHealthGroupRunner.GetCurrentStepTitle() ?? taskId,
                        _CodeHealthGroupRunner.GetCurrentStepDescription() ?? string.Empty,
                        expectedAssignments,
                        revision,
                        freshAttempt,
                        string.Equals(persistedTask.AgentRoutingMode, "generic", StringComparison.Ordinal)
                            ? persistedTask.GenericAgentReason
                            : null,
                        canonicalPlan?.Branch);
                    ScheduleDecomposeSystemEntry(
                        $"⚙ SquadDash closed contaminated execution attempt {executionAttempt.AttemptId} and created fresh attempt {freshAttempt.AttemptId}. Existing commits and work were preserved.");
                    EnqueuePrompt(
                        PlanFreshAttemptPrompt.Build(groupId, taskId, revision, repairError, routingContext),
                        isSystemInjected: true);
                    return;
                }
                recoveryAction = PlanExecutionRecoveryAction.Block;
            }

            recoveryBlocked:

            if (recoveryAction == PlanExecutionRecoveryAction.RequestRepair)
            {
                // Authoritative recovery gating: decision handler enforces bounded recovery
                var durableRepairCommit = canonicalPlan?.Tasks.FirstOrDefault(t =>
                    string.Equals(t.TaskId, taskId, StringComparison.Ordinal))?.Commit;

                if (_planRecoveryDecision is not null)
                {
                    var repairDecision = _planRecoveryDecision.HandleRepairDecision(
                        groupId, taskId, durableRepairCommit);
                    ScheduleDecomposeSystemEntry(repairDecision.UserMessage);
                    if (!repairDecision.Allowed)
                    {
                        // Recovery exhausted — do not proceed with repair prompt
                        SquadDashTrace.Write(TraceCategory.General,
                            $"Envelope-repair blocked for task '{taskId}' — falling through to block.");
                        recoveryAction = PlanExecutionRecoveryAction.Block;
                        goto handleBlock;
                    }
                }

                _conversationManager.UpdateActiveLoopExecutionState(
                    activeExecution with {
                        RecoveryTaskId = taskId,
                        RecoveryAttemptId = executionAttempt?.AttemptId,
                        RepairRequestCount = activeExecution.RepairRequestCount + 1
                    });
                var resultEnvelopeWasPresent =
                    _capturedTaskVerificationRawResponse?.Contains(
                        DecomposeStepResultParser.Marker,
                        StringComparison.Ordinal) == true;
                var repairPrompt = DecomposeEnvelopeRepairPrompt.Build(
                    groupId,
                    taskId,
                    revision,
                    repairError,
                    resultEnvelopeWasPresent,
                    executionAttempt?.AttemptId,
                    expectedAssignments,
                    result?.Status,
                    verificationOnly,
                    resultViolations,
                    result);
                if (persistedTask?.ProofRequirements is { Count: > 0 } proofRequirements)
                {
                    var resultRequirements = PlanProofCapabilityPolicy.ResultEnvelopeRequirements(proofRequirements);
                    if (resultRequirements.Count > 0)
                    {
                        repairPrompt += "\n\n" +
                                        DecomposeEnvelopeRepairPrompt.BuildProofEvidenceCorrection(
                                            resultRequirements);
                    }
                }
                if (assignmentEvidenceError is not null && expectedAssignments is { Count: > 0 })
                {
                    var stepTitle = _CodeHealthGroupRunner.GetCurrentStepTitle() ?? taskId;
                    var stepDescription = _CodeHealthGroupRunner.GetCurrentStepDescription() ?? string.Empty;
                    var routingContext = DecomposePlanningInstructions.BuildPlanStepRoutingContext(
                        _currentWorkspace.SquadFolderPath,
                        taskId,
                        stepTitle,
                        stepDescription,
                        expectedAssignments,
                        revision,
                        executionAttempt,
                        canonicalBranch: canonicalPlan?.Branch);
                    repairPrompt = PlanAssignmentRepairPrompt.Build(
                        groupId, taskId, revision, expectedAssignments, routingContext, repairError);
                    ScheduleDecomposeSystemEntry(
                        $"⚙ SquadDash is requesting the missing verified agent assignment (reason: {repairError})");
                }
                else if (assignmentError is not null &&
                         expectedAssignments is { Count: > 0 } &&
                         executionAttempt is not null)
                {
                    repairPrompt = PlanAssignmentWrapUpRepairPrompt.Build(
                        groupId,
                        taskId,
                        revision,
                        executionAttempt.AttemptId,
                        expectedAssignments,
                        repairError);
                    var repairPlan = _planStore?.Load(groupId);
                    var stepIdentity = repairPlan is null
                        ? "The current step"
                        : PlanLoopTranscriptPresentation.BuildTaskIdentity(
                            repairPlan, taskId, _CodeHealthGroupRunner.GetCurrentStepTitle());
                    var workState = taskCommitEvidence is not null
                        ? $"{stepIdentity} work is committed but not yet accepted. "
                        : $"The assigned worker completed {stepIdentity}, but the step is not yet accepted. ";
                    ScheduleDecomposeSystemEntry(
                        workState +
                        "SquadDash is validating the result envelope without relaunching workers. " +
                        $"Technical detail: {repairError}");
                }
                else if (assignmentError is not null &&
                         string.Equals(persistedTask?.AgentRoutingMode, "generic", StringComparison.Ordinal) &&
                         executionAttempt is not null)
                {
                    if (string.IsNullOrWhiteSpace(executionAttempt.GenericPrimaryToolCallId))
                    {
                        var routingContext = DecomposePlanningInstructions.BuildPlanStepRoutingContext(
                            _currentWorkspace.SquadFolderPath,
                            taskId,
                            _CodeHealthGroupRunner.GetCurrentStepTitle() ?? taskId,
                            _CodeHealthGroupRunner.GetCurrentStepDescription() ?? string.Empty,
                            null,
                            revision,
                            executionAttempt,
                            persistedTask!.GenericAgentReason,
                            canonicalPlan?.Branch);
                        repairPrompt = PlanGenericAssignmentRepairPrompt.Build(
                            groupId, taskId, revision, repairError, routingContext);
                        ScheduleDecomposeSystemEntry(
                            $"⚙ SquadDash is requesting the missing generic primary worker (reason: {repairError})");
                    }
                    else
                    {
                        repairPrompt += "\n\nDo not launch another primary worker; the host already observed it. " +
                                        $"Return `executionAttemptId`: `{executionAttempt.AttemptId}` and omit `agentExecutions`.";
                        ScheduleDecomposeSystemEntry(
                            $"⚙ SquadDash is repairing generic plan-execution wrap-up (reason: {repairError})");
                    }
                }
                else
                {
                    var repairPlan = _planStore?.Load(groupId);
                    var stepIdentity = repairPlan is null
                        ? "The current step"
                        : PlanLoopTranscriptPresentation.BuildTaskIdentity(
                            repairPlan, taskId, _CodeHealthGroupRunner.GetCurrentStepTitle());
                    ScheduleDecomposeSystemEntry(resultEnvelopeWasPresent
                        ? "⚙ The task result JSON did not match the required schema. " +
                          "SquadDash is asking the AI to correct it without repeating the work. " +
                          $"Technical detail: {repairError}"
                        : $"{stepIdentity} is not yet accepted. " +
                          "SquadDash is requesting the missing result envelope without repeating the task. " +
                           $"Technical detail: {repairError}");
                }
                if (activeExecution.PendingInboxLinkRepairError is { } inboxLinkError)
                    repairPrompt += DecomposeEnvelopeRepairPrompt.BuildInboxLinkCorrection(inboxLinkError);
                AppendPlanExecutionJournal(
                    groupId,
                    taskId,
                    "envelope-repair-requested",
                    PlanExecutionJournal.Serialize(new
                    {
                        Attempt = activeExecution.RepairRequestCount + 1,
                        Maximum = PlanExecutionRecoveryPolicy.MaxEnvelopeRepairRequestsPerAttempt,
                        Violations = resultViolations,
                        Error = repairError,
                    }));
                _planExecutionLog?.Append(new PlanExecutionLogEntry(
                    Kind: "envelope_repair_requested",
                    Timestamp: DateTimeOffset.UtcNow.ToString("O"),
                    PlanId: groupId,
                    Revision: revision,
                    Round: _loopCurrentIteration,
                    TaskId: taskId,
                    TaskTitle: _CodeHealthGroupRunner.GetCurrentStepTitle(),
                    Message: repairError,
                    Outcome: "pending",
                    Phase: "envelope_repair"));
                EnqueuePrompt(
                    repairPrompt,
                    isSystemInjected: true,
                    sourceTag: PlanRepairReplayPolicy.TaskResultRepairSourceTag);
                return;
            }

            // A repeated repair failure or repeated evidence contamination is terminal
            // for this automatic run. Preserve the attempt history and offer recovery.
            handleBlock:
            if (!branchLeaseFailure)
                _CodeHealthGroupRunner.MarkCurrentStepFailed();
            activeExecution = FinalizeTerminalPlanInboxDelivery(activeExecution, error);
            var pendingAcceptance = taskCommitEvidence is not null && result is not null
                ? new PlanWorkCompletePendingAcceptance(
                    taskId,
                    JsonSerializer.Serialize(result),
                    (resultViolations.Count > 0
                        ? resultViolations.Select(violation => violation.Message)
                        : [error ?? "The result was not accepted."]).ToArray(),
                    DateTimeOffset.UtcNow)
                : null;
            if (pendingAcceptance is not null)
                AppendPlanExecutionJournal(
                    groupId,
                    taskId,
                    "work-complete-pending-acceptance",
                    PlanExecutionJournal.Serialize(pendingAcceptance));
            StopAndOfferDecomposeRecovery(
                groupId,
                taskId,
                revision,
                $"SquadDash rejected the step result after repair attempt: {error ?? "no result was returned"}",
                taskCommitEvidence,
                pendingAcceptance,
                PlanAttentionCategory.AutomaticWorkExhausted);
            return;
        }

        if (replayingPendingResult || activeExecution.RepairRequestCount > 0)
        {
            AppendPlanExecutionJournal(
                groupId,
                taskId,
                "envelope-repair-accepted",
                PlanExecutionJournal.Serialize(new
                {
                    Attempts = activeExecution.RepairRequestCount,
                    Result = result,
                }));
            _planExecutionLog?.Append(new PlanExecutionLogEntry(
                Kind: "envelope_repair_accepted",
                Timestamp: DateTimeOffset.UtcNow.ToString("O"),
                PlanId: groupId,
                Revision: revision,
                Round: _loopCurrentIteration,
                TaskId: taskId,
                TaskTitle: _CodeHealthGroupRunner.GetCurrentStepTitle(),
                Message: null,
                Outcome: "accepted",
                Phase: "envelope_repair"));
        }

        activeExecution = CommitAcceptedPlanInboxDelivery(activeExecution);

        if (result.Status == "complete" && persistedTask is not null &&
            !PlanTaskExecutionPolicy.IsVerificationOnly(persistedTask))
        {
            var baseline = activeExecution.TaskBaselineCommit ?? _decomposeIterationBaselineCommit;
            if (string.IsNullOrWhiteSpace(baseline))
            {
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, revision,
                    "SquadDash could not start independent verification because the task baseline commit is missing.",
                    taskCommitEvidence);
                return;
            }

            var changedOutput = await RunGitAsync(
                _currentWorkspace.FolderPath,
                $"diff --name-only \"{baseline}\"..\"{result.VerificationTargetCommit}\"");
            var changedFiles = changedOutput
                .Split(['\r', '\n'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToArray();
            if (!result.IsVerifiedNoOp &&
                !PlanTaskExecutionPolicy.RequiresIndependentVerification(persistedTask, changedFiles))
            {
                AppendPlanExecutionJournal(
                    groupId,
                    taskId,
                    "lightweight-verification-complete",
                    PlanExecutionJournal.Serialize(new
                    {
                        VerificationLevel = PlanTaskVerificationLevel.Lightweight,
                        Candidate = result,
                        HostRecordedBaseline = baseline,
                        HostRecordedChangedFiles = changedFiles,
                        HostChecks = new[] { "result-schema", "proof-evidence", "commit-scope", "changed-files" },
                    }));
                goto accept_without_independent_verification;
            }

            var pendingVerification = new PendingTaskVerification(
                groupId,
                taskId,
                revision,
                JsonSerializer.Serialize(result),
                baseline,
                changedFiles,
                DateTimeOffset.UtcNow);
            AppendPlanExecutionJournal(
                groupId,
                taskId,
                "candidate-handoff-returned",
                PlanExecutionJournal.Serialize(new
                {
                    Candidate = result,
                    HostRecordedBaseline = baseline,
                    HostRecordedChangedFiles = changedFiles,
                }));
            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with
                {
                    PendingTaskVerification = pendingVerification,
                    ActiveVerificationTaskId = taskId,
                    VerificationReworkInstructions = null,
                    VerificationEnvelopeRepairCount = 0,
                    PendingRepairResult = null,
                    AssessedRecoveryContinuation = null,
                });

            var verificationPlan = _planStore?.Load(groupId);
            if (verificationPlan is not null)
            {
                var updated = PlanStoreUpdater.ApplyTaskVerificationPending(
                    verificationPlan, taskId, result, changedFiles, baseline);
                if (!TryPublishPlanProgress(updated, out var verificationProgressError))
                {
                    StopAndOfferDecomposeRecovery(
                        groupId, taskId, revision,
                        "The candidate result was ready, but SquadDash could not persist its verification state: " +
                        verificationProgressError,
                        taskCommitEvidence);
                    return;
                }
            }

            return;
        }

        accept_without_independent_verification:
        if (result.Status is "partial" or "failed")
        {
            var canonical = _planStore?.Load(groupId);
            if (canonical is null)
            {
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, revision,
                    "The non-complete result could not be applied because the durable plan is unavailable.",
                    taskCommitEvidence);
                return;
            }

            var continuation = result.Continuation!; // Required and validated by the result parser.
            var originTask = canonical.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, continuation.OriginTaskId, StringComparison.Ordinal));
            if (originTask is null)
            {
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, revision,
                    $"The requested continuation origin '{continuation.OriginTaskId}' is not in the durable plan.",
                    taskCommitEvidence);
                return;
            }

            if (continuation.Action == DecomposeStepContinuationAction.HumanRequired)
            {
                var recorded = PlanStoreUpdater.ApplyStepAccepted(canonical, nextExecutingTaskId: null, result);
                if (!TryPublishPlanProgress(recorded, out var humanResultSaveError))
                {
                    StopAndOfferDecomposeRecovery(
                        groupId, taskId, revision,
                        humanResultSaveError ?? "The result could not be saved.",
                        taskCommitEvidence);
                    return;
                }
                RefreshPlanProjectionBestEffort(recorded, "human-input-required");
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, revision,
                    continuation.Summary,
                    taskCommitEvidence,
                    attentionCategory: PlanAttentionCategory.HumanInputRequired);
                return;
            }

            if (!PlanExecutionRecoveryPolicy.HasAutomaticContinuationAvailable(
                    originTask.AutomaticContinuationCount))
            {
                var recorded = PlanStoreUpdater.ApplyStepAccepted(canonical, nextExecutingTaskId: null, result);
                if (!TryPublishPlanProgress(recorded, out var exhaustedSaveError))
                {
                    StopAndOfferDecomposeRecovery(
                        groupId, taskId, revision,
                        exhaustedSaveError ?? "The final continuation result could not be saved.",
                        taskCommitEvidence);
                    return;
                }
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, revision,
                    $"{continuation.Summary} SquadDash stopped after " +
                    $"{originTask.AutomaticContinuationCount} automatic continuation attempts.",
                    taskCommitEvidence,
                    attentionCategory: PlanAttentionCategory.AutomaticWorkExhausted);
                return;
            }

            var updated = continuation.Action switch
            {
                DecomposeStepContinuationAction.RetryCurrentTask =>
                    PlanStoreUpdater.ApplyAutomaticTaskRetry(
                        canonical, result, continuation.Instructions!),
                DecomposeStepContinuationAction.InsertPrerequisiteTasks =>
                    PlanStoreUpdater.ApplyAutomaticPrerequisiteTasks(
                        canonical, result, continuation, DateTimeOffset.UtcNow),
                _ => canonical,
            };
            if (ReferenceEquals(updated, canonical))
            {
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, revision,
                    "The coordinator requested an unsupported automatic continuation.",
                    taskCommitEvidence);
                return;
            }
            if (!TryPublishPlanProgress(updated, out var continuationSaveError))
            {
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, revision,
                    continuationSaveError ?? "The automatic continuation could not be saved.",
                    taskCommitEvidence);
                return;
            }

            RefreshPlanProjectionBestEffort(updated, "automatic-continuation");
            var effectiveGroup = PendingDecomposePlanAdapter.FromPlan(updated).Group;
            _CodeHealthGroupRunner.RefreshTaskDefinitions(effectiveGroup);
            var nextState = _CodeHealthGroupRunner.TrackFirstEligibleStep(
                updated,
                UnionBlockedTaskIds(updated));
            if (nextState != DecomposeGroupExecutionState.Eligible)
            {
                StopAndOfferDecomposeRecovery(
                    groupId, taskId, updated.Revision,
                    $"The continuation was saved, but no prerequisite-eligible task is available ({nextState}).",
                    taskCommitEvidence);
                return;
            }

            var history = (activeExecution.PreviousPlanExecutionAttempts ?? []).ToList();
            if (executionAttempt is not null)
                history.Add(executionAttempt with { Status = result.Status });
            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with
                {
                    DecomposeRevision = updated.Revision,
                    PendingDecomposeRevision = null,
                    PlanExecutionAttempt = null,
                    PreviousPlanExecutionAttempts = history.TakeLast(20).ToArray(),
                    RecoveryTaskId = null,
                    RecoveryAttemptId = null,
                    RepairRequestCount = 0,
                    FreshAttemptCount = 0,
                    TaskBaselineCommit = null,
                    PendingRepairResult = null,
                    AssessedRecoveryContinuation = null,
                });
            LoadTasksPanel();
            RefreshOpenPlanViewersAfterAutomaticContinuation(updated);
            ScheduleDecomposeSystemEntry(
                continuation.Summary + "\n\nPlan execution is continuing automatically.",
                groupId,
                updated.Revision,
                taskId);
            return;
        }

        if (!TryPublishPlanStepAccepted(groupId, result, out var state, out var persistenceError))
        {
            StopAndOfferDecomposeRecovery(
                groupId,
                taskId,
                revision,
                "SquadDash accepted the task result but could not durably record plan progress: " +
                (persistenceError ?? "unknown persistence failure"),
                taskCommitEvidence);
            return;
        }
        _conversationManager.UpdateActiveLoopExecutionState(
            activeExecution with
            {
                PlanExecutionAttempt = executionAttempt is null
                    ? null
                    : executionAttempt with { Status = "accepted" },
                PendingRepairResult = null,
            });
        LoadTasksPanel();
        var durableAfterAcceptance = _planStore?.Load(groupId);
        if (_pausePlanAfterCurrentStepRequested || durableAfterAcceptance?.IsPaused == true)
        {
            SuppressLoopResumeAfterExplicitStop("pause-plan-after-step");
            _loopController.RequestStop();
            ScheduleDecomposeSystemEntry(
                $"Plan will pause after accepted task \"{_CodeHealthGroupRunner.GetCurrentStepTitle() ?? result.TaskId}\".");
            return;
        }
        var readyValidation = durableAfterAcceptance is null
            ? null
            : PlanValidationScheduler.SelectNextSchedulable(durableAfterAcceptance);
        if (readyValidation is not null)
        {
            ActivateValidationForNextIteration(groupId, durableAfterAcceptance!, readyValidation);
            return;
        }
        if (state == DecomposeGroupExecutionState.Complete &&
            durableAfterAcceptance?.LifecycleStatus == PlanLifecycleStatus.Completed)
        {
            SuppressLoopResume("plan-complete");
            _loopController.RequestStop();
            PublishPlanCompletionSummary(durableAfterAcceptance);
            ScheduleDecomposeSystemEntry(
                PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(durableAfterAcceptance));
        }
        else if (_planStore is not null)
        {
            var plan = _planStore.Load(groupId);
            if (plan is not null &&
                (state is DecomposeGroupExecutionState.Eligible or DecomposeGroupExecutionState.AwaitingApproval ||
                 HasReadyPendingApprovalGate(plan)))
            {
                await ProcessPlanApprovalsAfterStepAsync(groupId, revision, result.TaskId, state, plan);
            }
        }
    }

    private async Task FinalizeTaskVerificationTurnAsync(
        string groupId,
        string taskId,
        ActiveLoopExecutionState activeExecution)
    {
        if (_planStore is null || _CodeHealthGroupRunner is null || _currentWorkspace is null)
            return;

        var pending = activeExecution.PendingTaskVerification;
        var candidate = pending is null
            ? null
            : JsonSerializer.Deserialize<DecomposeStepResult>(pending.CandidateResultJson);
        var verification = _capturedTaskVerificationResult;
        var verificationError = _capturedTaskVerificationResultError;
        _capturedTaskVerificationResult = null;
        _capturedTaskVerificationResultError = null;

        if (pending is null || candidate is null)
        {
            StopAndOfferDecomposeRecovery(
                groupId, taskId, activeExecution.DecomposeRevision ?? string.Empty,
                "SquadDash lost the candidate handoff required for independent verification.");
            return;
        }

        if (verification is not null &&
            (!string.Equals(verification.PlanId, groupId, StringComparison.Ordinal) ||
             !string.Equals(verification.TaskId, taskId, StringComparison.Ordinal) ||
             !string.Equals(verification.Revision, pending.Revision, StringComparison.Ordinal) ||
             !RecoveryCommitValidator.CommitIdentifiersMatch(
                 verification.EvaluatedCommit,
                 candidate.VerificationTargetCommit)))
        {
            verificationError = "The verification response did not match the active plan, task, revision, and evaluated snapshot.";
            verification = null;
        }

        AppendPlanExecutionJournal(
            groupId,
            taskId,
            "verification-result-returned",
            verification is null
                ? $"Structured verification result unavailable. {verificationError ?? "No result was returned."}"
                : PlanExecutionJournal.Serialize(verification));

        if (verification is null)
        {
            if (activeExecution.VerificationEnvelopeRepairCount < 1)
            {
                _conversationManager.UpdateActiveLoopExecutionState(
                    activeExecution with
                    {
                        VerificationEnvelopeRepairCount = 1,
                    });
                ScheduleDecomposeSystemEntry(
                    "Verification did not return the required structured result. SquadDash is requesting it once more without rerunning task work.");
                return;
            }

            verification = new PlanTaskVerificationResult(
                groupId,
                taskId,
                pending.Revision,
                candidate.VerificationTargetCommit ?? string.Empty,
                PlanTaskVerificationVerdict.HumanReviewRequired,
                "Independent verification could not produce a trustworthy structured verdict after one envelope repair.",
                [],
                [verificationError ?? "Missing verification result."],
                "Test adequacy could not be independently classified.",
                []);
        }

        _capturedTaskVerificationRawResponse = null;

        var plan = _planStore.Load(groupId);
        if (plan is null) return;
        var nextVerificationAction = PlanTaskVerificationRecoveryPolicy.Resolve(
            verification.Verdict,
            activeExecution.VerificationReworkCount);
        var automaticReworkAvailable =
            nextVerificationAction == PlanTaskVerificationNextAction.AutomaticRework;
        var reviewedPlan = PlanStoreUpdater.ApplyTaskVerificationResult(
            plan,
            taskId,
            verification,
            automaticReworkAvailable);
        var combinableHumanReview = nextVerificationAction == PlanTaskVerificationNextAction.HumanReview
            ? PlanHumanReviewGatePolicy.FindCombinableGate(reviewedPlan, taskId)
            : null;
        if (combinableHumanReview is not null)
            reviewedPlan = PlanStoreUpdater.ApplyGateReady(reviewedPlan, combinableHumanReview.GateId);
        if (!TryPublishPlanProgress(reviewedPlan, out var progressError))
        {
            StopAndOfferDecomposeRecovery(
                groupId, taskId, pending.Revision,
                "SquadDash could not persist the verification verdict: " + progressError);
            return;
        }

        if (nextVerificationAction == PlanTaskVerificationNextAction.Accept)
        {
            var cleared = activeExecution with
            {
                PendingTaskVerification = null,
                ActiveVerificationTaskId = null,
                VerificationReworkInstructions = null,
                VerificationReworkCount = 0,
                VerificationEnvelopeRepairCount = 0,
            };
            _conversationManager.UpdateActiveLoopExecutionState(cleared);
            ScheduleDecomposeSystemEntry(
                $"Work verified · \"{_CodeHealthGroupRunner.GetCurrentStepTitle() ?? taskId}\". {verification.Summary}");
            await AcceptVerifiedTaskAsync(
                groupId, taskId, pending.Revision, candidate, cleared, pending.BaselineCommit);
            return;
        }

        if (automaticReworkAvailable)
        {
            var instructions = verification.ReworkInstructions.Count > 0
                ? string.Join("\n", verification.ReworkInstructions.Select(item => "- " + item))
                : string.Join("\n", verification.MissingOrOverstatedWork.Select(item => "- " + item));
            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with
                {
                    PendingTaskVerification = null,
                    ActiveVerificationTaskId = null,
                    VerificationReworkCount = activeExecution.VerificationReworkCount + 1,
                    VerificationReworkInstructions = instructions,
                    VerificationEnvelopeRepairCount = 0,
                });
            ScheduleDecomposeSystemEntry(
                $"Verification found missing or overstated work in \"{_CodeHealthGroupRunner.GetCurrentStepTitle() ?? taskId}\". " +
                "SquadDash is starting the one permitted automatic rework.\n\n" + instructions);
            return;
        }

        if (combinableHumanReview is not null)
        {
            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with
                {
                    PendingTaskVerification = null,
                    ActiveVerificationTaskId = null,
                    VerificationReworkInstructions = null,
                    VerificationEnvelopeRepairCount = 0,
                });
            SuppressLoopResume("human-review-required");
            _loopController.RequestStop();
            ScheduleDecomposeSystemEntry(
                $"Review required · \"{_CodeHealthGroupRunner.GetCurrentStepTitle() ?? taskId}\". " +
                "Implementation and automated verification passed; complete the human observation checklist to continue.");
            AppendDecomposeRecoveryActions(PendingDecomposePlanAdapter.FromPlan(reviewedPlan), taskId);
            return;
        }

        _conversationManager.UpdateActiveLoopExecutionState(
            activeExecution with { ActiveVerificationTaskId = null });
        var discrepancies = verification.MissingOrOverstatedWork.Count == 0
            ? "- The evidence was inconclusive."
            : string.Join("\n", verification.MissingOrOverstatedWork.Select(item => "- " + item));
        var humanReviewReason = string.Equals(
            verification.Summary,
            "Independent verification could not produce a trustworthy structured verdict after one envelope repair.",
            StringComparison.Ordinal)
            ? "Independent verification did not return the required structured result after two attempts. " +
              "Test adequacy could not be independently classified."
            : $"Independent verification requires human review: {verification.Summary} " +
              $"Missing or overstated work: {discrepancies} Test assessment: {verification.TestAssessment}";
        var commitEvidence = candidate.IsVerifiedNoOp
            ? null
            : new PlanTaskCommitEvidence(
                taskId,
                candidate.ExecutionAttemptId,
                pending.BaselineCommit,
                candidate.Commit ?? string.Empty,
                candidate.Summary,
                candidate.Verification,
                ChangedFiles: pending.ChangedFiles);
        StopAndOfferDecomposeRecovery(
            groupId,
            taskId,
            pending.Revision,
            humanReviewReason,
            commitEvidence,
            attentionCategory: PlanAttentionCategory.AutomaticWorkExhausted);
    }

    private async Task AcceptVerifiedTaskAsync(
        string groupId,
        string taskId,
        string revision,
        DecomposeStepResult result,
        ActiveLoopExecutionState activeExecution,
        string verificationBaselineCommit)
    {
        if (_CodeHealthGroupRunner is null || _planStore is null) return;
        if (_currentWorkspace is not null && !string.IsNullOrWhiteSpace(result.Commit))
        {
            var commitOutput = await RunGitAsync(
                _currentWorkspace.FolderPath,
                $"rev-list --reverse \"{verificationBaselineCommit}..{result.Commit}\"");
            var commits = commitOutput.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                .Select(commit => new PlanEvidenceCommit(
                    commit, PlanRecoveryCommitRelation.Task, "Commit produced within this step's host-recorded baseline range."))
                .ToArray();
            if (commits.Length > 0) result = result with { Commits = commits };
        }
        _conversationManager.UpdateActiveLoopExecutionState(
            activeExecution with
            {
                PlanExecutionAttempt = activeExecution.PlanExecutionAttempt is { } attempt
                    ? attempt with { Status = "accepted" }
                    : null,
            });
        if (!TryPublishPlanStepAccepted(groupId, result, out var state, out var persistenceError))
        {
            StopAndOfferDecomposeRecovery(
                groupId, taskId, revision,
                "SquadDash accepted the verified result but could not durably record plan progress: " +
                (persistenceError ?? "unknown persistence failure"));
            return;
        }
        LoadTasksPanel();

        var durable = _planStore.Load(groupId);
        var readyValidation = durable is null ? null : PlanExecutionBoundaryPolicy.SelectValidation(durable);
        if (readyValidation is not null)
        {
            ActivateValidationForNextIteration(groupId, durable!, readyValidation);
            return;
        }
        if (state == DecomposeGroupExecutionState.Complete &&
            durable?.LifecycleStatus == PlanLifecycleStatus.Completed)
        {
            SuppressLoopResume("plan-complete");
            _loopController.RequestStop();
            PublishPlanCompletionSummary(durable);
            ScheduleDecomposeSystemEntry(
                PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(durable));
        }
        else if (durable is not null &&
                 (state is DecomposeGroupExecutionState.Eligible or DecomposeGroupExecutionState.AwaitingApproval ||
                  HasReadyPendingApprovalGate(durable)))
        {
            await ProcessPlanApprovalsAfterStepAsync(groupId, revision, result.TaskId, state, durable);
        }
    }

    private void PublishPlanCompletionSummary(Plan plan)
    {
        if (_inboxStore is null) return;
        var message = PlanCompletionSummaryBuilder.Build(plan);
        _inboxStore.Save(message);
        _inboxPanel?.Refresh(_inboxStore.LoadAll());
        Dispatcher.BeginInvoke(() =>
        {
            CoordinatorThread.Document.Blocks.Add(BuildInboxIndicatorParagraph(message.Id));
            OutputTextBox.ScrollToEnd();
        }, DispatcherPriority.Background);
    }

    private DecomposeGroupExecutionState TrackFirstEligiblePlanStep(string groupId)
    {
        if (_CodeHealthGroupRunner is null)
            return DecomposeGroupExecutionState.Missing;
        var plan = _planStore?.Load(groupId);
        if (plan is null)
            return DecomposeGroupExecutionState.Missing;

        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (activeExecution?.ActiveVerificationTaskId is { } verificationTaskId &&
            string.Equals(activeExecution.DecomposeGroupId, groupId, StringComparison.Ordinal) &&
            string.Equals(activeExecution.DecomposeRevision, plan.Revision, StringComparison.Ordinal))
        {
            if (_CodeHealthGroupRunner.TryRestoreVerificationStep(
                    plan,
                    verificationTaskId,
                    out var restorationError))
                return DecomposeGroupExecutionState.Eligible;
            SquadDashTrace.Write(
                "PlanVerification",
                $"Could not restore verification candidate plan={groupId} task={verificationTaskId}: {restorationError}");
            return DecomposeGroupExecutionState.Blocked;
        }
        return _CodeHealthGroupRunner.TrackFirstEligibleStep(plan, UnionBlockedTaskIds(plan));
    }

    private static IReadOnlySet<string>? UnionBlockedTaskIds(Plan plan)
    {
        var gateBlocked = ApprovalGateReadinessEvaluator.ComputeAllBlockedTaskIds(plan);
        var validationBlocked = PlanValidationScheduler.ComputeBlockedTaskIds(plan);
        if (gateBlocked.Count == 0) return validationBlocked.Count == 0 ? null : validationBlocked;
        if (validationBlocked.Count == 0) return gateBlocked;
        var union = new HashSet<string>(gateBlocked, StringComparer.Ordinal);
        union.UnionWith(validationBlocked);
        return union;
    }

    private static bool HasReadyPendingApprovalGate(Plan plan) =>
        ApprovalGateReadinessEvaluator.EvaluateGates(plan).Any(state =>
            state.IsReady && plan.ApprovalGates.Any(gate =>
                string.Equals(gate.GateId, state.GateId, StringComparison.Ordinal) &&
                gate.Status == PlanGateStatus.Pending));

    /// <summary>
    /// Activates a validation turn for a ready validation node. Transitions the validation to
    /// Validating state, persists durable progress, records <see cref="ActiveLoopExecutionState.ActiveValidationId"/>,
    /// and lets the next loop iteration execute the validation as first-class plan work.
    /// </summary>
    private bool ActivateValidationForNextIteration(
        string groupId,
        Plan plan,
        PlanValidationNode validation)
    {
        try
        {
            // Transition to Validating and persist. A recovered plan may have completed
            // prerequisites while the node still carries Pending/Stale rather than Ready.
            var readyPlan = validation.Status == PlanValidationStatus.Validating
                ? plan
                : PlanStoreUpdater.ApplyValidationReady(plan, validation.ValidationId);
            var updated = validation.Status == PlanValidationStatus.Validating
                ? readyPlan
                : PlanStoreUpdater.ApplyValidationStarted(readyPlan, validation.ValidationId);
            if (!TryPublishPlanProgress(updated, out var progressError))
            {
                SquadDashTrace.Write("PlanValidation",
                    $"Failed to persist validation-started for {validation.ValidationId}: {progressError}");
                return false;
            }

            // Record the active validation in durable execution state
            var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
            if (activeExecution is not null)
            {
                _conversationManager.UpdateActiveLoopExecutionState(
                    activeExecution with
                    {
                        ActiveValidationId = validation.ValidationId,
                        ValidationRepairCount = 0,
                        ValidationRepairReason = null,
                        ValidationProviderRetryCount = 0,
                        ValidationProviderFailureReason = null,
                    });
            }
            _CodeHealthGroupRunner?.ClearCurrentStep();
            return true;
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("PlanValidation",
                $"Failed to schedule validation turn for {validation.ValidationId}: {ex.Message}");
            return false;
        }
    }

    /// <summary>
    /// Finalizes a validation turn by applying the captured validation result to durable plan state.
    /// Handles bounded envelope repair, tolerant result acceptance, and state cleanup.
    /// </summary>
    private async Task FinalizeValidationTurnAsync(
        string groupId,
        string validationId)
    {
        var valResult = _capturedValidationResult;
        var valError = _capturedValidationResultError;
        _capturedValidationResult = null;
        _capturedValidationResultError = null;

        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (activeExecution is null)
        {
            SquadDashTrace.Write("PlanValidation",
                $"Skipping validation finalization — execution state is missing for {validationId}.");
            return;
        }

        if (!string.IsNullOrWhiteSpace(activeExecution.ValidationProviderFailureReason))
        {
            if (activeExecution.ValidationProviderRetryCount <= 1)
            {
                // A provider/process failure is not malformed JSON. Retry the complete
                // assignment once and retain the envelope-repair budget for a response that
                // actually completed but violated the structured contract.
                _conversationManager.UpdateActiveLoopExecutionState(
                    activeExecution with { ValidationProviderFailureReason = null });
                return;
            }

            FailValidationWithRecovery(
                groupId,
                validationId,
                activeExecution,
                PlanValidationProviderFailurePresentation.BuildRecoveryReason(
                    activeExecution.ValidationProviderFailureReason,
                    activeExecution.ValidationProviderRetryCount),
                validatedCommit: null);
            return;
        }

        if (valResult is null && valError is not null)
        {
            // Tolerant repair: attempt one envelope repair before failing
            if (activeExecution.ValidationRepairCount < 1)
            {
                _conversationManager.UpdateActiveLoopExecutionState(
                    activeExecution with
                    {
                        ValidationRepairCount = activeExecution.ValidationRepairCount + 1,
                        ValidationRepairReason = valError,
                    });
                ScheduleDecomposeSystemEntry(
                    $"⚙ Requesting missing validation result envelope for {validationId}.");
                return;
            }

            SquadDashTrace.Write("PlanValidation",
                $"Validation {validationId} failed after repair attempt: {valError}");
            FailValidationWithRecovery(groupId, validationId, activeExecution,
                $"The validation response was still missing its required result after one repair. {valError}", null);
            return;
        }

        if (valResult is not null)
        {
            // Validate scope
            if (!string.Equals(valResult.ValidationId, validationId, StringComparison.Ordinal) ||
                !string.Equals(valResult.PlanId, groupId, StringComparison.Ordinal))
            {
                SquadDashTrace.Write("PlanValidation",
                    $"Validation result scope mismatch: expected {groupId}/{validationId}, " +
                    $"got {valResult.PlanId}/{valResult.ValidationId}.");
                FailValidationWithRecovery(groupId, validationId, activeExecution,
                    "The validation result identified a different plan or validation node.", null);
                return;
            }

            var contractValidation = _planStore?.Load(groupId)?.Validations?.FirstOrDefault(candidate =>
                string.Equals(candidate.ValidationId, validationId, StringComparison.Ordinal));
            var evidenceContractError = contractValidation is null
                ? $"Plan {groupId} is missing validation {validationId}."
                : PlanValidationEvidencePolicy.Validate(contractValidation, valResult);
            if (evidenceContractError is not null)
            {
                if (activeExecution.ValidationRepairCount < 1)
                {
                    _conversationManager.UpdateActiveLoopExecutionState(
                        activeExecution with
                        {
                            ValidationRepairCount = activeExecution.ValidationRepairCount + 1,
                            ValidationRepairReason = evidenceContractError,
                        });
                    ScheduleDecomposeSystemEntry(
                        $"⚙ Requesting corrected validation evidence for {validationId}.");
                    return;
                }

                FailValidationWithRecovery(groupId, validationId, activeExecution,
                    $"The corrected validation result still did not match the approved evidence contract. {evidenceContractError}",
                    valResult.ValidatedCommit);
                return;
            }

            var evidence = valResult.AssertionEvidence
                .Select(e => $"[{(e.Passed ? "PASS" : "FAIL")}] {e.Assertion}: {e.Evidence}")
                .ToArray();
            if (valResult.NeedsHumanProof)
            {
                var reviewPlan = ApplyAndPublishValidationHumanReviewRequired(
                    groupId,
                    validationId,
                    valResult.Summary,
                    evidence,
                    valResult.ValidatedCommit,
                    valResult.HumanProofRequirements ?? []);
                ClearActiveValidation(activeExecution);
                if (reviewPlan is null)
                {
                    FailValidationWithRecovery(groupId, validationId, activeExecution,
                        "SquadDash could not save the required human review checkpoint.",
                        valResult.ValidatedCommit);
                    return;
                }

                ScheduleDecomposeSystemEntry(
                    $"Review required · {contractValidation!.Title}. " +
                    "Confirm the remaining observable evidence below; implementation work is preserved.");
                var evidenceTaskId = contractValidation.AfterTaskIds.LastOrDefault() ?? validationId;
                await ProcessPlanApprovalsAfterStepAsync(
                    groupId,
                    reviewPlan.Revision,
                    evidenceTaskId,
                    DecomposeGroupExecutionState.AwaitingApproval,
                    reviewPlan);
                return;
            }
            var resultingPlan = ApplyAndPublishValidationResult(groupId, validationId, valResult.Passed,
                valResult.Summary, evidence, valResult.ValidatedCommit);
            ClearActiveValidation(activeExecution);

            if (resultingPlan?.LifecycleStatus == PlanLifecycleStatus.Completed)
            {
                SuppressLoopResume("plan-complete");
                _loopController.RequestStop();
                PublishPlanCompletionSummary(resultingPlan);
                ScheduleDecomposeSystemEntry(
                    $"Plan validation passed · {contractValidation!.Title}. {valResult.Summary}\n\n" +
                    PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(resultingPlan));
            }
            else if (valResult.Passed)
            {
                ScheduleDecomposeSystemEntry(
                    $"Plan validation passed · {contractValidation!.Title}. {valResult.Summary}");
                if (resultingPlan is not null)
                {
                    var groupState = TrackFirstEligiblePlanStep(groupId);
                    var validation = resultingPlan.Validations?.FirstOrDefault(candidate =>
                        string.Equals(candidate.ValidationId, validationId, StringComparison.Ordinal));
                    var evidenceTaskId = validation?.AfterTaskIds.LastOrDefault()
                        ?? resultingPlan.Tasks.LastOrDefault(task =>
                            task.Status is PlanTaskStatus.Complete or PlanTaskStatus.Superseded)?.TaskId
                        ?? validationId;
                    if (groupState is DecomposeGroupExecutionState.Eligible or
                                      DecomposeGroupExecutionState.AwaitingApproval)
                    {
                        await ProcessPlanApprovalsAfterStepAsync(
                            groupId,
                            resultingPlan.Revision,
                            evidenceTaskId,
                            groupState,
                            resultingPlan);
                    }
                }
            }
            else
                ScheduleValidationRecoveryEntry(
                    groupId,
                    validationId,
                    $"Validation did not pass · {contractValidation!.Title}.\n" +
                    $"Why it stopped: {valResult.Summary}\n" +
                    "Completed implementation work is preserved and will not be repeated.");
            return;
        }

        // No result and no error — treat as missing envelope
        if (activeExecution.ValidationRepairCount < 1)
        {
            _conversationManager.UpdateActiveLoopExecutionState(
                activeExecution with
                {
                    ValidationRepairCount = activeExecution.ValidationRepairCount + 1,
                    ValidationRepairReason = "No validation result was returned.",
                });
            ScheduleDecomposeSystemEntry(
                $"⚙ Requesting missing validation result envelope for {validationId}.");
            return;
        }

        FailValidationWithRecovery(groupId, validationId, activeExecution,
            "No validation result was returned after one bounded repair.", null);
    }

    private void FailValidationWithRecovery(
        string groupId,
        string validationId,
        ActiveLoopExecutionState activeExecution,
        string reason,
        string? validatedCommit)
    {
        var plan = ApplyAndPublishValidationResult(
            groupId, validationId, false, reason, [], validatedCommit);
        ClearActiveValidation(activeExecution);
        var validation = plan?.Validations?.FirstOrDefault(candidate =>
            string.Equals(candidate.ValidationId, validationId, StringComparison.Ordinal));
        var title = validation?.Title ?? validationId;
        ScheduleValidationRecoveryEntry(
            groupId,
            validationId,
            $"Validation needs attention · {title}.\n" +
            $"Why it stopped: {reason}\n" +
            "Completed implementation work is preserved and will not be repeated.");
    }

    private void ScheduleValidationRecoveryEntry(
        string planId,
        string validationId,
        string message,
        bool addMessage = true)
    {
        void Publish()
        {
            var plan = _planStore?.Load(planId);
            var validation = plan?.Validations?.FirstOrDefault(candidate =>
                string.Equals(candidate.ValidationId, validationId, StringComparison.Ordinal));
            var preparesHumanReview =
                PlanValidationHumanProofRecoveryPolicy.IsLegacyHumanProofOnlyFailure(validation);
            if (addMessage)
                ShowSystemTranscriptEntry(preparesHumanReview && validation is not null
                    ? $"Review required · {validation.Title}.\n" +
                      "Why it paused: the remaining proof requires human observation. " +
                      "Prepare the review checklist to continue.\n" +
                      "Completed implementation work is preserved and will not be repeated."
                    : message);
            var tag = $"plan-validation-recovery:{planId}:{validationId}";
            foreach (var existing in CoordinatorThread.Document.Blocks
                         .OfType<Section>()
                         .Where(section => string.Equals(section.Tag as string, tag, StringComparison.Ordinal))
                         .ToArray())
                CoordinatorThread.Document.Blocks.Remove(existing);

            var section = new Section { Tag = tag };
            var card = new Border
            {
                BorderThickness = new Thickness(1),
                CornerRadius = new CornerRadius(8),
                Padding = new Thickness(14, 12, 14, 12),
                Margin = new Thickness(0, 6, 0, 8),
                HorizontalAlignment = HorizontalAlignment.Stretch,
            };
            card.SetResourceReference(Border.BackgroundProperty, "CardSurface");
            card.SetResourceReference(Border.BorderBrushProperty, "PanelBorder");
            var cardContent = new StackPanel();
            var heading = new TextBlock
            {
                Text = preparesHumanReview ? "Validation needs review" : "Validation failed",
                FontWeight = FontWeights.SemiBold,
                FontSize = _transcriptFontSize + 1,
            };
            heading.SetResourceReference(TextBlock.ForegroundProperty,
                preparesHumanReview ? "BodyText" : "PriorityCritical");
            cardContent.Children.Add(heading);
            if (validation is not null)
            {
                var title = new TextBlock
                {
                    Text = validation.Title,
                    FontWeight = FontWeights.SemiBold,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 5, 0, 0),
                };
                title.SetResourceReference(TextBlock.ForegroundProperty, "BodyText");
                cardContent.Children.Add(title);

                var summary = new TextBlock
                {
                    Text = validation.Summary ?? "The validation did not return acceptable evidence.",
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 5, 0, 0),
                    MaxWidth = 900,
                    HorizontalAlignment = HorizontalAlignment.Left,
                };
                summary.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
                cardContent.Children.Add(summary);
            }

            var actions = new WrapPanel
            {
                Orientation = Orientation.Horizontal,
                Margin = new Thickness(0, 10, 0, 0),
                VerticalAlignment = VerticalAlignment.Center,
            };
            var primary = TranscriptQuickReplyFactory.CreateButton(
                preparesHumanReview ? "Prepare Review Checklist" : "Fix defect and revalidate",
                _transcriptFontSize,
                toolTip: ToolTipHelper.MakeThemedToolTip(
                    preparesHumanReview
                        ? "Re-evaluate this non-mutating audit under the human-review protocol and present the specific observations as checkboxes."
                        : "Add one bounded repair step from the recorded failure evidence, preserve completed work, and rerun this validation after the repair."));
            primary.Click += async (_, _) =>
            {
                primary.IsEnabled = false;
                try
                {
                    CoordinatorThread.Document.Blocks.Remove(section);
                    if (preparesHumanReview)
                        await RetryFailedPlanValidationAsync(planId, validationId);
                    else
                        await FixFailedPlanValidationAsync(planId, validationId);
                }
                catch (Exception ex)
                {
                    primary.IsEnabled = true;
                    if (!CoordinatorThread.Document.Blocks.Contains(section))
                        CoordinatorThread.Document.Blocks.Add(section);
                    HandleUiCallbackException("Validation recovery", ex);
                }
            };
            actions.Children.Add(primary);
            if (plan is not null && validation is not null)
            {
                var reviewText = new TextBlock
                {
                    Margin = new Thickness(12, 5, 0, 0),
                    VerticalAlignment = VerticalAlignment.Center,
                };
                var review = new Hyperlink(new Run("Review details")) { Cursor = Cursors.Hand };
                review.Click += (_, _) => OpenPlanValidationDetails(planId, validationId);
                reviewText.Inlines.Add(review);
                actions.Children.Add(reviewText);
            }
            cardContent.Children.Add(actions);
            card.Child = cardContent;
            section.Blocks.Add(new BlockUIContainer(card));
            CoordinatorThread.Document.Blocks.Add(section);
            ScrollToEndIfAtBottom(CoordinatorThread);
        }

        if (Dispatcher.CheckAccess()) Publish();
        else Dispatcher.BeginInvoke(Publish, System.Windows.Threading.DispatcherPriority.Send);
    }

    private async Task RetryFailedPlanValidationAsync(string planId, string validationId)
    {
        if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
            throw new InvalidOperationException(
                "Wait for the current prompt or plan turn to finish before retrying validation.");

        var plan = _planStore?.Load(planId)
            ?? throw new InvalidOperationException($"Plan {planId} is no longer available.");
        var validation = plan.Validations?.FirstOrDefault(candidate =>
            string.Equals(candidate.ValidationId, validationId, StringComparison.Ordinal));
        if (validation is null)
            throw new InvalidOperationException($"Validation {validationId} is no longer part of this plan.");
        if (validation.Status != PlanValidationStatus.Failed)
            throw new InvalidOperationException(
                $"Validation “{validation.Title}” is no longer waiting to be retried.");
        var preparesHumanReview =
            PlanValidationHumanProofRecoveryPolicy.IsLegacyHumanProofOnlyFailure(validation);

        // A Copilot device sign-in is shared by the Windows user, while each
        // SquadDash instance owns its own long-lived bridge process. Refresh only
        // this instance before the explicit retry so a newly completed sign-in is
        // observed without requiring any SquadDash windows to restart.
        _bridge.RestartBridgeForNewSettings();
        ClearRuntimeIssue();

        var updated = PlanStoreUpdater.ApplyValidationRetry(plan, validationId);
        if (!TryPublishPlanProgress(updated, out var error))
            throw new InvalidOperationException(error ?? "The validation retry could not be saved.");

        PrepareForHostRecoveryAction();
        ScheduleDecomposeSystemEntry(
            preparesHumanReview
                ? $"Preparing review checklist · {validation.Title}. A fact-checker will identify only the specific human observations still needed; completed implementation work remains accepted."
                : $"Retrying validation · {validation.Title}. Completed implementation work remains accepted.");
        await StartOrResumeDurablePlanAsync(updated);
    }

    private async Task FixFailedPlanValidationAsync(string planId, string validationId)
    {
        if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
            throw new InvalidOperationException(
                "Wait for the current prompt or plan turn to finish before repairing validation.");

        var plan = _planStore?.Load(planId)
            ?? throw new InvalidOperationException($"Plan {planId} is no longer available.");
        var validation = plan.Validations?.FirstOrDefault(candidate =>
            string.Equals(candidate.ValidationId, validationId, StringComparison.Ordinal));
        if (validation is null || validation.Status != PlanValidationStatus.Failed)
            throw new InvalidOperationException("This validation is no longer waiting for a repair.");

        var updated = PlanStoreUpdater.ApplyValidationRepairRequested(plan, validationId);
        if (ReferenceEquals(updated, plan))
            throw new InvalidOperationException("SquadDash could not create a bounded repair step for this validation.");
        if (!TryPublishPlanProgress(updated, out var error))
            throw new InvalidOperationException(error ?? "The validation repair could not be saved.");

        RefreshPlanProjectionBestEffort(updated, "validation-defect-repair");
        LoadTasksPanel();
        PrepareForHostRecoveryAction();
        ScheduleDecomposeSystemEntry(
            $"Repairing validation defect · {validation.Title}. Completed work remains accepted; " +
            "the failed assertion evidence is attached to one bounded repair step, and validation will rerun automatically afterward.");
        await StartOrResumeDurablePlanAsync(updated);
    }

    private void OpenPlanValidationDetails(string planId, string validationId)
    {
        var plan = _planStore?.Load(planId)
            ?? throw new InvalidOperationException($"Plan {planId} is no longer available.");
        var validation = plan.Validations?.FirstOrDefault(candidate =>
            string.Equals(candidate.ValidationId, validationId, StringComparison.Ordinal))
            ?? throw new InvalidOperationException($"Validation {validationId} is no longer part of this plan.");
        var key = $"{planId}:{validationId}";
        if (_openPlanValidationDetailsWindows.TryGetValue(key, out var existing))
        {
            if (existing.WindowState == WindowState.Minimized)
                existing.WindowState = WindowState.Normal;
            existing.Activate();
            return;
        }

        var window = new PlanValidationDetailsWindow(
            PlanValidationDetailsPresentationBuilder.Build(plan, validation))
        {
            Owner = CanShowOwnedWindow() ? this : null,
        };
        _openPlanValidationDetailsWindows[key] = window;
        window.Closed += (_, _) =>
        {
            _openPlanValidationDetailsWindows.Remove(key);
            FloatingWindowPositionStore.Shared.Save($"ValidationDetails:{key}", window);
        };
        FloatingWindowPositionStore.Shared.TryRestore($"ValidationDetails:{key}", window);
        window.Show();
    }

    private Plan? ApplyAndPublishValidationResult(
        string groupId,
        string validationId,
        bool passed,
        string summary,
        IReadOnlyList<string> evidence,
        string? validatedCommit)
    {
        try
        {
            var plan = _planStore?.Load(groupId);
            if (plan is null) return null;
            var updated = PlanStoreUpdater.ApplyValidationResult(
                plan, validationId, passed, summary, evidence, validatedCommit);
            return TryPublishPlanProgress(updated, out _) ? updated : null;
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("PlanValidation",
                $"Failed to persist validation result for {validationId}: {ex.Message}");
            return null;
        }
    }

    private void ClearActiveValidation(ActiveLoopExecutionState activeExecution)
    {
        _conversationManager.UpdateActiveLoopExecutionState(
            activeExecution with
            {
                ActiveValidationId = null,
                ValidationRepairCount = 0,
                ValidationRepairReason = null,
                ValidationProviderRetryCount = 0,
                ValidationProviderFailureReason = null,
            });
        if (activeExecution.DecomposeGroupId is { Length: > 0 } planId)
            PromotePendingPlanRevisionAtBoundary(planId);
    }

    private async Task<(string? Error, string? EffectiveCommit)> ValidateDecomposeStepNoOpAsync(
        DecomposeStepResult result,
        string? baselineCommit)
    {
        if (_currentWorkspace is null) return ("No workspace is active.", null);
        if (!result.IsVerifiedNoOp)
            return ("The result is not a verified-no-op candidate.", null);
        if (string.IsNullOrWhiteSpace(baselineCommit))
            return ("SquadDash cannot verify a no-op result because the task baseline commit is missing.", null);
        if (string.IsNullOrWhiteSpace(result.EvaluatedCommit) ||
            !Regex.IsMatch(result.EvaluatedCommit, "^[0-9a-fA-F]{7,64}$", RegexOptions.CultureInvariant))
            return ("The verified-no-op evaluatedCommit was missing or malformed.", null);

        try
        {
            var workspace = _currentWorkspace.FolderPath;
            var head = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
            var baseline = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"{baselineCommit}^{{commit}}\"")).Trim();
            var evaluated = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"{result.EvaluatedCommit}^{{commit}}\"")).Trim();

            if (!string.Equals(evaluated, head, StringComparison.OrdinalIgnoreCase))
                return ($"The verified-no-op result evaluated {evaluated}, but the current inspected snapshot is HEAD {head}.", null);

            if (!string.Equals(head, baseline, StringComparison.OrdinalIgnoreCase))
            {
                try
                {
                    await RunGitAsync(workspace, $"merge-base --is-ancestor \"{baseline}\" \"{head}\"");
                }
                catch
                {
                    return ($"HEAD {head} is not descended from the verified-no-op task baseline {baseline}.", null);
                }
                SquadDashTrace.Write(
                    "PlanExecution",
                    $"Accepted verified no-op at current evaluated HEAD {head}; branch advanced from task baseline {baseline}. " +
                    "Intervening commits were not attributed to this step.");
            }

            await EnsurePlanWorktreeReadyAsync(workspace);
            return (null, evaluated);
        }
        catch (Exception ex)
        {
            return ($"Verified-no-op Git validation failed: {ex.Message}", null);
        }
    }


    private async Task<(string? Error, string? EffectiveCommit, IReadOnlyList<PlanEvidenceCommit> Commits, IReadOnlyList<PlanExecutionAnomaly> Anomalies, IReadOnlyList<string> ChangedFiles)> ValidateDecomposeStepCommitAsync(
        DecomposeStepResult result,
        bool verificationOnly,
        string? baselineOverride = null,
        string? transcriptCommit = null,
        bool skipWorktreePreflight = false,
        Func<string, string, Task<string>>? runGit = null)
    {
        runGit ??= RunGitAsync;
        if (_currentWorkspace is null) return ("No workspace is active.", null, [], [], []);
        if (string.IsNullOrWhiteSpace(result.Commit) ||
            !Regex.IsMatch(result.Commit, "^[0-9a-fA-F]{7,64}$", RegexOptions.CultureInvariant))
            return ("The reported commit was missing or malformed.", null, [], [], []);

        try
        {
            var workspace = _currentWorkspace.FolderPath;
            var head = (await runGit(workspace, "rev-parse HEAD")).Trim();
            var baseline = baselineOverride ?? _decomposeIterationBaselineCommit;
            string resolved;
            try
            {
                resolved = (await runGit(
                    workspace,
                    $"rev-parse --verify \"{result.Commit}^{{commit}}\"")).Trim();
            }
            catch when (!string.IsNullOrWhiteSpace(baseline) &&
                        ReportedCommitReconciler.MatchesObservedHead(transcriptCommit, head))
            {
                resolved = head;
                SquadDashTrace.Write(
                    "PlanExecution",
                    $"Reconciled unresolvable reported commit '{result.Commit}' from transcript commit " +
                    $"'{transcriptCommit}' at observed HEAD '{head}'. Normal ancestry and atomic-commit validation will still run.");
            }
            catch when (!string.IsNullOrWhiteSpace(baseline) &&
                        ReportedCommitReconciler.IsSingleCharacterSubstitution(result.Commit, head))
            {
                resolved = head;
                SquadDashTrace.Write(
                    "PlanExecution",
                    $"Reconciled one-character reported commit typo '{result.Commit}' to observed HEAD '{head}'. " +
                    "Normal ancestry and atomic-commit validation will still run.");
            }
            if (!verificationOnly)
            {
                try
                {
                    if (!string.IsNullOrWhiteSpace(baseline))
                        await runGit(workspace, $"merge-base --is-ancestor \"{baseline}\" \"{resolved}\"");
                    await runGit(workspace, $"merge-base --is-ancestor \"{resolved}\" \"{head}\"");
                }
                catch (InvalidOperationException ex)
                {
                    SquadDashTrace.Write("PlanRecovery", $"Task commit ancestry validation failed: {ex.Message}");
                    return ($"The reported task commit {resolved} is not reachable between the task baseline and active branch HEAD {head}.", null, [], [], []);
                }
            }
            else if (!string.Equals(resolved, head, StringComparison.OrdinalIgnoreCase))
            {
                try
                {
                    await runGit(workspace, $"merge-base --is-ancestor \"{resolved}\" \"{head}\"");
                }
                catch (InvalidOperationException ex)
                {
                    SquadDashTrace.Write("PlanRecovery", $"Verification commit ancestry validation failed: {ex.Message}");
                    return ($"The verification result referenced {resolved}, which is not part of the active branch at {head}.", null, [], [], []);
                }
            }

            if (!verificationOnly && string.Equals(baseline, resolved, StringComparison.OrdinalIgnoreCase))
                return ("The step reported completion without creating a new commit.", null, [], [], []);

            IReadOnlyList<PlanEvidenceCommit> commits = [];
            IReadOnlyList<PlanExecutionAnomaly> anomalies = [];

            if (!string.IsNullOrWhiteSpace(baseline))
            {
                var rangeEnd = verificationOnly ? head : resolved;
                await runGit(workspace, $"merge-base --is-ancestor \"{baseline}\" \"{rangeEnd}\"");
                var commitCountText = (await runGit(
                    workspace,
                    $"rev-list --count \"{baseline}..{rangeEnd}\"")).Trim();
                if (!int.TryParse(commitCountText, out var commitCount))
                    return ("SquadDash could not determine how many commits the step produced.", null, [], [], []);
                if (verificationOnly && commitCount != 0)
                    return ($"The verification-only step changed the branch by {commitCount} commit(s); it must only evaluate existing work.", null, [], [], []);

                if (!verificationOnly)
                {
                    var commitOutput = await runGit(
                        workspace,
                        $"rev-list --reverse \"{baseline}..{rangeEnd}\"");
                    commits = commitOutput
                        .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                        .Select(commit => new PlanEvidenceCommit(
                            commit,
                            commitCount == 1 ? PlanRecoveryCommitRelation.Task : PlanRecoveryCommitRelation.Unknown,
                            commitCount == 1
                                ? "Commit observed within this step's host-recorded baseline range."
                                : "Commit observed within the step range; individual task ownership was not assumed."))
                        .ToArray();
                    if (commitCount > 1)
                    {
                        anomalies =
                        [
                            new PlanExecutionAnomaly(
                                "multiple-commits",
                                PlanExecutionAnomalySeverity.Warning,
                                $"The step completed in {commitCount} commits. SquadDash preserved the full contiguous range and continued without rewriting history.",
                                DateTimeOffset.UtcNow,
                                commits),
                        ];
                    }
                }
            }

            var changedPaths = (await runGit(
                    workspace,
                    string.IsNullOrWhiteSpace(baseline)
                        ? $"diff-tree --no-commit-id --name-only -r \"{resolved}\""
                        : $"diff --name-only \"{baseline}..{(verificationOnly ? head : resolved)}\""))
                .Replace("\r\n", "\n", StringComparison.Ordinal)
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            var tasksRelativePath = await GetTasksRepositoryRelativePathAsync(workspace, runGit);
            if (tasksRelativePath is not null &&
                changedPaths.Any(path => string.Equals(
                    path.Replace('\\', '/'),
                    tasksRelativePath,
                    StringComparison.OrdinalIgnoreCase)))
                return ("The AI commit modified tasks.md; plan status is owned by SquadDash.", null, [], [], []);

            if (!skipWorktreePreflight)
                await EnsurePlanWorktreeReadyAsync(workspace);
            return (null, verificationOnly ? head : resolved, commits, anomalies, changedPaths);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("PlanRecovery", $"Task commit validation failed: {ex.Message}");
            return ($"Git validation failed: {ex.Message}", null, [], [], []);
        }
    }

    private void StopAndOfferDecomposeRecovery(
        string groupId,
        string taskId,
        string revision,
        string reason,
        PlanTaskCommitEvidence? taskCommitEvidence = null,
        PlanWorkCompletePendingAcceptance? workCompletePendingAcceptance = null,
        string attentionCategory = PlanAttentionCategory.UnexpectedState,
        string? attentionSummary = null)
    {
        SuppressLoopResume("plan-blocked");
        _loopController.RequestStop();
        AppendLoopOutputLine($"⏹ Plan blocked at {taskId}: {reason}", LoopLifecycleBrush);
        // Persist the final recovery state and its task-scoped commit evidence before rendering
        // transcript or Inbox actions. The UI must describe the durable state it will operate on.
        TryPublishPlanBlocked(groupId, taskId);
        TryPublishPlanInterrupted(
            groupId,
            taskId,
            reason,
            taskCommitEvidence,
            workCompletePendingAcceptance,
            attentionCategory,
            attentionSummary);
        ScheduleDecomposeSystemEntry(
            PlanRecoveryPresentationBuilder.BuildStatusMessage(taskCommitEvidence is not null),
            groupId,
            revision,
            taskId);
        SaveDecomposeRecoveryInboxReminder(groupId, revision, taskId, reason);
    }

    /// <summary>
    /// Restores task-scoped commit evidence durably captured before host result processing
    /// failed. The original handoff is host-validated before later repair envelopes, so a repair
    /// cannot replace its task commit with an unrelated newer HEAD and implementation is not repeated.
    /// </summary>
    private async Task ReconcileInterruptedPlanTaskEvidenceAsync()
    {
        if (_planStore is null || _currentWorkspace is null)
            return;

        var workspace = _currentWorkspace.FolderPath;
        var store = _planStore;
        using var recoveryBudget = new CancellationTokenSource(TimeSpan.FromSeconds(10));
        var cancellationToken = recoveryBudget.Token;
        var turns = _conversationManager.ConversationState.Turns;
        foreach (var plan in store.LoadAll())
        {
            if (cancellationToken.IsCancellationRequested) break;
            var interruption = plan.InterruptionData;
            var taskId = interruption?.InterruptedTaskId;
            var baseline = interruption?.LastCommit;
            if (plan.LifecycleStatus != PlanLifecycleStatus.Interrupted ||
                string.IsNullOrWhiteSpace(taskId) ||
                string.IsNullOrWhiteSpace(baseline))
                continue;

            var stableInterruption = interruption!;
            var selectedEvidence = stableInterruption.TaskCommitEvidence;
            var evidenceChanged = false;
            var candidates = InterruptedPlanEvidenceResolver.FindTaskResults(
                turns, plan.PlanId, plan.Revision, taskId);
            foreach (var candidate in candidates)
            {
                if (cancellationToken.IsCancellationRequested) break;
                string taskBaseline;
                string candidateCommit;
                try
                {
                    taskBaseline = (await PlanRecoveryGit.RunRequiredAsync(
                        workspace,
                        $"rev-parse --verify \"{baseline}^{{commit}}\"", cancellationToken)).Trim();
                    candidateCommit = (await PlanRecoveryGit.RunRequiredAsync(
                        workspace,
                        $"rev-parse --verify \"{candidate.Commit}^{{commit}}\"", cancellationToken)).Trim();
                    await PlanRecoveryGit.RunRequiredAsync(
                        workspace,
                        $"merge-base --is-ancestor \"{taskBaseline}\" \"{candidateCommit}\"", cancellationToken);
                }
                catch (InvalidOperationException ex)
                {
                    SquadDashTrace.Write(
                        "PlanRecovery",
                        $"Rejected captured result plan={plan.PlanId} task={taskId} commit={candidate.Commit}: it is not reachable from the recorded interruption baseline. {ex.Message}");
                    continue;
                }

                var validation = await ValidateDecomposeStepCommitAsync(
                    candidate,
                    verificationOnly: false,
                    baselineOverride: taskBaseline,
                    skipWorktreePreflight: true,
                    runGit: (folder, arguments) => PlanRecoveryGit.RunRequiredAsync(folder, arguments, cancellationToken));
                if (validation.Error is not null || string.IsNullOrWhiteSpace(validation.EffectiveCommit))
                {
                    SquadDashTrace.Write(
                        "PlanRecovery",
                        $"Rejected captured result plan={plan.PlanId} task={taskId} commit={candidate.Commit}: {validation.Error}");
                    continue;
                }

                var evidence = new PlanTaskCommitEvidence(
                    taskId,
                    candidate.ExecutionAttemptId,
                    taskBaseline,
                    validation.EffectiveCommit,
                    candidate.Summary,
                    candidate.Verification,
                    validation.Commits,
                    validation.ChangedFiles);
                var isDescendant = selectedEvidence is not null &&
                    !string.Equals(selectedEvidence.Commit, evidence.Commit, StringComparison.OrdinalIgnoreCase) &&
                    await PlanRecoveryGit.IsAncestorAsync(workspace, selectedEvidence.Commit, evidence.Commit, cancellationToken);
                var replacement = InterruptedPlanEvidenceRefresher.SelectReplacement(
                    selectedEvidence,
                    evidence,
                    (_, _) => isDescendant);
                if (replacement is null)
                {
                    if (selectedEvidence is not null)
                    {
                        if (!string.Equals(selectedEvidence.TaskId, evidence.TaskId, StringComparison.Ordinal))
                        {
                            SquadDashTrace.Write(
                                "PlanRecovery",
                                $"Skipped captured task evidence refresh task={taskId} existingTask={selectedEvidence.TaskId} candidateTask={evidence.TaskId}.");
                        }
                        else if (string.Equals(selectedEvidence.Commit, evidence.Commit, StringComparison.OrdinalIgnoreCase))
                        {
                            SquadDashTrace.Write(
                                "PlanRecovery",
                                $"Skipped captured task evidence refresh task={taskId} commit={evidence.Commit}: candidate commit matches recorded evidence.");
                        }
                        else
                        {
                            SquadDashTrace.Write(
                                "PlanRecovery",
                                $"Skipped captured task evidence refresh task={taskId} existing={selectedEvidence.Commit} candidate={evidence.Commit}: candidate is not a strict descendant.");
                        }
                    }
                    continue;
                }

                var merged = replacement with { Commits = MergeRecoveryEvidenceCommits(selectedEvidence, replacement) };
                if (selectedEvidence is null)
                {
                    SquadDashTrace.Write(
                        "PlanRecovery",
                        $"Restored captured task evidence plan={plan.PlanId} task={taskId} commit={merged.Commit}.");
                }
                else
                {
                    SquadDashTrace.Write(
                        "PlanRecovery",
                        $"Refreshed captured task evidence task={taskId} from={selectedEvidence.Commit} to={merged.Commit}");
                }
                selectedEvidence = merged;
                evidenceChanged = true;
            }

            if (!evidenceChanged)
                continue;
            if (!ReferenceEquals(store, _planStore) ||
                !string.Equals(workspace, _currentWorkspace?.FolderPath, StringComparison.OrdinalIgnoreCase) ||
                store.Load(plan.PlanId) is not { } latest ||
                !string.Equals(JsonSerializer.Serialize(latest), JsonSerializer.Serialize(plan), StringComparison.Ordinal))
            {
                SquadDashTrace.Write("PlanRecovery", $"Skipped evidence refresh for changed workspace or plan={plan.PlanId}.");
                continue;
            }

            var reconciled = plan with
            {
                InterruptionData = stableInterruption with
                {
                    TaskCommitEvidence = selectedEvidence,
                    LastCorrectionError = null,
                },
            };
            if (TryPublishPlanProgress(reconciled, out var saveError))
            {
                SquadDashTrace.Write(
                    "PlanRecovery",
                    $"Persisted captured task evidence refresh plan={plan.PlanId} task={taskId} commit={selectedEvidence?.Commit}.");
            }
            else
            {
                SquadDashTrace.Write(
                    "PlanRecovery",
                    $"Could not persist refreshed task evidence plan={plan.PlanId} task={taskId}: {saveError}");
            }
        }
        await RefreshRecoveryGitSnapshotAsync();
    }

    private static IReadOnlyList<PlanEvidenceCommit> MergeRecoveryEvidenceCommits(
        PlanTaskCommitEvidence? existingEvidence,
        PlanTaskCommitEvidence replacementEvidence)
    {
        var merged = new List<PlanEvidenceCommit>();
        var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        void AddCommit(PlanEvidenceCommit commit)
        {
            if (string.IsNullOrWhiteSpace(commit.Commit) || !seen.Add(commit.Commit))
                return;
            merged.Add(commit);
        }

        if (existingEvidence is not null)
        {
            foreach (var commit in existingEvidence.Commits ?? [])
                AddCommit(commit);
            if ((existingEvidence.Commits?.Count ?? 0) == 0 &&
                !string.IsNullOrWhiteSpace(existingEvidence.Commit))
            {
                AddCommit(new PlanEvidenceCommit(
                    existingEvidence.Commit,
                    PlanRecoveryCommitRelation.Task,
                    "Original host-recorded task result."));
            }
        }

        foreach (var commit in replacementEvidence.Commits ?? [])
            AddCommit(commit);
        if ((replacementEvidence.Commits?.Count ?? 0) == 0 &&
            !string.IsNullOrWhiteSpace(replacementEvidence.Commit))
        {
            AddCommit(new PlanEvidenceCommit(
                replacementEvidence.Commit,
                PlanRecoveryCommitRelation.Task,
                "Recovered host-validated task result."));
        }

        return merged;
    }

    private async Task InitializeApprovalRuntimeAsync()
    {
        // Developer simulations are deliberately session-scoped. Remove their disposable
        // Inbox artifact before restoring real workspace approval state after startup or a
        // workspace switch.
        ClearDeveloperApprovalSimulation(restoreInboxVisibility: false, refreshInbox: false);
        _inboxStore?.Delete(DeveloperApprovalSimulator.MessageId);
        foreach (var reviewWindow in _openPlanApprovalReviewWindows.Values.ToArray())
            reviewWindow.Close();
        _openPlanApprovalReviewWindows.Clear();
        _approvalTranscriptCards.Clear();
        _approvalPlansUpdating.Clear();
        _activePlanAwaitingGateApproval = null;
        _planReviewActivityRepairPending = false;
        _planApprovalRuntime = null;
        _approvalNotificationCoordinator = null;
        if (_currentWorkspace is null || _planStore is null || _inboxStore is null)
            return;

        var workspace = _currentWorkspace.FolderPath;
        var snapshotBuilder = new ApprovalReviewSnapshotBuilder(async (arguments, cancellationToken) =>
        {
            cancellationToken.ThrowIfCancellationRequested();
            return await RunGitAsync(workspace, arguments);
        }, _inboxStore);
        var requests = new DurableApprovalRequestManager(_inboxStore);
        var actions = new ApprovalActionCoordinator();
        _planApprovalRuntime = new PlanApprovalRuntime(
            requests,
            actions,
            async (plan, gate, cancellationToken) =>
            {
                try
                {
                    return await snapshotBuilder.BuildAsync(
                        plan, gate, cancellationToken: cancellationToken);
                }
                catch (Exception ex)
                {
                    // Approval itself must remain available if optional Git evidence cannot be read.
                    SquadDashTrace.Write("Approval", $"Review evidence fallback for {gate.GateId}: {ex.Message}");
                    return BuildLightweightApprovalSnapshot(plan, gate);
                }
            });
        _approvalNotificationCoordinator = new ApprovalCardNotificationCoordinator(
            requests,
            SoundNotifications,
            _pushNotificationService);

        var approvalPlans = _planStore.LoadAll().ToList();
        for (var index = 0; index < approvalPlans.Count; index++)
        {
            var plan = approvalPlans[index];
            if (!PlanExecutionBoundaryPolicy.ShouldRecoverInterruptedApprovalBoundary(plan))
                continue;

            try
            {
                var recovered = PlanStoreUpdater.ApplyApprovalBoundaryRecovery(plan);
                var advance = await _planApprovalRuntime.AdvanceAsync(recovered);
                if (TryPublishPlanProgress(advance.UpdatedPlan, out var recoveryError))
                {
                    approvalPlans[index] = advance.UpdatedPlan;
                    SquadDashTrace.Write(
                        "Approval",
                        $"Recovered interrupted approval boundary plan={plan.PlanId} gates={advance.NewlyReadyGates.Count}.");
                }
                else
                {
                    SquadDashTrace.Write(
                        "Approval",
                        $"Could not persist recovered approval boundary plan={plan.PlanId}: {recoveryError}");
                }
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write(
                    "Approval",
                    $"Could not recover interrupted approval boundary plan={plan.PlanId}: {ex.Message}");
            }
        }

        BindExistingManualTestKitMessages(_planStore.LoadAll());
        await _planApprovalRuntime.RestoreAsync(approvalPlans);
        PruneArchivedPlanFamilyArtifacts(approvalPlans);
        PlanRecoveryDecisionHandler.ArchiveObsoleteAppliedNotifications(_inboxStore);
        ReconcileDecomposeRecoveryInboxMessages();
        var messages = _inboxStore.LoadAll();
        _inboxPanel?.Refresh(messages);
        ReconcileOpenInboxWindows(messages);
    }

    private void BindExistingManualTestKitMessages(IReadOnlyList<Plan> plans)
    {
        if (_inboxStore is null || plans.Count == 0)
            return;

        foreach (var message in _inboxStore.LoadAll(includeApprovalKitSources: true))
        {
            var bound = ManualTestKitApprovalBinding.TryBindExistingMessage(message, plans);
            if (ReferenceEquals(bound, message))
                continue;

            _inboxStore.Save(bound);
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                $"Bound existing manual test kit message={message.Id} plan={bound.ResolvePlanGroupId()}");
        }
    }

    private async Task ProcessPlanApprovalsAfterStepAsync(
        string groupId,
        string revision,
        string completedTaskId,
        DecomposeGroupExecutionState groupState,
        Plan plan)
    {
        var hasReadyPendingGate = HasReadyPendingApprovalGate(plan);
        if (_planApprovalRuntime is null)
        {
            if (groupState == DecomposeGroupExecutionState.AwaitingApproval || hasReadyPendingGate)
                StopAndOfferDecomposeRecovery(
                    groupId, completedTaskId, revision,
                    "The approval runtime is unavailable for a ready plan checkpoint.");
            return;
        }

        var approvalMessageId = DurableApprovalRequestManager.BuildMessageId(plan.PlanId);
        var approvalMessageExisted = _inboxStore?.GetById(approvalMessageId) is not null;
        var pendingReadyGate = hasReadyPendingGate;
        if (pendingReadyGate)
        {
            foreach (var window in _openInboxWindows.Where(window =>
                         window.MessageId == approvalMessageId).ToArray())
                window.BeginApprovalUpdate();
        }

        ApprovalRuntimeAdvanceResult advance;
        _approvalPlansUpdating.Add(plan.PlanId);
        try
        {
            advance = await _planApprovalRuntime.AdvanceAsync(plan);
        }
        catch (Exception ex)
        {
            if (_inboxStore?.GetById(DurableApprovalRequestManager.BuildMessageId(plan.PlanId)) is { } currentMessage)
                RefreshOpenApprovalInboxWindows(currentMessage.Id, currentMessage);
            StopAndOfferDecomposeRecovery(
                groupId, completedTaskId, revision,
                $"SquadDash could not durably open the approval checkpoint: {ex.Message}");
            return;
        }
        finally
        {
            _approvalPlansUpdating.Remove(plan.PlanId);
        }

        if (!ReferenceEquals(advance.UpdatedPlan, plan) &&
            !TryPublishPlanProgress(advance.UpdatedPlan, out var publishError))
        {
            StopAndOfferDecomposeRecovery(
                groupId, completedTaskId, revision,
                "The approval checkpoint was created but plan state could not be persisted: " +
                (publishError ?? "unknown persistence failure"));
            return;
        }

        if (advance.NewlyReadyGates.Count > 0)
        {
            var primaryGate = advance.NewlyReadyGates[0];
            if (_approvalNotificationCoordinator is not null)
                await _approvalNotificationCoordinator.NotifyEarlyWindowAsync(advance.UpdatedPlan, primaryGate);

            if (advance.MessageId is not null && _inboxStore is not null)
            {
                var updatedMessage = _inboxStore.GetById(advance.MessageId);
                if (updatedMessage is not null)
                {
                    _inboxPanel?.Refresh(_inboxStore.LoadAll());
                    RefreshOpenApprovalInboxWindows(advance.MessageId, updatedMessage);
                    if (!approvalMessageExisted)
                        AppendInboxReceivedEntry(updatedMessage.Subject, updatedMessage.Id);
                }
            }
            RefreshOpenPlanBoundInboxWindows(
                advance.UpdatedPlan.PlanId,
                exceptMessageId: advance.MessageId);
            await TryShowApprovalCalloutAsync(advance.UpdatedPlan, primaryGate);
        }

        if (!advance.MustStop)
        {
            if (advance.NewlyReadyGates.Count > 0)
            {
                AppendLoopOutputLine(
                    $"⏳ Approval is available for {advance.NewlyReadyGates.Count} checkpoint(s); independent plan work will continue.",
                    LoopLifecycleBrush);
            }
            return;
        }

        var activeGates = advance.UpdatedPlan.ApprovalGates
            .Where(gate => gate.Status == PlanGateStatus.AwaitingApproval)
            .ToArray();
        if (activeGates.Length == 0 || advance.ClickToken is null || advance.ReviewSnapshot is null)
        {
            StopAndOfferDecomposeRecovery(
                groupId, completedTaskId, revision,
                "The plan reached an approval boundary without a durable approval action.");
            return;
        }

        _activePlanAwaitingGateApproval = activeGates[0].GateId;
        SuppressLoopResume("gate-approval-required");
        _loopController.RequestStop();
        AppendLoopOutputLine(
            $"⏸ Plan paused for {activeGates.Length} approval checkpoint(s).",
            LoopLifecycleBrush);
        AppendGateApprovalActions(
            advance.UpdatedPlan,
            activeGates[0],
            advance.ReviewSnapshot,
            advance.ClickToken);
    }

    /// <summary>
    /// On workspace load, restores the "Approve &amp; Continue Plan" button for any plan
    /// that was persisted with <see cref="PlanLifecycleStatus.AwaitingApproval"/>.
    /// Does not re-fire sound or push notifications (gate.NotifiedAt is already set).
    /// </summary>
    private void RestoreAwaitingApprovalGateUI(string? onlyPlanId = null)
    {
        if (_planStore is null || _planApprovalRuntime is null) return;
        (Plan Plan, PlanApprovalGate Gate)? attentionRequest = null;
        foreach (var plan in _planStore.LoadAll())
        {
            if (onlyPlanId is not null &&
                !string.Equals(plan.PlanId, onlyPlanId, StringComparison.Ordinal))
                continue;
            if (plan.LifecycleStatus != PlanLifecycleStatus.AwaitingApproval) continue;
            // A proposed plan revision is the higher-priority decision. Approving a checkpoint
            // from the currently authoritative definition while that proposal is unresolved is
            // both confusing and potentially stale. "Keep current plan" restores this surface.
            if (HasPendingPlanRevision(plan.PlanId)) continue;
            var awaitingGate = plan.ApprovalGates
                .FirstOrDefault(g => g.Status == PlanGateStatus.AwaitingApproval);
            if (awaitingGate is null) continue;
            var token = _planApprovalRuntime.Actions.GetCurrentToken(plan.PlanId);
            if (token is null) continue;
            _activePlanAwaitingGateApproval ??= awaitingGate.GateId;
            var snapshot = BuildLightweightApprovalSnapshot(plan, awaitingGate);
            Dispatcher.BeginInvoke(
                () => AppendGateApprovalActions(plan, awaitingGate, snapshot, token),
                System.Windows.Threading.DispatcherPriority.Background);
            attentionRequest ??= (plan, awaitingGate);
        }

        if (attentionRequest is { } request)
        {
            // The original attention cue does not survive a process restart. Replay one
            // cue after layout settles so the durable request is discoverable again.
            Dispatcher.BeginInvoke(
                new Action(async () => await TryShowApprovalCalloutAsync(request.Plan, request.Gate)),
                System.Windows.Threading.DispatcherPriority.ApplicationIdle);
        }
        SyncLoopPanel();
    }

    private void SuppressCheckpointApprovalCardsForPendingRevision(string planId)
    {
        if (_approvalTranscriptCards.Remove(planId, out var cards))
        {
            foreach (var card in cards)
            {
                if (card.Container.Parent is FlowDocument document)
                    document.Blocks.Remove(card.Container);
            }
        }
        if (_openPlanApprovalReviewWindows.Remove(planId, out var reviewWindow))
            reviewWindow.Close();

        _approvalAttentionCallout?.Close();
        _approvalAttentionCallout = null;
        SquadDashTrace.Write("PlanRevision",
            $"Suppressed checkpoint approval surface while plan revision is pending plan={planId}.");
    }

    private async Task RefreshOpenPlanApprovalReviewWindowAsync(Plan publishedPlan)
    {
        if (!_openPlanApprovalReviewWindows.TryGetValue(publishedPlan.PlanId, out var window) ||
            _planStore is null ||
            _planApprovalRuntime is null)
            return;

        try
        {
            var plan = _planStore.Load(publishedPlan.PlanId) ?? publishedPlan;
            var gate = plan.ApprovalGates.FirstOrDefault(candidate =>
                candidate.Status == PlanGateStatus.AwaitingApproval);
            if (gate is null)
            {
                _openPlanApprovalReviewWindows.Remove(plan.PlanId);
                window.Close();
                return;
            }

            await RefreshApprovalInboxMessageForUseAsync(
                DurableApprovalRequestManager.BuildMessageId(plan.PlanId));
            plan = _planStore.Load(plan.PlanId) ?? plan;
            gate = plan.ApprovalGates.FirstOrDefault(candidate =>
                candidate.Status == PlanGateStatus.AwaitingApproval);
            var token = _planApprovalRuntime.Actions.GetCurrentToken(plan.PlanId);
            if (gate is null || token is null)
            {
                _openPlanApprovalReviewWindows.Remove(plan.PlanId);
                window.Close();
                return;
            }
            if (window.Matches(token))
                return;

            ShowGateApprovalReviewWindow(
                plan,
                gate,
                BuildLightweightApprovalSnapshot(plan, gate),
                token,
                activate: false,
                status: "The approval changed while this window was open. Review the refreshed checklist.");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "Approval",
                $"Could not live-refresh approval review window plan={publishedPlan.PlanId}: {ex.Message}");
            if (_openPlanApprovalReviewWindows.TryGetValue(publishedPlan.PlanId, out var currentWindow))
                currentWindow.CancelApprovalUpdate(
                    "The approval may have changed. Close and reopen this window to refresh it.");
        }
    }

    /// <summary>Appends the normal execution-time approval card to the transcript.</summary>
    private void AppendGateApprovalActions(
        Plan plan,
        PlanApprovalGate gate,
        ApprovalReviewSnapshot snapshot,
        ApprovalClickToken clickToken)
    {
        var activeGates = plan.ApprovalGates
            .Where(candidate => candidate.Status == PlanGateStatus.AwaitingApproval)
            .ToArray();
        if (activeGates.Length > 0)
            snapshot = BuildLightweightApprovalSnapshot(plan, activeGates);

        TranscriptApprovalCardBuilder.CardResult? cardResult = null;
        cardResult = TranscriptApprovalCardBuilder.Build(
            snapshot,
            plan,
            gate,
            _transcriptFontSize,
            onApprove: note => _ = HandleApprovalClickAsync(clickToken, note),
            onRequestChanges: () =>
            {
                if (cardResult is not null)
                    TranscriptApprovalCardBuilder.ShowChangeRequestDraftingState(cardResult);
                BeginGateChangeRequest(plan.PlanId, gate.GateId, clickToken);
            },
            requestVersion: clickToken.RequestVersion,
            onOpenPlan: () => OpenPlanFromStore(plan),
            onOpenCommit: sha => _ = OpenCommitWithRemoteCheckAsync(sha),
            onOpenInbox: () => OpenOrFocusInboxMessage(
                DurableApprovalRequestManager.BuildMessageId(plan.PlanId)),
            onOpenEvidence: task => OpenApprovalStepEvidence(plan, task),
            onChecklistChanged: (item, isChecked) =>
                RecordHumanReviewChecklistSelection(plan.PlanId, item, isChecked),
            onClarifyItem: item => QueueClarifyHumanReviewItem(plan, item),
            onRefreshWordingItem: item => QueueRefreshHumanReviewWording(plan, item),
            onAddressUncheckedItems: uncheckedItems =>
            {
                if (cardResult is not null)
                    TranscriptApprovalCardBuilder.ShowChangeRequestDraftingState(cardResult);
                var reviewedTaskId = activeGates
                    .FirstOrDefault(candidate => string.Equals(
                        candidate.GateId,
                        uncheckedItems.FirstOrDefault()?.GateId,
                        StringComparison.Ordinal))?
                    .AfterTaskIds.FirstOrDefault()
                    ?? gate.AfterTaskIds.FirstOrDefault();
                if (!string.IsNullOrWhiteSpace(reviewedTaskId))
                    QueueAddressUncheckedItems(plan, reviewedTaskId, uncheckedItems, gate.GateId);
            });

        if (!_approvalTranscriptCards.TryGetValue(plan.PlanId, out var cards))
        {
            cards = [];
            _approvalTranscriptCards[plan.PlanId] = cards;
        }
        cards.Add(cardResult);
        CoordinatorThread.Document.Blocks.Add(cardResult.Container);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    /// <summary>
    /// Opens or refreshes the modeless per-plan approval window used by the Inbox action.
    /// This is additive and does not replace or retire a naturally rendered transcript card.
    /// </summary>
    private void ShowGateApprovalReviewWindow(
        Plan plan,
        PlanApprovalGate gate,
        ApprovalReviewSnapshot snapshot,
        ApprovalClickToken clickToken,
        bool activate = true,
        string? status = null)
    {
        var activeGates = plan.ApprovalGates
            .Where(candidate => candidate.Status == PlanGateStatus.AwaitingApproval)
            .ToArray();
        if (activeGates.Length > 0)
            snapshot = BuildLightweightApprovalSnapshot(plan, activeGates);

        TranscriptApprovalCardBuilder.CardResult? cardResult = null;
        cardResult = TranscriptApprovalCardBuilder.Build(
            snapshot,
            plan,
            gate,
            _transcriptFontSize,
            onApprove: note =>
            {
                if (_openPlanApprovalReviewWindows.TryGetValue(plan.PlanId, out var window))
                    window.BeginApprovalUpdate();
                _ = HandleApprovalClickAsync(clickToken, note, openedFromReviewWindow: true);
            },
            onRequestChanges: () =>
            {
                if (cardResult is not null)
                    TranscriptApprovalCardBuilder.ShowChangeRequestDraftingState(cardResult);
                BeginGateChangeRequest(plan.PlanId, gate.GateId, clickToken);
            },
            requestVersion: clickToken.RequestVersion,
            onOpenPlan: () => OpenPlanFromStore(plan),
            onOpenCommit: sha => _ = OpenCommitWithRemoteCheckAsync(sha),
            onOpenInbox: () => OpenOrFocusInboxMessage(
                DurableApprovalRequestManager.BuildMessageId(plan.PlanId)),
            onOpenEvidence: task => OpenApprovalStepEvidence(plan, task),
            onChecklistChanged: (item, isChecked) =>
                RecordHumanReviewChecklistSelection(plan.PlanId, item, isChecked),
            onClarifyItem: item => QueueClarifyHumanReviewItem(plan, item),
            onRefreshWordingItem: item => QueueRefreshHumanReviewWording(plan, item),
            onAddressUncheckedItems: uncheckedItems =>
            {
                if (cardResult is not null)
                    TranscriptApprovalCardBuilder.ShowChangeRequestDraftingState(cardResult);
                var reviewedTaskId = activeGates
                    .FirstOrDefault(candidate => string.Equals(
                        candidate.GateId,
                        uncheckedItems.FirstOrDefault()?.GateId,
                        StringComparison.Ordinal))?
                    .AfterTaskIds.FirstOrDefault()
                    ?? gate.AfterTaskIds.FirstOrDefault();
                if (!string.IsNullOrWhiteSpace(reviewedTaskId))
                    QueueAddressUncheckedItems(plan, reviewedTaskId, uncheckedItems, gate.GateId);
            });

        if (_openPlanApprovalReviewWindows.TryGetValue(plan.PlanId, out var existing))
        {
            existing.Replace(plan.Title, clickToken, cardResult, status);
            if (activate)
            {
                if (existing.WindowState == WindowState.Minimized)
                    existing.WindowState = WindowState.Normal;
                existing.Activate();
                NativeMethods.TryActivateWindow(
                    new System.Windows.Interop.WindowInteropHelper(existing).Handle);
            }
            return;
        }

        var reviewWindow = new PlanApprovalReviewWindow(
            plan.PlanId,
            plan.Title,
            clickToken,
            cardResult)
        {
            Owner = CanShowOwnedWindow() ? this : null,
        };
        if (!string.IsNullOrWhiteSpace(status))
            reviewWindow.ShowStatus(status);
        _openPlanApprovalReviewWindows[plan.PlanId] = reviewWindow;
        reviewWindow.Closed += (_, _) =>
        {
            _openPlanApprovalReviewWindows.Remove(plan.PlanId);
            FloatingWindowPositionStore.Shared.Save(
                $"PlanApproval:{plan.PlanId}", reviewWindow);
        };
        FloatingWindowPositionStore.Shared.TryRestore(
            $"PlanApproval:{plan.PlanId}", reviewWindow);
        reviewWindow.Show();
        if (activate)
        {
            reviewWindow.Activate();
            NativeMethods.TryActivateWindow(
                new System.Windows.Interop.WindowInteropHelper(reviewWindow).Handle);
        }
    }

    private void BeginGateChangeRequest(
        string planId,
        string gateId,
        ApprovalClickToken clickToken)
    {
        if (HasPendingPlanRevision(planId))
        {
            AppendLine("Resolve the pending plan revision proposal before changing this approval checkpoint.");
            return;
        }
        if (_planStore?.Load(planId) is not { } plan ||
            !string.Equals(plan.Revision, clickToken.PlanRevision, StringComparison.Ordinal))
        {
            AppendLine("⚠ This approval request changed. Reopen the current approval before requesting revisions.");
            return;
        }
        var gate = plan.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, gateId, StringComparison.Ordinal) &&
            candidate.Status == PlanGateStatus.AwaitingApproval);
        var currentToken = _planApprovalRuntime?.Actions.GetCurrentToken(planId);
        if (gate is null || currentToken is null || !clickToken.Matches(currentToken))
        {
            AppendLine("⚠ This approval request is stale. Reopen the current approval before requesting revisions.");
            return;
        }

        _pendingGateResponseContext = new PendingGateResponseContext(clickToken, gateId);
        _pendingSupplementalPromptInstruction = PlanGateResponseParser.BuildClassificationInstruction(
            plan,
            gate,
            clickToken);
        if (_approvalTranscriptCards.TryGetValue(planId, out var cards))
            foreach (var card in cards)
                TranscriptApprovalCardBuilder.ShowChangeRequestDraftingState(card);

        AppendLine($"What would you like changed in “**{gate.Message}**”? Describe it in the prompt box. " +
                   "The plan will remain awaiting approval until SquadDash receives a valid rework or amendment decision.");
        PromptTextBox.Focus();
    }

    private void SyncGateChangeActivity(bool isPromptRunning)
    {
        var pendingActivity = PlanReviewCorrectionActivityPolicy.ResolveActive(
            _pendingGateResponseContext is { } gateContext
                ? (gateContext.Token.PlanId, gateContext.GateId)
                : null,
            _pendingPlanReviewCorrectionContext,
            isPromptRunning);
        if (pendingActivity is { } next)
        {
            if (_activeGateChangeActivity == next)
            {
                if (isPromptRunning && _pendingPlanReviewCorrectionContext is not null &&
                    _approvalTranscriptCards.TryGetValue(next.PlanId, out var activeCards))
                {
                    foreach (var card in activeCards)
                        TranscriptApprovalCardBuilder.HideWhileCorrectionRuns(card);
                }
                return;
            }

            if (_activeGateChangeActivity is { } previous)
                _broker.Publish(new PlanApprovalChangeActivityEvent(
                    previous.PlanId, previous.GateId, IsActive: false));

            _activeGateChangeActivity = next;
            _broker.Publish(new PlanApprovalChangeActivityEvent(
                next.PlanId, next.GateId, IsActive: true));
            if (_pendingPlanReviewCorrectionContext is not null &&
                _approvalTranscriptCards.TryGetValue(next.PlanId, out var cards))
            {
                foreach (var card in cards)
                {
                    if (isPromptRunning)
                        TranscriptApprovalCardBuilder.HideWhileCorrectionRuns(card);
                    else
                        TranscriptApprovalCardBuilder.ShowChangeRequestDraftingState(card);
                }
            }
            return;
        }

        if (_activeGateChangeActivity is not { } active)
            return;

        _activeGateChangeActivity = null;
        _broker.Publish(new PlanApprovalChangeActivityEvent(
            active.PlanId, active.GateId, IsActive: false));
    }

    private void SyncPlanTaskCorrectionActivity(bool isPromptRunning)
    {
        var taskContext = _pendingPlanTaskCorrectionContext;
        var reviewContext = _pendingPlanReviewCorrectionContext;
        var dispatchedItem = _pec.CurrentDispatchedItem;
        (string PlanId, string TaskId, PlanTaskCorrectionActivityState State)? next = taskContext is not null
            ? (taskContext.PlanId,
               taskContext.TaskId,
               PlanTaskCorrectionActivityPolicy.Resolve(
                   taskContext,
                   taskContext.PlanId,
                   taskContext.TaskId,
                   isPromptRunning,
                   dispatchedItem?.Id,
                   dispatchedItem?.SourceTag))
            : reviewContext is not null
                ? (reviewContext.PlanId,
                   reviewContext.TaskId,
                   PlanReviewCorrectionTaskActivityPolicy.Resolve(
                       reviewContext,
                       reviewContext.PlanId,
                       reviewContext.TaskId,
                       isPromptRunning,
                       dispatchedItem?.Id,
                       dispatchedItem?.SourceTag))
                : null;
        if (_publishedPlanTaskCorrectionActivity == next)
            return;

        if (_publishedPlanTaskCorrectionActivity is { } previous &&
            (next is null ||
             !string.Equals(previous.PlanId, next.Value.PlanId, StringComparison.Ordinal) ||
             !string.Equals(previous.TaskId, next.Value.TaskId, StringComparison.Ordinal)))
        {
            _broker.Publish(new PlanTaskCorrectionActivityEvent(
                previous.PlanId,
                previous.TaskId,
                PlanTaskCorrectionActivityState.None));
        }

        _publishedPlanTaskCorrectionActivity = next;
        if (next is { } activity)
        {
            SquadDashTrace.Write(
                "Plan",
                $"Task correction activity plan={activity.PlanId} task={activity.TaskId} " +
                $"state={activity.State} promptRunning={isPromptRunning} " +
                $"queueItem={dispatchedItem?.Id ?? "(none)"} sourceTag={dispatchedItem?.SourceTag ?? "(none)"}.");
            _broker.Publish(new PlanTaskCorrectionActivityEvent(
                activity.PlanId,
                activity.TaskId,
                activity.State));
        }
    }

    /// <summary>
    /// Builds a lightweight <see cref="ApprovalReviewSnapshot"/> from plan data and bound Inbox guides
    /// without requiring async git operations. Used for immediate transcript card rendering.
    /// </summary>
    private ApprovalReviewSnapshot BuildLightweightApprovalSnapshot(Plan plan, PlanApprovalGate gate)
        => BuildLightweightApprovalSnapshot(plan, [gate]);

    private ApprovalReviewSnapshot BuildLightweightApprovalSnapshot(
        Plan plan,
        IReadOnlyList<PlanApprovalGate> gates)
    {
        if (gates.Count == 0)
            throw new ArgumentException("At least one approval gate is required.", nameof(gates));

        var afterSet = gates
            .SelectMany(candidate => candidate.AfterTaskIds)
            .ToHashSet(StringComparer.Ordinal);
        var beforeSet = gates
            .SelectMany(candidate => candidate.BeforeTaskIds)
            .ToHashSet(StringComparer.Ordinal);

        var completedTasks = plan.Tasks
            .Where(t => afterSet.Contains(t.TaskId) &&
                        t.Status is PlanTaskStatus.Complete or PlanTaskStatus.Partial)
            .Select(t =>
            {
                var commits = new List<ReviewCommitEntry>();
                if (!string.IsNullOrEmpty(t.Commit))
                {
                    var sha = t.Commit!;
                    var shortSha = sha.Length >= 7 ? sha[..7] : sha;
                    commits.Add(new ReviewCommitEntry(
                        new CommitLink(shortSha, sha, t.CompletionSummary ?? t.Title ?? t.TaskId),
                        VerificationPassed: null,
                        ChangedFiles: []));
                }
                return new ReviewTaskEntry(t.TaskId, t.Title ?? t.TaskId, t.CompletionSummary, commits);
            })
            .ToList();

        var downstreamTasks = plan.Tasks
            .Where(t => beforeSet.Contains(t.TaskId) &&
                        t.Status is PlanTaskStatus.Pending or PlanTaskStatus.Executing)
            .Select(t => new DownstreamTaskEntry(t.TaskId, t.Title ?? t.TaskId, t.Status))
            .ToList();

        return new ApprovalReviewSnapshot(
            PlanId: plan.PlanId,
            PlanTitle: plan.Title,
            CompletedTaskCount: plan.Progress.CompletedCount,
            TotalTaskCount: plan.Progress.TotalCount,
            CurrentStage: null,
            GateId: gates[0].GateId,
            GateReason: string.Join("; ", gates.Select(candidate => candidate.Message)),
            AfterTaskIds: plan.Tasks.Where(task => afterSet.Contains(task.TaskId)).Select(task => task.TaskId).ToArray(),
            BeforeTaskIds: plan.Tasks.Where(task => beforeSet.Contains(task.TaskId)).Select(task => task.TaskId).ToArray(),
            CompletedTasks: completedTasks,
            DownstreamTasks: downstreamTasks,
            AllChangedFiles: [],
            IndependentWork: [],
            BuiltAt: DateTimeOffset.UtcNow,
            HasOperatorInstructions: DurableApprovalRequestManager.HasOperatorInstructions(plan, gates, _inboxStore));
    }

    private sealed record InboxAttentionCalloutText(
        string Menu,
        string MessageRow,
        string FilteredPanel);

    private static readonly InboxAttentionCalloutText ApprovalInboxAttentionText = new(
        "**You have an approval request in your Inbox.**\n\nOpen **Inbox** to review the completed work and approve continuation.",
        "**Approval request ready.**\n\nOpen this message to review the completed work and approve continuation.",
        "**Approval request ready.**\n\nThe request is in your Inbox but may be hidden by the current Inbox filter.");

    private static readonly InboxAttentionCalloutText PlanInboxAttentionText = new(
        "**A plan moved to your Inbox.**\n\nOpen **Inbox** to review the plan and choose what to do with it.",
        "**Plan ready for review.**\n\nOpen this message to view the plan and choose an action.",
        "**Plan ready for review.**\n\nThe message is unread in your Inbox but may be hidden by the current filter.");

    /// <summary>
    /// Uses one targeting policy for every host-owned Inbox notification. During startup,
    /// persisted panel visibility is authoritative even before deferred panel restoration has
    /// created the controller, preventing an already-visible Inbox from being routed via Tools.
    /// </summary>
    private async Task<InboxAttentionTargetKind?> ShowInboxAttentionCalloutAsync(
        string messageId,
        InboxAttentionCalloutText text)
    {
        var shouldUsePanel = InboxAttentionTargetPolicy.ShouldUseInboxPanel(
            _inboxPanel?.PanelVisible == true,
            _docsPanelState?.InboxPanelVisible == true);
        if (shouldUsePanel && _inboxPanel?.PanelVisible != true)
        {
            EnsureInboxPanelCreated();
            _inboxPanel!.Show(flash: false);
        }

        if (_inboxPanel?.PanelVisible == true)
        {
            await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Loaded);
            await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Render);

            var row = _inboxPanel.FindVisibleMessageRow(messageId);
            var targetKind = InboxAttentionTargetPolicy.Select(
                panelVisible: true,
                messageRowVisible: row is not null);
            FrameworkElement target;
            string markdown;
            if (targetKind == InboxAttentionTargetKind.MessageRow)
            {
                row!.BringIntoView();
                await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.Render);
                target = row;
                markdown = text.MessageRow;
            }
            else
            {
                target = InboxPanelBorder;
                markdown = text.FilteredPanel;
            }

            ShowApprovalAttentionCallout(markdown, target, placement: CalloutPlacement.West);
            return _approvalAttentionCallout is null ? null : targetKind;
        }

        _approvalAttentionCallout?.Close();
        _approvalAttentionCallout = null;
        await Dispatcher.InvokeAsync(() => { }, DispatcherPriority.ContextIdle);
        var popupRoot = await _guidedTourCoordinator.OpenTourMenuItemAsync(
            PanelsMenuItem, nameof(PanelsMenuItem));
        var menuTarget = popupRoot is null
            ? null
            : VisualTreeSearch.FindByName(popupRoot, nameof(ViewInboxMenuItem)) as FrameworkElement
              ?? (PresentationSource.FromVisual(ViewInboxMenuItem) is not null
                  ? ViewInboxMenuItem
                  : null);
        if (menuTarget is null)
        {
            _guidedTourCoordinator.ClearTourMenuTracking(closeMenus: true);
            return null;
        }

        _guidedTourCoordinator.KeepTourMenuPathOpen(
            nameof(PanelsMenuItem), [PanelsMenuItem]);
        ShowApprovalAttentionCallout(text.Menu, menuTarget, placement: CalloutPlacement.East);
        var menuCallout = _approvalAttentionCallout;
        if (menuCallout is null)
        {
            _guidedTourCoordinator.ClearTourMenuTracking(closeMenus: true);
            return null;
        }

        menuCallout.Closed += (_, _) =>
        {
            if (ReferenceEquals(_approvalAttentionCallout, menuCallout))
                _guidedTourCoordinator.ClearTourMenuTracking(closeMenus: false);
        };
        return InboxAttentionTargetKind.Menu;
    }

    /// <summary>
    /// Shows a one-time Ultimate Callout at the visible Inbox request or Inbox menu item.
    /// </summary>
    private async Task TryShowApprovalCalloutAsync(Plan plan, PlanApprovalGate gate)
    {
        try
        {
            var messageId = DurableApprovalRequestManager.BuildMessageId(plan.PlanId);
            if (_shownApprovalCalloutMessageIds.Contains(messageId))
                return;

            // Never hold startup or approval processing open waiting for foreground activation.
            // Remember only durable IDs; MainWindow_Activated will reload and revalidate them.
            if (!WindowHelper.IsCurrentProcessForeground())
            {
                DeferApprovalCallout(plan.PlanId, gate.GateId);
                SquadDashTrace.Write("Approval", $"Callout deferred until SquadDash owns the foreground window plan={plan.PlanId} gate={gate.GateId}.");
                return;
            }

            ClearDeferredApprovalCallout();
            _pendingApprovalCalloutMessageId = messageId;

            var targetKind = await ShowInboxAttentionCalloutAsync(
                messageId,
                ApprovalInboxAttentionText);
            if (targetKind is null)
            {
                DeferApprovalCallout(plan.PlanId, gate.GateId);
                SquadDashTrace.Write("Approval", "Inbox attention target was unavailable; approval callout deferred.");
            }
            else
            {
                _shownApprovalCalloutMessageIds.Add(messageId);
                if (targetKind != InboxAttentionTargetKind.Menu)
                    _pendingApprovalCalloutMessageId = null;
            }
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Approval", $"Callout display failed: {ex.Message}");
        }
    }

    private async Task TryShowDeferredApprovalCalloutAsync()
    {
        SquadDashTrace.Write("Approval",
            $"Deferred callout evaluation entered deferred={_deferredApprovalCallout is not null} "
            + $"planStoreReady={_planStore is not null} {WindowHelper.DescribeForegroundOwnership()}.");

        if (_deferredApprovalCallout is not { } deferred || _planStore is null)
        {
            SquadDashTrace.Write("Approval", "Deferred callout evaluation skipped: no deferred request or plan store not ready.");
            return;
        }

        var messageId = DurableApprovalRequestManager.BuildMessageId(deferred.PlanId);
        if (_shownApprovalCalloutMessageIds.Contains(messageId))
        {
            ClearDeferredApprovalCallout();
            SquadDashTrace.Write("Approval", $"Deferred callout evaluation skipped: message already shown message={messageId}.");
            return;
        }

        var plan = _planStore.Load(deferred.PlanId);
        var gate = plan?.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, deferred.GateId, StringComparison.Ordinal) &&
            candidate.Status == PlanGateStatus.AwaitingApproval);
        if (plan is null || gate is null || plan.LifecycleStatus != PlanLifecycleStatus.AwaitingApproval)
        {
            ClearDeferredApprovalCallout();
            SquadDashTrace.Write("Approval", $"Deferred callout no longer eligible plan={deferred.PlanId} gate={deferred.GateId}.");
            return;
        }

        await TryShowApprovalCalloutAsync(plan, gate);
    }

    private void SchedulePendingPlanInboxCallout(string messageId)
    {
        _deferredPlanInboxCalloutMessageId = messageId;
        if (_deferredPlanInboxCalloutTimer is null)
        {
            _deferredPlanInboxCalloutTimer = new DispatcherTimer
            {
                Interval = TimeSpan.FromMilliseconds(200)
            };
            _deferredPlanInboxCalloutTimer.Tick += async (_, _) =>
            {
                if (_deferredPlanInboxCalloutEvaluationRunning ||
                    _deferredPlanInboxCalloutMessageId is null ||
                    !WindowHelper.IsCurrentProcessForeground())
                {
                    return;
                }

                _deferredPlanInboxCalloutEvaluationRunning = true;
                try
                {
                    await TryShowDeferredPlanInboxCalloutAsync();
                }
                catch (Exception ex)
                {
                    SquadDashTrace.Write(TraceCategory.Inbox,
                        $"Deferred pending-plan Inbox callout failed: {ex.Message}");
                }
                finally
                {
                    _deferredPlanInboxCalloutEvaluationRunning = false;
                }
            };
        }
        if (!_deferredPlanInboxCalloutTimer.IsEnabled)
            _deferredPlanInboxCalloutTimer.Start();
        _ = Dispatcher.BeginInvoke(
            new Action(async () => await TryShowDeferredPlanInboxCalloutAsync()),
            DispatcherPriority.ApplicationIdle);
    }

    private async Task TryShowDeferredPlanInboxCalloutAsync()
    {
        var messageId = _deferredPlanInboxCalloutMessageId;
        if (messageId is null || _shownApprovalCalloutMessageIds.Contains(messageId))
            return;

        if (!TryGetUnreadAutomaticPlanReminder(messageId, out _, out _))
        {
            ClearPendingPlanInboxCallout(messageId);
            return;
        }

        // Approval requests remain the higher-priority host-owned attention cue.
        if (_deferredApprovalCallout is not null || _pendingApprovalCalloutMessageId is not null)
            return;

        if (!WindowHelper.IsCurrentProcessForeground())
            return;

        _pendingPlanInboxCalloutMessageId = messageId;
        var targetKind = await ShowInboxAttentionCalloutAsync(
            messageId,
            PlanInboxAttentionText);
        if (targetKind is null)
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"Pending-plan Inbox callout deferred because no truthful target was available message={messageId}.");
            return;
        }

        _shownApprovalCalloutMessageIds.Add(messageId);
        _activePlanInboxCalloutMessageId = messageId;
        if (targetKind != InboxAttentionTargetKind.Menu)
            _pendingPlanInboxCalloutMessageId = null;
        _deferredPlanInboxCalloutMessageId = null;
        _deferredPlanInboxCalloutTimer?.Stop();
    }

    private bool TryGetUnreadAutomaticPlanReminder(
        string messageId,
        out PendingDecomposePlan? plan,
        out InboxMessage? message)
    {
        plan = null;
        message = _inboxStore?.GetById(messageId);
        var attachment = message?.ResolvePlanAttachment();
        if (_currentWorkspace is null || attachment?.PlanGroupId is not { Length: > 0 } groupId)
            return false;

        plan = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Load(groupId);
        return plan is not null && DecomposePlanInbox.IsUnreadAutomaticReminder(plan, message);
    }

    private async Task ShowPendingPlanInboxRowCalloutAsync()
    {
        var messageId = _pendingPlanInboxCalloutMessageId;
        if (messageId is null || _inboxPanel?.PanelVisible != true)
            return;

        if (!TryGetUnreadAutomaticPlanReminder(messageId, out _, out _))
        {
            ClearPendingPlanInboxCallout(messageId);
            return;
        }

        var targetKind = await ShowInboxAttentionCalloutAsync(
            messageId,
            PlanInboxAttentionText);
        if (targetKind is not null)
        {
            _activePlanInboxCalloutMessageId = messageId;
            _pendingPlanInboxCalloutMessageId = null;
            _deferredPlanInboxCalloutMessageId = null;
            _deferredPlanInboxCalloutTimer?.Stop();
        }
        else
        {
            _pendingPlanInboxCalloutMessageId = messageId;
            _deferredPlanInboxCalloutMessageId = messageId;
        }
    }

    private void ClearPendingPlanInboxCallout(string messageId)
    {
        if (string.Equals(_pendingPlanInboxCalloutMessageId, messageId, StringComparison.Ordinal))
            _pendingPlanInboxCalloutMessageId = null;
        if (string.Equals(_deferredPlanInboxCalloutMessageId, messageId, StringComparison.Ordinal))
        {
            _deferredPlanInboxCalloutMessageId = null;
            _deferredPlanInboxCalloutTimer?.Stop();
        }
        if (string.Equals(_activePlanInboxCalloutMessageId, messageId, StringComparison.Ordinal))
        {
            _approvalAttentionCallout?.Close();
            _approvalAttentionCallout = null;
            _activePlanInboxCalloutMessageId = null;
        }
    }

    private void DeferApprovalCallout(string planId, string gateId)
    {
        _deferredApprovalCallout = (planId, gateId);
        if (_deferredApprovalCalloutTimer is null)
        {
            _deferredApprovalCalloutTimer = new DispatcherTimer
            {
                Interval = TimeSpan.FromMilliseconds(200)
            };
            _deferredApprovalCalloutTimer.Tick += async (_, _) =>
            {
                if (_deferredApprovalCalloutEvaluationRunning ||
                    _deferredApprovalCallout is null ||
                    !WindowHelper.IsCurrentProcessForeground())
                    return;

                _deferredApprovalCalloutEvaluationRunning = true;
                try
                {
                    SquadDashTrace.Write("Approval",
                        $"Deferred callout foreground watcher triggered {WindowHelper.DescribeForegroundOwnership()}.");
                    await TryShowDeferredApprovalCalloutAsync();
                }
                catch (Exception ex)
                {
                    SquadDashTrace.Write("Approval", $"Deferred callout foreground watcher failed: {ex.Message}");
                }
                finally
                {
                    _deferredApprovalCalloutEvaluationRunning = false;
                }
            };
        }

        if (!_deferredApprovalCalloutTimer.IsEnabled)
            _deferredApprovalCalloutTimer.Start();
    }

    private void ClearDeferredApprovalCallout()
    {
        _deferredApprovalCallout = null;
        _deferredApprovalCalloutTimer?.Stop();
    }

    private bool TryActivateValidationForNextIteration(Plan plan)
    {
        var activeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        var validation = PlanExecutionBoundaryPolicy.SelectValidation(
            plan,
            activeExecution?.ActiveValidationId);
        if (validation is null)
            return false;

        if (!string.Equals(activeExecution?.ActiveValidationId, validation.ValidationId, StringComparison.Ordinal) ||
            validation.Status == PlanValidationStatus.Ready)
            return ActivateValidationForNextIteration(plan.PlanId, plan, validation);
        else
            _CodeHealthGroupRunner?.ClearCurrentStep();
        return true;
    }

    /// <summary>
    /// Shows the second approval-attention cue once the Inbox panel is visible. It points to the
    /// exact durable per-plan message. If a user filter hides that row, the panel is used as a
    /// truthful fallback without mutating the user's filter settings.
    /// </summary>
    private async Task ShowPendingApprovalInboxRowCalloutAsync()
    {
        var messageId = _pendingApprovalCalloutMessageId;
        if (messageId is null || _inboxPanel?.PanelVisible != true)
            return;

        var targetKind = await ShowInboxAttentionCalloutAsync(
            messageId,
            ApprovalInboxAttentionText);
        if (targetKind is not null)
            _pendingApprovalCalloutMessageId = null;
    }

    private void ShowApprovalAttentionCallout(
        string markdown,
        FrameworkElement target,
        CalloutPlacement placement)
    {
        // Menu opening and row layout both yield to the dispatcher before reaching here.
        // SquadDash may lose foreground activation during those awaits, so this is the
        // authoritative display-time check rather than relying only on the caller's check.
        if (!WindowHelper.IsCurrentProcessForeground())
        {
            _approvalAttentionCallout?.Close();
            _approvalAttentionCallout = null;
            _activePlanInboxCalloutMessageId = null;
            SquadDashTrace.Write("Approval", "Callout suppressed because another process owns the foreground window at display time.");
            return;
        }

        _approvalAttentionCallout?.Close();
        _activePlanInboxCalloutMessageId = null;
        var isDark = Resources.Contains("IsDarkTheme") && (bool)Resources["IsDarkTheme"];
        var theme = isDark ? CalloutTheme.Dark : CalloutTheme.Light;
        var fontSize = Application.Current?.Resources["FontSizeCallout"] is double calloutSize
            ? calloutSize
            : 18.0;
        _approvalAttentionCallout = FrmUltimateCallout.ShowCalloutBesideTarget(
            markdown,
            target,
            width: 330,
            theme: theme,
            fontSize: fontSize,
            placement: placement);
        if (_approvalAttentionCallout is not null)
        {
            _approvalAttentionCallout.ForceTopmost = true;
            _approvalAttentionCallout.Topmost = true;
            SquadDashTrace.Write("Approval",
                $"Approval callout displayed {WindowHelper.DescribeForegroundOwnership()}.");
        }
    }

    /// <summary>
    /// Notifies open inbox windows for an approval message that an update is starting,
    /// then replaces their content once the updated message is ready.
    /// </summary>
    private void RefreshOpenApprovalInboxWindows(string messageId, InboxMessage updatedMessage)
    {
        foreach (var win in _openInboxWindows.Where(w => w.MessageId == messageId).ToArray())
        {
            try
            {
                win.CompleteApprovalUpdate(updatedMessage, DispatchInboxAction);
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write("Approval", $"Inbox window refresh failed: {ex.Message}");
            }
        }
    }

    private async Task HandleApprovalClickAsync(
        ApprovalClickToken clickToken,
        string? note = null,
        IReadOnlyList<string>? gateIdsToResolve = null,
        bool openedFromReviewWindow = false)
    {
        if (await TryHandleDeveloperApprovalSimulationClickAsync(clickToken, note))
            return;
        if (_planStore is null || _planApprovalRuntime is null) return;
        if (HasPendingPlanRevision(clickToken.PlanId))
        {
            const string pendingRevisionMessage =
                "Resolve the pending plan revision proposal before approving this checkpoint. No approval state changed.";
            if (openedFromReviewWindow &&
                _openPlanApprovalReviewWindows.TryGetValue(clickToken.PlanId, out var pendingWindow))
                pendingWindow.CancelApprovalUpdate(pendingRevisionMessage);
            else
                AppendLine(pendingRevisionMessage);
            return;
        }
        if (_approvalPlansUpdating.Contains(clickToken.PlanId))
        {
            AppendLine("Approval details are being updated. Please use the refreshed approval button in a moment.");
            if (_inboxStore is not null)
            {
                var messages = _inboxStore.LoadAll();
                _inboxPanel?.Refresh(messages);
                var updatingMessageId = DurableApprovalRequestManager.BuildMessageId(clickToken.PlanId);
                if (_inboxStore.GetById(updatingMessageId) is { } updatingMessage)
                    RefreshOpenApprovalInboxWindows(updatingMessageId, updatingMessage);
            }
            return;
        }

        if (_approvalTranscriptCards.TryGetValue(clickToken.PlanId, out var cards))
            foreach (var card in cards) TranscriptApprovalCardBuilder.ShowUpdatingState(card);
        var messageId = DurableApprovalRequestManager.BuildMessageId(clickToken.PlanId);
        foreach (var window in _openInboxWindows.Where(window => window.MessageId == messageId).ToArray())
            window.BeginApprovalUpdate();

        var plan = _planStore.Load(clickToken.PlanId);
        if (plan is null)
        {
            var missingPlanText =
                $"Approval could not be applied because plan {clickToken.PlanId} no longer exists.";
            if (openedFromReviewWindow &&
                _openPlanApprovalReviewWindows.TryGetValue(clickToken.PlanId, out var missingPlanWindow))
                missingPlanWindow.CancelApprovalUpdate(missingPlanText);
            else
                AppendLine($"⚠ {missingPlanText}");
            if (_inboxStore?.GetById(messageId) is { } missingPlanMessage)
                RefreshOpenApprovalInboxWindows(messageId, missingPlanMessage);
            return;
        }

        var resolvedBy = _currentWorkspace is null
            ? Environment.UserName
            : await HumanApprovalIdentityResolver.ResolveAsync(_currentWorkspace.FolderPath);
        var primaryAction = PlanCheckpointPrimaryActionPresentationResolver.Resolve(
            plan,
            gateIdsToResolve ?? clickToken.GateIds);
        var representedGateIds = gateIdsToResolve ?? clickToken.GateIds;
        Func<Plan, Plan>? prepareResolution = null;
        string? currentHead = null;
        if (primaryAction is
            {
                Kind: PlanCheckpointPrimaryActionKind.CompleteHumanReviewTasks,
                ReviewAttentions.Count: > 0,
            })
        {
            void RejectReview(string message)
            {
                ReportPlanActionIssue(plan.PlanId, "Review could not be completed", message);
                if (cards is not null)
                    foreach (var card in cards) TranscriptApprovalCardBuilder.HideUpdatingState(card);
                if (_openPlanApprovalReviewWindows.TryGetValue(clickToken.PlanId, out var reviewWindow))
                    reviewWindow.CancelApprovalUpdate(message);
                if (_inboxStore?.GetById(messageId) is { } reviewMessage)
                    RefreshOpenApprovalInboxWindows(messageId, reviewMessage);
            }
            var workspace = _currentWorkspace?.FolderPath;
            var store = _planStore;
            using var validationBudget = new CancellationTokenSource(TimeSpan.FromSeconds(10));
            currentHead = await PlanRecoveryGit.TryReadHeadAsync(workspace, validationBudget.Token);
            if (currentHead is null)
            {
                RejectReview("Current Git evidence is unavailable. No task or checkpoint state changed; retry after Git is available.");
                return;
            }
            if (!PlanHumanReviewCheckpointCommitPolicy.OwnsCurrentHead(
                    plan, representedGateIds, currentHead))
            {
                RejectReview("The branch contains work beyond the represented checkpoint evidence. No state changed; reopen the review.");
                return;
            }
            var checkpointCommits = PlanHumanReviewCheckpointCommitPolicy.ResolveDurableCommits(
                plan, representedGateIds);
            foreach (var checkpointCommit in checkpointCommits)
            {
                if (await PlanRecoveryGit.IsAncestorAsync(
                        workspace, checkpointCommit, currentHead, validationBudget.Token))
                    continue;
                RejectReview("Represented checkpoint evidence is no longer reachable from the active branch. No state changed; reopen the review.");
                return;
            }
            var reviewedTaskCommits = new Dictionary<string, string>(StringComparer.Ordinal);
            foreach (var reviewAttention in primaryAction.ReviewAttentions)
            {
                if (!await ValidateHumanReviewStepAcceptanceAsync(
                        plan, reviewAttention, currentHead, validationBudget.Token))
                {
                    RejectReview("The review was not completed, so no task or checkpoint state changed.");
                    return;
                }
                var handoff = reviewAttention.Task.Handoff!;
                reviewedTaskCommits.Add(reviewAttention.Task.TaskId,
                    handoff.CompletionKind == DecomposeStepCompletionKind.VerifiedNoOp
                        ? handoff.EvaluatedCommit!
                        : handoff.Commit!);
            }
            var finalHead = await PlanRecoveryGit.TryReadHeadAsync(workspace, validationBudget.Token);
            var latest = store.Load(plan.PlanId);
            if (!ReferenceEquals(store, _planStore) ||
                !string.Equals(workspace, _currentWorkspace?.FolderPath, StringComparison.OrdinalIgnoreCase) ||
                !string.Equals(currentHead, finalHead, StringComparison.OrdinalIgnoreCase) ||
                latest is null ||
                !string.Equals(JsonSerializer.Serialize(latest), JsonSerializer.Serialize(plan), StringComparison.Ordinal))
            {
                RejectReview("The workspace, plan, or Git evidence changed during review. No state changed; reopen the review.");
                return;
            }
            prepareResolution = current =>
                PlanHumanReviewStepAcceptance.ApplyTasks(
                    current, primaryAction.ReviewAttentions, currentHead, reviewedTaskCommits);
        }
        var resolution = await _planApprovalRuntime.ApproveAsync(
            clickToken,
            plan,
            note,
            persistPlan: updated => TryPublishPlanProgress(updated, out _),
            gateIdsToResolve: gateIdsToResolve,
            resolvedBy: resolvedBy,
            prepareResolution: prepareResolution);

        if (resolution.Result == ApprovalClickResult.Approved && resolution.UpdatedPlan is not null)
        {
            if (string.Equals(_pendingApprovalCalloutMessageId, messageId, StringComparison.Ordinal))
                _pendingApprovalCalloutMessageId = null;
            _approvalAttentionCallout?.Close();
            _approvalAttentionCallout = null;
            _activePlanAwaitingGateApproval = resolution.UpdatedPlan.ApprovalGates
                .FirstOrDefault(gate => gate.Status == PlanGateStatus.AwaitingApproval)
                ?.GateId;
            if (cards is not null)
                foreach (var card in cards) TranscriptApprovalCardBuilder.ShowResolvedState(card);
            _approvalTranscriptCards.Remove(clickToken.PlanId);

            if (_inboxStore is not null)
            {
                var messages = _inboxStore.LoadAll();
                _inboxPanel?.Refresh(messages);
                var updatedMessage = _inboxStore.GetById(messageId);
                if (updatedMessage is not null)
                    RefreshOpenApprovalInboxWindows(messageId, updatedMessage);
            }
            RefreshOpenPlanBoundInboxWindows(clickToken.PlanId, exceptMessageId: messageId);

            AppendLoopOutputLine(
                $"▶ Approved {gateIdsToResolve?.Count ?? clickToken.GateIds.Count} checkpoint(s) for plan {clickToken.PlanId}.",
                LoopLifecycleBrush);
            if (resolution.NextClickToken is not null &&
                resolution.UpdatedPlan.LifecycleStatus == PlanLifecycleStatus.AwaitingApproval)
            {
                var remainingGate = resolution.UpdatedPlan.ApprovalGates.First(gate =>
                    gate.Status == PlanGateStatus.AwaitingApproval);
                if (openedFromReviewWindow ||
                    _openPlanApprovalReviewWindows.ContainsKey(clickToken.PlanId))
                {
                    ShowGateApprovalReviewWindow(
                        resolution.UpdatedPlan,
                        remainingGate,
                        BuildLightweightApprovalSnapshot(resolution.UpdatedPlan, remainingGate),
                        resolution.NextClickToken,
                        activate: openedFromReviewWindow);
                }
                if (!openedFromReviewWindow)
                {
                    AppendGateApprovalActions(
                        resolution.UpdatedPlan,
                        remainingGate,
                        BuildLightweightApprovalSnapshot(resolution.UpdatedPlan, remainingGate),
                        resolution.NextClickToken);
                }
            }
            else if (_openPlanApprovalReviewWindows.Remove(clickToken.PlanId, out var resolvedWindow))
            {
                resolvedWindow.Close();
            }
            var completedAtApproval = false;
            if (PlanExecutionBoundaryPolicy.IsReadyToComplete(resolution.UpdatedPlan))
            {
                var completedPlan = PlanStoreUpdater.ApplyCompleted(resolution.UpdatedPlan);
                if (TryPublishPlanProgress(completedPlan, out var completionError))
                {
                    completedAtApproval = true;
                    PublishPlanCompletionSummary(completedPlan);
                    ScheduleDecomposeSystemEntry(
                        PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(
                            completedPlan, "Final human approval accepted"));
                }
                else
                {
                    AppendLine("⚠ The checkpoint was approved, but final plan completion could not be saved: " +
                               (completionError ?? "unknown persistence failure"));
                }
            }
            if (resolution.ShouldResume && !completedAtApproval && !resolution.UpdatedPlan.IsPaused)
            {
                if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
                {
                    ScheduleApprovalResumeWhenIdle(clickToken.PlanId);
                    return;
                }
                try
                {
                    SquadDashTrace.Write(
                        "Approval",
                        $"Approval acquired; attempting automatic plan resume plan={clickToken.PlanId}.");
                    if (!await StartDecomposeLoopAsync(clickToken.PlanId))
                    {
                        if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
                        {
                            ScheduleApprovalResumeWhenIdle(clickToken.PlanId);
                            return;
                        }
                        SquadDashTrace.Write(
                            "Approval",
                            $"Automatic plan resume returned false plan={clickToken.PlanId}.");
                        ScheduleDecomposeSystemEntry(
                            $"Approval acquired for plan {clickToken.PlanId}, but the plan did not restart. " +
                            "Open the plan to retry continuation.");
                    }
                }
                catch (PlanPreflightBlockedException blocked)
                {
                    ScheduleApprovalResumeRetry(clickToken.PlanId, blocked);
                }
                catch (Exception ex)
                {
                    SquadDashTrace.Write(
                        "Approval",
                        $"Automatic plan resume failed plan={clickToken.PlanId}: {ex}");
                    ScheduleDecomposeSystemEntry(
                        $"Approval acquired for plan {clickToken.PlanId}, but automatic continuation failed: " +
                        ex.Message);
                }
            }
            return;
        }

        if (cards is not null)
            foreach (var card in cards) TranscriptApprovalCardBuilder.HideUpdatingState(card);

        if (resolution.Result == ApprovalClickResult.StaleRejected)
        {
            if (cards is not null)
            {
                foreach (var card in cards)
                    TranscriptApprovalCardBuilder.ShowHistoricalState(card);
                _approvalTranscriptCards.Remove(clickToken.PlanId);
            }

            try
            {
                var refreshedMessage = await RefreshApprovalInboxMessageForUseAsync(messageId);
                var currentToken = _planApprovalRuntime.Actions.GetCurrentToken(plan.PlanId);
                var currentGate = plan.ApprovalGates.FirstOrDefault(gate =>
                    gate.Status == PlanGateStatus.AwaitingApproval);
                if (refreshedMessage is not null && currentToken is not null && currentGate is not null)
                {
                    const string refreshedStatus =
                        "The approval changed, so the old action was not applied. " +
                        "SquadDash refreshed it from the current plan; review it and click again.";
                    if (!openedFromReviewWindow)
                        AppendLine($"⚠ {refreshedStatus}");
                    if (openedFromReviewWindow)
                    {
                        ShowGateApprovalReviewWindow(
                            plan,
                            currentGate,
                            BuildLightweightApprovalSnapshot(plan, currentGate),
                            currentToken,
                            status: refreshedStatus);
                    }
                    else
                    {
                        AppendGateApprovalActions(
                            plan,
                            currentGate,
                            BuildLightweightApprovalSnapshot(plan, currentGate),
                            currentToken);
                        if (_openPlanApprovalReviewWindows.ContainsKey(plan.PlanId))
                        {
                            ShowGateApprovalReviewWindow(
                                plan,
                                currentGate,
                                BuildLightweightApprovalSnapshot(plan, currentGate),
                                currentToken,
                                activate: false,
                                status: refreshedStatus);
                        }
                    }
                    return;
                }
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write(
                    "Approval",
                    $"Could not refresh stale approval action plan={clickToken.PlanId}: {ex.Message}");
            }
        }

        var reason = resolution.Result switch
        {
            ApprovalClickResult.AlreadyResolved => "This approval was already handled from another surface.",
            ApprovalClickResult.PersistenceFailed => "SquadDash could not save the plan transition; no approval was recorded.",
            _ => "This approval action is stale because the plan or approval request changed. Reopen the approval to refresh it.",
        };
        if (openedFromReviewWindow &&
            _openPlanApprovalReviewWindows.TryGetValue(clickToken.PlanId, out var failedWindow))
            failedWindow.CancelApprovalUpdate(reason);
        else
            AppendLine($"⚠ {reason}");

        if (_inboxStore?.GetById(messageId) is { } currentMessage)
            RefreshOpenApprovalInboxWindows(messageId, currentMessage);
    }

    private async Task<bool> TryHandleDeveloperApprovalSimulationClickAsync(
        ApprovalClickToken clickToken,
        string? note)
    {
        if (!string.Equals(
                clickToken.PlanId,
                DeveloperApprovalSimulator.PlanId,
                StringComparison.Ordinal))
            return false;

        var simulator = _developerApprovalSimulator;
        if (simulator is null || !simulator.IsActive)
        {
            const string inactiveMessage =
                "This developer approval simulation is no longer active. Clear it and start a fresh simulation.";
            if (_openPlanApprovalReviewWindows.TryGetValue(clickToken.PlanId, out var inactiveWindow))
                inactiveWindow.CancelApprovalUpdate(inactiveMessage);
            else
                AppendLine($"⚠ {inactiveMessage}");
            return true;
        }

        if (_approvalTranscriptCards.TryGetValue(clickToken.PlanId, out var cards))
            foreach (var card in cards) TranscriptApprovalCardBuilder.ShowUpdatingState(card);
        foreach (var window in _openInboxWindows.Where(window =>
                     window.MessageId == DeveloperApprovalSimulator.MessageId).ToArray())
            window.BeginApprovalUpdate();

        var resolution = await simulator.ApproveAsync(clickToken, note);
        if (resolution.Result == ApprovalClickResult.Approved)
        {
            if (string.Equals(
                    _pendingApprovalCalloutMessageId,
                    DeveloperApprovalSimulator.MessageId,
                    StringComparison.Ordinal))
                _pendingApprovalCalloutMessageId = null;
            _approvalAttentionCallout?.Close();
            _approvalAttentionCallout = null;
            if (cards is not null)
                foreach (var card in cards) TranscriptApprovalCardBuilder.ShowResolvedState(card);
            _approvalTranscriptCards.Remove(clickToken.PlanId);
            if (_openPlanApprovalReviewWindows.Remove(clickToken.PlanId, out var resolvedWindow))
                resolvedWindow.Close();

            RefreshDeveloperApprovalSimulationInbox();
            SquadDashTrace.Write(
                "Approval",
                "Developer approval simulation resolved; execution-loop resume intentionally suppressed.");
            return true;
        }

        if (cards is not null)
            foreach (var card in cards) TranscriptApprovalCardBuilder.HideUpdatingState(card);
        var failureMessage = resolution.Result == ApprovalClickResult.AlreadyResolved
            ? "This simulated approval was already handled."
            : "The simulated approval action became stale. Clear it and start a fresh simulation.";
        if (_openPlanApprovalReviewWindows.TryGetValue(clickToken.PlanId, out var failedWindow))
            failedWindow.CancelApprovalUpdate(failureMessage);
        else
            AppendLine($"⚠ {failureMessage}");
        RefreshDeveloperApprovalSimulationInbox();
        return true;
    }

    private void ApproveCurrentPlan(Plan plan, string? gateId = null)
    {
        var token = _planApprovalRuntime?.Actions.GetCurrentToken(plan.PlanId);
        if (token is not null)
            _ = HandleApprovalClickAsync(
                token,
                gateIdsToResolve: gateId is null ? null : [gateId]);
    }

    private async Task UnapproveCurrentPlanAsync(Plan displayedPlan, string gateId)
    {
        if (_planStore is null || _planApprovalRuntime is null) return;
        var current = _planStore.Load(displayedPlan.PlanId);
        if (current is null || !PlanGateManager.CanUnapproveGate(current, gateId)) return;

        var updated = PlanGateManager.UnapproveGate(current, gateId);
        if (ReferenceEquals(updated, current)) return;
        if (!TryPublishPlanProgress(updated, out var publishError))
        {
            if (publishError is not null)
                AppendLine($"⚠ The approval could not be reversed: {publishError}");
            return;
        }

        if (string.Equals(_approvalResumeRetryPlanId, updated.PlanId, StringComparison.Ordinal))
            StopApprovalResumeRetry();

        try
        {
            await _planApprovalRuntime.RestoreAsync([updated]);
            if (_inboxStore is not null)
            {
                var messages = _inboxStore.LoadAll();
                _inboxPanel?.Refresh(messages);
                var messageId = DurableApprovalRequestManager.BuildMessageId(updated.PlanId);
                if (_inboxStore.GetById(messageId) is { } message)
                    RefreshOpenApprovalInboxWindows(messageId, message);
            }
            AppendLoopOutputLine(
                $"↩ Reopened approval checkpoint {gateId} for plan {updated.PlanId}.",
                LoopLifecycleBrush);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Approval", $"Could not restore reversed approval {gateId}: {ex}");
            AppendLine(
                $"⚠ The approval was reversed, but its approval action could not be restored: {ex.Message}");
        }
    }

    /// <summary>
    /// Attempts to parse a <c>PLAN_GATE_APPROVAL_JSON:</c> block from <paramref name="rawResponse"/>.
    /// When found, validates the plan and gate, marks the gate approved, and resumes the loop.
    /// Returns <c>true</c> when the block was consumed (whether approved or rejected).
    /// </summary>
    private bool TryHandleGateApprovalFromResponse(string? rawResponse)
    {
        if (rawResponse is null || _planStore is null || _currentWorkspace is null) return false;
        if (!PlanGateApprovalParser.TryParse(rawResponse, out var approval) || approval is null) return false;

        var plan = _planStore.Load(approval.PlanId);
        if (plan is null)
        {
            AppendLoopOutputLine(
                $"⚠ Gate approval for plan {approval.PlanId} was rejected: plan not found.",
                LoopLifecycleBrush);
            return true;
        }

        if (!string.Equals(plan.Revision, approval.Revision, StringComparison.Ordinal))
        {
            AppendLoopOutputLine(
                $"⚠ Gate approval for plan {approval.PlanId} was rejected: revision mismatch.",
                LoopLifecycleBrush);
            return true;
        }

        var gate = plan.ApprovalGates.FirstOrDefault(g =>
            string.Equals(g.GateId, approval.GateId, StringComparison.Ordinal));
        if (gate is null)
        {
            AppendLoopOutputLine(
                $"⚠ Gate approval for plan {approval.PlanId} was rejected: gate '{approval.GateId}' not found.",
                LoopLifecycleBrush);
            return true;
        }
        if (gate.Status != PlanGateStatus.AwaitingApproval)
        {
            AppendLoopOutputLine(
                $"⚠ Gate approval for plan {approval.PlanId} was rejected: gate '{approval.GateId}' is not awaiting approval.",
                LoopLifecycleBrush);
            return true;
        }

        var token = _planApprovalRuntime?.Actions.GetCurrentToken(plan.PlanId);
        if (token is null ||
            !token.GateIds.Contains(gate.GateId, StringComparer.Ordinal) ||
            (approval.RequestVersion.HasValue && approval.RequestVersion.Value != token.RequestVersion))
        {
            AppendLoopOutputLine(
                $"⚠ Gate approval for plan {approval.PlanId} was rejected: durable approval request not found.",
                LoopLifecycleBrush);
            return true;
        }
        _ = HandleApprovalClickAsync(token, approval.Note, [approval.GateId]);
        return true;
    }

    private async Task<bool> TryHandleGateResponseFromResponseAsync(string? rawResponse)
    {
        if (!PlanGateResponseParser.TryParse(rawResponse, out var response) || response is null)
        {
            SquadDashTrace.Write("Approval",
                $"Gate response parser did not produce a payload markerPresent={rawResponse?.Contains(PlanGateResponseParser.Marker, StringComparison.Ordinal) == true} pendingContext={_pendingGateResponseContext is not null}.");
            if (PlanGateApprovalParser.TryParse(rawResponse, out var approval) && approval is not null)
            {
                ClearPendingGateResponse(approval.PlanId, keepForClarification: false);
                return false;
            }

            if (_pendingPlanReviewCorrectionContext is not null)
            {
                QueueUnifiedPlanReviewResponseRepair(
                    rawResponse?.Contains(PlanGateResponseParser.Marker, StringComparison.Ordinal) == true
                        ? $"The response used the legacy {PlanGateResponseParser.Marker} contract but did not match its schema."
                        : $"The required {PlanReviewResponseParser.Marker} object was missing.");
                return false;
            }

            if (_pendingGateResponseContext is not null)
                QueueGateResponseRepairOrExplainFailure();
            return false;
        }
        if (_planStore is null || _planApprovalRuntime is null)
        {
            SquadDashTrace.Write("Approval",
                $"Gate response ignored because runtime dependencies are unavailable planStore={_planStore is not null} approvalRuntime={_planApprovalRuntime is not null}.");
            return false;
        }

        var plan = _planStore.Load(response.PlanId);
        var currentToken = _planApprovalRuntime.Actions.GetCurrentToken(response.PlanId);
        var gate = plan?.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, response.GateId, StringComparison.Ordinal));
        if (plan is null || currentToken is null || gate is null ||
            gate.Status != PlanGateStatus.AwaitingApproval ||
            !string.Equals(plan.Revision, response.Revision, StringComparison.Ordinal) ||
            response.RequestVersion != currentToken.RequestVersion ||
            !currentToken.GateIds.Contains(response.GateId, StringComparer.Ordinal))
        {
            SquadDashTrace.Write("Approval",
                $"Gate response rejected as stale planFound={plan is not null} tokenFound={currentToken is not null} gateFound={gate is not null} gateStatus={gate?.Status} revisionMatch={string.Equals(plan?.Revision, response.Revision, StringComparison.Ordinal)} versionExpected={currentToken?.RequestVersion} versionActual={response.RequestVersion} gateInToken={currentToken?.GateIds.Contains(response.GateId, StringComparer.Ordinal) == true}.");
            AppendLine("⚠ The plan approval response was stale. No approval or rework state changed.");
            return true;
        }

        if (response.Disposition == PlanGateResponseDisposition.Unrelated)
        {
            ClearPendingGateResponse(response.PlanId, keepForClarification: false);
            AppendLine($"Plan **{plan.Title}** remains awaiting approval; the preceding request was handled as separate work.");
            return true;
        }
        if (response.Disposition == PlanGateResponseDisposition.Clarification)
        {
            _pendingGateResponseContext = new PendingGateResponseContext(
                currentToken,
                response.GateId);
            return true;
        }

        if (response.Disposition == PlanGateResponseDisposition.AddAmendment)
            return await ApplyGateAmendmentResponseAsync(plan, gate, currentToken, response);

        return await ApplyGateReworkResponseAsync(plan, gate, currentToken, response);
    }

    private bool TryHandleUnifiedPlanReviewResponse(string? rawResponse)
    {
        if (rawResponse?.Contains(PlanReviewResponseParser.Marker, StringComparison.Ordinal) != true)
            return false;

        if (!PlanReviewResponseParser.TryParse(rawResponse, out var response, out var error) || response is null)
        {
            var diagnostic = error;
            if (response is not null && _pendingGateResponseContext is { } context &&
                _planStore?.Load(context.Token.PlanId) is { } expectedPlan)
            {
                var expectedGate = expectedPlan.ApprovalGates.FirstOrDefault(candidate =>
                    string.Equals(candidate.GateId, context.GateId, StringComparison.Ordinal));
                if (expectedGate is not null)
                    diagnostic = PlanReviewResponseRepairDiagnostics.Build(
                        error, response, expectedPlan, expectedGate, context.Token);
            }
            SquadDashTrace.Write("Approval", $"Unified review response parse failed: {diagnostic}");
            QueueUnifiedPlanReviewResponseRepair(diagnostic);
            return true;
        }

        SquadDashTrace.Write("Approval",
            $"Unified review response parsed action={response.Action} plan={response.PlanId} gate={response.GateId} version={response.RequestVersion}.");
        _ = ApplyUnifiedPlanReviewResponseSafelyAsync(response);
        return true;
    }

    private async Task ApplyUnifiedPlanReviewResponseSafelyAsync(PlanReviewResponse response)
    {
        try
        {
            if (_planStore is null || _planApprovalRuntime is null)
            {
                SquadDashTrace.Write("Approval",
                    $"Unified review response stopped: runtime unavailable planStore={_planStore is not null} approvalRuntime={_planApprovalRuntime is not null}.");
                AppendLine("⚠ SquadDash could not apply the review response because approval state is unavailable.");
                return;
            }

            var plan = _planStore.Load(response.PlanId);
            var token = _planApprovalRuntime.Actions.GetCurrentToken(response.PlanId);
            var gate = plan?.ApprovalGates.FirstOrDefault(candidate =>
                string.Equals(candidate.GateId, response.GateId, StringComparison.Ordinal));
            var validation = PlanReviewResponseCorrelation.Validate(response, plan, gate, token);
            if (!validation.Success)
            {
                SquadDashTrace.Write("Approval", $"Unified review response stopped: {validation.Diagnostic}");
                AppendLine("⚠ The human-review response no longer matches the active checkpoint. Nothing changed.");
                return;
            }

            if (response.Action is PlanReviewResponseAction.Discuss or PlanReviewResponseAction.RecordCorrection)
            {
                ClearPendingGateResponse(response.PlanId, keepForClarification: false);
                await ApplyPlanReviewActivityResponseAsync(new PlanReviewActivityResponse(
                    response.PlanId,
                    response.Revision,
                    response.Action == PlanReviewResponseAction.Discuss
                        ? PlanReviewActivityKind.ReviewDiscussion
                        : PlanReviewActivityKind.ManualCorrection,
                    response.TaskIds!,
                    response.Summary!));
                return;
            }

            var disposition = response.Action switch
            {
                PlanReviewResponseAction.RequestRework => PlanGateResponseDisposition.RequestRework,
                PlanReviewResponseAction.AddAmendment => PlanGateResponseDisposition.AddAmendment,
                PlanReviewResponseAction.Clarify => PlanGateResponseDisposition.Clarification,
                _ => PlanGateResponseDisposition.Unrelated,
            };
            var gateResponse = new PlanGateResponse(
                response.PlanId,
                response.GateId,
                response.Revision,
                response.RequestVersion,
                disposition,
                response.TaskIds,
                response.Title,
                response.Instructions);
            if (disposition == PlanGateResponseDisposition.AddAmendment)
                await ApplyGateAmendmentResponseAsync(plan!, gate!, token!, gateResponse);
            else if (disposition == PlanGateResponseDisposition.RequestRework)
                await ApplyGateReworkResponseAsync(plan!, gate!, token!, gateResponse);
            else if (disposition == PlanGateResponseDisposition.Clarification)
                _pendingGateResponseContext = new PendingGateResponseContext(token!, response.GateId);
            else
                ClearPendingGateResponse(response.PlanId, keepForClarification: false);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Approval", $"Unified review response failed: {ex}");
            AppendLine("⚠ SquadDash could not apply the human-review response. The plan remains paused.");
        }
    }

    private void QueueUnifiedPlanReviewResponseRepair(string diagnostic)
    {
        var context = _pendingGateResponseContext;
        if (context is null || _planStore?.Load(context.Token.PlanId) is not { } plan)
        {
            SquadDashTrace.Write("Approval", "Unified review repair not queued: correlated gate context is unavailable.");
            AppendLine("⚠ SquadDash could not safely apply the human-review response because its approval context is no longer current. The plan remains paused.");
            return;
        }
        var gate = plan.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, context.GateId, StringComparison.Ordinal));
        var taskId = _pendingPlanReviewCorrectionContext?.TaskId ?? gate?.AfterTaskIds.FirstOrDefault();
        if (gate is null || string.IsNullOrWhiteSpace(taskId) || context.RepairAttempts > 0)
        {
            SquadDashTrace.Write("Approval",
                $"Unified review repair not queued: gateFound={gate is not null} taskFound={!string.IsNullOrWhiteSpace(taskId)} attempts={context.RepairAttempts}.");
            ClearPendingGateResponse(context.Token.PlanId, keepForClarification: false);
            ClearPendingPlanReviewCorrection(restoreCard: true);
            AppendLine("⚠ SquadDash could not safely apply the human-review response after one automatic metadata repair. The plan remains paused and the review actions are available again.");
            return;
        }

        _pendingGateResponseContext = context with { RepairAttempts = 1 };
        _promptQueue.EnqueueAtFront(
            PlanReviewResponseParser.BuildInstruction(plan, gate, context.Token, taskId, repair: true, diagnostic),
            _promptQueueCoordinator.NextSequenceNumber(),
            sourceTag: "plan-review-response-repair",
            isSystemInjected: true);
        SyncQueuePanel();
        AppendLine("SquadDash rejected invalid human-review response metadata and requested one automatic repair with the exact validation diagnostics. The plan remains paused while that repair runs.");
    }

    private bool TryHandleHumanReviewClarificationFromResponse(string? rawResponse)
    {
        if (rawResponse?.Contains(
                PlanHumanReviewClarificationResponseParser.Marker,
                StringComparison.Ordinal) != true)
            return false;

        if (!PlanHumanReviewClarificationResponseParser.TryParse(
                rawResponse, out var response, out var parseError) || response is null)
        {
            if (!_humanReviewClarificationRepairPending)
            {
                _humanReviewClarificationRepairPending = true;
                _promptQueue.EnqueueAtFront(
                    "Your previous clarification recommendation did not match the required " +
                    $"{PlanHumanReviewClarificationResponseParser.Marker} schema. " +
                    "Do not repeat analysis, change files, approve anything, or continue the plan. " +
                    "Return only one corrected complete payload using the exact planId, revision, gateId, " +
                    "itemId, and requestKind from the preceding clarification context. Obey the action and " +
                    "selection-preservation constraints for that requestKind. Null collections may be returned " +
                    "as empty arrays. Technical detail: " + parseError,
                    _promptQueueCoordinator.NextSequenceNumber(),
                    sourceTag: "plan-human-review-clarification-repair",
                    isSystemInjected: true);
                SyncQueuePanel();
                SyncSendButton();
                ShowSystemTranscriptEntry(
                    "SquadDash could not read the clarification recommendation. It requested one metadata-only repair; the plan remains paused.");
            }
            else
            {
                _humanReviewClarificationRepairPending = false;
                ShowSystemTranscriptEntry(
                    "SquadDash could not read the clarification recommendation after one repair. Nothing changed.");
            }
            return true;
        }

        _humanReviewClarificationRepairPending = false;
        var hasVisibleAnswer = !string.IsNullOrWhiteSpace(
            TranscriptTextUtilities.SanitizeResponseTextOrNull(rawResponse));
        _ = ApplyHumanReviewClarificationResponseAsync(response, hasVisibleAnswer);
        return true;
    }

    private bool HandleMissingHumanReviewClarificationResponse()
    {
        if (!_humanReviewClarificationRepairPending)
        {
            _humanReviewClarificationRepairPending = true;
            _promptQueue.EnqueueAtFront(
                "Your previous response used the wrong response contract or omitted the required " +
                $"{PlanHumanReviewClarificationResponseParser.Marker} payload. " +
                $"Do not emit {PlanReviewActivityResponseParser.Marker}. Do not repeat analysis, change files, " +
                "approve anything, or continue the plan. Return only one complete " +
                $"{PlanHumanReviewClarificationResponseParser.Marker} payload using the exact planId, revision, " +
                "gateId, itemId, and requestKind from the preceding human-review action context. Obey that " +
                "requestKind's action and selection-preservation constraints.",
                _promptQueueCoordinator.NextSequenceNumber(),
                sourceTag: HumanReviewResponseContractPolicy.RepairSourceTag,
                isSystemInjected: true);
            SyncQueuePanel();
            SyncSendButton();
            ShowSystemTranscriptEntry(
                "SquadDash did not receive the required human-review update. It requested one metadata-only correction; the review requirement and its selection remain unchanged.");
        }
        else
        {
            _humanReviewClarificationRepairPending = false;
            ShowSystemTranscriptEntry(
                "SquadDash did not receive the required human-review update after one correction. Nothing changed.");
        }

        // This turn belongs exclusively to the clarification contract. Never let a
        // syntactically valid generic review-activity payload masquerade as success.
        return true;
    }

    private async Task ApplyHumanReviewClarificationResponseAsync(
        PlanHumanReviewClarificationResponse response,
        bool hasVisibleAnswer)
    {
        // A clarification recommendation is the provider's completed response, not an
        // unfinished agent turn. Yield before opening any human decision UI so the response
        // callback can return, the bridge can become idle, and human think-time cannot trip
        // the stalled-agent watchdog. The plan remains unchanged until the user confirms.
        await Dispatcher.Yield(DispatcherPriority.Background);

        if (_planStore is null) return;
        var plan = _planStore.Load(response.PlanId);
        var gate = plan?.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, response.GateId, StringComparison.Ordinal));
        if (plan is null || gate is null ||
            !string.Equals(plan.Revision, response.Revision, StringComparison.Ordinal) ||
            gate.Status is not (PlanGateStatus.Pending or PlanGateStatus.AwaitingApproval))
        {
            ShowSystemTranscriptEntry(
                "The human-review checkpoint changed before clarification completed. Nothing changed.");
            return;
        }

        var checklist = PlanHumanReviewChecklist.Build(plan, [gate]);
        var item = checklist.FirstOrDefault(candidate =>
            string.Equals(candidate.ItemId, response.ItemId, StringComparison.Ordinal));
        if (item is null)
        {
            ShowSystemTranscriptEntry(
                "The human-review requirement changed before clarification completed. Nothing changed.");
            return;
        }

        if (!hasVisibleAnswer)
            ShowSystemTranscriptEntry(response.UserFacingAnswer);
        if (!PlanHumanReviewClarificationAction.ChangesReviewContract(response.Action))
            return;

        if (response.Action == PlanHumanReviewClarificationAction.Automate)
        {
            var validation = (plan.Validations ?? []).FirstOrDefault(candidate =>
                string.Equals(candidate.ValidationId, response.ExistingValidationId, StringComparison.Ordinal));
            if (validation is null ||
                !validation.AfterTaskIds.ToHashSet(StringComparer.Ordinal).SetEquals(gate.AfterTaskIds) ||
                !validation.BeforeTaskIds.ToHashSet(StringComparer.Ordinal).SetEquals(gate.BeforeTaskIds))
            {
                ShowSystemTranscriptEntry(
                    "The recommendation requires a new or differently placed automated validation. " +
                    "That change must use the plan-revision workflow, so this review card was not changed.");
                return;
            }
        }

        if (!HumanReviewClarificationDialog.Show(this, response, item))
        {
            ShowSystemTranscriptEntry("The clarification was answered, but its proposed review change was not applied.");
            return;
        }

        var recordedBy = _currentWorkspace is null
            ? Environment.UserName
            : await HumanApprovalIdentityResolver.ResolveAsync(_currentWorkspace.FolderPath);
        var updated = PlanStoreUpdater.ApplyHumanReviewClarification(
            plan, response, item, recordedBy);
        if (ReferenceEquals(updated, plan))
        {
            ShowSystemTranscriptEntry(
                "SquadDash could not apply the human-review clarification because the checkpoint changed. Nothing changed.");
            return;
        }
        if (!TryPublishPlanProgress(updated, out var saveError))
        {
            ShowSystemTranscriptEntry(
                "SquadDash could not save the human-review clarification. Nothing changed. " +
                (saveError ?? string.Empty));
            return;
        }

        await RefreshApprovalRequestAfterGateGuidanceEditAsync(updated);
        RefreshHumanReviewSurfaces(updated);
        ShowSystemTranscriptEntry(BuildHumanReviewClarificationAppliedMessage(response));
    }

    private static string BuildHumanReviewClarificationAppliedMessage(
        PlanHumanReviewClarificationResponse response) => response.Action switch
    {
        PlanHumanReviewClarificationAction.Reword when
            response.RequestKind == PlanHumanReviewClarificationRequestKind.RefreshWording =>
            "Human review wording refreshed. Review selection cleared.",
        PlanHumanReviewClarificationAction.Reword => "The human-review requirement was reworded.",
        PlanHumanReviewClarificationAction.Remove => "Human review requirement removed. Justification recorded in the plan.",
        PlanHumanReviewClarificationAction.Automate => "The human-review requirement was replaced with an automated validation.",
        PlanHumanReviewClarificationAction.Split => "The human-review requirement was split into focused checks.",
        PlanHumanReviewClarificationAction.Merge => "The human-review requirements were consolidated.",
        _ => "The human-review clarification was recorded.",
    };

    private void RefreshHumanReviewSurfaces(Plan plan)
    {
        if (plan.LifecycleStatus == PlanLifecycleStatus.AwaitingApproval &&
            _planApprovalRuntime is not null)
        {
            var transcriptCardWasVisible = _approvalTranscriptCards.ContainsKey(plan.PlanId);
            var reviewWindowWasOpen = _openPlanApprovalReviewWindows.ContainsKey(plan.PlanId);
            SuppressCheckpointApprovalCardsForPendingRevision(plan.PlanId);
            var gate = plan.ApprovalGates.FirstOrDefault(candidate =>
                candidate.Status == PlanGateStatus.AwaitingApproval);
            var token = _planApprovalRuntime.Actions.GetCurrentToken(plan.PlanId);
            if (gate is not null && token is not null)
            {
                var snapshot = BuildLightweightApprovalSnapshot(plan, gate);
                if (transcriptCardWasVisible || !reviewWindowWasOpen)
                    AppendGateApprovalActions(plan, gate, snapshot, token);
                if (reviewWindowWasOpen)
                    ShowGateApprovalReviewWindow(plan, gate, snapshot, token);
            }
            return;
        }

        if (plan.LifecycleStatus is PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked &&
            plan.InterruptionData?.InterruptedTaskId is { } taskId)
        {
            // This is an in-place data refresh of the current card, not a historical recovery
            // transition. Replace the whole plan-scoped surface so the old card body is not left
            // beside the refreshed card with only its buttons hidden.
            TranscriptQuickReplyFactory.RemoveDecomposeRecoveryContainers(
                CoordinatorThread.Document.Blocks, plan.PlanId);
            AppendDecomposeRecoveryActions(PendingDecomposePlanAdapter.FromPlan(plan), taskId);
            RefreshRecoveryInboxMessage(plan, taskId);
        }
    }

    private void RefreshRecoveryInboxMessage(Plan plan, string taskId)
    {
        if (_inboxStore is null ||
            (_pendingPlanTaskCorrectionContext is { } pending &&
             string.Equals(pending.PlanId, plan.PlanId, StringComparison.Ordinal) &&
             string.Equals(pending.TaskId, taskId, StringComparison.Ordinal)))
            return;

        var pendingPlan = PendingDecomposePlanAdapter.FromPlan(plan);
        var messageId = DecomposePlanInbox.BuildRecoveryMessageId(pendingPlan, taskId);
        var existing = _inboxStore.GetById(messageId);
        if (existing is null) return;
        var currentHead = ReadCachedRecoveryHeadCommit();

        var refreshed = DecomposePlanInbox.BuildRecoveryMessage(
            pendingPlan,
            taskId,
            plan.InterruptionData?.Reason ?? "Plan recovery is waiting for a decision.",
            existing.Timestamp,
            plan.InterruptionData?.TaskCommitEvidence,
            plan,
            currentHead,
            (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant)) with
        {
            Read = existing.Read,
        };
        _inboxStore.Save(refreshed);
        _inboxPanel?.Refresh(_inboxStore.LoadAll());
        RefreshOpenApprovalInboxWindows(messageId, refreshed);
    }

    private bool TryHandlePlanReviewActivityFromResponse(string? rawResponse)
    {
        if (!PlanReviewActivityResponseParser.TryParse(rawResponse, out var response) ||
            response is null)
        {
            if (rawResponse?.Contains(
                    PlanReviewActivityResponseParser.Marker,
                    StringComparison.Ordinal) != true)
            {
                ClearPendingPlanReviewCorrection(restoreCard: true);
                ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
                return false;
            }

            if (!_planReviewActivityRepairPending && _planStore is not null)
            {
                _planReviewActivityRepairPending = true;
                _promptQueue.EnqueueAtFront(
                    PlanReviewActivityResponseParser.BuildRepairInstruction(_planStore.LoadAll()),
                    _promptQueueCoordinator.NextSequenceNumber(),
                    sourceTag: "plan-review-activity-repair",
                    isSystemInjected: true);
                SyncQueuePanel();
                SyncSendButton();
                AppendLine("SquadDash could not read the conversational review metadata. " +
                           "It asked AI once to repair only that metadata; no plan state changed.");
            }
            else
            {
                _planReviewActivityRepairPending = false;
                AppendLine("⚠ SquadDash could not record the conversational review activity after one repair. " +
                           "The plan remains safely paused.");
            }
            return true;
        }
        _planReviewActivityRepairPending = false;
        _ = ApplyPlanReviewActivityResponseAsync(response);
        return true;
    }

    private async Task ApplyPlanReviewActivityResponseAsync(PlanReviewActivityResponse response)
    {
        if (_planStore is null)
        {
            ClearPendingPlanReviewCorrection(restoreCard: true);
            ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
            return;
        }

        var plan = _planStore.Load(response.PlanId);
        if (plan is null ||
            !string.Equals(plan.Revision, response.Revision, StringComparison.Ordinal) ||
            response.TaskIds.Any(taskId =>
                !PlanReviewActivityResponseParser.IsActiveTarget(plan, taskId)))
        {
            AppendLine("⚠ The conversational review context changed before the response completed. " +
                       "No plan review activity was recorded.");
            ClearPendingPlanReviewCorrection(restoreCard: true);
            ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
            return;
        }

        if (string.Equals(
                _pendingGateResponseContext?.Token.PlanId,
                response.PlanId,
                StringComparison.Ordinal))
            ClearPendingGateResponse(response.PlanId, keepForClarification: false);

        if (response.Activity == PlanReviewActivityKind.ReviewDiscussion)
        {
            SquadDashTrace.Write(
                "Approval",
                $"Related review discussion retained plan boundary plan={plan.PlanId} tasks={string.Join(",", response.TaskIds)}.");
            ClearPendingPlanReviewCorrection(restoreCard: true);
            ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
            return;
        }

        var updated = PlanStoreUpdater.ApplyManualReviewActivity(
            plan,
            response.TaskIds,
            response.Summary);
        if (ReferenceEquals(updated, plan))
        {
            AppendLine("⚠ SquadDash could not associate the conversational correction with the active review boundary. " +
                       "The plan remains unchanged.");
            ClearPendingPlanReviewCorrection(restoreCard: true);
            ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
            return;
        }

        var exactEvidence = updated.InterruptionData?.TaskCommitEvidence;
        var correctionContext = updated.InterruptionData?.RecoveryCorrection;
        if (_currentWorkspace is not null && exactEvidence is not null &&
            correctionContext is not null &&
            response.TaskIds.Count == 1 &&
            string.Equals(exactEvidence.TaskId, response.TaskIds[0], StringComparison.Ordinal))
        {
            try
            {
                var workspace = _currentWorkspace.FolderPath;
                var head = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
                await RunGitAsync(
                    workspace,
                    $"merge-base --is-ancestor \"{exactEvidence.Commit}\" \"{correctionContext.BaselineCommit}\"");
                await RunGitAsync(
                    workspace,
                    $"merge-base --is-ancestor \"{correctionContext.BaselineCommit}\" \"{head}\"");
                var countText = (await RunGitAsync(
                    workspace,
                    $"rev-list --count \"{correctionContext.BaselineCommit}..{head}\"")).Trim();
                if (!int.TryParse(countText, out var count) || count < 1)
                    throw new InvalidOperationException(
                        "The correction did not create a commit after the recorded task result.");
                await EnsurePlanWorktreeReadyAsync(workspace, updated.PlanId);
                var correctionCommits = (await RunGitAsync(
                    workspace,
                    $"rev-list --reverse \"{correctionContext.BaselineCommit}..{head}\"")).Split(
                        '\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
                var combinedCommits = (exactEvidence.Commits ??
                        [new PlanEvidenceCommit(exactEvidence.Commit, "task", "Original host-recorded task result.")])
                    .Concat(correctionCommits.Select(commit => new PlanEvidenceCommit(
                        commit,
                        "task",
                        count > 1
                            ? "One of multiple commits produced by the bounded correction; history was preserved."
                            : "Bounded correction requested from the recovery card.")))
                    .ToArray();
                updated = updated with
                {
                    InterruptionData = updated.InterruptionData! with
                    {
                        TaskCommitEvidence = exactEvidence with
                        {
                            Commit = head,
                            Summary = exactEvidence.Summary + " Correction: " + response.Summary,
                            Verification = null,
                            Commits = combinedCommits,
                        },
                        RecoveryCorrection = null,
                        LastCorrectionError = null,
                    },
                };
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write(
                    "PlanRecovery",
                    $"Could not extend correction evidence plan={updated.PlanId} task={response.TaskIds[0]}: {ex.Message}");
                updated = updated with
                {
                    InterruptionData = updated.InterruptionData! with
                    {
                        LastCorrectionError = ex.Message,
                    },
                };
                AppendLine(
                    "⚠ The correction completed, but SquadDash could not safely extend the task's commit evidence: " +
                    ex.Message + " The plan remains paused and no work will be rerun automatically.");
            }
        }
        if (!TryPublishPlanProgress(updated, out var saveError))
        {
            AppendLine("⚠ The conversational correction completed, but SquadDash could not record it for later plan assessment: " +
                       (saveError ?? "unknown persistence failure"));
            ClearPendingPlanReviewCorrection(restoreCard: true);
            ClearPendingPlanTaskCorrection(restoreRecoverySurface: true);
            return;
        }
        await ReconcileInterruptedPlanTaskEvidenceAsync();
        updated = _planStore.Load(updated.PlanId) ?? updated;

        if (updated.LifecycleStatus == PlanLifecycleStatus.AwaitingApproval &&
            _planApprovalRuntime is not null &&
            _inboxStore is not null)
        {
            try
            {
                await _planApprovalRuntime.Requests.RefreshFromPlanAsync(updated);
                var messageId = DurableApprovalRequestManager.BuildMessageId(updated.PlanId);
                _inboxPanel?.Refresh(_inboxStore.LoadAll());
                if (_inboxStore.GetById(messageId) is { } approvalMessage)
                    RefreshOpenApprovalInboxWindows(messageId, approvalMessage);
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write(
                    "Approval",
                    $"Could not refresh uncertain human-review selections plan={updated.PlanId}: {ex.Message}");
            }
        }

        var labels = response.TaskIds
            .Select(taskId => PlanRecoveryPresentationBuilder.FormatStepLabel(
                updated.Tasks.First(task => string.Equals(
                    task.TaskId, taskId, StringComparison.Ordinal)).DisplayStepLabel,
                updated.Tasks.First(task => string.Equals(
                    task.TaskId, taskId, StringComparison.Ordinal)).Title ?? taskId))
            .ToArray();
        ShowSystemTranscriptEntry(
            $"Conversational correction recorded for {string.Join(", ", labels)}. " +
            "The plan remains paused; use the refreshed recovery card to accept the step, continue working, or revise the remaining plan.");
        ClearPendingPlanReviewCorrection(restoreCard: false);
        ClearPendingPlanTaskCorrection(restoreRecoverySurface: false);
        RefreshHumanReviewSurfaces(updated);
    }

    private void QueueGateResponseRepairOrExplainFailure()
    {
        var context = _pendingGateResponseContext;
        if (context is null || _planStore?.Load(context.Token.PlanId) is not { } plan)
        {
            _pendingGateResponseContext = null;
            return;
        }
        var gate = plan.ApprovalGates.FirstOrDefault(candidate =>
            string.Equals(candidate.GateId, context.GateId, StringComparison.Ordinal) &&
            candidate.Status == PlanGateStatus.AwaitingApproval);
        if (gate is null)
        {
            _pendingGateResponseContext = null;
            return;
        }

        if (context.RepairAttempts == 0)
        {
            _pendingGateResponseContext = context with { RepairAttempts = 1 };
            _promptQueue.EnqueueAtFront(
                PlanGateResponseParser.BuildClassificationInstruction(
                    plan,
                    gate,
                    context.Token,
                    repair: true),
                _promptQueueCoordinator.NextSequenceNumber(),
                sourceTag: "plan-gate-response-repair",
                isSystemInjected: true);
            SyncQueuePanel();
            AppendLine("SquadDash did not receive the required approval-response classification. It asked AI once to repair the response; the plan remains unchanged.");
            return;
        }

        ClearPendingGateResponse(plan.PlanId, keepForClarification: false);
        AppendLine("⚠ SquadDash could not determine whether changes were requested after one automatic repair. The plan remains safely awaiting approval. Use **Request changes…** or reopen the approval to try again.");
    }

    private void ClearPendingGateResponse(string planId, bool keepForClarification)
    {
        if (!keepForClarification)
            _pendingGateResponseContext = null;
        if (_approvalTranscriptCards.TryGetValue(planId, out var cards))
            foreach (var card in cards)
                TranscriptApprovalCardBuilder.ClearChangeRequestDraftingState(card);
    }

    private void ClearPendingPlanReviewCorrection(bool restoreCard)
    {
        if (_pendingPlanReviewCorrectionContext is not { } context)
            return;

        _pendingPlanReviewCorrectionContext = null;
        SyncGateChangeActivity(isPromptRunning: false);
        SyncPlanTaskCorrectionActivity(isPromptRunning: false);
        if (!restoreCard || !_approvalTranscriptCards.TryGetValue(context.PlanId, out var cards))
            return;

        foreach (var card in cards)
            TranscriptApprovalCardBuilder.ClearChangeRequestDraftingState(card);
    }

    private void ClearPendingPlanTaskCorrection(bool restoreRecoverySurface)
    {
        if (_pendingPlanTaskCorrectionContext is not { } context)
            return;

        _pendingPlanTaskCorrectionContext = null;
        SyncPlanTaskCorrectionActivity(isPromptRunning: false);
        if (!restoreRecoverySurface || _planStore?.Load(context.PlanId) is not { } plan)
            return;
        RefreshHumanReviewSurfaces(plan);
    }

    private async Task<bool> ApplyGateReworkResponseAsync(
        Plan plan,
        PlanApprovalGate gate,
        ApprovalClickToken token,
        PlanGateResponse response)
    {
        if (_currentWorkspace is null || response.TaskIds is not { Count: > 0 } ||
            string.IsNullOrWhiteSpace(response.Instructions))
            return false;

        var taskIds = response.TaskIds.Distinct(StringComparer.Ordinal).ToArray();
        var invalidTargets = PlanApprovalBoundaryTargetPolicy.FindInvalidTargets(plan, gate, taskIds);
        if (invalidTargets.Length > 0)
        {
            if (_pendingPlanReviewCorrectionContext is not null)
            {
                QueueUnifiedPlanReviewResponseRepair(
                    PlanApprovalBoundaryTargetPolicy.BuildRepairDiagnostic(plan, gate, invalidTargets));
                return true;
            }
            AppendLine("⚠ The requested rework named tasks outside the current completed approval boundary: " +
                       string.Join(", ", invalidTargets) + ". The plan remains unchanged.");
            return true;
        }

        var result = await _planApprovalRuntime!.RequestReworkAsync(
            token,
            plan,
            gate.GateId,
            taskIds,
            response.Instructions,
            persistPlan: updated => TryPublishPlanProgress(updated, out _),
            allowEquivalentTokenRefresh: true);
        if (result.Result != ApprovalClickResult.Approved || result.UpdatedPlan is null)
        {
            SquadDashTrace.Write("Approval",
                $"Gate rework runtime rejected result={result.Result} updatedPlan={result.UpdatedPlan is not null} reason={result.RejectionReason ?? "none"}.");
            AppendLine(result.Result == ApprovalClickResult.PersistenceFailed
                ? "⚠ SquadDash could not persist the rework transition. The approval remains unchanged."
                : "⚠ SquadDash could not apply the rework request. " +
                  (result.RejectionReason ?? "The approval action changed before persistence.") +
                  " The plan remains unchanged.");
            return true;
        }
        RefreshPlanProjectionBestEffort(result.UpdatedPlan, "approval-rework");

        _pendingGateResponseContext = null;
        ClearPendingPlanReviewCorrection(restoreCard: false);
        _activePlanAwaitingGateApproval = result.UpdatedPlan.ApprovalGates
            .FirstOrDefault(candidate => candidate.Status == PlanGateStatus.AwaitingApproval)?.GateId;
        if (_approvalTranscriptCards.TryGetValue(plan.PlanId, out var cards))
        {
            foreach (var card in cards.Where(card =>
                         card.Container.Tag is TranscriptApprovalCardTag tag &&
                         string.Equals(tag.GateId, gate.GateId, StringComparison.Ordinal)))
                TranscriptApprovalCardBuilder.ShowReworkRequestedState(card);
        }

        var messageId = DurableApprovalRequestManager.BuildMessageId(plan.PlanId);
        if (_inboxStore is not null)
        {
            _inboxPanel?.Refresh(_inboxStore.LoadAll());
            if (_inboxStore.GetById(messageId) is { } updatedMessage)
                RefreshOpenApprovalInboxWindows(messageId, updatedMessage);
        }
        LoadTasksPanel();
        AppendLine($"↩ Changes requested for {string.Join(", ", taskIds)}. SquadDash preserved the prior attempt and queued a new verified attempt.");

        var group = PendingDecomposePlanAdapter.FromPlan(result.UpdatedPlan).Group with
        {
            HostRevision = result.UpdatedPlan.Revision,
        };
        if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
        {
            ScheduleApprovalResumeWhenIdle(result.UpdatedPlan.PlanId);
            return true;
        }
        try
        {
            await StartBackloggedDecomposeGroupAsync(group with { HostRevision = plan.Revision });
        }
        catch (PlanPreflightBlockedException blocked)
        {
            var reopenedTaskId = taskIds[0];
            var reopenedTaskTitle = result.UpdatedPlan.Tasks.FirstOrDefault(candidate =>
                string.Equals(candidate.TaskId, reopenedTaskId, StringComparison.Ordinal))?.Title ?? reopenedTaskId;
            var pausedPlan = PlanStoreUpdater.ApplyWaitingForCleanWorktree(result.UpdatedPlan);
            if (!TryPublishPlanProgress(pausedPlan, out var pauseError))
            {
                AppendLine("⚠ The rework was prepared but SquadDash could not save its paused recovery state: " +
                           (pauseError ?? "unknown persistence failure"));
                return true;
            }

            LoadTasksPanel();
            SyncPlansPanel();
            var pausedPending = PendingDecomposePlanAdapter.FromPlan(pausedPlan);
            ShowTranscriptPlanPreflightRecovery(
                pausedPending,
                action: "resume-rework",
                branchOverride: pausedPlan.Branch,
                blocked,
                sourceActionsPanel: null,
                CoordinatorThread.Document.Blocks,
                retryOverride: async () =>
                {
                    var latest = _planStore?.Load(pausedPlan.PlanId)
                        ?? throw new InvalidOperationException("The paused plan is no longer available.");
                    await StartBackloggedDecomposeGroupAsync(
                        PendingDecomposePlanAdapter.FromPlan(latest).Group with
                        {
                            HostRevision = latest.Revision,
                        });
                    return true;
                },
                contentFactory: exception => PlanPreflightRecoveryContent.FromRework(
                    exception,
                    pausedPlan.Title,
                    reopenedTaskTitle),
                retryLabel: "Resume Rework");
        }
        catch (Exception ex)
        {
            AppendLine($"⚠ The task was reopened, but its execution could not start: {ex.Message}");
        }
        return true;
    }

    private void ScheduleApprovalResumeRetry(
        string planId,
        PlanPreflightBlockedException blocked)
    {
        if (blocked.RequiresRepositoryInitialization)
        {
            SquadDashTrace.Write(
                "Approval",
                $"Automatic plan resume requires repository initialization plan={planId}.");
            ScheduleDecomposeSystemEntry(
                $"Approval acquired for plan {planId}, but continuation requires a Git repository. " +
                "Open the plan to initialize the repository and retry.");
            return;
        }

        if (_approvalResumeRetryTimer is not null &&
            string.Equals(_approvalResumeRetryPlanId, planId, StringComparison.Ordinal))
            return;

        StartApprovalResumeRetryTimer(planId);

        var changedPathSummary = blocked.ChangedPaths.Count == 1
            ? blocked.ChangedPaths[0]
            : $"{blocked.ChangedPaths.Count} repository paths";
        SquadDashTrace.Write(
            "Approval",
            $"Automatic plan resume delayed by worktree preflight plan={planId} " +
            $"condition={blocked.Condition} paths=[{string.Join(",", blocked.ChangedPaths)}].");
        ScheduleDecomposeSystemEntry(
            $"Approval acquired for plan {planId}. Continuation is waiting for current repository changes " +
            $"to finish ({changedPathSummary}) and will retry automatically.");
    }

    private void ScheduleApprovalResumeWhenIdle(string planId)
    {
        if (_approvalResumeRetryTimer is not null &&
            string.Equals(_approvalResumeRetryPlanId, planId, StringComparison.Ordinal))
            return;

        StartApprovalResumeRetryTimer(planId);
        SquadDashTrace.Write(
            "Approval",
            $"Approved plan continuation queued for the next idle coordinator slot plan={planId} " +
            $"promptRunning={_isPromptRunning} loopRunning={IsLoopRunning} queueDrain={_queueDrainActive}.");
        ScheduleDecomposeSystemEntry(
            $"Plan {planId} has runnable work. Continuation is waiting for the current turn to finish.");
    }

    private void StartApprovalResumeRetryTimer(string planId)
    {
        StopApprovalResumeRetry();
        _approvalResumeRetryPlanId = planId;
        _approvalResumeRetryTimer = new DispatcherTimer
        {
            Interval = TimeSpan.FromSeconds(1.5),
        };
        _approvalResumeRetryTimer.Tick += ApprovalResumeRetryTimer_Tick;
        _approvalResumeRetryTimer.Start();
    }

    private async void ApprovalResumeRetryTimer_Tick(object? sender, EventArgs e)
    {
        if (_approvalResumeRetryInFlight || string.IsNullOrWhiteSpace(_approvalResumeRetryPlanId))
            return;

        var planId = _approvalResumeRetryPlanId;
        var plan = _planStore?.Load(planId);
        var decision = ApprovalResumeRetryPolicy.Resolve(
            plan,
            planId,
            _isClosing,
            _isPromptRunning,
            IsLoopRunning,
            _activeDecomposeGroupId);
        if (decision == ApprovalResumeRetryDecision.AlreadyRunning)
        {
            StopApprovalResumeRetry();
            return;
        }
        if (decision == ApprovalResumeRetryDecision.Wait)
            return;
        if (decision == ApprovalResumeRetryDecision.Cancel)
        {
            SquadDashTrace.Write(
                "Approval",
                $"Cancelled delayed plan resume because plan is no longer resumable plan={planId} " +
                $"lifecycle={plan?.LifecycleStatus ?? "missing"}.");
            StopApprovalResumeRetry();
            return;
        }

        _approvalResumeRetryInFlight = true;
        try
        {
            if (!await IsPlanPreflightWorkspaceCleanAsync(planId))
                return;

            // The workspace probe yields. Recheck coordinator ownership before changing
            // durable plan state or starting a verification round.
            if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
                return;

            SquadDashTrace.Write(
                "Approval",
                $"Repository is clean; retrying approved plan continuation plan={planId}.");
            if (!await StartDecomposeLoopAsync(planId))
            {
                if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
                    return;
                StopApprovalResumeRetry();
                ScheduleDecomposeSystemEntry(
                    $"Approval was acquired for plan {planId}, but its delayed continuation did not start. " +
                    "Open the plan to retry.");
                return;
            }

            StopApprovalResumeRetry();
            ScheduleDecomposeSystemEntry(
                $"Plan {planId} is resuming automatically in the available coordinator slot.");
        }
        catch (PlanPreflightBlockedException blocked)
        {
            SquadDashTrace.Write(
                "Approval",
                $"Delayed plan resume remains blocked plan={planId} paths=[{string.Join(",", blocked.ChangedPaths)}].");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "Approval",
                $"Delayed plan resume failed plan={planId}: {ex}");
            StopApprovalResumeRetry();
            ScheduleDecomposeSystemEntry(
                $"Approval was acquired for plan {planId}, but its delayed continuation failed: {ex.Message}");
        }
        finally
        {
            _approvalResumeRetryInFlight = false;
        }
    }

    private void StopApprovalResumeRetry()
    {
        if (_approvalResumeRetryTimer is not null)
        {
            _approvalResumeRetryTimer.Stop();
            _approvalResumeRetryTimer.Tick -= ApprovalResumeRetryTimer_Tick;
            _approvalResumeRetryTimer = null;
        }
        _approvalResumeRetryPlanId = null;
    }

    private async Task<bool> ApplyGateAmendmentResponseAsync(
        Plan plan,
        PlanApprovalGate gate,
        ApprovalClickToken token,
        PlanGateResponse response)
    {
        if (_currentWorkspace is null || string.IsNullOrWhiteSpace(response.Title) ||
            string.IsNullOrWhiteSpace(response.Instructions))
        {
            SquadDashTrace.Write("Approval",
                $"Gate amendment stopped before validation workspace={_currentWorkspace is not null} title={!string.IsNullOrWhiteSpace(response.Title)} instructions={!string.IsNullOrWhiteSpace(response.Instructions)}.");
            return false;
        }

        var relatedTaskIds = response.TaskIds is { Count: > 0 }
            ? response.TaskIds.Distinct(StringComparer.Ordinal).ToArray()
            : gate.AfterTaskIds.Distinct(StringComparer.Ordinal).ToArray();
        var invalidTargets = PlanApprovalBoundaryTargetPolicy.FindInvalidTargets(plan, gate, relatedTaskIds);
        if (invalidTargets.Length > 0)
        {
            SquadDashTrace.Write("Approval",
                $"Gate amendment rejected invalidTargets=[{string.Join(",", invalidTargets)}] gate={gate.GateId}.");
            if (_pendingPlanReviewCorrectionContext is not null)
            {
                QueueUnifiedPlanReviewResponseRepair(
                    PlanApprovalBoundaryTargetPolicy.BuildRepairDiagnostic(plan, gate, invalidTargets));
                return true;
            }
            AppendLine("⚠ The requested amendment named tasks outside the current completed approval boundary: " +
                       string.Join(", ", invalidTargets) + ". The plan remains unchanged.");
            return true;
        }

        var result = await _planApprovalRuntime!.RequestAmendmentAsync(
            token,
            plan,
            gate.GateId,
            relatedTaskIds,
            response.Title,
            response.Instructions,
            persistPlan: updated => TryPublishPlanProgress(updated, out _),
            allowEquivalentTokenRefresh: true);
        if (result.Result != ApprovalClickResult.Approved || result.UpdatedPlan is null)
        {
            SquadDashTrace.Write("Approval",
                $"Gate amendment runtime rejected result={result.Result} updatedPlan={result.UpdatedPlan is not null} reason={result.RejectionReason ?? "none"}.");
            AppendLine(result.Result == ApprovalClickResult.PersistenceFailed
                ? "⚠ SquadDash could not persist the amendment. The approval remains unchanged."
                : "⚠ SquadDash could not apply the amendment. " +
                  (result.RejectionReason ?? "The approval action changed before persistence.") +
                  " The plan remains unchanged.");
            return true;
        }
        RefreshPlanProjectionBestEffort(result.UpdatedPlan, "approval-amendment");

        var amendmentTask = result.UpdatedPlan.Tasks.Single(task =>
            !plan.Tasks.Any(existing => string.Equals(existing.TaskId, task.TaskId, StringComparison.Ordinal)));
        _pendingGateResponseContext = null;
        ClearPendingPlanReviewCorrection(restoreCard: false);
        _activePlanAwaitingGateApproval = result.UpdatedPlan.ApprovalGates
            .FirstOrDefault(candidate => candidate.Status == PlanGateStatus.AwaitingApproval)?.GateId;
        if (_approvalTranscriptCards.TryGetValue(plan.PlanId, out var cards))
        {
            foreach (var card in cards.Where(card =>
                         card.Container.Tag is TranscriptApprovalCardTag tag &&
                         string.Equals(tag.GateId, gate.GateId, StringComparison.Ordinal)))
                TranscriptApprovalCardBuilder.ShowAmendmentRequestedState(card);
        }

        var messageId = DurableApprovalRequestManager.BuildMessageId(plan.PlanId);
        if (_inboxStore is not null)
        {
            _inboxPanel?.Refresh(_inboxStore.LoadAll());
            if (_inboxStore.GetById(messageId) is { } updatedMessage)
                RefreshOpenApprovalInboxWindows(messageId, updatedMessage);
        }
        LoadTasksPanel();
        AppendLine($"＋ Added amendment \"{amendmentTask.Title}\". Previously completed tasks remain accepted; " +
                   "SquadDash will verify only the additional work before returning to this approval checkpoint.");
        SquadDashTrace.Write("Approval",
            $"Gate amendment persisted plan={plan.PlanId} gate={gate.GateId} task={amendmentTask.TaskId} revision={result.UpdatedPlan.Revision}.");

        var group = PendingDecomposePlanAdapter.FromPlan(result.UpdatedPlan).Group with
        {
            HostRevision = result.UpdatedPlan.Revision,
        };
        if (_isPromptRunning || IsLoopRunning || _queueDrainActive)
        {
            ScheduleApprovalResumeWhenIdle(result.UpdatedPlan.PlanId);
            return true;
        }
        try
        {
            await StartBackloggedDecomposeGroupAsync(group with { HostRevision = result.UpdatedPlan.Revision });
        }
        catch (PlanPreflightBlockedException blocked)
        {
            var pausedPlan = PlanStoreUpdater.ApplyWaitingForCleanWorktree(result.UpdatedPlan);
            if (!TryPublishPlanProgress(pausedPlan, out var pauseError))
            {
                AppendLine("⚠ The amendment was prepared but SquadDash could not save its paused recovery state: " +
                           (pauseError ?? "unknown persistence failure"));
                return true;
            }

            LoadTasksPanel();
            SyncPlansPanel();
            var pausedPending = PendingDecomposePlanAdapter.FromPlan(pausedPlan);
            ShowTranscriptPlanPreflightRecovery(
                pausedPending,
                action: "resume-amendment",
                branchOverride: pausedPlan.Branch,
                blocked,
                sourceActionsPanel: null,
                CoordinatorThread.Document.Blocks,
                retryOverride: async () =>
                {
                    var latest = _planStore?.Load(pausedPlan.PlanId)
                        ?? throw new InvalidOperationException("The paused plan is no longer available.");
                    await StartBackloggedDecomposeGroupAsync(
                        PendingDecomposePlanAdapter.FromPlan(latest).Group with
                        {
                            HostRevision = latest.Revision,
                        });
                    return true;
                },
                contentFactory: exception => PlanPreflightRecoveryContent.FromAmendment(
                    exception,
                    pausedPlan.Title,
                    amendmentTask.Title ?? amendmentTask.TaskId),
                retryLabel: "Resume Amendment");
        }
        catch (Exception ex)
        {
            AppendLine($"⚠ The amendment was added, but its execution could not start: {ex.Message}");
        }
        return true;
    }

    private void SaveDecomposeRecoveryInboxReminder(
        string groupId,
        string revision,
        string taskId,
        string reason)
    {
        if (_currentWorkspace is null || _inboxStore is null) return;
        var plan = ResolveRecoveryPendingPlan(groupId, revision);
        if (plan is null) return;
        var durablePlan = _planStore?.Load(groupId);
        var evidence = durablePlan?.InterruptionData?.TaskCommitEvidence;
        var currentHead = ReadCachedRecoveryHeadCommit();
        var message = DecomposePlanInbox.BuildRecoveryMessage(
            plan,
            taskId,
            reason,
            DateTimeOffset.Now,
            evidence,
            durablePlan,
            currentHead,
            (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant));
        var existing = _inboxStore.GetById(message.Id);
        _inboxStore.Save(existing is null
            ? message
            : message with
            {
                Read = existing.Read,
                Timestamp = existing.Timestamp,
            });
        _inboxPanel?.Refresh(_inboxStore.LoadAll());
        if (existing is null)
            AppendInboxReceivedEntry(message.Subject, message.Id);
        _ = RefreshRecoveryGitSnapshotAsync(refreshSurfaces: true);
    }

    private void ScheduleDecomposeSystemEntry(
        string message,
        string? groupId = null,
        string? revision = null,
        string? taskId = null)
    {
        void Publish()
        {
            ShowSystemTranscriptEntry(message);
            if (groupId is null || revision is null || taskId is null || _currentWorkspace is null)
                return;
            var plan = ResolveRecoveryPendingPlan(groupId, revision);
            if (plan is null) return;
            AppendDecomposeRecoveryActions(plan, taskId);
        }

        if (Dispatcher.CheckAccess())
            Publish();
        else
            Dispatcher.BeginInvoke(Publish, System.Windows.Threading.DispatcherPriority.Send);
    }

    private void ResolveRecoveryTranscript(string outcome)
    {
        var staleMessages = new[]
        {
            PlanRecoveryPresentationBuilder.BuildStatusMessage(hasCommittedWork: true),
            PlanRecoveryPresentationBuilder.BuildStatusMessage(hasCommittedWork: false),
        };
        var persisted = _conversationManager.ReplaceLatestCoordinatorResponse(staleMessages, outcome);
        var rendered = ReplaceLatestRenderedRecoveryStatus(
            CoordinatorThread.Document.Blocks,
            staleMessages,
            outcome);
        TranscriptQuickReplyFactory.RemoveDecomposeRecoveryContainers(CoordinatorThread.Document.Blocks);
        TranscriptQuickReplyFactory.RemoveProtocolJsonIndicators(CoordinatorThread.Document.Blocks);
        if (!persisted && !rendered)
            ShowSystemTranscriptEntry(outcome);
    }

    private bool ReplaceLatestRenderedRecoveryStatus(
        BlockCollection blocks,
        IReadOnlyCollection<string> staleMessages,
        string outcome)
    {
        var expected = new HashSet<string>(staleMessages.Select(message => message.Trim()), StringComparer.Ordinal);
        foreach (var block in blocks.Cast<Block>().Reverse())
        {
            if (block is not Section section)
                continue;
            if (ReplaceLatestRenderedRecoveryStatus(section.Blocks, staleMessages, outcome))
                return true;

            var visibleText = new TextRange(section.ContentStart, section.ContentEnd).Text.Trim();
            if (!expected.Contains(visibleText))
                continue;

            foreach (var child in section.Blocks.ToArray())
                section.Blocks.Remove(child);
            var paragraph = CreateTranscriptParagraph(bottomMargin: 18);
            MarkdownFlowDocumentBuilder.AddInboxInlineText(paragraph.Inlines, outcome);
            section.Blocks.Add(paragraph);
            return true;
        }
        return false;
    }

    private PendingDecomposePlan? ResolveRecoveryPendingPlan(string groupId, string revision)
    {
        var durable = _planStore?.Load(groupId);
        if (durable is not null && string.Equals(durable.Revision, revision, StringComparison.Ordinal))
            return PendingDecomposePlanAdapter.FromPlan(durable);
        return null;
    }

    private async Task RestorePlanBranchAndResumeAsync(Plan plan)
    {
        await StartOrResumeDurablePlanAsync(_planStore?.Load(plan.PlanId) ?? plan);
    }

    private void RestoreInterruptedPlanRecoverySurfaces()
    {
        if (_currentWorkspace is null || _planStore is null) return;
        var branch = ReadGitBranch(_currentWorkspace.FolderPath);
        var plan = _planStore.LoadAll()
            .Where(candidate =>
                (candidate.LifecycleStatus is PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked) &&
                !PlanExecutionBoundaryPolicy.HasFailedValidation(candidate) &&
                (string.Equals(candidate.Branch, branch, StringComparison.Ordinal) ||
                 PlanBranchLeaseRecoveryPolicy.IsBranchMismatchReason(
                     candidate.InterruptionData?.Reason)))
            .OrderByDescending(candidate => candidate.Timestamps.InterruptedAt ?? candidate.Timestamps.CreatedAt)
            .FirstOrDefault();
        if (plan is null) return;
        var taskId = plan.InterruptionData?.InterruptedTaskId
            ?? plan.Progress.ExecutingTaskId
            ?? plan.Tasks.FirstOrDefault(task => task.Status != PlanTaskStatus.Complete)?.TaskId;
        if (taskId is null) return;
        var reason = plan.InterruptionData?.Reason ?? "Plan execution was interrupted and needs your attention.";
        SaveDecomposeRecoveryInboxReminder(plan.PlanId, plan.Revision, taskId, reason);

        var statusMessage = PlanRecoveryPresentationBuilder.BuildStatusMessage(
            plan.InterruptionData?.TaskCommitEvidence is not null);
        var interruptionStarted = plan.Timestamps.InterruptedAt ?? plan.Timestamps.CreatedAt;
        bool HasCurrentRecoveryEntry() => _conversationManager.ConversationState.Turns.Any(turn =>
            turn.Timestamp >= interruptionStarted.AddSeconds(-1) &&
            turn.ResponseText?.Contains(statusMessage, StringComparison.Ordinal) == true);

        // A virtualized history batch must never own current actions. Remove any recovery
        // surface left by an older build or an earlier restoration pass, then append exactly
        // one authoritative surface at the true end of the coordinator transcript.
        TranscriptQuickReplyFactory.RemoveDecomposeRecoveryContainers(
            CoordinatorThread.Document.Blocks);

        if (HasCurrentRecoveryEntry())
        {
            // Quick-reply controls are live WPF elements rather than serialized narrative.
            // Hydration restores the persisted marker but not those controls, so reconstruct
            // the actions without adding another copy of the marker to conversation history.
            var pendingPlan = ResolveRecoveryPendingPlan(plan.PlanId, plan.Revision);
            if (pendingPlan is not null)
                AppendDecomposeRecoveryActions(pendingPlan, taskId);
            return;
        }

        ScheduleDecomposeSystemEntry(
            statusMessage,
            plan.PlanId,
            plan.Revision,
            taskId);
    }

    private void RestoreFailedPlanValidationRecoverySurface()
    {
        if (_planStore is null) return;
        var plan = _planStore.LoadAll()
            .Where(candidate =>
                candidate.LifecycleStatus == PlanLifecycleStatus.Blocked &&
                PlanExecutionBoundaryPolicy.HasFailedValidation(candidate))
            .OrderByDescending(candidate => candidate.Timestamps.LastRunAt ?? candidate.Timestamps.CreatedAt)
            .FirstOrDefault();
        var validation = plan?.Validations?.FirstOrDefault(candidate =>
            candidate.Status == PlanValidationStatus.Failed);
        if (plan is null || validation is null) return;

        var message = $"Validation needs attention · {validation.Title}.\n" +
                      (PlanValidationHumanProofRecoveryPolicy.IsLegacyHumanProofOnlyFailure(validation)
                          ? "Why it paused: the remaining proof requires human observation. Prepare the review checklist to continue.\n"
                          : $"Why it stopped: {validation.Summary ?? "The validation did not return acceptable evidence."}\n") +
                      "Completed implementation work is preserved and will not be repeated.";
        var alreadyRecorded = _conversationManager.ConversationState.Turns.Any(turn =>
            turn.ResponseText?.Contains($"Validation needs attention · {validation.Title}", StringComparison.Ordinal) == true ||
            turn.ResponseText?.Contains($"Validation did not pass · {validation.Title}", StringComparison.Ordinal) == true);
        ScheduleValidationRecoveryEntry(
            plan.PlanId,
            validation.ValidationId,
            message,
            addMessage: !alreadyRecorded);
    }

    private bool HasPendingPlanRevision(string planId) =>
        _currentWorkspace is not null &&
        new PendingPlanRevisionProposalStore(_currentWorkspace.SquadFolderPath).Load(planId) is not null;

    private void RestorePendingManualLoopResumeSurface()
    {
        var oldSurfaces = CoordinatorThread.Document.Blocks
            .OfType<Section>()
            .Where(section => string.Equals(
                section.Tag as string,
                ManualLoopResumeSurfaceTag,
                StringComparison.Ordinal))
            .ToList();
        foreach (var oldSurface in oldSurfaces)
            CoordinatorThread.Document.Blocks.Remove(oldSurface);

        var pendingExecution = _conversationManager.ConversationState.PendingManualLoopResume;
        if (pendingExecution is null)
            return;

        var alreadyRecorded = _conversationManager.ConversationState.Turns.Any(turn =>
            turn.ResponseText?.Contains(ManualLoopResumeMessage, StringComparison.Ordinal) == true);
        if (!alreadyRecorded)
            ShowSystemTranscriptEntry(ManualLoopResumeMessage);

        var surface = new Section { Tag = ManualLoopResumeSurfaceTag };
        var panel = new WrapPanel { Orientation = Orientation.Horizontal };
        var resumeButton = TranscriptQuickReplyFactory.CreateButton(
            "Resume Loop",
            _transcriptFontSize,
            toolTip: ToolTipHelper.MakeThemedToolTip(
                "Resume the saved loop from its last completed iteration. Queued prompts will run first."));
        resumeButton.Click += async (_, _) =>
        {
            var execution = _conversationManager.ConversationState.PendingManualLoopResume;
            if (execution is null)
            {
                CoordinatorThread.Document.Blocks.Remove(surface);
                return;
            }

            resumeButton.IsEnabled = false;
            var mode = _conversationManager.ConversationState.LoopMode ?? _settingsSnapshot.LoopMode;
            try
            {
                _conversationManager.UpdatePendingManualLoopResumeState(null);
                CoordinatorThread.Document.Blocks.Remove(surface);
                await QueueOrStartLoopAsync(mode, execution);
            }
            catch (Exception ex)
            {
                _conversationManager.UpdatePendingManualLoopResumeState(execution);
                resumeButton.IsEnabled = true;
                HandleUiCallbackException("Resume saved loop", ex);
            }
        };
        panel.Children.Add(resumeButton);
        surface.Blocks.Add(TranscriptQuickReplyFactory.CreateContainer(
            panel,
            ManualLoopResumeSurfaceTag));
        CoordinatorThread.Document.Blocks.Add(surface);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private async void RecordHumanReviewChecklistSelection(
        string planId,
        PlanHumanReviewChecklistItem item,
        bool isChecked)
    {
        var current = _planStore?.Load(planId);
        if (current is null) return;
        var updated = PlanStoreUpdater.ApplyGateHumanReviewSelection(
            current,
            item.GateId,
            item.ItemId,
            isChecked,
            item.CandidateCommit,
            item.ReviewTarget);
        if (ReferenceEquals(updated, current)) return;
        if (!TryPublishPlanProgress(updated, out var saveError))
        {
            ReportPlanActionIssue(
                planId,
                "Save human review",
                saveError ?? "SquadDash could not save this verification selection.");
            return;
        }

        if (_approvalTranscriptCards.TryGetValue(planId, out var cards))
            foreach (var card in cards)
                card.SetChecklistSelection(item, isChecked);

        try
        {
            if (_planApprovalRuntime is not null && _inboxStore is not null)
            {
                await _planApprovalRuntime.Requests.RefreshFromPlanAsync(updated);
                var messageId = DurableApprovalRequestManager.BuildMessageId(planId);
                var messages = _inboxStore.LoadAll();
                _inboxPanel?.Refresh(messages);
                if (_inboxStore.GetById(messageId) is { } message)
                    RefreshOpenApprovalInboxWindows(messageId, message);
                RefreshOpenPlanBoundInboxWindows(planId, exceptMessageId: messageId);
            }

            if (_openPlanApprovalReviewWindows.ContainsKey(planId) &&
                _planApprovalRuntime?.Actions.GetCurrentToken(planId) is { } token &&
                updated.ApprovalGates.FirstOrDefault(gate =>
                    gate.Status == PlanGateStatus.AwaitingApproval) is { } gate)
            {
                ShowGateApprovalReviewWindow(
                    updated,
                    gate,
                    BuildLightweightApprovalSnapshot(updated, gate),
                    token,
                    activate: false);
            }
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "Approval",
                $"Could not synchronize human-review selection plan={planId} item={item.ItemId}: {ex.Message}");
        }
    }

    private void RefreshOpenPlanBoundInboxWindows(string planId, string? exceptMessageId = null)
    {
        if (_inboxStore is null)
            return;

        foreach (var window in _openInboxWindows.Where(candidate =>
                     candidate.HasManualTestKitApprovalBinding &&
                     string.Equals(candidate.PlanGroupId, planId, StringComparison.Ordinal) &&
                     !string.Equals(candidate.MessageId, exceptMessageId, StringComparison.Ordinal)).ToArray())
        {
            if (_inboxStore.GetById(window.MessageId) is not { } message)
                continue;
            try
            {
                window.CompleteApprovalUpdate(message, DispatchInboxAction);
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write("Approval", $"Plan-bound Inbox window refresh failed: {ex.Message}");
            }
        }
    }

    private void OpenApprovalStepEvidence(Plan plan, ReviewTaskEntry reviewTask)
    {
        var durableTask = plan.Tasks.FirstOrDefault(task =>
            string.Equals(task.TaskId, reviewTask.TaskId, StringComparison.Ordinal));
        var commits = durableTask is null
            ? Array.Empty<PlanEvidenceCommit>()
            : PlanRecoveryPresentationBuilder.ResolveTaskEvidence(plan, durableTask).ToArray();
        if (commits.Length == 0)
        {
            commits = reviewTask.Commits
                .Where(commit => !string.IsNullOrWhiteSpace(commit.Link.FullSha))
                .Select(commit => new PlanEvidenceCommit(
                    commit.Link.FullSha,
                    PlanRecoveryCommitRelation.Task,
                    commit.Link.Subject))
                .ToArray();
        }

        if (commits.Length == 0)
        {
            ReportPlanActionIssue(
                plan.PlanId,
                "Open evidence",
                $"SquadDash does not have commit evidence recorded for {reviewTask.Title}.");
            return;
        }

        _ = OpenEvidenceViewerAsync(commits);
    }

    private void AppendDecomposeRecoveryActions(
        PendingDecomposePlan plan,
        string taskId,
        bool showEndPlan = false,
        bool developerPreview = false)
    {
        var durablePlan = _planStore?.Load(plan.Group.GroupId);
        if (!developerPreview &&
            (durablePlan is null || !PlanRecoveryControlPolicy.HasActionableInterruption(durablePlan)))
        {
            SquadDashTrace.Write(
                TraceCategory.General,
                $"Recovery controls suppressed because plan={plan.Group.GroupId} is not at an actionable interruption.");
            return;
        }
        var planRunnerActive = durablePlan is not null && HasActivePlanWork(durablePlan.PlanId);

        var recoveryTag = new DecomposeRecoveryTag(plan.Group.GroupId, plan.Revision, taskId);
        var recoverySurface = new Section { Tag = recoveryTag };
        CoordinatorThread.Document.Blocks.Add(recoverySurface);
        var assessmentEvidence = durablePlan?.InterruptionData?.RecoveryAssessment;
        var durableTask = durablePlan?.Tasks.FirstOrDefault(task =>
            string.Equals(task.TaskId, taskId, StringComparison.Ordinal));
        var completedWorkReview = durablePlan is null
            ? null
            : CompletedWorkReviewPresentationBuilder.Build(durablePlan, taskId);
        var isBranchLeaseRecovery = PlanBranchLeaseRecoveryPolicy.IsBranchMismatchReason(
            durablePlan?.InterruptionData?.Reason);
        var humanReview = durablePlan is null
            ? null
            : PlanRecoveryPresentationBuilder.BuildHumanReviewCard(durablePlan, taskId);
        var reviewAttention = durablePlan is null
            ? null
            : PlanReviewAttentionPresentationResolver.Resolve(durablePlan, taskId);
        var combinedHumanReviewGate = reviewAttention?.Gate;
        var humanChecklistItems = reviewAttention?.Checklist.ToArray() ?? [];
        var humanChecklistState = humanChecklistItems.ToDictionary(
            item => item.ItemId,
            item => item.IsChecked,
            StringComparer.Ordinal);
        var attentionCard = durablePlan is null
            ? new PlanAttentionCardPresentation(
                PlanAttentionCategory.UnexpectedState,
                "Unexpected State Encountered",
                "SquadDash encountered an unexpected state and stopped the plan to preserve its current work.",
                "The durable plan record is unavailable.",
                ShowDiagnosticsActions: true)
            : PlanAttentionCardPresentationBuilder.Build(
                durablePlan,
                taskId,
                humanReview,
                humanChecklistItems.Length > 0);
        Action refreshHumanReviewActions = () => { };
        var panel = new WrapPanel { Orientation = Orientation.Horizontal };
        var cardDocument = new FlowDocument
        {
            PagePadding = new Thickness(0),
            ColumnWidth = double.PositiveInfinity,
            Background = Brushes.Transparent,
            FontFamily = new FontFamily("Segoe UI, Segoe UI Emoji"),
            FontSize = _transcriptFontSize,
        };
        cardDocument.SetResourceReference(TextElement.ForegroundProperty, "BodyText");
        var cardViewer = new FlowDocumentScrollViewer
        {
            Document = cardDocument,
            IsToolBarVisible = false,
            IsSelectionEnabled = true,
            VerticalScrollBarVisibility = ScrollBarVisibility.Disabled,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled,
            Background = Brushes.Transparent,
            BorderThickness = new Thickness(0),
            Padding = new Thickness(0),
        };
        cardViewer.PreviewMouseWheel += (_, e) =>
        {
            // This viewer exists only to provide selectable rich text inside the card; its own
            // scrollbars are intentionally disabled. Route wheel input to the transcript behind
            // it so hovering the card does not create a dead scrolling region.
            if (Keyboard.Modifiers.HasFlag(ModifierKeys.Control))
            {
                OutputTextBox_PreviewMouseWheel(OutputTextBox, e);
                return;
            }

            FocusTranscriptForInactiveSelectionScroll(OutputTextBox);
            if (OutputTextBox.Template?.FindName("PART_ContentHost", OutputTextBox) is not ScrollViewer transcriptScroll)
                return;

            var detents = Math.Max(1, Math.Abs(e.Delta) / Mouse.MouseWheelDeltaForOneLine);
            var configuredLines = SystemParameters.WheelScrollLines;
            if (configuredLines < 0)
            {
                for (var index = 0; index < detents; index++)
                {
                    if (e.Delta > 0) transcriptScroll.PageUp();
                    else transcriptScroll.PageDown();
                }
            }
            else
            {
                var lineCount = Math.Max(1, configuredLines) * detents;
                for (var index = 0; index < lineCount; index++)
                {
                    if (e.Delta > 0) transcriptScroll.LineUp();
                    else transcriptScroll.LineDown();
                }
            }

            e.Handled = true;
        };
        var card = new Border
        {
            Child = cardViewer,
            CornerRadius = new CornerRadius(8),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(14, 10, 14, 10),
            MaxWidth = _transcriptFontSize * 54,
            HorizontalAlignment = HorizontalAlignment.Left,
            Margin = new Thickness(0, 4, 0, 4),
            Effect = new System.Windows.Media.Effects.DropShadowEffect
            {
                BlurRadius = 6,
                ShadowDepth = 1,
                Opacity = 0.2,
                Color = Colors.Black,
            },
        };
        card.SetResourceReference(Border.BackgroundProperty, "CardSurface");
        card.SetResourceReference(Border.BorderBrushProperty, "SubtleBorder");
        var copyParts = new List<string>();
        var cardTag = new DecomposeRecoveryCardTag(recoveryTag, panel)
        {
            CopyTextProvider = () => string.Join(Environment.NewLine, copyParts),
        };
        recoverySurface.Blocks.Add(TranscriptQuickReplyFactory.CreateContainer(card, cardTag));
        var blocks = cardDocument.Blocks;

        var taskDefinition = plan.Group.Tasks.FirstOrDefault(task =>
            string.Equals(task.Id, taskId, StringComparison.Ordinal));
        var taskTitle = taskDefinition?.Title ?? taskId;
        var taskIndex = plan.Group.Tasks.ToList().FindIndex(task =>
            string.Equals(task.Id, taskId, StringComparison.Ordinal));
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            durableTask?.DisplayStepLabel ?? (taskIndex >= 0 ? (taskIndex + 1).ToString() : null),
            taskTitle);
        var cardTitle = attentionCard.Title;
        var titleParagraph = CreateTranscriptParagraph(bottomMargin: 9);
        titleParagraph.FontSize = _transcriptFontSize + 2;
        var titleRun = new Run(cardTitle) { FontWeight = FontWeights.SemiBold };
        titleRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        titleParagraph.Inlines.Add(titleRun);
        blocks.Add(titleParagraph);

        copyParts.Add(cardTitle);
        var planLinkParagraph = CreateTranscriptParagraph(bottomMargin: 4);
        var planLabelRun = new Run("Plan: ");
        planLabelRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        planLinkParagraph.Inlines.Add(planLabelRun);
        var planLink = new Hyperlink(new Run(plan.Group.GroupTitle))
        {
            Cursor = Cursors.Hand,
            ToolTip = "View plan and task dependencies",
        };
        planLink.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
        planLink.Click += (_, _) => OpenDecomposePlanViewer(plan);
        planLinkParagraph.Inlines.Add(planLink);
        blocks.Add(planLinkParagraph);

        var taskParagraph = CreateTranscriptParagraph(bottomMargin: 11);
        var stepRun = new Run(stepLabel + ": ");
        stepRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        taskParagraph.Inlines.Add(stepRun);
        var taskTitleText = new Span();
        taskTitleText.SetResourceReference(TextElement.ForegroundProperty, "ImportantText");
        MarkdownFlowDocumentBuilder.AddInboxInlineText(taskTitleText.Inlines, taskTitle);
        taskParagraph.Inlines.Add(taskTitleText);
        blocks.Add(taskParagraph);
        copyParts.Add($"Plan: {plan.Group.GroupTitle}");
        copyParts.Add($"{stepLabel}: {taskTitle}");

        var explanationParagraph = CreateTranscriptParagraph(bottomMargin: 8);
        var explanationRun = new Run(attentionCard.Explanation);
        explanationRun.SetResourceReference(TextElement.ForegroundProperty, "BodyText");
        explanationParagraph.Inlines.Add(explanationRun);
        blocks.Add(explanationParagraph);
        copyParts.Add(string.Empty);
        copyParts.Add(attentionCard.Explanation);

        var reasonParagraph = CreateTranscriptParagraph(bottomMargin: 11);
        var reasonLabel = new Run(attentionCard.Category is PlanAttentionCategory.HumanVerificationRequired or
                PlanAttentionCategory.HumanInputRequired
            ? "Human check: "
            : "What happened: ");
        reasonLabel.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        reasonParagraph.Inlines.Add(reasonLabel);
        var reasonText = new Span();
        reasonText.SetResourceReference(TextElement.ForegroundProperty, "ImportantText");
        AddRecoveryCommitLinkedText(reasonText.Inlines, attentionCard.RecordedReason);
        reasonParagraph.Inlines.Add(reasonText);
        blocks.Add(reasonParagraph);
        copyParts.Add(string.Empty);
        copyParts.Add((attentionCard.Category is PlanAttentionCategory.HumanVerificationRequired or
                PlanAttentionCategory.HumanInputRequired
            ? "Human check: "
            : "What happened: ") + CommitReferenceText.Shorten(attentionCard.RecordedReason));

        if (humanChecklistItems.Length > 0)
        {
            var checklistStack = new StackPanel { Margin = new Thickness(0, 0, 0, 7) };
            var checklistLabel = new TextBlock
            {
                Text = "Verify the Following:",
                FontSize = _transcriptFontSize - 1,
                FontWeight = FontWeights.SemiBold,
                Margin = new Thickness(0, 0, 0, 3),
            };
            checklistLabel.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
            checklistStack.Children.Add(checklistLabel);
            var setAllSelections = new List<Action>();
            foreach (var item in humanChecklistItems)
            {
                var itemText = new TextBlock
                {
                    Text = item.Text,
                    FontSize = _transcriptFontSize + 1,
                    TextWrapping = TextWrapping.Wrap,
                };
                itemText.SetResourceReference(TextBlock.ForegroundProperty, "ImportantText");
                var localChecked = item.IsChecked;
                var localUncertain = item.WasPreviouslyChecked && !item.IsChecked;
                var checkIcon = Application.Current?.TryFindResource("PlanApprovalResolvedCheck") as Viewbox
                    ?? new Viewbox();
                checkIcon.Visibility = localChecked ? Visibility.Visible : Visibility.Hidden;
                checkIcon.Margin = new Thickness(2);
                var questionIcon = Application.Current?.TryFindResource("TaskAwaitingHumanApproval") as Viewbox
                    ?? new Viewbox();
                questionIcon.Visibility = localUncertain ? Visibility.Visible : Visibility.Hidden;
                questionIcon.Margin = new Thickness(4);
                var stateIcons = new Grid();
                stateIcons.Children.Add(checkIcon);
                stateIcons.Children.Add(questionIcon);
                var boxSize = Math.Round((_transcriptFontSize + 1) * 1.2);
                var box = new Border
                {
                    Width = boxSize,
                    Height = boxSize,
                    BorderThickness = new Thickness(1.5),
                    CornerRadius = new CornerRadius(2),
                    Background = Brushes.Transparent,
                    Margin = new Thickness(8, 3, 6, 0),
                    VerticalAlignment = VerticalAlignment.Top,
                    Cursor = Cursors.Hand,
                    Child = stateIcons,
                    ToolTip = ToolTipHelper.MakeThemedToolTip(localUncertain
                        ? PlanHumanReviewChecklist.ReconfirmationToolTip
                        : "Check this after you personally verify that the statement is true."),
                };
                box.SetResourceReference(Border.BorderBrushProperty, "InputBorder");
                System.Windows.Automation.AutomationProperties.SetName(box, item.Text);
                var itemRow = new Grid { Margin = new Thickness(0, 0, 0, 4) };
                itemRow.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                itemRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                Grid.SetColumn(box, 0);
                Grid.SetColumn(itemText, 1);
                itemRow.Children.Add(box);
                itemRow.Children.Add(itemText);
                void AttachReviewItemMenu(FrameworkElement target)
                {
                    var itemMenu = new ContextMenu();
                    itemMenu.SetResourceReference(ContextMenu.StyleProperty, "ThemedContextMenuStyle");
                    var clarify = new MenuItem { Header = "Clarify This…" };
                    clarify.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                    clarify.Click += (_, _) => QueueClarifyHumanReviewItem(durablePlan!, item);
                    itemMenu.Items.Add(clarify);
                    var refreshWording = new MenuItem { Header = "Refresh Wording…" };
                    refreshWording.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                    refreshWording.Click += (_, _) => QueueRefreshHumanReviewWording(durablePlan!, item);
                    itemMenu.Items.Add(refreshWording);
                    target.ContextMenu = itemMenu;
                    target.PreviewMouseRightButtonUp += (_, e) =>
                    {
                        itemMenu.PlacementTarget = target;
                        itemMenu.IsOpen = true;
                        e.Handled = true;
                    };
                }

                AttachReviewItemMenu(itemRow);
                AttachReviewItemMenu(box);
                AttachReviewItemMenu(itemText);
                var capturedItem = item;
                void SetChecked(bool value)
                {
                    localChecked = value;
                    localUncertain = false;
                    checkIcon.Visibility = value ? Visibility.Visible : Visibility.Hidden;
                    questionIcon.Visibility = Visibility.Hidden;
                    box.ToolTip = ToolTipHelper.MakeThemedToolTip(
                        "Check this after you personally verify that the statement is true.");
                    humanChecklistState[capturedItem.ItemId] = value;
                    RecordHumanReviewChecklistSelection(durablePlan!.PlanId, capturedItem, value);
                    refreshHumanReviewActions();
                }
                box.MouseDown += (_, e) =>
                {
                    if (e.ChangedButton == MouseButton.Left)
                        SetChecked(!localChecked);
                };
                setAllSelections.Add(() => SetChecked(true));
                checklistStack.Children.Add(itemRow);
                copyParts.Add((item.IsChecked ? "☑ " : item.WasPreviouslyChecked ? "? " : "☐ ") + item.Text);
                var requirement = reviewAttention is null
                    ? null
                    : PlanReviewAttentionPresentationResolver.FindRequirement(reviewAttention, item);
                if (requirement?.VerificationRecipe is { } recipe)
                {
                    var recipeStack = new StackPanel
                    {
                        Margin = new Thickness(32, -1, 0, 5),
                    };
                    foreach (var (label, value) in new[]
                    {
                        ("Setup", recipe.Setup),
                        ("Open", recipe.Open),
                        ("Observe", recipe.Observe),
                        ("Cleanup", recipe.Cleanup),
                    })
                    {
                        if (string.IsNullOrWhiteSpace(value)) continue;
                        var instruction = new TextBlock
                        {
                            FontSize = _transcriptFontSize - 1,
                            TextWrapping = TextWrapping.Wrap,
                            Margin = new Thickness(0, 1, 0, 0),
                        };
                        instruction.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
                        instruction.Inlines.Add(new Run(label + ": ") { FontWeight = FontWeights.SemiBold });
                        instruction.Inlines.Add(new Run(value));
                        recipeStack.Children.Add(instruction);
                        copyParts.Add($"{label}: {value}");
                    }
                    checklistStack.Children.Add(recipeStack);
                }
            }
            var checklistBorder = new Border
            {
                Child = checklistStack,
                CornerRadius = new CornerRadius(6),
                BorderThickness = new Thickness(1),
                Padding = new Thickness(10, 8, 10, 8),
                Margin = new Thickness(0, 2, 0, 8),
            };
            checklistBorder.SetResourceReference(Border.BackgroundProperty, "ApprovalFieldSurface");
            checklistBorder.SetResourceReference(Border.BorderBrushProperty, "InputBorder");
            var menu = new ContextMenu();
            menu.SetResourceReference(ContextMenu.StyleProperty, "ThemedContextMenuStyle");
            var markAll = new MenuItem { Header = "Mark All as Verified" };
            markAll.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
            markAll.Click += (_, _) =>
            {
                foreach (var setChecked in setAllSelections)
                    setChecked();
            };
            menu.Items.Add(markAll);
            checklistBorder.ContextMenu = menu;
            blocks.Add(TranscriptCardLayout.CreateContainer(
                checklistBorder,
                margin: new Thickness(0)));
        }

        if (humanReview is { AnalysisBullets.Count: > 0 })
        {
            var analysisLabel = CreateTranscriptParagraph(bottomMargin: 2);
            var analysisLabelRun = new Run("Automated Review Status:");
            analysisLabelRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
            analysisLabel.Inlines.Add(analysisLabelRun);
            blocks.Add(analysisLabel);

            var analysisList = new System.Windows.Documents.List
            {
                MarkerStyle = TextMarkerStyle.Disc,
                Margin = new Thickness(18, 0, 0, 7),
                Padding = new Thickness(0),
            };
            foreach (var bullet in humanReview.AnalysisBullets)
            {
                var bulletParagraph = CreateTranscriptParagraph(bottomMargin: 2);
                // Keep every conclusion readable. Severity must not reduce text contrast.
                bulletParagraph.SetResourceReference(TextElement.ForegroundProperty, "ImportantText");
                AddRecoveryCommitLinkedText(bulletParagraph.Inlines, bullet.Text);
                analysisList.ListItems.Add(new ListItem(bulletParagraph));
                copyParts.Add("• " + bullet.Text);
            }
            blocks.Add(analysisList);
        }

        if (humanReview?.PreviousReview is { } previousReview)
        {
            var previousStack = new StackPanel { Margin = new Thickness(8, 4, 4, 4) };
            var previousExplanation = new TextBlock
            {
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 0, 0, 5),
            };
            previousExplanation.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
            AddRecoveryCommitLinkedText(
                previousExplanation.Inlines,
                $"This review applies to commit {previousReview.EvaluatedCommit}, not current commit {previousReview.CurrentCommit}.");
            previousStack.Children.Add(previousExplanation);
            foreach (var bullet in previousReview.AnalysisBullets)
            {
                var item = new TextBlock
                {
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(8, 1, 0, 2),
                };
                item.SetResourceReference(TextBlock.ForegroundProperty, "ImportantText");
                item.Inlines.Add(new Run("• "));
                AddRecoveryCommitLinkedText(item.Inlines, bullet.Text);
                previousStack.Children.Add(item);
            }

            var previousHeaderCommit = string.IsNullOrWhiteSpace(previousReview.EvaluatedCommit)
                ? "unknown commit"
                : previousReview.EvaluatedCommit.Length > 7
                ? previousReview.EvaluatedCommit[..7]
                : previousReview.EvaluatedCommit;
            var previousExpander = new Expander
            {
                Header = $"Previous review ({previousHeaderCommit})",
                Content = previousStack,
                IsExpanded = false,
                Margin = new Thickness(0, 0, 0, 6),
            };
            previousExpander.SetResourceReference(Expander.ForegroundProperty, "SubtleText");
            if (TryFindResource("TranscriptExpanderStyle") is Style previousExpanderStyle)
                previousExpander.Style = previousExpanderStyle;
            blocks.Add(TranscriptCardLayout.CreateContainer(
                previousExpander,
                margin: new Thickness(0)));
            copyParts.Add($"Previous review ({previousHeaderCommit}) is available separately.");
        }

        if (completedWorkReview is not null)
        {
            AppendCompletedWorkReviewDetails(
                blocks,
                completedWorkReview,
                durablePlan!.PlanId,
                durablePlan.Revision);
            copyParts.Add(CompletedWorkReviewPresentationBuilder.BuildCompactCopyText(
                completedWorkReview));
        }

        var recoveryHead = ReadCachedRecoveryHeadCommit();
        var correctionActivity = PlanTaskCorrectionActivityPolicy.Resolve(
            _pendingPlanTaskCorrectionContext,
            plan.Group.GroupId,
            taskId,
            _isPromptRunning,
            _pec.CurrentDispatchedItem?.Id,
            _pec.CurrentDispatchedItem?.SourceTag);
        var recoveryActionSet = durablePlan is null
            ? null
            : PlanRecoveryActionSetBuilder.Build(
                durablePlan,
                taskId,
                recoveryHead,
                (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant),
                includeEndPlan: !planRunnerActive,
                correctionActivity);
        var decisionPrompt = attentionCard.Category switch
        {
            PlanAttentionCategory.HumanVerificationRequired =>
                "Verify this step is complete to continue the plan.",
            PlanAttentionCategory.HumanInputRequired =>
                "Reply with the requested decision. SquadDash will preserve the plan until then.",
            PlanAttentionCategory.AutomaticWorkExhausted when recoveryActionSet is not null =>
                recoveryActionSet.DecisionPrompt,
            _ => "Continue from the preserved work or copy the diagnostic report for investigation.",
        };
        var decisionParagraph = CreateTranscriptParagraph(bottomMargin: 10);
        decisionParagraph.Margin = new Thickness(0, 9, 0, 10);
        var decisionRun = new Run(decisionPrompt);
        decisionRun.SetResourceReference(TextElement.ForegroundProperty, "BodyText");
        decisionParagraph.Inlines.Add(decisionRun);
        blocks.Add(decisionParagraph);
        copyParts.Add(string.Empty);
        copyParts.Add(decisionPrompt);

        var recoveryTechnicalDetails = completedWorkReview?.TechnicalDetails ??
            durablePlan?.InterruptionData?.Reason;
        if (!string.IsNullOrWhiteSpace(recoveryTechnicalDetails))
        {
            var technicalText = new TextBlock
            {
                Text = recoveryTechnicalDetails,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(8, 4, 0, 4),
                FontFamily = new FontFamily("Consolas"),
                FontSize = _transcriptFontSize - 1,
            };
            technicalText.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
            var technicalDetails = new Expander
            {
                Header = "Technical details",
                Content = technicalText,
                IsExpanded = false,
                Margin = new Thickness(0, 0, 0, 6),
            };
            technicalDetails.SetResourceReference(Expander.ForegroundProperty, "SubtleText");
            if (TryFindResource("TranscriptExpanderStyle") is Style expanderStyle)
                technicalDetails.Style = expanderStyle;
            blocks.Add(TranscriptCardLayout.CreateContainer(
                technicalDetails,
                margin: new Thickness(0)));
            copyParts.Add("Technical details:" + Environment.NewLine + recoveryTechnicalDetails);
        }
        var hasPreservedWork = string.Equals(_decomposeContinuationTaskId, taskId, StringComparison.Ordinal) &&
                               _decomposeContinuationPaths.Count > 0;
        var presentation = durablePlan is null
            ? null
            : PlanRecoveryPresentationBuilder.Build(durablePlan, taskId, hasPreservedWork);
        var primaryRecoveryAction = durablePlan is null
            ? null
            : PlanRecoveryActionPresentationBuilder.Build(
                durablePlan,
                taskId,
                recoveryHead,
                (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant));

        void AddCanonicalRecoveryAction(PlanRecoverySurfaceActionPresentation action)
        {
            switch (action.Kind)
            {
                case PlanRecoverySurfaceActionKind.AcceptStep when durablePlan is not null:
                    AddAsyncResultAction(
                        action.Label,
                        action.Hint,
                        async () => await AcceptInterruptedStepAfterReviewAsync(
                            _planStore?.Load(durablePlan.PlanId) ?? durablePlan));
                    break;
                case PlanRecoverySurfaceActionKind.ResumeVerification:
                    AddAsyncAction(
                        action.Label,
                        action.Hint,
                        async () => await AssessPlanRecoveryAsync(plan, taskId));
                    break;
                case PlanRecoverySurfaceActionKind.ContinueWorking:
                    if (string.Equals(action.ProtocolAction, "request-corrections", StringComparison.Ordinal))
                    {
                        AddAsyncAction(
                            action.Label,
                            action.Hint,
                            async () => await QueuePlanRecoveryCorrectionAsync(plan, taskId));
                    }
                    else
                    {
                        AddAsyncAction(
                            action.Label,
                            action.Hint,
                            async () => await RetryDecomposeTaskAsync(plan, taskId));
                    }
                    break;
                case PlanRecoverySurfaceActionKind.ReviseRemainingPlan:
                    AddAction(
                        action.Label,
                        action.Hint,
                        () => QueueDecomposeReplan(plan, taskId),
                        removeAfterAction: false,
                        tone: action.Tone);
                    break;
                case PlanRecoverySurfaceActionKind.EndPlan when durablePlan is not null:
                    AddAction(
                        action.Label,
                        action.Hint,
                        () => EndInterruptedPlan(_planStore?.Load(durablePlan.PlanId) ?? durablePlan),
                        tone: action.Tone);
                    break;
            }
        }

        if (isBranchLeaseRecovery && durablePlan is not null)
        {
            var canonicalBranchIsActive = _currentWorkspace is not null && string.Equals(
                ReadGitBranch(_currentWorkspace.FolderPath),
                durablePlan.Branch,
                StringComparison.Ordinal);
            AddAsyncAction(
                canonicalBranchIsActive ? "Resume Plan" : "Choose Branch & Resume…",
                canonicalBranchIsActive
                    ? "Resume with the pending task on the already-restored host-owned plan branch. No AI assessment or repeated completed work is needed."
                    : $"Compare the current branch with the plan branch '{durablePlan.Branch}', then choose whether to " +
                      "bring current work into the plan or switch while preserving it separately.",
                async () => await RestorePlanBranchAndResumeAsync(durablePlan));
            blocks.Add(TranscriptQuickReplyFactory.CreateContainer(panel, recoveryTag));
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        if (attentionCard.Category == PlanAttentionCategory.UnexpectedState)
        {
            if (completedWorkReview is not null && durablePlan is not null)
            {
                AddNavigationLink(
                    completedWorkReview.ComparisonLabel,
                    completedWorkReview.ComparisonHint,
                    () => _ = OpenInterruptedTaskReviewAsync(durablePlan.PlanId, durablePlan.Revision));
            }
            foreach (var action in recoveryActionSet?.Actions ?? [])
                AddCanonicalRecoveryAction(action);
            AddUtilityAction(
                "Copy Diagnostic Report",
                "Copy the plan identity, recorded error, and technical details for a SquadDash issue report.",
                () => SetClipboardTextWithRetry(
                    PlanAttentionCardPresentationBuilder.BuildCopyText(
                        attentionCard,
                        plan.Group.GroupTitle,
                        stepLabel,
                        taskTitle,
                        recoveryTechnicalDetails)));
            AddUtilityAction(
                "Open Logs",
                "Open the live SquadDash trace so the unexpected state can be investigated.",
                ShowTraceWindow);
            blocks.Add(TranscriptQuickReplyFactory.CreateContainer(panel, recoveryTag));
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        if (attentionCard.Category == PlanAttentionCategory.AutomaticWorkExhausted)
        {
            if (completedWorkReview is not null && durablePlan is not null)
            {
                AddNavigationLink(
                    completedWorkReview.ComparisonLabel,
                    completedWorkReview.ComparisonHint,
                    () => _ = OpenInterruptedTaskReviewAsync(durablePlan.PlanId, durablePlan.Revision));
            }
            foreach (var action in recoveryActionSet?.Actions ?? [])
                AddCanonicalRecoveryAction(action);
            blocks.Add(TranscriptQuickReplyFactory.CreateContainer(panel, recoveryTag));
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        if (assessmentEvidence is not null &&
            string.Equals(durablePlan?.InterruptionData?.InterruptedTaskId, taskId, StringComparison.Ordinal))
        {
            var assessmentTask = durablePlan!.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, taskId, StringComparison.Ordinal));
            var assessmentStepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
                assessmentTask?.DisplayStepLabel,
                assessmentTask?.Title ?? taskTitle);
            var assessmentPresentation = PlanRecoveryAssessmentCardPresentationBuilder.Build(
                assessmentEvidence,
                assessmentStepLabel);
            var assessmentParagraph = CreateTranscriptParagraph(bottomMargin: 5);
            var assessmentCommit = assessmentEvidence.EvaluatedCommit ?? assessmentEvidence.HeadCommit;
            var displayedCommit = presentation?.CommitEvidence?.Commit;
            if (!string.IsNullOrWhiteSpace(displayedCommit) &&
                !string.Equals(assessmentCommit, displayedCommit, StringComparison.OrdinalIgnoreCase))
            {
                var source = string.IsNullOrWhiteSpace(assessmentCommit)
                    ? "an unknown earlier commit"
                    : $"commit {assessmentCommit}";
                MarkdownFlowDocumentBuilder.AddInboxInlineText(
                    assessmentParagraph.Inlines,
                    $"Assessment below reflects {source}; current evidence is commit {displayedCommit}. " +
                    "These conclusions have not been reverified for the current evidence.\n\n");
            }
            MarkdownFlowDocumentBuilder.AddInboxInlineText(
                assessmentParagraph.Inlines,
                assessmentPresentation.Finding);
            blocks.Add(assessmentParagraph);

            if (assessmentEvidence.Verification is { } verification)
            {
                var verificationParagraph = CreateTranscriptParagraph(bottomMargin: 4);
                verificationParagraph.Margin = new Thickness(12, 0, 0, 4);
                var verificationText = string.IsNullOrWhiteSpace(verification.Summary)
                    ? $"Verification: {verification.Status}"
                    : $"Verification ({verification.Status}): {verification.Summary}";
                MarkdownFlowDocumentBuilder.AddInboxInlineText(
                    verificationParagraph.Inlines,
                    verificationText);
                blocks.Add(verificationParagraph);
            }

            if (assessmentEvidence.NoOpEvidence is { Count: > 0 })
            {
                var evidenceHeader = CreateTranscriptParagraph(bottomMargin: 2);
                evidenceHeader.Inlines.Add(new Run("Already-satisfied evidence:") { FontWeight = FontWeights.SemiBold });
                blocks.Add(evidenceHeader);
                foreach (var evidenceItem in assessmentEvidence.NoOpEvidence)
                {
                    var evidenceParagraph = CreateTranscriptParagraph(bottomMargin: 2);
                    evidenceParagraph.Margin = new Thickness(12, 0, 0, 2);
                    MarkdownFlowDocumentBuilder.AddInboxInlineText(
                        evidenceParagraph.Inlines,
                        $"• {evidenceItem.Requirement}: {evidenceItem.Observation} ({string.Join(", ", evidenceItem.Locations)})");
                    blocks.Add(evidenceParagraph);
                }
            }

            if (assessmentEvidence.RemainingWork is { Count: > 0 })
            {
                var remainingHeader = CreateTranscriptParagraph(bottomMargin: 2);
                remainingHeader.Inlines.Add(new Run("Remaining work:") { FontWeight = FontWeights.SemiBold });
                blocks.Add(remainingHeader);
                foreach (var remainingItem in assessmentEvidence.RemainingWork)
                {
                    var remainingParagraph = CreateTranscriptParagraph(bottomMargin: 2);
                    remainingParagraph.Margin = new Thickness(12, 0, 0, 2);
                    MarkdownFlowDocumentBuilder.AddInboxInlineText(
                        remainingParagraph.Inlines,
                        "• " + remainingItem);
                    blocks.Add(remainingParagraph);
                }
            }

            var assessmentRecommendation = CreateTranscriptParagraph(bottomMargin: 6);
            AddRecoveryRecommendationText(
                assessmentRecommendation.Inlines,
                assessmentPresentation.Recommendation);
            blocks.Add(assessmentRecommendation);

            if (!string.Equals(
                    assessmentEvidence.CompletionKind,
                    DecomposeStepCompletionKind.VerifiedNoOp,
                    StringComparison.Ordinal))
            {
                var assessmentTerminalCommit = assessmentEvidence.Commits?.LastOrDefault()?.Commit ??
                    completedWorkReview?.Commit?.Sha;
                AddNavigationLink(
                    completedWorkReview?.ComparisonLabel ??
                    PlanRecoveryPresentationBuilder.BuildCommittedReviewLabel(
                        assessmentStepLabel,
                        durablePlan.InterruptionData?.TaskCommitEvidence?.BaselineCommit ??
                        durablePlan.InterruptionData?.LastCommit,
                        assessmentTerminalCommit),
                    completedWorkReview?.ComparisonHint ??
                    PlanRecoveryPresentationBuilder.CommittedReviewHint(
                        assessmentStepLabel,
                        durablePlan.InterruptionData?.TaskCommitEvidence?.BaselineCommit ??
                        durablePlan.InterruptionData?.LastCommit,
                        assessmentTerminalCommit),
                    () => _ = OpenInterruptedTaskReviewAsync(durablePlan.PlanId, durablePlan.Revision));
            }

            AddAsyncResultAction(
                $"Accept {assessmentStepLabel} as Complete",
                $"Review and explicitly accept the existing evidence for {assessmentStepLabel}, mark only this step complete, and continue the plan.",
                async () =>
                {
                    var latest = _planStore?.Load(durablePlan.PlanId) ?? durablePlan;
                    return await AcceptInterruptedStepAfterReviewAsync(latest);
                });
            AddAsyncAction(
                $"Continue Working on {assessmentStepLabel}",
                $"Keep {assessmentStepLabel} incomplete and continue from the existing repository state.",
                async () => await RetryDecomposeTaskAsync(plan, taskId));
            AddAction("✎ Revise Remaining Plan…", "Create an editable replanning prompt with protected plan context attached.",
                () => QueueDecomposeReplan(plan, taskId));
            blocks.Add(TranscriptQuickReplyFactory.CreateContainer(panel, recoveryTag));
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        if (durablePlan is not null && PlanRecoveryResumePolicy.IsSafelyResumable(durablePlan))
        {
            var isReworkPause = PlanRecoveryResumePolicy.IsReworkPreflightPause(durablePlan);
            var isAmendmentPause = PlanRecoveryResumePolicy.IsAmendmentPreflightPause(durablePlan);
            AddAsyncAction(
                isAmendmentPause ? "Resume Amendment" : isReworkPause ? "Resume Rework" : "Resume Plan",
                isAmendmentPause
                    ? "Resume the added amendment after committing or stashing blocking changes; completed tasks remain accepted."
                    : isReworkPause
                        ? "Resume the already-reopened task after committing or stashing any blocking workspace changes. The change request will not be submitted again."
                        : "Resume with the next runnable plan step. Previously accepted work will not be repeated.",
                async () => await StartOrResumeDurablePlanAsync(durablePlan));
            blocks.Add(TranscriptQuickReplyFactory.CreateContainer(panel, recoveryTag));
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        if (durablePlan?.LifecycleStatus == PlanLifecycleStatus.Interrupted)
        {
            if (presentation!.CommitEvidence is { } commitEvidence)
            {
                var commitParagraph = CreateTranscriptParagraph(bottomMargin: 3);
                commitParagraph.Margin = new Thickness(12, 0, 0, 3);
                var shortCommit = commitEvidence.Commit.Length > 7
                    ? commitEvidence.Commit[..7]
                    : commitEvidence.Commit;
                commitParagraph.Inlines.Add(new Run("Commits: "));
                var commitLink = new Hyperlink(new Run(shortCommit))
                {
                    Cursor = Cursors.Hand,
                    ToolTip = "Open this commit on GitHub",
                };
                commitLink.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
                commitLink.Click += async (_, _) =>
                    await OpenCommitWithRemoteCheckAsync(commitEvidence.Commit);
                commitParagraph.Inlines.Add(commitLink);
                blocks.Add(commitParagraph);

                var compactTests = completedWorkReview is null
                    ? PlanRecoveryPresentationBuilder.BuildCompactTestSummary(commitEvidence.Verification)
                    : null;
                if (compactTests is not null)
                {
                    var verificationParagraph = CreateTranscriptParagraph(bottomMargin: 3);
                    verificationParagraph.Margin = new Thickness(12, 0, 0, 3);
                    var verificationPassed = string.Equals(
                        commitEvidence.Verification?.Status,
                        "passed",
                        StringComparison.OrdinalIgnoreCase);
                    verificationParagraph.SetResourceReference(
                        TextElement.ForegroundProperty,
                        verificationPassed ? "ToolSuccessIcon" : "SubtleText");
                    MarkdownFlowDocumentBuilder.AddInboxInlineText(
                        verificationParagraph.Inlines,
                        (verificationPassed ? "✓ " : string.Empty) + compactTests);
                    blocks.Add(verificationParagraph);
                }
            }

            var recommendation = CreateTranscriptParagraph(bottomMargin: 6);
            var recommendationText = combinedHumanReviewGate is null
                ? presentation.Recommendation
                : $"Use the commit link above to investigate. Confirming {stepLabel} also approves the human checkpoint above.";
            AddRecoveryRecommendationText(recommendation.Inlines, recommendationText);
            blocks.Add(recommendation);

        }

        if (combinedHumanReviewGate is not null && humanChecklistItems.Length > 0)
        {
            var completionButton = AddAsyncResultAction(
                durablePlan!.IsPaused
                    ? $"{stepLabel} Is Complete"
                    : $"{stepLabel} Is Complete & Continue",
                durablePlan.IsPaused
                    ? $"Enabled once every verification item is checked. Mark {stepLabel} complete and record the human checkpoint. The plan remains paused."
                    : $"Enabled once every verification item is checked. Mark {stepLabel} complete, record the human checkpoint, and continue without another AI review.",
                async () =>
                {
                    var latest = _planStore?.Load(durablePlan!.PlanId) ?? durablePlan!;
                    return await AcceptInterruptedStepAfterReviewAsync(latest);
                });
            var addressButton = AddAction(
                "✎ Address Unchecked Items…",
                "Create an editable queued prompt with the current plan and unchecked verification items attached as protected context.",
                () => QueueAddressUncheckedItems(
                    _planStore?.Load(durablePlan!.PlanId) ?? durablePlan!,
                    taskId,
                    humanChecklistItems.Select(item => item with
                    {
                        IsChecked = humanChecklistState[item.ItemId]
                    }).ToArray(),
                    combinedHumanReviewGate.GateId),
                removeAfterAction: true);
            AddAction(
                "✎ Revise Remaining Plan…",
                "Create an editable queued prompt with protected plan and replanning context attached. Nothing is sent until you review and submit it.",
                () => QueueDecomposeReplan(plan, taskId),
                removeAfterAction: false);
            refreshHumanReviewActions = () =>
            {
                var allChecked = humanChecklistState.Count > 0 &&
                                 humanChecklistState.Values.All(value => value);
                completionButton.IsEnabled = allChecked;
                addressButton.IsEnabled = humanChecklistState.Values.Any(value => !value);
            };
            refreshHumanReviewActions();
            blocks.Add(TranscriptQuickReplyFactory.CreateContainer(panel, recoveryTag));
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        if (durablePlan is not null &&
            primaryRecoveryAction?.Kind is PlanRecoveryPrimaryActionKind.AcceptStep or
                PlanRecoveryPrimaryActionKind.AcceptUnattributedStep or
                PlanRecoveryPrimaryActionKind.AcceptRejectedNoOp or
                PlanRecoveryPrimaryActionKind.ApproveAmendment)
        {
            if (completedWorkReview is not null)
            {
                AddNavigationLink(
                    completedWorkReview.ComparisonLabel,
                    completedWorkReview.ComparisonHint,
                    () => _ = OpenInterruptedTaskReviewAsync(durablePlan.PlanId, durablePlan.Revision));
            }
            else if (primaryRecoveryAction.Kind == PlanRecoveryPrimaryActionKind.AcceptUnattributedStep)
            {
                AddNavigationLink(
                    PlanRecoveryPresentationBuilder.BuildUnattributedReviewLabel(
                        stepLabel,
                        durablePlan.InterruptionData?.LastCommit),
                    PlanRecoveryPresentationBuilder.UnattributedReviewHint(
                        stepLabel,
                        durablePlan.InterruptionData?.LastCommit),
                    () => _ = OpenInterruptedTaskReviewAsync(durablePlan.PlanId, durablePlan.Revision));
            }
            AddAsyncResultAction(
                primaryRecoveryAction.Label,
                primaryRecoveryAction.Hint,
                async () =>
                {
                    var latest = _planStore?.Load(durablePlan.PlanId) ?? durablePlan;
                    return await AcceptInterruptedStepAfterReviewAsync(latest);
                });
            if (primaryRecoveryAction.Kind == PlanRecoveryPrimaryActionKind.AcceptStep)
            {
                AddAsyncAction(
                    $"✎ Continue Working on {stepLabel}…",
                    $"Open an editable, task-scoped correction prompt. Existing work is preserved and {stepLabel} is not rerun from scratch.",
                    async () => await QueuePlanRecoveryCorrectionAsync(plan, taskId));
            }
            else if (primaryRecoveryAction.Kind == PlanRecoveryPrimaryActionKind.AcceptUnattributedStep)
            {
                AddAsyncAction(
                    $"Continue Working on {stepLabel}",
                    $"Keep {stepLabel} incomplete and continue from the preserved repository state.",
                    async () => await RetryDecomposeTaskAsync(plan, taskId));
            }
            else if (primaryRecoveryAction.Kind == PlanRecoveryPrimaryActionKind.AcceptRejectedNoOp)
            {
                AddAsyncAction(
                    "Retry Verification",
                    $"Run the non-mutating checks for {stepLabel} again instead of accepting the prior reported result.",
                    async () => await RetryDecomposeTaskAsync(plan, taskId));
            }
            AddAction(
                "✎ Revise Remaining Plan…",
                "Create an editable queued prompt with protected plan and replanning context attached. Nothing is sent until you review and submit it.",
                () => QueueDecomposeReplan(plan, taskId),
                removeAfterAction: false);
            blocks.Add(TranscriptQuickReplyFactory.CreateContainer(panel, recoveryTag));
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        var recoveryActionLabel = primaryRecoveryAction?.Label ?? $"Continue Working on {stepLabel}";
        var recoveryActionHint = primaryRecoveryAction?.Hint ??
            $"Keep {stepLabel} incomplete and continue from the preserved repository state. No preliminary AI assessment runs.";
        AddAsyncAction(
            recoveryActionLabel,
            recoveryActionHint,
            async () =>
            {
                if (primaryRecoveryAction?.Kind == PlanRecoveryPrimaryActionKind.ResumeVerification)
                    await AssessPlanRecoveryAsync(plan, taskId);
                else
                    await RetryDecomposeTaskAsync(plan, taskId);
            });
        AddAction("✎ Revise Remaining Plan…", "Create an editable replanning prompt with protected plan context attached.",
            () => QueueDecomposeReplan(plan, taskId));

        if (showEndPlan && !planRunnerActive)
        {
            AddAction("End This Incomplete Plan",
                "Mark this plan as stopped without retrying or replanning. The plan history is preserved.",
                () =>
                {
                    var durablePlan = _planStore?.Load(plan.Group.GroupId);
                    if (durablePlan is not null) EndInterruptedPlan(durablePlan);
                },
                tone: QuickReplyTone.Destructive);
        }

        blocks.Add(TranscriptQuickReplyFactory.CreateContainer(
            panel,
            recoveryTag));
        ScrollToEndIfAtBottom(CoordinatorThread);

        void AddNavigationLink(string label, string hint, Action action)
        {
            var paragraph = CreateTranscriptParagraph(bottomMargin: 10);
            var link = new Hyperlink(new Run(label))
            {
                Cursor = Cursors.Hand,
                ToolTip = ToolTipHelper.MakeThemedToolTip(hint),
            };
            link.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
            link.Click += (_, _) => action();
            paragraph.Inlines.Add(link);
            blocks.Add(paragraph);
        }

        void AddRecoveryRecommendationText(InlineCollection inlines, string text)
        {
            copyParts.Add(CommitReferenceText.Shorten(text));
            const string recommendedLabel = "Recommended:";
            const string recommendationLabel = "Recommendation:";
            var label = text.StartsWith(recommendedLabel, StringComparison.Ordinal)
                ? recommendedLabel
                : text.StartsWith(recommendationLabel, StringComparison.Ordinal)
                    ? recommendationLabel
                    : null;
            if (label is null)
            {
                MarkdownFlowDocumentBuilder.AddInboxInlineText(inlines, text);
                return;
            }

            var labelRun = new Run(label);
            labelRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
            inlines.Add(labelRun);
            AddImportantRecoveryText(inlines, text[label.Length..]);
        }

        void AddImportantRecoveryText(InlineCollection inlines, string text)
        {
            var importantText = new Span();
            importantText.SetResourceReference(TextElement.ForegroundProperty, "ImportantText");
            foreach (var segment in CommitReferenceText.Parse(text))
            {
                if (segment.FullSha is null)
                {
                    MarkdownFlowDocumentBuilder.AddInboxInlineText(importantText.Inlines, segment.Text);
                    continue;
                }

                var commitLink = new Hyperlink(new Run(segment.Text))
                {
                    Cursor = Cursors.Hand,
                    ToolTip = ToolTipHelper.MakeThemedToolTip("Open this commit in SquadDash"),
                };
                commitLink.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
                var fullSha = segment.FullSha;
                commitLink.Click += async (_, _) => await OpenCommitWithRemoteCheckAsync(fullSha);
                importantText.Inlines.Add(commitLink);
            }
            inlines.Add(importantText);
        }

        Button AddAction(
            string label,
            string hint,
            Action action,
            bool removeAfterAction = true,
            QuickReplyTone tone = QuickReplyTone.Default)
        {
            var button = TranscriptQuickReplyFactory.CreateButton(
                label,
                _transcriptFontSize,
                toolTip: ToolTipHelper.MakeThemedToolTip(hint),
                tone: tone);
            button.Click += (_, _) =>
            {
                cardTag.SetActionsEnabled(false);
                if (removeAfterAction) panel.Visibility = Visibility.Collapsed;
                PrepareForHostRecoveryAction();
                action();
            };
            panel.Children.Add(button);
            return button;
        }

        Button AddUtilityAction(string label, string hint, Action action)
        {
            var button = TranscriptQuickReplyFactory.CreateButton(
                label,
                _transcriptFontSize,
                toolTip: ToolTipHelper.MakeThemedToolTip(hint));
            button.Click += (_, _) => action();
            panel.Children.Add(button);
            return button;
        }

        void AddAsyncAction(
            string label,
            string hint,
            Func<Task> action,
            bool removeAfterAction = true,
            QuickReplyTone tone = QuickReplyTone.Default)
        {
            var button = TranscriptQuickReplyFactory.CreateButton(
                label,
                _transcriptFontSize,
                toolTip: ToolTipHelper.MakeThemedToolTip(hint),
                tone: tone);
            button.Click += async (_, _) =>
            {
                cardTag.SetActionsEnabled(false);
                if (removeAfterAction) panel.Visibility = Visibility.Collapsed;
                PrepareForHostRecoveryAction();
                try { await action(); }
                catch (Exception ex)
                {
                    cardTag.SetActionsEnabled(true);
                    if (removeAfterAction) panel.Visibility = Visibility.Visible;
                    HandleUiCallbackException("Decompose recovery", ex);
                }
            };
            panel.Children.Add(button);
        }

        Button AddAsyncResultAction(
            string label,
            string hint,
            Func<Task<bool>> action,
            bool removeAfterAction = true,
            QuickReplyTone tone = QuickReplyTone.Default)
        {
            var actionStatus = new TextBlock
            {
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(4, 4, 4, 0),
                Visibility = Visibility.Collapsed,
            };
            actionStatus.SetResourceReference(TextBlock.ForegroundProperty, "PriorityHigh");
            actionStatus.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeSmall");
            var button = TranscriptQuickReplyFactory.CreateButton(
                label,
                _transcriptFontSize,
                toolTip: ToolTipHelper.MakeThemedToolTip(hint),
                tone: tone);
            button.Click += async (_, _) =>
            {
                actionStatus.Visibility = Visibility.Collapsed;
                cardTag.SetActionsEnabled(false);
                try
                {
                    var succeeded = await action();
                    if (!succeeded)
                    {
                        cardTag.SetActionsEnabled(true);
                        actionStatus.Text = _planActionIssues.TryGetValue(
                            plan.Group.GroupId,
                            out var planIssue)
                            ? planIssue
                            : "The action could not be completed. The plan remains stopped.";
                        actionStatus.Visibility = Visibility.Visible;
                        actionStatus.BringIntoView();
                    }
                    else if (removeAfterAction)
                        panel.Visibility = Visibility.Collapsed;
                }
                catch (PlanPreflightBlockedException blocked)
                {
                    ShowTranscriptPlanPreflightRecovery(
                        plan,
                        "run",
                        durablePlan?.Branch,
                        blocked,
                        panel,
                        CoordinatorThread.Document.Blocks,
                        retryOverride: action,
                        retryLabel: label);
                }
                catch (Exception ex)
                {
                    cardTag.SetActionsEnabled(true);
                    panel.Visibility = Visibility.Visible;
                    SquadDashTrace.Write("DecomposeRecovery", $"Transcript action failed: {ex}");
                    actionStatus.Text = $"Action failed: {ex.Message}";
                    actionStatus.Visibility = Visibility.Visible;
                    actionStatus.BringIntoView();
                }
            };
            panel.Children.Add(button);
            panel.Children.Add(actionStatus);
            return button;
        }
    }

    private async Task ShowRecoveryReassessmentWhenStaleAsync(
        string planId,
        string revision,
        string taskId,
        DateTimeOffset assessedAt,
        FrameworkElement assessmentPanel)
    {
        if (_currentWorkspace is null || _planStore is null) return;

        try
        {
            var snapshot = await CapturePlanRecoveryRepositorySnapshotAsync(
                _currentWorkspace.FolderPath);
            var latest = _planStore.Load(planId);
            var latestAssessment = latest?.InterruptionData?.RecoveryAssessment;
            if (latest is null ||
                !string.Equals(latest.Revision, revision, StringComparison.Ordinal) ||
                !string.Equals(latest.InterruptionData?.InterruptedTaskId, taskId, StringComparison.Ordinal) ||
                latestAssessment is null ||
                latestAssessment.AssessedAt != assessedAt ||
                PlanRecoveryAssessmentSnapshotPolicy.IsCurrent(latestAssessment, snapshot))
                return;

            await Dispatcher.InvokeAsync(() =>
            {
                if (assessmentPanel.IsLoaded || assessmentPanel.Parent is not null)
                    assessmentPanel.Visibility = Visibility.Visible;
            });
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                TraceCategory.General,
                $"Could not determine whether plan recovery assessment is stale for plan={planId} task={taskId}: {ex.Message}");
        }
    }

    private void AppendCompletedWorkReviewDetails(
        BlockCollection blocks,
        CompletedWorkReviewPresentation review,
        string planId,
        string planRevision)
    {
        if (review.Commit is not null)
        {
            var evidenceParagraph = CreateTranscriptParagraph(bottomMargin: 4);
            var commitLink = new Hyperlink(new Run(review.Commit.ShortSha))
            {
                Cursor = Cursors.Hand,
                ToolTip = ToolTipHelper.MakeThemedToolTip("Open the complete commit review"),
            };
            commitLink.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
            commitLink.Click += (_, _) => _ = OpenInterruptedTaskReviewAsync(planId, planRevision);
            evidenceParagraph.Inlines.Add(commitLink);
            if (!string.IsNullOrWhiteSpace(review.TestSummary))
            {
                var separator = new Run(" · ");
                separator.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
                evidenceParagraph.Inlines.Add(separator);
                var verification = new Run(review.TestSummary);
                verification.SetResourceReference(TextElement.ForegroundProperty, "BodyText");
                evidenceParagraph.Inlines.Add(verification);
            }
            blocks.Add(evidenceParagraph);
        }

        if (review.ChangedFiles.Count > 0)
        {
            var filesParagraph = CreateTranscriptParagraph(bottomMargin: 3);
            filesParagraph.Margin = new Thickness(0, 7, 0, 3);
            var filesLink = new Hyperlink(new Run($"Changed files ({review.ChangedFiles.Count})"))
            {
                Cursor = Cursors.Hand,
                ToolTip = ToolTipHelper.MakeThemedToolTip("Open the changed files in the commit review"),
            };
            filesLink.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
            filesLink.Click += (_, _) => _ = OpenInterruptedTaskReviewAsync(planId, planRevision);
            filesParagraph.Inlines.Add(filesLink);
            blocks.Add(filesParagraph);
        }
    }

    private void AddRecoveryCommitLinkedText(InlineCollection inlines, string text)
    {
        foreach (var segment in CommitReferenceText.Parse(text))
        {
            if (segment.FullSha is null)
            {
                MarkdownFlowDocumentBuilder.AddInboxInlineText(inlines, segment.Text);
                continue;
            }

            var commitLink = new Hyperlink(new Run(segment.Text))
            {
                Cursor = Cursors.Hand,
                ToolTip = ToolTipHelper.MakeThemedToolTip("Open this commit in SquadDash"),
            };
            commitLink.SetResourceReference(TextElement.ForegroundProperty, "DocumentLinkText");
            var fullSha = segment.FullSha;
            commitLink.Click += async (_, _) => await OpenCommitWithRemoteCheckAsync(fullSha);
            inlines.Add(commitLink);
        }
    }

    private sealed record PendingPlanRecoveryAssessment(
        PendingDecomposePlan Plan,
        string TaskId,
        string AssessmentId,
        string BaselineCommit,
        string AssessedHead,
        string StatusSnapshot,
        string RepositoryFingerprint,
        IReadOnlyList<PlanRecoveryCommitReference> CommitReferences,
        bool AdvisoryOnly,
        int RepairAttempts = 0,
        int RepositoryChangeRetries = 0);

    private async Task<bool> AssessInterruptedPlanFromDurableAsync(Plan plan)
    {
        if (PlanExecutionBoundaryPolicy.SelectValidation(plan) is { } validation)
        {
            PrepareForHostRecoveryAction();
            ShowSystemTranscriptEntry(
                $"Resuming “{plan.Title}” at validation “{validation.Title}.” Completed implementation steps will not be repeated.");
            return await StartDecomposeLoopAsync(
                plan.PlanId,
                resumeFromIteration: plan.InterruptionData?.LoopIteration ?? 0,
                expectedRevision: plan.Revision);
        }

        var taskId = plan.InterruptionData?.InterruptedTaskId
            ?? plan.Progress.ExecutingTaskId
            ?? plan.Tasks.FirstOrDefault(task => task.Status != PlanTaskStatus.Complete)?.TaskId;
        if (string.IsNullOrWhiteSpace(taskId))
            throw new InvalidOperationException("SquadDash cannot identify the interrupted task to assess.");
        await AssessPlanRecoveryAsync(PendingDecomposePlanAdapter.FromPlan(plan), taskId);
        return true;
    }

    private async Task ContinueInterruptedPlanFromDurableAsync(Plan plan)
    {
        try
        {
            var durable = _planStore?.Load(plan.PlanId) ?? plan;
            if (PlanRecoveryResumePolicy.IsSafelyResumable(durable))
            {
                await StartOrResumeDurablePlanAsync(durable);
                return;
            }

            var taskId = durable.InterruptionData?.InterruptedTaskId
                ?? durable.Progress.ExecutingTaskId
                ?? durable.Tasks.FirstOrDefault(task => task.Status != PlanTaskStatus.Complete)?.TaskId;
            if (string.IsNullOrWhiteSpace(taskId))
            {
                OpenPlanFromStore(durable);
                return;
            }

            await RefreshRecoveryGitSnapshotAsync();
            var currentHead = ReadCachedRecoveryHeadCommit();
            var action = PlanRecoveryActionPresentationBuilder.Build(
                durable,
                taskId,
                currentHead,
                (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant));
            switch (action.Kind)
            {
                case PlanRecoveryPrimaryActionKind.AcceptStep:
                case PlanRecoveryPrimaryActionKind.AcceptUnattributedStep:
                case PlanRecoveryPrimaryActionKind.AcceptRejectedNoOp:
                case PlanRecoveryPrimaryActionKind.ApproveAmendment:
                    // Acceptance is a human decision. Open the evidence-bearing surface instead
                    // of silently accepting work from the Plans panel's compact resume control.
                    OpenPlanFromStore(durable);
                    return;
                case PlanRecoveryPrimaryActionKind.ResumeVerification:
                    PrepareForHostRecoveryAction();
                    await ResumeInterruptedTaskVerificationAsync(durable, taskId);
                    return;
                case PlanRecoveryPrimaryActionKind.RetryVerification:
                case PlanRecoveryPrimaryActionKind.ContinueWorking:
                    PrepareForHostRecoveryAction();
                    await RetryDecomposeTaskAsync(PendingDecomposePlanAdapter.FromPlan(durable), taskId);
                    return;
                default:
                    OpenPlanFromStore(durable);
                    return;
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException("Continue plan recovery", ex);
        }
    }

    private async Task AssessPlanRecoveryAsync(
        PendingDecomposePlan plan,
        string taskId,
        bool advisoryOnly = false)
    {
        if (_currentWorkspace is null || _planStore is null) return;
        if (IsPlanRecoveryActionBusy(plan.Group.GroupId))
            throw new InvalidOperationException(
                "Wait for the current prompt or loop to finish before assessing interrupted work.");
        if (_pendingPlanRecoveryAssessment is not null)
            throw new InvalidOperationException("A plan recovery assessment is already in progress.");

        var durable = _planStore.Load(plan.Group.GroupId);
        if (durable is null ||
            durable.LifecycleStatus is not (PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked) ||
            !string.Equals(durable.Revision, plan.Revision, StringComparison.Ordinal) ||
            !string.Equals(durable.InterruptionData?.InterruptedTaskId, taskId, StringComparison.Ordinal))
            throw new InvalidOperationException(
                "The interrupted plan changed after these recovery controls were created. Reopen the current plan state.");

        var workspace = _currentWorkspace.FolderPath;
        var activeBranch = ReadGitBranch(workspace);
        if (!string.Equals(activeBranch, durable.Branch, StringComparison.Ordinal))
            throw new InvalidOperationException(
                $"Plan {durable.PlanId} requires branch '{durable.Branch}', but '{activeBranch}' is active.");

        if (!advisoryOnly && PlanVerificationRecoveryPolicy.CanResume(durable, taskId))
        {
            try
            {
                await ResumeInterruptedTaskVerificationAsync(durable, taskId);
                return;
            }
            catch (Exception ex)
            {
                var latest = _planStore.Load(durable.PlanId);
                if (latest is null ||
                    latest.LifecycleStatus is not (PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked) ||
                    !string.Equals(latest.Revision, durable.Revision, StringComparison.Ordinal))
                    throw;

                SquadDashTrace.Write(
                    "Plan",
                    $"Could not reconstruct verification for plan={durable.PlanId} task={taskId}; " +
                    $"preserving the candidate without fallback: {ex.Message}");
                throw new InvalidOperationException(
                    "SquadDash could not safely restore independent verification for the saved candidate. " +
                    "The candidate remains preserved, and implementation work was not restarted or replaced. " +
                    "Reopen the current recovery card after resolving the reported verification-restoration problem.",
                    ex);
            }
        }

        var currentSnapshot = await CapturePlanRecoveryRepositorySnapshotAsync(workspace);
        if (advisoryOnly && PlanRecoveryAssessmentSnapshotPolicy.IsCurrent(
                                durable.InterruptionData?.RecoveryAssessment,
                                currentSnapshot))
        {
            ShowSystemTranscriptEntry(
                "The existing AI recovery assessment already matches the current repository. No new assessment was requested.");
            return;
        }

        await QueuePlanRecoveryAssessmentAsync(
            plan,
            durable,
            taskId,
            repositoryChangeRetries: 0,
            advisoryOnly);
    }

    private async Task ResumeInterruptedTaskVerificationAsync(Plan durable, string taskId)
    {
        if (_currentWorkspace is null)
            throw new InvalidOperationException("No workspace is active.");

        var workspace = _currentWorkspace.FolderPath;
        var task = durable.Tasks.Single(candidate =>
            string.Equals(candidate.TaskId, taskId, StringComparison.Ordinal));
        var handoff = task.Handoff
            ?? throw new InvalidOperationException(
                $"Task {taskId} no longer has the candidate handoff required for verification.");
        var baseline = await ResolvePlanRecoveryBaselineAsync(workspace, durable, taskId);
        var handoffTarget = string.Equals(
            handoff.CompletionKind,
            DecomposeStepCompletionKind.VerifiedNoOp,
            StringComparison.Ordinal)
            ? handoff.EvaluatedCommit
            : handoff.Commit;
        if (string.IsNullOrWhiteSpace(handoffTarget))
            throw new InvalidOperationException($"Task {taskId} has no saved evaluated snapshot for verification.");
        var candidateCommit = (await RunGitAsync(
            workspace, $"rev-parse --verify \"{handoffTarget}^{{commit}}\"")).Trim();
        var head = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
        if (string.Equals(
                handoff.CompletionKind,
                DecomposeStepCompletionKind.VerifiedNoOp,
                StringComparison.Ordinal) &&
            !string.Equals(candidateCommit, head, StringComparison.OrdinalIgnoreCase))
            throw new InvalidOperationException(
                "The saved verified-no-op candidate no longer matches the current repository HEAD.");
        await RunGitAsync(workspace, $"merge-base --is-ancestor \"{baseline}\" \"{candidateCommit}\"");
        await RunGitAsync(workspace, $"merge-base --is-ancestor \"{candidateCommit}\" \"{head}\"");
        if (!PlanVerificationRecoveryPolicy.TryCreateCandidate(
                durable, taskId, candidateCommit, out var candidate, out var candidateError) ||
            candidate is null)
            throw new InvalidOperationException(candidateError ??
                "SquadDash could not reconstruct the saved candidate for verification.");

        var changedFiles = (handoff.ChangedFiles ?? [])
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Select(path => path.Trim())
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
        var pending = new PendingTaskVerification(
            durable.PlanId,
            taskId,
            durable.Revision,
            JsonSerializer.Serialize(candidate),
            baseline,
            changedFiles,
            handoff.SubmittedAt);
        var previousExecution = _conversationManager.ConversationState.ActiveLoopExecution;
        var loopPath = Path.Combine(_currentWorkspace.SquadFolderPath, "loop-executing-plan.md");
        var recoveryExecution = new ActiveLoopExecutionState(
            loopPath,
            durable.PlanId,
            durable.PlanId,
            durable.Revision,
            PreviousPlanExecutionAttempts: previousExecution?.PreviousPlanExecutionAttempts,
            LastCompletedIteration: durable.InterruptionData?.LoopIteration ?? 0,
            TaskBaselineCommit: baseline,
            PendingTaskVerification: pending,
            ActiveVerificationTaskId: taskId);
        _conversationManager.UpdateActiveLoopExecutionState(recoveryExecution);

        var shortCommit = candidateCommit[..Math.Min(7, candidateCommit.Length)];
        ShowSystemTranscriptEntry(
            $"Found the completed candidate for {taskId} at {shortCommit}; its recorded build passed. " +
            "SquadDash is resuming independent verification without repeating implementation work.");
        if (!await StartDecomposeLoopAsync(
                durable.PlanId,
                resumeFromIteration: durable.InterruptionData?.LoopIteration ?? 0,
                expectedRevision: durable.Revision))
        {
            _conversationManager.UpdateActiveLoopExecutionState(previousExecution);
            throw new InvalidOperationException(
                $"SquadDash could not resume independent verification for {taskId}.");
        }
    }

    private async Task<string> ResolvePlanRecoveryBaselineAsync(
        string workspace,
        Plan durable,
        string? taskId = null)
    {
        var baselineCandidate = durable.InterruptionData?.TaskCommitEvidence?.BaselineCommit
            ?? durable.InterruptionData?.LastCommit;
        if (string.IsNullOrWhiteSpace(baselineCandidate) &&
            !string.IsNullOrWhiteSpace(taskId) &&
            PlanVerificationRecoveryPolicy.TryGetAtomicCandidateCommit(
                durable,
                taskId,
                out var atomicCandidateCommit))
        {
            var resolvedCandidate = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"{atomicCandidateCommit}^{{commit}}\"")).Trim();
            var head = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
            await RunGitAsync(
                workspace,
                $"merge-base --is-ancestor \"{resolvedCandidate}\" \"{head}\"");
            baselineCandidate = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"{resolvedCandidate}^\"")).Trim();
            SquadDashTrace.Write(
                "PlanRecovery",
                $"Recovered task baseline from host-validated atomic candidate plan={durable.PlanId} task={taskId} candidate={resolvedCandidate} baseline={baselineCandidate}.");
        }
        if (string.IsNullOrWhiteSpace(baselineCandidate))
        {
            var history = (await RunGitAsync(workspace, "rev-list HEAD"))
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            baselineCandidate = RecoveryCommitValidator.FindNewestRecordedCommit(
                history,
                durable.Tasks
                    .Where(task => task.Status == PlanTaskStatus.Complete)
                    .Select(task => task.Commit));
        }
        if (string.IsNullOrWhiteSpace(baselineCandidate))
            throw new InvalidOperationException(
                "SquadDash does not have a reliable commit from before this task began. Replan the remaining work instead of guessing.");

        return (await RunGitAsync(
            workspace, $"rev-parse --verify \"{baselineCandidate}^{{commit}}\"")).Trim();
    }

    private async Task QueuePlanRecoveryAssessmentAsync(
        PendingDecomposePlan plan,
        Plan durable,
        string taskId,
        int repositoryChangeRetries,
        bool advisoryOnly = false)
    {
        if (_currentWorkspace is null) return;

        var workspace = _currentWorkspace.FolderPath;
        var baseline = await ResolvePlanRecoveryBaselineAsync(workspace, durable, taskId);
        var snapshot = await CapturePlanRecoveryRepositorySnapshotAsync(workspace);
        var head = snapshot.HeadCommit;
        await RunGitAsync(workspace, $"merge-base --is-ancestor \"{baseline}\" \"{head}\"");
        var assessmentId = Guid.NewGuid().ToString("N");
        var actualCommits = (await RunGitAsync(
                workspace, $"rev-list --reverse \"{baseline}..{head}\""))
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        var commitReferences = PlanRecoveryAssessmentValidator.CreateCommitReferences(actualCommits);
        var evidence = await GatherPlanRecoveryEvidenceAsync(
            workspace, durable.PlanId, taskId, baseline, plan, commitReferences);
        var prompt = BuildPlanRecoveryAssessmentPrompt(
            durable, taskId, assessmentId, evidence, advisoryOnly);

        _pendingPlanRecoveryAssessment = new PendingPlanRecoveryAssessment(
            plan, taskId, assessmentId, baseline, head, snapshot.StatusSnapshot, snapshot.Fingerprint, commitReferences,
            AdvisoryOnly: advisoryOnly,
            RepositoryChangeRetries: repositoryChangeRetries);
        _broker.Publish(new PlanRecoveryAssessmentActivityEvent(durable.PlanId, taskId, IsActive: true));
        _promptQueue.EnqueueAtFront(
            prompt,
            _promptQueueCoordinator.NextSequenceNumber(),
            sourceTag: PlanRecoveryAssessmentQueueTag,
            isSystemInjected: true);
        SyncQueuePanel();
        SyncSendButton();
        if (repositoryChangeRetries == 0)
            ShowSystemTranscriptEntry(
                advisoryOnly
                    ? $"Requesting a quick AI assessment of the current work for “{durable.Title}.” The plan remains stopped and no repository changes will be made."
                    : $"Assessing the current work for “{durable.Title}” before continuing. The plan remains stopped until the evidence is validated.");
        _ = DrainQueueIfNeededAsync();
    }

    private void PrepareForHostRecoveryAction()
    {
        if (_lastQuickReplyEntry?.AllowQuickReplies == true)
            _pec.DisableQuickReplies(_lastQuickReplyEntry);
        ClearActiveQuickReplyState();
        // Recovery assessment payloads contain an in-memory assessment identity and
        // cannot be replayed after an interruption or restart. Gather fresh evidence
        // after removing stale payloads only when no live assessment owns them.
        DiscardObsoletePlanQueueItems(
            "host-recovery-action",
            includeRecoveryAssessments: _pendingPlanRecoveryAssessment is null);
        // Do not clear a user pause here. A matching system recovery hold is released only
        // after branch/worktree preflight succeeds and the plan actually starts (or the
        // preserved step is durably accepted).
        ResetQueuePausedState();
        _loopFollowUpTcs?.TrySetResult(true);
    }

    private static string BuildPlanRecoveryAssessmentPrompt(
        Plan plan,
        string taskId,
        string assessmentId,
        string evidence,
        bool advisoryOnly = false)
    {
        var task = plan.Tasks.FirstOrDefault(candidate =>
            string.Equals(candidate.TaskId, taskId, StringComparison.Ordinal));
        var latestVerification = task?.VerificationHistory?.LastOrDefault();
        var unresolvedVerification = latestVerification is not null &&
                                 !string.Equals(
                                     latestVerification.Verdict,
                                     PlanTaskVerificationVerdict.Accepted,
                                     StringComparison.Ordinal)
            ? latestVerification
            : null;
        var verificationContext = unresolvedVerification is null
            ? string.Empty
            : $$"""

                Independent verification is unresolved and remains authoritative until corrected or accepted by a human:
                - Verdict: {{unresolvedVerification.Verdict}}
                - Summary: {{unresolvedVerification.Summary}}
                - Missing or overstated work: {{string.Join("; ", unresolvedVerification.MissingOrOverstatedWork)}}
                - Test assessment: {{unresolvedVerification.TestAssessment}}
                A recovery assessment must not classify this task complete while that verdict is unresolved. Use partial
                with bounded remaining work when the discrepancy is correctable, or inconclusive when it requires human judgment.
                """;
        var manualCorrections = task?.ReviewActivity?
            .Where(activity => activity.Kind == PlanReviewActivityKind.ManualCorrection)
            .OrderBy(activity => activity.RecordedAt)
            .ToArray() ?? [];
        var manualCorrectionContext = manualCorrections.Length == 0
            ? string.Empty
            : $$"""

                The user performed conversational corrections while this plan remained paused:
                {{string.Join("\n", manualCorrections.Select(activity =>
                    $"- {activity.RecordedAt:O}: {activity.Summary}"))}}
                These entries identify work that must be inspected; they are not proof of completion. Compare the
                repository changes with the current task specification and include them in the assessment.
                """;
        var assessmentScope = advisoryOnly
            ? """
              This is a quick recommendation for a human decision, not a full code review. Prioritize the task's
              observable outcome, expected files, and likely implementation commits; stop once there is enough
              evidence for a concise recommendation. Run at most one focused, non-mutating verification command when
              it materially improves confidence.
              """
            : """
              This assessment belongs to an automatic recovery path. Gather enough evidence for the host to apply its
              existing validated continuation policy without introducing a human checkpoint unnecessarily.
              """;
        return $$"""
            Perform a read-only recovery assessment for interrupted plan {{plan.PlanId}}, task {{taskId}}.
            {{assessmentScope}}
            Answer this user question directly: Does the current source satisfy every requirement of
            {{PlanRecoveryPresentationBuilder.FormatStepLabel(task?.DisplayStepLabel, task?.Title ?? taskId)}}
            ({{task?.Title ?? taskId}})? The summary must begin with a plain-language answer the user can understand,
            then cite the most important source-code and verification evidence. If the answer is partial, name the
            exact unmet requirements in remainingWork. If it is inconclusive, say exactly what evidence is missing.
            Do not edit files, create commits, revert work, or start the task. Do not build SquadDash itself because
            this live application treats a self-build as a restart request. Determine whether the task
            is complete, partially complete, not started, or inconclusive. Classify every commit in the supplied baseline-to-HEAD range as task, mixed,
            unrelated, unknown, or superseded. A mixed commit contains both task and unrelated work. Superseded means
            the commit implements an older task specification that the current plan revision replaced; it does not
            count as work satisfying the current task revision. Do not infer ownership from
            time, author, or commit position alone; compare actual changes with the task specification.

            Host-bound identity (copy exactly). This nonce is the only host identity the response must echo:
            - recoveryAssessmentId: {{assessmentId}}

            {{verificationContext}}

            {{manualCorrectionContext}}

            {{evidence}}

            Return exactly one {{PlanRecoveryAssessmentParser.Marker}} payload with this shape:
            {
              "recoveryAssessmentId": "{{assessmentId}}",
              "classification": "complete|partial|not_started|inconclusive",
              "completionKind": "changed|verified-no-op (complete only)",
              "evaluatedCommit": "exact assessed HEAD (verified-no-op only)",
              "summary": "brief evidence-based explanation",
              "remainingWork": ["required only for partial"],
              "noOpEvidence": [
                { "requirement": "exact task requirement", "observation": "existing behavior that satisfies it", "locations": ["repository/path:member-or-line"] }
              ],
              "verification": { "status": "passed|failed|not_run", "command": "...", "summary": "..." },
              "commits": [
                { "commitId": "c001", "relation": "task|mixed|unrelated|unknown|superseded", "reason": "required unless unrelated" }
              ],
              "supportingCommits": [
                { "commit": "short unambiguous Git ID", "relation": "task|mixed|unknown|superseded", "reason": "why older evidence is relevant" }
              ]
            }

            A changed completion requires passed verification and at least one task or mixed commit. If every task
            requirement is already satisfied at the exact assessed HEAD without attributing a commit to this task, use
            `classification: "complete"`, `completionKind: "verified-no-op"`, set `evaluatedCommit` to the exact assessed
            HEAD, and provide non-empty requirement-scoped `noOpEvidence`. Do not manufacture an empty commit or use no-op
            to excuse missing work. Classify every intervening commit, but do not attribute concurrent commits to this task.
            SquadDash will independently validate the current snapshot before any acceptance.
            Use inconclusive whenever the
            evidence cannot safely distinguish task work from unrelated work. Not_started requires no task or mixed
            commits against the current revision; use superseded for replaced older-spec work. Do not include recovery choices or execute
            a recovery action; SquadDash owns that decision.
            Candidate SHAs are input-only. If repository inspection is useful, use the full SHA paired with a commitId
            in a read-only Git command, but return only that commitId in commits. Include every listed cNNN ID exactly once.
            To keep the response compact, omit reason for commits classified unrelated. Explain task, mixed, unknown,
            and superseded classifications.
            When relevant implementation commits predate the captured baseline, include them chronologically in
            supportingCommits and explain why each is included. Use relation unknown when attribution is uncertain.
            """;
    }

    private void TryApplyPlanRecoveryAssessmentFromResponse(string? rawResponse)
    {
        if (_pendingPlanRecoveryAssessment is null) return;
        var context = _pendingPlanRecoveryAssessment;

        var parsed = PlanRecoveryAssessmentParser.TryParse(
            rawResponse, out var response, out var error);
        if ((!parsed || response is null) &&
            context.RepairAttempts > 0 &&
            PlanRecoveryAssessmentFallbackPolicy.TryDowngradeUnverifiedComplete(
                response, error, out var downgraded) &&
            downgraded is not null)
        {
            response = downgraded;
            parsed = true;
            ShowSystemTranscriptEntry(
                "The corrected assessment found implementation evidence but did not provide passed verification. " +
                "SquadDash preserved the findings for review instead of discarding the assessment or accepting the task.");
        }

        if (!parsed || response is null)
        {
            if (TryQueuePlanRecoveryAssessmentRepair(context, error, rawResponse))
                return;

            _pendingPlanRecoveryAssessment = null;
            _broker.Publish(new PlanRecoveryAssessmentActivityEvent(
                context.Plan.Group.GroupId, context.TaskId, IsActive: false));
            var validationReport = PlanRecoveryAssessmentErrorReport.Build(
                context.Plan.Group.GroupId,
                context.TaskId,
                context.AssessmentId,
                error,
                "Corrected assessment response");
            var validationReportTarget = PlanRecoveryAssessmentErrorReport.CreateLinkTarget(
                validationReport);
            KeepPlanStoppedAfterAssessment(
                context,
                "SquadDash could not validate the recovery assessment after one automatic repair. " +
                error + $" [Review validation details]({validationReportTarget}).");
            return;
        }

        _pendingPlanRecoveryAssessment = null;
        _planRecoveryAssessmentApplying = true;
        Dispatcher.BeginInvoke(new Action(async () =>
        {
            try { await ValidateAndApplyPlanRecoveryAssessmentAsync(response, context); }
            catch (Exception ex)
            {
                SquadDashTrace.Write("Plan", $"Plan recovery assessment validation failed safely: {ex}");
                KeepPlanStoppedAfterAssessment(
                    context,
                    "SquadDash could not safely validate the recovery assessment. " + ex.Message);
            }
            finally
            {
                _planRecoveryAssessmentApplying = false;
                // A repository-change retry installs a fresh pending assessment before this
                // attempt finishes. Keep the shared upper-right coordinator indicator alive
                // across that handoff; otherwise remove it only after validation/application.
                if (_pendingPlanRecoveryAssessment is null)
                {
                    _broker.Publish(new PlanRecoveryAssessmentActivityEvent(
                        context.Plan.Group.GroupId, context.TaskId, IsActive: false));
                }
                else
                {
                    // A structured-data repair queued during host validation must start before
                    // a deferred build restart is released, just like a parser-level repair.
                    _ = DrainQueueIfNeededAsync();
                }
                TryCompletePendingRestart(
                    "plan-recovery-assessment-finished",
                    emergencySaveBeforeClose: true);
            }
        }), System.Windows.Threading.DispatcherPriority.Background);
    }

    private bool TryQueuePlanRecoveryAssessmentRepair(
        PendingPlanRecoveryAssessment context,
        string? error,
        string? invalidResponse,
        IReadOnlyList<PlanRecoveryCommitReference>? expectedCommits = null)
    {
        if (context.RepairAttempts != 0)
            return false;

        _pendingPlanRecoveryAssessment = context with { RepairAttempts = 1 };
        _promptQueue.EnqueueAtFront(
            BuildPlanRecoveryAssessmentRepairPrompt(
                context,
                error,
                invalidResponse,
                expectedCommits ?? context.CommitReferences),
            _promptQueueCoordinator.NextSequenceNumber(),
            sourceTag: PlanRecoveryAssessmentQueueTag,
            isSystemInjected: true);
        SyncQueuePanel();
        SyncSendButton();
        var validationReport = PlanRecoveryAssessmentErrorReport.Build(
            context.Plan.Group.GroupId,
            context.TaskId,
            context.AssessmentId,
            error);
        var validationReportTarget = PlanRecoveryAssessmentErrorReport.CreateLinkTarget(validationReport);
        ShowSystemTranscriptEntry(
            $"The recovery assessment data was [invalid]({validationReportTarget}). SquadDash is asking AI once for a corrected response; the plan remains stopped while it is checked.");
        _ = Dispatcher.BeginInvoke(
            new Action(() => _ = DrainQueueIfNeededAsync()),
            System.Windows.Threading.DispatcherPriority.ContextIdle);
        return true;
    }

    private void RepairOrStopInvalidPlanRecoveryAssessment(
        PendingPlanRecoveryAssessment context,
        PlanRecoveryAssessmentResponse response,
        string error,
        IReadOnlyList<PlanRecoveryCommitReference>? expectedCommits = null)
    {
        var invalidResponse = PlanRecoveryAssessmentParser.Marker + "\n" +
                              JsonSerializer.Serialize(response);
        if (TryQueuePlanRecoveryAssessmentRepair(
                context,
                error,
                invalidResponse,
                expectedCommits))
        {
            return;
        }

        var validationReport = PlanRecoveryAssessmentErrorReport.Build(
            context.Plan.Group.GroupId,
            context.TaskId,
            context.AssessmentId,
            error,
            "Corrected assessment response");
        var validationReportTarget = PlanRecoveryAssessmentErrorReport.CreateLinkTarget(
            validationReport);
        KeepPlanStoppedAfterAssessment(
            context,
            "SquadDash could not validate the recovery assessment after one automatic repair. " +
            error + $" [Review validation details]({validationReportTarget}).");
    }

    private static string BuildPlanRecoveryAssessmentRepairPrompt(
        PendingPlanRecoveryAssessment context,
        string? error,
        string? invalidResponse,
        IReadOnlyList<PlanRecoveryCommitReference>? expectedCommits = null)
    {
        var response = invalidResponse ?? string.Empty;
        if (response.Length > 16000) response = response[^16000..];
        var expectedCommitInstructions = expectedCommits is { Count: > 0 }
            ? $$"""

                The commits array must contain each of these captured baseline-to-HEAD commits exactly once, using
                the short commitId shown here and no other commitId:
                {{string.Join("\n", expectedCommits.Select(reference => "- " + reference.Id))}}
                """
            : string.Empty;
        return $$"""
            Your previous recovery assessment was invalid: {{error ?? "invalid structured response"}}.
            Make no repository changes and do not repeat the assessment. Return only one corrected
            {{PlanRecoveryAssessmentParser.Marker}} JSON object using the evidence and conclusions already obtained.
            Copy this single host identity exactly:
            - recoveryAssessmentId: {{context.AssessmentId}}
            Use classification complete, partial, not_started, or inconclusive. Include summary, remainingWork (an
            empty array unless partial), verification, and a commits array classifying every commitId as task, mixed,
            unrelated, unknown, or superseded. Not_started must not mark any commit task or mixed; use superseded when
            an older implementation was replaced by the current plan revision. Output strict JSON with double-quoted
            property names and no prose after the object. Do not return planId, taskId, revision, baselineCommit,
            assessedHead, or a SHA for any captured commit. Omit reason for unrelated commits; include it for every
            other relation. Complete requires verification.status passed. A complete result with no task or mixed commit
            is valid only as `completionKind: "verified-no-op"`; it must preserve the exact assessed HEAD in
            `evaluatedCommit` and include non-empty requirement-scoped `noOpEvidence` from the completed inspection.
            If the available evidence does not support
            passed verification, use inconclusive instead of complete and preserve the implementation findings in summary.
            {{expectedCommitInstructions}}

            Previous response:
            {{response}}
            """;
    }

    private async Task ValidateAndApplyPlanRecoveryAssessmentAsync(
        PlanRecoveryAssessmentResponse response,
        PendingPlanRecoveryAssessment context)
    {
        if (_currentWorkspace is null || _planStore is null) return;
        var planId = context.Plan.Group.GroupId;
        if (!PlanRecoveryAssessmentValidator.MatchesRequest(
                response,
                context.AssessmentId))
        {
            RepairOrStopInvalidPlanRecoveryAssessment(
                context,
                response,
                "The AI response did not match the recovery assessment identity requested.");
            return;
        }

        var durable = _planStore.Load(planId);
        if (durable is null ||
            durable.LifecycleStatus is not (PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked) ||
            !string.Equals(durable.Revision, context.Plan.Revision, StringComparison.Ordinal) ||
            !string.Equals(durable.InterruptionData?.InterruptedTaskId, context.TaskId, StringComparison.Ordinal))
        {
            KeepPlanStoppedAfterAssessment(context, "The plan changed while AI was assessing it.");
            return;
        }
        if (!PlanRecoveryAssessmentValidator.TryValidateAgainstPlanEvidence(
                durable, context.TaskId, response, out var planEvidenceError))
        {
            RepairOrStopInvalidPlanRecoveryAssessment(context, response, planEvidenceError!);
            return;
        }

        var workspace = _currentWorkspace.FolderPath;
        var currentSnapshot = await CapturePlanRecoveryRepositorySnapshotAsync(workspace);
        var currentHead = currentSnapshot.HeadCommit;
        var currentStatus = currentSnapshot.StatusSnapshot;
        if (!string.Equals(currentHead, context.AssessedHead, StringComparison.OrdinalIgnoreCase) ||
            !string.Equals(currentSnapshot.StatusSnapshot, context.StatusSnapshot, StringComparison.Ordinal) ||
            !string.Equals(
                currentSnapshot.Fingerprint,
                context.RepositoryFingerprint,
                StringComparison.OrdinalIgnoreCase))
        {
            if (!context.AdvisoryOnly &&
                PlanRecoveryAssessmentRetryPolicy.CanRetryRepositoryChange(context.RepositoryChangeRetries))
            {
                SquadDashTrace.Write(
                    TraceCategory.General,
                    $"Plan recovery assessment snapshot changed for plan={planId} task={context.TaskId}; " +
                    $"oldHead={context.AssessedHead} newHead={currentHead}. Reassessing once.");
                ShowSystemTranscriptEntry(
                    "The repository changed during recovery assessment. SquadDash is rechecking once against the latest version; the plan remains stopped until that result is validated.");
                try
                {
                    await QueuePlanRecoveryAssessmentAsync(
                        PendingDecomposePlanAdapter.FromPlan(durable),
                        durable,
                        context.TaskId,
                        context.RepositoryChangeRetries + 1,
                        context.AdvisoryOnly);
                }
                catch (Exception ex)
                {
                    KeepPlanStoppedAfterAssessment(
                        context,
                        "SquadDash could not start the automatic reassessment. " + ex.Message);
                }
                return;
            }

            KeepPlanStoppedAfterAssessment(
                context,
                context.AdvisoryOnly
                    ? "The repository changed while AI was assessing it. Use Reassess with AI when you want a recommendation for the new state."
                    : "The repository changed again while evidence was being checked. Reopen the current recovery card after repository activity has settled.");
            return;
        }

        await RunGitAsync(
            workspace,
            $"merge-base --is-ancestor \"{context.BaselineCommit}\" \"{context.AssessedHead}\"");
        var actualCommits = (await RunGitAsync(
                workspace,
                $"rev-list --reverse \"{context.BaselineCommit}..{context.AssessedHead}\""))
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (!actualCommits.SequenceEqual(
                context.CommitReferences.Select(reference => reference.Commit),
                StringComparer.OrdinalIgnoreCase))
        {
            KeepPlanStoppedAfterAssessment(
                context,
                "The captured commit-ID mapping no longer matches the repository range. Reopen the current recovery card to choose how to continue.");
            return;
        }
        if (response.IsVerifiedNoOp)
        {
            if (!RecoveryCommitValidator.CommitIdentifiersMatch(
                    response.EvaluatedCommit,
                    context.AssessedHead))
            {
                RepairOrStopInvalidPlanRecoveryAssessment(
                    context,
                    response,
                    "A verified-no-op assessment must identify the current inspected HEAD in evaluatedCommit.",
                    context.CommitReferences);
                return;
            }

            var tasksRelativePath = await GetTasksRepositoryRelativePathAsync(workspace);
            var allowed = tasksRelativePath is null ? Array.Empty<string>() : new[] { tasksRelativePath };
            DecomposeWorktreePolicy.HasOnlyAllowedChanges(currentStatus, allowed, out var nonHostPaths);
            if (nonHostPaths.Count > 0)
            {
                KeepPlanStoppedAfterAssessment(
                    context,
                    "The no-op assessment cannot be accepted because the task has uncommitted repository changes.");
                return;
            }
        }
        if (!PlanRecoveryAssessmentValidator.TryValidateCommitCoverage(
                response, context.CommitReferences, out var attributed, out var coverageError))
        {
            RepairOrStopInvalidPlanRecoveryAssessment(
                context,
                response,
                coverageError!,
                context.CommitReferences);
            return;
        }

        var actualCommitById = context.CommitReferences.ToDictionary(
            reference => reference.Id,
            reference => reference.Commit,
            StringComparer.OrdinalIgnoreCase);
        var normalizedCommits = response.Commits
            .Select(assessment => new PlanEvidenceCommit(
                actualCommitById[assessment.CommitId],
                assessment.Relation,
                assessment.Reason))
            .ToArray();
        var normalizedSupporting = new List<PlanEvidenceCommit>();
        foreach (var assessment in response.SupportingCommits ?? [])
        {
            if (!PlanRecoveryAssessmentValidator.IsSafeGitCommitIdentifier(assessment.Commit))
            {
                RepairOrStopInvalidPlanRecoveryAssessment(
                    context,
                    response,
                    $"Supporting commit '{assessment.Commit}' is not a valid Git commit identifier.",
                    context.CommitReferences);
                return;
            }

            string resolved;
            try
            {
                resolved = (await RunGitAsync(
                    workspace, $"rev-parse --verify \"{assessment.Commit}^{{commit}}\"")).Trim();
            }
            catch (Exception)
            {
                RepairOrStopInvalidPlanRecoveryAssessment(
                    context,
                    response,
                    $"Supporting commit '{assessment.Commit}' does not resolve to a commit in this repository.",
                    context.CommitReferences);
                return;
            }
            normalizedSupporting.Add(new PlanEvidenceCommit(
                resolved,
                assessment.Relation,
                assessment.Reason));
        }

        if (PlanRecoveryAssessmentContinuationPolicy.MayContinueAutomatically(
                context.AdvisoryOnly,
                response.Classification))
        {
            switch (response.Classification)
            {
                case PlanRecoveryClassification.Complete:
                {
                    var tasksRelativePath = await GetTasksRepositoryRelativePathAsync(workspace);
                    var allowed = tasksRelativePath is null ? Array.Empty<string>() : new[] { tasksRelativePath };
                    DecomposeWorktreePolicy.HasOnlyAllowedChanges(currentStatus, allowed, out var nonHostPaths);
                    if (nonHostPaths.Count > 0)
                    {
                        KeepPlanStoppedAfterAssessment(
                            context,
                            "AI found completed work, but uncommitted repository changes prevent safe acceptance. Commit or stash them, then assess again.");
                        return;
                    }

                    await AcceptAssessedPlanRecoveryAsync(
                        durable,
                        context,
                        response,
                        response.IsVerifiedNoOp ? context.AssessedHead : attributed[^1],
                        requiredRepositorySnapshot: currentSnapshot);
                    return;
                }
                case PlanRecoveryClassification.Partial:
                {
                    var assessedContinuation = new AssessedRecoveryContinuationState(
                        planId, context.TaskId, response.Summary, response.RemainingWork!);
                    ShowSystemTranscriptEntry(
                        $"AI found partial work for {context.TaskId}. SquadDash preserved the assessment and is resuming only the remaining work.");
                    await RetryDecomposeTaskAsync(
                        context.Plan,
                        context.TaskId,
                        assessedContinuation,
                        allowUncommittedPreservedWork: true,
                        requiredPreservedSnapshot: currentSnapshot);
                    return;
                }
                case PlanRecoveryClassification.NotStarted:
                    ShowSystemTranscriptEntry(
                        $"AI found no work for {context.TaskId}. SquadDash is starting the task normally.");
                    await RetryDecomposeTaskAsync(
                        context.Plan,
                        context.TaskId,
                        requiredPreservedSnapshot: currentSnapshot);
                    return;
            }
        }

        var evidenceCommits = normalizedSupporting
            .Concat(normalizedCommits)
            .GroupBy(commit => commit.Commit, StringComparer.OrdinalIgnoreCase)
            .Select(group => group.First())
            .ToArray();
        var decisionEvidence = new PlanRecoveryDecisionEvidence(
            response.Summary,
            evidenceCommits,
            DateTimeOffset.UtcNow,
            response.Classification,
            response.Verification,
            response.RemainingWork,
            context.AssessedHead,
            context.RepositoryFingerprint,
            response.CompletionKind,
            response.EvaluatedCommit,
            response.NoOpEvidence);
        var interruption = durable.InterruptionData ?? new PlanInterruptionData(
            "Plan execution stopped before the task result was recorded.",
            "pending-recovery",
            0,
            context.TaskId);
        var assessedPlan = durable with
        {
            LifecycleStatus = PlanLifecycleStatus.Interrupted,
            InterruptionData = interruption with
            {
                RecoveryState = "assessment-ready",
                RecoveryAssessment = decisionEvidence,
            },
        };
        _planStore.Save(assessedPlan);
        _broker.Publish(new PlanProgressEvent(assessedPlan.PlanId, assessedPlan));
        LoadTasksPanel();

        var task = assessedPlan.Tasks.FirstOrDefault(candidate =>
            string.Equals(candidate.TaskId, context.TaskId, StringComparison.Ordinal));
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            task?.DisplayStepLabel,
            task?.Title ?? context.TaskId);
        var assessmentPresentation = PlanRecoveryAssessmentCardPresentationBuilder.Build(
            decisionEvidence,
            stepLabel);
        ShowSystemTranscriptEntry(
            $"AI assessment complete — {assessmentPresentation.Finding} The plan is still stopped for your decision.");
        TranscriptQuickReplyFactory.RemoveDecomposeRecoveryContainers(
            CoordinatorThread.Document.Blocks);
        AppendDecomposeRecoveryActions(context.Plan, context.TaskId);
    }

    private async Task AcceptAssessedPlanRecoveryAsync(
        Plan durable,
        PendingPlanRecoveryAssessment context,
        PlanRecoveryAssessmentResponse response,
        string terminalCommit,
        string summaryPrefix = "AI-assessed recovery: ",
        PlanRecoveryRepositorySnapshot? requiredRepositorySnapshot = null)
    {
        if (_currentWorkspace is null || _planStore is null) return;
        var workspace = _currentWorkspace.FolderPath;
        if (requiredRepositorySnapshot is not null)
        {
            var currentSnapshot = await CapturePlanRecoveryRepositorySnapshotAsync(workspace);
            if (!PlanRecoveryAssessmentSnapshotPolicy.Matches(
                    requiredRepositorySnapshot,
                    currentSnapshot))
            {
                throw new InvalidOperationException(
                    "The repository changed after recovery was assessed. SquadDash left the plan stopped so new work is not accepted without review.");
            }
        }

        var activeBranch = ReadGitBranch(workspace);
        if (!string.Equals(activeBranch, durable.Branch, StringComparison.Ordinal))
            throw new InvalidOperationException(
                $"Plan {durable.PlanId} requires branch '{durable.Branch}', but '{activeBranch}' is active.");

        var shortCommit = terminalCommit[..Math.Min(7, terminalCommit.Length)];
        var summary = summaryPrefix + response.Summary;
        var currentGroup = PendingDecomposePlanAdapter.FromPlan(durable).Group with
        {
            HostRevision = durable.Revision,
        };
        Plan updated;
        try
        {
            if (!TryValidateDecomposeGroupForExecution(currentGroup, out var startValidationError))
                throw new InvalidDataException(startValidationError);

            var syntheticResult = new DecomposeStepResult(
                durable.PlanId,
                context.TaskId,
                durable.Revision,
                "complete",
                response.IsVerifiedNoOp ? null : shortCommit,
                summary,
                [],
                response.Verification,
                CompletionKind: response.IsVerifiedNoOp
                    ? DecomposeStepCompletionKind.VerifiedNoOp
                    : DecomposeStepCompletionKind.Changed,
                EvaluatedCommit: response.IsVerifiedNoOp ? terminalCommit : null,
                NoOpEvidence: response.IsVerifiedNoOp ? response.NoOpEvidence : null);
            var nextTaskId = durable.Tasks.FirstOrDefault(task =>
                !string.Equals(task.TaskId, context.TaskId, StringComparison.Ordinal) &&
                task.Status is not PlanTaskStatus.Complete and not PlanTaskStatus.Superseded)?.TaskId;
            updated = PlanStoreUpdater.ApplyStepAccepted(
                durable, nextTaskId, syntheticResult) with
            {
                LifecycleStatus = PlanLifecycleStatus.Executing,
                InterruptionData = null,
            };
            if (!TryPublishPlanRecoveryProgress(
                    durable,
                    updated,
                    out var persistedUpdate,
                    out var saveError))
                throw new IOException(saveError ?? "The durable plan could not be saved.");
            updated = persistedUpdate!;
            RefreshPlanProjectionBestEffort(updated, "assessed-recovery-accepted");

            LoadTasksPanel();
            var nextValidation = PlanExecutionBoundaryPolicy.SelectValidation(updated);
            if (nextValidation is null && HasReadyPendingApprovalGate(updated))
            {
                await ProcessPlanApprovalsAfterStepAsync(
                    durable.PlanId,
                    durable.Revision,
                    context.TaskId,
                    DecomposeGroupExecutionState.Complete,
                    updated);

                updated = _planStore.Load(durable.PlanId) ?? updated;
                nextValidation = PlanExecutionBoundaryPolicy.SelectValidation(updated);
            }

            switch (AssessedPlanContinuationPolicy.Resolve(updated, nextTaskId, nextValidation))
            {
                case AssessedPlanContinuationAction.Complete:
                    updated = PlanStoreUpdater.ApplyCompleted(updated);
                    if (!TryPublishPlanProgress(updated, out var completionError))
                        throw new IOException(completionError ?? "The completed plan could not be saved.");
                    PublishPlanCompletionSummary(updated);
                    ScheduleDecomposeSystemEntry(PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(updated));
                    break;

                case AssessedPlanContinuationAction.StartExecution:
                    await StartBackloggedDecomposeGroupAsync(
                        currentGroup with { HostRevision = durable.Revision },
                        continuationTaskId: null,
                        continuationPaths: []);
                    break;

                case AssessedPlanContinuationAction.RemainStopped:
                    break;
            }
        }
        catch (Exception ex)
        {
            _planStore.Save(durable);
            _broker.Publish(new PlanProgressEvent(durable.PlanId, durable));
            LoadTasksPanel();
            KeepPlanStoppedAfterAssessment(
                context,
                "SquadDash could not safely accept and continue the assessed work. " + ex.Message);
            return;
        }

        var boundaryPlan = _planStore.Load(durable.PlanId);
        var boundaryMessage = boundaryPlan?.LifecycleStatus switch
        {
            PlanLifecycleStatus.AwaitingApproval => " Human approval is required before plan validation continues.",
            PlanLifecycleStatus.Completed => " The plan is complete.",
            _ when boundaryPlan is not null && PlanExecutionBoundaryPolicy.SelectValidation(boundaryPlan) is not null
                => " Plan validation is starting.",
            _ => " Continuing with the next plan task.",
        };
        ResolveRecoveryTranscript(
            response.IsVerifiedNoOp
                ? $"✓ Recovery completed. Confirmed the step was already satisfied at {shortCommit}.{boundaryMessage}"
                : $"✓ Recovery completed. Reused committed work from {shortCommit}.{boundaryMessage}");
    }

    private void KeepPlanStoppedAfterAssessment(
        PendingPlanRecoveryAssessment context,
        string message)
    {
        ShowSystemTranscriptEntry("The plan remains stopped. " + message);
        TranscriptQuickReplyFactory.RemoveDecomposeRecoveryContainers(
            CoordinatorThread.Document.Blocks);
        AppendDecomposeRecoveryActions(context.Plan, context.TaskId);
    }

    private static string NormalizeGitSnapshot(string value) =>
        value.Replace("\r\n", "\n", StringComparison.Ordinal).TrimEnd();

    private async Task<PlanRecoveryRepositorySnapshot> CapturePlanRecoveryRepositorySnapshotAsync(
        string workspace)
    {
        var hostOwnedPaths = await GetHostOwnedAssessmentPathsAsync(workspace);
        var pathspec = PlanRecoveryAssessmentSnapshotPolicy.BuildGitPathspec(hostOwnedPaths);
        var head = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
        var trackedDiff = await RunGitAsync(
            workspace,
            $"diff --binary --no-ext-diff HEAD {pathspec}");
        var status = NormalizeGitSnapshot(await RunGitAsync(
            workspace,
            $"status --porcelain --untracked-files=all {pathspec}"));
        var untrackedOutput = await RunGitAsync(
            workspace,
            $"ls-files --others --exclude-standard -z {pathspec}");
        var workspaceRoot = Path.GetFullPath(workspace)
            .TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar) +
            Path.DirectorySeparatorChar;
        var untracked = new List<(string Path, string ContentHash)>();
        foreach (var relativePath in untrackedOutput.Split(
                     '\0',
                     StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            var fullPath = Path.GetFullPath(Path.Combine(workspace, relativePath));
            if (!fullPath.StartsWith(workspaceRoot, StringComparison.OrdinalIgnoreCase) ||
                !File.Exists(fullPath))
            {
                untracked.Add((relativePath, "unavailable"));
                continue;
            }

            await using var stream = new FileStream(
                fullPath,
                FileMode.Open,
                FileAccess.Read,
                FileShare.ReadWrite | FileShare.Delete,
                bufferSize: 81920,
                useAsync: true);
            var hash = Convert.ToHexString(await SHA256.HashDataAsync(stream)).ToLowerInvariant();
            untracked.Add((relativePath, hash));
        }

        return new PlanRecoveryRepositorySnapshot(
            head,
            PlanRecoveryAssessmentSnapshotPolicy.CreateFingerprint(head, trackedDiff, untracked),
            status);
    }

    private sealed record PendingRecoveryAnalysisContext(PendingDecomposePlan Plan, string TaskId);

    private async Task AnalyzePlanRecoveryWithAiAsync(PendingDecomposePlan plan, string taskId)
    {
        if (_currentWorkspace is null) return;
        var workspace = _currentWorkspace.FolderPath;

        var fullPlan = _planStore?.Load(plan.Group.GroupId);
        var baselineCommit = fullPlan?.InterruptionData?.LastCommit
            ?? _decomposeIterationBaselineCommit
            ?? (await RunGitAsync(workspace, "rev-parse HEAD~1")).Trim();

        var evidence = await GatherPlanRecoveryEvidenceAsync(workspace, plan.Group.GroupId, taskId, baselineCommit, plan);
        var prompt = BuildRecoveryAnalysisPrompt(plan.Group.GroupId, taskId, plan.Revision, evidence);

        _pendingRecoveryAnalysis = new PendingRecoveryAnalysisContext(plan, taskId);

        _promptQueue.EnqueueAtFront(
            prompt,
            _promptQueueCoordinator.NextSequenceNumber(),
            sourceTag: "decompose-recovery-analysis",
            isSystemInjected: true);
        SyncQueuePanel();
        SyncSendButton();
    }

    private async Task<string> GatherPlanRecoveryEvidenceAsync(
        string workspace,
        string groupId,
        string taskId,
        string baselineCommit,
        PendingDecomposePlan plan,
        IReadOnlyList<PlanRecoveryCommitReference>? commitReferences = null)
    {
        var sb = new System.Text.StringBuilder();
        var durablePlan = _planStore?.Load(groupId);
        var durableTaskForQuestion = durablePlan?.Tasks.FirstOrDefault(task =>
            string.Equals(task.TaskId, taskId, StringComparison.Ordinal));
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            durableTaskForQuestion?.DisplayStepLabel,
            durableTaskForQuestion?.Title ?? taskId);

        sb.AppendLine("=== Question to answer for the user ===");
        sb.AppendLine($"Does the current source satisfy every requirement of {stepLabel} ({durableTaskForQuestion?.Title ?? taskId})?");
        sb.AppendLine("Answer with a clear complete, partial, not started, or inconclusive finding; explain the source-code evidence and name any remaining work.");
        sb.AppendLine();

        sb.AppendLine("--- Plan and stop context ---");
        if (durablePlan is null)
        {
            sb.AppendLine("(durable plan state was unavailable)");
        }
        else
        {
            sb.AppendLine($"Plan title: {durablePlan.Title}");
            sb.AppendLine($"Plan summary: {durablePlan.Summary}");
            sb.AppendLine($"Plan branch: {durablePlan.Branch}");
            sb.AppendLine($"Plan state: {durablePlan.LifecycleStatus}");
            sb.AppendLine($"Stop point: {stepLabel} ({taskId})");
            sb.AppendLine($"Stop reason: {durablePlan.InterruptionData?.Reason ?? "not recorded"}");
            var cardEvidence = CompletedWorkReviewPresentationBuilder.Build(durablePlan, taskId);
            if (cardEvidence is not null)
            {
                sb.AppendLine("Recovery-card evidence:");
                sb.AppendLine(CompletedWorkReviewPresentationBuilder.BuildCopyText(cardEvidence));
            }
            sb.AppendLine("Plan steps:");
            foreach (var planTask in durablePlan.Tasks)
            {
                var planStep = PlanRecoveryPresentationBuilder.FormatStepLabel(
                    planTask.DisplayStepLabel,
                    planTask.Title ?? planTask.TaskId);
                sb.AppendLine($"- {planStep}: {planTask.Title ?? planTask.TaskId} [{planTask.Status}]");
            }
        }
        sb.AppendLine();

        // 1. Candidate unrecorded commits since baseline
        var logOutput = string.Empty;
        var diffStat  = string.Empty;
        var status    = string.Empty;
        var diff      = string.Empty;
        try
        {
            var hostOwnedPaths = await GetHostOwnedAssessmentPathsAsync(workspace);
            var recoveryPathspec = PlanRecoveryAssessmentSnapshotPolicy.BuildGitPathspec(hostOwnedPaths);
            logOutput = await RunGitAsync(
                workspace,
                $"log --reverse --format=%H%x09%s \"{baselineCommit}..HEAD\"");
            diffStat  = await RunGitAsync(workspace, $"diff --stat {baselineCommit}..HEAD");
            status    = await RunGitAsync(
                workspace,
                $"status --porcelain --untracked-files=all {recoveryPathspec}");
            diff      = await RunGitAsync(
                workspace,
                $"diff --unified=3 HEAD {recoveryPathspec}");
        }
        catch { /* git unavailable — leave blanks */ }

        sb.AppendLine($"=== Baseline commit: {baselineCommit} ===");
        sb.AppendLine();
        sb.AppendLine("--- Candidate unrecorded commits (git log baseline..HEAD) ---");
        sb.AppendLine(string.IsNullOrWhiteSpace(logOutput)
            ? "(none)"
            : FormatPlanRecoveryCommitLog(logOutput, commitReferences));
        sb.AppendLine();
        sb.AppendLine("--- Changed files (git diff --stat baseline..HEAD) ---");
        sb.AppendLine(string.IsNullOrWhiteSpace(diffStat) ? "(no changes)" : diffStat.Trim());
        sb.AppendLine();
        sb.AppendLine("--- Uncommitted state (git status --porcelain) ---");
        sb.AppendLine(string.IsNullOrWhiteSpace(status) ? "(clean)" : status.Trim());
        sb.AppendLine();
        sb.AppendLine("--- Uncommitted diffs (git diff HEAD, truncated to 4000 chars) ---");
        var diffText = string.IsNullOrWhiteSpace(diff) ? "(none)" : diff.Trim();
        sb.AppendLine(diffText.Length > 4000 ? diffText[..4000] + "\n[truncated]" : diffText);
        sb.AppendLine();

        // 5. Task specification
        var failedTask = plan.Group.Tasks.FirstOrDefault(t =>
            string.Equals(t.Id, taskId, StringComparison.Ordinal));
        sb.AppendLine("--- Task specification ---");
        if (failedTask is not null)
            sb.AppendLine(System.Text.Json.JsonSerializer.Serialize(failedTask));
        else
            sb.AppendLine($"(task {taskId} not found in plan)");
        sb.AppendLine();

        // Durable execution state is authoritative recovery context. In particular, a worker
        // handoff may already contain a successful build while independent verification was the
        // phase interrupted by restart. Label it as candidate evidence so it is not confused
        // with an independent acceptance verdict.
        var durableTask = durablePlan?.Tasks.FirstOrDefault(task =>
            string.Equals(task.TaskId, taskId, StringComparison.Ordinal));
        sb.AppendLine("--- Durable task stage and candidate evidence ---");
        if (durableTask is null)
        {
            sb.AppendLine("(no durable task state was available)");
        }
        else
        {
            sb.AppendLine($"Task status: {durableTask.Status}");
            if (durableTask.Handoff is not null)
            {
                sb.AppendLine("Worker candidate handoff (not independent acceptance):");
                sb.AppendLine(JsonSerializer.Serialize(durableTask.Handoff));
            }
            if (durableTask.VerificationHistory?.LastOrDefault() is { } latestVerification)
            {
                sb.AppendLine("Latest independent verification report:");
                sb.AppendLine(JsonSerializer.Serialize(latestVerification));
            }
        }
        sb.AppendLine();

        // 6. Downstream dependencies
        var downstream = plan.Group.Tasks
            .Where(t => t.DependsOn.Contains(taskId, StringComparer.Ordinal))
            .ToList();
        sb.AppendLine("--- Downstream tasks that depend on this task ---");
        if (downstream.Count == 0)
        {
            sb.AppendLine("(none)");
        }
        else
        {
            foreach (var dep in downstream)
                sb.AppendLine($"  {dep.Id}: {dep.Title ?? dep.Description}");
        }
        sb.AppendLine();

        // 7. Plan revision
        sb.AppendLine($"--- Plan revision: {plan.Revision} ---");

        return sb.ToString();
    }

    internal static string FormatPlanRecoveryCommitLog(
        string logOutput,
        IReadOnlyList<PlanRecoveryCommitReference>? commitReferences)
        => PlanRecoveryCommitLogFormatter.Format(logOutput, commitReferences);

    private static string BuildRecoveryAnalysisPrompt(
        string groupId,
        string taskId,
        string revision,
        string evidence)
    {
        return $$"""
            Plan {{groupId}} was interrupted while executing task {{taskId}} (revision {{revision}}).
            
            The following objective evidence was collected automatically:
            
            {{evidence}}
            
            Analyze this evidence and return a PLAN_RECOVERY_OPTIONS_JSON response.
            Include only options that are supported by the evidence above.
            Do not recommend actions that are not mechanically feasible given the evidence.
            Never authorize git mutations — the host validates all options before executing them.
            
            Valid action values: "adopt-commit", "partial-adopt", "revert-and-retry", "clean-retry", "replan"
            - adopt-commit: adopt an unrecorded commit between baseline and HEAD as the step result
            - partial-adopt: adopt committed + uncommitted work as a partial result
            - revert-and-retry: revert candidate commits and retry the task from scratch
            - clean-retry: retry from clean state without reverting (no unrecorded commits exist)
            - replan: revise the remaining graph or supersede the blocked task with one or more replacements
            
            Respond with PLAN_RECOVERY_OPTIONS_JSON: followed by a JSON object with:
            - groupId: "{{groupId}}"
            - taskId: "{{taskId}}"
            - revision: "{{revision}}"
            - options: array of {id, label, description, action, viable, evidence}
            - recommendation: id of the recommended option (optional)
            - summary: brief overall analysis (optional)
            """;
    }

    private void TryApplyRecoveryOptionsFromResponse(string? rawResponse)
    {
        if (_pendingRecoveryAnalysis is null) return;
        if (!PlanRecoveryOptionsParser.TryParse(rawResponse, out var response) || response is null) return;

        var context = _pendingRecoveryAnalysis;
        _pendingRecoveryAnalysis = null;

        if (!string.Equals(response.GroupId, context.Plan.Group.GroupId, StringComparison.Ordinal)) return;
        if (!string.Equals(response.Revision, context.Plan.Revision, StringComparison.Ordinal)) return;

        _ = ValidateAndRenderRecoveryOptionsAsync(response, context);
    }

    private async Task ValidateAndRenderRecoveryOptionsAsync(
        PlanRecoveryOptionsResponse response,
        PendingRecoveryAnalysisContext context)
    {
        if (_currentWorkspace is null) return;
        var workspace = _currentWorkspace.FolderPath;
        var plan = context.Plan;

        var fullPlan = _planStore?.Load(plan.Group.GroupId);
        var baselineCommit = fullPlan?.InterruptionData?.LastCommit ?? string.Empty;
        var hasCandidateCommit = false;
        var hasUncommittedWork = false;

        if (!string.IsNullOrEmpty(baselineCommit))
        {
            try
            {
                var logOutput = await RunGitAsync(workspace, $"log --oneline {baselineCommit}..HEAD");
                hasCandidateCommit = !string.IsNullOrWhiteSpace(logOutput);
                var statusOutput = await RunGitAsync(workspace, "status --porcelain --untracked-files=normal");
                hasUncommittedWork = !string.IsNullOrWhiteSpace(statusOutput);
            }
            catch { /* git command failed — leave defaults */ }
        }

        var validated = PlanRecoveryOptionsParser.ValidateRecoveryViability(response.Options, hasCandidateCommit, hasUncommittedWork);
        var viableOptions = validated.Where(o => o.Viable).ToList();

        if (viableOptions.Count == 0)
        {
            _ = Dispatcher.BeginInvoke(() =>
                ShowSystemTranscriptEntry($"AI analysis complete for {plan.Group.GroupId}: no viable options found. " +
                    "Use the Replan or Retry buttons to proceed manually."));
            return;
        }

        _ = Dispatcher.BeginInvoke(() => AppendRecoveryOptionsPanel(response, viableOptions, plan, context.TaskId));
    }

    private void AppendRecoveryOptionsPanel(
        PlanRecoveryOptionsResponse response,
        IReadOnlyList<PlanRecoveryOption> viableOptions,
        PendingDecomposePlan plan,
        string taskId)
    {
        if (!string.IsNullOrWhiteSpace(response.Summary))
            ShowSystemTranscriptEntry($"🤖 Recovery analysis: {response.Summary}");

        var panel = new WrapPanel { Orientation = Orientation.Horizontal };
        foreach (var option in viableOptions)
        {
            var btn = TranscriptQuickReplyFactory.CreateButton(
                option.Label,
                _transcriptFontSize,
                toolTip: ToolTipHelper.MakeThemedToolTip(option.Description));
            var capturedOption = option;
            btn.Click += async (_, _) =>
            {
                ClearPlanActionIssue(plan.Group.GroupId);
                panel.Visibility = Visibility.Collapsed;
                try
                {
                    await ExecuteRecoveryOptionAsync(capturedOption, plan, taskId);
                }
                catch (Exception ex)
                {
                    HandleUiCallbackException("Recovery option", ex);
                }
            };
            if (string.Equals(option.Id, response.Recommendation, StringComparison.Ordinal))
            {
                btn.FontWeight = FontWeights.SemiBold;
                btn.SetResourceReference(Control.BorderBrushProperty, "PriorityMid");
            }
            panel.Children.Add(btn);
        }

        CoordinatorThread.Document.Blocks.Add(
            TranscriptQuickReplyFactory.CreateContainer(
                panel,
                new DecomposeRecoveryTag(plan.Group.GroupId, plan.Revision, taskId)));
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private async Task<bool> ExecuteRecoveryOptionAsync(
        PlanRecoveryOption option,
        PendingDecomposePlan plan,
        string taskId)
    {
        switch (option.Action)
        {
            case "replan":
                await ReplanWithCurrentStateAsync(option, plan, taskId);
                return true;
            case "clean-retry":
                await RetryDecomposeTaskAsync(plan, taskId);
                return true;
            case "revert-and-retry":
                return await RevertAndRetryAsync(option, plan, taskId);
            case "adopt-commit":
            case "partial-adopt":
                return await AdoptOrphanCommitAsync(option, plan, taskId);
            default:
                ReportPlanActionIssue(
                    plan.Group.GroupId,
                    "Unknown recovery action",
                    $"SquadDash does not recognize recovery action '{option.Action}'.");
                return false;
        }
    }

    // ── Recovery action: Accept reviewed repository work ─────────────────────

    private void ClearPlanActionIssue(string planId)
    {
        _planActionIssues.Remove(planId);
        _plansPanelController?.SetPlanStatus(planId, null);
    }

    private void ReportPlanActionIssue(string planId, string title, string message)
    {
        var status = $"{title}: {message}";
        SquadDashTrace.Write("PlanAction", $"{planId}: {status}");
        _planActionIssues[planId] = status;
        _plansPanelController?.SetPlanStatus(planId, status);
        ShowSystemTranscriptEntry($"Plan action did not continue. {status}");
        foreach (var entry in _openPlanViewerWindows.Where(entry =>
                     string.Equals(entry.GroupId, planId, StringComparison.Ordinal)))
            entry.Window.SetActionStatus(title, message);
    }

    private async Task<bool> AcceptInterruptedStepAfterReviewAsync(Plan displayedPlan)
    {
        if (_currentWorkspace is null || _planStore is null) return false;
        if (IsPlanRecoveryActionBusy(displayedPlan.PlanId))
        {
            ReportPlanActionIssue(
                displayedPlan.PlanId,
                "Work still running",
                "Wait for the current prompt, loop, or active plan task to finish before accepting interrupted work.");
            return false;
        }
        ClearPlanActionIssue(displayedPlan.PlanId);
        var workspace = _currentWorkspace.FolderPath;
        var storedPlan = _planStore.Load(displayedPlan.PlanId);
        if (storedPlan?.LifecycleStatus == PlanLifecycleStatus.AwaitingApproval &&
            PlanReviewAttentionPresentationResolver.Resolve(storedPlan) is { } reviewAttention)
            return await AcceptAwaitingReviewStepAsync(storedPlan, reviewAttention);
        if (storedPlan is null ||
            storedPlan.LifecycleStatus != PlanLifecycleStatus.Interrupted ||
            !string.Equals(storedPlan.Revision, displayedPlan.Revision, StringComparison.Ordinal))
        {
            ReportPlanActionIssue(
                displayedPlan.PlanId,
                "Plan changed",
                "The interrupted plan changed after this viewer opened. Reopen the plan before adopting preserved work.");
            return false;
        }

        var taskId = storedPlan.InterruptionData?.InterruptedTaskId;
        var pendingTask = storedPlan.Tasks.FirstOrDefault(task =>
            string.Equals(task.TaskId, taskId, StringComparison.Ordinal) &&
            task.Status != PlanTaskStatus.Complete);
        if (pendingTask is null || string.IsNullOrWhiteSpace(taskId))
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "No interrupted task",
                "SquadDash cannot identify a pending interrupted task for this plan.");
            return false;
        }
        var taskIndex = storedPlan.Tasks.ToList().FindIndex(task =>
            string.Equals(task.TaskId, taskId, StringComparison.Ordinal));
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            pendingTask.DisplayStepLabel ?? (taskIndex >= 0 ? (taskIndex + 1).ToString() : null),
            pendingTask.Title ?? pendingTask.Description);
        var combinedAmendmentGate = string.IsNullOrWhiteSpace(pendingTask.AmendmentGateId)
            ? null
            : storedPlan.ApprovalGates.FirstOrDefault(gate =>
                string.Equals(gate.GateId, pendingTask.AmendmentGateId, StringComparison.Ordinal) &&
                PlanAmendmentGateAcceptancePolicy.CanCombineWithTaskAcceptance(storedPlan, pendingTask) &&
                gate.Status is PlanGateStatus.Pending or PlanGateStatus.AwaitingApproval &&
                gate.AfterTaskIds.Contains(pendingTask.TaskId, StringComparer.Ordinal) &&
                gate.BeforeTaskIds.All(id => storedPlan.Tasks.Any(task =>
                    string.Equals(task.TaskId, id, StringComparison.Ordinal) &&
                    task.Status == PlanTaskStatus.Pending)));
        var combinedHumanReviewGate = combinedAmendmentGate is null
            ? PlanHumanReviewGatePolicy.FindCombinableGate(storedPlan, taskId)
            : null;
        var combinedApprovalGate = combinedAmendmentGate ?? combinedHumanReviewGate;

        var activeBranch = ReadGitBranch(workspace);
        if (!string.Equals(activeBranch, storedPlan.Branch, StringComparison.Ordinal))
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Branch mismatch",
                $"Plan '{storedPlan.PlanId}' requires branch '{storedPlan.Branch}', but '{activeBranch}' is active.");
            return false;
        }

        var recoveryAssessment = storedPlan.InterruptionData?.RecoveryAssessment;
        if (recoveryAssessment is { } noOpAssessment && string.Equals(
                noOpAssessment.CompletionKind,
                DecomposeStepCompletionKind.VerifiedNoOp,
                StringComparison.Ordinal))
        {
            var currentSnapshot = await CapturePlanRecoveryRepositorySnapshotAsync(workspace);
            var baseline = await ResolvePlanRecoveryBaselineAsync(workspace, storedPlan, taskId);
            if (!PlanRecoveryAssessmentSnapshotPolicy.IsCurrent(noOpAssessment, currentSnapshot) ||
                noOpAssessment.NoOpEvidence is not { Count: > 0 } ||
                !string.Equals(
                    noOpAssessment.Verification?.Status,
                    "passed",
                    StringComparison.OrdinalIgnoreCase))
            {
                ReportPlanActionIssue(
                    storedPlan.PlanId,
                    "Assessment changed",
                    "The already-satisfied assessment no longer matches the current repository snapshot. Reassess before accepting it.");
                return false;
            }

            try
            {
                await RunGitAsync(
                    workspace,
                    $"merge-base --is-ancestor \"{baseline}\" \"{currentSnapshot.HeadCommit}\"");
            }
            catch
            {
                ReportPlanActionIssue(
                    storedPlan.PlanId,
                    "Assessment changed",
                    "The assessed snapshot is no longer descended from the task baseline. Reassess before accepting it.");
                return false;
            }

            await EnsurePlanWorktreeReadyAsync(workspace, storedPlan.PlanId);
            var status = NormalizeGitSnapshot(await RunGitAsync(
                workspace, "status --porcelain --untracked-files=all"));
            var response = new PlanRecoveryAssessmentResponse(
                Guid.NewGuid().ToString("N"),
                PlanRecoveryClassification.Complete,
                noOpAssessment.Summary,
                [],
                noOpAssessment.Verification,
                [],
                CompletionKind: DecomposeStepCompletionKind.VerifiedNoOp,
                EvaluatedCommit: currentSnapshot.HeadCommit,
                NoOpEvidence: noOpAssessment.NoOpEvidence);
            var context = new PendingPlanRecoveryAssessment(
                PendingDecomposePlanAdapter.FromPlan(storedPlan),
                taskId,
                response.RecoveryAssessmentId,
                baseline,
                currentSnapshot.HeadCommit,
                status,
                currentSnapshot.Fingerprint,
                [],
                AdvisoryOnly: false);
            PrepareForHostRecoveryAction();
            await AcceptAssessedPlanRecoveryAsync(
                storedPlan,
                context,
                response,
                currentSnapshot.HeadCommit);
            return _planStore.Load(storedPlan.PlanId)?.Tasks.Any(task =>
                string.Equals(task.TaskId, taskId, StringComparison.Ordinal) &&
                task.Status == PlanTaskStatus.Complete) == true;
        }

        if (RejectedVerifiedNoOpRecoveryPolicy.CanAccept(storedPlan, taskId))
            return await AcceptRejectedVerifiedNoOpAsync(storedPlan, pendingTask, taskId, workspace);

        InterruptedTaskReviewRange reviewRange;
        try
        {
            reviewRange = await ResolveInterruptedTaskReviewRangeAsync(storedPlan, taskId);
        }
        catch (Exception ex)
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Review range unavailable",
                $"SquadDash could not reconstruct the reviewed repository range: {ex.Message}");
            return false;
        }
        var baselineCommit = reviewRange.BaselineCommit;

        IReadOnlyList<RecoveryCommitRangeEntry> candidates;
        var rangeEnd = reviewRange.TerminalCommit;
        try
        {
            await RunGitAsync(workspace,
                $"merge-base --is-ancestor \"{baselineCommit}\" \"{rangeEnd}\"");
            await RunGitAsync(workspace,
                $"merge-base --is-ancestor \"{rangeEnd}\" HEAD");
            var log = await RunGitAsync(
                workspace,
                $"log --reverse --format=%H%x09%s \"{baselineCommit}..{rangeEnd}\"");
            candidates = RecoveryCommitValidator.ParseCommitRange(log);
        }
        catch (Exception ex)
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Commit range unavailable",
                $"SquadDash could not enumerate the candidate range: {ex.Message}");
            return false;
        }
        if (candidates.Count == 0)
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Nothing to adopt",
                "There are no commits after the last accepted plan task.");
            return false;
        }

        var selected = candidates[^1];
        var selectedIndex = candidates.ToList().FindIndex(entry =>
            RecoveryCommitValidator.CommitIdentifiersMatch(entry.Commit, selected.Commit));
        if (selectedIndex < 0)
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Commit range changed",
                "The selected commit is no longer present in the reviewed range. Reopen the action and try again.");
            return false;
        }
        var selectedRange = candidates.Take(selectedIndex + 1).ToArray();
        var maximumReviewCommits = reviewRange.HasExactTaskAttribution ? 50 : 250;
        if (selectedRange.Length > maximumReviewCommits)
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Range too large",
                $"The reviewed range contains {selectedRange.Length} commits. Split or replan the task before acceptance.");
            return false;
        }

        await RunGitAsync(workspace,
            $"merge-base --is-ancestor \"{baselineCommit}\" \"{selected.Commit}\"");
        await RunGitAsync(workspace,
            $"merge-base --is-ancestor \"{selected.Commit}\" HEAD");
        var commitCountText = (await RunGitAsync(
            workspace,
            $"rev-list --count \"{baselineCommit}..{selected.Commit}\"")).Trim();
        if (!int.TryParse(commitCountText, out var commitCount) || commitCount != selectedRange.Length)
            throw new InvalidOperationException(
                "The selected commit range changed while it was being reviewed. Reopen the adoption action.");

        var changedPaths = (await RunGitAsync(
                workspace,
                $"diff --name-only \"{baselineCommit}..{selected.Commit}\"") )
            .Replace("\r\n", "\n", StringComparison.Ordinal)
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        var hostOwnedPaths = await GetHostOwnedRecoveryPathsAsync(workspace);
        if (!RecoveryCommitValidator.ContainsNonHostChanges(changedPaths, hostOwnedPaths))
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Suspicious commit range",
                reviewRange.HasExactTaskAttribution
                    ? "The recorded range contains no task changes after SquadDash-owned state is excluded. It cannot be accepted."
                    : "The reviewed range contains no non-host repository changes, so it cannot establish completed task work.");
            return false;
        }

        // A durable user pause means this action accepts already-reviewed committed evidence but
        // deliberately starts no downstream work. Uncommitted files therefore belong to the later
        // Resume preflight, not to step acceptance. An unpaused "Complete & Continue" action still
        // requires a clean worktree before the atomic accept-and-resume transition.
        if (PlanRecoveryAcceptancePolicy.RequiresCleanWorktreeBeforeAcceptance(storedPlan))
            await EnsurePlanWorktreeReadyAsync(workspace, storedPlan.PlanId);

        var terminalCommit = selected.Commit[..7];
        var firstCommit = selectedRange[0].Commit[..7];
        var rangeLabel = selectedRange.Length == 1
            ? terminalCommit
            : $"{firstCommit}..{terminalCommit}";
        var summary = reviewRange.HasExactTaskAttribution
            ? $"Human accepted host-recorded commit range {rangeLabel} ({selectedRange.Length} commit" +
              (selectedRange.Length == 1 ? ")." : "s).")
            : $"Human marked the step complete after reviewing repository changes through {terminalCommit}; " +
              "individual commit attribution remains uncertain.";
        var syntheticResult = new DecomposeStepResult(
            GroupId: storedPlan.PlanId,
            TaskId: taskId,
            Revision: storedPlan.Revision,
            Status: "complete",
            Commit: terminalCommit,
            Summary: summary,
            RemainingWork: [],
            Verification: new DecomposeStepVerification(
                "passed",
                reviewRange.HasExactTaskAttribution
                    ? "human acceptance with host-controlled commit-range validation"
                    : "explicit human completion after repository-difference review",
                $"The human reviewer accepted the task after SquadDash validated ancestry, {selectedRange.Length} commits, and {changedPaths.Length} changed paths."))
        {
            Commits = reviewRange.Commits,
        };

        // Consume the recovery surface only after validation succeeds. A rejected or stale
        // action remains in place instead of disappearing and being regenerated as an apparently
        // endless prompt loop. The completion button itself is the explicit user decision.
        PrepareForHostRecoveryAction();

        Plan? acceptedPlan = null;
        try
        {
            var updated = PlanStoreUpdater.ApplyStepAccepted(
                storedPlan,
                nextExecutingTaskId: null,
                syntheticResult);
            if (combinedApprovalGate is not null)
            {
                if (combinedApprovalGate.Status == PlanGateStatus.Pending)
                    updated = PlanStoreUpdater.ApplyGateReady(updated, combinedApprovalGate.GateId);
                var resolvedBy = await HumanApprovalIdentityResolver.ResolveAsync(workspace);
                updated = PlanStoreUpdater.ApplyGateApproved(
                    updated,
                    combinedApprovalGate.GateId,
                    combinedAmendmentGate is not null
                        ? PlanAmendmentGateAcceptancePolicy.CombinedApprovalNote
                        : $"Confirmed {stepLabel} complete while reviewing its commit evidence and human-observation checkpoint.",
                    resolvedBy);
            }
            if (PlanExecutionBoundaryPolicy.IsReadyToComplete(updated))
            {
                updated = PlanStoreUpdater.ApplyCompleted(updated with { InterruptionData = null });
            }
            else
            {
                var nextTaskId = updated.Tasks.FirstOrDefault(task =>
                    task.Status is not PlanTaskStatus.Complete and not PlanTaskStatus.Superseded)?.TaskId;
                var interruptionData = (updated.InterruptionData ?? new PlanInterruptionData(
                    "Preserved work was accepted by the human reviewer.",
                    PlanRecoveryState.PendingRecovery,
                    0)) with
                {
                    Reason = PlanRecoveryResumePolicy.BuildAcceptedWorkContinuationReason(
                        $"Preserved work for {taskId} was adopted as {rangeLabel}."),
                    InterruptedTaskId = nextTaskId,
                    LastCompletedTaskId = taskId,
                    LastCommit = terminalCommit,
                    AffectedPaths = changedPaths,
                    PartialWorkEvidence = $"Human-accepted commit range {rangeLabel}"
                };
                updated = updated with
                {
                    LifecycleStatus = PlanLifecycleStatus.Interrupted,
                    InterruptionData = interruptionData,
                    Progress = updated.Progress with { ExecutingTaskId = null }
                };
            }
            if (!TryPublishPlanProgress(updated, out var saveError))
                throw new IOException(saveError ?? "The durable plan could not be saved.");
            RefreshPlanProjectionBestEffort(updated, "verified-commit-range-adopted");
            acceptedPlan = updated;
            if (ClearQueueRecoveryHoldForPlan(storedPlan.PlanId, taskId, "step-accepted"))
                _ = DrainQueueIfNeededAsync();
        }
        catch { throw; }

        LoadTasksPanel();
        if (acceptedPlan!.LifecycleStatus == PlanLifecycleStatus.Completed)
        {
            ResolveRecoveryTranscript(combinedHumanReviewGate is not null
                ? $"✓ Recovery completed. {stepLabel} was accepted from {rangeLabel}; its human checkpoint is approved and the plan is complete."
                : combinedAmendmentGate is not null
                    ? $"✓ Recovery completed. Accepted reviewed amendment {rangeLabel}, approved its checkpoint, and completed the plan."
                    : $"✓ Recovery completed. Human accepted {rangeLabel} for {stepLabel}; the plan is complete.");
            PublishPlanCompletionSummary(acceptedPlan);
            ScheduleDecomposeSystemEntry(
                PlanLoopTranscriptPresentation.BuildPlanCompleteMessage(
                    acceptedPlan, "Final reviewed work accepted"));
            ReconcileDecomposeRecoveryInboxMessages(acceptedPlan.PlanId);
            return true;
        }
        var nextValidation = PlanExecutionBoundaryPolicy.SelectValidation(acceptedPlan!);
        var hasReadyApprovalBoundary = nextValidation is null &&
                                       HasReadyPendingApprovalGate(acceptedPlan!);
        var shouldAdvanceToApprovalBoundary =
            PlanRecoveryAcceptancePolicy.ShouldAdvanceAfterAcceptance(acceptedPlan!) &&
            hasReadyApprovalBoundary;
        var mustAwaitApproval = shouldAdvanceToApprovalBoundary &&
                                PlanExecutionBoundaryPolicy.ShouldStopForHumanApproval(acceptedPlan!);
        ResolveRecoveryTranscript(combinedHumanReviewGate is not null
            ? $"✓ Recovery completed. {stepLabel} was accepted from {rangeLabel}; its human checkpoint is also approved."
            : combinedAmendmentGate is not null
                ? $"✓ Recovery completed. Accepted reviewed amendment {rangeLabel} and approved its checkpoint."
                : mustAwaitApproval
                    ? $"✓ Recovery completed. Human accepted {rangeLabel} for {stepLabel}; the next human checkpoint is opening."
                    : acceptedPlan.IsPaused
                        ? $"✓ Recovery completed. Human accepted {rangeLabel} for {stepLabel}; the plan remains paused."
                        : $"✓ Recovery completed. Human accepted {rangeLabel} for {stepLabel}; the plan is continuing.");

        if (shouldAdvanceToApprovalBoundary)
        {
            // Recovery acceptance deliberately remains interrupted until the next boundary is
            // known. Once that boundary is a ready gate, the approval runtime owns the durable
            // state and must activate it before any native loop-stop callback can run.
            acceptedPlan = PlanStoreUpdater.ApplyApprovalBoundaryRecovery(acceptedPlan!);
            await ProcessPlanApprovalsAfterStepAsync(
                acceptedPlan.PlanId,
                acceptedPlan.Revision,
                taskId,
                mustAwaitApproval
                    ? DecomposeGroupExecutionState.AwaitingApproval
                    : DecomposeGroupExecutionState.Eligible,
                acceptedPlan);
            var boundaryPlan = _planStore.Load(acceptedPlan.PlanId) ?? acceptedPlan;
            if (boundaryPlan.LifecycleStatus == PlanLifecycleStatus.AwaitingApproval)
                return true;
            acceptedPlan = boundaryPlan;
        }
        // Continue from the canonical durable plan. tasks.md is intentionally a lossy UI/task
        // projection and does not contain outputs, inputs, approval gates, or validation nodes;
        // sending that projection back through TASKS_JSON validation can reject valid plans after
        // their completed work has already been accepted.
        if (PlanRecoveryAcceptancePolicy.ShouldAdvanceAfterAcceptance(acceptedPlan!))
            await StartOrResumeDurablePlanAsync(acceptedPlan);
        return true;
    }

    private Plan? ApplyAndPublishValidationHumanReviewRequired(
        string groupId,
        string validationId,
        string summary,
        IReadOnlyList<string> evidence,
        string? validatedCommit,
        IReadOnlyList<PlanTaskProofRequirement> proofRequirements)
    {
        try
        {
            var plan = _planStore?.Load(groupId);
            if (plan is null) return null;
            var updated = PlanStoreUpdater.ApplyValidationHumanReviewRequired(
                plan, validationId, summary, evidence, validatedCommit, proofRequirements);
            return TryPublishPlanProgress(updated, out _) ? updated : null;
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("PlanValidation",
                $"Failed to persist human review checkpoint for {validationId}: {ex.Message}");
            return null;
        }
    }

    private async Task<bool> AcceptRejectedVerifiedNoOpAsync(
        Plan storedPlan,
        PlanTask pendingTask,
        string taskId,
        string workspace)
    {
        if (_planStore is null) return false;

        var baseline = await ResolvePlanRecoveryBaselineAsync(workspace, storedPlan, taskId);
        var snapshot = await CapturePlanRecoveryRepositorySnapshotAsync(workspace);
        try
        {
            await RunGitAsync(
                workspace,
                $"merge-base --is-ancestor \"{baseline}\" \"{snapshot.HeadCommit}\"");
            await EnsurePlanWorktreeReadyAsync(workspace, storedPlan.PlanId);
        }
        catch (Exception ex)
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Current snapshot cannot be accepted",
                "SquadDash cannot safely accept the reported no-op at the current snapshot. " + ex.Message);
            return false;
        }

        var status = NormalizeGitSnapshot(await RunGitAsync(
            workspace, "status --porcelain --untracked-files=all"));
        var stepLabel = PlanRecoveryPresentationBuilder.FormatStepLabel(
            pendingTask.DisplayStepLabel,
            pendingTask.Title ?? pendingTask.Description);
        var shortHead = snapshot.HeadCommit[..Math.Min(7, snapshot.HeadCommit.Length)];
        var summary = $"The human reviewer accepted the previously reported no-op for {stepLabel} " +
                      $"at current snapshot {shortHead}. Commits after the task baseline were not attributed to this step.";
        var response = new PlanRecoveryAssessmentResponse(
            Guid.NewGuid().ToString("N"),
            PlanRecoveryClassification.Complete,
            summary,
            [],
            new DecomposeStepVerification(
                "passed",
                "explicit human recovery decision",
                "The reviewer explicitly accepted the reported verification result after current-snapshot safety checks."),
            [],
            CompletionKind: DecomposeStepCompletionKind.VerifiedNoOp,
            EvaluatedCommit: snapshot.HeadCommit,
            NoOpEvidence:
            [
                new PlanTaskNoOpEvidence(
                    pendingTask.Title ?? pendingTask.Description ?? taskId,
                    "Human accepted the prior no-op result after SquadDash confirmed current HEAD, baseline ancestry, and worktree safety.",
                    [$"repository HEAD {shortHead}"]),
            ]);
        var context = new PendingPlanRecoveryAssessment(
            PendingDecomposePlanAdapter.FromPlan(storedPlan),
            taskId,
            response.RecoveryAssessmentId,
            baseline,
            snapshot.HeadCommit,
            status,
            snapshot.Fingerprint,
            [],
            AdvisoryOnly: false);

        PrepareForHostRecoveryAction();
        await AcceptAssessedPlanRecoveryAsync(
            storedPlan,
            context,
            response,
            snapshot.HeadCommit,
            summaryPrefix: "Human-confirmed recovery: ");
        return _planStore.Load(storedPlan.PlanId)?.Tasks.Any(task =>
            string.Equals(task.TaskId, taskId, StringComparison.Ordinal) &&
            task.Status == PlanTaskStatus.Complete) == true;
    }

    private async Task<bool> AcceptAwaitingReviewStepAsync(
        Plan storedPlan,
        PlanReviewAttentionPresentation reviewAttention)
    {
        if (_planStore is null || _planApprovalRuntime is null) return false;
        var token = _planApprovalRuntime.Actions.GetCurrentToken(storedPlan.PlanId);
        if (token is null || !token.GateIds.Contains(reviewAttention.Gate.GateId, StringComparer.Ordinal))
        {
            ReportPlanActionIssue(
                storedPlan.PlanId,
                "Review changed",
                "The human-review checkpoint changed. Reopen the current review before continuing.");
            return false;
        }

        await HandleApprovalClickAsync(token, gateIdsToResolve: [reviewAttention.Gate.GateId]);
        var current = _planStore.Load(storedPlan.PlanId);
        return current?.Tasks.Any(task =>
                   string.Equals(task.TaskId, reviewAttention.Task.TaskId, StringComparison.Ordinal) &&
                   task.Status == PlanTaskStatus.Complete) == true &&
               current.ApprovalGates.Any(gate =>
                   string.Equals(gate.GateId, reviewAttention.Gate.GateId, StringComparison.Ordinal) &&
                   gate.Status == PlanGateStatus.Approved);
    }

    private async Task<bool> ValidateHumanReviewStepAcceptanceAsync(
        Plan plan,
        PlanReviewAttentionPresentation reviewAttention,
        string currentHead,
        CancellationToken cancellationToken)
    {
        if (_currentWorkspace is null) return false;
        if (reviewAttention.Checklist.Count == 0 || reviewAttention.Checklist.Any(item => !item.IsChecked))
        {
            ReportPlanActionIssue(plan.PlanId, "Review incomplete", "Verify every checklist item before continuing.");
            return false;
        }
        var handoff = reviewAttention.Task.Handoff;
        var isVerifiedNoOp = string.Equals(
            handoff?.CompletionKind,
            DecomposeStepCompletionKind.VerifiedNoOp,
            StringComparison.Ordinal);
        var reviewTarget = isVerifiedNoOp ? handoff?.EvaluatedCommit : handoff?.Commit;
        if (handoff is null || string.IsNullOrWhiteSpace(reviewTarget))
        {
            ReportPlanActionIssue(
                plan.PlanId,
                "Review evidence missing",
                "The reviewed task has no durable completion handoff.");
            return false;
        }

        var workspace = _currentWorkspace.FolderPath;
        var activeBranch = ReadGitBranch(workspace);
        if (!string.Equals(activeBranch, plan.Branch, StringComparison.Ordinal))
        {
            ReportPlanActionIssue(
                plan.PlanId,
                "Branch mismatch",
                $"Plan '{plan.PlanId}' requires branch '{plan.Branch}', but '{activeBranch}' is active.");
            return false;
        }
        try
        {
            if (!await PlanRecoveryGit.IsAncestorAsync(workspace, reviewTarget, currentHead, cancellationToken))
            {
                ReportPlanActionIssue(plan.PlanId, "Review evidence stale",
                    $"The reviewed commit for task {reviewAttention.Task.TaskId} could not be validated against the current branch.");
                return false;
            }
            if (PlanRecoveryAcceptancePolicy.RequiresCleanWorktreeBeforeAcceptance(plan))
                await EnsurePlanWorktreeReadyAsync(workspace, plan.PlanId);
            return true;
        }
        catch (Exception ex)
        {
            ReportPlanActionIssue(plan.PlanId, "Review could not be completed", ex.Message);
            return false;
        }
    }

    /// <summary>
    /// Revalidates active recovery reminders against the canonical plan lifecycle. Resolved
    /// reminders are retained in the archive without live actions; current blockers are critical.
    /// </summary>
    private void ReconcileDecomposeRecoveryInboxMessages(string? planId = null)
    {
        if (_inboxStore is null || _planStore is null) return;

        var currentHead = ReadCachedRecoveryHeadCommit();
        var changed = false;
        foreach (var message in _inboxStore.LoadAll()
                     .Where(DecomposeRecoveryInboxReconciler.IsRecoveryMessage)
                     .Where(message => planId is null || string.Equals(
                         DecomposeRecoveryInboxReconciler.GetPlanId(message),
                         planId,
                         StringComparison.Ordinal)))
        {
            var referencedPlanId = DecomposeRecoveryInboxReconciler.GetPlanId(message);
            var plan = string.IsNullOrWhiteSpace(referencedPlanId)
                ? null
                : _planStore.Load(referencedPlanId);
            var result = DecomposeRecoveryInboxReconciler.Reconcile(
                message,
                plan,
                currentHead,
                (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant));
            if (!Equals(result.Message, message))
            {
                _inboxStore.Save(result.Message);
                changed = true;
            }
            if (result.ShouldArchive)
            {
                _inboxStore.Archive(message.Id);
                changed = true;
            }
        }

        if (!changed) return;
        var current = _inboxStore.LoadAll();
        _inboxPanel?.Refresh(current);
        ReconcileOpenInboxWindows(current);
    }

    /// <summary>
    /// Final race-safe validation used when a recovery message is opened or one of its actions
    /// is clicked. A plan transition between rendering and clicking cannot invoke stale work.
    /// </summary>
    private bool TryPrepareRecoveryInboxMessageForUse(
        string messageId,
        out InboxMessage? preparedMessage)
    {
        preparedMessage = null;
        if (_inboxStore is null) return true;

        var message = _inboxStore.GetById(messageId);
        if (message is null)
            return !messageId.StartsWith("decompose-recovery-", StringComparison.Ordinal);
        if (!DecomposeRecoveryInboxReconciler.IsRecoveryMessage(message))
        {
            preparedMessage = message;
            return true;
        }

        var planId = DecomposeRecoveryInboxReconciler.GetPlanId(message);
        var plan = _planStore is null || string.IsNullOrWhiteSpace(planId)
            ? null
            : _planStore.Load(planId);
        var currentHead = ReadCachedRecoveryHeadCommit();
        var result = DecomposeRecoveryInboxReconciler.Reconcile(
            message,
            plan,
            currentHead,
            (ancestor, descendant) => IsCachedRecoveryAncestor(ancestor, descendant));
        if (!Equals(result.Message, message))
            _inboxStore.Save(result.Message);
        if (result.ShouldArchive)
            _inboxStore.Archive(message.Id);

        if (!result.IsActionable)
        {
            var current = _inboxStore.LoadAll();
            _inboxPanel?.Refresh(current);
            ReconcileOpenInboxWindows(current);
            return false;
        }

        preparedMessage = result.Message;
        return true;
    }

    private static void RestoreFileAtomically(string path, string content)
    {
        var temporaryPath = path + ".rollback.tmp";
        File.WriteAllText(temporaryPath, content, Encoding.UTF8);
        File.Move(temporaryPath, path, overwrite: true);
    }

    // ── Recovery action: Adopt orphan commit ─────────────────────────────────

    private async Task<bool> AdoptOrphanCommitAsync(
        PlanRecoveryOption option,
        PendingDecomposePlan plan,
        string taskId)
    {
        if (_currentWorkspace is null) return false;
        var workspace = _currentWorkspace.FolderPath;
        var tasksPath = Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");

        // 1. Branch check
        var activeBranch = ReadGitBranch(workspace);
        if (!string.Equals(activeBranch, plan.Group.Branch, StringComparison.Ordinal))
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Branch mismatch",
                $"Cannot adopt: plan '{plan.Group.GroupId}' requires branch '{plan.Group.Branch}', but '{activeBranch}' is active.");
            return false;
        }

        // 2. Revision check
        var storedPlan = _planStore?.Load(plan.Group.GroupId);
        if (storedPlan is null)
        {
            ReportPlanActionIssue(plan.Group.GroupId, "Plan not found", "The durable plan is no longer available.");
            return false;
        }
        var currentRevision = storedPlan.Revision;
        var currentGroup = PendingDecomposePlanAdapter.FromPlan(storedPlan).Group with
        {
            HostRevision = currentRevision,
        };
        if (!string.Equals(currentRevision, plan.Revision, StringComparison.Ordinal))
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Revision mismatch",
                "The plan changed after these recovery controls were created. Reload the recovery panel.");
            return false;
        }

        // 3. Baseline commit
        var baselineCommit = _planStore?.Load(plan.Group.GroupId)?.InterruptionData?.LastCommit
            ?? _decomposeIterationBaselineCommit;
        if (string.IsNullOrWhiteSpace(baselineCommit))
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Baseline unknown",
                "Cannot adopt: the baseline commit is unknown. The plan may need to be retried from scratch.");
            return false;
        }

        // 4. Candidate commit discovery — exactly one commit expected
        var logOutput = await RunGitAsync(workspace, $"log --oneline \"{baselineCommit}..HEAD\"");
        string? candidateCommit;
        try
        {
            candidateCommit = RecoveryCommitValidator.ExtractSingleCandidateCommit(logOutput);
        }
        catch (InvalidOperationException ex)
        {
            ReportPlanActionIssue(plan.Group.GroupId, "Ambiguous commits", $"Cannot adopt: {ex.Message}");
            return false;
        }
        if (candidateCommit is null)
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Nothing to adopt",
                "No commits found between the baseline and HEAD. There is nothing to adopt.");
            return false;
        }

        // 5. Commit reachability
        try
        {
            await RunGitAsync(workspace, $"rev-parse --verify \"{candidateCommit}^{{commit}}\"");
        }
        catch
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Commit not reachable",
                $"Commit {candidateCommit} could not be verified as a reachable commit object.");
            return false;
        }

        // 6. Changed files from commit
        var changedFilesRaw = (await RunGitAsync(workspace,
            $"diff-tree --no-commit-id -r --name-only \"{candidateCommit}\""))
            .Replace("\r\n", "\n", StringComparison.Ordinal)
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);

        var hostOwnedPaths = await GetHostOwnedRecoveryPathsAsync(workspace);

        if (!RecoveryCommitValidator.ContainsOnlyNonHostChanges(changedFilesRaw, hostOwnedPaths))
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Suspicious commit",
                $"Commit {candidateCommit} has no task changes or also modifies SquadDash-owned state " +
                "(tasks.md or plan files). Use a source-only task commit before adopting it.");
            return false;
        }

        // 7. Downstream dependency check (warning only, not a blocker)
        var planTasks   = storedPlan.Tasks;
        var downstream  = RecoveryCommitValidator.FindDownstreamCompletedDependents(planTasks, taskId);
        var warningNote = downstream.Count > 0
            ? $"\n\n⚠ Warning: tasks that depend on {taskId} are already complete: " +
              string.Join(", ", downstream) + ". Verify there is no conflict."
            : string.Empty;

        // 8. Collect commit summary and request explicit user confirmation
        var commitSummaryLine = (await RunGitAsync(workspace,
            $"log --format=%H %s -1 \"{candidateCommit}\"")).Trim();
        var changedFilesList = string.Join("\n", changedFilesRaw.Select(f => $"  • {f}"));

        var confirmation = MessageBox.Show(
            this,
            $"Adopt this commit as the result for task {taskId}?\n\n" +
            $"Commit: {commitSummaryLine}\n\n" +
            $"Changed files:\n{changedFilesList}" +
            warningNote + "\n\n" +
            "SquadDash will record it as a completed step.",
            "Adopt Orphan Commit",
            MessageBoxButton.YesNo,
            MessageBoxImage.Question,
            MessageBoxResult.No);
        if (confirmation != MessageBoxResult.Yes) return false;

        // 9. Record the adoption
        var commitSummary = commitSummaryLine.Length > 8
            ? commitSummaryLine[8..].Trim()   // strip leading SHA prefix
            : commitSummaryLine;

        var syntheticResult = new DecomposeStepResult(
            GroupId:       plan.Group.GroupId,
            TaskId:        taskId,
            Revision:      plan.Revision,
            Status:        "complete",
            Commit:        candidateCommit,
            Summary:       $"Adopted by host recovery: {commitSummary}",
            RemainingWork: null,
            Verification:  null);

        // Update canonical plan progress, then refresh its Markdown view.
        if (_planStore is not null)
        {
            var updated = PlanStoreUpdater.ApplyStepAccepted(
                storedPlan,
                nextExecutingTaskId: null,
                syntheticResult);
            if (!TryPublishPlanProgress(updated, out var saveError))
            {
                ReportPlanActionIssue(
                    plan.Group.GroupId,
                    "Plan progress not saved",
                    "The commit was validated, but durable plan progress could not be saved. " +
                    (saveError ?? "Unknown persistence error") +
                    " The plan will remain stopped for recovery.");
                return false;
            }
            RefreshPlanProjectionBestEffort(updated, "orphan-commit-adopted");
        }

        LoadTasksPanel();
        ResolveRecoveryTranscript(
            $"✓ Recovery completed. Adopted committed work from {candidateCommit} and continued the plan.");

        // Resume the plan loop from the next pending task
        await StartBackloggedDecomposeGroupAsync(
            currentGroup with { HostRevision = currentRevision },
            continuationTaskId: null,
            continuationPaths: []);
        return true;
    }

    // ── Recovery action: Revert commit and retry ──────────────────────────────

    private async Task<bool> RevertAndRetryAsync(
        PlanRecoveryOption option,
        PendingDecomposePlan plan,
        string taskId)
    {
        if (_currentWorkspace is null) return false;
        var workspace = _currentWorkspace.FolderPath;
        var tasksPath = Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");

        // 1. Branch check
        var activeBranch = ReadGitBranch(workspace);
        if (!string.Equals(activeBranch, plan.Group.Branch, StringComparison.Ordinal))
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Branch mismatch",
                $"Cannot revert: plan '{plan.Group.GroupId}' requires branch '{plan.Group.Branch}', but '{activeBranch}' is active.");
            return false;
        }

        var currentPlan = _planStore?.Load(plan.Group.GroupId);
        if (currentPlan is null)
        {
            ReportPlanActionIssue(plan.Group.GroupId, "Plan not found", "The durable plan is no longer available.");
            return false;
        }

        // 2. Baseline and candidate commits
        var baselineCommit = _planStore?.Load(plan.Group.GroupId)?.InterruptionData?.LastCommit
            ?? _decomposeIterationBaselineCommit;

        string? candidateCommit = null;
        if (!string.IsNullOrWhiteSpace(baselineCommit))
        {
            var logOutput = await RunGitAsync(workspace, $"log --oneline \"{baselineCommit}..HEAD\"");
            try
            {
                candidateCommit = RecoveryCommitValidator.ExtractSingleCandidateCommit(logOutput);
            }
            catch (InvalidOperationException ex)
            {
                ReportPlanActionIssue(plan.Group.GroupId, "Ambiguous commits", $"Cannot revert: {ex.Message}");
                return false;
            }
        }

        if (candidateCommit is null)
        {
            // No commits between baseline and HEAD — just retry from scratch without reverting
            await RetryDecomposeTaskAsync(plan, taskId);
            return true;
        }

        // 3. Dependency safety check — refuse if downstream tasks are already complete
        var storedPlan = _planStore?.Load(plan.Group.GroupId);
        var planTasks  = storedPlan?.Tasks ?? [];
        var downstream = RecoveryCommitValidator.FindDownstreamCompletedDependents(planTasks, taskId);
        if (downstream.Count > 0)
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Revert blocked by dependents",
                $"Cannot revert: tasks that built on {taskId} are already complete: " +
                string.Join(", ", downstream) + ". Manually revert and fix the dependent tasks before retrying.");
            return false;
        }

        // 4. Explicit user authorization (required by spec)
        var authorization = MessageBox.Show(
            this,
            $"Revert commit {candidateCommit}?\n\n" +
            $"This will create a new git revert commit and then retry task {taskId} from scratch.\n" +
            "Caution: This operation modifies git history in a recoverable way but cannot be undone automatically.\n\n" +
            "The revert will be committed to the active branch before the retry starts.",
            "Authorize Revert and Retry",
            MessageBoxButton.YesNo,
            MessageBoxImage.Warning,
            MessageBoxResult.No);
        if (authorization != MessageBoxResult.Yes) return false;

        // 5. Execute recoverable revert (git revert --no-edit creates a revert commit)
        try
        {
            await RunGitAsync(workspace, $"revert --no-edit \"{candidateCommit}\"");
        }
        catch (Exception ex)
        {
            ReportPlanActionIssue(
                plan.Group.GroupId,
                "Revert failed",
                "Git revert failed; there may be merge conflicts. Resolve conflicts manually and retry. " + ex.Message);
            return false;
        }

        // Audit trail
        ShowSystemTranscriptEntry($"↩ Reverted {candidateCommit} and restarted task {taskId}.");

        // 7. Restart via normal loop
        await RetryDecomposeTaskAsync(plan, taskId);
        return true;
    }

    // ── Recovery action: Replan with current repository state ─────────────────

    private async Task ReplanWithCurrentStateAsync(
        PlanRecoveryOption option,
        PendingDecomposePlan plan,
        string taskId)
    {
        if (_currentWorkspace is null)
        {
            QueueDecomposeReplan(plan, taskId);
            return;
        }
        var workspace = _currentWorkspace.FolderPath;

        // Gather current HEAD and changed files to give the AI the full repository context
        var currentHead = string.Empty;
        var repoStateSummary = string.Empty;
        try
        {
            currentHead = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
            var baselineCommit = _planStore?.Load(plan.Group.GroupId)?.InterruptionData?.LastCommit
                ?? _decomposeIterationBaselineCommit;

            if (!string.IsNullOrWhiteSpace(baselineCommit) &&
                !string.Equals(baselineCommit, currentHead, StringComparison.OrdinalIgnoreCase))
            {
                var changedFiles = (await RunGitAsync(workspace,
                    $"diff --name-only \"{baselineCommit}..{currentHead}\"")).Trim();
                repoStateSummary =
                    $"Current HEAD: {currentHead}\n" +
                    $"Baseline (before interrupted iteration): {baselineCommit}\n" +
                    "Files changed since baseline:\n" +
                    (string.IsNullOrWhiteSpace(changedFiles) ? "(none)" : changedFiles);
            }
            else
            {
                repoStateSummary = $"Current HEAD: {currentHead}";
            }
        }
        catch
        {
            // Non-fatal — fall back to the plain replan if git calls fail
            QueueDecomposeReplan(plan, taskId);
            return;
        }

        var failedTask = plan.Group.Tasks.FirstOrDefault(t =>
            string.Equals(t.Id, taskId, StringComparison.Ordinal));
        if (failedTask is null)
        {
            QueueDecomposeReplan(plan, taskId);
            return;
        }

        QueueDecomposeReplan(plan, taskId, repoStateSummary);

        var shortHead = currentHead.Length >= 7 ? currentHead[..7] : currentHead;
        ShowSystemTranscriptEntry(
            $"✎ Replan draft created for task {taskId} with current repository state as baseline (HEAD: {shortHead}).");
    }

    private void OpenDecomposePlanAttachment(InboxAttachment attachment)
    {
        if (_currentWorkspace is null)
            return;

        PendingDecomposePlan? plan = null;
        Plan? durablePlan = null;
        if (!string.IsNullOrWhiteSpace(attachment.PlanGroupId))
        {
            durablePlan = string.Equals(attachment.PlanGroupId, DeveloperApprovalSimulator.PlanId, StringComparison.Ordinal)
                ? _developerApprovalSimulator?.CurrentPlan
                : _planStore?.Load(attachment.PlanGroupId);
            var live = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath)
                .Load(attachment.PlanGroupId);
            // Prefer the live plan when it exists — gate edits may have advanced the
            // revision beyond the snapshot embedded in the inbox attachment.
            if (live is not null)
                plan = live;
        }
        if (plan is null && durablePlan is not null)
            plan = PendingDecomposePlanAdapter.FromPlan(durablePlan);
        if (plan is null)
            DecomposePlanInbox.TryReadSnapshot(attachment, out plan);
        if (plan is null)
        {
            UIErrorHelper.ShowWarning("Plan Unavailable", "The attached task plan could not be loaded.");
            return;
        }

        OpenDecomposePlanViewer(plan, durablePlan);
    }

    private DecomposedTaskGroup? ResolveInboxPlanGroupForThumbnail(string groupId)
    {
        if (_currentWorkspace is null || string.IsNullOrWhiteSpace(groupId))
            return null;

        var durablePlan = _planStore?.Load(groupId);
        if (durablePlan is not null)
            return PendingDecomposePlanAdapter.FromPlan(durablePlan).Group;

        var pendingPlan = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Load(groupId);
        return pendingPlan?.Group;
    }

    private Dictionary<string, double>? ResolveLayoutNudgesForThumbnail(string groupId)
    {
        if (_currentWorkspace is null || string.IsNullOrWhiteSpace(groupId))
            return null;

        return new PlanVisualizerLayoutStore(_currentWorkspace.SquadFolderPath).Load(groupId);
    }

    private bool IsPlanExecuted(string groupId)
    {
        if (string.IsNullOrWhiteSpace(groupId) || _planStore is null)
            return false;

        var plan = _planStore.Load(groupId);
        if (plan is null)
            return false;

        return plan.LifecycleStatus is not
            (PlanLifecycleStatus.Approved or PlanLifecycleStatus.WaitingForCleanWorktree);
    }

    private void OpenInboxPlanViewerByGroupId(string groupId)
    {
        if (_currentWorkspace is null || string.IsNullOrWhiteSpace(groupId))
            return;

        Plan? durablePlan = string.Equals(groupId, DeveloperApprovalSimulator.PlanId, StringComparison.Ordinal)
            ? _developerApprovalSimulator?.CurrentPlan
            : _planStore?.Load(groupId);
        var pendingPlan = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Load(groupId);
        var plan = pendingPlan ??
                   (durablePlan is not null ? PendingDecomposePlanAdapter.FromPlan(durablePlan) : null);
        if (plan is null)
        {
            UIErrorHelper.ShowWarning("Plan Unavailable", "The linked plan could not be loaded.");
            return;
        }

        OpenDecomposePlanViewer(plan, durablePlan);
    }

    // ── Loop config flyout helpers ───────────────────────────────────────────

    private void _LoopConfigFlyout_Opened(object sender, EventArgs e)
    {
        // Right-align popup's right edge with StartLoopButton's right edge.
        // ActualWidth is valid here because the popup has already been laid out.
        Dispatcher.InvokeAsync(() =>
        {
            _loopConfigFlyout.HorizontalOffset =
                StartLoopButton.ActualWidth - _loopConfigFlyoutBorder.ActualWidth;
        }, System.Windows.Threading.DispatcherPriority.Render);
    }

    private void OpenLoopConfigFlyout(string loopMdPath, LoopConfigFlyoutMode mode, LoopMdConfig? existingConfig)
    {
        _loopMdPathForConfig   = loopMdPath;
        _loopConfigFlyoutMode  = mode;

        LoopConfigIntervalBox.ClearValue(System.Windows.Controls.TextBox.BorderBrushProperty);
        LoopConfigTimeoutBox.ClearValue(System.Windows.Controls.TextBox.BorderBrushProperty);

        if (mode == LoopConfigFlyoutMode.Edit && existingConfig is not null)
        {
            LoopConfigHeaderText.Text     = "Edit loop settings:";
            LoopConfigIntervalBox.Text    = ((int)existingConfig.IntervalMinutes).ToString();
            LoopConfigTimeoutBox.Text     = ((int)existingConfig.TimeoutMinutes).ToString();
            LoopConfigDescriptionBox.Text = existingConfig.Description;
        }
        else
        {
            LoopConfigHeaderText.Text     = "loop.md is not configured. Click OK to start the loop with this configuration:";
            LoopConfigIntervalBox.Text    = "1";
            LoopConfigTimeoutBox.Text     = "60";
            LoopConfigDescriptionBox.Text = "My loop";
        }

        _loopConfigFlyout.PlacementTarget = StartLoopButton;
        _loopConfigFlyout.IsOpen = true;
    }

    private async void LoopConfigOk_Click(object sender, RoutedEventArgs e)
    {
        // Validate interval
        if (!int.TryParse(LoopConfigIntervalBox.Text.Trim(), out var interval) || interval <= 0)
        {
            LoopConfigIntervalBox.SetResourceReference(System.Windows.Controls.TextBox.BorderBrushProperty, "SystemErrorText");
            return;
        }
        LoopConfigIntervalBox.ClearValue(System.Windows.Controls.TextBox.BorderBrushProperty);

        // Validate timeout
        if (!int.TryParse(LoopConfigTimeoutBox.Text.Trim(), out var timeout) || timeout <= 0)
        {
            LoopConfigTimeoutBox.SetResourceReference(System.Windows.Controls.TextBox.BorderBrushProperty, "SystemErrorText");
            return;
        }
        LoopConfigTimeoutBox.ClearValue(System.Windows.Controls.TextBox.BorderBrushProperty);

        var description = LoopConfigDescriptionBox.Text.Trim();
        if (string.IsNullOrEmpty(description))
            description = "My loop";

        var loopMdPath = _loopMdPathForConfig;
        if (loopMdPath is null) return;

        var frontmatter = $"""
            ---
            configured: true
            interval: {interval}
            timeout: {timeout}
            description: "{description}"
            commands: [stop_loop]
            ---

            """;

        var existingContent = File.Exists(loopMdPath)
            ? await File.ReadAllTextAsync(loopMdPath)
            : string.Empty;

        // Strip old frontmatter so we don't double-up when editing an already-configured file.
        var bodyContent = _loopConfigFlyoutMode == LoopConfigFlyoutMode.Edit
            ? LoopMdParser.StripFrontmatter(existingContent)
            : existingContent;

        await File.WriteAllTextAsync(loopMdPath, frontmatter + (bodyContent.Length > 0 ? "\n" + bodyContent : ""));

        _loopConfigFlyout.IsOpen = false;

        if (_loopConfigFlyoutMode == LoopConfigFlyoutMode.Edit)
        {
            // Just refresh the picker labels to reflect the new description.
            PopulateLoopFilePicker();
            RefreshLoopOptionsPanel();
            UpdateLoopFileSubtitle();
            return;
        }

        try
        {
            await StartLoopImmediateAsync();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(LoopConfigOk_Click), ex);
        }
    }

    private void LoopConfigCancel_Click(object sender, RoutedEventArgs e)
    {
        _loopConfigFlyout.IsOpen = false;
    }

    // ── CommitApproval helpers ────────────────────────────────────────────────

    // Matches " committed <sha>" near the end of a notification summary, optionally preceded
    // by punctuation. Covers: ", committed abc1234.", "; committed abc1234", " committed abc1234."
    // The SHA is identified as a run of hex characters (5+) so the word "committed" in ordinary
    // prose is not accidentally stripped.
    private static readonly Regex _committedSuffixRe =
        new(@"[,;.]?\s+committed\s+[0-9a-f]{5,}\S*\.?\s*$", RegexOptions.IgnoreCase | RegexOptions.Compiled);

    // Matches "Committed" + optional SHA + optional punctuation at the START of an approval description.
    // e.g. "Committed d2d48a8: Fixed login bug" → "Fixed login bug"
    //      "Committed: Fixed login bug"         → "Fixed login bug"
    //      "Committed Fixed login bug"           → "Fixed login bug"
    private static readonly Regex _committedPrefixRe =
        new(@"^committed(\s+[0-9a-f]{5,}[^\w\s]*)?\s*[,;:!?]*\s+", RegexOptions.IgnoreCase | RegexOptions.Compiled);

    // Matches " as <commit-code><punctuation>" at the end of a notification summary.
    // e.g. "Fixed the login bug as abc1234.", "Refactored auth as 3f9a2bc,"
    private static readonly Regex _asCommitSuffixRe =
        new(@"\s+as\s+[0-9a-f]{5,}\S*[.,;:!?]*\s*$", RegexOptions.IgnoreCase | RegexOptions.Compiled);

    private static string BuildApprovalDescription(string? notifSummary, string? prompt)
    {
        if (!string.IsNullOrWhiteSpace(notifSummary))
        {
            var s = notifSummary.Trim();
            // Strip leading "Committed <sha><punct> " — the SHA is shown separately in the panel.
            s = _committedPrefixRe.Replace(s, string.Empty);
            // Strip trailing "<punct> committed XXXXXXX." —
            // the commit SHA link is already shown separately in the panel.
            var m = _committedSuffixRe.Match(s);
            if (m.Success)
                s = s[..m.Index].TrimEnd().TrimEnd('.').Trim();
            // Strip trailing " as <sha><punct>" — same reason.
            var m2 = _asCommitSuffixRe.Match(s);
            if (m2.Success)
                s = s[..m2.Index].TrimEnd().TrimEnd('.').Trim();
            return s;
        }
        if (string.IsNullOrWhiteSpace(prompt))
            return "Commit";
        var words = prompt.Split(' ', StringSplitOptions.RemoveEmptyEntries);
        return words.Length <= 8
            ? string.Join(' ', words)
            : string.Join(' ', words[..8]) + "…";
    }

    private static string? TruncatePromptHint(string? prompt, int maxChars) =>
        string.IsNullOrWhiteSpace(prompt) ? null
            : prompt.Length <= maxChars ? prompt.Trim()
            : prompt[..maxChars].Trim() + "…";

    private static bool CommitTouchesDecisionsFile(string sha, string workingDirectory)
    {
        try
        {
            using var proc = new System.Diagnostics.Process();
            proc.StartInfo = new System.Diagnostics.ProcessStartInfo("git",
                $"diff-tree --no-commit-id -r --name-only {sha}")
            {
                RedirectStandardOutput = true,
                UseShellExecute        = false,
                CreateNoWindow         = true,
                WorkingDirectory       = workingDirectory,
            };
            proc.Start();
            string output = proc.StandardOutput.ReadToEnd();
            proc.WaitForExit(3000);
            return output.Contains(".squad/decisions.md", StringComparison.OrdinalIgnoreCase);
        }
        catch
        {
            return false;
        }
    }

    private void OnApprovalItemChanged(CommitApprovalItem updated)
    {
        var idx = _approvalItems.FindIndex(i => i.Id == updated.Id);
        if (idx >= 0) _approvalItems[idx] = updated;
        _approvalStore?.Save(_approvalItems);
    }

    private void OnApprovalItemsRemoved(IReadOnlyList<CommitApprovalItem> removed)
    {
        foreach (var r in removed)
            _approvalItems.RemoveAll(i => i.Id == r.Id);
        _approvalStore?.Save(_approvalItems);
    }

    private void ScrollToApprovalTurn(CommitApprovalItem item)
    {
        var turnStartedAt = item.TurnStartedAt;

        // Dismiss any previous not-found popup immediately.
        DismissApprovalNotFoundPopup();

        // Capture mouse position now (on the UI thread during click handling) so the popup
        // can be positioned correctly even after the async retry completes.
        var relPos = Mouse.GetPosition(this);
        var screenPos = PointToScreen(relPos);

        // Ensure the coordinator transcript is visible in the main panel —
        // the prompt paragraphs live in CoordinatorThread's document.
        if (!ReferenceEquals(_selectedTranscriptThread, CoordinatorThread))
            SelectTranscriptThread(CoordinatorThread);

        var entry = CoordinatorThread.PromptParagraphs
            .FirstOrDefault(e => e.Timestamp == turnStartedAt);
        if (entry is not null)
        {
            ScrollToPromptParagraph(entry.Paragraph);
            return;
        }

        // The turn may exist but not yet be rendered (virtual window only shows recent turns).
        // Find its index in the full list and use EnsureTurnRenderedAsync to load batches until
        // it becomes visible, then scroll to it.
        _ = Dispatcher.BeginInvoke(async () =>
        {
            var turnIndex = _conversationManager.FindCoordinatorTurnIndexByTimestamp(turnStartedAt);
            if (turnIndex >= 0)
            {
                await _conversationManager.EnsureTurnRenderedAsync(turnIndex);
                var retryEntry = CoordinatorThread.PromptParagraphs
                    .FirstOrDefault(e => e.Timestamp == turnStartedAt);
                if (retryEntry is not null)
                {
                    ScrollToPromptParagraph(retryEntry.Paragraph);
                    return;
                }
            }
            // Only show the not-found popup if the turn truly doesn't exist in the transcript.
            ShowApprovalNotFoundPopup(screenPos, relPos, item.OriginalPrompt ?? item.TurnPromptHint);
        });
    }

    private void DismissApprovalNotFoundPopup()
    {
        if (_approvalNotFoundPopup is { IsOpen: true } p)
        {
            p.IsOpen = false;
            _approvalNotFoundPopup = null;
        }
    }

    private void ShowApprovalNotFoundPopup(System.Windows.Point screenPoint, System.Windows.Point windowOrigin, string? promptText)
    {
        // Dismiss any prior popup before showing a new one.
        DismissApprovalNotFoundPopup();

        // SetResourceReference doesn't work on Popup children that aren't in the logical tree.
        // Resolve brushes directly from the window's live merged resource dictionaries instead.
        var bgBrush = (TryFindResource("PopupSurface") as Brush) ?? new SolidColorBrush(Color.FromRgb(0x30, 0x2C, 0x28));
        var borderBrush = (TryFindResource("PopupBorder") as Brush) ?? new SolidColorBrush(Color.FromRgb(0x55, 0x4E, 0x47));
        var fgBrush = (TryFindResource("LabelText") as Brush) ?? Brushes.White;
        var subtleBrush = (TryFindResource("SubtleText") as Brush) ?? Brushes.LightGray;

        var stack = new StackPanel { Margin = new Thickness(10, 7, 10, 7) };

        var msgBlock = new TextBlock
        {
            Text = "Entry not found in transcript.",
            Foreground = fgBrush,
            FontWeight = FontWeights.SemiBold,
        };
        stack.Children.Add(msgBlock);

        if (!string.IsNullOrWhiteSpace(promptText))
        {
            var promptLabel = new TextBlock
            {
                Text = "Prompt:",
                Foreground = subtleBrush,
                Margin = new Thickness(0, 6, 0, 2),
            };
            promptLabel.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeXSmall");
            stack.Children.Add(promptLabel);

            var hintBlock = new TextBlock
            {
                Text = promptText,
                TextWrapping = TextWrapping.Wrap,
                MaxWidth = 340,
                Foreground = subtleBrush,
                FontStyle = FontStyles.Italic,
            };
            var scrollViewer = new ScrollViewer
            {
                Content = hintBlock,
                MaxHeight = 260,
                MaxWidth = 340,
                VerticalScrollBarVisibility = System.Windows.Controls.ScrollBarVisibility.Auto,
                HorizontalScrollBarVisibility = System.Windows.Controls.ScrollBarVisibility.Disabled,
            };
            stack.Children.Add(scrollViewer);
        }

        var border = new Border
        {
            Child = stack,
            Background = bgBrush,
            BorderBrush = borderBrush,
            CornerRadius = new CornerRadius(5),
            BorderThickness = new Thickness(1),
            Effect = new System.Windows.Media.Effects.DropShadowEffect
            {
                BlurRadius = 8,
                ShadowDepth = 2,
                Opacity = 0.35,
                Color = Colors.Black,
            },
        };

        var popup = new System.Windows.Controls.Primitives.Popup
        {
            Child = border,
            Placement = System.Windows.Controls.Primitives.PlacementMode.AbsolutePoint,
            HorizontalOffset = screenPoint.X,
            VerticalOffset = screenPoint.Y + 18,
            AllowsTransparency = true,
            StaysOpen = true,
            IsOpen = true,
        };
        _approvalNotFoundPopup = popup;

        bool dismissed = false;

        void FadeAndClose()
        {
            if (dismissed) return;
            dismissed = true;
            MouseMove -= OnWindowMouseMoved;
            var fade = new System.Windows.Media.Animation.DoubleAnimation(
                fromValue: 1.0,
                toValue: 0.0,
                duration: new Duration(TimeSpan.FromSeconds(0.4)),
                fillBehavior: System.Windows.Media.Animation.FillBehavior.Stop);
            fade.Completed += (_, _) =>
            {
                popup.IsOpen = false;
                if (ReferenceEquals(_approvalNotFoundPopup, popup))
                    _approvalNotFoundPopup = null;
            };
            border.BeginAnimation(UIElement.OpacityProperty, fade);
        }

        // Dismiss only once the mouse has moved ≥10 px from the original click position.
        // This prevents the popup from vanishing the instant the cursor drifts by a pixel or two.
        void OnWindowMouseMoved(object? sender, System.Windows.Input.MouseEventArgs e)
        {
            var pos = e.GetPosition(this);
            var dx  = pos.X - windowOrigin.X;
            var dy  = pos.Y - windowOrigin.Y;
            if (dx * dx + dy * dy >= 100.0) // 10 px radius
                FadeAndClose();
        }

        MouseMove += OnWindowMouseMoved;
    }

    // ─────────────────────────────────────────────────────────────────────────

    private void InitializeHostCommands()
    {
        _hostCommandExecutor = new HostCommandExecutor();
        var startLoopHandler = new Commands.StartLoopCommandHandler(() =>
        {
            if (!_loopController.IsRunning)
                _ = StartLoopImmediateAsync();
        });
        startLoopHandler.OnGroupIdExtracted = groupId =>
        {
            if (!_loopController.IsRunning)
                _ = StartDecomposeLoopAsync(groupId);
        };
        _hostCommandExecutor.Register(startLoopHandler);
        _hostCommandExecutor.Register(new Commands.StopLoopCommandHandler(() =>
        {
            SuppressLoopResumeAfterExplicitStop("host-command");
            _loopController.RequestStop();
            _loopFollowUpTcs?.TrySetResult(true); // unblock any follow-up wait
        }));
        _hostCommandExecutor.Register(new Commands.GetQueueStatusCommandHandler(() => _promptQueue.Items));
        _hostCommandExecutor.Register(new Commands.OpenPanelCommandHandler(panelName =>
        {
            switch (panelName.Trim().ToLowerInvariant())
            {
                case "approvals": ShowApprovalPanel(); break;
                case "tasks": ShowTasksStatusWindow(); break;
                case "trace": ShowTraceWindow(); break;
                case "health": ShowScreenshotHealthWindow(); break;
                case "inbox": ShowInboxPanel(); break;
            }
        }));
        _hostCommandExecutor.Register(new Commands.InjectTextCommandHandler(_ =>
        {
            // Text injection is handled by the done-event handler via InjectResultAsContext behavior.
        }));
        _hostCommandExecutor.Register(new Commands.ClearApprovedCommandHandler(() =>
        {
            _approvalItems.Clear();
            _pendingApprovalGroupsBySha.Clear();
            _approvalStore?.Save(_approvalItems);
            _approvalPanel?.ReplaceAllItems(_approvalItems);
        }));
        _hostCommandExecutor.Register(new Commands.TriggerIdleCycleCommandHandler(() =>
        {
            _idleDetectionService?.ForceIdle();
        }));
        _hostCommandExecutor.Register(new Commands.OrganizeApprovalsCommandHandler(assignments =>
        {
            bool anyChanged = false;
            var toAnnotate = new List<(string Sha, string Group)>();
            foreach (var (sha, group) in assignments)
            {
                var idx = _approvalItems.FindIndex(i =>
                    i.CommitSha.StartsWith(sha, StringComparison.OrdinalIgnoreCase) ||
                    sha.StartsWith(i.CommitSha, StringComparison.OrdinalIgnoreCase));
                if (idx < 0) continue;
                _approvalItems[idx] = _approvalItems[idx] with { FeatureGroup = group };
                _featureGroupStore?.EnsureGroup(group);
                toAnnotate.Add((sha, group));
                anyChanged = true;
            }
            if (anyChanged)
            {
                _approvalStore?.Save(_approvalItems);
                _approvalPanel?.ReplaceAllItems(_approvalItems);
            }
            // Defer annotation by one layout pass: the "Committed: sha" paragraph is written
            // in the same response as this HOST_COMMAND_JSON block, so RenderResponseEntry
            // may not have added it to Document.Blocks yet when this handler fires.
            Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded, () =>
            {
                foreach (var (sha, group) in toAnnotate)
                    AnnotateCommitInTranscript(sha, group);
            });
        }));
        _hostCommandExecutor.Register(new Commands.MergeFeatureCategoriesCommandHandler(ApplyFeatureCategoryMerges));

        _agentThreadRegistry.OnAgentApprovalGroup = (sha, group) =>
        {
            var idx = FindApprovalItemIndexBySha(sha);
            if (idx < 0)
            {
                _pendingApprovalGroupsBySha[sha] = group;
                return;
            }
            _approvalItems[idx] = _approvalItems[idx] with { FeatureGroup = group };
            _featureGroupStore?.EnsureGroup(group);
            AnnotateCommitInTranscript(sha, group);
            _approvalStore?.Save(_approvalItems);
            _approvalPanel?.ReplaceAllItems(_approvalItems);
        };

        _pec.GetHostCommandCatalogInstruction = () =>
            _hostCommandRegistry.BuildCatalogInstruction(_currentWorkspace?.FolderPath);
    }

    private int FindApprovalItemIndexBySha(string sha)
    {
        if (string.IsNullOrWhiteSpace(sha))
            return -1;

        return _approvalItems.FindIndex(i => ShaMatches(i.CommitSha, sha));
    }

    /// <summary>
    /// Applies AI-assigned categories from the Commit Viewer back to the approval store.
    /// Only updates items that are not yet categorized (FeatureGroup is null/empty).
    /// </summary>
    private void ApplyCommitCategories(IReadOnlyList<(string Sha, string Group)> assignments)
    {
        bool changed = false;
        foreach (var (sha, group) in assignments)
        {
            var idx = _approvalItems.FindIndex(i =>
                string.Equals(i.CommitSha, sha, StringComparison.OrdinalIgnoreCase) ||
                i.CommitSha.StartsWith(sha, StringComparison.OrdinalIgnoreCase) ||
                sha.StartsWith(i.CommitSha, StringComparison.OrdinalIgnoreCase));
            if (idx >= 0 && string.IsNullOrWhiteSpace(_approvalItems[idx].FeatureGroup))
            {
                _approvalItems[idx] = _approvalItems[idx] with { FeatureGroup = group };
                _featureGroupStore?.EnsureGroup(group);
                changed = true;
            }
        }
        if (changed)
        {
            _approvalStore?.Save(_approvalItems);
            _approvalPanel?.ReplaceAllItems(_approvalItems);
        }
    }

    private static bool ShaMatches(string storedSha, string candidateSha)
    {
        if (string.IsNullOrWhiteSpace(storedSha) || string.IsNullOrWhiteSpace(candidateSha))
            return false;

        return storedSha.StartsWith(candidateSha, StringComparison.OrdinalIgnoreCase) ||
               candidateSha.StartsWith(storedSha, StringComparison.OrdinalIgnoreCase);
    }

    private string? TakePendingApprovalGroup(string sha)
    {
        if (string.IsNullOrWhiteSpace(sha) || _pendingApprovalGroupsBySha.Count == 0)
            return null;

        foreach (var (pendingSha, group) in _pendingApprovalGroupsBySha.ToArray())
        {
            if (!ShaMatches(pendingSha, sha))
                continue;

            _pendingApprovalGroupsBySha.Remove(pendingSha);
            return group;
        }

        return null;
    }

    /// <summary>
    /// Handles a <c>{"squadash": {"command": "..."}}</c> payload extracted from an AI response.
    /// Must be called on the UI thread (invoked from the SDK event dispatcher).
    /// </summary>
    private void HandleSquadashCommand(string command)
    {
        switch (command.Trim().ToLowerInvariant())
        {
            case "stop_loop":
                if (_loopController.IsRunning)
                {
                    AppendLoopOutputLine(
                        "🤖 AI requested loop stop — finishing current iteration then halting.",
                        LoopLifecycleBrush);
                    SuppressLoopResumeAfterExplicitStop("squadash-command");
                    _loopController.RequestStop();
                    _loopFollowUpTcs?.TrySetResult(true); // unblock any follow-up wait
                    SyncLoopPanel();
                    _ = _pushNotificationService.NotifyEventAsync("squadash_command", "SquadDash", "AI command: stop_loop");
                }
                break;

            case "start_loop":
                if (!_loopController.IsRunning)
                {
                    AppendLoopOutputLine("🤖 AI requested loop start.", LoopLifecycleBrush);
                    _ = QueueOrStartLoopAsync(LoopMode.NativeAgents);
                    _ = _pushNotificationService.NotifyEventAsync("squadash_command", "SquadDash", "AI command: start_loop");
                }
                break;
        }
    }

    private async void StopLoopButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_loopQueued && !IsLoopRunning)
            {
                SuppressLoopResumeAfterExplicitStop("dequeue-button");
                _loopQueued = false;
                _conversationManager.UpdateQueuedPromptsState(
                    _promptQueue.Items, _followUpAttachments,
                    queueRightmostHeld: IsRightmostQueueTabActive(),
                    loopQueuedToDequeue: false,
                    activeDraftSimEntry: _pec.ActiveDraftSimEntry,
                    activeTabIndex: GetActiveQueueTabIndex());
                AppendLoopOutputLine($"⏹ Loop dequeued — {LoopTimestamp()} — will not resume after queue drains.", LoopLifecycleBrush);
                SyncLoopPanel();
                return;
            }
            SuppressLoopResumeAfterExplicitStop("stop-button");
            if (_activeLoopMode == LoopMode.NativeAgents)
            {
                AppendLoopOutputLine("⏹ Clean loop termination requested — current iteration will finish then stop.", LoopLifecycleBrush);
                _loopController.RequestStop();
                _loopFollowUpTcs?.TrySetResult(true); // unblock any follow-up wait so stop is honoured promptly
                SyncLoopPanel();
            }
            else
            {
                AppendLoopOutputLine("⏹ Clean loop termination requested — current iteration will finish then stop.", LoopLifecycleBrush);
                await _bridge.StopLoopAsync();
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(StopLoopButton_Click), ex);
        }
    }

    private void LoopContinuousContextCheckBox_Click(object sender, RoutedEventArgs e)
    {
        _settingsManager.Replace(_settingsStore.SaveLoopContinuousContext(
            LoopContinuousContextCheckBox.IsChecked == true));
        _conversationManager.UpdateLoopSettingsState(_activeLoopMode, _settingsSnapshot.LoopContinuousContext);
    }

    private async void AbortLoopButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var result = MessageBox.Show(
                "Abort the current agent and stop the loop immediately? The current iteration's work may be incomplete.",
                "Abort Loop",
                MessageBoxButton.OKCancel,
                MessageBoxImage.Warning);
            if (result == MessageBoxResult.OK)
            {
                AppendLoopOutputLine("⚡ Loop abruptly terminated via Abort — current iteration may be incomplete.", new SolidColorBrush(Color.FromRgb(0xFF, 0x88, 0x44)));
                SuppressLoopResumeAfterExplicitStop("abort-button");
                if (_activeLoopMode == LoopMode.NativeAgents)
                {
                    _loopController.RequestAbort();
                    _loopFollowUpTcs?.TrySetResult(false); // unblock any follow-up wait so abort takes effect
                }
                else
                    await _bridge.StopLoopAsync();
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(AbortLoopButton_Click), ex);
        }
    }

    private static bool ShouldSuppressSilentBackgroundAgent(SquadSdkEvent evt) =>
        SilentBackgroundAgentPolicy.ShouldSuppressThread(evt.AgentId, evt.AgentName, evt.AgentDisplayName);


    private static readonly string[] SlashCommands = [
        "/activate", "/agents", "/approval", "/clear", "/deactivate", "/doctor", "/dropTasks",
        "/cast", "/health", "/help", "/hire", "/maintenance", "/model", "/plan", "/queue-sim", "/resume", "/retire",
        "/session", "/sessions", "/status", "/tasks", "/test-queue", "/trace", "/version"
    ];

    private void SyncAgentCardsWithThreads()
    {
        foreach (var thread in _agentThreadRegistry.ThreadOrder)
        {
            _agentThreadRegistry.NormalizeThreadAgentIdentity(thread);
            _agentThreadRegistry.NormalizeInactiveThreadState(thread);
        }

        EnsureDynamicAgentCards();
        UpdateAvatarSizes();
        UpdateAgentCardVisibility();

        foreach (var card in _agents)
        {
            card.IsTranscriptTargetSelected = false;
            if (!card.IsLeadAgent)
                card.Threads.Clear();
        }

        // Reset IsSecondaryPanelOpen on all threads before re-sync
        foreach (var thread in _agentThreadRegistry.ThreadOrder)
            thread.IsSecondaryPanelOpen = false;

        foreach (var thread in _agentThreadRegistry.ThreadOrder.OrderBy(candidate => candidate.StartedAt))
        {
            var card = FindAgentCardForThread(thread);
            if (card is null)
                continue;

            card.Threads.Add(thread);
        }

        RefreshSecondaryTranscriptEntries();
        SyncSelectionControllerWithUiState("SyncAgentCardsWithThreads");
        SyncTranscriptTargetIndicators();

        foreach (var card in _agents)
            SyncCardThreads(card);

        SyncAgentCardBuckets();
        // Re-derive IsSecondaryPanelOpen from live secondary panels
        foreach (var entry in _secondaryTranscripts)
            entry.Thread.IsSecondaryPanelOpen = true;
        UpdateTranscriptThreadBadge();
        ScheduleAgentPanelLayoutRefresh();
        SchedulePrimaryAgentHostWarmup();
    }

    private void EnsureDynamicAgentCards()
    {
        var existingDynamicCards = _agents
            .Where(card => card.IsDynamicAgent)
            .ToArray();
        foreach (var dynamicCard in existingDynamicCards)
            _agents.Remove(dynamicCard);

        var now = DateTimeOffset.Now;
        var inactiveAllowance = DynamicAgentHistoryCardLimit;
        foreach (var thread in _agentThreadRegistry.ThreadOrder
                     .Where(candidate => BackgroundTaskPresenter.ShouldSurfaceDynamicAgentCard(candidate, now, DynamicAgentHistoryRetention))
                     .GroupBy(candidate => candidate.Title, StringComparer.OrdinalIgnoreCase)
                     .Select(group => group.OrderByDescending(AgentThreadRegistry.GetThreadLastActivityAt).First())
                     .OrderByDescending(_backgroundTaskPresenter.IsThreadActiveForDisplay)
                     .ThenByDescending(AgentThreadRegistry.GetThreadLastActivityAt))
        {
            if (!_backgroundTaskPresenter.IsThreadActiveForDisplay(thread))
            {
                if (now - AgentThreadRegistry.GetThreadLastActivityAt(thread) > DynamicAgentHistoryRetention)
                    continue;

                if (inactiveAllowance <= 0)
                    continue;

                inactiveAllowance--;
            }

            if (FindAgentCardForThread(thread, includeDynamicCards: false) is not null)
                continue;

            var card = new AgentStatusCard(
                thread.Title,
                GetAgentInitial(thread.Title),
                string.IsNullOrWhiteSpace(thread.AgentType) ? "Background Agent" : AgentThreadRegistry.HumanizeAgentName(thread.AgentType),
                thread.StatusText,
                string.Empty,
                thread.DetailText,
                DynamicAgentDefaultAccentHex,
                accentStorageKey: "dynamic:" + thread.Title,
                isDynamicAgent: true);
            ApplyAgentAccent(card, ResolveAgentAccentHex(card, isLeadAgent: false), persist: false);
            // Tour demo agents with a command-specified color always win over the default and user-set colors.
            if (thread.IsTourDemoThread && !string.IsNullOrWhiteSpace(thread.TourDemoAccentHex))
                ApplyAgentAccent(card, thread.TourDemoAccentHex, persist: false);
            ApplyAgentImage(card, ResolveAgentImagePath(card), persist: false);
            _agents.Add(card);
        }
    }

    private AgentStatusCard? FindAgentCardForThread(
        TranscriptThreadState thread,
        bool includeDynamicCards = true)
    {
        return _agents.FirstOrDefault(card =>
            !card.IsLeadAgent &&
            (includeDynamicCards || !card.IsDynamicAgent) &&
            CardMatchesThread(card, thread));
    }

    private static bool CardMatchesThread(AgentStatusCard card, TranscriptThreadState thread)
    {
        if (!card.IsDynamicAgent && AgentThreadRegistry.HasRosterBackedIdentity(thread) &&
            !string.Equals(card.AccentStorageKey, thread.AgentCardKey?.Trim(), StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        if (!string.IsNullOrWhiteSpace(thread.AgentCardKey) &&
            string.Equals(card.AccentStorageKey, thread.AgentCardKey.Trim(), StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (!string.IsNullOrWhiteSpace(thread.AgentDisplayName) &&
            string.Equals(card.Name, thread.AgentDisplayName.Trim(), StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        if (!string.IsNullOrWhiteSpace(thread.AgentName))
        {
            if (string.Equals(card.AccentStorageKey, thread.AgentName.Trim(), StringComparison.OrdinalIgnoreCase))
                return true;

            if (string.Equals(card.Name, AgentThreadRegistry.HumanizeAgentName(thread.AgentName), StringComparison.OrdinalIgnoreCase))
                return true;
        }

        if (!string.IsNullOrWhiteSpace(thread.AgentId))
        {
            if (string.Equals(card.AccentStorageKey, thread.AgentId.Trim(), StringComparison.OrdinalIgnoreCase))
                return true;

            if (string.Equals(card.Name, AgentThreadRegistry.HumanizeAgentName(thread.AgentId), StringComparison.OrdinalIgnoreCase))
                return true;
        }

        if (!string.IsNullOrWhiteSpace(thread.Title) &&
            string.Equals(card.Name, AgentThreadRegistry.HumanizeAgentName(thread.Title), StringComparison.OrdinalIgnoreCase))
        {
            return true;
        }

        return string.Equals(card.Name, thread.Title, StringComparison.OrdinalIgnoreCase);
    }

    private TranscriptThreadState? GetPrimaryThread(AgentStatusCard card)
    {
        var threads = card.Threads
            .Where(thread => !thread.IsPlaceholderThread)
            .ToArray();

        var currentRunThread = threads
            .Where(_backgroundTaskPresenter.IsThreadCurrentRunForDisplay)
            .OrderByDescending(AgentThreadRegistry.GetThreadLastActivityAt)
            .ThenByDescending(thread => thread.StartedAt)
            .FirstOrDefault();
        if (currentRunThread is not null)
            return currentRunThread;

        return threads
            .OrderByDescending(AgentThreadRegistry.GetThreadLastActivityAt)
            .ThenByDescending(thread => thread.StartedAt)
            .FirstOrDefault();
    }

    private string BuildAgentCardDisplayName(
        AgentStatusCard card,
        TranscriptThreadState? primaryThread,
        DateTimeOffset now)
    {
        if (primaryThread is null || !_backgroundTaskPresenter.IsThreadCurrentRunForDisplay(primaryThread))
            return card.Name;

        return StatusTimingPresentation.AppendRunningSuffix(card.Name, primaryThread.StartedAt, now);
    }

    private static string BuildAgentCardStatusText(TranscriptThreadState thread, DateTimeOffset now)
    {
        return BuildTimedStatusText(thread.StatusText, thread.StartedAt, thread.CompletedAt, now);
    }

    private static bool IsStickyTerminalBackgroundStatus(string? statusText)
    {
        if (string.IsNullOrWhiteSpace(statusText))
            return false;

        return statusText.Trim() switch
        {
            "Failed" => true,
            "Cancelled" => true,
            _ => false
        };
    }

    private static bool ShouldDisplayTerminalAgentStatus(TranscriptThreadState thread, DateTimeOffset now)
    {
        if (IsStickyTerminalBackgroundStatus(thread.StatusText))
            return true;

        return string.Equals(thread.StatusText?.Trim(), "Completed", StringComparison.OrdinalIgnoreCase)
            && now - AgentThreadRegistry.GetThreadLastActivityAt(thread) <= AgentActiveDisplayLinger;
    }

    private void SyncCardThreads(AgentStatusCard card, DateTimeOffset? nowOverride = null)
    {
        var now = nowOverride ?? DateTimeOffset.Now;
        var orderedThreads = card.Threads
            .OrderByDescending(thread => thread.StartedAt)
            .ToArray();

        var visibleChipLimit = 3;
        var chipIndex = 0;
        foreach (var orderedThread in orderedThreads)
        {
            if (AgentThreadRegistry.HasMeaningfulThreadTranscript(orderedThread))
            {
                chipIndex++;
                orderedThread.SequenceNumber = chipIndex;
                orderedThread.ChipVisibility = chipIndex <= visibleChipLimit
                    ? Visibility.Visible
                    : Visibility.Collapsed;
            }
            else
            {
                orderedThread.SequenceNumber = 0;
                orderedThread.ChipVisibility = Visibility.Collapsed;
            }

            SyncThreadChip(orderedThread);
        }

        // Reorder the Threads collection in-place so the ItemsControl renders chips
        // left-to-right as #1, #2, #3, [+N]. SequenceNumber=1 is the most recent thread.
        // Threads with SequenceNumber=0 (no meaningful transcript) are pushed to the end.
        SortThreadsForDisplay(card.Threads);

        var primaryThread = GetPrimaryThread(card);

        card.DisplayName = BuildAgentCardDisplayName(card, primaryThread, now);

        if (primaryThread is null)
        {
            card.IsThrottled = false;
            if (card.IsDynamicAgent)
            {
                card.StatusText = string.Empty;
                card.DetailText = string.Empty;
            }

            card.ThreadChipsVisibility = Visibility.Collapsed;
            card.OverflowChipVisibility = Visibility.Collapsed;
            card.OverflowChipText = string.Empty;
            return;
        }

        var isCurrentRunThread = _backgroundTaskPresenter.IsThreadCurrentRunForDisplay(primaryThread);
        var isThrottled = isCurrentRunThread &&
            string.Equals(primaryThread.StatusText, "Throttled", StringComparison.OrdinalIgnoreCase);
        card.IsThrottled = isThrottled;
        card.StatusText = isThrottled
            ? ProviderThrottlePresentation.BuildCardStatus(primaryThread.ThrottleRetryAt, now)
            : isCurrentRunThread
                ? _backgroundTaskPresenter.IsThreadStalledForDisplay(primaryThread, now)
                    ? _backgroundTaskPresenter.BuildStalledStatusText(primaryThread, now)
                    : AgentThreadRegistry.HumanizeThreadStatus(primaryThread.StatusText) is { Length: > 0 } s ? s : "Running"
            : ShouldDisplayTerminalAgentStatus(primaryThread, now)
                ? BuildAgentCardStatusText(primaryThread, now)
                : string.Empty;
        card.DetailText = isCurrentRunThread
            ? primaryThread.DetailText
            : string.Empty;
        var meaningfulThreadCount = orderedThreads.Count(AgentThreadRegistry.HasMeaningfulThreadTranscript);
        card.ThreadChipsVisibility = meaningfulThreadCount >= 1
            ? Visibility.Visible
            : Visibility.Collapsed;
        var overflowCount = Math.Max(0, meaningfulThreadCount - visibleChipLimit);
        card.OverflowChipVisibility = overflowCount > 0 ? Visibility.Visible : Visibility.Collapsed;
        card.OverflowChipText = overflowCount > 0 ? $"+{overflowCount}" : string.Empty;
        if (card.IsDynamicAgent)
        {
            card.RoleText = string.IsNullOrWhiteSpace(primaryThread.AgentType)
                ? "Background Agent"
                : AgentThreadRegistry.HumanizeAgentName(primaryThread.AgentType);
        }
    }

    /// <summary>
    /// Sorts <paramref name="threads"/> in-place so the ItemsControl renders chip buttons
    /// left-to-right as #1, #2, #3 (most-recent first). Threads with SequenceNumber=0
    /// (no meaningful transcript) are moved to the end. Uses ObservableCollection.Move()
    /// so WPF receives fine-grained CollectionChanged notifications rather than a full reset.
    /// </summary>
    private static void SortThreadsForDisplay(ObservableCollection<TranscriptThreadState> threads)
    {
        // Build the desired order: numbered threads ascending (1, 2, 3…), then un-numbered (0).
        var sorted = threads
            .OrderBy(t => t.SequenceNumber == 0 ? int.MaxValue : t.SequenceNumber)
            .ToList();

        for (var targetIndex = 0; targetIndex < sorted.Count; targetIndex++)
        {
            var currentIndex = threads.IndexOf(sorted[targetIndex]);
            if (currentIndex != targetIndex)
                threads.Move(currentIndex, targetIndex);
        }
    }

    private void UpdateAgentCardFromThread(TranscriptThreadState thread, bool syncBuckets = true)
    {
        var card = FindAgentCardForThread(thread);
        if (card is null)
        {
            SquadDashTrace.Write("AgentCards",
                $"UpdateAgentCardFromThread: card missing for thread={thread.ThreadId} selected={thread.IsSelected}; falling back to full sync");
            SyncAgentCardsWithThreads();
            return;
        }

        if (!card.Threads.Contains(thread))
            card.Threads.Add(thread);

        SyncTranscriptTargetIndicators();
        SyncCardThreads(card);
        if (syncBuckets)
        {
            SquadDashTrace.Write("AgentCards",
                $"UpdateAgentCardFromThread: full bucket sync card={card.Name} thread={thread.ThreadId} selected={thread.IsSelected} status={thread.StatusText}");
            SyncAgentCardBuckets();
        }
        else
        {
            SquadDashTrace.Write("AgentCards",
                $"UpdateAgentCardFromThread: lightweight refresh card={card.Name} thread={thread.ThreadId} selected={thread.IsSelected} status={thread.StatusText}");
        }
        if (thread.IsSelected)
            UpdateTranscriptThreadBadge();
    }

    private void SyncThreadChip(TranscriptThreadState thread)
    {
        var isFailed = thread.StatusText.Trim() is "Failed" or "Cancelled";

        var chipLabel = thread.SequenceNumber > 0 ? $"#{thread.SequenceNumber}" : "#";
        if (!string.IsNullOrWhiteSpace(thread.RequestedAgentHandle))
            chipLabel += "*";
        if (isFailed)
            chipLabel += "!";
        thread.ChipLabel    = chipLabel;
        thread.ChipToolTip  = BuildThreadChipToolTip(thread);
        thread.ChipFontWeight = FontWeights.Normal;

        thread.ChipBackground = (Brush)Application.Current.Resources[isFailed ? "ChipFailedSurface" : "ChipSurface"];
        if (isFailed)
        {
            thread.ChipBorderBrush = (Brush)Application.Current.Resources["ChipFailedBorder"];
            thread.ChipForeground  = (Brush)Application.Current.Resources["ChipFailedText"];
        }
        else
        {
            thread.ChipBorderBrush = (Brush)Application.Current.Resources["ChipBorder"];
            thread.ChipForeground  = (Brush)Application.Current.Resources["ChipText"];
        }

        var chipCard = FindAgentCardForThread(thread);
        // Guard on IsTranscriptTargetSelected so that chips never show an underline after their
        // parent card's selection bar has been cleared.
        thread.ChipSelectionIndicatorBrush =
            chipCard is not null &&
            chipCard.IsTranscriptTargetSelected &&
            (thread.IsSelected || thread.IsSecondaryPanelOpen)
                ? chipCard.EffectiveAccentBrush
                : Brushes.Transparent;
    }

    /// <summary>
    /// Lightweight post-selection sync: updates only chip appearance and card indicators.
    /// Used by SelectTranscriptThread to avoid the full SyncAgentCardsWithThreads cost
    /// (which rebuilds Threads collections and triggers ScheduleAgentPanelLayoutRefresh).
    /// </summary>
    private void SyncAgentCardsForSelectionChange(TranscriptThreadState? previousThread, TranscriptThreadState newThread)
    {
        // Re-sync chip visuals for threads that changed selection state
        if (previousThread is not null && !ReferenceEquals(previousThread, newThread))
            SyncThreadChip(previousThread);
        SyncThreadChip(newThread);

        SyncTranscriptTargetIndicators();
        SyncSelectionControllerWithUiState("SelectTranscriptThread");
    }

    private void TraceAgentCardVisualFirstRender(AgentStatusCard card, string reason, Stopwatch stopwatch)
    {
        var cardName = card.Name;
        EventHandler? renderingHandler = null;
        renderingHandler = (_, _) =>
        {
            CompositionTarget.Rendering -= renderingHandler;
            SquadDashTrace.Write(TraceCategory.Performance,
                $"AGENT_CARD_VISUAL_RENDER reason={reason} card={cardName} {stopwatch.ElapsedMilliseconds}ms");
        };
        CompositionTarget.Rendering += renderingHandler;
    }

    private void TraceTranscriptTitleFirstRender(TranscriptThreadState thread, string reason, Stopwatch stopwatch)
    {
        var threadId = thread.ThreadId;
        var title = TranscriptTitleTextBlock.Text;
        EventHandler? renderingHandler = null;
        renderingHandler = (_, _) =>
        {
            CompositionTarget.Rendering -= renderingHandler;
            SquadDashTrace.Write(TraceCategory.Performance,
                $"TRANSCRIPT_TITLE_RENDER reason={reason} thread={threadId} title=\"{title}\" {stopwatch.ElapsedMilliseconds}ms");
        };
        CompositionTarget.Rendering += renderingHandler;
    }

    private void QueueDeferredTranscriptPanelOperation(string reason, Action action)
    {
        var queuedAt = Stopwatch.GetTimestamp();
        _ = Dispatcher.BeginInvoke(PostVisualUpdatePriority, () =>
        {
            var queueMs = (long)((Stopwatch.GetTimestamp() - queuedAt) * 1000.0 / Stopwatch.Frequency);
            var sw = Stopwatch.StartNew();
            try
            {
                action();
            }
            catch (Exception ex)
            {
                HandleUiCallbackException($"DeferredTranscriptPanelOperation.{reason}", ex);
            }
            finally
            {
                sw.Stop();
                if (queueMs >= 20 || sw.ElapsedMilliseconds >= 20)
                    SquadDashTrace.Write(TraceCategory.Performance,
                        $"TRANSCRIPT_PANEL_DEFERRED_OP reason={reason} queue={queueMs}ms work={sw.ElapsedMilliseconds}ms");
            }
        });
    }

    private TranscriptThreadState ApplyImmediatePrimaryTranscriptSelectionVisuals(AgentStatusCard agent, TranscriptThreadState thread)
    {
        var sw = Stopwatch.StartNew();
        var previousActualThread = _selectedTranscriptThread ?? CoordinatorThread;
        var previousVisualThread = _pendingPrimaryTranscriptVisualThread ?? previousActualThread;

        _pendingPrimaryTranscriptVisualThread = thread;

        foreach (var card in _agents)
            card.IsTranscriptTargetSelected = ReferenceEquals(card, agent);

        _ownershipMap.SetMainPanelOwner(agent);

        if (!ReferenceEquals(previousVisualThread, thread))
        {
            previousVisualThread.IsSelected = false;
            SyncThreadChip(previousVisualThread);
        }

        foreach (var entry in _secondaryTranscripts)
        {
            entry.Thread.IsSecondaryPanelOpen = false;
            if (!ReferenceEquals(entry.Thread, thread))
                SyncThreadChip(entry.Thread);
        }

        thread.IsSelected = true;
        SyncThreadChip(thread);

        UpdateTranscriptThreadBadge(thread);
        var clearedSelections = CollapseTranscriptSelectionsForFastSwitch("primary-visual");

        _selectionController.ReconcilePanels(
            Array.Empty<(AgentStatusCard Agent, TranscriptThreadState Thread)>(),
            mainVisible: true,
            mainOwnerIsLeadAgent: agent.IsLeadAgent);

        sw.Stop();
        SquadDashTrace.Write(TraceCategory.Performance,
            $"AGENT_CARD_VISUAL_IMMEDIATE reason=primary-select card={agent.Name} thread={thread.ThreadId} title=\"{TranscriptTitleTextBlock.Text}\" selectionsCleared={clearedSelections} work={sw.ElapsedMilliseconds}ms");
        TraceAgentCardVisualFirstRender(agent, "primary-select", Stopwatch.StartNew());
        TraceTranscriptTitleFirstRender(thread, "primary-select", Stopwatch.StartNew());
        return previousActualThread;
    }

    private void QueueDeferredPrimaryTranscriptSelection(
        AgentStatusCard agent,
        TranscriptThreadState thread,
        TranscriptThreadState previousThread,
        bool scrollToStart = false)
    {
        var requestVersion = ++_deferredPrimaryTranscriptSelectionVersion;
        var queuedAt = Stopwatch.GetTimestamp();
        _ = Dispatcher.BeginInvoke(PostVisualUpdatePriority, () =>
        {
            if (requestVersion != _deferredPrimaryTranscriptSelectionVersion)
            {
                SquadDashTrace.Write(TraceCategory.Performance,
                    $"AGENT_CARD_DEFERRED_TRANSCRIPT_SELECT_SKIP card={agent.Name} thread={thread.ThreadId} reason=superseded");
                return;
            }

            var queueMs = (long)((Stopwatch.GetTimestamp() - queuedAt) * 1000.0 / Stopwatch.Frequency);
            var sw = Stopwatch.StartNew();
            try
            {
                _selectedTranscriptThread = thread;

                foreach (var entry in _secondaryTranscripts.ToList())
                    CloseSecondaryPanel(entry);

                ShowMainTranscript();
                SelectTranscriptThreadCore(
                    thread,
                    scrollToStart,
                    allowSnapshotFastPath: true,
                    previousThreadOverride: previousThread);

                if (ReferenceEquals(_pendingPrimaryTranscriptVisualThread, thread))
                    _pendingPrimaryTranscriptVisualThread = null;
            }
            catch (Exception ex)
            {
                HandleUiCallbackException("DeferredPrimaryTranscriptSelection", ex);
            }
            finally
            {
                sw.Stop();
                SquadDashTrace.Write(TraceCategory.Performance,
                    $"AGENT_CARD_DEFERRED_TRANSCRIPT_SELECT card={agent.Name} thread={thread.ThreadId} queue={queueMs}ms work={sw.ElapsedMilliseconds}ms");
            }
        });
    }

    private void SyncImmediatePanelToggleVisuals(AgentStatusCard card, string reason, Stopwatch stopwatch)
    {
        foreach (var thread in card.Threads)
            SyncThreadChip(thread);

        SquadDashTrace.Write(TraceCategory.Performance,
            $"AGENT_CARD_VISUAL_IMMEDIATE reason={reason} card={card.Name} work={stopwatch.ElapsedMilliseconds}ms");
        TraceAgentCardVisualFirstRender(card, reason, Stopwatch.StartNew());
    }

    private static ToolTip BuildThreadChipToolTip(TranscriptThreadState thread)
    {
        var lines = new List<string> {
            thread.Title
        };

        if (!string.IsNullOrWhiteSpace(thread.LatestIntent))
            lines.Add(thread.LatestIntent.Trim());
        if (!string.IsNullOrWhiteSpace(thread.StatusText))
            lines.Add("Status: " + thread.StatusText);
        if (!string.IsNullOrWhiteSpace(thread.DetailText))
            lines.Add(thread.DetailText);
        if (!string.IsNullOrWhiteSpace(thread.AgentId))
            lines.Add("Agent: " + thread.AgentId);
        if (!string.IsNullOrWhiteSpace(thread.RequestedAgentHandle))
        {
            var requestedName = AgentThreadRegistry.HumanizeAgentName(thread.RequestedAgentHandle);
            var actualName = string.IsNullOrWhiteSpace(thread.Title) ? "unknown" : thread.Title;
            lines.Add($"{requestedName} was requested but the launched agent was identified as '{actualName}'. Response may not reflect {requestedName}'s charter.");
        }

        var stack = new System.Windows.Controls.StackPanel { Margin = new Thickness(2) };
        for (int i = 0; i < lines.Count; i++)
        {
            var tb = new TextBlock {
                Text         = lines[i],
                TextWrapping = TextWrapping.Wrap,
                MaxWidth     = 340,
            };
            if (i == 0) tb.FontWeight = FontWeights.SemiBold;
            else         tb.Margin = new Thickness(0, 2, 0, 0);
            tb.SetResourceReference(TextBlock.ForegroundProperty, "ToolTipForeground");
            tb.SetResourceReference(TextBlock.FontSizeProperty,   "FontSizeBody");
            stack.Children.Add(tb);
        }

        var tip = new ToolTip {
            Content         = stack,
            Padding         = new Thickness(8, 6, 8, 6),
            BorderThickness = new Thickness(1),
        };
        tip.SetResourceReference(Control.BackgroundProperty,  "InputSurface");
        tip.SetResourceReference(Control.BorderBrushProperty, "SubtleBorder");
        return tip;
    }

    private void AppendLine(string text, Brush? color = null) =>
        AppendLine(CoordinatorThread, text, color);

    private void AppendLine(TranscriptThreadState thread, string text, Brush? color = null)
    {
        if (thread.CurrentTurn is not null)
        {
            if (thread.CurrentTurn.ResponseTextBuilder.Length > 0)
                thread.CurrentTurn.ResponseTextBuilder.AppendLine();
            if (!string.IsNullOrEmpty(text))
                thread.CurrentTurn.ResponseTextBuilder.Append(text);
            AppendResponseSegment(thread, text, startOnNewLine: true);
            ScrollToEndIfAtBottom(thread);
            return;
        }

        var paragraph = CreateTranscriptParagraph();

        if (!string.IsNullOrEmpty(text))
        {
            if (color is null)
            {
                _markdownRenderer.AppendInlineMarkdown(paragraph.Inlines, text);
            }
            else
            {
                var run = new Run(text)
                {
                    Foreground = color
                };
                paragraph.Inlines.Add(run);
            }
        }

        thread.Document.Blocks.Add(paragraph);
        ScrollToEndIfAtBottom(thread);
    }

    /// <summary>
    /// Appends an 8px diagonal-stripe separator to the coordinator transcript with a styled
    /// tooltip showing the shutdown time, offline duration, and startup time.  Called once on
    /// workspace load when a previous shutdown timestamp is found in settings, and also when
    /// rendering a persisted <see cref="TranscriptTurnRecord"/> with
    /// <c>IsSessionBoundary == true</c>.
    /// </summary>
    private void AppendSessionGapIndicator(
        DateTimeOffset shutdownTime,
        TimeSpan offlineDuration,
        DateTimeOffset? startupTime = null,
        string? appVersion = null)
    {
        SquadDashTrace.Write(TraceCategory.UI, $"SessionGap: AppendSessionGapIndicator called shutdownTime={shutdownTime:O} offline={offlineDuration.TotalSeconds:F1}s");
        var resolvedStartupTime = startupTime?.ToLocalTime() ?? DateTimeOffset.Now;

        var tooltip = new ToolTip { Padding = new Thickness(8, 6, 8, 6) };
        tooltip.SetResourceReference(Control.BackgroundProperty, "PopupSurface");
        tooltip.SetResourceReference(Control.BorderBrushProperty, "ActivePanelBorder");
        tooltip.BorderThickness = new Thickness(1);

        // Rebuild the tooltip content fresh each time it opens so relative timestamps
        // ("3 hours ago", "yesterday") are always up-to-date.
        tooltip.Opened += (_, _) =>
        {
            var panel = new StackPanel { Margin = new Thickness(2) };
            var rows = new List<(string label, string value)>
            {
                ("Shutdown: ", StatusTimingPresentation.FormatRelativeTimestamp(shutdownTime)),
                ("Offline:  ", StatusTimingPresentation.FormatOfflineDuration(offlineDuration)),
                ("Startup:  ", StatusTimingPresentation.FormatRelativeTimestamp(resolvedStartupTime)),
            };
            if (!string.IsNullOrEmpty(appVersion))
                rows.Add(("Version:  ", $"SquadDash v{appVersion}"));
            foreach (var (label, value) in rows)
            {
                var tb = new TextBlock { TextWrapping = TextWrapping.NoWrap };
                tb.Inlines.Add(new System.Windows.Documents.Bold(new System.Windows.Documents.Run(label)));
                tb.Inlines.Add(new System.Windows.Documents.Run(value));
                tb.SetResourceReference(TextBlock.ForegroundProperty, "BodyText");
                panel.Children.Add(tb);
            }
            tooltip.Content = panel;
        };

        var stripeBrush = BuildSessionGapStripeBrush();

        var border = new Border
        {
            Height              = 10,
            Margin              = new Thickness(0, 10, 0, 10),
            HorizontalAlignment = HorizontalAlignment.Stretch,
            Background          = stripeBrush,
            ToolTip             = tooltip,
            Cursor              = Cursors.Arrow,
            Tag                 = "SessionGapStripe",
        };
        ToolTipService.SetInitialShowDelay(border, 200);

        var container = new BlockUIContainer(border) { Margin = new Thickness(0) };
        CoordinatorThread.Document.Blocks.Add(container);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    /// <summary>Rebuilds the <see cref="DrawingBrush"/> for session-gap stripes using the current theme.</summary>
    private DrawingBrush BuildSessionGapStripeBrush()
    {
        // Derive stripe colors from the live (possibly tinted) TranscriptSurface resource
        // so the gap pattern always matches the current theme + tint stop.
        Color baseColor;
        if (Application.Current.Resources["TranscriptSurface"] is SolidColorBrush themeBrush)
            baseColor = themeBrush.Color;
        else if (string.Equals(_activeThemeName, "Light", StringComparison.OrdinalIgnoreCase))
            baseColor = Color.FromRgb(0xFF, 0xFC, 0xF8);
        else
            baseColor = Color.FromRgb(0x1E, 0x1C, 0x17);

        // Blend baseColor toward black (dark theme) or toward a mid-gray (light theme)
        // to produce two subtly-distinct stripe bands.
        bool isLight = string.Equals(_activeThemeName, "Light", StringComparison.OrdinalIgnoreCase);
        Color lightBandColor, darkBandColor;
        if (isLight)
        {
            darkBandColor  = Blend(baseColor, Colors.Black, 0.04);
            lightBandColor = Blend(baseColor, Colors.Black, 0.10);
        }
        else
        {
            darkBandColor  = Blend(baseColor, Colors.White, 0.06);
            lightBandColor = Blend(baseColor, Colors.White, 0.14);
        }

        var lightBand = new SolidColorBrush(lightBandColor);
        var darkBand  = new SolidColorBrush(darkBandColor);
        lightBand.Freeze();
        darkBand.Freeze();

        const double tileW = 16.0, tileH = 10.0;
        var drawingGroup = new DrawingGroup();
        drawingGroup.Children.Add(new GeometryDrawing(
            darkBand, null,
            new RectangleGeometry(new Rect(0, 0, tileW, tileH))));
        var lightFigure = new PathFigure(
            new Point(0, 0),
            new PathSegment[]
            {
                new LineSegment(new Point(tileW / 2, 0), true),
                new LineSegment(new Point(tileW,     tileH), true),
                new LineSegment(new Point(tileW / 2, tileH), true),
            },
            closed: true);
        drawingGroup.Children.Add(new GeometryDrawing(
            lightBand, null,
            new PathGeometry(new[] { lightFigure })));

        return new DrawingBrush
        {
            Drawing       = drawingGroup,
            TileMode      = TileMode.Tile,
            Viewport      = new Rect(0, 0, tileW, tileH),
            ViewportUnits = BrushMappingMode.Absolute,
        };
    }

    private static Color Blend(Color a, Color b, double t) => Color.FromArgb(
        a.A,
        (byte)(a.R + (b.R - a.R) * t),
        (byte)(a.G + (b.G - a.G) * t),
        (byte)(a.B + (b.B - a.B) * t));

    /// <summary>
    /// Re-paints all session-gap stripe borders in the coordinator transcript (and the
    /// Argus Weld transcript if it exists) with fresh brushes for the current theme.
    /// Called from <see cref="ApplyTheme"/> on every theme switch.
    /// </summary>
    private void RefreshSessionGapStripes()
    {
        RefreshSessionGapStripesInDocument(CoordinatorThread.Document);
        const string argusKey = "agent:argus-weld";
        if (_agentThreadRegistry.ThreadsByKey.TryGetValue(argusKey, out var argusThread))
            RefreshSessionGapStripesInDocument(argusThread.Document);
    }

    private void RefreshSessionGapStripesInDocument(FlowDocument doc)
    {
        foreach (var block in doc.Blocks)
        {
            if (block is BlockUIContainer { Child: Border border }
                && border.Tag is string tag && tag == "SessionGapStripe")
            {
                border.Background = BuildSessionGapStripeBrush();
            }
        }
    }

    /// <summary>
    /// Appends a session-gap stripe to Argus Weld's transcript document, unless the
    /// document is empty (first-ever session) or the last block is already a stripe
    /// (consolidation — avoids double-banners on rapid restarts).
    /// </summary>
    private void AppendArgusWeldSessionGapIfNeeded(TranscriptThreadState thread)
    {
        var doc = thread.Document;
        if (doc.Blocks.Count == 0) return;

        // Consolidate: skip if the last block is already a session-gap stripe.
        if (doc.Blocks.LastBlock is BlockUIContainer { Child: Border lastBorder }
            && lastBorder.Tag is string lastTag && lastTag == "SessionGapStripe")
            return;

        var startupTime = DateTimeOffset.Now;
        var tooltip = new ToolTip { Padding = new Thickness(8, 6, 8, 6) };
        tooltip.SetResourceReference(Control.BackgroundProperty, "PopupSurface");
        tooltip.SetResourceReference(Control.BorderBrushProperty, "ActivePanelBorder");
        tooltip.BorderThickness = new Thickness(1);
        tooltip.Opened += (_, _) =>
        {
            var panel = new StackPanel { Margin = new Thickness(2) };
            var tb = new TextBlock { TextWrapping = TextWrapping.NoWrap };
            tb.Inlines.Add(new System.Windows.Documents.Bold(new System.Windows.Documents.Run("Session: ")));
            tb.Inlines.Add(new System.Windows.Documents.Run(StatusTimingPresentation.FormatRelativeTimestamp(startupTime)));
            tb.SetResourceReference(TextBlock.ForegroundProperty, "BodyText");
            panel.Children.Add(tb);
            tooltip.Content = panel;
        };

        var border = new Border
        {
            Height              = 10,
            Margin              = new Thickness(0, 10, 0, 10),
            HorizontalAlignment = HorizontalAlignment.Stretch,
            Background          = BuildSessionGapStripeBrush(),
            ToolTip             = tooltip,
            Cursor              = Cursors.Arrow,
            Tag                 = "SessionGapStripe",
        };
        ToolTipService.SetInitialShowDelay(border, 200);
        doc.Blocks.Add(new BlockUIContainer(border) { Margin = new Thickness(0) });
    }

    private void AppendQrCode(string url)
    {
        try
        {
            var qrGenerator = new QRCoder.QRCodeGenerator();
            var qrData = qrGenerator.CreateQrCode(url, QRCoder.QRCodeGenerator.ECCLevel.Q);
            var qrCode = new QRCoder.BitmapByteQRCode(qrData);
            var bitmapBytes = qrCode.GetGraphic(4);

            using var ms = new System.IO.MemoryStream(bitmapBytes);
            var bitmapImage = new System.Windows.Media.Imaging.BitmapImage();
            bitmapImage.BeginInit();
            bitmapImage.CacheOption = System.Windows.Media.Imaging.BitmapCacheOption.OnLoad;
            bitmapImage.StreamSource = ms;
            bitmapImage.EndInit();
            bitmapImage.Freeze();

            var image = new System.Windows.Controls.Image
            {
                Source = bitmapImage,
                Width = 160,
                Height = 160,
                Stretch = System.Windows.Media.Stretch.Uniform,
                Margin = new Thickness(0, 6, 0, 6),
                HorizontalAlignment = HorizontalAlignment.Left,
                SnapsToDevicePixels = true
            };
            RenderOptions.SetBitmapScalingMode(image, BitmapScalingMode.NearestNeighbor);

            var container = new BlockUIContainer(image) { Margin = new Thickness(0, 2, 0, 6) };
            CoordinatorThread.Document.Blocks.Add(container);
            ScrollToEndIfAtBottom(CoordinatorThread);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("UI", $"QR code generation failed: {ex.Message}");
        }
    }

    private void AppendText(string text) =>
        AppendText(CoordinatorThread, text);

    private void AppendText(TranscriptThreadState thread, string text)
    {
        if (string.IsNullOrEmpty(text))
            return;

        CollapseCurrentTurnThoughts(thread);
        thread.CurrentTurn?.ResponseTextBuilder.Append(text);
        AppendResponseSegment(thread, text);
        ScrollToEndIfAtBottom(thread);
        _search.InvalidateAdornerHighlights();
    }

    private static void AppendParagraphText(
        Paragraph paragraph,
        string? text,
        Brush? color = null,
        bool startOnNewLine = false)
    {
        if (paragraph is null || string.IsNullOrEmpty(text))
            return;

        if (startOnNewLine && paragraph.Inlines.Count > 0)
            paragraph.Inlines.Add(new LineBreak());

        var normalized = text.Replace("\r\n", "\n").Replace('\r', '\n');
        var segments = normalized.Split('\n');

        for (var index = 0; index < segments.Length; index++)
        {
            if (index > 0)
                paragraph.Inlines.Add(new LineBreak());

            if (segments[index].Length == 0)
                continue;

            var run = new Run(segments[index]);
            if (color is not null)
                run.Foreground = color;

            paragraph.Inlines.Add(run);
        }
    }

    /// <summary>
    /// Walks backward through the coordinator transcript and appends " (group)" to the most
    /// recent paragraph whose Tag contains <paramref name="sha"/>. No-ops if not found or
    /// already annotated.
    /// </summary>
    private void AnnotateCommitInTranscript(string sha, string group)
    {
        if (string.IsNullOrEmpty(sha) || string.IsNullOrEmpty(group))
            return;

        var annotation = $" ({group})";

        foreach (var block in CoordinatorThread.Document.Blocks.Reverse())
        {
            if (TryAnnotateShaInBlock(block, sha, annotation))
                return;
        }
    }

    private static bool TryAnnotateShaInBlock(Block block, string sha, string annotation)
    {
        if (block is Paragraph paragraph)
            return TryAnnotateShaInParagraph(paragraph, sha, annotation);

        if (block is Section section)
        {
            foreach (var inner in section.Blocks.Reverse())
            {
                if (TryAnnotateShaInBlock(inner, sha, annotation))
                    return true;
            }
        }

        return false;
    }

    private static bool TryAnnotateShaInParagraph(Paragraph paragraph, string sha, string annotation)
    {
        if (paragraph.Tag is not string tag || string.IsNullOrEmpty(tag))
            return false;

        if (!tag.Contains(sha, StringComparison.OrdinalIgnoreCase))
            return false;

        // Idempotency: skip if already annotated with this group
        if (tag.Contains(annotation, StringComparison.Ordinal))
            return false;

        paragraph.Inlines.Add(new Run(annotation));
        paragraph.Tag = tag + annotation;
        return true;
    }

    private void OutputTextBox_PreviewMouseWheel(object sender, MouseWheelEventArgs e)
    {
        try
        {
            // During PTT voice recording, don't zoom — allow normal scroll
            if (_pttState == PttState.Active) return;
            var rtb = (sender as RichTextBox) ?? OutputTextBox;
            if (!Keyboard.Modifiers.HasFlag(ModifierKeys.Control))
            {
                FocusTranscriptForInactiveSelectionScroll(rtb);
                return;
            }

            // Capture text anchor under the mouse before zoom
            var mousePos = e.GetPosition(rtb);
            var anchor = rtb.GetPositionFromPoint(mousePos, snapToText: true);

            _transcriptFontSize = Math.Clamp(
                _transcriptFontSize + (e.Delta > 0 ? TranscriptFontSizeStep : -TranscriptFontSizeStep),
                TranscriptFontSizeMin,
                TranscriptFontSizeMax);
            ApplyTranscriptFontSize();
            _settingsManager.Replace(_settingsStore.SaveTranscriptFontSize(_transcriptFontSize));

            // After layout, scroll so the anchor stays under the mouse
            if (anchor is not null)
            {
                _ = Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded, () =>
                {
                    var sv = rtb.Template?.FindName("PART_ContentHost", rtb) as ScrollViewer;
                    if (sv is null)
                        return;
                    var newRect = anchor.GetCharacterRect(LogicalDirection.Forward);
                    sv.ScrollToVerticalOffset(sv.VerticalOffset + (newRect.Top - mousePos.Y));
                });
            }

            e.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(OutputTextBox_PreviewMouseWheel), ex);
        }
    }

    private void FocusTranscriptForInactiveSelectionScroll(RichTextBox rtb)
    {
        // Never steal focus away from the search box — doing so interrupts active searches
        // and causes subsequent keystrokes to land in the RTB instead of SearchBox.
        if (SearchBox?.IsKeyboardFocusWithin == true)
            return;

        if (rtb.IsKeyboardFocusWithin || rtb.Selection.IsEmpty)
            return;

        _ = rtb.Focus();
        _ = Keyboard.Focus(rtb);
    }

    /// <summary>
    /// Window-level pre-processing for left mouse button presses.
    /// Releases stale RichTextBox mouse capture when the user presses the mouse
    /// outside the captured RTB's visual subtree.
    ///
    /// <para>
    /// When a RichTextBox starts a drag-select it captures the mouse.  Normally the
    /// capture is released on <c>MouseLeftButtonUp</c>.  In rare edge cases (rapid
    /// panel switches, focus changes mid-gesture) the capture can survive beyond the
    /// drag, silently redirecting the next click away from its intended target — for
    /// example, the floating scroll-to-bottom button in a different transcript panel.
    /// </para>
    /// <para>
    /// The check is intentionally narrow: only stale RichTextBox capture is released,
    /// and only when the physical click position is outside the captured RTB.
    /// Normal in-progress drag-selects (where the cursor is still over the RTB)
    /// are unaffected.
    /// </para>
    /// </summary>
    protected override void OnPreviewMouseLeftButtonDown(System.Windows.Input.MouseButtonEventArgs e)
    {
        try
        {
            // If a RichTextBox has mouse capture but the user is pressing the mouse
            // somewhere outside it, the capture is stale.  Release it so the click
            // reaches its intended target.
            if (Mouse.Captured is RichTextBox capturedRtb)
            {
                // Use visual hit-testing at the raw mouse position to determine the
                // actual element under the cursor, bypassing the capture redirect.
                var mousePos   = e.GetPosition(this);
                var hitResult  = VisualTreeHelper.HitTest(this, mousePos);
                var hitElement = hitResult?.VisualHit as DependencyObject;

                if (hitElement is not null && !IsVisualDescendantOf(capturedRtb, hitElement))
                {
                    capturedRtb.ReleaseMouseCapture();

                    // The current event was already routed to the captured RTB.
                    // Schedule a synthetic click on the intended target at Input priority
                    // so it fires after the current routing completes and the capture is
                    // fully released.  This gives the user a one-click experience rather
                    // than requiring a second press.
                    var hitButton = FindVisualAncestorOrSelf<Button>(hitElement);
                    if (hitButton is not null)
                    {
                        _ = Dispatcher.BeginInvoke(
                            System.Windows.Threading.DispatcherPriority.Input,
                            () =>
                            {
                                try
                                {
                                    if (hitButton.IsEnabled && hitButton.IsVisible)
                                        hitButton.RaiseEvent(
                                            new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent, hitButton));
                                }
                                catch (Exception ex)
                                {
                                    HandleUiCallbackException("StaleCaptureRelease.SyntheticClick", ex);
                                }
                            });
                    }
                }
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(OnPreviewMouseLeftButtonDown), ex);
        }

        base.OnPreviewMouseLeftButtonDown(e);
    }

    /// <summary>Returns <c>true</c> if <paramref name="descendant"/> is the same as
    /// or is a visual descendant of <paramref name="ancestor"/>.</summary>
    private static bool IsVisualDescendantOf(DependencyObject ancestor, DependencyObject descendant)
    {
        var current = descendant;
        while (current is not null)
        {
            if (ReferenceEquals(current, ancestor)) return true;
            current = VisualTreeHelper.GetParent(current);
        }
        return false;
    }

    /// <summary>
    /// Walks the visual tree upward from <paramref name="element"/> (inclusive) and
    /// returns the first ancestor of type <typeparamref name="T"/>, or <c>null</c>.
    /// </summary>
    private static T? FindVisualAncestorOrSelf<T>(DependencyObject? element)
        where T : DependencyObject
    {
        var current = element;
        while (current is not null)
        {
            if (current is T match)
                return match;
            // FrameworkContentElement (Run, Paragraph, Span, etc.) is not a Visual —
            // walk up the logical tree until we reach a Visual, then switch to visual tree.
            if (current is not Visual and not System.Windows.Media.Media3D.Visual3D)
                current = (current as FrameworkContentElement)?.Parent;
            else
                current = VisualTreeHelper.GetParent(current);
        }
        return null;
    }

