    private static double ToolIconSizeForFontSize(double fontSize) => Math.Round(fontSize * 1.1);

    private void ApplyFontSizeScale()
    {
        var sw      = System.Diagnostics.Stopwatch.StartNew();
        var newDict = PrecomputedResourceDictsByLevel[_fontScaleLevel];
        if (ReferenceEquals(newDict, _activeFontSizeDict))
        {
            sw.Stop();
            SquadDashTrace.Write(TraceCategory.Performance,
                $"ApplyFontSizeScale level={_fontScaleLevel} no-op (same dict) elapsed={sw.ElapsedMilliseconds}ms");
            return;
        }

        // Nuclear option: detach the main transcript RTB from its parent Grid before the
        // ResourceDictionary swap so that the 117-block FlowDocument is NOT measured during
        // the font-scale layout cascade.  The RTB is re-inserted below, after the title
        // TextBlock's font size is already settled, giving a single controlled layout pass
        // instead of cascading invalidations.
        //
        // Background: OutputTextBox.FontSize is a direct local value (set by
        // ApplyTranscriptFontSize) and does not participate in the font-scale swap.
        // However, sibling rows in the outer Grid (agent-card panels in Row 2) DO resize
        // when their DynamicResource FontSize bindings update, shrinking the transcript
        // row (Row 4, Height="*") and triggering a full RTB remeasure → 117-block
        // FlowDocument reformat.  Detaching prevents that cascade.

        // Save scroll position before detaching so we can restore it after reattach.
        // Without this, WPF resets the ScrollViewer to offset 0 when the RTB is removed
        // and re-inserted, causing a visible flash to the top of the transcript.
        double savedScrollOffset = _coordinatorScrollController.GetVerticalOffset();
        bool wasAtBottom = !_coordinatorScrollController.IsUserScrolledAway;

        var transcriptGrid = OutputTextBox.Parent as Grid;
        var rtbIdx = transcriptGrid?.Children.IndexOf(OutputTextBox) ?? -1;
        if (rtbIdx >= 0)
            transcriptGrid!.Children.Remove(OutputTextBox);

        var mergedDicts = Application.Current.Resources.MergedDictionaries;
        var idx = mergedDicts.IndexOf(_activeFontSizeDict);
        var swapSw = System.Diagnostics.Stopwatch.StartNew();
        if (idx >= 0)
            mergedDicts[idx] = newDict;   // single ResourcesChanged event instead of 14
        else
            mergedDicts.Add(newDict);
        swapSw.Stop();
        _activeFontSizeDict = newDict;

        // TranscriptTitleTextBlock.FontSize is a static value in XAML (not DynamicResource)
        // so it won't auto-update.  Set it directly now while the RTB is still detached so
        // the resulting DockPanel remeasure doesn't cascade into the FlowDocument.
        if (newDict["FontSizeSubtitle"] is double subtitleSize)
            TranscriptTitleTextBlock.FontSize = subtitleSize;

        // Reattach the RTB: it is now measured exactly once at the settled post-swap size.
        if (transcriptGrid != null && rtbIdx >= 0)
            transcriptGrid.Children.Insert(rtbIdx, OutputTextBox);

        // Force a synchronous layout pass so the ScrollViewer has its final extent before
        // we restore the saved offset.  Without UpdateLayout() the ScrollableHeight is
        // still 0 (the RTB just re-entered the tree) and ScrollToVerticalOffset would
        // clamp to 0, leaving the viewport at the top.
        OutputTextBox.UpdateLayout();
        if (wasAtBottom)
            _coordinatorScrollController.ScrollToBottom();
        else
            _coordinatorScrollController.ScrollToAbsoluteOffset(savedScrollOffset);

        sw.Stop();
        SquadDashTrace.Write(TraceCategory.Performance,
            $"ApplyFontSizeScale level={_fontScaleLevel} keys={newDict.Count} swap={swapSw.ElapsedMilliseconds}ms total={sw.ElapsedMilliseconds}ms");
    }

    private void SetFontSizeScale(int levelIndex)
    {
        var clamped = Math.Clamp(levelIndex, 0, FontScaleFactors.Length - 1);
        if (clamped == _fontScaleLevel && _fontScaleCommitTimer is null)
            return;
        _fontScaleLevel = clamped;

        // Show a live indicator in the title bar (cheap — no layout pass).
        var pct = (int)Math.Round(FontScaleFactors[_fontScaleLevel] * 100);
        FontScaleIndicator.Text       = $"Font {pct}%";
        FontScaleIndicator.Visibility = Visibility.Visible;

        // Coalesce: if multiple wheel events arrive before the next render frame,
        // only one ResourceDictionary swap happens (at the final level).
        if (_fontSizeApplyPending)
        {
            SquadDashTrace.Write(TraceCategory.Performance,
                $"SetFontSizeScale coalesced, level={_fontScaleLevel}");
        }
        else
        {
            _fontSizeApplyPending = true;
            // Use Background priority so Input and Render frames can drain first.
            // Rapid wheel ticks arriving before this fires all coalesce into one
            // layout pass, and the title-bar indicator (updated synchronously above)
            // stays responsive throughout.
            Dispatcher.BeginInvoke(DispatcherPriority.Background, () =>
            {
                _fontSizeApplyPending = false;
                ApplyFontSizeScale();
                _guidedTourCoordinator.RaiseEnvironmentFontZoomed();
                // Graph window can wait until after the font layout pass settles.
                Dispatcher.BeginInvoke(DispatcherPriority.Background,
                    () =>
                    {
                        _commitActivityGraphWindow?.NotifyFontSizeChanged();
                        foreach (var (_, win) in _openPlanViewerWindows)
                            win.NotifyFontSizeChanged();
                    });
                SquadDashTrace.Write(TraceCategory.Performance,
                    $"SetFontSizeScale applied level={_fontScaleLevel} NotifyFontSizeChanged deferred to Background priority");
            });
        }

        // Debounce only the disk save so repeated ticks don't thrash storage.
        if (_fontScaleCommitTimer is null)
        {
            _fontScaleCommitTimer       = new DispatcherTimer { Interval = UiTimingConstants.FontScaleCommitInterval };
            _fontScaleCommitTimer.Tick += (_, _) => CommitFontSizeScale();
        }
        _fontScaleCommitTimer.Stop();
        _fontScaleCommitTimer.Start();
    }

    /// <summary>
    /// Persists the current <see cref="_fontScaleLevel"/> to disk and hides the indicator.
    /// The visual apply has already happened in <see cref="SetFontSizeScale"/>;
    /// this method is debounced so it runs once scrolling pauses.
    /// </summary>
    private void CommitFontSizeScale()
    {
        var sw = System.Diagnostics.Stopwatch.StartNew();
        _fontScaleCommitTimer?.Stop();
        FontScaleIndicator.Visibility = Visibility.Collapsed;
        // Visual already applied in SetFontSizeScale; only persist to disk here.
        var level = _fontScaleLevel;
        _ = Task.Run(() =>
        {
            try
            {
                var snapshot = _settingsStore.SaveFontSizeScaleLevel(level);
                Dispatcher.InvokeAsync(() => _settingsManager.Replace(snapshot));
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write("Settings", "[Warning] CommitFontSizeScale settings save failed: " + ex.Message);
            }
        });
        sw.Stop();
        SquadDashTrace.Write(TraceCategory.Performance,
            $"CommitFontSizeScale level={level} elapsed={sw.ElapsedMilliseconds}ms");
    }

    private bool IsInExcludedScrollArea(DependencyObject element)
    {
        var current = element;
        while (current != null)
        {
            if (current is RichTextBox) return true;
            if (current == PromptTextBox) return true;
            current = current is Visual || current is System.Windows.Media.Media3D.Visual3D
                ? VisualTreeHelper.GetParent(current)
                : LogicalTreeHelper.GetParent(current);
        }
        return false;
    }

    // WM_NCMOUSEWHEEL is sent when the wheel is rotated over the non-client caption area,
    // which WindowChrome uses for the empty title-bar background. WPF's routed events never
    // fire there, so we hook the raw message and route it to SetFontSizeScale ourselves.
    private const int WM_NCMOUSEWHEEL = 0x02A3;
    private nint TitlebarNcMouseWheelHook(nint hwnd, int msg, nint wParam, nint lParam, ref bool handled)
    {
        if (msg != WM_NCMOUSEWHEEL) return nint.Zero;
        if (!NativeMethods.IsCtrlPhysicallyDown()) return nint.Zero;
        // During PTT voice recording, let wheel events pass through as normal scroll
        if (_pttState == PttState.Active) return nint.Zero;
        var delta = (short)((uint)wParam >> 16);
        Dispatcher.BeginInvoke(() => SetFontSizeScale(_fontScaleLevel + (delta > 0 ? 1 : -1)));
        handled = true;
        return nint.Zero;
    }

    private void Window_PreviewMouseWheel(object sender, MouseWheelEventArgs e)
    {
        try
        {
            // During PTT voice recording, let wheel events pass through as normal scroll
            if (_pttState == PttState.Active) return;
            if (Keyboard.Modifiers != ModifierKeys.Control) return;
            if (Mouse.DirectlyOver is DependencyObject hovered && IsInExcludedScrollArea(hovered))
                return;
            SetFontSizeScale(_fontScaleLevel + (e.Delta > 0 ? 1 : -1));
            e.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(Window_PreviewMouseWheel), ex);
        }
    }

    private void ApplyTranscriptFontSize()
    {
        OutputTextBox.FontSize = _transcriptFontSize;
        foreach (var entry in _primaryAgentTranscriptHosts.Values)
            entry.TranscriptBox.FontSize = _transcriptFontSize;
        var iconSize = ToolIconSizeForFontSize(_transcriptFontSize);
        foreach (var img in _toolIconImages)
        {
            img.Width = iconSize;
            img.Height = iconSize;
        }
        foreach (var entry in _secondaryTranscripts)
            entry.TranscriptBox.FontSize = _transcriptFontSize;
        foreach (var thread in EnumerateTranscriptThreads())
            ApplyTranscriptFontSizeToDocument(thread.Document);

        // Adorner overlay text uses the RichTextBox FontSize — invalidate so it redraws
        // at the new size without waiting for a layout pass.
        _search.InvalidateAdornerHighlights();
    }

    private void ApplyTranscriptFontSizeToDocument(FlowDocument document)
    {
        // Guard using Tag rather than document.FontSize: WPF property inheritance means
        // document.FontSize (effective value) already reflects OutputTextBox.FontSize
        // before this method runs, so comparing document.FontSize would always short-circuit.
        // Tag is never touched by WPF, so it reliably tracks the last size we actually applied.
        if (document.Tag is double lastApplied && lastApplied == _transcriptFontSize) return;
        document.Tag = _transcriptFontSize;
        document.FontSize = _transcriptFontSize;

        var codeBlockFontSize = _transcriptFontSize * 0.9;

        // Walk all sections at all depths. Document structure is:
        //   Document → NarrativeSection (Section) → inner Section → BlockUIContainer/Paragraph
        // We use a local helper to avoid duplicating the per-section logic.
        void ApplySectionBlocks(Section section)
        {
            foreach (var inner in section.Blocks.OfType<BlockUIContainer>())
            {
                // Code block: BlockUIContainer > Grid > TextBox (Tag="codeblock")
                // Also handles legacy StackPanel wrappers from earlier code paths.
                var codeBox = inner.Child switch
                {
                    TextBox tb when tb.Tag is "codeblock" => tb,
                    Grid g =>
                        g.Children.OfType<TextBox>().FirstOrDefault(tb => tb.Tag is "codeblock"),
                    System.Windows.Controls.StackPanel sp =>
                        sp.Children.OfType<TextBox>().FirstOrDefault(tb => tb.Tag is "codeblock"),
                    _ => null
                };
                if (codeBox is not null)
                {
                    codeBox.FontSize = codeBlockFontSize;
                    // Update top padding so copy button (sized to 1.5× font) still fits.
                    var btnSize = _transcriptFontSize * 1.5;
                    var topPad = Math.Max(30, btnSize + 8);
                    codeBox.Padding = new Thickness(codeBox.Padding.Left, topPad, codeBox.Padding.Right, codeBox.Padding.Bottom);
                    // Resize the sticky copy host (Grid that wraps backdrop + CopyButton).
                    if (inner.Child is Grid outerGrid)
                    {
                        var stickyHost = outerGrid.Children.OfType<Grid>().FirstOrDefault();
                        if (stickyHost is not null)
                        {
                            stickyHost.Width = btnSize;
                            stickyHost.Height = btnSize;
                        }
                    }
                }

                if (TranscriptQuickReplyFactory.IsQuickReplyContainer(inner))
                    foreach (var button in TranscriptQuickReplyFactory.EnumerateButtons(inner.Child))
                        button.FontSize = _transcriptFontSize;
            }

            foreach (var para in section.Blocks.OfType<Paragraph>())
            {
                if (para.Tag is string headingTag)
                {
                    var level = headingTag switch { "h1" => 1, "h2" => 2, _ => 3 };
                    para.FontSize = MarkdownDocumentRenderer.HeadingFontSize(level, _transcriptFontSize);
                }
            }

            // Recurse into nested Sections (NarrativeSection → inner Section → content)
            foreach (var nested in section.Blocks.OfType<Section>())
                ApplySectionBlocks(nested);
        }

        foreach (var block in document.Blocks.OfType<Section>())
            ApplySectionBlocks(block);

        // Tour quick reply: BlockUIContainer added directly to document (not inside a Section)
        // Structure: BlockUIContainer > WrapPanel > Button
        foreach (var topBlock in document.Blocks.OfType<BlockUIContainer>())
        {
            if (topBlock.Child is not System.Windows.Controls.WrapPanel wp) continue;
            foreach (var btn in wp.Children.OfType<Button>())
                btn.FontSize = _transcriptFontSize;
        }
    }

    private ContextMenu CreateThinkingContextMenu(TranscriptTurnView view)
    {
        var copyMenuItem = MakeItem("Copy Thinking Block");
        copyMenuItem.Tag = view;
        copyMenuItem.Click += CopyThinkingMenuItem_Click;

        var menu = MakeMenu();
        menu.Items.Add(copyMenuItem);
        menu.Opened += ThinkingContextMenu_Opened;
        return menu;
    }

    private void ThinkingContextMenu_Opened(object? sender, RoutedEventArgs e)
    {
        try
        {
            if (sender is not ContextMenu { Items.Count: > 0 } menu)
                return;

            if (menu.Items[0] is not MenuItem { Tag: TranscriptTurnView view } copyMenuItem)
                return;

            copyMenuItem.IsEnabled = !string.IsNullOrWhiteSpace(BuildThinkingClipboardText(view));
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(ThinkingContextMenu_Opened), ex);
        }
    }

    private void CopyThinkingMenuItem_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (sender is not MenuItem { Tag: TranscriptTurnView view })
                return;

            var thinkingText = BuildThinkingClipboardText(view);

            if (string.IsNullOrWhiteSpace(thinkingText))
                return;

            Clipboard.SetText(thinkingText);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(CopyThinkingMenuItem_Click), ex);
        }
    }

    private string BuildThinkingClipboardText(TranscriptTurnView view)
    {
        var builder = new StringBuilder();
        foreach (var item in GetOrderedThinkingNarrativeItems(view))
        {
            switch (item)
            {
                case TranscriptThoughtEntry thought:
                    var thoughtText = FormatThinkingText(thought.RawTextBuilder.ToString());
                    if (!string.IsNullOrWhiteSpace(thoughtText))
                        builder.AppendLine($"{thought.Speaker}: {thoughtText}");
                    break;

                case TranscriptThinkingBlockView block:
                    builder.AppendLine("Tooling...");
                    foreach (var entry in block.ToolEntries.OrderBy(tool => tool.StartedAt))
                    {
                        var icon = entry.IconTextBlock.Text?.Trim();
                        var emoji = ToolTranscriptFormatter.GetToolEmoji(entry.Descriptor).Trim();
                        var message = ExtractInlineText(entry.MessageTextBlock.Inlines).Trim();
                        var combined = string.Join(" ", new[] { icon, emoji, message }.Where(part => !string.IsNullOrWhiteSpace(part)));
                        if (!string.IsNullOrWhiteSpace(combined))
                            builder.AppendLine("  " + combined);
                    }
                    break;
            }
        }

        return builder.ToString().TrimEnd();
    }

    private static IEnumerable<object> GetOrderedThinkingNarrativeItems(TranscriptTurnView view)
    {
        return view.ThoughtEntries
            .Cast<object>()
            .Concat(view.ThinkingBlocks)
            .OrderBy(item => item switch
            {
                TranscriptThoughtEntry thought => thought.Sequence,
                TranscriptThinkingBlockView block => block.Sequence,
                _ => int.MaxValue
            });
    }

    private static string ExtractInlineText(InlineCollection inlines) =>
        TranscriptCopyService.ExtractInlineText(inlines);

    private static void SetClipboardTextWithRetry(string text, int retries = 15)
    {
        Exception? lastEx = null;
        for (int i = 0; i < retries; i++)
        {
            try
            {
                Clipboard.SetDataObject(text, copy: true);
                return;
            }
            catch (System.Runtime.InteropServices.COMException ex)
            {
                lastEx = ex;
                System.Threading.Thread.Sleep(UiTimingConstants.ClipboardRetryBackoffUnitMs * (i + 1)); // 50, 100, 150... ms — linear backoff
            }
        }
        // CLIPBRD_E_CANT_OPEN is transient clipboard contention; swallow silently after exhausting retries.
        if (lastEx != null)
            SquadDashTrace.Write("UI", $"SetClipboardTextWithRetry: clipboard unavailable after {retries} attempts — {lastEx.Message}");
    }

    private void OutputTextBox_CopyExecuted(object sender, System.Windows.Input.ExecutedRoutedEventArgs e)
    {
        try
        {
            var text = TranscriptCopyService.BuildSelectionText((sender as RichTextBox) ?? OutputTextBox);
            if (!string.IsNullOrEmpty(text))
                SetClipboardTextWithRetry(text);
            e.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(OutputTextBox_CopyExecuted), ex);
        }
    }

    private void OutputTextBox_PreviewMouseRightButtonDown(object sender, System.Windows.Input.MouseButtonEventArgs e)
    {
        try
        {
            var clickSource = e.OriginalSource as DependencyObject;
            if (TranscriptApprovalCardBuilder.ShouldDeferContextMenuToEditableTextBox(clickSource, out var editableTextBox))
            {
                _ = editableTextBox.Focus();
                _ = Keyboard.Focus(editableTextBox);
                return;
            }

            var cardContainer = TranscriptCardLayout.FindContainer(clickSource);
            var cardViewer = cardContainer is null
                ? null
                : TranscriptCopyService.FindCardDocumentViewer(cardContainer);
            var contextualOwner = TranscriptApprovalCardBuilder.FindContextMenuOwner(
                clickSource,
                "Clarify This…");
            if (contextualOwner?.ContextMenu is { } contextualMenu)
            {
                EnsureTranscriptCardCopyItems(contextualMenu, cardViewer, cardContainer);
                contextualMenu.PlacementTarget = contextualOwner;
                contextualMenu.Placement = System.Windows.Controls.Primitives.PlacementMode.MousePoint;
                contextualMenu.IsOpen = true;
                e.Handled = true;
                return;
            }

            if (cardViewer is not null && TranscriptCardLayout.IsCard(cardContainer))
            {
                var cardMenu = new ContextMenu();
                cardMenu.SetResourceReference(ContextMenu.StyleProperty, "ThemedContextMenuStyle");
                EnsureTranscriptCardCopyItems(cardMenu, cardViewer, cardContainer);
                cardMenu.PlacementTarget = cardViewer;
                cardMenu.Placement = System.Windows.Controls.Primitives.PlacementMode.MousePoint;
                cardMenu.IsOpen = true;
                e.Handled = true;
                return;
            }

            var menu = new ContextMenu();
            menu.SetResourceReference(ContextMenu.StyleProperty, "ThemedContextMenuStyle");

            var activeRtb = (sender as RichTextBox) ?? OutputTextBox;

            // If the click originated inside a code block TextBox, use its selection.
            var codeBox = FindVisualAncestorOrSelf<TextBox>(e.OriginalSource as DependencyObject);
            if (codeBox is not null && !"codeblock".Equals(codeBox.Tag as string))
                codeBox = null;
            var hasCodeSelection = codeBox is not null && codeBox.SelectionLength > 0;
            var hasSelection     = hasCodeSelection || !activeRtb.Selection.IsEmpty;

            if (hasSelection)
            {
                var followUpItem = new MenuItem { Header = "Add to Chat" };
                followUpItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                followUpItem.Click += (_, _) => AttachTranscriptFollowUp(activeRtb);
                menu.Items.Add(followUpItem);

                var addToNewChatItem = new MenuItem { Header = "Add to New Chat" };
                addToNewChatItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                addToNewChatItem.Click += (_, _) => AddTranscriptSelectionToNewChat(activeRtb);
                menu.Items.Add(addToNewChatItem);

                var addToNotesItem = new MenuItem { Header = "Add to Notes" };
                addToNotesItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                addToNotesItem.Click += (_, _) => {
                    var text = TranscriptCopyService.BuildSelectionMarkdown(activeRtb);
                    if (!string.IsNullOrWhiteSpace(text))
                        AddNoteFromText(text);
                    activeRtb.Selection.Select(activeRtb.CaretPosition, activeRtb.CaretPosition);
                };
                menu.Items.Add(addToNotesItem);

                var sep = new Separator();
                sep.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
                menu.Items.Add(sep);
            }

            // Check if click is on a table — collected here, inserted after Copy below
            var tablePanel = FindVisualAncestor<StackPanel>(clickSource);
            string? tableMarkdown = tablePanel?.Tag as string;

            var copyItem = new MenuItem { Header = "_Copy" };
            copyItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
            copyItem.IsEnabled = hasSelection;
            copyItem.Click += (_, _) => {
                // Prefer code box selected text; fall back to RichTextBox selection.
                var text = hasCodeSelection
                    ? codeBox!.SelectedText
                    : TranscriptCopyService.BuildSelectionText(activeRtb);
                if (!string.IsNullOrEmpty(text))
                    SetClipboardTextWithRetry(text);
            };
            menu.Items.Add(copyItem);

            EnsureTranscriptCardCopyItems(menu, selectionViewer: null, cardContainer);

            if (!string.IsNullOrWhiteSpace(tableMarkdown))
            {
                var copyTableItem = new MenuItem { Header = "Copy Table" };
                copyTableItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                var captured = tableMarkdown;
                copyTableItem.Click += (_, _) => SetClipboardTextWithRetry(captured);
                menu.Items.Add(copyTableItem);
            }
            menu.PlacementTarget = activeRtb;
            menu.Placement = System.Windows.Controls.Primitives.PlacementMode.MousePoint;
            menu.IsOpen = true;
            e.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(OutputTextBox_PreviewMouseRightButtonDown), ex);
        }
    }

