    private void PromptTextBox_PreviewMouseWheel(object sender, MouseWheelEventArgs e)
    {
        try
        {
            if (!Keyboard.Modifiers.HasFlag(ModifierKeys.Control))
                return;

            _promptFontSize = Math.Clamp(
                _promptFontSize + (e.Delta > 0 ? PromptFontSizeStep : -PromptFontSizeStep),
                PromptFontSizeMin,
                PromptFontSizeMax);

            ApplyPromptFontSize();
            _settingsManager.Replace(_settingsStore.SavePromptFontSize(_promptFontSize));
            e.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(PromptTextBox_PreviewMouseWheel), ex);
        }
    }

    private void ApplyPromptFontSize()
    {
        PromptTextBox.FontSize = _promptFontSize;
        IntelliSenseList.FontSize = _promptFontSize;
        IntelliSenseList.MaxHeight = (_promptFontSize + 4) * 8;
    }

    private void ClearPromptTextBoxLogicalBuffer(string reason) =>
        SetPromptTextBoxLogicalBuffer(string.Empty, 0, 0, 0, reason);

    private void SetPromptTextBoxLogicalBuffer(
        string text,
        int caretIndex,
        int selectionStart = 0,
        int selectionLength = 0,
        string reason = "load")
    {
        text ??= string.Empty;
        var normalizedCaret = Math.Clamp(caretIndex, 0, text.Length);
        var normalizedSelectionStart = Math.Clamp(selectionStart, 0, text.Length);
        var normalizedSelectionLength = Math.Clamp(selectionLength, 0, text.Length - normalizedSelectionStart);

        PromptTextBox.Text = text;
        if (normalizedSelectionLength > 0)
            PromptTextBox.Select(normalizedSelectionStart, normalizedSelectionLength);
        else
            PromptTextBox.CaretIndex = normalizedCaret;

        var undoWasEnabled = PromptTextBox.IsUndoEnabled;
        if (undoWasEnabled)
        {
            // IsUndoEnabled cannot be set inside a WPF change block (e.g. from a TextChanged handler).
            // Defer to the next dispatcher frame so the change block has exited first.
            Dispatcher.InvokeAsync(() =>
            {
                PromptTextBox.IsUndoEnabled = false;
                PromptTextBox.IsUndoEnabled = true;
            }, System.Windows.Threading.DispatcherPriority.Normal);
        }
        SquadDashTrace.Write(
            TraceCategory.UI,
            $"PROMPT_BUFFER_LOAD reason={reason} textLen={text.Length} caret={PromptTextBox.CaretIndex} selectionLen={PromptTextBox.SelectionLength} undoCleared={undoWasEnabled}");
    }

    private void PromptTextBox_PreviewTextInput(object sender, System.Windows.Input.TextCompositionEventArgs e)
    {
        if (_suppressPromptNextTextInput)
        {
            _suppressPromptNextTextInput = false;
            e.Handled = true;
            return;
        }

        // Paren embedding (works on all keyboard layouts)
        if ((e.Text == "(" || e.Text == ")") && PromptTextBox.SelectionLength > 0
            && !PromptTextBox.SelectedText.Contains('\n'))
        {
            if (MarkdownEditorCommands.ApplyInlineParens(PromptTextBox, e.Text))
            {
                e.Handled = true;
                return;
            }
        }
    }

    private void PromptTextBox_PreviewDragEnter(object sender, DragEventArgs e)
    {
        if (e.Data.GetDataPresent(DataFormats.FileDrop))
            e.Effects = DragDropEffects.Copy;
        else
            e.Effects = DragDropEffects.None;
        e.Handled = true;
    }

    private void PromptTextBox_PreviewDragOver(object sender, DragEventArgs e)
    {
        if (e.Data.GetDataPresent(DataFormats.FileDrop))
            e.Effects = DragDropEffects.Copy;
        else
            e.Effects = DragDropEffects.None;
        e.Handled = true;
    }

    private void PromptTextBox_PreviewDrop(object sender, DragEventArgs e)
    {
        if (!e.Data.GetDataPresent(DataFormats.FileDrop)) return;
        var paths = (string[])e.Data.GetData(DataFormats.FileDrop);
        var list = GetOrCreateFollowUpList(_activeTabId ?? "");
        foreach (var path in paths)
        {
            if (list.Count >= 15) break;
            var leaf = System.IO.Path.GetFileName(path);
            if (list.Any(a => a.FileReferencePath == path)) continue;
            list.Add(new FollowUpAttachment(
                CommitSha:         string.Empty,
                Description:       leaf,
                OriginalPrompt:    null,
                FileReferencePath: path));
        }
        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (_activeTabId is null) PersistDraftFollowUp();
        e.Handled = true;
    }

    private void PromptTextBox_ContextMenuOpening(object sender, ContextMenuEventArgs e)
    {
        // Build a themed context menu, appending Smooth Dictation when text is selected.
        var menu = new ContextMenu { Style = (Style)FindResource("ThemedContextMenuStyle") };

        var cut = new MenuItem
        {
            Header  = "Cu_t",
            Style   = (Style)FindResource("ThemedMenuItemStyle"),
            Command = ApplicationCommands.Cut,
            CommandTarget = PromptTextBox,
            IsEnabled = PromptTextBox.SelectionLength > 0
        };
        var copy = new MenuItem
        {
            Header  = "_Copy",
            Style   = (Style)FindResource("ThemedMenuItemStyle"),
            Command = ApplicationCommands.Copy,
            CommandTarget = PromptTextBox,
            IsEnabled = PromptTextBox.SelectionLength > 0
        };
        var paste = new MenuItem
        {
            Header  = "_Paste",
            Style   = (Style)FindResource("ThemedMenuItemStyle"),
            Command = ApplicationCommands.Paste,
            CommandTarget = PromptTextBox,
            IsEnabled = Clipboard.ContainsText()
        };
        menu.Items.Add(cut);
        menu.Items.Add(copy);
        menu.Items.Add(paste);

        if (PromptTextBox.SelectionLength > 0)
        {
            menu.Items.Add(new Separator { Style = (Style)FindResource("ThemedMenuSeparatorStyle") });

            var capturedStart  = PromptTextBox.SelectionStart;
            var capturedLength = PromptTextBox.SelectionLength;
            var smoothItem = new MenuItem
            {
                Header           = "✨ Smooth Dictation",
                InputGestureText = "Shift+Space",
                Style            = (Style)FindResource("ThemedMenuItemStyle")
            };
            smoothItem.Click += (_, _) => {
                PromptTextBox.Select(capturedStart, capturedLength);
                SmoothDictationHelper.ApplyToTextBox(PromptTextBox);
            };
            menu.Items.Add(smoothItem);
        }

        PromptTextBox.ContextMenu = menu;
    }

    private void ApplyDocSourceFontSize()
    {
        if (DocSourceTextBox is not null)
            DocSourceTextBox.FontSize = _docSourceFontSize;
    }

    private void DocSourceTextBox_PreviewMouseWheel(object sender, MouseWheelEventArgs e)
    {
        try
        {
            if (!Keyboard.Modifiers.HasFlag(ModifierKeys.Control))
                return;

            _docSourceFontSize = Math.Clamp(
                _docSourceFontSize + (e.Delta > 0 ? DocSourceFontSizeStep : -DocSourceFontSizeStep),
                DocSourceFontSizeMin,
                DocSourceFontSizeMax);

            ApplyDocSourceFontSize();
            _settingsManager.Replace(_settingsStore.SaveDocSourceFontSize(_docSourceFontSize));
            e.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(DocSourceTextBox_PreviewMouseWheel), ex);
        }
    }

    private void DocSourceTextBox_PreviewKeyDown(object sender, System.Windows.Input.KeyEventArgs e)
    {
        // ── Ctrl+Shift+Z → Redo ───────────────────────────────────────────────────
        if (e.Key == System.Windows.Input.Key.Z
            && Keyboard.Modifiers == (ModifierKeys.Control | ModifierKeys.Shift))
        {
            if (DocSourceTextBox.CanRedo)
                DocSourceTextBox.Redo();
            e.Handled = true;
            return;
        }

        // ── Shift+F3: cycle case of selected text ─────────────────────────────────
        if (e.Key == System.Windows.Input.Key.F3
            && Keyboard.Modifiers == ModifierKeys.Shift
            && DocSourceTextBox.GetSelectionLength() > 0)
        {
            var selStart     = DocSourceTextBox.GetSelectionStart();
            var selectedText = DocSourceTextBox.GetSelectedText();

            bool continuing = _docCycleVariants is not null
                && selStart == _docCycleSelStart
                && selectedText == _docCycleVariants[_docCycleIndex];

            if (!continuing)
            {
                _docCycleOriginal = selectedText;
                _docCycleVariants = TextCaseHelper.ComputeOrderedVariants(selectedText);
                _docCycleIndex    = 0;
                _docCycleSelStart = selStart;

                var firstVariant = _docCycleVariants[_docCycleIndex];
                DocSourceTextBox.ReplaceSelection(firstVariant);
                DocSourceTextBox.SelectRange(selStart, firstVariant.Length);
            }
            else
            {
                _docCycleIndex = (_docCycleIndex + 1) % _docCycleVariants!.Count;
                var nextVariant = _docCycleVariants[_docCycleIndex];

                // Restore original (no undo), then apply next variant as a single undo entry.
                DocSourceTextBox.IsUndoEnabled = false;
                DocSourceTextBox.SelectRange(_docCycleSelStart, selectedText.Length);
                DocSourceTextBox.Selection.Text = _docCycleOriginal!;
                DocSourceTextBox.IsUndoEnabled  = true;
                DocSourceTextBox.SelectRange(_docCycleSelStart, _docCycleOriginal!.Length);
                DocSourceTextBox.ReplaceSelection(nextVariant);
                DocSourceTextBox.SelectRange(_docCycleSelStart, nextVariant.Length);
            }
            e.Handled = true;
            _guidedTourCoordinator.RaiseCycleCaseForward(this);
            return;
        }

        // ── Ctrl+Shift+F3: reverse cycle case of selected text ────────────────────
        if (e.Key == System.Windows.Input.Key.F3
            && Keyboard.Modifiers == (ModifierKeys.Shift | ModifierKeys.Control)
            && DocSourceTextBox.GetSelectionLength() > 0)
        {
            var selStart     = DocSourceTextBox.GetSelectionStart();
            var selectedText = DocSourceTextBox.GetSelectedText();

            bool continuing = _docCycleVariants is not null
                && selStart == _docCycleSelStart
                && selectedText == _docCycleVariants[_docCycleIndex];

            if (!continuing)
            {
                _docCycleOriginal = selectedText;
                _docCycleVariants = TextCaseHelper.ComputeOrderedVariants(selectedText);
                _docCycleSelStart = selStart;
                _docCycleIndex    = _docCycleVariants.Count - 1;

                var firstVariant = _docCycleVariants[_docCycleIndex];
                DocSourceTextBox.ReplaceSelection(firstVariant);
                DocSourceTextBox.SelectRange(selStart, firstVariant.Length);
            }
            else
            {
                _docCycleIndex = (_docCycleIndex - 1 + _docCycleVariants!.Count) % _docCycleVariants.Count;
                var prevVariant = _docCycleVariants[_docCycleIndex];

                DocSourceTextBox.IsUndoEnabled = false;
                DocSourceTextBox.SelectRange(_docCycleSelStart, selectedText.Length);
                DocSourceTextBox.Selection.Text = _docCycleOriginal!;
                DocSourceTextBox.IsUndoEnabled  = true;
                DocSourceTextBox.SelectRange(_docCycleSelStart, _docCycleOriginal!.Length);
                DocSourceTextBox.ReplaceSelection(prevVariant);
                DocSourceTextBox.SelectRange(_docCycleSelStart, prevVariant.Length);
            }
            e.Handled = true;
            _guidedTourCoordinator.RaiseCycleCaseReverse(this);
            return;
        }

        // ── Smooth Dictation: Shift+Space on selection ────────────────────────────
        if (e.Key == System.Windows.Input.Key.Space
            && Keyboard.Modifiers == ModifierKeys.Shift
            && DocSourceTextBox.GetSelectionLength() > 0)
        {
            e.Handled = SmoothDictationHelper.ApplyToRichTextBox(DocSourceTextBox);
            return;
        }

        // ── Selection embedding: backtick or apostrophe wraps inline code or fence ─
        if ((e.Key == System.Windows.Input.Key.OemTilde || e.Key == System.Windows.Input.Key.OemQuotes)
            && Keyboard.Modifiers == ModifierKeys.None
            && DocSourceTextBox.GetSelectionLength() > 0)
        {
            if (MarkdownEditorCommands.ApplyInlineCodeOrFence(DocSourceTextBox))
            {
                _suppressDocSourceNextTextInput = true;
                e.Handled = true;
                return;
            }
        }

        // ── Selection embedding: double-quote wraps inline quote ──────────────────
        if (e.Key == System.Windows.Input.Key.OemQuotes
            && Keyboard.Modifiers == ModifierKeys.Shift
            && DocSourceTextBox.GetSelectionLength() > 0)
        {
            if (MarkdownEditorCommands.ApplyInlineQuote(DocSourceTextBox))
            {
                _suppressDocSourceNextTextInput = true;
                e.Handled = true;
                return;
            }
        }

        // ── Shift+Enter: duplicate current line ───────────────────────────────────
        if (e.Key == System.Windows.Input.Key.Return
            && Keyboard.Modifiers == ModifierKeys.Shift)
        {
            MarkdownEditorCommands.DuplicateLine(DocSourceTextBox);
            e.Handled = true;
            return;
        }

        // ── List continuation: Enter at end of a bullet/numbered line ─────────────
        if (e.Key == System.Windows.Input.Key.Return
            && Keyboard.Modifiers == ModifierKeys.None)
        {
            if (MarkdownEditorCommands.ContinueListOnEnter(DocSourceTextBox))
                e.Handled = true;
            return;
        }

        if (e.Key == System.Windows.Input.Key.Tab)
        {
            e.Handled = true;
            var caret    = DocSourceTextBox.GetCaretOffset();
            var selLen   = DocSourceTextBox.GetSelectionLength();
            var selStart = DocSourceTextBox.GetSelectionStart();
            var text     = DocSourceTextBox.GetPlainText();
            if (selLen > 0)
            {
                DocSourceTextBox.SelectRange(selStart, selLen);
                DocSourceTextBox.ReplaceSelection("    ");
                DocSourceTextBox.SetCaretOffset(selStart + 4);
            }
            else
            {
                DocSourceTextBox.SetPlainText(text.Insert(caret, "    "));
                DocSourceTextBox.SetCaretOffset(caret + 4);
            }
        }
    }

    private void PromptTextBox_KeyDown(object sender, KeyEventArgs e)
    {
        var sw = Stopwatch.StartNew();
        try
        {
            // When selection embedding handles a key (e.g. `"` wraps selected text),
            // it sets e.Handled = true in this PreviewKeyDown handler.  WPF's
            // TextCompositionManager then skips raising PreviewTextInput for that
            // keystroke, so the suppression flag is never consumed and leaks into
            // the next key press, silently swallowing it.  Clearing the flag at the
            // top of every PreviewKeyDown ensures any stale suppression is discarded
            // before the new key's TextInput event is evaluated.
            _suppressPromptNextTextInput = false;

            var modifiers = Keyboard.Modifiers;

            if (modifiers == ModifierKeys.None
                && IsPrintableKey(e.Key)
                && !((e.Key == Key.OemTilde || e.Key == Key.OemQuotes) && PromptTextBox.SelectionLength > 0))
            {
                return;
            }

            // ── Ctrl+V / Shift+Insert clipboard-image intercept ───────────────────
            var isCtrlV = e.Key == Key.V && (modifiers & ModifierKeys.Control) == ModifierKeys.Control;
            var isShiftIns = e.Key == Key.Insert && (modifiers & ModifierKeys.Shift) == ModifierKeys.Shift;
            if (isCtrlV || isShiftIns)
            {
                bool clipboardHasImage;
                try { clipboardHasImage = Clipboard.ContainsImage(); }
                catch (System.Runtime.InteropServices.COMException) { clipboardHasImage = false; }

                if (clipboardHasImage)
                {
                    e.Handled = true;
                    BitmapSource? bitmap = null;
                    try { bitmap = Clipboard.GetImage(); }
                    catch (System.Runtime.InteropServices.COMException) { }
                    if (bitmap is not null)
                        SquadDashTrace.Write("UI",
                            $"[ClipboardPaste] raw clipboard bitmap: " +
                            $"pixels={bitmap.PixelWidth}x{bitmap.PixelHeight} " +
                            $"dpi={bitmap.DpiX:F1}x{bitmap.DpiY:F1} " +
                            $"format={bitmap.Format}");
                    if (bitmap is not null && _currentWorkspace is not null)
                    {
                        var workspace = _currentWorkspace;
                        var editor = new ClipboardImageEditorWindow(this, bitmap, isPromptMode: true);
                        editor.ImageAccepted += edited =>
                        {
                            var path = _pastedImageStore.SaveImage(edited, workspace.FolderPath);
                            SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Paste accepted: path={path} SourceImage={editor.SourceImage != null} AnnotationState={editor.AnnotationState != null}");
                            if (editor.SourceImage != null)
                            {
                                _pastedImageStore.SaveAnnotationSidecar(editor.SourceImage, editor.AnnotationState ?? new ClipboardAnnotationState(), path);
                                SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Sidecar saved: source={path}.source.png json={path}.annotation.json");
                            }
                            else
                            {
                                SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] WARNING: SourceImage was null — sidecar NOT saved");
                            }
                            var att  = new FollowUpAttachment("", "Image", null, null, null, ImagePath: path);
                            var list = GetOrCreateFollowUpList(_activeTabId ?? "");
                            list.Add(att);
                            UpdateFollowUpStrip();
                            PersistDraftFollowUp();
                        };
                        OpenEditorModeless(editor);
                    }
                    return;
                }
                // If it's Shift+Insert and there's no image, fall through to let the
                // default text-paste handler deal with it (isShiftIns only — Ctrl+V is
                // handled by the textbox natively for text).
                if (isShiftIns)
                {
                    e.Handled = true;
                    string text = string.Empty;
                    try { text = Clipboard.GetText() ?? string.Empty; }
                    catch (System.Runtime.InteropServices.COMException) { }
                    if (!string.IsNullOrEmpty(text))
                    {
                        var tb = sender as System.Windows.Controls.TextBox;
                        tb?.Focus();
                        System.Windows.Input.ApplicationCommands.Paste.Execute(null, tb);
                    }
                    return;
                }
            }

            // ── Shift+F3: cycle case of selected text ─────────────────────────────
            if (e.Key == Key.F3 && modifiers == ModifierKeys.Shift && PromptTextBox.SelectionLength > 0)
            {
                var selStart     = PromptTextBox.SelectionStart;
                var selectedText = PromptTextBox.SelectedText;

                // Continue an existing cycle if the selection is still on the same range and
                // shows one of our computed variants.
                bool continuing = _promptCycleVariants is not null
                    && selStart == _promptCycleSelStart
                    && selectedText == _promptCycleVariants[_promptCycleIndex];

                if (!continuing)
                {
                    // New selection — initialize cycle state.
                    _promptCycleOriginal  = PromptTextBox.Text;
                    _promptCycleVariants  = TextCaseHelper.ComputeOrderedVariants(selectedText);
                    _promptCycleIndex     = 0;
                    _promptCycleSelStart  = selStart;
                    _promptCycleSelLen    = PromptTextBox.SelectionLength;

                    // First press: normal replacement — creates one undo entry (original → variant).
                    PromptTextBox.SelectedText    = _promptCycleVariants[_promptCycleIndex];
                    PromptTextBox.SelectionStart  = _promptCycleSelStart;
                    PromptTextBox.SelectionLength = _promptCycleVariants[_promptCycleIndex].Length;
                }
                else
                {
                    // Subsequent press on same selection — advance to next variant.
                    _promptCycleIndex = (_promptCycleIndex + 1) % _promptCycleVariants!.Count;
                    var nextVariant = _promptCycleVariants[_promptCycleIndex];

                    // Restore original text without adding to the undo stack, then apply the
                    // new variant as a single replacement so Ctrl+Z always undoes back to original.
                    PromptTextBox.IsUndoEnabled   = false;
                    PromptTextBox.Text            = _promptCycleOriginal!;
                    PromptTextBox.IsUndoEnabled   = true;
                    PromptTextBox.SelectionStart  = _promptCycleSelStart;
                    PromptTextBox.SelectionLength = _promptCycleSelLen;
                    PromptTextBox.SelectedText    = nextVariant;
                    PromptTextBox.SelectionStart  = _promptCycleSelStart;
                    PromptTextBox.SelectionLength = nextVariant.Length;
                }
                e.Handled = true;
                _guidedTourCoordinator.RaiseCycleCaseForward(this);
                return;
            }

            // ── Ctrl+Shift+F3: reverse cycle case of selected text ────────────────
            if (e.Key == Key.F3 && modifiers == (ModifierKeys.Shift | ModifierKeys.Control) && PromptTextBox.SelectionLength > 0)
            {
                var selStart     = PromptTextBox.SelectionStart;
                var selectedText = PromptTextBox.SelectedText;

                bool continuing = _promptCycleVariants is not null
                    && selStart == _promptCycleSelStart
                    && selectedText == _promptCycleVariants[_promptCycleIndex];

                if (!continuing)
                {
                    _promptCycleOriginal  = PromptTextBox.Text;
                    _promptCycleVariants  = TextCaseHelper.ComputeOrderedVariants(selectedText);
                    _promptCycleIndex     = _promptCycleVariants.Count - 1;
                    _promptCycleSelStart  = selStart;
                    _promptCycleSelLen    = PromptTextBox.SelectionLength;

                    PromptTextBox.SelectedText    = _promptCycleVariants[_promptCycleIndex];
                    PromptTextBox.SelectionStart  = _promptCycleSelStart;
                    PromptTextBox.SelectionLength = _promptCycleVariants[_promptCycleIndex].Length;
                }
                else
                {
                    _promptCycleIndex = (_promptCycleIndex - 1 + _promptCycleVariants!.Count) % _promptCycleVariants.Count;
                    var prevVariant = _promptCycleVariants[_promptCycleIndex];

                    PromptTextBox.IsUndoEnabled   = false;
                    PromptTextBox.Text            = _promptCycleOriginal!;
                    PromptTextBox.IsUndoEnabled   = true;
                    PromptTextBox.SelectionStart  = _promptCycleSelStart;
                    PromptTextBox.SelectionLength = _promptCycleSelLen;
                    PromptTextBox.SelectedText    = prevVariant;
                    PromptTextBox.SelectionStart  = _promptCycleSelStart;
                    PromptTextBox.SelectionLength = prevVariant.Length;
                }
                e.Handled = true;
                _guidedTourCoordinator.RaiseCycleCaseReverse(this);
                return;
            }

            // ── Smooth Dictation: Shift+Space on selection ────────────────────────
            if (e.Key == Key.Space && modifiers == ModifierKeys.Shift && PromptTextBox.SelectionLength > 0)
            {
                e.Handled = SmoothDictationHelper.ApplyToTextBox(PromptTextBox);
                return;
            }

            // ── Selection embedding: backtick or apostrophe ───────────────────────────
            if ((e.Key == Key.OemTilde || e.Key == Key.OemQuotes) && modifiers == ModifierKeys.None
                && PromptTextBox.SelectionLength > 0)
            {
                if (MarkdownEditorCommands.ApplyInlineCodeOrFence(PromptTextBox))
                {
                    _suppressPromptNextTextInput = true;
                    e.Handled = true;
                    return;
                }
            }

            // ── Selection embedding: double-quote ─────────────────────────────────────
            if (e.Key == Key.OemQuotes && modifiers == ModifierKeys.Shift
                && PromptTextBox.SelectionLength > 0)
            {
                if (MarkdownEditorCommands.ApplyInlineQuote(PromptTextBox))
                {
                    _suppressPromptNextTextInput = true;
                    e.Handled = true;
                    return;
                }
            }

            // ── Shift+Enter: continue bullet/numbered list in prompt ─────────────
            if ((e.Key is Key.Return or Key.Enter) && modifiers == ModifierKeys.Shift)
            {
                if (MarkdownEditorCommands.ContinueListOnShiftEnter(PromptTextBox))
                {
                    RecordHintFeatureUsed(PromptHintFeature.ShiftEnterNewline);
                    e.Handled = true;
                    return;
                }
            }

            // Record Shift+Enter before dispatching so the hint hides even though WPF
            // handles the newline insertion itself (action resolves to None for Shift+Enter).
            if ((e.Key is Key.Return or Key.Enter) && modifiers == ModifierKeys.Shift)
                RecordHintFeatureUsed(PromptHintFeature.ShiftEnterNewline);

            var action = PromptInputBehavior.ResolveAction(
                MapPromptInputKey(e.Key),
                ctrlPressed: modifiers.HasFlag(ModifierKeys.Control),
                shiftPressed: modifiers.HasFlag(ModifierKeys.Shift),
                runButtonEnabled: RunButton.IsEnabled,
                isMultiLinePrompt: false,
                isIntelliSenseOpen: _intelliSenseState is not null);

            switch (action)
            {
                case PromptInputAction.PrioritizeInQueue:
                    PrioritizeActiveTabToFront();
                    e.Handled = true;
                    break;

                case PromptInputAction.SubmitPrompt:
                    RecordHintFeatureUsed(PromptHintFeature.EnterSend);
                    SquadDashTrace.Write("UI", "Prompt sent: Enter key");
                    RunButton_Click(sender, new RoutedEventArgs());
                    e.Handled = true;
                    break;

                case PromptInputAction.NavigateHistoryPrevious:
                    RecordHintFeatureUsed(PromptHintFeature.CtrlArrowHistory);
                    _conversationManager.NavigateHistory(-1);
                    e.Handled = true;
                    break;

                case PromptInputAction.NavigateHistoryNext:
                    RecordHintFeatureUsed(PromptHintFeature.CtrlArrowHistory);
                    _conversationManager.NavigateHistory(1);
                    e.Handled = true;
                    break;

                case PromptInputAction.IntelliSenseUp:
                    _intelliSenseState = IntelliSenseController.MoveSelection(_intelliSenseState!, -1);
                    UpdateIntelliSensePopup();
                    e.Handled = true;
                    break;

                case PromptInputAction.IntelliSenseDown:
                    _intelliSenseState = IntelliSenseController.MoveSelection(_intelliSenseState!, +1);
                    UpdateIntelliSensePopup();
                    e.Handled = true;
                    break;

                case PromptInputAction.IntelliSenseAccept:
                    ApplyIntelliSenseAccept(andSubmit: e.Key == Key.Return || e.Key == Key.Enter || e.Key == Key.Tab);
                    e.Handled = true;
                    break;

                case PromptInputAction.IntelliSenseDismiss:
                    _intelliSenseState = null;
                    _intelliSenseOwnerBox = null;
                    UpdateIntelliSensePopup();
                    e.Handled = true;
                    break;

                case PromptInputAction.AddQueueSlot:
                    AddEmptyQueueSlot();
                    e.Handled = true;
                    break;
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(PromptTextBox_KeyDown), ex);
        }
        finally
        {
            sw.Stop();
            RecordPromptInputTiming(isTextChanged: false, sw.ElapsedMilliseconds);
            if (sw.ElapsedMilliseconds >= 20)
            {
                SquadDashTrace.Write(TraceCategory.Performance,
                    $"PROMPT_KEYDOWN elapsed={sw.ElapsedMilliseconds}ms key={e.Key} repeat={e.IsRepeat} " +
                    $"handled={e.Handled} textLen={PromptTextBox.Text.Length} caret={PromptTextBox.CaretIndex}");
            }
        }
    }

    private static bool IsCtrlKey(Key key) =>
        key is Key.LeftCtrl or Key.RightCtrl;

    private static bool IsShiftKey(Key key) =>
        key is Key.LeftShift or Key.RightShift;

    private void Window_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        try
        {
            _idleDetectionService?.RecordActivity();
            ShowCodeHealthBannerIfPending();
            if (TryRecoverPromptInputFromStaleModifiers(e))
                return;

            // ── Tour shortcut routing ─────────────────────────────────────────────
            // When a guided-tour step sets a shortcut target (e.g. PromptTextBox for
            // Shift+F3 case-cycling), ensure that control has keyboard focus so the
            // keystroke reaches its normal handler instead of being swallowed by the
            // tour navigator window.
            if (_guidedTourCoordinator.ShortcutTarget is not null && !_guidedTourCoordinator.ShortcutTarget.IsKeyboardFocusWithin)
                _guidedTourCoordinator.ShortcutTarget.Focus();

            // ── Enter advances guided tour when editor does not have focus ────────
            // Allows the user to step through a running tour by pressing Enter while
            // interacting with SquadDash normally.  Swallowed so it doesn't reach
            // the prompt box, buttons, or any other control.
            if (e.Key == Key.Enter
                && Keyboard.Modifiers == ModifierKeys.None
                && _guidedTourController is { IsActive: true }
                && !_guidedTourController.IsEditorFocused
                && !(_guidedTourCoordinator.QuickReplyIntelliSenseEnterLetThrough && _intelliSenseState?.TriggerChar == '['))
            {
                _guidedTourController.Next();
                e.Handled = true;
                return;
            }

            // ── Ctrl+O: open Options ─────────────────────────────────────────────
            if (e.Key == Key.O
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift) == 0
                && (Keyboard.Modifiers & ModifierKeys.Alt) == 0)
            {
                PreferencesMenuItem_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }

            // ── Ctrl+Shift+Break: abort loop (more-specific, checked first) ──────────
            if (e.Key == Key.Cancel
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift) != 0
                && AbortLoopButton.IsEnabled)
            {
                AbortLoopButton_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }

            // ── Ctrl+Break: abort running prompt (from anywhere in the window) ─────
            if (e.Key == Key.Cancel
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift) == 0
                && AbortButton.IsEnabled)
            {
                AbortButton_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }

            // ── Ctrl+Q: add a new queue slot at the rightmost (front of dispatch) ──
            if (e.Key == Key.Q
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift) == 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)   == 0)
            {
                DismissHintPermanently(PromptHintFeature.CtrlQAddQueue);
                AddEmptyQueueSlot();
                e.Handled = true;
                return;
            }

            // ── Ctrl+Shift+Q: add a new queue slot at the leftmost (tail) ────────
            if (e.Key == Key.Q
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     == 0)
            {
                DismissHintPermanently(PromptHintFeature.CtrlQAddQueue);
                AddEmptyQueueSlotAtEnd();
                e.Handled = true;
                return;
            }

            // ── Ctrl+Delete: delete the active queue tab ──────────────────────────
            if (e.Key == Key.Delete
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift) == 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)   == 0
                && _activeTabId is not null)
            {
                DeleteActiveQueueTabWithKeyboard();
                e.Handled = true;
                return;
            }

            // ── Ctrl+Shift+Z: Redo — works in any focused text control ─────────────
            if (e.Key == Key.Z
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift) != 0)
            {
                if (Keyboard.FocusedElement is RichTextBox rtb && rtb.CanRedo)
                {
                    rtb.Redo();
                    e.Handled = true;
                    return;
                }
                if (Keyboard.FocusedElement is TextBox txb && txb.CanUndo)
                {
                    ApplicationCommands.Redo.Execute(null, txb);
                    e.Handled = true;
                    return;
                }
            }

            // ── Ctrl+Shift+A: Revise with AI — fires from ANY focused text box with a selection ──
            if (e.Key == Key.A
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift) != 0)
            {
                if (TryShowRevisePopupForFocusedTextBox())
                {
                    e.Handled = true;
                    return;
                }
            }

            // ── Ctrl+Alt+C: Append selection to clipboard ────────────────────────
            if (e.Key == Key.C
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   == 0)
            {
                string? selected = null;
                if (Keyboard.FocusedElement is System.Windows.Controls.RichTextBox rtb)
                    selected = rtb.Selection.Text;
                else if (Keyboard.FocusedElement is System.Windows.Controls.TextBox tb)
                    selected = tb.SelectedText;

                if (!string.IsNullOrEmpty(selected))
                {
                    ClipboardUtilities.AppendToClipboard(selected);
                    e.Handled = true;
                    return;
                }
            }

            // ── Ctrl+Shift+V: attach clipboard text as a follow-up to the active prompt/tab ──
            if (e.Key == Key.V
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   != 0)
            {
                var clipText = Clipboard.GetText();
                if (!string.IsNullOrEmpty(clipText))
                    AttachContextFollowUp(BuildClipboardAttachDescription(clipText), BuildTypedAttachmentBlock("clipboard", null, clipText));
                e.Handled = true;
                return;
            }

            // ── Ctrl+Alt+Shift+PageUp: move prompt panel above the transcript ─────────
            if (e.Key == Key.PageUp
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   != 0)
            {
                SetPromptPanelOnTop(true);
                e.Handled = true;
                return;
            }

            // ── Ctrl+Alt+Shift+PageDown: return prompt panel to the bottom ─────────────
            if (e.Key == Key.PageDown
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   != 0)
            {
                SetPromptPanelOnTop(false);
                e.Handled = true;
                return;
            }

            // ── Ctrl+Alt+Plus / Ctrl+Alt+Add: next tint stop ─────────────────────
            if ((e.Key == Key.OemPlus || e.Key == Key.Add)
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   == 0)
            {
                SetWorkspaceTintStop((_activeTintStop + 1) % 8);
                e.Handled = true;
                return;
            }

            // ── Ctrl+Alt+Minus / Ctrl+Alt+Subtract: previous tint stop ───────────
            if ((e.Key == Key.OemMinus || e.Key == Key.Subtract)
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   == 0)
            {
                SetWorkspaceTintStop((_activeTintStop + 7) % 8);
                e.Handled = true;
                return;
            }

            // ── Escape: cancel docking test recording ────────────────────────────────
            if (e.Key == Key.Escape && _dockingRecorder?.IsIdle == false)
            {
                _dockingRecorder.Cancel();
                _dockingRecorder = null;
                if (_dockingService is not null)
                    _dockingService.TestRecorder = null;
                RecordingIndicatorBorder.Visibility = Visibility.Collapsed;
                RecordDockingTestMenuItem.Header    = "Record Docking Test Case";
                RecordDockingTestMenuItem.IsEnabled = true;
                e.Handled = true;
                return;
            }

            // ── Escape: dismiss doc find bar from any focus position (incl. WebBrowser preview) ──
            if (e.Key == Key.Escape && _docSourceFindBar is not null)
            {
                HideDocSourceFindBar();
                e.Handled = true;
                return;
            }

            // ── Feature 1: Guard against rerouting input when DocSourceTextBox has focus ──
            if (DocSourceTextBox?.IsFocused == true)
            {
                // Allow Ctrl+F to trigger find-in-source instead of transcript search
                if (e.Key == Key.F && (Keyboard.Modifiers & ModifierKeys.Control) != 0)
                {
                    ShowDocSourceFindBar();
                    e.Handled = true;
                    return;
                }
                // Ctrl+B: wrap selection (or insert empty pair) in markdown bold
                if (e.Key == Key.B && (Keyboard.Modifiers & ModifierKeys.Control) != 0)
                {
                    DocSourceTextBox_ApplyBold();
                    e.Handled = true;
                    return;
                }
                // Ctrl+I: wrap selection in markdown italic
                if (e.Key == Key.I && (Keyboard.Modifiers & ModifierKeys.Control) != 0)
                {
                    DocSourceTextBox_ApplyItalic();
                    e.Handled = true;
                    return;
                }
                // Let Ctrl+Shift+A (Revise) and Ctrl+Shift+C (Cleanup) fall through
                // so the window-level handlers below can process them.
                if ((e.Key == Key.A || e.Key == Key.C)
                    && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                    && (Keyboard.Modifiers & ModifierKeys.Shift)   != 0
                    && (Keyboard.Modifiers & ModifierKeys.Alt)     == 0)
                {
                    // Fall through to the Ctrl+Shift+A / Ctrl+Shift+C handlers below.
                }
                // Let Alt+Arrow through for camelCase navigation.
                else
                {
                    var effectiveKeyDoc = e.Key == Key.System ? e.SystemKey : e.Key;
                    if ((effectiveKeyDoc == Key.Left || effectiveKeyDoc == Key.Right)
                        && (Keyboard.Modifiers & ModifierKeys.Alt) != 0
                        && (Keyboard.Modifiers & ModifierKeys.Control) == 0)
                    {
                        // Fall through to the camelCase nav block below.
                    }
                    // Let bare Ctrl key events fall through so the double-tap PTT state machine
                    // can track them. All other keys are eaten here.
                    else if (!IsCtrlKey(e.Key))
                        return;
                }
            }

            // Also guard the transcript search box and the doc find text box —
            // but let bare Ctrl key events fall through so the PTT state machine can track them.
            if (SearchBox?.IsFocused == true && !IsCtrlKey(e.Key)) return;
            if (_docSourceFindTextBox?.IsFocused == true && !IsCtrlKey(e.Key)) return;

            if (_pttState == PttState.Idle
                && PromptTextBox?.IsKeyboardFocusWithin == true
                && Keyboard.Modifiers == ModifierKeys.None
                && IsPrintableKey(e.Key))
            {
                return;
            }

            // ── Fullscreen transcript: any printable key (no Ctrl/Alt) peeks prompt without exiting fullscreen ──
            // Only intercept on the FIRST key (when prompt is hidden); once visible let the TextBox handle input normally.
            if (_transcriptFullScreenEnabled
                && !_fullScreenPromptVisible
                && Keyboard.FocusedElement is not TextBox
                && (Keyboard.Modifiers & (ModifierKeys.Control | ModifierKeys.Alt)) == ModifierKeys.None
                && IsPrintableKey(e.Key))
            {
                ShowFullScreenPrompt();
                var ch = KeyToChar(e.Key, (Keyboard.Modifiers & ModifierKeys.Shift) != 0);
                if (PromptTextBox is not { } promptBox)
                    return;
                if (ch.HasValue)
                    promptBox.AppendText(ch.Value.ToString());
                promptBox.CaretIndex = promptBox.Text.Length;
                promptBox.Focus();
                e.Handled = true;
                return;
            }

            // ── Search shortcuts ─────────────────────────────────────────────────
            if (e.Key == Key.F && (Keyboard.Modifiers & ModifierKeys.Control) != 0)
            {
                // If docs panel is open, Ctrl+F searches the doc — even if focus is on
                // a toolbar button, the topics tree, or the rendered preview.
                if (DocsPanel.Visibility == Visibility.Visible && DocSourceTextBox != null)
                {
                    ShowDocSourceFindBar();
                    e.Handled = true;
                    return;
                }
                SearchBox?.Focus();
                SearchBox?.SelectAll();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.F3)
            {
                // When the prompt box has a selection, Shift+F3 should cycle case there
                // (handled by PromptTextBox_KeyDown), not navigate search results.
                if ((Keyboard.Modifiers & ModifierKeys.Shift) != 0
                    && PromptTextBox?.IsKeyboardFocusWithin == true
                    && PromptTextBox.SelectionLength > 0)
                    return;

                if ((Keyboard.Modifiers & ModifierKeys.Shift) != 0)
                    _search.NavigatePrev();
                else
                    _search.NavigateNext();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.F10 || (e.Key == Key.System && e.SystemKey == Key.F10))
            {
                RecordDockingTestMenuItem_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }

            if (e.Key == Key.F11 && (Keyboard.Modifiers & ModifierKeys.Shift) != 0)
            {
                ToggleAgentsPanelFocusMode();
                e.Handled = true;
                return;
            }

            if (e.Key == Key.F11)
            {
                SetTranscriptFullScreen(!_transcriptFullScreenEnabled);
                e.Handled = true;
                return;
            }

            if (e.Key == Key.Escape && _transcriptFullScreenEnabled && _pttState != PttState.Active)
            {
                e.Handled = true;
                if (_fullScreenPromptVisible)
                    HideFullScreenPrompt();
                else
                    SetTranscriptFullScreen(false);
                return;
            }

            // ── Ctrl+Shift+C: AI Cleanup with selection, screenshot overlay otherwise ──
            if (e.Key == Key.C &&
                (Keyboard.Modifiers & ModifierKeys.Control) != 0 &&
                (Keyboard.Modifiers & ModifierKeys.Shift) != 0 &&
                (Keyboard.Modifiers & ModifierKeys.Alt) == 0)
            {
                if (TryDirectReviseForFocusedTextBox(_settingsSnapshot.CleanupPrompt))
                {
                    e.Handled = true;
                    return;
                }
                ShowScreenshotOverlay();
                e.Handled = true;
                return;
            }

            // ── Fullscreen: paste clipboard text to prompt (Ctrl+V or Shift+Insert) ──
            if (_transcriptFullScreenEnabled &&
                Keyboard.FocusedElement is not TextBox &&
                ((e.Key == Key.V && (Keyboard.Modifiers & ModifierKeys.Control) != 0) ||
                 (e.Key == Key.Insert && (Keyboard.Modifiers & ModifierKeys.Shift) != 0)) &&
                Clipboard.ContainsText())
            {
                var text = Clipboard.GetText();
                if (!_fullScreenPromptVisible)
                    ShowFullScreenPrompt();
                if (PromptTextBox is not { } promptBox)
                    return;
                promptBox.AppendText(text);
                promptBox.CaretIndex = promptBox.Text.Length;
                promptBox.Focus();
                e.Handled = true;
                return;
            }

            // ── Prompt text box: Ctrl+B for markdown bold ─────────────────────
            if (e.Key == Key.B &&
                (Keyboard.Modifiers & ModifierKeys.Control) != 0 &&
                PromptTextBox?.IsFocused == true)
            {
                PromptTextBox_ApplyBold();
                e.Handled = true;
                return;
            }

            // ── Ctrl+Tab / Ctrl+Shift+Tab: cycle through queue tabs ──────────────
            if (e.Key == Key.Tab &&
                (Keyboard.Modifiers & ModifierKeys.Control) != 0 &&
                _promptQueue.Items.Count > 0)
            {
                bool reverse = (Keyboard.Modifiers & ModifierKeys.Shift) != 0;
                DismissHintPermanently(PromptHintFeature.CtrlTabNavigation);
                CycleQueueTab(reverse);
                e.Handled = true;
                return;
            }

            // ── Ctrl+Alt+PageUp: navigate to previous question prompt ────────────
            if (e.Key == Key.PageUp
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   == 0)
            {
                PromptNavUpButton_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }

            // ── Ctrl+Alt+PageDown: navigate to next question prompt ──────────────
            if (e.Key == Key.PageDown
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   == 0)
            {
                PromptNavDownButton_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }

            // ── Ctrl+Page Up / Ctrl+Page Down: navigate between prompts ─────────
            if (e.Key == Key.PageUp
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     == 0)
            {
                PromptNavUpButton_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }
            if (e.Key == Key.PageDown
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   == 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     == 0)
            {
                PromptNavDownButton_Click(this, new RoutedEventArgs());
                e.Handled = true;
                return;
            }

            // ── Ctrl+Shift+Page Down: jump to the latest (most recent) prompt ────
            if (e.Key == Key.PageDown
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (Keyboard.Modifiers & ModifierKeys.Shift)   != 0
                && (Keyboard.Modifiers & ModifierKeys.Alt)     == 0)
            {
                NavigateToLatestTranscriptPrompt();
                e.Handled = true;
                return;
            }

            // ── Page Up / Page Down: scroll active transcript ────────────────
            // Intercept plain PageUp/PageDown unconditionally (even from the prompt
            // box) so the transcript is always reachable by keyboard, but leave the
            // key alone when a document editor or its find bar has focus so those
            // controls can scroll their own content normally.
            if (e.Key == Key.PageUp
                && Keyboard.Modifiers == ModifierKeys.None
                && DocSourceTextBox?.IsKeyboardFocusWithin != true
                && _docSourceFindTextBox?.IsFocused != true)
            {
                ActiveScrollController.ScrollPageUp();
                e.Handled = true;
                return;
            }
            if (e.Key == Key.PageDown
                && Keyboard.Modifiers == ModifierKeys.None
                && DocSourceTextBox?.IsKeyboardFocusWithin != true
                && _docSourceFindTextBox?.IsFocused != true)
            {
                ActiveScrollController.ScrollPageDown();
                e.Handled = true;
                return;
            }

            // ── Ctrl+End: scroll main transcript to bottom ────────────────────
            if (e.Key == Key.End &&
                (Keyboard.Modifiers & ModifierKeys.Control) != 0 &&
                PromptTextBox?.IsFocused != true)
            {
                ActiveScrollController.ScrollToBottom();
                e.Handled = true;
                return;
            }

            // ── F7/F8/F9 with Shift: save layout preset ──────────────────────
            if ((e.Key == Key.F7 || e.Key == Key.F8 || e.Key == Key.F9) &&
                (Keyboard.Modifiers & ModifierKeys.Shift) != 0)
            {
                int slotIndex = e.Key - Key.F7; // F7 -> 0, F8 -> 1, F9 -> 2
                SaveLayoutPreset(slotIndex);
                e.Handled = true;
                return;
            }

            // ── F7/F8/F9 without Shift: restore layout preset ──────────────────
            if ((e.Key == Key.F7 || e.Key == Key.F8 || e.Key == Key.F9) &&
                (Keyboard.Modifiers & ModifierKeys.Shift) == 0)
            {
                int slotIndex = e.Key - Key.F7; // F7 -> 0, F8 -> 1, F9 -> 2
                RestoreLayoutPreset(slotIndex);
                e.Handled = true;
                return;
            }

            // ── Alt+Left / Alt+Right: camelCase segment navigation ────────────────
            {
                var focusedTb  = Keyboard.FocusedElement as TextBox;
                var focusedRtb = Keyboard.FocusedElement as RichTextBox;
                if (focusedTb is not null && _camelCaseNav.HandlePreviewKeyDown(e, focusedTb)) {
                    e.Handled = true;
                    return;
                }
                if (focusedRtb is not null && _camelCaseNavRtb.HandlePreviewKeyDown(e, focusedRtb)) {
                    e.Handled = true;
                    return;
                }
            }

            switch (_pttState)
            {
                case PttState.Idle:
                    if (IsCtrlKey(e.Key) && !e.IsRepeat)
                    {
                        _ctrlFirstDownTime = DateTime.UtcNow;
                        _pttState = PttState.TapDown;
                    }
                    break;

                case PttState.TapDown:
                    if (IsCtrlKey(e.Key))
                    {
                        // Still holding first Ctrl — check if held too long
                        if (e.IsRepeat && (DateTime.UtcNow - _ctrlFirstDownTime).TotalMilliseconds > PttMaxTapHoldMs)
                            _pttState = PttState.Idle;
                    }
                    else
                    {
                        // Any other key invalidates the sequence
                        _pttState = PttState.Idle;
                    }
                    break;

                case PttState.TapReleased:
                    if (IsCtrlKey(e.Key) && !e.IsRepeat)
                    {
                        var gapMs = (DateTime.UtcNow - _ctrlFirstReleaseTime).TotalMilliseconds;
                        if (gapMs <= PttDoubleClickTime)
                        {
                            TryStartPushToTalkFromFocusedTarget(gapMs);
                        }
                        else
                        {
                            // Too slow — treat as fresh first tap
                            _ctrlFirstDownTime = DateTime.UtcNow;
                            _pttState = PttState.TapDown;
                        }
                    }
                    else if (!IsCtrlKey(e.Key))
                    {
                        _pttState = PttState.Idle;
                    }
                    break;

                case PttState.Active:
                    if (IsCtrlKey(e.Key) && e.IsRepeat)
                    {
                        // Still holding Ctrl — keep recording
                    }
                    else if (e.Key == Key.Escape)
                    {
                        e.Handled = true;
                        _ = StopPushToTalkAsync(send: false);
                    }
                    else if (IsShiftKey(e.Key))
                    {
                        // Shift held during recording — flag immediately so Ctrl release suppresses send
                        // even if the KeyUp is swallowed by an IME or third-party keyboard hook.
                        _pttShiftTappedDuringRecording = true;
                        _pttWindow?.MarkShiftSuppressed();
                    }
                    else if (!IsCtrlKey(e.Key))
                    {
                        // Any other key disengages PTT (no send)
                        _ = StopPushToTalkAsync(send: false);
                    }
                    break;
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(Window_PreviewKeyDown), ex);
        }
    }

    /// <summary>Resets the PTT double-tap state machine to Idle (called when an owned window closes).</summary>
    internal void ResetPttState()
    {
        _pttState = PttState.Idle;
        _ctrlFirstDownTime = default;
        _ctrlFirstReleaseTime = default;
    }

    private void TryStartPushToTalkFromFocusedTarget(double secondTapGapMs)
    {
        // Resolve the target at activation time — prefer a focused RichTextBox
        // (e.g. DocSourceTextBox) over the fallback TextBox path.
        var focusedTextBox     = Keyboard.FocusedElement as TextBox;
        var focusedRichTextBox = Keyboard.FocusedElement as RichTextBox;

        // If the focused element is the active transcript, auto-shift focus to the prompt box
        // so dictated text goes to the prompt input instead of the transcript.
        if (focusedRichTextBox == ActiveTranscriptBox)
        {
            focusedRichTextBox = null;
            PromptTextBox?.Focus();
            focusedTextBox = PromptTextBox;
        }

        _pttTargetRichTextBox = null;
        if (focusedRichTextBox != null)
        {
            _pttTargetRichTextBox = focusedRichTextBox;
            _pttTargetTextBox = null;
        }
        else
        {
            _pttTargetTextBox = focusedTextBox != null && focusedTextBox != PromptTextBox
                ? focusedTextBox
                : PromptTextBox;
        }

        var pttTargetExists = _pttTargetRichTextBox != null || _pttTargetTextBox != null;
        if (!pttTargetExists)
        {
            SquadDashTrace.Write("UI", "PTT pending cancelled: no target textbox");
            _pttState = PttState.Idle;
            return;
        }

        // Capture caret/selection before the PTT panel becomes visible (layout shifts can reset it).
        if (_pttTargetRichTextBox != null)
        {
            _sessionCaretIndex      = _pttTargetRichTextBox.GetSelectionStart();
            _sessionSelectionLength = _pttTargetRichTextBox.GetSelectionLength();
        }
        else
        {
            _sessionCaretIndex      = _pttTargetTextBox!.SelectionStart;
            _sessionSelectionLength = _pttTargetTextBox!.SelectionLength;
        }

        // Queue whenever the target is the prompt box AND auto-send is enabled.
        // EnqueueCurrentPrompt works whether or not a prompt is currently running,
        // so we no longer need to gate on !_isPromptRunning.
        // Guard _activeTabId == null: when the user is editing a queued tab via Ctrl+Up/Down,
        // the prompt box may be empty but we must not treat that as a new draft auto-send.
        _voiceStartedWithSendEnabled = _activeTabId == null
                                       && _settingsSnapshot.PttAutoSend
                                       && _pttTargetRichTextBox == null
                                       && _pttTargetTextBox == PromptTextBox
                                       && string.IsNullOrEmpty(PromptTextBox?.Text);
        SquadDashTrace.Write("UI",
            $"PTT started: secondTapGapMs={secondTapGapMs:0} voiceSendEnabled={_voiceStartedWithSendEnabled} " +
            $"targetIsPrompt={_pttTargetTextBox == PromptTextBox} promptHasText={!string.IsNullOrEmpty(PromptTextBox?.Text)}");

        // Re-evaluate on each PTT activation: true only when quick reply
        // buttons are visible, the prompt box was empty at start time,
        // and buttons appeared at least 400ms ago (so user could see them).
        // Guard _activeTabId == null: Ctrl+Up/Down navigation to a queued tab leaves
        // the prompt box empty, which must not be mistaken for an empty active draft.
        _dictationStartedForQuickReply = _activeTabId == null
                                         && _lastQuickReplyEntry?.AllowQuickReplies == true
                                         && _currentQuickReplyOptions.Length > 0
                                         && string.IsNullOrEmpty(PromptTextBox?.Text)
                                         && (DateTime.UtcNow - _quickRepliesShownAt).TotalMilliseconds >= QuickReplyReadWindowMs;
        _pttState = PttState.Active;
        _ = StartPushToTalkAsync();
    }

    /// <summary>
    /// Called when another application takes focus away from SquadDash.
    /// WPF does not deliver KeyUp events while the window is inactive, so if Ctrl is
    /// released in the other app we would never see it. Instead of stopping PTT
    /// immediately (which would discard in-progress dictation), we:
    ///   1. Flag that focus was lost — this suppresses auto-send when PTT eventually stops.
    ///   2. Start a 100 ms polling timer that uses GetAsyncKeyState to watch for Ctrl release.
    ///      When both Ctrl keys are up, PTT stops (no send).
    /// </summary>
    private void Window_Deactivated(object sender, EventArgs e)
    {
        try
        {
            SquadDashTrace.Write("Approval",
                $"MainWindow_Deactivated entered calloutVisible={_approvalAttentionCallout is not null} "
                + $"deferred={_deferredApprovalCallout is not null} wpfIsActive={IsActive} "
                + $"{WindowHelper.DescribeForegroundOwnership()}.");

            // Approval callouts are intentionally topmost while SquadDash is active. Dismiss
            // them as soon as another application takes focus so they cannot cover that app.
            // If one was already displayed its in-memory shown marker prevents another cue.
            if (_approvalAttentionCallout is not null)
            {
                _approvalAttentionCallout.Close();
                _approvalAttentionCallout = null;
                _guidedTourCoordinator.ClearTourMenuTracking(closeMenus: true);
                SquadDashTrace.Write("Approval", "Visible callout dismissed because SquadDash was deactivated.");
            }

            switch (_pttState)
            {
                case PttState.Active:
                    // Mark so that whenever PTT stops (via poll or KeyUp after refocus), send is suppressed.
                    _pttLostFocusDuringRecording = true;
                    _pttWindow?.MarkShiftSuppressed(); // update the visual hint
                    StartPttCtrlPollTimer();
                    break;

                case PttState.TapDown:
                case PttState.TapReleased:
                    // Reset stale tap sequence — cannot complete the double-tap while inactive.
                    _pttState = PttState.Idle;
                    _ctrlFirstDownTime = default;
                    _ctrlFirstReleaseTime = default;
                    break;
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(Window_Deactivated), ex);
        }
    }

    /// <summary>
    /// Called when SquadDash regains focus. If the user kept Ctrl held while switching back,
    /// cancel the poll timer and return to normal key-event handling. The
    /// <c>_pttLostFocusDuringRecording</c> flag remains set so that when they finally release
    /// Ctrl the send is still suppressed — they may not have seen what was dictated.
    /// If Ctrl is already up when we regain focus, the poll timer will fire within 100 ms
    /// and stop PTT cleanly.
    /// </summary>
    private void Window_Activated(object sender, EventArgs e)
    {
        try
        {
            if (_pttState == PttState.Active && _pttCtrlPollTimer is not null)
            {
                // Still Active — check immediately whether Ctrl is already released.
                if (!NativeMethods.IsCtrlPhysicallyDown())
                {
                    StopPttCtrlPollTimer();
                    _ = StopPushToTalkAsync(send: false); // _pttLostFocusDuringRecording already set
                }
                else
                {
                    // Ctrl still held — normal PreviewKeyUp will handle release; cancel poll.
                    StopPttCtrlPollTimer();
                }
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(Window_Activated), ex);
        }
    }

    private void StartPttCtrlPollTimer()
    {
        if (_pttCtrlPollTimer is not null)
            return; // already running

        _pttCtrlPollTimer = new DispatcherTimer(DispatcherPriority.Normal, Dispatcher)
        {
            Interval = UiTimingConstants.PttCtrlPollInterval
        };
        _pttCtrlPollTimer.Tick += (_, _) =>
        {
            if (_pttState != PttState.Active || NativeMethods.IsCtrlPhysicallyDown())
                return; // Ctrl still down or PTT already stopped — keep waiting

            // Ctrl has been released while inactive — stop PTT without sending.
            StopPttCtrlPollTimer();
            _ = StopPushToTalkAsync(send: false);
        };
        _pttCtrlPollTimer.Start();
    }

    private void StopPttCtrlPollTimer()
    {
        if (_pttCtrlPollTimer is null)
            return;
        _pttCtrlPollTimer.Stop();
        _pttCtrlPollTimer = null;
    }

    private bool TryRecoverPromptInputFromStaleModifiers(KeyEventArgs e)
    {
        if (PromptTextBox?.IsKeyboardFocusWithin != true || !IsPrintableKey(e.Key))
            return false;

        var logicalModifiers = Keyboard.Modifiers;
        var physicalModifiers = NativeMethods.GetPhysicalModifierKeys();
        const ModifierKeys shortcutModifiers = ModifierKeys.Control | ModifierKeys.Alt | ModifierKeys.Windows;

        if ((logicalModifiers & shortcutModifiers) == ModifierKeys.None ||
            (physicalModifiers & shortcutModifiers) != ModifierKeys.None)
            return false;

        var ch = KeyToChar(e.Key, (physicalModifiers & ModifierKeys.Shift) != 0);
        if (ch is null)
            return false;

        var insertionStart = PromptTextBox.SelectionStart;
        PromptTextBox.SelectedText = ch.Value.ToString();
        PromptTextBox.CaretIndex = insertionStart + 1;
        e.Handled = true;
        SquadDashTrace.Write(
            TraceCategory.UI,
            $"PROMPT_STALE_MODIFIER_RECOVERY key={e.Key} logical={logicalModifiers} physical={physicalModifiers} textLen={PromptTextBox.Text.Length}");
        ResetPttState();
        return true;
    }

    private void Window_PreviewKeyUp(object sender, KeyEventArgs e)
    {
        try
        {
            // Commit any pending font-scale change immediately when Ctrl is released
            // so the apply happens at the exact moment scrolling stops.
            if (IsCtrlKey(e.Key) && _fontScaleCommitTimer is { IsEnabled: true })
                CommitFontSizeScale();

            switch (_pttState)
            {
                case PttState.TapDown:
                    if (IsCtrlKey(e.Key))
                    {
                        var heldMs = (DateTime.UtcNow - _ctrlFirstDownTime).TotalMilliseconds;
                        if (heldMs <= PttMaxTapHoldMs)
                        {
                            _ctrlFirstReleaseTime = DateTime.UtcNow;
                            _pttState = PttState.TapReleased;
                        }
                        else
                        {
                            _pttState = PttState.Idle;
                        }
                    }
                    break;

                case PttState.Active:
                    if (IsShiftKey(e.Key))
                    {
                        _pttShiftTappedDuringRecording = true;
                        _pttWindow?.MarkShiftSuppressed();
                    }
                    else if (IsCtrlKey(e.Key))
                    {
                        // Check shift via multiple paths: ModifierKeys (VK_SHIFT), and the
                        // left/right-specific device state (VK_LSHIFT/VK_RSHIFT). Some IMEs
                        // and keyboard utilities update the sided VKs but not the combined flag,
                        // or vice versa — querying all three makes suppression reliable.
                        var shiftHeld = (e.KeyboardDevice.Modifiers & ModifierKeys.Shift) != 0
                                        || e.KeyboardDevice.IsKeyDown(Key.LeftShift)
                                        || e.KeyboardDevice.IsKeyDown(Key.RightShift);
                        var suppress = shiftHeld || _pttShiftTappedDuringRecording || _pttHadPreexistingText
                                                 || _pttLostFocusDuringRecording;
                        StopPttCtrlPollTimer();
                        var shouldSend = _voiceStartedWithSendEnabled && !suppress;
                        // When the dictation session started with quick replies visible and an
                        // empty box, route directly as a quick reply response instead of queuing.
                        var sendAsQuickReply = shouldSend && _dictationStartedForQuickReply;
                        _ = StopPushToTalkAsync(send: shouldSend && !sendAsQuickReply, sendAsQuickReply: sendAsQuickReply);
                    }
                    break;
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(Window_PreviewKeyUp), ex);
        }
    }

    private async Task StartPushToTalkAsync()
    {
        var targetIsPrompt = _pttTargetRichTextBox == null && (_pttTargetTextBox == null || _pttTargetTextBox == PromptTextBox);
        var targetHasText  = _pttTargetRichTextBox != null
            ? !string.IsNullOrEmpty(_pttTargetRichTextBox.GetPlainText())
            : !string.IsNullOrEmpty((_pttTargetTextBox ?? PromptTextBox).Text);
        _pttHadPreexistingText = targetHasText;
        _promptHasVoiceInput = false;
        RecordHintFeatureUsed(PromptHintFeature.PushToTalk);

        // In fullscreen transcript mode, peek the prompt so the user can see dictated text.
        if (_transcriptFullScreenEnabled && !_fullScreenPromptVisible)
            ShowFullScreenPrompt();
        _pttShiftTappedDuringRecording = false;
        _pttLostFocusDuringRecording = false;
        string key, region;
        if (_settingsSnapshot.SpeechProvider == SpeechProvider.OpenAI)
        {
            key = _settingsSnapshot.OpenAiSpeechApiKey ?? string.Empty;
            region = string.Empty;
        }
        else
        {
            key = Environment.GetEnvironmentVariable("SQUAD_SPEECH_KEY", EnvironmentVariableTarget.User) ?? string.Empty;
            region = _settingsSnapshot.SpeechRegion ?? string.Empty;
        }

        if (string.IsNullOrWhiteSpace(key) ||
            (_settingsSnapshot.SpeechProvider == SpeechProvider.Azure && string.IsNullOrWhiteSpace(region)))
        {
            SquadDashTrace.Write(
                TraceCategory.UI,
                $"PTT_START skipped missingConfig provider={_settingsSnapshot.SpeechProvider} hasKey={!string.IsNullOrWhiteSpace(key)} hasRegion={!string.IsNullOrWhiteSpace(region)}");
            _pttState = PttState.Idle;
            return;
        }

        SquadDashTrace.Write(
            TraceCategory.UI,
            $"PTT_START provider={_settingsSnapshot.SpeechProvider} targetIsPrompt={targetIsPrompt} targetHadText={_pttHadPreexistingText}");

        // Only show the "release to send" hint when targeting an empty prompt AND auto-send is enabled.
        _pttWindow = new PushToTalkWindow(this, showHint: targetIsPrompt && !_pttHadPreexistingText && _voiceStartedWithSendEnabled);
        PositionPttWindow();
        _pttWindow.Show();
        _pttWindow.VolumeBar.Height = 0;

        _speechService = _settingsSnapshot.SpeechProvider == SpeechProvider.OpenAI
            ? new WhisperSpeechRecognitionService()
            : new AzureSpeechRecognitionService();

        _speechService.PhraseRecognized += (_, text) =>
            Dispatcher.BeginInvoke(DispatcherPriority.Input, () => AppendSpeechToPrompt(text));

        _speechService.VolumeChanged += (_, level) => QueuePttVolumeUpdate(level);

        _speechService.RecognitionError += (_, msg) =>
            Dispatcher.BeginInvoke(DispatcherPriority.Input, () =>
            {
                _ = StopPushToTalkAsync(send: false);
                AppendLine("[voice error] " + msg, System.Windows.Media.Brushes.Red);
            });

        try
        {
            var phraseHints = BuildSpeechPhraseHints();
            await _speechService.StartAsync(key, region, phraseHints).ConfigureAwait(false);
        }
        catch (Exception ex)
        {
            Dispatcher.Invoke(() =>
            {
                _pttState = PttState.Idle;
                ClosePttWindow();
                try { _speechService?.Dispose(); } catch { }
                _speechService = null;
                SquadDashTrace.Write(TraceCategory.UI, $"PTT_START failed provider={_settingsSnapshot.SpeechProvider}: {ex.Message}");
                AppendLine("[voice error] " + ex.Message, System.Windows.Media.Brushes.Red);
            });
        }
    }

    /// <summary>
    /// Builds the phrase list registered with Azure Speech to improve recognition
    /// of unusual team member names (e.g. "Lyra Morn", "Vesper Knox", "Jae Min Kade").
    /// Emits both full names and individual name tokens so partial references ("ask Lyra") work.
    /// </summary>
    private IReadOnlyList<string> BuildSpeechPhraseHints()
    {
        if (_currentWorkspace is null)
            return [];

        try
        {
            var members = _teamRosterLoader.Load(_currentWorkspace.FolderPath);
            var phrases = new List<string>(members.Count * 3);
            foreach (var member in members)
            {
                if (string.IsNullOrWhiteSpace(member.Name))
                    continue;

                phrases.Add(member.Name);

                // Also add each individual token so partial references like "ask Lyra" resolve
                foreach (var token in member.Name.Split(' ', StringSplitOptions.RemoveEmptyEntries))
                    if (token.Length > 2)
                        phrases.Add(token);
            }
            return phrases;
        }
        catch
        {
            return [];
        }
    }

    private void PositionPttWindow()
    {
        if (_pttWindow is null)
            return;

        System.Windows.Point physicalPoint;
        FrameworkElement dpiSource;
        if (_pttTargetRichTextBox != null)
        {
            dpiSource = _pttTargetRichTextBox;
            try
            {
                var caretRect = _pttTargetRichTextBox.GetRectFromOffset(_sessionCaretIndex);
                physicalPoint = _pttTargetRichTextBox.PointToScreen(
                    new System.Windows.Point(caretRect.Left, caretRect.Bottom));
            }
            catch
            {
                physicalPoint = _pttTargetRichTextBox.PointToScreen(
                    new System.Windows.Point(0, _pttTargetRichTextBox.ActualHeight + 4));
            }
        }
        else
        {
            var target = _pttTargetTextBox ?? PromptTextBox;
            dpiSource = target;
            try
            {
                var caretRect = target.GetRectFromCharacterIndex(_sessionCaretIndex);
                physicalPoint = target.PointToScreen(new System.Windows.Point(caretRect.Left, caretRect.Bottom));
            }
            catch
            {
                physicalPoint = target.PointToScreen(new System.Windows.Point(0, target.ActualHeight + 4));
            }
        }

        // Get the work area (physical px) for whichever monitor the caret is on.
        var physWa = NativeMethods.GetWorkAreaForPhysicalPoint((int)physicalPoint.X, (int)physicalPoint.Y);

        // Convert everything to WPF logical DIPs.
        var logicalPoint = DpiHelper.PhysicalToLogical(dpiSource, physicalPoint);
        var logicalWaOrigin = DpiHelper.PhysicalToLogical(dpiSource, new System.Windows.Point(physWa.Left, physWa.Top));
        var logicalWaCorner = DpiHelper.PhysicalToLogical(dpiSource, new System.Windows.Point(physWa.Right, physWa.Bottom));
        var logicalWorkArea = new System.Windows.Rect(logicalWaOrigin, logicalWaCorner);

        _pttWindow.PositionUnderCaret(logicalPoint, logicalWorkArea);
    }

    private void ClosePttWindow()
    {
        _pttWindow?.Close();
        _pttWindow = null;
    }

    private void QueuePttVolumeUpdate(double level)
    {
        Interlocked.Increment(ref _pttVolumeEventTraceCount);
        lock (_pttVolumeUpdateGate)
        {
            _pendingPttVolumeHeight = Math.Max(2, level * 36);
            if (_pttVolumeUpdateQueued)
                return;

            _pttVolumeUpdateQueued = true;
        }

        // Volume callbacks can arrive very quickly. Keep them below keyboard input
        // priority and coalesce to one queued UI update so the meter cannot starve typing.
        try
        {
            _ = Dispatcher.BeginInvoke(DispatcherPriority.Background, new Action(FlushPttVolumeUpdate));
        }
        catch (ObjectDisposedException)
        {
            lock (_pttVolumeUpdateGate)
                _pttVolumeUpdateQueued = false;
        }
        catch (InvalidOperationException)
        {
            lock (_pttVolumeUpdateGate)
                _pttVolumeUpdateQueued = false;
        }
    }

    private void FlushPttVolumeUpdate()
    {
        double height;
        lock (_pttVolumeUpdateGate)
        {
            height = _pendingPttVolumeHeight;
            _pttVolumeUpdateQueued = false;
        }

        if (_pttWindow is not null)
            _pttWindow.VolumeBar.Height = height;

        Interlocked.Increment(ref _pttVolumeUiUpdateTraceCount);
        TracePttVolumeSummaryIfNeeded();
    }

    private void TracePttVolumeSummaryIfNeeded()
    {
        if (_pttVolumeTraceStopwatch.ElapsedMilliseconds < PttVolumeTraceIntervalMs)
            return;

        var eventCount = Interlocked.Exchange(ref _pttVolumeEventTraceCount, 0);
        var uiUpdateCount = Interlocked.Exchange(ref _pttVolumeUiUpdateTraceCount, 0);
        SquadDashTrace.Write(
            TraceCategory.UI,
            $"PTT_VOLUME batchMs={_pttVolumeTraceStopwatch.ElapsedMilliseconds} events={eventCount} uiUpdates={uiUpdateCount} " +
            $"state={_pttState} queued={_pttVolumeUpdateQueued}");
        _pttVolumeTraceStopwatch.Restart();
    }

    private async Task StopPushToTalkAsync(bool send, bool sendAsQuickReply = false)
    {
        SquadDashTrace.Write("UI", $"PTT_STOP begin send={send} sendAsQuickReply={sendAsQuickReply} state={_pttState}");
        _pttState = PttState.Idle;
        StopPttCtrlPollTimer();
        _pttLostFocusDuringRecording = false;
        var wasTargetingPrompt = _pttTargetRichTextBox == null
            && (_pttTargetTextBox is null || _pttTargetTextBox == PromptTextBox);
        // Do NOT null _pttTargetTextBox here — pending AppendSpeechToPrompt BeginInvoke
        // callbacks in the dispatcher queue still need it to route text to the correct target.
        // It is cleared inside the Background-priority dispatcher callback below, after all
        // Normal-priority phrase callbacks have drained.

        var service = _speechService;
        _speechService = null;

        // Set _pttDraining BEFORE ClosePttWindow so that HandleRestartRequestChanged and
        // MainWindow_Closing cannot slip through the gap between _pttState going Idle and
        // this flag being raised.  ClosePttWindow fires WPF window-lifecycle events that may
        // re-enter the dispatcher pump, so the flag must already be set when that happens.
        if (service != null)
            _pttDraining = true;

        ClosePttWindow();

        if (service != null)
        {
            // _pttDraining prevents HandleRestartRequestChanged and Window_Closing from
            // initiating a restart while Azure is flushing the final phrase recognition.
            // _pttState is already Idle at this point so without this flag the build watcher
            // could fire, see Idle state, and Close() before the last phrase arrives.
            try { await service.StopAsync().ConfigureAwait(false); }
            catch { }
            service.Dispose();
        }

        // Yield to the dispatcher at Background priority. All queued Normal-priority
        // PhraseRecognized → AppendSpeechToPrompt callbacks run first, writing the final
        // dictated text into PromptTextBox.Text. Then our Background item runs on the
        // dispatcher thread — we clear _pttDraining and trigger the deferred close if needed.
        await Dispatcher.InvokeAsync(() =>
        {
            _pttTargetTextBox = null;  // Clear after all Normal-priority phrase callbacks have run.
            _pttTargetRichTextBox = null;
            _pttDraining = false;
            TryCompletePendingRestart("ptt-restart-after-drain", emergencySaveBeforeClose: true);
        }, System.Windows.Threading.DispatcherPriority.Background);

        if (_restartPending && !_isPromptRunning)
            return; // Close() was initiated inside the dispatcher callback above.

        if (wasTargetingPrompt && (send || sendAsQuickReply) && !_promptHasVoiceInput)
        {
            SquadDashTrace.Write("UI", "PTT send suppressed: no recognized voice input.");
            send = false;
            sendAsQuickReply = false;
        }

        if (sendAsQuickReply && wasTargetingPrompt)
        {
            SquadDashTrace.Write("UI", "Prompt sent: PTT quick-reply send");
            // Dictation started with quick replies visible and an empty prompt box.
            // Send the dictated text directly as a quick reply response (bypass the queue).
            await Task.Delay(UiTimingConstants.PttSendSettleMs).ConfigureAwait(false);
            Dispatcher.Invoke(() =>
            {
                var text = PromptTextBox.Text.Trim();
                var quickReplyEntry = _lastQuickReplyEntry;
                if (!string.IsNullOrWhiteSpace(text) && quickReplyEntry?.AllowQuickReplies == true)
                {
                    if (_activeTabId != null)
                    {
                        var idToRemove = _activeTabId;
                        _activeTabId = null;
                        SetPromptTextBoxLogicalBuffer(_queuePreEditDraft ?? string.Empty, 0, 0);
                        _queuePreEditDraft = null;
                        _promptQueue.Remove(idToRemove);
                        SyncQueuePanel();
                    }
                    PromptTextBox.Clear();
                    _pec.DisableQuickReplies(quickReplyEntry);
                    ClearActiveQuickReplyState(quickReplyEntry);
                    ResumeQueueAfterStoppedWorkResponseIfNeeded();
                    ResetQueuePausedState();
                    // ApplyFollowUpHeader consumes any pending attachment for the active draft
                    // ("" tabId) and injects it as a header. Skipping it here would orphan the
                    // attachment — the strip would not clear and the image would not be sent.
                    _ = _pec.ExecutePromptAsync(ApplyFollowUpHeader(text, ""), addToHistory: true, clearPromptBox: false);
                }
                else if (!string.IsNullOrWhiteSpace(text))
                {
                    // No quick reply entry to attach to — fall back to queue.
                    EnqueueCurrentPrompt();
                    _ = DrainQueueIfNeededAsync();
                }
            });
        }
        else if (send && wasTargetingPrompt)
        {
            SquadDashTrace.Write("UI", "Prompt sent: PTT auto-send (voice released Ctrl)");
            await Task.Delay(UiTimingConstants.PttSendSettleMs).ConfigureAwait(false);
            Dispatcher.Invoke(() =>
            {
                if (_activeTabId is not null)
                {
                    // PTT completed while the user was editing a queued tab — dispatch
                    // that tab directly rather than enqueuing a duplicate new item.
                    _ = DispatchQueuedTabAsync(_activeTabId);
                }
                else if (!string.IsNullOrWhiteSpace(PromptTextBox.Text) ||
                         (_followUpAttachments.TryGetValue("", out var pttAttachCheck) && pttAttachCheck.Count > 0))
                {
                    EnqueueCurrentPrompt();
                    _ = DrainQueueIfNeededAsync();
                }
            });
        }
        else
        {
            SquadDashTrace.Write("UI", "PTT stopped: no send (Escape/focus-lost/other-key)");
        }
    }

    private void AppendSpeechToPrompt(string text)
    {
        _promptHasVoiceInput = true;

        // If this PTT result has more than 2 words and is landing on an active dummy tab, mark it.
        if (_activeTabId is not null && CountWords(text) > 2)
        {
            var activeItem = _promptQueue.Items.FirstOrDefault(
                i => i.Id == _activeTabId && i.SourceTag == TourDummyTag);
            if (activeItem is not null)
                activeItem.HasSubstantialVoiceWork = true;
        }

        if (_pttTargetRichTextBox != null)
        {
            AppendSpeechToRichTextBox(_pttTargetRichTextBox, text);
            return;
        }

        var target = _pttTargetTextBox ?? PromptTextBox;
        var current = target.Text;
        // Clamp in case text was externally modified since session start.
        var caretIndex = Math.Min(_sessionCaretIndex, current.Length);
        // If there was a selection when PTT started, replace it on the first insert.
        var selLength = _sessionSelectionLength;
        _sessionSelectionLength = 0; // consume once; subsequent dictation appends
        var selEndIndex = Math.Min(caretIndex + selLength, current.Length);
        var leftContext = current[..caretIndex];
        var rightContext = current[selEndIndex..];
        var precedingChar = caretIndex > 0 ? current[caretIndex - 1] : '\0';
        // Suppress the auto-inserted leading space when the caret sits immediately after
        // an opening double-quote that is itself preceded by a space — e.g. `like "`.
        // Inserting a space before the dictation would produce `like " word` (stray space
        // inside the quote). Straight and Unicode left-double-quote are both matched.
        var isQuoteAfterSpace = (precedingChar == '"' || precedingChar == '\u201C')
                                && caretIndex >= 2 && current[caretIndex - 2] == ' ';
        var prefix = precedingChar != '\0' && precedingChar != ' ' && precedingChar != '(' &&
                     precedingChar != '\n' && precedingChar != '\r' && !isQuoteAfterSpace ? " " : string.Empty;
        var processed = VoiceInsertionHeuristics.Apply(leftContext, text, rightContext);
        var insert = prefix + processed;
        var rules = _settingsSnapshot.VoiceReplacementRules;
        var replaced = rules.Count > 0
            ? prefix + VoiceInsertionHeuristics.ApplyReplacementRules(processed, rules)
            : insert;

        // Step 1: insert conditioned text
        target.Text = leftContext + insert + rightContext;
        target.CaretIndex = caretIndex + insert.Length;
        _sessionCaretIndex = caretIndex + insert.Length;

        // Step 2: apply replacements as a separate undo entry
        if (!string.Equals(replaced, insert, StringComparison.Ordinal))
        {
            target.Text = leftContext + replaced + rightContext;
            target.CaretIndex = caretIndex + replaced.Length;
            _sessionCaretIndex = caretIndex + replaced.Length;
        }
    }

    private void AppendSpeechToRichTextBox(RichTextBox rtb, string text)
    {
        var current    = rtb.GetPlainText();
        var caretIndex = Math.Min(_sessionCaretIndex, current.Length);
        var selLength  = _sessionSelectionLength;
        _sessionSelectionLength = 0; // consume once; subsequent dictation appends
        var selEndIndex   = Math.Min(caretIndex + selLength, current.Length);
        var leftContext   = current[..caretIndex];
        var rightContext  = current[selEndIndex..];
        var precedingChar = caretIndex > 0 ? current[caretIndex - 1] : '\0';
        // Suppress the auto-inserted leading space when the caret sits immediately after
        // an opening double-quote that is itself preceded by a space — e.g. `like "`.
        var isQuoteAfterSpace = (precedingChar == '"' || precedingChar == '\u201C')
                                && caretIndex >= 2 && current[caretIndex - 2] == ' ';
        var prefix = precedingChar != '\0' && precedingChar != ' ' && precedingChar != '('
                     && precedingChar != '\n' && precedingChar != '\r' && !isQuoteAfterSpace
                     ? " " : string.Empty;
        var processed = VoiceInsertionHeuristics.Apply(leftContext, text, rightContext);
        var insert    = prefix + processed;
        var rules = _settingsSnapshot.VoiceReplacementRules;
        var replaced = rules.Count > 0
            ? prefix + VoiceInsertionHeuristics.ApplyReplacementRules(processed, rules)
            : insert;

        // Step 1: insert conditioned text
        // Use SelectRange + ReplaceSelection — undo-safe, preserves scroll position and formatting.
        rtb.SelectRange(caretIndex, selEndIndex - caretIndex);
        rtb.ReplaceSelection(insert);
        rtb.SelectRange(caretIndex + insert.Length, 0);
        _sessionCaretIndex = caretIndex + insert.Length;

        // Step 2: apply replacements as a separate undo entry
        if (!string.Equals(replaced, insert, StringComparison.Ordinal))
        {
            rtb.SelectRange(caretIndex, insert.Length);
            rtb.ReplaceSelection(replaced);
            rtb.SelectRange(caretIndex + replaced.Length, 0);
            _sessionCaretIndex = caretIndex + replaced.Length;
        }
    }

    private void UpdateVoiceHintVisibility()
    {
        var hasSpeech = IsSpeechConfigured();
        VoiceHintText.Visibility = hasSpeech ? Visibility.Collapsed : Visibility.Visible;
        BuildShortcutsHint();
    }

    private bool IsSpeechConfigured()
    {
        if (_settingsSnapshot.SpeechProvider == SpeechProvider.OpenAI)
            return !string.IsNullOrWhiteSpace(_settingsSnapshot.OpenAiSpeechApiKey);
        var hasKey = !string.IsNullOrWhiteSpace(
            Environment.GetEnvironmentVariable("SQUAD_SPEECH_KEY", EnvironmentVariableTarget.User));
        return hasKey && !string.IsNullOrWhiteSpace(_settingsSnapshot.SpeechRegion);
    }

    private static Run Bold(string text) => new Run(text) { FontWeight = FontWeights.Bold };
    private static Run Normal(string text) => new Run(text);
    private static Run Gap() => new Run("  ");

    /// <summary>
    /// Rebuilds the shortcuts hint line below the prompt box. Each sentence is only included
    /// when its feature has not been used in the last <see cref="HintCooldown"/>. The
    /// Ctrl+Enter hint is additionally gated on there being queued items that precede the
    /// active prompt in the dispatch order. In QRB blocking state the hint area is taken
    /// over entirely to guide the user through responding to AI input.
    /// </summary>
    private void BuildShortcutsHint()
    {
        var inlines = PromptShortcutsHintTextBlock.Inlines;
        inlines.Clear();

        // QRB blocking state: replace all normal hints with the QRB guidance message.
        if (_queuePausedNotificationFired)
        {
            inlines.Add(Normal("AI needs your input. Press "));
            inlines.Add(Bold("Enter"));
            inlines.Add(Normal(" or click "));
            inlines.Add(Bold("Send"));
            inlines.Add(Normal(" to send the active prompt immediately (or click one of the Quick Reply Buttons above). To create a new response draft, press "));
            inlines.Add(Bold("Ctrl"));
            inlines.Add(Normal("+"));
            inlines.Add(Bold("Q"));
            inlines.Add(Normal("."));
            return;
        }

        var includePtt = IsSpeechConfigured();

        bool any = false;
        void AddGap() { if (any) inlines.Add(Gap()); }

        if (IsHintVisible(PromptHintFeature.EnterSend))
        {
            AddGap();
            inlines.Add(Bold("Enter")); inlines.Add(Normal(" sends."));
            any = true;
        }

        if (IsHintVisible(PromptHintFeature.ShiftEnterNewline))
        {
            AddGap();
            inlines.Add(Bold("Shift")); inlines.Add(Normal("+"));
            inlines.Add(Bold("Enter")); inlines.Add(Normal(" adds a new line."));
            any = true;
        }

        if (IsHintVisible(PromptHintFeature.CtrlArrowHistory))
        {
            AddGap();
            inlines.Add(Bold("Ctrl")); inlines.Add(Normal("+"));
            inlines.Add(Bold("Up")); inlines.Add(Normal("/"));
            inlines.Add(Bold("Down")); inlines.Add(Normal(" reviews prompt history."));
            any = true;
        }

        if (includePtt && IsHintVisible(PromptHintFeature.PushToTalk))
        {
            AddGap();
            inlines.Add(Bold("Double-tap")); inlines.Add(Normal(" "));
            inlines.Add(Bold("Ctrl")); inlines.Add(Normal(" (and "));
            inlines.Add(Bold("hold")); inlines.Add(Normal(") for push to talk."));
            any = true;
        }

        if (IsHintVisible(PromptHintFeature.CtrlEnterPrioritize) && IsCtrlEnterPrioritizeApplicable())
        {
            AddGap();
            inlines.Add(Bold("Ctrl")); inlines.Add(Normal("+"));
            inlines.Add(Bold("Enter")); inlines.Add(Normal(" moves this to the front of the queue."));
        }

        if (IsHintVisible(PromptHintFeature.CtrlQAddQueue))
        {
            AddGap();
            inlines.Add(Bold("Ctrl")); inlines.Add(Normal("+"));
            inlines.Add(Bold("Q")); inlines.Add(Normal(" to add a new queued prompt."));
            any = true;
        }

        if (IsHintVisible(PromptHintFeature.CtrlTabNavigation) && _promptQueue.Items.Count > 0)
        {
            AddGap();
            inlines.Add(Bold("Ctrl+Tab")); inlines.Add(Normal(" / "));
            inlines.Add(Bold("Ctrl+Shift+Tab")); inlines.Add(Normal(" to move forward/backwards through the prompt queue."));
        }
    }

    private bool IsHintVisible(PromptHintFeature feature) =>
        !_promptHintPermanentlyDismissed.Contains(feature) &&
        (!_promptHintLastUsed.TryGetValue(feature, out var last) ||
        DateTime.UtcNow - last >= HintCooldown);

    private void DismissHintPermanently(PromptHintFeature feature)
    {
        _promptHintPermanentlyDismissed.Add(feature);
        BuildShortcutsHint();
    }

    /// <summary>
    /// Returns true when Ctrl+Enter would have a meaningful effect — i.e., there are queue
    /// items that would be dispatched before the current prompt (either on the Active Draft
    /// tab with a non-empty queue, or on a queued tab that isn't already first).
    /// </summary>
    private bool IsCtrlEnterPrioritizeApplicable()
    {
        if (_activeTabId is null)
            return _promptQueue.Count > 0;
        var items = _promptQueue.Items;
        for (int i = 0; i < items.Count; i++)
            if (items[i].Id == _activeTabId) return i > 0;
        return false;
    }

    private void RecordHintFeatureUsed(PromptHintFeature feature)
    {
        _promptHintLastUsed[feature] = DateTime.UtcNow;
        BuildShortcutsHint();
    }

    private void VoiceHintLink_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            PreferencesMenuItem_Click(sender, e);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(VoiceHintLink_Click), ex);
        }
    }

    private void PromptTextBox_TextChanged(object sender, TextChangedEventArgs e)
    {
        var sw = Stopwatch.StartNew();
        var phaseStart = Stopwatch.GetTimestamp();
        void MarkPhase(PromptTextChangedPhase phase)
        {
            var elapsedMs = ElapsedMillisecondsSince(phaseStart);
            RecordPromptTextChangedPhaseTiming(phase, elapsedMs);
            phaseStart = Stopwatch.GetTimestamp();
        }

        try
        {
            if (_conversationManager.IsApplyingHistoryEntry)
                return;

            var text = PromptTextBox.Text;
            MarkPhase(PromptTextChangedPhase.ReadText);
            if (string.IsNullOrEmpty(text))
            {
                _promptHasVoiceInput = false;
                // In fullscreen, hide the peeked prompt when text is cleared
                if (_transcriptFullScreenEnabled && _fullScreenPromptVisible)
                    HideFullScreenPrompt();
            }
            MarkPhase(PromptTextChangedPhase.EmptyUi);

            _conversationManager.HistoryIndex = null;
            _conversationManager.HistoryDraft = text;
            MarkPhase(PromptTextChangedPhase.HistoryDraft);
            QueuePromptDraftStateRefresh();
            MarkPhase(PromptTextChangedPhase.QueueDraftRefresh);
            if (_isPromptRunning)
                UpdateInteractiveControlState(promptTextOnly: true);
            MarkPhase(PromptTextChangedPhase.InteractiveState);
            TryUpdateIntelliSense(text, PromptTextBox.CaretIndex);
            MarkPhase(PromptTextChangedPhase.IntelliSense);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(PromptTextBox_TextChanged), ex);
        }
        finally
        {
            sw.Stop();
            if (sw.ElapsedMilliseconds >= PromptTextChangedSevereTraceMs)
            {
                SquadDashTrace.Write(TraceCategory.Performance,
                    $"PROMPT_TEXT_CHANGED elapsed={sw.ElapsedMilliseconds}ms textLen={PromptTextBox.Text.Length} " +
                    $"caret={PromptTextBox.CaretIndex} primaryHosts={_primaryAgentTranscriptHosts.Count} " +
                    $"phaseMaxMs={FormatPromptTextChangedPhaseMaxes()}");
            }
            RecordPromptInputTiming(isTextChanged: true, sw.ElapsedMilliseconds);
        }
    }

    private void QueuePromptDraftStateRefresh()
    {
        if (_promptDraftStateRefreshPending)
            return;

        _promptDraftStateRefreshPending = true;
        _ = Dispatcher.BeginInvoke(DispatcherPriority.Background, () =>
        {
            try
            {
                _promptDraftStateRefreshPending = false;
                if (!_isClosing)
                    _conversationManager.UpdatePromptDraftState();
            }
            catch (Exception ex)
            {
                HandleUiCallbackException(nameof(QueuePromptDraftStateRefresh), ex);
            }
        });
    }

    private void AttachDispatcherDiagnostics()
    {
        if (_dispatcherDiagnosticsAttached)
            return;

        _dispatcherDiagnosticsAttached = true;
        Dispatcher.Hooks.OperationStarted += DispatcherHooks_OperationStarted;
        Dispatcher.Hooks.OperationCompleted += DispatcherHooks_OperationCompleted;
        Dispatcher.Hooks.OperationAborted += DispatcherHooks_OperationAborted;
    }

    private void DetachDispatcherDiagnostics()
    {
        if (!_dispatcherDiagnosticsAttached)
            return;

        _dispatcherDiagnosticsAttached = false;
        Dispatcher.Hooks.OperationStarted -= DispatcherHooks_OperationStarted;
        Dispatcher.Hooks.OperationCompleted -= DispatcherHooks_OperationCompleted;
        Dispatcher.Hooks.OperationAborted -= DispatcherHooks_OperationAborted;
        CompositionTarget.Rendering -= PromptCompositionTarget_Rendering;
        _promptRenderLatencyPending = false;
        _dispatcherOperationStarts.Clear();
    }

    private void DispatcherHooks_OperationStarted(object? sender, DispatcherHookEventArgs e)
    {
        try
        {
            if (_dispatcherOperationStarts.Count > 1024)
                _dispatcherOperationStarts.Clear();

            _dispatcherOperationStarts[e.Operation] = (Stopwatch.GetTimestamp(), e.Operation.Priority);
        }
        catch
        {
            // Diagnostics must never perturb UI dispatch.
        }
    }

    private void DispatcherHooks_OperationCompleted(object? sender, DispatcherHookEventArgs e) =>
        CompleteDispatcherOperationTrace(e.Operation, "completed");

    private void DispatcherHooks_OperationAborted(object? sender, DispatcherHookEventArgs e) =>
        CompleteDispatcherOperationTrace(e.Operation, "aborted");

    private void CompleteDispatcherOperationTrace(DispatcherOperation operation, string status)
    {
        try
        {
            if (!_dispatcherOperationStarts.Remove(operation, out var started))
                return;

            var elapsedMs = ElapsedMillisecondsSince(started.StartedAt);
            if (elapsedMs < DispatcherLongOperationTraceMs)
                return;

            _lastLongDispatcherOperationSummary = $"{status}:{started.Priority}:{elapsedMs}ms";
            SquadDashTrace.Write(
                TraceCategory.Performance,
                $"DISPATCHER_OP_LONG status={status} priority={started.Priority} elapsedMs={elapsedMs} " +
                $"promptFocused={PromptTextBox?.IsKeyboardFocusWithin == true} textLen={PromptTextBox?.Text.Length ?? 0} " +
                $"postedPending={_postedUiActionTracker.PendingCount} uiNativeThreadId={NativeMethods.GetCurrentNativeThreadId()} " +
                BuildTranscriptRenderState());
        }
        catch
        {
            // Diagnostics must never perturb UI dispatch.
        }
    }

    private void MarkPromptInputAwaitingRender()
    {
        _promptRenderLatencyStartedAt = Stopwatch.GetTimestamp();
        _promptRenderLatencyTextLen = PromptTextBox?.Text.Length ?? 0;

        if (_promptRenderLatencyPending)
            return;

        _promptRenderLatencyPending = true;
        CompositionTarget.Rendering += PromptCompositionTarget_Rendering;
    }

    private void PromptCompositionTarget_Rendering(object? sender, EventArgs e)
    {
        try
        {
            CompositionTarget.Rendering -= PromptCompositionTarget_Rendering;
            _promptRenderLatencyPending = false;

            var elapsedMs = ElapsedMillisecondsSince(_promptRenderLatencyStartedAt);
            if (elapsedMs < PromptRenderLatencyTraceMs)
                return;

            SquadDashTrace.Write(
                TraceCategory.Performance,
                $"PROMPT_RENDER_LATENCY elapsedMs={elapsedMs} textLenAtInput={_promptRenderLatencyTextLen} " +
                $"textLenNow={PromptTextBox?.Text.Length ?? 0} caret={PromptTextBox?.CaretIndex ?? 0} " +
                $"selectionLen={PromptTextBox?.SelectionLength ?? 0} uiNativeThreadId={NativeMethods.GetCurrentNativeThreadId()} " +
                $"lastLongDispatcherOp={_lastLongDispatcherOperationSummary} " +
                BuildTranscriptRenderState());
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(PromptCompositionTarget_Rendering), ex);
        }
    }

    private long GetPromptRenderPendingMs() =>
        _promptRenderLatencyPending ? ElapsedMillisecondsSince(_promptRenderLatencyStartedAt) : 0;

    private void RecordPromptInputTiming(bool isTextChanged, long elapsedMs)
    {
        MarkPromptInputAwaitingRender();

        if (isTextChanged)
        {
            _promptTextChangedTraceCount++;
            _promptTextChangedTraceElapsedMs += elapsedMs;
            _promptTextChangedTraceMaxMs = Math.Max(_promptTextChangedTraceMaxMs, elapsedMs);
        }
        else
        {
            _promptKeyDownTraceCount++;
            _promptKeyDownTraceElapsedMs += elapsedMs;
            _promptKeyDownTraceMaxMs = Math.Max(_promptKeyDownTraceMaxMs, elapsedMs);
        }

        if (_promptInputTraceStopwatch.ElapsedMilliseconds < PromptInputTraceIntervalMs)
            return;

        var textChangedCount = _promptTextChangedTraceCount;
        var keyDownCount = _promptKeyDownTraceCount;
        if (textChangedCount == 0 && keyDownCount == 0)
        {
            _promptInputTraceStopwatch.Restart();
            return;
        }

        SquadDashTrace.Write(
            TraceCategory.UI,
            $"PROMPT_INPUT batchMs={_promptInputTraceStopwatch.ElapsedMilliseconds} " +
            $"textChangedCount={textChangedCount} textChangedAvgMs={FormatAverageMs(_promptTextChangedTraceElapsedMs, textChangedCount)} textChangedMaxMs={_promptTextChangedTraceMaxMs} " +
            $"textChangedPhaseAvgMs={FormatPromptTextChangedPhaseAverages(textChangedCount)} textChangedPhaseMaxMs={FormatPromptTextChangedPhaseMaxes()} " +
            $"keyDownCount={keyDownCount} keyDownAvgMs={FormatAverageMs(_promptKeyDownTraceElapsedMs, keyDownCount)} keyDownMaxMs={_promptKeyDownTraceMaxMs} " +
            $"textLen={PromptTextBox.Text.Length} caret={PromptTextBox.CaretIndex} selectionLen={PromptTextBox.SelectionLength} " +
            $"logicalModifiers={Keyboard.Modifiers} physicalModifiers={NativeMethods.GetPhysicalModifierKeys()}");

        _promptInputTraceStopwatch.Restart();
        _promptTextChangedTraceCount = 0;
        _promptTextChangedTraceElapsedMs = 0;
        _promptTextChangedTraceMaxMs = 0;
        Array.Clear(_promptTextChangedPhaseElapsedMs);
        Array.Clear(_promptTextChangedPhaseMaxMs);
        _promptKeyDownTraceCount = 0;
        _promptKeyDownTraceElapsedMs = 0;
        _promptKeyDownTraceMaxMs = 0;
    }

    private static string FormatAverageMs(long elapsedMs, int count) =>
        count <= 0 ? "n/a" : ((double)elapsedMs / count).ToString("0.0", System.Globalization.CultureInfo.InvariantCulture);

    private void RecordPromptTextChangedPhaseTiming(PromptTextChangedPhase phase, long elapsedMs)
    {
        var index = (int)phase;
        _promptTextChangedPhaseElapsedMs[index] += elapsedMs;
        _promptTextChangedPhaseMaxMs[index] = Math.Max(_promptTextChangedPhaseMaxMs[index], elapsedMs);
    }

    private string FormatPromptTextChangedPhaseAverages(int textChangedCount)
    {
        if (textChangedCount <= 0)
            return "n/a";

        return string.Join(
            ',',
            Enumerable.Range(0, (int)PromptTextChangedPhase.Count)
                .Select(i => $"{PromptTextChangedPhaseNames[i]}={FormatAverageMs(_promptTextChangedPhaseElapsedMs[i], textChangedCount)}"));
    }

    private string FormatPromptTextChangedPhaseMaxes() =>
        string.Join(
            ',',
            Enumerable.Range(0, (int)PromptTextChangedPhase.Count)
                .Select(i => $"{PromptTextChangedPhaseNames[i]}={_promptTextChangedPhaseMaxMs[i]}"));

    private void BuildAgentSuggestions()
    {
        if (_currentWorkspace is null)
        {
            _agentDisplayNames = [];
            _agentHandleByDisplayName.Clear();
            return;
        }
        var members = _teamRosterLoader.Load(_currentWorkspace.FolderPath);
        var dict = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var member in members)
        {
            if (member.IsUtilityAgent) continue;
            if (string.Equals(member.Status, "Retired", StringComparison.OrdinalIgnoreCase)) continue;
            var handle = member.FolderPath is not null
                ? Path.GetFileName(member.FolderPath)
                : member.Name.ToLowerInvariant().Replace(" ", "-");
            if (!string.IsNullOrEmpty(handle))
                dict[member.Name] = handle;
        }
        _agentHandleByDisplayName = dict;
        _agentDisplayNames = [.. dict.Keys.OrderBy(k => k)];
        _inboxPanel?.SetAgentSuggestions(_agentDisplayNames);
    }

    /// <summary>
    /// Rebuilds <see cref="_tasksAgentSuggestions"/> from the owners that appear in
    /// <paramref name="result"/>. Adds "me" first if any task is user-owned, then adds
    /// the display names (alphabetically) of agents that own at least one task and whose
    /// display name is in <see cref="_agentHandleByDisplayName"/>.
    /// </summary>
    private void BuildTasksAgentSuggestions(TaskParseResult result)
    {
        var seen   = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        var names  = new List<string>();
        bool hasMe = false;

        foreach (var group in result.OpenGroups)
        {
            if (group.DecomposeGroupId is not null) continue;
            foreach (var item in group.Items)
            {
                if (item.IsUserOwned)
                    hasMe = true;

                if (item.Owner is not null &&
                    _agentHandleByDisplayName.ContainsKey(item.Owner) &&
                    seen.Add(item.Owner))
                {
                    names.Add(item.Owner);
                }
            }
        }

        names.Sort(StringComparer.OrdinalIgnoreCase);
        if (hasMe) names.Insert(0, "me");
        _tasksAgentSuggestions = [.. names];
    }

    /// <summary>
    /// Searches backward from <paramref name="caret"/> for an '@' that is preceded by
    /// start-of-text or whitespace (i.e. not embedded in a word like an email address).
    /// Returns the index of '@', or -1 if not found.
    /// </summary>
    private const int MaxAtTriggerScanChars = 96;

    private static int FindAtTriggerPosition(string text, int caret)
    {
        if (caret <= 0) return -1;
        var scanStart = Math.Max(0, caret - MaxAtTriggerScanChars);
        int i = caret - 1;
        while (i >= scanStart && !char.IsWhiteSpace(text[i]))
        {
            if (text[i] == '@')
                return (i == 0 || char.IsWhiteSpace(text[i - 1])) ? i : -1;
            i--;
        }
        return -1;
    }

    private void TryUpdateTasksIntelliSense()
    {
        if (_isApplyingIntelliSenseAccept) return;

        var text  = TasksFilterBox.Text;
        var caret = TasksFilterBox.CaretIndex;

        if (_intelliSenseState is not null && _intelliSenseOwnerBox == TasksFilterBox)
        {
            _intelliSenseState = IntelliSenseController.UpdateFromText(_intelliSenseState, text, caret);
            UpdateIntelliSensePopup();
            return;
        }

        // If IntelliSense is owned by another box, leave it alone.
        if (_intelliSenseState is not null) return;

        var atPos = FindAtTriggerPosition(text, caret);
        if (atPos >= 0 && _tasksAgentSuggestions.Length > 0)
        {
            var activated = IntelliSenseController.TryActivate('@', atPos, _tasksAgentSuggestions);
            if (activated is not null)
            {
                _intelliSenseOwnerBox = TasksFilterBox;
                _intelliSenseState = IntelliSenseController.UpdateFromText(activated, text, caret);
                UpdateIntelliSensePopup();
            }
        }
    }

    private void TryUpdateInboxIntelliSense()
    {
        if (_isApplyingIntelliSenseAccept) return;

        var text  = InboxFilterBox.Text;
        var caret = InboxFilterBox.CaretIndex;

        if (_intelliSenseState is not null && _intelliSenseOwnerBox == InboxFilterBox)
        {
            _intelliSenseState = IntelliSenseController.UpdateFromText(_intelliSenseState, text, caret);
            UpdateIntelliSensePopup();
            return;
        }

        if (_intelliSenseState is not null) return;

        var atPos = FindAtTriggerPosition(text, caret);
        var inboxSuggestions = _inboxPanel?.AgentSuggestions ?? [];
        if (atPos >= 0 && inboxSuggestions.Length > 0)
        {
            var activated = IntelliSenseController.TryActivate('@', atPos, inboxSuggestions);
            if (activated is not null)
            {
                _intelliSenseOwnerBox = InboxFilterBox;
                _intelliSenseState = IntelliSenseController.UpdateFromText(activated, text, caret);
                UpdateIntelliSensePopup();
            }
        }
    }

    private void TryUpdateIntelliSense() =>
        TryUpdateIntelliSense(PromptTextBox.Text, PromptTextBox.CaretIndex);

    private void TryUpdateIntelliSense(string text, int caret)
    {
        if (_conversationManager.IsApplyingHistoryEntry || _isApplyingIntelliSenseAccept)
            return;

        if (_intelliSenseState is not null)
        {
            // If IntelliSense belongs to another box, typing in PromptTextBox clears it.
            if (_intelliSenseOwnerBox is not null)
            {
                _intelliSenseState = null;
                _intelliSenseOwnerBox = null;
                UpdateIntelliSensePopup();
                // Fall through to check for a new trigger.
            }
            else
            {
                _intelliSenseState = IntelliSenseController.UpdateFromText(_intelliSenseState, text, caret);
                UpdateIntelliSensePopup();
                return;
            }
        }

        // Check for [ trigger — only when [ is the first char (prompt is otherwise empty)
        if (caret == 1 && text[0] == '[')
        {
            var options = GetCurrentQuickReplyOptions();
            if (options.Length > 0)
            {
                _intelliSenseState = IntelliSenseController.TryActivate('[', caret - 1, options);
                UpdateIntelliSensePopup();
                return;
            }
        }

        // / trigger for slash commands — only when / is the first char, no spaces, and the
        // text itself contains no newline.
        //
        // Bug 3 fix: check !text.Contains('\n') (full text) rather than !text[..caret].Contains('\n').
        // When Enter inserts a newline WPF fires TextChanged before updating CaretIndex, so the
        // stale caret (pointing before the '\n') caused text[..caret] to pass the check even
        // though the text already contained a newline.  Checking the full text is caret-lag-proof.
        //
        // Bug 2 fix: pass text.Length (not caret) to UpdateFromText on re-activation.
        // WPF CaretIndex can lag by one position when TextChanged fires immediately after a
        // Backspace key event, yielding caret=1 for text "/t".  UpdateFromText("/t", 1) builds
        // filter="/" and shows ALL commands instead of the filtered subset.  Using text.Length
        // always places the filter at the end of the typed text, which is where the user's
        // logical cursor is during re-activation.
        if (caret > 0 && text[0] == '/' && !text.Contains(' ') && !text.Contains('\n'))
        {
            var activated = IntelliSenseController.TryActivate('/', 0, SlashCommands, filterIncludesTrigger: true);
            _intelliSenseState = activated is not null
                ? IntelliSenseController.UpdateFromText(activated, text, text.Length)
                : null;
            UpdateIntelliSensePopup();
            return;
        }

        // @ trigger for agent names — works anywhere in the text (not just at position 0).
        var atPos = FindAtTriggerPosition(text, caret);
        if (atPos >= 0 && _agentDisplayNames.Length > 0)
        {
            var activated = IntelliSenseController.TryActivate('@', atPos, _agentDisplayNames);
            if (activated is not null)
            {
                _intelliSenseOwnerBox = null; // PromptTextBox owns this
                _intelliSenseState = IntelliSenseController.UpdateFromText(activated, text, caret);
                UpdateIntelliSensePopup();
            }
        }
    }

    private string[] GetCurrentQuickReplyOptions()
    {
        var cardOptions = TranscriptQuickReplyFactory
            .FindLatestActionButtons(CoordinatorThread.Document.Blocks)
            .Select(button => (string)button.Content)
            .ToArray();
        if (cardOptions.Length > 0)
            return cardOptions;

        var latestResponse = CoordinatorThread?.LatestResponse;
        if (string.IsNullOrEmpty(latestResponse))
            return _currentQuickReplyOptions;
        return TryExtractQuickReplyOptions(latestResponse, out _, out var options)
            ? options
            : _currentQuickReplyOptions;
    }

    private void UpdateIntelliSensePopup()
    {
        if (_intelliSenseState is null || _intelliSenseState.FilteredSuggestions.Count == 0)
        {
            IntelliSensePopup.IsOpen = false;
            _guidedTourCoordinator.NamedElements.Remove("IntelliSensePopup");
            return;
        }

        IntelliSenseList.Items.Clear();
        foreach (var suggestion in _intelliSenseState.FilteredSuggestions)
            IntelliSenseList.Items.Add(suggestion);

        IntelliSenseList.SelectedIndex = _intelliSenseState.SelectedIndex;
        if (IntelliSenseList.SelectedItem is not null)
            IntelliSenseList.ScrollIntoView(IntelliSenseList.SelectedItem);

        var ownerBox = _intelliSenseOwnerBox ?? PromptTextBox;
        IntelliSensePopup.PlacementTarget = ownerBox;
        IntelliSensePopup.CustomPopupPlacementCallback = (popupSize, targetSize, offset) =>
        {
            var caretRect = ownerBox.GetRectFromCharacterIndex(ownerBox.CaretIndex);
            return new[] {
                new CustomPopupPlacement(
                    new Point(caretRect.Left, caretRect.Bottom),
                    PopupPrimaryAxis.Vertical)
            };
        };
        IntelliSensePopup.IsOpen = true;
        if (IntelliSensePopup.Child is FrameworkElement popupChild)
            _guidedTourCoordinator.NamedElements["IntelliSensePopup"] = popupChild;
    }

    private void ApplyIntelliSenseAccept(bool andSubmit)
    {
        if (_intelliSenseState is null) return;

        var targetBox = _intelliSenseOwnerBox ?? PromptTextBox;
        var (newText, newCaret) = IntelliSenseController.Accept(
            _intelliSenseState, targetBox.Text, targetBox.CaretIndex);

        // Capture trigger char and selected label before state is cleared below.
        var triggerChar = _intelliSenseState.TriggerChar;
        var selectedLabel = _intelliSenseState.FilteredSuggestions[_intelliSenseState.SelectedIndex];

        // For @ trigger: replace accepted display name with @handle + trailing space.
        // Never submit on @ accept — the user is mentioning an agent mid-prompt.
        if (_intelliSenseState.TriggerChar == '@')
        {
            andSubmit = false;
            var displayName = _intelliSenseState.FilteredSuggestions[_intelliSenseState.SelectedIndex];
            // "me" is a special suggestion that maps to itself as the filter handle.
            var handle = string.Equals(displayName, "me", StringComparison.OrdinalIgnoreCase)
                ? "me"
                : (_agentHandleByDisplayName.TryGetValue(displayName, out var h) ? h : null);
            if (handle is not null)
            {
                var before = targetBox.Text[.._intelliSenseState.TriggerPosition];
                var after  = targetBox.CaretIndex < targetBox.Text.Length
                    ? targetBox.Text[targetBox.CaretIndex..]
                    : string.Empty;
                newText  = before + "@" + handle + " " + after;
                newCaret = _intelliSenseState.TriggerPosition + 1 + handle.Length + 1;
            }
        }

        // If Tab-completing a slash command that requires a parameter, insert a trailing
        // space and keep focus in the prompt so the user can type the argument.
        if (andSubmit && _intelliSenseState.TriggerChar == '/' && SlashCommandParameterPolicy.RequiresParameter(newText.Trim()))
        {
            newText = newText.TrimEnd() + " ";
            newCaret = newText.Length;
            andSubmit = false;
        }

        var ownerBox = _intelliSenseOwnerBox;
        _isApplyingIntelliSenseAccept = true;
        try
        {
            _intelliSenseState = null;
            _intelliSenseOwnerBox = null;
            targetBox.Text = newText;
            targetBox.CaretIndex = newCaret;
        }
        finally
        {
            _isApplyingIntelliSenseAccept = false;
        }
        UpdateIntelliSensePopup();
        if (andSubmit && ownerBox is null)
        {
            // For [ trigger: route through the quick reply button click handler so that
            // routing metadata (including sim mode) is respected, exactly as if the user
            // had clicked the button directly.
            if (triggerChar == '[')
                SimulateQuickReplyIntelliSenseAccept(selectedLabel, targetBox);
            else
                RunButton_Click(this, new RoutedEventArgs());
        }
    }

    /// <summary>
    /// Called when a quick reply option is accepted via IntelliSense ([ trigger).
    /// Routes the selection through the appropriate click handler so that routing
    /// metadata — including sim mode — is honoured, just as if the button were clicked.
    /// </summary>
    private void SimulateQuickReplyIntelliSenseAccept(string optionLabel, TextBox targetBox)
    {
        var cardButton = TranscriptQuickReplyFactory
            .FindLatestActionButtons(CoordinatorThread.Document.Blocks)
            .FirstOrDefault(button => string.Equals(
                button.Content as string,
                optionLabel,
                StringComparison.OrdinalIgnoreCase));
        if (cardButton is not null)
        {
            _isApplyingIntelliSenseAccept = true;
            try { targetBox.Text = string.Empty; }
            finally { _isApplyingIntelliSenseAccept = false; }
            cardButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent, cardButton));
            return;
        }

        // Look up the full routing payload for this label (populated when quick reply
        // buttons are built).  A match means this is a regular AI-routed quick reply.
        var payload = _currentQuickReplyPayloads
            .FirstOrDefault(p => string.Equals(p.Option, optionLabel, StringComparison.OrdinalIgnoreCase));

        if (payload is not null)
        {
            // Clear the accepted text — the button handler owns the submission.
            _isApplyingIntelliSenseAccept = true;
            try { targetBox.Text = string.Empty; }
            finally { _isApplyingIntelliSenseAccept = false; }
            var syntheticSender = new FrameworkElement { Tag = payload };
            QuickReplyButton_Click(syntheticSender, new RoutedEventArgs());
        }
        else if (_currentQuickReplyOptions.Length > 0)
        {
            // No routing payload = tour-injected quick reply.  Route through the tour handler.
            _isApplyingIntelliSenseAccept = true;
            try { targetBox.Text = string.Empty; }
            finally { _isApplyingIntelliSenseAccept = false; }
            var syntheticSender = new FrameworkElement { Tag = new TourQuickReplyPayload(optionLabel) };
            TourQuickReplyButton_Click(syntheticSender, new RoutedEventArgs());
        }
        else
        {
            // No quick reply state available — fall back to normal submission.
            RunButton_Click(this, new RoutedEventArgs());
        }
    }

    private void AgentCardBorder_MouseLeftButtonUp(object sender, MouseButtonEventArgs e)
    {
        try
        {
            if (sender is not FrameworkElement { DataContext: AgentStatusCard agentCard })
                return;
            if (e.OriginalSource is DependencyObject source && FindVisualAncestor<Button>(source) is not null)
                return;

            bool shiftHeld = (Keyboard.Modifiers & ModifierKeys.Shift) != 0;
            if (shiftHeld)
            {
                var visualSw = Stopwatch.StartNew();
                SyncSelectionControllerWithUiState("AgentCardBorder_MouseLeftButtonUp.Shift");

                if (agentCard.IsLeadAgent)
                {
                    HandleLeadAgentShiftClick(visualSw);
                }
                else
                {
                    // If one of this agent's threads is the current main transcript selection and there
                    // are no secondary panels, shift-click should dismiss it and revert to the
                    // coordinator rather than opening a redundant secondary panel.
                    bool isCurrentMain = _mainTranscriptVisible &&
                                         agentCard.Threads.Any(t => ReferenceEquals(t, _selectedTranscriptThread)) &&
                                         _secondaryTranscripts.Count == 0;
                    if (isCurrentMain)
                    {
                        SelectTranscriptThread(CoordinatorThread);
                        SyncTranscriptTargetIndicators();
                    }
                    else
                    {
                        _selectionController.HandleCardClick(agentCard, shiftHeld: true);
                        SyncImmediatePanelToggleVisuals(agentCard, "card-shift-click", visualSw);
                        Dispatcher.BeginInvoke(DispatcherPriority.Background, () => ApplyGlowIfMouseOver(agentCard));
                    }
                }
            }
            else
            {
                ShowSingleTranscript(agentCard);
            }
            e.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(AgentCardBorder_MouseLeftButtonUp), ex);
        }
    }

    /// <summary>
    /// Handles shift-click on the lead/coordinator card.
    /// Semantics: toggle coordinator visibility.
    /// - Coordinator visible in main + it's the only panel → do nothing (don't close last panel).
    /// - Coordinator visible in main + other panels exist → hide main.
    /// - Coordinator NOT visible, main shows Agent A → move Agent A to secondary, coordinator takes main.
    /// - Main not visible (only secondaries) → show main with coordinator.
    /// </summary>
    private void HandleLeadAgentShiftClick(Stopwatch visualSw)
    {
        bool coordinatorIsInMain = _mainTranscriptVisible &&
            (_selectedTranscriptThread == null || ReferenceEquals(_selectedTranscriptThread, CoordinatorThread));

        if (coordinatorIsInMain)
        {
            // Toggle off: only hide if other panels are open so we don't blank the screen
            if (_secondaryTranscripts.Count > 0)
                HideMainTranscript();
            return;
        }

        if (_mainTranscriptVisible && _selectedTranscriptThread != null
            && !ReferenceEquals(_selectedTranscriptThread, CoordinatorThread))
        {
            // Main is showing Agent A. Switch main to coordinator first (releases Agent A's
            // document from the primary transcript box), then open Agent A as secondary.
            // Order matters: OpenSecondaryPanel guards against opening a panel for the thread
            // that is currently _selectedTranscriptThread, so coordinator must be selected first.
            var formerMainThread = _selectedTranscriptThread;
            var formerMainCard = FindAgentCardForThread(formerMainThread);
            SelectTranscriptThread(CoordinatorThread);
            SyncTranscriptTargetIndicators();
            if (formerMainCard != null)
                OpenSecondaryPanel(formerMainCard, formerMainThread, isAutoOpenedInMultiMode: false);
            return;
        }

        // Main not visible — show it with coordinator
        ShowMainTranscript();
        SelectTranscriptThread(CoordinatorThread);
        SyncTranscriptTargetIndicators();
    }

    // The ScrollContentPresenter (SCP) inside the default ScrollViewer template sets
    // this.Clip = new RectangleGeometry(viewport) in ArrangeOverride whenever scrolling
    // is enabled.  That explicit Clip property clips the entire visual subtree — including
    // DropShadowEffect glow on AgentCardBorder — regardless of ClipToBounds=False on the
    // ScrollViewer element.  We inflate the SCP clip by the maximum glow BlurRadius (28 px)
    // after each layout pass so the glow has room to render on all four sides.
    private static void InflateAgentScrollViewerClip(ScrollViewer scrollViewer)
    {
        const double glowBlurRadius = 28.0;

        if (scrollViewer.Template?.FindName(
                "PART_ScrollContentPresenter", scrollViewer)
            is not System.Windows.Controls.ScrollContentPresenter scp)
            return;

        if (scp.Clip is not System.Windows.Media.RectangleGeometry clipRect)
            return;

        if (scp.ActualWidth <= 0 || scp.ActualHeight <= 0)
            return;

        var inflatedViewport = new Rect(
            -glowBlurRadius,
            -glowBlurRadius,
            scp.ActualWidth + glowBlurRadius * 2,
            scp.ActualHeight + glowBlurRadius * 2);

        if (clipRect.Rect != inflatedViewport)
            clipRect.Rect = inflatedViewport;
    }

    private bool TryGetAgentCardGlowOverlayContext(
        Border agentCardBorder,
        out Border overlay,
        out FrameworkElement overlayCoordinateRoot)
    {
        var owningScrollViewer = FindVisualAncestor<ScrollViewer>(agentCardBorder);
        if (ReferenceEquals(owningScrollViewer, ActiveAgentsScrollViewer))
        {
            overlay = AgentCardGlowOverlay;
            overlayCoordinateRoot = ActiveAgentsPanelGrid;
            return true;
        }

        if (ReferenceEquals(owningScrollViewer, InactiveAgentsScrollViewer))
        {
            overlay = InactiveAgentCardGlowOverlay;
            overlayCoordinateRoot = InactiveAgentsPanelGrid;
            return true;
        }

        overlay = null!;
        overlayCoordinateRoot = null!;
        return false;
    }

    private void HideAgentCardGlowOverlayElement(Border overlay)
    {
        if (overlay.Effect is not System.Windows.Media.Effects.DropShadowEffect cardGlow)
        {
            overlay.Visibility = Visibility.Collapsed;
            return;
        }

        var fadeOut = new System.Windows.Media.Animation.DoubleAnimation(0, AgentGlowFade)
        {
            FillBehavior = System.Windows.Media.Animation.FillBehavior.Stop
        };
        var capturedOverlay = overlay;
        var capturedGlow = cardGlow;
        fadeOut.Completed += (_, _) =>
        {
            if (!ReferenceEquals(capturedOverlay.Effect, capturedGlow)) return; // overlay was reused for another card
            capturedOverlay.Effect = null;
            capturedOverlay.Visibility = Visibility.Collapsed;
        };
        cardGlow.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, fadeOut);
    }

    private void ShowAgentCardGlowOverlay(Border agentCardBorder, System.Windows.Media.Color accentColor, bool isDark)
    {
        if (!TryGetAgentCardGlowOverlayContext(agentCardBorder, out var overlay, out _))
        {
            ApplyAgentCardBorderGlow(agentCardBorder, accentColor, isDark);
            return;
        }

        if (!ReferenceEquals(agentCardBorder, _agentCardGlowOverlayTarget))
            HideAgentCardGlowOverlay();

        _agentCardGlowOverlayTarget = agentCardBorder;

        overlay.BeginAnimation(UIElement.OpacityProperty, null);
        overlay.Opacity = 1;
        overlay.Visibility = Visibility.Visible;
        overlay.CornerRadius = agentCardBorder.CornerRadius;
        overlay.BorderThickness = agentCardBorder.BorderThickness;
        overlay.Background = agentCardBorder.Background;
        overlay.BorderBrush = agentCardBorder.BorderBrush;
        overlay.Width = agentCardBorder.ActualWidth;
        overlay.Height = agentCardBorder.ActualHeight;
        UpdateAgentCardGlowOverlayPosition();

        var cardGlow = new System.Windows.Media.Effects.DropShadowEffect
        {
            Color = accentColor,
            BlurRadius = isDark ? 28 : 20,
            ShadowDepth = 0,
            Opacity = 0
        };
        overlay.Effect = cardGlow;

        var cardOpacityAnim = new System.Windows.Media.Animation.DoubleAnimation(
            0,
            1.0,
            AgentGlowFade);
        cardGlow.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, cardOpacityAnim);
    }

    private void UpdateAgentCardGlowOverlayPosition()
    {
        if (_agentCardGlowOverlayTarget is null
            || !TryGetAgentCardGlowOverlayContext(_agentCardGlowOverlayTarget, out var overlay, out var overlayCoordinateRoot)
            || overlay.Visibility != Visibility.Visible
            || !overlay.IsLoaded)
            return;

        if (!_agentCardGlowOverlayTarget.IsVisible)
        {
            HideAgentCardGlowOverlay(_agentCardGlowOverlayTarget);
            return;
        }

        var topLeft = _agentCardGlowOverlayTarget.TranslatePoint(new System.Windows.Point(0, 0), overlayCoordinateRoot);
        if (overlay.Margin != new Thickness(0))
            overlay.Margin = new Thickness(0);
        if (overlay.RenderTransform is System.Windows.Media.TranslateTransform translate)
        {
            translate.X = topLeft.X;
            translate.Y = topLeft.Y;
        }
        else
        {
            overlay.RenderTransform = new System.Windows.Media.TranslateTransform(topLeft.X, topLeft.Y);
        }
        overlay.Width = _agentCardGlowOverlayTarget.ActualWidth;
        overlay.Height = _agentCardGlowOverlayTarget.ActualHeight;

        // Clip the glow overlay on whichever edge(s) the card is cropped by the ScrollViewer viewport.
        // The glow may freely bleed outside the card on any un-cropped side (~100px margin).
        var owningScrollViewer = FindVisualAncestor<ScrollViewer>(_agentCardGlowOverlayTarget);
        if (owningScrollViewer is not null && owningScrollViewer.IsLoaded)
        {
            try
            {
                // ScrollViewer viewport bounds in overlay coordinate space
                var scrollViewerTopLeft = owningScrollViewer.TranslatePoint(new System.Windows.Point(0, 0), overlayCoordinateRoot);
                var viewportLeft  = scrollViewerTopLeft.X;
                var viewportRight = scrollViewerTopLeft.X + owningScrollViewer.ViewportWidth;

                var cardLeft  = topLeft.X;
                var cardRight = topLeft.X + overlay.Width;

                bool clippedOnLeft  = cardLeft  < viewportLeft;
                bool clippedOnRight = cardRight > viewportRight;

                if (clippedOnLeft || clippedOnRight)
                {
                    const double glowMargin = 100;

                    // Clip boundaries in the overlay's local coordinate space.
                    // When a side IS cropped: clip flush with the viewport edge (no glow bleed).
                    // When a side is NOT cropped: allow the full glow margin.
                    double localClipLeft  = clippedOnLeft  ? (viewportLeft  - cardLeft) : -glowMargin;
                    double localClipRight = clippedOnRight ? (viewportRight - cardLeft) : (overlay.Width + glowMargin);

                    var clipRect = new Rect(
                        localClipLeft,
                        -glowMargin,
                        localClipRight - localClipLeft,
                        overlay.Height + (2 * glowMargin));

                    overlay.Clip = new System.Windows.Media.RectangleGeometry(clipRect);
                }
                else
                {
                    // Card fully within viewport — no clipping needed, glow extends freely.
                    overlay.Clip = null;
                }
            }
            catch
            {
                // If coordinate transform fails, clear clip to avoid hiding the glow entirely
                overlay.Clip = null;
            }
        }
        else
        {
            // No ScrollViewer found or not loaded, don't clip
            overlay.Clip = null;
        }
    }

    private void HideAgentCardGlowOverlay(Border? agentCardBorder = null)
    {
        if (agentCardBorder is not null && !ReferenceEquals(agentCardBorder, _agentCardGlowOverlayTarget))
            return;

        HideAgentCardGlowOverlayElement(AgentCardGlowOverlay);
        HideAgentCardGlowOverlayElement(InactiveAgentCardGlowOverlay);
        _agentCardGlowOverlayTarget = null;
    }

    private static void ApplyAgentCardBorderGlow(Border agentCardBorder, System.Windows.Media.Color accentColor, bool isDark)
    {
        double cardTargetOpacity = isDark ? 1.0 : 1.0;
        var cardGlow = new System.Windows.Media.Effects.DropShadowEffect
        {
            Color = accentColor,
            BlurRadius = isDark ? 28 : 20,
            ShadowDepth = 0,
            Opacity = 0
        };
        agentCardBorder.Effect = cardGlow;

        var cardOpacityAnim = new System.Windows.Media.Animation.DoubleAnimation(
            0,
            cardTargetOpacity,
            AgentGlowFade);
        cardGlow.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, cardOpacityAnim);
    }

    private static void ClearAgentCardBorderGlow(Border agentCardBorder)
    {
        if (agentCardBorder.Effect is not System.Windows.Media.Effects.DropShadowEffect cardGlow)
            return;

        var fadeOut = new System.Windows.Media.Animation.DoubleAnimation(0, AgentGlowFade)
        {
            FillBehavior = System.Windows.Media.Animation.FillBehavior.Stop
        };
        var capturedBorder = agentCardBorder;
        var capturedGlow = cardGlow;
        fadeOut.Completed += (_, _) =>
        {
            if (ReferenceEquals(capturedBorder.Effect, capturedGlow))
                capturedBorder.Effect = null;
        };
        cardGlow.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, fadeOut);
    }

    private static System.Windows.Media.Color GetAgentAccentColor(AgentStatusCard agent)
    {
        var accentColor = (System.Windows.Media.Color)ColorConverter.ConvertFromString(agent.AccentColorHex);
        bool isDark = AgentStatusCard.IsDarkTheme;
        if (isDark)
        {
            accentColor = System.Windows.Media.Color.FromRgb(
                (byte)(accentColor.R + (255 - accentColor.R) * 0.55),
                (byte)(accentColor.G + (255 - accentColor.G) * 0.55),
                (byte)(accentColor.B + (255 - accentColor.B) * 0.55));
        }
        return accentColor;
    }

    /// <summary>
    /// Applies hover glow immediately to the agent's card and transcript border when
    /// the mouse is already within one of those regions at the moment the transcript is
    /// shown or switched.  No MouseEnter fires in that case, so this method bridges the
    /// gap.  Call via <c>Dispatcher.BeginInvoke(DispatcherPriority.Background, …)</c>
    /// so it runs after all Loaded-priority panel-open/show operations have completed.
    /// </summary>
    private void ApplyGlowIfMouseOver(AgentStatusCard agent)
    {
        var accentColor = (System.Windows.Media.Color)ColorConverter.ConvertFromString(agent.AccentColorHex);
        bool isDark = AgentStatusCard.IsDarkTheme;
        if (isDark)
        {
            accentColor = System.Windows.Media.Color.FromRgb(
                (byte)(accentColor.R + (255 - accentColor.R) * 0.55),
                (byte)(accentColor.G + (255 - accentColor.G) * 0.55),
                (byte)(accentColor.B + (255 - accentColor.B) * 0.55));
        }

        var cardBorder = FindAgentCardBorderForCard(agent);

        bool cardHovered = cardBorder?.IsMouseOver == true;

        if (_ownershipMap.IsMainPanelOwner(agent) && _mainTranscriptVisible)
        {
            bool transcriptHovered = MainTranscriptBorder?.IsMouseOver == true;
            if (!cardHovered && !transcriptHovered) return;
            if (cardBorder is not null) ShowAgentCardGlowOverlay(cardBorder, accentColor, isDark);
            if (MainTranscriptBorder is not null) ApplyAgentCardBorderGlow(MainTranscriptBorder, accentColor, isDark);
            return;
        }

        var allSecondaryPanels = _ownershipMap.GetAllSecondaryPanelsForAgent(agent);
        if (allSecondaryPanels.Count == 0) return;

        bool anyHovered = cardHovered || allSecondaryPanels.Any(p => p is Border b && b.IsMouseOver);
        if (!anyHovered) return;

        if (cardBorder is not null) ShowAgentCardGlowOverlay(cardBorder, accentColor, isDark);
        foreach (var panelToken in allSecondaryPanels)
        {
            if (panelToken is Border b)
                ApplyAgentCardBorderGlow(b, accentColor, isDark);
        }
    }

    private void AgentCardBorder_MouseEnter(object sender, MouseEventArgs e)
    {
        try
        {
            if (sender is not FrameworkElement { DataContext: AgentStatusCard agentCard })
                return;

            // Parse accent color; brighten toward white in dark theme so the glow is visible
            // against a dark background (same accent color reads as nearly invisible in dark mode).
            var accentColor = (System.Windows.Media.Color)ColorConverter.ConvertFromString(agentCard.AccentColorHex);
            bool isDark = AgentStatusCard.IsDarkTheme;
            if (isDark)
            {
                accentColor = System.Windows.Media.Color.FromRgb(
                    (byte)(accentColor.R + (255 - accentColor.R) * 0.55),
                    (byte)(accentColor.G + (255 - accentColor.G) * 0.55),
                    (byte)(accentColor.B + (255 - accentColor.B) * 0.55));
            }

            // Render card hover glow from an unclipped sibling overlay.  The card lives
            // inside ScrollViewer/item-presenter layout bounds, so applying the effect
            // directly to the card can still crop pixels on tight top/left edges.
            if (sender is System.Windows.Controls.Border agentCardBorder)
                ShowAgentCardGlowOverlay(agentCardBorder, accentColor, isDark);

            // Glow the transcript border that belongs to this agent.
            // MainTranscriptBorder only glows if this agent's transcript is currently displayed there.
            bool isMainOwner = _ownershipMap.IsMainPanelOwner(agentCard);
            SquadDashTrace.Write(TraceCategory.TranscriptPanels,
                $"[glow-link] card-hover agent={agentCard.Name} isMainOwner={isMainOwner}");
            if (isMainOwner)
            {
                if (_mainTranscriptVisible && MainTranscriptBorder is not null)
                {
                    var glow = new System.Windows.Media.Effects.DropShadowEffect
                    {
                        Color = accentColor,
                        BlurRadius = isDark ? 28 : 20,
                        ShadowDepth = 0,
                        Opacity = 0
                    };
                    MainTranscriptBorder.Effect = glow;

                    var opacityAnim = new System.Windows.Media.Animation.DoubleAnimation(0, 1.0, AgentGlowFade);
                    glow.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, opacityAnim);
                }
                return;
            }

            // Glow ALL open secondary transcript panels for this agent
            var allPanels = _ownershipMap.GetAllSecondaryPanelsForAgent(agentCard);
            SquadDashTrace.Write(TraceCategory.TranscriptPanels,
                $"[glow-link] card-hover-secondary agent={agentCard.Name} panelsFound={allPanels.Count}");
            foreach (var panelToken in allPanels)
            {
                if (panelToken is not Border secondaryPanelBorder) continue;
                var secondaryGlow = new System.Windows.Media.Effects.DropShadowEffect
                {
                    Color = accentColor,
                    BlurRadius = isDark ? 28 : 20,
                    ShadowDepth = 0,
                    Opacity = 0
                };
                secondaryPanelBorder.Effect = secondaryGlow;
                var secondaryOpacityAnim = new System.Windows.Media.Animation.DoubleAnimation(0, 1.0, AgentGlowFade);
                secondaryGlow.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, secondaryOpacityAnim);
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(AgentCardBorder_MouseEnter), ex);
        }
    }

    private void AgentCardBorder_MouseLeave(object sender, MouseEventArgs e)
    {
        try
        {
            if (sender is not FrameworkElement { DataContext: AgentStatusCard agentCard })
                return;

            if (sender is System.Windows.Controls.Border agentCardBorder)
            {
                HideAgentCardGlowOverlay(agentCardBorder);
                ClearAgentCardBorderGlow(agentCardBorder);
            }

            // Remove glow from transcript border — only MainTranscriptBorder if this agent owns it.
            if (_ownershipMap.IsMainPanelOwner(agentCard))
            {
                if (MainTranscriptBorder is not null)
                    ClearAgentCardBorderGlow(MainTranscriptBorder);
                return;
            }

            var allPanels = _ownershipMap.GetAllSecondaryPanelsForAgent(agentCard);
            foreach (var panelToken in allPanels)
            {
                if (panelToken is not Border secondaryPanelBorder) continue;
                ClearAgentCardBorderGlow(secondaryPanelBorder);
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(AgentCardBorder_MouseLeave), ex);
        }
    }

    // ── Transcript-panel → agent-card reverse hover glow ──────────────────────

    private void TranscriptPanelBorder_MouseEnter(AgentStatusCard agentCard)
    {
        try
        {
            var accentColor = (System.Windows.Media.Color)ColorConverter.ConvertFromString(agentCard.AccentColorHex);
            bool isDark = AgentStatusCard.IsDarkTheme;
            if (isDark)
            {
                accentColor = System.Windows.Media.Color.FromRgb(
                    (byte)(accentColor.R + (255 - accentColor.R) * 0.55),
                    (byte)(accentColor.G + (255 - accentColor.G) * 0.55),
                    (byte)(accentColor.B + (255 - accentColor.B) * 0.55));
            }

            var cardBorder = FindAgentCardBorderForCard(agentCard);
            if (cardBorder is not null)
                ShowAgentCardGlowOverlay(cardBorder, accentColor, isDark);

            // Glow the transcript border that belongs to this agent.
            // MainTranscriptBorder only glows if this agent's transcript is currently shown there.
            if (_ownershipMap.IsMainPanelOwner(agentCard))
            {
                if (_mainTranscriptVisible && MainTranscriptBorder is not null)
                    ApplyAgentCardBorderGlow(MainTranscriptBorder, accentColor, isDark);
            }
            else
            {
                // Glow ALL secondary transcript panels for this agent (including the hovered one)
                var allPanels = _ownershipMap.GetAllSecondaryPanelsForAgent(agentCard);
                foreach (var panelToken in allPanels)
                {
                    if (panelToken is Border secondaryPanelBorder)
                        ApplyAgentCardBorderGlow(secondaryPanelBorder, accentColor, isDark);
                }
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(TranscriptPanelBorder_MouseEnter), ex);
        }
    }

    private void TranscriptPanelBorder_MouseLeave(AgentStatusCard agentCard)
    {
        try
        {
            var cardBorder = FindAgentCardBorderForCard(agentCard);
            if (cardBorder is not null)
            {
                HideAgentCardGlowOverlay(cardBorder);
                ClearAgentCardBorderGlow(cardBorder);
            }

            // Clear the transcript border glow — only clear MainTranscriptBorder if this agent owns it.
            if (_ownershipMap.IsMainPanelOwner(agentCard))
            {
                if (MainTranscriptBorder is not null)
                    ClearAgentCardBorderGlow(MainTranscriptBorder);
            }
            else
            {
                var allPanels = _ownershipMap.GetAllSecondaryPanelsForAgent(agentCard);
                foreach (var panelToken in allPanels)
                {
                    if (panelToken is Border secondaryPanelBorder)
                        ClearAgentCardBorderGlow(secondaryPanelBorder);
                }
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(TranscriptPanelBorder_MouseLeave), ex);
        }
    }

    private void MainTranscriptBorder_MouseEnter(object sender, MouseEventArgs e)
    {
        try
        {
            var mainOwner = _ownershipMap.MainPanelOwner ?? _leadAgent;
            if (mainOwner is null) return;
            TranscriptPanelBorder_MouseEnter(mainOwner);
            if (MainTranscriptBorder is not null)
                StartTranscriptGlowFadeTimer(MainTranscriptBorder);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(MainTranscriptBorder_MouseEnter), ex);
        }
    }

    private void MainTranscriptBorder_MouseLeave(object sender, MouseEventArgs e)
    {
        try
        {
            CancelTranscriptGlowFadeTimer();
            var mainOwner = _ownershipMap.MainPanelOwner ?? _leadAgent;
            if (mainOwner is null) return;
            TranscriptPanelBorder_MouseLeave(mainOwner);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(MainTranscriptBorder_MouseLeave), ex);
        }
    }

    /// <summary>
    /// Starts a 3-second hold timer for <paramref name="transcriptBorder"/>. When the timer fires
    /// and the mouse is still inside the border, animates the glow opacity from its current value
    /// to 0 over 3 seconds and then removes the effect.  Any previously running timer or animation
    /// is cancelled first.  Call <see cref="CancelTranscriptGlowFadeTimer"/> on MouseLeave so the
    /// existing immediate-clear behavior is preserved.
    /// </summary>
    private void StartTranscriptGlowFadeTimer(Border transcriptBorder)
    {
        try
        {
            CancelTranscriptGlowFadeTimer();
            _transcriptGlowFadeBorder = transcriptBorder;

            _transcriptGlowHoldTimer = new DispatcherTimer { Interval = UiTimingConstants.TranscriptGlowHoldInterval };
            _transcriptGlowHoldTimer.Tick += (_, _) =>
            {
                _transcriptGlowHoldTimer?.Stop();
                _transcriptGlowHoldTimer = null;

                if (_transcriptGlowFadeBorder is not Border border || !border.IsMouseOver)
                {
                    _transcriptGlowFadeBorder = null;
                    return;
                }

                if (border.Effect is not System.Windows.Media.Effects.DropShadowEffect glow)
                {
                    _transcriptGlowFadeBorder = null;
                    return;
                }

                var fadeAnim = new System.Windows.Media.Animation.DoubleAnimation(
                    glow.Opacity, 0.0, TimeSpan.FromSeconds(3))
                {
                    FillBehavior = System.Windows.Media.Animation.FillBehavior.Stop
                };
                var capturedBorder = border;
                fadeAnim.Completed += (_, _) =>
                {
                    if (!ReferenceEquals(_transcriptGlowFadeBorder, capturedBorder))
                        return;
                    if (capturedBorder.Effect is System.Windows.Media.Effects.DropShadowEffect g)
                    {
                        g.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, null);
                        capturedBorder.Effect = null;
                    }
                    _transcriptGlowFadeBorder = null;
                };
                glow.BeginAnimation(System.Windows.Media.Effects.DropShadowEffect.OpacityProperty, fadeAnim);
            };
            _transcriptGlowHoldTimer.Start();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(StartTranscriptGlowFadeTimer), ex);
        }
    }

    private void CancelTranscriptGlowFadeTimer()
    {
        _transcriptGlowHoldTimer?.Stop();
        _transcriptGlowHoldTimer = null;
        _transcriptGlowFadeBorder = null;
    }

    private Border? FindAgentCardBorderForCard(AgentStatusCard card)
    {
        foreach (var itemsControl in new ItemsControl[] { ActiveAgentItemsControl, InactiveAgentItemsControl })
        {
            var container = itemsControl.ItemContainerGenerator.ContainerFromItem(card);
            if (container is null) continue;
            var border = VisualTreeSearch.FindChildByName<Border>(container, "AgentCardBorder");
            if (border is not null) return border;
        }
        return null;
    }


