    private async void InstallSquadButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_currentWorkspace is null)
                return;

            _installSquadButtonPressed = true;
            WorkspaceIssueDetailTextBlock.Visibility = System.Windows.Visibility.Collapsed;

            if (IsDeveloperSimulationActive())
            {
                SetInstallStatus("Developer simulation is active. Install Squad is disabled while previewing issue states.");
                ShowTextWindow(
                    "Developer Simulation",
                    "Install Squad is disabled while a developer issue simulation is active.\n\nClear the simulation in Preferences to run the real install flow.");
                return;
            }

            SetInstallUiState(isInstalling: true, "Checking prerequisites...");
            WorkspaceIssueTitleTextBlock.Text = "Installing Squad workspace...";
            var sw = System.Diagnostics.Stopwatch.StartNew();
            var lastProgressMessage = "Checking prerequisites...";
            string? installSourceLabel = null;
            var progress = new Progress<string>(text =>
            {
                lastProgressMessage = text;
                if (InstallStatusTextFormatter.TryInferInstallSourceFromProgressMessage(text, out var inferredSource))
                    installSourceLabel = inferredSource;

                SetInstallStatus(InstallStatusTextFormatter.BuildProgressStatus(text, sw.Elapsed, installSourceLabel));
            });

            var elapsedTimer = new System.Windows.Threading.DispatcherTimer { Interval = UiTimingConstants.InstallProgressRefreshInterval };
            elapsedTimer.Tick += (_, _) => SetInstallStatus(InstallStatusTextFormatter.BuildProgressStatus(lastProgressMessage, sw.Elapsed, installSourceLabel));
            elapsedTimer.Start();

            SquadCommandResult result;
            try
            {
                result = await _installerService
                    .InstallAsync(_currentWorkspace.FolderPath, progress);
            }
            finally
            {
                elapsedTimer.Stop();
                sw.Stop();
            }

            await RefreshInstallationStateAsync();

            // The version-guard in RefreshInstallationStateAsync may have discarded the result
            // if the team-file watcher also triggered a refresh while install was creating files.
            // Do a direct fresh check so we never falsely enter the failure path on a successful install.
            if (_currentInstallationState?.IsSquadInstalledForActiveDirectory != true && _currentWorkspace is not null)
            {
                var resolvedCandidate = await _cliResolutionService.ResolveAsync(_currentWorkspace.FolderPath).ConfigureAwait(true);
                var freshState = await Task.Run(() => _installationStateService.GetState(_currentWorkspace.FolderPath, resolvedCandidate));
                if (freshState.IsSquadInstalledForActiveDirectory)
                {
                    _currentInstallationState = freshState;
                    _startupIssue = null;
                    UpdateWorkspaceIssuePanel();
                    UpdateInteractiveControlState();
                }
            }

            if (!string.IsNullOrWhiteSpace(result.InstallSource))
                installSourceLabel = result.InstallSource;

            if (_currentInstallationState?.IsSquadInstalledForActiveDirectory == true)
            {
                WorkspaceIssueTitleTextBlock.Text = "Squad workspace successfully installed.";
                SetInstallUiState(
                    isInstalling: false,
                    InstallStatusTextFormatter.BuildStatusText("Squad installed successfully. Starting the first Squad turn...", installSourceLabel));
                // Show global install tip if no global CLI is available on this machine
                var globalCliCandidate = await TryResolveGlobalSquadCliAsync(_currentWorkspace?.FolderPath).ConfigureAwait(true);
                bool hasGlobalCli = globalCliCandidate is { IsAvailable: true, DetectedSource: CliInstallSource.GlobalNpm };
                if (!hasGlobalCli)
                {
                    var isDark = Resources.Contains("IsDarkTheme") && (bool)Resources["IsDarkTheme"];
                    var fontSize = Resources.Contains("FontSizeBody") ? Convert.ToDouble(Resources["FontSizeBody"]) : 13.0;
                    _globalInstallTipCallout?.Close();
                    _globalInstallTipCallout = FrmUltimateCallout.ShowCalloutBesideTarget(
                        "**Tip:** Open the Squad version menu here to install Squad globally — this avoids per-folder setup in every new repo.",
                        SquadVersionPanel,
                        width: 320,
                        theme: isDark ? CalloutTheme.Dark : CalloutTheme.Light,
                        fontSize: fontSize,
                        placement: CalloutPlacement.South);
                }
                RefreshAgentCards();
                RefreshSidebar();
                MaybePromptForUniverseSelection();
                MaybePublishMissingUtilityAgentNotice();
                return;
            }

            // Install process reported failure and files are still missing
            if (_currentWorkspace is null) return;
            var failureMessage = result.Success
                ? "Squad setup completed, but the local Squad command is still unavailable."
                : result.Message;
            var activeDirectory = _currentWorkspace.FolderPath;

            SetInstallUiState(isInstalling: false, InstallStatusTextFormatter.BuildStatusText(failureMessage, installSourceLabel));

            ShowTextWindow(
                "Squad Install Diagnostics",
                BuildInstallDiagnostics(result, activeDirectory));
        }
        catch (Exception ex)
        {
            SetInstallUiState(isInstalling: false, "Squad install failed.");
            HandleUiCallbackException("Install Squad", ex);
        }
    }

    private async void RunDoctorButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_currentWorkspace is null)
                return;

            if (IsDeveloperSimulationActive())
            {
                SetInstallStatus("Developer simulation is active. Cleanup > Run Squad Doctor is disabled while previewing issue states.");
                ShowTextWindow(
                    "Developer Simulation",
                    "Cleanup > Run Squad Doctor is disabled while a developer issue simulation is active.\n\nClear the simulation in Preferences to run the real doctor flow.");
                return;
            }

            SetInstallUiState(isInstalling: true, "Running Squad doctor...");
            var progress = new Progress<string>(text => SetInstallStatus(text));

            var result = await _installerService
                .RunDoctorAsync(_currentWorkspace.FolderPath, progress);

            SetInstallUiState(isInstalling: false, result.Message);

            ShowTextWindow(
                "Squad Doctor",
                BuildInstallDiagnostics(result, _currentWorkspace.FolderPath));
        }
        catch (Exception ex)
        {
            SetInstallUiState(isInstalling: false, "Squad doctor failed.");
            HandleUiCallbackException("Run Doctor", ex);
        }
    }

