    }

    /// <summary>
    /// Activates or deactivates UI Reveal on the given window.
    /// Called from both the menu item and the global F12 shortcut.
    /// </summary>
    private void ToggleUiReveal(Window targetWindow)
    {
        _uiRevealOverlay ??= new UiRevealOverlay();
        if (_uiRevealOverlay.IsActive)
            _uiRevealOverlay.Deactivate();
        else
            _uiRevealOverlay.Activate(targetWindow);
    }

    /// <summary>
    /// Global input handler registered on <see cref="InputManager.PreProcessInput"/>.
    /// Fires for every WPF window on this thread before dispatch, so F12
    /// works even when a floating window (hint overlay, doc window, etc.) has keyboard focus.
    /// </summary>
    private void OnGlobalPreProcessInput(object sender, PreProcessInputEventArgs e)
    {
        try
        {
            if (e.StagingItem.Input is not KeyEventArgs keyArgs) return;
            if (keyArgs.RoutedEvent != Keyboard.PreviewKeyDownEvent) return;
            var key = keyArgs.Key == Key.System ? keyArgs.SystemKey : keyArgs.Key;

            // Ctrl+C or Ctrl+Insert while UI Reveal is active → copy happened, exit reveal.
            if (_uiRevealOverlay?.IsActive == true
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && (key == Key.C || key == Key.Insert))
            {
                _uiRevealOverlay.Deactivate();
                // Don't mark Handled — let the copy go through normally.
                return;
            }

            // Ctrl+C while Theme Reveal is active → copy visible tokens to clipboard and exit.
            if (_themeRevealOverlay?.IsActive == true
                && (Keyboard.Modifiers & ModifierKeys.Control) != 0
                && key == Key.C)
            {
                _themeRevealOverlay.CopyToClipboard();
                _themeRevealOverlay.Deactivate();
                keyArgs.Handled = true;
                return;
            }

            // Escape while UI Reveal is active → cancel reveal.
            if (_uiRevealOverlay?.IsActive == true
                && key == Key.Escape
                && Keyboard.Modifiers == ModifierKeys.None)
            {
                _uiRevealOverlay.Deactivate();
                keyArgs.Handled = true;
                return;
            }

            // Escape while Theme Reveal is active → cancel reveal.
            if (_themeRevealOverlay?.IsActive == true
                && key == Key.Escape
                && Keyboard.Modifiers == ModifierKeys.None)
            {
                _themeRevealOverlay.Deactivate();
                keyArgs.Handled = true;
                return;
            }

            if (key == Key.D &&
                Keyboard.Modifiers == (ModifierKeys.Control | ModifierKeys.Alt | ModifierKeys.Shift))
            {
                CaptureDockingLayoutSnapshot("manual Ctrl+Alt+Shift+D");
                keyArgs.Handled = true;
                return;
            }

            // Any key activity in the main window → sweep non-sticky callouts.
            FrmUltimateCallout.CloseAllNonSticky();

            if (key != Key.F12 && key != Key.F11 && key != Key.F6 && key != Key.F5) return;

            // F6 and F12 require no modifiers; F11 variants handle full-screen and other toggles.
            bool isCtrl      = (Keyboard.Modifiers & ModifierKeys.Control) == ModifierKeys.Control;
            bool isShift     = (Keyboard.Modifiers & ModifierKeys.Shift)   == ModifierKeys.Shift;
            bool noMods      = Keyboard.Modifiers == ModifierKeys.None;
            bool isCtrlOnly  = isCtrl && !isShift;
            bool isCtrlShift = isCtrl && isShift;

            // Bare F11 is handled here (not deferred to Window_PreviewKeyDown) so it works
            // even when a menu popup has focus and Window_PreviewKeyDown never fires.
            if (key == Key.F11 && noMods)
            {
                SetTranscriptFullScreen(!_transcriptFullScreenEnabled);
                keyArgs.Handled = true;
                return;
            }
            // Shift+F11 also handled here for the same reason (menu popup focus).
            if (key == Key.F11 && isShift && !isCtrl)
            {
                ToggleAgentsPanelFocusMode();
                keyArgs.Handled = true;
                return;
            }
            if (key != Key.F11 && !noMods) return;

            // Find the WPF window that currently has focus; fall back to MainWindow.
            var target = Application.Current.Windows
                             .OfType<Window>()
                             .FirstOrDefault(w => w.IsActive)
                         ?? this;

            if (key == Key.F5)
            {
                ToggleQueueDrain();
            }
            else if (key == Key.F6)
            {
                // F6: toggle Hint Authoring Mode — developer mode only
                if (DeveloperMenuItem.IsVisible)
                    ToggleHintAuthoring();
            }
            else if (key == Key.F11 && isCtrlShift)
            {
                _themeRevealOverlay ??= new ThemeRevealOverlay();
                if (_themeRevealOverlay.IsActive)
                    _themeRevealOverlay.Deactivate();
                else
                    _themeRevealOverlay.Activate(target);
            }
            else if (key == Key.F11 && isCtrlOnly)
            {
                ShowAgentAvatarsMenuItem.IsChecked = !ShowAgentAvatarsMenuItem.IsChecked;
                ShowAgentAvatarsMenuItem_Click(this, new RoutedEventArgs());
            }
            else if (key == Key.F12)
            {
                ToggleUiReveal(target);
            }
            keyArgs.Handled = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(OnGlobalPreProcessInput), ex);
        }
    }

