    private void StartFirstTour()
    {
        var tours = GuidedTourLoader.Load(_currentWorkspace?.FolderPath);
        if (tours.Count == 0)
        {
            MessageBox.Show("No guided tours are available.", "Start Guided Tour", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }
        LaunchTour(tours[0], tours);
    }

    private void OpenGuidedTourSelector()
    {
        var tours = GuidedTourLoader.Load(_currentWorkspace?.FolderPath);
        if (tours.Count == 0)
        {
            MessageBox.Show("No guided tours are available.", "Start Guided Tour", MessageBoxButton.OK, MessageBoxImage.Information);
            return;
        }

        FrmGuidedTourSelector.ShowModeless(this, tours, GuidedTourStateStore.Shared.IsCompleted,
            selected => LaunchTour(selected, tours));
    }

    private void LaunchTour(GuidedTour tour, List<GuidedTour>? allTours = null)
    {
        EnsureGuidedTourController();
        _guidedTourCoordinator.InjectedCoordinatorBlocks.Clear();
        _guidedTourCoordinator.NamedElements.Clear();
        _guidedTourController!.StartTour(tour, allTours);
    }

    private void EnsureGuidedTourController()
    {
        if (_guidedTourController is not null) return;
        RegisterTourCommands();
        RegisterTourAdvanceTriggers();
        RegisterTourContexts();
        _guidedTourController = new GuidedTourController(
            ownerWindow:             this,
            elementLocator:          name =>
            {
                if (_guidedTourCoordinator.NamedElements.TryGetValue(name, out var namedEl)) return namedEl;

                // Lazy-resolve FirstInactiveAgentCard / FirstActiveAgentCard — positional,
                // team-agnostic targets useful for generic guided tours.
                if (name == "FirstInactiveAgentCard")
                {
                    var card = _inactiveAgentCards.FirstOrDefault();
                    if (card is not null)
                    {
                        var border = FindAgentCardBorderForCard(card);
                        if (border is not null) return border;
                    }
                }
                if (name == "FirstActiveAgentCard")
                {
                    var card = _activeAgentCards.FirstOrDefault();
                    if (card is not null)
                    {
                        var border = FindAgentCardBorderForCard(card);
                        if (border is not null) return border;
                    }
                }
                if (name == "FirstActiveAgentCardWithHiddenTranscript")
                {
                    // First active agent whose transcript is not currently shown —
                    // none of its threads are selected in the main panel (IsSelected)
                    // or open as a secondary panel (IsSecondaryPanelOpen).
                    // Includes the lead/coordinator card.
                    var card = _activeAgentCards
                        .FirstOrDefault(c => c.Threads.All(
                            t => !t.IsSelected && !t.IsSecondaryPanelOpen));
                    if (card is not null)
                    {
                        var border = FindAgentCardBorderForCard(card);
                        if (border is not null) return border;
                    }
                }

                // Lazy-resolve TourDemoAgent_{name} at lookup time in case the border wasn't
                // registered yet (e.g. visual tree not rendered when CreateDemoAgent ran).
                if (name.StartsWith("TourDemoAgent_", StringComparison.Ordinal))
                {
                    var agentName = name.Substring("TourDemoAgent_".Length);
                    var liveCard = _activeAgentCards
                        .Concat(_inactiveAgentCards)
                        .FirstOrDefault(c => string.Equals(c.Name, agentName, StringComparison.OrdinalIgnoreCase));
                    if (liveCard is not null)
                    {
                        var liveBorder = FindAgentCardBorderForCard(liveCard);
                        if (liveBorder is not null)
                        {
                            _guidedTourCoordinator.NamedElements[name] = liveBorder;
                            return liveBorder;
                        }
                    }
                }

                // Lazy-resolve TourDemoAgentSpinner_{name}
                if (name.StartsWith("TourDemoAgentSpinner_", StringComparison.Ordinal))
                {
                    var agentName = name.Substring("TourDemoAgentSpinner_".Length);
                    var liveCard = _activeAgentCards
                        .Concat(_inactiveAgentCards)
                        .FirstOrDefault(c => string.Equals(c.Name, agentName, StringComparison.OrdinalIgnoreCase));
                    if (liveCard is not null)
                    {
                        var liveBorder = FindAgentCardBorderForCard(liveCard);
                        if (liveBorder is not null)
                        {
                            var spinner = VisualTreeSearch.FindChild<ActivitySpinner>(liveBorder);
                            if (spinner is not null) { _guidedTourCoordinator.NamedElements[name] = spinner; return spinner; }
                        }
                    }
                }

                // Lazy-resolve TourDemoAgentTitle_{name}
                if (name.StartsWith("TourDemoAgentTitle_", StringComparison.Ordinal))
                {
                    var agentName = name.Substring("TourDemoAgentTitle_".Length);
                    var liveCard = _activeAgentCards
                        .Concat(_inactiveAgentCards)
                        .FirstOrDefault(c => string.Equals(c.Name, agentName, StringComparison.OrdinalIgnoreCase));
                    if (liveCard is not null)
                    {
                        var liveBorder = FindAgentCardBorderForCard(liveCard);
                        if (liveBorder is not null)
                        {
                            var nameText = VisualTreeSearch.FindChildByName<TextBlock>(liveBorder, "AgentNameText");
                            if (nameText is not null) { _guidedTourCoordinator.NamedElements[name] = nameText; return nameText; }
                        }
                    }
                }

                // Lazy-resolve TourDemoAgentTranscriptTitle_{name}
                if (name.StartsWith("TourDemoAgentTranscriptTitle_", StringComparison.Ordinal))
                {
                    var agentName = name.Substring("TourDemoAgentTranscriptTitle_".Length);
                    if (_guidedTourCoordinator.NamedDemoAgents.TryGetValue(agentName, out var demoEntry))
                    {
                        var se = _secondaryTranscripts.FirstOrDefault(e => e.Agent == demoEntry.Card);
                        if (se is not null) { _guidedTourCoordinator.NamedElements[name] = se.TitleBlock; return se.TitleBlock; }
                    }
                }

                // Lazy-resolve NoteEntry_{title} — finds the visual row for a note by title.
                if (name.StartsWith("NoteEntry_", StringComparison.Ordinal))
                {
                    var noteTitle = name.Substring("NoteEntry_".Length);
                    if (_notesPanel is not null)
                    {
                        var row = _notesPanel.FindRowByTitle(noteTitle);
                        if (row is not null)
                        {
                            _guidedTourCoordinator.NamedElements[name] = row;
                            return row;
                        }
                    }
                }

                var inMain = VisualTreeSearch.FindByName(this, name);
                if (inMain is not null) return inMain;
                if (_preferencesWindow is { IsVisible: true })
                {
                    var inPrefs = VisualTreeSearch.FindByName(_preferencesWindow, name);
                    if (inPrefs is not null) return inPrefs;
                }
                // Also search popup trees registered by OpenMenu (e.g. HelpMenuItem_Popup).
                // This allows a callout to target a MenuItem that lives in an open menu dropdown.
                foreach (var popupRoot in _guidedTourCoordinator.NamedElements.Values)
                {
                    var inPopup = VisualTreeSearch.FindByName(popupRoot, name) as FrameworkElement;
                    if (inPopup is not null) return inPopup;
                }
                return null;
            },
            savePreTourLayout:       () => { if (!string.IsNullOrEmpty(_currentWorkspace?.FolderPath)) _dockingService?.SaveLayout(_currentWorkspace.FolderPath); },
            restorePreTourLayout:    () =>
            {
                // Layout restore: reload the active layout from workspace
                _guidedTourCoordinator.UnhighlightAllMenuItems();
                CleanUpTourInjectedThreads();
                CleanUpTourInjectedCoordinatorBlocks();
                CleanUpTourQueueItems();
            },
            executePreAction:        (kind, arg) => { /* no-op for initial release */ },
            workspaceFolderProvider: () => _currentWorkspace?.FolderPath,
            commandRegistry:         _guidedTourCoordinator.CommandRegistry,
            onStepChanging:          () =>
            {
                FreezeTypeIntoPromptAnimation();
                _guidedTourCoordinator.StopKeepingTourMenusOpen();
                _guidedTourCoordinator.StopKeepingTourIntelliSenseOpen();
                _guidedTourCoordinator.PrefsWindowEnterLetThrough = false;
                _guidedTourCoordinator.QuickReplyIntelliSenseEnterLetThrough = false;
            },
            onCalloutShown:           _guidedTourCoordinator.ReassertTourHighlightOverlays,
            triggerRegistry:         _guidedTourCoordinator.AdvanceTriggerRegistry,
            isTypeAnimationRunning:  () => _typeIntoPromptTimer != null,
            extraPickWindowsProvider: () => _preferencesWindow is { IsVisible: true }
                                            ? [(Window)_preferencesWindow]
                                            : null,
            elementNamesProvider: () => _guidedTourCoordinator.NamedElements.Keys
                                            .Concat(PreferencesWindow.NavElementNames)
                                            .OrderBy(k => k, StringComparer.OrdinalIgnoreCase)
                                            .ToList(),
            getLastEditorTourName:  () => _settingsSnapshot.LastGuidedTourEditorTourName,
            saveLastEditorTourName: name => { _settingsManager.Replace(_settingsStore.SaveLastGuidedTourEditorTourName(name)); },
            getLastEditorStepIndex: () => _settingsSnapshot.LastGuidedTourEditorStepIndex,
            saveLastEditorStepIndex: idx => { _settingsManager.Replace(_settingsStore.SaveLastGuidedTourEditorStepIndex(idx)); },
            contextRegistry:         _guidedTourCoordinator.ContextRegistry);

        // Register session cleanup callbacks that need the controller instance.
        _guidedTourController.RegisterTourSessionCleanup(async () =>
        {
            if (_simulatedPlanSessionId is not null && _simulationSessionManager is not null)
            {
                var sessionId = _simulatedPlanSessionId;
                _simulatedPlanSessionId = null;
                await _simulationSessionManager.EndSessionAsync(sessionId);
            }
        });

        _guidedTourController.RegisterTourSessionCleanup(async () =>
        {
            if (_simulatedNotesSessionId is not null && _simulationSessionManager is not null)
            {
                var sessionId = _simulatedNotesSessionId;
                _simulatedNotesSessionId = null;
                await _simulationSessionManager.EndSessionAsync(sessionId);
            }
        });

        _guidedTourController.RegisterTourSessionCleanup(async () =>
        {
            if (_simulatedTasksSessionId is not null && _simulationSessionManager is not null)
            {
                var sessionId = _simulatedTasksSessionId;
                _simulatedTasksSessionId = null;
                await _simulationSessionManager.EndSessionAsync(sessionId);
            }
        });

        _guidedTourController.RegisterTourSessionCleanup(async () =>
        {
            if (_simulatedApprovalsSessionId is not null && _simulationSessionManager is not null)
            {
                var sessionId = _simulatedApprovalsSessionId;
                _simulatedApprovalsSessionId = null;
                await _simulationSessionManager.EndSessionAsync(sessionId);
            }
        });

        _guidedTourController.RegisterTourSessionCleanup(async () =>
        {
            if (_simulatedInboxSessionId is not null && _simulationSessionManager is not null)
            {
                var sessionId = _simulatedInboxSessionId;
                _simulatedInboxSessionId = null;
                await _simulationSessionManager.EndSessionAsync(sessionId);
            }
        });

        _guidedTourController.RegisterTourSessionCleanup(async () =>
        {
            if (_simulatedLoopSessionId is not null && _simulationSessionManager is not null)
            {
                var sessionId = _simulatedLoopSessionId;
                _simulatedLoopSessionId = null;
                await _simulationSessionManager.EndSessionAsync(sessionId);
            }
        });

        _guidedTourController.RegisterTourSessionCleanup(() =>
        {
            if (_tourNoteItem is not null && _notesStore is not null)
            {
                var note = _tourNoteItem;
                _tourNoteItem = null;
                _noteItems.RemoveAll(n => n.Id == note.Id);
                _notesStore.DeleteContent(note.Id);
                _notesStore.SaveAll(_noteItems);
                _notesPanel?.Refresh(_noteItems);

                if (_documentationModeEnabled)
                    SetDocumentationMode(false, persistChange: false);
            }
            return Task.CompletedTask;
        });
    }

    /// <summary>
    /// Resolves a named element for the tour highlight system.  Searches _guidedTourCoordinator.NamedElements,
    /// the main window visual tree, any registered popup roots, and the Preferences window.
    /// </summary>
    private FrameworkElement? ResolveTourHighlightElement(string name)
    {
        if (_guidedTourCoordinator.NamedElements.TryGetValue(name, out var namedEl))
            return namedEl;
        var el = VisualTreeSearch.FindByName(this, name) as FrameworkElement;
        if (el is null)
        {
            foreach (var root in _guidedTourCoordinator.NamedElements.Values)
            {
                el = VisualTreeSearch.FindByName(root, name) as FrameworkElement;
                if (el is not null) break;
            }
        }
        if (el is null && _preferencesWindow is { IsVisible: true })
            el = VisualTreeSearch.FindByName(_preferencesWindow, name) as FrameworkElement;
        return el;
    }

    private void CleanUpTourInjectedThreads(IEnumerable<string>? injectedThreadIds = null)
    {
        if (_guidedTourController is null) return;
        var injectedIds = (injectedThreadIds ?? _guidedTourController.InjectedThreadIds).ToArray();
        if (injectedIds.Length == 0) return;

        var threadsToRemove = _agentThreadRegistry.ThreadOrder
            .Where(t => injectedIds.Contains(t.ThreadId))
            .ToArray();
        if (threadsToRemove.Length == 0) return;

        var removedSelected = _selectedTranscriptThread is not null &&
            threadsToRemove.Any(t => ReferenceEquals(t, _selectedTranscriptThread));

        RemovePrimaryAgentTranscriptHosts(threadsToRemove);
        _agentThreadRegistry.RemoveThreads(threadsToRemove);

        if (removedSelected)
            SelectTranscriptThread(CoordinatorThread);

        SyncAgentCardsWithThreads();
        CleanUpTourSimulatedAgentCard();
        CleanUpAllNamedDemoAgents();
        _guidedTourCoordinator.FirstInactiveAgentCard = null;
    }

    private void CleanUpTourSimulatedAgentCard()
    {
        if (_guidedTourCoordinator.SimulatedAgentCard is null) return;
        var card = _guidedTourCoordinator.SimulatedAgentCard;
        _guidedTourCoordinator.SimulatedAgentCard = null;
        _guidedTourCoordinator.FirstInactiveAgentCard = null;

        // Close any open secondary panel for this card
        var entry = _secondaryTranscripts.FirstOrDefault(e => e.Agent == card);
        if (entry is not null) CloseSecondaryPanel(entry);

        // Remove from agent collections
        _inactiveAgentCards.Remove(card);
        _agents.Remove(card);
        SyncAgentCardsWithThreads();
    }

    private void EnsureSimulationSessionManager()
    {
        if (_simulationSessionManager is not null)
            return;

        _simulationSessionManager = new SimulationSessionManager();

        if (_plansPanelController is not null)
        {
            _planSimulationSurfaceAdapter = new PlanSimulationSurfaceAdapter(
                _plansPanelController, Dispatcher);
            _simulationSessionManager.RegisterAdapter(_planSimulationSurfaceAdapter);
        }

        if (_notesPanel is not null)
        {
            _notesSimulationSurfaceAdapter = new NotesSimulationSurfaceAdapter(
                _notesPanel, Dispatcher);
            _simulationSessionManager.RegisterAdapter(_notesSimulationSurfaceAdapter);
        }

        if (_tasksPanelController is not null)
        {
            _tasksSimulationSurfaceAdapter = new TasksSimulationSurfaceAdapter(
                _tasksPanelController, Dispatcher);
            _simulationSessionManager.RegisterAdapter(_tasksSimulationSurfaceAdapter);
        }

        if (_approvalPanel is not null)
        {
            _approvalsSimulationSurfaceAdapter = new ApprovalsSimulationSurfaceAdapter(
                _approvalPanel, Dispatcher);
            _simulationSessionManager.RegisterAdapter(_approvalsSimulationSurfaceAdapter);
            _approvalPanel.IsSimulatedItem = id => _approvalsSimulationSurfaceAdapter.IsSimulatedItem(id);
        }

        if (_inboxPanel is not null)
        {
            _inboxSimulationSurfaceAdapter = new InboxSimulationSurfaceAdapter(
                _inboxPanel, Dispatcher);
            _simulationSessionManager.RegisterAdapter(_inboxSimulationSurfaceAdapter);
        }

        {
            _loopSimulationSurfaceAdapter = new LoopSimulationSurfaceAdapter(
                applyState: state =>
                {
                    _loopPanelVisible = true;
                    LoopStatusLabel.Text = state.StatusText;
                    LoopStatusLabel.Visibility = Visibility.Visible;
                    StartLoopButton.Visibility = Visibility.Collapsed;
                    StopLoopButton.IsEnabled = false;
                    AbortLoopButton.Visibility = Visibility.Collapsed;
                    SyncLoopPanel();
                },
                clearState: () =>
                {
                    LoopStatusLabel.Text = string.Empty;
                    LoopStatusLabel.Visibility = Visibility.Collapsed;
                    StartLoopButton.Visibility = Visibility.Visible;
                    StartLoopButton.IsEnabled = true;
                    StopLoopButton.IsEnabled = false;
                    AbortLoopButton.Visibility = Visibility.Collapsed;
                    SyncLoopPanel();
                },
                Dispatcher);
            _simulationSessionManager.RegisterAdapter(_loopSimulationSurfaceAdapter);
        }
    }

    private void CleanUpAllNamedDemoAgents()
    {
        if (_guidedTourCoordinator.NamedDemoAgents.Count == 0) return;

        foreach (var (name, timer) in _guidedTourCoordinator.DemoAgentSpinnerTimers)
            timer.Stop();
        _guidedTourCoordinator.DemoAgentSpinnerTimers.Clear();

        var threadsToRemove = new List<TranscriptThreadState>();

        foreach (var (name, (card, thread)) in _guidedTourCoordinator.NamedDemoAgents)
        {
            var secondaryEntry = _secondaryTranscripts.FirstOrDefault(e => e.Agent == card);
            if (secondaryEntry is not null) CloseSecondaryPanel(secondaryEntry);

            _inactiveAgentCards.Remove(card);
            _agents.Remove(card);

            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgent_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTranscript_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTranscriptTitle_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentSpinner_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTitle_{name}");

            threadsToRemove.Add(thread);
        }

        _guidedTourCoordinator.NamedDemoAgents.Clear();

        if (threadsToRemove.Count > 0)
        {
            RemovePrimaryAgentTranscriptHosts(threadsToRemove);
            _agentThreadRegistry.RemoveThreads(threadsToRemove);
        }

        SyncAgentCardsWithThreads();
    }

    private void CleanUpTourInjectedCoordinatorBlocks()
    {
        if (_guidedTourCoordinator.InjectedCoordinatorBlocks.Count == 0) return;

        var doc = CoordinatorThread.Document;
        foreach (var block in _guidedTourCoordinator.InjectedCoordinatorBlocks)
        {
            try { doc.Blocks.Remove(block); } catch { /* block may have already been removed */ }
        }
        _guidedTourCoordinator.InjectedCoordinatorBlocks.Clear();
        _guidedTourCoordinator.NamedElements.Clear();
    }

    /// <summary>
    /// Removes all demo prompt-queue items added during a guided tour (both dummy items and
    /// the TypeIntoPrompt animation item). Restores the pre-edit draft if the user had clicked
    /// into a demo tab. Safe to call when no tour items exist (no-op in that case).
    /// </summary>
    private void CleanUpTourQueueItems()
    {
        // The active tab's live text lives in PromptTextBox and has not been flushed to item.Text
        // yet (see comment at line ~4051).  Sync it now so that HasSubstantialTourWork sees the
        // real current text rather than the stale initial text stored in the item.
        if (_activeTabId is not null)
        {
            var liveItem = _promptQueue.Items.FirstOrDefault(i => i.Id == _activeTabId);
            if (liveItem is not null)
                liveItem.Text = PromptTextBox.Text;
        }

        // If the user clicked into a demo tab that will be removed, restore the pre-edit draft
        // so their real text is not lost.  Only restore if the active dummy item is being removed
        // (i.e., does not have substantial work that would cause it to be preserved).
        if (_activeTabId is not null &&
            _promptQueue.Items.Any(i => i.Id == _activeTabId && IsTourOrSimTag(i.SourceTag)))
        {
            var activeItem = _promptQueue.Items.FirstOrDefault(i => i.Id == _activeTabId);
            bool activeWillBeRemoved = activeItem is null || !HasSubstantialTourWork(activeItem);
            if (activeWillBeRemoved)
            {
                _activeTabId = null;
                SetPromptTextBoxLogicalBuffer(
                    _queuePreEditDraft ?? string.Empty,
                    _queuePreEditDraftCaretIndex,
                    _queuePreEditDraftSelectionStart,
                    _queuePreEditDraftSelectionLength,
                    "tour-cleanup-restore-draft");
                _queuePreEditDraft = null;
            }
            else
            {
                // The active dummy item is preserved — clear pre-edit draft state without restoring.
                _queuePreEditDraft = null;
            }
        }

        StopTypeIntoPromptAnimation(); // removes TourTypeTag item + stops timer

        // Remove dummy items, but preserve any the user has substantially edited.
        var dummyItems = _promptQueue.Items.Where(i => i.SourceTag == TourDummyTag).ToList();
        foreach (var item in dummyItems)
        {
            if (!HasSubstantialTourWork(item))
                _promptQueue.RemoveItem(item);
        }

        SyncQueuePanel();
    }

    private static bool HasSubstantialTourWork(PromptQueueItem item)
    {
        if (item.HasSubstantialVoiceWork) return true;
        var initialLength = item.InitialText?.Length ?? 0;
        return Math.Abs(item.Text.Length - initialLength) > 40;
    }

    private static int CountWords(string text)
        => text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;

    /// <summary>
    /// Removes the last <c>TourQuickReplyPanel</c> block from the coordinator transcript,
    /// so that consecutive tour text injections don't accumulate stale quick-reply panels.
    /// </summary>
    private void RemoveLastTourQuickReplyPanel()
    {
        var doc    = CoordinatorThread.Document;
        var blocks = doc.Blocks.ToList();
        for (int i = blocks.Count - 1; i >= 0; i--)
        {
            if (blocks[i] is System.Windows.Documents.BlockUIContainer buc &&
                buc.Child is System.Windows.Controls.WrapPanel wp &&
                wp.Name == "TourQuickReplyPanel")
            {
                try { doc.Blocks.Remove(blocks[i]); } catch { /* already gone */ }
                _guidedTourCoordinator.InjectedCoordinatorBlocks.Remove(blocks[i]);
                _currentQuickReplyOptions = [];
                _currentQuickReplyPayloads = [];
                return;
            }
        }
    }

