            var text  = (sep >= 0 ? arg[(sep + 1)..] : arg).Replace(@"\n", "\n");
            var list  = GetOrCreateFollowUpList("");
            if (list.Any(a => a.ContentBlock == text)) return;
            list.Add(new FollowUpAttachment("", label, null, ContentBlock: text));
            UpdateFollowUpStrip();
            SyncQueuePanel();
        });

