        _guidedTourCoordinator.CommandRegistry.Register("CreateTourNote", () =>
        {
            if (_notesStore is null) return;

            // Idempotent: skip creation if a note with this title already exists.
            if (_notesPanel is not null && _notesPanel.ContainsNoteWithTitle("Tour Sample Note"))
                return;

            var note = new NoteItem(Guid.NewGuid(), "Tour Sample Note", DateTimeOffset.UtcNow.ToUnixTimeSeconds());
            _notesStore.WriteContent(note.Id, "# Welcome to Notes\n\nThis is a **sample note** created for the guided tour.\n\n## Features\n\n- Markdown formatting\n- Quick access from the panel\n- Source editing mode");
            _noteItems.Insert(0, note);
            _notesStore.SaveAll(_noteItems);
            _tourNoteItem = note;

            if (!_notesPanelVisible)
            {
                _notesPanelVisible = true;
                SyncNotesPanel();
            }
            else
            {
                _notesPanel?.Refresh(_noteItems);
            }
        });

        _guidedTourCoordinator.CommandRegistry.Register("OpenTourNoteInDocsPanel", () =>
        {
            if (_tourNoteItem is null || _notesStore is null) return;
            var path = _notesStore.GetNotePath(_tourNoteItem.Id);
            if (!File.Exists(path)) return;

            if (!_documentationModeEnabled)
                SetDocumentationMode(true, persistChange: false);

            _currentDocPath = path;
            var rawMarkdown = File.ReadAllText(path);
            var markdown = StripDocFrontMatter(rawMarkdown, out _);
            var html = MarkdownHtmlBuilder.Build(markdown, _tourNoteItem.Title,
                filePath: path, isDark: AgentStatusCard.IsDarkTheme);
            DocMarkdownViewer?.NavigateToString(html);
        });

        _guidedTourCoordinator.CommandRegistry.Register("ShowNoteSource", () =>
        {
            if (!IsDocSourceVisible())
                ShowDocSourcePanel();
        });

        _guidedTourCoordinator.CommandRegistry.Register("CleanUpTourNote", () =>
        {
            if (_tourNoteItem is null || _notesStore is null) return;
            var note = _tourNoteItem;
            _tourNoteItem = null;
            _noteItems.RemoveAll(n => n.Id == note.Id);
            _notesStore.DeleteContent(note.Id);
            _notesStore.SaveAll(_noteItems);
            _notesPanel?.Refresh(_noteItems);

            if (_documentationModeEnabled)
                SetDocumentationMode(false, persistChange: false);
        });

        _guidedTourCoordinator.CommandRegistry.RegisterParameterizedAsync("CreateDemoAgent", async arg =>
        {
            // Format: "AgentName" or "AgentName|#RRGGBB"
            var parts = arg.Split('|', 2);
            var name = parts[0].Trim();
            var accentHex = parts.Length > 1 ? parts[1].Trim() : null;
            if (string.IsNullOrEmpty(name)) return;
            if (_guidedTourCoordinator.NamedDemoAgents.ContainsKey(name)) return;

            var agentId = "tour-demo-" + name.ToLowerInvariant().Replace(' ', '-');
            var thread = _agentThreadRegistry.GetOrCreateAgentThread(
                toolCallId:       null,
                agentId:          agentId,
                agentName:        agentId,
                agentDisplayName: name,
                agentDescription: "Simulated agent for guided tour.",
                status:           null,
                prompt:           null,
                startedAt:        null);
            thread.IsCurrentBackgroundRun    = true;
            thread.WasObservedAsBackgroundTask = true;
            thread.IsTourDemoThread          = true;
            thread.LastObservedActivityAt    = DateTimeOffset.UtcNow;
            if (!string.IsNullOrWhiteSpace(accentHex))
                thread.TourDemoAccentHex = accentHex;  // remembered so EnsureDynamicAgentCards re-applies it on rebuild
            _guidedTourController?.TrackInjectedThread(thread.ThreadId);

            await Dispatcher.InvokeAsync(() => { }, System.Windows.Threading.DispatcherPriority.Loaded);
            SyncAgentCardsWithThreads();
            await Dispatcher.InvokeAsync(() => { }, System.Windows.Threading.DispatcherPriority.Loaded);

            var card = _activeAgentCards
                .Concat(_inactiveAgentCards)
                .FirstOrDefault(c => string.Equals(c.Name, name, StringComparison.OrdinalIgnoreCase));
            if (card is null) return;

            // Apply the tour-specified color (already done by EnsureDynamicAgentCards via TourDemoAccentHex,
            // but guard here for the initial creation pass in case the card was just built).
            if (!string.IsNullOrWhiteSpace(accentHex))
                ApplyAgentAccent(card, accentHex, persist: false);

            _guidedTourCoordinator.NamedDemoAgents[name] = (card, thread);

            await Dispatcher.InvokeAsync(() => { }, System.Windows.Threading.DispatcherPriority.Loaded);
            var border = FindAgentCardBorderForCard(card);
            if (border is not null)
                _guidedTourCoordinator.NamedElements[$"TourDemoAgent_{name}"] = border;
        });

        _guidedTourCoordinator.CommandRegistry.RegisterParameterizedAsync("ActivateDemoAgent", async arg =>
        {
            var name = arg.Trim();
            if (!_guidedTourCoordinator.NamedDemoAgents.TryGetValue(name, out var entry)) return;
            var (card, thread) = entry;

            OpenSecondaryPanel(card, thread, isAutoOpenedInMultiMode: false);

            // Move the card into the active column.  EnsureDynamicAgentCards (called by
            // SyncAgentCardsWithThreads) rebuilds dynamic cards on every sync, so the
            // card object stored in _guidedTourCoordinator.NamedDemoAgents may be stale by the time
            // ActivateDemoAgent runs.  Refreshing LastObservedActivityAt and calling
            // SyncAgentCardsWithThreads guarantees (a) a fresh card object exists,
            // (b) the thread qualifies as active, and (c) the card lands in the active
            // column before we look up its visual elements.
            thread.LastObservedActivityAt = DateTimeOffset.UtcNow;
            SyncAgentCardsWithThreads();
            await Dispatcher.InvokeAsync(() => { }, System.Windows.Threading.DispatcherPriority.Loaded);

            // Refresh the card reference in case EnsureDynamicAgentCards replaced it.
            var latestCard = _activeAgentCards
                .Concat(_inactiveAgentCards)
                .FirstOrDefault(c => string.Equals(c.Name, name, StringComparison.OrdinalIgnoreCase));
            if (latestCard is not null && !ReferenceEquals(latestCard, card))
            {
                card = latestCard;
                _guidedTourCoordinator.NamedDemoAgents[name] = (card, thread);

                // Re-register the card-border element so tour highlights target the new card.
                var freshBorder = FindAgentCardBorderForCard(card);
                if (freshBorder is not null)
                    _guidedTourCoordinator.NamedElements[$"TourDemoAgent_{name}"] = freshBorder;
            }

            await Dispatcher.InvokeAsync(() => { }, System.Windows.Threading.DispatcherPriority.Loaded);
            var secondaryEntry = _secondaryTranscripts.FirstOrDefault(e => e.Agent == card);
            if (secondaryEntry is not null)
            {
                _guidedTourCoordinator.NamedElements[$"TourDemoAgentTranscript_{name}"] = secondaryEntry.PanelBorder;
                _guidedTourCoordinator.NamedElements[$"TourDemoAgentTranscriptTitle_{name}"] = secondaryEntry.TitleBlock;
            }

            // Register the spinner and name label inside the card's visual container.
            var cardContainer = FindAgentCardBorderForCard(card);
            if (cardContainer is not null)
            {
                var spinner = VisualTreeSearch.FindChild<ActivitySpinner>(cardContainer);
                if (spinner is not null)
                {
                    // Slow the tour demo spinner to ~1 rotation/sec (7 rad/s ≈ 3× slower than the 20 rad/s default)
                    spinner.MaxAngularVelocityCap = 7.0;
                    _guidedTourCoordinator.NamedElements[$"TourDemoAgentSpinner_{name}"] = spinner;
                }

                var nameText = VisualTreeSearch.FindChildByName<TextBlock>(cardContainer, "AgentNameText");
                if (nameText is not null)
                    _guidedTourCoordinator.NamedElements[$"TourDemoAgentTitle_{name}"] = nameText;
            }

            // Start an animated spinner so the demo card looks like it's actively working.
            if (!_guidedTourCoordinator.DemoAgentSpinnerTimers.ContainsKey(name))
            {
                var rng   = new Random();
                var timer = new DispatcherTimer(DispatcherPriority.Background);
                timer.Interval = TimeSpan.FromMilliseconds(rng.Next(600, 1200));
                timer.Tick += (_, _) =>
                {
                    // Weighted random: 50% Thinking, 35% Reading, 15% Writing
                    var roll = rng.NextDouble();
                    var kind = roll < 0.50
                        ? SpinnerActivityKind.Thinking
                        : roll < 0.85
                            ? SpinnerActivityKind.Reading
                            : SpinnerActivityKind.Writing;

                    if (_guidedTourCoordinator.NamedDemoAgents.TryGetValue(name, out var current))
                        current.Card.FireActivityPulse(kind);

                    // Randomize next interval for an organic feel
                    timer.Interval = TimeSpan.FromMilliseconds(rng.Next(600, 1200));
                };
                timer.Start();
                _guidedTourCoordinator.DemoAgentSpinnerTimers[name] = timer;
            }
        });

        _guidedTourCoordinator.CommandRegistry.RegisterParameterizedAsync("InjectDemoAgentTurn", async arg =>
        {
            var parts     = arg.Split('|');
            var name      = parts.Length > 0 ? parts[0].Trim() : string.Empty;
            var userText  = (parts.Length > 1 ? parts[1] : string.Empty).Replace(@"\n", "\n");
            var agentText = (parts.Length > 2 ? parts[2] : string.Empty).Replace(@"\n", "\n");

            if (!_guidedTourCoordinator.NamedDemoAgents.TryGetValue(name, out var demoEntry)) return;
            var (card, thread) = demoEntry;

            var idleDeadline = Environment.TickCount64 + 10_000;
            while ((_isPromptRunning || IsLoopRunning) && Environment.TickCount64 < idleDeadline)
                await Task.Delay(UiTimingConstants.TourStepAnimationMs);

            BeginTranscriptTurn(thread, userText);

            if (!_secondaryTranscripts.Any(e => e.Agent == card))
                OpenSecondaryPanel(card, thread, isAutoOpenedInMultiMode: false);

            var rng = new Random();
            foreach (var chunk in SplitIntoWordChunks(agentText))
            {
                if (_isPromptRunning) break;
                await Dispatcher.Yield(System.Windows.Threading.DispatcherPriority.Background);
                AppendText(thread, chunk);
                await Task.Delay(rng.Next(70, 111));
            }
            thread.CurrentTurn = null;
            ScrollToEndIfAtBottom(thread);
        });

        _guidedTourCoordinator.CommandRegistry.RegisterParameterizedAsync("InjectDemoAgentTools", async arg =>
        {
            // Format: "agentName|toolName:description:output[;toolName:description:output...]"
            // The agent name is the first pipe-delimited segment; the rest is the same
            // semicolon-separated tool-spec format used by InjectTranscriptTools.
            var pipeIdx = arg.IndexOf('|');
            if (pipeIdx < 0) return;
            var name     = arg[..pipeIdx].Trim();
            var toolsArg = arg[(pipeIdx + 1)..];

            if (!_guidedTourCoordinator.NamedDemoAgents.TryGetValue(name, out var demoEntry)) return;
            var (card, thread) = demoEntry;

            var specs = toolsArg.Split(';', StringSplitOptions.RemoveEmptyEntries);
            if (specs.Length == 0) return;

            var idleDeadline = Environment.TickCount64 + 10_000;
            while ((_isPromptRunning || IsLoopRunning) && Environment.TickCount64 < idleDeadline)
                await Task.Delay(UiTimingConstants.TourStepAnimationMs);

            if (!_secondaryTranscripts.Any(e => e.Agent == card))
                OpenSecondaryPanel(card, thread, isAutoOpenedInMultiMode: false);

            BeginTranscriptTurn(thread, string.Empty);
            var turn = thread.CurrentTurn!;
            var rng  = new Random();

            var thinkingBlock = CreateThinkingBlock(turn, isExpanded: true);
            thinkingBlock.Expander.HorizontalAlignment = HorizontalAlignment.Left;
            thinkingBlock.HeaderTextBlock.Inlines.Clear();
            thinkingBlock.HeaderTextBlock.Inlines.Add(new Run("Tooling... ") { FontWeight = FontWeights.SemiBold });
            thinkingBlock.HeaderTextBlock.Inlines.Add(new Run("(simulated)") { FontStyle = FontStyles.Italic, FontWeight = FontWeights.Normal });
            _guidedTourCoordinator.NamedElements[$"TourDemoAgentTools_{name}"] = thinkingBlock.Expander;

            foreach (var spec in specs)
            {
                var parts       = spec.Split(':', 3);
                var toolName    = parts.Length > 0 ? parts[0].Trim() : "tool";
                var description = parts.Length > 1 ? parts[1].Trim() : string.Empty;
                var outputRaw   = parts.Length > 2 ? parts[2] : string.Empty;
                var output      = outputRaw.Replace(@"\n", "\n");

                var toolCallId  = "tour-tool-" + Guid.NewGuid().ToString("N")[..8];
                var descriptor  = new ToolTranscriptDescriptor(
                    ToolName:    toolName,
                    Description: description,
                    DisplayText: description);

                var entry = CreateToolEntry(thinkingBlock, toolCallId, descriptor, null, DateTimeOffset.UtcNow);
                _agentThreadRegistry.SetToolEntry(toolCallId, entry);
                RenderToolEntry(entry);

                await Task.Delay(rng.Next(400, 900));

                entry.IsCompleted   = true;
                entry.Success       = true;
                entry.FinishedAt    = DateTimeOffset.UtcNow;
                entry.OutputText    = string.IsNullOrWhiteSpace(output) ? null : output;
                entry.DetailContent = ToolTranscriptDetailContent.Build(new ToolTranscriptDetail(
                    descriptor, null, output, entry.StartedAt, entry.FinishedAt, null, true, true));
                RenderToolEntry(entry);

                await Task.Delay(rng.Next(120, 300));
            }

            thread.CurrentTurn = null;
            ScrollToEndIfAtBottom(thread);
        });

        _guidedTourCoordinator.CommandRegistry.RegisterParameterized("DeactivateDemoAgent", arg =>
        {
            var name = arg.Trim();
            if (!_guidedTourCoordinator.NamedDemoAgents.TryGetValue(name, out var entry)) return;
            var (card, _) = entry;

            var secondaryEntry = _secondaryTranscripts.FirstOrDefault(e => e.Agent == card);
            if (secondaryEntry is not null)
                CloseSecondaryPanel(secondaryEntry);

            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTranscript_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTranscriptTitle_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentSpinner_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTitle_{name}");
        });

        _guidedTourCoordinator.CommandRegistry.Register("RemoveAllDemoAgents", () =>
        {
            CleanUpAllNamedDemoAgents();
        });

        _guidedTourCoordinator.CommandRegistry.RegisterParameterized("RemoveDemoAgent", arg =>
        {
            var name = arg.Trim();
            if (!_guidedTourCoordinator.NamedDemoAgents.TryGetValue(name, out var entry)) return;
            var (card, thread) = entry;

            if (_guidedTourCoordinator.DemoAgentSpinnerTimers.TryGetValue(name, out var timer))
            {
                timer.Stop();
                _guidedTourCoordinator.DemoAgentSpinnerTimers.Remove(name);
            }

            var secondaryEntry = _secondaryTranscripts.FirstOrDefault(e => e.Agent == card);
            if (secondaryEntry is not null) CloseSecondaryPanel(secondaryEntry);

            _inactiveAgentCards.Remove(card);
            _agents.Remove(card);

            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgent_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTranscript_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTranscriptTitle_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentSpinner_{name}");
            _guidedTourCoordinator.NamedElements.Remove($"TourDemoAgentTitle_{name}");
            _guidedTourCoordinator.NamedDemoAgents.Remove(name);

            RemovePrimaryAgentTranscriptHosts([thread]);
            _agentThreadRegistry.RemoveThreads([thread]);
            SyncAgentCardsWithThreads();
        });

        _guidedTourCoordinator.CommandRegistry.Register("EnterFullScreenTranscript", () =>
        {
            // Idempotent: only transitions to full-screen if not already there.
            if (!_transcriptFullScreenEnabled)
                SetTranscriptFullScreen(true);
        });

        _guidedTourCoordinator.CommandRegistry.Register("ExitFullScreenTranscript", () =>
        {
            // Idempotent: only exits full-screen if currently in it.
            if (_transcriptFullScreenEnabled)
                SetTranscriptFullScreen(false);
        });

        _guidedTourCoordinator.CommandRegistry.Register("ShowAgentsAndTopPanels", () =>
        {
            // Idempotent: exits focus mode only when it is currently hiding the status panel.
            if (_agentsPanelFocusModeEnabled)
                SetAgentsPanelFocusMode(false);
        });

        _guidedTourCoordinator.CommandRegistry.Register("OptionsPageCloseHasPriorityOnEnter", () =>
        {
            // When this command is active for a step, pressing Enter while the Preferences
            // window is open will close it (normal WPF behaviour) instead of advancing the tour.
            // The flag is automatically cleared when the step changes or the tour stops.
            _guidedTourCoordinator.PrefsWindowEnterLetThrough = true;
        });

        _guidedTourCoordinator.CommandRegistry.Register("QuickReplyIntelliSenseEnterHasPriority", () =>
        {
            // When this command is active for a step, pressing Enter while the quick-reply
            // intellisense popup is open ([ trigger) will accept the selected item instead
            // of advancing the tour. The flag is cleared when the step changes or tour stops.
            _guidedTourCoordinator.QuickReplyIntelliSenseEnterLetThrough = true;
        });

        _guidedTourCoordinator.CommandRegistry.RegisterParameterized("PeekPromptIfEmpty", arg =>
        {
            // Only peeks the prompt box if we are in full-screen AND the prompt is not
            // already visible (i.e. the user already typed something on their own).
            // If the prompt is already showing, the command is a no-op so the tour
            // doesn't overwrite what the user typed.
            //
            // Format mirrors TypeIntoPrompt: "text to type|Mode|OnCompleteCommand"
            // Mode: "Sim" or "Draft" (defaults to Draft)
            if (!_transcriptFullScreenEnabled || _fullScreenPromptVisible)
                return;

            ShowFullScreenPrompt();

            // Type text with the same animation path as TypeIntoPrompt.
            var parts = arg.Split('|');
            var text = parts[0];
            _guidedTourCoordinator.TypeItemIsSimulated = parts.Length >= 2 &&
                string.Equals(parts[1].Trim(), "Sim", StringComparison.OrdinalIgnoreCase);
            var onComplete = parts.Length >= 3 ? parts[2].Trim() : null;
            StartTypeIntoPromptAnimation(text, string.IsNullOrWhiteSpace(onComplete) ? null : onComplete);
        });

        _guidedTourCoordinator.CommandRegistry.Register("SuppressRestartHint", () =>
        {
            // Prevents the "you can find guided tours in the Help menu" hint callout from
            // appearing when this tour run is stopped or closed. Intended for use on the
            // penultimate step of a tour that already tells the user where to re-launch tours.
            // The suppression is automatically cleared when the tour stops.
            _guidedTourController?.SuppressRestartHint();
        });
    }

    /// <summary>
    /// Starts a tour-owned transcript turn only when doing so cannot replace a real turn.
    /// The returned view is also the ownership token callers must check before clearing CurrentTurn.
    /// </summary>
    private bool TryBeginTourTranscriptTurn(
        TranscriptThreadState thread,
        string prompt,
        out TranscriptTurnView simulatedTurn)
    {
        var coordinatorIsBusy = ReferenceEquals(thread, CoordinatorThread) &&
            (_isPromptRunning || IsLoopRunning);
        if (coordinatorIsBusy || thread.CurrentTurn is not null)
        {
            SquadDashTrace.Write(
                "Tour",
                $"Skipped simulated transcript injection because target thread is busy. " +
                $"thread={thread.ThreadId} coordinatorBusy={coordinatorIsBusy} hasCurrentTurn={thread.CurrentTurn is not null}");
            simulatedTurn = null!;
            return false;
        }

        simulatedTurn = BeginTranscriptTurn(thread, prompt);
        return true;
    }

    /// <summary>
    /// Injects simulated tool call blocks into the coordinator transcript for a guided tour step.
    /// Each tool runs with an animated delay, then completes. The "Tooling..." expander is
    /// registered as <c>TourInjectedToolingBlock</c> for callout targeting.
    /// </summary>
    private async Task InjectTourTranscriptTools(string arg)
    {
        var specs = arg.Split(';', StringSplitOptions.RemoveEmptyEntries);
        if (specs.Length == 0) return;

        var idleDeadline = Environment.TickCount64 + 1_500;
        while ((_isPromptRunning || IsLoopRunning) && Environment.TickCount64 < idleDeadline)
            await Task.Delay(UiTimingConstants.TourStepAnimationMs);

        int blocksBefore = CoordinatorThread.Document.Blocks.Count;
        var rng = new Random();

        if (!TryBeginTourTranscriptTurn(CoordinatorThread, string.Empty, out var turn))
            return;

        var thinkingBlock = CreateThinkingBlock(turn, isExpanded: true);
        thinkingBlock.Expander.Name                = "TourInjectedToolingBlock";
        thinkingBlock.Expander.HorizontalAlignment = HorizontalAlignment.Left;
        thinkingBlock.HeaderTextBlock.Inlines.Clear();
        thinkingBlock.HeaderTextBlock.Inlines.Add(new Run("Tooling... ") { FontWeight = FontWeights.SemiBold });
        thinkingBlock.HeaderTextBlock.Inlines.Add(new Run("(simulated)") { FontStyle = FontStyles.Italic, FontWeight = FontWeights.Normal });
        _guidedTourCoordinator.NamedElements["TourInjectedToolingBlock"] = thinkingBlock.Expander;

        foreach (var spec in specs)
        {
            var parts       = spec.Split(':', 3);
            var toolName    = parts.Length > 0 ? parts[0].Trim() : "tool";
            var description = parts.Length > 1 ? parts[1].Trim() : string.Empty;
            var outputRaw   = parts.Length > 2 ? parts[2] : string.Empty;
            var output      = outputRaw.Replace(@"\n", "\n");

            var toolCallId = "tour-tool-" + Guid.NewGuid().ToString("N")[..8];
            var descriptor = new ToolTranscriptDescriptor(
                ToolName:    toolName,
                Description: description,
                DisplayText: description);

            var entry = CreateToolEntry(thinkingBlock, toolCallId, descriptor, null, DateTimeOffset.UtcNow);
            _agentThreadRegistry.SetToolEntry(toolCallId, entry);
            RenderToolEntry(entry);

            await Task.Delay(rng.Next(400, 900));

            entry.IsCompleted   = true;
            entry.Success       = true;
            entry.FinishedAt    = DateTimeOffset.UtcNow;
            entry.OutputText    = string.IsNullOrWhiteSpace(output) ? null : output;
            entry.DetailContent = ToolTranscriptDetailContent.Build(new ToolTranscriptDetail(
                descriptor, null, output, entry.StartedAt, entry.FinishedAt, null, true, true));
            RenderToolEntry(entry);

            await Task.Delay(rng.Next(120, 300));
        }

        // Register the overall last tool entry and the last entry for each tool name
        // so tour steps can target e.g. "TourInjectedLastToolEntry_edit" directly.
        if (thinkingBlock.ToolEntries.Count > 0)
            _guidedTourCoordinator.NamedElements["TourInjectedLastToolEntry"] = thinkingBlock.ToolEntries[^1].Expander;
        foreach (var toolEntry in thinkingBlock.ToolEntries)
        {
            var key = "TourInjectedLastToolEntry_" + toolEntry.Descriptor.ToolName.Trim().ToLowerInvariant();
            _guidedTourCoordinator.NamedElements[key] = toolEntry.Expander;
        }

        if (!ReferenceEquals(CoordinatorThread.CurrentTurn, turn))
            return;
        CoordinatorThread.CurrentTurn = null;
        TrackNewCoordinatorBlocks(blocksBefore);
        SelectTranscriptThread(CoordinatorThread);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    /// <summary>
    /// Injects a synthetic markdown turn into the specified transcript thread for a guided tour step.
    /// Creates a temporary thread if <paramref name="agentName"/> is specified but not found.
    /// </summary>
    private void InjectTourTranscriptText(string markdownText, string? agentName)
    {
        // Remove any existing quick-reply panel before adding new text.
        if (string.IsNullOrWhiteSpace(agentName))
            RemoveLastTourQuickReplyPanel();
        TranscriptThreadState targetThread;

        if (string.IsNullOrWhiteSpace(agentName))
        {
            targetThread = CoordinatorThread;
        }
        else
        {
            var existing = _agentThreadRegistry.ThreadOrder.FirstOrDefault(t =>
                string.Equals(t.AgentName, agentName, StringComparison.OrdinalIgnoreCase) ||
                string.Equals(t.AgentDisplayName, agentName, StringComparison.OrdinalIgnoreCase) ||
                string.Equals(t.Title, agentName, StringComparison.OrdinalIgnoreCase));

            if (existing is not null)
            {
                targetThread = existing;
            }
            else
            {
                var agentId = "tour-demo-" + agentName.ToLowerInvariant().Replace(" ", "-");
                targetThread = _agentThreadRegistry.GetOrCreateAgentThread(
                    toolCallId:       null,
                    agentId:          agentId,
                    agentName:        agentId,
                    agentDisplayName: agentName,
                    agentDescription: null,
                    status:           null,
                    prompt:           null,
                    startedAt:        null);
                _guidedTourController?.TrackInjectedThread(targetThread.ThreadId);
            }
        }

        var syntheticTurn = new TranscriptTurnRecord(
            StartedAt:        DateTimeOffset.UtcNow,
            CompletedAt:      DateTimeOffset.UtcNow,
            Prompt:           string.Empty,
            ThinkingText:     string.Empty,
            ResponseText:     markdownText,
            ThinkingCollapsed: true,
            Tools:            Array.Empty<TranscriptToolRecord>())
        {
            IsTourInjected = true,
        };

        int blocksBefore = ReferenceEquals(targetThread, CoordinatorThread)
            ? CoordinatorThread.Document.Blocks.Count : -1;

        RenderPersistedTurn(targetThread, syntheticTurn, isLastTurn: true);
        SelectTranscriptThread(targetThread);

        if (blocksBefore >= 0)
            TrackNewCoordinatorBlocks(blocksBefore);
    }

    /// <summary>
    /// Records any blocks added to the coordinator thread's document since
    /// <paramref name="previousCount"/> so they can be removed when the tour ends.
    /// </summary>
    private void TrackNewCoordinatorBlocks(int previousCount)
    {
        var allBlocks = CoordinatorThread.Document.Blocks.ToList();
        for (int i = previousCount; i < allBlocks.Count; i++)
            _guidedTourCoordinator.InjectedCoordinatorBlocks.Add(allBlocks[i]);
    }

    private static IEnumerable<string> SplitIntoWordChunks(string text, int minWords = 3, int maxWords = 5)
    {
        var parts = text.Split(' ');
        var rng   = new Random();
        var i     = 0;
        while (i < parts.Length)
        {
            var take  = rng.Next(minWords, maxWords + 1);
            var chunk = string.Join(" ", parts.Skip(i).Take(take));
            if (i > 0) chunk = " " + chunk;
            yield return chunk;
            i += take;
        }
    }

    /// <summary>
    /// Injects a simulated agent response with real quick reply buttons into the coordinator
    /// transcript and waits until those buttons are rendered in the visual tree.
    /// </summary>
    private async Task InjectTourTranscriptTextWithReplies(string messageText, string[] buttonLabels)
    {
        // Remove any existing quick-reply panel before injecting a replacement.
        // Wait for coordinator to finish before injecting simulated text (max 10 s).
        var idleDeadline = Environment.TickCount64 + 10_000;
        while ((_isPromptRunning || IsLoopRunning) && Environment.TickCount64 < idleDeadline)
            await Task.Delay(UiTimingConstants.TourStepAnimationMs);

        RemoveLastTourQuickReplyPanel();

        int blocksBefore = CoordinatorThread.Document.Blocks.Count;

        // Create a streaming turn that mimics a real agent response.
        if (!TryBeginTourTranscriptTurn(CoordinatorThread, string.Empty, out var simulatedTurn))
            return;
        SelectTranscriptThread(CoordinatorThread);

        // Inject the badge prefix immediately (static label).
        AppendText(CoordinatorThread, "*🎓 Tour simulation — not a real agent response.*\n\n");

        // Stream message text word-by-word to simulate live AI output.
        var rng = new Random();
        foreach (var chunk in SplitIntoWordChunks(messageText))
        {
            if (!ReferenceEquals(CoordinatorThread.CurrentTurn, simulatedTurn)) break;
            await Dispatcher.Yield(System.Windows.Threading.DispatcherPriority.Background);
            if (!ReferenceEquals(CoordinatorThread.CurrentTurn, simulatedTurn)) break;
            AppendText(CoordinatorThread, chunk);
            await Task.Delay(rng.Next(70, 111));
        }

        // Finalise the turn in place (no persistence needed for tour simulation).
        if (!ReferenceEquals(CoordinatorThread.CurrentTurn, simulatedTurn))
            return;
        CoordinatorThread.CurrentTurn = null;

        var panel = new System.Windows.Controls.WrapPanel
        {
            Name                = "TourQuickReplyPanel",
            Margin              = new System.Windows.Thickness(0, 2, 0, 0),
            Orientation         = System.Windows.Controls.Orientation.Horizontal,
            HorizontalAlignment = System.Windows.HorizontalAlignment.Left,
        };

        foreach (var label in buttonLabels)
        {
            var button = TranscriptQuickReplyFactory.CreateButton(
                label,
                _transcriptFontSize,
                new TourQuickReplyPayload(label));
            button.Click += TourQuickReplyButton_Click;
            panel.Children.Add(button);
        }

        var block = TranscriptQuickReplyFactory.CreateContainer(panel);
        CoordinatorThread.Document.Blocks.Add(block);
        TrackNewCoordinatorBlocks(blocksBefore);
        ScrollToEndIfAtBottom(CoordinatorThread);

        // Expose labels in intellisense so [ in the prompt box offers the same options.
        // Tour buttons use TourQuickReplyPayload, so there are no routing payloads.
        _currentQuickReplyOptions = buttonLabels;
        _currentQuickReplyPayloads = [];

        // Poll until the panel is present in the visual tree (up to 2 s).
        var timeout = System.Threading.Tasks.Task.Delay(UiTimingConstants.TourPanelPollTimeoutMs);
        while (!timeout.IsCompleted)
        {
            await Dispatcher.Yield(System.Windows.Threading.DispatcherPriority.Background);
            if (VisualTreeSearch.FindByName(this, "TourQuickReplyPanel") is not null)
                break;
        }
    }

    /// <summary>
    /// Handles a click on a tour-injected quick reply button: injects a simulated user
    /// selection into the transcript and fires the <c>_tourQuickReplySelected</c> event
    /// so that a <c>QuickReplySelected</c> advance trigger can advance the tour step.
    /// </summary>
    private void TourQuickReplyButton_Click(object sender, System.Windows.RoutedEventArgs e)
    {
        if (sender is not System.Windows.FrameworkElement { Tag: TourQuickReplyPayload payload })
            return;

        _currentQuickReplyOptions = [];
        _currentQuickReplyPayloads = [];
        SquadDashTrace.Write("Tour", $"Tour quick reply selected: '{payload.Option}'");
        InjectTourTranscriptText($"*🎓 (Tour) You selected: {payload.Option}*", null);
        _guidedTourCoordinator.RaiseQuickReplySelected();
    }

    private void StopTypeIntoPromptAnimation()
    {
        _guidedTourCoordinator.TypeItemIsSimulated = false;

        // Stop the timer if it's still running (it self-nulls when the text is fully typed,
        // but TourTypeTag items may still be in the queue after that — handle both cases).
        FreezeTypeIntoPromptAnimation();

        // Nothing to clean up if no tour-type items remain.
        if (!_promptQueue.Items.Any(i => i.SourceTag == TourTypeTag))
            return;

        // If the tour-typed tab is currently active, restore the pre-edit draft before removing it.
        if (_activeTabId is not null &&
            _promptQueue.Items.Any(i => i.Id == _activeTabId && i.SourceTag == TourTypeTag))
        {
            _activeTabId = null;
            SetPromptTextBoxLogicalBuffer(
                _queuePreEditDraft ?? string.Empty,
                _queuePreEditDraftCaretIndex,
                _queuePreEditDraftSelectionStart,
                _queuePreEditDraftSelectionLength,
                "tour-type-cleanup-restore-draft");
            _queuePreEditDraft = null;
        }
        _promptQueue.RemoveByTag(TourTypeTag);
        SyncQueuePanel();
    }

    /// <summary>
    /// Stops the TypeIntoPrompt timer (freezing the animation mid-type) without removing
    /// the queue item. Used on step transitions so the typed text persists visibly until
    /// the tour step that owns it explicitly removes it via "Remove Dummy Queue Items".
    /// </summary>
    private void FreezeTypeIntoPromptAnimation()
    {
        if (_typeIntoPromptTimer is null) return;
        _typeIntoPromptTimer.Stop();
        _typeIntoPromptTimer = null;
    }

    private void StartTypeIntoPromptAnimation(string text, string? onCompleteCommand = null)
    {
        StopTypeIntoPromptAnimation(); // cancel any in-progress animation (also removes any prior tour-type item)

        var item = new PromptQueueItem
        {
            Text           = string.Empty,
            IsEditing      = true,
            SequenceNumber = _promptQueueCoordinator.NextSequenceNumber(),
            QueueNumber    = NextQueueNumber(),
            SourceTag      = TourTypeTag
        };
        _promptQueue.EnqueueItemAtFront(item);
        SyncQueuePanel();
        OnQueueTabClicked(item.Id);

        var charIndex = 0;
        var rng = new Random();

        // Pre-compute per-character delays for natural human-like typing.
        // Within a word: fast with small jitter (25–55 ms).
        // At a word boundary (space/punctuation before next word): longer pause
        // scaled by next-word length — short words get ~80 ms, long words up to ~200 ms,
        // with added random variance so no two pauses feel identical.
        var delays = new int[text.Length];
        for (int i = 0; i < text.Length; i++)
        {
            char c = text[i];
            bool isWordBoundary = c == ' ' || c == '\n' || c == '\t' ||
                                  c == ',' || c == '.' || c == '?' || c == '!';
            if (isWordBoundary)
            {
                // Measure length of the next word to scale the pause.
                int nextWordLen = 0;
                for (int j = i + 1; j < text.Length; j++)
                {
                    char nc = text[j];
                    if (nc == ' ' || nc == '\n' || nc == '\t') break;
                    nextWordLen++;
                }
                // Short words (1-3 chars) → ~80 ms pause; long words (8+) → ~200 ms.
                int basePause = 70 + Math.Min(nextWordLen, 8) * 16;
                delays[i] = basePause + rng.Next(-25, 60);
            }
            else
            {
                // Within a word: fast with light jitter.
                delays[i] = 28 + rng.Next(0, 30);
            }
        }

        int delayIndex = 0;
        void ScheduleNext()
        {
            if (delayIndex >= delays.Length) return;
            var ms = delays[delayIndex++];
            _typeIntoPromptTimer = new DispatcherTimer { Interval = TimeSpan.FromMilliseconds(ms) };
            _typeIntoPromptTimer.Tick += (_, _) =>
            {
                _typeIntoPromptTimer?.Stop();
                _typeIntoPromptTimer = null;
                if (charIndex < text.Length)
                {
                    item.Text = text[..++charIndex];
                    SetPromptTextBoxLogicalBuffer(item.Text, item.Text.Length, reason: "tour-type");
                    SyncQueuePanel();
                    if (charIndex == text.Length && !string.IsNullOrWhiteSpace(onCompleteCommand))
                        _ = _guidedTourCoordinator.CommandRegistry.ExecuteAsync(onCompleteCommand.Trim());
                    else
                        ScheduleNext();
                }
            };
            _typeIntoPromptTimer.Start();
        }

        if (text.Length == 0 && !string.IsNullOrWhiteSpace(onCompleteCommand))
            _ = _guidedTourCoordinator.CommandRegistry.ExecuteAsync(onCompleteCommand.Trim());
        else
            ScheduleNext();
    }

    private void OfferGuidedTourOnFirstRun()
    {
        if (GuidedTourStateStore.Shared.Offered) return;
        if (!WorkspaceHasRealTeamMembers()) return;
        GuidedTourStateStore.Shared.Offered = true;
        ShowWelcomeSplash();
    }

    private bool WorkspaceHasRealTeamMembers()
    {
        if (_currentWorkspace is null) return false;
        try
        {
            var members = new SquadTeamRosterLoader().Load(_currentWorkspace.FolderPath);
            return SquadTeamRosterLoader.HasNonUtilityMembers(members);
        }
        catch { return false; }
    }

    private void ShowWelcomeSplash()
    {
        var splash = new SquadDash.GuidedTours.FrmWelcome();
        splash.Owner = this;
        splash.StartTourClicked += (_, _) => StartFirstTour();
        splash.SkipClicked      += (_, _) => GuidedTourStateStore.Shared.SkippedFirstRun = true;
        splash.ShowDialog();
    }

