    private void PreferencesMenuItem_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_preferencesWindow is { IsVisible: true })
            {
                _preferencesWindow.Activate();
                _guidedTourCoordinator.RaisePreferencesWindowShown();
                return;
            }

            var showDevOptions = Keyboard.Modifiers.HasFlag(ModifierKeys.Shift);
            _preferencesWindow = PreferencesWindow.Open(
                CanShowOwnedWindow() ? this : null,
                _settingsStore,
                _settingsSnapshot,
                _pushNotificationService,
                _cliResolutionService,
                _cliSelectionStore,
                _cliModelCatalogService,
                _currentWorkspace?.FolderPath ?? _workspacePaths.ApplicationRoot,
                _workspacePaths,
                showDevOptions,
                snapshot =>
                {
                    _settingsManager.Replace(snapshot);
                    _pushNotificationService.ReloadProvider();
                    UpdateVoiceHintVisibility();
                    RefreshInstallationState();
                    RefreshDeveloperRuntimeIssuePreview();
                    if (!ApplyBridgeModelSettings(snapshot, "preferences-model-changed"))
                        SquadDashTrace.Write("Bridge", "Preferences saved; model bridge settings unchanged, no bridge restart needed.");
                },
                startPtt: (tb) => {
                    _pttTargetTextBox = tb;
                    _sessionCaretIndex = tb.SelectionStart;
                    _sessionSelectionLength = tb.SelectionLength;
                    _voiceStartedWithSendEnabled = false;
                    _pttState = PttState.Active;
                    _ = StartPushToTalkAsync();
                },
                stopPtt: () => _ = StopPushToTalkAsync(send: false),
                startGuidedTour: () => OpenGuidedTourSelector(),
                workHoursStore:      _workHoursStore,
                workHoursWorkspaceDir: _currentWorkspace is not null
                    ? _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace.FolderPath)
                    : null,
                onWorkHoursSaved: settings => _commitActivityGraphWindow?.SetWorkHours(settings),
                tourHasEnterPriority: () => _guidedTourController is { IsActive: true } && !_guidedTourCoordinator.PrefsWindowEnterLetThrough,
                advanceTourStep: () => _guidedTourController?.Next());
            _preferencesWindow.PageSelected += label => _guidedTourCoordinator.RaisePreferencePageSelected(label);
            _preferencesWindow.Closed += (_, _) => _guidedTourCoordinator.RaisePreferencesWindowClosed();
            _guidedTourCoordinator.RaisePreferencesWindowShown();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(PreferencesMenuItem_Click), ex);
        }
    }

