            if (_transcriptFullScreenEnabled)
            {
                // In full-screen: just exit. If avatars were off, turn them on so they
                // become visible. Don't toggle if already on (would hide them).
                SetTranscriptFullScreen(false);
                if (!_settingsSnapshot.ShowAgentAvatars)
                {
                    AgentStatusCard.AvatarsSettingEnabled = true;
                    _settingsManager.Replace(_settingsStore.SaveShowAgentAvatars(true));
                }
                return;
            }
            bool show = ShowAgentAvatarsMenuItem.IsChecked;
            // If panels are hidden (focus mode on), the item appeared unchecked regardless of
            // backing state. Clicking it means "show avatars" → restore panels first, then
            // ensure avatars are on.
            if (_agentsPanelFocusModeEnabled)
            {
                SetAgentsPanelFocusMode(false);
                AgentStatusCard.AvatarsSettingEnabled = true;
                _settingsManager.Replace(_settingsStore.SaveShowAgentAvatars(true));
                return;
            }
            AgentStatusCard.AvatarsSettingEnabled = show;
            _settingsManager.Replace(_settingsStore.SaveShowAgentAvatars(show));
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(ShowAgentAvatarsMenuItem_Click), ex); }
    }

    private void ToggleAgentsPanelFocusMode()
    {
        // Exit full-screen only when the user is about to SHOW panels (focus mode was on = panels hidden).
        if (_transcriptFullScreenEnabled && _agentsPanelFocusModeEnabled)
            SetTranscriptFullScreen(false);
        SetAgentsPanelFocusMode(!_agentsPanelFocusModeEnabled);
    }

    /// <summary>
    /// Hides the agent-cards / inline-panels strip (Shift+F11 toggle).
    /// The prompt stays visible. When the window is in the Normal state the window
    /// is resized to fill the work area height of the current monitor (width unchanged).
    /// Pressing Shift+F11 a second time restores the panels and the original geometry.
    /// </summary>
    private void SetAgentsPanelFocusMode(bool enabled)
    {
        if (_agentsPanelFocusModeEnabled == enabled)
            return;

        _agentsPanelFocusModeEnabled = enabled;

        if (enabled)
        {
            _preFocusModeWindowState = WindowState;
            if (WindowState == WindowState.Normal)
            {
                _preFocusModeHeight = Height;
                _preFocusModeTop    = Top;

                var hwnd   = new System.Windows.Interop.WindowInteropHelper(this).Handle;
                var physWa = NativeMethods.GetWorkAreaForWindow(hwnd);
                var dpi    = System.Windows.Media.VisualTreeHelper.GetDpi(this);

                // Skip height/top change when the window is in any kind of constrained
                // layout (Windows 11 Snap zone, top/bottom split, 4-way grid, etc.).
                // We use actual physical height from GetWindowRect rather than relying
                // on WS_MAXIMIZE, which is unreliable for WindowStyle=None + WindowChrome
                // windows and is cleared when the user drags the divider between snapped
                // windows even though the window remains partially sized.
                if (!NativeMethods.IsHeightConstrained(hwnd, physWa))
                {
                    Top    = physWa.Top    / dpi.DpiScaleY;
                    Height = physWa.Height / dpi.DpiScaleY;
                }
            }
        }
        else
        {
            if (_preFocusModeWindowState == WindowState.Normal && _preFocusModeHeight > 100)
            {
                Top    = _preFocusModeTop;
                Height = _preFocusModeHeight;
            }
        }

        bool wasAtBottom = !ActiveScrollController.IsUserScrolledAway;
        ApplyViewMode();

        // Re-anchor transcript after layout settles so revealing / hiding the
        // status panel doesn't leave a gap when the user was already at the bottom.
        if (wasAtBottom)
            Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded,
                (Action)(() => ActiveScrollController.ScrollToBottom()));
    }

    private void ShowFullScreenPrompt()
    {
        _fullScreenPromptVisible = true;
        _guidedTourCoordinator.RaiseFullScreenPromptPeek(this);
        if (PromptBorder is not null)
            PromptBorder.Visibility = Visibility.Visible;
