    // ── Panel docking ──────────────────────────────────────────────────────────

    private void UpdateMainGridSideMargins()
    {
        bool hasLeft  = LeftZoneColumn.Width.Value  > 0 || Left2ZoneColumn.Width.Value  > 0 || Left3ZoneColumn.Width.Value  > 0 || Left4ZoneColumn.Width.Value  > 0 || Left5ZoneColumn.Width.Value  > 0 || Left6ZoneColumn.Width.Value  > 0 || Left7ZoneColumn.Width.Value > 0;
        bool hasRight = RightZoneColumn.Width.Value > 0 || Right2ZoneColumn.Width.Value > 0 || Right3ZoneColumn.Width.Value > 0 || Right4ZoneColumn.Width.Value > 0 || Right5ZoneColumn.Width.Value > 0 || Right6ZoneColumn.Width.Value > 0 || Right7ZoneColumn.Width.Value > 0;
        var current = MainGrid.Margin;
        MainGrid.Margin = new System.Windows.Thickness(
            hasLeft  ? 4 : 12,
            current.Top,
            hasRight ? 4 : 14,
            current.Bottom);
    }

    private void WireGripStripHandlers()
    {
        var dockable = new[]
        {
            (Border: TasksPanelBorder,         PanelId: "tasks"),
            (Border: ApprovalPanelBorder,      PanelId: "approvals"),
            (Border: NotesPanelBorder,         PanelId: "notes"),
            (Border: CodeHealthPanelBorder,    PanelId: "maintenance"),
            (Border: InboxPanelBorder,         PanelId: "inbox"),
            (Border: LoopPanelBorder,          PanelId: "loop"),
            (Border: PlansPanelBorder,         PanelId: "plans"),
        };

        foreach (var (border, panelId) in dockable)
        {
            var id = panelId;
            border.GripStripClicked += (sender, e) =>
            {
                if (_dockingService is null) return;
                try
                {
                    var mousePos    = System.Windows.Input.Mouse.GetPosition(this);
                    var screenPoint = PointToScreen(mousePos);
                    SquadDashTrace.Write(TraceCategory.Docking,
                        $"GripStrip.OpenDockingMap: panel={id} " +
                        $"mouseLogical=({mousePos.X:F0},{mousePos.Y:F0}) " +
                        $"screenPhys=({screenPoint.X:F0},{screenPoint.Y:F0}) " +
                        $"windowState={WindowState} Left={Left:F0} Top={Top:F0} " +
                        $"ActualW={ActualWidth:F0} ActualH={ActualHeight:F0}");
                    var visibleIds  = dockable
                        .Where(d => d.Border.Visibility == Visibility.Visible)
                        .Select(d => d.PanelId)
                        .ToHashSet(StringComparer.OrdinalIgnoreCase);
                    if (_dockingRecorder is not null && !_dockingRecorder.IsIdle)
                    {
                        var layoutData = _dockingService.GetCurrentLayoutData(visibleIds);
                        var slotButtons = SquadDash.PanelDocking.DockingLayoutEngine.BuildSlotButtons(id, layoutData);
                        _dockingRecorder.OnSlotButtonsBuilt(id, slotButtons, layoutData);
                    }
                    var viewModel   = SquadDash.PanelDocking.DockingMapBuilder.BuildDockingMap(
                        id, _dockingService.CurrentLayout, visibleIds);
                    var mapViolations = SquadDash.PanelDocking.DockingMapBuilder.FindAdjacentThinViolations(viewModel.Slots);
                    foreach (var v in mapViolations)
                        SquadDashTrace.Write(TraceCategory.Docking, $"[DockingMap violation] panel={id}: {v}");
                    Brush? hoverBrush = null;
                    if (Application.Current.Resources["ActivePanelSurface"] is SolidColorBrush accentBrush)
                    {
                        var c = accentBrush.Color;
                        hoverBrush = new SolidColorBrush(Color.FromArgb(128, c.R, c.G, c.B));
                    }
                    var mapWindow = new SquadDash.PanelDocking.DockingMapWindow(
                        viewModel,
                        _dockingService,
                        _currentWorkspace?.FolderPath ?? string.Empty,
                        Application.Current.Resources,
                        hoverBrush);
                    mapWindow.Owner = this;
                    mapWindow.Closed += (_, _) => UpdateMainGridSideMargins();
                    mapWindow.ShowAtScreenPoint(screenPoint);
                }
                catch (Exception ex) { HandleUiCallbackException("GripStrip.OpenDockingMap", ex); }
            };
        }
    }

    /// <summary>
    /// Attaches a custom drag handler to Right2ZoneSplitter so that its resize direction
    /// matches user expectation for an outermost-right zone:
    ///   drag RIGHT → Right2Zone expands (takes space from Right zone or the star column)
    ///   drag LEFT  → Right2Zone shrinks (gives space back)
    ///
    /// The default WPF GridSplitter PreviousAndNext behaviour is inverted for Right2:
    ///   drag RIGHT → Previous (RightZone, col 6) grows, Next (Right2Zone, col 8) shrinks
    ///   drag LEFT  → Previous shrinks — but when Right zone is collapsed (width=0) this is
    ///                blocked, so Right2 can never expand via the standard handler.
    /// This override negates the delta and redirects the donor column appropriately.
    /// </summary>
    private void WireRight2ZoneSplitterDrag()
    {
        double dragStartX     = 0;
        double right2Start    = 0;
        double rightStart     = 0;
        bool   isDragging     = false;

        Right2ZoneSplitter.PreviewMouseLeftButtonDown += (_, e) =>
        {
            if (Right2ZoneSplitter.Visibility != Visibility.Visible) return;
            dragStartX  = e.GetPosition(ContentZoneGrid).X;
            right2Start = Right2ZoneColumn.Width.IsAbsolute  ? Right2ZoneColumn.Width.Value  : 0;
            rightStart  = RightZoneColumn.Width.IsAbsolute   ? RightZoneColumn.Width.Value   : 0;
            isDragging  = true;
            Right2ZoneSplitter.CaptureMouse();
            e.Handled = true;   // prevent GridSplitter's built-in (wrong-direction) handler
        };

        Right2ZoneSplitter.MouseMove += (_, e) =>
        {
            if (!isDragging || e.LeftButton != System.Windows.Input.MouseButtonState.Pressed) return;

            double dx             = e.GetPosition(ContentZoneGrid).X - dragStartX;
            // dx > 0 = dragged right → splitter moves right → Right2 (rightmost col) shrinks
            double newRight2Width = Math.Max(0, right2Start - dx);

            if (rightStart > 0)
            {
                // Right zone is active: exchange space between Right and Right2.
                double total  = right2Start + rightStart;
                newRight2Width = Math.Min(total, newRight2Width);
                RightZoneColumn.Width = new GridLength(total - newRight2Width);
            }
            // When Right zone is collapsed the star column (*) auto-adjusts; no explicit set needed.

            Right2ZoneColumn.Width = new GridLength(newRight2Width);
        };

        Right2ZoneSplitter.MouseLeftButtonUp += (_, e) =>
        {
            if (!isDragging) return;
            isDragging = false;
            Right2ZoneSplitter.ReleaseMouseCapture();
        };

        Right2ZoneSplitter.LostMouseCapture += (_, _) => { isDragging = false; };
    }

    /// <summary>
    /// Attaches a custom drag handler to Right3ZoneSplitter so that its resize direction
    /// matches user expectation for an outermost-right zone:
    ///   drag RIGHT → Right3Zone expands (takes space from Right2 zone or the star column)
