    private void ShowCommitActivityGraphWindow()
    {
        if (_commitActivityGraphWindow is null)
        {
            _commitStatService ??= new CommitStatService(_workspacePaths.ApplicationRoot);
            var isDark = string.Equals(_activeThemeName, "Dark", StringComparison.OrdinalIgnoreCase);
            _commitActivityGraphWindow = new CommitActivityGraphWindow(
                _commitStatService,
                _approvalItems,
                isDark,
                workspaceFolderPath: _workspacePaths.ApplicationRoot,
                workspacePaths:      _workspacePaths,
                getFeatureGroups:    () => (_featureGroupStore?.Load() ?? FeatureGroupStore.Defaults.ToList()).AsReadOnly(),
                workspaceStateDirectory: _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace!.FolderPath),
                onCategoriesAssigned: assignments => Dispatcher.Invoke(() => ApplyCommitCategories(assignments)),
                onCategoriesMerged:   merges      => Dispatcher.Invoke(() => ApplyFeatureCategoryMerges(merges)),
                settingsStore:        _settingsStore);
            if (CanShowOwnedWindow())
                _commitActivityGraphWindow.Owner = this;
            _commitActivityGraphWindow.Closed += (_, _) =>
            {
                _commitActivityGraphWindow = null;
                if (ToolsCommitHistoryMenuItem is not null)
                    ToolsCommitHistoryMenuItem.IsChecked = false;
            };
            _commitActivityGraphWindow.Show();
            if (ToolsCommitHistoryMenuItem is not null)
                ToolsCommitHistoryMenuItem.IsChecked = true;
        }
        else
        {
            _commitActivityGraphWindow.Activate();
        }
    }

