    private bool AppendAgentReport(string agentLabel, string header, string body)
    {
        if (_currentWorkspace is null)
        {
            AppendLine(header + Environment.NewLine + Environment.NewLine + body, null);
            return true;
        }

        string reportPath;
        try
        {
            var stateDir    = _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace.FolderPath);
            var reportsDir  = AgentReportStore.GetReportsDir(stateDir);
            reportPath      = AgentReportStore.Store(reportsDir, agentLabel, header, body, DateTimeOffset.UtcNow);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Agents", $"AppendAgentReport failed agent={agentLabel} error={ex.Message}");
            return false;
        }

        var attached = _conversationManager.AppendAgentReportToCurrentOrLastTurn(agentLabel, reportPath);
        SquadDashTrace.Write(
            "Agents",
            $"AppendAgentReport stored agent={agentLabel} path={reportPath} attached={attached}");
        AppendAgentReportButton(agentLabel, reportPath);
        return true;
    }

    private void ApplyFeatureCategoryMerges(IReadOnlyList<(string Source, string Target)> merges)
    {
        if (_approvalStore is null || _featureGroupStore is null || _currentWorkspace is null)
            throw new InvalidOperationException("No active workspace category store is available.");

        var mergeMap = merges
            .GroupBy(merge => merge.Source, StringComparer.OrdinalIgnoreCase)
            .ToDictionary(group => group.Key, group => group.Last().Target, StringComparer.OrdinalIgnoreCase);

        string ResolveTarget(string category)
        {
            var visited = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            var current = category;
            while (mergeMap.TryGetValue(current, out var next) && visited.Add(current))
                current = next;
            if (mergeMap.ContainsKey(current) && !visited.Add(current))
                throw new InvalidOperationException($"Category merge cycle detected at '{current}'.");
            return current;
        }

        for (var index = 0; index < _approvalItems.Count; index++)
        {
            var category = _approvalItems[index].FeatureGroup;
            if (category is null || !mergeMap.ContainsKey(category)) continue;
            _approvalItems[index] = _approvalItems[index] with { FeatureGroup = ResolveTarget(category) };
        }
        _approvalStore.Save(_approvalItems);

        var sourceNames = mergeMap.Keys.ToHashSet(StringComparer.OrdinalIgnoreCase);
        var groups = _featureGroupStore.Load()
            .Where(group => !sourceNames.Contains(group))
            .ToList();
        foreach (var target in mergeMap.Values.Select(ResolveTarget).Distinct(StringComparer.OrdinalIgnoreCase))
        {
            if (!groups.Contains(target, StringComparer.OrdinalIgnoreCase))
                groups.Add(target);
        }
        _featureGroupStore.Save(groups);

        var stateDirectory = _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace.FolderPath);
        var cache = new CommitCategoryCache(stateDirectory);
        var resolvedMerges = mergeMap.Select(merge => (merge.Key, ResolveTarget(merge.Key))).ToList();
        cache.MergeGroups(resolvedMerges);
        cache.Save();

        RefreshFeatureCategoryViewsFromStore();
    }

    private void RefreshFeatureCategoryViewsFromStore()
    {
        if (_approvalStore is null) return;
        _approvalItems = _approvalStore.Load();
        _approvalPanel?.ReplaceAllItems(_approvalItems);
        _commitActivityGraphWindow?.ReplaceItems(_approvalItems);
    }

    private bool HasVisibleOrPersistedAgentReport(TranscriptThreadState thread)
    {
        if (_currentWorkspace is null)
            return false;

        var labels = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        AddReportLabelCandidate(labels, thread.Title);
        AddReportLabelCandidate(labels, thread.AgentDisplayName);
        AddReportLabelCandidate(labels, BackgroundTaskPresenter.BuildBackgroundAgentLabel(thread));

        foreach (var turn in _conversationManager.ConversationState.Turns)
            if (turn.AgentReports is { Count: > 0 })
                foreach (var report in turn.AgentReports)
                    if (labels.Contains(report.AgentLabel) && File.Exists(report.ReportPath))
                        return true;

        var stateDir   = _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace.FolderPath);
        var reportsDir = AgentReportStore.GetReportsDir(stateDir);
        if (!Directory.Exists(reportsDir))
            return false;

        foreach (var file in Directory.EnumerateFiles(reportsDir, "*.md"))
        {
            var agentLabel = TryReadAgentLabelFromReport(file) ?? Path.GetFileNameWithoutExtension(file);
            if (labels.Contains(agentLabel))
                return true;
        }

        return false;
    }

    private static void AddReportLabelCandidate(HashSet<string> labels, string? label)
    {
        if (!string.IsNullOrWhiteSpace(label))
            labels.Add(label.Trim());
    }

    private bool AppendAgentReportButton(string agentLabel, string reportPath, TranscriptTurnView? view = null)
    {
        if (!File.Exists(reportPath))
        {
            SquadDashTrace.Write(
                "Agents",
                $"AppendAgentReportButton skipped missing report agent={agentLabel} path={reportPath}");
            return false;
        }

        var capturedPath  = reportPath;
        var capturedLabel = agentLabel;

        var fileTime = File.GetCreationTime(reportPath);
        var relTime = StatusTimingPresentation.FormatRelativeTimestamp(new DateTimeOffset(fileTime));

        var button = new Button
        {
            Content   = $"📋 {(AgentReportStore.IsKnownAgent(agentLabel) ? $"{agentLabel}'s" : agentLabel)} report — {relTime}",
            ToolTip   = "Click to open the full agent report",
            Cursor    = Cursors.Hand,
            Margin    = new Thickness(0, 0, 0, 0),
        };
        button.SetResourceReference(Control.StyleProperty, "TranscriptActionButtonStyle");
        button.Click += (_, _) =>
        {
            if (File.Exists(capturedPath))
                MarkdownDocumentWindow.Show(
                    CanShowOwnedWindow() ? this : null,
                    AgentReportStore.FormatReportTitle(capturedLabel),
                    capturedPath);
            else
                MessageBox.Show(
                    "This report is no longer available.",
                    "Report not found",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);
        };

        var para = new Paragraph { Margin = new Thickness(0, 4, 0, 6) };
        para.Inlines.Add(new InlineUIContainer(button) { BaselineAlignment = BaselineAlignment.Center });

        // Scope the link to the owning turn's NarrativeSection so it stays
        // with the turn both during live streaming and on transcript reload.
        var targetView = view ?? CoordinatorThread.CurrentTurn;
        if (targetView is not null)
            targetView.NarrativeSection.Blocks.Add(para);
        else
            CoordinatorThread.Document.Blocks.Add(para);
        return true;
    }

    /// <summary>
    /// Renders buttons for any agent-report <c>.md</c> files in <paramref name="reportsDir"/>
    /// that are not already referenced by a persisted coordinator turn.  This recovers buttons
    /// that were lost because the app closed before the active turn completed and was saved.
    /// Must be called on the UI thread after the conversation transcript has been rendered.
    /// </summary>
    private void RenderOrphanedAgentReports(string reportsDir)
    {
        if (!Directory.Exists(reportsDir))
            return;

        var referencedPaths = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        foreach (var turn in _conversationManager.ConversationState.Turns)
            if (turn.AgentReports is { Count: > 0 })
                foreach (var r in turn.AgentReports)
                    referencedPaths.Add(r.ReportPath);

        // Only recover reports newer than the oldest persisted turn.
        // Older reports belonged to turns that were trimmed by the 200-turn cap —
        // they are not crash-orphaned and should not re-appear as buttons.
        var oldestTurnTime = _conversationManager.ConversationState.Turns.Count > 0
            ? _conversationManager.ConversationState.Turns[0].Timestamp
            : DateTimeOffset.MaxValue;

        var renderedCount = 0;
        foreach (var file in Directory.EnumerateFiles(reportsDir, "*.md"))
        {
            if (referencedPaths.Contains(file))
                continue;
            var fileTime = new DateTimeOffset(File.GetCreationTimeUtc(file), TimeSpan.Zero);
            if (fileTime < oldestTurnTime)
                continue;
            var agentLabel = TryReadAgentLabelFromReport(file) ?? Path.GetFileNameWithoutExtension(file);
            AppendAgentReportButton(agentLabel, file);
            renderedCount++;
        }

        if (renderedCount > 0)
            SquadDashTrace.Write("Agents", $"RenderOrphanedAgentReports rendered={renderedCount}");
    }

    private static string? TryReadAgentLabelFromReport(string reportPath)
    {
        try
        {
            var firstLine = File.ReadLines(reportPath).FirstOrDefault();
            const string possessiveSuffix = "'s Report";
            const string plainSuffix      = " Report";
            if (firstLine?.StartsWith("# ") == true)
            {
                var title = firstLine[2..];
                if (title.EndsWith(possessiveSuffix))
                    return title[..^possessiveSuffix.Length];
                if (title.EndsWith(plainSuffix))
                    return title[..^plainSuffix.Length];
            }
        }
        catch { /* best effort */ }
        return null;
    }

