    private sealed record QuickReplyRoutingDecision(
        string? RoutingInstruction,
        string? ContinuationAgentLabel,
        string? RouteMode,
        string? TargetAgentHandle,
        string? Reason);

    private QuickReplyRoutingDecision BuildQuickReplyRouting(TranscriptResponseEntry entry, QuickReplyOptionMetadata option)
    {
        var trimmedOption = option.Label.Trim();
        if (string.IsNullOrWhiteSpace(trimmedOption))
            return new QuickReplyRoutingDecision(null, null, null, null, null);

        var routeMode = NormalizeQuickReplyRouteMode(option.RouteMode);
        var reason = string.IsNullOrWhiteSpace(option.Reason)
            ? null
            : option.Reason.Trim();

        if (string.Equals(routeMode, "continue_current_agent", StringComparison.OrdinalIgnoreCase))
        {
            var continuationThread = TryResolveQuickReplyContinuationThread(entry);
            var continuationHandle = GetQuickReplyAgentHandle(continuationThread);
            if (continuationThread is null || string.IsNullOrWhiteSpace(continuationHandle))
                return new QuickReplyRoutingDecision(null, null, routeMode, null, reason);

            var continuationLabel = ResolveQuickReplyAgentLabel(continuationThread);
            var continuationInstruction = "Route this quick-reply follow-up to @" + continuationHandle.Trim() +
                                          ". Have that agent continue from their most recent work on this task, follow their charter, and carry out the user's selected next step: " +
                                          trimmedOption;
            return new QuickReplyRoutingDecision(continuationInstruction, continuationLabel, routeMode, continuationHandle, reason);
        }

        if (string.Equals(routeMode, "start_named_agent", StringComparison.OrdinalIgnoreCase))
        {
            var targetHandle = NormalizeQuickReplyAgentHandle(option.TargetAgent);
            if (!string.IsNullOrWhiteSpace(targetHandle))
            {
                var targetLabel = ResolveQuickReplyAgentLabel(targetHandle);
                var targetInstruction = "Route this quick-reply follow-up to @" + targetHandle +
                                        ". This is a new task owned by that specialist according to the quick-reply metadata. Have them follow their charter and carry out the user's selected next step: " +
                                        trimmedOption;
                return new QuickReplyRoutingDecision(targetInstruction, targetLabel, routeMode, targetHandle, reason);
            }
        }

        if (string.Equals(routeMode, "fanout_team", StringComparison.OrdinalIgnoreCase))
        {
            return new QuickReplyRoutingDecision(
                "Treat this quick-reply follow-up as a coordinator-owned multi-agent task. Use `.squad/team.md` and `.squad/routing.md` to delegate the user's selected next step: " + trimmedOption,
                null,
                routeMode,
                null,
                reason);
        }

        if (string.Equals(routeMode, "start_coordinator", StringComparison.OrdinalIgnoreCase))
        {
            return new QuickReplyRoutingDecision(
                "Keep this quick-reply follow-up with the Coordinator. Carry out the user's selected next step directly: " + trimmedOption,
                null,
                routeMode,
                null,
                reason);
        }

        if (string.Equals(routeMode, "done", StringComparison.OrdinalIgnoreCase))
            return new QuickReplyRoutingDecision(null, null, routeMode, null, reason);

        if (string.Equals(routeMode, "draft", StringComparison.OrdinalIgnoreCase))
            return new QuickReplyRoutingDecision(null, null, routeMode, null, reason);

        var targetThread = TryResolveQuickReplyContinuationThread(entry);
        var agentHandle = GetQuickReplyAgentHandle(targetThread);
        if (targetThread is null || string.IsNullOrWhiteSpace(agentHandle))
            return new QuickReplyRoutingDecision(null, null, null, null, reason);

        var agentLabel = ResolveQuickReplyAgentLabel(targetThread);
        var routingInstruction = "Route this quick-reply follow-up to @" + agentHandle.Trim() +
                                 ". Have that agent continue from their most recent work on this task, follow their charter, and carry out the user's selected next step: " +
                                 trimmedOption;
        return new QuickReplyRoutingDecision(routingInstruction, agentLabel, null, agentHandle, reason);
    }

    private PendingQuickReplyLaunchState? CreatePendingQuickReplyLaunch(QuickReplyButtonPayload payload)
    {
        if (!QuickReplyAgentLaunchPolicy.RequiresObservedNamedAgentLaunch(payload.RouteMode, payload.TargetAgentHandle))
            return null;

        var contextDiagnostics = _conversationManager.CapturePromptContextDiagnostics();
        var diagnostics = PromptContextDiagnosticsPresentation.BuildTraceSummary(
            contextDiagnostics,
            DateTimeOffset.UtcNow);
        return new PendingQuickReplyLaunchState(
            payload.RouteMode!.Trim(),
            payload.TargetAgentHandle,
            payload.ContinuationAgentLabel,
            payload.Option.Trim(),
            contextDiagnostics,
            diagnostics,
            _conversationManager.CurrentSessionId);
    }

    private void NotePendingQuickReplyCoordinatorResponse()
    {
        var pendingLaunch = _pendingQuickReplyLaunch;
        if (pendingLaunch is null ||
            pendingLaunch.ExpectedAgentStarted ||
            pendingLaunch.CoordinatorRespondedBeforeLaunch)
        {
            return;
        }

        pendingLaunch.CoordinatorRespondedBeforeLaunch = true;
        SquadDashTrace.Write(
            "Routing",
            $"Named-agent quick reply produced coordinator response text before launch agent={pendingLaunch.ExpectedAgentHandle ?? "(unknown)"} option='{pendingLaunch.SelectedOption}' sessionAtClick={pendingLaunch.SessionIdAtClick ?? "(none)"} {pendingLaunch.ContextDiagnosticsSummary}");
    }

    private void NotePendingQuickReplySubagentStarted(SquadSdkEvent evt)
    {
        var pendingLaunch = _pendingQuickReplyLaunch;
        if (pendingLaunch is null || pendingLaunch.ExpectedAgentStarted)
            return;

        if (!QuickReplyAgentLaunchPolicy.MatchesExpectedAgent(
                pendingLaunch.ExpectedAgentHandle,
                pendingLaunch.ExpectedAgentLabel,
                evt))
        {
            // Generic agent launched for a named-agent request — tag thread for honest labeling.
            if (!string.IsNullOrWhiteSpace(pendingLaunch.ExpectedAgentHandle) &&
                !string.IsNullOrWhiteSpace(evt.ToolCallId) &&
                _agentThreadRegistry.ThreadsByToolCallId.TryGetValue(evt.ToolCallId.Trim(), out var mismatchThread))
            {
                mismatchThread.RequestedAgentHandle = pendingLaunch.ExpectedAgentHandle;
                SyncThreadChip(mismatchThread);
                UpdateAgentCardFromThread(mismatchThread);
            }

            return;
        }

        pendingLaunch.ExpectedAgentStarted = true;
        RecordDelegationOutcome(pendingLaunch, succeeded: true);
        SquadDashTrace.Write(
            "Routing",
            $"Named-agent quick reply observed expected launch agent={pendingLaunch.ExpectedAgentHandle ?? "(unknown)"} option='{pendingLaunch.SelectedOption}' sessionAtClick={pendingLaunch.SessionIdAtClick ?? "(none)"} {pendingLaunch.ContextDiagnosticsSummary}");
    }

    private bool HasPendingDirectQuickReplyAgentFollowUp() =>
        _directQuickReplyAgentThreadIds.Count > 0;

    private int RetireDirectQuickReplyHandoffBlockers(string reason)
    {
        if (_directQuickReplyAgentThreadIds.Count == 0)
            return 0;

        var interruptedHandoffs = _directQuickReplyAgentThreadIds.ToArray();
        _directQuickReplyAgentThreadIds.Clear();
        SquadDashTrace.Write(
            "Recovery",
            $"Retired {interruptedHandoffs.Length} direct quick-reply handoff blocker(s) reason={reason} threads={string.Join(",", interruptedHandoffs)}.");
        return interruptedHandoffs.Length;
    }

    private void ReconcileBridgeReset(SquadSdkProcessResetEventArgs reset)
    {
        if (_isClosing || _mainWindowClosingInProgress)
            return;

        if (RetireDirectQuickReplyHandoffBlockers($"bridge-reset:{reset.Reason}") == 0)
            return;

        SyncQueuePanel();
        UpdateRestartStatusPanelVisibility();
        if (_restartPending)
            TryCompletePendingRestart("bridge-reset", emergencySaveBeforeClose: true);
        else if (!_isPromptRunning && _interruptedPromptRecoveryHold is null)
            _ = DrainQueueIfNeededAsync();
    }

    private void TrackDirectQuickReplyAgentThread(TranscriptThreadState thread)
    {
        if (string.IsNullOrWhiteSpace(thread.ThreadId))
            return;

        if (_directQuickReplyAgentThreadIds.Add(thread.ThreadId))
        {
            SquadDashTrace.Write(
                "Routing",
                $"Direct named-agent quick reply is blocking queued dispatch until coordinator follow-up thread={thread.ThreadId} agent={thread.Title ?? "(unknown)"} pending={_directQuickReplyAgentThreadIds.Count}");
        }
    }

    private bool CompleteDirectQuickReplyAgentThread(TranscriptThreadState thread, string reason)
    {
        if (string.IsNullOrWhiteSpace(thread.ThreadId))
            return false;

        var removed = _directQuickReplyAgentThreadIds.Remove(thread.ThreadId);
        if (removed)
        {
            SquadDashTrace.Write(
                "Routing",
                $"Direct named-agent quick reply unblocked by {reason} thread={thread.ThreadId} agent={thread.Title ?? "(unknown)"} pending={_directQuickReplyAgentThreadIds.Count}");
        }

        return removed;
    }

    private void EnqueueDirectQuickReplyAgentFollowUp(TranscriptThreadState thread)
    {
        var reportText = !string.IsNullOrWhiteSpace(thread.LastCoordinatorAnnouncedResponse)
            ? thread.LastCoordinatorAnnouncedResponse
            : thread.LatestResponse;
        var prompt = SilentCompletionFollowUpPromptBuilder.Build([
            new SilentCompletionFollowUpReport(
                string.IsNullOrWhiteSpace(thread.Title) ? "Background Agent" : thread.Title,
                string.IsNullOrWhiteSpace(thread.ThreadId) ? null : thread.ThreadId,
                thread.CompletedAt,
                thread.Prompt,
                reportText)
        ]);

        if (string.IsNullOrWhiteSpace(prompt))
            return;

        EnqueuePrompt(prompt, isSystemInjected: true);
        SquadDashTrace.Write(
            "PromptHealth",
            $"DirectQuickReplyCompletion: queued coordinator follow-up thread={thread.ThreadId} agent={thread.Title ?? "(unknown)"}");
    }

    private void MaybeReportPendingQuickReplyLaunchFailure(PendingQuickReplyLaunchState? pendingLaunch)
    {
        if (pendingLaunch is null || pendingLaunch.ExpectedAgentStarted)
            return;

        var message = QuickReplyAgentLaunchPolicy.BuildLaunchFailureMessage(
            pendingLaunch.SelectedOption,
            pendingLaunch.ExpectedAgentLabel,
            pendingLaunch.ExpectedAgentHandle);
        RecordDelegationOutcome(pendingLaunch, succeeded: false);
        SquadDashTrace.Write(
            "Routing",
            $"Named-agent quick reply failed to launch expected agent={pendingLaunch.ExpectedAgentHandle ?? "(unknown)"} option='{pendingLaunch.SelectedOption}' sessionAtClick={pendingLaunch.SessionIdAtClick ?? "(none)"} {pendingLaunch.ContextDiagnosticsSummary} detail=\"{message}\"");
    }

    private void RecordDelegationOutcome(PendingQuickReplyLaunchState pendingLaunch, bool succeeded)
    {
        var riskBand = PromptContextDiagnosticsPresentation.GetRiskBand(
            pendingLaunch.ContextDiagnostics,
            DateTimeOffset.UtcNow);
        var totalTurns = pendingLaunch.ContextDiagnostics.CoordinatorTurnCount +
                         pendingLaunch.ContextDiagnostics.AgentThreadTurnCount;
        _recentDelegationOutcomes.Enqueue(
            new DelegationOutcomeTelemetry(
                succeeded,
                riskBand,
                pendingLaunch.ContextDiagnostics.TotalChars,
                totalTurns,
                pendingLaunch.SelectedOption,
                pendingLaunch.ExpectedAgentHandle));

        while (_recentDelegationOutcomes.Count > DelegationOutcomeRollupWindow)
            _recentDelegationOutcomes.Dequeue();

        SquadDashTrace.Write(
            "Routing",
            BuildDelegationOutcomeRollupTrace(succeeded, riskBand, pendingLaunch.SelectedOption, pendingLaunch.ExpectedAgentHandle));
    }

    private string BuildDelegationOutcomeRollupTrace(
        bool latestSucceeded,
        string latestRiskBand,
        string selectedOption,
        string? expectedAgentHandle)
    {
        var outcomes = _recentDelegationOutcomes.ToArray();
        var failures = outcomes.Count(outcome => !outcome.Succeeded);
        var successes = outcomes.Length - failures;
        var failureRate = outcomes.Length == 0
            ? 0
            : (int)Math.Round(failures * 100d / outcomes.Length, MidpointRounding.AwayFromZero);
        var highRiskFailures = outcomes.Count(outcome => !outcome.Succeeded && string.Equals(outcome.RiskBand, "high", StringComparison.OrdinalIgnoreCase));
        var mediumOrHighFailures = outcomes.Count(outcome =>
            !outcome.Succeeded &&
            !string.Equals(outcome.RiskBand, "low", StringComparison.OrdinalIgnoreCase));
        var clusterHint =
            failures >= 3 && highRiskFailures >= 2
                ? "high-risk-failure-cluster"
                : failures >= 3 && mediumOrHighFailures >= 2
                    ? "possible-session-growth-cluster"
                    : failures >= 2 && successes == 0
                        ? "back-to-back-failures"
                        : "none";

        return
            $"Delegation outcome rollup latest={(latestSucceeded ? "success" : "failure")} latestRisk={latestRiskBand} " +
            $"agent={expectedAgentHandle ?? "(unknown)"} option='{selectedOption}' recent={outcomes.Length} successes={successes} failures={failures} " +
            $"failureRatePct={failureRate} highRiskFailures={highRiskFailures} mediumOrHighFailures={mediumOrHighFailures} clusterHint={clusterHint}";
    }

    private TranscriptThreadState? TryResolveQuickReplyContinuationThread(TranscriptResponseEntry entry)
    {
        var ownerThread = entry.Turn.OwnerThread;
        if (CanRouteQuickReplyToAgent(ownerThread))
            return ownerThread;

        if (ownerThread.Kind != TranscriptThreadKind.Coordinator)
            return null;

        var now = DateTimeOffset.Now;
        var candidates = _agentThreadRegistry.ThreadOrder
            .Where(CanRouteQuickReplyToAgent)
            .Select(thread => new
            {
                Thread = thread,
                ActivityAt = thread.LastObservedActivityAt ?? thread.CompletedAt
            })
            .Where(candidate => candidate.ActivityAt is { } activityAt &&
                                now - activityAt <= MarkdownDocumentRenderer.QuickReplyAgentContinuationWindow)
            .OrderByDescending(candidate => candidate.ActivityAt)
            .ToArray();

        if (candidates.Length != 1)
            return null;

        return candidates[0].Thread;
    }

    private static bool CanRouteQuickReplyToAgent(TranscriptThreadState? thread)
    {
        if (thread is null || thread.Kind != TranscriptThreadKind.Agent || thread.IsPlaceholderThread)
            return false;

        return !string.IsNullOrWhiteSpace(thread.AgentName) ||
               !string.IsNullOrWhiteSpace(thread.AgentId);
    }

    private static string? GetQuickReplyAgentHandle(TranscriptThreadState? thread)
    {
        if (thread is null)
            return null;

        if (!string.IsNullOrWhiteSpace(thread.AgentName))
            return thread.AgentName.Trim();
        if (!string.IsNullOrWhiteSpace(thread.AgentId))
            return thread.AgentId.Trim();

        return null;
    }

    private static string? ResolveQuickReplyAgentLabel(TranscriptThreadState? thread)
    {
        if (thread is null)
            return null;

        if (!string.IsNullOrWhiteSpace(thread.AgentDisplayName))
            return thread.AgentDisplayName.Trim();
        if (!string.IsNullOrWhiteSpace(thread.AgentName))
            return AgentThreadRegistry.HumanizeAgentName(thread.AgentName);
        if (!string.IsNullOrWhiteSpace(thread.AgentId))
            return AgentThreadRegistry.HumanizeAgentName(thread.AgentId);

        return null;
    }

    private string? ResolveQuickReplyAgentLabel(string? handle)
    {
        var normalizedHandle = NormalizeQuickReplyAgentHandle(handle);
        if (string.IsNullOrWhiteSpace(normalizedHandle))
            return null;

        var matchingThread = _agentThreadRegistry.ThreadOrder.FirstOrDefault(thread =>
            string.Equals(NormalizeQuickReplyAgentHandle(thread.AgentName), normalizedHandle, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(NormalizeQuickReplyAgentHandle(thread.AgentId), normalizedHandle, StringComparison.OrdinalIgnoreCase));
        var threadLabel = ResolveQuickReplyAgentLabel(matchingThread);
        if (!string.IsNullOrWhiteSpace(threadLabel))
            return threadLabel;

        if (_currentWorkspace is not null)
        {
            var rosterMatch = _teamRosterLoader.Load(_currentWorkspace.FolderPath)
                .FirstOrDefault(member => string.Equals(
                    NormalizeQuickReplyAgentHandle(DeriveQuickReplyAgentHandle(member.Name, member.CharterPath)),
                    normalizedHandle,
                    StringComparison.OrdinalIgnoreCase));
            if (rosterMatch is not null)
                return rosterMatch.Name;
        }

        return AgentThreadRegistry.HumanizeAgentName(normalizedHandle);
    }

    private static string? NormalizeQuickReplyRouteMode(string? routeMode)
    {
        if (string.IsNullOrWhiteSpace(routeMode))
            return null;

        return routeMode.Trim().ToLowerInvariant();
    }

    private static string? NormalizeQuickReplyAgentHandle(string? handle)
    {
        if (string.IsNullOrWhiteSpace(handle))
            return null;

        return handle.Trim().TrimStart('@').ToLowerInvariant();
    }

    private static string DeriveQuickReplyAgentHandle(string? name, string? charterPath)
    {
        if (!string.IsNullOrWhiteSpace(charterPath))
        {
            var normalized = charterPath.Replace('\\', '/');
            const string marker = "agents/";
            var markerIndex = normalized.IndexOf(marker, StringComparison.OrdinalIgnoreCase);
            if (markerIndex >= 0)
            {
                var afterMarker = normalized[(markerIndex + marker.Length)..];
                var slashIndex = afterMarker.IndexOf('/');
                if (slashIndex > 0)
                    return afterMarker[..slashIndex].Trim().ToLowerInvariant();
            }
        }

        if (string.IsNullOrWhiteSpace(name))
            return string.Empty;

        var builder = new StringBuilder();
        var previousWasSeparator = false;
        foreach (var ch in name.Trim().ToLowerInvariant())
        {
            if (char.IsLetterOrDigit(ch))
            {
                builder.Append(ch);
                previousWasSeparator = false;
                continue;
            }

            if (previousWasSeparator)
                continue;

            builder.Append('-');
            previousWasSeparator = true;
        }

        return builder.ToString().Trim('-');
    }

    private bool IsRoutingIssueQuickReply(QuickReplyButtonPayload payload)
    {
        return _routingIssueQuickReplyEntry is not null &&
               ReferenceEquals(payload.Entry, _routingIssueQuickReplyEntry);
    }

    private bool IsTeamRootPollutionQuickReply(QuickReplyButtonPayload payload)
    {
        return _teamRootPollutionQuickReplyEntry is not null &&
               ReferenceEquals(payload.Entry, _teamRootPollutionQuickReplyEntry);
    }

    private void HandleRoutingIgnoreQuickReply(TranscriptResponseEntry entry)
    {
        _pec.DisableQuickReplies(entry);
        ClearActiveQuickReplyState(entry);
        _routingIssueQuickReplyEntry = null;

        if (!string.IsNullOrWhiteSpace(_currentRoutingAssessment?.IssueFingerprint))
            SetIgnoredRoutingIssueFingerprintForCurrentWorkspace(_currentRoutingAssessment.IssueFingerprint);

        ShowSystemTranscriptEntry(RoutingIssueWorkflow.BuildIgnoredMessage());
    }

    private async Task HandleRoutingRepairQuickReplyAsync(TranscriptResponseEntry entry)
    {
        if (!CanRunRoutingRepairPrompt())
        {
            ShowSystemTranscriptEntry(RoutingIssueWorkflow.BuildRepairBlockedMessage());
            return;
        }

        _pec.DisableQuickReplies(entry);
        ClearActiveQuickReplyState(entry);
        _routingIssueQuickReplyEntry = null;

        var backupPath = _currentWorkspace is null
            ? null
            : _routingDocumentService.BackupExistingRoutingFile(_currentWorkspace.FolderPath);
        ShowSystemTranscriptEntry(RoutingIssueWorkflow.BuildRepairQueuedMessage(backupPath));
        _pendingSupplementalPromptInstruction = RoutingIssueWorkflow.BuildRepairInstruction();
        _pendingRoutingRepairRecheck = true;

        await _pec.ExecutePromptAsync(string.Empty, addToHistory: false, clearPromptBox: false);
    }

    private async Task HandleResendLastPromptAsync()
    {
        var lastPrompt = _conversationManager.PromptHistory.LastOrDefault();
        if (string.IsNullOrWhiteSpace(lastPrompt))
        {
            AppendLine("[info] No previous prompt found to resend.", null);
            return;
        }

        SquadDashTrace.Write("UI", $"Interrupt recovery: resending last prompt ({lastPrompt.Length} chars).");
        ResumeQueueAfterStoppedWorkResponseIfNeeded();
        ResetQueuePausedState();
        await _pec.ExecutePromptAsync(lastPrompt, addToHistory: false, clearPromptBox: false);
    }

    private InterruptedPromptRecoveryStore? GetInterruptedPromptRecoveryStore()
    {
        if (_currentWorkspace is null)
            return null;

        var stateDirectory = _conversationManager.ConversationStore
            .GetWorkspaceStateDirectory(_currentWorkspace.FolderPath);
        return new InterruptedPromptRecoveryStore(stateDirectory);
    }

    private InterruptedPromptRecoveryState? LoadInterruptedPromptRecovery() =>
        GetInterruptedPromptRecoveryStore()?.Load();

    private void HandleInterruptedPromptRecoverySaved(InterruptedPromptRecoveryState recovery)
    {
        if (!Dispatcher.CheckAccess())
        {
            Dispatcher.BeginInvoke(new Action(() => HandleInterruptedPromptRecoverySaved(recovery)));
            return;
        }

        EnterInterruptedPromptRecoveryHold(recovery);
        _ = PrepareInterruptedPromptRecoverySurfaceAsync(recovery, restoredAfterRestart: false);
    }

    private async Task PrepareInterruptedPromptRecoverySurfaceAsync(
        InterruptedPromptRecoveryState recovery,
        bool restoredAfterRestart)
    {
        try
        {
            var enriched = await EnrichInterruptedPromptRecoveryAsync(recovery);
            var store = GetInterruptedPromptRecoveryStore();
            var current = store?.Load();
            if (current is null || !string.Equals(
                    current.RecoveryId,
                    recovery.RecoveryId,
                    StringComparison.Ordinal))
            {
                return;
            }

            enriched = enriched with {
                FailureCount = current.FailureCount,
                AutomaticContinuationAttempted = current.AutomaticContinuationAttempted
            };
            store!.Save(enriched);
            _interruptedPromptRecoveryHold = enriched;
            _pendingInterruptedPromptRecoveryPresentation = enriched;
            _pendingInterruptedPromptRecoveryRestoredAfterRestart = restoredAfterRestart;
            TryPresentPendingInterruptedPromptRecovery();
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "Recovery",
                $"Could not prepare interrupted recovery surface id={recovery.RecoveryId}: {ex.Message}");
            _pendingInterruptedPromptRecoveryPresentation = recovery;
            _pendingInterruptedPromptRecoveryRestoredAfterRestart = restoredAfterRestart;
            TryPresentPendingInterruptedPromptRecovery();
        }
    }

    private void TryPresentPendingInterruptedPromptRecovery()
    {
        if (_pendingInterruptedPromptRecoveryPresentation is not { } recovery ||
            _isPromptRunning ||
            _queueStateHydrationInProgress ||
            _isClosing ||
            _restartPending)
        {
            return;
        }

        var restoredAfterRestart = _pendingInterruptedPromptRecoveryRestoredAfterRestart;
        _pendingInterruptedPromptRecoveryPresentation = null;
        _pendingInterruptedPromptRecoveryRestoredAfterRestart = false;
        if (InterruptedPromptAutomaticRecoveryPolicy.ShouldAutomaticallyContinue(recovery))
        {
            ShowSystemTranscriptEntry(
                InterruptedPromptRecoveryPresentation.BuildAutomaticRecoveryText(
                    recovery,
                    restoredAfterRestart));
            _pendingAutomaticInterruptedPromptRecovery = recovery;
            TryStartPendingAutomaticInterruptedPromptRecovery();
            return;
        }

        var primaryAction = InterruptedPromptRecoveryPresentation.BuildPrimaryActionLabel(recovery);
        var existingCardRestored = restoredAfterRestart &&
            _lastQuickReplyEntry?.AllowQuickReplies == true &&
            _lastQuickReplyEntry.RawTextBuilder.ToString().Contains(
                $"[{primaryAction}]",
                StringComparison.OrdinalIgnoreCase);
        if (!existingCardRestored)
        {
            ShowSystemTranscriptEntry(
                InterruptedPromptRecoveryPresentation.BuildCardText(
                    recovery,
                    restoredAfterRestart));
        }
        SquadDashTrace.Write(
            "Recovery",
            $"Recovery requires user direction id={recovery.RecoveryId} existingCard={existingCardRestored} action='{primaryAction}' failures={recovery.FailureCount} autoAttempted={recovery.AutomaticContinuationAttempted}");
    }

    private async Task<InterruptedPromptRecoveryState> EnrichInterruptedPromptRecoveryAsync(
        InterruptedPromptRecoveryState recovery)
    {
        if (_currentWorkspace is null)
            return recovery;

        try
        {
            var status = await RunGitAsync(
                _currentWorkspace.FolderPath,
                "status --porcelain --untracked-files=all");
            DecomposeWorktreePolicy.HasOnlyAllowedChanges(
                status,
                Array.Empty<string>(),
                out var userOwnedPaths);
            return recovery with { PendingChangedFileCount = userOwnedPaths.Count };
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "Recovery",
                $"Could not count changed worktree entries for recovery id={recovery.RecoveryId}: {ex.Message}");
            return recovery;
        }
    }

    private void TryStartPendingAutomaticInterruptedPromptRecovery()
    {
        if (_pendingAutomaticInterruptedPromptRecovery is not { } recovery ||
            _isPromptRunning ||
            _queueStateHydrationInProgress ||
            _isClosing ||
            _restartPending)
        {
            return;
        }

        _pendingAutomaticInterruptedPromptRecovery = null;
        _ = ContinueInterruptedPromptAutomaticallyAsync(recovery);
    }

    private async Task ContinueInterruptedPromptAutomaticallyAsync(
        InterruptedPromptRecoveryState recovery)
    {
        var store = GetInterruptedPromptRecoveryStore();
        var current = store?.Load();
        if (current is null || !string.Equals(
                current.RecoveryId,
                recovery.RecoveryId,
                StringComparison.Ordinal))
        {
            return;
        }

        var attempted = recovery with { AutomaticContinuationAttempted = true };
        store!.Save(attempted);
        _interruptedPromptRecoveryHold = attempted;
        try
        {
            SquadDashTrace.Write(
                "Recovery",
                $"Starting automatic interrupted prompt recovery id={attempted.RecoveryId} failures={attempted.FailureCount}.");
            await ContinueInterruptedPromptAsync(attempted, automatic: true);
        }
        catch (Exception ex)
        {
            EnterInterruptedPromptRecoveryHold(attempted);
            SquadDashTrace.Write(
                "Recovery",
                $"Automatic interrupted prompt recovery could not start id={attempted.RecoveryId}: {ex}");
            ShowSystemTranscriptEntry(
                $"Automatic recovery could not continue safely: {ex.Message}\n\n" +
                InterruptedPromptRecoveryPresentation.BuildCardText(attempted));
        }
    }

    private void EnterInterruptedPromptRecoveryHold(InterruptedPromptRecoveryState recovery)
    {
        _interruptedPromptRecoveryHold = recovery;
        ClearRuntimeIssue();

        // The coordinator request is terminal even when child-agent work can continue briefly.
        // Keep the durable recovery checkpoint as the only handoff gate; the recovery envelope
        // retains the exact child thread IDs so their later output can still be reconciled.
        RetireDirectQuickReplyHandoffBlockers("recoverable-prompt-timeout");

        if (IsNativeLoopRunning)
        {
            _loopStoppedForInterruptedPromptRecovery = true;
            _loopInterruptedByQueue = true;
            var lastCompletedIteration = _conversationManager.ConversationState.ActiveLoopExecution?.LastCompletedIteration
                                         ?? Math.Max(0, _loopCurrentIteration - 1);
            _loopQueuedResumeFromIteration = Math.Max(_loopQueuedResumeFromIteration, lastCompletedIteration);
            _loopController.RequestRecoveryHold();
            _loopFollowUpTcs?.TrySetResult(false);
            AppendLoopOutputLine(
                InterruptedPromptAutomaticRecoveryPolicy.ShouldAutomaticallyContinue(recovery)
                    ? "↻ Loop held briefly — SquadDash is automatically recovering interrupted work."
                    : "⏸ Loop held — interrupted work requires a recovery choice in the transcript.",
                LoopLifecycleBrush);
        }
        else if (IsLoopRunning)
        {
            _ = _bridge.StopLoopAsync();
        }

        SquadDashTrace.Write(
            "Recovery",
            $"Execution hold entered id={recovery.RecoveryId} queueCount={_promptQueue.Count} loopRunning={IsLoopRunning} loopIteration={_loopCurrentIteration}.");
        SyncQueuePanel();
        SyncLoopPanel();
    }

    private void ReleaseInterruptedPromptRecoveryHold(string reason) =>
        ReleaseInterruptedPromptRecoveryHold(reason, resumePendingWork: true);

    private void ReleaseInterruptedPromptRecoveryHold(string reason, bool resumePendingWork)
    {
        _pendingInterruptedPromptRecoveryPresentation = null;
        _pendingInterruptedPromptRecoveryRestoredAfterRestart = false;
        _pendingAutomaticInterruptedPromptRecovery = null;
        if (_interruptedPromptRecoveryHold is null)
            return;

        var released = _interruptedPromptRecoveryHold;
        _interruptedPromptRecoveryHold = null;
        SquadDashTrace.Write(
            "Recovery",
            $"Execution hold released reason={reason} id={released.RecoveryId} queueCount={_promptQueue.Count} loopQueued={_loopQueued}.");
        SyncQueuePanel();
        SyncLoopPanel();

        if (!resumePendingWork || _isPromptRunning)
            return;

        if (_promptQueue.Count > 0)
            _ = DrainQueueIfNeededAsync();
        else
            _ = MaybeFireQueuedLoopAsync();
    }

    private void RestoreInterruptedPromptRecoverySurface()
    {
        var store = GetInterruptedPromptRecoveryStore();
        var recovery = store?.Load();
        if (recovery is null && store is not null)
        {
            recovery = InterruptedPromptRecoveryDetector.TryDetect(
                _conversationManager.ConversationState,
                _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace!.FolderPath));
            if (recovery is not null)
            {
                store.Save(recovery);
                SquadDashTrace.Write(
                    "Recovery",
                    $"Detected legacy interrupted prompt from persisted turn and trace id={recovery.RecoveryId} target={recovery.TargetAgentHandle ?? "(coordinator)"}");
            }
        }
        if (recovery is null)
            return;

        if (!InterruptedPromptRecoveryPresentation.IsStillLatestUnresolved(
                recovery,
                _conversationManager.ConversationState))
        {
            store?.Clear("superseded-by-newer-transcript-turn");
            SquadDashTrace.Write(
                "Recovery",
                $"Skipped stale interrupted prompt recovery id={recovery.RecoveryId}; a newer transcript turn exists.");
            return;
        }

        EnterInterruptedPromptRecoveryHold(recovery);
        _ = PrepareInterruptedPromptRecoverySurfaceAsync(recovery, restoredAfterRestart: true);
        SquadDashTrace.Write(
            "Recovery",
            $"Restored interrupted prompt recovery id={recovery.RecoveryId} autoEligible={InterruptedPromptAutomaticRecoveryPolicy.ShouldAutomaticallyContinue(recovery)}");
    }

    private async Task ContinueInterruptedPromptAsync(
        InterruptedPromptRecoveryState recovery,
        bool automatic = false)
    {
        // The user's primary action resolves the blocking checkpoint. The durable envelope
        // remains until the continuation succeeds, so a crash or repeated timeout can restore it.
        ReleaseInterruptedPromptRecoveryHold("continue-action", resumePendingWork: false);
        ResumeQueueAfterStoppedWorkResponseIfNeeded();
        ResetQueuePausedState();
        ClearRuntimeIssue();

        var continuationPrompt = BuildInterruptedPlanContinuationPrompt(recovery)
            ?? InterruptedPromptRecoveryPresentation.BuildContinuationPrompt(recovery);
        _pendingTranscriptAttachments = recovery.Attachments.ToArray();
        if (!automatic)
        {
            ShowSystemTranscriptEntry(
                InterruptedPromptRecoveryPresentation.BuildResumeAttemptText(recovery));
        }
        SquadDashTrace.Write(
            "Recovery",
            $"Continuing interrupted prompt id={recovery.RecoveryId} kind={recovery.ExecutionKind} target={recovery.TargetAgentHandle ?? "(coordinator)"}");

        switch (recovery.ExecutionKind)
        {
            case InterruptedPromptExecutionKind.NamedAgentDirect when !string.IsNullOrWhiteSpace(recovery.TargetAgentHandle):
                await _pec.ExecuteNamedAgentDirectAsync(
                    recovery.TargetAgentHandle,
                    continuationPrompt,
                    recovery.HandoffContext,
                    addToHistory: false,
                    clearPromptBox: false,
                    sessionIdOverride: recovery.SessionId,
                    preserveExistingRecovery: true);
                break;

            case InterruptedPromptExecutionKind.NamedAgentDelegation when !string.IsNullOrWhiteSpace(recovery.TargetAgentHandle):
                await _pec.ExecuteNamedAgentDelegationAsync(
                    continuationPrompt,
                    recovery.TargetAgentHandle,
                    addToHistory: false,
                    clearPromptBox: false,
                    sessionIdOverride: recovery.SessionId,
                    preserveExistingRecovery: true);
                break;

            default:
                await _pec.ExecutePromptAsync(
                    continuationPrompt,
                    addToHistory: false,
                    clearPromptBox: false,
                    sessionIdOverride: recovery.SessionId,
                    displayPrompt: $"Continue interrupted work from {recovery.InterruptedAt.ToLocalTime():g}",
                    preserveExistingRecovery: true);
                break;
        }
    }

    private string? BuildInterruptedPlanContinuationPrompt(InterruptedPromptRecoveryState recovery)
    {
        if (_currentWorkspace is null || _planStore is null)
            return null;

        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (!InterruptedPromptPlanRecoveryPolicy.MatchesActiveImplementationAttempt(recovery, execution) ||
            execution?.PlanExecutionAttempt is not { Status: "active" } interruptedAttempt)
        {
            return null;
        }

        var groupId = execution.DecomposeGroupId!;
        var revision = execution.DecomposeRevision
            ?? throw new InvalidOperationException(
                "SquadDash cannot continue the interrupted plan because its revision is unavailable.");
        var durablePlan = _planStore.Load(groupId)
            ?? throw new InvalidOperationException(
                $"SquadDash cannot continue the interrupted plan because {groupId} is unavailable.");
        if (!string.Equals(durablePlan.Revision, revision, StringComparison.Ordinal))
        {
            throw new InvalidOperationException(
                "SquadDash cannot continue the interrupted plan because its approved revision changed.");
        }

        var taskId = interruptedAttempt.TaskId;
        var task = PendingDecomposePlanAdapter.FromPlan(durablePlan).Group.Tasks.FirstOrDefault(candidate =>
            string.Equals(candidate.Id, taskId, StringComparison.Ordinal))
            ?? throw new InvalidOperationException(
                $"SquadDash cannot continue the interrupted plan because task {taskId} is unavailable.");
        var routingPolicy = PlanAgentRoutingPolicy.Normalize(_settingsSnapshot.PlanAgentRoutingPolicy);
        var assignments = routingPolicy == PlanAgentRoutingPolicy.Off
            ? null
            : task.AgentAssignments;
        var freshAttempt = CreatePlanExecutionAttempt(
            groupId,
            taskId,
            revision,
            task,
            assignments,
            routingPolicy)
            ?? throw new InvalidOperationException(
                "SquadDash cannot create a fresh execution attempt for the interrupted plan task.");

        var routingContext = DecomposePlanningInstructions.BuildPlanStepRoutingContext(
            _currentWorkspace.SquadFolderPath,
            taskId,
            task.Title ?? taskId,
            task.Description,
            assignments,
            revision,
            freshAttempt,
            string.Equals(task.AgentRoutingMode, "generic", StringComparison.Ordinal)
                ? task.GenericAgentReason
                : null,
            durablePlan.Branch);
        var continuedExecution = PlanExecutionRecoveryPolicy.ReplaceInterruptedAttempt(
            execution,
            freshAttempt);
        _conversationManager.UpdateActiveLoopExecutionState(continuedExecution);
        AppendPlanExecutionJournal(
            groupId,
            taskId,
            "interrupted-attempt-replaced",
            $"Closed interrupted execution attempt {interruptedAttempt.AttemptId} and created fresh attempt {freshAttempt.AttemptId} before continuation.");
        SquadDashTrace.Write(
            "PlanRecovery",
            $"Replaced interrupted plan attempt plan={groupId} task={taskId} oldAttempt={interruptedAttempt.AttemptId} newAttempt={freshAttempt.AttemptId} baseline={continuedExecution.TaskBaselineCommit ?? "unknown"}");

        return PlanFreshAttemptPrompt.BuildInterruptedContinuation(
            groupId,
            taskId,
            revision,
            routingContext);
    }

    private void EditInterruptedPrompt(InterruptedPromptRecoveryState recovery)
    {
        _conversationManager.RestorePromptDraft(
            InterruptedPromptRecoveryPresentation.BuildEditablePrompt(recovery),
            recovery.Attachments);
        PromptTextBox.Focus();
        PromptTextBox.CaretIndex = PromptTextBox.Text.Length;
        SquadDashTrace.Write("Recovery", $"Restored interrupted prompt to editor id={recovery.RecoveryId}");
    }

    private void ShowInterruptedPromptDiagnostics(InterruptedPromptRecoveryState recovery)
    {
        ShowTextWindow(
            "Squad Runtime Diagnostics",
            InterruptedPromptRecoveryPresentation.BuildDiagnosticsText(
                recovery,
                GetInterruptedPromptRecoveryStore()?.PathForDiagnostics));
    }

    private void DismissInterruptedPromptRecovery(
        InterruptedPromptRecoveryState recovery,
        TranscriptResponseEntry entry)
    {
        _pec.DisableQuickReplies(entry);
        ClearActiveQuickReplyState(entry);
        GetInterruptedPromptRecoveryStore()?.Clear("user-dismissed");
        ReleaseInterruptedPromptRecoveryHold("dismiss-action", resumePendingWork: true);
        ShowSystemTranscriptEntry(
            "Interrupted work recovery dismissed. Queued prompts and any preserved loop may continue.");
    }

    private async Task HandleCheckGitDiffAsync()
    {
        var workspacePath = _currentWorkspace?.FolderPath;
        if (string.IsNullOrWhiteSpace(workspacePath))
        {
            AppendLine("[info] No workspace folder — cannot run git diff.", null);
            return;
        }

        string diffOutput;
        try
        {
            var psi = new System.Diagnostics.ProcessStartInfo("git", "diff --stat")
            {
                WorkingDirectory           = workspacePath,
                RedirectStandardOutput     = true,
                RedirectStandardError      = true,
                UseShellExecute            = false,
                CreateNoWindow             = true,
            };
            using var proc = System.Diagnostics.Process.Start(psi)!;
            var stdout = await proc.StandardOutput.ReadToEndAsync();
            var stderr = await proc.StandardError.ReadToEndAsync();
            await proc.WaitForExitAsync();
            diffOutput = string.IsNullOrWhiteSpace(stdout)
                ? (string.IsNullOrWhiteSpace(stderr) ? "(no changes)" : stderr.Trim())
                : stdout.Trim();
        }
        catch (Exception ex)
        {
            AppendLine($"[info] Could not run git diff: {ex.Message}", null);
            return;
        }

        SquadDashTrace.Write("UI", $"Interrupt recovery: git diff captured ({diffOutput.Length} chars), injecting as prompt.");
        ResumeQueueAfterStoppedWorkResponseIfNeeded();
        ResetQueuePausedState();
        var prompt = $"The prompt was interrupted. Here is the current git diff — please review for partial changes and advise:\n\n```\n{diffOutput}\n```";
        await _pec.ExecutePromptAsync(prompt, addToHistory: false, clearPromptBox: false);
    }

    private void HandleDraftQuickReply(string? draftText, TranscriptResponseEntry? entry)
    {
        if (string.IsNullOrWhiteSpace(draftText))
            return;

        var text = draftText.Trim();

        if (entry is not null)
        {
            _pec.DisableQuickReplies(entry);
            ClearActiveQuickReplyState(entry);
        }

        // If the active draft box is empty, fill it directly.
        if (_activeTabId is null && string.IsNullOrWhiteSpace(PromptTextBox.Text))
        {
            SetPromptTextBoxLogicalBuffer(text, text.Length, reason: "draft-quick-reply");
            PromptTextBox.Focus();
            return;
        }

        // Active draft has content or we're on a queue tab — add a new queued item with
        // IsEditing=true so it won't auto-dispatch until the user reviews and sends it.
        var item = new PromptQueueItem
        {
            Text = text,
            SequenceNumber = _promptQueueCoordinator.NextSequenceNumber(),
            CaretIndex = text.Length,
            IsEditing = true
        };
        item.QueueNumber = NextQueueNumber();
        _promptQueue.EnqueueItem(item);
        SyncQueuePanel();
        OnQueueTabClicked(item.Id);
    }

    private void ClearActiveQuickReplyState(TranscriptResponseEntry? entry = null)
    {
        if (entry is not null && !ReferenceEquals(entry, _lastQuickReplyEntry))
            return;

        _lastQuickReplyEntry = null;
        _currentQuickReplyOptions = [];
        _currentQuickReplyPayloads = [];
        _quickRepliesShownAt = DateTime.MinValue;
    }

    private async void QuickReplyButton_Click(object sender, RoutedEventArgs e)
    {
        if (sender is not FrameworkElement { Tag: QuickReplyButtonPayload payload } ||
            string.IsNullOrWhiteSpace(payload.Option))
            return;

        if (_isPromptRunning || _currentWorkspace is null)
            return;

        // Draft quick replies pre-fill the input without dispatching. Handle before the try/finally
        // block so the loop's _loopFollowUpTcs is NOT signaled — the loop stays paused until the
        // user reviews the draft and actually sends it.
        if (string.Equals(payload.RouteMode, "draft", StringComparison.OrdinalIgnoreCase))
        {
            HandleDraftQuickReply(payload.DraftPrompt, payload.Entry);
            return;
        }

        try
        {
            if (IsRoutingIssueQuickReply(payload))
            {
                var option = payload.Option.Trim();
                if (string.Equals(option, RoutingIssueWorkflow.IgnoreQuickReply, StringComparison.OrdinalIgnoreCase))
                {
                    HandleRoutingIgnoreQuickReply(payload.Entry);
                    return;
                }

                if (string.Equals(option, RoutingIssueWorkflow.RepairQuickReply, StringComparison.OrdinalIgnoreCase))
                {
                    await HandleRoutingRepairQuickReplyAsync(payload.Entry);
                    return;
                }
            }

            if (IsTeamRootPollutionQuickReply(payload))
            {
                var option = payload.Option.Trim();
                if (string.Equals(option, SquadTeamRootRepairWorkflow.CleanQuickReply, StringComparison.OrdinalIgnoreCase))
                {
                    HandleTeamRootCleanQuickReply(payload.Entry);
                    return;
                }

                if (string.Equals(option, SquadTeamRootRepairWorkflow.IgnoreQuickReply, StringComparison.OrdinalIgnoreCase))
                {
                    HandleTeamRootIgnoreQuickReply(payload.Entry);
                    return;
                }
            }

            var interruptedRecovery = LoadInterruptedPromptRecovery();
            if (interruptedRecovery is not null)
            {
                var recoveryOption = payload.Option.Trim();
                var primaryRecoveryAction = InterruptedPromptRecoveryPresentation.BuildPrimaryActionLabel(interruptedRecovery);
                if (string.Equals(recoveryOption, primaryRecoveryAction, StringComparison.OrdinalIgnoreCase))
                {
                    _pec.DisableQuickReplies(payload.Entry);
                    ClearActiveQuickReplyState(payload.Entry);
                    await ContinueInterruptedPromptAsync(interruptedRecovery);
                    return;
                }

                if (string.Equals(recoveryOption, InterruptedPromptRecoveryPresentation.EditPromptAction, StringComparison.OrdinalIgnoreCase))
                {
                    EditInterruptedPrompt(interruptedRecovery);
                    return;
                }

                if (string.Equals(recoveryOption, InterruptedPromptRecoveryPresentation.ViewDiagnosticsAction, StringComparison.OrdinalIgnoreCase))
                {
                    ShowInterruptedPromptDiagnostics(interruptedRecovery);
                    return;
                }

                if (string.Equals(recoveryOption, InterruptedPromptRecoveryPresentation.DismissAction, StringComparison.OrdinalIgnoreCase))
                {
                    DismissInterruptedPromptRecovery(interruptedRecovery, payload.Entry);
                    return;
                }

                if (interruptedRecovery.FailureCount > 1 &&
                    string.Equals(recoveryOption, InterruptedPromptRecoveryPresentation.RunDoctorAction, StringComparison.OrdinalIgnoreCase))
                {
                    RunDoctorButton_Click(null!, null!);
                    return;
                }
            }

            // Programmatic interrupt recovery quick replies — handled locally, no AI dispatch.
            var trimmedOption = payload.Option.Trim();
            if (string.Equals(trimmedOption, PromptExecutionController.ResendLastPromptQuickReply, StringComparison.OrdinalIgnoreCase))
            {
                _pec.DisableQuickReplies(payload.Entry);
                ClearActiveQuickReplyState(payload.Entry);
                await HandleResendLastPromptAsync();
                return;
            }

            if (string.Equals(trimmedOption, PromptExecutionController.CheckGitDiffQuickReply, StringComparison.OrdinalIgnoreCase))
            {
                _pec.DisableQuickReplies(payload.Entry);
                ClearActiveQuickReplyState(payload.Entry);
                await HandleCheckGitDiffAsync();
                return;
            }

            // Sim quick replies (routeMode="sim") exercise the quick reply UI without
            // dispatching a real prompt to the AI — used by /test-queue and guided tours.
            if (string.Equals(payload.RouteMode, "sim", StringComparison.OrdinalIgnoreCase))
            {
                _pec.DisableQuickReplies(payload.Entry);
                ClearActiveQuickReplyState(payload.Entry);
                SquadDashTrace.Write("UI", $"Quick reply sim button clicked: '{payload.Option.Trim()}' — no AI dispatch.");
                return;
            }

            _pec.DisableQuickReplies(payload.Entry);
            ClearActiveQuickReplyState(payload.Entry);
            ResumeQueueAfterStoppedWorkResponseIfNeeded();
            ResetQueuePausedState();
            var pendingLaunch = CreatePendingQuickReplyLaunch(payload);
            _pendingQuickReplyLaunch = pendingLaunch;
            var promptText = payload.Option.Trim();
            var requiresNamedAgentDelegation = QuickReplyAgentLaunchPolicy.RequiresObservedNamedAgentLaunch(
                payload.RouteMode,
                payload.TargetAgentHandle);
            _pendingSupplementalPromptInstruction = null;
            _pendingQuickReplyRoutingInstruction = requiresNamedAgentDelegation || string.IsNullOrWhiteSpace(payload.RoutingInstruction)
                ? null
                : payload.RoutingInstruction.Trim();
            SquadDashTrace.Write(
                "UI",
                string.IsNullOrWhiteSpace(payload.ContinuationAgentLabel)
                    ? $"Quick reply selected option='{payload.Option.Trim()}' routed=coordinator mode={payload.RouteMode ?? "(legacy)"}"
                    : $"Quick reply selected option='{payload.Option.Trim()}' routed={payload.ContinuationAgentLabel} mode={payload.RouteMode ?? "(legacy)"}");
            SquadDashTrace.Write("UI", "Prompt sent: quick reply button");
            if (requiresNamedAgentDelegation)
            {
                SquadDashTrace.Write(
                    "Routing",
                    $"Quick reply entering named-agent direct launch target={payload.TargetAgentHandle?.Trim().TrimStart('@') ?? "(unknown)"} option='{promptText}'");
                var handoffContext = _conversationManager.BuildQuickReplyHandoffContext(
                    payload.Entry,
                    promptText,
                    payload.ContinuationAgentLabel,
                    payload.RouteMode,
                    payload.TargetAgentHandle);
                await _pec.ExecuteNamedAgentDirectAsync(
                    payload.TargetAgentHandle!,
                    promptText,
                    handoffContext,
                    addToHistory: true,
                    clearPromptBox: false);
            }
            else
            {
                await _pec.ExecutePromptAsync(promptText, addToHistory: true, clearPromptBox: false);
            }

            MaybeReportPendingQuickReplyLaunchFailure(pendingLaunch);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException("Quick Reply", ex);
        }
        finally
        {
            _pendingQuickReplyLaunch = null;
            _pendingQuickReplyRoutingInstruction = null;
            _pendingSupplementalPromptInstruction = null;
            // If a loop iteration is waiting for user follow-up, signal that input was received.
            // The loop will re-check LastTurnNeedsInput() to decide whether to wait again.
            _loopFollowUpTcs?.TrySetResult(true);
        }
    }

    private void AppendTextRuns(InlineCollection inlines, string? text)
    {
        if (string.IsNullOrEmpty(text))
            return;

        _markdownRenderer.AppendInlineMarkdown(inlines, text);
    }

    private void EnsureCurrentTurnThinkingVisible() =>
        EnsureCurrentTurnThinkingVisible(CoordinatorThread);

    private void EnsureCurrentTurnThinkingVisible(TranscriptThreadState thread)
    {
        if (thread.CurrentTurn is null)
            return;

        CollapseCurrentTurnThoughts(thread);
        var latestBlock = GetLatestThinkingBlock(thread.CurrentTurn);
        if (latestBlock is not null)
            SetExpanderOpen(latestBlock.Expander, true);
    }

    private void AppendThinkingText(string text, string? speaker) =>
        AppendThinkingText(CoordinatorThread, text, speaker);

    private void AppendThinkingText(TranscriptThreadState thread, string text, string? speaker)
    {
        if (thread.CurrentTurn is null || string.IsNullOrWhiteSpace(text))
            return;

        var thoughtEntry = GetOrCreateThoughtEntry(thread.CurrentTurn, speaker);
        AppendThoughtChunk(thoughtEntry.RawTextBuilder, text);

        if (thread.CurrentTurn.ThoughtBlocks.LastOrDefault() is { } thoughtBlock)
            thoughtBlock.LastUpdatedAt = DateTimeOffset.Now;

        QueueThoughtEntryRender(thoughtEntry, flushImmediately: false);
        ScrollToEndIfAtBottom(thread);
    }

    private static void AppendThoughtChunk(StringBuilder builder, string text)
    {
        var chunk = NormalizeThinkingChunk(text);
        if (string.IsNullOrWhiteSpace(chunk))
            return;

        builder.Append(chunk);
    }

    private void ScrollToEndIfAtBottom() =>
        ScrollToEndIfAtBottom(CoordinatorThread);

    private void ScrollToEndIfAtBottom(TranscriptThreadState thread)
    {
        if (!ReferenceEquals(_selectedTranscriptThread ?? CoordinatorThread, thread))
            return;

        EnsureThreadFooterAtEnd(thread);
        ActiveScrollController.RequestScrollToEnd();
    }

    private void ScrollToPromptParagraph(Paragraph paragraph)
    {
        _ = Dispatcher.BeginInvoke(System.Windows.Threading.DispatcherPriority.Loaded, () =>
        {
            var activeBox = ActiveTranscriptBox;
            var sv = activeBox.Template?.FindName("PART_ContentHost", activeBox) as ScrollViewer;
            if (sv is null) return;

            var tp = paragraph.ContentStart;
            var rect = tp.GetCharacterRect(System.Windows.Documents.LogicalDirection.Forward);

            // rect is in coordinates relative to the scroll viewer's visible area.
            // Always scroll to place this prompt at the viewport top.
            double targetOffset = sv.VerticalOffset + rect.Top;
            SquadDashTrace.Write(TraceCategory.TranscriptNav,
                $"ScrollToPromptParagraph: currentOffset={sv.VerticalOffset:F1} rect.Top={rect.Top:F1} " +
                $"targetOffset={targetOffset:F1} scrollableHeight={sv.ScrollableHeight:F1} rect.IsEmpty={rect.IsEmpty}");
            ActiveScrollController.ScrollToOffset(targetOffset);

            SyncPromptNavButtons();
        });
    }

    /// <summary>
    /// Finds TextPointers bracketing every question sentence (ending with <c>?</c>) in
    /// <paramref name="paragraph"/>.  Returns an empty list when no <c>?</c> exists.
    /// Adjacent or overlapping question sentences (e.g. <c>??</c>) are merged into one range.
    /// </summary>
    private static List<(TextPointer Start, TextPointer End)> FindAllQuestionSentencePointers(Paragraph paragraph)
    {
        var fullText = new System.Windows.Documents.TextRange(
            paragraph.ContentStart, paragraph.ContentEnd).Text;

        var ranges = QuestionSentenceExtractor.ExtractQuestionSentenceRanges(fullText);
        var result = new List<(TextPointer Start, TextPointer End)>(ranges.Count);
        foreach (var (sentenceStart, lastQIdx) in ranges)
        {
            var startPointer = CharOffsetToTextPointer(paragraph.ContentStart, paragraph.ContentEnd, sentenceStart);
            var endPointer   = CharOffsetToTextPointer(paragraph.ContentStart, paragraph.ContentEnd, lastQIdx + 1,
                System.Windows.Documents.LogicalDirection.Backward);
            result.Add((startPointer, endPointer));
        }
        return result;
    }

    /// <summary>
    /// Walks forward from <paramref name="rangeStart"/> through text runs to find the
    /// <see cref="System.Windows.Documents.TextPointer"/> that corresponds to
    /// <paramref name="charOffset"/> characters into the plain text of the range.
    /// </summary>
    private static System.Windows.Documents.TextPointer CharOffsetToTextPointer(
        System.Windows.Documents.TextPointer rangeStart,
        System.Windows.Documents.TextPointer rangeEnd,
        int charOffset,
        System.Windows.Documents.LogicalDirection gravityAtBoundary = System.Windows.Documents.LogicalDirection.Forward)
    {
        if (charOffset <= 0) return rangeStart;
        var tp = rangeStart;
        int remaining = charOffset;
        while (tp != null && remaining > 0 && tp.CompareTo(rangeEnd) < 0)
        {
            var ctx = tp.GetPointerContext(System.Windows.Documents.LogicalDirection.Forward);
            if (ctx == System.Windows.Documents.TextPointerContext.Text)
            {
                int runLen = tp.GetTextRunLength(System.Windows.Documents.LogicalDirection.Forward);
                if (remaining <= runLen)
                    return tp.GetPositionAtOffset(remaining, gravityAtBoundary);
                remaining -= runLen;
            }
            else if (ctx == System.Windows.Documents.TextPointerContext.None)
            {
                break;
            }
            tp = tp.GetNextContextPosition(System.Windows.Documents.LogicalDirection.Forward);
        }
        return tp ?? rangeEnd;
    }

    /// <summary>
    /// Highlights all question sentences in <paramref name="paragraph"/> by directly
    /// coloring the matching <see cref="Run"/> elements via
    /// <see cref="TextRange.ApplyPropertyValue"/>.  This avoids the adorner overlay
    /// approach (which drifts on word-wrap and redraws text on top of itself).
    /// </summary>
    private void ApplyQuestionHighlight(Paragraph paragraph)
    {
        ClearQuestionHighlightRuns();

        var ranges = FindAllQuestionSentencePointers(paragraph);
        if (ranges.Count == 0) return;

        _questionHighlightParagraph = paragraph;
        _questionHighlightRanges = ranges;

        var highlightBrush = TryFindResource("SearchHighlightCurrent") as Brush
            ?? new SolidColorBrush(Color.FromArgb(230, 255, 143, 0));
        var textBrush = TryFindResource("SearchHighlightTextCurrent") as Brush
            ?? new SolidColorBrush(Color.FromRgb(49, 34, 0));

        foreach (var (start, end) in ranges)
        {
            var range = new TextRange(start, end);
            range.ApplyPropertyValue(TextElement.BackgroundProperty, highlightBrush);
            range.ApplyPropertyValue(TextElement.ForegroundProperty, textBrush);
        }
    }

    /// <summary>
    /// Clears the question-sentence inline highlight by restoring Background and
    /// Foreground to their inherited (unset) values on all inlines in the previously
    /// highlighted paragraph.
    /// </summary>
    private void ClearQuestionHighlightRuns()
    {
        if (_questionHighlightParagraph == null)
        {
            _questionHighlightRanges = null;
            return;
        }

        ClearInlineHighlightProperties(_questionHighlightParagraph.Inlines);

        _questionHighlightParagraph = null;
        _questionHighlightRanges = null;
    }

    /// <summary>
    /// Recursively clears locally-set Background and Foreground values from every
    /// <see cref="Inline"/> in <paramref name="inlines"/>, restoring inherited styling.
    /// Only clears properties whose local value is a concrete <see cref="Brush"/> —
    /// this avoids a <see cref="NullReferenceException"/> from
    /// <c>ResourceReferenceExpression.OnDetach</c> when the inline already had a
    /// theme resource reference on that property before we applied the highlight.
    /// </summary>
    private static void ClearInlineHighlightProperties(InlineCollection inlines)
    {
        foreach (Inline inline in inlines)
        {
            if (inline.ReadLocalValue(TextElement.BackgroundProperty) is Brush)
                inline.ClearValue(TextElement.BackgroundProperty);
            if (inline.ReadLocalValue(TextElement.ForegroundProperty) is Brush)
                inline.ClearValue(TextElement.ForegroundProperty);
            if (inline is Span span)
                ClearInlineHighlightProperties(span.Inlines);
        }
    }

    private void RefreshActiveTranscriptScrollViewer()
    {
        var activeBox = ActiveTranscriptBox;
        var newScrollViewer = VisualTreeSearch.FindChild<ScrollViewer>(activeBox);
        if (ReferenceEquals(newScrollViewer, _transcriptScrollViewer))
            return;

        if (_transcriptScrollViewer is not null)
            _transcriptScrollViewer.ScrollChanged -= TranscriptScrollViewer_ScrollChanged;

        _transcriptScrollViewer = newScrollViewer;

        if (_transcriptScrollViewer is not null)
            _transcriptScrollViewer.ScrollChanged += TranscriptScrollViewer_ScrollChanged;
    }

    private void TranscriptScrollViewer_ScrollChanged(object sender, ScrollChangedEventArgs e)
    {
        // Re-evaluate enabled state whenever the scroll position, content height,
        // or viewport height changes — the last two cover window resize, maximize,
        // and F11 full-transcript mode toggling.
        if (e.VerticalChange != 0 || e.ExtentHeightChange != 0 || e.ViewportHeightChange != 0)
            SyncPromptNavButtons();

        // Ensure search highlights repaint on every scroll.  The SearchHighlightAdorner
        // already subscribes to the same ScrollViewer, but that subscription can miss
        // events when focus is on a sibling panel.  This is the authoritative path that
        // fires for all scroll causes (keyboard, scrollbar drag, touch, programmatic).
        if (e.VerticalChange != 0)
            _search.InvalidateAdornerHighlights();

        // When the document grows (content streamed in), the scrollbar marker fractions
        // were computed with the old ExtentHeight and are now stale.  Recompute them
        // using the cached pointers so the tick marks stay anchored to the correct
        // document positions without requiring a full adorner rebuild.
        if (e.ExtentHeightChange != 0)
            _search.RefreshScrollbarMarkerPositions();

        // Inactive transcript selection is rendered by TranscriptInactiveSelectionAdorner
        // so it can recompute geometry after scroll instead of using WPF's stale cache.

        // Debounce-refresh the coordinator intent label when the user scrolls the
        // coordinator transcript so the title reflects the last visible intent.
        if (e.VerticalChange != 0)
        {
            var activeThread = _selectedTranscriptThread ?? CoordinatorThread;
            if (activeThread.Kind == TranscriptThreadKind.Coordinator)
                RestartCoordinatorIntentDebounce();
        }
    }

    /// <summary>
    /// Returns scroll-based nav state for the active thread.
    /// All indices are into <c>thread.PromptParagraphs</c>.
    /// </summary>
    /// <param name="nearestAboveIdx">
    ///   Index of the prompt closest to (and strictly above) the viewport top.
    ///   -1 if no prompt is above the viewport.
    /// </param>
    /// <param name="nearestBelowIdx">
    ///   Index of the nearest prompt below the viewport top that can actually be
    ///   scrolled to the top of the viewport (i.e. enough document content exists
    ///   below it to fill the remaining viewport height).
    ///   -1 if no such prompt exists.
    /// </param>
    private void GetScrollBasedNavState(
        out bool canGoUp, out bool canGoDown,
        out int nearestAboveIdx, out int nearestBelowIdx)
    {
        canGoUp       = false;
        canGoDown     = false;
        nearestAboveIdx = -1;
        nearestBelowIdx = -1;

        var thread = _selectedTranscriptThread ?? CoordinatorThread;
        if (_transcriptScrollViewer is null || thread.PromptParagraphs.Count == 0)
            return;

        // A prompt is "above" (UP target) when it's scrolled above the viewport top.
        // A prompt is a "below" (DOWN target) when it is:
        //   (a) below the viewport top by more than the dead-zone, AND
        //   (b) can actually be scrolled to the viewport top — i.e. its absolute Y is
        //       within the scrollable range (≤ ScrollableHeight). Prompts near the very
        //       bottom of the document cannot be placed at the top because the scroll
        //       viewer hits its maximum offset; navigating to them would produce no
        //       meaningful movement, so the ↓ button should be disabled for them.
        const double DeadZone = 50.0;
        var sv         = _transcriptScrollViewer;
        var viewportTop    = sv.VerticalOffset;
        var scrollableMax  = sv.ScrollableHeight; // ExtentHeight − ViewportHeight

        double bestAboveY = double.MinValue;
        double bestBelowY = double.MaxValue;

        for (int i = 0; i < thread.PromptParagraphs.Count; i++)
        {
            var para = thread.PromptParagraphs[i].Paragraph;
            var rect = para.ContentStart.GetCharacterRect(System.Windows.Documents.LogicalDirection.Forward);
            if (rect.IsEmpty) continue;

            // Absolute Y in the document.
            var absY = viewportTop + rect.Top;

            if (absY < viewportTop - DeadZone)
            {
                // Prompt is above the viewport — candidate for ↑ (go up/back).
                // Pick the one with the LARGEST absoluteY (nearest from above).
                if (absY > bestAboveY) { bestAboveY = absY; nearestAboveIdx = i; }
            }
            else if (absY > viewportTop + DeadZone && absY <= scrollableMax)
            {
                // Prompt is below the viewport top AND can be brought to the top
                // (there is enough content below it to fill the viewport).
                // Pick the one with the SMALLEST absoluteY (nearest from below).
                if (absY < bestBelowY) { bestBelowY = absY; nearestBelowIdx = i; }
            }
        }

        canGoUp   = nearestAboveIdx >= 0;
        canGoDown = nearestBelowIdx >= 0;

        SquadDashTrace.Write(TraceCategory.TranscriptNav,
            $"GetScrollBasedNavState: viewportTop={viewportTop:F1} scrollableMax={scrollableMax:F1} " +
            $"prompts={thread.PromptParagraphs.Count} navIndex={thread.PromptNavIndex} " +
            $"nearestAbove={nearestAboveIdx} (absY={bestAboveY:F1}) " +
            $"nearestBelow={nearestBelowIdx} (absY={(nearestBelowIdx >= 0 ? bestBelowY : double.NaN):F1}) " +
            $"canGoUp={canGoUp} canGoDown={canGoDown}");
    }

    private void SchedulePromptNavGeometryRefresh()
    {
        _ = Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle, () =>
        {
            try { SyncPromptNavButtons(allowGeometry: true); }
            catch (Exception ex) { HandleUiCallbackException(nameof(SchedulePromptNavGeometryRefresh), ex); }
        });
    }

    private void SyncPromptNavButtons(bool allowGeometry = true)
    {
        var thread = _selectedTranscriptThread ?? CoordinatorThread;
        var count = thread.PromptParagraphs.Count;
        var idx = thread.PromptNavIndex;

        var isCoordinatorThread = ReferenceEquals(thread, CoordinatorThread);
        PromptNavButtonsPanel.Visibility = isCoordinatorThread || count > 1
            ? Visibility.Visible
            : Visibility.Collapsed;

        bool canGoUp;
        bool canGoDown;
        if (allowGeometry && _transcriptScrollViewer is not null)
        {
            // Base enabled state on scroll position so that manual scrolling keeps
            // both buttons in sync — not just on which button was last clicked.
            GetScrollBasedNavState(out canGoUp, out canGoDown, out _, out _);
        }
        else
        {
            canGoUp   = count > 0 && (idx == -1 || idx > 0);
            canGoDown = count > 0 && idx != -1 && idx < count - 1;
        }

        PromptNavUpButton.IsEnabled   = canGoUp;
        PromptNavDownButton.IsEnabled = canGoDown;
    }

    private static string FormatRelativeTime(DateTimeOffset timestamp)
    {
        return StatusTimingPresentation.FormatRelativeTimestamp(timestamp);
    }

    private static bool IsAltHeld()
        => (Keyboard.Modifiers & ModifierKeys.Alt) != 0
        || Keyboard.IsKeyDown(Key.LeftAlt)
        || Keyboard.IsKeyDown(Key.RightAlt);

    private void PromptNavUpButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var thread = _selectedTranscriptThread ?? CoordinatorThread;
            if (thread.PromptParagraphs.Count == 0) return;

            // Shift+click jumps to the very first prompt.
            if ((Keyboard.Modifiers & ModifierKeys.Shift) != 0)
            {
                ClearQuestionHighlightRuns();
                thread.PromptNavIndex = 0;
                ScrollToPromptParagraph(thread.PromptParagraphs[0].Paragraph);
                return;
            }

            // Alt+click: find the nearest prompt above that contains a question mark.
            if (IsAltHeld())
            {
                GetScrollBasedNavState(out _, out _, out int nearestAboveIdx, out _);
                // Fall back to one before the last-navigated question when nothing is
                // geometrically above the viewport (e.g. after a scroll landed exactly
                // on the target and it sits within the dead zone).
                var startIdx = nearestAboveIdx >= 0 ? nearestAboveIdx
                    : thread.PromptNavIndex > 0 ? thread.PromptNavIndex - 1
                    : thread.PromptParagraphs.Count - 1;
                SquadDashTrace.Write(TraceCategory.TranscriptNav,
                    $"PromptNavUp (Alt): nearestAboveIdx={nearestAboveIdx} navIndex={thread.PromptNavIndex} " +
                    $"startIdx={startIdx} totalPrompts={thread.PromptParagraphs.Count}");
                for (int i = startIdx; i >= 0; i--)
                {
                    var text = new System.Windows.Documents.TextRange(
                        thread.PromptParagraphs[i].Paragraph.ContentStart,
                        thread.PromptParagraphs[i].Paragraph.ContentEnd).Text;
                    if (text.Contains('?'))
                    {
                        SquadDashTrace.Write(TraceCategory.TranscriptNav,
                            $"PromptNavUp (Alt): found '?' at index={i}, navigating");
                        ClearQuestionHighlightRuns();
                        thread.PromptNavIndex = i;
                        ScrollToPromptParagraph(thread.PromptParagraphs[i].Paragraph);
                        ApplyQuestionHighlight(thread.PromptParagraphs[i].Paragraph);
                        return;
                    }
                }
                SquadDashTrace.Write(TraceCategory.TranscriptNav,
                    $"PromptNavUp (Alt): no '?' found scanning from startIdx={startIdx} to 0 — highlight preserved");
                return;
            }

            ClearQuestionHighlightRuns();
            GetScrollBasedNavState(out _, out _, out int nearestAboveIdx2, out _);

            int target;
            if (nearestAboveIdx2 >= 0)
            {
                // Jump to the nearest prompt above the viewport.
                target = nearestAboveIdx2;
            }
            else
            {
                // No prompt above the viewport yet (e.g. first press from the bottom):
                // jump to the most-recent prompt, falling back to index-based if already at one.
                var count = thread.PromptParagraphs.Count;
                target = thread.PromptNavIndex == -1
                    ? count - 1
                    : Math.Max(0, thread.PromptNavIndex - 1);
            }

            thread.PromptNavIndex = target;
            ScrollToPromptParagraph(thread.PromptParagraphs[target].Paragraph);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(PromptNavUpButton_Click), ex);
        }
    }

    private void PromptNavDownButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var thread = _selectedTranscriptThread ?? CoordinatorThread;
            if (thread.PromptParagraphs.Count == 0) return;

            // Shift+click jumps to the very last prompt.
            if ((Keyboard.Modifiers & ModifierKeys.Shift) != 0)
            {
                ClearQuestionHighlightRuns();
                var last = thread.PromptParagraphs.Count - 1;
                thread.PromptNavIndex = last;
                ScrollToPromptParagraph(thread.PromptParagraphs[last].Paragraph);
                return;
            }

            // Alt+click: find the nearest prompt below that contains a question mark.
            if (IsAltHeld())
            {
                GetScrollBasedNavState(out _, out _, out _, out int nearestBelowIdx);
                // Fall back to one after the last-navigated question when nothing is
                // geometrically below the viewport (e.g. scroll landed on the last
                // question and it sits within the dead zone or near the document bottom).
                var startIdxDown = nearestBelowIdx >= 0 ? nearestBelowIdx
                    : thread.PromptNavIndex >= 0 && thread.PromptNavIndex + 1 < thread.PromptParagraphs.Count
                        ? thread.PromptNavIndex + 1 : -1;
                SquadDashTrace.Write(TraceCategory.TranscriptNav,
                    $"PromptNavDown (Alt): nearestBelowIdx={nearestBelowIdx} navIndex={thread.PromptNavIndex} " +
                    $"startIdxDown={startIdxDown} totalPrompts={thread.PromptParagraphs.Count}");
                if (startIdxDown < 0)
                {
                    SquadDashTrace.Write(TraceCategory.TranscriptNav, "PromptNavDown (Alt): startIdxDown=-1, returning early — highlight preserved");
                    return;
                }
                for (int i = startIdxDown; i < thread.PromptParagraphs.Count; i++)
                {
                    var text = new System.Windows.Documents.TextRange(
                        thread.PromptParagraphs[i].Paragraph.ContentStart,
                        thread.PromptParagraphs[i].Paragraph.ContentEnd).Text;
                    if (text.Contains('?'))
                    {
                        SquadDashTrace.Write(TraceCategory.TranscriptNav,
                            $"PromptNavDown (Alt): found '?' at index={i}, navigating");
                        ClearQuestionHighlightRuns();
                        thread.PromptNavIndex = i;
                        ScrollToPromptParagraph(thread.PromptParagraphs[i].Paragraph);
                        ApplyQuestionHighlight(thread.PromptParagraphs[i].Paragraph);
                        return;
                    }
                }
                SquadDashTrace.Write(TraceCategory.TranscriptNav,
                    $"PromptNavDown (Alt): no '?' found scanning from startIdxDown={startIdxDown} to end — highlight preserved");
                return;
            }

            ClearQuestionHighlightRuns();
            GetScrollBasedNavState(out _, out _, out _, out int nearestBelowIdx2);
            if (nearestBelowIdx2 < 0) return;

            thread.PromptNavIndex = nearestBelowIdx2;
            ScrollToPromptParagraph(thread.PromptParagraphs[nearestBelowIdx2].Paragraph);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(PromptNavDownButton_Click), ex);
        }
    }

    private TranscriptThoughtEntry GetOrCreateThoughtEntry(
        TranscriptTurnView turn,
        string? speaker)
    {
        var normalizedSpeaker = string.IsNullOrWhiteSpace(speaker)
            ? "Coordinator"
            : AgentThreadRegistry.HumanizeAgentName(speaker);
        var existing = GetLatestThoughtEntry(turn);
        if (existing is not null &&
            string.Equals(existing.Speaker, normalizedSpeaker, StringComparison.OrdinalIgnoreCase))
        {
            return existing;
        }

        return CreateThoughtEntry(turn, normalizedSpeaker);
    }

    private TranscriptThoughtEntry CreateThoughtEntry(
        TranscriptTurnView turn,
        string speaker,
        int? sequence = null)
    {
        var block = GetOrCreateThoughtBlock(turn);

        var textBlock = new TextBlock
        {
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 0, 0, 4)
        };
        block.ContentPanel.Children.Add(textBlock);

        var entry = new TranscriptThoughtEntry(
            turn,
            AllocateNarrativeSequence(turn, sequence),
            speaker,
            textBlock);
        turn.ThoughtEntries.Add(entry);
        block.ThoughtEntries.Add(entry);
        return entry;
    }

    private TranscriptThoughtBlockView GetOrCreateThoughtBlock(TranscriptTurnView turn)
    {
        var latestBlock = turn.ThoughtBlocks.LastOrDefault();
        if (latestBlock is not null)
        {
            var latestSeq = latestBlock.ThoughtEntries.LastOrDefault()?.Sequence
                            ?? latestBlock.Sequence;
            if (latestSeq > Math.Max(GetLatestThinkingBlockSequence(turn), GetLatestResponseSequence(turn)))
                return latestBlock;
        }

        return CreateThoughtBlock(turn);
    }

    private TranscriptThoughtBlockView CreateThoughtBlock(TranscriptTurnView turn, int? sequence = null)
    {
        var header = new TextBlock
        {
            Text = "Thinking...",
            FontWeight = FontWeights.SemiBold
        };
        header.SetResourceReference(TextBlock.ForegroundProperty, "ThinkingText");

        var contentPanel = new StackPanel
        {
            Margin = new Thickness(18, 4, 0, 4)
        };

        var expander = new Expander
        {
            Header = header,
            Content = contentPanel,
            IsExpanded = true,
            Background = Brushes.Transparent,
            BorderBrush = Brushes.Transparent,
            Margin = new Thickness(0, 0, 0, 6)
        };
        if (TryFindResource("TranscriptExpanderStyle") is Style expanderStyle)
            expander.Style = expanderStyle;

        var container = new BlockUIContainer(expander);
        turn.NarrativeSection.Blocks.Add(container);

        var block = new TranscriptThoughtBlockView(
            turn,
            AllocateNarrativeSequence(turn, sequence),
            header,
            expander,
            contentPanel);
        container.Tag = block;
        block.StartedAt = DateTimeOffset.Now;
        turn.ThoughtBlocks.Add(block);
        expander.Expanded += (_, _) => { if (!_programmaticExpanderChange) block.UserPinnedOpen = true; };
        expander.Collapsed += (_, _) => { if (!_programmaticExpanderChange) block.UserPinnedOpen = false; };
        expander.ContextMenu = CreateThinkingContextMenu(turn);
        return block;
    }

    private void RenderPersistedThought(TranscriptTurnView turn, TranscriptThoughtRecord thought)
    {
        var entry = CreateThoughtEntry(turn, AgentThreadRegistry.HumanizeAgentName(thought.Speaker), thought.Sequence);
        entry.RawTextBuilder.Append(thought.Text);
        RenderThoughtEntry(entry);
    }

    private void RenderPersistedResponse(TranscriptTurnView turn, TranscriptResponseSegmentRecord responseSegment, bool allowQuickReplies = false)
    {
        var entry = CreateResponseEntry(turn, responseSegment.Sequence);
        entry.AllowQuickReplies = allowQuickReplies;
        // Raw protocol payloads remain durable in the conversation record and diagnostics,
        // but historical transcript turns should not regain orphaned "JSON received" buttons.
        entry.ProtocolJsonBlocks = [];
        entry.RawTextBuilder.Append(responseSegment.Text);
        RenderResponseEntry(entry);
    }

    private static TranscriptThoughtEntry? GetLatestThoughtEntry(TranscriptTurnView turn)
    {
        var latestThought = turn.ThoughtEntries.LastOrDefault();
        if (latestThought is null)
            return null;

        return latestThought.Sequence > Math.Max(
                GetLatestHostNoticeSequence(turn),
                Math.Max(GetLatestThinkingBlockSequence(turn), GetLatestResponseSequence(turn)))
            ? latestThought
            : null;
    }

    private static TranscriptThinkingBlockView? GetLatestThinkingBlock(TranscriptTurnView turn)
    {
        var latestBlock = turn.ThinkingBlocks.LastOrDefault();
        if (latestBlock is null)
            return null;

        return latestBlock.Sequence > Math.Max(
                GetLatestHostNoticeSequence(turn),
                Math.Max(GetLatestThoughtSequence(turn), GetLatestResponseSequence(turn)))
            ? latestBlock
            : null;
    }

    private static TranscriptResponseEntry? GetLatestResponseEntry(TranscriptTurnView turn)
    {
        var latestResponse = turn.ResponseEntries.LastOrDefault();
        if (latestResponse is null)
            return null;

        return latestResponse.Sequence > Math.Max(
                GetLatestHostNoticeSequence(turn),
                Math.Max(GetLatestThoughtSequence(turn), GetLatestThinkingBlockSequence(turn)))
            ? latestResponse
            : null;
    }

    private static int GetLatestThoughtSequence(TranscriptTurnView turn)
    {
        return turn.ThoughtEntries.LastOrDefault()?.Sequence ?? 0;
    }

    private static int GetLatestThinkingBlockSequence(TranscriptTurnView turn)
    {
        return turn.ThinkingBlocks.LastOrDefault()?.Sequence ?? 0;
    }

    private static int GetLatestResponseSequence(TranscriptTurnView turn)
    {
        return turn.ResponseEntries.LastOrDefault()?.Sequence ?? 0;
    }

    private static int GetLatestHostNoticeSequence(TranscriptTurnView turn)
    {
        return turn.HostNotices.LastOrDefault()?.Sequence ?? 0;
    }

    private static int AllocateNarrativeSequence(TranscriptTurnView turn, int? explicitSequence = null)
    {
        if (explicitSequence is { } sequence && sequence > 0)
        {
            turn.NextNarrativeSequence = Math.Max(turn.NextNarrativeSequence, sequence + 1);
            return sequence;
        }

        return turn.NextNarrativeSequence++;
    }

    private TranscriptResponseEntry GetOrCreateResponseEntry(TranscriptTurnView turn)
    {
        var latest = GetLatestResponseEntry(turn);
        if (latest is not null)
            return latest;

        return CreateResponseEntry(turn);
    }

    private TranscriptResponseEntry CreateResponseEntry(TranscriptTurnView turn, int? sequence = null)
    {
        var section = new Section();
        turn.NarrativeSection.Blocks.Add(section);
        var entry = new TranscriptResponseEntry(turn, AllocateNarrativeSequence(turn, sequence), section);
        turn.ResponseEntries.Add(entry);
        return entry;
    }

    private void RenderThoughtEntry(TranscriptThoughtEntry thought)
    {
        var text = FormatThinkingText(thought.RawTextBuilder.ToString());
        if (string.IsNullOrWhiteSpace(text))
        {
            thought.TextBlock.Inlines.Clear();
            return;
        }

        thought.TextBlock.Inlines.Clear();
        var prefixRun = new Run($"{thought.Speaker}: ") { FontWeight = FontWeights.SemiBold };
        prefixRun.SetResourceReference(TextElement.ForegroundProperty, "ThinkingText");
        thought.TextBlock.Inlines.Add(prefixRun);
        ThinkingInlineFormatter.AppendTo(thought.TextBlock.Inlines, text);
    }

    private static string NormalizeThinkingChunk(string? text)
    {
        return string.IsNullOrEmpty(text)
            ? string.Empty
            : text.Replace("\r\n", "\n").Replace('\r', '\n');
    }

    internal static string FormatThinkingText(string? text) =>
        TranscriptTextUtilities.FormatThinkingText(text);

    private Brush ResolveThoughtBrush(string speaker)
    {
        if (string.Equals(speaker, "Coordinator", StringComparison.OrdinalIgnoreCase) ||
            string.Equals(speaker, "Squad", StringComparison.OrdinalIgnoreCase))
        {
            return FindAgentAccentBrush("Squad") ?? Brushes.DarkGoldenrod;
        }

        return FindAgentAccentBrush(speaker) ?? Brushes.DarkGoldenrod;
    }

    private Brush? FindAgentAccentBrush(string speaker)
    {
        var card = _agents.FirstOrDefault(agent =>
            string.Equals(agent.Name, speaker, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(agent.AccentStorageKey, speaker, StringComparison.OrdinalIgnoreCase));
        return card?.EffectiveAccentBrush;
    }

    private void CollapseCurrentTurnThinking() =>
        CollapseCurrentTurnThinking(CoordinatorThread);

    private void CollapseCurrentTurnThinking(TranscriptThreadState thread)
    {
        if (thread.CurrentTurn is null)
            return;

        foreach (var block in thread.CurrentTurn.ThinkingBlocks)
        {
            if (block.UserPinnedOpen)
                continue;

            if (block.Expander.IsExpanded &&
                block.LastUpdatedAt is { } lastUpdatedAt &&
                lastUpdatedAt > block.StartedAt)
            {
                SetCollapsedBlockHeader(block.HeaderTextBlock, "Tooling...",
                    StatusTimingPresentation.FormatDuration(lastUpdatedAt - block.StartedAt),
                    ComputeBlockEditDiff(block));
            }

            SetExpanderOpen(block.Expander, false);
        }

        CollapseCurrentTurnThoughts(thread);
    }

    private void CollapseCurrentTurnThoughts(TranscriptThreadState thread)
    {
        if (thread.CurrentTurn is null)
            return;

        FlushPendingThoughtRendersForTurn(thread.CurrentTurn);

        foreach (var block in thread.CurrentTurn.ThoughtBlocks)
        {
            if (block.UserPinnedOpen)
                continue;

            if (block.Expander.IsExpanded &&
                block.LastUpdatedAt is { } lastUpdatedAt &&
                lastUpdatedAt > block.StartedAt)
            {
                SetCollapsedBlockHeader(block.HeaderTextBlock, "Thinking...",
                    StatusTimingPresentation.FormatDuration(lastUpdatedAt - block.StartedAt));
            }

            SetExpanderOpen(block.Expander, false);
        }
    }

    private static void SetCollapsedBlockHeader(
        TextBlock header,
        string label,
        string? duration = null,
        (int added, int removed)? diffAggregate = null)
    {
        header.Text = string.Empty;
        header.Inlines.Clear();
        var labelRun = new Run(label) { FontWeight = FontWeights.SemiBold };
        header.Inlines.Add(labelRun);
        if (diffAggregate is { } diff && (diff.added > 0 || diff.removed > 0))
        {
            if (diff.added > 0)
            {
                var addedRun = new Run($" +{diff.added}") { FontWeight = FontWeights.SemiBold };
                addedRun.SetResourceReference(TextElement.ForegroundProperty, "DiffAddedSummary");
                header.Inlines.Add(addedRun);
            }
            if (diff.removed > 0)
            {
                var removedRun = new Run($" -{diff.removed}") { FontWeight = FontWeights.SemiBold };
                removedRun.SetResourceReference(TextElement.ForegroundProperty, "DiffRemovedSummary");
                header.Inlines.Add(removedRun);
            }
        }
        if (!string.IsNullOrWhiteSpace(duration))
        {
            var durationRun = new Run($" {duration}") { FontWeight = FontWeights.Normal };
            durationRun.SetResourceReference(TextElement.ForegroundProperty, "ThinkingMetaText");
            header.Inlines.Add(durationRun);
        }
    }

    private static (int added, int removed) ComputeBlockEditDiff(TranscriptThinkingBlockView block)
    {
        var added   = 0;
        var removed = 0;
        foreach (var entry in block.ToolEntries)
        {
            if (!entry.IsCompleted || !entry.Success) continue;
            var diff = ToolTranscriptFormatter.TryBuildEditDiffSummary(entry.Descriptor, entry.OutputText, entry.ArgsJson);
            if (diff is null) continue;
            added   += diff.AddedLineCount;
            removed += diff.RemovedLineCount;
        }
        return (added, removed);
    }

    private void SetExpanderOpen(Expander expander, bool open)
    {
        _programmaticExpanderChange = true;
        try { expander.IsExpanded = open; }
        finally { _programmaticExpanderChange = false; }
    }
    private void StartToolExecution(SquadSdkEvent evt) =>
        StartToolExecution(CoordinatorThread, evt);

    private void StartToolExecution(TranscriptThreadState thread, SquadSdkEvent evt)
    {
        if (!TryGetOrCreateToolEntry(thread, evt, out var entry))
            return;

        CapturePlanAwareBackgroundAgentLaunch(thread, evt);

        if (!string.IsNullOrWhiteSpace(evt.ProgressMessage))
            entry.ProgressText = evt.ProgressMessage;

        // When the AI uses multiple consecutive tools, the thinking block is reused (not
        // reallocated for the 2nd+ tool), so GetLatestResponseEntry still finds the
        // post-previous-tool response entry. Without an explicit paragraph break here, the
        // post-this-tool streaming text would fuse inline with whatever text already ends
        // that entry (e.g. "rendered).Committed"). Injecting \n\n closes the paragraph now.
        if (thread.CurrentTurn is { } turn)
        {
            TranscriptTextUtilities.EnsureResponseParagraphBreak(turn.ResponseTextBuilder);

            var responseEntry = GetLatestResponseEntry(turn);
            if (responseEntry is not null)
                TranscriptTextUtilities.EnsureResponseParagraphBreak(responseEntry.RawTextBuilder);
        }

        EnsureCurrentTurnThinkingVisible(thread);
        RenderToolEntry(entry);
        UpdateToolSpinnerState();
        if (thread.Kind == TranscriptThreadKind.Coordinator)
        {
            SyncActiveToolName();
            UpdateLeadAgent(
                "Tooling",
                string.Empty,
                ToolTranscriptFormatter.BuildRunningText(entry.Descriptor, entry.ProgressText));
            UpdateSessionState("Using tool");
        }

        ScrollToEndIfAtBottom(thread);
    }

    private void UpdateToolExecution(SquadSdkEvent evt) =>
        UpdateToolExecution(CoordinatorThread, evt);

    private void UpdateToolExecution(TranscriptThreadState thread, SquadSdkEvent evt)
    {
        if (!TryGetOrCreateToolEntry(thread, evt, out var entry))
            return;

        if (!string.IsNullOrWhiteSpace(evt.ProgressMessage))
            entry.ProgressText = evt.ProgressMessage;
        if (!string.IsNullOrWhiteSpace(evt.PartialOutput))
            entry.OutputText = ToolTranscriptOutputLimiter.TrimForLiveTranscript(
                entry.Descriptor,
                MergeToolOutput(entry.OutputText, evt.PartialOutput));

        // Update elapsed+poll display for coalesced read_agent polls.
        if (entry.PollCount > 0 &&
            string.Equals(entry.Descriptor.ToolName, "read_agent", StringComparison.OrdinalIgnoreCase))
        {
            var elapsed = StatusTimingPresentation.FormatDuration(DateTimeOffset.Now - entry.StartedAt);
            entry.ProgressText = $"poll {entry.PollCount} · {elapsed}";
        }

        EnsureCurrentTurnThinkingVisible(thread);
        RenderToolEntry(entry);
        UpdateToolSpinnerState();
        if (thread.Kind == TranscriptThreadKind.Coordinator)
        {
            SyncActiveToolName();
            UpdateLeadAgent(
                "Tooling",
                string.Empty,
                ToolTranscriptFormatter.BuildRunningText(entry.Descriptor, entry.ProgressText));
            UpdateSessionState("Using tool");
        }

        ScrollToEndIfAtBottom(thread);
    }

    private void CompleteToolExecution(SquadSdkEvent evt) =>
        CompleteToolExecution(CoordinatorThread, evt);

    private void CapturePlanAwareBackgroundAgentLaunch(
        TranscriptThreadState ownerThread,
        SquadSdkEvent evt)
    {
        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        var attempt = execution?.PlanExecutionAttempt;
        var launch = _agentThreadRegistry.CaptureBackgroundAgentLaunchInfo(
            evt,
            attempt,
            ownerThread.Kind == TranscriptThreadKind.Coordinator,
            ownerThread.Kind == TranscriptThreadKind.Agent ? ownerThread.ToolCallId : null);
        if (launch is null || execution is null || attempt is null)
            return;

        var updated = PlanExecutionEvidenceRecorder.RecordLaunch(
            attempt,
            launch,
            ownerThread.Kind == TranscriptThreadKind.Coordinator,
            ownerThread.Kind == TranscriptThreadKind.Agent ? ownerThread.ToolCallId : null);

        _conversationManager.UpdateActiveLoopExecutionState(
            execution with { PlanExecutionAttempt = updated });
    }

    private void DiscardUnstartedPlanAgentLaunch(SquadSdkEvent evt)
    {
        if (evt.Success != false || string.IsNullOrWhiteSpace(evt.ToolCallId))
            return;
        var failureDetail = string.Join(
            "\n",
            new[] { evt.OutputText, evt.Reason, evt.Message, evt.Description }
                .Where(value => !string.IsNullOrWhiteSpace(value)));
        var agentThreadObserved =
            _agentThreadRegistry.ThreadsByToolCallId.ContainsKey(evt.ToolCallId);
        if (!PlanAgentLaunchFailurePolicy.ShouldDiscardLaunch(
                evt.Success,
                evt.ToolName,
                agentThreadObserved,
                failureDetail))
            return;

        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        var attempt = execution?.PlanExecutionAttempt;
        if (execution is null || attempt is null)
            return;
        var updated = attempt.DiscardRejectedLaunch(evt.ToolCallId);
        if (!Equals(updated, attempt))
            _conversationManager.UpdateActiveLoopExecutionState(
                execution with { PlanExecutionAttempt = updated });
    }

    private void RecordPlanContextRead(TranscriptThreadState thread, SquadSdkEvent evt)
    {
        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        var attempt = execution?.PlanExecutionAttempt;
        if (execution is null || attempt is null || string.IsNullOrWhiteSpace(thread.ToolCallId))
            return;

        var path = PlanContextReadEvidence.TryResolveFullPath(evt, attempt.WorkspacePath);
        if (path is null)
            return;
        var updated = attempt.RecordContextRead(thread.ToolCallId, path);
        if (!Equals(updated, attempt))
            _conversationManager.UpdateActiveLoopExecutionState(
                execution with { PlanExecutionAttempt = updated });
    }

    private void RecordPlanAgentCompletion(
        TranscriptThreadState thread,
        SquadSdkEvent evt,
        bool succeeded)
    {
        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        var attempt = execution?.PlanExecutionAttempt;
        if (execution is null || attempt is null || string.IsNullOrWhiteSpace(thread.ToolCallId))
            return;

        var completedAt = TryParseTimestamp(evt.FinishedAt) ?? DateTimeOffset.UtcNow;
        var updated = attempt.RecordPrimaryCompletion(thread.ToolCallId, completedAt, succeeded);
        if (!Equals(updated, attempt))
            _conversationManager.UpdateActiveLoopExecutionState(
                execution with { PlanExecutionAttempt = updated });
    }

    private void CompleteToolExecution(TranscriptThreadState thread, SquadSdkEvent evt)
    {
        if (!TryGetOrCreateToolEntry(thread, evt, out var entry))
            return;

        if (evt.Success == false)
            DiscardUnstartedPlanAgentLaunch(evt);
        else
            CapturePlanAwareBackgroundAgentLaunch(thread, evt);

        entry.IsCompleted = true;
        entry.Success = evt.Success ?? true;
        entry.FinishedAt = ParseTimestamp(evt.FinishedAt);

        if (thread.Kind == TranscriptThreadKind.Agent && (evt.Success ?? true))
            RecordPlanContextRead(thread, evt);

        if (entry.FinishedAt is { } finishedAt)
            entry.ThinkingBlock.LastUpdatedAt = finishedAt;

        if (!string.IsNullOrWhiteSpace(evt.OutputText))
            entry.OutputText = ToolTranscriptOutputLimiter.TrimForLiveTranscript(
                entry.Descriptor,
                evt.OutputText);

        if (thread.Kind == TranscriptThreadKind.Coordinator)
            TraceCoordinatorToolCompletion(evt, entry);

        entry.DetailContent = ToolTranscriptFormatter.BuildDetailContent(new ToolTranscriptDetail(
            entry.Descriptor,
            entry.ArgsJson,
            entry.OutputText,
            entry.StartedAt,
            entry.FinishedAt,
            entry.ProgressText,
            entry.IsCompleted,
            entry.Success));

        RenderToolEntry(entry);
        UpdateToolSpinnerState();
        if (thread.Kind == TranscriptThreadKind.Coordinator)
        {
            SyncActiveToolName();
            if (string.IsNullOrWhiteSpace(_pec.ActiveToolName))
                UpdateSessionState("Running");
            else
                UpdateSessionState("Using tool");
        }

        ScrollToEndIfAtBottom(thread);
    }

    private void TraceCoordinatorToolCompletion(SquadSdkEvent evt, ToolTranscriptEntry entry)
    {
        var toolName = entry.Descriptor.ToolName;
        if (string.Equals(toolName, "read_agent", StringComparison.OrdinalIgnoreCase))
        {
            TraceCoordinatorReadAgentCompletion(evt, entry);
            return;
        }

        if (string.Equals(toolName, "task", StringComparison.OrdinalIgnoreCase) &&
            entry.Success == false &&
            IsMaximumConcurrentAgentLimit(entry.OutputText ?? evt.OutputText))
        {
            var requestedName = TryGetJsonString(evt.Args, "name") ?? "(unknown)";
            SquadDashTrace.Write(
                "Agents",
                $"TaskLaunch.Blocked reason=max_concurrent requested={requestedName} toolCallId={evt.ToolCallId ?? "(none)"} active={BuildActiveBackgroundAgentTraceList()} outputChars={evt.OutputText?.Length ?? 0}");
        }
    }

    private void TraceCoordinatorReadAgentCompletion(SquadSdkEvent evt, ToolTranscriptEntry entry)
    {
        var requestedAgentId = TryGetJsonString(evt.Args, "agent_id") ?? "(unknown)";
        var wait = TryGetJsonBool(evt.Args, "wait");
        var output = entry.OutputText ?? evt.OutputText ?? string.Empty;
        var outcome = BuildReadAgentOutcome(entry.Success, output);
        var local = BuildReadAgentLocalState(requestedAgentId);
        var message =
            $"ReadAgent.Resolve requested={requestedAgentId} wait={wait?.ToString() ?? "(unknown)"} outcome={outcome} success={entry.Success} toolCallId={evt.ToolCallId ?? "(none)"} " +
            $"rawOutputChars={evt.OutputText?.Length ?? 0} transcriptOutputChars={entry.OutputText?.Length ?? 0} placeholder={IsReadAgentPlaceholder(output)} {local}";

        if (string.Equals(outcome, "not_found", StringComparison.OrdinalIgnoreCase))
        {
            NoteCoordinatorToolFailure(
                "read_agent",
                requestedAgentId,
                "Agent not found",
                message);
            return;
        }

        SquadDashTrace.Write("Agents", message);
    }

    private string BuildReadAgentLocalState(string requestedAgentId)
    {
        var matchingAgent = _backgroundTaskPresenter.BackgroundAgents.FirstOrDefault(agent =>
            MatchesAgentReadId(agent, requestedAgentId));
        var snapshotStatus = matchingAgent?.Status?.Trim();
        var snapshotLive = matchingAgent is not null && !AgentThreadRegistry.IsTerminalBackgroundStatus(snapshotStatus);

        var thread = string.Equals(requestedAgentId, "(unknown)", StringComparison.Ordinal)
            ? null
            : _agentThreadRegistry.FindExistingAgentThread(
                toolCallId: null,
                agentId: requestedAgentId,
                agentName: null,
                agentDisplayName: null);
        var threadTerminal = thread is not null && AgentThreadRegistry.IsTerminalBackgroundStatus(thread.StatusText);
        return
            $"snapshotMatch={matchingAgent is not null} snapshotLive={snapshotLive} snapshotStatus={snapshotStatus ?? "(none)"} " +
            $"threadMatch={thread is not null} threadId={thread?.ThreadId ?? "(none)"} threadStatus={thread?.StatusText ?? "(none)"} threadTerminal={threadTerminal} " +
            $"threadResponseChars={thread?.LatestResponse?.Length ?? 0} threadLastAnnouncedChars={thread?.LastCoordinatorAnnouncedResponse?.Length ?? 0}";
    }

    private static bool MatchesAgentReadId(SquadBackgroundAgentInfo agent, string requestedAgentId)
    {
        if (string.IsNullOrWhiteSpace(requestedAgentId) || string.Equals(requestedAgentId, "(unknown)", StringComparison.Ordinal))
            return false;

        return string.Equals(agent.AgentId?.Trim(), requestedAgentId, StringComparison.OrdinalIgnoreCase) ||
               string.Equals(agent.ToolCallId?.Trim(), requestedAgentId, StringComparison.OrdinalIgnoreCase) ||
               string.Equals(agent.AgentName?.Trim(), requestedAgentId, StringComparison.OrdinalIgnoreCase) ||
               string.Equals(agent.AgentDisplayName?.Trim(), requestedAgentId, StringComparison.OrdinalIgnoreCase);
    }

    private string BuildActiveBackgroundAgentTraceList()
    {
        var active = _backgroundTaskPresenter.BackgroundAgents
            .Where(agent => !AgentThreadRegistry.IsTerminalBackgroundStatus(agent.Status))
            .Take(8)
            .Select(agent =>
                $"{agent.AgentId ?? "(no-id)"}/{agent.ToolCallId ?? "(no-tool)"}/{agent.Status ?? "(no-status)"}")
            .ToArray();

        return active.Length == 0 ? "[]" : "[" + string.Join(",", active) + "]";
    }

    private void NoteCoordinatorToolFailure(
        string toolName,
        string identity,
        string error,
        string traceMessage)
    {
        var key = toolName + "\n" + identity + "\n" + error;
        var now = DateTimeOffset.Now;
        if (!_coordinatorToolFailureTraces.TryGetValue(key, out var state))
        {
            state = new CoordinatorToolFailureTraceState {
                Count = 0,
                FirstSeenAt = now
            };
            _coordinatorToolFailureTraces[key] = state;
        }

        state.Count++;
        var shouldTrace = state.Count == 1 ||
                          state.Count == CoordinatorToolFailureTraceThreshold ||
                          state.Count % CoordinatorToolFailureTraceEvery == 0;
        if (!shouldTrace)
            return;

        var elapsedSeconds = Math.Max(0, (now - state.FirstSeenAt).TotalSeconds);
        SquadDashTrace.Write(
            "Agents",
            $"{traceMessage} repeatedFailureCount={state.Count} repeatedFailureElapsedSec={elapsedSeconds:0}");
    }

    private static string BuildReadAgentOutcome(bool success, string output)
    {
        if (success)
            return "success";

        if (output.Contains("Agent not found", StringComparison.OrdinalIgnoreCase))
            return "not_found";

        return output.Contains("Code: failure", StringComparison.OrdinalIgnoreCase)
            ? "failure"
            : "unknown_failure";
    }

    private static bool IsMaximumConcurrentAgentLimit(string? output) =>
        !string.IsNullOrWhiteSpace(output) &&
        output.Contains("Maximum concurrent agent limit", StringComparison.OrdinalIgnoreCase);

    private static bool IsReadAgentPlaceholder(string output) =>
        output.Contains("(Full response provided to agent)", StringComparison.OrdinalIgnoreCase);

    private bool TryGetOrCreateToolEntry(
        TranscriptThreadState thread,
        SquadSdkEvent evt,
        out ToolTranscriptEntry entry)
    {
        var toolCallId = evt.ToolCallId?.Trim();
        var hasToolCallId = !string.IsNullOrWhiteSpace(toolCallId);
        ToolTranscriptEntry existingEntry = null!;
        var hasExistingEntry = hasToolCallId &&
                               _agentThreadRegistry.TryGetToolEntry(toolCallId!, out existingEntry);
        var routing = ToolEventRoutingPolicy.Resolve(
            hasToolCallId,
            hasExistingEntry,
            thread.CurrentTurn is not null);

        if (routing == ToolEventRoutingDecision.Ignore)
        {
            entry = null!;
            return false;
        }

        if (routing == ToolEventRoutingDecision.UseExistingEntry)
        {
            entry = existingEntry!;
            SyncTaskToolTranscriptLink(entry);
            return true;
        }

        // ToolEventRoutingPolicy only permits creation while a turn is active.
        var currentTurn = thread.CurrentTurn!;

        // Coalesce consecutive read_agent polls for the same agent_id into one row.
        if (string.Equals(evt.ToolName, "read_agent", StringComparison.OrdinalIgnoreCase))
        {
            var agentId = TryGetJsonString(evt.Args, "agent_id");
            if (!string.IsNullOrWhiteSpace(agentId))
            {
                var existing = ReadAgentSatelliteCoalescer.FindActiveEntry(currentTurn.ToolEntries, agentId);
                if (existing is not null)
                {
                    existing.PollCount++;
                    _agentThreadRegistry.SetToolEntry(toolCallId!, existing);
                    SyncTaskToolTranscriptLink(existing);
                    entry = existing;
                    return true;
                }
            }
        }

        entry = CreateToolEntry(
            GetOrCreateThinkingBlockForNewTool(currentTurn),
            toolCallId!,
            CreateToolDescriptor(evt),
            TryFormatJson(evt.Args),
            ParseTimestamp(evt.StartedAt));
        _agentThreadRegistry.SetToolEntry(toolCallId!, entry);
        return true;
    }

    private void SyncTaskToolTranscriptLink(TranscriptThreadState thread)
    {
        if (string.IsNullOrWhiteSpace(thread.ToolCallId) ||
            !_agentThreadRegistry.TryGetToolEntry(thread.ToolCallId, out var entry))
        {
            return;
        }

        entry.TranscriptThreadId = thread.ThreadId;
        SyncTaskToolTranscriptLink(entry);
    }

    private void SyncTaskToolTranscriptLink(ToolTranscriptEntry entry)
    {
        if (!string.Equals(entry.Descriptor.ToolName, "task", StringComparison.OrdinalIgnoreCase) &&
            !string.Equals(
                entry.Descriptor.ToolName,
                "delegate_temporary_agent",
                StringComparison.OrdinalIgnoreCase))
        {
            entry.TranscriptThreadId = null;
            entry.TranscriptButton.Visibility = Visibility.Collapsed;
            entry.TranscriptButton.ToolTip = null;
            return;
        }

        if (string.IsNullOrWhiteSpace(entry.TranscriptThreadId) &&
            _agentThreadRegistry.ThreadsByToolCallId.TryGetValue(entry.ToolCallId, out var thread))
        {
            entry.TranscriptThreadId = thread.ThreadId;
        }

        var isVisible = !string.IsNullOrWhiteSpace(entry.TranscriptThreadId);
        entry.TranscriptButton.Visibility = isVisible ? Visibility.Visible : Visibility.Collapsed;
        entry.TranscriptButton.ToolTip = isVisible ? MakeThemedToolTip("Open transcript") : null;
    }

    private ToolTranscriptEntry CreateToolEntry(
        TranscriptThinkingBlockView block,
        string toolCallId,
        ToolTranscriptDescriptor descriptor,
        string? argsJson,
        DateTimeOffset startedAt)
    {
        var iconTextBlock = new TextBlock
        {
            Text = ToolSpinnerFrames[_toolSpinnerFrame],
            Width = 24,
            FontFamily = new FontFamily("Segoe UI Symbol"),
            FontWeight = FontWeights.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        };
        iconTextBlock.SetResourceReference(TextBlock.ForegroundProperty, "ToolRunningIcon");

        var iconSize = ToolIconSizeForFontSize(_transcriptFontSize);
        var emojiImage = new Image
        {
            Width = iconSize,
            Height = iconSize,
            VerticalAlignment = VerticalAlignment.Center,
            Margin = new Thickness(2, 0, 4, 0)
        };
        System.Windows.Media.RenderOptions.SetBitmapScalingMode(emojiImage, System.Windows.Media.BitmapScalingMode.HighQuality);
        _toolIconImages.Add(emojiImage);

        var messageTextBlock = new TextBlock
        {
            TextWrapping = TextWrapping.Wrap,
            VerticalAlignment = VerticalAlignment.Center
        };
        messageTextBlock.SetResourceReference(TextBlock.ForegroundProperty, "ToolBodyText");

        var headerPanel = new StackPanel
        {
            Orientation = Orientation.Horizontal
        };
        headerPanel.Children.Add(iconTextBlock);
        headerPanel.Children.Add(emojiImage);
        headerPanel.Children.Add(messageTextBlock);

        var transcriptButton = new Button
        {
            Content = "Transcript",
            Visibility = Visibility.Collapsed,
            Margin = new Thickness(10, 0, 0, 0),
            Padding = new Thickness(8, 2, 8, 2),
            HorizontalAlignment = HorizontalAlignment.Left,
            VerticalAlignment = VerticalAlignment.Center,
        };
        transcriptButton.SetResourceReference(Control.StyleProperty, "TranscriptActionButtonStyle");
        headerPanel.Children.Add(transcriptButton);

        var detailTextBox = new TextBox
        {
            IsReadOnly = true,
            AcceptsReturn = true,
            TextWrapping = TextWrapping.Wrap,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Auto,
            FontFamily = new FontFamily("Consolas"),
            MinHeight = 140,
            MaxHeight = 260
        };
        detailTextBox.SetResourceReference(TextBox.BackgroundProperty, "CodeSurface");
        detailTextBox.SetResourceReference(TextBox.BorderBrushProperty, "InputBorder");
        detailTextBox.SetResourceReference(TextBox.ForegroundProperty, "LabelText");

        var detailPanel = new StackPanel
        {
            Margin = new Thickness(8, 6, 0, 2)
        };

        var expander = new Expander
        {
            Header = headerPanel,
            IsExpanded = false,
            Background = Brushes.Transparent,
            BorderBrush = Brushes.Transparent,
            Margin = new Thickness(0, 2, 0, 2)
        };
        if (TryFindResource("TranscriptExpanderStyle") is Style expanderStyle)
            expander.Style = expanderStyle;

        var entry = new ToolTranscriptEntry(
            toolCallId,
            block.Turn,
            block,
            descriptor,
            argsJson,
            startedAt,
            expander,
            iconTextBlock,
            emojiImage,
            messageTextBlock,
            detailTextBox,
            transcriptButton);
        block.Turn.ToolEntries.Add(entry);
        block.ToolEntries.Add(entry);

        // Refresh the coordinator intent label when a new tool entry arrives for it.
        if (entry.Turn.OwnerThread.Kind == TranscriptThreadKind.Coordinator)
            RestartCoordinatorIntentDebounce();
        // Refresh the agent secondary-transcript header when a report_intent arrives.
        else if (entry.Turn.OwnerThread.Kind == TranscriptThreadKind.Agent &&
                 string.Equals(entry.Descriptor.ToolName, "report_intent", StringComparison.OrdinalIgnoreCase))
            RestartAgentIntentDebounce(entry.Turn.OwnerThread);

        expander.ContextMenu = CreateToolBlockContextMenu(entry);
        headerPanel.ContextMenu = CreateThinkingContextMenu(block.Turn);
        iconTextBlock.ContextMenu = CreateThinkingContextMenu(block.Turn);
        emojiImage.ContextMenu = CreateThinkingContextMenu(block.Turn);
        messageTextBlock.ContextMenu = CreateThinkingContextMenu(block.Turn);
        transcriptButton.ContextMenu = CreateThinkingContextMenu(block.Turn);
        transcriptButton.Tag = entry;
        transcriptButton.Click += OpenToolTranscriptButton_Click;
        SyncTaskToolTranscriptLink(entry);

        detailPanel.Children.Add(detailTextBox);
        expander.Content = detailPanel;

        AttachToolTimingTooltip(headerPanel, entry);

        block.ContentPanel.Children.Add(expander);
        return entry;
    }

    private void AttachToolTimingTooltip(FrameworkElement headerPanel, ToolTranscriptEntry entry)
    {
        var toolTip = MakeThemedToolTip(string.Empty);
        if (toolTip.Content is not TextBlock toolTipTextBlock)
            return;

        DispatcherTimer? timer = null;

        void UpdateTooltipText()
        {
            var now = DateTimeOffset.UtcNow;
            toolTipTextBlock.Text = entry.IsCompleted
                ? ToolCallElapsedTimePresenter.BuildCompletedMessage(entry.StartedAt, entry.FinishedAt, now)
                : ToolCallElapsedTimePresenter.BuildRunningMessage(entry.StartedAt, now);
        }

        toolTip.Opened += (_, _) =>
        {
            UpdateTooltipText();

            if (entry.IsCompleted)
                return;

            timer ??= new DispatcherTimer(
                TimeSpan.FromSeconds(1),
                DispatcherPriority.Normal,
                (_, _) =>
                {
                    UpdateTooltipText();
                    if (entry.IsCompleted)
                        timer?.Stop();
                },
                Dispatcher);

            if (!timer.IsEnabled)
                timer.Start();
        };

        toolTip.Closed += (_, _) =>
        {
            if (timer?.IsEnabled == true)
                timer.Stop();
        };

        headerPanel.Unloaded += (_, _) =>
        {
            if (timer?.IsEnabled == true)
                timer.Stop();
        };

        headerPanel.ToolTip = toolTip;
    }

    private void RenderPersistedTool(TranscriptThinkingBlockView block, TranscriptToolRecord tool)
    {
        var toolCallId = string.IsNullOrWhiteSpace(tool.ToolCallId)
            ? Guid.NewGuid().ToString("N")
            : tool.ToolCallId;
        var entry = CreateToolEntry(
            block,
            toolCallId,
            tool.Descriptor,
            tool.ArgsJson,
            tool.StartedAt);
        _agentThreadRegistry.SetToolEntry(toolCallId, entry);

        entry.FinishedAt = tool.FinishedAt;
        entry.ProgressText = tool.ProgressText;
        entry.OutputText = ToolTranscriptOutputLimiter.TrimForLiveTranscript(entry.Descriptor, tool.OutputText);
        entry.DetailContent = ToolTranscriptOutputLimiter.TrimForLiveTranscript(entry.Descriptor, tool.DetailContent);
        entry.CapturedEdits = tool.CapturedEdits is { Count: > 0 }
            ? tool.CapturedEdits
            : ToolTranscriptFormatter.TryExtractCapturedEdits(
                entry.Descriptor, entry.OutputText, entry.ArgsJson);
        entry.IsCompleted = tool.IsCompleted;
        entry.Success = tool.Success;
        RenderToolEntry(entry);
    }

    private void RenderSuppressedToolsStub(TranscriptTurnView view, int count)
    {
        var label = count == 1 ? "Tooling... (1 tool)" : $"Tooling... ({count} tools)";
        var tb = new TextBlock
        {
            Text = label,
            FontWeight = FontWeights.SemiBold,
            Margin = new Thickness(0, 0, 0, 6),
            ToolTip = "Tooling output removed for transcript optimization"
        };
        tb.SetResourceReference(TextBlock.ForegroundProperty, "ThinkingText");
        view.NarrativeSection.Blocks.Add(new BlockUIContainer(tb));
    }

    private TranscriptThinkingBlockView GetOrCreateThinkingBlockForNewTool(TranscriptTurnView turn)
    {
        var latestBlock = GetLatestThinkingBlock(turn);
        if (latestBlock is not null)
        {
            latestBlock.Expander.IsExpanded = true;
            return latestBlock;
        }

        return CreateThinkingBlock(turn, isExpanded: true);
    }

    private TranscriptThinkingBlockView CreateThinkingBlock(
        TranscriptTurnView turn,
        int? sequence = null,
        bool isExpanded = true)
    {
        var header = new TextBlock
        {
            Text = "Tooling...",
            FontWeight = FontWeights.SemiBold
        };
        header.SetResourceReference(TextBlock.ForegroundProperty, "ThinkingText");

        var contentPanel = new StackPanel
        {
            Margin = new Thickness(18, 4, 0, 2)
        };

        var expander = new Expander
        {
            Header = header,
            Content = contentPanel,
            IsExpanded = isExpanded,
            Background = Brushes.Transparent,
            BorderBrush = Brushes.Transparent,
            Margin = new Thickness(0, 0, 0, 6)
        };
        if (TryFindResource("TranscriptExpanderStyle") is Style expanderStyle)
            expander.Style = expanderStyle;

        var container = new BlockUIContainer(expander);
        turn.NarrativeSection.Blocks.Add(container);

        var block = new TranscriptThinkingBlockView(
            turn,
            AllocateNarrativeSequence(turn, sequence),
            header,
            expander,
            contentPanel);
        container.Tag = block;
        block.StartedAt = DateTimeOffset.Now;
        turn.ThinkingBlocks.Add(block);
        expander.Expanded += (_, _) =>
        {
            if (!_programmaticExpanderChange) block.UserPinnedOpen = true;
            // When re-opened, hide the collapsed diff aggregate — only shown when closed.
            block.HeaderTextBlock.Inlines.Clear();
            block.HeaderTextBlock.Inlines.Add(new Run("Tooling...") { FontWeight = FontWeights.SemiBold });
        };
        expander.Collapsed += (_, _) =>
        {
            if (!_programmaticExpanderChange) block.UserPinnedOpen = false;
            var duration = block.LastUpdatedAt is { } lastUpdated && lastUpdated > block.StartedAt
                ? StatusTimingPresentation.FormatDuration(lastUpdated - block.StartedAt)
                : null;
            SetCollapsedBlockHeader(block.HeaderTextBlock, "Tooling...", duration, ComputeBlockEditDiff(block));
        };
        header.ContextMenu = CreateThinkingContextMenu(turn);
        expander.ContextMenu = CreateThinkingContextMenu(turn);
        return block;
    }

    private void RenderToolEntry(ToolTranscriptEntry entry)
    {
        SyncTaskToolTranscriptLink(entry);
        entry.IconTextBlock.Text = entry.IsCompleted
            ? entry.Success ? "✔️" : "⚠"
            : ToolSpinnerFrames[_toolSpinnerFrame];
        entry.IconTextBlock.SetResourceReference(TextBlock.ForegroundProperty,
            entry.IsCompleted
                ? (entry.Success ? "ToolSuccessIcon" : "ToolFailureIcon")
                : "ToolRunningIcon");
        entry.MessageTextBlock.SetResourceReference(TextBlock.ForegroundProperty,
            entry.IsCompleted && !entry.Success ? "ToolFailureText" : "ToolBodyText");
        entry.MessageTextBlock.Inlines.Clear();
        RenderToolMessage(entry);
        entry.DetailTextBox.Text = entry.DetailContent ?? ToolTranscriptFormatter.BuildDetailContent(new ToolTranscriptDetail(
            entry.Descriptor,
            entry.ArgsJson,
            entry.OutputText,
            entry.StartedAt,
            entry.FinishedAt,
            entry.ProgressText,
            entry.IsCompleted,
            entry.Success));
    }

    private void RenderToolMessage(ToolTranscriptEntry entry)
    {
        var iconKey = ToolTranscriptFormatter.ResolveToolIconKey(entry.Descriptor.ToolName);
        if (entry.Descriptor.ToolName.Trim() == "read_powershell" && entry.ArgsJson is { } argsJsonForIcon)
        {
            try
            {
                using var doc = JsonDocument.Parse(argsJsonForIcon);
                if (doc.RootElement.TryGetProperty("delay", out var delayEl) &&
                    delayEl.TryGetDouble(out var delayVal) &&
                    delayVal >= 30)
                {
                    iconKey = "ToolIcon_read_powershell_waiting";
                }
            }
            catch { }
        }
        entry.EmojiImage.Source = (TryFindResource(iconKey) ?? TryFindResource("ToolIcon_default"))
            as System.Windows.Media.ImageSource;
        entry.EmojiImage.Visibility = entry.EmojiImage.Source is not null
            ? Visibility.Visible : Visibility.Collapsed;

        if (entry.IsCompleted && entry.Success)
            entry.CapturedEdits ??= ToolTranscriptFormatter.TryExtractCapturedEdits(
                entry.Descriptor, entry.OutputText, entry.ArgsJson);

        if (entry.IsCompleted &&
            entry.Success &&
            ToolEditLinkPresenter.TryRender(
                entry.MessageTextBlock,
                entry.Descriptor,
                entry.OutputText,
                entry.ArgsJson,
                entry.CapturedEdits,
                async clickedEdit =>
                {
                    var originatingCall = new CapturedEditCall(
                        entry.ToolCallId,
                        entry.StartedAt,
                        entry.CapturedEdits ?? Array.Empty<CapturedFileEdit>());
                    var viewer = await CommitViewerWindow.CreateFromCapturedEditsAsync(
                        originatingCall,
                        clickedEdit.Path,
                        () => BuildCapturedTurnEdits(entry.Turn));
                    viewer.ConfigureEnvironmentFontZoom(Window_PreviewMouseWheel);
                    if (CanShowOwnedWindow())
                        viewer.Owner = this;
                    viewer.Show();
                }))
        {
            return;
        }

        var rawText = entry.IsCompleted
            ? ToolTranscriptFormatter.BuildCompletedText(entry.Descriptor, entry.Success, entry.ProgressText, entry.OutputText)
            : ToolTranscriptFormatter.BuildRunningText(entry.Descriptor, entry.ProgressText);

        // Strip any emoji prefix the formatter prepended — the icon is now shown as a DrawingImage
        var toolEmoji = ToolTranscriptFormatter.GetToolEmoji(entry.Descriptor);
        entry.MessageTextBlock.Text = !string.IsNullOrEmpty(toolEmoji) && rawText.StartsWith(toolEmoji, StringComparison.Ordinal)
            ? rawText[toolEmoji.Length..].TrimStart(' ')
            : rawText;
    }

    private static IReadOnlyList<CapturedEditCall> BuildCapturedTurnEdits(TranscriptTurnView turn) {
        var calls = new List<CapturedEditCall>();
        foreach (var entry in turn.ToolEntries
                     .Where(candidate => candidate.IsCompleted && candidate.Success)
                     .OrderBy(candidate => candidate.StartedAt)) {
            entry.CapturedEdits ??= ToolTranscriptFormatter.TryExtractCapturedEdits(
                entry.Descriptor, entry.OutputText, entry.ArgsJson);
            if (entry.CapturedEdits.Count == 0)
                continue;
            calls.Add(new CapturedEditCall(entry.ToolCallId, entry.StartedAt, entry.CapturedEdits));
        }
        return calls;
    }

    private void AdvanceToolSpinner()
    {
        _toolSpinnerFrame = (_toolSpinnerFrame + 1) % ToolSpinnerFrames.Length;

        _plansPanelController?.AdvancePlanActivityFrame(_toolSpinnerFrame);

        var runningEntries = _agentThreadRegistry.ToolEntries.Values.Where(item => !item.IsCompleted).ToList();

        foreach (var entry in runningEntries)
            RenderToolEntry(entry);

        // Update the elapsed time label on each ThinkingBlock that has running tools
        var activeBlocks = runningEntries
            .Select(e => e.ThinkingBlock)
            .Distinct();
        var now = DateTimeOffset.Now;
        foreach (var block in activeBlocks)
        {
            var elapsed = now - block.StartedAt;
            if (elapsed > TimeSpan.Zero)
            {
                block.HeaderTextBlock.Inlines.Clear();
                var liveLabel = new Run("Tooling...") { FontWeight = FontWeights.SemiBold };
                var liveDuration = new Run($" {StatusTimingPresentation.FormatDuration(elapsed)}") { FontWeight = FontWeights.Normal };
                liveDuration.SetResourceReference(TextElement.ForegroundProperty, "ThinkingMetaText");
                block.HeaderTextBlock.Inlines.Add(liveLabel);
                block.HeaderTextBlock.Inlines.Add(liveDuration);
            }
        }
    }

    private void UpdateToolSpinnerState()
    {
        if (_agentThreadRegistry.ToolEntries.Values.Any(entry => !entry.IsCompleted))
        {
            if (!_toolSpinnerTimer.IsEnabled)
                _toolSpinnerTimer.Start();
            return;
        }

        _toolSpinnerTimer.Stop();
        _toolSpinnerFrame = 0;
    }

    private void SyncActiveToolName()
    {
        _pec.ActiveToolName = _agentThreadRegistry.ToolEntries.Values
            .Where(entry => !entry.IsCompleted && ReferenceEquals(entry.Turn, CoordinatorThread.CurrentTurn))
            .Select(entry => ToolTranscriptFormatter.HumanizeToolName(entry.Descriptor.ToolName))
            .LastOrDefault();
    }

    private void OpenToolDetailsButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (sender is not FrameworkElement { Tag: ToolTranscriptEntry entry })
                return;

            ShowTextWindow(
                $"{ToolTranscriptFormatter.HumanizeToolName(entry.Descriptor.ToolName)} Tool Details",
                entry.DetailContent ?? ToolTranscriptFormatter.BuildDetailContent(new ToolTranscriptDetail(
                    entry.Descriptor,
                    entry.ArgsJson,
                    entry.OutputText,
                    entry.StartedAt,
                    entry.FinishedAt,
                    entry.ProgressText,
                    entry.IsCompleted,
                    entry.Success)));
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(OpenToolDetailsButton_Click), ex);
        }
    }

    private ContextMenu CreateToolBlockContextMenu(ToolTranscriptEntry entry)
    {
        string GetDetailText() =>
            entry.DetailContent ?? ToolTranscriptFormatter.BuildDetailContent(new ToolTranscriptDetail(
                entry.Descriptor,
                entry.ArgsJson,
                entry.OutputText,
                entry.StartedAt,
                entry.FinishedAt,
                entry.ProgressText,
                entry.IsCompleted,
                entry.Success));

        var openDetailsItem = new MenuItem
        {
            Header = "Open Details Window",
            Style  = (Style)FindResource("ThemedMenuItemStyle")
        };
        openDetailsItem.Click += (_, _) =>
        {
            try
            {
                ShowTextWindow(
                    $"{ToolTranscriptFormatter.HumanizeToolName(entry.Descriptor.ToolName)} Tool Details",
                    GetDetailText());
            }
            catch (Exception ex)
            {
                HandleUiCallbackException(nameof(CreateToolBlockContextMenu), ex);
            }
        };

        var copyItem = new MenuItem
        {
            Header = "Copy",
            Style  = (Style)FindResource("ThemedMenuItemStyle")
        };
        copyItem.Click += (_, _) =>
        {
            try
            {
                var text = GetDetailText();
                if (!string.IsNullOrEmpty(text))
                    Clipboard.SetText(text);
            }
            catch (Exception ex)
            {
                HandleUiCallbackException(nameof(CreateToolBlockContextMenu), ex);
            }
        };

        var menu = new ContextMenu();
        menu.SetResourceReference(ContextMenu.StyleProperty, "ThemedContextMenuStyle");
        menu.Items.Add(openDetailsItem);
        menu.Items.Add(copyItem);
        return menu;
    }

    private ToolTranscriptDescriptor CreateToolDescriptor(SquadSdkEvent evt)
    {
        return new ToolTranscriptDescriptor(
            evt.ToolName ?? "tool",
            evt.Description,
            evt.Command,
            evt.Path,
            evt.Intent,
            evt.Skill,
            BuildToolDisplayText(evt));
    }

    private static SpinnerActivityKind GetToolActivityKind(string? toolName)
        => ToolTranscriptFormatter.ClassifyToolActivityKind(toolName);

    private string? BuildToolDisplayText(SquadSdkEvent evt)
    {
        if (string.IsNullOrWhiteSpace(evt.ToolName))
            return null;

        return evt.ToolName.Trim() switch
        {
            "glob" => TryGetJsonString(evt.Args, "pattern"),
            "grep" => BuildRelativeToolPathLabel(TryGetJsonString(evt.Args, "path") ?? evt.Path)
                      ?? TryGetJsonString(evt.Args, "pattern"),
            "rg" => BuildRipGrepDisplayText(evt.Args),
            "view" => BuildRelativeToolPathLabel(TryGetJsonString(evt.Args, "path") ?? evt.Path),
            "edit" => BuildRelativeToolPathLabel(TryGetJsonString(evt.Args, "path") ?? evt.Path),
            "apply_patch" => BuildRelativeToolPathLabel(
                ToolTranscriptFormatter.TryExtractEditTargetPath(GetApplyPatchText(evt.Args)) ?? evt.Path),
            "create" => BuildRelativeToolPathLabel(TryGetJsonString(evt.Args, "path") ?? evt.Path),
            "web_fetch" => StripUrlScheme(TryGetJsonString(evt.Args, "url")),
            "task" => TryGetJsonString(evt.Args, "description"),
            "delegate_roster_agent" => BuildDelegateRosterAgentDisplayLabel(evt.Args),
            "skill" => TryGetJsonString(evt.Args, "skill") ?? evt.Skill,
            "store_memory" => TryGetJsonString(evt.Args, "subject") ?? TryGetJsonString(evt.Args, "fact"),
            "report_intent" => TryGetJsonString(evt.Args, "intent") ?? evt.Intent,
            "sql" => TryGetJsonString(evt.Args, "description"),
            "powershell" => TryGetJsonString(evt.Args, "description") ?? TryGetJsonString(evt.Args, "command") ?? evt.Command,
            "read_powershell"  => AppendDelaySuffix(LookupShellLabel(TryGetJsonString(evt.Args, "shellId")), TryGetJsonInt(evt.Args, "delay")),
            "write_powershell" => LookupShellLabel(TryGetJsonString(evt.Args, "shellId")),
            "stop_powershell"  => LookupShellLabel(TryGetJsonString(evt.Args, "shellId")),
            "list_powershell"  => null,
            "read_agent"       => TryGetJsonString(evt.Args, "agent_id"),
            "list_agents"      => null,
            "fetch_copilot_cli_documentation" => null,
            _ => null
        };
    }

    private string? BuildRipGrepDisplayText(JsonElement args)
    {
        var pattern = TryGetJsonString(args, "pattern");
        var scopeLabels = new List<string>();
        if (args.ValueKind == JsonValueKind.Object &&
            args.TryGetProperty("paths", out var pathsProperty))
        {
            if (pathsProperty.ValueKind == JsonValueKind.String)
            {
                var scope = BuildRelativeToolPathLabel(pathsProperty.GetString());
                if (!string.IsNullOrWhiteSpace(scope))
                    scopeLabels.Add(scope);
            }
            else if (pathsProperty.ValueKind == JsonValueKind.Array)
            {
                foreach (var entry in pathsProperty.EnumerateArray())
                {
                    if (entry.ValueKind != JsonValueKind.String)
                        continue;

                    var scope = BuildRelativeToolPathLabel(entry.GetString());
                    if (!string.IsNullOrWhiteSpace(scope))
                        scopeLabels.Add(scope);
                }
            }
        }

        return ToolTranscriptFormatter.BuildRipGrepDisplayText(pattern, scopeLabels);
    }

    private string? BuildDelegateRosterAgentDisplayLabel(JsonElement args)
    {
        var rawHandle = TryGetJsonString(args, "agent_handle");
        if (string.IsNullOrWhiteSpace(rawHandle))
            return null;

        var normalizedHandle = rawHandle.Trim().TrimStart('@').ToLowerInvariant();
        var friendlyName = _agents
            .Where(card => !card.IsLeadAgent && !card.IsDynamicAgent)
            .FirstOrDefault(card =>
                string.Equals(
                    card.AccentStorageKey.Trim().TrimStart('@').ToLowerInvariant(),
                    normalizedHandle,
                    StringComparison.Ordinal))
            ?.Name;
        if (!string.IsNullOrWhiteSpace(friendlyName))
            return friendlyName;

        return "@" + normalizedHandle;
    }

    private static string? GetApplyPatchText(JsonElement args)
    {
        if (args.ValueKind == JsonValueKind.String)
            return args.GetString();

        if (args.ValueKind != JsonValueKind.Object)
            return null;

        foreach (var propertyName in new[] { "patch", "input" })
        {
            if (args.TryGetProperty(propertyName, out var property) &&
                property.ValueKind == JsonValueKind.String)
                return property.GetString();
        }

        return null;
    }

    private string? LookupShellLabel(string? shellId)
    {
        if (string.IsNullOrWhiteSpace(shellId)) return null;
        return _shellDescriptions.TryGetValue(shellId, out var desc) && !string.IsNullOrWhiteSpace(desc)
            ? desc
            : $"Shell {shellId}";
    }

    private string? BuildRelativeToolPathLabel(string? path)
    {
        if (string.IsNullOrWhiteSpace(path))
            return null;

        var normalized = Path.GetFullPath(path);
        if (_currentWorkspace is null)
            return Path.GetFileName(normalized) is { Length: > 0 } name ? name : normalized;

        try
        {
            var rel = Path.GetRelativePath(_currentWorkspace.FolderPath, normalized);
            if (rel == ".")
                rel = Path.GetFileName(normalized.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
            return string.IsNullOrWhiteSpace(rel) ? normalized : rel;
        }
        catch
        {
            return normalized;
        }
    }

    private TeamAgentDescriptor[] GetKnownTeamAgentDescriptors()
    {
        return _agents
            .Where(card => !card.IsLeadAgent && !card.IsDynamicAgent)
            .Select(card => new TeamAgentDescriptor(card.Name, card.AccentStorageKey, card.RoleText))
            .ToArray();
    }

    private void RefreshBridgeNamedAgentRoutes()
    {
        _bridge.NamedAgentRoutes = BuildNamedAgentRoutes();
        _bridge.TemporaryAgentRoute = BuildTemporaryAgentRoute();
    }

    private SquadSdkNamedAgentRoute? BuildTemporaryAgentRoute()
    {
        var profiles = _modelProfileStore.GetProfiles();
        var assignments = _modelProfileStore.GetCategoryAssignments();
        var profile = ModelProfileResolver.Resolve(
            profiles,
            assignments,
            perAgentOverrideProfileId: null,
            agentCategory: ModelProfileCategory.TemporaryAgents);
        return SquadSdkProcess.BuildTemporaryAgentRoute(profile);
    }

    private IReadOnlyList<SquadSdkNamedAgentRoute> BuildNamedAgentRoutes()
    {
        var profiles = _modelProfileStore.GetProfiles();
        var assignments = _modelProfileStore.GetCategoryAssignments();
        var overrides = _modelProfileStore.GetAgentOverrides();
        var routes = new List<SquadSdkNamedAgentRoute>();

        foreach (var card in _agents.Where(candidate => !candidate.IsLeadAgent && !candidate.IsDynamicAgent))
        {
            var handle = card.AccentStorageKey.Trim().TrimStart('@').ToLowerInvariant();
            if (string.IsNullOrWhiteSpace(handle) ||
                routes.Any(route => string.Equals(route.Handle, handle, StringComparison.OrdinalIgnoreCase))) {
                continue;
            }

            var profile = ModelProfileResolver.Resolve(
                profiles,
                assignments,
                handle,
                ResolveNamedAgentProfileCategory(handle),
                overrides);
            string? charterContent = null;
            if (!string.IsNullOrWhiteSpace(card.CharterPath) && File.Exists(card.CharterPath)) {
                try {
                    charterContent = File.ReadAllText(card.CharterPath);
                }
                catch (Exception ex) when (ex is IOException or UnauthorizedAccessException) {
                    SquadDashTrace.Write("Bridge", $"Could not load charter for named-agent route @{handle}: {ex.Message}");
                }
            }

            if (string.Equals(handle, FactCheckerInstructions.Handle, StringComparison.OrdinalIgnoreCase))
                charterContent = FactCheckerInstructions.BuildEffectiveCharter(charterContent);

            routes.Add(SquadSdkProcess.BuildNamedAgentRoute(
                handle,
                card.Name,
                card.RoleText,
                charterContent,
                profile));
        }

        SquadDashTrace.Write(
            "Bridge",
            $"Refreshed {routes.Count} named-agent route(s): " +
            string.Join(", ", routes.Select(route => $"@{route.Handle}={route.ProfileAlias ?? "default"}/{route.Model ?? "auto"}")));
        return routes;
    }

    private static string ResolveNamedAgentProfileCategory(string handle) => handle.ToLowerInvariant() switch
    {
        "rai" => ModelProfileCategory.RAI,
        "scribe" => ModelProfileCategory.Scribe,
        "ralph" => ModelProfileCategory.Ralph,
        "fact-checker" => ModelProfileCategory.FactChecker,
        _ => ModelProfileCategory.SpawnedNamedAgents
    };

    private static string? StripUrlScheme(string? url)
    {
        if (string.IsNullOrWhiteSpace(url))
            return null;

        var trimmed = url.Trim();
        foreach (var scheme in new[] { "https://", "http://" })
        {
            if (trimmed.StartsWith(scheme, StringComparison.OrdinalIgnoreCase))
                return trimmed[scheme.Length..];
        }

        return trimmed;
    }

    private static string? TryGetJsonString(JsonElement element, string propertyName)
    {
        if (element.ValueKind != JsonValueKind.Object)
            return null;

        return element.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.String
            ? property.GetString()
            : null;
    }

    private static bool? TryGetJsonBool(JsonElement element, string propertyName)
    {
        if (element.ValueKind != JsonValueKind.Object)
            return null;

        return element.TryGetProperty(propertyName, out var property) && property.ValueKind is JsonValueKind.True or JsonValueKind.False
            ? property.GetBoolean()
            : null;
    }

    private static int? TryGetJsonInt(JsonElement element, string propertyName)
    {
        if (element.ValueKind != JsonValueKind.Object)
            return null;
        return element.TryGetProperty(propertyName, out var property) && property.ValueKind == JsonValueKind.Number
            ? property.GetInt32()
            : null;
    }

    private static string? AppendDelaySuffix(string? label, int? delay)
    {
        if (label is null) return null;
        return delay is > 0 ? $"{label} ({delay}s)" : label;
    }

    private static DateTimeOffset ParseTimestamp(string? value)
    {
        return DateTimeOffset.TryParse(value, out var parsed)
            ? parsed
            : DateTimeOffset.Now;
    }

    private static DateTimeOffset? TryParseTimestamp(string? value)
    {
        return DateTimeOffset.TryParse(value, out var parsed)
            ? parsed
            : null;
    }

    internal static string BuildTimedStatusText(
        string? statusText,
        DateTimeOffset? startedAt,
        DateTimeOffset? completedAt,
        DateTimeOffset now) =>
        TranscriptTextUtilities.BuildTimedStatusText(statusText, startedAt, completedAt, now);

    private static string? TryFormatJson(JsonElement element)
    {
        return element.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null
            ? null
            : FormatJson(element);
    }

    private static string? MergeToolOutput(string? existingOutput, string? newOutput)
    {
        if (string.IsNullOrWhiteSpace(newOutput))
            return existingOutput;
        if (string.IsNullOrWhiteSpace(existingOutput))
            return newOutput.TrimEnd();
        if (existingOutput.Contains(newOutput, StringComparison.Ordinal))
            return existingOutput;

        return existingOutput.TrimEnd() + Environment.NewLine + newOutput.TrimEnd();
    }

    private void ClearSessionView(bool clearAgentReports = false)
    {
        DisposeInboxWatcher();
        DisposeTeamFileWatcher();
        DisposeCodeHealthMdWatcher();
        _conversationManager.CurrentSessionId = null;
        _hasAuthoritativeBackgroundTaskSnapshot = false;
        _workspaceConversationHydrated = false;
        SquadDashTrace.Write("Persistence", $"Coordinator CurrentTurn cleared reason=ClearSessionView currentTurnWasPresent={_currentTurn is not null}");
        _currentTurn = null;
        if (clearAgentReports && _currentWorkspace is not null)
        {
            var stateDir   = _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace.FolderPath);
            var reportsDir = AgentReportStore.GetReportsDir(stateDir);
            AgentReportStore.ClearAll(reportsDir);
        }
        // Reset completion-footer state on all threads before clearing documents so that
        // UpdateCompletedTimeFooters() (called indirectly by SelectTranscriptThread below)
        // does not re-inject the "Completed N minutes ago" paragraph into the now-empty doc.
        foreach (var thread in EnumerateTranscriptThreads())
        {
            thread.CompletedAt = null;
            thread.CompletedTimeParagraph = null;
        }
        CoordinatorThread.Document.Blocks.Clear();
        RemovePrimaryAgentTranscriptHosts(_primaryAgentTranscriptHosts.Keys.ToArray());
        _transcriptSnapshots.Clear();
        TranscriptSnapshotBackdrop.Visibility = Visibility.Collapsed;
        TranscriptSnapshotImage.Visibility = Visibility.Collapsed;
        TranscriptSnapshotImage.Source = null;
        _snapshotThread = null;
        _agentThreadRegistry.ClearAll();
        _backgroundTaskPresenter.ClearState();
        DismissCodeHealthBanner();
        _routingIssueQuickReplyEntry = null;
        _teamRootPollutionQuickReplyEntry = null;
        ClearActiveQuickReplyState();
        _directQuickReplyAgentThreadIds.Clear();
        _announcedRoutingIssueFingerprint = null;
        _pendingSupplementalPromptInstruction = null;
        _pendingRoutingRepairRecheck = false;
        _conversationManager.ConversationState = WorkspaceConversationState.Empty with {
            ClearedAt = _conversationManager.ConversationState.ClearedAt
        };
        _conversationManager.ResetVirtualWindow();
        _toolSpinnerTimer.Stop();
        _toolSpinnerFrame = 0;
        // Flush thread chips from all agent cards now that the registry is empty.
        SyncAgentCardsWithThreads();
        SelectTranscriptThread(CoordinatorThread);
    }

    private string? GetIgnoredRoutingIssueFingerprintForCurrentWorkspace()
    {
        if (_currentWorkspace is null)
            return null;

        return _settingsSnapshot.IgnoredRoutingIssueFingerprintsByWorkspace.TryGetValue(
            _currentWorkspace.FolderPath,
            out var fingerprint)
            ? fingerprint
            : null;
    }

    private void SetIgnoredRoutingIssueFingerprintForCurrentWorkspace(string? fingerprint)
    {
        if (_currentWorkspace is null)
            return;

        _settingsManager.Replace(_settingsStore.SaveIgnoredRoutingIssueFingerprint(
            _currentWorkspace.FolderPath,
            fingerprint));
    }

    private void ClearIgnoredRoutingIssueFingerprintIfResolved()
    {
        if (_currentWorkspace is null ||
            _currentRoutingAssessment is { NeedsRepair: true })
        {
            return;
        }

        if (!string.IsNullOrWhiteSpace(GetIgnoredRoutingIssueFingerprintForCurrentWorkspace()))
            SetIgnoredRoutingIssueFingerprintForCurrentWorkspace(null);
    }

    private bool CanRunRoutingRepairPrompt()
    {
        return _currentWorkspace is not null &&
               !_isInstallingSquad &&
               _currentInstallationState?.IsSquadInstalledForActiveDirectory == true &&
               _startupIssue is null;
    }

    private TranscriptResponseEntry? ShowSystemTranscriptEntry(string text)
    {
        if (_isClosing || string.IsNullOrWhiteSpace(text))
            return null;

        // A host status entry may arrive while the coordinator is awaiting a background worker.
        // Render it as a separate transcript item without replacing the live coordinator turn;
        // otherwise the worker's eventual tool_complete event is orphaned and persisted as a failure.
        var suspendedCoordinatorTurn = _isPromptRunning ? _currentTurn : null;
        SelectTranscriptThread(CoordinatorThread);
        try
        {
            var turn = BeginTranscriptTurn(string.Empty);
            AppendLine(text);
            FinalizeCurrentTurnResponse();
            return turn.ResponseEntries.LastOrDefault();
        }
        finally
        {
            if (suspendedCoordinatorTurn is not null)
            {
                _currentTurn = suspendedCoordinatorTurn;
                SquadDashTrace.Write(
                    "Persistence",
                    "Coordinator CurrentTurn restored after system-transcript-entry; active worker remains pending.");
            }
            else
            {
                SquadDashTrace.Write("Persistence", "Coordinator CurrentTurn cleared reason=system-transcript-entry");
                _currentTurn = null;
            }
        }
    }

    private void MaybePublishRoutingIssueSystemEntry(string reason, bool force = false)
    {
        if (_isClosing || _isPromptRunning || _currentWorkspace is null)
            return;

        var assessment = _currentRoutingAssessment;
        if (assessment is null)
        {
            _routingIssueQuickReplyEntry = null;
            _announcedRoutingIssueFingerprint = null;
            return;
        }

        if (!assessment.NeedsRepair || string.IsNullOrWhiteSpace(assessment.IssueFingerprint))
        {
            _routingIssueQuickReplyEntry = null;
            _announcedRoutingIssueFingerprint = null;
            return;
        }

        if (string.Equals(
                assessment.IssueFingerprint,
                GetIgnoredRoutingIssueFingerprintForCurrentWorkspace(),
                StringComparison.OrdinalIgnoreCase))
        {
            _routingIssueQuickReplyEntry = null;
            return;
        }

        if (!force &&
            string.Equals(
                assessment.IssueFingerprint,
                _announcedRoutingIssueFingerprint,
                StringComparison.OrdinalIgnoreCase))
        {
            return;
        }

        _routingIssueQuickReplyEntry = ShowSystemTranscriptEntry(
            RoutingIssueWorkflow.BuildSystemEntry(assessment));
        _announcedRoutingIssueFingerprint = assessment.IssueFingerprint;
        SquadDashTrace.Write(
            "Routing",
            $"Published routing issue entry reason={reason} status={assessment.Status} fingerprint={assessment.IssueFingerprint}");
    }

    private async Task WaitForRoutingRepairStateToSettleAsync()
    {
        if (_currentWorkspace is null)
            return;

        var attempts = 6;
        for (var attempt = 0; attempt < attempts; attempt++)
        {
            await RefreshInstallationStateAsync();
            if (_currentRoutingAssessment is null || !_currentRoutingAssessment.NeedsRepair)
                return;

            await Task.Delay(UiTimingConstants.RoutingRepairPollMs);
        }
    }

    private void RefreshInstallationState()
    {
        _ = RefreshInstallationStateAndHandleErrorsAsync();
    }

    private async Task RefreshInstallationStateAndHandleErrorsAsync()
    {
        try
        {
            await RefreshInstallationStateAsync();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(RefreshInstallationState), ex, showDialog: false);
        }
    }

    private async Task RefreshInstallationStateAsync()
    {
        var workspaceFolder = _currentWorkspace?.FolderPath;
        var startupSimulation = _settingsSnapshot.GetStartupIssueSimulation(workspaceFolder ?? "");
        var refreshVersion = Interlocked.Increment(ref _installationStateRefreshVersion);

        ResolvedCliCandidate? resolvedCandidate = null;
        if (!string.IsNullOrWhiteSpace(workspaceFolder))
            resolvedCandidate = await _cliResolutionService.ResolveAsync(workspaceFolder).ConfigureAwait(false);

        var result = await Task.Run(() =>
        {
            SquadInstallationState? installationState = null;
            SquadRoutingDocumentAssessment? routingAssessment = null;

            if (!string.IsNullOrWhiteSpace(workspaceFolder) && resolvedCandidate is not null)
            {
                installationState = _installationStateService.GetState(workspaceFolder, resolvedCandidate);
                if (startupSimulation == DeveloperStartupIssueSimulation.None)
                    routingAssessment = _routingDocumentService.Assess(workspaceFolder);
            }

            return new InstallationStateRefreshResult(
                workspaceFolder,
                installationState,
                routingAssessment,
                WorkspaceIssueFactory.CreateStartupIssue(installationState, startupSimulation));
        }).ConfigureAwait(true);

        await Dispatcher.InvokeAsync(() =>
        {
            if (refreshVersion != Interlocked.Read(ref _installationStateRefreshVersion))
                return;

            if (!string.Equals(_currentWorkspace?.FolderPath, result.WorkspaceFolder, StringComparison.OrdinalIgnoreCase))
                return;

            ApplyInstallationStateRefresh(result);
        });
    }

    private void ApplyInstallationStateRefresh(InstallationStateRefreshResult result)
    {
        _currentInstallationState = _currentWorkspace is null
            ? null
            : result.InstallationState;
        _currentRoutingAssessment = _currentWorkspace is null
            ? null
            : result.RoutingAssessment;
        ClearIgnoredRoutingIssueFingerprintIfResolved();

        _startupIssue = result.StartupIssue;
        _installSquadButtonPressed = false;
        UpdateWorkspaceIssuePanel();
        UpdateInteractiveControlState();
    }

    private void SetInstallUiState(bool isInstalling, string statusText)
    {
        _isInstallingSquad = isInstalling;
        SetInstallStatus(statusText);
        UpdateInteractiveControlState();
    }

    private void SetInstallStatus(string statusText)
    {
        InstallStatusTextBlock.Text = statusText;
        InstallStatusTextBlock.Visibility = string.IsNullOrWhiteSpace(statusText)
            ? Visibility.Collapsed
            : Visibility.Visible;
    }

    private void UpdateWorkspaceIssuePanel()
    {
        var issue = _runtimeIssue ?? _startupIssue;
        var issueKey = WorkspaceIssuePanelState.BuildDismissalKey(issue);
        var isDismissed = issue is not null &&
                          string.Equals(_dismissedWorkspaceIssueKey, issueKey, StringComparison.Ordinal);
        WorkspaceIssuePanelBorder.Visibility = issue is null || isDismissed
            ? Visibility.Collapsed
            : Visibility.Visible;

        if (issue is null)
        {
            _dismissedWorkspaceIssueKey = null;
            WorkspaceIssueTitleTextBlock.Text = string.Empty;
            WorkspaceIssueDetailTextBlock.Text = string.Empty;
            WorkspaceIssueDetailTextBlock.Visibility = Visibility.Collapsed;
            SetInstallStatus(string.Empty);
            InstallSquadButton.Visibility = Visibility.Collapsed;
            IssueHelpButton.Visibility = Visibility.Collapsed;
            IssueDiagnosticsButton.Visibility = Visibility.Collapsed;
            IssueActionButton.Visibility = Visibility.Collapsed;
            IssueSecondaryActionButton.Visibility = Visibility.Collapsed;
            IssuePrimaryLinkButton.Visibility = Visibility.Collapsed;
            IssueSecondaryLinkButton.Visibility = Visibility.Collapsed;
            IssueDismissButton.Visibility = Visibility.Collapsed;
            return;
        }

        WorkspaceIssueTitleTextBlock.Text = issue.Title;
        SetInstallStatus(issue.Message);
        WorkspaceIssueDetailTextBlock.Text = issue.DetailText ?? string.Empty;
        WorkspaceIssueDetailTextBlock.Visibility = string.IsNullOrWhiteSpace(issue.DetailText) || _installSquadButtonPressed || _isInstallingSquad
            ? Visibility.Collapsed
            : Visibility.Visible;

        InstallSquadButton.Visibility = issue.ShowInstallButton && _currentWorkspace is not null
            ? Visibility.Visible
            : Visibility.Collapsed;

        IssueHelpButton.Content = string.IsNullOrWhiteSpace(issue.HelpButtonLabel)
            ? "View Fix Steps"
            : issue.HelpButtonLabel;
        IssueHelpButton.Visibility = string.IsNullOrWhiteSpace(issue.HelpWindowContent)
            ? Visibility.Collapsed
            : Visibility.Visible;

        IssueDiagnosticsButton.Visibility = issue.ShowInstallButton && _currentWorkspace is not null
            ? Visibility.Visible
            : Visibility.Collapsed;

        ConfigureIssueActionButton(IssueActionButton, issue.Action);
        ConfigureIssueActionButton(IssueSecondaryActionButton, issue.SecondaryAction);
        ConfigureIssueLinkButton(IssuePrimaryLinkButton, issue.PrimaryLink);
        ConfigureIssueLinkButton(IssueSecondaryLinkButton, issue.SecondaryLink);
        IssueDismissButton.Visibility = Visibility.Visible;
    }

    private static void ConfigureIssueActionButton(Button button, WorkspaceIssueAction? action)
    {
        if (action is null)
        {
            button.Visibility = Visibility.Collapsed;
            button.Tag = null;
            button.Content = string.Empty;
            return;
        }

        button.Visibility = Visibility.Visible;
        button.Tag = action;
        button.Content = action.Label;
    }

    private static void ConfigureIssueLinkButton(Button button, WorkspaceIssueExternalLink? link)
    {
        if (link is null)
        {
            button.Visibility = Visibility.Collapsed;
            button.Tag = null;
            button.Content = string.Empty;
            return;
        }

        button.Visibility = Visibility.Visible;
        button.Tag = link.Url;
        button.Content = link.Label;
    }

    private WorkspaceIssuePresentation ShowRuntimeIssue(string errorMessage)
    {
        _runtimeIssue = _settingsSnapshot.GetRuntimeIssueSimulation(_currentWorkspace?.FolderPath ?? "") == DeveloperRuntimeIssueSimulation.None
            ? WorkspaceIssueFactory.CreateRuntimeIssue(errorMessage, _currentInstallationState)
            : WorkspaceIssueFactory.CreateSimulatedRuntimeIssue(
                _settingsSnapshot.GetRuntimeIssueSimulation(_currentWorkspace?.FolderPath ?? ""),
                _currentInstallationState);
        _dismissedWorkspaceIssueKey = null;
        UpdateWorkspaceIssuePanel();
        return _runtimeIssue;
    }

    private void ClearRuntimeIssue()
    {
        if (_runtimeIssue is null)
            return;

        _runtimeIssue = null;
        UpdateWorkspaceIssuePanel();
    }

    private void RefreshDeveloperRuntimeIssuePreview()
    {
        if (_currentWorkspace is null || !File.Exists(Path.Combine(_currentWorkspace.FolderPath, "squad-dash.slnx")))
        {
            ClearRuntimeIssue();
            return;
        }

        if (_settingsSnapshot.GetRuntimeIssueSimulation(_currentWorkspace.FolderPath) == DeveloperRuntimeIssueSimulation.None)
        {
            ClearRuntimeIssue();
            return;
        }

        _runtimeIssue = WorkspaceIssueFactory.CreateSimulatedRuntimeIssue(
            _settingsSnapshot.GetRuntimeIssueSimulation(_currentWorkspace.FolderPath),
            _currentInstallationState);
        _dismissedWorkspaceIssueKey = null;
        UpdateWorkspaceIssuePanel();
    }

    private void IssueDismissButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var issue = _runtimeIssue ?? _startupIssue;
            if (issue is null)
                return;

            // If the panel shows an install button but the user hasn't pressed it yet,
            // warn before dismissing — SquadDash won't work without Squad installed.
            if (issue.ShowInstallButton && !_installSquadButtonPressed)
            {
                var result = MessageBox.Show(
                    "Are you sure you want to close this panel? SquadDash cannot run without having Squad installed first.",
                    "Close Panel",
                    MessageBoxButton.YesNo,
                    MessageBoxImage.Warning);
                if (result != MessageBoxResult.Yes)
                    return;
            }

            _dismissedWorkspaceIssueKey = WorkspaceIssuePanelState.BuildDismissalKey(issue);
            UpdateWorkspaceIssuePanel();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(IssueDismissButton_Click), ex);
        }
    }

    private bool IsDeveloperSimulationActive()
    {
        var folder = _currentWorkspace?.FolderPath ?? "";
        return _settingsSnapshot.GetStartupIssueSimulation(folder) != DeveloperStartupIssueSimulation.None ||
               _settingsSnapshot.GetRuntimeIssueSimulation(folder) != DeveloperRuntimeIssueSimulation.None;
    }

    private void IssueHelpButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var issue = _runtimeIssue ?? _startupIssue;
            if (issue is null || string.IsNullOrWhiteSpace(issue.HelpWindowContent))
                return;

            ShowTextWindow(
                issue.HelpWindowTitle ?? "Squad Help",
                issue.HelpWindowContent);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(IssueHelpButton_Click), ex);
        }
    }

    private void QueueLoopResumeAfterQueueDrain(int resumeFromIteration, string reason, bool updateUi = true)
    {
        _loopQueued = true;
        _loopQueuedResumeFromIteration = Math.Max(_loopQueuedResumeFromIteration, resumeFromIteration);
        _conversationManager.UpdateQueuedPromptsState(
            _promptQueue.Items, _followUpAttachments,
            queueRightmostHeld: IsRightmostQueueTabActive(),
            loopQueuedToDequeue: true,
            activeDraftSimEntry: _pec.ActiveDraftSimEntry,
            activeTabIndex: GetActiveQueueTabIndex());
        SquadDashTrace.Write(
            "Loop",
            $"Loop queued until queue drains reason={reason} resumeFromIteration={_loopQueuedResumeFromIteration} promptRunning={_isPromptRunning} queueCount={_promptQueue.Count} restartPending={_restartPending}");
        if (updateUi)
        {
            AppendLoopOutputLine($"⏳ Loop queued — {LoopTimestamp()} — waiting for current turn/queue to drain.", LoopLifecycleBrush);
            SyncLoopPanel();
        }
    }

    private async void IssueDiagnosticsButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_currentWorkspace is null)
                return;

            var state = _currentInstallationState;
            if (state is null)
            {
                var resolvedCandidate = await _cliResolutionService.ResolveAsync(_currentWorkspace.FolderPath).ConfigureAwait(true);
                state = _installationStateService.GetState(_currentWorkspace.FolderPath, resolvedCandidate);
