    private void ExecuteIssueAction(object sender)
    {
        if (sender is not FrameworkElement { Tag: WorkspaceIssueAction action })
            return;

        switch (action.Kind)
        {
            case WorkspaceIssueActionKind.CopyText:
                if (string.IsNullOrWhiteSpace(action.Argument))
                    return;
                Clipboard.SetText(action.Argument);
                SetInstallStatus(BuildIssueActionStatusMessage(action, launched: false));
                break;

            case WorkspaceIssueActionKind.LaunchPowerShellCommand:
                if (string.IsNullOrWhiteSpace(action.Argument))
                    return;
                if (string.Equals(action.Label, "Install PowerShell 7", StringComparison.OrdinalIgnoreCase))
                    _pendingPowerShellInstallRecheck = true;
                _squadCliAdapter.LaunchPowerShellCommandWindow(action);
                SetInstallStatus(BuildIssueActionStatusMessage(action, launched: true));
                break;

            case WorkspaceIssueActionKind.SwitchModelToAuto:
                _settingsManager.Replace(_settingsStore.SaveModelSettings(ModelProvider.GitHubCopilot, "auto"));
                _bridge.CopilotDefaultModel = BuildCopilotDefaultModel(_settingsSnapshot);
                _bridge.ActiveProfile = ResolveActiveProfile(_settingsSnapshot);
                RefreshBridgeNamedAgentRoutes();
                SetInstallStatus("Model switched to 'auto'. Retry your prompt.");
                ClearRuntimeIssue();
                break;
        }
    }

    private static string BuildIssueActionStatusMessage(WorkspaceIssueAction action, bool launched)
    {
        if (action.Kind == WorkspaceIssueActionKind.CopyText)
            return "Copied the command to the clipboard.";

        return action.Label switch
        {
            "Run Build in PowerShell" => "Opened a PowerShell window to run the build check.",
            "Install PowerShell 7" => "Opened a PowerShell window to install PowerShell 7.",
            _ => launched
                ? $"Opened a PowerShell window for {action.Label.ToLowerInvariant()}."
                : $"Completed {action.Label.ToLowerInvariant()}."
        };
    }

    private void UpdateInteractiveControlState(bool promptTextOnly = false)
    {
        var canAbortBackgroundTask = promptTextOnly && _lastInteractiveControlState is not null
            ? _lastCanAbortBackgroundTask
            : _backgroundTaskPresenter.GetAbortTargets().Count > 0;
        if (!promptTextOnly || _lastInteractiveControlState is null)
            _lastCanAbortBackgroundTask = canAbortBackgroundTask;

        var state = InteractiveControlStateCalculator.Calculate(
            hasWorkspace: _currentWorkspace is not null,
            squadInstalled: _currentInstallationState?.IsSquadInstalledForActiveDirectory == true,
            isInstallingSquad: _isInstallingSquad,
            isPromptRunning: _isPromptRunning,
            canAbortBackgroundTask: canAbortBackgroundTask,
            currentPromptText: PromptTextBox.Text);
        var previous = _lastInteractiveControlState;
        _lastInteractiveControlState = state;

        if (previous?.AgentItemsEnabled != state.AgentItemsEnabled)
        {
            SetIsEnabledIfChanged(StatusAgentPanelsGrid, state.AgentItemsEnabled);
            SetIsEnabledIfChanged(ActiveAgentItemsControl, state.AgentItemsEnabled);
            SetIsEnabledIfChanged(InactiveAgentItemsControl, state.AgentItemsEnabled);
        }

        if (previous?.OutputEnabled != state.OutputEnabled)
        {
            SetIsEnabledIfChanged(OutputTextBox, state.OutputEnabled);
            foreach (var entry in _primaryAgentTranscriptHosts.Values)
                SetIsEnabledIfChanged(entry.TranscriptBox, state.OutputEnabled);
        }

        SetIsEnabledIfChanged(PromptTextBox, state.PromptEnabled);
        SetIsEnabledIfChanged(RunButton, state.RunEnabled
            || ((_isPromptRunning || IsLoopRunning) && _currentWorkspace is not null));
        SetIsEnabledIfChanged(AbortButton, state.AbortEnabled);
        if (RunDoctorMenuItem is not null)
            SetIsEnabledIfChanged(RunDoctorMenuItem, state.RunDoctorEnabled);
        SetIsEnabledIfChanged(InstallSquadButton, state.InstallSquadEnabled);
        SetIsEnabledIfChanged(IssueHelpButton, true);
        SetIsEnabledIfChanged(IssueDiagnosticsButton, true);
        SetIsEnabledIfChanged(IssueActionButton, true);
        SetIsEnabledIfChanged(IssueSecondaryActionButton, true);
        SetIsEnabledIfChanged(IssuePrimaryLinkButton, true);
        SetIsEnabledIfChanged(IssueSecondaryLinkButton, true);

        // Help menu: tour items require Squad to be installed
        bool squadInstalled = _currentInstallationState?.IsSquadInstalledForActiveDirectory == true;
        SetIsEnabledIfChanged(WelcomeMenuItem,         squadInstalled);
        SetIsEnabledIfChanged(MoreGuidedToursMenuItem, squadInstalled);

        // "Start Guided Tour" is only available when Squad is installed AND
        // the first tour has not been completed yet.
        bool firstTourAvailable = false;
        if (squadInstalled)
        {
            var tours = GuidedTourLoader.Load(_currentWorkspace?.FolderPath);
            firstTourAvailable = tours.Count > 0 &&
                !GuidedTourStateStore.Shared.IsCompleted(tours[0].Id);
        }
        SetIsEnabledIfChanged(StartGuidedTourMenuItem, firstTourAvailable);
        StartGuidedTourMenuItem.Visibility = firstTourAvailable ? Visibility.Visible : Visibility.Collapsed;
    }

    private static void SetIsEnabledIfChanged(UIElement element, bool isEnabled)
    {
        if (element.IsEnabled != isEnabled)
            element.IsEnabled = isEnabled;
    }

    private void UpdateWindowTitle()
    {
        var solutionDisplay = _currentSolutionName is { Length: > 0 }
            ? Path.GetFileNameWithoutExtension(_currentSolutionName)
            : null;
        Title = solutionDisplay is { Length: > 0 }
            ? $"SquadDash - {solutionDisplay}"
            : _currentWorkspace is { FolderPath.Length: > 0 }
                ? $"SquadDash - {Path.GetFileName(_currentWorkspace.FolderPath)}"
                : "SquadDash";
        // Keep the titlebar workspace label in sync
        WorkspaceTitleDisplay = solutionDisplay is { Length: > 0 }
            ? solutionDisplay
            : _currentWorkspace is { FolderPath.Length: > 0 }
                ? Path.GetFileName(_currentWorkspace.FolderPath)
                : "SquadDash";
        SyncNoWorkspaceHintOverlay();
    }

