    private async Task ShowVersionContextMenuAsync()
    {
        var menu = MakeMenu();
        var copyItem = MakeItem("Copy Squad system info");
        copyItem.Click += (_, _) => CopySquadSystemInfoToClipboard();
        menu.Items.Add(copyItem);

        var candidate = _squadCliAdapter.LastResolvedCandidate;
        var updateInstruction = candidate?.UpdateInstruction;
        var workspaceFolder = _currentWorkspace?.FolderPath;
        var globalCandidate = await TryResolveGlobalSquadCliAsync(workspaceFolder).ConfigureAwait(true);
        var cliActionAdded = false;

        void AddCliAction(MenuItem item)
        {
            if (!cliActionAdded)
            {
                menu.Items.Add(MakeSep());
                cliActionAdded = true;
            }

            menu.Items.Add(item);
        }

        if (updateInstruction?.CanAutoUpdate == true &&
            !string.IsNullOrWhiteSpace(updateInstruction.TargetVersion))
        {
            var updateLabel = candidate?.DetectedSource switch
            {
                CliInstallSource.WorkspaceNpm =>
                    $"Update this workspace's Squad CLI to v{updateInstruction.TargetVersion}",
                CliInstallSource.GlobalNpm =>
                    $"Update global Squad CLI to v{updateInstruction.TargetVersion}",
                _ => $"Update Squad CLI to v{updateInstruction.TargetVersion}"
            };
            var updateItem = MakeItem(updateLabel);
            updateItem.Click += (_, _) => RunSquadCliUpdate(updateInstruction);
            AddCliAction(updateItem);
        }

        var isUsingGlobalCli = candidate?.DetectedSource == CliInstallSource.GlobalNpm;
        if (!isUsingGlobalCli && !string.IsNullOrWhiteSpace(workspaceFolder))
        {
            var detectedGlobalCli = globalCandidate is
            {
                IsAvailable: true,
                DetectedSource: CliInstallSource.GlobalNpm
            };
            var globalTargetVersion = globalCandidate?.UpdateInstruction.TargetVersion ??
                                      updateInstruction?.TargetVersion;

            if (detectedGlobalCli &&
                globalCandidate!.UpdateInstruction.CanAutoUpdate &&
                !string.IsNullOrWhiteSpace(globalTargetVersion))
            {
                var updateGlobalItem = MakeItem(
                    $"Update global Squad CLI to v{globalTargetVersion} and use it for this workspace");
                updateGlobalItem.Click += (_, _) =>
                    InstallOrUpdateGlobalSquadCliAndUse(globalTargetVersion!);
                AddCliAction(updateGlobalItem);
            }
            else if (!detectedGlobalCli && !string.IsNullOrWhiteSpace(globalTargetVersion))
            {
                var installGlobalItem = MakeItem(
                    $"Install global Squad CLI v{globalTargetVersion} and use it for this workspace");
                installGlobalItem.Click += (_, _) =>
                    InstallOrUpdateGlobalSquadCliAndUse(globalTargetVersion!);
                AddCliAction(installGlobalItem);
            }

            if (detectedGlobalCli && !string.IsNullOrWhiteSpace(globalCandidate!.Version))
            {
                var useGlobalItem = MakeItem(
                    $"Use global Squad CLI v{globalCandidate.Version} for this workspace");
                useGlobalItem.Click += async (_, _) =>
                    await UseGlobalSquadCliAsync(workspaceFolder).ConfigureAwait(true);
                AddCliAction(useGlobalItem);
            }
        }

        var workspaceUpgradeVersion = GetWorkspaceUpgradeVersionForMenu();
        if (ShouldShowWorkspaceUpgradeEntryPoint() && !string.IsNullOrWhiteSpace(workspaceUpgradeVersion))
        {
            menu.Items.Add(MakeSep());
            var workspaceUpgradeItem = MakeItem($"Upgrade workspace files to Squad v{workspaceUpgradeVersion}");
            workspaceUpgradeItem.Click += async (_, _) => await OpenWorkspaceUpgradeSummaryAsync();
            menu.Items.Add(workspaceUpgradeItem);
        }

        menu.IsOpen = true;
    }

    private async Task<ResolvedCliCandidate?> TryResolveGlobalSquadCliAsync(string? workspaceFolder)
    {
        if (string.IsNullOrWhiteSpace(workspaceFolder))
            return null;

        try
        {
            return await _cliResolutionService
                .ResolveWithModeAsync(CliSelectionMode.GlobalNpm, workspaceFolder)
                .ConfigureAwait(true);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("CliResolution", $"Global Squad CLI probe failed: {ex.Message}");
            return null;
        }
    }

    private void UpdateSquadUpdateBadge()
    {
        if (SquadUpdateBadge is null || WorkspaceUpgradePendingBadge is null)
            return;
        var updateInstruction = _squadCliAdapter.LastResolvedCandidate?.UpdateInstruction;
        var hasUpdate = updateInstruction?.CanAutoUpdate == true &&
                        !string.IsNullOrWhiteSpace(updateInstruction.TargetVersion);
        SquadUpdateBadge.Visibility = hasUpdate ? Visibility.Visible : Visibility.Collapsed;
        if (hasUpdate)
            SquadUpdateBadge.ToolTip = MakeThemedToolTip($"Squad CLI v{updateInstruction!.TargetVersion} available — click to update");

        var hasWorkspaceUpgrade = ShouldShowWorkspaceUpgradeEntryPoint();
        WorkspaceUpgradePendingBadge.Visibility = hasWorkspaceUpgrade ? Visibility.Visible : Visibility.Collapsed;
        if (hasWorkspaceUpgrade)
        {
            var workspaceVersion = GetWorkspaceUpgradeVersionForMenu();
            var tooltipSuffix = string.IsNullOrWhiteSpace(workspaceVersion) ? string.Empty : $" to v{workspaceVersion}";
            WorkspaceUpgradePendingBadge.ToolTip = MakeThemedToolTip(
                $"Workspace-file layout upgrade{tooltipSuffix} — updates this workspace's Squad-managed files; click to review");
        }

        UpdateTitleBarResponsiveLayout();
    }

    private void TitlebarGrid_SizeChanged(object sender, SizeChangedEventArgs e) =>
        UpdateTitleBarResponsiveLayout();

    // Cached ActualWidths of each hideable info-panel control, measured while visible.
    // Updated every time a control is visible and has a real layout width.
    private double _cachedSdVersionWidth;
    private double _cachedSquadVersionWidth;
    private double _cachedWorkspaceTitleWidth;

    private void UpdateTitleBarResponsiveLayout()
    {
        if (TitlebarGrid is null)
            return;

        // Refresh cached widths from controls that are currently visible and measured.
        // Never called between Visibility changes (no UpdateLayout()), so this reflects
        // the layout pass that preceded this SizeChanged call.
        if (SquadDashVersionTextBlock.Visibility == Visibility.Visible &&
            SquadDashVersionTextBlock.ActualWidth > 0)
        {
            var m = SquadDashVersionTextBlock.Margin;
            _cachedSdVersionWidth = SquadDashVersionTextBlock.ActualWidth + m.Left + m.Right;
        }
        if (SquadVersionPanel.Visibility == Visibility.Visible &&
            SquadVersionPanel.ActualWidth > 0)
        {
            var m = SquadVersionPanel.Margin;
            _cachedSquadVersionWidth = SquadVersionPanel.ActualWidth + m.Left + m.Right;
        }
        if (WorkspaceTitleText.Visibility == Visibility.Visible &&
            WorkspaceTitleText.ActualWidth > 0)
        {
            var m = WorkspaceTitleText.Margin;
            _cachedWorkspaceTitleWidth = WorkspaceTitleText.ActualWidth + m.Left + m.Right;
        }

        // Fallback estimates for first call before any layout pass has occurred.
        double sdVersionW    = _cachedSdVersionWidth    > 0 ? _cachedSdVersionWidth    : 85;
        double squadVersionW = _cachedSquadVersionWidth > 0 ? _cachedSquadVersionWidth : 75;
        double workspaceTitleW = _cachedWorkspaceTitleWidth > 0 ? _cachedWorkspaceTitleWidth : 180;

        // Space available between the menu bar (left) and the caption buttons (right, 114px).
        // The *-column search area sits here; so does the right-anchored info panel.
        double menuW = MainMenu?.ActualWidth ?? 130;
        const double captionW = 114;   // 3 × 38px caption buttons
        const double searchMinW = 145; // SearchBox.MinWidth=135 + padding
        const double gap = 12;         // breathing room between search right-edge and info left-edge

        double available = ActualWidth - menuW - captionW;

        // Determine how many info items can coexist with the search box.
        // Greedy: hide highest-priority items first until the remaining info
        // fits alongside the minimum-width search box.
        double infoNeeded = sdVersionW + squadVersionW + workspaceTitleW;
        double budgetForInfo = available - searchMinW - gap;

        bool showSdVersion, showSquadVersion, showWorkspace;
        if (budgetForInfo >= infoNeeded)
        {
            showSdVersion = showSquadVersion = showWorkspace = true;
        }
        else if (budgetForInfo >= squadVersionW + workspaceTitleW)
        {
            // Hiding SquadDash version is enough
            showSdVersion = false;
            showSquadVersion = showWorkspace = true;
        }
        else if (budgetForInfo >= workspaceTitleW)
        {
            // Hide both version labels
            showSdVersion = showSquadVersion = false;
            showWorkspace = true;
        }
        else
        {
            // Hide everything in the info panel
            showSdVersion = showSquadVersion = showWorkspace = false;
        }

        SquadDashVersionTextBlock.Visibility = showSdVersion    ? Visibility.Visible : Visibility.Collapsed;
        SquadVersionPanel.Visibility         = showSquadVersion ? Visibility.Visible : Visibility.Collapsed;
        WorkspaceTitleText.Visibility        = showWorkspace    ? Visibility.Visible : Visibility.Collapsed;

        // Hide search only if there's not enough room for even the minimum-width search box,
        // unless the user is actively searching (never hide an active search).
        double infoActual = (showSdVersion ? sdVersionW : 0)
                          + (showSquadVersion ? squadVersionW : 0)
                          + (showWorkspace ? workspaceTitleW : 0);
        bool showSearch = (available - infoActual - gap) >= searchMinW;
        if (!showSearch && _search.IsSearchActive)
            showSearch = true;

        SearchStackPanel.Visibility = showSearch ? Visibility.Visible : Visibility.Collapsed;
    }

    private void RunSquadCliUpdate(CliUpdateInstruction updateInstruction)
    {
        var command = updateInstruction.UpdateCommand
            ?? $"npm install @bradygaster/squad-cli@{updateInstruction.TargetVersion}";
        var previousVersion = _squadCliAdapter.SquadVersion;
        var workspaceFolder = _currentWorkspace?.FolderPath;
        var action = new WorkspaceIssueAction(
            "Update Squad CLI",
            WorkspaceIssueActionKind.LaunchPowerShellCommand,
            command);
        var updateProcess = _squadCliAdapter.LaunchPowerShellCommandWindow(action, workspaceFolder);
        if (updateProcess is null)
            return;

        try
        {
            updateProcess.EnableRaisingEvents = true;
            updateProcess.Exited += (_, _) =>
            {
                _ = Dispatcher.InvokeAsync(async () =>
                {
                    try
                    {
                        await _squadCliAdapter.ResolveSquadVersionAsync(workspaceFolder).ConfigureAwait(true);
                        await CompleteCliChangeAsync(workspaceFolder, previousVersion).ConfigureAwait(true);
                    }
                    catch (Exception ex)
                    {
                        HandleUiCallbackException(nameof(RunSquadCliUpdate), ex);
                    }
                });
            };
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(RunSquadCliUpdate), ex);
        }
    }

    private void InstallOrUpdateGlobalSquadCliAndUse(string targetVersion)
    {
        var workspaceFolder = _currentWorkspace?.FolderPath;
        if (string.IsNullOrWhiteSpace(workspaceFolder) || string.IsNullOrWhiteSpace(targetVersion))
            return;

        var previousVersion = _squadCliAdapter.SquadVersion;
        var action = new WorkspaceIssueAction(
            "Install global Squad CLI",
            WorkspaceIssueActionKind.LaunchPowerShellCommand,
            $"npm install -g @bradygaster/squad-cli@{targetVersion}");
        var updateProcess = _squadCliAdapter.LaunchPowerShellCommandWindow(action, workspaceFolder);
        if (updateProcess is null)
            return;

        try
        {
            updateProcess.EnableRaisingEvents = true;
            updateProcess.Exited += (_, _) =>
            {
                _ = Dispatcher.InvokeAsync(async () =>
                {
                    try
                    {
                        var globalCandidate = await _cliResolutionService
                            .ResolveWithModeAsync(CliSelectionMode.GlobalNpm, workspaceFolder)
                            .ConfigureAwait(true);
                        if (!globalCandidate.IsAvailable ||
                            globalCandidate.DetectedSource != CliInstallSource.GlobalNpm ||
                            !WorkspaceUpgradeVersionPolicy.MatchesActiveCandidate(
                                targetVersion,
                                globalCandidate.Version))
                        {
                            throw new InvalidOperationException(
                                $"Global Squad CLI v{targetVersion} was not detected after installation. " +
                                "This workspace is still using its previous CLI selection.");
                        }

                        await _cliSelectionStore
                            .SaveSelectionAsync(workspaceFolder, CliSelectionMode.GlobalNpm, customPath: null)
                            .ConfigureAwait(true);
                        await _squadCliAdapter.ResolveSquadVersionAsync(workspaceFolder).ConfigureAwait(true);
                        await CompleteCliChangeAsync(workspaceFolder, previousVersion).ConfigureAwait(true);
                    }
                    catch (Exception ex)
                    {
                        HandleUiCallbackException(nameof(InstallOrUpdateGlobalSquadCliAndUse), ex);
                    }
                });
            };
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(InstallOrUpdateGlobalSquadCliAndUse), ex);
        }
    }

    private async Task UseGlobalSquadCliAsync(string workspaceFolder)
    {
        var previousVersion = _squadCliAdapter.SquadVersion;
        var previousMode = _cliSelectionStore.GetSelectionMode(workspaceFolder);
        var previousCustomPath = _cliSelectionStore.GetCustomPath(workspaceFolder);

        try
        {
            await _cliSelectionStore
                .SaveSelectionAsync(workspaceFolder, CliSelectionMode.GlobalNpm, customPath: null)
                .ConfigureAwait(true);
            await _squadCliAdapter.ResolveSquadVersionAsync(workspaceFolder).ConfigureAwait(true);
            var selectedCandidate = _squadCliAdapter.LastResolvedCandidate;
            if (selectedCandidate is not
                {
                    IsAvailable: true,
                    DetectedSource: CliInstallSource.GlobalNpm
                })
            {
                throw new InvalidOperationException(
                    "The global Squad CLI could not be selected. The previous CLI selection has been restored.");
            }

            await CompleteCliChangeAsync(workspaceFolder, previousVersion).ConfigureAwait(true);
        }
        catch (Exception ex)
        {
            await _cliSelectionStore
                .SaveSelectionAsync(workspaceFolder, previousMode, previousCustomPath)
                .ConfigureAwait(true);
            await _squadCliAdapter.ResolveSquadVersionAsync(workspaceFolder).ConfigureAwait(true);
            UpdateStatusTitle();
            UpdateSquadUpdateBadge();
            HandleUiCallbackException(nameof(UseGlobalSquadCliAsync), ex);
        }
    }

    private async Task CompleteCliChangeAsync(string? workspaceFolder, string? previousVersion)
    {
        UpdateStatusTitle();
        SyncLoopPanel();

        var currentVersion = _squadCliAdapter.SquadVersion;
        if (!string.IsNullOrWhiteSpace(workspaceFolder) &&
            !string.IsNullOrWhiteSpace(currentVersion) &&
            IsNewerSquadVersion(currentVersion, previousVersion))
        {
            await _workspacePendingUpgradeStore
                .SavePendingAsync(workspaceFolder, currentVersion)
                .ConfigureAwait(true);
        }

        await RefreshWorkspaceUpgradeStateAsync().ConfigureAwait(true);
    }

    private async Task RefreshWorkspaceUpgradeStateAsync()
    {
        if (_currentWorkspace is null)
        {
            _workspacePendingUpgradeState = WorkspacePendingUpgradeState.None;
            UpdateSquadUpdateBadge();
            return;
        }

        try
        {
            _workspacePendingUpgradeState = await _workspacePendingUpgradeStore
                .GetAsync(_currentWorkspace.FolderPath)
                .ConfigureAwait(true);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.General, $"Workspace pending-upgrade load failed: {ex.Message}");
            _workspacePendingUpgradeState = WorkspacePendingUpgradeState.None;
        }

        UpdateSquadUpdateBadge();
    }

    private bool ShouldShowWorkspaceUpgradeEntryPoint()
    {
        if (_currentWorkspace is null)
            return false;

        if (_workspacePendingUpgradeState.IsPending)
            return true;

        var installedVersion = _squadCliAdapter.SquadVersion;
        var recordedVersion = _workspacePendingUpgradeState.RecordedCliVersion;
        return !string.IsNullOrWhiteSpace(installedVersion) &&
               !string.IsNullOrWhiteSpace(recordedVersion) &&
               IsNewerSquadVersion(installedVersion, recordedVersion);
    }

    private string? GetWorkspaceUpgradeVersionForMenu()
    {
        return WorkspaceUpgradeVersionPolicy.ResolveDisplayVersion(
            _workspacePendingUpgradeState.IsPending,
            _workspacePendingUpgradeState.RecordedCliVersion,
            _squadCliAdapter.SquadVersion,
            _squadCliAdapter.LatestSquadVersion);
    }

    private async Task OpenWorkspaceUpgradeSummaryAsync()
    {
        if (_currentWorkspace is null)
            return;

        if (_workspaceUpgradeSummaryWindow is not null)
        {
            if (_workspaceUpgradeSummaryWindow.WindowState == WindowState.Minimized)
                _workspaceUpgradeSummaryWindow.WindowState = WindowState.Normal;
            _workspaceUpgradeSummaryWindow.Activate();
            _workspaceUpgradeSummaryWindow.Focus();
            return;
        }

        var candidate = _squadCliAdapter.LastResolvedCandidate;
        if (candidate is null || !candidate.IsAvailable)
        {
            await _squadCliAdapter.ResolveSquadVersionAsync(_currentWorkspace.FolderPath).ConfigureAwait(true);
            candidate = _squadCliAdapter.LastResolvedCandidate;
            UpdateStatusTitle();
            UpdateSquadUpdateBadge();
        }

        if (candidate is null || !candidate.IsAvailable)
        {
            MessageBox.Show(
                "Squad CLI could not be resolved for this workspace.",
                "Workspace Upgrade",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
            return;
        }

        var targetWorkspaceVersion = GetWorkspaceUpgradeVersionForMenu();
        if (!WorkspaceUpgradeVersionPolicy.MatchesActiveCandidate(
                targetWorkspaceVersion,
                candidate.Version))
        {
            MessageBox.Show(
                $"Workspace files are waiting for Squad v{targetWorkspaceVersion}, but the active CLI is " +
                $"v{candidate.Version ?? "unknown"}. Update and re-resolve the Squad CLI before upgrading workspace files.",
                "Workspace Upgrade Version Mismatch",
                MessageBoxButton.OK,
                MessageBoxImage.Warning);
            return;
        }

        var panel = new WorkspaceUpgradeSummaryPanel
        {
            CurrentState = WorkspaceUpgradeSummaryPanelState.Running,
            ErrorMessage = string.Empty,
            DryRunResult = WorkspaceUpgradeDryRunResult.Empty
        };
        panel.SetApplyAvailability(candidate.IsAvailable);

        var window = new Window
        {
            Title = "Workspace Upgrade Summary",
            Width = 860,
            Height = 680,
            MinWidth = 680,
            MinHeight = 500,
            Content = panel
        };
        window.SetResourceReference(Window.BackgroundProperty, "PanelSurface");
        window.SetResourceReference(Window.ForegroundProperty, "BodyText");
        if (CanShowOwnedWindow())
            window.Owner = this;
        WindowPlacementHelper.CenterOnOwnerAndEnsureOnScreen(window, this);
        _workspaceUpgradeSummaryWindow = window;
        window.Closed += (_, _) =>
        {
            if (ReferenceEquals(_workspaceUpgradeSummaryWindow, window))
                _workspaceUpgradeSummaryWindow = null;
        };

        panel.FilePreviewRequested = (path, category) =>
            OpenWorkspaceUpgradeFilePreviewAsync(candidate, _currentWorkspace.FolderPath, path, category);

        panel.ApplyWorkspaceUpdateRequested = async () =>
        {
            if (_currentWorkspace is null)
                return;

            var workspacePath = _currentWorkspace.FolderPath;
            var resolvedCandidate = _squadCliAdapter.LastResolvedCandidate;
            if (resolvedCandidate is null || !resolvedCandidate.IsAvailable)
            {
                await _squadCliAdapter.ResolveSquadVersionAsync(workspacePath).ConfigureAwait(true);
                resolvedCandidate = _squadCliAdapter.LastResolvedCandidate;
                UpdateStatusTitle();
                UpdateSquadUpdateBadge();
            }

            var targetWorkspaceVersion = GetWorkspaceUpgradeVersionForMenu();
            if (resolvedCandidate is null || !resolvedCandidate.IsAvailable)
            {
                panel.SetApplyAvailability(
                    false,
                    "Apply is disabled because Squad CLI could not be resolved. Re-resolve the CLI and reopen this panel.");
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Failed;
                panel.ErrorMessage = "Squad CLI could not be resolved for this workspace.";
                return;
            }

            if (!WorkspaceUpgradeVersionPolicy.MatchesActiveCandidate(
                    targetWorkspaceVersion,
                    resolvedCandidate.Version))
            {
                panel.SetApplyAvailability(
                    false,
                    $"Apply is disabled because the active Squad CLI version (v{resolvedCandidate.Version ?? "unknown"}) " +
                    $"does not match the pending workspace target (v{targetWorkspaceVersion ?? "unknown"}).");
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Failed;
                panel.ErrorMessage = "Active Squad CLI version does not match the workspace upgrade target.";
                return;
            }

            panel.SetApplyAvailability(true);
            panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Running;
            panel.ErrorMessage = string.Empty;
            panel.SetPartiallyAppliedFiles([]);

            WorkspaceUpgradeResult applyResult;
            try
            {
                applyResult = await _workspaceUpgradeService
                    .UpgradeAsync(resolvedCandidate, workspacePath)
                    .ConfigureAwait(true);
            }
            catch (Exception ex)
            {
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Failed;
                panel.ErrorMessage = ex.Message;
                SquadDashTrace.Write(TraceCategory.General, $"Workspace upgrade apply failed: {ex.Message}");
                return;
            }

            var appliedResult = new WorkspaceUpgradeDryRunResult(
                applyResult.SafeAdditionsOrRefreshes,
                applyResult.TrackedLocalChangesAtRisk,
                applyResult.GeneratedFilesAtRisk);

            if (applyResult.Success)
            {
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Succeeded;
                panel.ErrorMessage = string.Empty;
                panel.SetPartiallyAppliedFiles([]);
                await _workspacePendingUpgradeStore.SaveResolvedAsync(workspacePath).ConfigureAwait(true);
                await _squadCliAdapter.ResolveSquadVersionAsync(workspacePath).ConfigureAwait(true);
                UpdateStatusTitle();
                await RefreshWorkspaceUpgradeStateAsync().ConfigureAwait(true);
                AppendLine("✅ Workspace update applied. Opening git changes for review.");
                await OpenWorkspaceUpgradeChangesAsync(appliedResult, simulated: false).ConfigureAwait(true);
                return;
            }

            if (applyResult.IsPartial)
            {
                panel.DryRunResult = appliedResult;
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.PartiallyApplied;
                panel.ErrorMessage = string.IsNullOrWhiteSpace(applyResult.ErrorMessage)
                    ? "Workspace upgrade was partially applied."
                    : applyResult.ErrorMessage.Trim();
                panel.SetPartiallyAppliedFiles(CollectWorkspaceUpgradePaths(
                    applyResult.SafeAdditionsOrRefreshes,
                    applyResult.TrackedLocalChangesAtRisk,
                    applyResult.GeneratedFilesAtRisk));
                AppendLine($"⚠ Workspace update partially applied: {panel.ErrorMessage}");
                await OpenWorkspaceUpgradeChangesAsync(panel.DryRunResult, simulated: false).ConfigureAwait(true);
                return;
            }

            panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Failed;
            panel.ErrorMessage = string.IsNullOrWhiteSpace(applyResult.ErrorMessage)
                ? "Workspace upgrade failed."
                : applyResult.ErrorMessage.Trim();
        };

        panel.LaterRequested = async () =>
        {
            if (panel.CurrentState == WorkspaceUpgradeSummaryPanelState.Succeeded)
            {
                window.Close();
                return;
            }

            if (_currentWorkspace is null)
                return;

            var workspacePath = _currentWorkspace.FolderPath;
            var recordedVersion = _squadCliAdapter.LastResolvedCandidate?.Version;
            if (string.IsNullOrWhiteSpace(recordedVersion))
                recordedVersion = GetWorkspaceUpgradeVersionForMenu();

            if (string.IsNullOrWhiteSpace(recordedVersion))
            {
                await _squadCliAdapter.ResolveSquadVersionAsync(workspacePath).ConfigureAwait(true);
                recordedVersion = _squadCliAdapter.LastResolvedCandidate?.Version;
                UpdateStatusTitle();
            }

            if (string.IsNullOrWhiteSpace(recordedVersion))
            {
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Failed;
                panel.ErrorMessage = "Could not determine the Squad CLI version to record for deferred workspace upgrade.";
                return;
            }

            await _workspacePendingUpgradeStore.SavePendingAsync(workspacePath, recordedVersion).ConfigureAwait(true);
            await RefreshWorkspaceUpgradeStateAsync().ConfigureAwait(true);
            AppendLine($"⏳ Workspace upgrade deferred until later (target Squad v{recordedVersion.Trim()}).");
            window.Close();
        };

        window.Show();

        try
        {
            var dryRun = await _workspaceUpgradeService
                .DryRunAsync(candidate, _currentWorkspace.FolderPath)
                .ConfigureAwait(true);
            panel.DryRunResult = dryRun;
            if (dryRun.Success)
            {
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Idle;
                panel.ErrorMessage = string.Empty;
            }
            else
            {
                panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Failed;
                panel.ErrorMessage = dryRun.ErrorMessage ?? "Workspace upgrade dry-run failed.";
            }
        }
        catch (Exception ex)
        {
            panel.CurrentState = WorkspaceUpgradeSummaryPanelState.Failed;
            panel.ErrorMessage = ex.Message;
        }
    }

    private async Task OpenWorkspaceUpgradeFilePreviewAsync(
        ResolvedCliCandidate? candidate,
        string workspacePath,
        string reportedPath,
        WorkspaceUpgradeFileCategory category)
    {
        var preview = await WorkspaceUpgradeFilePreviewService
            .CreateAsync(candidate, workspacePath, reportedPath, category)
            .ConfigureAwait(true);
        var window = new WorkspaceUpgradeFileDiffWindow(preview);
        if (CanShowOwnedWindow())
            window.Owner = this;
        WindowPlacementHelper.CenterOnOwnerAndEnsureOnScreen(window, this);
        window.Show();
        window.Activate();
    }

    private static IReadOnlyList<string> CollectWorkspaceUpgradePaths(params IReadOnlyList<string>[] groups)
    {
        return groups
            .SelectMany(group => group)
            .Where(path => !string.IsNullOrWhiteSpace(path))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .OrderBy(path => path, StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private async Task OpenWorkspaceUpgradeChangesAsync(
        WorkspaceUpgradeDryRunResult result,
        bool simulated)
    {
        string? gitStatus = null;
        string? gitDiff = null;

        if (!simulated && _currentWorkspace is not null)
        {
            var workspacePath = _currentWorkspace.FolderPath;
            gitStatus = await RunGitAsync(
                workspacePath,
                "status --short --untracked-files=all").ConfigureAwait(true);
            gitDiff = await RunGitAsync(
                workspacePath,
                "diff --no-ext-diff --no-color").ConfigureAwait(true);
        }

        if (_workspaceUpgradeChangesWindow is null)
        {
            var window = new WorkspaceUpgradeChangesWindow(_transcriptFontSize);
            if (CanShowOwnedWindow())
                window.Owner = this;
            WindowPlacementHelper.CenterOnOwnerAndEnsureOnScreen(window, this);
            window.Closed += (_, _) =>
            {
                if (ReferenceEquals(_workspaceUpgradeChangesWindow, window))
                    _workspaceUpgradeChangesWindow = null;
            };
            _workspaceUpgradeChangesWindow = window;
        }

        _workspaceUpgradeChangesWindow.UpdateEvidence(result, gitStatus, gitDiff, simulated);
        if (!_workspaceUpgradeChangesWindow.IsVisible)
            _workspaceUpgradeChangesWindow.Show();
        if (_workspaceUpgradeChangesWindow.WindowState == WindowState.Minimized)
            _workspaceUpgradeChangesWindow.WindowState = WindowState.Normal;
        _workspaceUpgradeChangesWindow.Activate();
        _workspaceUpgradeChangesWindow.Focus();
    }

    private static string GetGitShortSha(string workingDirectory)
    {
        try
        {
            using var proc = new System.Diagnostics.Process();
            proc.StartInfo = new System.Diagnostics.ProcessStartInfo("git", "rev-parse --short HEAD")
            {
                RedirectStandardOutput = true,
                UseShellExecute        = false,
                CreateNoWindow         = true,
                WorkingDirectory       = workingDirectory
            };
            proc.Start();
            var sha = proc.StandardOutput.ReadToEnd().Trim();
            proc.WaitForExit(3000);
            return string.IsNullOrWhiteSpace(sha) ? "unknown" : sha;
        }
        catch
        {
            return "unknown";
        }
    }

    private sealed class SimulatedButtonFlowUpgradeService : IWorkspaceUpgradeService
    {
        private static readonly IReadOnlyList<string> SafeFiles = [
            ".squad/team.md",
            ".squad/routing.md"
        ];
        private static readonly IReadOnlyList<string> TrackedAtRisk = [
            ".squad/agents/lyra-morn/charter.md"
        ];

        internal WorkspaceUpgradeDryRunResult BuildRepresentativeDryRunResult() =>
            new(SafeFiles, TrackedAtRisk, []);

        public Task<WorkspaceUpgradeDryRunResult> DryRunAsync(
            ResolvedCliCandidate candidate, string workspaceDir) =>
            Task.FromResult(BuildRepresentativeDryRunResult());

        public Task<WorkspaceUpgradeResult> UpgradeAsync(
            ResolvedCliCandidate candidate, string workspaceDir) =>
            Task.FromResult(new WorkspaceUpgradeResult(
                Success: true,
                IsPartial: false,
                ErrorMessage: null,
                SafeAdditionsOrRefreshes: SafeFiles,
                TrackedLocalChangesAtRisk: TrackedAtRisk,
                GeneratedFilesAtRisk: []));
    }

    /// <summary>
    /// Returns <c>true</c> if the installed Squad CLI version supports <c>squad loop</c>.
    /// The <c>--agent-cmd</c> flag required for Windows CLI looping was added in 0.9.5.
    /// When the version is unknown (null/empty) we allow it so we don't block users whose
    /// version resolution is still pending or failed.
    /// </summary>
    private static bool SquadCliSupportsLoop(string? version)
    {
        if (string.IsNullOrWhiteSpace(version)) return true;
        var v = ParseSimpleVersion(version);
        if (v is null) return true;
        // Minimum: 0.9.5
        if (v[0] > 0) return true;
        if (v[0] < 0) return false;
        if (v[1] > 9) return true;
        if (v[1] < 9) return false;
        return v[2] >= 5;
    }

    private static bool IsNewerSquadVersion(string candidate, string? current) =>
        DocumentUtilities.IsNewerSquadVersion(candidate, current);

    private static int[]? ParseSimpleVersion(string v) =>
        DocumentUtilities.ParseSimpleVersion(v);

    private void CopySquadSystemInfoToClipboard()
    {
        try
        {
            var squadVersion = _squadCliAdapter.SquadVersion;
            var sb = new System.Text.StringBuilder();
            sb.AppendLine($"SquadDash version: {AppVersion.Full}");
            sb.AppendLine($"Squad version:     {(string.IsNullOrWhiteSpace(squadVersion) ? "(unknown)" : squadVersion)}");
            sb.AppendLine($"Workspace folder:  {_currentWorkspace?.FolderPath ?? "(none)"}");
            if (!string.IsNullOrWhiteSpace(_currentSolutionPath))
                sb.AppendLine($"Solution file:     {_currentSolutionPath}");

            // Workspace-specific paths (only when a workspace is open).
            if (_currentWorkspace is not null)
            {
                var stateDir = _conversationManager.ConversationStore.GetWorkspaceStateDirectory(_currentWorkspace.FolderPath);
                sb.AppendLine($"Workspace state:   {stateDir}");
                sb.AppendLine($"Conversation file: {System.IO.Path.Combine(stateDir, "conversation.json")}");
            }

            sb.AppendLine($"Trace log:         {SquadDashTrace.CurrentLogPath}");
            sb.AppendLine($"OS:                {System.Runtime.InteropServices.RuntimeInformation.OSDescription}");
            sb.AppendLine($".NET runtime:      {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
            sb.AppendLine($"Architecture:      {System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture}");
            Clipboard.SetText(sb.ToString());
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(CopySquadSystemInfoToClipboard), ex);
        }
    }

