    private void TitlebarGrid_MouseLeftButtonDown(object sender, MouseButtonEventArgs e)
    {
        try
        {
            // WindowChrome handles native drag for non-interactive areas (CaptionHeight region).
            // This handler catches double-click on the background to maximize/restore.
            if (e.ClickCount == 2 && e.OriginalSource is Grid)
            {
                if (_transcriptFullScreenEnabled)
                {
                    SetTranscriptFullScreen(false);
                }
                else if (WindowState == WindowState.Maximized)
                {
                    SystemCommands.RestoreWindow(this);
                }
                else
                {
                    SystemCommands.MaximizeWindow(this);
                }
                e.Handled = true;
            }
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(TitlebarGrid_MouseLeftButtonDown), ex);
        }
    }

    private void UpdateMaximizeRestoreIcon()
    {
        if (MaximizeIconCanvas is null) return;
        // Close any open tooltip before replacing it to avoid
        // "ToolTip cannot have a logical or visual parent" when StateChanged
        // fires while the user is hovering over the button (tooltip is shown
        // and has a non-null visual parent via its Popup).
        if (MaximizeRestoreButton.ToolTip is ToolTip openTip)
            openTip.IsOpen = false;
        if (WindowState == WindowState.Maximized)
        {
            MaximizeIconCanvas.Visibility = Visibility.Collapsed;
            RestoreIconCanvas.Visibility = Visibility.Visible;
            MaximizeRestoreButton.ToolTip = MakeThemedToolTip("Restore");
        }
        else
        {
            MaximizeIconCanvas.Visibility = Visibility.Visible;
            RestoreIconCanvas.Visibility = Visibility.Collapsed;
            MaximizeRestoreButton.ToolTip = MakeThemedToolTip("Maximize");
        }
    }

    private void ActivateOwnedWindow()
    {
        if (_isClosing)
            return;

        try
        {
            if (WindowState == WindowState.Minimized)
                WindowState = WindowState.Normal;

            if (!IsVisible)
                Show();

            Activate();

            var wasTopmost = Topmost;
            if (!wasTopmost)
            {
                Topmost = true;
                Topmost = false;
            }

            var handle = new WindowInteropHelper(this).Handle;
            if (handle != nint.Zero)
                NativeMethods.TryActivateWindow(handle);

            Focus();
            if (PromptTextBox.IsEnabled)
                PromptTextBox.Focus();
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Workspace", $"Window activation failed: {ex.Message}");
        }
    }

    private async void MainWindow_Closed(object? sender, EventArgs e)
    {
        try
        {
            // SystemEvents and InputManager subscriptions are now routed through the broker via
            // WeakReference lambdas; the broker's dead-ref pruning handles GC safety.
            // Unsubscribe the broker handler fields so they are released immediately on close.
            if (_onUserPreferenceChanged is not null)   _broker.Unsubscribe(_onUserPreferenceChanged);
            if (_onPowerModeChanged is not null)         _broker.Unsubscribe(_onPowerModeChanged);
            if (_onMainPreProcessInput is not null)      _broker.Unsubscribe(_onMainPreProcessInput);
            if (_onGlobalPreProcessInput is not null)    _broker.Unsubscribe(_onGlobalPreProcessInput);
            if (_onHintRequested is not null)            _broker.Unsubscribe(_onHintRequested);
            if (_onDocRevisionCompleted is not null)     _broker.Unsubscribe(_onDocRevisionCompleted);
            DetachDispatcherDiagnostics();
            _isClosing = true;
            StopPttCtrlPollTimer();
            _promptHealthTimer.Stop();
            _statusPresentationTimer.Stop();
            _responseRenderTimer.Stop();
            _uiResponsivenessTimer.Stop();
            _teamRefreshDebounceTimer.Stop();
            CleanupActiveLoopCliProjection("window-closed");
            _speechService?.Dispose();
            _speechService = null;
            var pendingPlacement = _pendingWindowPlacement;
            var pendingUtilityWindowState = _pendingUtilityWindowState;
            var pendingDocsPanelState = _pendingDocsPanelState;
            var pendingConversation = _conversationManager.PendingConversationSave;
            var closedSw = Stopwatch.StartNew();
            SquadDashTrace.Write(TraceCategory.Shutdown, "MainWindow_Closed: begin async dispose (WhenAll).");
            await Task.WhenAll(
                Task.Run(() =>
                {
                    var sw = Stopwatch.StartNew();
                    RemoveRunningInstanceRegistration();
                    SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closed: RemoveRunningInstanceRegistration {sw.ElapsedMilliseconds}ms.");
                }),
                // All three settings saves share the same named mutex
                // (Local\SquadDash.ApplicationSettings).  Running them in separate
                // concurrent Tasks causes the re-entrant guard in MutexLease to reject
                // the second and third acquisition, silently dropping those saves.
                // Serialize them inside a single Task.Run to eliminate the contention.
                Task.Run(() =>
                {
                    var sw = Stopwatch.StartNew();
                    if (pendingPlacement is { } p)
                        _settingsStore.SaveWindowPlacement(p.FolderPath, p.Placement);
                    if (pendingUtilityWindowState is { } u)
                        _settingsStore.SaveUtilityWindowState(u.TasksOpen, u.TraceOpen, dockingTestPlaybackWindowOpen: u.PlaybackWindowOpen, traceWindowOffsetX: u.TraceOffsetX, traceWindowOffsetY: u.TraceOffsetY, guidedTourEditorOpen: u.GuidedTourEditorOpen);
                    if (pendingDocsPanelState is { } docs)
                        _settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, new WorkspaceDocsPanelState
                        {
                            Open = docs.Open ? null : false,
                            ExpandedNodes = docs.ExpandedNodes,
                            SelectedTopic = docs.SelectedTopic,
                            PanelWidth = docs.DocsPanelWidth,
                            PanelWidthFraction = docs.DocsPanelWidthFraction,
                            SourceOpen = docs.DocsSourceOpen,
                            SourceWidth = docs.DocsSourceWidth,
                        });
                    SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closed: settings saves {sw.ElapsedMilliseconds}ms.");
                }),
                Task.Run(() =>
                {
                    var sw = Stopwatch.StartNew();
                    if (pendingConversation is { } c)
                        _conversationManager.ConversationStore.Save(c.FolderPath, c.State);
                    SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closed: conversation save {sw.ElapsedMilliseconds}ms.");
                }),
                _bridge.DisposeAsync().AsTask().ContinueWith(t =>
                    SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closed: bridge dispose {closedSw.ElapsedMilliseconds}ms elapsed (status={t.Status}).")),
                _instanceActivationChannel.DisposeAsync().AsTask().ContinueWith(t =>
                    SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closed: activationChannel dispose {closedSw.ElapsedMilliseconds}ms elapsed (status={t.Status}).")));
            SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closed: WhenAll complete {closedSw.ElapsedMilliseconds}ms.");
            _workspaceOwnershipLease?.Dispose();
            _workspaceOwnershipLease = null;
            _startupWorkspaceLease?.Dispose();
            _startupWorkspaceLease = null;
            DisposeInboxWatcher();
            DisposeTeamFileWatcher();
            DisposeRestartRequestWatcher();
            DisposeDocsWatcher();
            DisposeCodeHealthMdWatcher();
            DisposeFeatureCategoryWatcher();
            DisposeGitHeadWatcher();
            _search.Dispose();
            SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closed: complete {closedSw.ElapsedMilliseconds}ms total.");
        }
        catch (Exception ex)
        {
            HandleUiCallbackException("Shutdown", ex, showDialog: false);
        }
        finally
        {
            // A hidden document/browser window can outlive MainWindow and keep the dispatcher
            // running forever. Restart coordinators wait for this process to exit, so explicitly
            // end the application only after all asynchronous persistence and disposal above.
            SquadDashTrace.Write(TraceCategory.Shutdown,
                "MainWindow_Closed: requesting explicit application shutdown after cleanup.");
            Application.Current?.Shutdown();
        }
    }

    private void EnsureTranscriptCardCopyItems(
        ContextMenu menu,
        FlowDocumentScrollViewer? selectionViewer,
        BlockUIContainer? cardContainer)
    {
        if (!TranscriptCardLayout.IsCard(cardContainer))
            return;

        const string selectionTag = "squaddash:copy-card-selection";
        const string cardTag = "squaddash:copy-whole-card";
        const string separatorTag = "squaddash:copy-card-separator";

        if (selectionViewer is not null)
        {
            var selectionItem = menu.Items.OfType<MenuItem>()
                .FirstOrDefault(item => string.Equals(item.Tag as string, selectionTag, StringComparison.Ordinal));
            if (selectionItem is null)
            {
                selectionItem = new MenuItem { Header = "_Copy", Tag = selectionTag };
                selectionItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                selectionItem.Click += (_, _) =>
                {
                    if (selectionItem.CommandParameter is string text && text.Length > 0)
                        SetClipboardTextWithRetry(text);
                };
                menu.Items.Add(selectionItem);
            }

            var selectedText = TranscriptCopyService.BuildSelectionText(selectionViewer);
            selectionItem.CommandParameter = selectedText;
            selectionItem.IsEnabled = !string.IsNullOrEmpty(selectedText);
        }

        var wholeCardItem = menu.Items.OfType<MenuItem>()
            .FirstOrDefault(item => string.Equals(item.Tag as string, cardTag, StringComparison.Ordinal));
        if (wholeCardItem is null)
        {
            if (menu.Items.Count > 0 && !menu.Items.OfType<Separator>()
                    .Any(separator => string.Equals(separator.Tag as string, separatorTag, StringComparison.Ordinal)))
            {
                var separator = new Separator { Tag = separatorTag };
                separator.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
                menu.Items.Add(separator);
            }

            wholeCardItem = new MenuItem { Header = "Copy _Card", Tag = cardTag };
            wholeCardItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
            wholeCardItem.Click += (_, _) =>
            {
                if (wholeCardItem.CommandParameter is BlockUIContainer container &&
                    TranscriptCopyService.BuildCardText(container) is { Length: > 0 } text)
                    SetClipboardTextWithRetry(text);
            };
            menu.Items.Add(wholeCardItem);
        }

        wholeCardItem.CommandParameter = cardContainer;
        wholeCardItem.IsEnabled = TranscriptCopyService.BuildCardText(cardContainer!) is { Length: > 0 };
    }

    private void MainWindow_Closing(object? sender, CancelEventArgs e)
    {
        try
        {
            _mainWindowClosingInProgress = true;
            var userCloseRequested = _userCloseRequested;
            _userCloseRequested = false;

            // If the restart-request watcher has not fired yet, adopt the persisted request
            // here so an automated launcher close cannot fall through to the manual-close dialog.
            TryAdoptPendingRestartRequestForClose();

            // If a deferred shutdown was already scheduled and has now fired, honour it — skip dialog.
            // Also skip dialog for rebuild-triggered restarts: the launcher wants to reload the new
            // binary immediately; queue items will resume in the reloaded instance.
            bool isDeferredClose = _deferredShutdown != DeferredShutdownMode.None ||
                                   (_restartPending && !userCloseRequested);

            if (_pttState == PttState.Active || _pttDraining)
            {
                e.Cancel = true;
                _restartPending = true;
                ResumeUiDispatchAfterCancelledClose();
                SquadDashTrace.Write("Shutdown", "Close requested while PTT active or draining. Deferring restart until final phrase is received.");
                EmergencySaveAfterDrainingBridgeEvents("close-while-ptt-active");
                return;
            }

            // If the clipboard image editor is open, save its state async so it can be
            // restored on next launch, then allow the close to proceed immediately.
            if (_clipboardEditorOpen)
            {
                _ = SaveAllClipboardEditorsAsync("window-closing");
                SquadDashTrace.Write("Shutdown", $"Close requested while {_clipboardEditorCount} ClipboardImageEditorWindow(s) open. State saved async; proceeding with close.");
            }

            // Safety-net: save positions for any inbox windows still open.
            foreach (var inboxWin in _openInboxWindows)
                FloatingWindowPositionStore.Shared.Save($"InboxMessage:{inboxWin.MessageId}", inboxWin);

            // Safety-net: save positions for any plan viewer windows still open.
            foreach (var (gid, planWin) in _openPlanViewerWindows)
                FloatingWindowPositionStore.Shared.Save($"PlanViewer:{gid}", planWin);

            if (_restartPending && !userCloseRequested && DeferPendingRestartIfBlocked("window-closing"))
            {
                e.Cancel = true;
                EmergencySaveAfterDrainingBridgeEvents("restart-close-deferred");
                ResumeUiDispatchAfterCancelledClose();
                return;
            }

            _backgroundTaskPresenter.RecoverStaleBackgroundThreads(DateTimeOffset.Now, "window-closing");

            // Queued items are only a blocking concern when they can begin executing.
            // Empty items, a manually paused queue, and a queue held by its active rightmost
            // tab are dormant persisted UI state, so closing immediately is safe.
            // Background work entries are treated the same way: if the queue is manually
            // paused and no prompt is actively running, stale background entries should not
            // block the close dialog.
            bool hasExecutableQueueItem = _promptQueue.Items.Any(item => !IsEmptyQueueItem(item));
            bool queueBlocking = ShutdownProtectionPolicy.HasQueueWorkThatCanStart(
                hasExecutableQueueItem,
                IsQueueDispatchHeld,
                IsRightmostQueueTabActive());
            bool backgroundWorkBlocking = (_isPromptRunning || !IsQueueDispatchHeld) &&
                                          _backgroundTaskPresenter.HasRestartBlockingBackgroundWork();
            bool isBusy = _isPromptRunning ||
                          IsNativeLoopRunning ||
                          backgroundWorkBlocking ||
                          HasPendingDirectQuickReplyAgentFollowUp() ||
                          queueBlocking;
            if (isBusy && !isDeferredClose)
            {
                e.Cancel = true;
                EmergencySaveAfterDrainingBridgeEvents("busy-close-dialog");

                var dialog = new ShutdownProtectionWindow(
                    isRunning: _isPromptRunning,
                    hasQueue: queueBlocking,
                    isLoopRunning: IsNativeLoopRunning,
                    blocker: GetRestartDeferralReason())
                {
                    Owner = this
                };

                if (dialog.ShowDialog() != true)
                {
                    SquadDashTrace.Write("Shutdown", "Close cancelled by user.");
                    ResumeUiDispatchAfterCancelledClose();
                    return;
                }

                switch (dialog.Choice)
                {
                    case ShutdownChoice.CloseNow:
                        SquadDashTrace.Write("Shutdown", "User chose Close Now — proceeding immediately.");
                        e.Cancel = false;
                        break; // fall through to cleanup below

                    case ShutdownChoice.AfterCurrentTurn:
                        _deferredShutdown = DeferredShutdownMode.AfterCurrentTurn;
                        SquadDashTrace.Write("Shutdown", "Deferred shutdown scheduled: after current turn.");
                        ResumeUiDispatchAfterCancelledClose();
                        return;

                    case ShutdownChoice.AfterAllQueued:
                        _deferredShutdown = DeferredShutdownMode.AfterAllQueued;
                        SquadDashTrace.Write("Shutdown", "Deferred shutdown scheduled: after all queued items.");
                        ResumeUiDispatchAfterCancelledClose();
                        return;

                    default:
                        ResumeUiDispatchAfterCancelledClose();
                        return;
                }
            }

            if (e.Cancel)
            {
                ResumeUiDispatchAfterCancelledClose();
                return;
            }

            // The tour editor is an owned window and may otherwise close after the
            // main-window shutdown sequence has begun. Flush it while all controls
            // and the active workspace are still intact.
            if (_guidedTourController?.FlushEditorChanges() == false)
            {
                e.Cancel = true;
                ResumeUiDispatchAfterCancelledClose();
                MessageBox.Show(
                    "The guided tour editor could not save its pending changes. Shutdown was cancelled.",
                    "Guided Tour Save Failed",
                    MessageBoxButton.OK,
                    MessageBoxImage.Warning);
                return;
            }

            // Flush any pending doc-source edits to disk BEFORE _isClosing is set.
            // This prevents two data-loss scenarios on build-triggered restarts:
            //   1. Unsaved edits in the 400 ms debounce window being silently dropped.
            //   2. WPF firing TextChanged on the RichTextBox during visual-tree teardown
            //      (template detachment / document reset) after _isClosing=true, which would
            //      restart the save timer with an empty document and then write
            //      frontmatter + "" to disk — wiping the file to frontmatter-only.
            _docSourceSaveTimer?.Stop();
            _docPreviewRefreshTimer?.Stop();
            SaveDocSourceToDisk();

            _deferredShutdown = DeferredShutdownMode.None;
            _isClosing = true;
            var closingSw = Stopwatch.StartNew();
            SquadDashTrace.Write(TraceCategory.Shutdown, "MainWindow_Closing: begin clean shutdown.");
            // Clear the loop resume flag on a user-initiated close so we don't auto-resume next
            // launch. On a build-triggered restart (_restartPending) we preserve the flag so the
            // new instance picks up where we left off and shows Stop/Abort instead of Start Loop.
            // A crash or kill signal never reaches this handler, so the flag also stays true there.
            if (_settingsSnapshot.LoopActiveOnExit && !_restartPending)
                _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
            var closeExecution = _conversationManager.ConversationState.ActiveLoopExecution;
            switch (LoopCloseRecoveryPolicy.Resolve(closeExecution, _restartPending))
            {
                case LoopCloseRecoveryAction.PreserveAutomaticResume:
                    _conversationManager.UpdatePendingManualLoopResumeState(null);
                    break;

                case LoopCloseRecoveryAction.OfferManualResume:
                    _conversationManager.UpdatePendingManualLoopResumeState(closeExecution);
                    _conversationManager.UpdateActiveLoopExecutionState(null);
                    break;

                case LoopCloseRecoveryAction.UsePlanRecovery:
                    // A normal close lets the durable plan repair path present its richer
                    // Assess/Resume actions rather than offering a generic loop restart.
                    _conversationManager.UpdatePendingManualLoopResumeState(null);
                    _conversationManager.UpdateActiveLoopExecutionState(null);
                    break;
            }
            // RC is intentionally NOT cleared on clean shutdown — we always want RC to auto-resume
            // on the next launch with the same token so the phone's saved link keeps working.
            // Users who want to stop RC should use "Stop Remote Access" explicitly (which clears
            // RemoteAccessActiveOnExit via HandleRcStopped).
            _instanceActivationChannel.Stop();
            SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closing: InstanceActivationChannel stopped {closingSw.ElapsedMilliseconds}ms.");
            // If a queued item is selected, the prompt box shows that item's text while the real
            // draft is stashed in _queuePreEditDraft. Switch back to Active Draft first so that
            // CaptureWorkspaceInputState reads the actual draft — not the queue item's text —
            // preventing a duplicate queue entry on the next launch.
            bool queueWasRightmostHeld = IsRightmostQueueTabActive();
            int? queueActiveTabIndex = FlushSelectedQueueEditorToDraft();
            // Persist the pre-switch tab identity. FlushSelectedQueueEditorToDraft flushes the
            // active item's live text/caret/selection without triggering a second state write or drain.
            _conversationManager.UpdateQueuedPromptsState(
                _promptQueue.Items,
                _followUpAttachments,
                queueRightmostHeld: queueWasRightmostHeld,
                loopQueuedToDequeue: _loopQueued,
                activeDraftSimEntry: _pec.ActiveDraftSimEntry,
                activeTabIndex: queueActiveTabIndex,
                queueDayCounter: _queueDayCounter,
                queueCounterDate: _queueCounterDate);
            SquadDashTrace.Write("Queue", $"Shutdown save: count={_promptQueue.Count} changedAt={QueueLastChangedForTrace()} wasHeld={queueWasRightmostHeld} restartPending={_restartPending} items={DescribeQueueForTrace(_promptQueue.Items)}");
            _conversationManager.CaptureWorkspaceInputState();
            CaptureWindowPlacement();
            _pendingUtilityWindowState = (
                _tasksStatusWindow is { IsVisible: true },
                _traceWindow is { IsVisible: true },
                _dockingTestPlaybackWindow is { IsVisible: true },
                _traceWindowOffset?.X,
                _traceWindowOffset?.Y,
                _guidedTourController?.IsEditorOpen ?? false);

            // Persist open inbox viewer IDs.
            if (_inboxStore is not null)
            {
                var openIds = _openInboxWindows
                    .Select(w => w.MessageId)
                    .Where(id => !string.IsNullOrEmpty(id))
                    .ToList();
                var inboxState = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
                _docsPanelState = inboxState with
                {
                    InboxPanelVisible = _inboxPanel?.PanelVisible ?? false,
                    OpenInboxMessageIds = openIds.Count > 0 ? openIds : [],
                };
                _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
            }

            // Persist open plan viewer IDs.
            var openPlanGroupIds = _openPlanViewerWindows
                .Select(entry => entry.GroupId)
                .Where(id => !string.IsNullOrEmpty(id))
                .ToList();
            var planViewerState = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
            _docsPanelState = planViewerState with
            {
                OpenPlanViewerGroupIds = openPlanGroupIds.Count > 0 ? openPlanGroupIds : [],
            };
            _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));

            // Capture docs panel state (only when panel is open; closed state is already
            // written by SetDocumentationMode when the user toggles it off).
            if (_documentationModeEnabled)
            {
                double? docsPanelWidth = null;
                double? docsPanelWidthFraction = null;
                if (DocsPanelColumn is not null && DocsPanelColumn.ActualWidth > 0)
                {
                    docsPanelWidth = DocsPanelColumn.ActualWidth;
                    if (MainGrid is not null && MainGrid.ActualWidth > 0)
                        docsPanelWidthFraction = DocsPanelColumn.ActualWidth / MainGrid.ActualWidth;
                }
                bool? docsSourceOpen = IsDocSourceVisible() ? true : (bool?)null;
                double? docsSourceWidth = IsDocSourceVisible() ? GetDocSourceSize() : (double?)null;

                _pendingDocsPanelState = (
                    Open: true,
                    ExpandedNodes: DocTopicsTreeView is not null
                        ? CollectExpandedDocNodes(DocTopicsTreeView.Items)
                        : null,
                    SelectedTopic: (DocTopicsTreeView?.SelectedItem as TreeViewItem)?.Tag as string,
                    DocsPanelWidth: docsPanelWidth,
                    DocsTopicsWidth: null,
                    DocsPanelWidthFraction: docsPanelWidthFraction,
                    DocsTopicsWidthFraction: null,
                    DocsSourceOpen: docsSourceOpen,
                    DocsSourceWidth: docsSourceWidth);

                // Save synchronously here — MainWindow_Closed is async void and may not
                // complete before the process exits.
                var s = _pendingDocsPanelState.Value;
                var docsPanelSaveSw = Stopwatch.StartNew();
                _settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, new WorkspaceDocsPanelState
                {
                    Open = s.Open ? null : false,
                    ExpandedNodes = s.ExpandedNodes,
                    SelectedTopic = s.SelectedTopic,
                    PanelWidth = s.DocsPanelWidth,
                    PanelWidthFraction = s.DocsPanelWidthFraction,
                    SourceOpen = s.DocsSourceOpen,
                    SourceWidth = s.DocsSourceWidth,
                });
                SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closing: SaveDocsPanelState(docs-open) {docsPanelSaveSw.ElapsedMilliseconds}ms elapsed={closingSw.ElapsedMilliseconds}ms.");
            }
            // Write synchronously so state is on disk before the process exits.
            if (_pendingDocsPanelState is { } docs)
            {
                var pendingDocsSaveSw = Stopwatch.StartNew();
                _settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, new WorkspaceDocsPanelState
                {
                    Open = docs.Open ? null : false,
                    ExpandedNodes = docs.ExpandedNodes,
                    SelectedTopic = docs.SelectedTopic,
                    PanelWidth = docs.DocsPanelWidth,
                    PanelWidthFraction = docs.DocsPanelWidthFraction,
                    SourceOpen = docs.DocsSourceOpen,
                    SourceWidth = docs.DocsSourceWidth,
                });
                SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closing: SaveDocsPanelState(pending) {pendingDocsSaveSw.ElapsedMilliseconds}ms elapsed={closingSw.ElapsedMilliseconds}ms.");
            }
            var emergencySaveSw = Stopwatch.StartNew();
            if (_currentWorkspace is not null)
            {
                SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closing: SaveWorkspaceShutdownTime path={_currentWorkspace.FolderPath}");
                _settingsStore.SaveWorkspaceShutdownTime(_currentWorkspace.FolderPath, DateTimeOffset.UtcNow);
                SquadDashTrace.Write(TraceCategory.Shutdown, "MainWindow_Closing: SaveWorkspaceShutdownTime done.");
            }
            else
            {
                SquadDashTrace.Write(TraceCategory.Shutdown, "MainWindow_Closing: _currentWorkspace is null — skipping SaveWorkspaceShutdownTime.");
            }
            // If a guided tour is active, stop it synchronously before saving so that demo agents
            // and dummy queue items created by the tour are removed before they can be persisted.
            if (_guidedTourController?.IsActive == true)
            {
                SquadDashTrace.Write(TraceCategory.Shutdown, "MainWindow_Closing: guided tour active — stopping tour and purging tour artifacts before save.");
                // StopTourForShutdown clears the controller's tracking list. Preserve the IDs so
                // cleanup can still remove the exact synthetic threads created by this tour.
                var injectedThreadIds = _guidedTourController.InjectedThreadIds.ToArray();
                _guidedTourController.StopTourForShutdown();
                CleanUpTourInjectedThreads(injectedThreadIds);
                CleanUpTourQueueItems();
                SquadDashTrace.Write(TraceCategory.Shutdown, "MainWindow_Closing: tour artifacts purged.");
            }
            EmergencySaveAfterDrainingBridgeEvents("main-window-closing");
            SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closing: EmergencySave {emergencySaveSw.ElapsedMilliseconds}ms elapsed={closingSw.ElapsedMilliseconds}ms.");
            SquadDashTrace.Write(TraceCategory.Shutdown, $"MainWindow_Closing: complete {closingSw.ElapsedMilliseconds}ms.");
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(MainWindow_Closing), ex, showDialog: false);
        }
    }

    /// <summary>
    /// Synchronously flushes all conversation state (including any in-flight turn) to disk.
    /// Safe to call from Closing, unhandled exception handlers, or any crash path.
    /// </summary>

    private void UpdateRunningInstanceRegistration()
    {
        try
        {
            var launchFolder = _currentWorkspace?.FolderPath;
            if (string.IsNullOrWhiteSpace(launchFolder))
            {
                launchFolder = StartupWorkspaceResolver.Resolve(
                    null,
                    _settingsSnapshot.LastOpenedFolder,
                    TryGetApplicationRoot()) ?? Environment.CurrentDirectory;
            }

            _instanceRegistry.Upsert(new RunningInstanceRecord(
                _workspacePaths.ApplicationRoot,
                launchFolder,
                Environment.ProcessId,
                _processStartedAtUtcTicks,
                DateTimeOffset.UtcNow.Ticks)
            {
                ActiveWorkspaceFolder = _currentWorkspace?.FolderPath
            });
        }
        catch
        {
        }
    }

    private void CaptureWindowPlacement()
    {
        if (_currentWorkspace is null)
            return;

        try
        {
            var bounds = WindowState == WindowState.Normal ? new Rect(Left, Top, Width, Height) : RestoreBounds;
            if (bounds.Width <= 0 || bounds.Height <= 0)
                return;

            _pendingWindowPlacement = (
                _currentWorkspace.FolderPath,
                new WorkspaceWindowPlacement(
                    bounds.Left,
                    bounds.Top,
                    bounds.Width,
                    bounds.Height,
                    WindowState == WindowState.Maximized));
        }
        catch
        {
        }
    }

    private void SaveWorkspaceWindowPlacement()
    {
        if (_currentWorkspace is null)
            return;

        try
        {
            var bounds = WindowState == WindowState.Normal ? new Rect(Left, Top, Width, Height) : RestoreBounds;
            if (bounds.Width <= 0 || bounds.Height <= 0)
                return;

            _settingsManager.Replace(_settingsStore.SaveWindowPlacement(
                _currentWorkspace.FolderPath,
                new WorkspaceWindowPlacement(
                    bounds.Left,
                    bounds.Top,
                    bounds.Width,
                    bounds.Height,
                    WindowState == WindowState.Maximized)));
        }
        catch
        {
        }
    }

    private void RestoreWorkspaceWindowPlacement()
    {
        if (_currentWorkspace is null)
            return;

        if (!_settingsSnapshot.WindowPlacementByWorkspace.TryGetValue(_currentWorkspace.FolderPath, out var placement))
            return;

        if (!placement.IsUsable)
            return;

        WindowState = WindowState.Normal;
        Left = placement.Left;
        Top = placement.Top;
        Width = placement.Width;
        Height = placement.Height;

        if (!IsPlacementOnScreen(placement))
        {
            Left = SystemParameters.WorkArea.Left;
            Top = SystemParameters.WorkArea.Top;
        }
        else
        {
            // Validate that the restored bounds fit within the work area of the
            // nearest monitor. IsPlacementOnScreen only checks the title-bar strip
            // (Left .. Left+200, Top .. Top+30), so it passes even when a stale
            // narrow Width (saved from a remote/phone session) causes Left + Width
            // to overflow the monitor's right edge. When that happens, Windows
            // keeps the snapped HWND at the full docked width while WPF's layout
            // commits to the narrow saved Width — producing a solid black void to
            // the right of the visible content area. Clamping here prevents that.
            ClampRestoredBoundsToMonitor();
        }

        if (placement.IsMaximized)
            WindowState = WindowState.Maximized;
    }

    /// <summary>
    /// After applying a persisted placement, verifies that the window's right
    /// and bottom edges lie within the work area of the nearest monitor.
    /// If either edge overflows — which happens when a placement saved on a
    /// narrow display (e.g. an iPhone remote session) is restored on a wider
    /// one while the window is snapped/docked — the window is reset to a safe
    /// default size centred on that monitor's work area.
    /// </summary>
    private void ClampRestoredBoundsToMonitor()
    {
        try
        {
            // Convert WPF logical origin to physical pixels for the monitor query.
            var dpi   = System.Windows.Media.VisualTreeHelper.GetDpi(this);
            int physX = (int)(Left * dpi.DpiScaleX);
            int physY = (int)(Top  * dpi.DpiScaleY);

            var physWa  = NativeMethods.GetWorkAreaForPhysicalPoint(physX, physY);

            // Convert physical work-area edges back to WPF logical units.
            double waLeft   = physWa.Left   / dpi.DpiScaleX;
            double waTop    = physWa.Top    / dpi.DpiScaleY;
            double waRight  = physWa.Right  / dpi.DpiScaleX;
            double waBottom = physWa.Bottom / dpi.DpiScaleY;
            double waWidth  = waRight  - waLeft;
            double waHeight = waBottom - waTop;

            // Allow 1 logical pixel of rounding slack.
            bool overflowsRight  = Left + Width  > waRight  + 1.0;
            bool overflowsBottom = Top  + Height > waBottom + 1.0;

            if (overflowsRight || overflowsBottom)
            {
                // The persisted dimensions don't fit on the current monitor — most
                // likely the window was saved on a narrower display. Reset to a
                // comfortable default, centred on this monitor's work area.
                double safeWidth  = Math.Min(1200.0, waWidth);
                double safeHeight = Math.Min( 820.0, waHeight);

                // Never shrink below the window's declared minimum dimensions.
                if (safeWidth  < MinWidth)  safeWidth  = MinWidth;
                if (safeHeight < MinHeight) safeHeight = MinHeight;

                Width  = safeWidth;
                Height = safeHeight;
                Left   = waLeft + (waWidth  - safeWidth)  / 2.0;
                Top    = waTop  + (waHeight - safeHeight) / 2.0;
            }
        }
        catch
        {
            // Non-critical: if anything goes wrong the already-applied placement
            // is left as-is. The window may not be perfectly positioned but it
            // will still be functional.
        }
    }

    private static bool IsPlacementOnScreen(WorkspaceWindowPlacement placement)
    {
        // Check that a usable strip across the top of the window (title bar area) intersects
        // at least one monitor's working area, so the user can always grab and move the window.
        var titleBarLeft = (int)placement.Left;
        var titleBarTop = (int)placement.Top;
        var titleBarRight = (int)(placement.Left + Math.Min(placement.Width, 200));
        var titleBarBottom = (int)(placement.Top + 30);

        return NativeMethods.IsRectOnAnyMonitor(titleBarLeft, titleBarTop, titleBarRight, titleBarBottom);
    }

    private void RemoveRunningInstanceRegistration()
    {
        try
        {
            _instanceRegistry.Remove(
                _workspacePaths.ApplicationRoot,
                Environment.ProcessId,
                _processStartedAtUtcTicks);
        }
        catch
        {
        }
    }

    internal void ReportUnhandledUiException(
        string operation,
        Exception ex,
        bool showPanel = true,
        string? diagnosticContext = null)
    {
        if (Dispatcher.CheckAccess())
        {
            HandleUiCallbackException(operation, ex, showDialog: showPanel, diagnosticContext: diagnosticContext);
            return;
        }

        TryPostToUi(
            () => HandleUiCallbackException(operation, ex, showDialog: showPanel, diagnosticContext: diagnosticContext),
            $"Unhandled.{operation}");
    }

    private void HandleUiCallbackException(
        string operation,
        Exception ex,
        bool showDialog = true,
        string? diagnosticContext = null)
    {
        SquadDashTrace.Write("UI", $"{operation} callback failed: {ex}");

        if (!showDialog || _isClosing || Dispatcher.HasShutdownStarted || Dispatcher.HasShutdownFinished)
            return;

        try
        {
            ShowExceptionPanel(operation, ex, diagnosticContext);
        }
        catch (Exception panelEx)
        {
            SquadDashTrace.Write("UI", $"Failed to show exception panel for {operation}: {panelEx}");

            if (!CanShowOwnedWindow())
                return;

            try
            {
                UIErrorHelper.ShowError(operation, $"{operation} failed.{Environment.NewLine}{Environment.NewLine}{ex.Message}");
            }
            catch
            {
            }
        }
    }

    private void ShowExceptionPanel(string operation, Exception ex, string? diagnosticContext = null)
    {
        var title = $"{operation} failed";
        var summary = string.IsNullOrWhiteSpace(ex.Message)
            ? "An unexpected error occurred."
            : ex.Message.Trim();
        var details = BuildExceptionPanelDetails(operation, ex, diagnosticContext);

        _activeUiException = new UiExceptionPanelState(title, summary, details);
        ExceptionPanelTitleTextBlock.Text = title;
        ExceptionPanelSummaryTextBlock.Text = summary;
        ExceptionPanelTextBox.Text = details;
        ExceptionPanelTextBox.ScrollToHome();
        AddExceptionToChatButton.Visibility = SquadDashEnvironment.IsDeveloperMode ? Visibility.Visible : Visibility.Collapsed;
        ExceptionPanelBorder.Visibility = Visibility.Visible;
        UpdateLeadAgent("Error", string.Empty, summary);
        UpdateSessionState("Error");
    }

    private static string BuildExceptionPanelDetails(
        string operation,
        Exception ex,
        string? diagnosticContext = null)
    {
        var builder = new StringBuilder();
        builder.AppendLine($"Operation: {operation}");
        builder.AppendLine($"Occurred: {DateTimeOffset.Now:O}");
        builder.AppendLine();
        builder.AppendLine(ex.ToString());
        if (!string.IsNullOrWhiteSpace(diagnosticContext))
        {
            builder.AppendLine();
            builder.AppendLine(diagnosticContext.Trim());
        }
        return builder.ToString().TrimEnd();
    }

    private void CopyExceptionDetailsButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_activeUiException is null || string.IsNullOrWhiteSpace(_activeUiException.Details))
                return;

            Clipboard.SetText(_activeUiException.Details);
            SquadDashTrace.Write("UI", "Copied exception details to clipboard.");
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(CopyExceptionDetailsButton_Click), ex);
        }
    }

    private void AddExceptionToChatButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_activeUiException is null || string.IsNullOrWhiteSpace(_activeUiException.Details))
                return;

            AttachContextFollowUp(
                BuildClipboardAttachDescription(_activeUiException.Details),
                BuildTypedAttachmentBlock("clipboard", _activeUiException.Title, _activeUiException.Details));
            
            // Pre-fill an evidence-first diagnostic request. A framework-only stack can
            // still be triggered by application teardown during WPF input routing.
            var errorPromptText = UiExceptionChatPromptBuilder.Build();
            SetPromptTextBoxLogicalBuffer(
                text: errorPromptText,
                caretIndex: 0,
                selectionStart: 0,
                selectionLength: errorPromptText.Length,
                reason: "error-add-to-chat");
            
            // Focus the prompt box so the user can immediately start typing
            PromptTextBox.Focus();
            
            SquadDashTrace.Write("UI", "Added exception details to chat and pre-filled prompt.");
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(AddExceptionToChatButton_Click), ex);
        }
    }

