    private MenuItem? OpenSquadFolderMenuItem;
    // Temporary accumulator used while building the sorted top group in RefreshSidebar.
    private readonly List<(string Header, string SortKey, Action ClickAction)> _squadFileMenuEntries = [];

    private void RefreshSidebar()
    {
        ClearWorkspaceMenuFileItems();
        DisposeInboxWatcher();

        if (_currentWorkspace is null)
        {
            OpenSquadFolderMenuItem?.IsEnabled = false;
            UpdateInteractiveControlState();
            SyncTasksPanel();
            return;
        }

        RefreshInstallationState();

        var squadRoot = _currentWorkspace.SquadFolderPath;
        var squadFolderExists = Directory.Exists(squadRoot);
        ConfigureTeamFileWatcher();
        InitCodeHealthMdWatcher(squadRoot);

        var loopMdPath        = Path.Combine(squadRoot, "loop.md");
        var maintenanceMdPath = Path.Combine(squadRoot, "code-health.md");
        var tasksMdPath       = Path.Combine(squadRoot, "tasks.md");

        // 1. Cast New Agent — topmost item
        var castMenuItem = new MenuItem
        {
            Header = "👤 _Cast New Agent",
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };
        castMenuItem.Click += (_, _) =>
        {
            var submission = ShowCastAgentWindow();
            if (submission is null)
                return;
            EnqueuePrompt(submission.PromptText, isSystemInjected: false);
        };
        WorkspaceMenuItem.Items.Add(castMenuItem);

        WorkspaceMenuItem.Items.Add(new Separator { Style = (Style)FindResource("ThemedMenuSeparatorStyle") });

        // 2. "Files & Folders" submenu
        var filesAndFoldersMenuItem = new MenuItem
        {
            Header = "Files & _Folders",
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };

        // Regular squad files: added only when they exist.
        foreach (var relativePath in new[] {
                     "ceremonies.md",
                     "decisions.md",
                     "history.md",
                     Path.Combine("identity", "now.md"),
                     "routing.md",
                     Path.Combine("skills", "project-conventions", "SKILL.md"),
                     "team.md",
                     Path.Combine("identity", "wisdom.md")
                 })
        {
            var fullPath = Path.Combine(squadRoot, relativePath);
            if (File.Exists(fullPath))
            {
                var e = new SidebarEntry("📄" + Path.GetFileName(relativePath), string.Empty, fullPath, true, SidebarEntryKind.File);
                _squadFileMenuEntries.Add(("📄" + Path.GetFileName(relativePath), Path.GetFileName(relativePath), () => OpenSidebarEntry(e)));
            }
        }

        // loop.md, code-health.md, and tasks.md always appear; clicking creates the file when missing.
        _squadFileMenuEntries.Add(("🔁 loop.md",        "loop.md",        () => OpenOrCreateLoopMd(loopMdPath)));
        _squadFileMenuEntries.Add(("🔧 code-health.md", "code-health.md", () => OpenOrCreateCodeHealthMd(maintenanceMdPath)));
        _squadFileMenuEntries.Add(("📋 tasks.md",       "tasks.md",       () => OpenOrCreateTasksMd(tasksMdPath)));

        foreach (var (header, _, clickAction) in _squadFileMenuEntries.OrderBy(x => x.SortKey, StringComparer.OrdinalIgnoreCase))
        {
            var fileMenuItem = new MenuItem { Header = header, Style = (Style)FindResource("ThemedMenuItemStyle") };
            fileMenuItem.Click += (_, _) => clickAction();
            filesAndFoldersMenuItem.Items.Add(fileMenuItem);
        }
        _squadFileMenuEntries.Clear();

        filesAndFoldersMenuItem.Items.Add(new Separator { Style = (Style)FindResource("ThemedMenuSeparatorStyle") });

        OpenSquadFolderMenuItem = new MenuItem
        {
            Header = "📂 _Squad Folder",
            Name = "OpenSquadFolderMenuItem",
            IsEnabled = squadFolderExists,
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };
        OpenSquadFolderMenuItem.Click += OpenSquadFolderMenuItem_Click;
        filesAndFoldersMenuItem.Items.Add(OpenSquadFolderMenuItem);

        var inboxRelativePath = Path.Combine("decisions", "inbox");
        var inboxPath = Path.Combine(squadRoot, inboxRelativePath);
        if (Directory.Exists(inboxPath))
        {
            var inboxFileCount = CountFiles(inboxPath);
            var inboxEntry = new SidebarEntry(
                $"📂{Path.GetFileName(inboxRelativePath)} folder ({inboxFileCount})",
                string.Empty,
                inboxPath,
                true,
                SidebarEntryKind.Folder);
            var inboxMenuItem = new MenuItem
            {
                Header = inboxEntry.Title,
                Tag = inboxEntry,
                Style = (Style)FindResource("ThemedMenuItemStyle")
            };
            inboxMenuItem.Click += (_, _) => OpenSidebarEntry(inboxEntry);
            filesAndFoldersMenuItem.Items.Add(inboxMenuItem);
        }

        WorkspaceMenuItem.Items.Add(filesAndFoldersMenuItem);

        PopulateLoopFilePicker();
        RefreshLoopOptionsPanel();
        UpdateLoopPanelButtonStates();
        _pec.TasksFilePath = tasksMdPath;

        AddWorkspaceMenuSeparator();

        var squadCliMenuItem = new MenuItem
        {
            Header = "Squad _CLI",
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };
        squadCliMenuItem.Click += SquadCliMenuItem_Click;
        WorkspaceMenuItem.Items.Add(squadCliMenuItem);

        var discoverSquadsMenuItem = new MenuItem
        {
            Header = "Discover S_quads",
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };
        discoverSquadsMenuItem.Click += DiscoverSquadsMenuItem_Click;
        WorkspaceMenuItem.Items.Add(discoverSquadsMenuItem);

        var delegateToSquadMenuItem = new MenuItem
        {
            Header = "_Delegate to Squad...",
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };
        delegateToSquadMenuItem.Click += DelegateToSquadMenuItem_Click;
        WorkspaceMenuItem.Items.Add(delegateToSquadMenuItem);

        _remoteAccessMenuItem = new MenuItem
        {
            Header = _settingsSnapshot.RemoteAccessActiveOnExit ? "Stop _Remote Access" : "Start _Remote Access",
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };
        _remoteAccessMenuItem.Click += RemoteAccessMenuItem_Click;
        RemoteMenuItem.Items.Add(_remoteAccessMenuItem);

        EnsureTintMenuItems();
        BuildContrastMenuItem();
        BuildSaturationMenuItem();

        AddWorkspaceMenuSeparator();

        var powershellMenuItem = new MenuItem
        {
            Header = "PowerShell",
            Style = (Style)FindResource("ThemedMenuItemStyle")
        };
        powershellMenuItem.Click += PowerShellMenuItem_Click;
        WorkspaceMenuItem.Items.Add(powershellMenuItem);

        ConfigureInboxWatcher(Path.Combine(squadRoot, "inbox"));
        UpdateInteractiveControlState();
        SyncTasksPanel();
    }

