    private void ConfigureGitHeadWatcher()
    {
        _watcherCoordinator.DisposeGitHeadWatcher();
        if (_currentWorkspace is null)
        {
            UpdateBranchIndicator();
            return;
        }
        var gitDir = WorkspaceIdentityPresentation
            .Resolve(_currentWorkspace.FolderPath, branch: null)
            .GitDirectory;
        if (string.IsNullOrWhiteSpace(gitDir) || !Directory.Exists(gitDir))
        {
            UpdateBranchIndicator();
            return;
        }
        _watcherCoordinator.TryConfigureGitHeadWatcher(gitDir);
        UpdateBranchIndicator();
    }

    private static bool HasGitRemote(string workspaceFolder)
    {
        try
        {
            var gitConfigPath = WorkspaceIdentityPresentation
                .Resolve(workspaceFolder, branch: null)
                .GitConfigPath;
            if (string.IsNullOrWhiteSpace(gitConfigPath) || !File.Exists(gitConfigPath))
                return false;
            var config = File.ReadAllText(gitConfigPath);
            return config.Contains("[remote \"origin\"]", StringComparison.Ordinal)
                || config.Contains("[remote 'origin']", StringComparison.Ordinal);
        }
        catch
        {
            return false;
        }
    }

    private static string ReadGitBranch(string workspaceFolder)
    {
        try
        {
            return WorkspaceIdentityPresentation.Resolve(workspaceFolder, branch: null).Branch
                ?? string.Empty;
        }
        catch
        {
            return string.Empty;
        }
    }

    private static readonly PlanRecoveryGitQuery PlanRecoveryGit = new();

    private readonly PlanRecoveryGitPresentationCache _recoveryGitPresentationCache = new();

    private PlanRecoveryGitSnapshot? RecoveryPresentationSnapshot =>
        string.Equals(_recoveryGitPresentationCache.Current?.Workspace, _currentWorkspace?.FolderPath, StringComparison.OrdinalIgnoreCase)
            ? _recoveryGitPresentationCache.Current
            : null;

    private string? ReadCachedRecoveryHeadCommit() => RecoveryPresentationSnapshot?.Head;

    private bool IsCachedRecoveryAncestor(string ancestor, string descendant) =>
        RecoveryPresentationSnapshot?.IsAncestor(ancestor, descendant) == true;

    private async Task RefreshRecoveryGitSnapshotAsync(bool refreshSurfaces = false)
    {
        var workspace = _currentWorkspace?.FolderPath;
        var store = _planStore;
        var version = _recoveryGitPresentationCache.BeginRefresh(workspace, refreshSurfaces);
        if (workspace is null || store is null) return;
        var commits = store.LoadAll()
            .Select(plan => plan.InterruptionData?.TaskCommitEvidence?.Commit)
            .OfType<string>().ToArray();
        using var budget = new CancellationTokenSource(TimeSpan.FromSeconds(5));
        var snapshot = await PlanRecoveryGit.ReadSnapshotAsync(workspace, commits, budget.Token);
        if (!ReferenceEquals(store, _planStore) ||
            !string.Equals(workspace, _currentWorkspace?.FolderPath, StringComparison.OrdinalIgnoreCase))
            return;
        if (!_recoveryGitPresentationCache.TryApply(version, snapshot, out var shouldRefreshSurfaces))
            return;
        if (shouldRefreshSurfaces)
        {
            foreach (var plan in store.LoadAll().Where(plan =>
                         plan.LifecycleStatus is PlanLifecycleStatus.Interrupted or PlanLifecycleStatus.Blocked))
                RefreshHumanReviewSurfaces(plan);
            SyncPlansPanel();
            _recoveryGitPresentationCache.MarkRendered();
        }
    }

    private async Task RefreshBranchIfChangedAsync()
    {
        // Capture workspace folder on the UI thread before going async.
        var folder = _currentWorkspace?.FolderPath;
        if (folder is null)
            return;

        var branch = await Task.Run(() => ReadGitBranch(folder));
        var previousHead = ReadCachedRecoveryHeadCommit();
        await RefreshRecoveryGitSnapshotAsync(refreshSurfaces: true);
        var currentHead = ReadCachedRecoveryHeadCommit();
        if (_activeDecomposeGroupId is not null &&
            !string.IsNullOrWhiteSpace(previousHead) &&
            !string.IsNullOrWhiteSpace(currentHead) &&
            !string.Equals(previousHead, currentHead, StringComparison.OrdinalIgnoreCase))
            _loopController.RenewIterationLease(LoopIterationProgressKind.CommitObserved);
        if (branch != _currentBranch)
            await Dispatcher.InvokeAsync(UpdateBranchIndicator);
    }

    private int _branchIndicatorRevision;
    private static readonly TimeSpan RecentBranchRefreshInterval = TimeSpan.FromMinutes(5);
    private string? _lastRecordedBranchWorkspace;
    private string? _lastRecordedBranch;
    private DateTimeOffset _lastRecordedBranchUtc;

    private async void UpdateBranchIndicator()
    {
        var revision = ++_branchIndicatorRevision;
        if (_currentWorkspace is null)
        {
            _lastRecordedBranch = null;
            SetPromptStripVisibilityPreservingViewports(
                BranchIndicatorStrip,
                Visibility.Collapsed,
                "branch strip hidden without workspace");
            SetPromptStripVisibilityPreservingViewports(
                NoRepoPromptStrip,
                Visibility.Collapsed,
                "repository prompt hidden without workspace");
            WorkspaceTitleText.ToolTip = null;
            return;
        }

        var workspaceFolder = _currentWorkspace.FolderPath;
        var branch = ReadGitBranch(workspaceFolder);
        _currentBranch = branch;
        var identity = WorkspaceIdentityPresentation.Resolve(workspaceFolder, branch);
        WorkspaceTitleText.ToolTip = MakeThemedToolTip(identity.BuildTooltip(includeRevealHint: true));
        BranchIndicatorStrip.ToolTip = MakeThemedToolTip(identity.BuildTooltip(includeRevealHint: false));

        if (identity.RepositoryRoot is not null && !string.IsNullOrWhiteSpace(branch)
            && branch != "(detached)" && !branch.StartsWith("(detached ", StringComparison.Ordinal))
        {
            var nowUtc = DateTimeOffset.UtcNow;
            if (!string.Equals(_lastRecordedBranchWorkspace, workspaceFolder, StringComparison.OrdinalIgnoreCase)
                || !string.Equals(_lastRecordedBranch, branch, StringComparison.Ordinal)
                || nowUtc < _lastRecordedBranchUtc
                || nowUtc - _lastRecordedBranchUtc >= RecentBranchRefreshInterval)
            {
                try
                {
                    _settingsManager.Replace(_settingsStore.RecordRecentBranch(workspaceFolder, branch, nowUtc));
                    _lastRecordedBranchWorkspace = workspaceFolder;
                    _lastRecordedBranch = branch;
                    _lastRecordedBranchUtc = nowUtc;
                }
                catch (Exception ex)
                {
                    SquadDashTrace.Write("Branch", $"Could not record recent branch '{branch}': {ex}");
                }
            }
        }
        else
        {
            _lastRecordedBranch = null;
        }

        if (string.IsNullOrEmpty(branch))
        {
            SetPromptStripVisibilityPreservingViewports(
                BranchIndicatorStrip,
                Visibility.Collapsed,
                "branch strip hidden without repository");
            // Only offer "Initialize repository" once the workspace has real team members —
            // an empty or Squad-only folder has nothing meaningful to commit yet.
            SetPromptStripVisibilityPreservingViewports(
                NoRepoPromptStrip,
                WorkspaceHasRealTeamMembers() ? Visibility.Visible : Visibility.Collapsed,
                "repository prompt visibility changed");
            return;
        }

        SetPromptStripVisibilityPreservingViewports(
            NoRepoPromptStrip,
            Visibility.Collapsed,
            "repository prompt hidden for repository");
        SetPromptStripVisibilityPreservingViewports(
            BranchIndicatorStrip,
            Visibility.Visible,
            "branch strip shown for repository");

        HomeBranchResolution resolution;
        string? resolutionError = null;
        try
        {
            resolution = await ResolveHomeBranchAsync(workspaceFolder);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Branch", $"Could not resolve home branch: {ex}");
            if (revision != _branchIndicatorRevision) return;
            resolutionError = $"Could not read the local home branch: {ex.Message}";
            resolution = new(null, HomeBranchResolutionSource.None, false);
        }
        if (revision != _branchIndicatorRevision
            || _currentWorkspace?.FolderPath != workspaceFolder || _currentBranch != branch)
            return;
        if ((resolutionError ?? resolution.Notice) is { } notice)
            BranchIndicatorStrip.ToolTip = MakeThemedToolTip($"{identity.BuildTooltip(includeRevealHint: false)}\n\n{notice}");

        bool isMaintenance = branch.StartsWith("maintenance/", StringComparison.OrdinalIgnoreCase)
                          || branch.StartsWith("hotfix/", StringComparison.OrdinalIgnoreCase);
        bool isHomeBranch = _settingsSnapshot.IsHomeBranch(resolution, branch);

        if (isMaintenance)
        {
            BranchDot.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, "PriorityCritical");
            BranchNameText.SetResourceReference(TextBlock.ForegroundProperty, "ImportantText");
            BranchNameText.Text = $"⚠ {branch}";
        }
        else if (isHomeBranch)
        {
            BranchDot.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, "ScrollBarThumbBrush");
            BranchNameText.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");
            BranchNameText.Text = branch;
        }
        else
        {
            BranchDot.SetResourceReference(System.Windows.Shapes.Shape.FillProperty, "PriorityCritical");
            BranchNameText.SetResourceReference(TextBlock.ForegroundProperty, "ImportantText");
            BranchNameText.Text = branch;
        }
    }

