    private void EnsureTintMenuItems()
    {
        if (TintMenuItem.Items.Count > 0)
        {
            UpdateTintMenuState();
            for (int i = 0; i < TintMenuItem.Items.Count; i++)
            {
                if (TintMenuItem.Items[i] is MenuItem existing)
                    ApplyTintSwatchToItem(existing, i);
            }
            return;
        }
        string[] labels = ["Natural", "Amber", "Mint", "Sage", "Aqua", "Sky", "Plum", "Blush"];
        for (int i = 0; i < labels.Length; i++)
        {
            var stop = i;
            var item = new MenuItem
            {
                Header    = labels[i],
                IsCheckable = true,
                IsChecked   = _activeTintStop == stop,
                Style       = (Style)FindResource("TintMenuItemStyle")
            };
            ApplyTintSwatchToItem(item, stop);
            item.Click += (_, _) =>
            {
                try { SetWorkspaceTintStop(stop); }
                catch (Exception ex) { HandleUiCallbackException("TintStop_Click", ex); }
            };
            TintMenuItem.Items.Add(item);
        }
    }

