    private void SyncApprovalPanel()
    {
        if (ApprovalPanelBorder is null) return;
        ApprovalPanelBorder.Visibility = _approvalPanelVisible ? Visibility.Visible : Visibility.Collapsed;
        _dockingService?.OnPanelVisibilityChanged("approvals", _approvalPanelVisible);
        NotifyToolPanelVisibilityChanged("approvals", _approvalPanelVisible);
        UpdateMainGridSideMargins();
        if (_approvalPanelVisible && _approvalPanel is null)
        {
            _approvalPanel = new CommitApprovalPanel(
                ApprovalNeedsPanel!,
                ApprovalApprovedPanel!,
                ApprovalRejectedPanel!,
                ApprovalRejectedSection!,
                ApprovalApprovedSection!,
                ApprovalApprovedScrollViewer!,
                ApprovalPanelBorder!,
                ApprovalNeedsScrollViewer!,
                navigateUrl: url => _ = OpenExternalLinkWithCommitCheckAsync(url),
                scrollToTurn: item => ScrollToApprovalTurn(item),
                onItemChanged: item => OnApprovalItemChanged(item),
                onItemsRemoved: items => OnApprovalItemsRemoved(items),
                onFollowUp: item => AttachFollowUpToActiveTab(item),
                addToNewChat: item => { AddEmptyQueueSlot(); AttachFollowUpToActiveTab(item); },
                addToNotes: item => AddNoteFromTextWithTitle(
                    $"Approval - {item.Description}",
                    BuildApprovalContentBlock(item)),
                initialShowApproved: _settingsStore.Load().ApprovalShowApproved,
                onShowApprovedChanged: show => _settingsStore.SaveApprovalShowApproved(show),
                initialShowRejected: _settingsStore.Load().ApprovalShowRejected,
                onShowRejectedChanged: show => _settingsStore.SaveApprovalShowRejected(show),
                initialGroupedView: _settingsStore.Load().ApprovalGroupedView,
                onGroupedViewChanged: grouped => _settingsStore.SaveApprovalGroupedView(grouped),
                getGroups: () => (_featureGroupStore?.Load() ?? FeatureGroupStore.Defaults).ToList().AsReadOnly(),
                onCategorizeUncategorized: items => EnqueueOrganizeUncategorizedPrompt(items),
                categorizeRow: ApprovalCategorizeRow,
                needsApprovalHeader: ApprovalNeedsHeader,
                emptyStateText: ApprovalEmptyStateText,
                onCategoriesMerged: merges => Dispatcher.Invoke(() => ApplyFeatureCategoryMerges(merges)));
            _approvalPanel.ClearFilterAction = () => { if (ApprovalFilterBox is not null) ApprovalFilterBox.Text = string.Empty; };
            _approvalPanel.ReplaceAllItems(_approvalItems);

            // Wire dynamic max-width hint so splitter double-click snaps to content width
            if (ApprovalPanelBorder is { } apb)
                apb.MaximumUsefulSizeProvider = orientation => orientation switch
                {
                    DockResizeOrientation.Horizontal => _approvalPanel.GetMaximumUsefulWidth(),
                    DockResizeOrientation.Vertical   => _approvalPanel.GetMaximumUsefulHeight(),
                    _                                => null
                };
        }
    }

    // ── Transcript follow-up attachment ──────────────────────────────────────

    private void AttachTranscriptFollowUp(RichTextBox rtb)
    {
        var quote = TranscriptCopyService.BuildSelectionText(rtb);
        if (string.IsNullOrWhiteSpace(quote)) return;

        var list = GetOrCreateFollowUpList(_activeTabId ?? "");
        // Deduplicate: don't add if the same transcript quote is already in the list.
        if (list.Count >= 15 || list.Any(a => a.TranscriptQuote == quote)) return;

        // Title: first non-whitespace line of the selection, capped at 80 chars.
        var firstLine = quote.Split('\n')
            .Select(l => l.Trim())
            .FirstOrDefault(l => l.Length > 0) ?? quote.TrimStart();
        var title = firstLine.Length > 80 ? firstLine[..80].TrimEnd() + "…" : firstLine;

        // Scan backwards through the thread's prompt paragraphs to find the prompt
        // that precedes the selection, giving the AI useful context.
        var thread = FindThreadForDocument(rtb.Document);
        var selectionStart = rtb.Selection.Start;
        PromptEntry? precedingEntry = null;
        // Guard: only compare TextPointers when both belong to the same FlowDocument.
        // FindThreadForDocument falls back to CoordinatorThread when the RTB's document
        // isn't registered yet; in that case the PromptParagraphs belong to a different
        // TextTree and CompareTo would throw ArgumentException.
        // Secondary guard: when the selection spans a BlockUIContainer (e.g. quick-reply
        // buttons), WPF can return a Selection.Start TextPointer anchored inside the hosted
        // UIElement's internal layout tree rather than the FlowDocument TextTree.  The outer
        // ReferenceEquals check passes (rtb.Document still matches), but CompareTo throws.
        // A null Parent on an entry means the Paragraph was detached; skip those too.
        if (ReferenceEquals(thread.Document, rtb.Document))
        {
            try
            {
                foreach (var entry in thread.PromptParagraphs)
                {
                    if (entry.Paragraph.Parent is null) continue;
                    if (entry.Paragraph.ContentStart.CompareTo(selectionStart) < 0)
                        precedingEntry = entry;
                    else
                        break;
                }
            }
            catch (ArgumentException)
            {
                // selectionStart was from a different TextTree (selection spanned a
                // BlockUIContainer hosting interactive controls).  Skip preceding-context
                // lookup; the attachment still works, just without the prior-prompt hint.
                precedingEntry = null;
            }
        }
        string? originalPrompt = precedingEntry is not null
            ? new TextRange(precedingEntry.Paragraph.ContentStart, precedingEntry.Paragraph.ContentEnd).Text.Trim()
            : null;

        // TRACE: log raw bytes of quote at build time to diagnose missing-space bug
        var quoteBytes = System.Text.Encoding.UTF8.GetBytes(quote.Length > 200 ? quote[..200] : quote);
        SquadDashTrace.Write(TraceCategory.UI,
            $"[ExcerptTrace] AttachTranscriptFollowUp — quote length={quote.Length}, " +
            $"bytes[0..{Math.Min(quoteBytes.Length, 200)}]: {string.Join(",", quoteBytes.Select(b => b.ToString()))}");

        list.Add(new FollowUpAttachment(
            CommitSha:      string.Empty,
            Description:    title,
            OriginalPrompt: originalPrompt,
            TranscriptQuote: quote));
        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (_activeTabId is null) PersistDraftFollowUp();
    }

    /// <summary>
    /// Creates a queue slot and attaches the selected transcript text without allowing the
    /// queue-strip layout change to disturb the originating transcript's viewport.
    /// </summary>
    private void AddTranscriptSelectionToNewChat(RichTextBox rtb)
    {
        void AddAndAttach()
        {
            AddEmptyQueueSlot();
            AttachTranscriptFollowUp(rtb);
        }

        PreserveVisibleTranscriptViewportsThroughLayout(
            AddAndAttach,
            "add transcript selection to new chat",
            FindScrollControllerForTranscriptBox(rtb));
    }

    /// <summary>
    /// Preserves every visible transcript because prompt-composer height changes resize the
    /// shared transcript row, including secondary panels that did not initiate the operation.
    /// </summary>
    private void PreserveVisibleTranscriptViewportsThroughLayout(
        Action operation,
        string reason,
        TranscriptScrollController? requiredController = null)
    {
        var controllers = new List<TranscriptScrollController>();

        void AddController(TranscriptScrollController? controller)
        {
            if (controller is not null && !controllers.Any(existing => ReferenceEquals(existing, controller)))
                controllers.Add(controller);
        }

        if (_coordinatorScrollController is not null && OutputTextBox?.IsVisible == true)
            AddController(_coordinatorScrollController);

        foreach (var entry in _primaryAgentTranscriptHosts.Values)
        {
            if (entry.TranscriptBox.IsVisible)
                AddController(entry.ScrollController);
        }

        foreach (var entry in _secondaryTranscripts)
        {
            if (entry.TranscriptBox.IsVisible)
                AddController(entry.ScrollController);
        }

        AddController(requiredController);

        Action guardedOperation = operation;
        for (int i = controllers.Count - 1; i >= 0; i--)
        {
            var controller = controllers[i];
            var innerOperation = guardedOperation;
            guardedOperation = () => controller.PreserveViewportThroughLayout(innerOperation, reason);
        }

        guardedOperation();
    }

    private void SetPromptStripVisibilityPreservingViewports(
        FrameworkElement strip,
        Visibility visibility,
        string reason)
    {
        if (strip.Visibility == visibility)
            return;

        PreserveVisibleTranscriptViewportsThroughLayout(
            () => strip.Visibility = visibility,
            reason);
    }

    private TranscriptScrollController? FindScrollControllerForTranscriptBox(RichTextBox rtb)
    {
        if (ReferenceEquals(rtb, OutputTextBox))
            return _coordinatorScrollController;

        foreach (var entry in _primaryAgentTranscriptHosts.Values)
        {
            if (ReferenceEquals(entry.TranscriptBox, rtb))
                return entry.ScrollController;
        }

        foreach (var entry in _secondaryTranscripts)
        {
            if (ReferenceEquals(entry.TranscriptBox, rtb))
                return entry.ScrollController;
        }

        return null;
    }

    private TranscriptThreadState FindThreadForDocument(FlowDocument document)
    {
        if (ReferenceEquals(CoordinatorThread.Document, document))
            return CoordinatorThread;
        return _agentThreadRegistry.ThreadOrder.FirstOrDefault(t => ReferenceEquals(t.Document, document))
            ?? CoordinatorThread;
    }

    // ── Follow-up attachment ──────────────────────────────────────────────────

    private void AttachNoteFollowUp(NoteItem note)
    {
        var path = _notesStore?.GetNotePath(note.Id) ?? "";
        string content = "";
        try { if (!string.IsNullOrEmpty(path)) content = File.ReadAllText(path); }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Attach", $"Read failed for {path}: {ex.Message}");
            UIErrorHelper.ShowWarning("Read Failed", $"Could not read file:\n{ex.Message}");
        }

        var body = new System.Text.StringBuilder();
        if (!string.IsNullOrEmpty(path))
            body.AppendLine($"File: {path}");
        if (!string.IsNullOrWhiteSpace(content))
        {
            if (body.Length > 0) body.AppendLine();
            body.Append(content);
        }

        AttachContextFollowUp($"Note: {note.Title}", BuildTypedAttachmentBlock("note", note.Title, body.ToString().TrimEnd()));
    }

    private void AttachTopicFollowUp(TreeViewItem treeItem, string filePath)
    {
        // Extract display title from TreeViewItem header or fall back to filename.
        string title = filePath;
        if (treeItem.Header is FrameworkElement fe)
        {
            var tb = VisualTreeSearch.FindChild<TextBlock>(fe);
            if (tb is not null && !string.IsNullOrWhiteSpace(tb.Text))
                title = tb.Text.Trim();
        }
        if (string.IsNullOrWhiteSpace(title) || title == filePath)
            title = Path.GetFileNameWithoutExtension(filePath);

        string content = "";
        try { content = File.ReadAllText(filePath); }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Attach", $"Read failed for {filePath}: {ex.Message}");
            UIErrorHelper.ShowWarning("Read Failed", $"Could not read file:\n{ex.Message}");
        }

        var body = new System.Text.StringBuilder();
        body.AppendLine($"File: {filePath}");
        if (!string.IsNullOrWhiteSpace(content))
        {
            body.AppendLine();
            body.Append(content);
        }

        AttachContextFollowUp($"Topic: {title}", BuildTypedAttachmentBlock("doc", title, body.ToString().TrimEnd()));
    }

    private static string BuildTaskContentBlock(TaskItem task)
    {
        var sb = new System.Text.StringBuilder();
        sb.AppendLine("## Task context");
        sb.AppendLine($"Title: {task.Text}");
        var priority = task.Emoji switch {
            "⚫" => "Critical",
            "🔴" => "High",
            "🟡" => "Mid",
            "🟢" => "Low",
            "✅" => "Done",
            _    => task.Emoji
        };
        sb.AppendLine($"Priority: {priority}");
        sb.AppendLine($"Status: {(task.IsChecked ? "Done" : "Open")}");
        if (!string.IsNullOrWhiteSpace(task.Owner))
            sb.AppendLine($"Owner: {task.Owner}");
        if (!string.IsNullOrWhiteSpace(task.Description))
        {
            sb.AppendLine();
            sb.AppendLine("Description:");
            sb.AppendLine(task.Description.Trim());
        }
        return sb.ToString().TrimEnd();
    }

    /// <summary>
    /// Body content for a task typed attachment block (no markdown header — title goes in the XML attribute).
    /// </summary>
    private static string BuildTaskContentBody(TaskItem task)
    {
        var sb = new System.Text.StringBuilder();
        var priority = task.Emoji switch {
            "⚫" => "Critical",
            "🔴" => "High",
            "🟡" => "Mid",
            "🟢" => "Low",
            "✅" => "Done",
            _    => task.Emoji
        };
        sb.AppendLine($"Priority: {priority}");
        sb.AppendLine($"Status: {(task.IsChecked ? "Done" : "Open")}");
        if (!string.IsNullOrWhiteSpace(task.Owner))
            sb.AppendLine($"Owner: {task.Owner}");
        if (!string.IsNullOrWhiteSpace(task.Description))
        {
            sb.AppendLine();
            sb.AppendLine("Description:");
            sb.AppendLine(task.Description.Trim());
        }
        return sb.ToString().TrimEnd();
    }

    private static string BuildPlanContentBody(Plan plan)
    {
        var sb = new System.Text.StringBuilder();
        sb.AppendLine($"Plan ID: {plan.PlanId}");
        sb.AppendLine($"Title: {plan.Title}");
        sb.AppendLine($"Branch: {plan.Branch}");
        sb.AppendLine($"Status: {plan.LifecycleStatus}");
        sb.AppendLine($"Progress: {plan.Progress.CompletedCount}/{plan.Progress.TotalCount} tasks complete");
        if (!string.IsNullOrWhiteSpace(plan.Summary))
        {
            sb.AppendLine();
            sb.AppendLine("Summary:");
            sb.AppendLine(plan.Summary.Trim());
        }
        sb.AppendLine();
        sb.AppendLine($"File: .squad/plans/{plan.PlanId}.json");
        return sb.ToString().TrimEnd();
    }

    private static string BuildApprovalContentBlock(CommitApprovalItem item)
    {
        var sb = new System.Text.StringBuilder();
        sb.AppendLine("## Approval context");
        sb.AppendLine($"Description: {item.Description}");
        if (!string.IsNullOrWhiteSpace(item.CommitSha))
            sb.AppendLine($"Commit: {item.CommitSha}");
        if (!string.IsNullOrWhiteSpace(item.OriginalPrompt))
        {
            sb.AppendLine();
            sb.AppendLine("Original prompt:");
            sb.AppendLine(item.OriginalPrompt!.Trim());
        }
        return sb.ToString().TrimEnd();
    }

    private static string BuildClipboardAttachDescription(string text)
    {
        const int PreviewLength = 60;
        var normalized = System.Text.RegularExpressions.Regex.Replace(text.Trim(), @"\s+", " ");
        var preview = normalized.Length > PreviewLength
            ? normalized[..PreviewLength] + "…"
            : normalized;
        return $"Clipboard: {preview} ({text.Length:N0} chars)";
    }

    /// <summary>
    /// Builds a typed XML-style attachment block for the AI.
    /// Format: <c>&lt;attachment type="…" title="…"&gt;\ncontent\n&lt;/attachment&gt;</c>.
    /// The <paramref name="title"/> attribute is omitted when null.
    /// Any <c>&lt;/attachment&gt;</c> in <paramref name="content"/> is escaped so the
    /// block close tag cannot collide with content.
    /// </summary>
    private static string BuildTypedAttachmentBlock(string type, string? title, string content)
    {
        var result = AttachmentBlockFormatter.BuildTypedAttachmentBlock(type, title, content);
        
        // Log inbox-excerpt creation for diagnostics
        if (type == "inbox-excerpt")
        {
            var logPath = Path.Combine(Path.GetTempPath(), "squaddash-excerpt-debug.log");
            var preview = result.Substring(0, Math.Min(300, result.Length));
            File.AppendAllText(logPath,
                $"[{DateTime.Now:HH:mm:ss.fff}] [BUILD ATTACHMENT] Created inbox-excerpt block:\n{preview}...\n");
        }
        
        return result;
    }

    [Obsolete("Use BuildTypedAttachmentBlock for new attachments. This overload is retained only to generate " +
              "SQUADCLIP fences for addToNotes callers that still expect the old markdown format.")]
    private static string BuildClipboardContentBlock(string text)
    {
        var nonce = Guid.NewGuid().ToString("N")[..8];
        return $"<<<SQUADCLIP:{nonce}>>>\n{text}\n<<<ENDCLIP:{nonce}>>>";
    }

    /// <summary>
    /// Given a <paramref name="prompt"/> that starts with a nonce-fenced clipboard block
    /// (<c>&lt;&lt;&lt;SQUADCLIP:nonce&gt;&gt;&gt;</c>), returns the index of the first character
    /// AFTER the close fence and its trailing <c>\n\n</c> separator (i.e. the start of the user's
    /// actual prompt body).  Returns -1 if the fence is malformed or the separator is missing.
    /// </summary>
    private static int StripClipboardFenceHeader(string prompt)
    {
        // Open fence line: <<<SQUADCLIP:{nonce}>>>
        var openEnd = prompt.IndexOf(">>>", StringComparison.Ordinal);
        if (openEnd < 0) return -1;
        var nonce = prompt["<<<SQUADCLIP:".Length..openEnd];
        var closeFence = $"\n<<<ENDCLIP:{nonce}>>>";
        var closeIdx = prompt.IndexOf(closeFence, openEnd, StringComparison.Ordinal);
        if (closeIdx < 0) return -1;
        var afterClose = closeIdx + closeFence.Length;
        // Expect \n\n separator immediately after the close fence line.
        if (afterClose + 2 <= prompt.Length && prompt[afterClose] == '\n' && prompt[afterClose + 1] == '\n')
            return afterClose + 2;
        return -1;
    }

    /// <summary>
    /// Given a prompt that uses the typed attachment format (preamble line + XML-style
    /// <c>&lt;attachment&gt;</c> blocks), returns the index of the first character of the user's
    /// actual message.  Returns -1 if the header section cannot be parsed.
    /// </summary>
    private static int StripTypedAttachmentHeaders(string prompt) =>
        AttachmentBlockFormatter.StripTypedAttachmentHeaders(prompt);

    private static FollowUpAttachment BuildHistoricalTypedAttachment(string block)
    {
        var (type, title) = AttachmentBlockFormatter.ExtractAttachmentMetadata(block);
        var description = !string.IsNullOrWhiteSpace(title)
            ? title!
            : type switch
            {
                "clipboard"      => "Clipboard",
                "doc"            => "Documentation",
                "inbox-excerpt"  => "Inbox excerpt",
                "inbox-message"  => "Inbox message",
                "note"           => "Note",
                "task"           => "Task",
                "transcript"     => "Transcript",
                _                => "Attachment",
            };

        return new FollowUpAttachment(
            CommitSha: string.Empty,
            Description: description,
            OriginalPrompt: null,
            ContentBlock: block);
    }

    private void AttachContextFollowUp(string description, string contentBlock)    {
        var list = GetOrCreateFollowUpList(_activeTabId ?? "");
        // Deduplicate by description.
        if (list.Count >= 15 || list.Any(a => a.Description == description)) return;
        list.Add(new FollowUpAttachment(
            CommitSha:    string.Empty,
            Description:  description,
            OriginalPrompt: null,
            ContentBlock: contentBlock));
        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (_activeTabId is null) PersistDraftFollowUp();
    }

    private void AttachPlanFollowUp(Plan plan)
    {
        var list = GetOrCreateFollowUpList(_activeTabId ?? "");
        var description = $"Plan: {plan.Title}";
        if (list.Count >= 15 || list.Any(a => a.Description == description)) return;
        list.Add(new FollowUpAttachment(
            CommitSha: string.Empty,
            Description: description,
            OriginalPrompt: null,
            ContentBlock: BuildTypedAttachmentBlock("plan", plan.Title, BuildPlanContentBody(plan)),
            FileReferencePath: $".squad/plans/{plan.PlanId}.json"));
        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (_activeTabId is null) PersistDraftFollowUp();
    }

    private void BeginPlanRevision(Plan plan)
    {
        AddEmptyQueueSlot();
        if (_activeTabId is null) return;

        const string draft = "I'd like to make the following changes to this plan:\r\n\r\n";
        var item = _promptQueue.Items.FirstOrDefault(candidate => candidate.Id == _activeTabId);
        if (item is null) return;
        item.Text = draft;
        item.CaretIndex = draft.Length;
        item.SelectionStart = draft.Length;
        item.SelectionLength = 0;

        var attachments = GetOrCreateFollowUpList(item.Id);
        attachments.RemoveAll(attachment =>
            attachment.ContentBlock is not null &&
            PlanRevisionPromptContextParser.TryParse(attachment.ContentBlock, out _));
        attachments.Add(new FollowUpAttachment(
            CommitSha: string.Empty,
            Description: $"Revise plan: {plan.Title}",
            OriginalPrompt: null,
            ContentBlock: PlanRevisionPromptContextParser.BuildAttachment(plan),
            FileReferencePath: $".squad/plans/{plan.PlanId}.json"));

        if (_transcriptFullScreenEnabled && !_fullScreenPromptVisible)
            ShowFullScreenPrompt();
        else if (PromptBorder is not null)
            PromptBorder.Visibility = Visibility.Visible;

        SetPromptTextBoxLogicalBuffer(draft, draft.Length, draft.Length, 0, "revise-plan");
        UpdateFollowUpStrip();
        SyncQueuePanel();
        PromptTextBox.Focus();
        PromptTextBox.CaretIndex = draft.Length;
        ShowPlanRevisionPromptGlow();
    }

    private void ShowPlanRevisionPromptGlow()
    {
        if (PromptBorder is null) return;
        _planRevisionPromptGlowTimer?.Stop();
        PromptBorder.Effect = new System.Windows.Media.Effects.DropShadowEffect
        {
            Color = Colors.DodgerBlue,
            BlurRadius = 28,
            ShadowDepth = 0,
            Opacity = 0.8,
        };
        var timer = new DispatcherTimer { Interval = TimeSpan.FromSeconds(2.4) };
        timer.Tick += (_, _) =>
        {
            timer.Stop();
            if (ReferenceEquals(_planRevisionPromptGlowTimer, timer))
            {
                _planRevisionPromptGlowTimer = null;
                PromptBorder.Effect = null;
            }
        };
        _planRevisionPromptGlowTimer = timer;
        timer.Start();
    }

    private void AttachInboxMessageFollowUp(InboxMessage msg)
        => AttachInboxMessageFollowUp(msg, _activeTabId ?? "");

    private void ReplyInChatFromInboxMessage(InboxMessage msg)
    {
        var draftKey = _activeTabId ?? "";
        var hasDraftText = !string.IsNullOrWhiteSpace(PromptTextBox.Text);
        var hasDraftAttachments = _followUpAttachments.TryGetValue(draftKey, out var draftList) && draftList.Count > 0;

        if (hasDraftText || hasDraftAttachments)
            AddEmptyQueueSlot();

        AttachInboxMessageFollowUp(msg, _activeTabId ?? "");
    }

    private void AttachInboxMessageFollowUp(InboxMessage msg, string tabId)
    {
        var list = GetOrCreateFollowUpList(tabId);
        if (list.Count >= 15 || list.Any(a => a.InboxMessageId == msg.Id)) return;
        var sb = new System.Text.StringBuilder();
        sb.AppendLine($"From: {msg.From}");
        sb.AppendLine($"Date: {msg.Timestamp:g}");
        sb.AppendLine();
        sb.Append(msg.Body.Trim());
        var contentBlock = BuildTypedAttachmentBlock("inbox-message", msg.Subject, sb.ToString().TrimEnd());
        list.Add(new FollowUpAttachment(
            CommitSha:      string.Empty,
            Description:    msg.Subject,
            OriginalPrompt: null,
            ContentBlock:   contentBlock,
            InboxMessageId: msg.Id));
        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (tabId == "") PersistDraftFollowUp();
    }

    private void AttachInboxMessageSelectedTextFollowUp(string selectedText, InboxMessage msg)
    {
        var list = GetOrCreateFollowUpList(_activeTabId ?? "");
        if (list.Count >= 15) return;

        // Build attachment content with message context
        var sb = new System.Text.StringBuilder();
        sb.AppendLine($"From: {msg.From}");
        sb.AppendLine($"Subject: {msg.Subject}");
        sb.AppendLine($"Date: {msg.Timestamp:g}");
        sb.AppendLine();
        sb.AppendLine("Selected excerpt:");
        sb.AppendLine("---");
        sb.Append(selectedText.Trim());

        var contentBlock = BuildTypedAttachmentBlock(
            "inbox-excerpt", 
            $"Excerpt from: {msg.Subject}", 
            sb.ToString().TrimEnd());

        list.Add(new FollowUpAttachment(
            CommitSha:      string.Empty,
            Description:    $"Excerpt: {msg.Subject}",
            OriginalPrompt: null,
            ContentBlock:   contentBlock,
            InboxMessageId: msg.Id));

        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (_activeTabId is null) PersistDraftFollowUp();
    }

    private async void OpenOrFocusInboxMessage(string messageId, Action? onMarkedRead = null)
    {
        SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessage: messageId={messageId} openWindowCount={_openInboxWindows.Count}");
        if (!TryPrepareRecoveryInboxMessageForUse(messageId, out var preparedMessage))
        {
            _inboxPanel?.ShowTransientNotice("This recovery request is no longer active.");
            return;
        }

        try
        {
            preparedMessage = await RefreshApprovalInboxMessageForUseAsync(messageId) ?? preparedMessage;
        }
        catch (Exception ex)
        {
            // Opening the existing durable message is still useful when evidence refresh fails.
            // A captured action remains protected by normal stale-token validation.
            SquadDashTrace.Write(
                "Approval",
                $"Could not refresh approval message before opening message={messageId}: {ex.Message}");
        }

        var existing = _openInboxWindows.FirstOrDefault(w => w.MessageId == messageId);
        if (existing is not null)
        {
            SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessage: found existing window — activating (minimized={existing.WindowState == WindowState.Minimized})");
            if (existing.WindowState == WindowState.Minimized)
                existing.WindowState = WindowState.Normal;
            existing.Activate();
            NativeMethods.TryActivateWindow(new System.Windows.Interop.WindowInteropHelper(existing).Handle);
            existing.PulseAttention();
            return;
        }
        var msg = preparedMessage ?? _inboxStore?.LoadAll().FirstOrDefault(m => m.Id == messageId);
        if (msg is null)
        {
            SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessage: message not found — refreshing list for msgId={messageId}");
            _inboxPanel?.ShowTransientNotice("This message no longer exists.");
            var refreshed = _inboxStore?.LoadAll() ?? [];
            _inboxPanel?.Refresh(refreshed);
            ReconcileOpenInboxWindows(refreshed);
            return;
        }
        SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessage: creating new InboxMessageWindow for msgId={messageId}");
        var win = new InboxMessageWindow(
            msg, 
            DispatchInboxAction, 
            LookupTaskById,
            attachSelectedTextToChat: AttachInboxMessageSelectedTextFollowUp,
            attachSelectedTextToNewChat: (text, msg2) => { AddEmptyQueueSlot(); AttachInboxMessageSelectedTextFollowUp(text, msg2); },
            onMarkedRead: onMarkedRead,
            onMarkedUnread: () => { _inboxStore?.MarkUnread(messageId); _inboxPanel?.Refresh(_inboxStore?.LoadAll() ?? []); },
            onRepliedInChat: () => ReplyInChatFromInboxMessage(msg),
            initialFontSize:   _inboxFontSize,
            onFontSizeChanged: size => { _inboxFontSize = size; _settingsManager.Replace(_settingsStore.SaveInboxFontSize(size)); },
            openDecomposePlan: OpenDecomposePlanAttachment,
            openCommit: sha => _ = OpenCommitWithRemoteCheckAsync(sha),
            openPlanByGroupId: OpenInboxPlanViewerByGroupId,
            resolvePlanGroupForThumbnail: ResolveInboxPlanGroupForThumbnail,
            resolveLayoutNudgesForThumbnail: ResolveLayoutNudgesForThumbnail,
            isPlanExecuted: IsPlanExecuted,
            resolveAgentAvatar: ResolveAgentAvatarForPlanViewer,
            workspaceFolder: _currentWorkspace?.FolderPath,
            loadPlan: planId => _planStore?.Load(planId),
            onHumanReviewSelectionChanged: RecordHumanReviewChecklistSelection,
            resolveMessageFilePath: id => _inboxStore?.GetMessageFilePath(id),
            openInboxMessage: id => OpenOrFocusInboxMessage(id));
        win.Owner = CanShowOwnedWindow() ? this : null;
        _openInboxWindows.Add(win);
        win.Closed    += (_, _) => _openInboxWindows.Remove(win);
        win.Closed    += (_, _) => FloatingWindowPositionStore.Shared.Save($"InboxMessage:{win.MessageId}", win);
        win.Activated += (_, _) => _inboxPanel?.SelectMessageById(messageId);
        FloatingWindowPositionStore.Shared.TryRestore($"InboxMessage:{messageId}", win);
        win.Show();
    }

    /// <summary>
    /// Rebinds an approval Inbox message and the live action coordinator to the authoritative
    /// durable plan when either surface still carries an older revision. Returns the current
    /// message when <paramref name="messageId"/> belongs to a known approval plan; otherwise null.
    /// </summary>
    private async Task<InboxMessage?> RefreshApprovalInboxMessageForUseAsync(string messageId)
    {
        if (_planStore is null || _planApprovalRuntime is null || _inboxStore is null)
            return null;

        var plan = _planStore.LoadAll().FirstOrDefault(candidate => string.Equals(
            DurableApprovalRequestManager.BuildMessageId(candidate.PlanId),
            messageId,
            StringComparison.Ordinal));
        if (plan is null)
            return null;

        var message = _inboxStore.GetById(messageId);
        var renderedToken = message?.Actions
            .Where(action =>
                string.Equals(
                    action.RouteMode,
                    DurableApprovalRequestManager.ApprovalReviewRouteMode,
                    StringComparison.OrdinalIgnoreCase) ||
                string.Equals(
                    action.RouteMode,
                    DurableApprovalRequestManager.ApprovalRouteMode,
                    StringComparison.OrdinalIgnoreCase))
            .Select(action => ApprovalInboxActionPayload.TryParse(action.Prompt, out var payload)
                ? payload?.ToClickToken()
                : null)
            .FirstOrDefault(token => token is not null);
        var currentToken = _planApprovalRuntime.Actions.GetCurrentToken(plan.PlanId);
        if (renderedToken is not null &&
            currentToken is not null &&
            renderedToken.Matches(currentToken) &&
            string.Equals(renderedToken.PlanRevision, plan.Revision, StringComparison.Ordinal))
            return message;

        await _planApprovalRuntime.RestoreAsync([plan]);
        var messages = _inboxStore.LoadAll();
        _inboxPanel?.Refresh(messages);
        message = _inboxStore.GetById(messageId);
        if (message is not null)
            RefreshOpenApprovalInboxWindows(messageId, message);
        return message;
    }

    private void OpenOrFocusInboxMessageAndSelectText(string messageId, string excerptText)
    {
        SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessageAndSelectText: messageId={messageId} excerptLen={excerptText.Length} excerpt='{excerptText[..Math.Min(80, excerptText.Length)]}'");
        var existing = _openInboxWindows.FirstOrDefault(w => w.MessageId == messageId);
        if (existing is not null)
        {
            SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessageAndSelectText: found existing window — activating + calling SelectAndScrollToText immediately");
            if (existing.WindowState == WindowState.Minimized)
                existing.WindowState = WindowState.Normal;
            existing.Activate();
            existing.SelectAndScrollToText(excerptText);
            return;
        }

        var msg = _inboxStore?.LoadAll().FirstOrDefault(m => m.Id == messageId);
        if (msg is null)
        {
            SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessageAndSelectText: message not found — refreshing list for msgId={messageId}");
            _inboxPanel?.ShowTransientNotice("This message no longer exists.");
            var refreshed = _inboxStore?.LoadAll() ?? [];
            _inboxPanel?.Refresh(refreshed);
            ReconcileOpenInboxWindows(refreshed);
            return;
        }
        SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessageAndSelectText: creating new InboxMessageWindow for msgId={messageId}");
        var win = new InboxMessageWindow(
            msg, 
            DispatchInboxAction, 
            LookupTaskById,
            attachSelectedTextToChat: AttachInboxMessageSelectedTextFollowUp,
            attachSelectedTextToNewChat: (text, msg2) => { AddEmptyQueueSlot(); AttachInboxMessageSelectedTextFollowUp(text, msg2); },
            onMarkedUnread: () => { _inboxStore?.MarkUnread(messageId); _inboxPanel?.Refresh(_inboxStore?.LoadAll() ?? []); },
            onRepliedInChat: () => ReplyInChatFromInboxMessage(msg),
            initialFontSize:   _inboxFontSize,
            onFontSizeChanged: size => { _inboxFontSize = size; _settingsManager.Replace(_settingsStore.SaveInboxFontSize(size)); },
            openDecomposePlan: OpenDecomposePlanAttachment,
            openCommit: sha => _ = OpenCommitWithRemoteCheckAsync(sha),
            openPlanByGroupId: OpenInboxPlanViewerByGroupId,
            resolvePlanGroupForThumbnail: ResolveInboxPlanGroupForThumbnail,
            resolveLayoutNudgesForThumbnail: ResolveLayoutNudgesForThumbnail,
            isPlanExecuted: IsPlanExecuted,
            resolveAgentAvatar: ResolveAgentAvatarForPlanViewer,
            workspaceFolder: _currentWorkspace?.FolderPath,
            loadPlan: planId => _planStore?.Load(planId),
            onHumanReviewSelectionChanged: RecordHumanReviewChecklistSelection,
            resolveMessageFilePath: id => _inboxStore?.GetMessageFilePath(id),
            openInboxMessage: id => OpenOrFocusInboxMessage(id));
        win.Owner = CanShowOwnedWindow() ? this : null;
        _openInboxWindows.Add(win);
        win.Closed += (_, _) => _openInboxWindows.Remove(win);
        win.Closed += (_, _) => FloatingWindowPositionStore.Shared.Save($"InboxMessage:{win.MessageId}", win);
        FloatingWindowPositionStore.Shared.TryRestore($"InboxMessage:{messageId}", win);
        SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessageAndSelectText: hooking win.Loaded to defer SelectAndScrollToText via Dispatcher.BeginInvoke(Loaded priority) — excerptLen={excerptText.Length}");
        win.Loaded += (_, _) =>
        {
            SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessageAndSelectText: win.Loaded fired for msgId={messageId} — queuing Dispatcher.BeginInvoke at DispatcherPriority.Loaded");
            Dispatcher.BeginInvoke(() =>
            {
                SquadDashTrace.Write(TraceCategory.Inbox, $"OpenOrFocusInboxMessageAndSelectText: Dispatcher.BeginInvoke executing — calling SelectAndScrollToText for msgId={messageId}");
                win.SelectAndScrollToText(excerptText);
            }, System.Windows.Threading.DispatcherPriority.Loaded);
        };
        
        win.Show();
    }

    private void ReconcileOpenInboxWindows(IReadOnlyList<InboxMessage> messages)
    {
        var existingIds = new System.Collections.Generic.HashSet<string>(
            messages.Select(m => m.Id), StringComparer.Ordinal);
        foreach (var win in _openInboxWindows.ToList())
        {
            if (!existingIds.Contains(win.MessageId))
            {
                SquadDashTrace.Write(TraceCategory.Inbox,
                    $"ReconcileOpenInboxWindows: closing orphaned window for removed msgId={win.MessageId}");
                win.Close();
            }
        }
    }

    private void OnInboxWatcherChanged()
    {
        RefreshSidebar();
        if (_inboxPanel is not null && _inboxStore is not null)
        {
            var messages = _inboxStore.LoadAll();
            _inboxPanel.Refresh(messages);
            ReconcileOpenInboxWindows(messages);
        }
    }

    private static IReadOnlyList<string> ParseGitPorcelainPaths(string porcelain) =>
        porcelain.Split('\n', StringSplitOptions.RemoveEmptyEntries)
                 .Select(l => l.Length > 3 ? l[3..].Trim() : l.Trim())
                 .Where(s => s.Length > 0)
                 .ToList();

    private static string ExtractExcerptTextFromAttachment(string contentBlock)
    {
        // Extract the content from the attachment block
        var content = AttachmentBlockFormatter.ExtractAttachmentContent(contentBlock);
        
        // Find the "Selected excerpt:" section followed by "---"
        var excerptMarker = "Selected excerpt:";
        var excerptStart = content.IndexOf(excerptMarker, StringComparison.Ordinal);
        if (excerptStart < 0) return string.Empty;

        excerptStart += excerptMarker.Length;
        
        // Skip past the separator line "---"
        var separatorStart = content.IndexOf("---", excerptStart, StringComparison.Ordinal);
        if (separatorStart < 0) return string.Empty;
        
        separatorStart += 3; // Move past "---"
        
        // Extract the text after the separator (this is the actual excerpt)
        var excerptText = content[separatorStart..].Trim();
        return excerptText;
    }

    private void AttachFollowUpToActiveTab(CommitApprovalItem item)
    {
        var list = GetOrCreateFollowUpList(_activeTabId ?? "");
        // Deduplicate: don't add the same commit SHA twice.
        if (list.Count >= 15 || list.Any(a => string.Equals(a.CommitSha, item.CommitSha, StringComparison.OrdinalIgnoreCase))) return;

        list.Add(new FollowUpAttachment(item.CommitSha, item.Description, item.OriginalPrompt));
        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (_activeTabId is null) PersistDraftFollowUp();
    }

    private List<FollowUpAttachment> GetOrCreateFollowUpList(string key)
    {
        if (!_followUpAttachments.TryGetValue(key, out var list))
            _followUpAttachments[key] = list = [];
        return list;
    }

    private void UpdateFollowUpStrip()
    {
        if (FollowUpStrip is null || FollowUpItemsPanel is null) return;

        int desiredRowCount = _followUpAttachments.TryGetValue(_activeTabId ?? "", out var list)
            ? list.Count
            : 0;
        var desiredVisibility = desiredRowCount > 0 ? Visibility.Visible : Visibility.Collapsed;
        bool layoutWillChange = FollowUpStrip.Visibility != desiredVisibility
                                || (desiredRowCount > 0 && FollowUpItemsPanel.Children.Count != desiredRowCount);

        if (layoutWillChange)
        {
            PreserveVisibleTranscriptViewportsThroughLayout(
                UpdateFollowUpStripCore,
                "follow-up attachment strip changed");
            return;
        }

        UpdateFollowUpStripCore();
    }

    private void UpdateFollowUpStripCore()
    {
        if (FollowUpStrip is null || FollowUpItemsPanel is null) return;
        if (_followUpAttachments.TryGetValue(_activeTabId ?? "", out var list) && list.Count > 0)
        {
            FollowUpItemsPanel.Children.Clear();
            for (int i = 0; i < list.Count; i++)
            {
                var att = list[i];
                var row = new DockPanel();
                if (i > 0)
                    row.Margin = new System.Windows.Thickness(0, 3, 0, 0);

                var dismissBtn = new Button
                {
                    Content           = "×",
                    Width             = 20,
                    Height            = 20,
                    Padding           = new System.Windows.Thickness(0),
                    VerticalAlignment = VerticalAlignment.Center,
                    Style             = (Style)FindResource("ThemedIconButtonStyle"),
                };
                DockPanel.SetDock(dismissBtn, Dock.Right);
                var capturedAtt = att;
                dismissBtn.Click += (_, e) =>
                {
                    e.Handled = true;
                    var l = GetOrCreateFollowUpList(_activeTabId ?? "");
                    if (capturedAtt.RequiresRemovalConfirmation &&
                        MessageBox.Show(
                            this,
                            capturedAtt.RemovalWarning ??
                            "This attachment is required to continue the plan with the correct context. Remove it anyway?",
                            "Remove Required Context?",
                            MessageBoxButton.YesNo,
                            MessageBoxImage.Warning,
                            MessageBoxResult.No) != MessageBoxResult.Yes)
                        return;
                    l.Remove(capturedAtt);
                    if (l.Count == 0) _guidedTourCoordinator.RaiseAllAttachmentsRemoved();
                    UpdateFollowUpStrip();
                    SyncQueuePanel();
                    if (_activeTabId is null) PersistDraftFollowUp();
                };
                row.Children.Add(dismissBtn);

                var label = new TextBlock
                {
                    VerticalAlignment = VerticalAlignment.Center,
                    TextTrimming      = TextTrimming.CharacterEllipsis,
                };
                label.SetResourceReference(TextBlock.FontSizeProperty, "FontSizeSmall");
                label.SetResourceReference(TextBlock.ForegroundProperty, "SubtleText");

                if (att.InboxMessageId != null
                    && (att.ContentBlock == null
                        || att.ContentBlock.Contains("type=\"inbox-message\"", StringComparison.Ordinal)))
                {
                    var icon    = new Run("📧 ");
                    var descRun = new Run(att.Description);
                    descRun.SetResourceReference(Run.ForegroundProperty, "LabelText");
                    label.Inlines.Add(icon);
                    label.Inlines.Add(descRun);
                    label.Cursor = System.Windows.Input.Cursors.Hand;
                    var capturedMsgId = att.InboxMessageId;
                    label.MouseLeftButtonUp += (_, _) => OpenOrFocusInboxMessage(capturedMsgId);
                }
                else if (att.ImagePath != null)
                {
                    int imgIndex = list.Take(i + 1).Count(a => a.ImagePath != null);
                    var icon    = new Run("📷 ");
                    var descRun = new Run($"(image {imgIndex})");
                    descRun.SetResourceReference(Run.ForegroundProperty, "LabelText");
                    label.Inlines.Add(icon);
                    label.Inlines.Add(descRun);
                    label.Cursor = System.Windows.Input.Cursors.Hand;
                    var capturedImg    = capturedAtt;
                    var capturedItemId = _activeTabId ?? "";
                    label.MouseLeftButtonUp += (_, _) =>
                    {
                        var annotJsonPath = capturedImg.ImagePath + ".annotation.json";
                        var sourcePngPath = capturedImg.ImagePath + ".source.png";
                        var annotExists  = File.Exists(annotJsonPath);
                        var sourceExists = File.Exists(sourcePngPath);
                        SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Chip clicked: imagePath={capturedImg.ImagePath} annotJson={annotExists} sourcePng={sourceExists}");
                        if (annotExists && sourceExists)
                        {
                            SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Opening editor (sidecar present)");
                            ReopenImageForEditing(capturedImg, capturedItemId);
                        }
                        else
                        {
                            SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Opening plain viewer (no sidecar) annotJson={annotJsonPath} sourcePng={sourcePngPath}");
                            PromptAttachmentViewerWindow.Show(new[] { capturedImg }, CanShowOwnedWindow() ? this : null);
                        }
                    };
                    if (File.Exists(att.ImagePath))
                    {
                        var bmp = new BitmapImage();
                        bmp.BeginInit();
                        bmp.UriSource        = new Uri(att.ImagePath, UriKind.Absolute);
                        bmp.DecodePixelWidth = 600;
                        bmp.CacheOption      = BitmapCacheOption.OnLoad;
                        bmp.EndInit();
                        bmp.Freeze();

                        var thumb = new System.Windows.Controls.Image
                        {
                            Source    = bmp,
                            MaxWidth  = 300,
                            MaxHeight = 100,
                            Stretch   = Stretch.Uniform,
                        };
                        RenderOptions.SetBitmapScalingMode(thumb, BitmapScalingMode.HighQuality);

                        var tt = new ToolTip
                        {
                            Content         = thumb,
                            Placement       = System.Windows.Controls.Primitives.PlacementMode.Top,
                            HasDropShadow   = true,
                            Background      = Brushes.Transparent,
                            BorderThickness = new Thickness(0),
                            Padding         = new Thickness(0),
                            IsOpen          = false,
                        };
                        label.ToolTip = tt;
                    }
                }
                else if (att.FileReferencePath != null)
                {
                    var isPlanAttachment = att.FileReferencePath.Contains(".squad/plans/", StringComparison.OrdinalIgnoreCase)
                        && att.FileReferencePath.EndsWith(".json", StringComparison.OrdinalIgnoreCase);
                    var resolvedPlan = isPlanAttachment && _planStore is not null
                        ? _planStore.Load(System.IO.Path.GetFileNameWithoutExtension(att.FileReferencePath))
                        : null;

                    if (resolvedPlan is not null)
                    {
                        var icon = new Run("📋 ");
                        var descRun = new Run(resolvedPlan.Title ?? System.IO.Path.GetFileNameWithoutExtension(att.FileReferencePath));
                        descRun.SetResourceReference(Run.ForegroundProperty, "LabelText");
                        label.Inlines.Add(icon);
                        label.Inlines.Add(descRun);
                        label.ToolTip = MakeThemedToolTip($"Plan: {resolvedPlan.Title ?? System.IO.Path.GetFileNameWithoutExtension(att.FileReferencePath)}");
                        label.Cursor = System.Windows.Input.Cursors.Hand;
                        var capturedPlan = resolvedPlan;
                        label.MouseLeftButtonUp += (_, _) => OpenPlanFromStore(capturedPlan);
                    }
                    else
                    {
                        var icon    = new Run("📁 ");
                        var leafName = System.IO.Path.GetFileName(att.FileReferencePath);
                        var display  = leafName.Length > 40 ? leafName[..40] + "…" : leafName;
                        var descRun  = new Run(display);
                        descRun.SetResourceReference(Run.ForegroundProperty, "LabelText");
                        label.Inlines.Add(icon);
                        label.Inlines.Add(descRun);
                        label.ToolTip = MakeThemedToolTip(att.FileReferencePath);
                        label.Cursor  = System.Windows.Input.Cursors.Hand;
                        var capturedPath = att.FileReferencePath;
                        label.MouseLeftButtonUp += (_, _) =>
                            System.Diagnostics.Process.Start("explorer.exe", $"/select,\"{capturedPath}\"");
                    }
                }
                else if (att.ContentBlock != null)
                {
                    // Check if this is an inbox-excerpt attachment
                    var isInboxExcerpt = att.ContentBlock.Contains("type=\"inbox-excerpt\"", StringComparison.Ordinal)
                        && att.InboxMessageId != null;

                    SquadDashTrace.Write(TraceCategory.Inbox,
                        $"FollowUpStrip.BuildItem: contentBlock att — isInboxExcerpt={isInboxExcerpt} inboxMessageId={att.InboxMessageId ?? "NULL"} contentBlockLen={att.ContentBlock.Length}");
                    if (isInboxExcerpt)
                        SquadDashTrace.Write(TraceCategory.Inbox,
                            $"FollowUpStrip.BuildItem: inbox-excerpt block preview='{att.ContentBlock[..Math.Min(200, att.ContentBlock.Length)]}'");

                    if (att.Description.StartsWith("Note: ", StringComparison.Ordinal))
                    {
                        var icon = new Run("📝 ");
                        var descRun = new Run(att.Description["Note: ".Length..]);
                        descRun.SetResourceReference(Run.ForegroundProperty, "LabelText");
                        label.Inlines.Add(icon);
                        label.Inlines.Add(descRun);
                    }
                    else
                    {
                        var icon = new Run("📎 ");
                        var displayText = att.Description.StartsWith("Task: ", StringComparison.Ordinal)
                            ? att.Description["Task: ".Length..]
                            : att.Description.StartsWith("Topic: ", StringComparison.Ordinal)
                                ? att.Description["Topic: ".Length..]
                                : att.Description;
                        var descRun = new Run(displayText);
                        descRun.SetResourceReference(Run.ForegroundProperty, "LabelText");
                        label.Inlines.Add(icon);
                        label.Inlines.Add(descRun);
                    }
                    label.Cursor = System.Windows.Input.Cursors.Hand;
                    var capturedContent = capturedAtt;

                    if (isInboxExcerpt)
                    {
                        // For inbox-excerpt: open the message window and select the excerpt
                        SquadDashTrace.Write(TraceCategory.Inbox,
                            $"FollowUpStrip.BuildItem: registering inbox-excerpt click handler for msgId={att.InboxMessageId}");
                        label.MouseLeftButtonUp += (_, _) =>
                        {
                            SquadDashTrace.Write(TraceCategory.Inbox,
                                $"FollowUpStrip.ExcerptChip.Click: clicked — inboxMessageId={capturedContent.InboxMessageId}");
                            var excerptText = ExtractExcerptTextFromAttachment(capturedContent.ContentBlock!);
                            SquadDashTrace.Write(TraceCategory.Inbox,
                                $"FollowUpStrip.ExcerptChip.Click: extracted excerptText len={excerptText.Length} text='{excerptText[..Math.Min(80, excerptText.Length)]}'");
                            OpenOrFocusInboxMessageAndSelectText(capturedContent.InboxMessageId!, excerptText);
                        };
                    }
                    else
                    {
                        // For other content blocks: show the viewer window
                        label.MouseLeftButtonUp += (_, _) =>
                            PromptAttachmentViewerWindow.Show(new[] { capturedContent }, CanShowOwnedWindow() ? this : null, msgId => OpenOrFocusInboxMessage(msgId));
                    }
                }
                else if (att.TranscriptQuote != null)
                {
                    var prefix = new Run("↩ ");
                    prefix.SetResourceReference(Run.ForegroundProperty, "SubtleText");
                    var quoteRun = new Run($"\"{att.Description}\"");
                    quoteRun.SetResourceReference(Run.ForegroundProperty, "LabelText");
                    label.Inlines.Add(prefix);
                    label.Inlines.Add(quoteRun);
                    label.Cursor = System.Windows.Input.Cursors.Hand;
                    var capturedQuote = capturedAtt;
                    label.MouseLeftButtonUp += (_, _) =>
                        PromptAttachmentViewerWindow.Show(new[] { capturedQuote }, CanShowOwnedWindow() ? this : null);
                }
                else
                {
                    AppendCommitFollowUpInlines(label, att);
                }

                row.Children.Add(label);
                FollowUpItemsPanel.Children.Add(row);
                _guidedTourCoordinator.NamedElements[$"FollowUpAttachmentRow{i}"]     = row;
                _guidedTourCoordinator.NamedElements[$"FollowUpAttachmentDismiss{i}"] = dismissBtn;
            }
            FollowUpStrip.Visibility = Visibility.Visible;
            _guidedTourCoordinator.NamedElements["FollowUpStrip"] = FollowUpStrip;
        }
        else
        {
            FollowUpItemsPanel.Children.Clear();
            FollowUpStrip.Visibility = Visibility.Collapsed;
            var staleKeys = _guidedTourCoordinator.NamedElements.Keys
                .Where(k => k.StartsWith("FollowUpAttachmentRow", StringComparison.Ordinal)
                         || k.StartsWith("FollowUpAttachmentDismiss", StringComparison.Ordinal))
                .ToList();
            foreach (var k in staleKeys) _guidedTourCoordinator.NamedElements.Remove(k);
        }
    }

    /// <summary>
    /// Re-opens a queued image attachment in the annotation editor, loading the
    /// saved source image and annotation state from their companion sidecar files.
    /// On confirmation, overwrites the existing PNG and updates the sidecar.
    /// </summary>
    private void ReopenImageForEditing(FollowUpAttachment att, string promptItemId)
    {
        if (att.ImagePath == null || _currentWorkspace == null)
        {
            SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] ReopenImageForEditing: early exit — ImagePath={att.ImagePath} workspace={_currentWorkspace != null}");
            return;
        }

        var annotJsonPath = att.ImagePath + ".annotation.json";
        var sourcePngPath = att.ImagePath + ".source.png";
        SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] ReopenImageForEditing: annotJson={File.Exists(annotJsonPath)} sourcePng={File.Exists(sourcePngPath)} path={att.ImagePath}");
        if (!File.Exists(annotJsonPath) || !File.Exists(sourcePngPath)) return;

        ClipboardAnnotationState? state    = null;
        BitmapSource?             srcImage = null;
        try
        {
            var jsonOpts = new System.Text.Json.JsonSerializerOptions { NumberHandling = System.Text.Json.Serialization.JsonNumberHandling.AllowNamedFloatingPointLiterals };
            state = System.Text.Json.JsonSerializer.Deserialize<ClipboardAnnotationState>(
                File.ReadAllText(annotJsonPath), jsonOpts);
            var bi = new System.Windows.Media.Imaging.BitmapImage(new Uri(sourcePngPath));
            bi.Freeze();
            srcImage = bi;
            SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Sidecar loaded: state={state != null} srcImage={srcImage != null}");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] ERROR loading sidecar: {ex.Message}");
        }

        if (state == null || srcImage == null)
        {
            SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Falling back to plain viewer (state={state != null} srcImage={srcImage != null})");
            PromptAttachmentViewerWindow.Show(new[] { att }, CanShowOwnedWindow() ? this : null);
            return;
        }

        SquadDashTrace.Write(TraceCategory.UI, $"[ImageReEdit] Opening editor with restored state");
        var capturedAtt = att;
        var editor = new ClipboardImageEditorWindow(this, srcImage, isPromptMode: true, initialState: state, isUpdateMode: true);
        editor.PromptItemId = promptItemId;
        editor.ImageAccepted += edited =>
        {
            _pastedImageStore.OverwriteImage(edited, capturedAtt.ImagePath!);
            if (editor.SourceImage != null)
                _pastedImageStore.SaveAnnotationSidecar(editor.SourceImage, editor.AnnotationState ?? new ClipboardAnnotationState(), capturedAtt.ImagePath!);
            else
                _pastedImageStore.DeleteAnnotationSidecar(capturedAtt.ImagePath!);
            UpdateFollowUpStrip();
            PersistDraftFollowUp();
        };
        OpenEditorModeless(editor);
    }

    private void AppendCommitFollowUpInlines(TextBlock label, FollowUpAttachment att)
    {
        var shaDisplay = att.CommitSha.Length >= 7 ? att.CommitSha[..7] : att.CommitSha;

        var prefix = new Run("↩ ");
        prefix.SetResourceReference(Run.ForegroundProperty, "SubtleText");

        var shaRun = new Run(shaDisplay)
        {
            TextDecorations = TextDecorations.Underline,
            Cursor          = System.Windows.Input.Cursors.Hand,
        };
        shaRun.SetResourceReference(Run.ForegroundProperty, "DocumentLinkText");

        var suffix = new Run($" — \"{att.Description}\"");
        suffix.SetResourceReference(Run.ForegroundProperty, "LabelText");

        if (label.Inlines.Count == 0)
            label.Inlines.Add(prefix);
        label.Inlines.Add(shaRun);
        label.Inlines.Add(suffix);

        // Clicking the underlined SHA opens the commit on GitHub.
        var capturedSha = att.CommitSha;
        shaRun.MouseLeftButtonUp += (_, e) =>
        {
            e.Handled = true;
            var commitUrl = _workspaceGitHubUrl is not null
                ? $"{_workspaceGitHubUrl}/commit/{capturedSha}"
                : null;
            if (commitUrl is not null)
                _ = OpenExternalLinkWithCommitCheckAsync(commitUrl);
        };
    }

    // Clicking anywhere on the follow-up strip (not the dismiss buttons) scrolls the
    // transcript to the turn where the first approval prompt was dispatched.
    private void FollowUpStrip_MouseLeftButtonUp(object sender, System.Windows.Input.MouseButtonEventArgs e)
    {
        if (e.Handled) return;
        if (!_followUpAttachments.TryGetValue(_activeTabId ?? "", out var list)) return;

        // Find the first attachment that came from an approval item (has a commit SHA).
        var commitAtt = list.FirstOrDefault(a => !string.IsNullOrEmpty(a.CommitSha));
        if (commitAtt is null) return;

        var item = _approvalItems.FirstOrDefault(i =>
            string.Equals(i.CommitSha, commitAtt.CommitSha, StringComparison.OrdinalIgnoreCase) ||
            (commitAtt.CommitSha.Length >= 7 && i.CommitSha.StartsWith(commitAtt.CommitSha, StringComparison.OrdinalIgnoreCase)));
        if (item is not null)
            ScrollToApprovalTurn(item);
    }

    private void BranchIndicatorStrip_MouseLeftButtonUp(object sender, System.Windows.Input.MouseButtonEventArgs e)
    {
        ShowBranchContextMenu();
        e.Handled = true;
    }

    private void NoRepoPromptStrip_MouseLeftButtonUp(object sender, System.Windows.Input.MouseButtonEventArgs e)
    {
        const string prompt = RepositoryInitializationPrompt;
        if (_isPromptRunning || IsNativeLoopRunning)
        {
            _promptQueue.EnqueueAtFront(prompt, _promptQueueCoordinator.NextSequenceNumber(), sourceTag: "branch-indicator");
            _promptQueue.RenumberSequentially();
            SyncQueuePanel();
            _ = DrainQueueIfNeededAsync();
        }
        else
        {
            _ = _pec.ExecutePromptAsync(prompt, addToHistory: true, clearPromptBox: true);
        }
        e.Handled = true;
    }

    private void BranchIndicatorStrip_MouseRightButtonUp(object sender, System.Windows.Input.MouseButtonEventArgs e)
    {
        ShowBranchContextMenu();
        e.Handled = true;
    }

    private async void ShowBranchContextMenu()
    {
        try
        {
            var branch = _currentBranch;
            var workspaceFolder = _currentWorkspace?.FolderPath;
            if (workspaceFolder is null) return;

            // No git repo — no menu to show
            if (string.IsNullOrEmpty(branch)) return;

            var resolution = await ResolveHomeBranchAsync(workspaceFolder);
            if (_currentWorkspace?.FolderPath != workspaceFolder || _currentBranch != branch) return;
            bool isHomeBranch = _settingsSnapshot.IsHomeBranch(resolution, branch);
            bool hasRemote = HasGitRemote(workspaceFolder);

            var menu = new ContextMenu();
            menu.SetResourceReference(ContextMenu.StyleProperty, "ThemedContextMenuStyle");

            var headerItem = new MenuItem { Header = branch, IsEnabled = false };
            headerItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
            menu.Items.Add(headerItem);

            if (resolution.Notice is { } notice)
            {
                var noticeItem = new MenuItem { Header = notice, IsEnabled = false };
                noticeItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                menu.Items.Add(noticeItem);
            }

            var sep1 = new Separator();
            sep1.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
            menu.Items.Add(sep1);

            if (hasRemote)
            {
                var pushItem = new MenuItem { Header = "Push branch" };
                pushItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                pushItem.Click += async (_, _) =>
                {
                    try
                    {
                        string pushArgs;
                        try
                        {
                            var upstream = await RunGitAsync(workspaceFolder, "rev-parse --abbrev-ref --symbolic-full-name @{u}");
                            pushArgs = $"push origin {branch}";
                        }
                        catch
                        {
                            pushArgs = $"push --set-upstream origin {branch}";
                        }
                        await RunGitAsync(workspaceFolder, pushArgs);
                        UpdateBranchIndicator();
                    }
                    catch (Exception ex)
                    {
                        UIErrorHelper.ShowError("Push Failed", $"Could not push branch '{branch}':\n\n{ex.Message}");
                    }
                };
                menu.Items.Add(pushItem);
            }

            if (!isHomeBranch)
            {
                bool alreadyQueued = _promptQueue.Items.Any(i => i.SourceTag == "branch-indicator");
                var actions = resolution.IsResolved ? new HomeBranchActions(resolution, branch) : null;
                var mergeItem = new MenuItem
                {
                    Header = actions?.MergeLabel ?? "Merge into home branch (not resolved)",
                    IsEnabled = actions is not null && !alreadyQueued && hasRemote
                };
                mergeItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                menu.Items.Add(mergeItem);

                var switchItem = new MenuItem
                {
                    Header = actions?.SwitchLabel ?? "Switch to home branch (not resolved)",
                    IsEnabled = actions is not null && !alreadyQueued
                };
                switchItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                menu.Items.Add(switchItem);

                if (actions is not null)
                {
                    mergeItem.Click += async (_, _) =>
                    {
                        var step = HomeBranchGitStep.VerifyTarget;
                        try
                        {
                            await VerifyHomeBranchTargetAsync(workspaceFolder, resolution, actions);
                            if (_isPromptRunning || IsNativeLoopRunning)
                            {
                                BranchNameText.Text += " — queued, waiting for active turn to finish";
                                _promptQueue.EnqueueAtFront(actions.QueuedMergePrompt, _promptQueueCoordinator.NextSequenceNumber(), sourceTag: "branch-indicator");
                                _promptQueue.RenumberSequentially();
                                SyncQueuePanel();
                                _ = DrainQueueIfNeededAsync();
                                return;
                            }

                            var result = MessageBox.Show(actions.Confirmation, "Confirm Merge",
                                MessageBoxButton.YesNo, MessageBoxImage.Question);
                            if (result != MessageBoxResult.Yes) return;

                            await VerifyHomeBranchTargetAsync(workspaceFolder, resolution, actions);
                            step = HomeBranchGitStep.Checkout;
                            await RunGitAsync(workspaceFolder, actions.CheckoutArguments);
                            step = HomeBranchGitStep.FastForwardMerge;
                            await RunGitAsync(workspaceFolder, actions.MergeArguments);
                            step = HomeBranchGitStep.Push;
                            await RunGitAsync(workspaceFolder, actions.PushArguments);
                            UpdateBranchIndicator();
                        }
                        catch (Exception ex)
                        {
                            SquadDashTrace.Write("Branch", $"{step} failed: {ex}");
                            var message = HomeBranchFailure.Describe(step, ex.Message, actions);
                            if (step != HomeBranchGitStep.VerifyTarget)
                            {
                                try { await RunGitAsync(workspaceFolder, actions.RestoreArguments); }
                                catch (Exception restoreError)
                                {
                                    SquadDashTrace.Write("Branch", $"Restore of '{branch}' failed: {restoreError}");
                                    message += $"\n\nCould not restore '{branch}': {restoreError.Message}";
                                }
                            }
                            UIErrorHelper.ShowError("Branch Operation Failed", message);
                            UpdateBranchIndicator();
                        }
                    };

                    switchItem.Click += async (_, _) =>
                    {
                        var step = HomeBranchGitStep.VerifyTarget;
                        try
                        {
                            await VerifyHomeBranchTargetAsync(workspaceFolder, resolution, actions);
                            if (_isPromptRunning || IsNativeLoopRunning)
                            {
                                BranchNameText.Text += " — queued, waiting for active turn to finish";
                                _promptQueue.EnqueueAtFront(actions.QueuedSwitchPrompt, _promptQueueCoordinator.NextSequenceNumber(), sourceTag: "branch-indicator");
                                _promptQueue.RenumberSequentially();
                                SyncQueuePanel();
                                _ = DrainQueueIfNeededAsync();
                                return;
                            }
                            step = HomeBranchGitStep.Checkout;
                            await RunGitAsync(workspaceFolder, actions.CheckoutArguments);
                            UpdateBranchIndicator();
                        }
                        catch (Exception ex)
                        {
                            SquadDashTrace.Write("Branch", $"{step} failed: {ex}");
                            UIErrorHelper.ShowError("Switch Branch", HomeBranchFailure.Describe(step, ex.Message, actions));
                        }
                    };
                }

                var sep2 = new Separator();
                sep2.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
                menu.Items.Add(sep2);
            }

            var recentBranches = _settingsSnapshot.GetRecentBranches(workspaceFolder, DateTimeOffset.UtcNow)
                .Where(entry => !string.Equals(entry.BranchName, branch, StringComparison.Ordinal)
                    && !resolution.IsHomeBranch(entry.BranchName))
                .ToArray();
            if (recentBranches.Length > 0)
            {
                if (menu.Items[menu.Items.Count - 1] is not Separator)
                {
                    var recentSeparator = new Separator();
                    recentSeparator.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
                    menu.Items.Add(recentSeparator);
                }

                bool alreadyQueued = _promptQueue.Items.Any(i => i.SourceTag == "branch-indicator");
                foreach (var recentBranch in recentBranches)
                {
                    var targetBranch = recentBranch.BranchName;
                    var recentSwitchItem = new MenuItem
                    {
                        Header = $"Switch to {targetBranch}",
                        IsEnabled = !alreadyQueued
                    };
                    recentSwitchItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                    recentSwitchItem.Click += async (_, _) =>
                    {
                        try
                        {
                            var checkoutArguments = HomeBranchActions.CheckoutBranchArguments(targetBranch);
                            if (_isPromptRunning || IsNativeLoopRunning)
                            {
                                BranchNameText.Text += " \u2014 queued, waiting for active turn to finish";
                                var prompt = $"Switch git branch to '{targetBranch}' using git {checkoutArguments}. "
                                    + "If checkout fails, report the error; do not discard or overwrite uncommitted changes.";
                                _promptQueue.EnqueueAtFront(prompt, _promptQueueCoordinator.NextSequenceNumber(), sourceTag: "branch-indicator");
                                _promptQueue.RenumberSequentially();
                                SyncQueuePanel();
                                _ = DrainQueueIfNeededAsync();
                                return;
                            }

                            await RunGitAsync(workspaceFolder, checkoutArguments);
                            UpdateBranchIndicator();
                        }
                        catch (Exception ex)
                        {
                            SquadDashTrace.Write("Branch", $"Checkout of recent branch '{targetBranch}' failed: {ex}");
                            UIErrorHelper.ShowError("Switch Branch", $"Could not switch to branch '{targetBranch}':\n\n{ex.Message}");
                        }
                    };
                    menu.Items.Add(recentSwitchItem);
                }

                var afterRecentSeparator = new Separator();
                afterRecentSeparator.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
                menu.Items.Add(afterRecentSeparator);
            }

            var setHomeItem = new MenuItem { Header = "Set as home branch" };
            setHomeItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
            setHomeItem.Click += async (_, _) =>
            {
                try
                {
                    await RunGitAsync(workspaceFolder, HomeBranchActions.LocalBranchVerificationArguments(branch));
                    _settingsManager.Replace(_settingsStore.SaveHomeBranch(workspaceFolder, branch));
                    UpdateBranchIndicator();
                }
                catch (Exception ex)
                {
                    SquadDashTrace.Write("Branch", $"Could not set home branch '{branch}': {ex}");
                    UIErrorHelper.ShowError("Set Home Branch", $"Could not save '{branch}' as home. Select an existing local branch.\n\n{ex.Message}");
                }
            };
            menu.Items.Add(setHomeItem);

            var sep3 = new Separator();
            sep3.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
            menu.Items.Add(sep3);

            var copyItem = new MenuItem { Header = "Copy branch name" };
            copyItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
            copyItem.Click += (_, _) => SetClipboardTextWithRetry(branch);
            menu.Items.Add(copyItem);

            if (!hasRemote)
            {
                var sep4 = new Separator();
                sep4.SetResourceReference(Separator.StyleProperty, "ThemedMenuSeparatorStyle");
                menu.Items.Add(sep4);

                var createRepoItem = new MenuItem { Header = "Create GitHub repository..." };
                createRepoItem.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
                createRepoItem.Click += (_, _) =>
                {
                    const string prompt = "Create a new GitHub repository for this workspace and push the current branch";
                    if (_isPromptRunning || IsNativeLoopRunning)
                    {
                        _promptQueue.EnqueueAtFront(prompt, _promptQueueCoordinator.NextSequenceNumber(), sourceTag: "branch-indicator");
                        _promptQueue.RenumberSequentially();
                        SyncQueuePanel();
                        _ = DrainQueueIfNeededAsync();
                    }
                    else
                    {
                        _ = _pec.ExecutePromptAsync(prompt, addToHistory: true, clearPromptBox: true);
                    }
                };
                menu.Items.Add(createRepoItem);
            }

            // Anchor to BranchNameText (tight visual bounds) rather than the full-width
            // BranchIndicatorStrip Border. On Mac/VM with DPI scaling, the full-width
            // element causes WPF to position the popup far to the right.
            menu.PlacementTarget = BranchNameText;
            menu.Placement = System.Windows.Controls.Primitives.PlacementMode.Bottom;
            menu.IsOpen = true;
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(ShowBranchContextMenu), ex);
        }
    }

    private Task<HomeBranchResolution> ResolveHomeBranchAsync(string workspaceFolder) =>
        HomeBranchRepositoryReader.ResolveAsync(workspaceFolder, _settingsSnapshot.GetHomeBranch(workspaceFolder), RunGitAsync);

    private async Task VerifyHomeBranchTargetAsync(
        string workspaceFolder, HomeBranchResolution expected, HomeBranchActions actions)
    {
        var current = await ResolveHomeBranchAsync(workspaceFolder);
        HomeBranchRepositoryReader.VerifyUnchangedTarget(expected, current);
        await RunGitAsync(workspaceFolder, actions.VerifyArguments);
    }

    private static async Task<string> RunGitAsync(string workingDirectory, string arguments)
    {
        var psi = new System.Diagnostics.ProcessStartInfo("git", arguments)
        {
            WorkingDirectory       = workingDirectory,
            RedirectStandardOutput = true,
            RedirectStandardError  = true,
            UseShellExecute        = false,
            CreateNoWindow         = true,
        };
        using var proc = System.Diagnostics.Process.Start(psi)
            ?? throw new InvalidOperationException("Could not start git process.");
        var stdout = await proc.StandardOutput.ReadToEndAsync();
        var stderr = await proc.StandardError.ReadToEndAsync();
        await proc.WaitForExitAsync();
        if (proc.ExitCode != 0)
            throw new InvalidOperationException(
                string.IsNullOrWhiteSpace(stderr) ? stdout.Trim() : stderr.Trim());
        return stdout.Trim();
    }

    /// <summary>
    /// Asynchronously reads HEAD SHA from git. Used at inbox-message save time so the
    /// SHA can be stored with the message for later staleness calculation.
    /// Returns null on any error (non-git repo, git not on PATH, etc.).
    /// A missed SHA is always acceptable — this task is never awaited on the UI thread.
    /// </summary>
    private static async Task<string?> TryGetGitShaAsync(string workingDirectory)
    {
        try
        {
            var psi = new System.Diagnostics.ProcessStartInfo("git", "rev-parse HEAD")
            {
                WorkingDirectory       = workingDirectory,
                RedirectStandardOutput = true,
                RedirectStandardError  = true,
                UseShellExecute        = false,
                CreateNoWindow         = true,
            };
            using var proc = System.Diagnostics.Process.Start(psi);
            if (proc is null) return null;
            var sha = await proc.StandardOutput.ReadToEndAsync().ConfigureAwait(false);
            await proc.WaitForExitAsync().ConfigureAwait(false);
            if (proc.ExitCode != 0) return null;
            sha = sha.Trim();
            return string.IsNullOrEmpty(sha) ? null : sha;
        }
        catch { return null; }
    }

    /// <summary>
    /// Returns the number of commits between <paramref name="savedSha"/> and HEAD.
    /// Returns 0 when <paramref name="savedSha"/> is null, HEAD equals savedSha, or any error occurs.
    /// </summary>
    private async Task<int> TryGetCommitCountSinceAsync(string? savedSha)
    {
        if (string.IsNullOrWhiteSpace(savedSha))
            return 0;
        try
        {
            var output = await RunGitAsync(_workspacePaths.ApplicationRoot, $"rev-list --count {savedSha}..HEAD");
            return int.TryParse(output.Trim(), out var count) ? count : 0;
        }
        catch { return 0; }
    }

    private void FollowUpDismissBtn_Click(object sender, RoutedEventArgs e)
    {
        var hadAttachments = _followUpAttachments.TryGetValue(_activeTabId ?? "", out var existing) && existing.Count > 0;
        if (existing?.Any(attachment => attachment.RequiresRemovalConfirmation) == true &&
            MessageBox.Show(
                this,
                "One or more attachments provide required plan-continuation context. Remove all attachments anyway?",
                "Remove Required Context?",
                MessageBoxButton.YesNo,
                MessageBoxImage.Warning,
                MessageBoxResult.No) != MessageBoxResult.Yes)
            return;
        _followUpAttachments.Remove(_activeTabId ?? "");
        if (hadAttachments) _guidedTourCoordinator.RaiseAllAttachmentsRemoved();
        UpdateFollowUpStrip();
        SyncQueuePanel();
        if (_activeTabId is null) PersistDraftFollowUp();
    }

    /// <summary>
    /// Saves (or clears) the active-draft follow-up attachments to workspace settings
    /// so they survive a restart.  Only the draft slot (key "") is persisted; queue items
    /// are not persisted because the queue itself does not survive a restart.
    /// </summary>
    private void PersistDraftFollowUp()
    {
        var state = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
        if (_followUpAttachments.TryGetValue("", out var list) && list.Count > 0)
        {
            var dtos = list.Select(a => new FollowUpAttachmentDto
            {
                CommitSha         = a.CommitSha,
                Description       = a.Description,
                OriginalPrompt    = a.OriginalPrompt,
                TranscriptQuote   = a.TranscriptQuote,
                ContentBlock      = a.ContentBlock,
                ImagePath         = a.ImagePath,
                ImageSubmittedAt  = a.ImageSubmittedAt?.ToString("O"),
                InboxMessageId    = a.InboxMessageId,
                FileReferencePath = a.FileReferencePath,
                RequiresRemovalConfirmation = a.RequiresRemovalConfirmation,
                RemovalWarning = a.RemovalWarning,
            }).ToList();
            _docsPanelState = state with
            {
                DraftFollowUpsJson          = System.Text.Json.JsonSerializer.Serialize(dtos),
                DraftFollowUpCommitSha      = null,
                DraftFollowUpDescription    = null,
                DraftFollowUpOriginalPrompt = null,
            };
        }
        else
        {
            // "[]" is the sentinel for "explicitly cleared". We cannot use null here because
            // SaveDocsPanelState uses (new ?? existing) merge logic — null would cause the
            // stale JSON from a previous save to survive and re-show follow-ups on restart.
            _docsPanelState = state with
            {
                DraftFollowUpsJson          = "[]",
                DraftFollowUpCommitSha      = null,
                DraftFollowUpDescription    = null,
                DraftFollowUpOriginalPrompt = null,
            };
        }
        _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
    }

    private string ApplyFollowUpHeader(string text, string tabId)
    {
        _pendingTranscriptAttachments = null;
        if (!_followUpAttachments.TryGetValue(tabId, out var list) || list.Count == 0)
            return text;

        // Stamp SubmittedAt for image attachments and rebuild the list with the timestamp set.
        var submittedAt = DateTime.UtcNow;
        var stamped = new List<FollowUpAttachment>(list.Count);
        foreach (var att in list)
        {
            if (att.ImagePath != null)
            {
                _pastedImageStore.SetSubmittedAt(att.ImagePath, submittedAt);
                _pastedImageStore.DeleteAnnotationSidecar(att.ImagePath);
                stamped.Add(att with { ImageSubmittedAt = submittedAt });
            }
            else
            {
                stamped.Add(att);
            }
        }

        _pendingTranscriptAttachments = stamped;
        _followUpAttachments.Remove(tabId);
        if (tabId == "") PersistDraftFollowUp();
        UpdateFollowUpStrip();

        var headers = stamped.Select(att =>
        {
            if (att.ImagePath != null)
                return $"[Attached image: {att.ImagePath}]";
            if (att.ContentBlock != null)
                return att.ContentBlock;
            if (att.FileReferencePath != null)
                return BuildTypedAttachmentBlock("file-reference", att.Description, att.FileReferencePath);
            if (att.TranscriptQuote != null)
                return $"Regarding this section of the transcript: \"{att.TranscriptQuote}\"";
            var summaryHint = att.OriginalPrompt is { Length: > 0 } op
                ? (op.Length > 120 ? op[..120] + "…" : op)
                : att.Description;
            return $"[Follow-up on {att.CommitSha} — \"{att.Description}\": {summaryHint}]";
        }).ToList();

        // When the user has any typed content/image attachments, prepend a one-liner so the AI
        // understands the structure it is receiving.
        bool hasTypedBlocks = stamped.Any(a => a.ContentBlock != null || a.ImagePath != null || a.FileReferencePath != null);
        const string AttachmentPreamble = "The user has attached the following context items. Please refer to them as needed.";
        var headerSection = string.Join("\n", headers);
        return (hasTypedBlocks ? AttachmentPreamble + "\n" + headerSection : headerSection) + "\n\n" + text;
    }

