    private void SyncNotesPanel()
    {
        if (NotesPanelBorder is null) return;
        NotesPanelBorder.Visibility = _notesPanelVisible ? Visibility.Visible : Visibility.Collapsed;
        _dockingService?.OnPanelVisibilityChanged("notes", _notesPanelVisible);
        NotifyToolPanelVisibilityChanged("notes", _notesPanelVisible);
        UpdateMainGridSideMargins();
        if (_notesPanelVisible && _notesPanel is null)
        {
            _notesPanel = new NotesPanelController(
                listPanel:           NotesListPanel!,
                scrollContainer:     (FrameworkElement)NotesListPanel!.Parent,
                openNote:            note => OpenNote(note),
                editNote:            note => EditNote(note),
                renameNote:          (note, title) => RenameNote(note, title),
                deleteNote:          note => DeleteNote(note),
                newNote:             () => CreateNewNote(),
                attachFollowUp:      note => AttachNoteFollowUp(note),
                addToNewChat:        note => { AddEmptyQueueSlot(); AttachNoteFollowUp(note); },
                loadPreview:         note => note.Scope == DataScope.Shared
                                         ? (File.Exists(NotesStore.GetSharedNotePath(_currentWorkspace?.SquadFolderPath ?? "", note.Id))
                                                ? File.ReadAllText(NotesStore.GetSharedNotePath(_currentWorkspace?.SquadFolderPath ?? "", note.Id))
                                                : string.Empty)
                                         : (_notesStore?.LoadContent(note.Id) ?? ""),
                initialSortOrder:    _docsPanelState?.NotesSortOrder ?? NotesSortOrder.MostRecentOnTop,
                onSortOrderChanged:  order => {
                    var st = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
                    _docsPanelState = st with { NotesSortOrder = order };
                    _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
                },
                newSharedNote:       () => CreateNewSharedNote());
            _notesPanel.ClearFilterAction = () => { if (NotesFilterBox is not null) NotesFilterBox.Text = string.Empty; };
            _notesPanel.Refresh(_noteItems);

            // Wire dynamic max-width hint so splitter snap targets content width
            if (NotesPanelBorder is { } npb)
                npb.MaximumUsefulSizeProvider = orientation => orientation switch
                {
                    DockResizeOrientation.Horizontal => _notesPanel.GetMaximumUsefulWidth(),
                    DockResizeOrientation.Vertical   => _notesPanel.GetMaximumUsefulHeight(),
                    _                                => null
                };
        }
    }

