    private const string RepositoryInitializationPrompt =
        "Initialize a git repository and create an initial commit";

    private async Task<bool> InitializeRepositoryForPlanAsync()
    {
        if (_currentWorkspace is null)
            return false;

        var workspace = _currentWorkspace.FolderPath;
        var activeBranch = ReadGitBranch(workspace);
        if (!string.IsNullOrWhiteSpace(activeBranch) &&
            !activeBranch.StartsWith("(detached", StringComparison.Ordinal))
            return true;

        if (_isPromptRunning || IsNativeLoopRunning)
            return false;

        await _pec.ExecutePromptAsync(
            RepositoryInitializationPrompt,
            addToHistory: true,
            clearPromptBox: true);
        UpdateBranchIndicator();

        activeBranch = ReadGitBranch(workspace);
        return !string.IsNullOrWhiteSpace(activeBranch) &&
               !activeBranch.StartsWith("(detached", StringComparison.Ordinal);
    }

    private async Task StartOrResumeDurablePlanAsync(Plan plan)
    {
        try
        {
            if (plan.LifecycleStatus != PlanLifecycleStatus.Approved &&
                !await EnsureResumeBranchChoiceAsync(plan))
                return;
            if (!await StartDurablePlanExecutionAsync(plan))
                AppendLine($"⚠ Plan “{plan.Title}” did not start. Open the plan to review its current state.");
        }
        catch (PlanPreflightBlockedException blocked)
        {
            var latest = _planStore?.Load(plan.PlanId) ?? plan;
            var pending = PendingDecomposePlanAdapter.FromPlan(latest);
            var taskId = latest.InterruptionData?.InterruptedTaskId
                ?? latest.Tasks.FirstOrDefault(task => task.Status == PlanTaskStatus.Pending)?.TaskId;
            var taskTitle = latest.Tasks.FirstOrDefault(task =>
                string.Equals(task.TaskId, taskId, StringComparison.Ordinal))?.Title ?? taskId ?? "reopened task";
            var isReworkPause = PlanRecoveryResumePolicy.IsReworkPreflightPause(latest) ||
                                PlanRecoveryResumePolicy.HasPendingRework(latest);
            var isAmendmentPause = PlanRecoveryResumePolicy.IsAmendmentPreflightPause(latest) ||
                                   PlanRecoveryResumePolicy.HasPendingAmendment(latest);

            ShowTranscriptPlanPreflightRecovery(
                pending,
                action: "resume-plan",
                branchOverride: latest.Branch,
                exception: blocked,
                sourceActionsPanel: null,
                blocks: CoordinatorThread.Document.Blocks,
                retryOverride: async () => await StartDurablePlanExecutionAsync(latest),
                contentFactory: isAmendmentPause
                    ? exception => PlanPreflightRecoveryContent.FromAmendment(
                        exception,
                        latest.Title,
                        taskTitle)
                    : isReworkPause
                    ? exception => PlanPreflightRecoveryContent.FromRework(
                        exception,
                        latest.Title,
                        taskTitle)
                    : null,
                retryLabel: isAmendmentPause ? "Resume Amendment" : isReworkPause ? "Resume Rework" : "Resume Plan");
        }
        catch (Exception ex)
        {
            HandleUiCallbackException("Resume plan", ex);
        }
    }

    private async Task<bool> EnsureResumeBranchChoiceAsync(Plan plan)
    {
        if (_currentWorkspace is null)
            throw new InvalidOperationException("No workspace is active.");

        var workspace = _currentWorkspace.FolderPath;
        var currentBranch = ReadGitBranch(workspace);
        if (string.Equals(currentBranch, plan.Branch, StringComparison.Ordinal))
            return true;
        if (string.IsNullOrWhiteSpace(currentBranch) ||
            currentBranch.StartsWith("(detached", StringComparison.Ordinal))
            throw new InvalidOperationException(
                "Resume cannot choose a branch while the repository is in detached-HEAD state.");

        await EnsurePlanWorktreeReadyAsync(workspace, plan.PlanId);
        var situation = await InspectResumeBranchSituationAsync(
            workspace,
            currentBranch,
            plan.Branch);
        var dialog = new PlanResumeBranchDialog(situation, this);
        if (dialog.ShowDialog() != true || dialog.Choice == PlanResumeBranchAction.Cancel)
            return false;

        await ApplyResumeBranchChoiceAsync(workspace, situation, dialog.Choice);
        UpdateBranchIndicator();
        ScheduleDecomposeSystemEntry(dialog.Choice == PlanResumeBranchAction.BringCurrentWork
            ? $"SquadDash brought work from '{situation.CurrentBranch}' into the plan branch " +
              $"'{situation.PlanBranch}' and will resume there."
            : $"SquadDash switched to the plan branch '{situation.PlanBranch}'. " +
              $"Work on '{situation.CurrentBranch}' remains preserved on that branch.");
        return true;
    }

    private async Task<PlanResumeBranchSituation> InspectResumeBranchSituationAsync(
        string workspace,
        string currentBranch,
        string planBranch)
    {
        var escapedPlanBranch = planBranch.Replace("\"", "\\\"");
        var existing = (await RunGitAsync(
            workspace,
            $"branch --list --format=\"%(refname:short)\" \"{escapedPlanBranch}\"")).Trim();
        if (!string.Equals(existing, planBranch, StringComparison.Ordinal))
            throw new InvalidOperationException(
                $"The host-owned plan branch '{planBranch}' no longer exists. " +
                "SquadDash left repository history unchanged.");

        var escapedCurrentBranch = currentBranch.Replace("\"", "\\\"");
        var currentHead = (await RunGitAsync(workspace, $"rev-parse \"{escapedCurrentBranch}^{{commit}}\"")).Trim();
        var planHead = (await RunGitAsync(workspace, $"rev-parse \"{escapedPlanBranch}^{{commit}}\"")).Trim();

        async Task<bool> IsAncestorAsync(string possibleAncestor, string possibleDescendant)
        {
            try
            {
                await RunGitAsync(
                    workspace,
                    $"merge-base --is-ancestor \"{possibleAncestor}\" \"{possibleDescendant}\"");
                return true;
            }
            catch
            {
                return false;
            }
        }

        async Task<int> CountAsync(string range)
        {
            var value = (await RunGitAsync(workspace, $"rev-list --count \"{range}\"")).Trim();
            return int.TryParse(value, out var count) ? count : 0;
        }

        var planIsAncestorOfCurrent = await IsAncestorAsync(planHead, currentHead);
        var currentIsAncestorOfPlan = await IsAncestorAsync(currentHead, planHead);
        var relationship = PlanResumeBranchPolicy.Classify(
            planIsAncestorOfCurrent,
            currentIsAncestorOfPlan);
        var currentOnlyCount = await CountAsync($"{planHead}..{currentHead}");
        var planOnlyCount = await CountAsync($"{currentHead}..{planHead}");
        var status = await RunGitAsync(workspace, "status --porcelain --untracked-files=all");

        return new PlanResumeBranchSituation(
            currentBranch,
            planBranch,
            currentHead,
            planHead,
            relationship,
            currentOnlyCount,
            planOnlyCount,
            string.IsNullOrWhiteSpace(status));
    }

    private async Task ApplyResumeBranchChoiceAsync(
        string workspace,
        PlanResumeBranchSituation situation,
        PlanResumeBranchAction action)
    {
        var escapedCurrent = situation.CurrentBranch.Replace("\"", "\\\"");
        var escapedPlan = situation.PlanBranch.Replace("\"", "\\\"");

        if (action == PlanResumeBranchAction.SwitchOnly ||
            situation.Relationship is PlanResumeBranchRelationship.PlanAhead or
                PlanResumeBranchRelationship.SameCommit)
        {
            await RunGitAsync(workspace, $"checkout \"{escapedPlan}\"");
            return;
        }

        if (action != PlanResumeBranchAction.BringCurrentWork || !situation.CanBringCurrentWork)
            throw new InvalidOperationException("The selected branch action is not currently available.");

        if (situation.Relationship == PlanResumeBranchRelationship.CurrentAhead)
        {
            // Recheck ancestry immediately before moving the plan branch, then fast-forward its
            // pointer while the current branch remains checked out. The subsequent checkout has
            // no file-tree delta, so allowed plan metadata can remain in the working tree.
            await RunGitAsync(
                workspace,
                $"merge-base --is-ancestor \"{situation.PlanHead}\" \"{situation.CurrentHead}\"");
            await RunGitAsync(
                workspace,
                $"branch -f \"{escapedPlan}\" \"{escapedCurrent}\"");
            await RunGitAsync(workspace, $"checkout \"{escapedPlan}\"");
            return;
        }

        if (situation.Relationship != PlanResumeBranchRelationship.Diverged)
            throw new InvalidOperationException("The branches no longer have the expected relationship.");

        await RunGitAsync(workspace, $"checkout \"{escapedPlan}\"");
        try
        {
            await RunGitAsync(workspace, $"merge --no-edit \"{escapedCurrent}\"");
        }
        catch (Exception mergeError)
        {
            try { await RunGitAsync(workspace, "merge --abort"); } catch { }
            try { await RunGitAsync(workspace, $"checkout \"{escapedCurrent}\""); } catch { }
            UpdateBranchIndicator();
            throw new InvalidOperationException(
                "The branches could not be combined automatically. SquadDash aborted the merge " +
                "and returned to the current branch; both branch histories remain intact. " +
                mergeError.Message,
                mergeError);
        }
    }

    private void OpenPlanFromStore(Plan plan)
    {
        try
        {
            // The Plans panel is a durable-plan surface. A pending Inbox proposal can legitimately
            // have the same plan ID while representing a different revision, so never substitute
            // it here. Inbox and transcript proposal links open their own pending snapshots.
            plan = _planStore?.Load(plan.PlanId) ?? plan;
            OpenDecomposePlanViewer(PendingDecomposePlanAdapter.FromPlan(plan), durablePlan: plan);
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(OpenPlanFromStore), ex); }
    }

    private void ArchivePlan(Plan plan)
    {
        if (_planStore is null) return;
        var archived = PlanStoreUpdater.ApplyArchived(plan);
        if (ReferenceEquals(archived, plan))
        {
            AppendLine("A running plan must be paused or ended before it can be archived.");
            return;
        }
        if (!TryPublishPlanProgress(archived, out var error))
        {
            AppendLine($"⚠ Plan could not be archived: {error}");
            return;
        }
        ArchivePlanFamilyArtifacts(archived.PlanId);
        if (PlansShowArchivedCheckBox is not null)
            PlansShowArchivedCheckBox.IsChecked = true;
    }

    private bool IsDurablePlanArchived(string planId)
    {
        if (_currentWorkspace is null || string.IsNullOrWhiteSpace(planId))
            return false;

        _planStore ??= new PlanStore(_currentWorkspace.SquadFolderPath);
        return _planStore.Load(planId)?.LifecycleStatus == PlanLifecycleStatus.Archived;
    }

    private void PruneArchivedPlanFamilyArtifacts(IEnumerable<Plan> plans)
    {
        ArchivePlanFamilyArtifacts(plans
            .Where(candidate => candidate.LifecycleStatus == PlanLifecycleStatus.Archived)
            .Select(candidate => candidate.PlanId));
    }

    private void ArchivePlanFamilyArtifacts(string planId) =>
        ArchivePlanFamilyArtifacts([planId]);

    private void ArchivePlanFamilyArtifacts(IEnumerable<string> planIds)
    {
        if (_currentWorkspace is null || _inboxStore is null)
            return;

        var archivedPlanIds = planIds.ToHashSet(StringComparer.Ordinal);
        if (archivedPlanIds.Count == 0)
            return;

        var archivedMessageIds = PlanFamilyArtifactArchiver.ArchiveMany(
            archivedPlanIds,
            new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath),
            _inboxStore);
        _pendingPlansAtCoordinatorTurnStart = _pendingPlansAtCoordinatorTurnStart
            .Where(candidate => !archivedPlanIds.Contains(candidate.Group.GroupId))
            .ToArray();

        foreach (var window in _openInboxWindows
                     .Where(window => archivedMessageIds.Contains(window.MessageId, StringComparer.Ordinal))
                     .ToArray())
            window.Close();

        var messages = _inboxStore.LoadAll();
        _inboxPanel?.Refresh(messages);
        ReconcileOpenInboxWindows(messages);
        SquadDashTrace.Write(TraceCategory.Inbox,
            $"Archived {archivedPlanIds.Count} plan family/families: retired {archivedMessageIds.Count} active Inbox artifact(s) and all pending revisions.");
    }

    private bool RequestPlanPauseAfterCurrentStep(Plan plan)
    {
        if (!string.Equals(_activeDecomposeGroupId, plan.PlanId, StringComparison.Ordinal) || !IsLoopRunning)
            return false;

        if (!TrySetPlanPauseState(plan, pause: true, out var current, out var pauseError))
        {
            ReportPlanActionIssue(
                plan.PlanId,
                "Pause not saved",
                pauseError ?? "SquadDash could not save the pause request. Plan execution is still running.");
            return false;
        }
        if (_pausePlanAfterCurrentStepRequested)
            return true;

        ClearPlanActionIssue(plan.PlanId);
        _pausePlanAfterCurrentStepRequested = true;
        ShowPlanPauseRequestedEntry(current);
        return true;
    }

    private bool HasActivePlanWork(string planId)
    {
        if (string.IsNullOrWhiteSpace(planId))
            return false;

        var runtimeOwnsPlan = string.Equals(
            _activeDecomposeGroupId,
            planId,
            StringComparison.Ordinal);
        if (runtimeOwnsPlan && (_isPromptRunning || IsLoopRunning || _loopController.IsRunning))
            return true;

        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (execution?.IsExecutingPlan != true ||
            !string.Equals(execution.DecomposeGroupId, planId, StringComparison.Ordinal))
        {
            return false;
        }

        return execution.PlanExecutionAttempt is { Status: "active" } ||
               !string.IsNullOrWhiteSpace(execution.ActiveVerificationTaskId) ||
               !string.IsNullOrWhiteSpace(execution.ActiveValidationId);
    }

    private bool IsPlanRecoveryActionBusy(string planId) =>
        _isPromptRunning || IsLoopRunning || _loopController.IsRunning || HasActivePlanWork(planId);

    private bool TrySetPlanPauseState(
        Plan plan,
        bool pause,
        out Plan persistedPlan,
        out string? error)
    {
        persistedPlan = plan;
        if (_planStore is null)
        {
            error = "The plan store is unavailable.";
            return false;
        }

        var current = _planStore.Load(plan.PlanId);
        if (current is null)
        {
            error = $"The durable plan '{plan.PlanId}' is unavailable.";
            return false;
        }

        return PlanPauseTransitionCoordinator.TryApply(
            current,
            pause,
            candidate =>
            {
                var success = TryPublishPlanProgress(candidate, out var persistError);
                return (success, persistError);
            },
            RefreshOpenPlanViewersAfterPauseTransition,
            out persistedPlan,
            out error);
    }

    private void RefreshOpenPlanViewersAfterPauseTransition(Plan plan)
        => RefreshOpenPlanViewers(plan, "pause state");

    private void RefreshOpenPlanViewersAfterAutomaticContinuation(Plan plan)
        => RefreshOpenPlanViewers(plan, "automatic continuation");

    private void RefreshOpenPlanViewers(Plan plan, string reason)
    {
        foreach (var entry in _openPlanViewerWindows
                     .Where(entry => string.Equals(entry.GroupId, plan.PlanId, StringComparison.Ordinal))
                     .ToArray())
        {
            try
            {
                entry.Window.RefreshPlan(PendingDecomposePlanAdapter.FromPlan(plan), plan);
            }
            catch (Exception ex)
            {
                SquadDashTrace.Write(
                    "PlanViewer",
                    $"Could not refresh {reason} for plan={plan.PlanId}: {ex.Message}");
            }
        }
    }

    private bool CancelPlanPauseAfterCurrentStep(Plan plan)
    {
        if (!string.Equals(_activeDecomposeGroupId, plan.PlanId, StringComparison.Ordinal) || !IsLoopRunning)
            return false;

        var current = _planStore?.Load(plan.PlanId) ?? plan;
        if (!_pausePlanAfterCurrentStepRequested && !current.IsPaused)
        {
            RemovePlanPauseRequestedEntries(plan.PlanId);
            return false;
        }

        if (!TrySetPlanPauseState(current, pause: false, out _, out var resumeError))
        {
            ReportPlanActionIssue(
                plan.PlanId,
                "Pause still active",
                resumeError ?? "SquadDash could not save the request to keep the plan running.");
            return false;
        }

        ClearPlanActionIssue(plan.PlanId);
        _pausePlanAfterCurrentStepRequested = false;
        RemovePlanPauseRequestedEntries(plan.PlanId);
        ShowSystemTranscriptEntry("Pause canceled. Plan execution will continue after the current task completes.");
        return true;
    }

    private void ShowPlanPauseRequestedEntry(Plan plan)
    {
        RemovePlanPauseRequestedEntries(plan.PlanId);
        ShowSystemTranscriptEntry(PlanLoopTranscriptPresentation.BuildPauseRequestedMessage(plan));

        var panel = new WrapPanel { Orientation = Orientation.Horizontal };
        var container = TranscriptQuickReplyFactory.CreateContainer(
            panel,
            new PlanPauseRequestedTag(plan.PlanId, plan.Revision));

        var keepRunning = TranscriptQuickReplyFactory.CreateButton(
            PlanLoopTranscriptPresentation.KeepPlanRunningLabel,
            _transcriptFontSize,
            toolTip: ToolTipHelper.MakeThemedToolTip(
                "Cancel the pause request. The current task continues and the next task may start normally."));
        keepRunning.Focusable = false;
        keepRunning.Click += (_, _) =>
        {
            var current = _planStore?.Load(plan.PlanId) ?? plan;
            if (!CancelPlanPauseAfterCurrentStep(current))
                OpenPlanFromStore(current);
        };
        panel.Children.Add(keepRunning);

        var viewWork = TranscriptQuickReplyFactory.CreateButton(
            PlanLoopTranscriptPresentation.ViewActiveWorkLabel,
            _transcriptFontSize,
            toolTip: ToolTipHelper.MakeThemedToolTip(
                "Open the plan visualizer at the task that is still running."));
        viewWork.Focusable = false;
        viewWork.Click += (_, _) => OpenPlanFromStore(_planStore?.Load(plan.PlanId) ?? plan);
        panel.Children.Add(viewWork);

        CoordinatorThread.Document.Blocks.Add(container);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private void RemovePlanPauseRequestedEntries(string planId)
    {
        var entries = CoordinatorThread.Document.Blocks
            .OfType<BlockUIContainer>()
            .Where(container =>
                container.Tag is PlanPauseRequestedTag tag &&
                string.Equals(tag.PlanId, planId, StringComparison.Ordinal))
            .ToArray();
        foreach (var entry in entries)
            CoordinatorThread.Document.Blocks.Remove(entry);
    }

    private sealed record PlanPauseRequestedTag(string PlanId, string Revision);

    private async void AbortCurrentPlanWork(Plan plan)
    {
        if (!string.Equals(_activeDecomposeGroupId, plan.PlanId, StringComparison.Ordinal) || !IsLoopRunning)
            return;
        var result = MessageBox.Show(
            "Abort the current plan work immediately? Files and commits will be preserved, and the task will require recovery assessment before continuing.",
            "Abort Current Plan Work",
            MessageBoxButton.OKCancel,
            MessageBoxImage.Warning);
        if (result != MessageBoxResult.OK) return;

        _planAbortRequestedByUser = true;
        SuppressLoopResumeAfterExplicitStop("abort-plan-work");
        if (_activeLoopMode == LoopMode.NativeAgents)
        {
            _loopController.RequestAbort();
            _loopFollowUpTcs?.TrySetResult(false);
        }
        else
        {
            await _bridge.StopLoopAsync();
        }
    }

    // ── Plan lifecycle event helpers ──────────────────────────────────────────

    /// <summary>
    /// On startup, transitions any plan still in <see cref="PlanLifecycleStatus.Executing"/>
    /// to <see cref="PlanLifecycleStatus.Interrupted"/>. These plans were interrupted by a
    /// process restart and must not silently remain Executing with no active loop.
    /// </summary>
    private void RepairStalePlanExecutingState()
    {
        if (_planStore is null || _activeDecomposeGroupId is not null) return;
        try
        {
            var resumableExecution = _conversationManager.ConversationState.ActiveLoopExecution;
            var allPlans = _planStore.LoadAll();
            foreach (var plan in allPlans)
            {
                if (plan.LifecycleStatus != PlanLifecycleStatus.Executing) continue;

                // The workspace envelope is the durable owner of this execution. Leave
                // the matching plan executing until startup either claims it or records
                // a visible, recoverable interruption.
                if (string.Equals(
                        resumableExecution?.DecomposeGroupId,
                        plan.PlanId,
                        StringComparison.Ordinal) &&
                    (string.Equals(
                         resumableExecution?.DecomposeRevision,
                         plan.Revision,
                         StringComparison.Ordinal) ||
                     string.Equals(
                         resumableExecution?.PendingDecomposeRevision,
                         plan.Revision,
                         StringComparison.Ordinal)))
                    continue;

                var interruptedTaskId = plan.Progress.ExecutingTaskId
                    ?? plan.Tasks.FirstOrDefault(task => task.Status != PlanTaskStatus.Complete)?.TaskId;
                var repairReason = PlanRecoveryResumePolicy.HasPendingAmendment(plan)
                    ? PlanRecoveryResumePolicy.BuildAmendmentPreflightReason(
                        "No matching workspace execution envelope was available after restart.")
                    : PlanRecoveryResumePolicy.HasPendingRework(plan)
                    ? PlanRecoveryResumePolicy.BuildReworkPreflightReason(
                        "No matching workspace execution envelope was available after restart.")
                    : "No matching workspace execution envelope was available after restart.";
                var repaired = PlanStoreUpdater.ApplyInterrupted(
                    plan,
                    reason:        repairReason,
                    loopIteration: 0,
                    interruptedTaskId: interruptedTaskId);
                _planStore.Save(repaired);
                _broker.Publish(new PlanProgressEvent(repaired.PlanId, repaired));
                ScheduleDecomposeSystemEntry(
                    $"Plan {repaired.PlanId} could not resume automatically because its saved execution ownership was unavailable. The plan was preserved for recovery.",
                    repaired.PlanId,
                    repaired.Revision,
                    interruptedTaskId);
            }

            foreach (var plan in _planStore.LoadAll())
            {
                var repaired = PlanStoreUpdater.RepairInconsistentState(plan);
                if (!ReferenceEquals(repaired, plan))
                {
                    SquadDashTrace.Write("PlanRepair", $"Repaired inconsistent plan {plan.PlanId}: {plan.LifecycleStatus} → {repaired.LifecycleStatus}");
                    _planStore.Save(repaired);
                    if (_currentWorkspace is not null)
                    {
                        var tasksPath = Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");
                        var projectionRepair = PlanTaskProjectionRepair.EnsureCanonicalStatuses(tasksPath, repaired);
                        if (projectionRepair.Outcome == PlanTaskProjectionRepairOutcome.Conflict)
                        {
                            SquadDashTrace.Write(
                                "PlanProjection",
                                $"Could not synchronize repaired plan {plan.PlanId}: {projectionRepair.Error}");
                        }
                    }
                }
            }
            ReconcileDecomposeRecoveryInboxMessages();
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.General, $"RepairStalePlanExecutingState: {ex.Message}");
        }
    }

    private void ReconcileCollectedPendingPlans()
    {
        if (_currentWorkspace is null || _planStore is null) return;
        try
        {
            var removed = PendingPlanCollectionReconciler.Reconcile(
                _planStore,
                new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath));
            if (removed.Count == 0) return;

            foreach (var pending in removed)
            {
                _inboxStore?.MarkActionUsed(
                    DecomposePlanInbox.BuildMessageId(pending),
                    "Add to Plans");
                SquadDashTrace.Write(
                    TraceCategory.UI,
                    $"Removed already-collected pending plan group={pending.Group.GroupId} revision={pending.Revision} during workspace hydration.");
            }
            _inboxPanel?.Refresh(_inboxStore?.LoadAll() ?? []);
            RemovePendingDecomposeApprovalButtons();
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                TraceCategory.General,
                $"ReconcileCollectedPendingPlans: {ex.Message}");
        }
    }

    private async Task<bool> StartDurablePlanExecutionAsync(Plan plan)
    {
        if (_currentWorkspace is null)
            return false;

        // A collected approved plan has not passed through the immediate-execution branch
        // preparation path. Create or select its canonical branch before establishing the
        // branch lease. Interrupted plans already own that branch and retain their statuses.
        if (plan.LifecycleStatus == PlanLifecycleStatus.Approved)
            await PrepareDecomposeBranchAsync(_currentWorkspace.FolderPath, plan.Branch.Trim(), plan.PlanId);

        return await StartDecomposeLoopAsync(plan.PlanId);
    }

    private void RepairActivePlanTaskProjections()
    {
        if (_currentWorkspace is null || _planStore is null) return;
        try
        {
            var branch = ReadGitBranch(_currentWorkspace.FolderPath);
            var tasksPath = Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");
            foreach (var plan in _planStore.LoadAll().Where(plan =>
                         (plan.LifecycleStatus is PlanLifecycleStatus.Executing or
                             PlanLifecycleStatus.AwaitingApproval or
                             PlanLifecycleStatus.Interrupted or
                             PlanLifecycleStatus.Blocked) &&
                         string.Equals(plan.Branch, branch, StringComparison.Ordinal)))
            {
                var result = PlanTaskProjectionRepair.EnsureAfterHostTopologyMigration(tasksPath, plan);
                if (result.Outcome == PlanTaskProjectionRepairOutcome.Repaired)
                {
                    SquadDashTrace.Write(
                        "PlanProjection",
                        $"Restored missing tasks.md projection from durable plan plan={plan.PlanId} revision={plan.Revision}.");
                }
                else if (result.Outcome == PlanTaskProjectionRepairOutcome.Conflict)
                {
                    SquadDashTrace.Write(
                        "PlanProjection",
                        $"Did not overwrite conflicting tasks.md projection plan={plan.PlanId}: {result.Error}");
                }
            }
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("PlanProjection", $"Active plan projection repair failed: {ex.Message}");
        }
    }

    private bool TryPublishPlanProgress(Plan plan, out string? error)
    {
        if (_planStore is null)
        {
            error = "The plan store is unavailable.";
            return false;
        }
        return TryPublishPlanProgressCore(
            plan,
            persisted => _planStore.Save(persisted),
            out error);
    }

    private bool TryPublishPlanRecoveryProgress(
        Plan expected,
        Plan plan,
        out Plan? persistedPlan,
        out string? error)
    {
        persistedPlan = null;
        error = null;
        if (_planStore is null)
        {
            error = "The plan store is unavailable.";
            return false;
        }

        try
        {
            persistedPlan = _planStore.SaveRecoveryTransition(expected, plan);
        }
        catch (Exception ex)
        {
            error = ex.Message;
            SquadDashTrace.Write(TraceCategory.General, $"PublishPlanRecoveryProgress: {error}");
            return false;
        }

        try
        {
            _broker.Publish(new PlanProgressEvent(persistedPlan.PlanId, persistedPlan));
        }
        catch (Exception ex)
        {
            // Persistence succeeded. UI refresh can recover from PlanStore and must not cause
            // the transition to be repeated.
            SquadDashTrace.Write(TraceCategory.General, $"PublishPlanRecoveryProgress event: {ex.Message}");
        }
        ReconcileDecomposeRecoveryInboxMessages(persistedPlan.PlanId);
        return true;
    }

    private bool TryPublishPlanProgressCore(
        Plan plan,
        Action<Plan> persist,
        out string? error)
    {
        error = null;
        var published = PlanProgressPublisher.TryPublish(
            plan,
            persist,
            persisted => _broker.Publish(new PlanProgressEvent(persisted.PlanId, persisted)),
            out error,
            out var notificationError);
        if (!published)
        {
            SquadDashTrace.Write(TraceCategory.General, $"PublishPlanProgress: {error}");
            return false;
        }
        if (notificationError is not null)
        {
            // The durable transition succeeded. A UI refresh failure must not cause the task to
            // execute again; the panel can recover from PlanStore on its next refresh.
            SquadDashTrace.Write(TraceCategory.General, $"PublishPlanProgress event: {notificationError}");
        }
        ReconcileDecomposeRecoveryInboxMessages(plan.PlanId);
        return true;
    }

    private void PublishPlanProgress(Plan plan) => TryPublishPlanProgress(plan, out _);

    /// <summary>
    /// Refreshes the human-readable tasks.md view after canonical state has been saved. A
    /// projection failure is diagnostic only and can never reject, roll back, or steer plan
    /// execution.
    /// </summary>
    private void RefreshPlanProjectionBestEffort(Plan plan, string reason)
    {
        if (_currentWorkspace is null) return;
        try
        {
            var tasksPath = Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");
            var result = PlanTaskProjectionRepair.EnsureCanonicalStatuses(tasksPath, plan);
            if (result.Outcome == PlanTaskProjectionRepairOutcome.Conflict)
                SquadDashTrace.Write(
                    "PlanProjection",
                    $"Projection refresh did not affect canonical execution plan={plan.PlanId} reason={reason}: {result.Error}");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "PlanProjection",
                $"Projection refresh failed without affecting canonical execution plan={plan.PlanId} reason={reason}: {ex.Message}");
        }
    }

    private async Task RefreshApprovalRequestAfterGateGuidanceEditAsync(Plan plan)
    {
        if (_planApprovalRuntime is null || _inboxStore is null ||
            !plan.ApprovalGates.Any(gate => gate.Status == PlanGateStatus.AwaitingApproval))
            return;

        try
        {
            await _planApprovalRuntime.Requests.RefreshFromPlanAsync(plan);
            var messages = _inboxStore.LoadAll();
            _inboxPanel?.Refresh(messages);
            var messageId = DurableApprovalRequestManager.BuildMessageId(plan.PlanId);
            if (_inboxStore.GetById(messageId) is { } message)
                RefreshOpenApprovalInboxWindows(messageId, message);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write("Approval",
                $"Could not refresh edited approval guidance for {plan.PlanId}: {ex.Message}");
        }
    }

    /// <summary>
    /// Called when a decompose loop starts or resumes. Creates or updates the Plan in
    /// <see cref="PlanStore"/> and fires a progress event so the panel reflects
    /// <see cref="PlanLifecycleStatus.Executing"/>.
    /// </summary>
    private bool TryPublishPlanStarted(
        string groupId,
        DecomposedTaskGroup? group,
        string revision,
        out string? error)
    {
        error = null;
        if (_currentWorkspace is null)
        {
            error = "No workspace is active.";
            return false;
        }
        if (_planStore is null)
        {
            error = "The plan store is unavailable.";
            return false;
        }
        try
        {
            var existing = _planStore.Load(groupId);
            if (existing is not null)
                existing = RepairPlanSchemaBeforeExecution(existing);
            var resolvedGroup = existing is not null
                ? PendingDecomposePlanAdapter.FromPlan(existing).Group with { HostRevision = existing.Revision }
                : group;
            if (resolvedGroup is null)
            {
                error = $"Plan {groupId} has no durable execution contract.";
                return false;
            }

            var updated = existing is not null
                ? PlanStoreUpdater.ApplyExecutionStarted(
                    existing,
                    _CodeHealthGroupRunner?.CurrentStepId)
                : PlanStoreUpdater.ApplyExecutionStarted(
                    null,
                    resolvedGroup,
                    revision,
                    [],
                    _CodeHealthGroupRunner?.CurrentStepId);
            if (existing is null && !PendingDecomposePlanAdapter.RevisionIsValid(updated))
            {
                error =
                    "Its durable task, approval-gate, and validation projection does not match " +
                    "the user-approved revision.";
                return false;
            }
            if (!TryPublishPlanProgress(updated, out error))
                return false;
            RefreshPlanProjectionBestEffort(updated, "plan-started");
            return true;
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.General, $"TryPublishPlanStarted: {ex.Message}");
            error = ex.Message;
            return false;
        }
    }

    private Plan RepairPlanSchemaBeforeExecution(Plan plan)
    {
        var repaired = PlanStoreUpdater.RepairValidationHumanProofGateSchema(plan);
        if (ReferenceEquals(repaired, plan))
            return plan;

        try
        {
            _planStore?.Save(repaired);
            SquadDashTrace.Write(
                "PlanRepair",
                $"Repaired execution schema compatibility for plan {plan.PlanId} before start/resume.");
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or InvalidOperationException)
        {
            SquadDashTrace.Write(
                "PlanRepair",
                $"Could not persist execution schema compatibility repair for plan {plan.PlanId}: {ex.Message}");
        }

        return repaired;
    }

    private void InterruptPlanAfterFailedResume(
        ActiveLoopExecutionState execution,
        string reason)
    {
        if (_planStore is null || string.IsNullOrWhiteSpace(execution.DecomposeGroupId))
            return;

        // Some lower-level validation paths clear runtime state while refusing a
        // start. Restore the captured durable envelope until recovery is recorded.
        _conversationManager.UpdateActiveLoopExecutionState(execution);
        var plan = _planStore.Load(execution.DecomposeGroupId);
        if (plan is null)
        {
            ScheduleDecomposeSystemEntry(
                $"Plan {execution.DecomposeGroupId} was not resumed after restart: {reason} " +
                "Its saved execution details were preserved because the durable plan could not be loaded.");
            return;
        }

        var interruptedTaskId = plan.Progress.ExecutingTaskId
            ?? plan.Tasks.FirstOrDefault(task => task.Status != PlanTaskStatus.Complete)?.TaskId;
        try
        {
            var interruptionReason = PlanRecoveryResumePolicy.HasPendingAmendment(plan)
                ? PlanRecoveryResumePolicy.BuildAmendmentPreflightReason(reason)
                : PlanRecoveryResumePolicy.HasPendingRework(plan)
                ? PlanRecoveryResumePolicy.BuildReworkPreflightReason(reason)
                : $"Automatic restart recovery failed: {reason}";
            var interrupted = PlanStoreUpdater.ApplyInterrupted(
                plan,
                interruptionReason,
                execution.LastCompletedIteration,
                interruptedTaskId,
                lastCommit: execution.TaskBaselineCommit);
            _planStore.Save(interrupted);
            _broker.Publish(new PlanProgressEvent(interrupted.PlanId, interrupted));

            // Only clear ownership after the plan has durably transitioned to a state
            // with an explicit recovery path.
            _settingsManager.Replace(_settingsStore.SaveLoopActive(false));
            ClearExecutingPlanState();
            ScheduleDecomposeSystemEntry(
                $"Plan {interrupted.PlanId} was not resumed after restart: {reason} The plan and its recovery choices were preserved.",
                interrupted.PlanId,
                interrupted.Revision,
                interruptedTaskId);
        }
        catch (Exception persistenceError)
        {
            // Retain the envelope if interruption state itself cannot be persisted. It is
            // safer to retry ownership recovery than to orphan an executing plan silently.
            SquadDashTrace.Write(
                "Loop",
                $"Failed to persist restart interruption for plan {plan.PlanId}: {persistenceError}");
            ScheduleDecomposeSystemEntry(
                $"Plan {plan.PlanId} could not resume, and SquadDash could not save its recovery state. " +
                "The saved execution details remain intact. " + persistenceError.Message);
        }
    }

    /// <summary>
    /// Called after a step result is accepted. Updates progress and fires a progress event.
    /// <paramref name="groupState"/> tells us whether the plan is now complete or still has
    /// eligible steps.
    /// </summary>
    private bool TryPublishPlanStepAccepted(
        string groupId,
        DecomposeStepResult acceptedResult,
        out DecomposeGroupExecutionState groupState,
        out string? error)
    {
        groupState = DecomposeGroupExecutionState.Missing;
        error = null;
        if (_currentWorkspace is null)
        {
            error = "No workspace is active.";
            return false;
        }
        if (_planStore is null)
        {
            error = "The plan store is unavailable.";
            return false;
        }
        try
        {
            var existing = _planStore.Load(groupId);
            if (existing is null)
            {
                error = $"Durable plan {groupId} could not be loaded.";
                return false;
            }

            var proofTask = PendingDecomposePlanAdapter.FromPlan(existing).Group.Tasks.FirstOrDefault(task =>
                string.Equals(task.Id, acceptedResult.TaskId, StringComparison.Ordinal));
            var proofError = PlanStepProofPolicy.Validate(proofTask, acceptedResult);
            if (proofError is not null)
            {
                error = proofError;
                return false;
            }

            var accepted = PlanStoreUpdater.ApplyStepAccepted(
                existing,
                nextExecutingTaskId: null,
                acceptedResult);
            if (_CodeHealthGroupRunner is null)
            {
                error = "The canonical plan scheduler is unavailable.";
                return false;
            }
            groupState = _CodeHealthGroupRunner.TrackFirstEligibleStep(
                accepted,
                UnionBlockedTaskIds(accepted));
            if (groupState is not (DecomposeGroupExecutionState.Eligible or
                                   DecomposeGroupExecutionState.AwaitingApproval or
                                   DecomposeGroupExecutionState.Complete))
            {
                error = $"Plan {groupId} has no valid next execution state ({groupState}).";
                return false;
            }

            Plan updated;
            if (groupState == DecomposeGroupExecutionState.Complete)
            {
                updated = PlanValidationReadinessEvaluator.AllRequiredPassed(accepted) &&
                          ApprovalGateReadinessEvaluator.AllRequiredApproved(accepted)
                    ? PlanStoreUpdater.ApplyCompleted(accepted)
                    : accepted;
            }
            else
            {
                var nextId  = groupState == DecomposeGroupExecutionState.Eligible
                    ? _CodeHealthGroupRunner?.CurrentStepId
                    : null;
                updated = accepted with
                {
                    Progress = accepted.Progress with { ExecutingTaskId = nextId },
                };
            }

            if (!TryPublishPlanProgress(updated, out error))
                return false;
            RefreshPlanProjectionBestEffort(updated, "step-accepted");
            PromotePendingPlanRevisionAtBoundary(groupId);
            return true;
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.General, $"TryPublishPlanStepAccepted: {ex.Message}");
            error = ex.Message;
            return false;
        }
    }

    /// <summary>
    /// Called when a plan is blocked. Transitions the Plan to
    /// <see cref="PlanLifecycleStatus.Blocked"/> and fires a progress event.
    /// </summary>
    private void TryPublishPlanBlocked(string groupId, string taskId)
    {
        if (_currentWorkspace is null || _planStore is null) return;
        try
        {
            var existing = _planStore.Load(groupId);
            if (existing is null) return;
            var updated = PlanStoreUpdater.ApplyBlocked(existing, taskId);
            PublishPlanProgress(updated);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.General, $"TryPublishPlanBlocked: {ex.Message}");
        }
    }

    /// <summary>
    /// Transitions the plan to <see cref="PlanLifecycleStatus.Interrupted"/> and fires a
    /// progress event. Called when the plan loop stops unexpectedly mid-execution.
    /// </summary>
    private void TryPublishPlanInterrupted(
        string groupId,
        string taskId,
        string reason,
        PlanTaskCommitEvidence? taskCommitEvidence = null,
        PlanWorkCompletePendingAcceptance? workCompletePendingAcceptance = null,
        string attentionCategory = PlanAttentionCategory.UnexpectedState,
        string? attentionSummary = null)
    {
        if (_currentWorkspace is null || _planStore is null) return;
        try
        {
            var existing = _planStore.Load(groupId);
            if (existing is null) return;
            var updated = PlanStoreUpdater.ApplyInterrupted(
                existing,
                reason:            reason,
                loopIteration:     _loopCurrentIteration,
                interruptedTaskId: taskId,
                lastCommit:        _decomposeIterationBaselineCommit,
                taskCommitEvidence: taskCommitEvidence,
                workCompletePendingAcceptance: workCompletePendingAcceptance,
                attentionCategory: attentionCategory,
                attentionSummary: attentionSummary ?? reason);
            PublishPlanProgress(updated);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.General, $"TryPublishPlanInterrupted: {ex.Message}");
        }
    }

    /// <summary>
    /// Ends an interrupted plan by transitioning it to <see cref="PlanLifecycleStatus.Stopped"/>.
    /// Preserves history; suppresses further recovery reminders.
    /// </summary>
    private void EndInterruptedPlan(Plan plan)
    {
        if (_planStore is null) return;
        var current = _planStore.Load(plan.PlanId) ?? plan;
        if (HasActivePlanWork(current.PlanId))
        {
            ShowSystemTranscriptEntry(
                "This plan still owns active work. Wait for it to finish or recover before ending the plan; existing files and execution evidence remain preserved.");
            return;
        }
        if (!PlanRecoveryControlPolicy.HasActionableInterruption(current))
            return;

        var confirmation = MessageBox.Show(
            "End this incomplete plan? Its history and repository work will be preserved, but the plan cannot be resumed.",
            "End Incomplete Plan",
            MessageBoxButton.OKCancel,
            MessageBoxImage.Warning);
        if (confirmation != MessageBoxResult.OK) return;

        var updated = PlanStoreUpdater.ApplyStopped(current);
        PublishPlanProgress(updated);
    }

    /// <summary>Extracts task items belonging to a specific decompose group from the parse result.</summary>
    private static IReadOnlyList<TaskItem> GetGroupTaskItems(TaskParseResult? parsed, string groupId)
    {
        if (parsed is null) return [];
        return parsed.OpenGroups
            .SelectMany(g => g.Items)
            .Concat(parsed.CompletedItems)
            .Where(i => string.Equals(i.DecomposeGroupId, groupId, StringComparison.Ordinal))
            .ToList();
    }

    private void SyncCodeHealthPanel()
    {
        if (CodeHealthPanelBorder is null) return;
        CodeHealthPanelBorder.Visibility = _codeHealthPanelVisible ? Visibility.Visible : Visibility.Collapsed;
        _dockingService?.OnPanelVisibilityChanged("maintenance", _codeHealthPanelVisible);
        NotifyToolPanelVisibilityChanged("maintenance", _codeHealthPanelVisible);
        UpdateMainGridSideMargins();
        if (!_codeHealthPanelVisible) return;

        var workspacePath = _currentWorkspace?.FolderPath;
        if (workspacePath is null) return;

        if (_codeHealthPanel is null)
        {
            _codeHealthPanel = new CodeHealthPanelController(
                listPanel:              CodeHealthTaskListPanel,
                statusLabel:            CodeHealthStatusLabel,
                enabledOnIdleHost:      CodeHealthEnabledOnIdleHost,
                getWorkspacePath:       () => _currentWorkspace?.FolderPath,
                toggleTaskEnabled:      (taskId, enabled) => OnMaintenanceTaskToggled(taskId, enabled),
                reloadPanel:            () => OnMaintenanceTaskToggled(string.Empty, false),
                openInMarkdownEditor:   path => MarkdownDocumentWindow.Show(
                    CanShowOwnedWindow() ? this : null,
                    "code-health.md",
                    path,
                    showSource: true,
                    BuildMarkdownCaptureContext()),
                openReportViewer:       path => MarkdownDocumentWindow.Show(
                    CanShowOwnedWindow() ? this : null,
                    "Maintenance Report",
                    path,
                    showSource: false,
                    BuildMarkdownCaptureContext(),
                    isReadOnly: true),
                showInboxPanel:         () => ShowInboxPanel(),
                runTask:                taskId => StartCodeHealthCycleAsync(isManual: true, forceTaskIds: new System.Collections.Generic.HashSet<string> { taskId })
                                            .ContinueWith(t => HandleUiCallbackException(nameof(SyncCodeHealthPanel), t.Exception!), TaskContinuationOptions.OnlyOnFaulted),
                simulateIdle:           () => StartCodeHealthCycleAsync()
                                            .ContinueWith(t => HandleUiCallbackException(nameof(SyncCodeHealthPanel), t.Exception!), TaskContinuationOptions.OnlyOnFaulted),
                onReviseWithAi:         (rtb, path) => ShowDocRevisePopup(rtb, path),
                onDirectRevise:         (rtb, path, instructions) => DirectReviseRichTextBox(rtb, path, instructions));
            _codeHealthPanel.ClearFilterAction = () => { if (CodeHealthFilterBox is not null) CodeHealthFilterBox.Text = string.Empty; };

            // Wire dynamic max-width hint so splitter snap targets content width
            if (CodeHealthPanelBorder is { } mpb)
                mpb.MaximumUsefulSizeProvider = orientation => orientation switch
                {
                    DockResizeOrientation.Horizontal => _codeHealthPanel.GetMaximumUsefulWidth(),
                    DockResizeOrientation.Vertical   => _codeHealthPanel.GetMaximumUsefulHeight(),
                    _                                => null
                };
        }

        var config = CodeHealthMdParser.ParseWithAllSources(workspacePath);

        // Ensure the state store is loaded even when no health cycle has run this session.
        if (_CodeHealthStateStore is null)
        {
            _CodeHealthStateStore = new CodeHealthStateStore(Path.Combine(workspacePath, ".squad"));
            _CodeHealthStateStore.Reload();
        }

        _codeHealthPanel.Refresh(config, _CodeHealthStateStore);
    }

    private void PersistCodeHealthPanelVisible()
    {
        var state = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
        _docsPanelState = state with { CodeHealthPanelVisible = _codeHealthPanelVisible };
        _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
    }

    private void ShowInboxPanel()
    {
        EnsureInboxPanelCreated();
        _inboxPanel!.Show(flash: true);
        if (_pendingApprovalCalloutMessageId is not null)
            _ = ShowPendingApprovalInboxRowCalloutAsync();
        else if (_pendingPlanInboxCalloutMessageId is not null)
            _ = ShowPendingPlanInboxRowCalloutAsync();
    }

    /// <summary>Returns the workspace tint accent color used for active-panel chrome
    /// (the <c>ActivePanelBorder</c> resource), which rotates with the user's chosen
    /// hue stop. Falls back to CornflowerBlue if the resource is unavailable.</summary>
    private System.Windows.Media.Color GetActiveAgentAccentColor()
    {
        if (Application.Current.Resources["ActivePanelBorder"] is SolidColorBrush brush)
            return brush.Color;
        return System.Windows.Media.Colors.CornflowerBlue;
    }

    /// <summary>
    /// Lazily creates <see cref="_inboxPanel"/> (and its <see cref="_inboxStore"/>) if it has
    /// not been created yet. Wires all state-management delegates so the controller owns
    /// panel visibility, filter persistence, and intellisense coordination.
    /// Idempotent — safe to call multiple times.
    /// </summary>
    private void EnsureInboxPanelCreated()
    {
        if (_inboxPanel is not null) return;

        var workspacePath = _currentWorkspace?.FolderPath;
        _inboxStore ??= workspacePath is not null
            ? new InboxStore(System.IO.Path.Combine(workspacePath, ".squad"))
            : new InboxStore(string.Empty);

        _inboxPanel = new InboxPanelController(
            listPanel:              InboxListPanel!,
            listScrollContainer:    (FrameworkElement)InboxListPanel!.Parent,
            viewerBorder:           InboxViewerBorder!,
            viewerSubjectLabel:     InboxViewerSubjectLabel!,
            viewerMetaLabel:        InboxViewerMetaLabel!,
            viewerAttachmentsPanel: InboxViewerAttachmentsPanel!,
            viewerBody:             InboxViewerBody!,
            markRead:               id => _inboxStore?.MarkRead(id),
            markUnread:             id => _inboxStore?.MarkUnread(id),
            archive:                id => _inboxStore?.Archive(id),
            delete:                 id => _inboxStore?.Delete(id),
            viewerActionsPanel:     InboxViewerActionsPanel!,
            onActionClicked:        DispatchInboxAction,
            openMessageWindow:      (msg, onMarkedRead) => OpenOrFocusInboxMessage(msg.Id, onMarkedRead),
            lookupTask:             LookupTaskById,
            addToChat:              msg => AttachInboxMessageFollowUp(msg),
            addToNewChat:           msg => { AddEmptyQueueSlot(); AttachInboxMessageFollowUp(msg); },
            openDecomposePlan:      OpenDecomposePlanAttachment,
            addAsNote:              msg => AddNoteFromTextWithTitle(msg.Subject, msg.Body ?? string.Empty),
            syncBorderVisibility:   visible => {
                                        if (InboxPanelBorder is null) return;
                                        InboxPanelBorder.Visibility = visible ? Visibility.Visible : Visibility.Collapsed;
                                        _dockingService?.OnPanelVisibilityChanged("inbox", visible);
                                        NotifyToolPanelVisibilityChanged("inbox", visible);
                                        UpdateMainGridSideMargins();
                                    },
            flashPanel:             () => {
                                        if (InboxPanelBorder is null) return;
                                        var accentColor = GetActiveAgentAccentColor();
                                        _ = Dispatcher.BeginInvoke(DispatcherPriority.Loaded,
                                            () => FlashGlowHighlight(InboxPanelBorder, accentColor));
                                    },
            setMenuChecked:         isChecked => { if (ViewInboxMenuItem is not null) ViewInboxMenuItem.IsChecked = isChecked; },
            persistVisibility:      () => {
                                        var s = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
                                        _docsPanelState = s with { InboxPanelVisible = _inboxPanel?.PanelVisible ?? false };
                                        _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
                                    },
            onFilterPersisted:      text => {
                                        _docsPanelState = (_docsPanelState ?? new WorkspaceDocsPanelState()) with { InboxFilterText = text.Length > 0 ? text : string.Empty };
                                        _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
                                    },
            onUnreadOnlyPersisted:  v => {
                                        _docsPanelState = (_docsPanelState ?? new WorkspaceDocsPanelState()) with { InboxShowUnreadOnly = v };
                                        _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
                                    },
            onFilterChangedForIntelliSense: () => TryUpdateInboxIntelliSense(),
            agentSuggestions:       _agentDisplayNames,
            resolveMessageFilePath: id => _inboxStore?.GetMessageFilePath(id));

        _inboxPanel.ClearFilterAction = () => { if (InboxFilterBox is not null) InboxFilterBox.Text = string.Empty; };

        // Wire dynamic max-width hint so splitter snap targets content width.
        if (InboxPanelBorder is { } ipb)
            ipb.MaximumUsefulSizeProvider = orientation => orientation switch
            {
                DockResizeOrientation.Horizontal => _inboxPanel.GetMaximumUsefulWidth(),
                DockResizeOrientation.Vertical   => _inboxPanel.GetMaximumUsefulHeight(),
                _                                => null
            };

        var messages = _inboxStore?.LoadAll() ?? [];
        _inboxPanel.Refresh(messages);
        ReconcileOpenInboxWindows(messages);

        var inboxWorkspaceState = _docsPanelState ?? _settingsStore.GetDocsPanelState(_currentWorkspace?.FolderPath);
        if (inboxWorkspaceState.InboxShowUnreadOnly == true)
        {
            InboxUnreadOnlyCheckBox.IsChecked = true;
            _inboxPanel.SetUnreadOnly(true);
        }
        if (inboxWorkspaceState.InboxFilterText is { Length: > 0 } savedFilter)
        {
            if (InboxFilterBox is not null) InboxFilterBox.Text = savedFilter;
        }
    }

    private TaskItem? LookupTaskById(string taskId)
    {
        var path = _currentWorkspace is null
            ? null
            : Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");
        if (path is null || !File.Exists(path)) return null;
        var lines  = File.ReadAllLines(path);
        var result = TasksPanelParser.Parse(lines);
        var allItems = result.OpenGroups.SelectMany(g => g.Items)
            .Concat(result.CompletedItems);
        return allItems.FirstOrDefault(t =>
            t.Text.Contains(taskId, StringComparison.OrdinalIgnoreCase));
    }

    private async Task<bool> DispatchInboxAction(InboxAction action, InboxMessage message)
    {
        try
        {
            if (string.Equals(
                    action.RouteMode,
                    DurableApprovalRequestManager.ApprovalReviewRouteMode,
                    StringComparison.OrdinalIgnoreCase))
            {
                if (!ApprovalInboxActionPayload.TryParse(action.Prompt, out var payload) || payload is null)
                    throw new InvalidOperationException("This approval action is malformed and cannot be applied.");
                await ShowCurrentApprovalCardFromInboxAsync(payload, message);
                return true;
            }

            if (string.Equals(
                    action.RouteMode,
                    DurableApprovalRequestManager.ApprovalRouteMode,
                    StringComparison.OrdinalIgnoreCase))
            {
                if (!ApprovalInboxActionPayload.TryParse(action.Prompt, out var payload) || payload is null)
                    throw new InvalidOperationException("This approval action is malformed and cannot be applied.");
                await HandleApprovalClickAsync(payload.ToClickToken());
                return true;
            }

            if (string.Equals(action.RouteMode, DecomposePlanInbox.RecoveryRouteMode, StringComparison.OrdinalIgnoreCase))
            {
                if (!TryPrepareRecoveryInboxMessageForUse(message.Id, out var preparedMessage) || preparedMessage is null)
                {
                    ShowSystemTranscriptEntry(
                        "This plan recovery request has already been resolved. Open the plan to see its current state.");
                    return false;
                }
                message = preparedMessage;
                var actionKey = message.Id + "\u001f" + action.Label;
                if (!_decomposeInboxActionsInProgress.Add(actionKey))
                    return false;
                var recoveryWindows = _openInboxWindows
                    .Where(window => string.Equals(window.MessageId, message.Id, StringComparison.Ordinal))
                    .ToArray();
                foreach (var window in recoveryWindows)
                    window.SetDecisionActionsEnabled(false);
                try
                {
                    var applied = await TryApplyDecomposeRecoveryFromResponseAsync(action.Prompt);
                    if (applied)
                        _inboxStore?.MarkActionUsed(message.Id, action.Label);
                    return applied;
                }
                finally
                {
                    _decomposeInboxActionsInProgress.Remove(actionKey);
                    foreach (var window in recoveryWindows)
                        window.SetDecisionActionsEnabled(true);
                }
            }

            if (string.Equals(
                    action.RouteMode,
                    DecomposePlanInbox.RecoveryEvidenceRouteMode,
                    StringComparison.OrdinalIgnoreCase))
            {
                if (!DecomposeRecoveryDecisionParser.TryParse(action.Prompt, out var evidenceDecision) ||
                    evidenceDecision is null)
                    throw new InvalidOperationException("This completed-work review link is malformed.");
                await OpenInterruptedTaskReviewAsync(evidenceDecision.GroupId, evidenceDecision.Revision);
                return true;
            }

            if (string.Equals(action.RouteMode, DecomposePlanInbox.ActionRouteMode, StringComparison.OrdinalIgnoreCase))
            {
                var actionKey = message.Id + "\u001f" + action.Label;
                if (!_decomposeInboxActionsInProgress.Add(actionKey))
                    return false;
                try
                {
                    if (!DecomposeDecisionParser.TryParse(action.Prompt, out var decision) || decision is null)
                        throw new InvalidOperationException("This Inbox plan action is malformed and cannot be applied.");
                    if (_isPromptRunning &&
                        !DecomposePlanActionDispatchPolicy.CanApplyWhilePromptRunning(decision.Action))
                    {
                        ShowSystemTranscriptEntry(
                            "Wait for the current prompt to finish before applying the task plan.");
                        return false;
                    }
                    if (_currentWorkspace is null)
                        return false;
                    var plan = new PendingDecomposePlanStore(_currentWorkspace.SquadFolderPath).Load(decision.GroupId);
                    if (plan is null || !string.Equals(plan.Revision, decision.Revision, StringComparison.Ordinal))
                        throw new InvalidOperationException("This task-plan action is stale because the pending plan changed or was already handled.");
                    await ApplyDecomposeDecisionAsync(plan, decision.Action, decision.Branch);
                }
                finally
                {
                    _decomposeInboxActionsInProgress.Remove(actionKey);
                }
                return true;
            }

            if (string.Equals(action.RouteMode, InboxAction.HostCommandRouteMode, StringComparison.OrdinalIgnoreCase))
            {
                return ExecuteInboxHostCommand(action, message);
            }

            _inboxStore?.MarkActionUsed(message.Id, action.Label);

            if (action.RouteMode == "done" || string.IsNullOrWhiteSpace(action.Prompt))
                return true;

            if (action.RouteMode == "draft")
            {
                HandleDraftQuickReply(action.Prompt, entry: null);
                this.Activate();
                return true;
            }

            var filePath    = _inboxStore?.GetMessageFilePath(message.Id);
            var commitCount = await TryGetCommitCountSinceAsync(message.GitSha);

            if (action.RouteMode == "start_named_agent" && !string.IsNullOrWhiteSpace(action.TargetAgent))
            {
                if (!_isPromptRunning && !IsNativeLoopRunning && !IsQueueDispatchHeld && !HasPendingDirectQuickReplyAgentFollowUp())
                {
                    var targetAgent = action.TargetAgent.Trim().TrimStart('@');
                    var selectedOption = string.IsNullOrWhiteSpace(action.Label)
                        ? action.Prompt
                        : action.Label.Trim();
                    SquadDashTrace.Write(
                        TraceCategory.Inbox,
                        $"DispatchInboxAction: direct named-agent launch target={targetAgent} label='{selectedOption}' msgId={message.Id}");
                    
                    // Track this as an inbox-launched agent so we can add response to Coordinator transcript
                    _inboxLaunchedAgentHandles.Add(targetAgent);
                    
                    ResetQueuePausedState();
                    await _pec.ExecuteNamedAgentDirectAsync(
                        targetAgent,
                        selectedOption,
                        BuildInboxActionHandoffContext(action, message, filePath, commitCount),
                        addToHistory: true,
                        clearPromptBox: false);
                    return true;
                }

                var context = BuildInboxActionHandoffContext(action, message, filePath, commitCount);
                var deferredPrompt = $"[Deferred inbox action — route to @{action.TargetAgent}]\n\n{context}";
                var item = EnqueuePrompt(deferredPrompt, isSystemInjected: true, forceAtTail: true);
                if (item is not null)
                    AttachInboxMessageFollowUp(message, item.Id);
                return item is not null;
            }

            var coordContext = BuildInboxActionHandoffContext(action, message, filePath, commitCount);
            var coordItem = EnqueuePrompt(coordContext, isSystemInjected: true, forceAtTail: true);
            if (coordItem is not null)
                AttachInboxMessageFollowUp(message, coordItem.Id);
            return coordItem is not null;
        }
        catch (PlanPreflightBlockedException ex)
        {
            ShowInboxPlanPreflightRecovery(message, action, ex);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(DispatchInboxAction), ex);
        }
        return false;
    }

    private bool ExecuteInboxHostCommand(InboxAction action, InboxMessage message)
    {
        if (_hostCommandExecutor is null)
        {
            ShowSystemTranscriptEntry("This Inbox action cannot run because host commands are not initialized.");
            return false;
        }

        if (!_hostCommandRegistry.TryResolveInboxAction(
                action.HostCommand,
                _currentWorkspace?.FolderPath,
                out var invocation,
                out var descriptor,
                out var error) ||
            invocation is null || descriptor is null)
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"Inbox host command rejected label='{action.Label}' reason={error ?? "unknown"}");
            ShowSystemTranscriptEntry($"Inbox action failed: {error ?? "The host command is invalid."}");
            return false;
        }

        var execution = _hostCommandExecutor.Execute(
            [invocation], _hostCommandRegistry, _currentWorkspace?.FolderPath).SingleOrDefault();
        if (execution.Result?.Success != true)
        {
            var failure = execution.Result?.ErrorMessage ?? "The host command did not complete.";
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"Inbox host command failed command={descriptor.Name} label='{action.Label}' reason={failure}");
            ShowSystemTranscriptEntry($"Inbox action failed: {failure}");
            return false;
        }

        _inboxStore?.MarkActionUsed(message.Id, action.Label);
        SquadDashTrace.Write(TraceCategory.Inbox,
            $"Inbox host command completed command={descriptor.Name} label='{action.Label}' msgId={message.Id}");
        ShowSystemTranscriptEntry($"Completed Inbox action “{action.Label}”.");
        return true;
    }

    private async Task ShowCurrentApprovalCardFromInboxAsync(
        ApprovalInboxActionPayload payload,
        InboxMessage sourceMessage)
    {
        if (_planStore is null || _planApprovalRuntime is null)
            return;
        if (!string.Equals(
                sourceMessage.Id,
                DurableApprovalRequestManager.BuildMessageId(payload.PlanId),
                StringComparison.Ordinal))
            throw new InvalidOperationException("This approval action does not belong to the selected Inbox message.");

        await RefreshApprovalInboxMessageForUseAsync(sourceMessage.Id);
        var plan = _planStore.Load(payload.PlanId);
        var currentToken = _planApprovalRuntime.Actions.GetCurrentToken(payload.PlanId);
        var currentGate = plan?.ApprovalGates.FirstOrDefault(gate =>
            gate.Status == PlanGateStatus.AwaitingApproval);
        if (plan is null || currentToken is null || currentGate is null)
        {
            ReportPlanActionIssue(
                payload.PlanId,
                "Approval review",
                "This approval is no longer waiting for review. Open the plan to see its current state.");
            return;
        }
        if (HasPendingPlanRevision(plan.PlanId))
        {
            ReportPlanActionIssue(
                plan.PlanId,
                "Approval review",
                "Resolve the pending plan revision proposal before reviewing this approval checkpoint.");
            return;
        }

        ShowGateApprovalReviewWindow(
            plan,
            currentGate,
            BuildLightweightApprovalSnapshot(plan, currentGate),
            currentToken);
    }

    /// <summary>
    /// Atomically turns an actively executing durable plan into a recoverable interruption.
    /// Terminal, blocked, approval-paused, or already-interrupted plans are left untouched so
    /// late loop callbacks cannot overwrite a more specific outcome.
    /// </summary>
    private PlanInterruptionPersistenceResult TryInterruptExecutingPlan(
        string groupId,
        string? taskId,
        string reason,
        int loopIteration,
        bool preferDurableTaskId)
    {
        if (_planStore is null)
            return PlanInterruptionPersistenceResult.Failed("The plan store is unavailable.");
        try
        {
            var existing = _planStore.Load(groupId);
            return PlanInterruptionPersistence.Apply(
                existing,
                groupId,
                taskId,
                reason,
                loopIteration,
                _decomposeIterationBaselineCommit,
                preferDurableTaskId,
                interrupted =>
                {
                    var succeeded = TryPublishPlanProgress(interrupted, out var error);
                    return (succeeded, error);
                });
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "Loop",
                $"Could not persist interrupted plan {groupId}: {ex.Message}");
            return PlanInterruptionPersistenceResult.Failed(ex.Message);
        }
    }


    private void ShowInboxPlanPreflightRecovery(
        InboxMessage message,
        InboxAction action,
        PlanPreflightBlockedException exception)
    {
        var window = _openInboxWindows.FirstOrDefault(candidate => candidate.MessageId == message.Id);
        if (window is null)
        {
            OpenOrFocusInboxMessage(message.Id);
            window = _openInboxWindows.FirstOrDefault(candidate => candidate.MessageId == message.Id);
        }
        if (window is null)
        {
            HandleUiCallbackException(nameof(DispatchInboxAction), exception);
            return;
        }

        window.ShowPlanPreflightRecovery(
            exception,
            retry: async () =>
            {
                if (exception.RequiresRepositoryInitialization &&
                    !await InitializeRepositoryForPlanAsync())
                    return false;
                return await DispatchInboxAction(action, message);
            },
            viewChanges: () => _ = ShowPlanPreflightChangesAsync(exception),
            isWorkspaceClean: exception.RequiresRepositoryInitialization
                ? null
                : () => IsPlanPreflightWorkspaceCleanAsync(),
            getDirtyPaths: exception.RequiresRepositoryInitialization
                ? null
                : () => GetPlanPreflightDirtyPathsAsync());
        if (window.WindowState == WindowState.Minimized)
            window.WindowState = WindowState.Normal;
        window.Activate();
    }

    private async Task<bool> IsPlanPreflightWorkspaceCleanAsync(string? planId = null)
    {
        var dirtyPaths = await GetPlanPreflightDirtyPathsAsync(planId);
        return dirtyPaths is { Count: 0 };
    }

    /// <summary>
    /// Returns the current non-host-owned dirty paths for live preflight presentation. Null
    /// means the repository could not be inspected; callers retain their last known snapshot.
    /// </summary>
    private async Task<IReadOnlyList<string>?> GetPlanPreflightDirtyPathsAsync(string? planId = null)
    {
        if (_currentWorkspace is null) return null;
        try
        {
            var status = await RunGitAsync(
                _currentWorkspace.FolderPath,
                "status --porcelain --untracked-files=all");
            var allowedPlanPaths = await GetAllowedPlanPathsAsync(
                _currentWorkspace.FolderPath,
                planId);
            if (DecomposeWorktreePolicy.HasOnlyAllowedChanges(
                    status,
                    allowedPlanPaths,
                    out var candidates))
                return [];
            return await DecomposeWorktreePolicy.FilterMetadataOnlyAsync(
                candidates,
                cmd => RunGitAsync(_currentWorkspace.FolderPath, cmd));
        }
        catch { return null; }
    }

    private async Task ShowPlanPreflightChangesAsync(PlanPreflightBlockedException exception)
    {
        if (_currentWorkspace is null) return;
        try
        {
            var workspace = _currentWorkspace.FolderPath;
            var status = await RunGitAsync(workspace, "status --short --untracked-files=all");
            var diff = await RunGitAsync(workspace, "diff --no-ext-diff --no-color");
            var window = new PlanPreflightChangesWindow(
                exception, status, diff, _transcriptFontSize)
            {
                Owner = CanShowOwnedWindow() ? this : null,
            };
            window.Show();
        }
        catch (Exception ex)
        {
            HandleUiCallbackException("View plan preflight changes", ex);
        }
    }

    private static string BuildInboxActionHandoffContext(InboxAction action, InboxMessage message, string? messageFilePath = null, int commitCount = 0)
    {
        var builder = new StringBuilder();
        builder.AppendLine("SquadDash deferred inbox action context.");
        builder.AppendLine();
        builder.AppendLine($"Inbox subject: {message.Subject}");
        builder.AppendLine($"Inbox from: {message.From}");
        builder.AppendLine($"Inbox timestamp: {message.Timestamp:u}");
        if (!string.IsNullOrWhiteSpace(messageFilePath))
            builder.AppendLine($"Inbox message file: {messageFilePath}");
        builder.AppendLine($"Clicked action: {action.Label}");
        if (!string.IsNullOrWhiteSpace(action.TargetAgent))
            builder.AppendLine($"Target handle: @{action.TargetAgent.Trim().TrimStart('@')}");

        if (commitCount > 0)
        {
            builder.AppendLine();
            var urgency = commitCount switch
            {
                1        => "1 commit",
                <= 5     => $"a few commits ({commitCount})",
                <= 20    => $"several commits ({commitCount})",
                _        => $"many commits ({commitCount})",
            };
            builder.AppendLine(
                $"> ⚠️ Note: This action was dispatched from an inbox message sent {urgency} ago " +
                $"({message.Timestamp:yyyy-MM-dd}). File paths, line numbers, or conditions it " +
                $"references may have changed.");
        }

        builder.AppendLine();
        builder.AppendLine("Action prompt:");
        builder.AppendLine(action.Prompt?.Trim() ?? string.Empty);

        if (!string.IsNullOrWhiteSpace(message.Body))
        {
            builder.AppendLine();
            builder.AppendLine("Inbox message body:");
            builder.AppendLine(message.Body.Trim());
        }

        var attachments = message.Attachments
            .Where(attachment =>
                !string.IsNullOrWhiteSpace(attachment.Label) ||
                !string.IsNullOrWhiteSpace(attachment.Path) ||
                !string.IsNullOrWhiteSpace(attachment.Href) ||
                !string.IsNullOrWhiteSpace(attachment.TaskId) ||
                !string.IsNullOrWhiteSpace(attachment.Content))
            .ToArray();
        if (attachments.Length > 0)
        {
            builder.AppendLine();
            builder.AppendLine("Inbox attachments:");
            foreach (var attachment in attachments)
            {
                var detail = attachment.Path ?? attachment.Href ?? attachment.TaskId ?? attachment.Content;
                builder.Append("- ");
                builder.Append(string.IsNullOrWhiteSpace(attachment.Type) ? "attachment" : attachment.Type.Trim());
                if (!string.IsNullOrWhiteSpace(attachment.Label))
                    builder.Append(": ").Append(attachment.Label.Trim());
                if (!string.IsNullOrWhiteSpace(detail))
                    builder.Append(" (").Append(detail.Trim()).Append(')');
                builder.AppendLine();
            }
        }

        builder.AppendLine();
        builder.AppendLine("The action prompt is the authoritative task brief. Use the inbox body and attachments only to resolve context.");
        return builder.ToString().TrimEnd();
    }

    private (bool HasInboxDelivery, string? Error) ValidateDeliveredPlanInboxOpenPaths(string? rawResponse)
    {
        if (string.IsNullOrWhiteSpace(rawResponse) || _currentWorkspace is null)
            return (false, null);

        var workspaceRoot = GetActiveArtifactWorkspaceRoot();
        var errors = new List<string>();
        var hasInboxDelivery = false;

        foreach (var extraction in InboxMessageFileReferenceParser.ExtractAll(rawResponse, out _))
        {
            hasInboxDelivery = true;
            if (!AgentArtifactStore.TryMaterialize(
                    workspaceRoot,
                    extraction.Reference,
                    AgentArtifactStore.DefaultMaxInboxBytes,
                    archive: false,
                    out var artifact,
                    out var artifactError) ||
                artifact is null)
            {
                errors.Add("The delivered INBOX_MESSAGE_JSON_FILE could not be validated: " + artifactError);
                continue;
            }

            if (!InboxMessageParser.TryParseJsonObject(artifact.Content, out var fileDto) || fileDto is null)
            {
                errors.Add("The delivered INBOX_MESSAGE_JSON_FILE did not contain a parseable Inbox message.");
                continue;
            }

            ValidateInboxBody(fileDto.Body, errors, workspaceRoot);
        }

        if (InboxMessageParser.TryExtract(rawResponse, out var inlineExtraction) &&
            inlineExtraction?.Message is { } inlineDto)
        {
            hasInboxDelivery = true;
            ValidateInboxBody(inlineDto.Body, errors, workspaceRoot);
        }

        return (hasInboxDelivery, DecomposeStepResultContractDiagnostics.Combine(errors));
    }

    private void ValidateInboxBody(string body, List<string> errors, string workspaceRoot)
    {
        if (InboxOpenPathValidator.Validate(body, workspaceRoot) is { } linkError)
            errors.Add(linkError);

        var execution = _conversationManager.ConversationState.ActiveLoopExecution;
        if (execution?.DecomposeGroupId is not { } planId ||
            execution.RecoveryTaskId is not { } taskId ||
            _planStore?.Load(planId) is not { } plan)
            return;

        if (ManualTestKitApprovalBinding.ValidateSourceBody(plan, taskId, body) is { } kitError)
        {
            errors.Add(kitError);
            SquadDashTrace.Write(TraceCategory.Inbox, "APPROVAL_SETUP_ERROR: " + kitError);
        }
    }

    private bool ShouldValidatePlanTaskInbox(string rawResponse) =>
        _conversationManager.ConversationState.ActiveLoopExecution?.IsExecutingPlan == true &&
        rawResponse.Contains(DecomposeStepResultParser.Marker, StringComparison.Ordinal);

    private bool TryValidatePlanTaskInboxBeforeSave(
        InboxMessageDto message,
        string rawResponse,
        out string? error)
    {
        error = null;
        if (!ShouldValidatePlanTaskInbox(rawResponse))
            return true;

        var errors = new List<string>();
        ValidateInboxBody(message.Body, errors, GetActiveArtifactWorkspaceRoot());
        error = DecomposeStepResultContractDiagnostics.Combine(errors);
        if (error is null)
            return true;

        SquadDashTrace.Write(
            TraceCategory.Inbox,
            "INBOX_SAVE: deferred invalid plan-task Inbox delivery for result repair — " + error);
        return false;
    }

    private InboxMessage BindPlanTaskManualTestKitIfApplicable(InboxMessage message)
    {
        message = ManualTestKitApprovalBinding.RemoveUntrustedBinding(message);
        var result = _capturedDecomposeStepResult;
        if (result is null || _planStore?.Load(result.GroupId) is not { } plan ||
            !string.Equals(plan.Revision, result.Revision, StringComparison.Ordinal))
            return _planStore is null
                ? message
                : ManualTestKitApprovalBinding.TryBindExistingMessage(message, _planStore.LoadAll());

        var bound = ManualTestKitApprovalBinding.BindForCompletedTask(message, plan, result.TaskId);
        if (!ReferenceEquals(bound, message))
        {
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                $"INBOX_SAVE: bound manual test kit to plan={plan.PlanId} task={result.TaskId}");
        }
        return bound;
    }

    private void ScheduleApprovalKitAbsorption(InboxMessage source)
    {
        var binding = ManualTestKitApprovalBinding.Read(source);
        if (binding is null || _planStore?.Load(binding.PlanId) is not { } plan ||
            _planApprovalRuntime is null || _inboxStore is null)
            return;

        _ = AbsorbApprovalKitAsync(source.Id, plan);
    }

    private async Task AbsorbApprovalKitAsync(string sourceMessageId, Plan plan)
    {
        try
        {
            await _planApprovalRuntime!.Requests.RefreshFromPlanAsync(plan);
            var approvalMessageId = DurableApprovalRequestManager.BuildMessageId(plan.PlanId);
            var approvalMessage = _inboxStore!.GetById(approvalMessageId);
            if (approvalMessage is null)
                return; // The gate is not active yet; retain the hidden source for later absorption.

            foreach (var candidate in _inboxStore.LoadAll(includeApprovalKitSources: true)
                         .Where(candidate => candidate.Id != approvalMessageId)
                         .Where(candidate => ManualTestKitApprovalBinding.LooksLikeSourceForPlan(candidate, plan))
                         .ToArray())
                _inboxStore.Archive(candidate.Id);

            _inboxPanel?.Refresh(_inboxStore.LoadAll());
            RefreshOpenApprovalInboxWindows(approvalMessageId, approvalMessage);
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                $"Approval kit absorbed into message={approvalMessageId}; retired source={sourceMessageId}");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                $"APPROVAL_SETUP_ERROR: kit absorption failed source={sourceMessageId}: {ex}");
        }
    }

    /// <summary>
    /// Saves any INBOX_MESSAGE_JSON block found in <paramref name="rawResponse"/> to the inbox store
    /// and refreshes the panel. No-ops if already saved for this turn, if no block is found, or if
    /// the inbox store is unavailable.
    /// </summary>
    private string? TrySaveInboxMessageFromResponse(
        string? rawResponse,
        bool planEnvelopeAccepted = false)
    {
        var isExecutingPlan =
            _conversationManager.ConversationState.ActiveLoopExecution?.IsExecutingPlan == true;
        if (PlanInboxLinkRepairPolicy.ShouldStageDelivery(
                isExecutingPlan,
                planEnvelopeAccepted,
                rawResponse))
        {
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                "INBOX_SAVE: staged plan Inbox delivery until its result envelope is accepted");
            return null;
        }

        if (_inboxSavedForCurrentTurn && !planEnvelopeAccepted)
            return null;
        var messageId = TrySaveInboxMessage(rawResponse);
        if (messageId is not null)
            _inboxSavedForCurrentTurn = true;
        return messageId;
    }

    private ActiveLoopExecutionState CommitAcceptedPlanInboxDelivery(
        ActiveLoopExecutionState execution)
    {
        var rawResponse = execution.PendingInboxDeliveryRawResponse;
        if (string.IsNullOrWhiteSpace(rawResponse))
            return execution;

        var messageId = TrySaveInboxMessageFromResponse(
            rawResponse,
            planEnvelopeAccepted: true);
        if (messageId is null && PlanInboxLinkRepairPolicy.HasDeliveryIntent(rawResponse))
        {
            messageId = SaveInboxDeliveryFailure(
                "The plan result was accepted, but its Inbox message could not be persisted.",
                rawResponse);
        }

        var updated = PlanInboxLinkRepairPolicy.ClearPendingDelivery(execution);
        _conversationManager.UpdateActiveLoopExecutionState(updated);
        SquadDashTrace.Write(
            TraceCategory.Inbox,
            $"INBOX_SAVE: committed accepted plan Inbox delivery message={messageId ?? "(failure not persisted)"}");
        return updated;
    }

    private ActiveLoopExecutionState FinalizeTerminalPlanInboxDelivery(
        ActiveLoopExecutionState execution,
        string? fallbackError)
    {
        var deliveryError = execution.PendingInboxLinkRepairError;
        var rawResponse = execution.PendingInboxDeliveryRawResponse;
        if (string.IsNullOrWhiteSpace(deliveryError) && string.IsNullOrWhiteSpace(rawResponse))
            return execution;

        if (!string.IsNullOrWhiteSpace(deliveryError))
        {
            SaveInboxDeliveryFailure(
                "SquadDash could not deliver a plan-generated Inbox message after automatic repair was exhausted.\n\n" +
                (deliveryError ?? fallbackError ?? "The Inbox delivery was invalid."),
                rawResponse ?? _capturedTaskVerificationRawResponse ?? string.Empty);
        }

        var updated = PlanInboxLinkRepairPolicy.ClearPendingDelivery(execution);
        _conversationManager.UpdateActiveLoopExecutionState(updated);
        return updated;
    }

    /// <summary>
    /// Parses and saves any INBOX_MESSAGE_JSON block found in <paramref name="rawResponse"/> to the
    /// inbox store, then refreshes the panel.
    /// </summary>
    /// <returns>The saved message ID, or null if no INBOX_MESSAGE_JSON was found/saved.</returns>
    private string? TrySaveInboxMessage(string? rawResponse)
    {
        if (string.IsNullOrWhiteSpace(rawResponse))
        {
            SquadDashTrace.Write(TraceCategory.Inbox, "INBOX_SAVE: skipped — rawResponse is null/empty");
            return null;
        }
        if (_inboxStore is null)
        {
            SquadDashTrace.Write(TraceCategory.Inbox, "INBOX_SAVE: skipped — _inboxStore is null");
            return null;
        }

        static string? DecodeFallbackJsonString(System.Text.RegularExpressions.Match match)
        {
            if (!match.Success)
                return null;

            var raw = match.Groups[1].Value;
            try
            {
                return System.Text.Json.JsonSerializer.Deserialize<string>($"\"{raw}\"");
            }
            catch (System.Text.Json.JsonException)
            {
                return raw.Replace("\\\"", "\"").Replace("\\\\", "\\");
            }
        }

        bool hasBlock = rawResponse.Contains("INBOX_MESSAGE_JSON", StringComparison.Ordinal);
        SquadDashTrace.Write(TraceCategory.Inbox,
            $"INBOX_SAVE: rawResponse len={rawResponse.Length} hasBlock={hasBlock}");

        // Strip known structured wrapper blocks before parsing. The inbox parser itself is
        // tolerant of visible prose after the JSON payload and reports that prose separately.
        var responseForParsing = ToolTranscriptFormatter.StripSystemNotifications(rawResponse);
        SquadDashTrace.Write(TraceCategory.Inbox,
            $"INBOX_SAVE: after StripSystemNotifications len={responseForParsing.Length} hasBlock={responseForParsing.Contains("INBOX_MESSAGE_JSON", StringComparison.Ordinal)}");

        if (QuickReplyOptionParser.TryExtract(responseForParsing, out var withoutQuickReplies, out _))
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: QuickReplyOptionParser stripped — before={responseForParsing.Length} after={withoutQuickReplies.Length} hasBlock={withoutQuickReplies.Contains("INBOX_MESSAGE_JSON", StringComparison.Ordinal)}");
            responseForParsing = withoutQuickReplies;
        }
        if (HostCommandParser.TryExtract(responseForParsing, out var withoutHostCommands, out _))
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: HostCommandParser stripped — before={responseForParsing.Length} after={withoutHostCommands.Length} hasBlock={withoutHostCommands.Contains("INBOX_MESSAGE_JSON", StringComparison.Ordinal)}");
            responseForParsing = withoutHostCommands;
        }

        var fileExtractions = InboxMessageFileReferenceParser.ExtractAll(responseForParsing, out _);
        if (fileExtractions.Count > 0)
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: processing {fileExtractions.Count} inbox file reference(s)");
            string? lastSavedMessageId = null;
            foreach (var fileExtraction in fileExtractions)
            {
                lastSavedMessageId =
                    TrySaveInboxMessageFromFileReference(fileExtraction, responseForParsing) ??
                    lastSavedMessageId;
            }
            return lastSavedMessageId;
        }

        if (!InboxMessageParser.TryExtract(responseForParsing, out var extraction) ||
            extraction is null ||
            extraction.Message is not { } dto)
        {
            // Log the tail of the text so we can see what the parser is seeing
            var tail = responseForParsing.Length > 500
                ? responseForParsing[^500..]
                : responseForParsing;
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: InboxMessageParser failed — finalLen={responseForParsing.Length} tail=«{tail}»");

            // If the sentinel plus an opening brace was present the AI intended to emit a block
            // but the JSON was malformed — surface the error so the user can diagnose it.
            // A plain prose mention of "INBOX_MESSAGE_JSON" (e.g. in backtick code spans or
            // AI narration) lacks the colon+brace sequence and must NOT trigger the error panel.
            const string sentinel = "INBOX_MESSAGE_JSON:";
            const string fileSentinel = AgentArtifactStore.InboxMessageFileMarker;
            int sentinelIdx = responseForParsing.LastIndexOf(sentinel, StringComparison.Ordinal);
            int fileSentinelIdx = responseForParsing.LastIndexOf(fileSentinel, StringComparison.Ordinal);
            bool hasActualBlock = sentinelIdx >= 0 &&
                responseForParsing.IndexOf('{', sentinelIdx + sentinel.Length) >= 0;
            bool hasActualFileBlock = fileSentinelIdx >= 0 &&
                responseForParsing.IndexOf('{', fileSentinelIdx + fileSentinel.Length) >= 0;
            if (hasActualBlock || hasActualFileBlock)
            {
                // Extract a short snippet of the JSON text following the marker for diagnostics.
                var activeSentinelIdx = hasActualFileBlock && fileSentinelIdx > sentinelIdx
                    ? fileSentinelIdx
                    : sentinelIdx;
                var activeSentinel = activeSentinelIdx == fileSentinelIdx
                    ? fileSentinel
                    : sentinel;
                int jsonSnippetStart = responseForParsing.IndexOf('{', activeSentinelIdx + activeSentinel.Length);
                var jsonSnippet = jsonSnippetStart >= 0 && responseForParsing.Length - jsonSnippetStart > 0
                    ? responseForParsing.Substring(jsonSnippetStart, Math.Min(200, responseForParsing.Length - jsonSnippetStart))
                    : "(no opening brace found)";

                var rawSample = responseForParsing.Length > 3000
                    ? "...(truncated)...\n" + responseForParsing[^3000..]
                    : responseForParsing;
                var parseExMessage =
                    $"{activeSentinel.TrimEnd(':')} was present in the response but could not be parsed as valid JSON.\n\n" +
                    $"Response length: {responseForParsing.Length} chars\n\n" +
                    $"--- JSON head (first 200 chars after marker) ---\n{jsonSnippet}";

                SquadDashTrace.Write(TraceCategory.Inbox,
                    $"INBOX_SAVE: hasActualBlock — attempting fallback parse. jsonSnippetStart={jsonSnippetStart}");

                // --- Fallback parse: recover subject/from; store a degraded inbox message ---
                // subject and from are typically simple one-line strings, so a line-safe Regex
                // extracts them even when body/attachments/actions are malformed.
                string recoveredSubject = "Inbox message (parse error)";
                string recoveredFrom    = "system";
                if (jsonSnippetStart >= 0)
                {
                    var rawJsonText = responseForParsing[jsonSnippetStart..];
                    var subjectMatch = System.Text.RegularExpressions.Regex.Match(
                        rawJsonText, @"""subject""\s*:\s*""((?:[^""\\\r\n]|\\.)*)""");
                    var fromMatch = System.Text.RegularExpressions.Regex.Match(
                        rawJsonText, @"""from""\s*:\s*""((?:[^""\\\r\n]|\\.)*)""");
                    var decodedSubject = DecodeFallbackJsonString(subjectMatch);
                    var decodedFrom = DecodeFallbackJsonString(fromMatch);
                    if (!string.IsNullOrWhiteSpace(decodedSubject))
                        recoveredSubject = decodedSubject.Trim();
                    if (!string.IsNullOrWhiteSpace(decodedFrom))
                        recoveredFrom = decodedFrom.Trim();
                }

                // Attempt a minimal JsonSerializer round-trip on just subject + from.
                InboxMessageDto? fallbackDto = null;
                try
                {
                    var minimalJsonOptions = new System.Text.Json.JsonSerializerOptions { PropertyNameCaseInsensitive = true };
                    var minimalJson = $"{{\"subject\":{System.Text.Json.JsonSerializer.Serialize(recoveredSubject)}," +
                                     $"\"from\":{System.Text.Json.JsonSerializer.Serialize(recoveredFrom)}}}";
                    fallbackDto = System.Text.Json.JsonSerializer.Deserialize<InboxMessageDto>(minimalJson, minimalJsonOptions);
                }
                catch (System.Text.Json.JsonException) { /* ignore — use recovered strings */ }

                var degradedMessage = new InboxMessage
                {
                    Id          = Guid.NewGuid().ToString("N"),
                    Subject     = fallbackDto?.Subject ?? recoveredSubject,
                    From        = fallbackDto?.From    ?? recoveredFrom,
                    Body        = "⚠️ This inbox message could not be fully parsed. The raw response is attached below.",
                    Timestamp   = DateTimeOffset.Now,
                    Attachments = [
                        new InboxAttachment { Type = "text", Label = "Parse error details", Content = parseExMessage },
                        new InboxAttachment { Type = "text", Label = "Raw response",        Content = rawSample },
                    ],
                    Actions = [],
                };

                _inboxStore.Save(degradedMessage);
                SquadDashTrace.Write(TraceCategory.Inbox,
                    $"INBOX_SAVE: saved degraded message id={degradedMessage.Id} subject=\"{degradedMessage.Subject}\"");

                if (_inboxPanel is not null)
                    _inboxPanel.Refresh(_inboxStore.LoadAll());

                AppendInboxReceivedEntry(degradedMessage.Subject, degradedMessage.Id);
                return degradedMessage.Id;
            }
            return null;
        }

        if (!string.IsNullOrWhiteSpace(extraction.TrailingText))
        {
            var trailingSnippet = extraction.TrailingText.Length > 500
                ? extraction.TrailingText[^500..]
                : extraction.TrailingText;
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: trailing visible text after INBOX_MESSAGE_JSON preserved — chars={extraction.TrailingText.Length} tail=«{trailingSnippet}»");
        }

        if (string.IsNullOrWhiteSpace(dto.Subject))
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: skipped — subject is empty (from={dto.From})");
            return null;
        }

        if (!TryValidatePlanTaskInboxBeforeSave(dto, responseForParsing, out _))
            return null;

        var message = BindPlanTaskManualTestKitIfApplicable(new InboxMessage
        {
            Id          = Guid.NewGuid().ToString("N"),
            Subject     = dto.Subject,
            From        = dto.From,
            Body        = dto.Body,
            Priority    = dto.Priority,
            Timestamp   = DateTimeOffset.Now,
            GitSha      = null,   // populated asynchronously after save (see below)
            Attachments = dto.Attachments,
            Actions     = dto.Actions,
        });

        if (_inboxStore.FindRecentSimilarMessage(message, TimeSpan.FromMinutes(5)) is { } existing)
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: skipped duplicate id={existing.Id} subject=\"{existing.Subject}\"");
            return existing.Id;
        }

        _inboxStore.Save(message);

        var isApprovalKitSource = ManualTestKitApprovalBinding.Read(message) is not null;
        if (isApprovalKitSource)
        {
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                $"INBOX_SAVE: staged manual-test-kit source id={message.Id}; the durable approval message will present its procedure");
            ScheduleApprovalKitAbsorption(message);
            return message.Id;
        }

        // Fetch the git SHA off the UI thread and patch the saved message once available.
        // Null is always acceptable — the SHA is informational only (inbox staleness display).
        var capturedStore = _inboxStore;
        var capturedRoot  = GetActiveArtifactWorkspaceRoot();
        var capturedMsg   = message;
        _ = TryGetGitShaAsync(capturedRoot).ContinueWith(t =>
        {
            if (t.IsCompletedSuccessfully && t.Result is string sha)
                capturedStore.Save(capturedMsg with { GitSha = sha });
        }, TaskScheduler.Default);

        SquadDashTrace.Write(TraceCategory.Inbox,
            $"INBOX_SAVE: saved id={message.Id} subject=\"{message.Subject}\" panelVisible={_inboxPanel is not null}");

        if (_inboxPanel is not null)
            _inboxPanel.Refresh(_inboxStore.LoadAll());

        AppendInboxReceivedEntry(message.Subject, message.Id);

        return message.Id;
    }

    private string? TrySaveInboxMessageFromFileReference(
        InboxMessageFileReferenceExtraction extraction,
        string responseForParsing)
    {
        if (_inboxStore is null)
            return null;

        if (!AgentArtifactStore.TryMaterialize(
                GetActiveArtifactWorkspaceRoot(),
                extraction.Reference,
                AgentArtifactStore.DefaultMaxInboxBytes,
                archive: true,
                out var artifact,
                out var artifactError) ||
            artifact is null)
        {
            return SaveInboxDeliveryFailure(
                $"INBOX_MESSAGE_JSON_FILE could not be loaded.\n\nPath: {extraction.Reference.Path}\nError: {artifactError}",
                responseForParsing);
        }

        if (!InboxMessageParser.TryParseJsonObject(artifact.Content, out var dto) || dto is null)
        {
            return SaveInboxDeliveryFailure(
                $"INBOX_MESSAGE_JSON_FILE was loaded but did not contain a parseable inbox JSON object.\n\n" +
                $"Source: {artifact.SourceRelativePath}\n" +
                $"Archive: {artifact.ArchivedRelativePath ?? "(not archived)"}\n" +
                $"SHA-256: {artifact.Sha256}",
                responseForParsing);
        }

        if (string.IsNullOrWhiteSpace(dto.Subject))
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: skipped file inbox — subject is empty (from={dto.From})");
            return null;
        }

        if (!TryValidatePlanTaskInboxBeforeSave(dto, responseForParsing, out _))
            return null;

        var attachments = dto.Attachments.ToList();
        attachments.Add(new InboxAttachment
        {
            Type = "text",
            Label = "Inbox source artifact",
            Content =
                $"Source: {artifact.SourceRelativePath}\n" +
                $"Archive: {artifact.ArchivedRelativePath ?? "(not archived)"}\n" +
                $"SHA-256: {artifact.Sha256}\n" +
                $"Bytes: {artifact.ByteLength}"
        });

        var message = BindPlanTaskManualTestKitIfApplicable(new InboxMessage
        {
            Id          = Guid.NewGuid().ToString("N"),
            Subject     = dto.Subject,
            From        = dto.From,
            Body        = dto.Body,
            Priority    = dto.Priority,
            Timestamp   = DateTimeOffset.Now,
            GitSha      = null,
            Attachments = attachments,
            Actions     = dto.Actions,
        });

        if (_inboxStore.FindRecentSimilarMessage(message, TimeSpan.FromMinutes(5)) is { } existing)
        {
            SquadDashTrace.Write(TraceCategory.Inbox,
                $"INBOX_SAVE: skipped duplicate file inbox id={existing.Id} subject=\"{existing.Subject}\"");
            return existing.Id;
        }

        _inboxStore.Save(message);

        var isApprovalKitSource = ManualTestKitApprovalBinding.Read(message) is not null;
        if (isApprovalKitSource)
        {
            SquadDashTrace.Write(
                TraceCategory.Inbox,
                $"INBOX_SAVE: staged manual-test-kit file source id={message.Id}; the durable approval message will present its procedure");
            ScheduleApprovalKitAbsorption(message);
            return message.Id;
        }

        var capturedStore = _inboxStore;
        var capturedRoot  = GetActiveArtifactWorkspaceRoot();
        var capturedMsg   = message;
        _ = TryGetGitShaAsync(capturedRoot).ContinueWith(t =>
        {
            if (t.IsCompletedSuccessfully && t.Result is string sha)
                capturedStore.Save(capturedMsg with { GitSha = sha });
        }, TaskScheduler.Default);

        SquadDashTrace.Write(TraceCategory.Inbox,
            $"INBOX_SAVE: saved file inbox id={message.Id} subject=\"{message.Subject}\" archive=\"{artifact.ArchivedRelativePath ?? "(none)"}\"");

        if (_inboxPanel is not null)
            _inboxPanel.Refresh(_inboxStore.LoadAll());

        AppendInboxReceivedEntry(message.Subject, message.Id);
        return message.Id;
    }

    private string SaveInboxDeliveryFailure(string details, string rawResponse)
    {
        var rawSample = rawResponse.Length > 3000
            ? "...(truncated)...\n" + rawResponse[^3000..]
            : rawResponse;

        var degradedMessage = new InboxMessage
        {
            Id          = Guid.NewGuid().ToString("N"),
            Subject     = "Inbox delivery failed",
            From        = "system",
            Body        = "SquadDash could not deliver an Inbox message. The details are attached below.",
            Timestamp   = DateTimeOffset.Now,
            Attachments = [
                new InboxAttachment { Type = "text", Label = "Delivery failure details", Content = details },
                new InboxAttachment { Type = "text", Label = "Raw response", Content = rawSample },
            ],
            Actions = [],
        };

        _inboxStore!.Save(degradedMessage);
        SquadDashTrace.Write(TraceCategory.Inbox,
            $"INBOX_SAVE: saved degraded file inbox id={degradedMessage.Id} subject=\"{degradedMessage.Subject}\"");

        if (_inboxPanel is not null)
            _inboxPanel.Refresh(_inboxStore.LoadAll());

        AppendInboxReceivedEntry(degradedMessage.Subject, degradedMessage.Id);
        return degradedMessage.Id;
    }

    /// <summary>
    /// Appends a "📬 Inbox message received: [subject]" paragraph to the Coordinator
    /// transcript. Clicking it opens the message in the inbox viewer.
    /// </summary>
    private void AppendInboxReceivedEntry(string? subject, string messageId)
    {
        var paragraph = CreateTranscriptParagraph();

        var prefix = new Run("📬 ");
        prefix.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        paragraph.Inlines.Add(prefix);

        var displaySubject = string.IsNullOrWhiteSpace(subject) ? "(no subject)" : subject;
        var link = new Run($"Inbox message received: {displaySubject}")
        {
            FontWeight      = FontWeights.Normal,
            TextDecorations = TextDecorations.Underline,
            Cursor          = Cursors.Hand,
        };
        link.SetResourceReference(TextElement.ForegroundProperty, "ActionLinkText");
        link.MouseLeftButtonDown += (_, e) =>
        {
            OpenOrFocusInboxMessage(messageId);
            e.Handled = true;
        };
        paragraph.Inlines.Add(link);

        CoordinatorThread.Document.Blocks.Add(paragraph);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private void DismissCodeHealthBadge()
    {
    }


    private void DismissCodeHealthBanner()
    {
        _codeHealthBannerTimer?.Stop();
        _codeHealthBannerTimer = null;
        _pendingCodeHealthBannerReport = null;
        if (CodeHealthBannerBorder is not null)
            CodeHealthBannerBorder.Visibility = Visibility.Collapsed;
        DismissCodeHealthBadge();
    }

    private void ShowCodeHealthBannerIfPending()
    {
        if (_pendingCodeHealthBannerReport is null) return;
        var report = _pendingCodeHealthBannerReport;

        int ran     = report.RanTaskIds?.Count  ?? 0;
        int skipped = report.SkippedTaskIds?.Count ?? 0;
        string summary = ran == 1
            ? $"Code Health complete — {ran} task ran, {skipped} skipped."
            : $"Code Health complete — {ran} tasks ran, {skipped} skipped.";

        if (CodeHealthBannerTextBlock is not null)
            CodeHealthBannerTextBlock.Text = summary;
        if (CodeHealthBannerBorder is not null)
            CodeHealthBannerBorder.Visibility = Visibility.Visible;

        _codeHealthBannerTimer?.Stop();
        _codeHealthBannerTimer = new DispatcherTimer { Interval = UiTimingConstants.CodeHealthBannerInterval };
        _codeHealthBannerTimer.Tick += (_, _) => DismissCodeHealthBanner();
        _codeHealthBannerTimer.Start();
    }

    private void OnMaintenanceTaskToggled(string taskId, bool enabled)
    {
        var workspacePath = _currentWorkspace?.FolderPath;
        if (workspacePath is null || _codeHealthPanel is null) return;
        var config = CodeHealthMdParser.ParseWithAllSources(workspacePath);
        _codeHealthPanel.Refresh(config, _CodeHealthStateStore);
    }

    private async Task StartCodeHealthCycleAsync(bool isManual = false, IReadOnlySet<string>? forceTaskIds = null)
    {
        var workspacePath = _currentWorkspace?.FolderPath;
        if (workspacePath is null) return;
        if (ShouldSuppressCodeHealthCycle())
        {
            if (isManual) _codeHealthPanel?.ShowTransientStatus("Cannot run — AI is busy. Try again when idle.");
            return;
        }

        var config = CodeHealthMdParser.ParseWithAllSources(workspacePath);
        if (config is null)
        {
            if (isManual) _codeHealthPanel?.ShowTransientStatus("No code-health.md found in this workspace.");
            return;
        }
        if (!CodeHealthRunPolicy.CanStart(config, isManual)) return;
        if (config.Tasks is not { Count: > 0 } tasks || !tasks.Any(task => task.Enabled))
        {
            if (isManual) _codeHealthPanel?.ShowTransientStatus("No enabled maintenance tasks to run.");
            return;
        }

        _CodeHealthStateStore ??= new CodeHealthStateStore(Path.Combine(workspacePath, ".squad"));
        _CodeHealthStateStore.Reload();
        _CodeHealthReportWriter = new CodeHealthReportWriter(workspacePath);

        if (_CodeHealthRunner?.IsRunning == true)
        {
            if (isManual) _codeHealthPanel?.ShowTransientStatus("Maintenance is already running.");
            return;
        }

        string? latestMaintenanceThreadId = null;
        var stubRecords = new System.Collections.Generic.List<CodeHealthStubRecord>();
        var enabledTasks = config.Tasks?.Where(t => t.Enabled).ToList() ?? [];

        _CodeHealthRunner = new CodeHealthRunner(
            executePromptAsync: (prompt, ct) =>
            {
                var tcs = new TaskCompletionSource<int>(TaskCreationOptions.RunContinuationsAsynchronously);
                Dispatcher.InvokeAsync(async () =>
                {
                    try
                    {
                        var anchorIndex = -1;
                        latestMaintenanceThreadId = null;
                        await _pec.ExecuteCodeHealthTurnAsync("argus-weld", prompt);
                        if (FindLatestArgusWeldRunThread() is { } argusThread)
                        {
                            latestMaintenanceThreadId = argusThread.ThreadId;
                            anchorIndex = argusThread.PromptParagraphs.Count - 1;
                            TrySaveInboxMessageFromResponse(
                                argusThread.CurrentTurn?.ResponseTextBuilder.ToString()
                                ?? argusThread.LatestResponse);
                        }
                        tcs.TrySetResult(anchorIndex);
                    }
                    catch (OperationCanceledException) { tcs.TrySetCanceled(ct); }
                    catch (Exception ex) { tcs.TrySetException(ex); }
                });
                return tcs.Task;
            },
            stateStore:      _CodeHealthStateStore,
            onTaskStarted:   title => Dispatcher.InvokeAsync(() => {
                EnsureArgusWeldRegistered(workspacePath);
                _codeHealthPanel?.OnRunnerStarted(title);
            }),
            onTaskCompleted: (id, title, anchorIndex, startedAt, duration) => Dispatcher.InvokeAsync(() => {
                _codeHealthPanel?.OnRunnerCompleted();
                AppendMaintenanceStub(title, latestMaintenanceThreadId, anchorIndex, startedAt, duration);
                stubRecords.Add(new CodeHealthStubRecord {
                    TaskTitle       = title,
                    ThreadId        = latestMaintenanceThreadId,
                    AnchorIndex     = anchorIndex,
                    StartedAt       = startedAt,
                    DurationSeconds = duration.TotalSeconds,
                });
            }),
            onCompleted:     report =>
            {
                Dispatcher.InvokeAsync(async () =>
                {
                    // Skip the report file when nothing actually ran (e.g. all tasks skipped).
                    // Empty reports add noise.
                    var hasActivity = report.TaskResults.Any(
                        t => t.Outcome != CodeHealthTaskOutcome.Skipped);
                    var reportPath = hasActivity
                        ? (_CodeHealthReportWriter?.WriteReport(report) ?? "")
                        : "";
                    if (!string.IsNullOrEmpty(reportPath) && stubRecords.Count > 0)
                    {
                        _CodeHealthReportWriter?.WriteStubSidecar(reportPath, stubRecords);
                        var sidecarPath = System.IO.Path.ChangeExtension(reportPath, ".json");
                        _renderedSidecarPaths.Add(sidecarPath);
                        var stubState = new CodeHealthStubStateStore(System.IO.Path.Combine(workspacePath, ".squad"));
                        stubState.LastRenderedSidecarPath = sidecarPath;
                        stubState.Save();
                    }
                    _pendingCodeHealthBannerReport = report;
                    _idleDetectionService?.SetRunnerActive(false);
                    _codeHealthPanel?.OnRunnerCompleted();
                    var updatedConfig = CodeHealthMdParser.ParseWithAllSources(workspacePath);
                    _codeHealthPanel?.Refresh(updatedConfig, _CodeHealthStateStore);
                    if (isManual && report.RanTaskIds.Count == 0 && report.SkippedTaskIds.Count > 0)
                    {
                        AppendManualRunSkippedFeedback(enabledTasks, workspacePath);
                    }
                    // Banner surfaces on next user activity (see Window_PreviewKeyDown).
                    var notifBody = !string.IsNullOrEmpty(report.Summary)
                        ? report.Summary
                        : $"{report.TaskResults.Count} task(s) completed";
                    await _pushNotificationService.NotifyEventAsync(
                        "maintenance_completed",
                        "Argus Weld — Maintenance Complete",
                        notifBody);
                });
            },
            wasInboxSavedSince: t => _inboxStore?.HasMessageSavedSince(t) ?? false,
            executePromptAndCaptureAsync: (prompt, ct) =>
            {
                var tcs = new TaskCompletionSource<(int, string)>(TaskCreationOptions.RunContinuationsAsynchronously);
                Dispatcher.InvokeAsync(async () =>
                {
                    try
                    {
                        var anchorIndex = -1;
                        var responseText = string.Empty;
                        latestMaintenanceThreadId = null;
                        await _pec.ExecuteCodeHealthTurnAsync("argus-weld", prompt);
                        if (FindLatestArgusWeldRunThread() is { } argusThread)
                        {
                            latestMaintenanceThreadId = argusThread.ThreadId;
                            anchorIndex = argusThread.PromptParagraphs.Count - 1;
                            responseText =
                                argusThread.CurrentTurn?.ResponseTextBuilder.ToString()
                                ?? argusThread.LatestResponse
                                ?? string.Empty;
                            TrySaveInboxMessageFromResponse(responseText);
                        }
                        tcs.TrySetResult((anchorIndex, responseText));
                    }
                    catch (OperationCanceledException) { tcs.TrySetCanceled(ct); }
                    catch (Exception ex) { tcs.TrySetException(ex); }
                });
                return tcs.Task;
            },
            onDecomposeGroupReady: group => Dispatcher.InvokeAsync(() =>
            {
                if (!_loopController.IsRunning)
                    _ = StartDecomposeLoopAsync(group.GroupId, group);
            }),
            getUncategorizedApprovals: () => {
                var items = _approvalItems
                    .Where(i => !i.IsApproved && !i.IsRejected && string.IsNullOrEmpty(i.FeatureGroup))
                    .ToList();
                if (items.Count == 0) return "(none)";
                var sb = new System.Text.StringBuilder();
                foreach (var item in items)
                    sb.AppendLine($"- SHA: {item.CommitSha} | \"{item.Description}\"");
                return sb.ToString().TrimEnd();
            },
            getFeatureCategoryInventory: BuildFeatureCategoryInventory);

        _idleDetectionService?.SetRunnerActive(true);
        _codeHealthPanel?.OnRunnerStarted("starting…");

        await _CodeHealthRunner.StartAsync(config, workspacePath, CancellationToken.None, forceTaskIds);
    }

    private string BuildFeatureCategoryInventory()
    {
        var groups = _featureGroupStore?.Load() ?? FeatureGroupStore.Defaults.ToList();
        var usages = FeatureGroupPromptBuilder.BuildUsages(groups, _approvalItems);
        var sb = new System.Text.StringBuilder();

        foreach (var usage in usages)
        {
            var origin = usage.IsStarter ? "starter" : "workspace";
            sb.AppendLine($"## {usage.Name} ({usage.CommitCount} commits; {origin})");
            foreach (var item in _approvalItems
                         .Where(item => string.Equals(item.FeatureGroup, usage.Name, StringComparison.OrdinalIgnoreCase))
                         .OrderByDescending(item => item.TurnStartedAt)
                         .Take(5))
            {
                sb.AppendLine($"- {item.CommitSha}: {item.Description}");
            }
            sb.AppendLine();
        }

        return sb.ToString().TrimEnd();
    }

    private bool ShouldSuppressCodeHealthCycle()
    {
        if (_isPromptRunning)
            return true;

        if (IsLoopRunning || _loopController.IsRunning || _loopQueued)
            return true;

        if (_promptQueue.Count > 0 && !IsQueueDispatchHeld)
            return true;

        if (_backgroundTaskPresenter.HasBackgroundTasks())
            return true;

        if (HasPendingDirectQuickReplyAgentFollowUp() || _loopFollowUpTcs is not null)
            return true;

        return false;
    }

    /// <summary>
    /// Fires a deferred maintenance cycle if <c>_codeHealthPendingOnIdle</c> is set and the
    /// system is currently truly idle.  Uses <see cref="ShouldSuppressCodeHealthCycle"/> for
    /// the idle check (which does NOT include manual-mode), then calls
    /// <see cref="StartCodeHealthCycleAsync"/> with <c>isManual: true</c> to bypass the
    /// manual-mode gate — that is the whole point of the /maintenance override.
    /// </summary>
    private async void TryFireDeferredCodeHealth()
    {
        if (!_codeHealthPendingOnIdle)
            return;

        if (ShouldSuppressCodeHealthCycle())
            return;

        _codeHealthPendingOnIdle = false;
        SquadDashTrace.Write("UI", "TryFireDeferredCodeHealth: firing deferred maintenance cycle");
        try
        {
            await StartCodeHealthCycleAsync(isManual: true);
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(TryFireDeferredCodeHealth), ex); }
    }

    private void EnsureArgusWeldRegistered(string workspacePath) {
        const string threadKey = "agent:argus-weld";
        if (_agentThreadRegistry.ThreadsByKey.ContainsKey(threadKey)) {
            // Thread already exists (restored from a previous session). On the first
            // maintenance task of this app session, append a session-gap stripe so the
            // transcript shows a clear visual break between sessions.
            if (!_argusWeldSessionGapAppended) {
                var existingThread = _agentThreadRegistry.ThreadsByKey[threadKey];
                AppendArgusWeldSessionGapIfNeeded(existingThread);
                _argusWeldSessionGapAppended = true;
            }
            return;
        }

        string? charter = null;
        var charterPath = Path.Combine(workspacePath, ".squad", "agents", "argus-weld", "charter.md");
        if (File.Exists(charterPath)) {
            try { charter = File.ReadAllText(charterPath); }
            catch { /* best-effort */ }
        }

        _agentThreadRegistry.GetOrCreateAgentThread(
            toolCallId:       null,
            agentId:          "argus-weld",
            agentName:        "argus-weld",
            agentDisplayName: "Argus Weld",
            agentDescription: "Maintenance Coordinator",
            status:           null,
            prompt:           charter,
            startedAt:        DateTimeOffset.UtcNow.ToString("O"));
        // Brand-new thread — no gap stripe needed; mark handled so subsequent calls skip.
        _argusWeldSessionGapAppended = true;
    }

    /// <summary>
    /// Returns true when the thread belongs to the Argus Weld maintenance agent.
    /// </summary>
    private static bool IsArgusWeldThread(TranscriptThreadState thread) =>
        string.Equals(thread.AgentId, "argus-weld", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(thread.AgentName, "argus-weld", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(thread.AgentDisplayName, "Argus Weld", StringComparison.OrdinalIgnoreCase) ||
        string.Equals(thread.Title, "Argus Weld", StringComparison.OrdinalIgnoreCase);

    /// <summary>
    /// Appends a lightweight stub paragraph to the Coordinator transcript for a completed
    /// maintenance task. The stub shows a wrench emoji and a clickable link that navigates
    /// to the corresponding turn in Argus Weld's thread.
    /// </summary>
    private TranscriptThreadState? FindLatestArgusWeldRunThread()
    {
        return _agentThreadRegistry.ThreadOrder
            .Where(thread =>
                !thread.IsPlaceholderThread &&
                (thread.PromptParagraphs.Count > 0 || thread.SavedTurns.Count > 0 || thread.CurrentTurn is not null) &&
                (string.Equals(thread.AgentId, "argus-weld", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(thread.AgentName, "argus-weld", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(thread.AgentDisplayName, "Argus Weld", StringComparison.OrdinalIgnoreCase) ||
                 string.Equals(thread.Title, "Argus Weld", StringComparison.OrdinalIgnoreCase)))
            .OrderByDescending(thread => thread.LastObservedActivityAt ?? thread.CompletedAt ?? thread.StartedAt)
            .FirstOrDefault();
    }

    private void AppendMaintenanceStub(
        string taskTitle,
        string? threadId,
        int anchorIndex,
        DateTimeOffset startedAt,
        TimeSpan duration)
    {
        // Maintenance appends new content to the coordinator transcript, so any quick-reply
        // buttons from the previous coordinator response are now stale and should be hidden.
        if (_lastQuickReplyEntry?.AllowQuickReplies == true)
            _pec.DisableQuickReplies(_lastQuickReplyEntry);
        ClearActiveQuickReplyState();

        var paragraph = CreateTranscriptParagraph();

        var prefix = new Run("🔧 ");
        prefix.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        paragraph.Inlines.Add(prefix);

        var link = new Run(taskTitle)
        {
            FontWeight      = FontWeights.Normal,
            TextDecorations = TextDecorations.Underline,
            Cursor          = Cursors.Hand,
        };
        link.SetResourceReference(TextElement.ForegroundProperty, "ActionLinkText");
        link.MouseLeftButtonDown += (_, e) =>
        {
            NavigateToArgusWeldTask(threadId, anchorIndex);
            e.Handled = true;
        };
        paragraph.Inlines.Add(link);

        // Rebuild tooltip on each open so the relative timestamp ("3 minutes ago") stays current.
        var toolTip = new ToolTip();
        toolTip.SetResourceReference(Control.BackgroundProperty, "InputSurface");
        toolTip.SetResourceReference(Control.BorderBrushProperty, "InputBorder");
        paragraph.ToolTip = toolTip;
        paragraph.ToolTipOpening += (_, _) =>
        {
            var durationText = StatusTimingPresentation.FormatDuration(duration);
            toolTip.Content = $"Maintenance task performed while you were away\nStarted: {StatusTimingPresentation.FormatRelativeTimestamp(startedAt)}\nTook: {durationText}";
        };

        CoordinatorThread.Document.Blocks.Add(paragraph);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }

    private void AppendManualRunSkippedFeedback(
        IReadOnlyList<CodeHealthTask> enabledTasks,
        string workspacePath)
    {
        var msgParagraph = CreateTranscriptParagraph(bottomMargin: 4);
        var msgRun = new Run("Manual maintenance run invoked.");
        msgRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        msgParagraph.Inlines.Add(msgRun);
        msgParagraph.Inlines.Add(new LineBreak());
        var skipRun = new Run("All selected maintenance tasks have been recently run.");
        skipRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        msgParagraph.Inlines.Add(skipRun);
        CoordinatorThread.Document.Blocks.Add(msgParagraph);

        if (enabledTasks.Count == 0)
        {
            ScrollToEndIfAtBottom(CoordinatorThread);
            return;
        }

        var preParagraph = CreateTranscriptParagraph(bottomMargin: 4);
        var preRun = new Run("You can force a maintenance task to run right now by clicking one of the buttons below:");
        preRun.SetResourceReference(TextElement.ForegroundProperty, "SubtleText");
        preParagraph.Inlines.Add(preRun);
        CoordinatorThread.Document.Blocks.Add(preParagraph);

        var panel = new WrapPanel { Orientation = Orientation.Horizontal };
        foreach (var task in enabledTasks)
        {
            var taskId = task.Id;
            var button = TranscriptQuickReplyFactory.CreateButton(task.Title, _transcriptFontSize);
            button.Click += async (_, _) =>
            {
                try
                {
                    await StartCodeHealthCycleAsync(
                        isManual: true,
                        forceTaskIds: new HashSet<string> { taskId });
                }
                catch (Exception ex) { HandleUiCallbackException(nameof(AppendManualRunSkippedFeedback), ex); }
            };
            panel.Children.Add(button);
        }
        var buttonsBlock = TranscriptQuickReplyFactory.CreateContainer(panel);
        CoordinatorThread.Document.Blocks.Add(buttonsBlock);
        ScrollToEndIfAtBottom(CoordinatorThread);
    }
    /// if it has not been rendered yet (i.e. the app was restarted since the last maintenance run).
    /// </summary>
    private void RestoreCodeHealthStubs(string workspacePath)
    {
        try
        {
            var writer    = new CodeHealthReportWriter(workspacePath);
            var stubState = new CodeHealthStubStateStore(System.IO.Path.Combine(workspacePath, ".squad"));
            stubState.Load();

            var sidecarPath = writer.GetMostRecentSidecarPath();
            if (sidecarPath is null) return;

            if (string.Equals(stubState.LastRenderedSidecarPath, sidecarPath, StringComparison.OrdinalIgnoreCase))
                return; // already rendered this session

            if (_renderedSidecarPaths.Contains(sidecarPath))
                return; // already rendered live in this session

            var stubs = writer.TryReadStubSidecar(System.IO.Path.ChangeExtension(sidecarPath, ".md"));
            if (stubs is null || stubs.Count == 0) return;

            foreach (var stub in stubs)
                AppendMaintenanceStub(stub.TaskTitle, stub.ThreadId, stub.AnchorIndex, stub.StartedAt,
                    TimeSpan.FromSeconds(stub.DurationSeconds));

            stubState.LastRenderedSidecarPath = sidecarPath;
            stubState.Save();
            _renderedSidecarPaths.Add(sidecarPath);
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(TraceCategory.General,
                $"RestoreCodeHealthStubs: error — {ex.Message}");
        }
    }

    /// <summary>
    /// Opens Argus Weld's transcript panel (secondary or primary) and scrolls it to the
    /// prompt paragraph at <paramref name="anchorIndex"/>.
    /// </summary>
    private void NavigateToArgusWeldTask(string? threadId, int anchorIndex)
    {
        var thread = !string.IsNullOrWhiteSpace(threadId)
            ? _agentThreadRegistry.ThreadOrder.FirstOrDefault(t =>
                string.Equals(t.ThreadId, threadId, StringComparison.OrdinalIgnoreCase))
            : null;
        thread ??= FindLatestArgusWeldRunThread();
        if (thread is null) return;

        var card = FindAgentCardForThread(thread);
        if (card is null) return;

        OpenSecondaryPanel(card, thread, isAutoOpenedInMultiMode: false);

        if (anchorIndex >= 0)
        {
            _ = Dispatcher.BeginInvoke(DispatcherPriority.Loaded,
                () => ScrollThreadToPromptParagraph(thread, anchorIndex));
        }
    }

    /// <summary>
    /// Scrolls <paramref name="thread"/>'s visible transcript to the prompt paragraph at
    /// <paramref name="promptParagraphIndex"/>, whether the thread is shown in a secondary
    /// panel or in the main transcript area.
    /// </summary>
    private void ScrollThreadToPromptParagraph(TranscriptThreadState thread, int promptParagraphIndex)
    {
        if (promptParagraphIndex < 0 || promptParagraphIndex >= thread.PromptParagraphs.Count)
            return;

        var promptEntry   = thread.PromptParagraphs[promptParagraphIndex];
        var secondaryEntry = _secondaryTranscripts.FirstOrDefault(e => ReferenceEquals(e.Thread, thread));
        if (secondaryEntry is not null)
        {
            var sv = secondaryEntry.TranscriptBox.Template?.FindName("PART_ContentHost", secondaryEntry.TranscriptBox) as ScrollViewer;
            if (sv is not null)
            {
                var tp          = promptEntry.Paragraph.ContentStart;
                var rect        = tp.GetCharacterRect(LogicalDirection.Forward);
                double offset   = sv.VerticalOffset + rect.Top;
                secondaryEntry.ScrollController.ScrollToOffset(offset);
                return;
            }
        }

        if (ReferenceEquals(_selectedTranscriptThread ?? CoordinatorThread, thread))
            ScrollToPromptParagraph(promptEntry.Paragraph);
    }

    private void InitIdleDetection(string workspacePath)
    {
        _CodeHealthStateStore ??= new CodeHealthStateStore(Path.Combine(workspacePath, ".squad"));
        _CodeHealthStateStore.Reload();

        var config = CodeHealthMdParser.ParseWithAllSources(workspacePath);
        double thresholdMinutes = config?.IdleTimeout ?? 15.0;

        _idleDetectionService = new IdleDetectionService();
        _idleDetectionService.IdleThresholdReached += () =>
            Dispatcher.InvokeAsync(() => StartCodeHealthCycleAsync()
                .ContinueWith(t => HandleUiCallbackException("IdleThresholdReached", t.Exception!),
                    TaskContinuationOptions.OnlyOnFaulted));
        _idleDetectionService.Start(thresholdMinutes);
    }

    private void StopIdleDetection()
    {
        _idleDetectionService?.Stop();
        _idleDetectionService = null;
    }

    private void OpenNote(NoteItem note)
    {
        if (_notesStore is null) return;
        var path = note.Scope == DataScope.Shared
            ? NotesStore.GetSharedNotePath(_currentWorkspace?.SquadFolderPath ?? "", note.Id)
            : _notesStore.GetNotePath(note.Id);
        if (!File.Exists(path)) return;
        var liveNote = note;
        MarkdownDocumentWindow.Show(
            CanShowOwnedWindow() ? this : null,
            "Edit Note",
            path,
            showSource: true,
            BuildMarkdownCaptureContext(),
            autoSave: true,
            noteContext: new NoteEditContext(
                InitialTitle: liveNote.Title,
                OnTitleCommit: newTitle => RenameNote(liveNote, newTitle)));
    }

    private void EditNote(NoteItem note)
    {
        if (_notesStore is null) return;
        var path = note.Scope == DataScope.Shared
            ? NotesStore.GetSharedNotePath(_currentWorkspace?.SquadFolderPath ?? "", note.Id)
            : _notesStore.GetNotePath(note.Id);
        if (!File.Exists(path)) return;
        var liveNote = note;
        MarkdownDocumentWindow.Show(
            CanShowOwnedWindow() ? this : null,
            liveNote.Title,
            path,
            showSource: true,
            BuildMarkdownCaptureContext(),
            autoSave: true,
            noteContext: new NoteEditContext(
                InitialTitle: liveNote.Title,
                OnTitleCommit: newTitle => RenameNote(liveNote, newTitle)));
    }

    private void CreateNewNote()
    {
        if (_notesStore is null) return;
        var note = new NoteItem(Guid.NewGuid(), "New Note", DateTimeOffset.UtcNow.ToUnixTimeSeconds());
        _notesStore.WriteContent(note.Id, string.Empty);
        _noteItems.Insert(0, note);
        _notesStore.SaveAll(_noteItems);

        if (!_notesPanelVisible)
        {
            _notesPanelVisible = true;
            SyncNotesPanel();
            if (ViewNotesMenuItem is not null)
                ViewNotesMenuItem.IsChecked = true;
            PersistNotesPanelVisible();
        }
        else
        {
            _notesPanel?.AddNote(note);
        }

        // Open with source visible so the user can start typing immediately.
        var path = _notesStore.GetNotePath(note.Id);
        MarkdownDocumentWindow.Show(
            CanShowOwnedWindow() ? this : null,
            note.Title,
            path,
            showSource: true,
            BuildMarkdownCaptureContext(),
            autoSave: true,
            noteContext: new NoteEditContext(
                InitialTitle: note.Title,
                OnTitleCommit: newTitle => RenameNote(note, newTitle)));
    }

    private void CreateNewSharedNote()
    {
        if (_notesStore is null || _currentWorkspace is null) return;
        var note = new NoteItem(Guid.NewGuid(), "New Shared Note", DateTimeOffset.UtcNow.ToUnixTimeSeconds(), DataScope.Shared);
        NotesStore.WriteSharedContent(_currentWorkspace.SquadFolderPath, note.Id, string.Empty);
        _noteItems.Insert(0, note);
        _notesStore.SaveAll(_noteItems);

        if (!_notesPanelVisible)
        {
            _notesPanelVisible = true;
            SyncNotesPanel();
            if (ViewNotesMenuItem is not null)
                ViewNotesMenuItem.IsChecked = true;
            PersistNotesPanelVisible();
        }
        else
        {
            _notesPanel?.AddNote(note);
        }

        // Open with source visible so the user can start typing immediately.
        var path = NotesStore.GetSharedNotePath(_currentWorkspace.SquadFolderPath, note.Id);
        MarkdownDocumentWindow.Show(
            CanShowOwnedWindow() ? this : null,
            note.Title,
            path,
            showSource: true,
            BuildMarkdownCaptureContext(),
            autoSave: true,
            noteContext: new NoteEditContext(
                InitialTitle: note.Title,
                OnTitleCommit: newTitle => RenameNote(note, newTitle)));
    }

    private void RenameNote(NoteItem oldNote, string newTitle)
    {
        var idx = _noteItems.FindIndex(n => n.Id == oldNote.Id);
        if (idx < 0 || _notesStore is null) return;
        var updated = oldNote with { Title = newTitle };
        _noteItems[idx] = updated;
        _notesStore.SaveAll(_noteItems);
        _notesPanel?.Refresh(_noteItems);
    }

    private void DeleteNote(NoteItem note)
    {
        if (_notesStore is null) return;
        _noteItems.RemoveAll(n => n.Id == note.Id);
        if (note.Scope == DataScope.Shared) {
            var sharedPath = NotesStore.GetSharedNotePath(_currentWorkspace?.SquadFolderPath ?? "", note.Id);
            try { if (File.Exists(sharedPath)) File.Delete(sharedPath); } catch { }
        } else {
            _notesStore.DeleteContent(note.Id);
        }
        _notesStore.SaveAll(_noteItems);
        _notesPanel?.Refresh(_noteItems);
    }

    private void AddNoteFromText(string text)
    {
        if (_notesStore is null) return;
        var title = NotesStore.DeriveTitle(text);
        var note  = new NoteItem(Guid.NewGuid(), title, DateTimeOffset.UtcNow.ToUnixTimeSeconds());
        _notesStore.WriteContent(note.Id, text);
        _noteItems.Insert(0, note);
        _notesStore.SaveAll(_noteItems);

        // Show the panel if hidden
