    private void ApprovalCategorizeButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var pending = _approvalItems.Where(i => !i.IsApproved && !i.IsRejected).ToList();
            if (pending.Count == 0)
            {
                MessageBox.Show("No pending approval items to organize.", "Organize Approvals",
                    MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            var groups    = _featureGroupStore?.Load() ?? FeatureGroupStore.Defaults.ToList();
            var groupContext = FeatureGroupPromptBuilder.BuildContext(
                FeatureGroupPromptBuilder.BuildUsages(groups, _approvalItems));

            // Build the item list as an attachment content block
            var itemsSb = new System.Text.StringBuilder();
            itemsSb.AppendLine("## Items to organize");
            foreach (var item in pending)
            {
                var current = item.FeatureGroup is not null ? $" [currently: {item.FeatureGroup}]" : string.Empty;
                itemsSb.AppendLine($"- SHA: {item.CommitSha} | \"{item.Description}\"{current}");
            }

            var attachment = new FollowUpAttachment(
                CommitSha:      string.Empty,
                Description:    $"{pending.Count} pending approval items",
                OriginalPrompt: null,
                ContentBlock:   itemsSb.ToString());

            // Short instruction prompt — items are in the attachment
            var sb = new System.Text.StringBuilder();
            sb.AppendLine("Please organize the attached pending approval items into feature groups.");
            sb.AppendLine("Assign each item to the most appropriate feature category.");
            sb.AppendLine(groupContext);
            sb.AppendLine();
            sb.AppendLine("Respond using the organize_approvals command with the exact SHAs from the attached list:");
            sb.AppendLine("HOST_COMMAND_JSON:");
            sb.AppendLine("[{\"command\":\"organize_approvals\",\"parameters\":{\"assignments\":[{\"sha\":\"abc1234\",\"group\":\"Login Flow Refactor\"},{\"sha\":\"def5678\",\"group\":\"Bug Fixes\"}]}}]");

            EnqueueRcPrompt(sb.ToString(), new List<FollowUpAttachment> { attachment });
            ShowCategorizationQueuedCallout();
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(ApprovalCategorizeButton_Click), ex); }
    }

    private void ScheduleAutoCategorization()
    {
        if (_categorizationDebounceTimer is null)
        {
            _categorizationDebounceTimer = new DispatcherTimer { Interval = UiTimingConstants.CategorizationDebounceInterval };
            _categorizationDebounceTimer.Tick += (_, _) =>
            {
                _categorizationDebounceTimer.Stop();
                var uncategorized = _approvalItems
                    .Where(i => !i.IsApproved && !i.IsRejected && string.IsNullOrEmpty(i.FeatureGroup))
                    .ToList();
                if (uncategorized.Count > 0)
                    EnqueueOrganizeUncategorizedPrompt(uncategorized);
            };
        }
        _categorizationDebounceTimer.Stop();
        _categorizationDebounceTimer.Start();
    }

    private void EnqueueOrganizeUncategorizedPrompt(IReadOnlyList<CommitApprovalItem> uncategorizedItems)
    {
        try
        {
            if (uncategorizedItems.Count == 0) return;

            var groups    = _featureGroupStore?.Load() ?? FeatureGroupStore.Defaults.ToList();
            var groupContext = FeatureGroupPromptBuilder.BuildContext(
                FeatureGroupPromptBuilder.BuildUsages(groups, _approvalItems));

            var itemsSb = new System.Text.StringBuilder();
            itemsSb.AppendLine("## Uncategorized items to organize");
            foreach (var item in uncategorizedItems)
                itemsSb.AppendLine($"- SHA: {item.CommitSha} | \"{item.Description}\"");

            var attachment = new FollowUpAttachment(
                CommitSha:      string.Empty,
                Description:    $"{uncategorizedItems.Count} uncategorized approval items",
                OriginalPrompt: null,
                ContentBlock:   itemsSb.ToString());

            var sb = new System.Text.StringBuilder();
            sb.AppendLine("Please categorize the attached uncategorized approval items into feature groups.");
            sb.AppendLine("Assign each item to the most appropriate feature category.");
            sb.AppendLine(groupContext);
            sb.AppendLine();
            sb.AppendLine("Respond using the organize_approvals command with the exact SHAs from the attached list:");
            sb.AppendLine("HOST_COMMAND_JSON:");
            sb.AppendLine("[{\"command\":\"organize_approvals\",\"parameters\":{\"assignments\":[{\"sha\":\"abc1234\",\"group\":\"Login Flow Refactor\"},{\"sha\":\"def5678\",\"group\":\"Bug Fixes\"}]}}]");

            EnqueueRcPrompt(sb.ToString(), new List<FollowUpAttachment> { attachment });
            ShowCategorizationQueuedCallout();
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(EnqueueOrganizeUncategorizedPrompt), ex); }
    }

    /// <summary>
    /// After enqueuing a categorization prompt, finds the newly-added queue tab
    /// and shows a callout pointing at it.
    /// </summary>
    private void ShowCategorizationQueuedCallout()
    {
        // The newly-enqueued item is the last in the queue list.
        var newItem = _promptQueue.Items.Count > 0 ? _promptQueue.Items[^1] : null;
        if (newItem is null) return;

        // Queue tabs are rebuilt synchronously by SyncQueuePanel (called inside EnqueueRcPrompt).
        // Find the Border whose Tag matches the new item's Id.
        var tabBorder = QueueTabStrip.Children
            .OfType<Border>()
            .FirstOrDefault(b => b.Tag as string == newItem.Id);

        if (tabBorder is null) return;

        var isDark = Resources.Contains("IsDarkTheme") && (bool)Resources["IsDarkTheme"];
        var theme  = isDark ? CalloutTheme.Dark : CalloutTheme.Light;
        var fontSize = Resources.Contains("FontSizeBody") ? Convert.ToDouble(Resources["FontSizeBody"]) : 13.0;

        _categorizationCallout?.Close();
        _categorizationCallout = FrmUltimateCallout.ShowCalloutBesideTarget(
            "AI will categorize these approvals when this queue item is processed.",
            tabBorder,
            width: 280,
            theme: theme,
            fontSize: fontSize,
            placement: CalloutPlacement.North);
    }

