    private void InboxFilterBox_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        try
        {
            if (_intelliSenseState is null || _intelliSenseOwnerBox != InboxFilterBox) return;
            switch (e.Key)
            {
                case Key.Up:
                    _intelliSenseState = IntelliSenseController.MoveSelection(_intelliSenseState, -1);
                    UpdateIntelliSensePopup();
                    e.Handled = true;
                    break;
                case Key.Down:
                    _intelliSenseState = IntelliSenseController.MoveSelection(_intelliSenseState, +1);
                    UpdateIntelliSensePopup();
                    e.Handled = true;
                    break;
                case Key.Return:
                case Key.Tab:
                    ApplyIntelliSenseAccept(andSubmit: false);
                    e.Handled = true;
                    break;
                case Key.Escape:
                    _intelliSenseState = null;
                    _intelliSenseOwnerBox = null;
                    UpdateIntelliSensePopup();
                    _inboxPanel?.SetFilter(InboxFilterBox.Text.Trim());
                    e.Handled = true;
                    break;
            }
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(InboxFilterBox_PreviewKeyDown), ex); }
    }

    private void TasksFilterBox_TextChanged(object sender, System.Windows.Controls.TextChangedEventArgs e)
    {
        try
        {
            var text = TasksFilterBox?.Text ?? string.Empty;
            if (TasksFilterClearButton is not null)
                TasksFilterClearButton.Visibility = text.Length > 0 ? Visibility.Visible : Visibility.Collapsed;
            // Update IntelliSense first — a character like space may dismiss it (returning null).
            // The suppression check below must see the post-update state so that typing e.g. "@me "
            // doesn't spuriously show all tasks due to stale open-popup state.
            if (TasksFilterBox is not null)
                TryUpdateTasksIntelliSense();
            // While @ IntelliSense is open, pass the live typed text so the Tasks panel can do
            // prefix-based owner filtering (e.g. "@v" shows all tasks owned by any agent whose
            // handle starts with "v"). Once the user accepts a suggestion the full resolved handle
            // is committed and the exact filter takes over.
            string filterText = text;
            _tasksPanelController?.SetFilter(filterText);
            UpdateTasksDoThesePresentation(text);
            ScheduleLoopPreviewRefreshFromFilter();
            _docsPanelState = (_docsPanelState ?? new WorkspaceDocsPanelState()) with { TasksPanelFilter = text.Length > 0 ? text : string.Empty };
            _settingsManager.Replace(_settingsStore.SaveDocsPanelState(_currentWorkspace?.FolderPath, _docsPanelState));
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(TasksFilterBox_TextChanged), ex); }
    }

    private void UpdateTasksDoThesePresentation(string filterText)
    {
        if (TasksPanelDoTheseContainer is null || TasksPanelDoTheseCountText is null) return;
        if (string.IsNullOrWhiteSpace(filterText))
        {
            TasksPanelDoTheseContainer.Visibility = Visibility.Collapsed;
            TasksPanelDoTheseCountText.Text = string.Empty;
            return;
        }

        var selection = _tasksPanelController?.ResolveVisibleExecutionSelection();
        var count = selection?.VisibleTaskCount ?? 0;
        TasksPanelDoTheseContainer.Visibility = Visibility.Visible;
        TasksPanelDoTheseCountText.Text = $"{count} filtered {(count == 1 ? "task" : "tasks")}";
    }

    private void TasksFilterBox_PreviewKeyDown(object sender, KeyEventArgs e)
    {
        try
        {
            if (_intelliSenseState is null || _intelliSenseOwnerBox != TasksFilterBox) return;
            switch (e.Key)
            {
                case Key.Up:
                    _intelliSenseState = IntelliSenseController.MoveSelection(_intelliSenseState, -1);
                    UpdateIntelliSensePopup();
                    e.Handled = true;
                    break;
                case Key.Down:
                    _intelliSenseState = IntelliSenseController.MoveSelection(_intelliSenseState, +1);
                    UpdateIntelliSensePopup();
                    e.Handled = true;
                    break;
                case Key.Return:
                case Key.Tab:
                    ApplyIntelliSenseAccept(andSubmit: false);
                    e.Handled = true;
