    private async void TasksPanelDoTheseButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            var workspaceFolder = _currentWorkspace?.FolderPath;
            if (string.IsNullOrEmpty(workspaceFolder)) return;

            var selection = _tasksPanelController?.ResolveVisibleExecutionSelection();
            SquadDashTrace.Write(
                "Loop",
                $"Tasks Do these resolved kind={selection?.Kind.ToString() ?? "Unavailable"} visible={selection?.VisibleTaskCount ?? 0} filter='{TasksFilterBox?.Text?.Trim() ?? ""}' group={selection?.Group?.GroupId ?? "(none)"}.");

            if (selection is null ||
                selection.Kind is TasksPanelExecutionKind.NoTasks or TasksPanelExecutionKind.InvalidPlanSelection)
            {
                ShowSystemTranscriptEntry(
                    "Nothing safe to run. " +
                    (selection?.Error ?? "SquadDash could not determine which tasks are visible."));
                return;
            }

            if (selection.Kind == TasksPanelExecutionKind.DecomposeGroup && selection.Group is { } decomposeGroup)
            {
                if (IsLoopRunning)
                {
                    ShowSystemTranscriptEntry(
                        "Plan not started. A structured plan cannot be started while another loop is running. " +
                        "Queueing plan executions requires its own branch and recovery preflight.");
                    return;
                }
                if (selection.ContainsBlockedTask)
                {
                    ShowSystemTranscriptEntry(
                        "Plan not started. This plan contains a failed or partial task. " +
                        "Use its recovery actions to replan or retry it.");
                    return;
                }

                await StartBackloggedDecomposeGroupAsync(decomposeGroup);
                return;
            }

            var taskScope = FilteredTaskScopeSnapshot.Capture(
                TasksFilterBox?.Text,
                selection.GenericTasks ?? []);

            // Shift+click remains available for ordinary backlog tasks only. Structured plans
            // always use the dedicated dependency-aware Executing Plan engine. The alternate
            // loop selection receives the same immutable scope as the default loop.
            if ((Keyboard.Modifiers & ModifierKeys.Shift) != 0)
            {
                ShowDoTheseWithMenu(sender as FrameworkElement, taskScope);
                return;
            }

            var loopFilePath = Path.Combine(workspaceFolder, ".squad", "loop-filtered-tasks.md");
            if (!File.Exists(loopFilePath)) return;

            if (IsLoopRunning)
            {
                EnqueueFilteredLoopJob(new QueuedLoopJob(
                    new ActiveLoopExecutionState(loopFilePath, taskScope.Encode()),
                    $"{taskScope.Tasks.Count} filtered {(taskScope.Tasks.Count == 1 ? "task" : "tasks")}",
                    taskScope.Tasks.Count));
                return;
            }

            // When the loop panel is visible and the current loop is not the filtered-tasks loop,
            // show a picker so the user can choose which loop to run.
            if (_loopPanelVisible && !IsFilteredTasksLoopSelected())
            {
                var dialog = new LoopPickerDialog(
                    currentLoopPath:   _selectedLoopMdPath ?? loopFilePath,
                    currentLoopLabel:  GetCurrentLoopLabel(),
                    filteredTasksPath: loopFilePath,
                    otherLoops:        GetOtherLoopEntries(loopFilePath),
                    owner:             this);
                if (dialog.ShowDialog() != true) return;

                if (!string.Equals(dialog.SelectedLoopPath, _selectedLoopMdPath, StringComparison.OrdinalIgnoreCase))
                {
                    _selectedLoopMdPath = dialog.SelectedLoopPath;
                    PersistLoopFileSelection();
                    _loopPanelVisible = true;
                    SyncLoopPanel();
                    PopulateLoopFilePicker();
                    RefreshLoopOptionsPanel();
                }
            }
            else
            {
                // Select the filtered-tasks loop file and persist the choice
                _selectedLoopMdPath = loopFilePath;
                PersistLoopFileSelection();

                // Ensure the loop panel is visible and fully refreshed
                _loopPanelVisible = true;
                SyncLoopPanel();
                PopulateLoopFilePicker();
                RefreshLoopOptionsPanel();
            }

            await QueueOrStartLoopAsync(
                LoopMode.NativeAgents,
                new ActiveLoopExecutionState(loopFilePath, taskScope.Encode()));
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(TasksPanelDoTheseButton_Click), ex); }
    }

    private async Task StartBackloggedDecomposeGroupAsync(
        DecomposedTaskGroup group,
        string? continuationTaskId = null,
        IReadOnlyList<string>? continuationPaths = null,
        AssessedRecoveryContinuationState? assessedRecoveryContinuation = null)
    {
        if (_currentWorkspace is null) return;
        // The durable plan is the execution contract. A group supplied by the tasks panel is
        // only a lossy display projection and cannot participate in execution decisions.
        var durablePlan = _planStore?.Load(group.GroupId);
        if (durablePlan is not null)
        {
            durablePlan = RepairPlanSchemaBeforeExecution(durablePlan);
            group = PendingDecomposePlanAdapter.FromPlan(durablePlan).Group with
            {
                HostRevision = durablePlan.Revision,
            };
        }
        if (!TryValidateDecomposeGroupForExecution(group, out var validationError))
            throw new InvalidOperationException(validationError);

        var workspace = _currentWorkspace.FolderPath;
        var targetBranch = group.Branch.Trim();
        var isConfirmedContinuation = !string.IsNullOrWhiteSpace(continuationTaskId) &&
                                      continuationPaths is { Count: > 0 };
        if (isConfirmedContinuation)
        {
            var activeBranch = ReadGitBranch(workspace);
            if (!string.Equals(activeBranch, targetBranch, StringComparison.Ordinal))
                throw new InvalidOperationException(
                    $"Plan {group.GroupId} requires branch '{targetBranch}', but '{activeBranch}' is active.");
        }
        else
        {
            await PrepareDecomposeBranchAsync(workspace, targetBranch, group.GroupId);
        }

        if (!await StartDecomposeLoopAsync(
                group.GroupId,
                group,
                continuationTaskId: continuationTaskId,
                continuationPaths: continuationPaths,
                assessedRecoveryContinuation: assessedRecoveryContinuation))
            throw new InvalidOperationException("SquadDash could not start the decomposition loop.");
    }

    private static bool TryValidateDecomposeGroupForExecution(
        DecomposedTaskGroup group,
        out string error)
    {
        if (!TasksJsonParser.TryParse(
                "TASKS_JSON:\n" + System.Text.Json.JsonSerializer.Serialize(group),
                out _,
                out var diagnostic))
        {
            error = "The selected task plan no longer passes schema validation: " +
                    (diagnostic?.Message ?? "unknown schema error");
            return false;
        }
        if (!CodeHealthGroupRunner.HasNoDependencyCycle(group, out var cycle))
        {
            error = "The selected task plan contains a dependency cycle: " +
                    string.Join(", ", cycle ?? []);
            return false;
        }

        error = string.Empty;
        return true;
    }

    private async Task PrepareDecomposeBranchAsync(
        string workspace,
        string targetBranch,
        string? planId = null)
    {
        var activeBranch = ReadGitBranch(workspace);
        if (string.IsNullOrWhiteSpace(activeBranch) || activeBranch.StartsWith("(detached", StringComparison.Ordinal))
            throw new PlanPreflightBlockedException(
                PlanPreflightBlockedException.RepositoryInitializationRequiredCondition,
                [],
                targetBranch);

        var dirty = await RunGitAsync(workspace, "status --porcelain --untracked-files=all");
        if (!string.IsNullOrWhiteSpace(dirty))
        {
            var allowed = await GetAllowedPlanPathsAsync(workspace, planId);
            if (!DecomposeWorktreePolicy.HasOnlyAllowedChanges(dirty, allowed, out var candidates))
            {
                var genuinelyDirty = await DecomposeWorktreePolicy.FilterMetadataOnlyAsync(
                    candidates,
                    command => RunGitAsync(workspace, command));
                if (genuinelyDirty.Count > 0)
                    throw new PlanPreflightBlockedException("Uncommitted changes", genuinelyDirty, targetBranch);
            }
        }

        if (string.Equals(activeBranch, targetBranch, StringComparison.Ordinal))
            return;

        var escapedBranch = targetBranch.Replace("\"", "\\\"");
        await RunGitAsync(workspace, $"check-ref-format --branch \"{escapedBranch}\"");
        var existing = await RunGitAsync(
            workspace,
            $"branch --list --format=\"%(refname:short)\" \"{escapedBranch}\"");
        await RunGitAsync(
            workspace,
            string.Equals(existing.Trim(), targetBranch, StringComparison.Ordinal)
                ? $"checkout \"{escapedBranch}\""
                : $"checkout -b \"{escapedBranch}\"");
        UpdateBranchIndicator();
    }

    private async Task<PlanBranchEnforcementResult> EnforcePlanBranchLeaseAsync(
        PlanBranchLease lease,
        string? candidateCommit,
        bool mutationAllowed,
        string? transcriptCommit = null)
    {
        if (_currentWorkspace is null)
            return new(false, false, false, "No workspace is active.");

        var workspace = _currentWorkspace.FolderPath;
        var activeBranch = ReadGitBranch(workspace);
        if (string.Equals(activeBranch, lease.CanonicalBranch, StringComparison.Ordinal))
            return new(true, false, false, "The canonical plan branch is active.");

        try
        {
            var escapedCanonical = lease.CanonicalBranch.Replace("\"", "\\\"");
            var canonicalHead = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"refs/heads/{escapedCanonical}^{{commit}}\"")).Trim();
            var activeHead = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();

            string? resolvedCandidate = null;
            if (!string.IsNullOrWhiteSpace(candidateCommit) &&
                Regex.IsMatch(candidateCommit, "^[0-9a-fA-F]{7,64}$", RegexOptions.CultureInvariant))
            {
                try
                {
                    resolvedCandidate = (await RunGitAsync(
                        workspace,
                        $"rev-parse --verify \"{candidateCommit}^{{commit}}\"")).Trim();
                }
                catch when (ReportedCommitReconciler.MatchesObservedHead(transcriptCommit, activeHead))
                {
                    resolvedCandidate = activeHead;
                    SquadDashTrace.Write(
                        "PlanBranchLease",
                        $"Reconciled unresolvable reported commit '{candidateCommit}' from transcript commit " +
                        $"'{transcriptCommit}' at active HEAD '{activeHead}'. Branch ancestry and single-commit validation will still run.");
                }
                catch when (ReportedCommitReconciler.IsSingleCharacterSubstitution(candidateCommit, activeHead))
                {
                    resolvedCandidate = activeHead;
                    SquadDashTrace.Write(
                        "PlanBranchLease",
                        $"Reconciled one-character reported commit typo '{candidateCommit}' to active HEAD '{activeHead}'. " +
                        "Branch ancestry and single-commit validation will still run.");
                }
            }

            var worktreeIsSafe = true;
            var status = await RunGitAsync(workspace, "status --porcelain --untracked-files=all");
            var allowed = await GetAllowedPlanPathsAsync(workspace, lease.PlanId);
            if (!DecomposeWorktreePolicy.HasOnlyAllowedChanges(status, allowed, out var candidates))
            {
                var genuinelyDirty = await DecomposeWorktreePolicy.FilterMetadataOnlyAsync(
                    candidates,
                    command => RunGitAsync(workspace, command));
                worktreeIsSafe = genuinelyDirty.Count == 0;
            }

            var canonicalIsAncestor = false;
            var commitCount = -1;
            if (resolvedCandidate is not null)
            {
                try
                {
                    await RunGitAsync(
                        workspace,
                        $"merge-base --is-ancestor \"{canonicalHead}\" \"{resolvedCandidate}\"");
                    canonicalIsAncestor = true;
                    var countText = (await RunGitAsync(
                        workspace,
                        $"rev-list --count \"{canonicalHead}..{resolvedCandidate}\"")).Trim();
                    _ = int.TryParse(countText, out commitCount);
                }
                catch
                {
                    canonicalIsAncestor = false;
                }
            }

            var assessment = PlanBranchLeasePolicy.Assess(
                lease,
                activeBranch,
                canonicalHead,
                activeHead,
                resolvedCandidate,
                canonicalIsAncestor,
                commitCount,
                worktreeIsSafe,
                mutationAllowed);
            if (!assessment.CanContinue)
            {
                var message =
                    $"SquadDash detected that plan work left the host-owned branch '{lease.CanonicalBranch}' " +
                    $"and is now on '{activeBranch}'. {assessment.Explanation} No downstream task was started or failed.";
                SquadDashTrace.Write("PlanBranchLease", message);
                return new(false, false, false, message);
            }

            if (assessment.Action == PlanBranchRepairAction.RestoreCanonicalBranch)
            {
                await RunGitAsync(workspace, $"checkout \"{escapedCanonical}\"");
                UpdateBranchIndicator();
                var message =
                    $"SquadDash restored the host-owned plan branch '{lease.CanonicalBranch}'. No commit movement was required.";
                SquadDashTrace.Write("PlanBranchLease", message);
                return new(true, true, false, message);
            }

            if (assessment.Action == PlanBranchRepairAction.AdoptCandidateCommit && resolvedCandidate is not null)
            {
                await RunGitAsync(
                    workspace,
                    $"branch -f \"{escapedCanonical}\" \"{resolvedCandidate}\"");
                await RunGitAsync(workspace, $"checkout \"{escapedCanonical}\"");
                var repairedBranch = ReadGitBranch(workspace);
                var repairedHead = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
                if (!string.Equals(repairedBranch, lease.CanonicalBranch, StringComparison.Ordinal) ||
                    !string.Equals(repairedHead, resolvedCandidate, StringComparison.OrdinalIgnoreCase))
                    throw new InvalidOperationException("Git did not retain the canonical branch and adopted commit after repair.");

                UpdateBranchIndicator();
                var message =
                    $"SquadDash preserved task commit {resolvedCandidate[..Math.Min(7, resolvedCandidate.Length)]} " +
                    $"and restored it to the host-owned plan branch '{lease.CanonicalBranch}'.";
                SquadDashTrace.Write("PlanBranchLease", message);
                return new(true, true, true, message);
            }

            return new(true, false, false, assessment.Explanation);
        }
        catch (Exception ex)
        {
            var message =
                $"SquadDash could not restore the host-owned plan branch '{lease.CanonicalBranch}' safely: {ex.Message} " +
                "No downstream task was started or failed.";
            SquadDashTrace.Write("PlanBranchLease", message);
            return new(false, false, false, message);
        }
    }

    private async Task EnsurePlanWorktreeReadyAsync(string workspace, string? planId = null)
    {
        var status = await RunGitAsync(workspace, "status --porcelain --untracked-files=all");
        var allowed = await GetAllowedPlanPathsAsync(workspace, planId);
        if (!DecomposeWorktreePolicy.HasOnlyAllowedChanges(status, allowed, out var candidates))
        {
            var genuinelyDirty = await DecomposeWorktreePolicy.FilterMetadataOnlyAsync(
                candidates,
                cmd => RunGitAsync(workspace, cmd));
            if (genuinelyDirty.Count > 0)
            {
                throw new PlanPreflightBlockedException("Uncommitted changes", genuinelyDirty, targetBranch: null);
            }
        }
    }

    private async Task<IReadOnlyList<string>> GetAllowedPlanPathsAsync(
        string workspace,
        string? planId = null)
    {
        var paths = new List<string>();
        var tasksPath = await GetTasksRepositoryRelativePathAsync(workspace);
        if (tasksPath is not null) paths.Add(tasksPath);

        var effectivePlanId = planId ?? _activeDecomposeGroupId;
        if (effectivePlanId is not null && _currentWorkspace is not null)
        {
            var repositoryRoot = (await RunGitAsync(workspace, "rev-parse --show-toplevel")).Trim();
            var planJsonPath = Path.Combine(_currentWorkspace.SquadFolderPath, "plans", effectivePlanId + ".json");
            if (File.Exists(planJsonPath))
            {
                var relative = Path.GetRelativePath(repositoryRoot, planJsonPath).Replace('\\', '/');
                if (!relative.StartsWith("../", StringComparison.Ordinal) && !Path.IsPathRooted(relative))
                    paths.Add(relative);
            }
        }
        return paths;
    }

    private async Task<string?> GetTasksRepositoryRelativePathAsync(
        string workspace, Func<string, string, Task<string>>? runGit = null)
    {
        if (_currentWorkspace is null) return null;
        var tasksPath = Path.Combine(_currentWorkspace.SquadFolderPath, "tasks.md");
        var repositoryRoot = await (runGit ?? RunGitAsync)(workspace, "rev-parse --show-toplevel");
        return DecomposeWorktreePolicy.GetRepositoryRelativePath(repositoryRoot, tasksPath);
    }

    private async Task<IReadOnlyCollection<string>> GetHostOwnedRecoveryPathsAsync(string workspace)
    {
        var paths = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { ".squad/" };
        if (_currentWorkspace is null) return paths;

        var repositoryRoot = await RunGitAsync(workspace, "rev-parse --show-toplevel");
        var squadRelativePath = DecomposeWorktreePolicy.GetRepositoryRelativePath(
            repositoryRoot,
            _currentWorkspace.SquadFolderPath);
        if (!string.IsNullOrWhiteSpace(squadRelativePath))
            paths.Add(squadRelativePath.TrimEnd('/', '\\') + "/");

        var tasksRelativePath = await GetTasksRepositoryRelativePathAsync(workspace);
        if (!string.IsNullOrWhiteSpace(tasksRelativePath))
            paths.Add(tasksRelativePath);
        return paths;
    }

    private async Task<IReadOnlyCollection<string>> GetHostOwnedAssessmentPathsAsync(string workspace)
    {
        var squadRoots = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { ".squad" };
        if (_currentWorkspace is not null)
        {
            var repositoryRoot = await RunGitAsync(workspace, "rev-parse --show-toplevel");
            var squadRelativePath = DecomposeWorktreePolicy.GetRepositoryRelativePath(
                repositoryRoot,
                _currentWorkspace.SquadFolderPath);
            if (!string.IsNullOrWhiteSpace(squadRelativePath))
                squadRoots.Add(squadRelativePath.TrimEnd('/', '\\'));
        }

        return squadRoots
            .SelectMany(DecomposeWorktreePolicy.GetHostOwnedRuntimePaths)
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToArray();
    }

    private async void CodeHealthDoTheseButton_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (ShouldSuppressCodeHealthCycle())
            {
                EnqueuePrompt("/codehealth", isSystemInjected: false);
                _codeHealthPanel?.ShowTransientStatus("Queued — will run when AI is free.");
                return;
            }
            await StartCodeHealthCycleAsync(isManual: true);
        }
        catch (Exception ex) { HandleUiCallbackException(nameof(CodeHealthDoTheseButton_Click), ex); }
    }

    private bool IsFilteredTasksLoopSelected()
    {
        if (_selectedLoopMdPath is null) return false;
        return string.Equals(
            Path.GetFileName(_selectedLoopMdPath),
            "loop-filtered-tasks.md",
            StringComparison.OrdinalIgnoreCase);
    }

    private string GetCurrentLoopLabel()
    {
        var entry = GetSelectedLoopFileEntry();
        if (entry is not null) return entry.DisplayName;
        if (_selectedLoopMdPath is not null) return Path.GetFileName(_selectedLoopMdPath);
        return "loop.md";
    }

    private IReadOnlyList<LoopFileEntry> GetOtherLoopEntries(string filteredTasksPath)
    {
        if (_currentWorkspace is null) return Array.Empty<LoopFileEntry>();
        var allEntries = LoopMdParser.ScanForLoopFiles(_currentWorkspace.SquadFolderPath);
        var result = new List<LoopFileEntry>();
        foreach (var entry in allEntries)
        {
            if (IsExecutingPlanLoopFile(entry.FilePath))
                continue;
            if (string.Equals(entry.FilePath, _selectedLoopMdPath, StringComparison.OrdinalIgnoreCase))
                continue;
            if (string.Equals(entry.FilePath, filteredTasksPath, StringComparison.OrdinalIgnoreCase))
                continue;
            result.Add(entry);
        }
        return result;
    }

    private void ShowDoTheseWithMenu(
        FrameworkElement? anchor,
        FilteredTaskScopeSnapshot taskScope)
    {
        if (_currentWorkspace is null) return;
        var entries = LoopMdParser.ScanForLoopFiles(_currentWorkspace.SquadFolderPath)
            .Where(entry => !IsExecutingPlanLoopFile(entry.FilePath))
            .ToArray();
        if (entries.Length == 0) return;

        var menu = new ContextMenu();
        menu.SetResourceReference(ContextMenu.StyleProperty, "ThemedContextMenuStyle");

        var header = new MenuItem {
            Header = "Do these with:",
            IsEnabled = false,
        };
        header.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
        menu.Items.Add(header);

        menu.Items.Add(new Separator { Style = (Style)FindResource("ThemedMenuSeparatorStyle") });

        foreach (var entry in entries)
        {
            var capturedPath = entry.FilePath;
            var item = new MenuItem { Header = entry.DisplayName };
            item.SetResourceReference(MenuItem.StyleProperty, "ThemedMenuItemStyle");
            if (!string.IsNullOrEmpty(entry.TooltipText))
                item.ToolTip = MakeThemedToolTip(entry.TooltipText);
            item.Click += async (_, _) =>
            {
                try
                {
                    _selectedLoopMdPath = capturedPath;
                    PersistLoopFileSelection();
                    _loopPanelVisible = true;
                    SyncLoopPanel();
                    PopulateLoopFilePicker();
                    RefreshLoopOptionsPanel();
                    await QueueOrStartLoopAsync(
                        LoopMode.NativeAgents,
                        new ActiveLoopExecutionState(capturedPath, taskScope.Encode()));
                }
                catch (Exception ex) { HandleUiCallbackException("DoTheseWithMenu.Click", ex); }
            };
            menu.Items.Add(item);
        }

        if (anchor != null)
        {
            menu.PlacementTarget = anchor;
            menu.Placement = System.Windows.Controls.Primitives.PlacementMode.Bottom;
        }
        menu.IsOpen = true;
    }

    private static bool IsExecutingPlanLoopFile(string path) =>
        string.Equals(
            Path.GetFileName(path),
            "loop-executing-plan.md",
            StringComparison.OrdinalIgnoreCase);

