    private sealed record InterruptedTaskReviewRange(
        string TaskId,
        string BaselineCommit,
        string TerminalCommit,
        IReadOnlyList<PlanEvidenceCommit> Commits,
        bool HasExactTaskAttribution);

    private async Task OpenInterruptedTaskReviewAsync(
        string planId,
        string expectedRevision,
        string? initialFilePath = null)
    {
        var plan = _planStore?.Load(planId);
        if (plan is null || !string.Equals(plan.Revision, expectedRevision, StringComparison.Ordinal))
        {
            UIErrorHelper.ShowWarning(
                "Review Repository Changes",
                "This recovery request is stale because the plan changed. Reopen the current plan state.");
            return;
        }

        var taskId = plan.InterruptionData?.InterruptedTaskId;
        if (plan.LifecycleStatus != PlanLifecycleStatus.Interrupted || string.IsNullOrWhiteSpace(taskId))
        {
            UIErrorHelper.ShowWarning(
                "Review Repository Changes",
                "This plan is no longer waiting for an interrupted-step decision.");
            return;
        }

        try
        {
            var exactCommitEvidence = plan.InterruptionData?.TaskCommitEvidence is { } exactEvidence &&
                                      string.Equals(exactEvidence.TaskId, taskId, StringComparison.Ordinal);
            var workspace = _currentWorkspace?.FolderPath;
            if (!exactCommitEvidence && !string.IsNullOrWhiteSpace(workspace))
            {
                var status = await RunGitAsync(workspace, "status --short --untracked-files=all");
                if (!string.IsNullOrWhiteSpace(status))
                {
                    var baseline = await ResolvePlanRecoveryBaselineAsync(workspace, plan, taskId);
                    var diff = await RunGitAsync(
                        workspace,
                        $"diff --no-ext-diff --no-color \"{baseline}\" --");
                    var changedPaths = status
                        .Replace("\r\n", "\n", StringComparison.Ordinal)
                        .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
                        .Select(line => line.Length > 3 ? line[3..].Trim() : line)
                        .ToArray();
                    var shortBaseline = baseline[..Math.Min(7, baseline.Length)];
                    var window = new PlanPreflightChangesWindow(
                        new PlanPreflightBlockedException(
                            "Interrupted workspace comparison",
                            changedPaths,
                            plan.Branch),
                        status,
                        diff,
                        _transcriptFontSize,
                        windowTitle: $"Workspace Changes Since {shortBaseline}",
                        heading: $"Workspace changes compared with baseline {shortBaseline}",
                        guidance: "This comparison includes committed, staged, and tracked working-tree changes since the recorded task baseline. Untracked files are listed in Git status.",
                        diffLabel: $"GIT DIFF {shortBaseline} → WORKSPACE");
                    window.Owner = CanShowOwnedWindow() ? this : null;
                    window.Show();
                    return;
                }
            }

            var review = await ResolveInterruptedTaskReviewRangeAsync(plan, taskId);
            if (string.IsNullOrWhiteSpace(workspace))
                throw new InvalidOperationException("The workspace is unavailable.");
            var viewer = await CommitViewerWindow.CreateRangeAsync(
                workspace,
                review.BaselineCommit,
                review.TerminalCommit,
                initialFilePath ?? string.Empty);
            viewer.ConfigureEnvironmentFontZoom(Window_PreviewMouseWheel);
            viewer.Owner = CanShowOwnedWindow() ? this : null;
            viewer.Show();
        }
        catch (Exception ex)
        {
            UIErrorHelper.ShowWarning(
                "Review Repository Changes",
                $"SquadDash could not build the repository review.\n\n{ex.Message}");
        }
    }

    private async Task<InterruptedTaskReviewRange> ResolveInterruptedTaskReviewRangeAsync(
        Plan plan,
        string taskId)
    {
        if (_currentWorkspace is null)
            throw new InvalidOperationException("The workspace is unavailable.");

        var workspace = _currentWorkspace.FolderPath;
        var exact = plan.InterruptionData?.TaskCommitEvidence is { } evidence &&
                    string.Equals(evidence.TaskId, taskId, StringComparison.Ordinal) &&
                    !string.IsNullOrWhiteSpace(evidence.BaselineCommit) &&
                    !string.IsNullOrWhiteSpace(evidence.Commit)
            ? evidence
            : null;
        string baseline;
        string terminal;
        if (exact is not null)
        {
            baseline = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"{exact.BaselineCommit}^{{commit}}\"")).Trim();
            terminal = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"{exact.Commit}^{{commit}}\"")).Trim();
            baseline = await RecoverBroadenedInterruptedTaskBaselineAsync(
                           plan,
                           workspace,
                           baseline,
                           terminal)
                       ?? baseline;
        }
        else
        {
            var head = (await RunGitAsync(workspace, "rev-parse HEAD")).Trim();
            var history = (await RunGitAsync(workspace, $"rev-list \"{head}\""))
                .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
            baseline = RecoveryCommitValidator.FindNewestRecordedCommit(
                history,
                plan.Tasks
                    .Where(task => task.Status == PlanTaskStatus.Complete)
                    .Select(task => task.Commit))
                ?? throw new InvalidOperationException(
                    "SquadDash does not have a reliable accepted-task commit from before this step.");

            terminal = head;
            var capturedResults = InterruptedPlanEvidenceResolver.FindTaskResults(
                _conversationManager.ConversationState.Turns,
                plan.PlanId,
                plan.Revision,
                taskId);
            foreach (var result in capturedResults)
            {
                try
                {
                    var resolved = (await RunGitAsync(
                        workspace,
                        $"rev-parse --verify \"{result.Commit}^{{commit}}\"")).Trim();
                    await RunGitAsync(
                        workspace,
                        $"merge-base --is-ancestor \"{baseline}\" \"{resolved}\"");
                    await RunGitAsync(
                        workspace,
                        $"merge-base --is-ancestor \"{resolved}\" \"{head}\"");
                    terminal = resolved;
                    break;
                }
                catch
                {
                    // Try the next captured result. A later envelope repair may have recorded
                    // an unrelated HEAD, while an earlier handoff still identifies the range.
                }
            }
        }

        await RunGitAsync(workspace, $"merge-base --is-ancestor \"{baseline}\" \"{terminal}\"");
        var commitIds = (await RunGitAsync(
                workspace,
                $"rev-list --reverse \"{baseline}..{terminal}\""))
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
        if (commitIds.Length == 0)
            throw new InvalidOperationException("There are no repository commits to review for this interrupted step.");

        var recordedByCommit = (exact?.Commits ?? [])
            .Where(commit => !string.IsNullOrWhiteSpace(commit.Commit))
            .ToDictionary(commit => commit.Commit, StringComparer.OrdinalIgnoreCase);
        var commits = commitIds.Select(commit =>
        {
            var recorded = recordedByCommit.FirstOrDefault(pair =>
                RecoveryCommitValidator.CommitIdentifiersMatch(pair.Key, commit)).Value;
            if (recorded is not null) return recorded with { Commit = commit };
            return exact is not null
                ? new PlanEvidenceCommit(
                    commit,
                    PlanRecoveryCommitRelation.Task,
                    "Commit in the exact host-recorded task range.")
                : new PlanEvidenceCommit(
                    commit,
                    PlanRecoveryCommitRelation.Unknown,
                    "This commit is between the last accepted step and the captured completion checkpoint; exact task attribution was not recorded.");
        }).ToArray();

        return new InterruptedTaskReviewRange(
            taskId,
            baseline,
            terminal,
            commits,
            exact is not null);
    }

    private async Task<string?> RecoverBroadenedInterruptedTaskBaselineAsync(
        Plan plan,
        string workspace,
        string exactBaseline,
        string terminal)
    {
        var interruptionBaseline = plan.InterruptionData?.LastCommit;
        if (string.IsNullOrWhiteSpace(interruptionBaseline))
            return null;

        string resolvedInterruptionBaseline;
        try
        {
            resolvedInterruptionBaseline = (await RunGitAsync(
                workspace,
                $"rev-parse --verify \"{interruptionBaseline}^{{commit}}\"")).Trim();
            if (string.Equals(resolvedInterruptionBaseline, exactBaseline, StringComparison.OrdinalIgnoreCase))
                return null;
            await RunGitAsync(
                workspace,
                $"merge-base --is-ancestor \"{resolvedInterruptionBaseline}\" \"{exactBaseline}\"");
            await RunGitAsync(
                workspace,
                $"merge-base --is-ancestor \"{resolvedInterruptionBaseline}\" \"{terminal}\"");
        }
        catch (Exception ex)
        {
            SquadDashTrace.Write(
                "PlanRecovery",
                $"Could not broaden interrupted review range for plan={plan.PlanId}: {ex.Message}");
            return null;
        }

        var hostOwnedPaths = await GetHostOwnedRecoveryPathsAsync(workspace);
        var exactChangedPaths = await GetChangedPathsInRangeAsync(workspace, exactBaseline, terminal);
        if (RecoveryCommitValidator.ContainsNonHostChanges(exactChangedPaths, hostOwnedPaths))
            return null;

        var broadenedChangedPaths = await GetChangedPathsInRangeAsync(
            workspace,
            resolvedInterruptionBaseline,
            terminal);
        if (!RecoveryCommitValidator.ShouldRecoverBroadenedInterruptedRange(
                exactChangedPaths,
                broadenedChangedPaths,
                hostOwnedPaths))
            return null;

        SquadDashTrace.Write(
            "PlanRecovery",
            $"Broadened interrupted review range for plan={plan.PlanId} from baseline={exactBaseline} to interruptionBaseline={resolvedInterruptionBaseline}.");
        return resolvedInterruptionBaseline;
    }

    private async Task<IReadOnlyList<string>> GetChangedPathsInRangeAsync(
        string workspace,
        string baseline,
        string terminal)
    {
        return (await RunGitAsync(workspace, $"diff --name-only \"{baseline}..{terminal}\""))
            .Replace("\r\n", "\n", StringComparison.Ordinal)
            .Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries);
    }

    private async Task<bool> IsCommitOnRemoteAsync(string sha)
    {
        var folderPath = _currentWorkspace?.FolderPath;
        if (string.IsNullOrWhiteSpace(folderPath))
            return true; // can't check — assume pushed to avoid false positives

        try
        {
            var process = Process.Start(new ProcessStartInfo
            {
                FileName = "git",
                Arguments = $"branch -r --contains {sha}",
                WorkingDirectory = folderPath,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            });

            if (process is null)
                return true;

            var stdout = await process.StandardOutput.ReadToEndAsync().ConfigureAwait(false);
            await process.WaitForExitAsync().ConfigureAwait(false);

            // Any output means the commit is on at least one remote branch
            return !string.IsNullOrWhiteSpace(stdout);
        }
        catch
        {
            return true; // can't check — assume pushed to avoid false positives
        }
    }

    private void AppendSystemLineOrDefer(string text, Brush? brush = null)
    {
        if (_isPromptRunning)
            _deferredSystemLines.Enqueue((text, brush));
        else
            AppendLine(text, brush);
    }

    private void FlushDeferredSystemLines()
    {
        while (_deferredSystemLines.TryDequeue(out var item))
            AppendLine(item.Text, item.Brush);
    }

    private async Task<bool> PushToOriginAsync()
    {
        var folderPath = _currentWorkspace?.FolderPath;
        if (string.IsNullOrWhiteSpace(folderPath))
        {
            Dispatcher.Invoke(() => AppendSystemLineOrDefer("⚠ No workspace folder — cannot push.", ThemeBrush("SystemErrorText")));
            return false;
        }

        Dispatcher.Invoke(() => AppendSystemLineOrDefer("Pushing to origin…"));

        try
        {
            var process = Process.Start(new ProcessStartInfo
            {
                FileName = "git",
                Arguments = "push",
                WorkingDirectory = folderPath,
                RedirectStandardOutput = true,
                RedirectStandardError = true,
                UseShellExecute = false,
                CreateNoWindow = true
            });

            if (process is null)
            {
                Dispatcher.Invoke(() => AppendSystemLineOrDefer("⚠ Failed to start git process.", ThemeBrush("SystemErrorText")));
                return false;
            }

            var stdout = await process.StandardOutput.ReadToEndAsync().ConfigureAwait(false);
            var stderr = await process.StandardError.ReadToEndAsync().ConfigureAwait(false);
            await process.WaitForExitAsync().ConfigureAwait(false);

            Dispatcher.Invoke(() =>
            {
                if (process.ExitCode == 0)
                    AppendSystemLineOrDefer("✓ Pushed successfully.");
                else
                    AppendSystemLineOrDefer($"⚠ git push failed (exit {process.ExitCode}): {stderr.Trim()}", ThemeBrush("SystemErrorText"));
            });

            return process.ExitCode == 0;
        }
        catch (Exception ex)
        {
            Dispatcher.Invoke(() => AppendSystemLineOrDefer($"⚠ Push error: {ex.Message}", ThemeBrush("SystemErrorText")));
            return false;
        }
    }

