    private void SaveLayoutPreset(int slotIndex)
    {
        if (_dockingService is null || _currentWorkspace is null) return;

        try
        {
            var visibleIds = _dockingService.GetCurrentLayoutData().VisiblePanelIds;
            _layoutPresetManager.SavePreset(slotIndex, _dockingService.CurrentLayout, visibleIds,
                documentationVisible: _documentationModeEnabled);
            ShowStatusNotification($"Layout preset {slotIndex + 1} saved (Shift+F{7 + slotIndex})", 2000);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(SaveLayoutPreset), ex);
        }
    }

    private void RestoreLayoutPreset(int slotIndex)
    {
        if (_dockingService is null || _currentWorkspace is null) return;

        try
        {
            var preset = _layoutPresetManager.GetPreset(slotIndex);
            if (preset is null)
            {
                ShowStatusNotification($"Layout preset {slotIndex + 1} is empty", 1500);
                return;
            }

            _dockingService.ApplyLayout(preset);
            _dockingService.SaveLayout(_currentWorkspace.FolderPath);
            
            // Restore zone widths
            if (preset.LeftZoneWidth is double lw && lw > 0 && LeftZoneColumn.Width.Value > 0)
                LeftZoneColumn.Width = new System.Windows.GridLength(lw, System.Windows.GridUnitType.Pixel);
            if (preset.RightZoneWidth is double rw && rw > 0 && RightZoneColumn.Width.Value > 0)
                RightZoneColumn.Width = new System.Windows.GridLength(rw, System.Windows.GridUnitType.Pixel);
            if (preset.Left2ZoneWidth is double l2w && l2w > 0 && Left2ZoneColumn.Width.Value > 0)
                Left2ZoneColumn.Width = new System.Windows.GridLength(l2w, System.Windows.GridUnitType.Pixel);
            if (preset.Right2ZoneWidth is double r2w && r2w > 0 && Right2ZoneColumn.Width.Value > 0)
                Right2ZoneColumn.Width = new System.Windows.GridLength(r2w, System.Windows.GridUnitType.Pixel);
            if (preset.Left3ZoneWidth is double l3w && l3w > 0 && Left3ZoneColumn.Width.Value > 0)
                Left3ZoneColumn.Width = new System.Windows.GridLength(l3w, System.Windows.GridUnitType.Pixel);
            if (preset.Right3ZoneWidth is double r3w && r3w > 0 && Right3ZoneColumn.Width.Value > 0)
                Right3ZoneColumn.Width = new System.Windows.GridLength(r3w, System.Windows.GridUnitType.Pixel);
            if (preset.Left4ZoneWidth is double l4w && l4w > 0 && Left4ZoneColumn.Width.Value > 0)
                Left4ZoneColumn.Width = new System.Windows.GridLength(l4w, System.Windows.GridUnitType.Pixel);
            if (preset.Right4ZoneWidth is double r4w && r4w > 0 && Right4ZoneColumn.Width.Value > 0)
                Right4ZoneColumn.Width = new System.Windows.GridLength(r4w, System.Windows.GridUnitType.Pixel);
            if (preset.Left5ZoneWidth is double l5w && l5w > 0 && Left5ZoneColumn.Width.Value > 0)
                Left5ZoneColumn.Width = new System.Windows.GridLength(l5w, System.Windows.GridUnitType.Pixel);
            if (preset.Right5ZoneWidth is double r5w && r5w > 0 && Right5ZoneColumn.Width.Value > 0)
                Right5ZoneColumn.Width = new System.Windows.GridLength(r5w, System.Windows.GridUnitType.Pixel);
            if (preset.Left6ZoneWidth is double l6w && l6w > 0 && Left6ZoneColumn.Width.Value > 0)
                Left6ZoneColumn.Width = new System.Windows.GridLength(l6w, System.Windows.GridUnitType.Pixel);
            if (preset.Right6ZoneWidth is double r6w && r6w > 0 && Right6ZoneColumn.Width.Value > 0)
                Right6ZoneColumn.Width = new System.Windows.GridLength(r6w, System.Windows.GridUnitType.Pixel);
            if (preset.Left7ZoneWidth is double l7w && l7w > 0 && Left7ZoneColumn.Width.Value > 0)
                Left7ZoneColumn.Width = new System.Windows.GridLength(l7w, System.Windows.GridUnitType.Pixel);
            if (preset.Right7ZoneWidth is double r7w && r7w > 0 && Right7ZoneColumn.Width.Value > 0)
                Right7ZoneColumn.Width = new System.Windows.GridLength(r7w, System.Windows.GridUnitType.Pixel);

            // Restore panel visibility — only when the preset carries visibility state
            // (VisiblePanelIds is null for legacy presets saved before this feature existed).
            if (preset.VisiblePanelIds is not null)
            {
                var ids = new HashSet<string>(preset.VisiblePanelIds, StringComparer.OrdinalIgnoreCase);

                _loopPanelVisible = ids.Contains("loop");
                SyncLoopPanel();
                if (ViewLoopPanelMenuItem is not null) ViewLoopPanelMenuItem.IsChecked = _loopPanelVisible;

                _tasksPanelVisible = ids.Contains("tasks");
                SyncTasksPanel();
                if (ViewTasksMenuItem is not null) ViewTasksMenuItem.IsChecked = _tasksPanelVisible;

                _approvalPanelVisible = ids.Contains("approvals");
                SyncApprovalPanel();
                if (ViewCommitApprovalsMenuItem is not null) ViewCommitApprovalsMenuItem.IsChecked = _approvalPanelVisible;

                _notesPanelVisible = ids.Contains("notes");
                SyncNotesPanel();
                if (ViewNotesMenuItem is not null) ViewNotesMenuItem.IsChecked = _notesPanelVisible;

                _codeHealthPanelVisible = ids.Contains("maintenance");
                SyncCodeHealthPanel();
                if (ViewCodeHealthMenuItem is not null) ViewCodeHealthMenuItem.IsChecked = _codeHealthPanelVisible;

                if (ids.Contains("inbox"))
                {
                    EnsureInboxPanelCreated();
                    if (!_inboxPanel!.PanelVisible) _inboxPanel.Show(flash: false);
                }
                else
                {
                    if (_inboxPanel is not null && _inboxPanel.PanelVisible)
                        _inboxPanel.Hide();
                    else if (InboxPanelBorder is not null)
                    {
                        InboxPanelBorder.Visibility = Visibility.Collapsed;
                        _dockingService?.OnPanelVisibilityChanged("inbox", false);
                        NotifyToolPanelVisibilityChanged("inbox", false);
                        UpdateMainGridSideMargins();
                    }
                }

            }

            // Restore documentation panel visibility — only when preset carries the state
            // (DocumentationVisible is null for legacy presets saved before this feature).
            if (preset.DocumentationVisible is bool docsVisible)
                SetDocumentationMode(docsVisible, persistChange: false);

            ShowStatusNotification($"Layout preset {slotIndex + 1} restored (F{7 + slotIndex})", 2000);
        }
        catch (Exception ex)
        {
            HandleUiCallbackException(nameof(RestoreLayoutPreset), ex);
        }
    }

    private void ShowStatusNotification(string message, int durationMs)
    {
        // Display a brief status notification. Using Trace for now as a simple feedback mechanism.
        // A more sophisticated implementation could use a status bar message or toast notification.
        SquadDashTrace.Write(TraceCategory.UI, message);
    }

    // ── Edit menu focus tracking ──────────────────────────────────────────

    private void OnWindowElementGotFocus(object sender, RoutedEventArgs e)
    {
        if (e.OriginalSource is TextBox or RichTextBox)
            _lastFocusedTextElement = (IInputElement)e.OriginalSource;
    }

    private void OnWindowFocusedElementChanged(object sender, DependencyPropertyChangedEventArgs e)
    {
        if (e.NewValue is TextBox or RichTextBox)
            _lastFocusedTextElement = (IInputElement)e.NewValue;
    }

    private bool LastFocusedIsPrompt() =>
        ReferenceEquals(_lastFocusedTextElement, PromptTextBox);

    private bool LastFocusedIsMarkdownEditor() =>
        _lastFocusedTextElement is RichTextBox;

    private bool LastFocusedHasSelection()
    {
        if (_lastFocusedTextElement is System.Windows.Controls.TextBox tb) return tb.SelectionLength > 0;
        if (_lastFocusedTextElement is System.Windows.Controls.RichTextBox rtb) return !rtb.Selection.IsEmpty;
        return false;
    }

    // ── Edit menu: submenu opened ─────────────────────────────────────────

    private void EditMenuItem_SubmenuOpened(object sender, RoutedEventArgs e)
    {
        bool isPrompt   = LastFocusedIsPrompt();
        bool isMdEditor = LastFocusedIsMarkdownEditor();
        bool hasSel     = LastFocusedHasSelection();
        bool isText     = _lastFocusedTextElement is not null;
        bool hasQueuedTab = _activeTabId is not null;

        EditPasteAsAttachmentMenuItem.IsEnabled = isPrompt;
        EditCopyAppendMenuItem.IsEnabled        = hasSel;

        EditBoldMenuItem.IsEnabled= hasSel;
        EditItalicMenuItem.IsEnabled        = hasSel;
        EditInlineCodeMenuItem.IsEnabled    = hasSel;
        EditParenthesesMenuItem.IsEnabled   = isText;
        EditQuotesMenuItem.IsEnabled        = hasSel;
        EditCycleCaseMenuItem.IsEnabled     = hasSel;
        EditSmoothDictationMenuItem.IsEnabled = hasSel;
        EditReviseWithAiMenuItem.IsEnabled    = hasSel;
        EditCleanUpMenuItem.IsEnabled         = hasSel;

        EditInsertHorizontalRuleMenuItem.IsEnabled = isMdEditor;
        EditInsertImageMenuItem.IsEnabled          = isMdEditor;
        EditInsertLineBreakMenuItem.IsEnabled      = isPrompt;
        EditInsertLinkMenuItem.IsEnabled           = isMdEditor;
        EditInsertTableMenuItem.IsEnabled          = isMdEditor;

        EditNewQueueToFrontMenuItem.IsEnabled    = isPrompt;
        EditNewQueueToTailMenuItem.IsEnabled     = isPrompt;
        EditMoveToFrontMenuItem.IsEnabled        = isPrompt;
        EditDeleteQueuedPromptMenuItem.IsEnabled = isPrompt && hasQueuedTab;
    }

