    private void EditMoveToFrontMenuItem_Click(object sender, RoutedEventArgs e) =>
        PrioritizeActiveTabToFront();

    private void EditDeleteQueuedPromptMenuItem_Click(object sender, RoutedEventArgs e) =>
        DeleteActiveQueueTabWithKeyboard();

    // ── Edit menu: Prompt History ─────────────────────────────────────────

    private void EditPromptHistoryPrevMenuItem_Click(object sender, RoutedEventArgs e)
    {
        RecordHintFeatureUsed(PromptHintFeature.CtrlArrowHistory);
        _conversationManager.NavigateHistory(-1);
    }

    private void EditPromptHistoryNextMenuItem_Click(object sender, RoutedEventArgs e)
    {
        RecordHintFeatureUsed(PromptHintFeature.CtrlArrowHistory);
        _conversationManager.NavigateHistory(1);
    }

    internal void SwitchTheme(string name) => ApplyTheme(name);
    internal string ActiveThemeName => _activeThemeName;

    private ThemeColorsWindow? _themeColorsWindow;

    private void ThemeColorsMenuItem_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            SquadDashTrace.Write("UI", "ThemeColorsMenuItem_Click: entered, existing window is null=" + (_themeColorsWindow is null));
            if (_themeColorsWindow is not null)
            {
                SquadDashTrace.Write("UI", "ThemeColorsMenuItem_Click: activating existing window");
                _themeColorsWindow.Activate();
                return;
            }
            SquadDashTrace.Write("UI", "ThemeColorsMenuItem_Click: creating new ThemeColorsWindow");
            var win = new ThemeColorsWindow(this);
            SquadDashTrace.Write("UI", "ThemeColorsMenuItem_Click: constructor completed, calling Show");
            if (CanShowOwnedWindow())
                win.Owner = this;
            win.Closed += (_, _) => _themeColorsWindow = null;
            _themeColorsWindow = win;
            win.Show();
            SquadDashTrace.Write("UI", "ThemeColorsMenuItem_Click: Show() returned");
        }
        catch (Exception ex)
        {
            _themeColorsWindow = null;
            HandleUiCallbackException(nameof(ThemeColorsMenuItem_Click), ex);
        }
    }

    private FontSizesWindow? _fontSizesWindow;

    private void FontSizesMenuItem_Click(object sender, RoutedEventArgs e)
    {
        try
        {
            if (_fontSizesWindow is not null)
            {
                _fontSizesWindow.Activate();
                return;
            }
            var win = new FontSizesWindow(this);
            if (CanShowOwnedWindow())
                win.Owner = this;
            win.Closed += (_, _) => _fontSizesWindow = null;
            _fontSizesWindow = win;
            win.Show();
        }
        catch (Exception ex)
        {
            _fontSizesWindow = null;
            HandleUiCallbackException(nameof(FontSizesMenuItem_Click), ex);
        }
    }
}

/// <summary>
/// COM-visible scripting bridge that allows JavaScript in the docs <see cref="System.Windows.Controls.WebBrowser"/>
/// to call back into <see cref="MainWindow"/>.  Set as
/// <c>DocMarkdownViewer.ObjectForScripting</c> so that <c>window.external.*</c>
/// calls in the rendered HTML reach this object.
/// </summary>
[ComVisible(true)]
[System.Runtime.InteropServices.ClassInterface(System.Runtime.InteropServices.ClassInterfaceType.AutoDispatch)]
public sealed class DocViewerScriptingBridge
{
    private readonly MainWindow _window;

    public DocViewerScriptingBridge(MainWindow window) => _window = window;

    /// <summary>Handles hyperlink navigation forwarded from the JS click handler.</summary>
    public void Navigate(string href)
    {
        _window.Dispatcher.BeginInvoke(() => _window.InvokeDocNavigation(href));
    }

    /// <summary>
    /// Called when the user right-clicks a 📸 placeholder blockquote.
    /// <paramref name="imagePath"/> is the relative path from the <c>src</c>
    /// attribute of the <c>&lt;img&gt;</c> immediately preceding the blockquote.
    /// </summary>
    public void ShowScreenshotMenu(string imagePath)
    {
        SquadDashTrace.Write("DocViewer", $"ShowScreenshotMenu called: {imagePath}");
        _window.Dispatcher.BeginInvoke(() => _window.ShowDocScreenshotContextMenu(imagePath));
    }

    /// <summary>
    /// Called when the user right-clicks an existing image in the docs viewer.
    /// <paramref name="imagePath"/> is the relative path from the <c>src</c> attribute.
    /// </summary>
    public void ShowImageMenu(string imagePath)
    {
        SquadDashTrace.Write("DocViewer", $"ShowImageMenu called: {imagePath}");
        _window.Dispatcher.BeginInvoke(() => _window.ShowImageContextMenu(imagePath));
    }

    /// <summary>
    /// Feature 3: Called when hovering over an element in the doc viewer.
    /// <paramref name="lineHint"/> is the line number from data-source-line attribute.
    /// </summary>
    public void HoverElement(string lineHint)
    {
        _window.Dispatcher.BeginInvoke(() => _window.HighlightDocSourceFromHover(lineHint));
    }

    /// <summary>
    /// Called when the user clicks an element in the doc viewer preview.
    /// Scrolls the source editor to the corresponding line and highlights it.
    /// </summary>
    public void ClickElement(string lineHint)
    {
        _window.Dispatcher.BeginInvoke(() => _window.ScrollDocSourceToLine(lineHint));
    }
}
